      'copy.subscription.paused',
    ]);
    expect(rows[0]?.idempotencyKey).not.toBe(rows[2]?.idempotencyKey);
    expect(new Set(rows.map((row) => row.idempotencyKey)).size).toBe(3);
    expect(rows.map((row) => row.aggregateSequence)).toEqual([1, 2, 3]);
  });
});

