import { Injectable, Logger } from '@nestjs/common';
import { CacheService } from '../../../infrastructure/redis/cache.service';
import { ReportingPeriod } from './revenue-analytics.types';

/**
 * Safe cache/read-through layer for expensive analytics queries using existing Redis/cache infrastructure
 * without becoming a source of truth.
 * Cache key includes tenant/admin scope, metric, period, currency, relevant filters.
 * TTL configurable, invalidate/refresh, fallback to source on failure.
 * Cache is never a source of truth.
 */
@Injectable()
export class AnalyticsCacheService {
  private readonly logger = new Logger(AnalyticsCacheService.name);
  private readonly defaultTtlSeconds: number;

  constructor(private readonly cacheService: CacheService) {
    this.defaultTtlSeconds = parseInt(process.env.ANALYTICS_CACHE_TTL || '300', 10); // 5 min default
  }

  private buildKey(params: {
    scope: string; // tenantId or platform
    metric: string;
    period?: ReportingPeriod;
    currency?: string;
    filters?: Record<string, any>;
  }): string {
    const parts = [
      'analytics',
      params.scope,
      params.metric,
      params.currency || 'ALL',
      params.period ? `${params.period.startDate}_${params.period.endDate}_${params.period.type}` : 'NO_PERIOD',
    ];

    if (params.filters) {
      const filterStr = Object.entries(params.filters)
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([k, v]) => `${k}=${JSON.stringify(v)}`)
        .join('&');
      parts.push(filterStr);
    }

    // Hash long keys to avoid Redis key length issues, but keep readable prefix
    const rawKey = parts.join(':');
    if (rawKey.length > 200) {
      // Simple hash for long keys
      let hash = 0;
      for (let i = 0; i < rawKey.length; i++) {
        const char = rawKey.charCodeAt(i);
        hash = (hash << 5) - hash + char;
        hash = hash & hash;
      }
      return `${parts.slice(0, 4).join(':')}:hash_${Math.abs(hash)}`;
    }

    return rawKey;
  }

  async get<T>(params: {
    scope: string;
    metric: string;
    period?: ReportingPeriod;
    currency?: string;
    filters?: Record<string, any>;
  }): Promise<T | null> {
    const key = this.buildKey(params);
    try {
      const cached = await this.cacheService.get<T>(key);
      if (cached) {
        this.logger.debug(`Cache hit for analytics key=${key}`);
      }
      return cached;
    } catch (e: any) {
      this.logger.warn(`Cache get failed for key=${key}: ${e.message}, falling back to source`);
      return null;
    }
  }

  async set<T>(params: {
    scope: string;
    metric: string;
    period?: ReportingPeriod;
    currency?: string;
    filters?: Record<string, any>;
    ttlSeconds?: number;
  }, value: T): Promise<void> {
    const key = this.buildKey(params);
    const ttl = params.ttlSeconds || this.defaultTtlSeconds;
    try {
      await this.cacheService.set(key, value, ttl);
      this.logger.debug(`Cache set for analytics key=${key} ttl=${ttl}s`);
    } catch (e: any) {
      this.logger.warn(`Cache set failed for key=${key}: ${e.message}, continuing without cache`);
      // Never throw - cache failure must not break source computation
    }
  }

  async remember<T>(params: {
    scope: string;
    metric: string;
    period?: ReportingPeriod;
    currency?: string;
    filters?: Record<string, any>;
    ttlSeconds?: number;
  }, factory: () => Promise<T>): Promise<T> {
    const key = this.buildKey(params);
    const ttl = params.ttlSeconds || this.defaultTtlSeconds;

    try {
      // Try cache first
      const cached = await this.cacheService.get<T>(key);
      if (cached !== null) {
        return cached;
      }
    } catch (e: any) {
      this.logger.warn(`Cache read failed for key=${key}: ${e.message}, computing from source`);
      // Fall through to factory
      return factory();
    }

    try {
      const value = await factory();
      // Try to cache, but don't fail if cache unavailable
      try {
        await this.cacheService.set(key, value, ttl);
      } catch (e: any) {
        this.logger.warn(`Cache write failed for key=${key}: ${e.message}`);
      }
      return value;
    } catch (e) {
      // Factory failed - rethrow, don't cache failure
      throw e;
    }
  }

  async invalidateScope(scope: string): Promise<number> {
    try {
      const pattern = `analytics:${scope}:*`;
      const deleted = await this.cacheService.deleteByPattern(pattern);
      this.logger.log(`Invalidated ${deleted} analytics cache keys for scope=${scope}`);
      return deleted;
    } catch (e: any) {
      this.logger.warn(`Cache invalidation failed for scope=${scope}: ${e.message}`);
      return 0;
    }
  }

  async invalidateMetric(metric: string): Promise<number> {
    try {
      const pattern = `analytics:*:${metric}:*`;
      const deleted = await this.cacheService.deleteByPattern(pattern);
      this.logger.log(`Invalidated ${deleted} analytics cache keys for metric=${metric}`);
      return deleted;
    } catch (e: any) {
      this.logger.warn(`Cache invalidation failed for metric=${metric}: ${e.message}`);
      return 0;
    }
  }

  async invalidateAll(): Promise<number> {
    try {
      const deleted = await this.cacheService.deleteByPattern('analytics:*');
      this.logger.log(`Invalidated ${deleted} analytics cache keys (all)`);
      return deleted;
    } catch (e: any) {
      this.logger.warn(`Cache invalidation failed for all analytics: ${e.message}`);
      return 0;
    }
  }

  async deleteKey(params: {
    scope: string;
    metric: string;
    period?: ReportingPeriod;
    currency?: string;
    filters?: Record<string, any>;
  }): Promise<void> {
    const key = this.buildKey(params);
    try {
      await this.cacheService.delete(key);
    } catch (e: any) {
      this.logger.warn(`Cache delete failed for key=${key}: ${e.message}`);
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import {
  BillingInterval,
  SubscriptionStatus,
  MoneyAmount,
  ArrBreakdown,
  zeroMoney,
  parseToMinorUnits,
  formatFromMinorUnits,
  getMinorUnitForCurrency,
} from './revenue-analytics.types';

/**
 * Deterministic ARR calculation based on canonical recurring subscription state and normalized annual value.
 * MONTHLY × 12, QUARTERLY × 4, YEARLY × 1, LIFETIME excluded unless explicitly configured.
 * Uses canonical subscription state and price, Decimal-safe.
 */
@Injectable()
export class ArrCalculationService {
  private readonly logger = new Logger(ArrCalculationService.name);

  constructor(private readonly prisma: PrismaService) {}

  async calculateArr(params: {
    tenantId?: string;
    currency?: string;
    asOfDate?: Date;
    includeTrials?: boolean;
    includeLifetimeAsRecurring?: boolean;
  }): Promise<ArrBreakdown | ArrBreakdown[]> {
    const asOfDate = params.asOfDate || new Date();
    const currencyFilter = params.currency?.toUpperCase();
    const includeTrials = params.includeTrials ?? false;
    const includeLifetime = params.includeLifetimeAsRecurring ?? false;

    const subscriptions = await this.fetchActiveSubscriptions({
      tenantId: params.tenantId,
      asOfDate,
      includeTrials,
    });

    if (subscriptions.length === 0) {
      const currency = currencyFilter || 'USD';
      return {
        totalArr: zeroMoney(currency),
        currency,
        activeSubscriptions: 0,
        calculationDate: asOfDate.toISOString(),
        methodology: 'Active recurring subscriptions normalized to annual: MONTHLY×12, QUARTERLY×4, YEARLY×1, LIFETIME excluded unless policy says recurring',
        byPlan: [],
        byInterval: [],
      };
    }

    const byCurrency = new Map<string, typeof subscriptions>();
    for (const sub of subscriptions) {
      const curr = (sub.plan?.currency || 'USD').toUpperCase();
      if (currencyFilter && curr !== currencyFilter) continue;
      if (!byCurrency.has(curr)) byCurrency.set(curr, []);
      byCurrency.get(curr)!.push(sub);
    }

    const results: ArrBreakdown[] = [];

    for (const [currency, subs] of byCurrency.entries()) {
      let totalMinor = 0;
      const byPlanMap = new Map<string, { planId: string; planCode: string; planName: string; arrMinor: number; count: number }>();
      const byIntervalMap = new Map<BillingInterval, { arrMinor: number; count: number }>();

      for (const sub of subs) {
        const plan = sub.plan;
        if (!plan) continue;

        const interval = (plan.interval as BillingInterval) || BillingInterval.MONTHLY;
        const priceStr = plan.price?.toString() || '0';
        const priceMinor = parseToMinorUnits(priceStr, currency);

        let arrMinor: number;
        switch (interval) {
          case BillingInterval.MONTHLY:
            arrMinor = priceMinor * 12;
            break;
          case BillingInterval.QUARTERLY:
            arrMinor = priceMinor * 4;
            break;
          case BillingInterval.YEARLY:
            arrMinor = priceMinor;
            break;
          case BillingInterval.LIFETIME:
            arrMinor = includeLifetime ? priceMinor : 0;
            break;
          default:
            arrMinor = priceMinor * 12;
        }

        const seats = sub.seatsPurchased || 1;
        if (seats > 1) arrMinor = arrMinor * seats;

        if (arrMinor === 0) continue;

        totalMinor += arrMinor;

        const planKey = plan.id;
        if (!byPlanMap.has(planKey)) {
          byPlanMap.set(planKey, { planId: plan.id, planCode: plan.code, planName: plan.name, arrMinor: 0, count: 0 });
        }
        const planAgg = byPlanMap.get(planKey)!;
        planAgg.arrMinor += arrMinor;
        planAgg.count += 1;

        if (!byIntervalMap.has(interval)) {
          byIntervalMap.set(interval, { arrMinor: 0, count: 0 });
        }
        const intervalAgg = byIntervalMap.get(interval)!;
        intervalAgg.arrMinor += arrMinor;
        intervalAgg.count += 1;
      }

      const totalArr = { amount: formatFromMinorUnits(totalMinor, currency), currency, minorUnit: getMinorUnitForCurrency(currency) } as MoneyAmount;

      results.push({
        totalArr,
        currency,
        activeSubscriptions: subs.length,
        calculationDate: asOfDate.toISOString(),
        methodology: 'Active recurring subscriptions normalized to annual: MONTHLY×12, QUARTERLY×4, YEARLY×1, LIFETIME excluded unless policy says recurring. Decimal-safe minor-unit arithmetic.',
        byPlan: Array.from(byPlanMap.values()).map((v) => ({
          planId: v.planId,
          planCode: v.planCode,
          planName: v.planName,
          arr: { amount: formatFromMinorUnits(v.arrMinor, currency), currency, minorUnit: getMinorUnitForCurrency(currency) },
          count: v.count,
        })),
        byInterval: Array.from(byIntervalMap.entries()).map(([interval, v]) => ({
          interval,
          arr: { amount: formatFromMinorUnits(v.arrMinor, currency), currency, minorUnit: getMinorUnitForCurrency(currency) },
          count: v.count,
        })),
      });
    }

    if (currencyFilter) {
      return results[0] || {
        totalArr: zeroMoney(currencyFilter),
        currency: currencyFilter,
        activeSubscriptions: 0,
        calculationDate: asOfDate.toISOString(),
        methodology: 'No active subscriptions for currency',
        byPlan: [],
        byInterval: [],
      };
    }

    return results;
  }

  async calculateArrForTenant(tenantId: string, currency?: string, asOfDate?: Date): Promise<ArrBreakdown> {
    const result = await this.calculateArr({ tenantId, currency, asOfDate });
    if (Array.isArray(result)) {
      return result[0] || {
        totalArr: zeroMoney(currency || 'USD'),
        currency: currency || 'USD',
        activeSubscriptions: 0,
        calculationDate: (asOfDate || new Date()).toISOString(),
        methodology: 'Tenant ARR',
        byPlan: [],
        byInterval: [],
      };
    }
    return result;
  }

  async calculatePlatformArr(currency?: string): Promise<ArrBreakdown[]> {
    const result = await this.calculateArr({ currency });
    return Array.isArray(result) ? result : [result];
  }

  private async fetchActiveSubscriptions(params: { tenantId?: string; asOfDate: Date; includeTrials: boolean }): Promise<any[]> {
    const { tenantId, asOfDate, includeTrials } = params;
    const statuses = includeTrials
      ? [SubscriptionStatus.ACTIVE, SubscriptionStatus.TRIALING, SubscriptionStatus.PAST_DUE]
      : [SubscriptionStatus.ACTIVE, SubscriptionStatus.PAST_DUE];

    try {
      const where: any = {
        status: { in: statuses },
        currentPeriodEnd: { gte: asOfDate },
      };
      if (tenantId) where.tenantId = tenantId;

      const subs = await (this.prisma as any).tenantSubscription.findMany({
        where,
        include: { plan: true },
      });
      return subs || [];
    } catch (e: any) {
      this.logger.warn(`Failed to fetch active subscriptions for ARR: ${e.message}`);
      throw e;
    }
  }

  normalizeToArr(price: string, interval: BillingInterval, currency: string, includeLifetime = false): MoneyAmount {
    const minor = parseToMinorUnits(price, currency);
    let arrMinor: number;
    switch (interval) {
      case BillingInterval.MONTHLY:
        arrMinor = minor * 12;
        break;
      case BillingInterval.QUARTERLY:
        arrMinor = minor * 4;
        break;
      case BillingInterval.YEARLY:
        arrMinor = minor;
        break;
      case BillingInterval.LIFETIME:
        arrMinor = includeLifetime ? minor : 0;
        break;
      default:
        arrMinor = minor * 12;
    }
    return { amount: formatFromMinorUnits(arrMinor, currency), currency, minorUnit: getMinorUnitForCurrency(currency) };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import {
  ReportingPeriod,
  MoneyAmount,
  CashflowSnapshot,
  zeroMoney,
  parseToMinorUnits,
  formatFromMinorUnits,
  getMinorUnitForCurrency,
} from './revenue-analytics.types';

/**
 * Cash collected, refunds, net cash, outstanding amounts, payment-failure impact, period cashflow
 * derived from canonical payment/invoice/ledger data.
 * Does NOT treat invoice as cash unless payment evidence supports it.
 */
@Injectable()
export class CashflowAnalyticsService {
  private readonly logger = new Logger(CashflowAnalyticsService.name);

  constructor(private readonly prisma: PrismaService) {}

  async calculateCashflow(params: {
    tenantId?: string;
    currency?: string;
    period: ReportingPeriod;
  }): Promise<CashflowSnapshot> {
    const currency = (params.currency || 'USD').toUpperCase();
    const { start, end } = this.parsePeriod(params.period);

    const payments = await this.fetchPayments({ tenantId: params.tenantId, currency, start, end });
    const invoices = await this.fetchInvoices({ tenantId: params.tenantId, currency, start, end });
    const refunds = await this.fetchRefunds({ tenantId: params.tenantId, currency, start, end });
    const dunningCases = await this.fetchDunningCases({ tenantId: params.tenantId, start, end });
    const feeSettlements = await this.fetchFeeSettlements({ tenantId: params.tenantId, currency, start, end });

    let collectedMinor = 0;
    let successfulMinor = 0;
    let failedMinor = 0;
    let pendingMinor = 0;
    let refundMinor = 0;
    let outstandingMinor = 0;
    let dunningExposureMinor = 0;
    let feePayoutMinor = 0;
    let taxCollectedMinor = 0;
    let grossCashInMinor = 0;
    let grossCashOutMinor = 0;

    let successfulCount = 0;
    let failedCount = 0;
    let pendingCount = 0;

    for (const p of payments) {
      const amountMinor = parseToMinorUnits(p.amount || '0', currency);
      const status = (p.status || '').toUpperCase();

      if (['SUCCEEDED', 'PAID', 'COMPLETED', 'CONFIRMED'].includes(status)) {
        collectedMinor += amountMinor;
        successfulMinor += amountMinor;
        grossCashInMinor += amountMinor;
        successfulCount++;
      } else if (['FAILED', 'CANCELLED', 'EXPIRED'].includes(status)) {
        failedMinor += amountMinor;
        failedCount++;
      } else if (['PENDING', 'CREATED', 'PROCESSING', 'REQUIRES_ACTION'].includes(status)) {
        pendingMinor += amountMinor;
        pendingCount++;
      }
    }

    for (const r of refunds) {
      if (['SUCCEEDED', 'COMPLETED', 'PROCESSED'].includes((r.status || '').toUpperCase())) {
        const amountMinor = parseToMinorUnits(r.amount || '0', currency);
        refundMinor += amountMinor;
        grossCashOutMinor += amountMinor;
      }
    }

    for (const inv of invoices) {
      if (['OPEN', 'OVERDUE', 'PARTIALLY_PAID'].includes((inv.status || '').toUpperCase())) {
        const dueMinor = parseToMinorUnits(inv.amountDue || inv.total || '0', currency);
        outstandingMinor += dueMinor;
      }
      const taxMinor = parseToMinorUnits(inv.taxTotal || '0', currency);
      taxCollectedMinor += taxMinor;
    }

    for (const d of dunningCases) {
      // Dunning exposure: payment amount that is at risk
      try {
        const payment = await (this.prisma as any).payment?.findFirst({ where: { id: d.paymentId } });
        if (payment && payment.currency?.toUpperCase() === currency) {
          dunningExposureMinor += parseToMinorUnits(payment.amount || '0', currency);
        }
      } catch {}
    }

    for (const fs of feeSettlements) {
      if (['PAID', 'FINALIZED'].includes((fs.status || '').toUpperCase())) {
        feePayoutMinor += parseToMinorUnits(fs.finalSettlementAmount || fs.grossFeeAmount || '0', currency);
      }
    }

    const netCashMinor = collectedMinor - refundMinor;

    const minorUnit = getMinorUnitForCurrency(currency);

    return {
      period: params.period,
      currency,
      collectedCash: { amount: formatFromMinorUnits(collectedMinor, currency), currency, minorUnit },
      successfulPaymentAmount: { amount: formatFromMinorUnits(successfulMinor, currency), currency, minorUnit },
      failedPaymentAmount: { amount: formatFromMinorUnits(failedMinor, currency), currency, minorUnit },
      pendingPaymentAmount: { amount: formatFromMinorUnits(pendingMinor, currency), currency, minorUnit },
      refunds: { amount: formatFromMinorUnits(refundMinor, currency), currency, minorUnit },
      netCash: { amount: formatFromMinorUnits(netCashMinor, currency), currency, minorUnit },
      outstandingInvoicesAmount: { amount: formatFromMinorUnits(outstandingMinor, currency), currency, minorUnit },
      dunningExposure: { amount: formatFromMinorUnits(dunningExposureMinor, currency), currency, minorUnit },
      feePayouts: { amount: formatFromMinorUnits(feePayoutMinor, currency), currency, minorUnit },
      taxCollected: { amount: formatFromMinorUnits(taxCollectedMinor, currency), currency, minorUnit },
      grossCashIn: { amount: formatFromMinorUnits(grossCashInMinor, currency), currency, minorUnit },
      grossCashOut: { amount: formatFromMinorUnits(grossCashOutMinor, currency), currency, minorUnit },
      source: {
        paymentCount: payments.length,
        invoiceCount: invoices.length,
        refundCount: refunds.length,
      },
      calculatedAt: new Date().toISOString(),
    };
  }

  async calculateOutstanding(params: { tenantId?: string; currency?: string }): Promise<{
    currency: string;
    outstandingAmount: MoneyAmount;
    overdueAmount: MoneyAmount;
    invoiceCount: number;
    overdueCount: number;
    calculatedAt: string;
  }> {
    const currency = (params.currency || 'USD').toUpperCase();
    try {
      const where: any = {
        currency,
        status: { in: ['OPEN', 'OVERDUE', 'PARTIALLY_PAID'] },
      };
      if (params.tenantId) where.tenantId = params.tenantId;

      const invoices = await (this.prisma as any).invoice?.findMany({ where }) || [];
      let outstandingMinor = 0;
      let overdueMinor = 0;
      let overdueCount = 0;

      for (const inv of invoices) {
        const dueMinor = parseToMinorUnits(inv.amountDue || inv.total || '0', currency);
        outstandingMinor += dueMinor;
        if ((inv.status || '').toUpperCase() === 'OVERDUE') {
          overdueMinor += dueMinor;
          overdueCount++;
        }
      }

      return {
        currency,
        outstandingAmount: { amount: formatFromMinorUnits(outstandingMinor, currency), currency, minorUnit: getMinorUnitForCurrency(currency) },
        overdueAmount: { amount: formatFromMinorUnits(overdueMinor, currency), currency, minorUnit: getMinorUnitForCurrency(currency) },
        invoiceCount: invoices.length,
        overdueCount,
        calculatedAt: new Date().toISOString(),
      };
    } catch (e: any) {
      this.logger.warn(`Failed to calculate outstanding: ${e.message}`);
      return {
        currency,
        outstandingAmount: zeroMoney(currency),
        overdueAmount: zeroMoney(currency),
        invoiceCount: 0,
        overdueCount: 0,
        calculatedAt: new Date().toISOString(),
      };
    }
  }

  private parsePeriod(period: ReportingPeriod): { start: Date; end: Date } {
    return { start: new Date(period.startDate), end: new Date(period.endDate) };
  }

  private async fetchPayments(params: { tenantId?: string; currency: string; start: Date; end: Date }): Promise<any[]> {
    const where: any = {
      currency: params.currency,
      createdAt: { gte: params.start, lte: params.end },
    };
    if (params.tenantId) where.tenantId = params.tenantId;
    return await (this.prisma as any).payment?.findMany({ where }) || [];
  }

  private async fetchInvoices(params: { tenantId?: string; currency: string; start: Date; end: Date }): Promise<any[]> {
    const where: any = {
      currency: params.currency,
      createdAt: { gte: params.start, lte: params.end },
    };
    if (params.tenantId) where.tenantId = params.tenantId;
    return await (this.prisma as any).invoice?.findMany({ where }) || [];
  }

  private async fetchRefunds(params: { tenantId?: string; currency: string; start: Date; end: Date }): Promise<any[]> {
    const where: any = {
      currency: params.currency,
      createdAt: { gte: params.start, lte: params.end },
    };
    if (params.tenantId) where.tenantId = params.tenantId;
    return await (this.prisma as any).refund?.findMany({ where }) || [];
  }

  private async fetchDunningCases(params: { tenantId?: string; start: Date; end: Date }): Promise<any[]> {
    const where: any = {
      createdAt: { gte: params.start, lte: params.end },
