import { Injectable } from '@nestjs/common';
import { InjectPinoLogger, PinoLogger } from 'nestjs-pino';

import { UsageService } from './usage.service';
import { EnforcementContextBuilder } from './enforcement.context';
import { EnforcementAuditService } from './enforcement.audit';
import {
  EnforcementDecisionCode,
  type EnforcementActor,
  type QuotaCheckResult,
} from './enforcement.types';
import { PlanLimitExceededError } from './enforcement.errors';

/**
 * Runtime enforcement for websocket connection limits.
 *
 * Enforces the `websocketConnections` plan limit at connection-open time.
 *
 * Flow:
 *   connection request → tenant context → current plan → websocket limit →
 *   current usage → reserve connection slot → allow/reject
 *
 * The reservation is released on:
 *   - disconnect
 *   - connection failure
 *   - server-side termination
 *
 * Concurrency: the reserve operation uses an atomic Lua script in Redis so
 * two simultaneous connection attempts cannot both succeed when only one slot
 * remains.
 */
@Injectable()
export class WebsocketLimitGuard {
  constructor(
    private readonly usageService: UsageService,
    private readonly contextBuilder: EnforcementContextBuilder,
    private readonly audit: EnforcementAuditService,
    @InjectPinoLogger(WebsocketLimitGuard.name) private readonly logger: PinoLogger,
  ) {}

  /**
   * Attempt to reserve a websocket connection slot for the tenant.
   *
   * Returns a `QuotaCheckResult` indicating whether the reservation succeeded.
   * When `allowed` is false, the caller must reject the connection.
   */
  async reserveConnection(actor: EnforcementActor): Promise<QuotaCheckResult> {
    const billingCtx = await this.contextBuilder.resolveBillingContext(actor.tenantId);
    const maximum = billingCtx.planLimits.websocketConnections;

    // Unlimited plan
    if (maximum === null) {
      return {
        allowed: true,
        decision: EnforcementDecisionCode.ALLOWED,
        limitKey: 'websocketConnections',
        currentUsage: 0,
        configuredMaximum: null,
        remaining: null,
        scope: 'TENANT' as any,
        scopeId: actor.tenantId,
      };
    }

    const reserveResult = await this.usageService.reserveWebsocketConnection(
      actor.tenantId,
      maximum,
    );

    const result: QuotaCheckResult = {
      allowed: reserveResult.reserved,
      decision: reserveResult.reserved
        ? EnforcementDecisionCode.ALLOWED
        : EnforcementDecisionCode.PLAN_LIMIT_EXCEEDED,
      limitKey: 'websocketConnections',
      currentUsage: reserveResult.currentAfter,
      configuredMaximum: maximum,
      remaining: reserveResult.remaining,
      scope: 'TENANT' as any,
      scopeId: actor.tenantId,
      reason: reserveResult.reserved
        ? undefined
        : `WebSocket connection limit reached: ${reserveResult.currentAfter}/${maximum}.`,
    };

    const enforcementCtx = { tenant: billingCtx, actor };
    await this.audit.logLimitCheck(enforcementCtx, result, actor.userId);

    if (!reserveResult.reserved) {
      throw new PlanLimitExceededError({
        limitKey: 'websocketConnections',
        currentUsage: reserveResult.currentAfter,
        configuredMaximum: maximum,
        remaining: 0,
        scope: 'TENANT' as any,
      });
    }

    return result;
  }

  /**
   * Release a previously reserved websocket connection slot.
   *
   * Must be called on disconnect, connection failure, or server-side
   * termination so the counter does not permanently leak.
   */
  async releaseConnection(tenantId: string): Promise<void> {
    await this.usageService.releaseWebsocketConnection(tenantId);
  }

  /**
   * Check whether the tenant can open another websocket connection without
   * reserving a slot.  Non-destructive: does not increment the counter.
   */
  async canConnect(actor: EnforcementActor): Promise<QuotaCheckResult> {
    const billingCtx = await this.contextBuilder.resolveBillingContext(actor.tenantId);
    const maximum = billingCtx.planLimits.websocketConnections;

    if (maximum === null) {
      return {
        allowed: true,
        decision: EnforcementDecisionCode.ALLOWED,
        limitKey: 'websocketConnections',
        currentUsage: 0,
        configuredMaximum: null,
        remaining: null,
        scope: 'TENANT' as any,
        scopeId: actor.tenantId,
      };
    }

    const usage = await this.usageService.getWebsocketUsage(actor.tenantId, maximum);
    const allowed = usage.current < maximum;

    return {
      allowed,
      decision: allowed
        ? EnforcementDecisionCode.ALLOWED
        : EnforcementDecisionCode.PLAN_LIMIT_EXCEEDED,
      limitKey: 'websocketConnections',
      currentUsage: usage.current,
      configuredMaximum: maximum,
      remaining: usage.remaining,
      scope: 'TENANT' as any,
      scopeId: actor.tenantId,
      reason: allowed
        ? undefined
        : `WebSocket connection limit reached: ${usage.current}/${maximum}.`,
    };
  }
}

/**
 * Entitlement Resolver - GraphQL resolver for entitlements
 * 
 * This module handles GraphQL queries and mutations for entitlements.
 */

import { EntitlementService } from './entitlement.service';
import { EntitlementPolicy } from './entitlement.policy';
import {
  Entitlement,
  EntitlementFeature,
  EntitlementLimit,
  CreateEntitlementRequest,
  UpdateEntitlementRequest,
  EntitlementFilter,
  EntitlementSummary,
  FeatureAccess,
} from './entitlement.types';

export class EntitlementResolver {
  private readonly policy: EntitlementPolicy;

  constructor(private readonly service: EntitlementService) {
    this.policy = new EntitlementPolicy();
  }

  /**
   * Query: Get entitlement by ID
   */
  async getEntitlement(
    id: string,
    context: { userId: string; tenantId: string }
  ): Promise<Entitlement | null> {
    try {
      const entitlement = await this.service.getEntitlement(id);
      // Another tenant's entitlement is reported exactly like a missing one.
      return entitlement.tenantId === context.tenantId ? entitlement : null;
    } catch (error) {
      return null;
    }
  }

  /**
   * Query: Get current user's entitlement
   */
  async getMyEntitlement(
    context: { userId: string; tenantId: string }
  ): Promise<Entitlement | null> {
    return this.service.getUserEntitlement(context.userId, context.tenantId);
  }

  /**
   * Query: List entitlements
   */
  async listEntitlements(
    filter: EntitlementFilter,
    context: { userId: string; tenantId: string }
  ): Promise<Entitlement[]> {
    // Apply tenant filter from context
    return this.service.listEntitlements({
      ...filter,
      tenantId: context.tenantId,
    });
  }

  /**
   * Query: Get entitlement summary
   */
  async getEntitlementSummary(
    context: { userId: string; tenantId: string }
  ): Promise<EntitlementSummary | null> {
    return this.service.getEntitlementSummary(context.userId, context.tenantId);
  }

  /**
   * Query: Check feature access
   */
  async checkFeatureAccess(
    featureKey: string,
    context: { userId: string; tenantId: string }
  ): Promise<FeatureAccess> {
    return this.service.checkFeatureAccess(
      context.userId,
      context.tenantId,
      featureKey
    );
  }

  /**
   * Query: Get active features
   */
  async getActiveFeatures(
    context: { userId: string; tenantId: string }
  ): Promise<EntitlementFeature[]> {
    return this.service.getActiveFeatures(context.userId, context.tenantId);
  }

  /**
   * Query: Get limits near threshold
   */
  async getLimitsNearThreshold(
    thresholdPercentage: number,
    context: { userId: string; tenantId: string }
  ): Promise<EntitlementLimit[]> {
    return this.service.getLimitsNearThreshold(
      context.userId,
      context.tenantId,
      thresholdPercentage
    );
  }

  /**
   * Mutation: Create entitlement
   */
  async createEntitlement(
    data: CreateEntitlementRequest,
    context: { userId: string; tenantId: string }
  ): Promise<Entitlement> {
    // Ensure tenant matches context
    if (data.tenantId !== context.tenantId) {
      throw new Error('Cannot create entitlement for different tenant');
    }

    return this.service.createEntitlement(data);
  }

  /**
   * Mutation: Update entitlement
   */
  async updateEntitlement(
    id: string,
    data: UpdateEntitlementRequest,
    context: { userId: string; tenantId: string }
  ): Promise<Entitlement> {
    // Verify entitlement belongs to tenant
    const existing = await this.service.getEntitlement(id);
    if (existing.tenantId !== context.tenantId) {
      throw new Error('Entitlement does not belong to this tenant');
    }

    return this.service.updateEntitlement(id, data);
  }

  /**
   * Mutation: Cancel entitlement
   */
  async cancelEntitlement(
    id: string,
    context: { userId: string; tenantId: string }
  ): Promise<Entitlement> {
    // Verify entitlement belongs to tenant
    const existing = await this.service.getEntitlement(id);
    if (existing.tenantId !== context.tenantId) {
      throw new Error('Entitlement does not belong to this tenant');
    }

    return this.service.cancelEntitlement(id);
  }

  /**
   * Mutation: Suspend entitlement
   */
  async suspendEntitlement(
    id: string,
    context: { userId: string; tenantId: string }
  ): Promise<Entitlement> {
    // Verify entitlement belongs to tenant
    const existing = await this.service.getEntitlement(id);
    if (existing.tenantId !== context.tenantId) {
      throw new Error('Entitlement does not belong to this tenant');
    }

    return this.service.suspendEntitlement(id);
  }

  /**
   * Mutation: Reactivate entitlement
   */
  async reactivateEntitlement(
    id: string,
    context: { userId: string; tenantId: string }
  ): Promise<Entitlement> {
    // Verify entitlement belongs to tenant
    const existing = await this.service.getEntitlement(id);
    if (existing.tenantId !== context.tenantId) {
      throw new Error('Entitlement does not belong to this tenant');
    }

    return this.service.reactivateEntitlement(id);
  }

  /**
   * Mutation: Record usage
   */
  async recordUsage(
    featureKey: string,
    amount: number,
    context: { userId: string; tenantId: string }
  ): Promise<boolean> {
    try {
      await this.service.recordUsage(
        context.userId,
        context.tenantId,
        featureKey,
        amount
      );
      return true;
    } catch (error) {
      return false;
    }
  }

  /**
   * Mutation: Reset usage
   */
  async resetUsage(
    limitKey: string,
    context: { userId: string; tenantId: string }
  ): Promise<boolean> {
    try {
      await this.service.resetUsage(
        context.userId,
        context.tenantId,
        limitKey
      );
      return true;
    } catch (error) {
      return false;
    }
  }

  /**
   * Field resolver: Check if entitlement is active
   */
  async isActive(
    entitlement: Entitlement,
    context: { userId: string; tenantId: string }
  ): Promise<boolean> {
    return this.policy.isEntitlementActive(entitlement);
  }

  /**
   * Field resolver: Get feature access for a specific feature
   */
  async featureAccess(
    entitlement: Entitlement,
    featureKey: string,
    context: { userId: string; tenantId: string }
  ): Promise<FeatureAccess> {
    return this.policy.checkFeatureAccess(entitlement, featureKey);
  }

  /**
   * Field resolver: Get active features
   */
  async activeFeatures(
    entitlement: Entitlement,
    context: { userId: string; tenantId: string }
  ): Promise<EntitlementFeature[]> {
    return this.policy.getActiveFeatures(entitlement);
  }

  /**
   * Field resolver: Get limits near threshold
   */
  async limitsNearThreshold(
    entitlement: Entitlement,
    thresholdPercentage: number,
    context: { userId: string; tenantId: string }
  ): Promise<EntitlementLimit[]> {
    return this.policy.getLimitsNearThreshold(entitlement, thresholdPercentage);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import type { Prisma } from '@prisma/client';
import { FeeAccrual, FeeAccrualStatus, SettlementState, PayoutState, FeeType, FeeSourceType, RateBasis } from './fee.types';
import { randomUUID } from 'crypto';

/** Accrual fields without a FeeAccrual column, stored in `metadata` under this key. */
export const FEE_ACCRUAL_METADATA_KEY = '_fee';

export interface FeeAccrualExtras {
  netAmount?: string | null;
  payoutState?: string | null;
  payoutId?: string | null;
  ledgerTransactionId?: string | null;
  policySnapshot?: unknown;
  calculationTimestamp?: string | null;
}

/** Metadata JSON for a write: caller metadata (replacing the stored one when given) plus merged accrual fields. */
export function buildFeeAccrualMetadata(existing: unknown, userMetadata: Record<string, unknown> | null, extras: FeeAccrualExtras): Record<string, unknown> {
  const current: Record<string, unknown> = existing && typeof existing === 'object' && !Array.isArray(existing) ? { ...(existing as Record<string, unknown>) } : {};
  const storedRaw = current[FEE_ACCRUAL_METADATA_KEY];
  const stored: Record<string, unknown> = storedRaw && typeof storedRaw === 'object' ? { ...(storedRaw as Record<string, unknown>) } : {};
  const user: Record<string, unknown> = userMetadata ? { ...userMetadata } : current;
  delete user[FEE_ACCRUAL_METADATA_KEY];
  for (const [key, value] of Object.entries(extras)) {
    if (value !== undefined) stored[key] = value;
  }
  return { ...user, [FEE_ACCRUAL_METADATA_KEY]: stored };
}

/**
 * Persistent storage abstraction for immutable fee accruals.
 * Idempotency via unique idempotencyKey and source reference.
 * Tenant-scoped queries, auditable history.
 */
@Injectable()
export class FeeAccrualRepository {
  private readonly logger = new Logger(FeeAccrualRepository.name);

  constructor(private readonly prisma: PrismaService) {}

  async create(data: {
    tenantId: string;
    sourceType: FeeSourceType;
    sourceId: string;
    feeType: FeeType;
    feeRateBps: number;
    rateBasis: RateBasis;
    grossAmount: string;
    feeAmount: string;
    netAmount: string;
    currency: string;
    status: FeeAccrualStatus;
    settlementState: SettlementState;
    payoutState?: PayoutState | null;
    settlementId?: string | null;
    payoutId?: string | null;
    ledgerTransactionId?: string | null;
    idempotencyKey: string;
    policySnapshot: any;
    calculationTimestamp: string;
    metadata?: Record<string, unknown> | null;
    safeMetadata?: Record<string, unknown> | null;
  }, tx?: Prisma.TransactionClient): Promise<FeeAccrual> {
    const client = (tx ?? this.prisma) as any;
    // Idempotency checks use the same transaction as the insert when supplied.
    const existingByIdempotencyRow = await client.feeAccrual?.findFirst({
      where: { idempotencyKey: data.idempotencyKey, tenantId: data.tenantId },
    });
    const existingByIdempotency = existingByIdempotencyRow ? this.mapToDomain(existingByIdempotencyRow) : null;
    if (existingByIdempotency) {
      this.logger.log(`Idempotent accrual return by idempotencyKey: ${data.idempotencyKey}`);
      return existingByIdempotency;
    }

    const existingBySourceRow = await client.feeAccrual?.findFirst({
      where: {
        tenantId: data.tenantId,
        feeSourceType: data.sourceType,
        sourceId: data.sourceId,
        feeType: data.feeType,
      },
      orderBy: { createdAt: 'desc' },
    });
    const existingBySource = existingBySourceRow ? this.mapToDomain(existingBySourceRow) : null;
    if (existingBySource) {
      this.logger.log(`Idempotent accrual return by source: ${data.sourceType}:${data.sourceId} feeType=${data.feeType}`);
      return existingBySource;
    }

    const id = randomUUID();
    const now = new Date().toISOString();

    const accrual: FeeAccrual = {
      id,
      tenantId: data.tenantId,
      sourceType: data.sourceType,
      sourceId: data.sourceId,
      feeType: data.feeType,
      feeRateBps: data.feeRateBps,
      rateBasis: data.rateBasis,
      grossAmount: data.grossAmount,
      feeAmount: data.feeAmount,
      netAmount: data.netAmount,
      currency: data.currency.toUpperCase(),
      status: data.status,
      settlementState: data.settlementState,
      payoutState: data.payoutState || null,
      settlementId: data.settlementId || null,
      payoutId: data.payoutId || null,
      ledgerTransactionId: data.ledgerTransactionId || null,
      idempotencyKey: data.idempotencyKey,
      policySnapshot: data.policySnapshot,
      calculationTimestamp: data.calculationTimestamp,
      settlementTimestamp: null,
      createdAt: now,
      updatedAt: now,
      metadata: data.metadata || null,
      safeMetadata: data.safeMetadata || null,
    };

    try {
      // FeeAccrual columns only (feeSourceType, sourceAmount, rateBps,
      // rateReference); the rest of the accrual lives in metadata._fee. The
      // previous column names made Prisma reject every accrual.
      const created = await client.feeAccrual?.create({
        data: {
          id: accrual.id,
          tenantId: accrual.tenantId,
          feeType: accrual.feeType,
          feeSourceType: accrual.sourceType,
          sourceId: accrual.sourceId,
          sourceAmount: accrual.grossAmount,
          feeAmount: accrual.feeAmount,
          currency: accrual.currency,
          rateBps: accrual.feeRateBps ?? null,
          rateReference: accrual.rateBasis ?? null,
          status: accrual.status,
          settlementState: accrual.settlementState,
          settlementId: accrual.settlementId,
          settlementTimestamp: null,
          idempotencyKey: accrual.idempotencyKey,
          metadata: buildFeeAccrualMetadata(null, (accrual.metadata as any) ?? {}, {
            netAmount: accrual.netAmount,
            payoutState: accrual.payoutState,
            payoutId: accrual.payoutId,
            ledgerTransactionId: accrual.ledgerTransactionId,
            policySnapshot: accrual.policySnapshot,
            calculationTimestamp: new Date(accrual.calculationTimestamp).toISOString(),
          }) as any,
          safeMetadata: (accrual.safeMetadata ?? {}) as any,
          createdAt: new Date(accrual.createdAt),
        },
      });

      if (created) {
        return this.mapToDomain(created);
      }
      if (tx) {
        throw new Error('fee accrual was not persisted; refusing to append its outbox event');
      }
    } catch (error: any) {
      // A PostgreSQL transaction is aborted after a unique-constraint error;
      // let the caller retry instead of querying through a broken transaction.
      if ((error.code === 'P2002' || error.message?.includes('Unique constraint')) && tx) {
        throw error;
      }
      // Handle duplicate key (idempotency) for non-transactional callers.
      if (error.code === 'P2002' || error.message?.includes('Unique constraint')) {
        this.logger.warn(`Duplicate accrual detected, returning existing: ${data.idempotencyKey}`);
        const existing = await this.findByIdempotencyKey(data.idempotencyKey, data.tenantId);
        if (existing) return existing;
        const bySource = await this.findBySource(data.tenantId, data.sourceType, data.sourceId, data.feeType);
        if (bySource) return bySource;
      }

      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        if (tx) throw new Error('fee accrual table is unavailable inside the caller transaction');
        // Table doesn't exist - fallback to audit log storage but return domain object
        this.logger.warn(`feeAccrual table not found, using fallback storage: ${error.message}`);
        // Try to store in audit log as fallback for auditability
        try {
          await (this.prisma as any).auditLog?.create({
            data: {
              id: randomUUID(),
              tenantId: data.tenantId,
              action: 'FEE_ACCRUED',
              resourceType: 'FeeAccrual',
              resourceId: id,
              metadata: {
                ...accrual,
                fallback: true,
              },
              createdAt: new Date(),
            },
          });
        } catch {}
        return accrual;
      }

      this.logger.error(`Failed to create fee accrual: ${error.message}`, error.stack);
      throw error;
    }

    // Fallback if prisma model not available
    return accrual;
  }

  async findById(id: string, tenantId?: string): Promise<FeeAccrual | null> {
    try {
      const result = await (this.prisma as any).feeAccrual?.findFirst({
        where: {
          id,
          ...(tenantId ? { tenantId } : {}),
        },
      });
      if (!result) return null;
      return this.mapToDomain(result);
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        return null;
      }
      throw error;
    }
  }

  async findByIdempotencyKey(idempotencyKey: string, tenantId: string): Promise<FeeAccrual | null> {
    const result = await (this.prisma as any).feeAccrual?.findFirst({
      where: { idempotencyKey, tenantId },
    });
    if (!result) return null;
    return this.mapToDomain(result);
  }

  async findBySource(tenantId: string, sourceType: FeeSourceType, sourceId: string, feeType?: FeeType): Promise<FeeAccrual | null> {
    const result = await (this.prisma as any).feeAccrual?.findFirst({
      where: {
        tenantId,
        feeSourceType: sourceType,
        sourceId,
        ...(feeType ? { feeType } : {}),
      },
      orderBy: { createdAt: 'desc' },
    });
    if (!result) return null;
    return this.mapToDomain(result);
  }

  async listByTenant(
    tenantId: string,
    filter?: {
      feeType?: FeeType;
      sourceType?: FeeSourceType;
      status?: FeeAccrualStatus;
      settlementState?: SettlementState;
      currency?: string;
      fromDate?: Date;
      toDate?: Date;
      limit?: number;
      offset?: number;
    },
  ): Promise<FeeAccrual[]> {
    const where: any = { tenantId };
    if (filter?.feeType) where.feeType = filter.feeType;
    if (filter?.sourceType) where.feeSourceType = filter.sourceType;
    if (filter?.status) where.status = filter.status;
    if (filter?.settlementState) where.settlementState = filter.settlementState;
    if (filter?.currency) where.currency = filter.currency;
    if (filter?.fromDate || filter?.toDate) {
      where.createdAt = {};
      if (filter.fromDate) where.createdAt.gte = filter.fromDate;
      if (filter.toDate) where.createdAt.lte = filter.toDate;
    }

    const results = await (this.prisma as any).feeAccrual?.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: filter?.limit || 100,
      skip: filter?.offset || 0,
    });

    if (!results) return [];
    return results.map((r: any) => this.mapToDomain(r));
  }

  async listEligibleForSettlement(tenantId: string, currency?: string, feeType?: FeeType, limit?: number): Promise<FeeAccrual[]> {
    const where: any = {
      tenantId,
      status: FeeAccrualStatus.ACCRUED,
      settlementState: { in: [SettlementState.DRAFT, SettlementState.CALCULATED] },
    };
    if (currency) where.currency = currency;
    if (feeType) where.feeType = feeType;

    const results = await (this.prisma as any).feeAccrual?.findMany({
      where,
      orderBy: { createdAt: 'asc' },
      take: limit || 100,
    });

    if (!results) return [];
    return results.map((r: any) => this.mapToDomain(r));
  }

  async updateStatus(
    id: string,
    updates: {
      status?: FeeAccrualStatus;
      settlementState?: SettlementState;
      payoutState?: PayoutState | null;
      settlementId?: string | null;
      payoutId?: string | null;
      ledgerTransactionId?: string | null;
      settlementTimestamp?: string | null;
    },
  ): Promise<FeeAccrual | null> {
    try {
      const existing = await (this.prisma as any).feeAccrual?.findFirst({ where: { id } });
      if (!existing) return null;

      const data: any = {};
      if (updates.status) data.status = updates.status;
      if (updates.settlementState) data.settlementState = updates.settlementState;
      if (updates.settlementId !== undefined) data.settlementId = updates.settlementId;
      const extras: FeeAccrualExtras = {};
      if (updates.payoutState !== undefined) extras.payoutState = updates.payoutState;
      if (updates.payoutId !== undefined) extras.payoutId = updates.payoutId;
      if (updates.ledgerTransactionId !== undefined) extras.ledgerTransactionId = updates.ledgerTransactionId;
      if (Object.keys(extras).length > 0) data.metadata = buildFeeAccrualMetadata(existing.metadata, null, extras);
      if (updates.settlementTimestamp !== undefined) {
        data.settlementTimestamp = updates.settlementTimestamp ? new Date(updates.settlementTimestamp) : null;
      }

      const updated = await (this.prisma as any).feeAccrual?.update({
        where: { id },
        data,
      });

      if (!updated) return null;
      return this.mapToDomain(updated);
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        return null;
      }
      throw error;
    }
  }

  async aggregateByTenant(
    tenantId: string,
    filter?: { currency?: string; feeType?: FeeType; fromDate?: Date; toDate?: Date },
  ): Promise<{ totalFeeAmount: string; count: number; currency: string }> {
    const accruals = await this.listByTenant(tenantId, {
      currency: filter?.currency,
      feeType: filter?.feeType,
      fromDate: filter?.fromDate,
      toDate: filter?.toDate,
      limit: 1000,
    });

    let totalMinor = 0;
    let currency = filter?.currency || 'USD';
    const { parseToMinorUnits, formatFromMinorUnits, getMinorUnitForCurrency } = await import('../finance/money.types');

    for (const accrual of accruals) {
      if (!currency) currency = accrual.currency;
      try {
        const minor = parseToMinorUnits(accrual.feeAmount, accrual.currency);
        totalMinor += minor;
      } catch {}
    }

    return {
      totalFeeAmount: formatFromMinorUnits(totalMinor, currency),
      count: accruals.length,
      currency,
    };
  }

  private mapToDomain(raw: any): FeeAccrual {
    const metadata: Record<string, any> = raw.metadata && typeof raw.metadata === 'object' ? { ...raw.metadata } : {};
    const record: Record<string, any> = metadata[FEE_ACCRUAL_METADATA_KEY] && typeof metadata[FEE_ACCRUAL_METADATA_KEY] === 'object' ? metadata[FEE_ACCRUAL_METADATA_KEY] : {};
    delete metadata[FEE_ACCRUAL_METADATA_KEY];
    return {
      id: raw.id,
      tenantId: raw.tenantId,
      sourceType: raw.feeSourceType as FeeSourceType,
      sourceId: raw.sourceId,
      feeType: raw.feeType as FeeType,
      feeRateBps: raw.rateBps,
      rateBasis: raw.rateReference as RateBasis,
      grossAmount: raw.sourceAmount?.toString() || '0',
      feeAmount: raw.feeAmount?.toString() || '0',
      netAmount: record.netAmount?.toString() || '0',
      currency: raw.currency,
      status: raw.status as FeeAccrualStatus,
      settlementState: raw.settlementState as SettlementState,
      payoutState: (record.payoutState as PayoutState) || null,
      settlementId: raw.settlementId || null,
      payoutId: record.payoutId || null,
      ledgerTransactionId: record.ledgerTransactionId || null,
      idempotencyKey: raw.idempotencyKey,
      policySnapshot: record.policySnapshot,
      calculationTimestamp: record.calculationTimestamp
        ? new Date(record.calculationTimestamp).toISOString()
        : raw.createdAt
          ? new Date(raw.createdAt).toISOString()
          : new Date().toISOString(),
      settlementTimestamp: raw.settlementTimestamp ? new Date(raw.settlementTimestamp).toISOString() : null,
      createdAt: raw.createdAt ? new Date(raw.createdAt).toISOString() : new Date().toISOString(),
      updatedAt: raw.updatedAt ? new Date(raw.updatedAt).toISOString() : new Date().toISOString(),
      metadata: raw.metadata ? metadata : null,
      safeMetadata: raw.safeMetadata && Object.keys(raw.safeMetadata).length > 0 ? raw.safeMetadata : null,
    };
  }

}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { randomUUID } from 'crypto';

/**
 * Structured audit events for fee pipeline.
 * Never logs secrets: payout secrets, bank credentials, wallet private keys,
 * exchange API keys, payment provider secrets, access tokens.
 */

export enum FeeAuditOperation {
  FEE_POLICY_RESOLVED = 'FEE_POLICY_RESOLVED',
  FEE_CALCULATED = 'FEE_CALCULATED',
  FEE_ACCRUED = 'FEE_ACCRUED',
  FEE_ACCRUAL_REJECTED = 'FEE_ACCRUAL_REJECTED',
  FEE_LEDGER_POSTED = 'FEE_LEDGER_POSTED',
  FEE_LEDGER_POST_FAILED = 'FEE_LEDGER_POST_FAILED',
  SETTLEMENT_CREATED = 'SETTLEMENT_CREATED',
  SETTLEMENT_APPROVED = 'SETTLEMENT_APPROVED',
  SETTLEMENT_FINALIZED = 'SETTLEMENT_FINALIZED',
  SETTLEMENT_FAILED = 'SETTLEMENT_FAILED',
  PAYOUT_CREATED = 'PAYOUT_CREATED',
  PAYOUT_PROCESSING = 'PAYOUT_PROCESSING',
  PAYOUT_SUCCEEDED = 'PAYOUT_SUCCEEDED',
  PAYOUT_FAILED = 'PAYOUT_FAILED',
  PAYOUT_REVERSED = 'PAYOUT_REVERSED',
  PAYOUT_CANCELLED = 'PAYOUT_CANCELLED',
  FEE_RECONCILIATION_DETECTED = 'FEE_RECONCILIATION_DETECTED',
  FEE_RECONCILIATION_RESOLVED = 'FEE_RECONCILIATION_RESOLVED',
}

export interface FeeAuditRecord {
  id: string;
  tenantId: string;
  operation: FeeAuditOperation;
  referenceId: string;
  referenceType: string;
  status: string;
  amount: string | null;
  currency: string | null;
  metadata: Record<string, unknown> | null;
  actorId: string | null;
  timestamp: Date;
}

@Injectable()
export class FeeAuditService {
  private readonly logger = new Logger(FeeAuditService.name);

  constructor(private readonly prisma: PrismaService) {}

  private async log(input: {
    tenantId: string;
    operation: FeeAuditOperation;
    referenceId: string;
    referenceType: string;
    status: string;
    amount?: string;
    currency?: string;
    metadata?: Record<string, unknown>;
    actorId?: string;
  }): Promise<void> {
    const sanitized = this.sanitizeMetadata(input.metadata);

    try {
      await (this.prisma as any).feeAuditLog?.create({
        data: {
          id: randomUUID(),
          tenantId: input.tenantId,
          operation: input.operation,
          referenceId: input.referenceId,
          referenceType: input.referenceType,
          status: input.status,
          amount: input.amount || null,
          currency: input.currency || null,
          metadata: sanitized,
          actorId: input.actorId || null,
          timestamp: new Date(),
          createdAt: new Date(),
        },
      });
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        // Fallback to general audit log and console
        this.logger.log(`[FEE_AUDIT] ${input.operation} tenant=${input.tenantId} ref=${input.referenceId} status=${input.status} amount=${input.amount || ''} ${input.currency || ''}`);

        try {
          await (this.prisma as any).auditLog?.create({
            data: {
              id: randomUUID(),
              tenantId: input.tenantId,
              action: input.operation,
              resourceType: input.referenceType,
              resourceId: input.referenceId,
              metadata: sanitized,
              createdAt: new Date(),
            },
          });
        } catch {}
        return;
      }
      this.logger.warn(`Failed to create fee audit log: ${error.message}`);
    }
  }

  async logPolicyResolved(tenantId: string, feeType: string, platformBps: number, performanceBps: number, source: string): Promise<void> {
    await this.log({
      tenantId,
      operation: FeeAuditOperation.FEE_POLICY_RESOLVED,
      referenceId: `${tenantId}_${feeType}`,
      referenceType: 'FeePolicy',
      status: 'RESOLVED',
      metadata: { feeType, platformFeeBps: platformBps, performanceFeeBps: performanceBps, source },
    });
  }

  async logFeeCalculated(tenantId: string, sourceId: string, feeType: string, feeAmount: string, currency: string, rateBps: number): Promise<void> {
