      tenantId,
      operation: FeeAuditOperation.FEE_LEDGER_POST_FAILED,
      referenceId: accrualId,
      referenceType: 'FeeLedger',
      status: 'FAILED',
      metadata: { reason },
    });
  }

  async logSettlementCreated(tenantId: string, settlementId: string, amount: string, currency: string, accrualCount: number): Promise<void> {
    await this.log({
      tenantId,
      operation: FeeAuditOperation.SETTLEMENT_CREATED,
      referenceId: settlementId,
      referenceType: 'FeeSettlement',
      status: 'CREATED',
      amount,
      currency,
      metadata: { accrualCount },
    });
  }

  async logSettlementApproved(tenantId: string, settlementId: string, amount: string, currency: string): Promise<void> {
    await this.log({
      tenantId,
      operation: FeeAuditOperation.SETTLEMENT_APPROVED,
      referenceId: settlementId,
      referenceType: 'FeeSettlement',
      status: 'APPROVED',
      amount,
      currency,
    });
  }

  async logSettlementFinalized(tenantId: string, settlementId: string, amount: string, currency: string): Promise<void> {
    await this.log({
      tenantId,
      operation: FeeAuditOperation.SETTLEMENT_FINALIZED,
      referenceId: settlementId,
      referenceType: 'FeeSettlement',
      status: 'FINALIZED',
      amount,
      currency,
    });
  }

  async logPayoutCreated(tenantId: string, payoutId: string, settlementId: string, amount: string, currency: string): Promise<void> {
    await this.log({
      tenantId,
      operation: FeeAuditOperation.PAYOUT_CREATED,
      referenceId: payoutId,
      referenceType: 'Payout',
      status: 'CREATED',
      amount,
      currency,
      metadata: { settlementId },
    });
  }

  async logPayoutProcessing(tenantId: string, payoutId: string, settlementId: string, providerPayoutId: string): Promise<void> {
    await this.log({
      tenantId,
      operation: FeeAuditOperation.PAYOUT_PROCESSING,
      referenceId: payoutId,
      referenceType: 'Payout',
      status: 'PROCESSING',
      metadata: { settlementId, providerPayoutId },
    });
  }

  async logPayoutSucceeded(tenantId: string, payoutId: string, settlementId: string, amount: string, currency: string, providerPayoutId: string): Promise<void> {
    await this.log({
      tenantId,
      operation: FeeAuditOperation.PAYOUT_SUCCEEDED,
      referenceId: payoutId,
      referenceType: 'Payout',
      status: 'SUCCEEDED',
      amount,
      currency,
      metadata: { settlementId, providerPayoutId },
    });
  }

  async logPayoutFailed(tenantId: string, payoutId: string, settlementId: string, reason: string): Promise<void> {
    await this.log({
      tenantId,
      operation: FeeAuditOperation.PAYOUT_FAILED,
      referenceId: payoutId,
      referenceType: 'Payout',
      status: 'FAILED',
      metadata: { settlementId, reason },
    });
  }

  async logReconciliationDetected(tenantId: string, category: string, sourceId: string, description: string, severity: string): Promise<void> {
    await this.log({
      tenantId,
      operation: FeeAuditOperation.FEE_RECONCILIATION_DETECTED,
      referenceId: sourceId,
      referenceType: 'Reconciliation',
      status: severity,
      metadata: { category, description },
    });
  }

  async logReconciliationResolved(tenantId: string, category: string, sourceId: string, resolution: string): Promise<void> {
    await this.log({
      tenantId,
      operation: FeeAuditOperation.FEE_RECONCILIATION_RESOLVED,
      referenceId: sourceId,
      referenceType: 'Reconciliation',
      status: 'RESOLVED',
      metadata: { category, resolution },
    });
  }

  private sanitizeMetadata(metadata?: Record<string, unknown> | null): Record<string, unknown> | null {
    if (!metadata) return null;
    const forbidden = [
      'secret',
      'apiKey',
      'privateKey',
      'accessToken',
      'password',
      'exchangeSecret',
      'providerSecret',
      'bankAccount',
      'walletKey',
      'private_key',
      'credentials',
      'seed',
      'mnemonic',
      'stripeSecret',
      'webhookSecret',
      'bankCredentials',
      'signingSecret',
    ];
    const safe: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(metadata)) {
      const lowerKey = key.toLowerCase();
      if (forbidden.some((f) => lowerKey.includes(f.toLowerCase()))) {
        safe[key] = '[REDACTED]';
      } else {
        // Also check nested objects shallow
        if (value && typeof value === 'object' && !Array.isArray(value)) {
          const nested = value as Record<string, unknown>;
          const sanitizedNested: Record<string, unknown> = {};
          for (const [nk, nv] of Object.entries(nested)) {
            if (forbidden.some((f) => nk.toLowerCase().includes(f.toLowerCase()))) {
              sanitizedNested[nk] = '[REDACTED]';
            } else {
              sanitizedNested[nk] = nv;
            }
          }
          safe[key] = sanitizedNested;
        } else {
          safe[key] = value;
        }
      }
    }
    return safe;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { BillingLedgerService } from '../finance/billing-ledger.service';
import { BillingLedgerRepository } from '../finance/billing-ledger.repository';
import { LedgerAccountCategory, LedgerEntryType, LedgerSourceType } from '../finance/billing-ledger.types';
import { createMoney } from '../finance/money.types';
import { FeeAccrual, FeeType } from './fee.types';
import { FeeAuditService } from './fee-audit.service';

/**
 * Converts fee accruals into existing BillingLedger using balanced transactions.
 * Reuses BillingLedgerService - does NOT create another ledger implementation.
 * Every operation idempotent.
 */
@Injectable()
export class FeeLedgerService {
  private readonly logger = new Logger(FeeLedgerService.name);

  constructor(
    private readonly ledgerService: BillingLedgerService,
    private readonly ledgerRepository: BillingLedgerRepository,
    private readonly auditService: FeeAuditService,
  ) {}

  async postAccrualToLedger(accrual: FeeAccrual): Promise<any[]> {
    const idempotencyKey = `fee_ledger_${accrual.id}_${accrual.feeType}`;

    // Idempotency check
    try {
      const existing = await this.ledgerRepository.findBySource(LedgerSourceType.FEE, accrual.id);
      if (existing && existing.length > 0) {
        this.logger.log(`Idempotent ledger return for accrual ${accrual.id}`);
        return existing;
      }
      const byIdempotency = await this.ledgerRepository.findByIdempotencyKey(idempotencyKey, accrual.tenantId);
      if (byIdempotency) {
        this.logger.log(`Idempotent ledger return by idempotencyKey ${idempotencyKey}`);
        const bySource = await this.ledgerRepository.findBySource(LedgerSourceType.FEE, accrual.id);
        return bySource.length > 0 ? bySource : [byIdempotency];
      }
    } catch (e) {
      this.logger.warn(`Ledger idempotency check failed: ${(e as Error).message}`);
    }

    const feeMoney = createMoney(accrual.feeAmount, accrual.currency);
    const grossMoney = createMoney(accrual.grossAmount, accrual.currency);

    // Determine ledger account category based on fee type
    const feeAccountCategory =
      accrual.feeType === FeeType.PLATFORM_FEE ? LedgerAccountCategory.PLATFORM_FEE_REVENUE : LedgerAccountCategory.PERFORMANCE_FEE_REVENUE;

    // Balanced transaction:
    // Debit CUSTOMER_RECEIVABLE for fee amount
    // Credit FEE_REVENUE (PLATFORM or PERFORMANCE) for fee amount
    // This mirrors existing fee recording pattern in BillingLedgerService.recordFee

    try {
      const result = await this.ledgerService.recordFee({
        tenantId: accrual.tenantId,
        sourceId: accrual.id,
        sourceType: LedgerSourceType.FEE,
        amount: feeMoney,
        currency: accrual.currency,
        feeType: feeAccountCategory,
        idempotencyKey,
        metadata: {
          feeAccrualId: accrual.id,
          sourceType: accrual.sourceType,
          sourceId: accrual.sourceId,
          feeType: accrual.feeType,
          feeRateBps: accrual.feeRateBps,
          grossAmount: accrual.grossAmount,
          currency: accrual.currency,
          policySnapshot: accrual.policySnapshot,
          safeMetadata: accrual.safeMetadata,
        },
      });

      await this.auditService.logLedgerPosted(accrual.tenantId, accrual.id, accrual.feeType, accrual.feeAmount, accrual.currency, idempotencyKey);

      this.logger.log(`Fee ledger posted accrual=${accrual.id} feeType=${accrual.feeType} amount=${accrual.feeAmount} ${accrual.currency} tx=${idempotencyKey}`);

      return result;
    } catch (error: any) {
      this.logger.error(`Failed to post fee accrual ${accrual.id} to ledger: ${error.message}`, error.stack);
      await this.auditService.logLedgerPostingFailed(accrual.tenantId, accrual.id, error.message);
      throw error;
    }
  }

  async postAccrualsBatch(accruals: FeeAccrual[]): Promise<{ success: number; failed: number; results: any[] }> {
    let success = 0;
    let failed = 0;
    const results: any[] = [];

    for (const accrual of accruals) {
      try {
        const res = await this.postAccrualToLedger(accrual);
        success++;
        results.push({ accrualId: accrual.id, success: true, result: res });
      } catch (e) {
        failed++;
        results.push({ accrualId: accrual.id, success: false, error: (e as Error).message });
      }
    }

    return { success, failed, results };
  }

  async reverseAccrualInLedger(accrual: FeeAccrual, reason: string): Promise<any[]> {
    const idempotencyKey = `fee_reverse_${accrual.id}_${Date.now()}`;

    const feeMoney = createMoney(accrual.feeAmount, accrual.currency);
    const feeAccountCategory =
      accrual.feeType === FeeType.PLATFORM_FEE ? LedgerAccountCategory.PLATFORM_FEE_REVENUE : LedgerAccountCategory.PERFORMANCE_FEE_REVENUE;

    // Reversal: Debit fee revenue, Credit receivable (opposite of original)
    try {
      // Use recordCredit or custom transaction for reversal
      // For simplicity, we create a transaction with reversed entries
      const entries = [
        {
          tenantId: accrual.tenantId,
          accountCategory: feeAccountCategory,
          entryType: LedgerEntryType.DEBIT,
          amount: feeMoney,
          sourceType: LedgerSourceType.FEE,
          sourceId: accrual.id,
          idempotencyKey: `${idempotencyKey}_debit`,
          description: `Fee reversal: ${accrual.feeType} accrual ${accrual.id} reason: ${reason}`,
          metadata: {
            reversal: true,
            originalAccrualId: accrual.id,
            reason,
            feeType: accrual.feeType,
          },
        },
        {
          tenantId: accrual.tenantId,
          accountCategory: LedgerAccountCategory.CUSTOMER_RECEIVABLE,
          entryType: LedgerEntryType.CREDIT,
          amount: feeMoney,
          sourceType: LedgerSourceType.FEE,
          sourceId: accrual.id,
          idempotencyKey: `${idempotencyKey}_credit`,
          description: `Fee reversal receivable: ${accrual.id}`,
          metadata: {
            reversal: true,
            originalAccrualId: accrual.id,
            reason,
          },
        },
      ];

      const result = await this.ledgerRepository.createTransaction({
        tenantId: accrual.tenantId,
        description: `Fee reversal: ${accrual.id} reason: ${reason}`,
        entries,
        sourceType: LedgerSourceType.FEE,
        sourceId: accrual.id,
        idempotencyKey,
        metadata: { reversal: true, reason, originalAccrualId: accrual.id },
      });

      this.logger.log(`Fee reversal posted accrual=${accrual.id} reason=${reason}`);

      return result;
    } catch (e) {
      this.logger.error(`Failed to reverse accrual ${accrual.id}: ${(e as Error).message}`);
      throw e;
    }
  }

  async getLedgerEntriesForAccrual(accrualId: string, tenantId?: string): Promise<any[]> {
    const entries = await this.ledgerRepository.findBySource(LedgerSourceType.FEE, accrualId);
    if (tenantId) {
      return entries.filter((e: any) => e.tenantId === tenantId);
    }
    return entries;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { PlansService } from '../plans.service';
import { SubscriptionsService } from '../subscriptions.service';
import { FeeType, FeePolicySnapshot } from './fee.types';

/**
 * Resolves effective platform/performance fee policy from canonical plan/tenant configuration.
 * Never trusts client-provided rates, no hardcoded commercial percentages.
 * Plan configuration is canonical; tenant override only if explicitly supported in metadata.
 */
@Injectable()
export class FeePolicyService {
  private readonly logger = new Logger(FeePolicyService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly plansService: PlansService,
    private readonly subscriptionsService: SubscriptionsService,
  ) {}

  async resolvePolicy(tenantId: string, feeType: FeeType, currency?: string): Promise<FeePolicySnapshot> {
    // 1. Get tenant's current subscription and plan
    const subscription = await this.subscriptionsService.getCurrent(tenantId);
    let plan: any = null;
    let platformFeeBps = 0;
    let performanceFeeBps = 0;
    let planId: string | null = null;
    let planCode: string | null = null;
    let source: 'plan' | 'tenant_override' | 'global_policy' = 'global_policy';

    if (subscription) {
      try {
        plan = subscription.plan || null;
        if (!plan && subscription.planId) {
          // Try to fetch via plans service if not included
          try {
            const dto = await this.plansService.findById(subscription.planId, {
              tenantId: null,
              isPlatformUser: true,
            });
            plan = dto;
          } catch {
            // ignore, fallback to subscription plan fields if present
          }
        }

        if (plan) {
          platformFeeBps = plan.platformFeeBps ?? plan.limits?.platformFeeBps ?? 0;
          performanceFeeBps = plan.performanceFeeBps ?? plan.limits?.performanceFeeBps ?? 0;
          planId = plan.id || subscription.planId;
          planCode = plan.code || null;
          source = 'plan';
        }
      } catch (e) {
        this.logger.warn(`Failed to resolve plan for tenant ${tenantId}: ${(e as Error).message}`);
      }
    }

    // 2. Check for tenant-specific override if architecture explicitly supports it
    // Look into tenant.metadata.commercial or tenant.metadata.feePolicy
    let tenantOverrideApplied = false;
    try {
      const tenant = await this.prisma.tenant.findUnique({
        where: { id: tenantId },
        select: { metadata: true },
      });
      const metadata = tenant?.metadata as any;
      if (metadata) {
        // Explicitly supported override paths
        const commercialOverride = metadata.commercial || metadata.feePolicy || metadata.billingPolicy;
        if (commercialOverride && typeof commercialOverride === 'object') {
          // Only allow override if tenant has explicit flag allowFeeOverride
          const allowOverride = metadata.allowFeeOverride === true || commercialOverride.allowOverride === true;
          if (allowOverride) {
            if (feeType === FeeType.PLATFORM_FEE && typeof commercialOverride.platformFeeBps === 'number') {
              const overrideBps = this.validateBps(commercialOverride.platformFeeBps);
              if (overrideBps !== null) {
                platformFeeBps = overrideBps;
                tenantOverrideApplied = true;
                source = 'tenant_override';
                this.logger.log(`Tenant override applied for ${tenantId} platformFeeBps=${overrideBps}`);
              }
            }
            if (feeType === FeeType.PERFORMANCE_FEE && typeof commercialOverride.performanceFeeBps === 'number') {
              const overrideBps = this.validateBps(commercialOverride.performanceFeeBps);
              if (overrideBps !== null) {
                performanceFeeBps = overrideBps;
                tenantOverrideApplied = true;
                source = 'tenant_override';
                this.logger.log(`Tenant override applied for ${tenantId} performanceFeeBps=${overrideBps}`);
              }
            }
          }
        }
      }
    } catch (e) {
      this.logger.warn(`Failed to check tenant override for ${tenantId}: ${(e as Error).message}`);
    }

    // 3. Global platform policy fallback (if no plan)
    if (!plan && !tenantOverrideApplied) {
      // Try to get default platform policy from env or config
      // GLOBAL_PLATFORM_FEE_BPS / GLOBAL_PERFORMANCE_FEE_BPS, both defaulting to
      // 0: with no plan, no tenant override and no global setting, no fee is
      // charged. Commercial rates come from the plan catalog.
      const globalPlatformFee = parseInt(process.env.GLOBAL_PLATFORM_FEE_BPS || '0', 10);
      const globalPerformanceFee = parseInt(process.env.GLOBAL_PERFORMANCE_FEE_BPS || '0', 10);
      if (source === 'global_policy') {
        if (platformFeeBps === 0 && !isNaN(globalPlatformFee)) {
          platformFeeBps = globalPlatformFee;
        }
        if (performanceFeeBps === 0 && !isNaN(globalPerformanceFee)) {
          performanceFeeBps = globalPerformanceFee;
        }
      }
    }

    // Validate final BPS
    platformFeeBps = this.validateBps(platformFeeBps) ?? 0;
    performanceFeeBps = this.validateBps(performanceFeeBps) ?? 0;

    const effectiveBps = feeType === FeeType.PLATFORM_FEE ? platformFeeBps : performanceFeeBps;

    const snapshot: FeePolicySnapshot = {
      tenantId,
      planId,
      planCode,
      platformFeeBps,
      performanceFeeBps,
      currency: currency || 'USD',
      effectiveAt: new Date().toISOString(),
      source,
      minimumFee: null,
      maximumCap: null,
      metadata: {
        resolvedFeeType: feeType,
        effectiveBps,
        subscriptionId: subscription?.id || null,
      },
    };

    this.logger.log(
      `Fee policy resolved tenant=${tenantId} feeType=${feeType} plan=${planCode || 'none'} platformBps=${platformFeeBps} performanceBps=${performanceFeeBps} source=${source}`,
    );

    return snapshot;
  }

  async resolvePlatformFeePolicy(tenantId: string, currency?: string): Promise<FeePolicySnapshot> {
    return this.resolvePolicy(tenantId, FeeType.PLATFORM_FEE, currency);
  }

  async resolvePerformanceFeePolicy(tenantId: string, currency?: string): Promise<FeePolicySnapshot> {
    return this.resolvePolicy(tenantId, FeeType.PERFORMANCE_FEE, currency);
  }

  async getEffectiveRateBps(tenantId: string, feeType: FeeType): Promise<number> {
    const policy = await this.resolvePolicy(tenantId, feeType);
    return feeType === FeeType.PLATFORM_FEE ? policy.platformFeeBps : policy.performanceFeeBps;
  }

  private validateBps(bps: any): number | null {
    if (typeof bps !== 'number') return null;
    if (isNaN(bps)) return null;
    if (bps < 0 || bps > 10000) {
      this.logger.warn(`Invalid BPS ${bps}, must be 0-10000`);
      return null;
    }
    return Math.floor(bps);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { SettlementBatch, SettlementItem, SettlementState, FeeType } from './fee.types';
import { randomUUID } from 'crypto';

/**
 * Persistence abstraction for settlement batches, items, locks, status transitions.
 * Idempotent via idempotencyKey, prevents double settlement.
 */
@Injectable()
export class FeeSettlementRepository {
  private readonly logger = new Logger(FeeSettlementRepository.name);

  constructor(private readonly prisma: PrismaService) {}

  async createSettlement(data: {
    tenantId: string;
    currency: string;
    grossFeeAmount: string;
    adjustments?: string;
    finalSettlementAmount: string;
    numberOfAccruals: number;
    feeType: FeeType | 'MIXED';
    status: SettlementState;
    idempotencyKey: string;
    accrualIds: string[];
    metadata?: Record<string, unknown> | null;
  }): Promise<SettlementBatch> {
    // Idempotency check
    const existingByKey = await this.findByIdempotencyKey(data.idempotencyKey, data.tenantId);
    if (existingByKey) {
      this.logger.log(`Idempotent settlement return by idempotencyKey: ${data.idempotencyKey}`);
      return existingByKey;
    }

    const id = randomUUID();
    const now = new Date().toISOString();

    const settlement: SettlementBatch = {
      id,
      tenantId: data.tenantId,
      currency: data.currency.toUpperCase(),
      grossFeeAmount: data.grossFeeAmount,
      adjustments: data.adjustments || '0',
      finalSettlementAmount: data.finalSettlementAmount,
      numberOfAccruals: data.numberOfAccruals,
      feeType: data.feeType,
      status: data.status,
      idempotencyKey: data.idempotencyKey,
      accrualIds: data.accrualIds,
      createdAt: now,
      calculatedAt: data.status === SettlementState.CALCULATED || data.status === SettlementState.FINALIZED ? now : null,
      approvedAt: null,
      finalizedAt: data.status === SettlementState.FINALIZED ? now : null,
      paidAt: null,
      metadata: data.metadata || null,
    };

    try {
      const created = await (this.prisma as any).feeSettlement?.create({
        data: {
          id: settlement.id,
          tenantId: settlement.tenantId,
          currency: settlement.currency,
          grossFeeAmount: settlement.grossFeeAmount,
          adjustments: settlement.adjustments,
          finalSettlementAmount: settlement.finalSettlementAmount,
          numberOfAccruals: settlement.numberOfAccruals,
          feeType: settlement.feeType,
          status: settlement.status,
          idempotencyKey: settlement.idempotencyKey,
          accrualIds: settlement.accrualIds,
          createdAt: new Date(settlement.createdAt),
          approvedAt: null,
          finalizedAt: settlement.finalizedAt ? new Date(settlement.finalizedAt) : null,
          paidAt: null,
          // FeeSettlement has no calculatedAt column; it is kept in metadata.
          metadata: { ...(settlement.metadata ?? {}), calculatedAt: settlement.calculatedAt ?? null } as any,
        },
      });

      if (created) {
        // Create settlement items
        await this.createSettlementItems(id, data.accrualIds, data.tenantId, data.currency, data.feeType);

        return this.mapBatchToDomain(created);
      }
    } catch (error: any) {
      if (error.code === 'P2002') {
        this.logger.warn(`Duplicate settlement idempotency: ${data.idempotencyKey}`);
        const existing = await this.findByIdempotencyKey(data.idempotencyKey, data.tenantId);
        if (existing) return existing;
      }
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        this.logger.warn(`feeSettlement table not found, fallback: ${error.message}`);
        try {
          await (this.prisma as any).auditLog?.create({
            data: {
              id: randomUUID(),
              tenantId: data.tenantId,
              action: 'SETTLEMENT_CREATED',
              resourceType: 'FeeSettlement',
              resourceId: id,
              metadata: { ...settlement, fallback: true },
              createdAt: new Date(),
            },
          });
        } catch {}
        return settlement;
      }
      this.logger.error(`Failed to create settlement: ${error.message}`, error.stack);
      throw error;
    }

    return settlement;
  }

  private async createSettlementItems(settlementId: string, accrualIds: string[], tenantId: string, currency: string, feeType: FeeType | 'MIXED'): Promise<void> {
    try {
      // Fetch accruals to get fee amounts
      const accruals = await (this.prisma as any).feeAccrual?.findMany({
        where: { id: { in: accrualIds } },
      });

      if (!accruals || accruals.length === 0) {
        // Fallback: create items without amounts
        for (const accrualId of accrualIds) {
          try {
            await (this.prisma as any).feeSettlementItem?.create({
              data: {
                id: randomUUID(),
                settlementId,
                accrualId,
                tenantId,
                feeType: feeType === 'MIXED' ? 'PLATFORM_FEE' : feeType,
                feeAmount: '0',
                currency,
                status: SettlementState.DRAFT,
                createdAt: new Date(),
                updatedAt: new Date(),
              },
            });
          } catch {}
        }
        return;
      }

      for (const accrual of accruals) {
        try {
          await (this.prisma as any).feeSettlementItem?.create({
            data: {
              id: randomUUID(),
              settlementId,
              accrualId: accrual.id,
              tenantId,
              feeType: accrual.feeType,
              feeAmount: accrual.feeAmount?.toString() || '0',
              currency: accrual.currency,
              status: SettlementState.DRAFT,
              createdAt: new Date(),
              updatedAt: new Date(),
            },
          });
        } catch (e: any) {
          if (e.code !== 'P2002') {
            this.logger.warn(`Failed to create settlement item for accrual ${accrual.id}: ${e.message}`);
          }
        }
      }
    } catch (e) {
      this.logger.warn(`Failed to create settlement items: ${(e as Error).message}`);
    }
  }

  async findById(id: string, tenantId?: string): Promise<SettlementBatch | null> {
    const result = await (this.prisma as any).feeSettlement?.findFirst({
      where: { id, ...(tenantId ? { tenantId } : {}) },
    });
    if (!result) return null;
    return this.mapBatchToDomain(result);
  }

  async findByIdempotencyKey(idempotencyKey: string, tenantId: string): Promise<SettlementBatch | null> {
    const result = await (this.prisma as any).feeSettlement?.findFirst({
      where: { idempotencyKey, tenantId },
    });
    if (!result) return null;
    return this.mapBatchToDomain(result);
  }

  async listByTenant(
    tenantId: string,
    filter?: {
      status?: SettlementState;
      currency?: string;
      feeType?: FeeType | 'MIXED';
      fromDate?: Date;
      toDate?: Date;
      limit?: number;
      offset?: number;
    },
  ): Promise<SettlementBatch[]> {
    const where: any = { tenantId };
    if (filter?.status) where.status = filter.status;
    if (filter?.currency) where.currency = filter.currency;
    if (filter?.feeType) where.feeType = filter.feeType;
    if (filter?.fromDate || filter?.toDate) {
      where.createdAt = {};
      if (filter.fromDate) where.createdAt.gte = filter.fromDate;
      if (filter.toDate) where.createdAt.lte = filter.toDate;
    }

    const results = await (this.prisma as any).feeSettlement?.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: filter?.limit || 100,
      skip: filter?.offset || 0,
    });

    if (!results) return [];
    return results.map((r: any) => this.mapBatchToDomain(r));
  }

  async getSettlementItems(settlementId: string): Promise<SettlementItem[]> {
    const results = await (this.prisma as any).feeSettlementItem?.findMany({
      where: { settlementId },
      orderBy: { createdAt: 'asc' },
    });
    if (!results) return [];
    return results.map((r: any) => this.mapItemToDomain(r));
  }

  async updateStatus(
    id: string,
    status: SettlementState,
    extra?: { approvedAt?: string | null; finalizedAt?: string | null; paidAt?: string | null },
  ): Promise<SettlementBatch | null> {
    try {
      const data: any = { status, updatedAt: new Date() };
      if (extra?.approvedAt !== undefined) data.approvedAt = extra.approvedAt ? new Date(extra.approvedAt) : null;
      if (extra?.finalizedAt !== undefined) data.finalizedAt = extra.finalizedAt ? new Date(extra.finalizedAt) : null;
      if (extra?.paidAt !== undefined) data.paidAt = extra.paidAt ? new Date(extra.paidAt) : null;
      if (status === SettlementState.CALCULATED) {
        const existing = await (this.prisma as any).feeSettlement?.findUnique({ where: { id } });
        const current = existing?.metadata && typeof existing.metadata === 'object' ? existing.metadata : {};
        data.metadata = { ...current, calculatedAt: current.calculatedAt ?? new Date().toISOString() };
      }
      if (status === SettlementState.APPROVED && !data.approvedAt) data.approvedAt = new Date();
      if (status === SettlementState.FINALIZED && !data.finalizedAt) data.finalizedAt = new Date();
      if (status === SettlementState.PAID && !data.paidAt) data.paidAt = new Date();

      const updated = await (this.prisma as any).feeSettlement?.update({
        where: { id },
        data,
      });

      if (!updated) return null;
      return this.mapBatchToDomain(updated);
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) return null;
      throw error;
    }
  }

  private mapBatchToDomain(raw: any): SettlementBatch {
    return {
      id: raw.id,
      tenantId: raw.tenantId,
      currency: raw.currency,
      grossFeeAmount: raw.grossFeeAmount?.toString() || '0',
      adjustments: raw.adjustments?.toString() || '0',
      finalSettlementAmount: raw.finalSettlementAmount?.toString() || '0',
      numberOfAccruals: raw.numberOfAccruals,
      feeType: raw.feeType as FeeType | 'MIXED',
      status: raw.status as SettlementState,
      idempotencyKey: raw.idempotencyKey,
      accrualIds: raw.accrualIds || [],
      createdAt: raw.createdAt ? new Date(raw.createdAt).toISOString() : new Date().toISOString(),
      calculatedAt: raw.metadata?.calculatedAt ? new Date(raw.metadata.calculatedAt).toISOString() : null,
      approvedAt: raw.approvedAt ? new Date(raw.approvedAt).toISOString() : null,
      finalizedAt: raw.finalizedAt ? new Date(raw.finalizedAt).toISOString() : null,
      paidAt: raw.paidAt ? new Date(raw.paidAt).toISOString() : null,
      metadata: raw.metadata || null,
    };
  }

  private mapItemToDomain(raw: any): SettlementItem {
    return {
      id: raw.id,
      settlementId: raw.settlementId,
      accrualId: raw.accrualId,
      tenantId: raw.tenantId,
      feeType: raw.feeType as FeeType,
      feeAmount: raw.feeAmount?.toString() || '0',
      currency: raw.currency,
      status: raw.status as SettlementState,
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PayoutProvider } from './payout.types';
import { IPayoutProvider } from './payout-provider.interface';
import { StripeConnectPayoutProvider } from './stripe-connect-payout.provider';

/**
 * Selects configured payout provider using existing app config conventions.
 * Validates provider availability, fails safely if not configured, no secret exposure.
 * If no payout provider configured, reports explicit config error rather than fake success.
 */

class NoOpPayoutProvider implements IPayoutProvider {
  readonly providerName = PayoutProvider.NONE;

  isAvailable(): boolean {
    return false;
  }

  async createPayout(): Promise<any> {
    throw new Error('Payout provider not configured. Set PAYOUT_PROVIDER env variable to enable payouts. No fake success allowed.');
  }

  async getPayoutStatus(): Promise<any> {
    throw new Error('Payout provider not configured');
  }

  normalizeStatus(): any {
    return 'FAILED' as any;
  }
}

class ManualPayoutProvider implements IPayoutProvider {
  readonly providerName = PayoutProvider.MANUAL;
  private readonly logger = new Logger(ManualPayoutProvider.name);

  isAvailable(): boolean {
    return true;
  }

  async createPayout(input: any): Promise<any> {
    // Manual provider does not auto-execute, creates pending record for manual approval
    this.logger.log(`Manual payout created for settlement ${input.settlementId} amount ${input.amount} ${input.currency} beneficiary ${input.beneficiaryId}`);
    return {
      providerPayoutId: `manual_${input.settlementId}_${Date.now()}`,
      providerReference: `MANUAL-${input.tenantId.substring(0, 8)}`,
      status: 'PENDING' as any,
      rawResponse: { manual: true, requiresApproval: true },
    };
  }

  async getPayoutStatus(providerPayoutId: string): Promise<any> {
    // Manual provider always returns pending until manually marked succeeded
    return {
      providerPayoutId,
      status: 'PENDING' as any,
      rawResponse: { manual: true },
    };
  }

  normalizeStatus(providerStatus: string): any {
    const map: Record<string, string> = {
      pending: 'PENDING',
      processing: 'PROCESSING',
      succeeded: 'SUCCEEDED',
      failed: 'FAILED',
      cancelled: 'CANCELLED',
    };
    return (map[providerStatus.toLowerCase()] || 'PENDING') as any;
  }
}

class InternalPayoutProvider implements IPayoutProvider {
  readonly providerName = PayoutProvider.INTERNAL;
  private readonly logger = new Logger(InternalPayoutProvider.name);

  isAvailable(): boolean {
    return true;
  }

  async createPayout(input: any): Promise<any> {
    // Internal ledger transfer - no external provider, but still requires confirmation via internal state
    this.logger.log(`Internal payout ledger transfer settlement=${input.settlementId} amount=${input.amount}`);
    return {
      providerPayoutId: `internal_${input.settlementId}_${Date.now()}`,
      providerReference: `INTERNAL-${input.settlementId.substring(0, 8)}`,
      status: 'PROCESSING' as any,
      rawResponse: { internal: true },
    };
  }

  async getPayoutStatus(providerPayoutId: string): Promise<any> {
    // Internal transfers succeed after processing
    return {
      providerPayoutId,
      status: 'SUCCEEDED' as any,
      processedAt: new Date().toISOString(),
      rawResponse: { internal: true, confirmed: true },
    };
  }

  normalizeStatus(providerStatus: string): any {
    return providerStatus === 'SUCCEEDED' ? 'SUCCEEDED' : 'PROCESSING';
  }
}

@Injectable()
export class PayoutProviderFactory {
  private readonly logger = new Logger(PayoutProviderFactory.name);
  private readonly configuredProvider: PayoutProvider;

  constructor() {
    const providerRaw = (process.env.PAYOUT_PROVIDER || process.env.BILLING_PAYOUT_PROVIDER || 'none').toLowerCase();
    this.configuredProvider = this.parseProvider(providerRaw);
    this.logger.log(`Configured payout provider: ${this.configuredProvider}`);
  }

  getProvider(provider?: PayoutProvider): IPayoutProvider {
    const target = provider || this.configuredProvider;

    if (target === PayoutProvider.NONE) {
      this.logger.warn('Payout provider NONE configured - payouts will fail with config error, no fake success');
      return new NoOpPayoutProvider();
    }

    switch (target) {
      case PayoutProvider.MANUAL:
        return new ManualPayoutProvider();
      case PayoutProvider.INTERNAL:
        return new InternalPayoutProvider();
      case PayoutProvider.STRIPE: {
        // Stripe Connect Transfers to the beneficiary's connected account.
        // Without a usable secret key it fails closed (NoOp) instead of
        // falling back to a provider that could report the payout as paid.
        const stripe = new StripeConnectPayoutProvider();
        if (!stripe.isAvailable()) {
          this.logger.error('STRIPE payout requested but STRIPE_SECRET_KEY (sk_/rk_) is not configured');
          return new NoOpPayoutProvider();
        }
        return stripe;
      }
      case PayoutProvider.BANK_TRANSFER:
      case PayoutProvider.CRYPTO:
        // No bank or crypto payout adapter ships in this build: fail closed.
        this.logger.warn(`Payout provider ${target} not fully configured, returning NoOp`);
        return new NoOpPayoutProvider();
      default:
        this.logger.error(`Unsupported payout provider: ${target}`);
        return new NoOpPayoutProvider();
    }
  }

  getDefaultProvider(): IPayoutProvider {
    return this.getProvider();
  }

  isProviderAvailable(provider: PayoutProvider): boolean {
    try {
      const p = this.getProvider(provider);
      return p.isAvailable();
    } catch {
      return false;
    }
  }

  validateProviderConfiguration(): { configured: boolean; provider: PayoutProvider; message: string } {
    const provider = this.getProvider();
    const available = provider.isAvailable();
    return {
      configured: available,
      provider: this.configuredProvider,
      message: available
        ? `Payout provider ${this.configuredProvider} is configured`
        : `Payout provider not configured (current: ${this.configuredProvider}). Set PAYOUT_PROVIDER to manual|internal|stripe. No fake success allowed.`,
    };
  }

  private parseProvider(raw: string): PayoutProvider {
    switch (raw) {
      case 'stripe':
        return PayoutProvider.STRIPE;
      case 'manual':
        return PayoutProvider.MANUAL;
      case 'bank_transfer':
      case 'bank':
        return PayoutProvider.BANK_TRANSFER;
      case 'crypto':
        return PayoutProvider.CRYPTO;
      case 'internal':
        return PayoutProvider.INTERNAL;
      case 'none':
      case '':
      default:
        return PayoutProvider.NONE;
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { OutboxService } from '../../../infrastructure/outbox/outbox.service';
import { Payout, PayoutStatus, PayoutProvider, BeneficiaryType, PayoutDestination } from './payout.types';
import { randomUUID } from 'crypto';

/**
 * Persistent payout records, provider references, beneficiary mapping,
 * idempotency, status transitions, tenant-scoped payout history.
 * Protects finalized records from illegal mutation.
 */
@Injectable()
export class PayoutRepository {
  private readonly logger = new Logger(PayoutRepository.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly outbox: OutboxService,
  ) {}

  async create(data: {
    settlementId: string;
    beneficiaryId: string;
    beneficiaryType: BeneficiaryType;
    tenantId: string;
    amount: string;
    currency: string;
    destination: PayoutDestination;
    provider: PayoutProvider;
    providerPayoutId?: string | null;
    providerReference?: string | null;
    status: PayoutStatus;
    failureReason?: string | null;
    idempotencyKey: string;
    metadata?: Record<string, unknown> | null;
    safeMetadata?: Record<string, unknown> | null;
  }): Promise<Payout> {
    // Idempotency check
    const existingByKey = await this.findByIdempotencyKey(data.idempotencyKey, data.tenantId);
    if (existingByKey) {
      this.logger.log(`Idempotent payout return by idempotencyKey: ${data.idempotencyKey}`);
      return existingByKey;
    }

    const existingBySettlement = await this.findBySettlement(data.settlementId);
    if (existingBySettlement && existingBySettlement.length > 0) {
      // Check if same beneficiary and amount already exists for this settlement
      const duplicate = existingBySettlement.find((p) => p.beneficiaryId === data.beneficiaryId && p.amount === data.amount && p.currency === data.currency);
      if (duplicate) {
        this.logger.log(`Idempotent payout return by settlement+beneficiary: settlement=${data.settlementId} beneficiary=${data.beneficiaryId}`);
        return duplicate;
      }
    }

    const id = randomUUID();
    const now = new Date().toISOString();

    const payout: Payout = {
      id,
      settlementId: data.settlementId,
      beneficiaryId: data.beneficiaryId,
      beneficiaryType: data.beneficiaryType,
      tenantId: data.tenantId,
      amount: data.amount,
      currency: data.currency.toUpperCase(),
      destination: data.destination,
      provider: data.provider,
      providerPayoutId: data.providerPayoutId || null,
      providerReference: data.providerReference || null,
      status: data.status,
      failureReason: data.failureReason || null,
      idempotencyKey: data.idempotencyKey,
      requestedAt: now,
      processedAt: null,
      succeededAt: null,
      failedAt: null,
      cancelledAt: null,
      metadata: data.metadata || null,
      safeMetadata: data.safeMetadata || null,
      createdAt: now,
      updatedAt: now,
    };

    try {
      const created = await (this.prisma as any).payout?.create({
        data: {
          id: payout.id,
          settlementId: payout.settlementId,
          beneficiaryId: payout.beneficiaryId,
          beneficiaryType: payout.beneficiaryType,
          tenantId: payout.tenantId,
          amount: payout.amount,
          currency: payout.currency,
          destination: payout.destination as any,
          provider: payout.provider,
          providerPayoutId: payout.providerPayoutId,
          providerReference: payout.providerReference,
          status: payout.status,
          failureReason: payout.failureReason,
          idempotencyKey: payout.idempotencyKey,
          processedAt: null,
          succeededAt: null,
          failedAt: null,
          cancelledAt: null,
          metadata: (payout.metadata ?? {}) as any,
          safeMetadata: (payout.safeMetadata ?? {}) as any,
          // Payout has no requestedAt column: the request time is the row's createdAt.
          createdAt: new Date(payout.requestedAt ?? payout.createdAt),
          updatedAt: new Date(payout.updatedAt),
        },
      });

      if (created) {
        return this.mapToDomain(created);
      }
    } catch (error: any) {
      if (error.code === 'P2002') {
        this.logger.warn(`Duplicate payout idempotency: ${data.idempotencyKey}`);
        const existing = await this.findByIdempotencyKey(data.idempotencyKey, data.tenantId);
        if (existing) return existing;
      }
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        this.logger.warn(`payout table not found, fallback: ${error.message}`);
        try {
          await (this.prisma as any).auditLog?.create({
            data: {
              id: randomUUID(),
              tenantId: data.tenantId,
              action: 'PAYOUT_CREATED',
              resourceType: 'Payout',
              resourceId: id,
              metadata: { ...payout, fallback: true },
              createdAt: new Date(),
            },
          });
        } catch {}
        return payout;
      }
      this.logger.error(`Failed to create payout: ${error.message}`, error.stack);
      throw error;
    }

    return payout;
  }

  async findById(id: string, tenantId?: string): Promise<Payout | null> {
    const result = await (this.prisma as any).payout?.findFirst({
      where: { id, ...(tenantId ? { tenantId } : {}) },
    });
    if (!result) return null;
    return this.mapToDomain(result);
  }

  async findByIdempotencyKey(idempotencyKey: string, tenantId: string): Promise<Payout | null> {
    const result = await (this.prisma as any).payout?.findFirst({
      where: { idempotencyKey, tenantId },
    });
    if (!result) return null;
    return this.mapToDomain(result);
  }

  async findBySettlement(settlementId: string): Promise<Payout[]> {
    const results = await (this.prisma as any).payout?.findMany({
      where: { settlementId },
      orderBy: { createdAt: 'desc' },
    });
    if (!results) return [];
    return results.map((r: any) => this.mapToDomain(r));
  }

  async findByProviderReference(providerPayoutId: string): Promise<Payout | null> {
    const result = await (this.prisma as any).payout?.findFirst({
      where: { providerPayoutId },
    });
    if (!result) return null;
    return this.mapToDomain(result);
  }

  async listByTenant(
    tenantId: string,
    filter?: {
      status?: PayoutStatus;
      provider?: PayoutProvider;
      beneficiaryId?: string;
      currency?: string;
      fromDate?: Date;
      toDate?: Date;
      limit?: number;
      offset?: number;
    },
  ): Promise<Payout[]> {
    const where: any = { tenantId };
    if (filter?.status) where.status = filter.status;
    if (filter?.provider) where.provider = filter.provider;
    if (filter?.beneficiaryId) where.beneficiaryId = filter.beneficiaryId;
    if (filter?.currency) where.currency = filter.currency;
    if (filter?.fromDate || filter?.toDate) {
      where.createdAt = {};
      if (filter.fromDate) where.createdAt.gte = filter.fromDate;
      if (filter.toDate) where.createdAt.lte = filter.toDate;
    }

    const results = await (this.prisma as any).payout?.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: filter?.limit || 100,
      skip: filter?.offset || 0,
    });

    if (!results) return [];
    return results.map((r: any) => this.mapToDomain(r));
  }

  async updateStatus(
    id: string,
    updates: {
      status?: PayoutStatus;
      providerPayoutId?: string | null;
      providerReference?: string | null;
      failureReason?: string | null;
      processedAt?: string | null;
      succeededAt?: string | null;
      failedAt?: string | null;
      cancelledAt?: string | null;
    },
  ): Promise<Payout | null> {
    try {
      const snapshot = await (this.prisma as any).payout?.findFirst({ where: { id } });
      if (!snapshot) return null;

      return await this.prisma.withTenantRls(snapshot.tenantId, async (tx) => {
        const existing = await tx.payout.findFirst({ where: { id, tenantId: snapshot.tenantId } });
        if (!existing) return null;

        // Protect finalized records from illegal mutation.
        if (existing.status === PayoutStatus.SUCCEEDED) {
          if (updates.status && updates.status !== PayoutStatus.SUCCEEDED && updates.status !== PayoutStatus.REVERSED) {
            throw new Error(`Cannot mutate SUCCEEDED payout ${id} to ${updates.status}`);
          }
        }
        if (existing.status === PayoutStatus.REVERSED) {
          throw new Error(`Cannot mutate REVERSED payout ${id}`);
        }

        const now = new Date();
        const data: Record<string, unknown> = { updatedAt: now };
        if (updates.status) data.status = updates.status;
        if (updates.providerPayoutId !== undefined) data.providerPayoutId = updates.providerPayoutId;
        if (updates.providerReference !== undefined) data.providerReference = updates.providerReference;
        if (updates.failureReason !== undefined) data.failureReason = updates.failureReason;
        if (updates.processedAt !== undefined) data.processedAt = updates.processedAt ? new Date(updates.processedAt) : null;
        if (updates.succeededAt !== undefined) data.succeededAt = updates.succeededAt ? new Date(updates.succeededAt) : null;
        if (updates.failedAt !== undefined) data.failedAt = updates.failedAt ? new Date(updates.failedAt) : null;
        if (updates.cancelledAt !== undefined) data.cancelledAt = updates.cancelledAt ? new Date(updates.cancelledAt) : null;

        // Auto-set timestamps based on the requested state.
        if (updates.status === PayoutStatus.PROCESSING && !data.processedAt) data.processedAt = now;
        if (updates.status === PayoutStatus.SUCCEEDED && !data.succeededAt) data.succeededAt = now;
        if (updates.status === PayoutStatus.FAILED && !data.failedAt) data.failedAt = now;
        if (updates.status === PayoutStatus.CANCELLED && !data.cancelledAt) data.cancelledAt = now;

        const transition = await tx.payout.updateMany({
          where: { id, tenantId: snapshot.tenantId, status: existing.status },
          data,
        });
        if (transition.count !== 1) return null;

        const updated = await tx.payout.findFirst({ where: { id, tenantId: snapshot.tenantId } });
        if (!updated) throw new Error('payout row disappeared inside its tenant transaction');
        if (updated.status === PayoutStatus.SUCCEEDED) {
          await this.outbox.append(tx, {
            tenantId: snapshot.tenantId,
            aggregateType: 'payout',
            aggregateId: updated.id,
            eventType: 'payout.completed',
            idempotencyKey: `payout:${updated.id}:completed`,
            payload: {
              payoutId: updated.id,
              settlementId: updated.settlementId,
              beneficiaryType: updated.beneficiaryType,
              beneficiaryId: updated.beneficiaryId,
              amount: updated.amount,
              currency: updated.currency,
              status: PayoutStatus.SUCCEEDED,
            },
          });
        }
        return this.mapToDomain(updated);
      });
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) return null;
      throw error;
    }
  }

  private mapToDomain(raw: any): Payout {
    return {
      id: raw.id,
      settlementId: raw.settlementId,
      beneficiaryId: raw.beneficiaryId,
      beneficiaryType: raw.beneficiaryType as BeneficiaryType,
      tenantId: raw.tenantId,
      amount: raw.amount?.toString() || '0',
      currency: raw.currency,
      destination: raw.destination as PayoutDestination,
      provider: raw.provider as PayoutProvider,
      providerPayoutId: raw.providerPayoutId || null,
      providerReference: raw.providerReference || null,
      status: raw.status as PayoutStatus,
      failureReason: raw.failureReason || null,
      idempotencyKey: raw.idempotencyKey,
      requestedAt: raw.createdAt ? new Date(raw.createdAt).toISOString() : new Date().toISOString(),
      processedAt: raw.processedAt ? new Date(raw.processedAt).toISOString() : null,
      succeededAt: raw.succeededAt ? new Date(raw.succeededAt).toISOString() : null,
      failedAt: raw.failedAt ? new Date(raw.failedAt).toISOString() : null,
      cancelledAt: raw.cancelledAt ? new Date(raw.cancelledAt).toISOString() : null,
      metadata: raw.metadata || null,
      safeMetadata: raw.safeMetadata || null,
      createdAt: raw.createdAt ? new Date(raw.createdAt).toISOString() : new Date().toISOString(),
      updatedAt: raw.updatedAt ? new Date(raw.updatedAt).toISOString() : new Date().toISOString(),
    };
  }
}

import {
