} from './stripe-connect-payout.provider';
import { BeneficiaryType, CreatePayoutInput, PayoutStatus } from './payout.types';

const input = (overrides: Partial<CreatePayoutInput> = {}): CreatePayoutInput => ({
  settlementId: 'set_1',
