      line1: string;
      line2?: string;
      city: string;
      region?: string;
      postalCode?: string;
      country: string;
    };
    taxId?: string;
  };
  lineItems: Array<{
    description: string;
    quantity: number;
    unitPrice: string;
    amount: string;
    type: string;
  }>;
  totals: {
    subtotal: string;
    discountTotal: string;
    taxTotal: string;
    total: string;
    amountPaid: string;
    amountDue: string;
    amountRefunded: string;
