      billingPeriod: {
        start: invoice.billingPeriodStart ? invoice.billingPeriodStart.toISOString().split('T')[0] : null,
        end: invoice.billingPeriodEnd ? invoice.billingPeriodEnd.toISOString().split('T')[0] : null,
