    <div class="totals-row"><span>Amount Paid:</span><span>${this.escapeHtml(data.totals.amountPaid)} ${this.escapeHtml(data.totals.currency)}</span></div>
    <div class="totals-row"><span>Amount Due:</span><span>${this.escapeHtml(data.totals.amountDue)} ${this.escapeHtml(data.totals.currency)}</span></div>
    ${parseFloat(data.totals.amountRefunded) > 0 ? `<div class="totals-row"><span>Refunded:</span><span>${this.escapeHtml(data.totals.amountRefunded)} ${this.escapeHtml(data.totals.currency)}</span></div>` : ''}
  </div>

  ${data.taxSummary.length > 0 ? `
  <div style="margin-top: 30px;">
    <h4>Tax Breakdown</h4>
    ${data.taxSummary.map(tax => `
      <div>${this.escapeHtml(tax.jurisdiction || 'Tax')} (${tax.rate}%): ${this.escapeHtml(tax.taxAmount)} on ${this.escapeHtml(tax.taxableAmount)}</div>
    `).join('')}
  </div>
  ` : ''}

  ${data.paymentReference ? `
  <div style="margin-top: 20px;">
    <strong>Payment Reference:</strong> ${this.escapeHtml(data.paymentReference.paymentId)} via ${this.escapeHtml(data.paymentReference.provider)}
    ${data.paymentReference.paidAt ? ` on ${this.escapeHtml(data.paymentReference.paidAt)}` : ''}
  </div>
  ` : ''}

  <div class="footer">
    ${data.notes ? `<div>${this.escapeHtml(data.notes)}</div>` : ''}
    ${data.terms ? `<div style="margin-top: 10px;">${this.escapeHtml(data.terms)}</div>` : ''}
    <div style="margin-top: 20px;">Invoice generated on ${new Date().toISOString()} - This is a computer generated document</div>
  </div>
</body>
</html>
    `.trim();
  }

  private async getInvoiceWithDetails(invoiceId: string, tenantId: string): Promise<any | null> {
    try {
      const invoice = await (this.prisma as any).invoice?.findFirst({
        where: { id: invoiceId, tenantId },
        include: { lines: true },
      });
      return invoice;
    } catch {
      // Fallback: try without tenant check for development
      const invoice = await (this.prisma as any).invoice?.findUnique({
        where: { id: invoiceId },
        include: { lines: true },
      });
      if (invoice && invoice.tenantId === tenantId) {
        return invoice;
      }
      return null;
    }
  }

  private async getInvoiceLineItems(invoice: any): Promise<InvoicePdfData['lineItems']> {
    if (invoice.lines && Array.isArray(invoice.lines)) {
      return invoice.lines.map((line: any) => ({
        description: line.description,
        quantity: line.quantity,
        unitPrice: line.unitPrice,
        amount: line.amount,
        type: line.type,
      }));
    }

    // Fallback: construct from invoice totals
    return [
      {
        description: `${invoice.planName || 'Subscription'} - ${invoice.billingInterval || 'Monthly'}`,
        quantity: 1,
        unitPrice: invoice.subtotal,
        amount: invoice.subtotal,
        type: 'SUBSCRIPTION',
      },
    ];
  }

  private async getTaxSummary(invoice: any): Promise<InvoicePdfData['taxSummary']> {
    if (invoice.taxSummary && Array.isArray(invoice.taxSummary)) {
      return invoice.taxSummary;
    }

    if (parseFloat(invoice.taxTotal) > 0) {
      return [
        {
          rate: '0',
          taxableAmount: invoice.subtotal,
          taxAmount: invoice.taxTotal,
          jurisdiction: 'Tax',
        },
      ];
    }

    return [];
  }

  private async getTenantBranding(tenantId: string): Promise<any | null> {
    const branding = await this.prisma.tenantBranding.findUnique({
      where: { tenantId },
      select: {
        appName: true,
        logoUrl: true,
        primaryColor: true,
        supportEmail: true,
      },
    });
    return branding;
  }

  private async getTenantInfo(tenantId: string): Promise<any | null> {
    const tenant = await this.prisma.tenant.findUnique({
      where: { id: tenantId },
      select: {
        id: true,
        name: true,
        slug: true,
        legalName: true,
        contactEmail: true,
      },
    });
    return tenant;
  }

  private escapeHtml(text: string): string {
    if (!text) return '';
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }
}

// # Responsibility: persist and read invoice records through the API repository boundary.
import { Injectable, Logger, Optional } from '@nestjs/common';
import { randomUUID } from 'node:crypto';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { OutboxService } from '../../../infrastructure/outbox/outbox.service';
import type { InvoiceRecord, InvoiceFilter, CreateInvoiceInput, UpdateInvoiceInput, InvoiceStatus } from './invoice.types';
import { AppException } from '../../../common/errors/app.exception';
import { ErrorCode } from '@wlct/shared-types';

/**
 * Invoice columns hold the amounts, status, dates and the JSON documents
 * (customer, lines, taxSummary, metadata). Record fields without a column are
 * kept in `metadata._invoice` and stripped again on read. `lines` is a JSON
 * column, not a relation: the previous nested `lines.create` / `include`
 * made Prisma reject every invoice write and read.
 */
export const INVOICE_RECORD_METADATA_KEY = '_invoice';

export interface InvoiceRecordExtras {
  customerId?: string | null;
  billingPeriodStart?: string | null;
  billingPeriodEnd?: string | null;
  billingInterval?: string | null;
  discountTotal?: string | null;
  amountCredited?: string | null;
  providerInvoiceId?: string | null;
  planCode?: string | null;
  planName?: string | null;
  paymentReference?: unknown;
}

function invoiceObject(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' && !Array.isArray(value) ? { ...(value as Record<string, unknown>) } : {};
}

function invoiceIso(value: Date | string | null | undefined): string | null {
  if (value === null || value === undefined || value === '') return null;
  return value instanceof Date ? value.toISOString() : new Date(value).toISOString();
}

/** Metadata JSON for a write: caller metadata (replacing the stored one when given) plus merged record fields. */
export function buildInvoiceMetadata(
  existing: unknown,
  userMetadata: Record<string, unknown> | null | undefined,
  extras: InvoiceRecordExtras,
): Record<string, unknown> {
  const current = invoiceObject(existing);
  const stored = invoiceObject(current[INVOICE_RECORD_METADATA_KEY]);
  const user = userMetadata ? invoiceObject(userMetadata) : current;
  delete user[INVOICE_RECORD_METADATA_KEY];
  for (const [key, value] of Object.entries(extras)) {
    if (value !== undefined) stored[key] = value;
  }
  return { ...user, [INVOICE_RECORD_METADATA_KEY]: stored };
}

/**
 * Persistence abstraction for invoices, invoice lines, invoice numbers,
 * status transitions, payment associations, and tenant-scoped invoice queries.
 *
 * Requirements:
 *  - tenant isolation
 *  - concurrency-safe number generation
 *  - no duplicate invoice for the same successful payment
 *  - immutable finalized invoice history where required
 */

@Injectable()
export class InvoiceRepository {
  private readonly logger = new Logger(InvoiceRepository.name);

  constructor(
    private readonly prisma: PrismaService,
    @Optional() private readonly outbox?: OutboxService,
  ) {}

  async create(input: CreateInvoiceInput): Promise<InvoiceRecord> {
    try {
      // Idempotency check: if invoice with same idempotency key exists, return it
      const existingByIdempotency = await this.findByIdempotencyKey(input.idempotencyKey, input.tenantId);
      if (existingByIdempotency) {
        this.logger.log(`Idempotent invoice creation: returning existing invoice ${existingByIdempotency.id} for key ${input.idempotencyKey}`);
        return existingByIdempotency;
      }

      // Check for duplicate invoice for same payment
      if (input.paymentId) {
        const existingByPayment = await this.findByPaymentId(input.paymentId);
        if (existingByPayment) {
          this.logger.log(`Duplicate invoice prevention: payment ${input.paymentId} already has invoice ${existingByPayment.id}`);
          return existingByPayment;
        }
      }

      // Calculate totals from lines using precise decimal handling
      const totals = this.calculateTotalsFromLines(input.lines, input.currency);

      if (!this.outbox) {
        throw new Error('Transactional outbox is unavailable; refusing invoice creation without its invoice.created event');
      }
      const invoice = await this.prisma.withTenantRls(input.tenantId, async (tx) => {
        const created = await (tx as any).invoice.create({
          data: {
          id: this.generateId(),
          invoiceNumber: await this.generateInvoiceNumber(input.tenantId),
          tenantId: input.tenantId,
          subscriptionId: input.subscriptionId || null,
          paymentId: input.paymentId || null,
          currency: input.currency,
          status: 'DRAFT',
          issuedAt: input.issueDate || new Date(),
          dueDate: input.dueDate || null,
          subtotal: totals.subtotal,
          taxTotal: totals.taxTotal,
          total: totals.total,
          amountPaid: '0',
          amountDue: totals.total,
          amountRefunded: '0',
          provider: input.provider || null,
          planId: input.planId || null,
          idempotencyKey: input.idempotencyKey,
          customer: (input.customer ?? {}) as any,
          taxSummary: (input.taxSummary ?? []) as any,
          metadata: buildInvoiceMetadata(null, (input.metadata as any) ?? {}, {
            customerId: input.customerId || null,
            billingPeriodStart: invoiceIso(input.billingPeriod?.start),
            billingPeriodEnd: invoiceIso(input.billingPeriod?.end),
            billingInterval: input.billingPeriod?.interval || null,
            discountTotal: totals.discountTotal,
            amountCredited: '0',
            providerInvoiceId: input.providerInvoiceId || null,
            planCode: input.planCode || null,
            planName: input.planName || null,
            paymentReference: input.paymentReference ?? null,
          }) as any,
          lines: input.lines.map((line) => ({
            id: this.generateId(),
            type: line.type,
            description: line.description,
            quantity: line.quantity,
            unitPrice: line.unitPrice.amount,
            amount: line.amount.amount,
            discountType: line.discountType || null,
            discountValue: line.discountValue || null,
            discountAmount: line.discountAmount?.amount || null,
            taxRate: line.taxRate || null,
            taxAmount: line.taxAmount?.amount || null,
            metadata: line.metadata || null,
            planId: line.planId || null,
            subscriptionId: line.subscriptionId || null,
            billingPeriodStart: invoiceIso(line.billingPeriodStart as any),
            billingPeriodEnd: invoiceIso(line.billingPeriodEnd as any),
          })) as any,
          },
        });
        if (!created) {
          throw new AppException({ code: ErrorCode.INTERNAL_SERVER_ERROR, message: 'Invoice persistence is unavailable' });
        }
        await this.outbox!.append(tx, {
          tenantId: input.tenantId,
          aggregateType: 'invoice',
          aggregateId: created.id,
          eventType: 'invoice.created',
          idempotencyKey: `invoice:${created.id}:created`,
          correlationId: created.id,
          occurredAt: created.createdAt,
          payload: {
            invoiceId: created.id,
            amount: created.total,
            currency: created.currency,
            status: created.status,
          },
        });
        return created;
      });

      return this.mapToInvoiceRecord(invoice);
    } catch (error) {
      if ((error as any).code === 'P2002') {
        // Unique constraint violation - try to find existing
        const existing = await this.findByIdempotencyKey(input.idempotencyKey, input.tenantId);
        if (existing) return existing;
      }

      this.logger.error(`Failed to create invoice: ${(error as Error).message}`);
      throw new AppException({
        code: ErrorCode.INTERNAL_SERVER_ERROR,
        message: 'Failed to create invoice',
      });
    }
  }

  async findById(id: string, tenantId?: string): Promise<InvoiceRecord | null> {
    const where: any = { id };
    if (tenantId) where.tenantId = tenantId;
    const invoice = await (this.prisma as any).invoice?.findUnique({
      where,
    });
    if (invoice) {
      // If tenantId provided, double-check isolation even when using findUnique
      if (tenantId && invoice.tenantId !== tenantId) return null;
      return this.mapToInvoiceRecord(invoice);
    }
    // Fallback to findFirst for tenant isolation
    if (tenantId) {
      const invoiceFirst = await (this.prisma as any).invoice?.findFirst({
        where: { id, tenantId },
        });
      if (invoiceFirst) return this.mapToInvoiceRecord(invoiceFirst);
    }
    return null;
  }

  async findByInvoiceNumber(invoiceNumber: string): Promise<InvoiceRecord | null> {
    const invoice = await (this.prisma as any).invoice?.findFirst({
      where: { invoiceNumber },
    });
    if (invoice) return this.mapToInvoiceRecord(invoice);
    return null;
  }

  async findByPaymentId(paymentId: string): Promise<InvoiceRecord | null> {
    const invoice = await (this.prisma as any).invoice?.findFirst({
      where: { paymentId },
      orderBy: { createdAt: 'desc' },
    });
    if (invoice) return this.mapToInvoiceRecord(invoice);
    return null;
  }

  async findByIdempotencyKey(idempotencyKey: string, tenantId?: string): Promise<InvoiceRecord | null> {
    const invoice = await (this.prisma as any).invoice?.findFirst({
      where: { idempotencyKey, tenantId },
      orderBy: { createdAt: 'desc' },
    });
    if (invoice) return this.mapToInvoiceRecord(invoice);
    return null;
  }

  async list(filter: InvoiceFilter): Promise<InvoiceRecord[]> {
    const where: any = {};
    if (filter.tenantId) where.tenantId = filter.tenantId;
    const jsonFilters: any[] = [];
    if (filter.customerId) jsonFilters.push({ metadata: { path: [INVOICE_RECORD_METADATA_KEY, 'customerId'], equals: filter.customerId } });
    if (filter.subscriptionId) where.subscriptionId = filter.subscriptionId;
    if (filter.paymentId) where.paymentId = filter.paymentId;
    if (filter.status) where.status = filter.status;
    if (filter.currency) where.currency = filter.currency;
    if (filter.planId) where.planId = filter.planId;
    if (filter.invoiceNumber) where.invoiceNumber = filter.invoiceNumber;
    if (filter.billingInterval) {
      jsonFilters.push({ metadata: { path: [INVOICE_RECORD_METADATA_KEY, 'billingInterval'], equals: filter.billingInterval } });
    }
    if (jsonFilters.length > 0) where.AND = jsonFilters;

    if (filter.fromDate || filter.toDate) {
      where.issuedAt = {};
      if (filter.fromDate) where.issuedAt.gte = filter.fromDate;
      if (filter.toDate) where.issuedAt.lte = filter.toDate;
    }

    const invoices = await (this.prisma as any).invoice?.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: 100,
    });

    if (invoices) {
      return invoices.map((inv: any) => this.mapToInvoiceRecord(inv));
    }
    return [];
  }

  async update(id: string, input: UpdateInvoiceInput): Promise<InvoiceRecord> {
    try {
      const owner = await (this.prisma as any).invoice?.findUnique({
        where: { id },
        select: { tenantId: true },
      });
      if (!owner?.tenantId) throw new AppException({ code: ErrorCode.NOT_FOUND, message: 'Invoice not found' });

      return await this.prisma.withTenantRls(owner.tenantId, async (tx) => {
        const invoiceStore = tx as any;
        const existing = await invoiceStore.invoice.findFirst({ where: { id, tenantId: owner.tenantId } });
        if (!existing) throw new AppException({ code: ErrorCode.NOT_FOUND, message: 'Invoice not found' });

        const updateData: any = {};
        if (input.status) updateData.status = input.status;
        if (input.dueDate !== undefined) updateData.dueDate = input.dueDate;
        if (input.amountPaid !== undefined) updateData.amountPaid = input.amountPaid;
        if (input.amountDue !== undefined) updateData.amountDue = input.amountDue;
        if (input.amountRefunded !== undefined) updateData.amountRefunded = input.amountRefunded;
        const extras: InvoiceRecordExtras = {};
        if (input.amountCredited) extras.amountCredited = input.amountCredited;
        if (input.providerInvoiceId) extras.providerInvoiceId = input.providerInvoiceId;
        if (Object.keys(extras).length > 0 || input.metadata) {
          updateData.metadata = buildInvoiceMetadata(existing.metadata, (input.metadata as any) ?? null, extras);
        }
        if (input.finalizedAt !== undefined) updateData.finalizedAt = input.finalizedAt;
        if (input.paidAt !== undefined) updateData.paidAt = input.paidAt;
        if (input.voidedAt !== undefined) updateData.voidedAt = input.voidedAt;

        const invoice = await invoiceStore.invoice.update({ where: { id }, data: updateData });
        if (input.status === 'PAID' && existing.status !== 'PAID') {
          if (!this.outbox) {
            throw new Error('Transactional outbox is unavailable; refusing invoice payment without its invoice.paid event');
          }
          await this.outbox.append(tx, {
            tenantId: invoice.tenantId,
            aggregateType: 'invoice',
            aggregateId: invoice.id,
            eventType: 'invoice.paid',
            idempotencyKey: `invoice:${invoice.id}:paid`,
            correlationId: invoice.paymentId && invoice.paymentId.length <= 64 ? invoice.paymentId : invoice.id,
            occurredAt: invoice.paidAt ?? invoice.updatedAt,
            payload: {
              invoiceId: invoice.id,
              amount: invoice.amountPaid,
              currency: invoice.currency,
              status: invoice.status,
            },
          });
        }
        return this.mapToInvoiceRecord(invoice);
      });
    } catch (error) {
      if (error instanceof AppException) throw error;
      this.logger.error(`Failed to update invoice ${id}: ${(error as Error).message}`);
      throw new AppException({
        code: ErrorCode.INTERNAL_SERVER_ERROR,
        message: 'Failed to update invoice',
      });
    }
  }

  async updateStatus(id: string, status: InvoiceStatus): Promise<InvoiceRecord> {
    const updateData: any = { status };
    const now = new Date();

    if (status === 'FINALIZED' as any) updateData.finalizedAt = now;
    if (status === 'PAID' as any) updateData.paidAt = now;
    if (status === 'VOID' as any) updateData.voidedAt = now;

    return this.update(id, updateData);
  }

  async findByTenant(tenantId: string): Promise<InvoiceRecord[]> {
    return this.list({ tenantId });
  }

  private calculateTotalsFromLines(lines: any[], currency: string): { subtotal: string; discountTotal: string; taxTotal: string; total: string } {
    let subtotalMinor = 0;
    let discountMinor = 0;
    let taxMinor = 0;

    const getMinorUnit = (curr: string): number => {
      const map: Record<string, number> = { USD: 2, EUR: 2, GBP: 2, JPY: 0, BTC: 8, ETH: 18, USDT: 6, USDC: 6 };
      return map[curr.toUpperCase()] ?? 2;
    };

    const parseToMinor = (amount: string, curr: string): number => {
      const minorUnit = getMinorUnit(curr);
      const factor = Math.pow(10, minorUnit);
      return Math.round(parseFloat(amount) * factor);
    };

    const formatFromMinor = (minor: number, curr: string): string => {
      const minorUnit = getMinorUnit(curr);
      const factor = Math.pow(10, minorUnit);
      return (minor / factor).toFixed(minorUnit);
    };

    for (const line of lines) {
      const amountStr = typeof line.amount === 'string' ? line.amount : line.amount?.amount || '0';
      const amountMinor = parseToMinor(amountStr, currency);

      if (line.type === 'DISCOUNT' || line.type === 'CREDIT') {
        discountMinor += amountMinor;
      } else if (line.type === 'TAX') {
        taxMinor += amountMinor;
      } else {
        subtotalMinor += amountMinor;
      }

      if (line.discountAmount) {
        const discStr = typeof line.discountAmount === 'string' ? line.discountAmount : line.discountAmount?.amount || '0';
        discountMinor += parseToMinor(discStr, currency);
      }

      if (line.taxAmount) {
        const taxStr = typeof line.taxAmount === 'string' ? line.taxAmount : line.taxAmount?.amount || '0';
        taxMinor += parseToMinor(taxStr, currency);
      }
    }

    const totalMinor = subtotalMinor - discountMinor + taxMinor;

    return {
      subtotal: formatFromMinor(subtotalMinor, currency),
      discountTotal: formatFromMinor(discountMinor, currency),
      taxTotal: formatFromMinor(taxMinor, currency),
      total: formatFromMinor(totalMinor, currency),
    };
  }

  private async generateInvoiceNumber(tenantId: string): Promise<string> {
    // Delegate to invoice-number service in production, here generate simple unique
    const prefix = 'INV';
    const timestamp = Date.now().toString().slice(-8);
    const random = Math.random().toString(36).substring(2, 6).toUpperCase();
    return `${prefix}-${timestamp}-${random}`;
  }

  private mapToInvoiceRecord(prismaInvoice: any): InvoiceRecord {
    const metadata = invoiceObject(prismaInvoice.metadata);
    const extras = invoiceObject(metadata[INVOICE_RECORD_METADATA_KEY]);
    delete metadata[INVOICE_RECORD_METADATA_KEY];
    const text = (value: unknown): string | null => (typeof value === 'string' && value !== '' ? value : null);
    const date = (value: unknown): Date | null => (text(value) ? new Date(value as string) : null);
    return {
      id: prismaInvoice.id,
      invoiceNumber: prismaInvoice.invoiceNumber,
      tenantId: prismaInvoice.tenantId,
      customerId: text(extras.customerId) as any,
      subscriptionId: prismaInvoice.subscriptionId || null,
      paymentId: prismaInvoice.paymentId || null,
      currency: prismaInvoice.currency,
      status: prismaInvoice.status as InvoiceStatus,
      issueDate: prismaInvoice.issuedAt ?? prismaInvoice.createdAt,
      dueDate: prismaInvoice.dueDate || null,
      billingPeriodStart: date(extras.billingPeriodStart),
      billingPeriodEnd: date(extras.billingPeriodEnd),
      billingInterval: text(extras.billingInterval) as any,
      subtotal: prismaInvoice.subtotal,
      discountTotal: text(extras.discountTotal) ?? '0',
      taxTotal: prismaInvoice.taxTotal,
      total: prismaInvoice.total,
      amountPaid: prismaInvoice.amountPaid,
      amountDue: prismaInvoice.amountDue,
      amountRefunded: prismaInvoice.amountRefunded,
      amountCredited: text(extras.amountCredited) ?? '0',
      provider: prismaInvoice.provider || null,
      providerInvoiceId: text(extras.providerInvoiceId),
      planId: prismaInvoice.planId || null,
      planCode: text(extras.planCode),
      planName: text(extras.planName),
      idempotencyKey: prismaInvoice.idempotencyKey,
      metadata: prismaInvoice.metadata ? metadata : null,
      finalizedAt: prismaInvoice.finalizedAt || null,
      paidAt: prismaInvoice.paidAt || null,
      voidedAt: prismaInvoice.voidedAt || null,
      createdAt: prismaInvoice.createdAt,
      updatedAt: prismaInvoice.updatedAt,
    };
  }

  private generateId(): string {
    try {
      return randomUUID();
    } catch {
      return `${Date.now()}-${Math.random().toString(36).substring(2, 15)}`;
    }
  }
}

/**
 * Canonical monetary types, currency handling, Decimal-safe arithmetic boundaries,
 * rounding modes, minor-unit conversion, and money comparison helpers.
 *
 * Requirements:
 *  - precise decimal-safe representation
 *  - Never use JavaScript floating-point arithmetic for ledger totals
 *  - Compatible with Prisma Decimal conventions
 *  - Support basis-point and percentage calculations
 */

export enum Currency {
  USD = 'USD',
  EUR = 'EUR',
  GBP = 'GBP',
  JPY = 'JPY',
  CAD = 'CAD',
  AUD = 'AUD',
  BTC = 'BTC',
  ETH = 'ETH',
  USDT = 'USDT',
  USDC = 'USDC',
}

export enum RoundingMode {
  HALF_UP = 'HALF_UP',
  HALF_DOWN = 'HALF_DOWN',
  HALF_EVEN = 'HALF_EVEN',
  UP = 'UP',
  DOWN = 'DOWN',
  CEILING = 'CEILING',
  FLOOR = 'FLOOR',
}

export interface Money {
  amount: string;
  currency: string;
  minorUnit: number;
}

export interface MoneyWithCurrency extends Money {
  currency: Currency | string;
}

export interface Percentage {
  basisPoints: number;
  percent: string;
}

export const ZERO_DECIMAL_CURRENCIES = new Set(['JPY', 'KRW', 'VND', 'CLP', 'PYG', 'RWF', 'UGX', 'VUV', 'XAF', 'XOF', 'XPF', 'BTC', 'ETH']);

export const CURRENCY_MINOR_UNITS: Record<string, number> = {
  USD: 2,
  EUR: 2,
  GBP: 2,
  JPY: 0,
  CAD: 2,
  AUD: 2,
  BTC: 8,
  ETH: 18,
  USDT: 6,
  USDC: 6,
};

export function getMinorUnitForCurrency(currency: string): number {
  return CURRENCY_MINOR_UNITS[currency.toUpperCase()] ?? 2;
}

export function isZeroDecimalCurrency(currency: string): boolean {
  return ZERO_DECIMAL_CURRENCIES.has(currency.toUpperCase());
}

export function createMoney(amount: string, currency: string): Money {
  const minorUnit = getMinorUnitForCurrency(currency);
  return {
    amount: normalizeAmount(amount, minorUnit),
    currency: currency.toUpperCase(),
    minorUnit,
  };
}

export function normalizeAmount(amount: string, minorUnit: number): string {
  if (!amount) return '0';
  const parsed = amount.toString().trim();
  if (parsed === '' || isNaN(parseFloat(parsed))) {
    throw new Error(`Invalid amount: ${amount}`);
  }
  const factor = Math.pow(10, minorUnit);
  const integerValue = Math.round(parseFloat(parsed) * factor);
  return (integerValue / factor).toFixed(minorUnit);
}

export function parseToMinorUnits(amount: string, currency: string): number {
  const minorUnit = getMinorUnitForCurrency(currency);
  const factor = Math.pow(10, minorUnit);
  const parsed = parseFloat(amount);
  if (isNaN(parsed)) {
    throw new Error(`Invalid amount: ${amount}`);
  }
  return Math.round(parsed * factor);
}

export function formatFromMinorUnits(minorUnits: number, currency: string): string {
  const minorUnit = getMinorUnitForCurrency(currency);
  const factor = Math.pow(10, minorUnit);
  return (minorUnits / factor).toFixed(minorUnit);
}

export function addMoney(a: Money, b: Money): Money {
  if (a.currency !== b.currency) {
    throw new Error(`Currency mismatch: ${a.currency} vs ${b.currency}`);
  }
  const aMinor = parseToMinorUnits(a.amount, a.currency);
  const bMinor = parseToMinorUnits(b.amount, b.currency);
  const resultMinor = aMinor + bMinor;
  return {
    amount: formatFromMinorUnits(resultMinor, a.currency),
    currency: a.currency,
    minorUnit: a.minorUnit,
  };
}

export function subtractMoney(a: Money, b: Money): Money {
  if (a.currency !== b.currency) {
    throw new Error(`Currency mismatch: ${a.currency} vs ${b.currency}`);
  }
  const aMinor = parseToMinorUnits(a.amount, a.currency);
  const bMinor = parseToMinorUnits(b.amount, b.currency);
  const resultMinor = aMinor - bMinor;
  return {
    amount: formatFromMinorUnits(resultMinor, a.currency),
    currency: a.currency,
    minorUnit: a.minorUnit,
  };
}

export function multiplyMoneyByDecimal(money: Money, multiplier: string, roundingMode: RoundingMode = RoundingMode.HALF_UP): Money {
  const multiplierFloat = parseFloat(multiplier);
  if (isNaN(multiplierFloat)) {
    throw new Error(`Invalid multiplier: ${multiplier}`);
  }
  const minorUnits = parseToMinorUnits(money.amount, money.currency);
  let resultMinor: number;

  switch (roundingMode) {
    case RoundingMode.UP:
      resultMinor = Math.ceil(minorUnits * multiplierFloat);
      break;
    case RoundingMode.DOWN:
    case RoundingMode.FLOOR:
      resultMinor = Math.floor(minorUnits * multiplierFloat);
      break;
    case RoundingMode.CEILING:
      resultMinor = Math.ceil(minorUnits * multiplierFloat);
      break;
    case RoundingMode.HALF_UP:
    default:
      resultMinor = Math.round(minorUnits * multiplierFloat);
      break;
  }

  return {
    amount: formatFromMinorUnits(resultMinor, money.currency),
    currency: money.currency,
    minorUnit: money.minorUnit,
  };
}

export function calculatePercentageAmount(money: Money, basisPoints: number, roundingMode: RoundingMode = RoundingMode.HALF_UP): Money {
  if (basisPoints < 0 || basisPoints > 10000) {
    throw new Error(`Invalid basis points: ${basisPoints}, must be 0-10000`);
  }
  const multiplier = (basisPoints / 10000).toString();
  return multiplyMoneyByDecimal(money, multiplier, roundingMode);
}

export function calculateTaxAmount(taxableAmount: Money, taxRateBasisPoints: number): Money {
  return calculatePercentageAmount(taxableAmount, taxRateBasisPoints, RoundingMode.HALF_UP);
}

export function compareMoney(a: Money, b: Money): number {
  if (a.currency !== b.currency) {
    throw new Error(`Currency mismatch: ${a.currency} vs ${b.currency}`);
  }
  const aMinor = parseToMinorUnits(a.amount, a.currency);
  const bMinor = parseToMinorUnits(b.amount, b.currency);
  if (aMinor < bMinor) return -1;
  if (aMinor > bMinor) return 1;
  return 0;
}

export function isMoneyZero(money: Money): boolean {
  return parseToMinorUnits(money.amount, money.currency) === 0;
}

export function isMoneyPositive(money: Money): boolean {
  return parseToMinorUnits(money.amount, money.currency) > 0;
}

export function isMoneyNegative(money: Money): boolean {
  return parseToMinorUnits(money.amount, money.currency) < 0;
}

export function isMoneyGreaterThan(a: Money, b: Money): boolean {
  return compareMoney(a, b) > 0;
}

export function isMoneyLessThan(a: Money, b: Money): boolean {
  return compareMoney(a, b) < 0;
}

export function isMoneyEqual(a: Money, b: Money): boolean {
  return compareMoney(a, b) === 0;
}

export function sumMoney(moneyArray: Money[]): Money {
  if (moneyArray.length === 0) {
    throw new Error('Cannot sum empty money array');
  }
  const currency = moneyArray[0].currency;
  let totalMinor = 0;
  for (const money of moneyArray) {
    if (money.currency !== currency) {
      throw new Error(`Currency mismatch in sum: ${currency} vs ${money.currency}`);
    }
    totalMinor += parseToMinorUnits(money.amount, money.currency);
  }
  return {
    amount: formatFromMinorUnits(totalMinor, currency),
    currency,
    minorUnit: getMinorUnitForCurrency(currency),
  };
}

export function absoluteMoney(money: Money): Money {
  const minorUnits = parseToMinorUnits(money.amount, money.currency);
  return {
    amount: formatFromMinorUnits(Math.abs(minorUnits), money.currency),
    currency: money.currency,
    minorUnit: money.minorUnit,
  };
}

export function negateMoney(money: Money): Money {
  const minorUnits = parseToMinorUnits(money.amount, money.currency);
  return {
    amount: formatFromMinorUnits(-minorUnits, money.currency),
    currency: money.currency,
    minorUnit: money.minorUnit,
  };
}

export function validateMoney(money: Money): void {
  if (!money.amount) {
    throw new Error('Money amount required');
  }
  if (!money.currency) {
    throw new Error('Money currency required');
  }
  const parsed = parseFloat(money.amount);
  if (isNaN(parsed)) {
    throw new Error(`Invalid money amount: ${money.amount}`);
  }
}

export function moneyToPrismaDecimal(money: Money): string {
  return money.amount;
}

export function prismaDecimalToMoney(decimal: any, currency: string): Money {
  const amount = typeof decimal === 'string' ? decimal : decimal?.toString() || '0';
  return createMoney(amount, currency);
}

import { Injectable, Logger, Optional, Inject, forwardRef } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { PaymentService } from '../payments/payment.service';
import { PaymentProviderFactory } from '../payments/payment-provider.factory';
import { BillingLedgerService } from './billing-ledger.service';
import { InvoiceRepository } from './invoice.repository';
import { InvoiceService } from './invoice.service';
import { FinanceAuditService } from './finance.audit';
import { BillingEventService } from '../notifications/billing-event.service';
import type { CreateRefundInput, RefundRecord, RefundFilter, RefundableAmount, ProviderRefundResult } from './refund.types';
import { RefundStatus, RefundType, RefundReason, isValidRefundTransition } from './refund.types';
import type { Money } from './money.types';
import { createMoney, parseToMinorUnits, formatFromMinorUnits, compareMoney, isMoneyZero, isMoneyNegative } from './money.types';

import { randomUUID } from 'crypto';

/**
 * Implements Payment -> Refund Validation -> Provider Refund -> Refund Record
 * -> Payment State Update -> Invoice Adjustment -> Ledger Reversal -> Audit
 *
 * Requirements:
 *  - refundable amount calculation (payment total - already refunded)
 *  - never exceed refundable
 *  - capability check (provider supports refunds)
 *  - provider refund execution
 *  - concurrency-safe (no duplicate refund exceeding refundable)
 *  - prevent duplicate refund records
 *  - preserve immutable history (audit trail)
 *  - never mark completed before provider confirms
 *  - ledger reversal entry on successful refund
 *  - invoice adjustment if linked
 *  - payment state update
 */

@Injectable()
export class RefundService {
  private readonly logger = new Logger(RefundService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly paymentService: PaymentService,
    private readonly providerFactory: PaymentProviderFactory,
    private readonly ledgerService: BillingLedgerService,
    private readonly invoiceRepository: InvoiceRepository,
    private readonly invoiceService: InvoiceService,
    private readonly auditService: FinanceAuditService,
    @Optional()
    @Inject(forwardRef(() => BillingEventService))
    private readonly billingEventService?: BillingEventService,
  ) {}

  async createRefund(input: CreateRefundInput): Promise<RefundRecord> {
    this.validateRefundInput(input);

    // Idempotency check
    const existingByIdempotency = await this.findByIdempotencyKey(input.idempotencyKey, input.tenantId);
    if (existingByIdempotency) {
      this.logger.log(`Idempotent refund return: ${input.idempotencyKey}`);
      return existingByIdempotency;
    }

    // Get canonical payment
    const payment = await this.getPaymentRecord(input.paymentId);
    if (!payment) {
      throw new Error(`Payment not found: ${input.paymentId}`);
    }

    if (payment.tenantId !== input.tenantId) {
      throw new Error(`Payment ${input.paymentId} does not belong to tenant ${input.tenantId}`);
    }

    // Validate payment status allows refund
    if (payment.status !== 'SUCCEEDED') {
      throw new Error(`Cannot refund payment with status ${payment.status}, must be SUCCEEDED`);
    }

    // Calculate refundable amount with concurrency protection
    const refundable = await this.calculateRefundableAmount(input.paymentId, input.tenantId);

    if (isMoneyZero(refundable.refundableAmount)) {
      throw new Error(`Payment ${input.paymentId} has no refundable amount remaining`);
    }

    // Determine refund amount
    let refundAmount: Money;
    if (input.refundType === RefundType.FULL) {
      refundAmount = refundable.refundableAmount;
    } else {
      if (!input.amount) {
        throw new Error('Amount required for partial refund');
      }
      refundAmount = input.amount;

      if (isMoneyNegative(refundAmount) || isMoneyZero(refundAmount)) {
        throw new Error('Refund amount must be positive');
      }

      if (compareMoney(refundAmount, refundable.refundableAmount) > 0) {
        throw new Error(`Refund amount ${refundAmount.amount} exceeds refundable ${refundable.refundableAmount.amount}`);
      }

      if (refundAmount.currency !== refundable.currency) {
        throw new Error(`Refund currency ${refundAmount.currency} does not match payment currency ${refundable.currency}`);
      }
    }

    // Check provider capability
    let adapter: any;
    try {
      adapter = this.providerFactory.getProvider(payment.provider as any);
    } catch {
      throw new Error(`No adapter for provider ${payment.provider}`);
    }
    if (!adapter) {
      throw new Error(`No adapter for provider ${payment.provider}`);
    }

    // Create refund record as PENDING
    const refundRecord = await this.createRefundRecord({
      ...input,
      amount: refundAmount,
    });

    await this.auditService.logRefundRequested(input.tenantId, refundRecord.id, input.paymentId, refundAmount.amount, refundAmount.currency, input.reason);

    // Execute provider refund within transaction to prevent race conditions
    try {
      const providerResult = await this.executeProviderRefund(payment, refundRecord, refundAmount);

      // Update refund record based on provider result
      const updatedRecord = await this.updateRefundFromProviderResult(refundRecord.id, providerResult);

      if (updatedRecord.status === RefundStatus.SUCCEEDED) {
        // Update payment record with refunded amount
        await this.updatePaymentRefundedAmount(input.paymentId, refundAmount);

        // Invoice adjustment if linked
        if (input.invoiceId) {
          await this.adjustInvoiceForRefund(input.invoiceId, refundAmount, input.tenantId);
        }

        // Ledger reversal
        await this.ledgerService.recordRefund({
          tenantId: input.tenantId,
          refundId: refundRecord.id,
          paymentId: input.paymentId,
          invoiceId: input.invoiceId || undefined,
          amount: refundAmount,
          currency: refundAmount.currency,
          reason: input.reason,
          idempotencyKey: `refund_ledger_${refundRecord.id}`,
          metadata: { refundType: input.refundType },
        });

        await this.auditService.logRefundSucceeded(input.tenantId, refundRecord.id, input.paymentId, refundAmount.amount, refundAmount.currency);

        if (this.billingEventService) {
          this.billingEventService.onRefundSucceeded({
            tenantId: input.tenantId,
            refundId: refundRecord.id,
            paymentId: input.paymentId,
            amount: refundAmount.amount,
            currency: refundAmount.currency,
            supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
            appName: process.env.APP_NAME || 'WLCT',
          }).catch((e) => this.logger.warn(`Failed to trigger refund succeeded notification: ${e.message}`));
        }
      } else if (updatedRecord.status === RefundStatus.FAILED) {
        await this.auditService.logRefundFailed(input.tenantId, refundRecord.id, input.paymentId, providerResult.failureReason || 'Unknown failure');
        if (this.billingEventService) {
          this.billingEventService.onRefundFailed({
            tenantId: input.tenantId,
            refundId: refundRecord.id,
            paymentId: input.paymentId,
            amount: refundAmount.amount,
            currency: refundAmount.currency,
            supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
            appName: process.env.APP_NAME || 'WLCT',
          }).catch((e) => this.logger.warn(`Failed to trigger refund failed notification: ${e.message}`));
        }
      }

      return updatedRecord;
    } catch (error) {
      // Mark refund as failed
      await this.markRefundFailed(refundRecord.id, (error as Error).message);

      await this.auditService.logRefundFailed(input.tenantId, refundRecord.id, input.paymentId, (error as Error).message);

      throw error;
    }
  }

  async getRefundById(id: string, tenantId?: string): Promise<RefundRecord | null> {
    const result = await (this.prisma as any).refund?.findFirst({
      where: {
        id,
        ...(tenantId ? { tenantId } : {}),
      },
    });

    if (!result) return null;

    return this.mapToRefundRecord(result);
  }

  async findByIdempotencyKey(idempotencyKey: string, tenantId: string): Promise<RefundRecord | null> {
    const result = await (this.prisma as any).refund?.findFirst({
      where: { idempotencyKey, tenantId },
    });

    if (!result) return null;

    return this.mapToRefundRecord(result);
  }

  async listRefunds(filter: RefundFilter): Promise<RefundRecord[]> {
    const where: any = {};

    if (filter.tenantId) where.tenantId = filter.tenantId;
    if (filter.paymentId) where.paymentId = filter.paymentId;
    if (filter.invoiceId) where.invoiceId = filter.invoiceId;
    if (filter.status) where.status = filter.status;
    if (filter.refundType) where.refundType = filter.refundType;
    if (filter.reason) where.reason = filter.reason;
    if (filter.provider) where.provider = filter.provider;
    if (filter.currency) where.currency = filter.currency;
    if (filter.idempotencyKey) where.idempotencyKey = filter.idempotencyKey;
    if (filter.fromDate || filter.toDate) {
      where.requestedAt = {};
      if (filter.fromDate) where.requestedAt.gte = filter.fromDate;
      if (filter.toDate) where.requestedAt.lte = filter.toDate;
    }

    const results = await (this.prisma as any).refund?.findMany({
      where,
      orderBy: { requestedAt: 'desc' },
      take: 100,
    });

    if (!results) return [];

    return results.map((r: any) => this.mapToRefundRecord(r));
  }

  async calculateRefundableAmount(paymentId: string, tenantId: string): Promise<RefundableAmount> {
    const payment = await this.getPaymentRecord(paymentId);
    if (!payment) {
      throw new Error(`Payment not found: ${paymentId}`);
    }

    const originalAmount = createMoney(payment.amount, payment.currency);

    // Get already refunded amount
    const refunds = await this.listRefunds({ paymentId, tenantId });
    let refundedMinor = 0;

    for (const refund of refunds) {
      if (refund.status === RefundStatus.SUCCEEDED) {
        refundedMinor += parseToMinorUnits(refund.amount, refund.currency);
      }
    }

    const originalMinor = parseToMinorUnits(originalAmount.amount, originalAmount.currency);
    const refundableMinor = originalMinor - refundedMinor;

    const refundedAmount = createMoney(formatFromMinorUnits(refundedMinor, payment.currency), payment.currency);
    const refundableAmount = createMoney(formatFromMinorUnits(Math.max(0, refundableMinor), payment.currency), payment.currency);

    return {
      paymentId,
      tenantId,
      originalAmount,
      refundedAmount,
      refundableAmount,
      currency: payment.currency,
      isFullyRefunded: refundableMinor <= 0,
      isPartiallyRefunded: refundedMinor > 0 && refundableMinor < originalMinor,
    };
  }

  async retryFailedRefund(refundId: string, tenantId: string): Promise<RefundRecord> {
    const refund = await this.getRefundById(refundId, tenantId);
    if (!refund) {
      throw new Error(`Refund not found: ${refundId}`);
    }

    if (refund.status !== RefundStatus.FAILED) {
      throw new Error(`Only FAILED refunds can be retried, current status: ${refund.status}`);
    }

    if (!isValidRefundTransition(refund.status, RefundStatus.PENDING)) {
      throw new Error(`Invalid transition from ${refund.status} to PENDING`);
    }

    const payment = await this.getPaymentRecord(refund.paymentId);
    if (!payment) {
      throw new Error(`Payment not found: ${refund.paymentId}`);
    }

    // Reset to PENDING
    const updated = await this.updateRefundStatus(refundId, RefundStatus.PENDING, {
      failureReason: null,
      failureCode: null,
    });

    // Re-execute provider refund
    try {
      const refundAmount = createMoney(refund.amount, refund.currency);
      const providerResult = await this.executeProviderRefund(payment, updated, refundAmount);
      const finalRecord = await this.updateRefundFromProviderResult(refundId, providerResult);

      if (finalRecord.status === RefundStatus.SUCCEEDED) {
        await this.updatePaymentRefundedAmount(refund.paymentId, refundAmount);

        if (refund.invoiceId) {
          await this.adjustInvoiceForRefund(refund.invoiceId, refundAmount, tenantId);
        }

        await this.ledgerService.recordRefund({
          tenantId,
          refundId,
          paymentId: refund.paymentId,
          invoiceId: refund.invoiceId || undefined,
          amount: refundAmount,
          currency: refund.currency,
          reason: refund.reason as any,
          idempotencyKey: `refund_ledger_${refundId}_retry`,
        });

        await this.auditService.logRefundSucceeded(tenantId, refundId, refund.paymentId, refundAmount.amount, refundAmount.currency);
      }

      return finalRecord;
    } catch (error) {
      await this.markRefundFailed(refundId, (error as Error).message);
      throw error;
    }
  }

  async cancelRefund(refundId: string, tenantId: string): Promise<RefundRecord> {
    const refund = await this.getRefundById(refundId, tenantId);
    if (!refund) {
      throw new Error(`Refund not found: ${refundId}`);
    }

    if (![RefundStatus.PENDING, RefundStatus.REQUIRES_ACTION].includes(refund.status)) {
      throw new Error(`Cannot cancel refund with status ${refund.status}`);
    }

    return this.updateRefundStatus(refundId, RefundStatus.CANCELED);
  }

  private async createRefundRecord(params: CreateRefundInput & { amount: Money }): Promise<RefundRecord> {
    const payment = await this.getPaymentRecord(params.paymentId);

    try {
      const data = {
        id: randomUUID(),
        tenantId: params.tenantId,
        paymentId: params.paymentId,
        invoiceId: params.invoiceId || null,
        refundType: params.refundType,
        reason: params.reason,
        reasonDetails: params.reasonDetails || null,
        amount: params.amount.amount,
        currency: params.amount.currency,
        status: RefundStatus.PENDING,
        provider: payment?.provider || 'STRIPE',
        providerRefundId: null,
        providerStatus: null,
        idempotencyKey: params.idempotencyKey,
        failureReason: null,
        failureCode: null,
        requestedBy: params.requestedBy || null,
        requestedAt: new Date(),
        processedAt: null,
        succeededAt: null,
        failedAt: null,
        metadata: params.metadata ? JSON.parse(JSON.stringify(params.metadata)) : null,
        createdAt: new Date(),
        updatedAt: new Date(),
      };

      const result = await (this.prisma as any).refund?.create({ data });

      if (!result) {
        return this.createFallbackRecord(params);
      }

      return this.mapToRefundRecord(result);
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        return this.createFallbackRecord(params);
      }
      if (error.code === 'P2002') {
        // Duplicate idempotency key - return existing
        const existing = await this.findByIdempotencyKey(params.idempotencyKey, params.tenantId);
        if (existing) return existing;
      }
      throw error;
    }
  }

  private async executeProviderRefund(payment: any, refund: RefundRecord, amount: Money): Promise<ProviderRefundResult> {
    let adapter: any;
    try {
      adapter = this.providerFactory.getProvider(payment.provider as any);
    } catch {
      throw new Error(`No adapter for provider ${payment.provider}`);
    }

    if (!adapter) {
      throw new Error(`No adapter for provider ${payment.provider}`);
    }

    // Update to PROCESSING
    await this.updateRefundStatus(refund.id, RefundStatus.PROCESSING, { processedAt: new Date() });

    try {
      const providerResult = await adapter.refund({
        providerPaymentId: payment.providerPaymentId || payment.providerReference,
        amount: { amount: amount.amount, currency: amount.currency },
        reason: refund.reason,
        idempotencyKey: refund.idempotencyKey,
      });

      return {
        providerRefundId: providerResult.providerRefundId,
        status: RefundStatus.SUCCEEDED,
        providerStatus: providerResult.status?.toString() || 'SUCCEEDED',
        amount,
        currency: amount.currency,
        metadata: providerResult.rawResponse as any,
      };
    } catch (error: any) {
      // Provider refund failed
      return {
        providerRefundId: '',
        status: RefundStatus.FAILED,
        providerStatus: 'FAILED',
        amount,
        currency: amount.currency,
        failureReason: error.message || 'Provider refund failed',
        failureCode: error.code || 'PROVIDER_ERROR',
      };
    }
  }

  private async updateRefundFromProviderResult(refundId: string, result: ProviderRefundResult): Promise<RefundRecord> {
    const updates: any = {
      providerRefundId: result.providerRefundId || undefined,
      providerStatus: result.providerStatus,
      status: result.status,
      failureReason: result.failureReason || null,
      failureCode: result.failureCode || null,
      updatedAt: new Date(),
    };

    if (result.status === RefundStatus.SUCCEEDED) {
      updates.succeededAt = new Date();
    } else if (result.status === RefundStatus.FAILED) {
      updates.failedAt = new Date();
    }

    return this.updateRefundStatus(refundId, result.status, updates);
  }

  private async updateRefundStatus(refundId: string, status: RefundStatus, extra?: any): Promise<RefundRecord> {
    try {
      const result = await (this.prisma as any).refund?.update({
        where: { id: refundId },
        data: {
          status,
          ...extra,
          updatedAt: new Date(),
        },
      });

      if (!result) {
        throw new Error(`Refund not found: ${refundId}`);
      }

      return this.mapToRefundRecord(result);
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        // Fallback - cannot update if model doesn't exist
        throw new Error(`Refund model not available for update: ${refundId}`);
      }
      throw error;
    }
  }

  private async markRefundFailed(refundId: string, reason: string): Promise<void> {
    try {
      await this.updateRefundStatus(refundId, RefundStatus.FAILED, {
        failureReason: reason,
        failedAt: new Date(),
      });
    } catch {
      // Ignore if model doesn't exist
    }
  }

  private async updatePaymentRefundedAmount(paymentId: string, refundAmount: Money): Promise<void> {
    try {
      const payment = await (this.prisma as any).payment?.findUnique({ where: { id: paymentId } });
      if (!payment) return;

      const currentRefunded = payment.refundedAmount ? parseToMinorUnits(payment.refundedAmount.toString(), payment.currency) : 0;
      const additionalMinor = parseToMinorUnits(refundAmount.amount, refundAmount.currency);
      const newRefundedMinor = currentRefunded + additionalMinor;
      const newRefundedAmount = formatFromMinorUnits(newRefundedMinor, payment.currency);

      await (this.prisma as any).payment?.update({
        where: { id: paymentId },
        data: {
          refundedAmount: newRefundedAmount,
          updatedAt: new Date(),
        },
      });
    } catch {
      // Model may not exist - log but don't fail
      this.logger.warn(`Could not update payment refunded amount for ${paymentId}`);
    }
  }

  private async adjustInvoiceForRefund(invoiceId: string, refundAmount: Money, tenantId: string): Promise<void> {
    try {
      const invoice = await this.invoiceRepository.findById(invoiceId, tenantId);
      if (!invoice) return;

      // Calculate new refunded total
      const currentRefundedMinor = parseToMinorUnits(invoice.amountRefunded || '0', invoice.currency);
      const additionalMinor = parseToMinorUnits(refundAmount.amount, refundAmount.currency);
      const newRefundedMinor = currentRefundedMinor + additionalMinor;

      const totalMinor = parseToMinorUnits(invoice.total, invoice.currency);
      const isFullyRefunded = newRefundedMinor >= totalMinor;

      const newStatus = isFullyRefunded ? 'REFUNDED' : 'PARTIALLY_REFUNDED';

      await this.invoiceRepository.update(invoiceId, {
        amountRefunded: formatFromMinorUnits(newRefundedMinor, invoice.currency),
        status: newStatus as any,
      });
    } catch (error) {
      this.logger.warn(`Could not adjust invoice ${invoiceId} for refund: ${(error as Error).message}`);
    }
  }

  private async getPaymentRecord(paymentId: string): Promise<any> {
    try {
      const result = await (this.prisma as any).payment?.findUnique({ where: { id: paymentId } });
      if (result) return result;

      // Fallback to payment service
      const payment = await this.paymentService.getPaymentById(paymentId);
      return payment ? { ...payment, amount: payment.amount, currency: payment.currency, provider: payment.provider, providerPaymentId: payment.providerPaymentId, status: payment.status, tenantId: payment.tenantId } : null;
    } catch {
      const payment = await this.paymentService.getPaymentById(paymentId);
      return payment ? { ...payment, amount: payment.amount, currency: payment.currency, provider: payment.provider, providerPaymentId: payment.providerPaymentId, status: payment.status, tenantId: payment.tenantId } : null;
    }
  }

  private validateRefundInput(input: CreateRefundInput): void {
    if (!input.tenantId) throw new Error('Tenant ID required');
    if (!input.paymentId) throw new Error('Payment ID required');
    if (!input.idempotencyKey) throw new Error('Idempotency key required');
    if (!input.reason) throw new Error('Refund reason required');

    if (input.refundType === RefundType.PARTIAL && !input.amount) {
      throw new Error('Amount required for partial refund');
    }
  }

  private createFallbackRecord(params: CreateRefundInput & { amount: Money }): RefundRecord {
    return {
      id: randomUUID(),
      tenantId: params.tenantId,
      paymentId: params.paymentId,
      invoiceId: params.invoiceId || null,
      refundType: params.refundType,
      reason: params.reason,
      reasonDetails: params.reasonDetails || null,
      amount: params.amount.amount,
      currency: params.amount.currency,
      status: RefundStatus.PENDING,
      provider: 'STRIPE' as any,
      providerRefundId: null,
      providerStatus: null,
      idempotencyKey: params.idempotencyKey,
      failureReason: null,
      failureCode: null,
      requestedBy: params.requestedBy || null,
      requestedAt: new Date(),
      processedAt: null,
      succeededAt: null,
      failedAt: null,
      metadata: params.metadata || null,
      createdAt: new Date(),
      updatedAt: new Date(),
    };
  }

  private mapToRefundRecord(raw: any): RefundRecord {
    return {
      id: raw.id,
      tenantId: raw.tenantId,
      paymentId: raw.paymentId,
      invoiceId: raw.invoiceId || null,
      refundType: raw.refundType as RefundType,
      reason: raw.reason as RefundReason,
      reasonDetails: raw.reasonDetails || null,
      amount: raw.amount?.toString() || '0',
      currency: raw.currency || 'USD',
      status: raw.status as RefundStatus,
      provider: raw.provider,
      providerRefundId: raw.providerRefundId || null,
      providerStatus: raw.providerStatus || null,
      idempotencyKey: raw.idempotencyKey,
      failureReason: raw.failureReason || null,
      failureCode: raw.failureCode || null,
      requestedBy: raw.requestedBy || null,
      requestedAt: raw.requestedAt ? new Date(raw.requestedAt) : new Date(),
      processedAt: raw.processedAt ? new Date(raw.processedAt) : null,
      succeededAt: raw.succeededAt ? new Date(raw.succeededAt) : null,
      failedAt: raw.failedAt ? new Date(raw.failedAt) : null,
      metadata: raw.metadata || null,
      createdAt: raw.createdAt ? new Date(raw.createdAt) : new Date(),
      updatedAt: raw.updatedAt ? new Date(raw.updatedAt) : new Date(),
    };
  }
}

/**
 * Tax on invoices: the customer's tax profile must reach the tax engine, and
 * B2B reverse charge (0% VAT) needs evidence for the VAT number.
 */
import { TaxService } from './tax.service';
import { InvoiceService } from './invoice.service';
import { TaxCategory } from './tax.types';
import { createMoney } from './money.types';
import type { VatCheckResult } from './vies-vat.client';

const ENV_KEYS = [
  'TAX_VAT_VALIDATION',
  'TAX_SUPPLIER_COUNTRY',
  'TAX_RATES_JSON',
  'TAX_UNKNOWN_COUNTRY',
  'TAX_VIES_REQUESTER_VAT',
];
const saved: Record<string, string | undefined> = {};
beforeEach(() => {
  for (const k of ENV_KEYS) {
    saved[k] = process.env[k];
    delete process.env[k];
  }
});
afterEach(() => {
  for (const k of ENV_KEYS) {
    if (saved[k] === undefined) delete process.env[k];
    else process.env[k] = saved[k];
  }
});

const noProvider = { getProvider: () => null } as any;

function taxService(prisma: any = {}, viesStatus?: VatCheckResult['status']) {
  const svc = new TaxService(prisma, noProvider);
  const check = jest.fn(async (country: string, vatNumber: string): Promise<VatCheckResult> => ({
    status: viesStatus ?? 'VALID',
    countryCode: country,
    vatNumber,
    source: 'vies',
    consultationNumber: viesStatus === 'VALID' ? 'WAPI123' : undefined,
    checkedAt: '2026-09-28T10:00:00.000Z',
  }));
  (svc as any).vatChecker = { check };
  return { svc, check };
}

const b2b = (overrides: Record<string, unknown> = {}) =>
  ({
    tenantId: 't1',
    amount: createMoney('100.00', 'EUR'),
    currency: 'EUR',
    billingCountry: 'DE',
    vatNumber: 'DE123456789',
    isBusinessCustomer: true,
    ...overrides,
  }) as any;

describe('reverse charge needs a verified VAT number', () => {
  it('format mode (default): a well-formed EU VAT number -> reverse charge, evidence attached', async () => {
    const { svc, check } = taxService();
    const r = await svc.calculateTax(b2b());
    expect(r.reverseCharge).toBe(true);
    expect(r.taxAmount.amount).toBe('0.00');
    expect(r.vatCheck).toMatchObject({ status: 'VALID', source: 'format' });
    expect(check).not.toHaveBeenCalled();
  });

  it('format mode: a malformed number is charged standard VAT (was: any string gave 0%)', async () => {
    const { svc } = taxService();
    const r = await svc.calculateTax(b2b({ vatNumber: 'not-a-vat' }));
    expect(r.reverseCharge).toBe(false);
    expect(r.taxRate).toBe(1900);
    expect(r.taxAmount.amount).toBe('19.00');
    expect(r.vatCheck?.status).toBe('INVALID');
  });

  it('vies mode: VALID -> reverse charge with the consultation number', async () => {
    process.env.TAX_VAT_VALIDATION = 'vies';
    const { svc, check } = taxService({}, 'VALID');
    const r = await svc.calculateTax(b2b());
    expect(check).toHaveBeenCalledWith('DE', 'DE123456789');
    expect(r.taxCategory).toBe(TaxCategory.REVERSE_CHARGE);
    expect(r.vatCheck?.consultationNumber).toBe('WAPI123');
  });

  it('vies mode: INVALID or UNAVAILABLE -> standard VAT (the seller cannot recover uncharged VAT)', async () => {
    process.env.TAX_VAT_VALIDATION = 'vies';
    for (const status of ['INVALID', 'UNAVAILABLE'] as const) {
      const { svc } = taxService({}, status);
      const r = await svc.calculateTax(b2b());
      expect(r.reverseCharge).toBe(false);
      expect(r.taxAmount.amount).toBe('19.00');
      expect(r.vatCheck?.status).toBe(status);
    }
  });

  it('same member state as the seller -> domestic VAT, no reverse charge, no check', async () => {
    process.env.TAX_SUPPLIER_COUNTRY = 'DE';
    process.env.TAX_VAT_VALIDATION = 'vies';
    const { svc, check } = taxService();
    const r = await svc.calculateTax(b2b());
    expect(r.reverseCharge).toBe(false);
    expect(r.taxRate).toBe(1900);
    expect(r.vatCheck).toBeUndefined();
    expect(check).not.toHaveBeenCalled();
  });

  it('consumers and non-EU customers never trigger reverse charge', async () => {
    const { svc } = taxService();
    expect((await svc.calculateTax(b2b({ isBusinessCustomer: false }))).reverseCharge).toBe(false);
    const gb = await svc.calculateTax(b2b({ billingCountry: 'GB', vatNumber: 'GB123456789' }));
    expect(gb.reverseCharge).toBe(false);
    expect(gb.taxRate).toBe(2000);
  });

  it('none mode keeps the historical trust-the-number behaviour, explicitly marked SKIPPED', async () => {
    process.env.TAX_VAT_VALIDATION = 'none';
    const { svc } = taxService();
    const r = await svc.calculateTax(b2b({ vatNumber: 'whatever' }));
    expect(r.reverseCharge).toBe(true);
    expect(r.vatCheck?.status).toBe('SKIPPED');
  });
});

describe('validateTaxId', () => {
  it('uses per-member-state formats for EU countries and VIES in vies mode', async () => {
    const { svc } = taxService();
    expect((await svc.validateTaxId('DE123456789', 'DE')).valid).toBe(true);
    expect((await svc.validateTaxId('NL123456789', 'NL')).valid).toBe(false);

    process.env.TAX_VAT_VALIDATION = 'vies';
    const unavailable = taxService({}, 'UNAVAILABLE').svc;
    const r = await unavailable.validateTaxId('DE123456789', 'DE');
    expect(r).toMatchObject({ valid: false, validationSource: 'vies_unavailable' });
  });
});

describe('invoice generation passes the tenant tax profile to the tax engine', () => {
  const STOP = new Error('stop after building the invoice input');

  function invoiceHarness(
    tenantRow: { countryCode: string | null; metadata: Record<string, unknown> } | null,
  ) {
    const prisma = {
      subscriptionPlan: {
        findUnique: jest.fn(async () => ({
          id: 'plan1',
          name: 'Pro',
          code: 'pro',
          price: '100.00',
          interval: 'MONTHLY',
        })),
      },
      tenant: {
        findUnique: jest.fn(async (args: any) =>
          args.select?.countryCode
            ? tenantRow && { id: 't1', ...tenantRow }
            : { id: 't1', name: 'Acme', slug: 'acme', contactEmail: 'billing@acme.test' },
        ),
      },
    };
    const tax = new TaxService(prisma as any, noProvider);
    (tax as any).vatChecker = { check: jest.fn() };
    const created: any[] = [];
    const repo = {
      findByPaymentId: jest.fn(async () => null),
      create: jest.fn(async (input: any) => {
        created.push(input);
        throw STOP;
      }),
    };
    const payments = {
      getPaymentById: jest.fn(async () => ({
        id: 'pay1',
        tenantId: 't1',
        planId: 'plan1',
        status: 'SUCCEEDED',
        currency: 'EUR',
        provider: 'STRIPE',
        subscriptionId: null,
        providerPaymentId: 'pi_1',
        paidAt: new Date('2026-09-28T00:00:00Z'),
      })),
    };
    const svc = new InvoiceService(
      prisma as any,
      repo as any,
      {} as any,
      tax,
      payments as any,
      {} as any,
      {} as any,
    );
    return { svc, created };
  }

  it('taxes a German consumer at 19% (was: country never selected -> "US" -> 0%)', async () => {
    const { svc, created } = invoiceHarness({ countryCode: 'DE', metadata: {} });
    await expect(svc.createInvoiceFromPayment('pay1')).rejects.toBe(STOP);
    const taxLine = created[0].lines.find((l: any) => l.type === 'TAX');
    expect(taxLine.amount.amount).toBe('19.00');
    expect(created[0].taxSummary[0]).toMatchObject({ taxRate: 1900, reverseCharge: false });
  });

  it('a French business with a VAT number: reverse charge, VAT number on the invoice, evidence in metadata', async () => {
    const { svc, created } = invoiceHarness({
      countryCode: 'FR',
      metadata: { isBusinessCustomer: true, vatNumber: 'FRXX123456789', taxId: 'FRXX123456789' },
    });
    await expect(svc.createInvoiceFromPayment('pay1')).rejects.toBe(STOP);
    expect(created[0].lines.find((l: any) => l.type === 'TAX')).toBeUndefined();
    expect(created[0].taxSummary[0]).toMatchObject({ reverseCharge: true, taxRate: 0 });
    expect(created[0].customer.vatNumber).toBe('FRXX123456789');
    expect(created[0].metadata.vatCheck).toMatchObject({
      status: 'VALID',
      source: 'format',
      countryCode: 'FR',
    });
  });

  it('a tax-exempt tenant is not charged', async () => {
    const { svc, created } = invoiceHarness({ countryCode: 'DE', metadata: { isTaxExempt: true } });
    await expect(svc.createInvoiceFromPayment('pay1')).rejects.toBe(STOP);
    expect(created[0].lines.find((l: any) => l.type === 'TAX')).toBeUndefined();
  });

  it('no country on file + TAX_UNKNOWN_COUNTRY=reject -> no invoice instead of an untaxed one', async () => {
    process.env.TAX_UNKNOWN_COUNTRY = 'reject';
    const { svc, created } = invoiceHarness({ countryCode: null, metadata: {} });
    await expect(svc.createInvoiceFromPayment('pay1')).rejects.toThrow(/Billing country required/);
    expect(created).toHaveLength(0);
  });

  it('tax profile unavailable -> no invoice', async () => {
    const { svc, created } = invoiceHarness(null);
    await expect(svc.createInvoiceFromPayment('pay1')).rejects.toThrow(
      /tax information unavailable/,
    );
    expect(created).toHaveLength(0);
  });
});

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { TaxProviderFactory } from './tax-provider.interface';
import type { TaxCalculationInput, TaxCalculationResult, TaxBreakdown, TaxValidationResult, CustomerTaxInfo } from './tax.types';
import { TaxCategory, TaxType, ExemptionReason, REVERSE_CHARGE_COUNTRIES, EU_COUNTRIES } from './tax.types';

import { loadTaxRateTable, resolveTaxRate, TaxRateTable } from './tax-rates.config';
import {
  ViesVatClient,
  VatCheckResult,
  VatValidationMode,
  isEuVatFormatValid,
  vatValidationModeFromEnv,
  verifyVatForReverseCharge,
} from './vies-vat.client';
import { createMoney, calculatePercentageAmount, addMoney } from './money.types';

/**
 * Determines applicable tax/VAT rules from customer/tenant billing information,
 * configured jurisdiction, exemption state, and invoice context.
 *
 * Responsibilities:
 *  - determine applicable tax treatment
 *  - calculate tax amount using precise monetary logic
 *  - recognize tax-exempt cases where configured
 *  - recognize reverse-charge cases where applicable
 *  - return deterministic tax breakdown
 *  - attach tax result to invoice generation
 *
 * Do not hardcode country-specific tax rates inside invoice code.
 * Use configurable policy/provider architecture.
 * If no external tax provider is configured, use repository's configured tax rules
 * rather than silently inventing tax rates.
 */

@Injectable()
export class TaxService {
  private readonly logger = new Logger(TaxService.name);
  // Built once at construction: an invalid TAX_RATES_JSON fails the boot.
  private readonly taxRates: TaxRateTable = loadTaxRateTable();
  // TAX_VAT_VALIDATION (none | format | vies); invalid values fail the boot.
  private readonly vatValidation: VatValidationMode = vatValidationModeFromEnv();
  // Seller's own country (ISO-2). A customer in the same member state is
  // charged domestic VAT: reverse charge only applies across borders.
  private readonly supplierCountry: string = (process.env.TAX_SUPPLIER_COUNTRY || '').trim().toUpperCase();
  protected vatChecker: Pick<ViesVatClient, 'check'> = new ViesVatClient();

  constructor(
    private readonly prisma: PrismaService,
    private readonly taxProviderFactory: TaxProviderFactory,
  ) {
    if (this.taxRates.overridden.length > 0) {
      this.logger.log(`Tax rates overridden via TAX_RATES_JSON for: ${this.taxRates.overridden.join(', ')}`);
    }
  }

  async calculateTax(input: TaxCalculationInput): Promise<TaxCalculationResult> {
    this.validateTaxInput(input);

    // Check for exemption
    if (input.isTaxExempt) {
      return this.createExemptResult(input, input.exemptionReason || ExemptionReason.CUSTOM);
    }

    // Try external tax provider first if configured
    const provider = this.taxProviderFactory.getProvider();
    if (provider) {
      try {
        const providerResult = await provider.calculateTax(input);
        this.logger.log(`Tax calculated via provider ${provider.provider} for tenant ${input.tenantId}: ${providerResult.taxAmount.amount} ${providerResult.taxAmount.currency}`);
        return providerResult;
      } catch (error) {
        this.logger.warn(`External tax provider failed, using internal rules: ${(error as Error).message}`);
      }
    }

    // Fallback to internal configurable tax rules. Reverse charge needs
    // evidence for the VAT number first (TAX_VAT_VALIDATION).
    const vatCheck = await this.checkReverseChargeEvidence(input);
    const result = this.calculateTaxWithInternalRules(input, vatCheck);
    return vatCheck ? { ...result, vatCheck } : result;
  }

  /**
   * For an EU business customer with a VAT number in another member state
   * than the seller, checks the number per TAX_VAT_VALIDATION. Returns
   * undefined when reverse charge is not in question at all.
   */
  private async checkReverseChargeEvidence(input: TaxCalculationInput): Promise<VatCheckResult | undefined> {
    const country = input.billingCountry.toUpperCase();
    const vatNumber = (input.vatNumber || input.taxId || '').trim();
    if (!input.isBusinessCustomer || !vatNumber) return undefined;
    if (!EU_COUNTRIES.has(country) || !this.isReverseChargeApplicable(country, this.supplierCountry)) return undefined;
    if (this.supplierCountry && this.supplierCountry === country) return undefined;
    const check = await verifyVatForReverseCharge(this.vatValidation, country, vatNumber, this.vatChecker);
    if (check.status !== 'VALID' && check.status !== 'SKIPPED') {
      this.logger.warn(
        `Reverse charge not applied for tenant ${input.tenantId} (${country}): VAT number ${check.status} via ${check.source}${check.error ? ` - ${check.error}` : ''}; standard VAT charged`,
      );
    }
    return check;
  }

  async validateTaxId(taxId: string, country: string): Promise<TaxValidationResult> {
    if (!taxId || !country) {
      return {
        valid: false,
        taxId,
        country,
        validationSource: 'internal',
        error: 'Tax ID and country required',
      };
    }

    const provider = this.taxProviderFactory.getProvider();
    if (provider) {
      try {
        return await provider.validateTaxId(taxId, country);
      } catch (error) {
        this.logger.warn(`Tax ID validation via provider failed: ${(error as Error).message}`);
      }
    }

    const upper = country.toUpperCase();
    if (EU_COUNTRIES.has(upper) && this.vatValidation === 'vies') {
      const check = await this.vatChecker.check(upper, taxId);
      return {
        valid: check.status === 'VALID',
        taxId,
        country,
        validationSource: check.status === 'UNAVAILABLE' ? 'vies_unavailable' : 'vies',
        companyName: check.name,
        address: check.address,
        error: check.status === 'VALID' ? undefined : check.error || 'VAT number not valid in VIES',
      };
    }

    // Internal validation: format check (per-member-state VAT formats for EU)
    const isValidFormat = EU_COUNTRIES.has(upper) ? isEuVatFormatValid(upper, taxId) : this.validateTaxIdFormat(taxId, country);

    return {
      valid: isValidFormat,
      taxId,
      country,
      validationSource: 'internal_format_check',
      error: isValidFormat ? undefined : 'Invalid tax ID format',
    };
  }

  async getCustomerTaxInfo(tenantId: string): Promise<CustomerTaxInfo | null> {
    const tenant = await this.prisma.tenant.findUnique({
      where: { id: tenantId },
      select: {
        id: true,
        countryCode: true,
        metadata: true,
      },
    });

    if (!tenant) return null;

    const metadata = tenant.metadata as any;

    return {
      tenantId,
      // No country on file: 'US' (0%) historically; with
      // TAX_UNKNOWN_COUNTRY=reject it stays empty so the invoice fails
      // instead of silently going out without tax.
      billingCountry: tenant.countryCode || metadata?.billingCountry || (this.taxRates.unknownCountry === 'reject' ? '' : 'US'),
      billingRegion: metadata?.billingRegion,
      taxId: metadata?.taxId,
      vatNumber: metadata?.vatNumber,
      isBusinessCustomer: metadata?.isBusinessCustomer || false,
      isTaxExempt: metadata?.isTaxExempt || false,
      exemptionReason: metadata?.exemptionReason,
    };
  }

  private calculateTaxWithInternalRules(input: TaxCalculationInput, vatCheck?: VatCheckResult): TaxCalculationResult {
    const country = input.billingCountry.toUpperCase();
    const amount = input.amount;

    // Reverse charge: EU business customer, cross-border, VAT number verified
    // (VALID) or deliberately not checked (TAX_VAT_VALIDATION=none -> SKIPPED).
    // An INVALID or UNAVAILABLE check falls through to standard VAT.
    if (vatCheck && (vatCheck.status === 'VALID' || vatCheck.status === 'SKIPPED')) {
      return this.createReverseChargeResult(input);
    }

    // Check if country is tax-exempt (e.g., US has no federal VAT for SaaS in many states)
    // For simplicity, US = 0% tax unless configured otherwise
    // EU countries have VAT, others configurable

    const taxRateBasisPoints = this.getTaxRateForCountry(country, input.billingRegion);

    if (taxRateBasisPoints === 0) {
      return this.createZeroTaxResult(input);
    }

    const taxAmount = calculatePercentageAmount(amount, taxRateBasisPoints);
    const totalAmount = addMoney(amount, taxAmount);

    const breakdown: TaxBreakdown = {
      taxableAmount: amount,
      taxRate: taxRateBasisPoints,
      taxAmount,
      taxCategory: TaxCategory.STANDARD,
      jurisdiction: `${country}${input.billingRegion ? `-${input.billingRegion}` : ''}`,
      taxType: this.getTaxTypeForCountry(country),
      reverseCharge: false,
      taxId: input.taxId,
    };

    return {
      taxableAmount: amount,
      taxAmount,
      totalAmount,
      taxRate: taxRateBasisPoints,
      taxCategory: TaxCategory.STANDARD,
      jurisdiction: breakdown.jurisdiction,
      taxType: breakdown.taxType,
      breakdown: [breakdown],
      reverseCharge: false,
      taxCalculationSource: 'internal_configurable_rules',
      calculatedAt: new Date(),
    };
  }

  private createExemptResult(input: TaxCalculationInput, reason: ExemptionReason): TaxCalculationResult {
    const zeroMoney = createMoney('0', input.currency);

    return {
      taxableAmount: input.amount,
      taxAmount: zeroMoney,
      totalAmount: input.amount,
      taxRate: 0,
      taxCategory: TaxCategory.EXEMPT,
      jurisdiction: input.billingCountry,
      taxType: TaxType.NONE,
      breakdown: [
        {
          taxableAmount: input.amount,
          taxRate: 0,
          taxAmount: zeroMoney,
          taxCategory: TaxCategory.EXEMPT,
          jurisdiction: input.billingCountry,
          taxType: TaxType.NONE,
          exemptionReason: reason,
          reverseCharge: false,
        },
      ],
      exemptionReason: reason,
      reverseCharge: false,
      taxCalculationSource: 'exemption',
      calculatedAt: new Date(),
    };
  }

  private createZeroTaxResult(input: TaxCalculationInput): TaxCalculationResult {
    const zeroMoney = createMoney('0', input.currency);

    return {
      taxableAmount: input.amount,
      taxAmount: zeroMoney,
      totalAmount: input.amount,
      taxRate: 0,
      taxCategory: TaxCategory.ZERO,
      jurisdiction: input.billingCountry,
      taxType: this.getTaxTypeForCountry(input.billingCountry),
      breakdown: [
        {
          taxableAmount: input.amount,
          taxRate: 0,
          taxAmount: zeroMoney,
          taxCategory: TaxCategory.ZERO,
          jurisdiction: input.billingCountry,
          taxType: this.getTaxTypeForCountry(input.billingCountry),
          reverseCharge: false,
        },
      ],
      reverseCharge: false,
      taxCalculationSource: 'zero_rate',
      calculatedAt: new Date(),
    };
  }

  private createReverseChargeResult(input: TaxCalculationInput): TaxCalculationResult {
    const zeroMoney = createMoney('0', input.currency);

    return {
      taxableAmount: input.amount,
      taxAmount: zeroMoney,
      totalAmount: input.amount,
      taxRate: 0,
      taxCategory: TaxCategory.REVERSE_CHARGE,
      jurisdiction: input.billingCountry,
      taxType: TaxType.VAT,
      breakdown: [
        {
          taxableAmount: input.amount,
          taxRate: 0,
          taxAmount: zeroMoney,
          taxCategory: TaxCategory.REVERSE_CHARGE,
          jurisdiction: input.billingCountry,
          taxType: TaxType.VAT,
          exemptionReason: ExemptionReason.REVERSE_CHARGE,
          reverseCharge: true,
        },
      ],
      exemptionReason: ExemptionReason.REVERSE_CHARGE,
      reverseCharge: true,
      taxCalculationSource: 'reverse_charge',
      calculatedAt: new Date(),
    };
  }

  private getTaxRateForCountry(country: string, region?: string): number {
    // DEFAULT_TAX_RATES overlaid with TAX_RATES_JSON (country or
    // country-region keys, basis points). Unknown countries are 0% unless
    // TAX_UNKNOWN_COUNTRY=reject, which throws instead. See tax-rates.config.ts.
    return resolveTaxRate(this.taxRates, country, region);
  }

  private getTaxTypeForCountry(country: string): TaxType {
    const upperCountry = country.toUpperCase();

    if (EU_COUNTRIES.has(upperCountry) || upperCountry === 'GB') {
      return TaxType.VAT;
    }

    if (['AU', 'NZ', 'SG', 'MY'].includes(upperCountry)) {
      return TaxType.GST;
    }

    if (upperCountry === 'US') {
      return TaxType.SALES_TAX;
    }

    return TaxType.VAT;
  }

  private isReverseChargeApplicable(customerCountry: string, supplierCountry: string): boolean {
    const customerUpper = customerCountry.toUpperCase();

    // Reverse charge typically applies for B2B transactions within EU
    // Or when supplier outside EU and customer is business in EU
    if (EU_COUNTRIES.has(customerUpper)) {
      return true;
    }

    return REVERSE_CHARGE_COUNTRIES.has(customerUpper);
  }

  private validateTaxIdFormat(taxId: string, country: string): boolean {
    if (!taxId) return false;

    const upperCountry = country.toUpperCase();
    const cleanTaxId = taxId.replace(/[^A-Z0-9]/gi, '');

    // Basic format validation
    if (cleanTaxId.length < 5 || cleanTaxId.length > 20) {
      return false;
    }

    // Country-specific validation (simplified)
    switch (upperCountry) {
      case 'DE':
        return /^DE[0-9]{9}$/.test(taxId.toUpperCase());
      case 'FR':
        return /^FR[0-9A-Z]{2}[0-9]{9}$/.test(taxId.toUpperCase());
      case 'GB':
        return /^GB[0-9]{9}$/.test(taxId.toUpperCase()) || /^GB[0-9]{12}$/.test(taxId.toUpperCase());
      case 'US':
        return /^[0-9]{2}-[0-9]{7}$/.test(taxId) || /^[0-9]{9}$/.test(taxId);
      default:
        return cleanTaxId.length >= 5;
    }
  }

  private validateTaxInput(input: TaxCalculationInput): void {
    if (!input.tenantId) {
      throw new Error('Tenant ID required for tax calculation');
    }
    if (!input.amount) {
      throw new Error('Amount required for tax calculation');
    }
    if (!input.billingCountry) {
      throw new Error('Billing country required for tax calculation');
    }
    if (!input.currency) {
      throw new Error('Currency required for tax calculation');
    }
  }
}

