    });
    const r = await client.check('DE', 'DE123456789');
    expect(calls[0].url).toBe(
      'https://ec.europa.eu/taxation_customs/vies/rest-api/check-vat-number',
    );
    expect(JSON.parse(calls[0].init.body)).toEqual({
      countryCode: 'DE',
