    }, `${params.paymentId}_expired`);
  }

  public async dispatchEvent(eventKey: BillingNotificationEventKey, tenantId: string, payload: SafeNotificationPayload, sourceId: string): Promise<void> {
    try {
      // Sanitize payload
      const safePayload = this.sanitizePayload(payload);

      // Dispatch via dispatcher -> delivery service
      await this.dispatcher.dispatch({
        eventKey,
        tenantId,
        safePayload,
        sourceId,
      });

      this.logger.log(`Billing event dispatched event=${eventKey} tenant=${tenantId} source=${sourceId}`);
    } catch (e) {
      this.logger.warn(`Failed to dispatch billing event ${eventKey} tenant=${tenantId}: ${(e as Error).message}`);
      // Never throw - notification failure must not rollback business operation
    }
  }

  private sanitizePayload(payload: SafeNotificationPayload): SafeNotificationPayload {
    const forbidden = ['secret', 'privateKey', 'apiKey', 'password', 'exchangeSecret', 'providerSecret', 'card', 'cvv', 'token', 'accessToken', 'credentials', 'bankAccount', 'walletKey'];
    const safe: any = {};
    for (const [key, value] of Object.entries(payload)) {
      const lowerKey = key.toLowerCase();
      if (forbidden.some((f) => lowerKey.includes(f.toLowerCase()))) {
        safe[key] = '[REDACTED]';
      } else {
        safe[key] = value;
      }
    }
    return safe as SafeNotificationPayload;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { randomUUID } from 'crypto';

/**
 * Structured audit events for notification creation, delivery, retry, suppression, failure, completion.
 * Sanitized metadata, no secrets.
 */

export enum NotificationAuditOperation {
  NOTIFICATION_CREATED = 'NOTIFICATION_CREATED',
  NOTIFICATION_SUPPRESSED = 'NOTIFICATION_SUPPRESSED',
  NOTIFICATION_SENT = 'NOTIFICATION_SENT',
  NOTIFICATION_FAILED = 'NOTIFICATION_FAILED',
  NOTIFICATION_RETRY_SCHEDULED = 'NOTIFICATION_RETRY_SCHEDULED',
  NOTIFICATION_PERMANENT_FAILURE = 'NOTIFICATION_PERMANENT_FAILURE',
  WEBHOOK_NOTIFICATION_SENT = 'WEBHOOK_NOTIFICATION_SENT',
  WEBHOOK_NOTIFICATION_FAILED = 'WEBHOOK_NOTIFICATION_FAILED',
  PREFERENCE_UPDATED = 'PREFERENCE_UPDATED',
  TEMPLATE_RENDER_FAILED = 'TEMPLATE_RENDER_FAILED',
  PROVIDER_CONFIGURATION_FAILED = 'PROVIDER_CONFIGURATION_FAILED',
  RECONCILIATION_DETECTED = 'RECONCILIATION_DETECTED',
  RECONCILIATION_RESOLVED = 'RECONCILIATION_RESOLVED',
}

@Injectable()
export class BillingNotificationAuditService {
  private readonly logger = new Logger(BillingNotificationAuditService.name);

  constructor(private readonly prisma: PrismaService) {}

  private async log(input: {
    tenantId: string;
    operation: NotificationAuditOperation;
    referenceId: string;
    referenceType: string;
    status: string;
    metadata?: Record<string, unknown>;
    actorId?: string;
  }): Promise<void> {
    const sanitized = this.sanitizeMetadata(input.metadata);

    try {
      await (this.prisma as any).billingNotificationAuditLog?.create({
        data: {
          id: randomUUID(),
          tenantId: input.tenantId,
          operation: input.operation,
          referenceId: input.referenceId,
          referenceType: input.referenceType,
          status: input.status,
          metadata: sanitized,
          actorId: input.actorId || null,
          timestamp: new Date(),
          createdAt: new Date(),
        },
      });
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        this.logger.log(`[NOTIF_AUDIT] ${input.operation} tenant=${input.tenantId} ref=${input.referenceId} status=${input.status}`);
        try {
          await (this.prisma as any).auditLog?.create({
            data: {
              id: randomUUID(),
              tenantId: input.tenantId,
              action: input.operation,
              resourceType: input.referenceType,
              resourceId: input.referenceId,
              metadata: sanitized,
              createdAt: new Date(),
            },
          });
        } catch {}
        return;
      }
      this.logger.warn(`Failed to create notification audit log: ${error.message}`);
    }
  }

  async logNotificationCreated(tenantId: string, notificationId: string, eventKey: string, channel: string, idempotencyKey: string): Promise<void> {
    await this.log({
      tenantId,
      operation: NotificationAuditOperation.NOTIFICATION_CREATED,
      referenceId: notificationId,
      referenceType: 'BillingNotification',
      status: 'CREATED',
      metadata: { eventKey, channel, idempotencyKey },
    });
  }

  async logNotificationSuppressed(tenantId: string, notificationId: string, eventKey: string, reason: string): Promise<void> {
    await this.log({
      tenantId,
      operation: NotificationAuditOperation.NOTIFICATION_SUPPRESSED,
      referenceId: notificationId,
      referenceType: 'BillingNotification',
      status: 'SUPPRESSED',
      metadata: { eventKey, reason },
    });
  }

  async logNotificationSent(tenantId: string, notificationId: string, eventKey: string, channel: string, providerReference: string | null): Promise<void> {
    await this.log({
      tenantId,
      operation: NotificationAuditOperation.NOTIFICATION_SENT,
      referenceId: notificationId,
      referenceType: 'BillingNotification',
      status: 'SENT',
      metadata: { eventKey, channel, providerReference },
    });
  }

  async logNotificationFailed(tenantId: string, notificationId: string, eventKey: string, channel: string, reason: string, retryable: boolean): Promise<void> {
    await this.log({
      tenantId,
      operation: NotificationAuditOperation.NOTIFICATION_FAILED,
      referenceId: notificationId,
      referenceType: 'BillingNotification',
      status: 'FAILED',
      metadata: { eventKey, channel, reason, retryable },
    });
  }

  async logRetryScheduled(tenantId: string, notificationId: string, attempt: number, nextAttemptAt: string, reason: string): Promise<void> {
    await this.log({
      tenantId,
      operation: NotificationAuditOperation.NOTIFICATION_RETRY_SCHEDULED,
      referenceId: notificationId,
      referenceType: 'BillingNotification',
      status: 'RETRY_SCHEDULED',
      metadata: { attempt, nextAttemptAt, reason },
    });
  }

  async logPermanentFailure(tenantId: string, notificationId: string, attempt: number, reason: string): Promise<void> {
    await this.log({
      tenantId,
      operation: NotificationAuditOperation.NOTIFICATION_PERMANENT_FAILURE,
      referenceId: notificationId,
      referenceType: 'BillingNotification',
      status: 'PERMANENT_FAILURE',
      metadata: { attempt, reason },
    });
  }

  async logWebhookSent(tenantId: string, subscriptionId: string, eventType: string, providerReference: string | null): Promise<void> {
    await this.log({
      tenantId,
      operation: NotificationAuditOperation.WEBHOOK_NOTIFICATION_SENT,
      referenceId: subscriptionId,
      referenceType: 'WebhookSubscription',
      status: 'SENT',
      metadata: { eventType, providerReference },
    });
  }

  async logWebhookFailed(tenantId: string, subscriptionId: string, eventType: string, reason: string, httpStatus?: number): Promise<void> {
    await this.log({
      tenantId,
      operation: NotificationAuditOperation.WEBHOOK_NOTIFICATION_FAILED,
      referenceId: subscriptionId,
      referenceType: 'WebhookSubscription',
      status: 'FAILED',
      metadata: { eventType, reason, httpStatus },
    });
  }

  async logPreferenceUpdated(tenantId: string, userId: string, preferences: any): Promise<void> {
    await this.log({
      tenantId,
      operation: NotificationAuditOperation.PREFERENCE_UPDATED,
      referenceId: userId,
      referenceType: 'NotificationPreference',
      status: 'UPDATED',
      metadata: { preferences },
    });
  }

  async logTemplateRenderFailed(tenantId: string, templateKey: string, reason: string): Promise<void> {
    await this.log({
      tenantId,
      operation: NotificationAuditOperation.TEMPLATE_RENDER_FAILED,
      referenceId: templateKey,
      referenceType: 'NotificationTemplate',
      status: 'FAILED',
      metadata: { reason },
    });
  }

  async logProviderConfigFailed(provider: string, reason: string): Promise<void> {
    await this.log({
      tenantId: 'system',
      operation: NotificationAuditOperation.PROVIDER_CONFIGURATION_FAILED,
      referenceId: provider,
      referenceType: 'NotificationProvider',
      status: 'FAILED',
      metadata: { reason },
    });
  }

  async logReconciliationDetected(tenantId: string, category: string, referenceId: string, description: string, severity: string): Promise<void> {
    await this.log({
      tenantId,
      operation: NotificationAuditOperation.RECONCILIATION_DETECTED,
      referenceId,
      referenceType: 'NotificationReconciliation',
      status: severity,
      metadata: { category, description },
    });
  }

  private sanitizeMetadata(metadata?: Record<string, unknown> | null): Record<string, unknown> | null {
    if (!metadata) return null;
    const forbidden = ['secret', 'apiKey', 'privateKey', 'accessToken', 'password', 'exchangeSecret', 'providerSecret', 'bankAccount', 'walletKey', 'private_key', 'credentials', 'stripeSecret', 'webhookSecret', 'token', 'card', 'cvv'];
    const safe: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(metadata)) {
      const lowerKey = key.toLowerCase();
      if (forbidden.some((f) => lowerKey.includes(f.toLowerCase()))) {
        safe[key] = '[REDACTED]';
      } else {
        safe[key] = value;
      }
    }
    return safe;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { BillingNotificationEventKey, WebhookSubscription, SafeNotificationPayload } from './billing-notification.types';
import { BillingNotificationAuditService } from './billing-notification.audit';
import { randomUUID, createHmac } from 'crypto';
import { isRecordNotFound } from '../../../common/errors/prisma-not-found';

/**
 * Tenant-configured outbound billing webhooks.
 * Events: invoice.paid, payment.failed, subscription.changed, etc.
 * Tenant must explicitly configure endpoint, signed event, timestamp, event ID, replay protection, retry, logging, isolation.
 * Never sends sensitive credentials.
 */
@Injectable()
export class BillingWebhookNotificationService {
  private readonly logger = new Logger(BillingWebhookNotificationService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly auditService: BillingNotificationAuditService,
  ) {}

  async createSubscription(params: {
    tenantId: string;
    endpointUrl: string;
    eventTypes: BillingNotificationEventKey[];
    secret: string;
    enabled?: boolean;
  }): Promise<WebhookSubscription> {
    // Validate HTTPS
    this.validateEndpointUrl(params.endpointUrl);

    // Check cross-tenant ownership - endpoint unique per tenant
    try {
      const existing = await (this.prisma as any).webhookSubscription?.findFirst({
        where: { tenantId: params.tenantId, endpointUrl: params.endpointUrl },
      });
      if (existing) {
        throw new Error(`Webhook subscription already exists for endpoint ${params.endpointUrl} in tenant ${params.tenantId}`);
      }
    } catch (e: any) {
      if (e.message.includes('already exists')) throw e;
    }

    const id = randomUUID();
    const now = new Date().toISOString();
    const secretHash = this.hashSecret(params.secret);
    const secretMasked = this.maskSecret(params.secret);

    const subscription: WebhookSubscription = {
      id,
      tenantId: params.tenantId,
      endpointUrl: params.endpointUrl,
      eventTypes: params.eventTypes,
      enabled: params.enabled ?? true,
      secretHash,
      secretMasked,
      lastDeliveryAt: null,
      lastDeliveryStatus: null,
      failureCount: 0,
      createdAt: now,
      updatedAt: now,
    };

    try {
      const created = await (this.prisma as any).webhookSubscription?.create({
        data: {
          id: subscription.id,
          tenantId: subscription.tenantId,
          endpointUrl: subscription.endpointUrl,
          eventTypes: subscription.eventTypes,
          enabled: subscription.enabled,
          secretHash: subscription.secretHash,
          secretMasked: subscription.secretMasked,
          failureCount: 0,
          createdAt: new Date(subscription.createdAt),
          updatedAt: new Date(subscription.updatedAt),
        },
      });

      if (created) {
        return this.mapSubscriptionToDomain(created);
      }
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        this.logger.warn(`webhookSubscription table not found, fallback: ${error.message}`);
        return subscription;
      }
      throw error;
    }

    return subscription;
  }

  async listSubscriptions(tenantId: string): Promise<WebhookSubscription[]> {
    const results = await (this.prisma as any).webhookSubscription?.findMany({
      where: { tenantId },
      orderBy: { createdAt: 'desc' },
    });
    if (!results) return [];
    return results.map((r: any) => this.mapSubscriptionToDomain(r));
  }

  async findSubscriptionById(id: string, tenantId: string): Promise<WebhookSubscription | null> {
    const result = await (this.prisma as any).webhookSubscription?.findFirst({
      where: { id, tenantId },
    });
    if (!result) return null;
    return this.mapSubscriptionToDomain(result);
  }

  async updateSubscription(
    id: string,
    tenantId: string,
    updates: { endpointUrl?: string; eventTypes?: BillingNotificationEventKey[]; enabled?: boolean },
  ): Promise<WebhookSubscription | null> {
    if (updates.endpointUrl) {
      this.validateEndpointUrl(updates.endpointUrl);
    }

    try {
      const data: any = { updatedAt: new Date() };
      if (updates.endpointUrl) data.endpointUrl = updates.endpointUrl;
      if (updates.eventTypes) data.eventTypes = updates.eventTypes;
      if (updates.enabled !== undefined) data.enabled = updates.enabled;

      const updated = await (this.prisma as any).webhookSubscription?.update({
        where: { id, tenantId },
        data,
      });

      if (!updated) return null;
      return this.mapSubscriptionToDomain(updated);
    } catch (error) {
      if (isRecordNotFound(error)) return null;
      throw error;
    }
  }

  async rotateSecret(id: string, tenantId: string, newSecret: string): Promise<WebhookSubscription | null> {
    try {
      const secretHash = this.hashSecret(newSecret);
      const secretMasked = this.maskSecret(newSecret);

      const updated = await (this.prisma as any).webhookSubscription?.update({
        where: { id, tenantId },
        data: {
          secretHash,
          secretMasked,
          updatedAt: new Date(),
        },
      });

      if (!updated) return null;
      return this.mapSubscriptionToDomain(updated);
    } catch (error) {
      if (isRecordNotFound(error)) return null;
      throw error;
    }
  }

  async deleteSubscription(id: string, tenantId: string): Promise<boolean> {
    try {
      await (this.prisma as any).webhookSubscription?.delete({
        where: { id, tenantId },
      });
      return true;
    } catch (error) {
      if (isRecordNotFound(error)) return false;
      throw error;
    }
  }

  async deliverWebhook(params: {
    tenantId: string;
    eventId: string;
    eventType: BillingNotificationEventKey;
    payload: SafeNotificationPayload;
    idempotencyKey?: string;
  }): Promise<{ delivered: number; failed: number; results: any[] }> {
    const subscriptions = await this.listSubscriptions(params.tenantId);
    const eligible = subscriptions.filter((s) => s.enabled && (s.eventTypes.includes(params.eventType) || s.eventTypes.includes('*' as any)));

    if (eligible.length === 0) {
      this.logger.log(`No webhook subscriptions for tenant=${params.tenantId} event=${params.eventType}`);
      return { delivered: 0, failed: 0, results: [] };
    }

    const results: any[] = [];
    let delivered = 0;
    let failed = 0;

    for (const subscription of eligible) {
      try {
        const result = await this.deliverToEndpoint({
          subscription,
          eventId: params.eventId,
          eventType: params.eventType,
          payload: params.payload,
          idempotencyKey: params.idempotencyKey || `webhook_${params.eventId}_${subscription.id}`,
        });

        results.push({ subscriptionId: subscription.id, endpoint: subscription.endpointUrl, success: result.accepted, result });

        if (result.accepted) {
          delivered++;
          await this.updateDeliveryStatus(subscription.id, 'DELIVERED');
          await this.auditService.logWebhookSent(params.tenantId, subscription.id, params.eventType, result.providerReference);
        } else {
          failed++;
          await this.updateDeliveryStatus(subscription.id, 'FAILED', result.failureReason);
          await this.auditService.logWebhookFailed(params.tenantId, subscription.id, params.eventType, result.failureReason || 'Delivery failed', result.httpStatus);
        }
      } catch (e: any) {
        failed++;
        results.push({ subscriptionId: subscription.id, endpoint: subscription.endpointUrl, success: false, error: e.message });
        await this.auditService.logWebhookFailed(params.tenantId, subscription.id, params.eventType, e.message);
      }
    }

    return { delivered, failed, results };
  }

  private async deliverToEndpoint(params: {
    subscription: WebhookSubscription;
    eventId: string;
    eventType: BillingNotificationEventKey;
    payload: SafeNotificationPayload;
    idempotencyKey: string;
  }): Promise<{ accepted: boolean; providerReference: string | null; httpStatus?: number; failureReason?: string }> {
    const timestamp = new Date().toISOString();
    const payloadToSign = {
      eventId: params.eventId,
      eventType: params.eventType,
      timestamp,
      tenantId: params.subscription.tenantId,
      payload: this.sanitizePayload(params.payload),
    };

    const signature = this.signPayload(payloadToSign, params.subscription.secretHash);

    // Idempotency check for webhook delivery
    try {
      const existing = await (this.prisma as any).webhookDeliveryAttempt?.findFirst({
        where: { eventId: params.eventId, subscriptionId: params.subscription.id },
      });
      if (existing && existing.status === 'DELIVERED') {
        this.logger.log(`Idempotent webhook delivery return: event=${params.eventId} subscription=${params.subscription.id}`);
        return { accepted: true, providerReference: existing.id, httpStatus: 200 };
      }
    } catch {}

    try {
      // Use fetch to deliver webhook
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 10000);

      const response = await fetch(params.subscription.endpointUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Webhook-Event-Id': params.eventId,
          'X-Webhook-Event-Type': params.eventType,
          'X-Webhook-Timestamp': timestamp,
          'X-Webhook-Signature': signature,
          'X-Idempotency-Key': params.idempotencyKey,
          'User-Agent': 'WLCT-Billing-Webhook/1.0',
        },
        body: JSON.stringify(payloadToSign),
        signal: controller.signal,
      });

      clearTimeout(timeout);

      const responseText = await response.text().catch(() => '');

      if (response.ok) {
        // Record delivery attempt
        try {
          await (this.prisma as any).webhookDeliveryAttempt?.create({
            data: {
              id: randomUUID(),
              subscriptionId: params.subscription.id,
              tenantId: params.subscription.tenantId,
              eventId: params.eventId,
              eventType: params.eventType,
              endpointUrl: params.subscription.endpointUrl,
              payload: payloadToSign as any,
              signature,
              timestamp: new Date(timestamp),
              status: 'DELIVERED',
              attempt: 1,
              providerReference: `http_${response.status}`,
              createdAt: new Date(),
            },
          });
        } catch {}

        return { accepted: true, providerReference: `http_${response.status}`, httpStatus: response.status };
      } else {
        // Record failed attempt
        try {
          await (this.prisma as any).webhookDeliveryAttempt?.create({
            data: {
              id: randomUUID(),
              subscriptionId: params.subscription.id,
              tenantId: params.subscription.tenantId,
              eventId: params.eventId,
              eventType: params.eventType,
              endpointUrl: params.subscription.endpointUrl,
              payload: payloadToSign as any,
              signature,
              timestamp: new Date(timestamp),
              status: 'FAILED',
              attempt: 1,
              failureReason: `HTTP ${response.status}: ${responseText.substring(0, 500)}`,
              createdAt: new Date(),
            },
          });
        } catch {}

        const retryable = response.status >= 500 || response.status === 429;
        return {
          accepted: false,
          providerReference: null,
          httpStatus: response.status,
          failureReason: `HTTP ${response.status}: ${responseText.substring(0, 500)}`,
        };
      }
    } catch (error: any) {
      const isTimeout = error.name === 'AbortError' || error.message.includes('timeout');
      const failureReason = isTimeout ? `Timeout delivering to ${params.subscription.endpointUrl}` : error.message;

      try {
        await (this.prisma as any).webhookDeliveryAttempt?.create({
          data: {
            id: randomUUID(),
            subscriptionId: params.subscription.id,
            tenantId: params.subscription.tenantId,
            eventId: params.eventId,
            eventType: params.eventType,
            endpointUrl: params.subscription.endpointUrl,
            payload: payloadToSign as any,
            signature,
            timestamp: new Date(timestamp),
            status: 'FAILED',
            attempt: 1,
            failureReason,
            createdAt: new Date(),
          },
        });
      } catch {}

      return {
        accepted: false,
        providerReference: null,
        failureReason,
      };
    }
  }

  private async updateDeliveryStatus(subscriptionId: string, status: string, failureReason?: string): Promise<void> {
    try {
      const data: any = {
        lastDeliveryAt: new Date(),
        lastDeliveryStatus: status,
        updatedAt: new Date(),
      };
      if (status === 'FAILED') {
        data.failureCount = { increment: 1 };
      } else {
        data.failureCount = 0;
      }

      await (this.prisma as any).webhookSubscription?.update({
        where: { id: subscriptionId },
        data,
      });
    } catch {}
  }

  private validateEndpointUrl(url: string): void {
    try {
      const parsed = new URL(url);
      if (parsed.protocol !== 'https:' && process.env.NODE_ENV === 'production') {
        throw new Error('Webhook endpoint must be HTTPS in production');
      }
      // Prevent local/internal destinations
      const blockedHosts = ['localhost', '127.0.0.1', '0.0.0.0', '::1', '169.254.', '10.', '192.168.', '172.16.', '172.17.', '172.18.', '172.19.', '172.20.', '172.21.', '172.22.', '172.23.', '172.24.', '172.25.', '172.26.', '172.27.', '172.28.', '172.29.', '172.30.', '172.31.'];
      const hostname = parsed.hostname.toLowerCase();
      for (const blocked of blockedHosts) {
        if (hostname === blocked || hostname.startsWith(blocked) || hostname.endsWith('.local')) {
          if (process.env.NODE_ENV === 'production') {
            throw new Error(`Webhook endpoint host ${hostname} not allowed`);
          }
        }
      }
      if (url.length > 2048) {
        throw new Error('Endpoint URL too long');
      }
    } catch (e: any) {
      if (e.message.includes('not allowed') || e.message.includes('HTTPS') || e.message.includes('too long')) throw e;
      throw new Error(`Invalid endpoint URL: ${url} - ${e.message}`);
    }
  }

  private hashSecret(secret: string): string {
    // Store hash, not plaintext, using HMAC with server pepper
    const pepper = process.env.WEBHOOK_SECRET_PEPPER || 'default-pepper-change-me';
    return createHmac('sha256', pepper).update(secret).digest('hex');
  }

  private maskSecret(secret: string): string {
    if (secret.length <= 8) return '****';
    return `${secret.substring(0, 4)}...${secret.substring(secret.length - 4)}`;
  }

  private signPayload(payload: any, secretHash: string): string {
    // Sign with secret hash (in real impl, would use actual secret, but we have hash)
    // For demo, sign with hash + timestamp
    const data = JSON.stringify(payload);
    const signingKey = process.env.WEBHOOK_SIGNING_KEY || secretHash;
    return createHmac('sha256', signingKey).update(data).digest('hex');
  }

  private sanitizePayload(payload: SafeNotificationPayload): SafeNotificationPayload {
    const forbidden = ['secret', 'privateKey', 'apiKey', 'password', 'exchangeSecret', 'providerSecret', 'card', 'cvv', 'token', 'accessToken', 'credentials', 'bankAccount', 'walletKey'];
    const safe: any = {};
    for (const [key, value] of Object.entries(payload)) {
      const lowerKey = key.toLowerCase();
      if (forbidden.some((f) => lowerKey.includes(f.toLowerCase()))) {
        safe[key] = '[REDACTED]';
      } else {
        safe[key] = value;
      }
    }
    return safe as SafeNotificationPayload;
  }

  private mapSubscriptionToDomain(raw: any): WebhookSubscription {
    return {
      id: raw.id,
      tenantId: raw.tenantId,
      endpointUrl: raw.endpointUrl,
      eventTypes: raw.eventTypes as BillingNotificationEventKey[],
      enabled: raw.enabled,
      secretHash: raw.secretHash,
      secretMasked: raw.secretMasked,
      lastDeliveryAt: raw.lastDeliveryAt ? new Date(raw.lastDeliveryAt).toISOString() : null,
      lastDeliveryStatus: raw.lastDeliveryStatus || null,
      failureCount: raw.failureCount || 0,
      createdAt: raw.createdAt ? new Date(raw.createdAt).toISOString() : new Date().toISOString(),
      updatedAt: raw.updatedAt ? new Date(raw.updatedAt).toISOString() : new Date().toISOString(),
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { BillingEventService } from './billing-event.service';

/**
 * Dunning notification service: retry, recovered, final failure.
 * Authoritative dunning is DunningService; this service only notifies.
 * Never mutates subscription or payment state.
 */

@Injectable()
export class DunningNotificationService {
  private readonly logger = new Logger(DunningNotificationService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly billingEventService: BillingEventService,
  ) {}

  async notifyDunningRetry(params: {
    tenantId: string;
    paymentId: string;
    dunningId?: string;
    attempt: number;
    maxAttempts: number;
    nextRetryAt?: string;
    amount: string;
    currency: string;
    userId?: string;
  }): Promise<void> {
    try {
      await this.billingEventService.onDunningRetry({
        tenantId: params.tenantId,
        dunningId: params.dunningId || `${params.tenantId}_${params.paymentId}_${params.attempt}`,
        paymentId: params.paymentId,
        userId: params.userId,
        amount: params.amount,
        currency: params.currency,
        dunningAttempt: params.attempt,
        dunningMaxAttempts: params.maxAttempts,
        nextRetryAt: params.nextRetryAt || new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
        supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
        appName: process.env.APP_NAME || 'WLCT',
      });
      this.logger.log(`Dunning retry notification sent tenant=${params.tenantId} attempt=${params.attempt}`);
    } catch (e: any) {
      this.logger.warn(`Failed to notify dunning retry: ${e.message}`);
    }
  }

  async notifyDunningRecovered(params: {
    tenantId: string;
    paymentId: string;
    dunningId?: string;
    amount: string;
    currency: string;
    userId?: string;
  }): Promise<void> {
    try {
      await this.billingEventService.onDunningRecovered({
        tenantId: params.tenantId,
        dunningId: params.dunningId || `${params.tenantId}_${params.paymentId}_recovered`,
        paymentId: params.paymentId,
        userId: params.userId,
        amount: params.amount,
        currency: params.currency,
        supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
        appName: process.env.APP_NAME || 'WLCT',
      });
    } catch (e: any) {
      this.logger.warn(`Failed to notify dunning recovered: ${e.message}`);
    }
  }

  async notifyDunningFinalFailure(params: {
    tenantId: string;
    paymentId: string;
    dunningId?: string;
    amount: string;
    currency: string;
    userId?: string;
  }): Promise<void> {
    try {
      await this.billingEventService.onDunningFinalFailure({
        tenantId: params.tenantId,
        dunningId: params.dunningId || `${params.tenantId}_${params.paymentId}_final`,
        paymentId: params.paymentId,
        userId: params.userId,
        amount: params.amount,
        currency: params.currency,
        dunningMaxAttempts: 4,
        supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
        appName: process.env.APP_NAME || 'WLCT',
      });
    } catch (e: any) {
      this.logger.warn(`Failed to notify dunning final failure: ${e.message}`);
    }
  }

  async processDunningCasesNeedingNotification(): Promise<{ checked: number; notified: number }> {
    let cases: any[] = [];
    try {
      cases = await (this.prisma as any).dunningCase?.findMany?.({
        where: { status: 'ACTIVE', nextRetryAt: { lte: new Date() } },
        take: 50,
      }) || [];
    } catch {
      return { checked: 0, notified: 0 };
    }

    let notified = 0;
    for (const dunningCase of cases) {
      try {
        // Fetch payment for amount
        let payment: any;
        try {
          payment = await (this.prisma as any).payment?.findFirst?.({ where: { id: dunningCase.paymentId } });
        } catch {}

        await this.notifyDunningRetry({
          tenantId: dunningCase.tenantId,
          paymentId: dunningCase.paymentId,
          attempt: dunningCase.attempt || 1,
          maxAttempts: dunningCase.maxAttempts || 4,
          nextRetryAt: dunningCase.nextRetryAt?.toISOString(),
          amount: payment?.amount || '0',
          currency: payment?.currency || 'USD',
        });
        notified++;
      } catch {}
    }

    return { checked: cases.length, notified };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { INotificationProvider, SendNotificationInput, SendNotificationResult, ProviderDeliveryResultType } from './notification-provider.interface';
import { NotificationChannel } from './billing-notification.types';

/**
 * Real email delivery adapter using existing SMTP/email infrastructure.
 * No fake success, no secret leakage, safe error classification.
 */

interface SmtpConfig {
  host: string;
  port: number;
  user: string;
  pass: string;
  from: string;
  secure: boolean;
}

@Injectable()
export class EmailNotificationProvider implements INotificationProvider {
  readonly providerName = 'smtp_email';
  readonly supportedChannels = [NotificationChannel.EMAIL] as NotificationChannel[];
  private readonly logger = new Logger(EmailNotificationProvider.name);
  private readonly smtpConfig: SmtpConfig | null;

  constructor() {
    this.smtpConfig = this.buildSmtpConfig();
  }

  isAvailable(): boolean {
    if (!this.smtpConfig) return false;
    return !!(this.smtpConfig.host && this.smtpConfig.from);
  }

  async send(input: SendNotificationInput): Promise<SendNotificationResult> {
    if (!this.isAvailable()) {
      this.logger.error('SMTP not configured - cannot send email');
      return {
        accepted: false,
        providerReference: null,
        resultType: ProviderDeliveryResultType.PERMANENT_FAILURE,
        retryable: false,
        errorCode: 'SMTP_NOT_CONFIGURED',
        failureReason: 'Email provider not configured. Set SMTP_HOST, SMTP_USER, SMTP_PASS, SMTP_FROM.',
      };
    }

    // Validate recipient
    if (!input.recipientEmail) {
      return {
        accepted: false,
        providerReference: null,
        resultType: ProviderDeliveryResultType.PERMANENT_FAILURE,
        retryable: false,
        errorCode: 'INVALID_RECIPIENT',
        failureReason: 'Recipient email required',
      };
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(input.recipientEmail)) {
      return {
        accepted: false,
        providerReference: null,
        resultType: ProviderDeliveryResultType.PERMANENT_FAILURE,
        retryable: false,
        errorCode: 'INVALID_EMAIL',
        failureReason: `Invalid email: ${input.recipientEmail}`,
      };
    }

    // Sanitize subject/body - no secrets
    const sanitizedSubject = this.sanitizeContent(input.subject);
    const sanitizedBody = this.sanitizeContent(input.body);

    try {
      // Send through nodemailer; without it the message is refused, never faked.
      let messageId: string | null = null;

      try {
        // Dynamic import: nodemailer is a declared dependency of @wlct/api, but a
        // broken install must surface as EMAIL_TRANSPORT_UNAVAILABLE, not a crash.
        const nodemailer = await EmailNotificationProvider.loadNodemailer();

        if (nodemailer) {
          const transporter = nodemailer.createTransport({
            host: this.smtpConfig!.host,
            port: this.smtpConfig!.port,
            secure: this.smtpConfig!.secure,
            auth: this.smtpConfig!.user
              ? {
                  user: this.smtpConfig!.user,
                  pass: this.smtpConfig!.pass,
                }
              : undefined,
          });

          const info = await transporter.sendMail({
            from: this.smtpConfig!.from,
            to: input.recipientEmail,
            subject: sanitizedSubject,
            text: sanitizedBody,
            html: input.htmlBody ? this.sanitizeContent(input.htmlBody) : undefined,
            headers: {
              'X-Idempotency-Key': input.idempotencyKey,
              'X-Tenant-Id': input.tenantId,
              'X-Template-Key': input.templateKey,
            },
          });

          messageId = info.messageId || `smtp_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`;

          this.logger.log(`Email sent via SMTP to=${input.recipientEmail} template=${input.templateKey} messageId=${messageId} tenant=${input.tenantId}`);
        } else {
          // nodemailer could not be loaded, so nothing was sent. Reporting
          // acceptance here (the previous behaviour, with a `dev_` message id)
          // marked invoices and dunning notices as delivered when no message
          // left the process. A missing transport is a deployment fault, not a
          // property of this message: non-retryable for this attempt, and the
          // error code names the fix.
          this.logger.error(
            `Email transport unavailable (nodemailer not installed) - NOT sent to=${input.recipientEmail} template=${input.templateKey} tenant=${input.tenantId} idempotency=${input.idempotencyKey}`,
          );
          return {
            accepted: false,
            providerReference: null,
            resultType: ProviderDeliveryResultType.PERMANENT_FAILURE,
            retryable: false,
            errorCode: 'EMAIL_TRANSPORT_UNAVAILABLE',
            failureReason: 'Email transport unavailable: the nodemailer package is not installed.',
          };
        }
      } catch (smtpError: any) {
        // Classify SMTP errors as temporary vs permanent
        const isTemporary = this.isTemporarySmtpError(smtpError);

        this.logger.error(`SMTP send failed to=${input.recipientEmail} error=${smtpError.message}`, smtpError.stack);

        return {
          accepted: false,
          providerReference: null,
          resultType: isTemporary ? ProviderDeliveryResultType.TEMPORARY_FAILURE : ProviderDeliveryResultType.PERMANENT_FAILURE,
          retryable: isTemporary,
          errorCode: isTemporary ? 'SMTP_TEMPORARY_FAILURE' : 'SMTP_PERMANENT_FAILURE',
          failureReason: smtpError.message,
        };
      }

      // Success - provider returned valid delivery acceptance
      return {
        accepted: true,
        providerReference: messageId,
        resultType: ProviderDeliveryResultType.ACCEPTED,
        retryable: false,
        deliveredAt: new Date().toISOString(),
      };
    } catch (error: any) {
      this.logger.error(`Email provider unexpected error: ${error.message}`, error.stack);

      return {
        accepted: false,
        providerReference: null,
        resultType: ProviderDeliveryResultType.TEMPORARY_FAILURE,
        retryable: true,
        errorCode: 'EMAIL_PROVIDER_ERROR',
        failureReason: error.message,
      };
    }
  }

  /** The nodemailer module, or null when it cannot be loaded. Static so a test can replace it. */
  static async loadNodemailer(): Promise<typeof import('nodemailer') | null> {
    return import('nodemailer').catch(() => null);
  }

  private buildSmtpConfig(): SmtpConfig | null {
    const host = process.env.SMTP_HOST || process.env.EMAIL_HOST || '';
    const port = parseInt(process.env.SMTP_PORT || process.env.EMAIL_PORT || '587', 10);
    const user = process.env.SMTP_USER || process.env.EMAIL_USER || '';
    const pass = process.env.SMTP_PASS || process.env.EMAIL_PASS || '';
    const from = process.env.SMTP_FROM || process.env.EMAIL_FROM || process.env.SMTP_USER || '';
    const secure = (process.env.SMTP_SECURE || 'false').toLowerCase() === 'true';

    if (!host) {
      this.logger.warn('SMTP_HOST not configured - email delivery will fail with config error');
      return null;
    }

    return { host, port, user, pass, from, secure };
  }

  private isTemporarySmtpError(error: any): boolean {
    const message = (error.message || '').toLowerCase();
    const code = (error.code || '').toLowerCase();

    // Temporary errors: network, timeout, rate limit, mailbox full, etc
    const temporaryIndicators = ['timeout', 'econnreset', 'etimedout', 'esocket', 'rate', 'limit', 'try again', 'temporarily', '4.7', '4.3', '4.4', '450', '451', '452', '421'];

    // Permanent errors: invalid recipient, authentication failure, etc
    const permanentIndicators = ['invalid', 'auth', '5.1', '5.2', '550', '551', '553', '501', '535', 'authentication'];

    if (temporaryIndicators.some((ind) => message.includes(ind) || code.includes(ind))) {
      return true;
    }
    if (permanentIndicators.some((ind) => message.includes(ind) || code.includes(ind))) {
      return false;
    }

    // Default to temporary for retry safety, unless clearly permanent
    return true;
  }

  private sanitizeContent(content: string): string {
    if (!content) return '';
    // Never include secrets in email content
    const forbiddenPatterns = [
      /stripe[_-]?secret/gi,
      /nowpayments[_-]?api[_-]?key/gi,
      /exchange[_-]?secret/gi,
      /private[_-]?key/gi,
      /api[_-]?secret/gi,
      /password/gi,
    ];

    let sanitized = content;
    for (const pattern of forbiddenPatterns) {
      if (pattern.test(sanitized)) {
        // Redact lines containing forbidden patterns
        sanitized = sanitized
          .split('\n')
          .map((line) => (pattern.test(line) ? line.replace(pattern, '[REDACTED]') : line))
          .join('\n');
      }
    }

    return sanitized;
  }
}

import { Injectable, Logger, Optional } from '@nestjs/common';
import { RealtimeEvent } from '@wlct/shared-types';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { BillingNotificationEventKey, NotificationChannel } from './billing-notification.types';
import { randomUUID } from 'crypto';
import { RealtimeService } from '../../realtime/realtime.service';

/**
 * Creates tenant/user-scoped in-app notification records using existing
 * notification/persistence infrastructure where available.
 * Does NOT create second generic notification DB if one already exists.
 */
@Injectable()
export class InAppNotificationService {
  private readonly logger = new Logger(InAppNotificationService.name);

  constructor(
    private readonly prisma: PrismaService,
    // Global module; optional so unit tests and workers without realtime still build.
    @Optional() private readonly realtime?: RealtimeService,
  ) {}

  async createNotification(params: {
    tenantId: string;
    userId: string;
    eventKey: BillingNotificationEventKey;
    channel: NotificationChannel;
    title: string;
    body: string;
    safePayload: any;
    idempotencyKey: string;
  }): Promise<any> {
    // Idempotency check
    try {
      const existing = await (this.prisma as any).notification?.findFirst({
        where: {
          tenantId: params.tenantId,
          userId: params.userId,
          type: params.eventKey,
          // Check idempotency via data field if possible
        },
      });

      // Check by idempotency key in billingNotificationJob if exists
      const existingBilling = await (this.prisma as any).billingNotificationJob?.findFirst({
        where: { tenantId: params.tenantId, idempotencyKey: params.idempotencyKey },
      });
      if (existingBilling && existingBilling.deliveryStatus === 'SENT') {
        this.logger.log(`Idempotent in-app notification return by idempotencyKey: ${params.idempotencyKey}`);
        return existing;
      }
    } catch {}

    try {
      const record = await this.prisma.notification.create({
        data: {
          id: randomUUID(),
          tenantId: params.tenantId,
          userId: params.userId,
          channel: NotificationChannel.IN_APP as any,
          type: params.eventKey,
          title: params.title,
          body: params.body,
          data: params.safePayload as any,
          deliveredAt: new Date(),
          createdAt: new Date(),
        },
      });

      this.logger.log(`In-app notification created tenant=${params.tenantId} user=${params.userId} event=${params.eventKey} id=${record.id}`);

      // Realtime fan-out through the shared RealtimeService (Redis -> socket
      // owner). The notification is already persisted, so a publish failure
      // only delays the client until its next fetch; it is logged, not thrown.
      if (this.realtime) {
        try {
          await this.realtime.emitToUser(params.tenantId, params.userId, RealtimeEvent.NOTIFICATION_CREATED, {
            id: record.id,
            type: params.eventKey,
            title: params.title,
          });
        } catch (e) {
          this.logger.warn(`Realtime publish failed for notification ${record.id}: ${(e as Error).message}`);
        }
      }

      return record;
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        this.logger.warn(`notification table not found, fallback: ${error.message}`);
        // Fallback to audit log
        try {
          await (this.prisma as any).auditLog?.create({
            data: {
              id: randomUUID(),
              tenantId: params.tenantId,
              action: 'IN_APP_NOTIFICATION_CREATED',
              resourceType: 'Notification',
              resourceId: randomUUID(),
              metadata: {
                userId: params.userId,
                eventKey: params.eventKey,
                title: params.title,
                body: params.body,
                safePayload: params.safePayload,
                idempotencyKey: params.idempotencyKey,
                fallback: true,
              },
              createdAt: new Date(),
            },
          });
        } catch {}
        return { id: randomUUID(), tenantId: params.tenantId, userId: params.userId, type: params.eventKey, title: params.title, fallback: true };
      }
      throw error;
    }
  }

  async markRead(tenantId: string, userId: string, notificationId: string): Promise<any> {
    try {
      const existing = await this.prisma.notification.findFirst({
        where: { id: notificationId, tenantId, userId },
        select: { id: true },
      });

      if (!existing) {
        throw new Error(`Notification not found: ${notificationId}`);
      }

      const updated = await this.prisma.notification.update({
        where: { id: notificationId },
        data: { readAt: new Date() },
      });

      return updated;
    } catch (error: any) {
      if (error.message.includes('not found')) throw error;
      this.logger.warn(`Failed to mark notification read: ${error.message}`);
      throw error;
    }
  }

  async markAllRead(tenantId: string, userId: string): Promise<{ updated: number }> {
    try {
      const result = await this.prisma.notification.updateMany({
        where: { tenantId, userId, readAt: null },
        data: { readAt: new Date() },
      });
      return { updated: result.count };
    } catch {
      return { updated: 0 };
    }
  }

  async getUnreadCount(tenantId: string, userId: string): Promise<number> {
    const count = await this.prisma.notification.count({
      where: { tenantId, userId, readAt: null },
    });
    return count;
  }

  async listNotifications(
    tenantId: string,
    userId: string,
    filter?: { unreadOnly?: boolean; eventKey?: string; channel?: string; fromDate?: Date; toDate?: Date; limit?: number; offset?: number },
  ): Promise<any[]> {
    const where: any = { tenantId, userId };
    if (filter?.unreadOnly) where.readAt = null;
    if (filter?.eventKey) where.type = filter.eventKey;
    if (filter?.channel) where.channel = filter.channel;
    if (filter?.fromDate || filter?.toDate) {
      where.createdAt = {};
      if (filter.fromDate) where.createdAt.gte = filter.fromDate;
      if (filter.toDate) where.createdAt.lte = filter.toDate;
    }

    const results = await this.prisma.notification.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: filter?.limit || 50,
      skip: filter?.offset || 0,
    });

    return results;
  }

  async archiveNotification(tenantId: string, userId: string, notificationId: string): Promise<any> {
    try {
      const existing = await this.prisma.notification.findFirst({
        where: { id: notificationId, tenantId, userId },
      });
      if (!existing) throw new Error(`Notification not found: ${notificationId}`);

      // Archive by setting readAt and optionally deletedAt if model supports
      const updated = await this.prisma.notification.update({
        where: { id: notificationId },
        data: { readAt: new Date() },
      });

      return updated;
    } catch (error: any) {
      this.logger.warn(`Failed to archive notification: ${error.message}`);
      throw error;
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { BillingEventService } from './billing-event.service';

/**
 * Invoice delivery service: safe totals + access link, no internal paths.
 * Ensures invoice delivery is tenant-safe, sanitized, idempotent.
 */

@Injectable()
export class InvoiceDeliveryService {
  private readonly logger = new Logger(InvoiceDeliveryService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly billingEventService: BillingEventService,
  ) {}

  async deliverInvoice(params: {
    tenantId: string;
    invoiceId: string;
    userId?: string;
    accessLinkBaseUrl?: string;
  }): Promise<{ delivered: boolean; accessLink: string; safeTotals: any }> {
    // Fetch invoice
    let invoice: any;
    try {
      invoice = await (this.prisma as any).invoice?.findFirst({
        where: { id: params.invoiceId, tenantId: params.tenantId },
      });
    } catch {}

    if (!invoice) {
      try {
        const repo = await (this.prisma as any).invoice?.findFirst?.({ where: { id: params.invoiceId } });
        invoice = repo;
      } catch {}
    }

    // Build safe totals - never expose internal paths, only safe fields
    const safeTotals = {
      invoiceNumber: invoice?.invoiceNumber || params.invoiceId,
      subtotal: invoice?.subtotal || '0',
      taxTotal: invoice?.taxTotal || '0',
      total: invoice?.total || '0',
      amountPaid: invoice?.amountPaid || '0',
      amountDue: invoice?.amountDue || invoice?.total || '0',
      currency: invoice?.currency || 'USD',
      status: invoice?.status || 'FINALIZED',
      dueDate: invoice?.dueDate ? new Date(invoice.dueDate).toISOString() : null,
      issuedAt: invoice?.issuedAt ? new Date(invoice.issuedAt).toISOString() : new Date().toISOString(),
    };

    // Build safe access link - no internal paths, only via portal
    const baseUrl = params.accessLinkBaseUrl || process.env.BILLING_PORTAL_URL || process.env.APP_URL || 'https://app.example.com';
    // Ensure baseUrl is HTTPS in production and not internal
    const safeBase = this.sanitizeBaseUrl(baseUrl);
    const accessLink = `${safeBase}/billing/invoices/${params.invoiceId}`;

    this.logger.log(`Invoice delivery prepared tenant=${params.tenantId} invoice=${params.invoiceId} link=${accessLink}`);

    // Trigger notification via billing event service
    try {
      if (invoice?.status === 'PAID') {
        await this.billingEventService.onInvoicePaid({
          tenantId: params.tenantId,
          invoiceId: params.invoiceId,
          invoiceNumber: safeTotals.invoiceNumber,
          userId: params.userId,
          amount: safeTotals.total,
          currency: safeTotals.currency,
          supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
          appName: process.env.APP_NAME || 'WLCT',
        });
      } else {
        await this.billingEventService.onInvoiceFinalized({
          tenantId: params.tenantId,
          invoiceId: params.invoiceId,
          invoiceNumber: safeTotals.invoiceNumber,
          userId: params.userId,
          amount: safeTotals.total,
          currency: safeTotals.currency,
          supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
          appName: process.env.APP_NAME || 'WLCT',
        });
      }
    } catch (e: any) {
      this.logger.warn(`Failed to trigger invoice delivery notification: ${e.message}`);
    }

    return { delivered: true, accessLink, safeTotals };
  }

  async deliverOverdueNotice(params: { tenantId: string; invoiceId: string; userId?: string }): Promise<void> {
    try {
      let invoice: any;
      try {
        invoice = await (this.prisma as any).invoice?.findFirst({
          where: { id: params.invoiceId, tenantId: params.tenantId },
        });
      } catch {}

      await this.billingEventService.onInvoiceOverdue({
        tenantId: params.tenantId,
        invoiceId: params.invoiceId,
        invoiceNumber: invoice?.invoiceNumber || params.invoiceId,
        userId: params.userId,
        amount: invoice?.total || '0',
        currency: invoice?.currency || 'USD',
        supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
        appName: process.env.APP_NAME || 'WLCT',
      });
    } catch (e: any) {
      this.logger.warn(`Failed to trigger overdue notice: ${e.message}`);
    }
  }

  private sanitizeBaseUrl(url: string): string {
    try {
      const parsed = new URL(url);
      // Prevent internal destinations
      const blocked = ['localhost', '127.0.0.1', '0.0.0.0', '169.254.', '10.', '192.168.'];
      const hostname = parsed.hostname.toLowerCase();
      for (const b of blocked) {
        if (hostname === b || hostname.startsWith(b)) {
          if (process.env.NODE_ENV === 'production') {
            return 'https://app.example.com';
          }
        }
      }
      // No internal paths, only origin
      return `${parsed.protocol}//${parsed.host}`;
    } catch {
      return 'https://app.example.com';
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { BillingNotificationJob, DeliveryStatus, NotificationChannel, BillingNotificationEventKey, NotificationPriority, NotificationCategory } from './billing-notification.types';
import { randomUUID } from 'crypto';

/**
 * Persistent notification job storage, idempotency, retry state, attempts, next-attempt,
 * delivery status, tenant isolation. Prevents duplicate jobs from same canonical event.
 */
@Injectable()
export class NotificationJobRepository {
  private readonly logger = new Logger(NotificationJobRepository.name);

  constructor(private readonly prisma: PrismaService) {}

  async create(job: {
    tenantId: string;
    userId?: string;
    recipient: any;
    eventKey: BillingNotificationEventKey;
    channel: NotificationChannel;
    templateKey: string;
    locale: string;
    priority: NotificationPriority;
    category: NotificationCategory;
    deliveryStatus: DeliveryStatus;
    maxAttempts: number;
    idempotencyKey: string;
    safePayload: any;
    renderedSubject?: string;
    renderedBody?: string;
  }): Promise<BillingNotificationJob> {
    // Idempotency check
    const existingByKey = await this.findByIdempotencyKey(job.idempotencyKey, job.tenantId);
    if (existingByKey) {
      this.logger.log(`Idempotent notification job return by key: ${job.idempotencyKey}`);
      return existingByKey;
    }

    const id = randomUUID();
    const now = new Date().toISOString();

    const notificationJob: BillingNotificationJob = {
      id,
      tenantId: job.tenantId,
      userId: job.userId,
      recipient: job.recipient,
      eventKey: job.eventKey,
      channel: job.channel,
      templateKey: job.templateKey,
      locale: job.locale,
      priority: job.priority,
      category: job.category,
      deliveryStatus: job.deliveryStatus,
      attemptCount: 0,
      maxAttempts: job.maxAttempts,
      nextAttemptAt: null,
      providerReference: null,
      idempotencyKey: job.idempotencyKey,
      safePayload: job.safePayload,
      renderedSubject: job.renderedSubject,
      renderedBody: job.renderedBody,
      failureReason: null,
      createdAt: now,
      updatedAt: now,
      sentAt: null,
      deliveredAt: null,
    };

    try {
      const created = await (this.prisma as any).billingNotificationJob?.create({
        data: {
          id: notificationJob.id,
          tenantId: notificationJob.tenantId,
          userId: notificationJob.userId || null,
          recipient: notificationJob.recipient as any,
          eventKey: notificationJob.eventKey,
          channel: notificationJob.channel,
          templateKey: notificationJob.templateKey,
          locale: notificationJob.locale,
          priority: notificationJob.priority,
          category: notificationJob.category,
          deliveryStatus: notificationJob.deliveryStatus,
          attemptCount: notificationJob.attemptCount,
          maxAttempts: notificationJob.maxAttempts,
          nextAttemptAt: null,
          providerReference: null,
          idempotencyKey: notificationJob.idempotencyKey,
          safePayload: notificationJob.safePayload as any,
          renderedSubject: notificationJob.renderedSubject || null,
          renderedBody: notificationJob.renderedBody || null,
          failureReason: null,
          createdAt: new Date(notificationJob.createdAt),
          updatedAt: new Date(notificationJob.updatedAt),
          sentAt: null,
          deliveredAt: null,
        },
      });

      if (created) {
        return this.mapToDomain(created);
      }
    } catch (error: any) {
      if (error.code === 'P2002') {
        this.logger.warn(`Duplicate notification job idempotency: ${job.idempotencyKey}`);
        const existing = await this.findByIdempotencyKey(job.idempotencyKey, job.tenantId);
        if (existing) return existing;
      }
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        this.logger.warn(`billingNotificationJob table not found, fallback: ${error.message}`);
        try {
          await (this.prisma as any).auditLog?.create({
            data: {
              id: randomUUID(),
              tenantId: job.tenantId,
              action: 'NOTIFICATION_CREATED',
              resourceType: 'BillingNotificationJob',
              resourceId: id,
              metadata: { ...notificationJob, fallback: true },
              createdAt: new Date(),
            },
          });
        } catch {}
        return notificationJob;
      }
      this.logger.error(`Failed to create notification job: ${error.message}`, error.stack);
      throw error;
    }

    return notificationJob;
  }

  async findById(id: string, tenantId?: string): Promise<BillingNotificationJob | null> {
    const result = await (this.prisma as any).billingNotificationJob?.findFirst({
      where: { id, ...(tenantId ? { tenantId } : {}) },
    });
    if (!result) return null;
    return this.mapToDomain(result);
  }

  async findByIdempotencyKey(idempotencyKey: string, tenantId: string): Promise<BillingNotificationJob | null> {
    const result = await (this.prisma as any).billingNotificationJob?.findFirst({
      where: { idempotencyKey, tenantId },
    });
    if (!result) return null;
    return this.mapToDomain(result);
  }

  async findPendingJobs(limit: number = 50): Promise<BillingNotificationJob[]> {
    const results = await (this.prisma as any).billingNotificationJob?.findMany({
      where: {
        deliveryStatus: { in: [DeliveryStatus.CREATED, DeliveryStatus.PENDING, DeliveryStatus.QUEUED] },
      },
      orderBy: [{ priority: 'desc' }, { createdAt: 'asc' }],
      take: limit,
    });
    if (!results) return [];
    return results.map((r: any) => this.mapToDomain(r));
  }

  async findRetryableJobs(limit: number = 50): Promise<BillingNotificationJob[]> {
    const now = new Date();
    const results = await (this.prisma as any).billingNotificationJob?.findMany({
      where: {
        deliveryStatus: DeliveryStatus.RETRY_SCHEDULED,
        nextAttemptAt: { lte: now },
        attemptCount: { lt: 10 },
      },
      orderBy: { nextAttemptAt: 'asc' },
      take: limit,
    });
    if (!results) return [];
    return results.map((r: any) => this.mapToDomain(r));
  }

  async findFailedJobs(limit: number = 50): Promise<BillingNotificationJob[]> {
    const results = await (this.prisma as any).billingNotificationJob?.findMany({
      where: {
        deliveryStatus: { in: [DeliveryStatus.FAILED, DeliveryStatus.PERMANENT_FAILURE] },
      },
      orderBy: { updatedAt: 'desc' },
      take: limit,
    });
    if (!results) return [];
    return results.map((r: any) => this.mapToDomain(r));
  }

  async listByTenant(
    tenantId: string,
    filter?: {
      eventKey?: BillingNotificationEventKey;
      channel?: NotificationChannel;
      status?: DeliveryStatus;
      userId?: string;
      fromDate?: Date;
      toDate?: Date;
      limit?: number;
      offset?: number;
    },
  ): Promise<BillingNotificationJob[]> {
    const where: any = { tenantId };
    if (filter?.eventKey) where.eventKey = filter.eventKey;
    if (filter?.channel) where.channel = filter.channel;
    if (filter?.status) where.deliveryStatus = filter.status;
    if (filter?.userId) where.userId = filter.userId;
    if (filter?.fromDate || filter?.toDate) {
      where.createdAt = {};
      if (filter.fromDate) where.createdAt.gte = filter.fromDate;
      if (filter.toDate) where.createdAt.lte = filter.toDate;
    }

    const results = await (this.prisma as any).billingNotificationJob?.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: filter?.limit || 100,
      skip: filter?.offset || 0,
    });

    if (!results) return [];
    return results.map((r: any) => this.mapToDomain(r));
  }

  async updateStatus(
    id: string,
    updates: {
      deliveryStatus?: DeliveryStatus;
      attemptCount?: number;
      nextAttemptAt?: string | null;
      providerReference?: string | null;
      failureReason?: string | null;
      renderedSubject?: string;
      renderedBody?: string;
      sentAt?: string | null;
      deliveredAt?: string | null;
    },
  ): Promise<BillingNotificationJob | null> {
    try {
      const data: any = { updatedAt: new Date() };
      if (updates.deliveryStatus) data.deliveryStatus = updates.deliveryStatus;
      if (updates.attemptCount !== undefined) data.attemptCount = updates.attemptCount;
      if (updates.nextAttemptAt !== undefined) data.nextAttemptAt = updates.nextAttemptAt ? new Date(updates.nextAttemptAt) : null;
      if (updates.providerReference !== undefined) data.providerReference = updates.providerReference;
      if (updates.failureReason !== undefined) data.failureReason = updates.failureReason;
      if (updates.renderedSubject) data.renderedSubject = updates.renderedSubject;
      if (updates.renderedBody) data.renderedBody = updates.renderedBody;
      if (updates.sentAt !== undefined) data.sentAt = updates.sentAt ? new Date(updates.sentAt) : null;
      if (updates.deliveredAt !== undefined) data.deliveredAt = updates.deliveredAt ? new Date(updates.deliveredAt) : null;

      const updated = await (this.prisma as any).billingNotificationJob?.update({
        where: { id },
        data,
      });

      if (!updated) return null;
      return this.mapToDomain(updated);
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) return null;
      throw error;
    }
  }

  private mapToDomain(raw: any): BillingNotificationJob {
    return {
      id: raw.id,
      tenantId: raw.tenantId,
      userId: raw.userId || undefined,
      recipient: raw.recipient,
      eventKey: raw.eventKey as BillingNotificationEventKey,
      channel: raw.channel as NotificationChannel,
      templateKey: raw.templateKey,
      locale: raw.locale,
      priority: raw.priority as any,
      category: raw.category as any,
      deliveryStatus: raw.deliveryStatus as DeliveryStatus,
      attemptCount: raw.attemptCount,
      maxAttempts: raw.maxAttempts,
      nextAttemptAt: raw.nextAttemptAt ? new Date(raw.nextAttemptAt).toISOString() : null,
      providerReference: raw.providerReference || null,
      idempotencyKey: raw.idempotencyKey,
      safePayload: raw.safePayload,
      renderedSubject: raw.renderedSubject || undefined,
      renderedBody: raw.renderedBody || undefined,
      failureReason: raw.failureReason || null,
      createdAt: raw.createdAt ? new Date(raw.createdAt).toISOString() : new Date().toISOString(),
      updatedAt: raw.updatedAt ? new Date(raw.updatedAt).toISOString() : new Date().toISOString(),
      sentAt: raw.sentAt ? new Date(raw.sentAt).toISOString() : null,
      deliveredAt: raw.deliveredAt ? new Date(raw.deliveredAt).toISOString() : null,
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { BillingNotificationEventKey, NotificationChannel, MANDATORY_BILLING_EVENTS } from './billing-notification.types';
import { randomUUID } from 'crypto';

/**
 * Tenant/user notification preferences, channel preferences, opt-in/out rules,
 * mandatory vs optional notification policy.
 * Mandatory billing notifications cannot be disabled.
 */

export interface NotificationPreference {
  id: string;
  tenantId: string;
  userId?: string;
  eventKey?: BillingNotificationEventKey;
  channel: NotificationChannel;
  enabled: boolean;
  category: string;
  isMandatory: boolean;
  locale: string;
  createdAt: string;
  updatedAt: string;
}

@Injectable()
export class NotificationPreferenceService {
  private readonly logger = new Logger(NotificationPreferenceService.name);

  constructor(private readonly prisma: PrismaService) {}

  async getPreferences(tenantId: string, userId?: string): Promise<NotificationPreference[]> {
    try {
      const where: any = { tenantId };
      if (userId) where.userId = userId;

      const results = await (this.prisma as any).billingNotificationPreference?.findMany({
        where,
        orderBy: { eventKey: 'asc' },
      });

      if (results && results.length > 0) {
        return results.map((r: any) => this.mapToDomain(r));
      }

      // Return defaults if none configured
      return this.getDefaultPreferences(tenantId, userId);
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        return this.getDefaultPreferences(tenantId, userId);
      }
      throw error;
    }
  }

  async getChannelPreferences(tenantId: string, userId: string, category: string): Promise<{ channel: NotificationChannel; enabled: boolean }[]> {
    // Reuse existing notification preferences from main notifications module if available
    try {
      const existing = await (this.prisma as any).notificationPreference?.findMany({
        where: { userId, category },
      });

      if (existing && existing.length > 0) {
        return existing.map((p: any) => ({
          channel: p.channel as NotificationChannel,
          enabled: p.enabled,
        }));
      }
    } catch {}

    // Fallback to billing preferences
    const billingPrefs = await this.getPreferences(tenantId, userId);
    const grouped = new Map<NotificationChannel, boolean>();

    for (const pref of billingPrefs) {
      if (pref.category === category || !category) {
        grouped.set(pref.channel, pref.enabled);
      }
    }

    if (grouped.size === 0) {
      // Default: all channels enabled
      return [
        { channel: NotificationChannel.EMAIL, enabled: true },
        { channel: NotificationChannel.IN_APP, enabled: true },
        { channel: NotificationChannel.PUSH, enabled: true },
        { channel: NotificationChannel.WEBHOOK, enabled: false },
      ];
    }

    return Array.from(grouped.entries()).map(([channel, enabled]) => ({ channel, enabled }));
  }

  async isChannelEnabled(tenantId: string, userId: string | undefined, eventKey: BillingNotificationEventKey, channel: NotificationChannel): Promise<{ enabled: boolean; isMandatory: boolean; reason?: string }> {
    const isMandatory = MANDATORY_BILLING_EVENTS.has(eventKey);

    // Mandatory billing notifications cannot be disabled
    if (isMandatory && (channel === NotificationChannel.EMAIL || channel === NotificationChannel.IN_APP)) {
      return { enabled: true, isMandatory: true, reason: 'Mandatory billing notification - cannot be disabled' };
    }

    try {
      const pref = await (this.prisma as any).billingNotificationPreference?.findFirst({
        where: {
          tenantId,
          ...(userId ? { userId } : {}),
          eventKey,
          channel,
        },
      });

      if (pref) {
        // Even if user disabled, mandatory events remain enabled
        if (isMandatory && !pref.enabled && (channel === NotificationChannel.EMAIL || channel === NotificationChannel.IN_APP)) {
          return { enabled: true, isMandatory: true, reason: 'Mandatory billing notification overrides user preference' };
        }
        return { enabled: pref.enabled, isMandatory, reason: pref.enabled ? undefined : 'User disabled this channel for this event' };
      }

      // No specific preference - check category preference
      const category = this.getCategoryForEvent(eventKey);
      // A tenant-level billing event has no recipient user, so there is no
      // per-user category preference to consult. Querying with a placeholder
      // id put a non-UUID into a UUID column and logged a database error on
      // every tenant-level delivery.
      const categoryPrefs = userId ? await this.getChannelPreferences(tenantId, userId, category) : [];
      const channelPref = categoryPrefs.find((p) => p.channel === channel);
      if (channelPref) {
        if (isMandatory && !channelPref.enabled && (channel === NotificationChannel.EMAIL || channel === NotificationChannel.IN_APP)) {
          return { enabled: true, isMandatory: true, reason: 'Mandatory billing notification overrides category preference' };
        }
        return { enabled: channelPref.enabled, isMandatory };
      }

      // Default enabled for all except webhook
      const defaultEnabled = channel !== NotificationChannel.WEBHOOK;
      return { enabled: defaultEnabled, isMandatory };
    } catch {
      // On error, default to enabled for mandatory, disabled for optional webhook
      const defaultEnabled = isMandatory || channel !== NotificationChannel.WEBHOOK;
      return { enabled: defaultEnabled, isMandatory };
    }
  }

  async updatePreference(params: {
    tenantId: string;
    userId?: string;
    eventKey?: BillingNotificationEventKey;
    channel: NotificationChannel;
    enabled: boolean;
    category?: string;
    locale?: string;
  }): Promise<NotificationPreference> {
    // Prevent disabling mandatory billing notifications for EMAIL and IN_APP
    if (params.eventKey && MANDATORY_BILLING_EVENTS.has(params.eventKey) && !params.enabled) {
      if (params.channel === NotificationChannel.EMAIL || params.channel === NotificationChannel.IN_APP) {
        throw new Error(`Cannot disable mandatory billing notification ${params.eventKey} for channel ${params.channel}`);
      }
    }

    const id = randomUUID();
    const now = new Date().toISOString();
    const isMandatory = params.eventKey ? MANDATORY_BILLING_EVENTS.has(params.eventKey) : false;
    const category = params.category || (params.eventKey ? this.getCategoryForEvent(params.eventKey) : 'billing');

    const preference: NotificationPreference = {
      id,
      tenantId: params.tenantId,
      userId: params.userId,
      eventKey: params.eventKey,
      channel: params.channel,
      enabled: params.enabled,
      category,
      isMandatory,
      locale: params.locale || 'en',
      createdAt: now,
      updatedAt: now,
    };

    try {
      const result = await (this.prisma as any).billingNotificationPreference?.upsert({
        where: {
          tenantId_userId_eventKey_channel: {
            tenantId: params.tenantId,
            userId: params.userId || '',
            eventKey: params.eventKey || '',
            channel: params.channel,
          },
        },
        update: {
          enabled: params.enabled,
          updatedAt: new Date(),
          locale: params.locale || 'en',
        },
        create: {
          id: preference.id,
          tenantId: preference.tenantId,
          userId: preference.userId || null,
          eventKey: preference.eventKey || null,
          channel: preference.channel,
          enabled: preference.enabled,
          category: preference.category,
          isMandatory: preference.isMandatory,
          locale: preference.locale,
          createdAt: new Date(preference.createdAt),
          updatedAt: new Date(preference.updatedAt),
        },
      });

      if (result) return this.mapToDomain(result);
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        this.logger.warn(`billingNotificationPreference table not found, fallback: ${error.message}`);
        return preference;
      }
      if (error.code === 'P2002') {
        // Try to find existing
        try {
          const existing = await (this.prisma as any).billingNotificationPreference?.findFirst({
            where: {
              tenantId: params.tenantId,
              userId: params.userId || null,
              eventKey: params.eventKey || null,
              channel: params.channel,
            },
          });
          if (existing) {
            const updated = await (this.prisma as any).billingNotificationPreference?.update({
              where: { id: existing.id },
              data: { enabled: params.enabled, updatedAt: new Date() },
            });
            if (updated) return this.mapToDomain(updated);
          }
        } catch {}
      }
      throw error;
    }

    return preference;
  }

  async updatePreferencesBulk(
    tenantId: string,
    userId: string | undefined,
    preferences: { eventKey?: BillingNotificationEventKey; channel: NotificationChannel; enabled: boolean; category?: string }[],
  ): Promise<NotificationPreference[]> {
    const results: NotificationPreference[] = [];
    for (const pref of preferences) {
      try {
        const updated = await this.updatePreference({
          tenantId,
          userId,
          eventKey: pref.eventKey,
          channel: pref.channel,
          enabled: pref.enabled,
          category: pref.category,
        });
        results.push(updated);
      } catch (e) {
        this.logger.warn(`Failed to update preference ${pref.eventKey} ${pref.channel}: ${(e as Error).message}`);
        // For mandatory, we throw, but for bulk we skip and continue
        if ((e as Error).message.includes('Cannot disable mandatory')) {
          throw e;
        }
      }
    }
    return results;
  }

  private getDefaultPreferences(tenantId: string, userId?: string): NotificationPreference[] {
    const now = new Date().toISOString();
    const preferences: NotificationPreference[] = [];

    for (const eventKey of Object.values(BillingNotificationEventKey)) {
      const isMandatory = MANDATORY_BILLING_EVENTS.has(eventKey as BillingNotificationEventKey);
      const category = this.getCategoryForEvent(eventKey as BillingNotificationEventKey);

      for (const channel of [NotificationChannel.EMAIL, NotificationChannel.IN_APP, NotificationChannel.PUSH]) {
        preferences.push({
          id: `default_${tenantId}_${userId || 'tenant'}_${eventKey}_${channel}`,
          tenantId,
          userId,
          eventKey: eventKey as BillingNotificationEventKey,
          channel,
          enabled: true,
          category,
          isMandatory,
          locale: 'en',
          createdAt: now,
          updatedAt: now,
        });
      }

      // Webhook disabled by default
      preferences.push({
        id: `default_${tenantId}_${userId || 'tenant'}_${eventKey}_WEBHOOK`,
        tenantId,
        userId,
        eventKey: eventKey as BillingNotificationEventKey,
        channel: NotificationChannel.WEBHOOK,
        enabled: false,
        category,
        isMandatory: false,
        locale: 'en',
        createdAt: now,
        updatedAt: now,
      });
    }

    return preferences;
  }

  private getCategoryForEvent(eventKey: BillingNotificationEventKey): string {
    if (eventKey.startsWith('PAYMENT_') || eventKey.startsWith('REFUND_')) return 'billing';
    if (eventKey.startsWith('INVOICE_')) return 'billing';
    if (eventKey.startsWith('SUBSCRIPTION_') || eventKey.startsWith('TRIAL_')) return 'subscription';
    if (eventKey.startsWith('DUNNING_')) return 'dunning';
    if (eventKey.startsWith('USAGE_')) return 'usage';
    if (eventKey.startsWith('FEE_') || eventKey.startsWith('PAYOUT_')) return 'fee';
    if (eventKey.startsWith('CUSTOM_DOMAIN_') || eventKey.startsWith('WHITE_LABEL_') || eventKey.startsWith('SAAS_')) return 'saas_admin';
    return 'billing';
  }

  private mapToDomain(raw: any): NotificationPreference {
    return {
      id: raw.id,
      tenantId: raw.tenantId,
      userId: raw.userId || undefined,
      eventKey: raw.eventKey as BillingNotificationEventKey || undefined,
      channel: raw.channel as NotificationChannel,
      enabled: raw.enabled,
      category: raw.category,
      isMandatory: raw.isMandatory || false,
      locale: raw.locale || 'en',
      createdAt: raw.createdAt ? new Date(raw.createdAt).toISOString() : new Date().toISOString(),
      updatedAt: raw.updatedAt ? new Date(raw.updatedAt).toISOString() : new Date().toISOString(),
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { NotificationChannel } from './billing-notification.types';
import { INotificationProvider } from './notification-provider.interface';
import { EmailNotificationProvider } from './email-notification.provider';
import { PushNotificationService } from './push-notification.service';
import { TwilioSmsProvider } from './twilio-sms.provider';

/**
 * Selects configured notification providers using existing app config and availability.
 * Explicit config error when missing, no fake success, no secrets in logs.
 */

class NoOpNotificationProvider implements INotificationProvider {
  readonly providerName = 'noop';
  readonly supportedChannels = [] as NotificationChannel[];

  isAvailable(): boolean {
    return false;
  }

  async send(): Promise<any> {
    throw new Error('Notification provider not configured. No fake success allowed.');
  }
}

class InAppOnlyProvider implements INotificationProvider {
  readonly providerName = 'in_app_only';
  readonly supportedChannels = [NotificationChannel.IN_APP] as NotificationChannel[];

  isAvailable(): boolean {
    return true;
  }

  async send(input: any): Promise<any> {
    // In-app is always available via DB
    return {
      accepted: true,
      providerReference: `inapp_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`,
      resultType: 'ACCEPTED',
      retryable: false,
      deliveredAt: new Date().toISOString(),
    };
  }
}

@Injectable()
export class NotificationProviderFactory {
  private readonly logger = new Logger(NotificationProviderFactory.name);

  constructor(
    private readonly emailProvider: EmailNotificationProvider,
    private readonly pushProvider: PushNotificationService,
  ) {}

  getProvider(channel: NotificationChannel): INotificationProvider {
    switch (channel) {
      case NotificationChannel.EMAIL:
        if (this.emailProvider.isAvailable()) {
          this.logger.log(`Selected notification provider for EMAIL: ${this.emailProvider.providerName}`);
          return this.emailProvider;
        }
        this.logger.warn(`Email provider not available, falling back to NoOp - will fail with config error`);
        return new NoOpNotificationProvider();

      case NotificationChannel.IN_APP:
        return new InAppOnlyProvider();

      case NotificationChannel.PUSH:
        // The real FCM adapter. It reports PUSH_NOT_CONFIGURED /
        // PUSH_PROVIDER_UNAVAILABLE itself; previously a configured push
        // channel was handed the in-app stub, which "accepted" every push
        // without sending anything.
        if (this.pushProvider.isAvailable()) {
          return this.pushProvider;
        }
        this.logger.warn('Push provider not configured');
        return new NoOpNotificationProvider();

      case NotificationChannel.WEBHOOK:
        // Webhook delivery is performed by NotificationDeliveryService
        // (deliverWebhook) and never reaches this factory; answering here with
        // an always-accepting stub would hide a routing mistake.
        return new NoOpNotificationProvider();

      case NotificationChannel.SMS: {
        // SMS_PROVIDER=twilio selects the Twilio REST adapter; it is only
        // returned when fully configured. Anything else (unset, unknown
        // provider, incomplete Twilio settings) fails closed. SMS_PROVIDER
        // used to select the in-app stub, which reported every SMS as sent.
        const smsProvider = (process.env.SMS_PROVIDER || '').trim().toLowerCase();
        if (smsProvider === 'twilio') {
          const twilio = new TwilioSmsProvider();
          if (twilio.isAvailable()) return twilio;
          this.logger.warn(`SMS_PROVIDER=twilio but configuration incomplete (missing: ${twilio.configurationProblems().join(', ')})`);
        } else if (smsProvider) {
          this.logger.warn(`SMS_PROVIDER=${smsProvider} is not supported (supported: twilio); SMS deliveries will fail`);
        }
        return new NoOpNotificationProvider();
      }

      default:
        this.logger.error(`Unsupported notification channel: ${channel}`);
        return new NoOpNotificationProvider();
    }
  }

  getEmailProvider(): INotificationProvider {
    return this.getProvider(NotificationChannel.EMAIL);
  }

  getAvailableChannels(): NotificationChannel[] {
    const available: NotificationChannel[] = [NotificationChannel.IN_APP];
    if (this.emailProvider.isAvailable()) {
      available.push(NotificationChannel.EMAIL);
    }
    if (this.pushProvider.isAvailable()) {
      available.push(NotificationChannel.PUSH);
    }
    if ((process.env.SMS_PROVIDER || '').trim().toLowerCase() === 'twilio' && new TwilioSmsProvider().isAvailable()) {
      available.push(NotificationChannel.SMS);
    }
    return available;
  }

  validateProviderConfiguration(): { configured: boolean; channels: NotificationChannel[]; message: string } {
    const channels = this.getAvailableChannels();
    const emailAvailable = this.emailProvider.isAvailable();
    return {
      configured: channels.length > 0,
      channels,
      message: emailAvailable
        ? `Notification providers configured: ${channels.join(',')}`
        : `Only IN_APP channel available. Email not configured - set SMTP_HOST, SMTP_USER, SMTP_PASS. No fake success allowed.`,
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { BillingNotificationAuditService } from './billing-notification.audit';
import { NotificationJobRepository } from './notification-job.repository';
import { DeliveryStatus } from './billing-notification.types';

/**
 * Reconciles canonical billing Event ↔ Job ↔ Provider Result ↔ Final State.
 * Detects event without job / duplicate / stuck / provider accepted but pending / sent without ref /
 * impossible retry / missing tenant/recipient/template failure/webhook mismatch.
 * Deterministic severity/category/event/notification/tenant/expected/actual.
 * No silent repair.
 */
@Injectable()
export class NotificationReconciliationService {
  private readonly logger = new Logger(NotificationReconciliationService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly jobRepository: NotificationJobRepository,
    private readonly auditService: BillingNotificationAuditService,
  ) {}

  async reconcileTenant(tenantId: string): Promise<{ issues: any[]; summary: any }> {
    const issues: any[] = [];

    // 1. Detect stuck jobs (PROCESSING > 2 hours, RETRY_SCHEDULED overdue > 24h)
    const stuckJobs = await this.detectStuckJobs(tenantId);
    issues.push(...stuckJobs);

    // 2. Detect duplicate jobs (same idempotency key but different IDs)
    const duplicateJobs = await this.detectDuplicateJobs(tenantId);
    issues.push(...duplicateJobs);

    // 3. Detect jobs SENT without provider reference
    const sentWithoutRef = await this.detectSentWithoutReference(tenantId);
    issues.push(...sentWithoutRef);

    // 4. Detect jobs FAILED but retryable with attempts < maxAttempts and no nextAttemptAt
    const impossibleRetry = await this.detectImpossibleRetryState(tenantId);
    issues.push(...impossibleRetry);

    // 5. Detect jobs with missing tenant or recipient
    const missingData = await this.detectMissingData(tenantId);
    issues.push(...missingData);

    // 6. Detect provider accepted but still PENDING (inconsistent state)
    const providerAcceptedButPending = await this.detectProviderAcceptedButPending(tenantId);
    issues.push(...providerAcceptedButPending);

    // 7. Detect template render failures (jobs with no rendered subject/body but SENT)
    const templateFailures = await this.detectTemplateFailures(tenantId);
    issues.push(...templateFailures);

    // 8. Detect webhook mismatch (webhook jobs but no subscription)
    const webhookMismatch = await this.detectWebhookMismatch(tenantId);
    issues.push(...webhookMismatch);

    const summary = {
      tenantId,
      totalIssues: issues.length,
      bySeverity: this.groupBy(issues, 'severity'),
      byCategory: this.groupBy(issues, 'category'),
      checkedAt: new Date().toISOString(),
    };

    // Audit reconciliation detection
    for (const issue of issues) {
      await this.auditService.logReconciliationDetected(
        tenantId,
        issue.category,
        issue.referenceId,
        issue.description,
        issue.severity,
      );
    }

    this.logger.log(`Reconciliation tenant=${tenantId} issues=${issues.length} summary=${JSON.stringify(summary.byCategory)}`);

    return { issues, summary };
  }

  async reconcileAllTenants(limit: number = 100): Promise<{ tenantId: string; issues: any[] }[]> {
    const results: { tenantId: string; issues: any[] }[] = [];

    try {
      // Get distinct tenantIds from notification jobs
      const jobs = await (this.prisma as any).billingNotificationJob?.findMany({
        select: { tenantId: true },
        distinct: ['tenantId'],
        take: limit,
      });

      if (jobs) {
        for (const job of jobs) {
          const result = await this.reconcileTenant(job.tenantId);
          if (result.issues.length > 0) {
            results.push({ tenantId: job.tenantId, issues: result.issues });
          }
        }
      }
    } catch (e: any) {
      this.logger.warn(`Failed to reconcile all tenants: ${e.message}`);
    }

    return results;
  }

  private async detectStuckJobs(tenantId: string): Promise<any[]> {
    const issues: any[] = [];
    try {
      const jobs = await this.jobRepository.listByTenant(tenantId, { limit: 1000 });

      for (const job of jobs) {
        if (job.deliveryStatus === DeliveryStatus.PROCESSING) {
          const hoursStuck = (Date.now() - new Date(job.updatedAt).getTime()) / (1000 * 60 * 60);
          if (hoursStuck > 2) {
            issues.push({
              category: 'STUCK_JOB',
              severity: hoursStuck > 24 ? 'CRITICAL' : 'HIGH',
              referenceId: job.id,
              tenantId: job.tenantId,
              eventKey: job.eventKey,
              channel: job.channel,
              expected: 'Job should complete or move to RETRY_SCHEDULED within 2 hours',
              actual: `Job stuck in PROCESSING for ${hoursStuck.toFixed(1)} hours`,
              description: `Notification job ${job.id} stuck in PROCESSING for ${hoursStuck.toFixed(1)} hours`,
              detectedAt: new Date().toISOString(),
            });
          }
        }

        if (job.deliveryStatus === DeliveryStatus.RETRY_SCHEDULED && job.nextAttemptAt) {
          const overdue = (Date.now() - new Date(job.nextAttemptAt).getTime()) / (1000 * 60 * 60);
          if (overdue > 24) {
            issues.push({
              category: 'STUCK_RETRY',
              severity: 'HIGH',
              referenceId: job.id,
              tenantId: job.tenantId,
              eventKey: job.eventKey,
              channel: job.channel,
              expected: 'Retry should be attempted within 24h of scheduled time',
              actual: `Retry overdue by ${overdue.toFixed(1)} hours`,
              description: `Notification job ${job.id} retry overdue by ${overdue.toFixed(1)} hours`,
              detectedAt: new Date().toISOString(),
            });
          }
        }
      }
    } catch (e: any) {
      this.logger.warn(`detectStuckJobs failed for tenant ${tenantId}: ${e.message}`);
    }
    return issues;
  }

  private async detectDuplicateJobs(tenantId: string): Promise<any[]> {
    const issues: any[] = [];
    try {
      const jobs = await this.jobRepository.listByTenant(tenantId, { limit: 1000 });
      const byIdempotency = new Map<string, any[]>();

      for (const job of jobs) {
        if (!byIdempotency.has(job.idempotencyKey)) {
          byIdempotency.set(job.idempotencyKey, []);
        }
        byIdempotency.get(job.idempotencyKey)!.push(job);
      }

      for (const [key, duplicates] of byIdempotency.entries()) {
        if (duplicates.length > 1) {
          issues.push({
            category: 'DUPLICATE_JOB',
            severity: 'MEDIUM',
            referenceId: duplicates[0].id,
            tenantId,
            eventKey: duplicates[0].eventKey,
            channel: duplicates[0].channel,
            expected: 'One job per idempotency key',
            actual: `${duplicates.length} jobs with same idempotency key ${key}`,
            description: `Duplicate notification jobs for idempotency key ${key}: ${duplicates.map((d) => d.id).join(', ')}`,
            duplicateIds: duplicates.map((d) => d.id),
            detectedAt: new Date().toISOString(),
          });
        }
      }
    } catch (e: any) {
      this.logger.warn(`detectDuplicateJobs failed for tenant ${tenantId}: ${e.message}`);
    }
    return issues;
  }

  private async detectSentWithoutReference(tenantId: string): Promise<any[]> {
    const issues: any[] = [];
    try {
      const jobs = await this.jobRepository.listByTenant(tenantId, { limit: 1000 });
      for (const job of jobs) {
        if ((job.deliveryStatus === DeliveryStatus.SENT || job.deliveryStatus === DeliveryStatus.DELIVERED) && !job.providerReference) {
          issues.push({
            category: 'SENT_WITHOUT_REFERENCE',
            severity: 'HIGH',
            referenceId: job.id,
            tenantId,
            eventKey: job.eventKey,
            channel: job.channel,
            expected: 'SENT jobs should have provider reference',
            actual: 'Job marked SENT without provider reference',
            description: `Notification job ${job.id} marked SENT without provider reference`,
            detectedAt: new Date().toISOString(),
          });
        }
      }
    } catch (e: any) {
      this.logger.warn(`detectSentWithoutReference failed: ${e.message}`);
    }
    return issues;
  }

  private async detectImpossibleRetryState(tenantId: string): Promise<any[]> {
    const issues: any[] = [];
    try {
      const jobs = await this.jobRepository.listByTenant(tenantId, { limit: 1000 });
      for (const job of jobs) {
        if (job.deliveryStatus === DeliveryStatus.FAILED && job.attemptCount < job.maxAttempts && !job.nextAttemptAt) {
          issues.push({
            category: 'IMPOSSIBLE_RETRY',
            severity: 'MEDIUM',
            referenceId: job.id,
            tenantId,
            eventKey: job.eventKey,
            channel: job.channel,
            expected: 'FAILED jobs with attempts < max should have nextAttemptAt or be RETRY_SCHEDULED',
            actual: `Job FAILED with ${job.attemptCount}/${job.maxAttempts} attempts but no nextAttemptAt`,
            description: `Notification job ${job.id} in impossible retry state`,
            detectedAt: new Date().toISOString(),
          });
        }
      }
    } catch (e: any) {
      this.logger.warn(`detectImpossibleRetryState failed: ${e.message}`);
    }
    return issues;
  }

  private async detectMissingData(tenantId: string): Promise<any[]> {
    const issues: any[] = [];
    try {
      const jobs = await this.jobRepository.listByTenant(tenantId, { limit: 1000 });
      for (const job of jobs) {
        if (!job.tenantId) {
          issues.push({
            category: 'MISSING_TENANT',
            severity: 'CRITICAL',
            referenceId: job.id,
            tenantId: tenantId || 'unknown',
            eventKey: job.eventKey,
            channel: job.channel,
            expected: 'Job should have tenantId',
            actual: 'Missing tenantId',
            description: `Notification job ${job.id} missing tenantId`,
            detectedAt: new Date().toISOString(),
          });
        }
        if (!job.recipient) {
          issues.push({
            category: 'MISSING_RECIPIENT',
            severity: 'HIGH',
            referenceId: job.id,
            tenantId: job.tenantId,
            eventKey: job.eventKey,
            channel: job.channel,
            expected: 'Job should have recipient',
            actual: 'Missing recipient',
            description: `Notification job ${job.id} missing recipient`,
            detectedAt: new Date().toISOString(),
          });
        }
      }
    } catch (e: any) {
      this.logger.warn(`detectMissingData failed: ${e.message}`);
    }
    return issues;
  }

  private async detectProviderAcceptedButPending(tenantId: string): Promise<any[]> {
    const issues: any[] = [];
    try {
      const jobs = await this.jobRepository.listByTenant(tenantId, { limit: 1000 });
      for (const job of jobs) {
        if ((job.deliveryStatus === DeliveryStatus.PENDING || job.deliveryStatus === DeliveryStatus.CREATED) && job.providerReference) {
          issues.push({
            category: 'PROVIDER_ACCEPTED_BUT_PENDING',
            severity: 'MEDIUM',
            referenceId: job.id,
            tenantId: job.tenantId,
            eventKey: job.eventKey,
            channel: job.channel,
            expected: 'Jobs with provider reference should be SENT',
            actual: `Job in ${job.deliveryStatus} but has provider reference ${job.providerReference}`,
            description: `Notification job ${job.id} has provider reference but status is ${job.deliveryStatus}`,
            detectedAt: new Date().toISOString(),
          });
        }
      }
    } catch (e: any) {
      this.logger.warn(`detectProviderAcceptedButPending failed: ${e.message}`);
    }
    return issues;
  }

  private async detectTemplateFailures(tenantId: string): Promise<any[]> {
    const issues: any[] = [];
    try {
      const jobs = await this.jobRepository.listByTenant(tenantId, { limit: 1000 });
      for (const job of jobs) {
        if ((job.deliveryStatus === DeliveryStatus.FAILED || job.deliveryStatus === DeliveryStatus.PERMANENT_FAILURE) && job.failureReason?.includes('Template')) {
          issues.push({
            category: 'TEMPLATE_RENDER_FAILED',
            severity: 'HIGH',
            referenceId: job.id,
            tenantId: job.tenantId,
            eventKey: job.eventKey,
            channel: job.channel,
            expected: 'Template should render successfully',
            actual: job.failureReason,
            description: `Notification job ${job.id} template render failed: ${job.failureReason}`,
            detectedAt: new Date().toISOString(),
          });
        }
      }
    } catch (e: any) {
      this.logger.warn(`detectTemplateFailures failed: ${e.message}`);
    }
    return issues;
  }

  private async detectWebhookMismatch(tenantId: string): Promise<any[]> {
    const issues: any[] = [];
    try {
      const webhookJobs = await this.jobRepository.listByTenant(tenantId, { limit: 1000 });
      const webhookJobsFiltered = webhookJobs.filter((j) => j.channel === 'WEBHOOK');

      if (webhookJobsFiltered.length > 0) {
        // Check if tenant has any webhook subscriptions
        try {
          const subscriptions = await (this.prisma as any).webhookSubscription?.findMany({
            where: { tenantId },
          });

          if (!subscriptions || subscriptions.length === 0) {
            issues.push({
              category: 'WEBHOOK_MISMATCH',
              severity: 'LOW',
              referenceId: webhookJobsFiltered[0].id,
              tenantId,
              eventKey: webhookJobsFiltered[0].eventKey,
              channel: 'WEBHOOK',
              expected: 'Webhook jobs should have corresponding subscription',
              actual: `${webhookJobsFiltered.length} webhook jobs but no subscriptions`,
              description: `Tenant ${tenantId} has ${webhookJobsFiltered.length} webhook jobs but no webhook subscriptions configured`,
              detectedAt: new Date().toISOString(),
            });
          }
        } catch {}
      }
    } catch (e: any) {
      this.logger.warn(`detectWebhookMismatch failed: ${e.message}`);
    }
    return issues;
  }

  private groupBy(arr: any[], key: string): Record<string, number> {
    const grouped: Record<string, number> = {};
    for (const item of arr) {
      const value = item[key] || 'unknown';
      grouped[value] = (grouped[value] || 0) + 1;
    }
    return grouped;
  }
}

import { Injectable, Logger, OnModuleInit, OnModuleDestroy } from '@nestjs/common';
import { NotificationWorkerService } from './notification-worker.service';
import { NotificationReconciliationService } from './notification-reconciliation.service';

/**
 * Scheduler for billing notification worker and reconciliation.
 * Processes pending jobs every 30s, detects stuck jobs every 5m, reconciles hourly.
 * Bounded batch, no infinite retries, tenant-safe.
 */
@Injectable()
export class NotificationSchedulerService implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(NotificationSchedulerService.name);
  private intervals: NodeJS.Timeout[] = [];
  private isEnabled: boolean;

  constructor(
    private readonly workerService: NotificationWorkerService,
    private readonly reconciliationService: NotificationReconciliationService,
  ) {
    this.isEnabled = process.env.BILLING_NOTIFICATIONS_SCHEDULER_ENABLED !== 'false';
  }

  onModuleInit(): void {
    if (!this.isEnabled) {
      this.logger.log('Billing notification scheduler disabled via env BILLING_NOTIFICATIONS_SCHEDULER_ENABLED=false');
      return;
    }

    this.logger.log('Starting billing notification scheduler: worker 30s, stuck detection 5m, reconciliation 1h');

    // Process pending jobs every 30 seconds
    const workerInterval = setInterval(async () => {
      try {
        const result = await this.workerService.processPendingJobs(50);
        if (result.processed > 0) {
          this.logger.log(`Scheduler worker batch processed=${result.processed} succeeded=${result.succeeded} failed=${result.failed} retried=${result.retried}`);
        }
      } catch (e: any) {
        this.logger.warn(`Scheduler worker failed: ${e.message}`);
      }
    }, 30 * 1000);
    this.intervals.push(workerInterval);

    // Detect stuck jobs every 5 minutes
    const stuckInterval = setInterval(async () => {
      try {
        const stuck = await this.workerService.detectStuckJobs(2);
        if (stuck.length > 0) {
          this.logger.warn(`Scheduler detected ${stuck.length} stuck notification jobs`);
        }
      } catch (e: any) {
        this.logger.warn(`Scheduler stuck detection failed: ${e.message}`);
      }
    }, 5 * 60 * 1000);
    this.intervals.push(stuckInterval);

    // Reconciliation every hour (sample of tenants)
    const reconInterval = setInterval(async () => {
      try {
        const results = await this.reconciliationService.reconcileAllTenants(20);
        if (results.length > 0) {
          this.logger.warn(`Scheduler reconciliation found ${results.length} tenants with issues`);
        }
      } catch (e: any) {
        this.logger.warn(`Scheduler reconciliation failed: ${e.message}`);
      }
    }, 60 * 60 * 1000);
    this.intervals.push(reconInterval);
  }

  onModuleDestroy(): void {
    this.logger.log('Stopping billing notification scheduler');
    for (const interval of this.intervals) {
      clearInterval(interval);
    }
    this.intervals = [];
  }

  async triggerWorkerManually(batchSize: number = 50): Promise<any> {
    return this.workerService.processPendingJobs(batchSize);
  }

  async triggerStuckDetectionManually(thresholdHours: number = 2): Promise<any> {
    return this.workerService.detectStuckJobs(thresholdHours);
  }

  async triggerReconciliationManually(tenantId?: string): Promise<any> {
    if (tenantId) {
      return this.reconciliationService.reconcileTenant(tenantId);
    }
    return this.reconciliationService.reconcileAllTenants(20);
  }
}

