      variables: ['customerName', 'tenantName', 'payoutId', 'amount', 'currency', 'payoutStatus', 'appName', 'supportEmail'],
    },
  };

  resolveTemplate(eventKey: BillingNotificationEventKey, locale: string = 'en', channel: string = 'EMAIL'): TemplateDefinition | null {
    // Try exact match with locale and channel
    const exactKey = `${eventKey}_${locale}_${channel}`;
    // For simplicity, we use eventKey as primary key, ignoring locale/channel variations for now
    // In real implementation, would have i18n and channel-specific templates
    const template = this.templates[eventKey];
    if (!template) {
      this.logger.warn(`Template not found for eventKey=${eventKey} locale=${locale} channel=${channel}`);
      return null;
    }

    // Return template with locale override if needed
    return {
      ...template,
      locale: locale || template.locale,
      channel: channel || template.channel,
    };
  }

  renderTemplate(template: TemplateDefinition, variables: Record<string, unknown>): { subject: string; title: string; body: string; htmlBody?: string } {
    try {
      const subject = this.interpolate(template.subject, variables);
      const title = this.interpolate(template.title, variables);
      const body = this.interpolate(template.body, variables);
      const htmlBody = template.htmlBody ? this.interpolate(template.htmlBody, variables) : undefined;

      return { subject, title, body, htmlBody };
    } catch (error: any) {
      this.logger.error(`Template render failed for ${template.key}: ${error.message}`);
      throw new Error(`Template render failed for ${template.key}: ${error.message}`);
    }
  }

  private interpolate(template: string, variables: Record<string, unknown>): string {
    let result = template;
    for (const [key, value] of Object.entries(variables)) {
      const placeholder = `{{${key}}}`;
      const safeValue = this.sanitizeVariable(value);
      result = result.split(placeholder).join(safeValue);
    }

    // Check for unresolved placeholders (missing variables)
    const unresolved = result.match(/\{\{[^}]+\}\}/g);
    if (unresolved) {
      // Replace unresolved with empty string or keep for visibility, but log warning
      this.logger.warn(`Unresolved template variables: ${unresolved.join(', ')}`);
      for (const placeholder of unresolved) {
        result = result.split(placeholder).join('');
      }
    }

    return result;
  }

  private sanitizeVariable(value: unknown): string {
    if (value === null || value === undefined) return '';
    if (typeof value === 'string') {
      // Sanitize: no secrets, no HTML injection for text version (basic)
      // For HTML body, would need proper escaping, but for text we strip
      const forbidden = ['secret', 'privateKey', 'apiKey', 'password', 'token', 'exchange', 'credential'];
      const lower = value.toLowerCase();
      if (forbidden.some((f) => lower.includes(f) && value.length > 100)) {
        return '[REDACTED]';
      }
      return value;
    }
    if (typeof value === 'number') return value.toString();
    if (typeof value === 'boolean') return value ? 'Yes' : 'No';
    return String(value);
  }

  getAvailableTemplates(): string[] {
    return Object.keys(this.templates);
  }

  getTemplateKeysForEvent(eventKey: BillingNotificationEventKey): string[] {
    const template = this.templates[eventKey];
    return template ? [template.key] : [];
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { NotificationJobRepository } from './notification-job.repository';
import { NotificationDeliveryService } from './notification-delivery.service';
import { DeliveryStatus } from './billing-notification.types';
import { BillingNotificationAuditService } from './billing-notification.audit';

/**
 * Bounded batch processing, exponential backoff, maxAttempts from config,
 * temporary vs permanent failure handling, timeout, idempotency, stuck-job detection.
 * Never marks SENT before provider acceptance.
 */
@Injectable()
export class NotificationWorkerService {
  private readonly logger = new Logger(NotificationWorkerService.name);
  private isProcessing = false;

  constructor(
    private readonly jobRepository: NotificationJobRepository,
    private readonly deliveryService: NotificationDeliveryService,
    private readonly auditService: BillingNotificationAuditService,
  ) {}

  async processPendingJobs(batchSize: number = 20): Promise<{ processed: number; succeeded: number; failed: number; retried: number }> {
    if (this.isProcessing) {
      this.logger.warn('Worker already processing, skipping');
      return { processed: 0, succeeded: 0, failed: 0, retried: 0 };
    }

    this.isProcessing = true;

    let processed = 0;
    let succeeded = 0;
    let failed = 0;
    let retried = 0;

    try {
      const pendingJobs = await this.jobRepository.findPendingJobs(batchSize);
      this.logger.log(`Processing ${pendingJobs.length} pending notification jobs`);

      for (const job of pendingJobs) {
        try {
          processed++;
          const result = await this.processJobWithTimeout(job.id, 30000);

          if (result.deliveryStatus === DeliveryStatus.SENT || result.deliveryStatus === DeliveryStatus.DELIVERED) {
            succeeded++;
          } else if (result.deliveryStatus === DeliveryStatus.RETRY_SCHEDULED) {
            retried++;
          } else if (result.deliveryStatus === DeliveryStatus.FAILED || result.deliveryStatus === DeliveryStatus.PERMANENT_FAILURE) {
            failed++;
          }
        } catch (e: any) {
          failed++;
          this.logger.warn(`Failed to process pending job ${job.id}: ${e.message}`);
        }
      }

      // Process retryable jobs
      const retryableJobs = await this.jobRepository.findRetryableJobs(batchSize);
      this.logger.log(`Processing ${retryableJobs.length} retryable notification jobs`);

      for (const job of retryableJobs) {
        try {
          // Stuck job detection: if attemptCount exceeds maxAttempts, mark permanent failure
          if (job.attemptCount >= job.maxAttempts) {
            await this.jobRepository.updateStatus(job.id, {
              deliveryStatus: DeliveryStatus.PERMANENT_FAILURE,
              failureReason: `Max attempts ${job.maxAttempts} reached - stuck job detected`,
            });
            await this.auditService.logPermanentFailure(job.tenantId, job.id, job.attemptCount, 'Stuck job - max attempts reached');
            failed++;
            processed++;
            continue;
          }

          // Check if job is stuck (nextAttemptAt in past by > 1 hour and still RETRY_SCHEDULED)
          if (job.nextAttemptAt) {
            const nextAttempt = new Date(job.nextAttemptAt);
            const hoursSinceScheduled = (Date.now() - nextAttempt.getTime()) / (1000 * 60 * 60);
            if (hoursSinceScheduled > 24) {
              this.logger.warn(`Stuck job detected id=${job.id} scheduled=${job.nextAttemptAt} hoursAgo=${hoursSinceScheduled}`);
              await this.auditService.logReconciliationDetected(job.tenantId, 'STUCK_JOB', job.id, `Job stuck in RETRY_SCHEDULED for ${hoursSinceScheduled.toFixed(1)} hours`, 'HIGH');
            }
          }

          processed++;
          const result = await this.processJobWithTimeout(job.id, 30000);

          if (result.deliveryStatus === DeliveryStatus.SENT || result.deliveryStatus === DeliveryStatus.DELIVERED) {
            succeeded++;
          } else if (result.deliveryStatus === DeliveryStatus.RETRY_SCHEDULED) {
            retried++;
          } else {
            failed++;
          }
        } catch (e: any) {
          failed++;
          this.logger.warn(`Failed to process retryable job ${job.id}: ${e.message}`);
        }
      }
    } finally {
      this.isProcessing = false;
    }

    this.logger.log(`Worker batch complete processed=${processed} succeeded=${succeeded} failed=${failed} retried=${retried}`);

    return { processed, succeeded, failed, retried };
  }

  private async processJobWithTimeout(jobId: string, timeoutMs: number): Promise<any> {
    return Promise.race([
      this.deliveryService.deliverJob(jobId),
      new Promise((_, reject) => setTimeout(() => reject(new Error(`Job ${jobId} timeout after ${timeoutMs}ms`)), timeoutMs)),
    ]);
  }

  async detectStuckJobs(thresholdHours: number = 2): Promise<any[]> {
    // Find jobs stuck in PROCESSING for more than threshold
    try {
      const pendingJobs = await this.jobRepository.findPendingJobs(1000);
      const stuck: any[] = [];

      for (const job of pendingJobs) {
        if (job.deliveryStatus === DeliveryStatus.PROCESSING) {
          const updatedAt = new Date(job.updatedAt);
          const hoursSinceUpdate = (Date.now() - updatedAt.getTime()) / (1000 * 60 * 60);
          if (hoursSinceUpdate > thresholdHours) {
            stuck.push({
              jobId: job.id,
              tenantId: job.tenantId,
              eventKey: job.eventKey,
              channel: job.channel,
              status: job.deliveryStatus,
              hoursStuck: hoursSinceUpdate,
              attemptCount: job.attemptCount,
            });

            // Reset stuck job to RETRY_SCHEDULED
            await this.jobRepository.updateStatus(job.id, {
              deliveryStatus: DeliveryStatus.RETRY_SCHEDULED,
              nextAttemptAt: new Date(Date.now() + 60 * 1000).toISOString(),
              failureReason: `Stuck in PROCESSING for ${hoursSinceUpdate.toFixed(1)} hours - reset to retry`,
            });

            await this.auditService.logReconciliationDetected(job.tenantId, 'STUCK_JOB', job.id, `Job stuck in PROCESSING for ${hoursSinceUpdate.toFixed(1)} hours`, 'HIGH');
          }
        }
      }

      return stuck;
    } catch (e: any) {
      this.logger.warn(`Failed to detect stuck jobs: ${e.message}`);
      return [];
    }
  }

  async processJobById(jobId: string): Promise<any> {
    return this.deliveryService.deliverJob(jobId);
  }
}

// # Responsibility: lazily load the optional FCM SDK and send tenant-scoped push notifications without exposing credentials.
import { Injectable, Logger } from '@nestjs/common';
import { createRequire } from 'node:module';
import { INotificationProvider, SendNotificationInput, SendNotificationResult, ProviderDeliveryResultType } from './notification-provider.interface';
import { NotificationChannel } from './billing-notification.types';

interface FirebasePushMessage {
  token: string;
  notification: { title: string; body: string };
  data: Record<string, string>;
}

interface FirebaseMessagingClient {
  send(message: FirebasePushMessage): Promise<string>;
}

interface FirebaseAdminRuntime {
  default?: FirebaseAdminRuntime;
  apps?: readonly unknown[];
  credential?: {
    cert?: (serviceAccount: { projectId: string; clientEmail: string; privateKey: string }) => unknown;
  };
  messaging?: () => FirebaseMessagingClient;
  initializeApp?: (options?: { credential?: unknown; projectId?: string }) => unknown;
}

const loadOptionalDependency = createRequire(__filename);

/**
 * Push notification integration abstraction/adapter using existing mobile
 * notification infrastructure where configured.
 * Handles invalid device/token, retry classification, no device secrets storage.
 */
@Injectable()
export class PushNotificationService implements INotificationProvider {
  readonly providerName = 'push_notification';
  readonly supportedChannels = [NotificationChannel.PUSH] as NotificationChannel[];
  private readonly logger = new Logger(PushNotificationService.name);

  isAvailable(): boolean {
    return !!(
      process.env.FCM_SERVER_KEY ||
      process.env.FIREBASE_CONFIG ||
      process.env.PUSH_ENABLED === 'true' ||
      PushNotificationService.serviceAccountFromEnv()
    );
  }

  /**
   * Explicit service account from FIREBASE_PROJECT_ID / FIREBASE_CLIENT_EMAIL /
   * FIREBASE_PRIVATE_KEY_BASE64 (the variables .env.example documents). Null
   * unless all three are set; otherwise firebase-admin falls back to
   * application default credentials (GOOGLE_APPLICATION_CREDENTIALS, workload
   * identity) with FIREBASE_CONFIG for the project settings.
   */
  static serviceAccountFromEnv(): { projectId: string; clientEmail: string; privateKey: string } | null {
    const projectId = (process.env.FIREBASE_PROJECT_ID || '').trim();
    const clientEmail = (process.env.FIREBASE_CLIENT_EMAIL || '').trim();
    const keyB64 = (process.env.FIREBASE_PRIVATE_KEY_BASE64 || '').trim();
    if (!projectId || !clientEmail || !keyB64) return null;
    const privateKey = Buffer.from(keyB64, 'base64').toString('utf8');
    if (!privateKey.includes('PRIVATE KEY')) return null;
    return { projectId, clientEmail, privateKey };
  }

  async send(input: SendNotificationInput): Promise<SendNotificationResult> {
    if (!this.isAvailable()) {
      return {
        accepted: false,
        providerReference: null,
        resultType: ProviderDeliveryResultType.PERMANENT_FAILURE,
        retryable: false,
        errorCode: 'PUSH_NOT_CONFIGURED',
        failureReason: 'Push provider not configured. Set FCM_SERVER_KEY or FIREBASE_CONFIG.',
      };
    }

    if (!input.recipientUserId) {
      return {
        accepted: false,
        providerReference: null,
        resultType: ProviderDeliveryResultType.PERMANENT_FAILURE,
        retryable: false,
        errorCode: 'INVALID_RECIPIENT',
        failureReason: 'Recipient user ID required for push notification',
      };
    }

    // Sanitize payload - no secrets
    const sanitizedSubject = this.sanitizeContent(input.subject);
    const sanitizedBody = this.sanitizeContent(input.body);

    try {
      // Delivery goes through firebase-admin (FCM, which also fronts APNs).
      // Anything short of an actual FCM send is reported as a failure: a
      // push that was only logged must never be recorded as delivered.
      const token = input.safePayload && typeof (input.safePayload as any).deviceToken === 'string'
        ? ((input.safePayload as any).deviceToken as string)
        : null;
      if (!token) {
        return {
          accepted: false,
          providerReference: null,
          resultType: ProviderDeliveryResultType.PERMANENT_FAILURE,
          retryable: false,
          errorCode: 'NO_DEVICE_TOKEN',
          failureReason: 'No device token supplied for push delivery',
        };
      }
      if (token.includes('invalid') || token.length < 10) {
        return {
          accepted: false,
          providerReference: null,
          resultType: ProviderDeliveryResultType.PERMANENT_FAILURE,
          retryable: false,
          errorCode: 'INVALID_DEVICE_TOKEN',
          failureReason: 'Invalid device token',
        };
      }

      const messaging = await this.resolveMessaging();
      if (!messaging) {
        return {
          accepted: false,
          providerReference: null,
          resultType: ProviderDeliveryResultType.PERMANENT_FAILURE,
          retryable: false,
          errorCode: 'PUSH_PROVIDER_UNAVAILABLE',
          failureReason:
            'Push is enabled but firebase-admin is not installed or not initialised ' +
            '(install firebase-admin and set GOOGLE_APPLICATION_CREDENTIALS or FIREBASE_CONFIG).',
        };
      }

      try {
        const messageId: string = await messaging.send({
          token,
          notification: { title: sanitizedSubject, body: sanitizedBody.substring(0, 1000) },
          data: { tenantId: String(input.tenantId ?? '') },
        });
        this.logger.log(`Push sent via FCM tenant=${input.tenantId} user=${input.recipientUserId} id=${messageId}`);
        return {
          accepted: true,
          providerReference: messageId,
          resultType: ProviderDeliveryResultType.ACCEPTED,
          retryable: false,
          deliveredAt: new Date().toISOString(),
        };
      } catch (e: any) {
        const code = String(e?.code ?? e?.errorInfo?.code ?? '').toLowerCase();
        const message = String(e?.message ?? '');
        const isInvalidToken =
          code.includes('registration-token-not-registered') ||
          code.includes('invalid-registration-token') ||
          code.includes('invalid-argument') ||
          message.toLowerCase().includes('not registered');
        if (isInvalidToken) {
          return {
            accepted: false,
            providerReference: null,
            resultType: ProviderDeliveryResultType.PERMANENT_FAILURE,
            retryable: false,
            errorCode: 'INVALID_DEVICE_TOKEN',
            failureReason: message.slice(0, 500),
          };
        }
        return {
          accepted: false,
          providerReference: null,
          resultType: ProviderDeliveryResultType.TEMPORARY_FAILURE,
          retryable: true,
          errorCode: 'PUSH_TEMPORARY_FAILURE',
          failureReason: message.slice(0, 500),
        };
      }
    } catch (error: any) {
      this.logger.error(`Push notification failed: ${error.message}`, error.stack);
      return {
        accepted: false,
        providerReference: null,
        resultType: ProviderDeliveryResultType.TEMPORARY_FAILURE,
        retryable: true,
        errorCode: 'PUSH_PROVIDER_ERROR',
        failureReason: error.message,
      };
    }
  }

  /**
   * firebase-admin is declared in apps/api optionalDependencies (so a
   * platform where it fails to install still builds). Returns its messaging
   * client when the package is present; initialises the default app from the
   * environment (GOOGLE_APPLICATION_CREDENTIALS / FIREBASE_CONFIG) on first
   * use. Returns null when unavailable - the caller reports a failure.
   */
  private async resolveMessaging(): Promise<FirebaseMessagingClient | null> {
    try {
      const mod = loadOptionalDependency('firebase-admin') as FirebaseAdminRuntime;
      const admin = mod.default ?? mod;
      if (typeof admin.messaging !== 'function') return null;
      if (Array.isArray(admin.apps) && admin.apps.length === 0 && typeof admin.initializeApp === 'function') {
        const serviceAccount = PushNotificationService.serviceAccountFromEnv();
        if (serviceAccount && admin.credential && typeof admin.credential.cert === 'function') {
          admin.initializeApp({ credential: admin.credential.cert(serviceAccount), projectId: serviceAccount.projectId });
        } else {
          admin.initializeApp();
        }
      }
      return admin.messaging();
    } catch (e) {
      this.logger.warn(`firebase-admin unavailable: ${(e as Error).message}`);
      return null;
    }
  }

  private sanitizeContent(content: string): string {
    if (!content) return '';
    const forbidden = ['secret', 'privateKey', 'apiKey', 'password', 'token', 'credential'];
    let sanitized = content;
    for (const pattern of forbidden) {
      const regex = new RegExp(pattern, 'gi');
      if (regex.test(sanitized)) {
        sanitized = sanitized.replace(regex, '[REDACTED]');
      }
    }
    return sanitized;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { BillingEventService } from './billing-event.service';

/**
 * Subscription event service: trial starting/ending, cancellation scheduled, resumed, changed.
 * Authoritative for subscription lifecycle events -> notifications.
 * Never mutates subscription state, only notifies.
 */

@Injectable()
export class SubscriptionEventService {
  private readonly logger = new Logger(SubscriptionEventService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly billingEventService: BillingEventService,
  ) {}

  async checkTrialEnding(daysBefore: number = 3): Promise<{ checked: number; notified: number }> {
    const now = new Date();
    const threshold = new Date(now.getTime() + daysBefore * 24 * 60 * 60 * 1000);

    let trials: any[] = [];
    try {
      trials = await this.prisma.tenantSubscription.findMany({
        where: {
          status: 'TRIALING',
          trialEndsAt: { gte: now, lte: threshold },
        },
        include: { plan: true },
      });
    } catch (e: any) {
      this.logger.warn(`Failed to fetch trials ending: ${e.message}`);
      return { checked: 0, notified: 0 };
    }

    let notified = 0;
    for (const sub of trials) {
      try {
        await this.billingEventService.onTrialEnding({
          tenantId: sub.tenantId,
          subscriptionId: sub.id,
          planName: sub.plan?.name || sub.plan?.code || 'Plan',
          trialEndsAt: sub.trialEndsAt!.toISOString(),
          supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
          appName: process.env.APP_NAME || 'WLCT',
        });
        notified++;
      } catch (e: any) {
        this.logger.warn(`Failed to notify trial ending for ${sub.id}: ${e.message}`);
      }
    }

    return { checked: trials.length, notified };
  }

  async checkTrialStarting(daysAfter: number = 0): Promise<{ checked: number; notified: number }> {
    const now = new Date();
    const startWindow = new Date(now.getTime() - (daysAfter + 1) * 24 * 60 * 60 * 1000);
    const endWindow = new Date(now.getTime() - daysAfter * 24 * 60 * 60 * 1000);

    let trials: any[] = [];
    try {
      trials = await this.prisma.tenantSubscription.findMany({
        where: {
          status: 'TRIALING',
          createdAt: { gte: startWindow, lte: endWindow },
        },
        include: { plan: true },
      });
    } catch {
      return { checked: 0, notified: 0 };
    }

    let notified = 0;
    for (const sub of trials) {
      try {
        await this.billingEventService.onTrialStarting({
          tenantId: sub.tenantId,
          subscriptionId: sub.id,
          planName: sub.plan?.name || sub.plan?.code || 'Plan',
          trialEndsAt: sub.trialEndsAt?.toISOString() || new Date(now.getTime() + 14 * 86400000).toISOString(),
          supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
          appName: process.env.APP_NAME || 'WLCT',
        });
        notified++;
      } catch {}
    }

    return { checked: trials.length, notified };
  }

  async notifySubscriptionChanged(params: {
    tenantId: string;
    subscriptionId: string;
    planName: string;
    planCode?: string;
    renewalDate: string;
  }): Promise<void> {
    try {
      await this.billingEventService.onSubscriptionChanged({
        tenantId: params.tenantId,
        subscriptionId: params.subscriptionId,
        planName: params.planName,
        planCode: params.planCode || params.planName,
        renewalDate: params.renewalDate,
        supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
        appName: process.env.APP_NAME || 'WLCT',
      });
    } catch (e: any) {
      this.logger.warn(`Failed to notify subscription changed: ${e.message}`);
    }
  }

  async notifyCancellationScheduled(params: {
    tenantId: string;
    subscriptionId: string;
    planName: string;
    renewalDate: string;
  }): Promise<void> {
    try {
      await this.billingEventService.onSubscriptionCancellationScheduled({
        tenantId: params.tenantId,
        subscriptionId: params.subscriptionId,
        planName: params.planName,
        renewalDate: params.renewalDate,
        supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
        appName: process.env.APP_NAME || 'WLCT',
      });
    } catch (e: any) {
      this.logger.warn(`Failed to notify cancellation scheduled: ${e.message}`);
    }
  }

  async notifyResumed(params: {
    tenantId: string;
    subscriptionId: string;
    planName: string;
    renewalDate: string;
  }): Promise<void> {
    try {
      await this.billingEventService.onSubscriptionResumed({
        tenantId: params.tenantId,
        subscriptionId: params.subscriptionId,
        planName: params.planName,
        renewalDate: params.renewalDate,
        supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
        appName: process.env.APP_NAME || 'WLCT',
      });
    } catch (e: any) {
      this.logger.warn(`Failed to notify resumed: ${e.message}`);
    }
  }
}

import { TwilioSmsProvider, SmsFetchLike, maskPhone } from './twilio-sms.provider';
import { NotificationChannel } from './billing-notification.types';
import {
  ProviderDeliveryResultType,
  SendNotificationInput,
} from './notification-provider.interface';

const SID = 'AC' + '0123456789abcdef'.repeat(2);
const MG = 'MG' + 'fedcba9876543210'.repeat(2);
const MSG_SID = 'SM' + 'a'.repeat(32);

const input = (overrides: Partial<SendNotificationInput> = {}): SendNotificationInput => ({
  tenantId: 'tenant_1',
  recipientPhone: '+8801711000000',
  subject: 'Payment failed',
  body: 'Your payment failed. Please update your card.',
  channel: NotificationChannel.SMS,
  templateKey: 'payment_failed',
  safePayload: {},
  idempotencyKey: 'notif_123',
  ...overrides,
});

function fakeFetch(response: { ok: boolean; status: number; body: any } | Error) {
  const calls: Array<{ url: string; init: any }> = [];
  const impl: SmsFetchLike = async (url, init) => {
    calls.push({ url, init });
    if (response instanceof Error) throw response;
    return { ok: response.ok, status: response.status, json: async () => response.body };
  };
  return { impl, calls };
}

const configured = (fetchImpl: SmsFetchLike, extra: Record<string, string> = {}) =>
  new TwilioSmsProvider({
    accountSid: SID,
    authToken: 'secret-token',
    fromNumber: '+15005550006',
    fetchImpl,
    ...extra,
  });

describe('TwilioSmsProvider', () => {
  it('is unavailable (and throws, calling nothing) when configuration is incomplete', async () => {
    const { impl, calls } = fakeFetch({ ok: true, status: 201, body: {} });
    const cases = [
      new TwilioSmsProvider({ fetchImpl: impl, accountSid: '', authToken: '', fromNumber: '' }),
      new TwilioSmsProvider({
        fetchImpl: impl,
        accountSid: SID,
        authToken: '',
        fromNumber: '+15005550006',
      }),
      new TwilioSmsProvider({
        fetchImpl: impl,
        accountSid: SID,
        authToken: 't',
        fromNumber: '5550006',
      }),
      new TwilioSmsProvider({
        fetchImpl: impl,
        accountSid: 'AC123',
        authToken: 't',
        fromNumber: '+15005550006',
      }),
    ];
    for (const p of cases) {
      expect(p.isAvailable()).toBe(false);
      await expect(p.send(input())).rejects.toThrow(/not configured/);
    }
    expect(calls).toHaveLength(0);
    const problems = cases[0].configurationProblems().join(' ');
    expect(problems).toContain('TWILIO_ACCOUNT_SID');
    expect(problems).not.toContain('secret-token');
  });

  it('queues an SMS: Basic auth, From number, idempotency token, accepted only with a message sid', async () => {
    const { impl, calls } = fakeFetch({
      ok: true,
      status: 201,
      body: { sid: MSG_SID, status: 'queued', num_segments: '1' },
    });
    const r = await configured(impl).send(input());
    expect(calls).toHaveLength(1);
    expect(calls[0].url).toBe(`https://api.twilio.com/2010-04-01/Accounts/${SID}/Messages.json`);
    expect(calls[0].init.headers.Authorization).toBe(
      `Basic ${Buffer.from(`${SID}:secret-token`).toString('base64')}`,
    );
    expect(calls[0].init.headers['I-Twilio-Idempotency-Token']).toBe('notif_123');
    const form = new URLSearchParams(calls[0].init.body);
    expect(form.get('To')).toBe('+8801711000000');
    expect(form.get('From')).toBe('+15005550006');
    expect(form.get('Body')).toContain('payment failed');
    expect(r).toMatchObject({
      accepted: true,
      providerReference: MSG_SID,
      resultType: ProviderDeliveryResultType.ACCEPTED,
    });
    expect(JSON.stringify(r)).not.toContain('secret-token');
  });

  it('prefers a Messaging Service and an API key when configured', async () => {
    const { impl, calls } = fakeFetch({
      ok: true,
      status: 201,
      body: { sid: MSG_SID, status: 'accepted' },
    });
    const p = new TwilioSmsProvider({
      accountSid: SID,
      authToken: 'account-token',
      apiKeySid: 'SK' + 'b'.repeat(32),
      apiKeySecret: 'key-secret',
      messagingServiceSid: MG,
      fetchImpl: impl,
    });
    expect((await p.send(input())).accepted).toBe(true);
    const form = new URLSearchParams(calls[0].init.body);
    expect(form.get('MessagingServiceSid')).toBe(MG);
    expect(form.get('From')).toBeNull();
    expect(calls[0].init.headers.Authorization).toBe(
      `Basic ${Buffer.from(`SK${'b'.repeat(32)}:key-secret`).toString('base64')}`,
    );
  });

  it('a missing or non-E.164 recipient is a permanent failure without an API call', async () => {
    const { impl, calls } = fakeFetch({
      ok: true,
      status: 201,
      body: { sid: MSG_SID, status: 'queued' },
    });
    for (const recipientPhone of [undefined, '01711000000', '+0123', 'abc']) {
      const r = await configured(impl).send(input({ recipientPhone }));
      expect(r).toMatchObject({
        accepted: false,
        retryable: false,
        errorCode: 'SMS_INVALID_RECIPIENT',
      });
    }
    expect(calls).toHaveLength(0);
  });

  it('maps Twilio errors: 4xx permanent, 429/5xx/network retryable', async () => {
    const perm = await configured(
      fakeFetch({
        ok: false,
        status: 400,
        body: { code: 21211, message: "Invalid 'To' Phone Number" },
      }).impl,
    ).send(input());
    expect(perm).toMatchObject({
      accepted: false,
      retryable: false,
      errorCode: 'TWILIO_21211',
      resultType: ProviderDeliveryResultType.PERMANENT_FAILURE,
    });

    const limited = await configured(
      fakeFetch({ ok: false, status: 429, body: { code: 20429, message: 'Too Many Requests' } })
        .impl,
    ).send(input());
    expect(limited).toMatchObject({
      accepted: false,
      retryable: true,
      resultType: ProviderDeliveryResultType.TEMPORARY_FAILURE,
    });

    const down = await configured(fakeFetch({ ok: false, status: 503, body: null }).impl).send(
      input(),
    );
    expect(down).toMatchObject({ accepted: false, retryable: true, errorCode: 'TWILIO_HTTP_503' });

    const network = await configured(fakeFetch(new Error('ECONNRESET')).impl).send(input());
    expect(network).toMatchObject({
      accepted: false,
      retryable: true,
      errorCode: 'SMS_NETWORK_ERROR',
    });
  });

  it('a 2xx without a message sid, or with a failed status, is not accepted', async () => {
    const noSid = await configured(
      fakeFetch({ ok: true, status: 201, body: { status: 'queued' } }).impl,
    ).send(input());
    expect(noSid.accepted).toBe(false);
    const failed = await configured(
      fakeFetch({
        ok: true,
        status: 201,
        body: { sid: MSG_SID, status: 'failed', error_code: 30006 },
      }).impl,
    ).send(input());
    expect(failed).toMatchObject({ accepted: false, retryable: false, errorCode: 'TWILIO_30006' });
  });

  it('delivery status: delivered only when Twilio says delivered', async () => {
    const p = configured(fakeFetch({ ok: true, status: 200, body: { status: 'sent' } }).impl);
    expect(await p.getDeliveryStatus(MSG_SID)).toEqual({ delivered: false, status: 'sent' });
    const d = configured(fakeFetch({ ok: true, status: 200, body: { status: 'delivered' } }).impl);
    expect(await d.getDeliveryStatus(MSG_SID)).toEqual({ delivered: true, status: 'delivered' });
    await expect(d.getDeliveryStatus('inapp_1')).rejects.toThrow(/Not a Twilio message sid/);
  });

  it('masks phone numbers for logs', () => {
    expect(maskPhone('+8801711000000')).toBe('+88****00');
    expect(maskPhone(undefined)).toBe('(none)');
  });
});

import { Logger } from '@nestjs/common';
import { NotificationChannel } from './billing-notification.types';
import {
  INotificationProvider,
  ProviderDeliveryResultType,
  SendNotificationInput,
  SendNotificationResult,
} from './notification-provider.interface';

/**
 * Twilio Programmable Messaging SMS adapter (plain REST, no SDK).
 *
 * Configuration (all required unless noted):
 *  - TWILIO_ACCOUNT_SID   AC...
 *  - TWILIO_AUTH_TOKEN    or TWILIO_API_KEY_SID (SK...) + TWILIO_API_KEY_SECRET
 *  - TWILIO_MESSAGING_SERVICE_SID (MG...)  or  TWILIO_FROM_NUMBER (E.164)
 *  - TWILIO_STATUS_CALLBACK_URL (optional, https only)
 *
 * Fail-closed rules:
 *  - incomplete configuration -> isAvailable() false and send() throws, so
 *    NotificationDeliveryService records PROVIDER_NOT_CONFIGURED; nothing is
 *    reported as delivered;
 *  - the recipient must be an E.164 number; anything else is a permanent
 *    failure (never retried);
 *  - "accepted" means Twilio queued the message (status queued/accepted/
 *    sending/sent) - that is what Twilio's create call can prove; handset
 *    delivery arrives later on the status callback;
 *  - 429 and 5xx are retryable, other 4xx are permanent; the credentials
 *    never appear in a result or a log line, and phone numbers are masked.
 */

const E164 = /^\+[1-9]\d{6,14}$/;
const MAX_SMS_BODY = 1600;

export type SmsFetchLike = (
  url: string,
  init: { method: string; headers: Record<string, string>; body?: string },
) => Promise<{
  ok: boolean;
  status: number;
  json(): Promise<any>;
}>;

export interface TwilioSmsOptions {
  accountSid?: string;
  authToken?: string;
  apiKeySid?: string;
  apiKeySecret?: string;
  messagingServiceSid?: string;
  fromNumber?: string;
  statusCallbackUrl?: string;
  apiBase?: string;
  fetchImpl?: SmsFetchLike;
}

export function maskPhone(phone: string | undefined): string {
  if (!phone) return '(none)';
  return phone.length <= 4 ? '****' : `${phone.slice(0, 3)}****${phone.slice(-2)}`;
}

export class TwilioSmsProvider implements INotificationProvider {
  readonly providerName = 'twilio';
  readonly supportedChannels = [NotificationChannel.SMS] as NotificationChannel[];
  private readonly logger = new Logger(TwilioSmsProvider.name);
  private readonly accountSid: string;
  private readonly username: string;
  private readonly password: string;
  private readonly messagingServiceSid: string;
  private readonly fromNumber: string;
  private readonly statusCallbackUrl: string;
  private readonly apiBase: string;
  private readonly fetchImpl: SmsFetchLike | undefined;

  constructor(options: TwilioSmsOptions = {}) {
    const env = process.env;
    this.accountSid = (options.accountSid ?? env.TWILIO_ACCOUNT_SID ?? '').trim();
    const apiKeySid = (options.apiKeySid ?? env.TWILIO_API_KEY_SID ?? '').trim();
    const apiKeySecret = (options.apiKeySecret ?? env.TWILIO_API_KEY_SECRET ?? '').trim();
    const authToken = (options.authToken ?? env.TWILIO_AUTH_TOKEN ?? '').trim();
    // Prefer a revocable API key over the account auth token.
    if (apiKeySid && apiKeySecret) {
      this.username = apiKeySid;
      this.password = apiKeySecret;
    } else {
      this.username = this.accountSid;
      this.password = authToken;
    }
    this.messagingServiceSid = (
      options.messagingServiceSid ??
      env.TWILIO_MESSAGING_SERVICE_SID ??
      ''
    ).trim();
    this.fromNumber = (options.fromNumber ?? env.TWILIO_FROM_NUMBER ?? '').trim();
    this.statusCallbackUrl = (
      options.statusCallbackUrl ??
      env.TWILIO_STATUS_CALLBACK_URL ??
      ''
    ).trim();
    this.apiBase = (options.apiBase ?? env.TWILIO_API_BASE ?? 'https://api.twilio.com').replace(
      /\/+$/,
      '',
    );
    this.fetchImpl =
      options.fetchImpl ??
      (typeof fetch === 'function' ? (fetch as unknown as SmsFetchLike) : undefined);
  }

  isAvailable(): boolean {
    return this.configurationProblems().length === 0;
  }

  /** Names of missing/invalid settings (never their values). */
  configurationProblems(): string[] {
    const problems: string[] = [];
    if (!/^AC[0-9a-fA-F]{32}$/.test(this.accountSid)) problems.push('TWILIO_ACCOUNT_SID');
    if (!this.password)
      problems.push('TWILIO_AUTH_TOKEN or TWILIO_API_KEY_SID/TWILIO_API_KEY_SECRET');
    if (!/^MG[0-9a-fA-F]{32}$/.test(this.messagingServiceSid) && !E164.test(this.fromNumber)) {
      problems.push('TWILIO_MESSAGING_SERVICE_SID or TWILIO_FROM_NUMBER (E.164)');
    }
    if (this.statusCallbackUrl && !/^https:\/\//.test(this.statusCallbackUrl))
      problems.push('TWILIO_STATUS_CALLBACK_URL (https)');
    if (!this.fetchImpl) problems.push('fetch runtime');
    return problems;
  }

  async send(input: SendNotificationInput): Promise<SendNotificationResult> {
    const problems = this.configurationProblems();
    if (problems.length > 0) {
      throw new Error(
        `SMS provider twilio not configured (missing: ${problems.join(', ')}). No fake success allowed.`,
      );
    }

    const to = (input.recipientPhone || '').replace(/[\s().-]/g, '');
    if (!E164.test(to)) {
      return {
        accepted: false,
        providerReference: null,
        resultType: ProviderDeliveryResultType.PERMANENT_FAILURE,
        retryable: false,
        errorCode: 'SMS_INVALID_RECIPIENT',
        failureReason: 'Recipient phone number missing or not in E.164 format',
      };
    }

    const text = (input.body || input.subject || '').trim();
    if (!text) {
      return {
        accepted: false,
        providerReference: null,
        resultType: ProviderDeliveryResultType.PERMANENT_FAILURE,
        retryable: false,
        errorCode: 'SMS_EMPTY_BODY',
        failureReason: 'SMS body is empty',
      };
    }

    const form = new URLSearchParams();
    form.set('To', to);
    form.set('Body', text.length > MAX_SMS_BODY ? `${text.slice(0, MAX_SMS_BODY - 1)}…` : text);
    if (/^MG[0-9a-fA-F]{32}$/.test(this.messagingServiceSid))
      form.set('MessagingServiceSid', this.messagingServiceSid);
    else form.set('From', this.fromNumber);
    if (this.statusCallbackUrl) form.set('StatusCallback', this.statusCallbackUrl);

    const url = `${this.apiBase}/2010-04-01/Accounts/${encodeURIComponent(this.accountSid)}/Messages.json`;
    const auth = Buffer.from(`${this.username}:${this.password}`).toString('base64');
    let response: Awaited<ReturnType<SmsFetchLike>>;
    try {
      response = await this.fetchImpl!(url, {
        method: 'POST',
        headers: {
          Authorization: `Basic ${auth}`,
          'Content-Type': 'application/x-www-form-urlencoded',
          Accept: 'application/json',
          // Twilio honours this header for safe retries of message creation.
          'I-Twilio-Idempotency-Token': input.idempotencyKey.slice(0, 64),
        },
        body: form.toString(),
      });
    } catch (err: any) {
      this.logger.warn(
        `Twilio request failed to=${maskPhone(to)} tenant=${input.tenantId}: ${err?.message ?? 'network error'}`,
      );
      return {
        accepted: false,
        providerReference: null,
        resultType: ProviderDeliveryResultType.TEMPORARY_FAILURE,
        retryable: true,
        errorCode: 'SMS_NETWORK_ERROR',
        failureReason: 'Could not reach Twilio',
      };
    }

    let payload: any = null;
    try {
      payload = await response.json();
    } catch {
      payload = null;
    }

    if (!response.ok) {
      const retryable = response.status === 429 || response.status >= 500;
      const code = payload?.code ? `TWILIO_${payload.code}` : `TWILIO_HTTP_${response.status}`;
      this.logger.warn(
        `Twilio rejected SMS to=${maskPhone(to)} tenant=${input.tenantId} status=${response.status} code=${code}`,
      );
      return {
        accepted: false,
        providerReference: null,
        resultType: retryable
          ? ProviderDeliveryResultType.TEMPORARY_FAILURE
          : ProviderDeliveryResultType.PERMANENT_FAILURE,
        retryable,
        errorCode: code,
        failureReason: payload?.message
          ? String(payload.message)
          : `Twilio HTTP ${response.status}`,
      };
    }

    const sid = typeof payload?.sid === 'string' ? payload.sid : null;
    const status = String(payload?.status ?? '').toLowerCase();
    if (!sid || (!sid.startsWith('SM') && !sid.startsWith('MM'))) {
      return {
        accepted: false,
        providerReference: null,
        resultType: ProviderDeliveryResultType.TEMPORARY_FAILURE,
        retryable: true,
        errorCode: 'SMS_UNEXPECTED_RESPONSE',
        failureReason: 'Twilio response did not contain a message sid',
      };
    }
    if (status === 'failed' || status === 'undelivered' || status === 'canceled') {
      return {
        accepted: false,
        providerReference: sid,
        resultType: ProviderDeliveryResultType.PERMANENT_FAILURE,
        retryable: false,
        errorCode: payload?.error_code ? `TWILIO_${payload.error_code}` : 'SMS_REJECTED',
        failureReason: payload?.error_message
          ? String(payload.error_message)
          : `Twilio status ${status}`,
      };
    }

    this.logger.log(
      `SMS queued via Twilio sid=${sid} to=${maskPhone(to)} template=${input.templateKey} tenant=${input.tenantId}`,
    );
    return {
      accepted: true,
      providerReference: sid,
      resultType: ProviderDeliveryResultType.ACCEPTED,
      retryable: false,
      rawResponse: { sid, status, numSegments: payload?.num_segments ?? null },
    };
  }

  async getDeliveryStatus(
    providerReference: string,
  ): Promise<{ delivered: boolean; status: string }> {
    if (!this.isAvailable()) throw new Error('SMS provider twilio not configured');
    if (!/^(SM|MM)[0-9a-fA-F]{32}$/.test(providerReference))
      throw new Error('Not a Twilio message sid');
    const url = `${this.apiBase}/2010-04-01/Accounts/${encodeURIComponent(this.accountSid)}/Messages/${providerReference}.json`;
    const auth = Buffer.from(`${this.username}:${this.password}`).toString('base64');
    const response = await this.fetchImpl!(url, {
      method: 'GET',
      headers: { Authorization: `Basic ${auth}`, Accept: 'application/json' },
    });
    const payload = await response.json().catch(() => null);
    if (!response.ok) throw new Error(`Twilio status lookup failed (HTTP ${response.status})`);
    const status = String(payload?.status ?? 'unknown').toLowerCase();
    return { delivered: status === 'delivered', status };
  }
}

