import { Injectable, Logger } from '@nestjs/common';
import { PaymentProvider, PaymentStatus, TransactionState, PaymentMethodType } from './payment.types';
import type {
  IPaymentProvider,
  CreateCheckoutInput,
  CreateCheckoutResult,
  RetrievePaymentInput,
  VerifyWebhookInput,
  VerifyWebhookResult,
  NormalizeEventInput,
  ProviderCapabilities,
} from './payment-provider.interface';
import type { NormalizedPaymentResult, PaymentAmount } from './payment.types';
import type { NormalizedWebhookEvent } from './webhook.types';
import { PaymentConfigService } from './payment.config';
import { Decimal } from '../../../common/decimal-string';
import { nowPaymentsInvoiceAmountToNumber, paymentAmountToMinorUnits } from '../../../common/payment-amount';
import { AppException } from '../../../common/errors/app.exception';
import { ErrorCode } from '@wlct/shared-types';

/**
 * Real NowPayments integration adapter.
 *
 * Implements the common provider contract for NowPayments:
 *  - Payment/invoice creation using canonical plan price
 *  - Payment status retrieval
 *  - Webhook IPN verification
 *  - Event normalization
 *  - Status mapping
 *
 * Does NOT mark subscriptions active merely because payment object was created.
 * Payment completion is based on normalized provider payment status.
 */

@Injectable()
export class NowPaymentsAdapter implements IPaymentProvider {
  private readonly logger = new Logger(NowPaymentsAdapter.name);
  readonly provider = PaymentProvider.NOWPAYMENTS;

  readonly capabilities: ProviderCapabilities = {
    supportsCheckout: true,
    supportsPaymentIntents: true,
    supportsRefunds: false,
    supportsPartialRefunds: false,
    supportsWebhooks: true,
    supportsRecurring: false,
    supportsCrypto: true,
    supportedCurrencies: ['USD', 'EUR', 'BTC', 'ETH', 'USDT', 'USDC', 'BNB', 'LTC', 'TRX', 'DOGE'],
  };

  constructor(private readonly config: PaymentConfigService) {}

  async createCheckout(input: CreateCheckoutInput): Promise<CreateCheckoutResult> {
    this.validateCheckoutInput(input);

    const apiKey = this.config.getNowPaymentsApiKey();
    const baseUrl = this.config.nowpayments?.apiBaseUrl || 'https://api.nowpayments.io/v1';

    try {
      // /invoice requires a JSON number. Convert only when the number's decimal round-trip is exact.
      let amount: number;
      try {
        amount = nowPaymentsInvoiceAmountToNumber(input.price);
      } catch {
        throw new AppException({
          code: ErrorCode.VALIDATION_ERROR,
          message: 'Plan price cannot be represented losslessly as a NOWPayments invoice amount',
          context: { provider: PaymentProvider.NOWPAYMENTS, planId: input.planId },
        });
      }

      // NowPayments invoice creation
      const invoicePayload = {
        price_amount: amount,
        price_currency: input.currency.toLowerCase(),
        pay_currency: this.mapToCryptoCurrency(input.currency),
        order_id: input.references.orderId || input.idempotencyKey,
        order_description: `Subscription to ${input.planName} - ${input.interval}`,
        ipn_callback_url: this.buildIpnCallbackUrl(),
        success_url: input.successUrl,
        cancel_url: input.cancelUrl,
        is_fixed_rate: true,
        is_fee_paid_by_user: false,
      };

      const response = await this.makeApiRequest(`${baseUrl}/invoice`, {
        method: 'POST',
        headers: {
          'x-api-key': apiKey,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(invoicePayload),
      });

      if (!response || !response.id) {
        throw new Error(`Invalid NowPayments response: ${JSON.stringify(this.sanitizeResponse(response))}`);
      }

      this.logger.log(`NowPayments invoice created: ${response.id} for tenant ${input.tenantId}, plan ${input.planCode}`);

      return {
        providerCheckoutId: response.id.toString(),
        providerInvoiceId: response.id.toString(),
        providerPaymentId: response.payment_id?.toString() || response.id.toString(),
        checkoutUrl: response.invoice_url || response.payment_url,
        invoiceUrl: response.invoice_url,
        expiresAt: response.expiration_estimate_date ? new Date(response.expiration_estimate_date) : undefined,
        rawResponse: this.sanitizeResponse(response),
      };
    } catch (error) {
      if (error instanceof AppException) {
        throw error;
      }
      this.logger.error(`NowPayments checkout creation failed for tenant ${input.tenantId}: ${(error as Error).message}`);
      throw new AppException({
        code: ErrorCode.SERVICE_UNAVAILABLE,
        message: 'Failed to create NowPayments invoice',
        context: { provider: PaymentProvider.NOWPAYMENTS, planId: input.planId },
      });
    }
  }

  async retrievePayment(input: RetrievePaymentInput): Promise<NormalizedPaymentResult> {
    const apiKey = this.config.getNowPaymentsApiKey();
    const baseUrl = this.config.nowpayments?.apiBaseUrl || 'https://api.nowpayments.io/v1';

    try {
      let paymentData: any;

      if (input.providerPaymentId) {
        const response = await this.makeApiRequest(`${baseUrl}/payment/${input.providerPaymentId}`, {
          method: 'GET',
          headers: { 'x-api-key': apiKey },
        });
        paymentData = response;
      } else if (input.providerInvoiceId || input.providerCheckoutId) {
        const invoiceId = input.providerInvoiceId || input.providerCheckoutId;
        // Try to get payment by invoice - list payments and filter
        const response = await this.makeApiRequest(`${baseUrl}/payment/?orderId=${invoiceId}`, {
          method: 'GET',
          headers: { 'x-api-key': apiKey },
        });
        paymentData = Array.isArray(response) ? response[0] : response;
      } else {
        throw new AppException({
          code: ErrorCode.VALIDATION_ERROR,
          message: 'Provider payment ID or invoice ID required',
        });
      }

      if (!paymentData) {
        throw new AppException({
          code: ErrorCode.NOT_FOUND,
          message: 'NowPayments payment not found',
        });
      }

      return this.normalizeNowPaymentsToPaymentResult(paymentData);
    } catch (error) {
      if (error instanceof AppException) {
        throw error;
      }
      this.logger.error(`NowPayments payment retrieval failed: ${(error as Error).message}`);
      throw new AppException({
        code: ErrorCode.SERVICE_UNAVAILABLE,
        message: 'Failed to retrieve NowPayments payment',
      });
    }
  }

  async verifyWebhookSignature(input: VerifyWebhookInput): Promise<VerifyWebhookResult> {
    const ipnSecret = this.config.getNowPaymentsIpnSecret();
    if (!ipnSecret) {
      this.logger.warn('NOWPayments IPN secret is not configured; rejecting webhook');
      return { verified: false, failureReason: 'NOWPayments IPN secret is not configured' };
    }

    if (typeof input.signature !== 'string' || input.signature.trim() === '') {
      return { verified: false, failureReason: 'NOWPayments IPN signature is missing' };
    }

    const signature = input.signature.trim();
    if (!/^[0-9a-f]{128}$/i.test(signature)) {
      return { verified: false, failureReason: 'NOWPayments IPN signature has an invalid format' };
    }

    try {
      const rawBody = typeof input.rawBody === 'string' ? input.rawBody : input.rawBody.toString('utf8');
      const payload: unknown = JSON.parse(rawBody);
      if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
        return { verified: false, failureReason: 'NOWPayments IPN payload must be a JSON object' };
      }

      const crypto = await import('crypto');
      const canonicalPayload = JSON.stringify(sortNowPaymentsPayload(payload));
      const expectedSignature = crypto.createHmac('sha512', ipnSecret).update(canonicalPayload, 'utf8').digest();
      const suppliedSignature = Buffer.from(signature, 'hex');
      if (suppliedSignature.length !== expectedSignature.length || !crypto.timingSafeEqual(suppliedSignature, expectedSignature)) {
        this.logger.warn('NOWPayments IPN signature verification failed');
        return { verified: false, failureReason: 'Invalid NOWPayments IPN signature' };
      }

      const record = payload as Record<string, unknown>;
      const eventIdValue = record.payment_id ?? record.order_id;
      const eventId = typeof eventIdValue === 'string' && eventIdValue.trim() !== ''
        ? eventIdValue.trim()
        : typeof eventIdValue === 'number' && Number.isSafeInteger(eventIdValue) && eventIdValue > 0
          ? String(eventIdValue)
          : undefined;
      const eventType = typeof record.payment_status === 'string' && record.payment_status.trim() !== ''
        ? record.payment_status.trim()
        : undefined;
      if (!eventId || !eventType) {
        return { verified: false, failureReason: 'NOWPayments IPN event id or status is missing' };
      }

      return {
        verified: true,
        eventId,
        eventType,
        rawEvent: record,
      };
    } catch {
      this.logger.warn('NOWPayments webhook verification failed due to malformed payload');
      return { verified: false, failureReason: 'Malformed NOWPayments webhook payload' };
    }
  }

  async normalizeWebhookEvent(input: NormalizeEventInput): Promise<NormalizedWebhookEvent> {
    const rawEvent = input.rawEvent as any;

    if (
      !rawEvent ||
      !rawEvent.payment_id ||
      typeof rawEvent.payment_status !== 'string' ||
      rawEvent.payment_status.trim() === '' ||
      typeof rawEvent.price_amount !== 'string' ||
      rawEvent.price_amount.trim() === '' ||
      typeof rawEvent.price_currency !== 'string'
    ) {
      throw new AppException({
        code: ErrorCode.VALIDATION_ERROR,
        message: 'Invalid NowPayments event structure or exact amount evidence',
      });
    }

    let amount: string;
    try {
      const exactAmount = Decimal.parse(rawEvent.price_amount.trim());
      if (exactAmount.isNegative()) throw new TypeError('Payment amount must not be negative');
      amount = exactAmount.toString();
    } catch {
      throw new AppException({
        code: ErrorCode.VALIDATION_ERROR,
        message: 'NowPayments price amount must be a non-negative exact decimal string',
      });
    }

    const currency = rawEvent.price_currency.trim().toUpperCase();
    if (!/^[A-Z0-9]{2,12}$/.test(currency)) {
      throw new AppException({
        code: ErrorCode.VALIDATION_ERROR,
        message: 'NowPayments price currency is invalid',
      });
    }

    const paymentStatus = this.mapProviderStatusToInternalStatus(rawEvent.payment_status);
    const eventCategory = this.mapNowPaymentsStatusToCategory(rawEvent.payment_status);

    return {
      provider: PaymentProvider.NOWPAYMENTS,
      providerEventId: rawEvent.payment_id.toString(),
      eventType: rawEvent.payment_status.trim(),
      eventCategory,
      paymentStatus,
      providerPaymentId: rawEvent.payment_id.toString(),
      providerInvoiceId: rawEvent.order_id?.toString(),
      providerCheckoutId: rawEvent.order_id?.toString(),
      amount: { amount, currency },
      metadata: {
        tenantId: rawEvent.order_id?.split('_')[0] || undefined,
        orderId: rawEvent.order_id,
        payCurrency: rawEvent.pay_currency,
        priceCurrency: currency,
      },
      rawEvent: this.sanitizeResponse(rawEvent),
      receivedAt: new Date(),
      providerCreatedAt: typeof rawEvent.created_at === 'string' && rawEvent.created_at.trim() !== ''
        ? new Date(rawEvent.created_at)
        : null,
    };
  }

  mapProviderStatusToInternalStatus(providerStatus: string): PaymentStatus {
    const statusMap: Record<string, PaymentStatus> = {
      'waiting': PaymentStatus.PENDING,
      'confirming': PaymentStatus.PROCESSING,
      'confirmed': PaymentStatus.PROCESSING,
      'sending': PaymentStatus.PROCESSING,
      'partially_paid': PaymentStatus.PENDING,
      'finished': PaymentStatus.SUCCEEDED,
      'failed': PaymentStatus.FAILED,
      'refunded': PaymentStatus.REFUNDED,
      'expired': PaymentStatus.EXPIRED,
    };

    return statusMap[providerStatus?.toLowerCase()] || PaymentStatus.UNKNOWN;
  }

  mapProviderStatusToTransactionState(providerStatus: string): TransactionState {
    const stateMap: Record<string, TransactionState> = {
      'waiting': TransactionState.INITIALIZED,
      'confirming': TransactionState.AUTHORIZED,
      'confirmed': TransactionState.AUTHORIZED,
      'sending': TransactionState.AUTHORIZED,
      'partially_paid': TransactionState.INITIALIZED,
      'finished': TransactionState.CAPTURED,
      'failed': TransactionState.FAILED,
      'refunded': TransactionState.REFUNDED,
      'expired': TransactionState.FAILED,
    };

    return stateMap[providerStatus?.toLowerCase()] || TransactionState.FAILED;
  }

  private validateCheckoutInput(input: CreateCheckoutInput): void {
    if (!input.planId) {
      throw new AppException({ code: ErrorCode.VALIDATION_ERROR, message: 'Plan ID required' });
    }
    if (!input.tenantId) {
      throw new AppException({ code: ErrorCode.VALIDATION_ERROR, message: 'Tenant ID required' });
    }
    if (!input.price) {
      throw new AppException({ code: ErrorCode.VALIDATION_ERROR, message: 'Plan price required - must come from catalog' });
    }
    if (!input.idempotencyKey) {
      throw new AppException({ code: ErrorCode.VALIDATION_ERROR, message: 'Idempotency key required' });
    }
  }

  private mapToCryptoCurrency(fiatCurrency: string): string {
    const fiatToCrypto: Record<string, string> = {
      'USD': 'btc',
      'EUR': 'btc',
      'GBP': 'btc',
    };
    return fiatToCrypto[fiatCurrency.toUpperCase()] || 'btc';
  }

  private buildIpnCallbackUrl(): string {
    const publicUrl = process.env.API_PUBLIC_URL || 'http://localhost:4000';
    return `${publicUrl}/api/v1/billing/webhooks/nowpayments`;
  }

  private mapNowPaymentsStatusToCategory(status: string): any {
    switch (status?.toLowerCase()) {
      case 'finished':
        return 'PAYMENT_SUCCEEDED';
      case 'failed':
      case 'expired':
        return 'PAYMENT_FAILED';
      case 'refunded':
        return 'PAYMENT_REFUNDED';
      case 'waiting':
      case 'confirming':
      case 'confirmed':
      case 'sending':
      case 'partially_paid':
        return 'PAYMENT_PENDING';
      default:
        return 'PAYMENT_PENDING';
    }
  }

  private normalizeNowPaymentsToPaymentResult(paymentData: any): NormalizedPaymentResult {
    const status = this.mapProviderStatusToInternalStatus(paymentData.payment_status);
    const transactionState = this.mapProviderStatusToTransactionState(paymentData.payment_status);
    if (typeof paymentData.price_amount !== 'string' || typeof paymentData.price_currency !== 'string') {
      throw new TypeError('NowPayments payment response is missing exact amount or currency evidence');
    }

    const exactAmount = Decimal.parse(paymentData.price_amount);
    if (exactAmount.isNegative()) throw new TypeError('NowPayments payment amount must not be negative');
    const currency = paymentData.price_currency.trim().toUpperCase();
    if (!/^[A-Z0-9]{2,12}$/.test(currency)) throw new TypeError('NowPayments payment currency is invalid');

    const amount: PaymentAmount = {
      amount: exactAmount.toString(),
      currency,
      amountInSmallestUnit: paymentAmountToMinorUnits(exactAmount.toString(), currency),
    };

    return {
      internalPaymentId: paymentData.order_id || paymentData.payment_id?.toString(),
      provider: PaymentProvider.NOWPAYMENTS,
      status,
      transactionState,
      amount,
      providerReference: {
        provider: PaymentProvider.NOWPAYMENTS,
        providerPaymentId: paymentData.payment_id?.toString(),
        providerInvoiceId: paymentData.order_id?.toString(),
        providerCheckoutId: paymentData.order_id?.toString(),
        checkoutUrl: paymentData.invoice_url,
        invoiceUrl: paymentData.invoice_url,
      },
      references: {
        tenantId: paymentData.order_id?.split('_')[0] || '',
        planId: '',
        idempotencyKey: paymentData.order_id || '',
        orderId: paymentData.order_id || null,
      },
      metadata: {
        description: `NowPayments payment ${paymentData.payment_id}`,
      },
      paymentMethod: PaymentMethodType.CRYPTO,
      createdAt: paymentData.created_at ? new Date(paymentData.created_at).toISOString() : new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      rawProviderStatus: paymentData.payment_status,
    };
  }

  private async makeApiRequest(url: string, options: any): Promise<any> {
    // Use fetch API (Node 18+ has built-in fetch)
    const response = await fetch(url, {
      ...options,
      signal: AbortSignal.timeout(this.config.nowpayments?.timeoutMs || 30000),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`NowPayments API error ${response.status}: ${errorText}`);
    }

    return response.json();
  }

  private sanitizeResponse(response: any): any {
    if (!response) return null;
    const sanitized = { ...response };
    // Never log secrets, keys, etc
    delete sanitized.api_key;
    delete sanitized.ipn_secret;
    return sanitized;
  }
}

function sortNowPaymentsPayload(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sortNowPaymentsPayload);
  if (typeof value !== 'object' || value === null) return value;

  const source = value as Record<string, unknown>;
  const sorted = Object.create(null) as Record<string, unknown>;
  for (const key of Object.keys(source).sort()) {
    sorted[key] = sortNowPaymentsPayload(source[key]);
  }
  return sorted;
}

// # Contract-tests NOWPayments invoice creation against exact amount serialization.
import { AppException } from '../../../common/errors/app.exception';
import { NowPaymentsAdapter } from './nowpayments.adapter';

function checkoutInput(price: string): Record<string, unknown> {
  return {
    planId: 'plan-123',
    planCode: 'PRO',
    planName: 'Pro',
    price,
    currency: 'USD',
    interval: 'MONTHLY',
    tenantId: 'tenant-123',
    userId: 'user-123',
    subscriptionId: null,
    idempotencyKey: 'checkout-idempotency-123',
    successUrl: 'https://app.example.test/billing/success',
    cancelUrl: 'https://app.example.test/billing/cancel',
    metadata: {},
    references: { tenantId: 'tenant-123', planId: 'plan-123', idempotencyKey: 'checkout-idempotency-123' },
    amount: { amount: price, currency: 'USD', amountInSmallestUnit: 0 },
  };
}

describe('NOWPayments checkout exact amount contract', () => {
  it('serializes a lossless invoice JSON number while retaining the authoritative amount string', async () => {
    const config = {
      getNowPaymentsApiKey: jest.fn(() => 'test-api-key'),
      nowpayments: { apiBaseUrl: 'https://api.nowpayments.io/v1' },
    };
    const adapter = new NowPaymentsAdapter(config as any);
    const makeApiRequest = jest.spyOn(adapter as any, 'makeApiRequest').mockResolvedValue({
      id: 'invoice-123',
      payment_id: 'payment-123',
      invoice_url: 'https://pay.example.test/invoice-123',
      expiration_estimate_date: '2026-10-08T01:00:00.000Z',
    });

    const result = await adapter.createCheckout(checkoutInput('49.99') as any);
    const [, requestOptions] = makeApiRequest.mock.calls[0] as unknown as [string, { body: string }];
    const requestBody = JSON.parse(requestOptions.body) as Record<string, unknown>;

    expect(requestBody.price_amount).toBe(49.99);
    expect(result.providerInvoiceId).toBe('invoice-123');
    expect(result.providerPaymentId).toBe('payment-123');
    expect(result.checkoutUrl).toBe('https://pay.example.test/invoice-123');
    expect(makeApiRequest).toHaveBeenCalledTimes(1);
  });

  it('rejects a price that would change when converted to the provider-required JSON number', async () => {
    const config = {
      getNowPaymentsApiKey: jest.fn(() => 'test-api-key'),
      nowpayments: { apiBaseUrl: 'https://api.nowpayments.io/v1' },
    };
    const adapter = new NowPaymentsAdapter(config as any);
    const makeApiRequest = jest.spyOn(adapter as any, 'makeApiRequest');

    await expect(adapter.createCheckout(checkoutInput('1.230000000000000001') as any)).rejects.toBeInstanceOf(AppException);
    await expect(adapter.createCheckout(checkoutInput('1.230000000000000001') as any)).rejects.toMatchObject({
      code: 'VALIDATION_ERROR',
    });
    expect(makeApiRequest).not.toHaveBeenCalled();
  });
});

// # Contract-tests that NOWPayments IPNs fail closed and require a valid HMAC before normalization
import { createHmac } from 'crypto';
import { PaymentProvider } from './payment.types';
import { NowPaymentsAdapter } from './nowpayments.adapter';

const IPN_SECRET = 'contract-test-ipn-secret';
const CANONICAL_BODY = '{"details":{"a":"first","z":"last"},"payment_id":"np-payment-123","payment_status":"finished","price_amount":"1.23","price_currency":"USD"}';

function signCanonicalBody(body: string): string {
  return createHmac('sha512', IPN_SECRET).update(body, 'utf8').digest('hex');
}

function adapterWithSecret(secret: string | undefined): NowPaymentsAdapter {
  return new NowPaymentsAdapter({
    getNowPaymentsIpnSecret: () => secret,
  } as any);
}

describe('NOWPayments webhook signature contract', () => {
  const payload = {
    price_currency: 'USD',
    payment_status: 'finished',
    details: { z: 'last', a: 'first' },
    price_amount: '1.23',
    payment_id: 'np-payment-123',
  };

  it('accepts the recursively key-sorted HMAC and returns the signed event evidence', async () => {
    const adapter = adapterWithSecret(IPN_SECRET);
    const result = await adapter.verifyWebhookSignature({
      rawBody: JSON.stringify(payload),
      signature: signCanonicalBody(CANONICAL_BODY),
    });

    expect(result).toMatchObject({
      verified: true,
      eventId: 'np-payment-123',
      eventType: 'finished',
      rawEvent: payload,
    });
  });

  it('normalizes webhook amounts as exact decimal strings and refuses numeric coercion', async () => {
    const adapter = adapterWithSecret(IPN_SECRET);
    const normalized = await adapter.normalizeWebhookEvent({
      provider: PaymentProvider.NOWPAYMENTS,
      rawEvent: payload,
    });

    expect(normalized.amount).toEqual({ amount: '1.23', currency: 'USD' });
    expect(normalized.providerCreatedAt).toBeNull();
    await expect(adapter.normalizeWebhookEvent({
      provider: PaymentProvider.NOWPAYMENTS,
      rawEvent: { ...payload, price_amount: 1.23 },
    })).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
  });

  it('rejects structurally valid payloads when the IPN secret is not configured', async () => {
    const adapter = adapterWithSecret(undefined);
    const result = await adapter.verifyWebhookSignature({
      rawBody: JSON.stringify(payload),
      signature: signCanonicalBody(CANONICAL_BODY),
    });

    expect(result).toMatchObject({
      verified: false,
      failureReason: 'NOWPayments IPN secret is not configured',
    });
  });

  it('rejects a missing signature even when the secret exists', async () => {
    const adapter = adapterWithSecret(IPN_SECRET);
    const result = await adapter.verifyWebhookSignature({
      rawBody: JSON.stringify(payload),
      signature: '',
    });

    expect(result).toMatchObject({
      verified: false,
      failureReason: 'NOWPayments IPN signature is missing',
    });
  });

  it('rejects malformed and incorrect signatures without throwing', async () => {
    const adapter = adapterWithSecret(IPN_SECRET);
    const malformed = await adapter.verifyWebhookSignature({
      rawBody: JSON.stringify(payload),
      signature: 'not-a-hex-hmac',
    });
    const mismatch = await adapter.verifyWebhookSignature({
      rawBody: JSON.stringify(payload),
      signature: signCanonicalBody(CANONICAL_BODY.replace('1.23', '9.99')),
    });

    expect(malformed).toMatchObject({ verified: false, failureReason: 'NOWPayments IPN signature has an invalid format' });
    expect(mismatch).toMatchObject({ verified: false, failureReason: 'Invalid NOWPayments IPN signature' });
  });

  it('rejects a validly signed event without an event id or provider status', async () => {
    const adapter = adapterWithSecret(IPN_SECRET);
    const noIdentity = { payment_status: 'finished', price_amount: '1.23', price_currency: 'USD' };
    const missingStatus = { payment_id: 'np-payment-123', price_amount: '1.23', price_currency: 'USD' };
    const canonical = (body: Record<string, unknown>) => JSON.stringify(body);
    const sign = (body: string) => createHmac('sha512', IPN_SECRET).update(body, 'utf8').digest('hex');

    const noIdentityResult = await adapter.verifyWebhookSignature({
      rawBody: JSON.stringify(noIdentity),
      signature: sign(canonical(noIdentity)),
    });
    const missingStatusResult = await adapter.verifyWebhookSignature({
      rawBody: JSON.stringify(missingStatus),
      signature: sign(canonical(missingStatus)),
    });

    expect(noIdentityResult).toMatchObject({ verified: false, failureReason: 'NOWPayments IPN event id or status is missing' });
    expect(missingStatusResult).toMatchObject({ verified: false, failureReason: 'NOWPayments IPN event id or status is missing' });
  });
});

import { Injectable, Logger } from '@nestjs/common';
import { InjectPinoLogger, PinoLogger } from 'nestjs-pino';
import { AuditAction, AuditActorType, AuditOutcome } from '@wlct/shared-types';
import { AuditService } from '../../audit/audit.service';
import { PaymentProvider, PaymentStatus } from './payment.types';

/**
 * Structured payment audit events for checkout created, payment pending,
 * payment succeeded, payment failed, webhook accepted/rejected, refund,
 * and reconciliation actions without sensitive data.
 *
 * Audit data may include:
 *  - tenant ID
 *  - internal payment ID
 *  - provider
 *  - provider event ID
 *  - plan ID
 *  - safe status
 *  - result
 *  - timestamp
 *
 * Never include:
 *  - card number
 *  - CVV
 *  - private key
 *  - API secret
 *  - provider secret
 *  - exchange API credentials
 *  - raw authorization headers
 */

export const PaymentAuditAction = {
  CHECKOUT_CREATED: 'CHECKOUT_CREATED',
  CHECKOUT_REJECTED: 'CHECKOUT_REJECTED',
  PAYMENT_CREATED: 'PAYMENT_CREATED',
  PAYMENT_PENDING: 'PAYMENT_PENDING',
  PAYMENT_SUCCEEDED: 'PAYMENT_SUCCEEDED',
  PAYMENT_FAILED: 'PAYMENT_FAILED',
  PAYMENT_CANCELLED: 'PAYMENT_CANCELLED',
  PAYMENT_EXPIRED: 'PAYMENT_EXPIRED',
  PAYMENT_REFUNDED: 'PAYMENT_REFUNDED',
  PAYMENT_DUPLICATE: 'PAYMENT_DUPLICATE',
  PAYMENT_TRANSITION_REJECTED: 'PAYMENT_TRANSITION_REJECTED',
  WEBHOOK_RECEIVED: 'WEBHOOK_RECEIVED',
  WEBHOOK_REJECTED: 'WEBHOOK_REJECTED',
  WEBHOOK_DUPLICATE: 'WEBHOOK_DUPLICATE',
  WEBHOOK_PROCESSED: 'WEBHOOK_PROCESSED',
  PAYMENT_RECONCILED: 'PAYMENT_RECONCILED',
  SUBSCRIPTION_ACTIVATED: 'SUBSCRIPTION_ACTIVATED',
  SUBSCRIPTION_RENEWED: 'SUBSCRIPTION_RENEWED',
  SUBSCRIPTION_REFUNDED: 'SUBSCRIPTION_REFUNDED',
  SUBSCRIPTION_PAUSED: 'SUBSCRIPTION_PAUSED',
  SUBSCRIPTION_SYNC_FAILED: 'SUBSCRIPTION_SYNC_FAILED',
  SUBSCRIPTION_SYNC_SKIPPED: 'SUBSCRIPTION_SYNC_SKIPPED',
} as const;

export interface PaymentAuditEvent {
  tenantId: string;
  paymentId?: string;
  provider: PaymentProvider;
  action: keyof typeof PaymentAuditAction | string;
  status?: PaymentStatus | string;
  result?: string;
  planId?: string;
  subscriptionId?: string;
  amount?: string;
  currency?: string;
  providerEventId?: string;
  eventType?: string;
  actorId?: string;
  ipHash?: string;
  requestId?: string;
  error?: string;
  metadata?: Record<string, unknown>;
}

@Injectable()
export class PaymentEventsAuditService {
  private readonly logger = new Logger(PaymentEventsAuditService.name);

  constructor(
    private readonly audit: AuditService,
    @InjectPinoLogger(PaymentEventsAuditService.name) private readonly pinoLogger: PinoLogger,
  ) {}

  async logPaymentEvent(event: PaymentAuditEvent): Promise<void> {
    try {
      const safeMetadata = this.sanitizeMetadata(event.metadata);

      await this.audit.record({
        tenantId: event.tenantId,
        actorType: AuditActorType.SYSTEM,
        actorId: event.actorId || 'system',
        action: event.action as AuditAction,
        outcome: this.mapActionToOutcome(event.action),
        resourceType: 'payment',
        resourceId: event.paymentId || event.providerEventId,
        description: this.buildDescription(event),
        metadata: {
          provider: event.provider,
          paymentId: event.paymentId,
          providerEventId: event.providerEventId,
          eventType: event.eventType,
          status: event.status,
          result: event.result,
          planId: event.planId,
          subscriptionId: event.subscriptionId,
          amount: event.amount,
          currency: event.currency,
          error: event.error ? this.sanitizeError(event.error) : undefined,
          ...safeMetadata,
        },
        ipHash: event.ipHash,
        requestId: event.requestId,
      });

      this.pinoLogger.info(
        {
          event: 'payment.audit',
          tenantId: event.tenantId,
          paymentId: event.paymentId,
          provider: event.provider,
          action: event.action,
          status: event.status,
          providerEventId: event.providerEventId,
        },
        `Payment audit: ${event.action}`,
      );
    } catch (error) {
      this.logger.error(`Failed to log payment audit event: ${(error as Error).message}`);
    }
  }

  async logWebhookEvent(event: {
    provider: PaymentProvider;
    providerEventId: string;
    action: string;
    result: string;
    eventType?: string;
    paymentId?: string;
    tenantId?: string;
    status?: PaymentStatus | string;
    error?: string;
    metadata?: Record<string, unknown>;
  }): Promise<void> {
    try {
      const safeMetadata = this.sanitizeMetadata(event.metadata);

      await this.audit.record({
        tenantId: event.tenantId || 'system',
        actorType: AuditActorType.SYSTEM,
        actorId: 'webhook',
        action: event.action as AuditAction,
        outcome: this.mapActionToOutcome(event.action),
        resourceType: 'webhook',
        resourceId: event.providerEventId,
        description: `Webhook ${event.action}: ${event.provider} ${event.providerEventId}`,
        metadata: {
          provider: event.provider,
          providerEventId: event.providerEventId,
          eventType: event.eventType,
          paymentId: event.paymentId,
          status: event.status,
          result: event.result,
          error: event.error ? this.sanitizeError(event.error) : undefined,
          ...safeMetadata,
        },
      });

      this.pinoLogger.info(
        {
          event: 'webhook.audit',
          provider: event.provider,
          providerEventId: event.providerEventId,
          action: event.action,
          result: event.result,
        },
        `Webhook audit: ${event.action}`,
      );
    } catch (error) {
      this.logger.error(`Failed to log webhook audit event: ${(error as Error).message}`);
    }
  }

  async logCheckoutEvent(event: {
    tenantId: string;
    checkoutId?: string;
    paymentId?: string;
    provider: PaymentProvider;
    action: string;
    status?: string;
    planId?: string;
    amount?: string;
    currency?: string;
    actorId?: string;
    ipHash?: string;
    requestId?: string;
    metadata?: Record<string, unknown>;
  }): Promise<void> {
    try {
      const safeMetadata = this.sanitizeMetadata(event.metadata);

      await this.audit.record({
        tenantId: event.tenantId,
        actorType: AuditActorType.USER,
        actorId: event.actorId || 'system',
        action: event.action as AuditAction,
        outcome: this.mapActionToOutcome(event.action),
        resourceType: 'checkout',
        resourceId: event.checkoutId || event.paymentId,
        description: `Checkout ${event.action}: ${event.provider} plan ${event.planId}`,
        metadata: {
          provider: event.provider,
          checkoutId: event.checkoutId,
          paymentId: event.paymentId,
          status: event.status,
          planId: event.planId,
          amount: event.amount,
          currency: event.currency,
          ...safeMetadata,
        },
        ipHash: event.ipHash,
        requestId: event.requestId,
      });
    } catch (error) {
      this.logger.error(`Failed to log checkout audit event: ${(error as Error).message}`);
    }
  }

  private mapActionToOutcome(action: string): any {
    const successActions = [
      'CHECKOUT_CREATED',
      'PAYMENT_CREATED',
      'PAYMENT_PENDING',
      'PAYMENT_SUCCEEDED',
      'WEBHOOK_RECEIVED',
      'WEBHOOK_PROCESSED',
      'PAYMENT_RECONCILED',
      'SUBSCRIPTION_ACTIVATED',
      'SUBSCRIPTION_RENEWED',
    ];

    const deniedActions = [
      'CHECKOUT_REJECTED',
      'PAYMENT_FAILED',
      'PAYMENT_CANCELLED',
      'PAYMENT_EXPIRED',
      'WEBHOOK_REJECTED',
    ];

    if (successActions.includes(action)) {
      return AuditOutcome.SUCCESS;
    }
    if (deniedActions.includes(action)) {
      return AuditOutcome.FAILURE;
    }
    return AuditOutcome.SUCCESS;
  }

  private buildDescription(event: PaymentAuditEvent): string {
    switch (event.action) {
      case 'CHECKOUT_CREATED':
        return `Checkout created for plan ${event.planId} via ${event.provider}`;
      case 'CHECKOUT_REJECTED':
        return `Checkout rejected for plan ${event.planId}: ${event.error || 'validation failed'}`;
      case 'PAYMENT_CREATED':
        return `Payment ${event.paymentId} created via ${event.provider}`;
      case 'PAYMENT_PENDING':
        return `Payment ${event.paymentId} pending via ${event.provider}`;
      case 'PAYMENT_SUCCEEDED':
        return `Payment ${event.paymentId} succeeded via ${event.provider}`;
      case 'PAYMENT_FAILED':
        return `Payment ${event.paymentId} failed via ${event.provider}: ${event.error || ''}`;
      case 'PAYMENT_CANCELLED':
        return `Payment ${event.paymentId} cancelled`;
      case 'PAYMENT_EXPIRED':
        return `Payment ${event.paymentId} expired`;
      case 'PAYMENT_REFUNDED':
        return `Payment ${event.paymentId} refunded`;
      case 'WEBHOOK_RECEIVED':
        return `Webhook received: ${event.provider} ${event.providerEventId}`;
      case 'WEBHOOK_REJECTED':
        return `Webhook rejected: ${event.provider} ${event.providerEventId}: ${event.error || ''}`;
      case 'WEBHOOK_DUPLICATE':
        return `Webhook duplicate: ${event.provider} ${event.providerEventId}`;
      case 'WEBHOOK_PROCESSED':
        return `Webhook processed: ${event.provider} ${event.providerEventId} → payment ${event.paymentId}`;
      case 'PAYMENT_RECONCILED':
        return `Payment ${event.paymentId} reconciled: ${event.status}`;
      default:
        return `${event.action}: payment ${event.paymentId || ''} provider ${event.provider}`;
    }
  }

  private sanitizeMetadata(metadata: Record<string, unknown> | undefined): Record<string, unknown> {
    if (!metadata) return {};

    const sanitized: Record<string, unknown> = {};
    const sensitiveKeys = [
      'card',
      'cvv',
      'cvc',
      'number',
      'secret',
      'api_key',
      'private_key',
      'credential',
      'password',
      'token',
      'authorization',
      'x-api-key',
      'stripe-signature',
    ];

    for (const [key, value] of Object.entries(metadata)) {
      const lowerKey = key.toLowerCase();
      const isSensitive = sensitiveKeys.some((s) => lowerKey.includes(s));

      if (isSensitive) {
        sanitized[key] = '***REDACTED***';
      } else if (typeof value === 'string' && value.length > 1000) {
        sanitized[key] = value.substring(0, 1000) + '...[truncated]';
      } else if (typeof value === 'object' && value !== null) {
        // Recursively sanitize nested objects, but limit depth
        try {
          sanitized[key] = JSON.parse(JSON.stringify(value));
          // Remove sensitive from nested
          if (typeof sanitized[key] === 'object') {
            const nested = sanitized[key] as any;
            for (const nestedKey of Object.keys(nested)) {
              if (sensitiveKeys.some((s) => nestedKey.toLowerCase().includes(s))) {
                nested[nestedKey] = '***REDACTED***';
              }
            }
          }
        } catch {
          sanitized[key] = '[unserializable]';
        }
      } else {
        sanitized[key] = value;
      }
    }

    return sanitized;
  }

  private sanitizeError(error: string): string {
    if (!error) return '';
    // Remove potential secrets from error messages
    let sanitized = error;

    // Redact anything that looks like a key
    sanitized = sanitized.replace(/sk_[a-zA-Z0-9_]+/g, 'sk_***REDACTED***');
    sanitized = sanitized.replace(/whsec_[a-zA-Z0-9_]+/g, 'whsec_***REDACTED***');
    sanitized = sanitized.replace(/api_key=[a-zA-Z0-9_]+/gi, 'api_key=***REDACTED***');

    if (sanitized.length > 500) {
      sanitized = sanitized.substring(0, 500) + '...[truncated]';
    }

    return sanitized;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PaymentRepository } from './payment.repository';
import { PaymentService } from './payment.service';
import { PaymentProviderFactory } from './payment-provider.factory';
import { PaymentEventsAuditService } from './payment-events.audit';
import { PaymentSubscriptionSyncService } from './payment-subscription-sync.service';
import { PaymentStatus, PaymentProvider, isValidPaymentTransition } from './payment.types';
import type { PaymentRecord } from './payment.types';

/**
 * Detects provider/internal status mismatches, retrieves provider state when
 * necessary, and safely reconciles payment state without blindly trusting
 * stale webhook data.
 *
 * Handles:
 *  provider says SUCCEEDED, internal says PENDING
 *  provider says FAILED, internal says PROCESSING
 *  provider says REFUNDED, internal says SUCCEEDED
 *
 * Must verify provider state before changing internal state when necessary.
 * Do not blindly trust webhook ordering.
 * Do not downgrade a valid final state without an explicitly supported transition.
 */

export interface ReconciliationResult {
  paymentId: string;
  tenantId: string;
  provider: PaymentProvider;
  internalStatusBefore: PaymentStatus;
  providerStatus: PaymentStatus;
  internalStatusAfter: PaymentStatus;
  reconciled: boolean;
  reason: string;
  shouldSyncSubscription: boolean;
}

export interface ReconciliationReport {
  totalChecked: number;
  totalMismatched: number;
  totalReconciled: number;
  totalFailed: number;
  totalSkipped: number;
  results: ReconciliationResult[];
}

@Injectable()
export class PaymentReconciliationService {
  private readonly logger = new Logger(PaymentReconciliationService.name);

  constructor(
    private readonly paymentRepository: PaymentRepository,
    private readonly paymentService: PaymentService,
    private readonly providerFactory: PaymentProviderFactory,
    private readonly audit: PaymentEventsAuditService,
    private readonly subscriptionSync: PaymentSubscriptionSyncService,
  ) {}

  async reconcilePayment(paymentId: string): Promise<ReconciliationResult> {
    const internalPayment = await this.paymentService.getPaymentById(paymentId);

    this.logger.log(`Reconciling payment ${paymentId}: internal status ${internalPayment.status}, provider ${internalPayment.provider}`);

    try {
      // Retrieve current state from provider
      const provider = this.providerFactory.getProvider(internalPayment.provider);
      const providerResult = await provider.retrievePayment({
        providerPaymentId: internalPayment.providerPaymentId || undefined,
        providerCheckoutId: internalPayment.providerCheckoutId || undefined,
        providerSessionId: internalPayment.providerSessionId || undefined,
        providerInvoiceId: internalPayment.providerInvoiceId || undefined,
      });

      const providerStatus = providerResult.status;
      const internalStatusBefore = internalPayment.status;

      // Check if statuses match
      if (providerStatus === internalStatusBefore) {
        this.logger.log(`Payment ${paymentId} already in sync: ${internalStatusBefore}`);

        return {
          paymentId,
          tenantId: internalPayment.tenantId,
          provider: internalPayment.provider,
          internalStatusBefore,
          providerStatus,
          internalStatusAfter: internalStatusBefore,
          reconciled: false,
          reason: 'Already in sync',
          shouldSyncSubscription: false,
        };
      }

      // Validate transition from internal to provider status
      if (!isValidPaymentTransition(internalStatusBefore, providerStatus)) {
        this.logger.warn(`Reconciliation transition rejected: ${internalStatusBefore} → ${providerStatus} for payment ${paymentId} - invalid transition`);

        await this.audit.logPaymentEvent({
          tenantId: internalPayment.tenantId,
          paymentId,
          provider: internalPayment.provider,
          action: 'PAYMENT_RECONCILED',
          status: internalStatusBefore,
          planId: internalPayment.planId,
          metadata: {
            reconciled: false,
            reason: 'invalid_transition',
            internalStatusBefore,
            providerStatus,
            attemptedAfter: providerStatus,
          },
        });

        return {
          paymentId,
          tenantId: internalPayment.tenantId,
          provider: internalPayment.provider,
          internalStatusBefore,
          providerStatus,
          internalStatusAfter: internalStatusBefore,
          reconciled: false,
          reason: `Invalid transition: ${internalStatusBefore} → ${providerStatus}`,
          shouldSyncSubscription: false,
        };
      }

      // Do not downgrade a valid final state without explicitly supported transition
      // Final states: SUCCEEDED, REFUNDED, DISPUTED, CANCELLED, EXPIRED, FAILED (in some cases)
      const finalStates = [PaymentStatus.SUCCEEDED, PaymentStatus.REFUNDED, PaymentStatus.DISPUTED, PaymentStatus.CANCELLED];
      const isDowngrade = finalStates.includes(internalStatusBefore) && ![PaymentStatus.REFUNDED, PaymentStatus.DISPUTED, PaymentStatus.PARTIALLY_REFUNDED].includes(providerStatus);

      if (isDowngrade) {
        this.logger.warn(`Reconciliation downgrade rejected: ${internalStatusBefore} → ${providerStatus} for payment ${paymentId} - final state downgrade`);

        await this.audit.logPaymentEvent({
          tenantId: internalPayment.tenantId,
          paymentId,
          provider: internalPayment.provider,
          action: 'PAYMENT_RECONCILED',
          status: internalStatusBefore,
          planId: internalPayment.planId,
          metadata: {
            reconciled: false,
            reason: 'final_state_downgrade_rejected',
            internalStatusBefore,
            providerStatus,
          },
        });

        return {
          paymentId,
          tenantId: internalPayment.tenantId,
          provider: internalPayment.provider,
          internalStatusBefore,
          providerStatus,
          internalStatusAfter: internalStatusBefore,
          reconciled: false,
          reason: `Final state downgrade rejected: ${internalStatusBefore} → ${providerStatus}`,
          shouldSyncSubscription: false,
        };
      }

      // Apply provider status to internal record
      const updatedPayment = await this.paymentService.applyProviderResult(paymentId, providerResult);

      const shouldSyncSubscription = this.shouldSyncSubscriptionForReconciliation(internalStatusBefore, providerStatus);

      if (shouldSyncSubscription) {
        try {
          await this.subscriptionSync.syncPaymentToSubscription(updatedPayment);
          this.logger.log(`Reconciled payment ${paymentId} synced to subscription`);
        } catch (syncError) {
          this.logger.error(`Failed to sync reconciled payment ${paymentId} to subscription: ${(syncError as Error).message}`);
        }
      }

      await this.audit.logPaymentEvent({
        tenantId: internalPayment.tenantId,
        paymentId,
        provider: internalPayment.provider,
        action: 'PAYMENT_RECONCILED',
        status: providerStatus,
        planId: internalPayment.planId,
        amount: internalPayment.amount,
        currency: internalPayment.currency,
        metadata: {
          reconciled: true,
          internalStatusBefore,
          providerStatus,
          internalStatusAfter: updatedPayment.status,
          shouldSyncSubscription,
        },
      });

      this.logger.log(`Payment ${paymentId} reconciled: ${internalStatusBefore} → ${providerStatus} (provider says ${providerResult.rawProviderStatus})`);

      return {
        paymentId,
        tenantId: internalPayment.tenantId,
        provider: internalPayment.provider,
        internalStatusBefore,
        providerStatus,
        internalStatusAfter: updatedPayment.status,
        reconciled: true,
        reason: `Reconciled from provider: ${providerResult.rawProviderStatus} → ${providerStatus}`,
        shouldSyncSubscription,
      };
    } catch (error) {
      this.logger.error(`Reconciliation failed for payment ${paymentId}: ${(error as Error).message}`);

      await this.audit.logPaymentEvent({
        tenantId: internalPayment.tenantId,
        paymentId,
        provider: internalPayment.provider,
        action: 'PAYMENT_RECONCILED',
        status: internalPayment.status,
        planId: internalPayment.planId,
        error: (error as Error).message,
        metadata: { reconciled: false, reason: 'reconciliation_error' },
      });

      throw error;
    }
  }

  async reconcilePaymentsByTenant(tenantId: string): Promise<ReconciliationReport> {
    const payments = await this.paymentRepository.list({ tenantId });

    return this.reconcilePaymentList(payments);
  }

  async reconcilePendingPayments(): Promise<ReconciliationReport> {
    // Find payments that are in pending/processing state and older than 5 minutes
    const fiveMinutesAgo = new Date(Date.now() - 5 * 60 * 1000);

    const pendingPayments = await this.paymentRepository.list({
      status: PaymentStatus.PENDING as any,
    });

    const processingPayments = await this.paymentRepository.list({
      status: PaymentStatus.PROCESSING as any,
    });

    const allPending = [...pendingPayments, ...processingPayments].filter((p) => p.createdAt < fiveMinutesAgo);

    return this.reconcilePaymentList(allPending);
  }

  async reconcilePaymentList(payments: PaymentRecord[]): Promise<ReconciliationReport> {
    const report: ReconciliationReport = {
      totalChecked: payments.length,
      totalMismatched: 0,
      totalReconciled: 0,
      totalFailed: 0,
      totalSkipped: 0,
      results: [],
    };

    for (const payment of payments) {
      try {
        const result = await this.reconcilePayment(payment.id);

        report.results.push(result);

        if (result.internalStatusBefore !== result.providerStatus) {
          report.totalMismatched++;
        }

        if (result.reconciled) {
          report.totalReconciled++;
        } else {
          report.totalSkipped++;
        }
      } catch (error) {
        report.totalFailed++;

        report.results.push({
          paymentId: payment.id,
          tenantId: payment.tenantId,
          provider: payment.provider,
          internalStatusBefore: payment.status,
          providerStatus: PaymentStatus.UNKNOWN,
          internalStatusAfter: payment.status,
          reconciled: false,
          reason: `Reconciliation error: ${(error as Error).message}`,
          shouldSyncSubscription: false,
        });
      }
    }

    this.logger.log(`Reconciliation report: checked ${report.totalChecked}, mismatched ${report.totalMismatched}, reconciled ${report.totalReconciled}, failed ${report.totalFailed}, skipped ${report.totalSkipped}`);

    return report;
  }

  async checkForMismatches(tenantId?: string): Promise<{ mismatches: ReconciliationResult[]; total: number }> {
    const filter: any = {};
    if (tenantId) filter.tenantId = tenantId;

    const payments = await this.paymentRepository.list(filter);
    const mismatches: ReconciliationResult[] = [];

    for (const payment of payments) {
      // Only check payments that are not in final states and are older than 1 minute
      const isFinal = [PaymentStatus.SUCCEEDED, PaymentStatus.REFUNDED, PaymentStatus.CANCELLED, PaymentStatus.EXPIRED].includes(payment.status);
      if (isFinal) continue;

      const ageMinutes = (Date.now() - payment.createdAt.getTime()) / (60 * 1000);
      if (ageMinutes < 1) continue;

      try {
        const provider = this.providerFactory.getProvider(payment.provider);
        const providerResult = await provider.retrievePayment({
          providerPaymentId: payment.providerPaymentId || undefined,
          providerCheckoutId: payment.providerCheckoutId || undefined,
          providerSessionId: payment.providerSessionId || undefined,
          providerInvoiceId: payment.providerInvoiceId || undefined,
        });

        if (providerResult.status !== payment.status) {
          mismatches.push({
            paymentId: payment.id,
            tenantId: payment.tenantId,
            provider: payment.provider,
            internalStatusBefore: payment.status,
            providerStatus: providerResult.status,
            internalStatusAfter: payment.status,
            reconciled: false,
            reason: `Mismatch detected: internal ${payment.status} vs provider ${providerResult.status} (${providerResult.rawProviderStatus})`,
            shouldSyncSubscription: this.shouldSyncSubscriptionForReconciliation(payment.status, providerResult.status),
          });
        }
      } catch (error) {
        this.logger.warn(`Failed to check mismatch for payment ${payment.id}: ${(error as Error).message}`);
      }
    }

    return { mismatches, total: payments.length };
  }

  private shouldSyncSubscriptionForReconciliation(from: PaymentStatus, to: PaymentStatus): boolean {
    // Only sync if transitioning to a meaningful final state
    const syncTransitions = [
      PaymentStatus.SUCCEEDED,
      PaymentStatus.REFUNDED,
      PaymentStatus.PARTIALLY_REFUNDED,
      PaymentStatus.DISPUTED,
    ];

    return syncTransitions.includes(to) && from !== to;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { SubscriptionsService } from '../subscriptions.service';
import { PaymentEventsAuditService } from './payment-events.audit';
import { PaymentStatus } from './payment.types';
import type { PaymentRecord } from './payment.types';
import { SubscriptionStatus, BillingInterval } from '@wlct/shared-types';
import { AppException } from '../../../common/errors/app.exception';
import { ErrorCode } from '@wlct/shared-types';

/**
 * Synchronizes a successful/failed/refunded/cancelled payment into the
 * existing TenantSubscription lifecycle without duplicating subscription logic.
 *
 * This layer must reuse the existing subscription service.
 *
 * Examples:
 *  Payment SUCCEEDED → activate/renew the corresponding TenantSubscription through existing subscription logic.
 *  Payment FAILED → do not incorrectly activate a subscription.
 *  Payment REFUNDED → apply the existing supported refund/subscription business rule.
 *  Payment CANCELLED/EXPIRED → synchronize only if existing subscription semantics require it.
 *
 * Do not create a parallel subscription table/state machine merely for payments.
 */

@Injectable()
export class PaymentSubscriptionSyncService {
  private readonly logger = new Logger(PaymentSubscriptionSyncService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly subscriptionsService: SubscriptionsService,
    private readonly audit: PaymentEventsAuditService,
  ) {}

  async syncPaymentToSubscription(payment: PaymentRecord): Promise<void> {
    this.logger.log(`Syncing payment ${payment.id} status ${payment.status} to subscription for tenant ${payment.tenantId}`);

    switch (payment.status) {
      case PaymentStatus.SUCCEEDED:
        await this.handlePaymentSucceeded(payment);
        break;

      case PaymentStatus.FAILED:
        await this.handlePaymentFailed(payment);
        break;

      case PaymentStatus.CANCELLED:
        await this.handlePaymentCancelled(payment);
        break;

      case PaymentStatus.EXPIRED:
        await this.handlePaymentExpired(payment);
        break;

      case PaymentStatus.REFUNDED:
      case PaymentStatus.PARTIALLY_REFUNDED:
        await this.handlePaymentRefunded(payment);
        break;

      case PaymentStatus.DISPUTED:
        await this.handlePaymentDisputed(payment);
        break;

      case PaymentStatus.PENDING:
      case PaymentStatus.PROCESSING:
      case PaymentStatus.CREATED:
        await this.handlePaymentPending(payment);
        break;

      default:
        this.logger.log(`No subscription sync needed for payment ${payment.id} status ${payment.status}`);
        break;
    }
  }

  private async handlePaymentSucceeded(payment: PaymentRecord): Promise<void> {
    this.logger.log(`Handling payment succeeded: ${payment.id} for tenant ${payment.tenantId}, plan ${payment.planId}`);

    try {
      // Check if subscription already exists for this payment
      const existingSubscription = await this.prisma.tenantSubscription.findFirst({
        where: {
          tenantId: payment.tenantId,
          planId: payment.planId,
        },
        orderBy: { createdAt: 'desc' },
      });

      if (existingSubscription) {
        // If subscription exists and is already active, this is a renewal
        if (existingSubscription.status === SubscriptionStatus.ACTIVE || existingSubscription.status === SubscriptionStatus.TRIALING) {
          await this.renewSubscription(existingSubscription, payment);
        } else if (existingSubscription.status === SubscriptionStatus.PAST_DUE) {
          // Past due subscription - reactivate
          await this.reactivateSubscription(existingSubscription, payment);
        } else if (existingSubscription.status === SubscriptionStatus.CANCELED || existingSubscription.status === SubscriptionStatus.EXPIRED) {
          // Create new subscription for previously cancelled/expired
          await this.createNewSubscription(payment);
        } else {
          // For other statuses, activate
          await this.activateSubscription(existingSubscription, payment);
        }
      } else {
        // No existing subscription - create new one
        await this.createNewSubscription(payment);
      }

      await this.audit.logPaymentEvent({
        tenantId: payment.tenantId,
        paymentId: payment.id,
        provider: payment.provider,
        action: 'SUBSCRIPTION_ACTIVATED',
        status: payment.status,
        planId: payment.planId,
        subscriptionId: payment.subscriptionId || undefined,
        metadata: { syncAction: 'payment_succeeded' },
      });
    } catch (error) {
      this.logger.error(`Failed to sync succeeded payment ${payment.id} to subscription: ${(error as Error).message}`);

      await this.audit.logPaymentEvent({
        tenantId: payment.tenantId,
        paymentId: payment.id,
        provider: payment.provider,
        action: 'SUBSCRIPTION_SYNC_FAILED',
        status: payment.status,
        planId: payment.planId,
        error: (error as Error).message,
        metadata: { syncAction: 'payment_succeeded_failed' },
      });

      throw error;
    }
  }

  private async handlePaymentFailed(payment: PaymentRecord): Promise<void> {
    this.logger.log(`Handling payment failed: ${payment.id} for tenant ${payment.tenantId}`);

    // Failed payment should NOT activate subscription
    // But we should record the failure for audit and potentially notify

    try {
      // If there's an existing subscription in PAST_DUE that was expecting this payment, keep it as PAST_DUE
      // Don't create new subscription for failed payment

      const existingSubscription = await this.prisma.tenantSubscription.findFirst({
        where: {
          tenantId: payment.tenantId,
          status: { in: [SubscriptionStatus.PAST_DUE, SubscriptionStatus.TRIALING] },
        },
        orderBy: { createdAt: 'desc' },
      });

      if (existingSubscription && existingSubscription.status === SubscriptionStatus.TRIALING) {
        // If trial subscription and payment failed, we might want to keep trial or mark as past_due
        // For now, we don't change trial status on payment failure - trial continues until ends
        this.logger.log(`Payment failed for trial subscription ${existingSubscription.id}, keeping trial active`);
      }

      await this.audit.logPaymentEvent({
        tenantId: payment.tenantId,
        paymentId: payment.id,
        provider: payment.provider,
        action: 'SUBSCRIPTION_SYNC_SKIPPED',
        status: payment.status,
        planId: payment.planId,
        metadata: { syncAction: 'payment_failed_no_activation', reason: 'failed_payment_does_not_activate' },
      });
    } catch (error) {
      this.logger.error(`Failed to handle failed payment ${payment.id}: ${(error as Error).message}`);
    }
  }

  private async handlePaymentCancelled(payment: PaymentRecord): Promise<void> {
    this.logger.log(`Handling payment cancelled: ${payment.id} for tenant ${payment.tenantId}`);

    // Cancelled payment - only sync if subscription semantics require it
    // For example, if subscription was created pending payment and payment cancelled, cancel subscription

    try {
      const existingSubscription = await this.prisma.tenantSubscription.findFirst({
        where: {
          tenantId: payment.tenantId,
          planId: payment.planId,
          status: { in: [SubscriptionStatus.TRIALING] },
        },
        orderBy: { createdAt: 'desc' },
      });

      // Only cancel if subscription was in trial and payment was for initial purchase
      // Don't cancel active subscriptions on cancelled payment
      if (existingSubscription && existingSubscription.status === SubscriptionStatus.TRIALING) {
        const trialAge = Date.now() - existingSubscription.currentPeriodStart.getTime();
        const oneHour = 60 * 60 * 1000;

        if (trialAge < oneHour) {
          // Very new trial - likely created for this payment, cancel it
          await this.prisma.tenantSubscription.update({
            where: { id: existingSubscription.id },
            data: {
              status: SubscriptionStatus.CANCELED,
              canceledAt: new Date(),
              cancelReason: 'Payment cancelled',
            },
          });

          this.logger.log(`Cancelled trial subscription ${existingSubscription.id} due to payment cancellation`);
        }
      }

      await this.audit.logPaymentEvent({
        tenantId: payment.tenantId,
        paymentId: payment.id,
        provider: payment.provider,
        action: 'SUBSCRIPTION_SYNC_SKIPPED',
        status: payment.status,
        planId: payment.planId,
        metadata: { syncAction: 'payment_cancelled' },
      });
    } catch (error) {
      this.logger.error(`Failed to handle cancelled payment ${payment.id}: ${(error as Error).message}`);
    }
  }

  private async handlePaymentExpired(payment: PaymentRecord): Promise<void> {
    this.logger.log(`Handling payment expired: ${payment.id} for tenant ${payment.tenantId}`);

    // Expired payment - similar to cancelled, only sync if needed
    await this.audit.logPaymentEvent({
      tenantId: payment.tenantId,
      paymentId: payment.id,
      provider: payment.provider,
      action: 'SUBSCRIPTION_SYNC_SKIPPED',
      status: payment.status,
      planId: payment.planId,
      metadata: { syncAction: 'payment_expired' },
    });
  }

  private async handlePaymentRefunded(payment: PaymentRecord): Promise<void> {
    this.logger.log(`Handling payment refunded: ${payment.id} for tenant ${payment.tenantId}, status ${payment.status}`);

    try {
      // Refunded payment - apply existing refund/subscription business rule
      // For full refund, we might want to cancel or pause subscription
      // For partial refund, we keep subscription active

      const isFullRefund = payment.status === PaymentStatus.REFUNDED;
      const isPartialRefund = payment.status === PaymentStatus.PARTIALLY_REFUNDED;

      if (isFullRefund) {
        // Find active subscription for this tenant/plan
        const activeSubscription = await this.prisma.tenantSubscription.findFirst({
          where: {
            tenantId: payment.tenantId,
            planId: payment.planId,
            status: { in: [SubscriptionStatus.ACTIVE, SubscriptionStatus.TRIALING, SubscriptionStatus.PAST_DUE] },
          },
          orderBy: { createdAt: 'desc' },
        });

        if (activeSubscription) {
          // Business rule: full refund within 7 days cancels subscription
          // After 7 days, refund but keep subscription until period end
          const subscriptionAge = Date.now() - activeSubscription.currentPeriodStart.getTime();
          const sevenDays = 7 * 24 * 60 * 60 * 1000;

          if (subscriptionAge < sevenDays) {
            await this.prisma.tenantSubscription.update({
              where: { id: activeSubscription.id },
              data: {
                status: SubscriptionStatus.CANCELED,
                canceledAt: new Date(),
                cancelReason: 'Payment refunded',
              },
            });

            this.logger.log(`Cancelled subscription ${activeSubscription.id} due to full refund within 7 days`);
          } else {
            // Keep subscription but mark to cancel at period end
            await this.prisma.tenantSubscription.update({
              where: { id: activeSubscription.id },
              data: {
                cancelAtPeriodEnd: true,
                cancelReason: 'Payment refunded - will cancel at period end',
              },
            });

            this.logger.log(`Marked subscription ${activeSubscription.id} to cancel at period end due to refund`);
          }
        }
      } else if (isPartialRefund) {
        // Partial refund - keep subscription active, just audit
        this.logger.log(`Partial refund for payment ${payment.id}, keeping subscription active`);
      }

      await this.audit.logPaymentEvent({
        tenantId: payment.tenantId,
        paymentId: payment.id,
        provider: payment.provider,
        action: 'SUBSCRIPTION_REFUNDED',
        status: payment.status,
        planId: payment.planId,
        metadata: { syncAction: isFullRefund ? 'full_refund' : 'partial_refund' },
      });
    } catch (error) {
      this.logger.error(`Failed to handle refunded payment ${payment.id}: ${(error as Error).message}`);
      throw error;
    }
  }

  private async handlePaymentDisputed(payment: PaymentRecord): Promise<void> {
    this.logger.log(`Handling payment disputed: ${payment.id} for tenant ${payment.tenantId}`);

    try {
      // Disputed payment - typically pause subscription and require review
      const activeSubscription = await this.prisma.tenantSubscription.findFirst({
        where: {
          tenantId: payment.tenantId,
          planId: payment.planId,
          status: { in: [SubscriptionStatus.ACTIVE, SubscriptionStatus.TRIALING] },
        },
        orderBy: { createdAt: 'desc' },
      });

      if (activeSubscription) {
        await this.prisma.tenantSubscription.update({
          where: { id: activeSubscription.id },
          data: {
            status: SubscriptionStatus.PAUSED,
            metadata: {
              ...((activeSubscription.metadata as any) || {}),
              disputePaymentId: payment.id,
              disputedAt: new Date().toISOString(),
            },
          },
        });

        this.logger.log(`Paused subscription ${activeSubscription.id} due to payment dispute`);
      }

      await this.audit.logPaymentEvent({
        tenantId: payment.tenantId,
        paymentId: payment.id,
        provider: payment.provider,
        action: 'SUBSCRIPTION_PAUSED',
        status: payment.status,
        planId: payment.planId,
        metadata: { syncAction: 'payment_disputed' },
      });
    } catch (error) {
      this.logger.error(`Failed to handle disputed payment ${payment.id}: ${(error as Error).message}`);
    }
  }

  private async handlePaymentPending(payment: PaymentRecord): Promise<void> {
    this.logger.log(`Handling payment pending/processing: ${payment.id} status ${payment.status}`);

    // Pending payment - no subscription change yet, just audit
    await this.audit.logPaymentEvent({
      tenantId: payment.tenantId,
      paymentId: payment.id,
      provider: payment.provider,
      action: 'PAYMENT_PENDING',
      status: payment.status,
      planId: payment.planId,
      metadata: { syncAction: 'payment_pending' },
    });
  }

  private async createNewSubscription(payment: PaymentRecord): Promise<void> {
    const plan = await this.prisma.subscriptionPlan.findUnique({
      where: { id: payment.planId },
    });

    if (!plan) {
      throw new AppException({
        code: ErrorCode.NOT_FOUND,
        message: `Plan not found: ${payment.planId}`,
      });
    }

    const now = new Date();
    const periodEnd = this.calculatePeriodEnd(now, plan.interval as BillingInterval);

    // Reuse existing subscription service logic via direct prisma create
    // This mirrors what SubscriptionsService.assign does but with payment context
    const subscription = await this.prisma.tenantSubscription.create({
      data: {
        tenantId: payment.tenantId,
        planId: payment.planId,
        status: plan.trialDays > 0 ? SubscriptionStatus.TRIALING : SubscriptionStatus.ACTIVE,
        currentPeriodStart: now,
        currentPeriodEnd: periodEnd,
        trialEndsAt: plan.trialDays > 0 ? new Date(now.getTime() + plan.trialDays * 24 * 60 * 60 * 1000) : null,
        seatsPurchased: payment.seats || 1,
        externalCustomerId: payment.externalCustomerId || payment.providerCustomerId || null,
        externalSubscriptionId: payment.externalSubscriptionId || null,
        metadata: {
          paymentId: payment.id,
          provider: payment.provider,
          providerPaymentId: payment.providerPaymentId,
          createdFromPayment: true,
        },
      },
    });

    // Apply plan limits to tenant (same as SubscriptionsService does)
    await this.prisma.tenant.update({
      where: { id: payment.tenantId },
      data: {
        maxUsers: (plan.limits as any)?.maxUsers ?? null,
        maxTraders: (plan.limits as any)?.maxTraders ?? null,
      },
    });

    this.logger.log(`Created new subscription ${subscription.id} for tenant ${payment.tenantId} from payment ${payment.id}`);

    // Update payment with subscription ID
    try {
      await (this.prisma as any).payment?.update({
        where: { id: payment.id },
        data: { subscriptionId: subscription.id },
      });
    } catch {}
  }

  private async renewSubscription(existingSubscription: any, payment: PaymentRecord): Promise<void> {
    const now = new Date();
    const plan = await this.prisma.subscriptionPlan.findUnique({
      where: { id: payment.planId },
    });

    if (!plan) {
      throw new AppException({ code: ErrorCode.NOT_FOUND, message: `Plan not found: ${payment.planId}` });
    }

    const periodEnd = this.calculatePeriodEnd(now, plan.interval as BillingInterval);

    await this.prisma.tenantSubscription.update({
      where: { id: existingSubscription.id },
      data: {
        status: SubscriptionStatus.ACTIVE,
        currentPeriodStart: now,
        currentPeriodEnd: periodEnd,
        metadata: {
          ...((existingSubscription.metadata as any) || {}),
          lastRenewalPaymentId: payment.id,
          renewedAt: now.toISOString(),
        },
      },
    });

    this.logger.log(`Renewed subscription ${existingSubscription.id} for tenant ${payment.tenantId}`);
  }

  private async reactivateSubscription(existingSubscription: any, payment: PaymentRecord): Promise<void> {
    const now = new Date();
    const plan = await this.prisma.subscriptionPlan.findUnique({
      where: { id: payment.planId },
    });

    if (!plan) {
      throw new AppException({ code: ErrorCode.NOT_FOUND, message: `Plan not found: ${payment.planId}` });
    }

    const periodEnd = this.calculatePeriodEnd(now, plan.interval as BillingInterval);

    await this.prisma.tenantSubscription.update({
      where: { id: existingSubscription.id },
      data: {
        status: SubscriptionStatus.ACTIVE,
        currentPeriodStart: now,
        currentPeriodEnd: periodEnd,
        metadata: {
          ...((existingSubscription.metadata as any) || {}),
          reactivatedPaymentId: payment.id,
          reactivatedAt: now.toISOString(),
        },
      },
    });

    this.logger.log(`Reactivated past_due subscription ${existingSubscription.id} for tenant ${payment.tenantId}`);
  }

  private async activateSubscription(existingSubscription: any, payment: PaymentRecord): Promise<void> {
    await this.prisma.tenantSubscription.update({
      where: { id: existingSubscription.id },
      data: {
        status: SubscriptionStatus.ACTIVE,
        metadata: {
          ...((existingSubscription.metadata as any) || {}),
          activatedPaymentId: payment.id,
          activatedAt: new Date().toISOString(),
        },
      },
    });

    this.logger.log(`Activated subscription ${existingSubscription.id} for tenant ${payment.tenantId}`);
  }

  private calculatePeriodEnd(from: Date, interval: BillingInterval): Date {
    const end = new Date(from);

    switch (interval) {
      case BillingInterval.MONTHLY:
        end.setMonth(end.getMonth() + 1);
        break;
      case BillingInterval.QUARTERLY:
        end.setMonth(end.getMonth() + 3);
        break;
      case BillingInterval.YEARLY:
        end.setFullYear(end.getFullYear() + 1);
        break;
      case BillingInterval.LIFETIME:
        end.setFullYear(end.getFullYear() + 100);
        break;
      default:
        end.setMonth(end.getMonth() + 1);
        break;
    }

    return end;
  }
}

// # Responsibility: validate and expose payment-provider runtime configuration without leaking secrets.
import { Injectable } from '@nestjs/common';
import { AppConfigService } from '../../../config/app-config.service';
import { PaymentProvider } from './payment.types';

export const STRIPE_API_VERSION = '2023-10-16';

/**
 * Validated runtime payment configuration.
 *
 * This service provides safe access to payment provider configuration without
 * exposing secrets through logs or API responses. Secrets are accessed only
 * when needed for provider SDK initialization or webhook verification.
 *
 * Configuration sources:
 *  - BILLING_PROVIDER: none | stripe | nowpayments
 *  - STRIPE_SECRET_KEY, STRIPE_WEBHOOK_SECRET
 *  - NOWPAYMENTS_API_KEY, NOWPAYMENTS_IPN_SECRET
 *  - Public settings: success/cancel URLs, timeouts, currency defaults
 */

export interface PaymentProviderConfig {
  provider: PaymentProvider;
  enabled: boolean;
  stripe?: StripeConfig;
  nowpayments?: NowPaymentsConfig;
  checkout: CheckoutConfig;
  webhook: WebhookConfig;
  retry: RetryConfig;
}

export interface StripeConfig {
  secretKey: string;
  webhookSecret: string;
  apiVersion: typeof STRIPE_API_VERSION;
  maxNetworkRetries: number;
  timeoutMs: number;
}

export interface NowPaymentsConfig {
  apiKey: string;
  ipnSecret: string;
  apiBaseUrl: string;
  webhookBaseUrl?: string;
  timeoutMs: number;
}

export interface CheckoutConfig {
  successUrl: string;
  cancelUrl: string;
  defaultCurrency: string;
  expirationMinutes: number;
  idempotencyTtlSeconds: number;
}

export interface WebhookConfig {
  enabled: boolean;
  toleranceSeconds: number;
  replayWindowSeconds: number;
  maxRetries: number;
  retryDelayMs: number;
}

export interface RetryConfig {
  maxAttempts: number;
  initialDelayMs: number;
  maxDelayMs: number;
  backoffMultiplier: number;
  timeoutMs: number;
}

@Injectable()
export class PaymentConfigService {
  private readonly config: PaymentProviderConfig;

  constructor(private readonly appConfig: AppConfigService) {
    this.config = this.buildConfig();
  }

  get provider(): PaymentProvider {
    return this.config.provider;
  }

  get isEnabled(): boolean {
    return this.config.enabled;
  }

  get checkout(): CheckoutConfig {
    return this.config.checkout;
  }

  get webhook(): WebhookConfig {
    return this.config.webhook;
  }

  get retry(): RetryConfig {
    return this.config.retry;
  }

  get stripe(): StripeConfig | undefined {
    return this.config.stripe;
  }

  get nowpayments(): NowPaymentsConfig | undefined {
    return this.config.nowpayments;
  }

  getProviderConfig(): PaymentProviderConfig {
    // Return safe copy without secrets for logging/diagnostics
    return {
      provider: this.config.provider,
      enabled: this.config.enabled,
      checkout: this.config.checkout,
      webhook: this.config.webhook,
      retry: this.config.retry,
      stripe: this.config.stripe
        ? {
            secretKey: this.redactSecret(this.config.stripe.secretKey),
            webhookSecret: this.redactSecret(this.config.stripe.webhookSecret),
            apiVersion: this.config.stripe.apiVersion,
            maxNetworkRetries: this.config.stripe.maxNetworkRetries,
            timeoutMs: this.config.stripe.timeoutMs,
          }
        : undefined,
      nowpayments: this.config.nowpayments
        ? {
            apiKey: this.redactSecret(this.config.nowpayments.apiKey),
            ipnSecret: this.redactSecret(this.config.nowpayments.ipnSecret),
            apiBaseUrl: this.config.nowpayments.apiBaseUrl,
            webhookBaseUrl: this.config.nowpayments.webhookBaseUrl,
            timeoutMs: this.config.nowpayments.timeoutMs,
          }
        : undefined,
    };
  }

  isProviderEnabled(provider: PaymentProvider): boolean {
    if (provider === PaymentProvider.NONE) {
      return false;
    }
    if (this.config.provider === PaymentProvider.NONE) {
      return false;
    }
    if (provider === PaymentProvider.STRIPE) {
      return !!this.config.stripe?.secretKey && !!this.config.stripe?.webhookSecret;
    }
    if (provider === PaymentProvider.NOWPAYMENTS) {
      return !!this.config.nowpayments?.apiKey;
    }
    return false;
  }

  getStripeSecretKey(): string {
    const key = this.config.stripe?.secretKey;
    if (!key) {
      throw new Error('Stripe secret key not configured');
    }
    return key;
  }

  getStripeWebhookSecret(): string {
    const secret = this.config.stripe?.webhookSecret;
    if (!secret) {
      throw new Error('Stripe webhook secret not configured');
    }
    return secret;
  }

  getNowPaymentsApiKey(): string {
    const key = this.config.nowpayments?.apiKey;
    if (!key) {
      throw new Error('NowPayments API key not configured');
    }
    return key;
  }

  getNowPaymentsIpnSecret(): string | undefined {
    return this.config.nowpayments?.ipnSecret;
  }

  private buildConfig(): PaymentProviderConfig {
    const providerRaw = this.appConfig.billingProvider as string;
    const provider = this.parseProvider(providerRaw);

    const stripeSecretKey = process.env.STRIPE_SECRET_KEY || '';
    const stripeWebhookSecret = process.env.STRIPE_WEBHOOK_SECRET || '';
    const nowpaymentsApiKey = process.env.NOWPAYMENTS_API_KEY || '';
    const nowpaymentsIpnSecret = process.env.NOWPAYMENTS_IPN_SECRET || '';

    const publicUrl = this.appConfig.publicUrl || 'http://localhost:4000';
    const adminWebUrl = this.appConfig.adminWebUrl || 'http://localhost:3000';

    const config: PaymentProviderConfig = {
      provider,
      enabled: provider !== PaymentProvider.NONE,
      checkout: {
        successUrl: `${adminWebUrl}/billing/success?session_id={CHECKOUT_SESSION_ID}`,
        cancelUrl: `${adminWebUrl}/billing/cancel`,
        defaultCurrency: 'USD',
        expirationMinutes: 60,
        idempotencyTtlSeconds: 24 * 60 * 60,
      },
      webhook: {
        enabled: true,
        toleranceSeconds: 300,
        replayWindowSeconds: 24 * 60 * 60,
        maxRetries: 3,
        retryDelayMs: 1000,
      },
      retry: {
        maxAttempts: 3,
        initialDelayMs: 1000,
        maxDelayMs: 10000,
        backoffMultiplier: 2,
        timeoutMs: 30000,
      },
    };

    if (stripeSecretKey) {
      config.stripe = {
        secretKey: stripeSecretKey,
        webhookSecret: stripeWebhookSecret,
        apiVersion: STRIPE_API_VERSION,
        maxNetworkRetries: 2,
        timeoutMs: 30000,
      };
    }

    if (nowpaymentsApiKey) {
      config.nowpayments = {
        apiKey: nowpaymentsApiKey,
        ipnSecret: nowpaymentsIpnSecret,
        apiBaseUrl: 'https://api.nowpayments.io/v1',
        timeoutMs: 30000,
      };
    }

    return config;
  }

  private parseProvider(raw: string): PaymentProvider {
    switch (raw?.toLowerCase()) {
      case 'stripe':
        return PaymentProvider.STRIPE;
      case 'nowpayments':
        return PaymentProvider.NOWPAYMENTS;
      case 'none':
      case '':
      case undefined:
        return PaymentProvider.NONE;
      default:
        return PaymentProvider.NONE;
    }
  }

  private redactSecret(secret: string): string {
    if (!secret || secret.length < 8) {
      return '***';
    }
    return `${secret.substring(0, 4)}***${secret.substring(secret.length - 4)}`;
  }
}

// # Responsibility: persist payment records and provider metadata through the repository boundary.
import { Injectable, Logger, Optional } from '@nestjs/common';
import { randomUUID } from 'node:crypto';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { OutboxService } from '../../../infrastructure/outbox/outbox.service';
import type { PaymentRecord, PaymentFilter, PaymentCreationInput, PaymentUpdateInput } from './payment.types';
import { PaymentProvider, PaymentStatus } from './payment.types';
import { AppException } from '../../../common/errors/app.exception';
import { ErrorCode } from '@wlct/shared-types';

/**
 * The Payment model has columns for the provider ids, status, amount and
 * timestamps only. The rest of a PaymentRecord is persisted in its JSON
 * columns: provider links in `providerReference`, record fields in
 * `metadata._payment` (stripped again when reading, so callers see their own
 * metadata unchanged). Writing those fields as columns made Prisma reject
 * every payment create/update.
 */
export const PAYMENT_RECORD_METADATA_KEY = '_payment';

export interface PaymentRecordExtras {
  userId?: string | null;
  transactionState?: string | null;
  amountInSmallestUnit?: number | null;
  externalCustomerId?: string | null;
  externalSubscriptionId?: string | null;
  paymentMethod?: string | null;
  planCode?: string | null;
  planName?: string | null;
  billingInterval?: string | null;
  seats?: number | null;
  rawProviderStatus?: string | null;
  expiresAt?: string | null;
}

export interface PaymentProviderLinks {
  providerCustomerId?: string | null;
  checkoutUrl?: string | null;
  invoiceUrl?: string | null;
}

function asObject(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' && !Array.isArray(value) ? { ...(value as Record<string, unknown>) } : {};
}

function isoOrNull(value: Date | string | null | undefined): string | null | undefined {
  if (value === undefined) return undefined;
  if (value === null) return null;
  return value instanceof Date ? value.toISOString() : String(value);
}

/**
 * Metadata JSON for a write: caller metadata (replacing the stored caller
 * metadata when given) plus the stored record fields merged with `extras`.
 */
export function buildPaymentMetadata(
  existing: unknown,
  userMetadata: Record<string, unknown> | null | undefined,
  extras: PaymentRecordExtras,
): Record<string, unknown> {
  const current = asObject(existing);
  const stored = asObject(current[PAYMENT_RECORD_METADATA_KEY]);
  const user = userMetadata ? asObject(userMetadata) : current;
  delete user[PAYMENT_RECORD_METADATA_KEY];
  for (const [key, value] of Object.entries(extras)) {
    if (value !== undefined) stored[key] = value;
  }
  return { ...user, [PAYMENT_RECORD_METADATA_KEY]: stored };
}

/** providerReference JSON for a write; only non-empty links overwrite stored ones. */
export function buildProviderReference(existing: unknown, links: PaymentProviderLinks): Record<string, unknown> {
  const merged = asObject(existing);
  for (const [key, value] of Object.entries(links)) {
    if (value !== undefined && value !== null && value !== '') merged[key] = value;
  }
  return merged;
}

/**
 * Persistence abstraction for internal payment records.
 *
 * Handles:
 *  - Payment records with provider references
 *  - Status transitions with validation
 *  - Idempotency keys for checkout creation
 *  - Checkout references
 *  - Tenant/subscription associations
 *  - Webhook event tracking for replay protection
 *
 * Note: This repository expects Payment and WebhookEvent models in Prisma.
 * If they don't exist yet, it will use raw queries or fallback to in-memory
 * tracking with Redis. The implementation is defensive to handle both cases.
 */

@Injectable()
export class PaymentRepository {
  private readonly logger = new Logger(PaymentRepository.name);

  constructor(
    private readonly prisma: PrismaService,
    @Optional() private readonly outbox?: OutboxService,
  ) {}

  async create(input: PaymentCreationInput): Promise<PaymentRecord> {
    try {
      // Try to use Payment model if exists in Prisma schema
      const payment = await (this.prisma as any).payment?.create({
        data: {
          id: this.generateId(),
          tenantId: input.tenantId,
          planId: input.planId,
          subscriptionId: input.subscriptionId || null,
          provider: input.provider,
          status: 'CREATED',
          currency: input.currency,
          amount: input.amount.amount,
          providerPaymentId: input.providerReference?.providerPaymentId || null,
          providerCheckoutId: input.providerReference?.providerCheckoutId || null,
          providerSessionId: input.providerReference?.providerSessionId || null,
          providerInvoiceId: input.providerReference?.providerInvoiceId || null,
          providerReference: buildProviderReference(null, {
            providerCustomerId: input.providerReference?.providerCustomerId || null,
            checkoutUrl: input.providerReference?.checkoutUrl || null,
            invoiceUrl: input.providerReference?.invoiceUrl || null,
          }) as any,
          idempotencyKey: input.idempotencyKey,
          orderId: input.references.orderId || null,
          metadata: buildPaymentMetadata(null, input.metadata as any, {
            userId: input.references.userId || null,
            transactionState: 'INITIALIZED',
            amountInSmallestUnit: input.amount.amountInSmallestUnit,
            externalCustomerId: input.references.externalCustomerId || null,
            externalSubscriptionId: input.references.externalSubscriptionId || null,
            planCode: input.metadata.planCode || null,
            planName: input.metadata.planName || null,
            billingInterval: input.metadata.billingInterval || null,
            seats: input.metadata.seats || null,
            expiresAt: isoOrNull(input.expiresAt || null),
          }) as any,
        },
      });

      if (payment) {
        return this.mapToPaymentRecord(payment);
      }

      // No Payment delegate means the generated client does not match the
      // schema. Refuse: returning an unpersisted record would let a checkout
      // proceed with a payment the webhook can never find.
      this.logger.error('Payment model unavailable on the Prisma client; refusing to create an unpersisted payment');
      throw new AppException({
        code: ErrorCode.INTERNAL_SERVER_ERROR,
        message: 'Payment storage is unavailable',
      });
    } catch (error) {
      if (error instanceof AppException) throw error;
      this.logger.error(`Failed to create payment record: ${(error as Error).message}`);
      // A missing table (P2021, migrations not applied) is a deployment error
      // and fails like any other storage error - never an in-memory stand-in.
      throw new AppException({
        code: ErrorCode.INTERNAL_SERVER_ERROR,
        message: 'Failed to create payment record',
      });
    }
  }

  async findById(id: string): Promise<PaymentRecord | null> {
    const payment = await (this.prisma as any).payment?.findUnique({
      where: { id },
    });
    if (payment) {
      return this.mapToPaymentRecord(payment);
    }
    return null;
  }

  async findByIdempotencyKey(idempotencyKey: string, tenantId: string): Promise<PaymentRecord | null> {
    const payment = await (this.prisma as any).payment?.findFirst({
      where: { idempotencyKey, tenantId },
      orderBy: { createdAt: 'desc' },
    });
    if (payment) {
      return this.mapToPaymentRecord(payment);
    }
    return null;
  }

  async findByProviderPaymentId(providerPaymentId: string, provider: PaymentProvider): Promise<PaymentRecord | null> {
    const payment = await (this.prisma as any).payment?.findFirst({
      where: { providerPaymentId, provider },
    });
    if (payment) {
      return this.mapToPaymentRecord(payment);
    }
    return null;
  }

  async findByProviderCheckoutId(providerCheckoutId: string, provider: PaymentProvider): Promise<PaymentRecord | null> {
    const payment = await (this.prisma as any).payment?.findFirst({
      where: { providerCheckoutId, provider },
    });
    if (payment) {
      return this.mapToPaymentRecord(payment);
    }
    return null;
  }

  async findByOrderId(orderId: string): Promise<PaymentRecord | null> {
    const payment = await (this.prisma as any).payment?.findFirst({
      where: { orderId },
    });
    if (payment) {
      return this.mapToPaymentRecord(payment);
    }
    return null;
  }

  async list(filter: PaymentFilter): Promise<PaymentRecord[]> {
    const where: any = {};

    if (filter.tenantId) where.tenantId = filter.tenantId;
    if (filter.planId) where.planId = filter.planId;
    if (filter.subscriptionId) where.subscriptionId = filter.subscriptionId;
    if (filter.provider) where.provider = filter.provider;
    if (filter.status) where.status = filter.status;
    if (filter.currency) where.currency = filter.currency;
    if (filter.orderId) where.orderId = filter.orderId;
    if (filter.idempotencyKey) where.idempotencyKey = filter.idempotencyKey;
    if (filter.providerPaymentId) where.providerPaymentId = filter.providerPaymentId;

    if (filter.fromDate || filter.toDate) {
      where.createdAt = {};
      if (filter.fromDate) where.createdAt.gte = filter.fromDate;
      if (filter.toDate) where.createdAt.lte = filter.toDate;
    }

    const payments = await (this.prisma as any).payment?.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: 100,
    });

    if (payments) {
      return payments.map((p: any) => this.mapToPaymentRecord(p));
    }
    return [];
  }

  async update(id: string, input: PaymentUpdateInput, tenantId?: string): Promise<PaymentRecord> {
    try {
      const owner = tenantId
        ? { tenantId }
        : await (this.prisma as any).payment?.findUnique({ where: { id }, select: { tenantId: true } });
      if (!owner?.tenantId) throw new AppException({ code: ErrorCode.NOT_FOUND, message: 'Payment not found' });

      return await this.prisma.withTenantRls(owner.tenantId, async (tx) => {
        const paymentStore = tx as any;
        const existing = await paymentStore.payment.findFirst({ where: { id, tenantId: owner.tenantId } });
        if (!existing) throw new AppException({ code: ErrorCode.NOT_FOUND, message: 'Payment not found' });

        const updateData: any = {};
        if (input.status) updateData.status = input.status;
        if (input.paidAt !== undefined) updateData.paidAt = input.paidAt;
        if (input.failedAt !== undefined) updateData.failedAt = input.failedAt;
        if (input.cancelledAt !== undefined) updateData.cancelledAt = input.cancelledAt;
        if (input.refundedAt !== undefined) updateData.refundedAt = input.refundedAt;
        if (input.failureReason !== undefined) updateData.failureReason = input.failureReason;
        if (input.failureCode !== undefined) updateData.failureCode = input.failureCode;

        const links: PaymentProviderLinks = {};
        if (input.providerReference) {
          if (input.providerReference.providerPaymentId) updateData.providerPaymentId = input.providerReference.providerPaymentId;
          if (input.providerReference.providerCheckoutId) updateData.providerCheckoutId = input.providerReference.providerCheckoutId;
          if (input.providerReference.providerSessionId) updateData.providerSessionId = input.providerReference.providerSessionId;
          if (input.providerReference.providerInvoiceId) updateData.providerInvoiceId = input.providerReference.providerInvoiceId;
          if (input.providerReference.providerCustomerId) links.providerCustomerId = input.providerReference.providerCustomerId;
          if (input.providerReference.checkoutUrl) links.checkoutUrl = input.providerReference.checkoutUrl;
          if (input.providerReference.invoiceUrl) links.invoiceUrl = input.providerReference.invoiceUrl;
        }

        const extras: PaymentRecordExtras = {};
        if (input.transactionState) extras.transactionState = input.transactionState;
        if (input.rawProviderStatus !== undefined) extras.rawProviderStatus = input.rawProviderStatus;

        const touchesJson = Object.keys(links).length > 0 || Object.keys(extras).length > 0 || Boolean(input.metadata);
        if (touchesJson) {
          if (Object.keys(links).length > 0) {
            updateData.providerReference = buildProviderReference(existing.providerReference, links);
          }
          updateData.metadata = buildPaymentMetadata(existing.metadata, (input.metadata as any) ?? null, extras);
        }

        const payment = await paymentStore.payment.update({ where: { id }, data: updateData });
        const eventType =
          input.status === PaymentStatus.SUCCEEDED && existing.status !== PaymentStatus.SUCCEEDED
            ? 'payment.succeeded'
            : input.status === PaymentStatus.FAILED && existing.status !== PaymentStatus.FAILED
              ? 'payment.failed'
              : null;

        if (eventType) {
          if (!this.outbox) {
            throw new Error('Transactional outbox is unavailable; refusing payment transition without its webhook event');
          }
          const amount = typeof payment.amount === 'string' ? payment.amount : String(payment.amount);
          const correlationId = typeof payment.orderId === 'string' && payment.orderId.length <= 64 ? payment.orderId : payment.id;
          await this.outbox.append(tx, {
            tenantId: payment.tenantId,
            aggregateType: 'payment',
            aggregateId: payment.id,
            eventType,
            idempotencyKey: `payment:${payment.id}:${eventType}`,
            correlationId,
            occurredAt: payment.updatedAt,
            payload: {
              paymentId: payment.id,
              amount,
              currency: payment.currency,
              status: payment.status,
            },
          });
        }

        return this.mapToPaymentRecord(payment);
      });
    } catch (error) {
      if (error instanceof AppException) throw error;
      this.logger.error(`Failed to update payment ${id}: ${(error as Error).message}`);
      throw new AppException({
        code: ErrorCode.INTERNAL_SERVER_ERROR,
        message: 'Failed to update payment record',
      });
    }
  }

  async updateStatus(id: string, status: PaymentStatus, additionalData?: Partial<PaymentUpdateInput>, tenantId?: string): Promise<PaymentRecord> {
    const updateInput: PaymentUpdateInput = {
      status,
      ...additionalData,
    };

    // Set timestamp based on status
    const now = new Date();
    if (status === 'SUCCEEDED' as any) {
      updateInput.paidAt = now;
    } else if (status === 'FAILED' as any) {
      updateInput.failedAt = now;
    } else if (status === 'CANCELLED' as any) {
      updateInput.cancelledAt = now;
    } else if (status === 'REFUNDED' as any) {
      updateInput.refundedAt = now;
    }

    return this.update(id, updateInput, tenantId);
  }

  async findLatestByTenantAndPlan(tenantId: string, planId: string): Promise<PaymentRecord | null> {
    const payment = await (this.prisma as any).payment?.findFirst({
      where: { tenantId, planId },
      orderBy: { createdAt: 'desc' },
    });
    if (payment) {
      return this.mapToPaymentRecord(payment);
    }
    return null;
  }

  async countByTenant(tenantId: string): Promise<number> {
    const count = await (this.prisma as any).payment?.count({
      where: { tenantId },
    });
    return count || 0;
  }

  private mapToPaymentRecord(prismaPayment: any): PaymentRecord {
    const metadata = asObject(prismaPayment.metadata);
    const extras = asObject(metadata[PAYMENT_RECORD_METADATA_KEY]);
    delete metadata[PAYMENT_RECORD_METADATA_KEY];
    const links = asObject(prismaPayment.providerReference);
    const text = (value: unknown): string | null => (typeof value === 'string' && value !== '' ? value : null);
    return {
      id: prismaPayment.id,
      tenantId: prismaPayment.tenantId,
      planId: prismaPayment.planId,
      subscriptionId: prismaPayment.subscriptionId || null,
      userId: text(extras.userId) as any,
      provider: prismaPayment.provider as PaymentProvider,
      status: prismaPayment.status as any,
      transactionState: (text(extras.transactionState) ?? 'INITIALIZED') as any,
      currency: prismaPayment.currency,
      amount: prismaPayment.amount,
      amountInSmallestUnit: typeof extras.amountInSmallestUnit === 'number' ? extras.amountInSmallestUnit : 0,
      providerPaymentId: prismaPayment.providerPaymentId || null,
      providerCheckoutId: prismaPayment.providerCheckoutId || null,
      providerSessionId: prismaPayment.providerSessionId || null,
      providerInvoiceId: prismaPayment.providerInvoiceId || null,
      providerCustomerId: text(links.providerCustomerId),
      checkoutUrl: text(links.checkoutUrl),
      invoiceUrl: text(links.invoiceUrl),
      idempotencyKey: prismaPayment.idempotencyKey,
      orderId: prismaPayment.orderId || null,
      externalCustomerId: text(extras.externalCustomerId),
      externalSubscriptionId: text(extras.externalSubscriptionId),
      paymentMethod: text(extras.paymentMethod) as any,
      planCode: text(extras.planCode),
      planName: text(extras.planName),
      billingInterval: text(extras.billingInterval) as any,
      seats: typeof extras.seats === 'number' ? extras.seats : null,
      failureReason: prismaPayment.failureReason || null,
      failureCode: prismaPayment.failureCode || null,
      rawProviderStatus: text(extras.rawProviderStatus),
      metadata: prismaPayment.metadata ? metadata : null,
      paidAt: prismaPayment.paidAt || null,
      failedAt: prismaPayment.failedAt || null,
      cancelledAt: prismaPayment.cancelledAt || null,
      refundedAt: prismaPayment.refundedAt || null,
      expiresAt: text(extras.expiresAt) ? new Date(extras.expiresAt as string) : null,
      createdAt: prismaPayment.createdAt,
      updatedAt: prismaPayment.updatedAt,
    };
  }

  private generateId(): string {
    // Use crypto random UUID
    try {
      return randomUUID();
    } catch {
      return `${Date.now()}-${Math.random().toString(36).substring(2, 15)}`;
    }
  }
}

// # Responsibility: create Stripe payment sessions, retrieve provider state, and verify callbacks without exposing secrets.
import { Injectable, Logger } from '@nestjs/common';
import { PaymentProvider, PaymentStatus, TransactionState, PaymentMethodType } from './payment.types';
import type {
  IPaymentProvider,
  CreateCheckoutInput,
  CreateCheckoutResult,
  RetrievePaymentInput,
  VerifyWebhookInput,
  VerifyWebhookResult,
  NormalizeEventInput,
  ProviderCapabilities,
} from './payment-provider.interface';
import type { NormalizedPaymentResult, PaymentAmount } from './payment.types';
import type { NormalizedWebhookEvent, WebhookEventCategory } from './webhook.types';
import { PaymentConfigService, STRIPE_API_VERSION } from './payment.config';
import { Decimal } from '../../../common/decimal-string';
import { AppException } from '../../../common/errors/app.exception';
import { ErrorCode } from '@wlct/shared-types';

/**
 * Real Stripe integration adapter.
 *
 * Implements the common provider contract for Stripe:
 *  - Checkout/session creation using canonical plan price from billing catalog
 *  - Payment state retrieval
 *  - Webhook signature verification using Stripe's official method
 *  - Event normalization into internal payment states
 *  - Status mapping
 *
 * Never stores raw card numbers, CVV, or secrets in logs.
 * Never exposes provider secrets through API responses.
 */

@Injectable()
export class StripeAdapter implements IPaymentProvider {
  private readonly logger = new Logger(StripeAdapter.name);
  readonly provider = PaymentProvider.STRIPE;

  readonly capabilities: ProviderCapabilities = {
    supportsCheckout: true,
    supportsPaymentIntents: true,
    supportsRefunds: true,
    supportsPartialRefunds: true,
    supportsWebhooks: true,
    supportsRecurring: true,
    supportsCrypto: false,
    supportedCurrencies: ['USD', 'EUR', 'GBP', 'JPY', 'CAD', 'AUD'],
  };

  constructor(private readonly config: PaymentConfigService) {}

  async createCheckout(input: CreateCheckoutInput): Promise<CreateCheckoutResult> {
    this.validateCheckoutInput(input);
    const amountInMinorUnits = this.parseAmountToMinorUnits(input.price, input.currency);

    const stripeSecretKey = this.config.getStripeSecretKey();

    // Use dynamic import to avoid hard dependency if stripe not installed
    // In production, stripe SDK should be installed: npm install stripe
    let stripe: any;
    try {
      const Stripe = await this.loadStripeSdk();
      stripe = new Stripe(stripeSecretKey, {
        apiVersion: this.config.stripe?.apiVersion || STRIPE_API_VERSION,
        maxNetworkRetries: this.config.stripe?.maxNetworkRetries || 2,
        timeout: this.config.stripe?.timeoutMs || 30000,
      });
    } catch (error) {
      this.logger.error(`Failed to load Stripe SDK: ${(error as Error).message}`);
      throw new AppException({
        code: ErrorCode.SERVICE_UNAVAILABLE,
        message: 'Stripe SDK not available',
      });
    }

    try {
      // input.price comes from the canonical billing plan catalog and has been exactly scaled above.
      const sessionParams: any = {
        payment_method_types: ['card'],
        line_items: [
          {
            price_data: {
              currency: input.currency.toLowerCase(),
              product_data: {
                name: input.planName,
                description: `Subscription to ${input.planName} - ${input.interval}`,
                metadata: {
                  planId: input.planId,
                  planCode: input.planCode,
                  tenantId: input.tenantId,
                },
              },
              unit_amount: amountInMinorUnits,
              recurring: input.interval !== 'LIFETIME' ? {
                interval: this.mapIntervalToStripeInterval(input.interval),
              } : undefined,
            },
            quantity: 1,
          },
        ],
        mode: input.interval === 'LIFETIME' ? 'payment' : 'subscription',
        success_url: this.buildSuccessUrl(input.successUrl, '{CHECKOUT_SESSION_ID}'),
        cancel_url: input.cancelUrl,
        client_reference_id: input.references.orderId || input.idempotencyKey,
        metadata: {
          tenantId: input.tenantId,
          planId: input.planId,
          planCode: input.planCode,
          subscriptionId: input.subscriptionId || '',
          userId: input.userId || '',
          idempotencyKey: input.idempotencyKey,
          orderId: input.references.orderId || '',
        },
        customer_email: undefined,
        expires_at: Math.floor(Date.now() / 1000) + this.config.checkout.expirationMinutes * 60,
      };

      // Idempotency key passed via header
      const session = await stripe.checkout.sessions.create(sessionParams, {
        idempotencyKey: input.idempotencyKey,
      });

      this.logger.log(`Stripe checkout session created: ${session.id} for tenant ${input.tenantId}, plan ${input.planCode}`);

      return {
        providerCheckoutId: session.id,
        providerSessionId: session.id,
        providerPaymentId: session.payment_intent as string || session.id,
        providerCustomerId: (session.customer as string) || undefined,
        checkoutUrl: session.url,
        expiresAt: session.expires_at ? new Date(session.expires_at * 1000) : undefined,
        rawResponse: this.sanitizeRawResponse(session),
      };
    } catch (error) {
      this.logger.error(`Stripe checkout creation failed for tenant ${input.tenantId}: ${(error as Error).message}`);
      throw new AppException({
        code: ErrorCode.SERVICE_UNAVAILABLE,
        message: 'Failed to create Stripe checkout session',
        context: { provider: PaymentProvider.STRIPE, planId: input.planId },
      });
    }
  }

  async retrievePayment(input: RetrievePaymentInput): Promise<NormalizedPaymentResult> {
    const stripeSecretKey = this.config.getStripeSecretKey();
    let stripe: any;
    try {
      const Stripe = await this.loadStripeSdk();
      stripe = new Stripe(stripeSecretKey, {
        apiVersion: this.config.stripe?.apiVersion || STRIPE_API_VERSION,
      });
    } catch (error) {
      throw new AppException({
        code: ErrorCode.SERVICE_UNAVAILABLE,
        message: 'Stripe SDK not available',
      });
    }

    try {
      let stripeObject: any;
      let objectType: 'session' | 'payment_intent' | 'invoice' = 'session';

      if (input.providerSessionId || input.providerCheckoutId) {
        const sessionId = input.providerSessionId || input.providerCheckoutId!;
        stripeObject = await stripe.checkout.sessions.retrieve(sessionId);
        objectType = 'session';
      } else if (input.providerPaymentId) {
        try {
          stripeObject = await stripe.paymentIntents.retrieve(input.providerPaymentId);
          objectType = 'payment_intent';
        } catch {
          stripeObject = await stripe.checkout.sessions.retrieve(input.providerPaymentId);
          objectType = 'session';
        }
      } else {
        throw new AppException({
          code: ErrorCode.VALIDATION_ERROR,
          message: 'Provider payment ID or checkout ID required',
        });
      }

      return this.normalizeStripeObjectToPaymentResult(stripeObject, objectType);
    } catch (error) {
      if (error instanceof AppException) {
        throw error;
      }
      this.logger.error(`Stripe payment retrieval failed: ${(error as Error).message}`);
      throw new AppException({
        code: ErrorCode.SERVICE_UNAVAILABLE,
        message: 'Failed to retrieve Stripe payment',
      });
    }
  }

  async verifyWebhookSignature(input: VerifyWebhookInput): Promise<VerifyWebhookResult> {
    try {
      const webhookSecret = this.config.getStripeWebhookSecret();
      const rawBody = typeof input.rawBody === 'string' ? input.rawBody : input.rawBody.toString('utf8');

      let stripe: any;
      try {
        const Stripe = await this.loadStripeSdk();
        stripe = new Stripe(this.config.getStripeSecretKey(), {
          apiVersion: this.config.stripe?.apiVersion || STRIPE_API_VERSION,
        });
      } catch {
        return {
          verified: false,
          failureReason: 'Stripe SDK not available',
        };
      }

      const event = stripe.webhooks.constructEvent(rawBody, input.signature, webhookSecret);

      return {
        verified: true,
        eventId: event.id,
        eventType: event.type,
        rawEvent: event,
      };
    } catch (error) {
      this.logger.warn(`Stripe webhook signature verification failed: ${(error as Error).message}`);
      return {
        verified: false,
        failureReason: (error as Error).message,
      };
    }
  }

  async normalizeWebhookEvent(input: NormalizeEventInput): Promise<NormalizedWebhookEvent> {
    const rawEvent = input.rawEvent as any;

    if (!rawEvent || !rawEvent.id || !rawEvent.type) {
      throw new AppException({
        code: ErrorCode.VALIDATION_ERROR,
        message: 'Invalid Stripe event structure',
      });
    }

    const eventObject = rawEvent.data?.object;
    const eventCategory = this.mapStripeEventToCategory(rawEvent.type);
    const paymentStatus = this.mapStripeEventToPaymentStatus(rawEvent.type, eventObject);
    const amountTotal = eventObject?.amount_total;
    const amount = amountTotal === null || amountTotal === undefined
      ? undefined
      : {
          amount: stripeMinorUnitsToDecimalString(amountTotal, eventObject.currency),
          currency: normalizeStripeCurrency(eventObject.currency),
          amountInSmallestUnit: stripeMinorUnitNumber(amountTotal),
        };

    return {
      provider: PaymentProvider.STRIPE,
      providerEventId: rawEvent.id,
      eventType: rawEvent.type,
      eventCategory,
      paymentStatus,
      providerPaymentId: eventObject?.payment_intent || eventObject?.id,
      providerCheckoutId: eventObject?.id,
      providerSessionId: rawEvent.type.includes('checkout') ? eventObject?.id : undefined,
      amount,
      metadata: {
        tenantId: rawEvent.data?.object?.metadata?.tenantId,
        planId: rawEvent.data?.object?.metadata?.planId,
        subscriptionId: rawEvent.data?.object?.metadata?.subscriptionId,
        idempotencyKey: rawEvent.data?.object?.metadata?.idempotencyKey,
      },
      rawEvent: this.sanitizeRawResponse(rawEvent),
      receivedAt: new Date(),
      providerCreatedAt: typeof rawEvent.created === 'number' && Number.isSafeInteger(rawEvent.created)
        ? new Date(rawEvent.created * 1000)
        : null,
    };
  }

  mapProviderStatusToInternalStatus(providerStatus: string): PaymentStatus {
    const statusMap: Record<string, PaymentStatus> = {
      'open': PaymentStatus.PENDING,
      'complete': PaymentStatus.SUCCEEDED,
      'expired': PaymentStatus.EXPIRED,
      'requires_payment_method': PaymentStatus.PENDING,
      'requires_confirmation': PaymentStatus.PENDING,
      'requires_action': PaymentStatus.PENDING,
      'processing': PaymentStatus.PROCESSING,
      'requires_capture': PaymentStatus.PROCESSING,
      'canceled': PaymentStatus.CANCELLED,
      'succeeded': PaymentStatus.SUCCEEDED,
      'failed': PaymentStatus.FAILED,
      'refunded': PaymentStatus.REFUNDED,
      'partially_refunded': PaymentStatus.PARTIALLY_REFUNDED,
    };

    return statusMap[providerStatus?.toLowerCase()] || PaymentStatus.UNKNOWN;
  }

  mapProviderStatusToTransactionState(providerStatus: string): TransactionState {
    const stateMap: Record<string, TransactionState> = {
      'open': TransactionState.INITIALIZED,
      'complete': TransactionState.CAPTURED,
      'expired': TransactionState.FAILED,
      'requires_payment_method': TransactionState.INITIALIZED,
      'requires_confirmation': TransactionState.INITIALIZED,
      'requires_action': TransactionState.INITIALIZED,
      'processing': TransactionState.AUTHORIZED,
      'requires_capture': TransactionState.AUTHORIZED,
      'canceled': TransactionState.VOIDED,
      'succeeded': TransactionState.CAPTURED,
      'failed': TransactionState.FAILED,
      'refunded': TransactionState.REFUNDED,
      'partially_refunded': TransactionState.REFUNDED,
    };

    return stateMap[providerStatus?.toLowerCase()] || TransactionState.FAILED;
  }

  private validateCheckoutInput(input: CreateCheckoutInput): void {
    if (!input.planId) {
      throw new AppException({ code: ErrorCode.VALIDATION_ERROR, message: 'Plan ID required' });
    }
    if (!input.tenantId) {
      throw new AppException({ code: ErrorCode.VALIDATION_ERROR, message: 'Tenant ID required' });
    }
    if (!input.price) {
      throw new AppException({ code: ErrorCode.VALIDATION_ERROR, message: 'Plan price required - must come from catalog' });
    }
    if (!input.idempotencyKey) {
      throw new AppException({ code: ErrorCode.VALIDATION_ERROR, message: 'Idempotency key required' });
    }
  }

  private parseAmountToMinorUnits(price: string, currency: string): number {
    try {
      return stripeDecimalToMinorUnits(price, currency);
    } catch {
      throw new AppException({
        code: ErrorCode.VALIDATION_ERROR,
        message: 'Price must be a non-negative exact decimal representable in the currency minor unit',
      });
    }
  }

  private mapIntervalToStripeInterval(interval: string): 'day' | 'week' | 'month' | 'year' {
    switch (interval?.toUpperCase()) {
      case 'MONTHLY':
        return 'month';
      case 'QUARTERLY':
        return 'month';
      case 'YEARLY':
      case 'ANNUAL':
        return 'year';
      case 'LIFETIME':
        return 'year';
      default:
        return 'month';
    }
  }

  private buildSuccessUrl(baseUrl: string, sessionIdPlaceholder: string): string {
    if (baseUrl.includes('{CHECKOUT_SESSION_ID}')) {
      return baseUrl.replace('{CHECKOUT_SESSION_ID}', sessionIdPlaceholder);
    }
    const separator = baseUrl.includes('?') ? '&' : '?';
    return `${baseUrl}${separator}session_id=${sessionIdPlaceholder}`;
  }

  private mapStripeEventToCategory(eventType: string): WebhookEventCategory {
    if (eventType.includes('checkout.session.completed') || eventType.includes('payment_intent.succeeded')) {
      return 'PAYMENT_SUCCEEDED' as WebhookEventCategory;
    }
    if (eventType.includes('checkout.session.expired') || eventType.includes('payment_intent.payment_failed')) {
      return 'PAYMENT_FAILED' as WebhookEventCategory;
    }
    if (eventType.includes('charge.refunded')) {
      return 'PAYMENT_REFUNDED' as WebhookEventCategory;
    }
    if (eventType.includes('checkout.session.async_payment_succeeded')) {
      return 'PAYMENT_SUCCEEDED' as WebhookEventCategory;
    }
    if (eventType.includes('checkout.session.async_payment_failed')) {
      return 'PAYMENT_FAILED' as WebhookEventCategory;
    }
    return 'PAYMENT_PENDING' as WebhookEventCategory;
  }

  private mapStripeEventToPaymentStatus(eventType: string, object: any): PaymentStatus {
    if (eventType === 'checkout.session.completed') {
      const paymentStatus = object?.payment_status;
      if (paymentStatus === 'paid' || paymentStatus === 'no_payment_required') {
        return PaymentStatus.SUCCEEDED;
      }
      return PaymentStatus.PENDING;
    }
    if (eventType === 'checkout.session.expired') {
      return PaymentStatus.EXPIRED;
    }
    if (eventType === 'payment_intent.succeeded') {
      return PaymentStatus.SUCCEEDED;
    }
    if (eventType === 'payment_intent.payment_failed') {
      return PaymentStatus.FAILED;
    }
    if (eventType === 'payment_intent.canceled') {
      return PaymentStatus.CANCELLED;
    }
    if (eventType === 'charge.refunded') {
      return object?.refunded ? PaymentStatus.REFUNDED : PaymentStatus.PARTIALLY_REFUNDED;
    }
    return PaymentStatus.PENDING;
  }

  private normalizeStripeObjectToPaymentResult(stripeObject: any, objectType: string): NormalizedPaymentResult {
    const isSession = objectType === 'session';
    const amountTotal = isSession ? stripeObject.amount_total : stripeObject.amount;
    const currency = normalizeStripeCurrency(stripeObject.currency);

    const amount: PaymentAmount = {
      amount: stripeMinorUnitsToDecimalString(amountTotal, currency),
      currency,
      amountInSmallestUnit: stripeMinorUnitNumber(amountTotal),
    };

    const status = isSession
      ? this.mapProviderStatusToInternalStatus(stripeObject.status)
      : this.mapProviderStatusToInternalStatus(stripeObject.status);

    const transactionState = isSession
      ? this.mapProviderStatusToTransactionState(stripeObject.status)
      : this.mapProviderStatusToTransactionState(stripeObject.status);

    return {
      internalPaymentId: stripeObject.metadata?.internalPaymentId || stripeObject.id,
      provider: PaymentProvider.STRIPE,
      status,
      transactionState,
      amount,
      providerReference: {
        provider: PaymentProvider.STRIPE,
        providerPaymentId: isSession ? (stripeObject.payment_intent as string) || stripeObject.id : stripeObject.id,
        providerCheckoutId: isSession ? stripeObject.id : null,
        providerSessionId: isSession ? stripeObject.id : null,
        providerCustomerId: (stripeObject.customer as string) || undefined,
        checkoutUrl: isSession ? stripeObject.url : null,
      },
      references: {
        tenantId: stripeObject.metadata?.tenantId || '',
        planId: stripeObject.metadata?.planId || '',
        subscriptionId: stripeObject.metadata?.subscriptionId || null,
        userId: stripeObject.metadata?.userId || null,
        idempotencyKey: stripeObject.metadata?.idempotencyKey || '',
        orderId: stripeObject.metadata?.orderId || stripeObject.client_reference_id || null,
      },
      metadata: {
        planCode: stripeObject.metadata?.planCode,
        billingInterval: stripeObject.metadata?.billingInterval as any,
        successUrl: stripeObject.success_url,
        cancelUrl: stripeObject.cancel_url,
      },
      paymentMethod: PaymentMethodType.CARD,
      createdAt: new Date(stripeObject.created * 1000).toISOString(),
      updatedAt: new Date().toISOString(),
      rawProviderStatus: stripeObject.status,
    };
  }

  private sanitizeRawResponse(response: any): any {
    if (!response) return null;
    // Never include secrets, card numbers, etc
    const sanitized = { ...response };
    delete sanitized.client_secret;
    delete sanitized.card;
    delete sanitized.source;
    delete sanitized.payment_method;
    return sanitized;
  }

  private async loadStripeSdk(): Promise<typeof import('stripe').default> {
    // Load on demand so a missing optional runtime install is reported at the provider boundary.
    try {
      return (await import('stripe')).default;
    } catch {
      throw new Error('Stripe SDK not installed. Run: npm install stripe');
    }
  }
}

const STRIPE_ZERO_DECIMAL_CURRENCIES = new Set([
  'BIF', 'CLP', 'DJF', 'GNF', 'ISK', 'JPY', 'KMF', 'KRW', 'MGA', 'PYG',
  'RWF', 'UGX', 'VND', 'VUV', 'XAF', 'XOF', 'XPF',
]);
const STRIPE_TWO_DECIMAL_CURRENCIES = new Set(['AUD', 'CAD', 'EUR', 'GBP', 'USD']);
const STRIPE_THREE_DECIMAL_CURRENCIES = new Set(['BHD', 'IQD', 'JOD', 'KWD', 'LYD', 'OMR', 'TND']);
const STRIPE_FOUR_DECIMAL_CURRENCIES = new Set(['CLF', 'UYW']);

function normalizeStripeCurrency(value: unknown): string {
  if (typeof value !== 'string') throw new TypeError('Stripe currency must be a string');
  const currency = value.trim().toUpperCase();
  if (!/^[A-Z]{3}$/.test(currency)) throw new TypeError('Stripe currency must be a three-letter code');
  return currency;
}

function stripeCurrencyMinorUnitScale(currencyValue: unknown): number {
  const currency = normalizeStripeCurrency(currencyValue);
  if (STRIPE_ZERO_DECIMAL_CURRENCIES.has(currency)) return 0;
  if (STRIPE_FOUR_DECIMAL_CURRENCIES.has(currency)) return 4;
  if (STRIPE_THREE_DECIMAL_CURRENCIES.has(currency)) return 3;
  if (STRIPE_TWO_DECIMAL_CURRENCIES.has(currency)) return 2;
  throw new TypeError('Stripe currency minor-unit exponent is not configured');
}

function stripeMinorUnitNumber(value: unknown): number {
  if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < 0) {
    throw new TypeError('Stripe amount must be a non-negative safe integer in minor units');
  }
  return value;
}

export function stripeMinorUnitsToDecimalString(value: unknown, currencyValue: unknown): string {
  const minorUnits = stripeMinorUnitNumber(value);
  const scale = stripeCurrencyMinorUnitScale(currencyValue);
  return Decimal.fromUnscaled(BigInt(minorUnits), scale).toString();
}

function stripeDecimalToMinorUnits(price: string, currencyValue: unknown): number {
  if (typeof price !== 'string') throw new TypeError('Stripe price must be an exact decimal string');
  const scale = stripeCurrencyMinorUnitScale(currencyValue);
  const minorUnits = Decimal.parse(price).toScaledBigInt(scale);
  if (minorUnits < 0n || minorUnits > BigInt(Number.MAX_SAFE_INTEGER)) {
    throw new RangeError('Stripe amount exceeds the exact safe integer minor-unit range');
  }
  return Number(minorUnits);
}

import {
  Controller,
  Post,
  Req,
  Headers,
  HttpCode,
  HttpStatus,
  Logger,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiExcludeEndpoint } from '@nestjs/swagger';
import { WebhookService } from './webhook.service';
import { PaymentProvider } from './payment.types';
import type { WebhookPayload } from './webhook.types';
import { ApiStandardResponses } from '../../../common/decorators/api-standard-responses.decorator';
import { Public } from '../../../common/decorators/public.decorator';
import { PlatformOnly, RequirePermissions } from '../../../common/decorators/permissions.decorator';
import { Permission } from '@wlct/shared-types';

/**
 * Public webhook endpoints for Stripe and NowPayments using raw request-body
 * / signature-safe handling and existing API routing conventions.
 *
 * Webhook endpoints must be public only where required by provider callbacks,
 * while all provider authenticity and replay checks must occur before processing.
 *
 * The provider endpoints are @Public(): Stripe and NowPayments cannot send a
 * user JWT, and without the marker the global JwtAuthGuard answered 401 before
 * any signature check ran, so no payment webhook was ever processed. Their
 * authentication is the provider signature plus replay protection below.
 * The signature-bypassing test endpoint stays authenticated and platform-only.
 *
 * Security:
 *  - Raw body preserved for signature verification (main.ts: rawBody: true)
 *  - Signature verification before any processing
 *  - Replay protection via provider event ID
 *  - No secrets logged
 */

@ApiTags('Billing - webhooks')
@Controller({ path: 'billing/webhooks', version: '1' })
@ApiStandardResponses()
export class WebhookController {
  private readonly logger = new Logger(WebhookController.name);

  constructor(private readonly webhookService: WebhookService) {}

  @Post('stripe')
  @Public()
  @HttpCode(HttpStatus.OK)
  @ApiOperation({
    summary: 'Stripe webhook endpoint',
    description: 'Receives and processes Stripe webhook events. Verifies signature using STRIPE_WEBHOOK_SECRET, checks replay protection, and syncs payment to subscription.',
  })
  @ApiExcludeEndpoint(false)
  async handleStripeWebhook(
    @Req() req: any,
    @Headers('stripe-signature') signature: string,
  ): Promise<{ received: boolean; eventId?: string }> {
    this.logger.log('Stripe webhook received');

    if (!signature) {
      this.logger.warn('Stripe webhook missing signature header');
      return { received: false };
    }

    // Raw body should be available via middleware that preserves raw body
    // In NestJS, you need to configure raw body parser for webhook routes
    const rawBody = req.rawBody || req.body;

    if (!rawBody) {
      this.logger.warn('Stripe webhook missing raw body');
      return { received: false };
    }

    const payload: WebhookPayload = {
      provider: PaymentProvider.STRIPE,
      rawBody: Buffer.isBuffer(rawBody) ? rawBody : Buffer.from(typeof rawBody === 'string' ? rawBody : JSON.stringify(rawBody)),
      signature,
      headers: req.headers,
    };

    try {
      const result = await this.webhookService.processWebhook(payload);

      this.logger.log(`Stripe webhook processed: ${result.providerEventId} status ${result.processingStatus}`);

      return {
        received: true,
        eventId: result.providerEventId,
      };
    } catch (error) {
      // For webhooks, we still return 200 to prevent provider retries for invalid signatures
      // But log the error for investigation
      const isAuthError = (error as any).code === 'UNAUTHORIZED' || (error as Error).message.includes('signature');

      if (isAuthError) {
        this.logger.warn(`Stripe webhook signature verification failed: ${(error as Error).message}`);
        return { received: false };
      }

      this.logger.error(`Stripe webhook processing failed: ${(error as Error).message}`);

      // Return received true to prevent infinite retries for processing errors
      // Failed events can be retried via replay guard
      return { received: true };
    }
  }

  @Post('nowpayments')
  @Public()
  @HttpCode(HttpStatus.OK)
  @ApiOperation({
    summary: 'NowPayments IPN webhook endpoint',
    description: 'Receives and processes NowPayments IPN callbacks. Verifies authenticity via IPN secret, checks replay protection, and syncs payment to subscription.',
  })
  @ApiExcludeEndpoint(false)
  async handleNowPaymentsWebhook(
    @Req() req: any,
    @Headers('x-nowpayments-sig') signature?: string,
  ): Promise<{ received: boolean; eventId?: string }> {
    this.logger.log('NowPayments webhook received');

    const rawBody = req.rawBody || req.body;

    if (!rawBody) {
      this.logger.warn('NowPayments webhook missing raw body');
      return { received: false };
    }

    // NOWPayments authenticity is the IPN HMAC only; an API key is never a webhook signature.
    const effectiveSignature = signature || '';

    const payload: WebhookPayload = {
      provider: PaymentProvider.NOWPAYMENTS,
      rawBody: Buffer.isBuffer(rawBody) ? rawBody : Buffer.from(typeof rawBody === 'string' ? rawBody : JSON.stringify(rawBody)),
      signature: effectiveSignature,
      headers: req.headers,
    };

    try {
      const result = await this.webhookService.processWebhook(payload);

      this.logger.log(`NowPayments webhook processed: ${result.providerEventId} status ${result.processingStatus}`);

      return {
        received: true,
        eventId: result.providerEventId,
      };
    } catch (error) {
      const isAuthError = (error as any).code === 'UNAUTHORIZED' || (error as Error).message.includes('signature');

      if (isAuthError) {
        this.logger.warn(`NowPayments webhook verification failed: ${(error as Error).message}`);
        return { received: false };
      }

      this.logger.error(`NowPayments webhook processing failed: ${(error as Error).message}`);

      return { received: true };
    }
  }

  @Post('stripe/test')
  @PlatformOnly()
  @RequirePermissions(Permission.PLATFORM_MANAGE)
  @HttpCode(HttpStatus.OK)
  @ApiOperation({
    summary: 'Stripe webhook test endpoint (development only)',
    description: 'Test endpoint for Stripe webhook verification without signature check - only enabled in development',
  })
  @ApiExcludeEndpoint(true)
  async handleStripeTestWebhook(@Req() req: any): Promise<{ received: boolean; eventId?: string; warning: string }> {
    if (process.env.NODE_ENV === 'production') {
      return { received: false, warning: 'Test endpoint disabled in production' } as any;
    }

    const rawBody = req.rawBody || req.body;

    // For testing, we bypass signature verification but still process
    this.logger.warn('Stripe TEST webhook received - bypassing signature verification');

    const payload: WebhookPayload = {
      provider: PaymentProvider.STRIPE,
      rawBody: Buffer.isBuffer(rawBody) ? rawBody : Buffer.from(JSON.stringify(rawBody)),
      signature: 'test_signature',
      headers: req.headers,
    };

    try {
      // In test mode, we directly try to normalize without signature verification
      const result = await this.webhookService.processWebhook(payload);

      return {
        received: true,
        eventId: result.providerEventId,
        warning: 'TEST MODE - signature verification bypassed',
      };
    } catch (error) {
      this.logger.error(`Stripe test webhook failed: ${(error as Error).message}`);
      return {
        received: false,
        warning: `Test failed: ${(error as Error).message}`,
      } as any;
    }
  }
}

import { WebhookReplayGuard } from './webhook.replay-guard';
import { WebhookProcessingStatus } from './webhook.types';
import { PaymentProvider } from './payment.types';

type Row = Record<string, any>;

/** Minimal in-memory webhookEvent delegate honouring equality and `{ not }` filters. */
function fakeWebhookEvents() {
  const rows: Row[] = [];
  let clock = 1_700_000_000_000;
  const matches = (row: Row, where: Row): boolean =>
    Object.entries(where).every(([key, cond]) => {
      if (cond !== null && typeof cond === 'object' && 'not' in cond) {
        return row[key] !== cond.not;
      }
      return row[key] === cond;
    });
  const delegate = {
    rows,
    create: jest.fn(async ({ data }: { data: Row }) => {
      clock += 1000;
      const row = {
        processingAttempts: 0,
        processingStatus: WebhookProcessingStatus.RECEIVED,
        createdAt: new Date(clock),
        updatedAt: new Date(clock),
        ...data,
      };
      rows.push(row);
      return row;
    }),
    findFirst: jest.fn(async ({ where, orderBy }: { where: Row; orderBy?: Row }) => {
      const hits = rows.filter((r) => matches(r, where));
      if (orderBy?.createdAt === 'desc') {
        hits.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
      }
      return hits[0] ?? null;
    }),
    updateMany: jest.fn(async ({ where, data }: { where: Row; data: Row }) => {
      let count = 0;
      for (const row of rows) {
        if (!matches(row, where)) {
          continue;
        }
        count += 1;
        for (const [key, value] of Object.entries(data)) {
          if (value !== null && typeof value === 'object' && 'increment' in value) {
            row[key] = (row[key] ?? 0) + value.increment;
          } else if (value !== undefined) {
            row[key] = value;
          }
        }
      }
      return { count };
    }),
  };
  return delegate;
}

const EVENT = {
  provider: PaymentProvider.STRIPE,
  providerEventId: 'evt_123',
  eventType: 'invoice.paid',
  eventCategory: 'PAYMENT',
  paymentStatus: 'SUCCEEDED',
  // Inside the guard's 24h replay window: an older event is refused for age,
  // which would hide what these tests are about.
  receivedAt: new Date(),
  providerCreatedAt: new Date(),
  metadata: {},
} as any;

describe('WebhookReplayGuard (durable replay protection)', () => {
  let events: ReturnType<typeof fakeWebhookEvents>;
  let guard: WebhookReplayGuard;
  const cache = { get: jest.fn(async () => null), set: jest.fn(async () => undefined) };

  beforeEach(() => {
    events = fakeWebhookEvents();
    cache.get.mockClear();
    cache.set.mockClear();
    guard = new WebhookReplayGuard({ webhookEvent: events } as any, cache as any);
  });

  /** The order WebhookService uses for one delivery. */
  async function deliver(): Promise<boolean> {
    await guard.recordEventReceived(EVENT, { id: EVENT.providerEventId }, 'sig');
    await guard.markEventVerified(EVENT.provider, EVENT.providerEventId);
    const check = await guard.checkReplay(EVENT);
    if (!check.shouldProcess) {
      if (check.isDuplicate) {
        await guard.markEventDuplicate(EVENT.provider, EVENT.providerEventId);
      }
      return false;
    }
    await guard.markEventProcessing(EVENT.provider, EVENT.providerEventId);
    await guard.markEventProcessed(EVENT.provider, EVENT.providerEventId, 'pay_1', 'tenant-1');
    return true;
  }

  it('processes the first delivery', async () => {
    await expect(deliver()).resolves.toBe(true);
    expect(
      events.rows.filter((r) => r.processingStatus === WebhookProcessingStatus.PROCESSED),
    ).toHaveLength(1);
  });

  it('refuses a replay from the database once the cache entry has expired', async () => {
    await deliver();
    // cache.get always returns null here: the Redis entry is gone.
    await expect(deliver()).resolves.toBe(false);
    await expect(deliver()).resolves.toBe(false);
  });

  it('never downgrades the PROCESSED row when later deliveries are marked', async () => {
    await deliver();
    await deliver();
    await guard.markEventFailed(EVENT.provider, EVENT.providerEventId, 'late failure');
    await guard.markEventProcessing(EVENT.provider, EVENT.providerEventId);
    const processed = events.rows.filter(
      (r) => r.processingStatus === WebhookProcessingStatus.PROCESSED,
    );
    expect(processed).toHaveLength(1);
    expect(processed[0].paymentId).toBe('pay_1');
  });

  it('excludes PROCESSED rows in every non-terminal status update', async () => {
    await guard.markEventVerified(EVENT.provider, EVENT.providerEventId);
    await guard.markEventProcessing(EVENT.provider, EVENT.providerEventId);
    await guard.markEventFailed(EVENT.provider, EVENT.providerEventId, 'x');
    await guard.markEventDuplicate(EVENT.provider, EVENT.providerEventId);
    expect(events.updateMany).toHaveBeenCalledTimes(4);
    for (const [args] of events.updateMany.mock.calls) {
      expect(args.where).toEqual({
        provider: EVENT.provider,
        providerEventId: EVENT.providerEventId,
        processingStatus: { not: WebhookProcessingStatus.PROCESSED },
      });
    }
  });

  it('answers from the PROCESSED row even when a newer row exists', async () => {
    await deliver();
    await guard.recordEventReceived(EVENT, { id: EVENT.providerEventId }, 'sig');
    const check = await guard.checkReplay(EVENT);
    expect(check.shouldProcess).toBe(false);
    expect(check.isDuplicate).toBe(true);
    expect(check.existingRecord?.processingStatus).toBe(WebhookProcessingStatus.PROCESSED);
  });

  it('allows a retry after a failed attempt', async () => {
    await guard.recordEventReceived(EVENT, { id: EVENT.providerEventId }, 'sig');
    await guard.markEventProcessing(EVENT.provider, EVENT.providerEventId);
    await guard.markEventFailed(EVENT.provider, EVENT.providerEventId, 'provider timeout');
    const check = await guard.checkReplay(EVENT);
    expect(check.shouldProcess).toBe(true);
  });

  it('does not invent a provider timestamp when replay-age evidence is absent', async () => {
    const check = await guard.checkReplay({ ...EVENT, providerCreatedAt: null });
    expect(check).toMatchObject({ isDuplicate: false, isReplay: false, shouldProcess: true });
  });

  it('short-circuits on the cache fast path', async () => {
    cache.get.mockResolvedValueOnce({ processedAt: 'x' } as never);
    const check = await guard.checkReplay(EVENT);
    expect(check).toMatchObject({ isDuplicate: true, shouldProcess: false });
    expect(events.findFirst).not.toHaveBeenCalled();
  });
});

// # Responsibility: enforce persistent replay protection and idempotency for tenant payment webhooks.
import { Injectable, Logger } from '@nestjs/common';
import { createHash, randomUUID } from 'node:crypto';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { CacheService } from '../../../infrastructure/redis/cache.service';
import { PaymentProvider } from './payment.types';
import type { WebhookEventRecord, WebhookReplayCheck, NormalizedWebhookEvent } from './webhook.types';
import { WebhookProcessingStatus } from './webhook.types';

/**
 * Replay/idempotency protection for webhook events using provider event ID,
 * event hash, timestamps, and persistent processing state.
 *
 * Webhook replay prevention must support:
 *  - provider
 *  - provider event ID
 *  - event hash where appropriate
 *  - received timestamp
 *  - first-seen timestamp
 *  - processing status
 *  - successful/failed processing result
 *
 * Same provider event received twice must not apply the subscription transition twice.
 */

@Injectable()
export class WebhookReplayGuard {
  private readonly logger = new Logger(WebhookReplayGuard.name);
  private readonly CACHE_TTL_SECONDS = 24 * 60 * 60;
  private readonly PROCESSED_EVENT_TTL = 7 * 24 * 60 * 60;

  constructor(
    private readonly prisma: PrismaService,
    private readonly cache: CacheService,
  ) {}

  async checkReplay(event: NormalizedWebhookEvent): Promise<WebhookReplayCheck> {
    const provider = event.provider;
    const providerEventId = event.providerEventId;

    if (!providerEventId) {
      return {
        isDuplicate: false,
        isReplay: false,
        shouldProcess: true,
        reason: 'No provider event ID - cannot deduplicate',
      };
    }

    // Step 1: Check Redis cache for recently processed events (fast path)
    const cacheKey = `webhook:processed:${provider}:${providerEventId}`;
    const cached = await this.cache.get(cacheKey);

    if (cached) {
      this.logger.log(`Webhook replay detected (cache): ${provider}:${providerEventId} already processed`);

      return {
        isDuplicate: true,
        isReplay: true,
        shouldProcess: false,
        reason: `Event ${providerEventId} already processed (cached)`,
      };
    }

    // Step 2: Check database for existing event record
    try {
      const existingRecord = await this.findExistingEvent(provider, providerEventId);

      if (existingRecord) {
        // Event already exists - check if it was successfully processed
        if (existingRecord.processingStatus === WebhookProcessingStatus.PROCESSED) {
          this.logger.log(`Webhook duplicate detected (DB): ${provider}:${providerEventId} already processed at ${existingRecord.processedAt}`);

          return {
            isDuplicate: true,
            isReplay: true,
            existingRecord,
            shouldProcess: false,
            reason: `Event ${providerEventId} already processed successfully`,
          };
        }

        if (existingRecord.processingStatus === WebhookProcessingStatus.PROCESSING) {
          // Event is currently being processed - possible concurrent delivery
          const processingAge = Date.now() - existingRecord.updatedAt.getTime();
          const processingTimeout = 5 * 60 * 1000; // 5 minutes

          if (processingAge < processingTimeout) {
            this.logger.log(`Webhook concurrent processing detected: ${provider}:${providerEventId} is being processed`);

            return {
              isDuplicate: false,
              isReplay: true,
              existingRecord,
              shouldProcess: false,
              reason: `Event ${providerEventId} is currently being processed`,
            };
          }

          // Processing timed out - allow retry
          this.logger.log(`Webhook processing timeout for ${provider}:${providerEventId}, allowing retry`);
        }

        // For FAILED status, allow retry
        if (existingRecord.processingStatus === WebhookProcessingStatus.FAILED) {
          this.logger.log(`Webhook previous failure for ${provider}:${providerEventId}, allowing retry (attempt ${existingRecord.processingAttempts + 1})`);

          return {
            isDuplicate: false,
            isReplay: false,
            existingRecord,
            shouldProcess: true,
            reason: `Retrying failed event ${providerEventId}`,
          };
        }
      }
    } catch (error) {
      this.logger.warn(`Failed to check existing webhook event: ${(error as Error).message}`);
      // On DB failure, allow processing but log warning
    }

    // Step 3: Check event age for replay window only when the provider supplied a valid timestamp.
    // Missing provider time is unknown evidence, not permission to substitute the receive time.
    const replayWindowSeconds = 24 * 60 * 60; // 24 hours
    const providerCreatedAtMs = event.providerCreatedAt?.getTime();

    if (providerCreatedAtMs !== undefined && Number.isFinite(providerCreatedAtMs)) {
      const eventAgeSeconds = (Date.now() - providerCreatedAtMs) / 1000;
      if (eventAgeSeconds > replayWindowSeconds) {
        this.logger.warn(`Webhook event too old: ${provider}:${providerEventId} age ${eventAgeSeconds}s exceeds window ${replayWindowSeconds}s`);

        return {
          isDuplicate: false,
          isReplay: true,
          shouldProcess: false,
          reason: `Event too old: ${eventAgeSeconds}s old, window is ${replayWindowSeconds}s`,
        };
      }
    }

    // Event is new and should be processed
    return {
      isDuplicate: false,
      isReplay: false,
      shouldProcess: true,
      reason: `New event ${providerEventId} should be processed`,
    };
  }

  async recordEventReceived(event: NormalizedWebhookEvent, rawPayload?: any, signature?: string): Promise<WebhookEventRecord> {
    const eventHash = this.computeEventHash(event);

    try {
      const record = await (this.prisma as any).webhookEvent?.create({
        data: {
          id: this.generateId(),
          provider: event.provider,
          providerEventId: event.providerEventId,
          eventType: event.eventType,
          eventCategory: event.eventCategory,
          providerPaymentId: event.providerPaymentId || null,
          providerCheckoutId: event.providerCheckoutId || null,
          eventHash,
          payload: rawPayload ? this.sanitizePayload(rawPayload) : null,
          signature: signature ? '***REDACTED***' : null,
          processingStatus: WebhookProcessingStatus.RECEIVED,
          processingAttempts: 0,
          paymentId: null,
          tenantId: event.metadata?.tenantId || null,
          receivedAt: event.receivedAt,
          firstSeenAt: new Date(),
        },
      });

      if (record) {
        return this.mapToRecord(record);
      }

      return this.createFallbackRecord(event, eventHash);
    } catch (error) {
      this.logger.warn(`Failed to record webhook event received: ${(error as Error).message}`);
      return this.createFallbackRecord(event, eventHash);
    }
  }

  async markEventVerified(provider: PaymentProvider, providerEventId: string): Promise<void> {
    try {
      await (this.prisma as any).webhookEvent?.updateMany({
        where: { provider, providerEventId, processingStatus: { not: WebhookProcessingStatus.PROCESSED } },
        data: {
          processingStatus: WebhookProcessingStatus.VERIFIED,
          updatedAt: new Date(),
        },
      });
    } catch (error) {
      this.logger.warn(`Failed to mark event verified: ${(error as Error).message}`);
    }
  }

  async markEventProcessing(provider: PaymentProvider, providerEventId: string): Promise<void> {
    try {
      await (this.prisma as any).webhookEvent?.updateMany({
        where: { provider, providerEventId, processingStatus: { not: WebhookProcessingStatus.PROCESSED } },
        data: {
          processingStatus: WebhookProcessingStatus.PROCESSING,
          processingAttempts: { increment: 1 },
          updatedAt: new Date(),
        },
      });
    } catch (error) {
      this.logger.warn(`Failed to mark event processing: ${(error as Error).message}`);
    }
  }

  async markEventProcessed(provider: PaymentProvider, providerEventId: string, paymentId?: string, tenantId?: string): Promise<void> {
    try {
      await (this.prisma as any).webhookEvent?.updateMany({
        where: { provider, providerEventId },
        data: {
          processingStatus: WebhookProcessingStatus.PROCESSED,
          processedAt: new Date(),
          paymentId: paymentId || undefined,
          tenantId: tenantId || undefined,
          updatedAt: new Date(),
        },
      });

      // Cache processed event for fast replay detection
      const cacheKey = `webhook:processed:${provider}:${providerEventId}`;
      await this.cache.set(cacheKey, { processedAt: new Date().toISOString(), paymentId }, this.PROCESSED_EVENT_TTL);
    } catch (error) {
      this.logger.warn(`Failed to mark event processed: ${(error as Error).message}`);
    }
  }

  async markEventFailed(provider: PaymentProvider, providerEventId: string, errorMessage: string): Promise<void> {
    try {
      await (this.prisma as any).webhookEvent?.updateMany({
        where: { provider, providerEventId, processingStatus: { not: WebhookProcessingStatus.PROCESSED } },
        data: {
          processingStatus: WebhookProcessingStatus.FAILED,
          lastProcessingError: errorMessage.substring(0, 1000),
          updatedAt: new Date(),
        },
      });
    } catch (error) {
      this.logger.warn(`Failed to mark event failed: ${(error as Error).message}`);
    }
  }

  async markEventDuplicate(provider: PaymentProvider, providerEventId: string): Promise<void> {
    try {
      await (this.prisma as any).webhookEvent?.updateMany({
        where: { provider, providerEventId, processingStatus: { not: WebhookProcessingStatus.PROCESSED } },
        data: {
          processingStatus: WebhookProcessingStatus.DUPLICATE,
          processedAt: new Date(),
          updatedAt: new Date(),
        },
      });

      const cacheKey = `webhook:processed:${provider}:${providerEventId}`;
      await this.cache.set(cacheKey, { processedAt: new Date().toISOString(), duplicate: true }, this.PROCESSED_EVENT_TTL);
    } catch (error) {
      this.logger.warn(`Failed to mark event duplicate: ${(error as Error).message}`);
    }
  }

  async markEventRejected(provider: PaymentProvider, providerEventId: string, reason: string): Promise<void> {
    try {
      await (this.prisma as any).webhookEvent?.create({
        data: {
          id: this.generateId(),
          provider,
          providerEventId,
          eventType: 'REJECTED',
          eventCategory: 'UNKNOWN',
          eventHash: this.computeSimpleHash(`${provider}:${providerEventId}:${reason}`),
          processingStatus: WebhookProcessingStatus.REJECTED,
          lastProcessingError: reason.substring(0, 1000),
          receivedAt: new Date(),
          firstSeenAt: new Date(),
        },
      });
    } catch (error) {
      this.logger.warn(`Failed to mark event rejected: ${(error as Error).message}`);
    }
  }

  private async findExistingEvent(provider: PaymentProvider, providerEventId: string): Promise<WebhookEventRecord | null> {
    // A PROCESSED row wins over any newer one. The webhook service records
    // every delivery (recordEventReceived runs before checkReplay), so for a
    // replay the NEWEST row is always the fresh RECEIVED one; answering from
    // it would let a replay through once the Redis entry has expired.
    const processed = await (this.prisma as any).webhookEvent?.findFirst({
      where: { provider, providerEventId, processingStatus: WebhookProcessingStatus.PROCESSED },
      orderBy: { createdAt: 'desc' },
    });
    if (processed) {
      return this.mapToRecord(processed);
    }
    const record = await (this.prisma as any).webhookEvent?.findFirst({
      where: { provider, providerEventId },
      orderBy: { createdAt: 'desc' },
    });

    if (record) {
      return this.mapToRecord(record);
    }
    return null;
  }

  private computeEventHash(event: NormalizedWebhookEvent): string {
    try {
      const data = `${event.provider}:${event.providerEventId}:${event.eventType}:${event.providerPaymentId || ''}:${JSON.stringify(event.amount || {})}`;
      return createHash('sha256').update(data).digest('hex');
    } catch {
      return this.computeSimpleHash(`${event.provider}:${event.providerEventId}:${event.eventType}`);
    }
  }

  private computeSimpleHash(data: string): string {
    try {
      return createHash('sha256').update(data).digest('hex');
    } catch {
      return data.substring(0, 64);
    }
  }

  private sanitizePayload(payload: any): any {
    if (!payload) return null;
    try {
      const sanitized = JSON.parse(JSON.stringify(payload));
      // Remove sensitive fields
      const sensitiveFields = ['card', 'source', 'payment_method', 'api_key', 'secret', 'cvv', 'cvc', 'number'];
      const removeSensitive = (obj: any) => {
        if (typeof obj !== 'object' || obj === null) return;
        for (const key of Object.keys(obj)) {
          if (sensitiveFields.some((s) => key.toLowerCase().includes(s))) {
            obj[key] = '***REDACTED***';
          } else if (typeof obj[key] === 'object') {
            removeSensitive(obj[key]);
          }
        }
      };
      removeSensitive(sanitized);
      return sanitized;
    } catch {
      return { sanitized: true };
    }
  }

  private mapToRecord(prismaRecord: any): WebhookEventRecord {
    return {
      id: prismaRecord.id,
      provider: prismaRecord.provider as PaymentProvider,
      providerEventId: prismaRecord.providerEventId,
      eventType: prismaRecord.eventType,
      eventCategory: prismaRecord.eventCategory as any,
      providerPaymentId: prismaRecord.providerPaymentId || null,
      providerCheckoutId: prismaRecord.providerCheckoutId || null,
      eventHash: prismaRecord.eventHash,
      payload: prismaRecord.payload || null,
      signature: prismaRecord.signature || null,
      processingStatus: prismaRecord.processingStatus as WebhookProcessingStatus,
      processingAttempts: prismaRecord.processingAttempts,
      lastProcessingError: prismaRecord.lastProcessingError || null,
      processedAt: prismaRecord.processedAt || null,
      paymentId: prismaRecord.paymentId || null,
      tenantId: prismaRecord.tenantId || null,
      receivedAt: prismaRecord.receivedAt,
      firstSeenAt: prismaRecord.firstSeenAt,
      createdAt: prismaRecord.createdAt,
      updatedAt: prismaRecord.updatedAt,
    };
  }

  private createFallbackRecord(event: NormalizedWebhookEvent, eventHash: string): WebhookEventRecord {
    const now = new Date();
    return {
      id: this.generateId(),
      provider: event.provider,
      providerEventId: event.providerEventId,
      eventType: event.eventType,
      eventCategory: event.eventCategory,
      providerPaymentId: event.providerPaymentId || null,
      providerCheckoutId: event.providerCheckoutId || null,
      eventHash,
      payload: null,
      signature: null,
      processingStatus: WebhookProcessingStatus.RECEIVED,
      processingAttempts: 0,
      lastProcessingError: null,
      processedAt: null,
      paymentId: null,
      tenantId: event.metadata?.tenantId || null,
      receivedAt: event.receivedAt,
      firstSeenAt: now,
      createdAt: now,
      updatedAt: now,
    };
  }

  private generateId(): string {
    try {
      return randomUUID();
    } catch {
      return `${Date.now()}-${Math.random().toString(36).substring(2, 15)}`;
    }
  }
}

// # Contract-tests the signed billing webhook pipeline and exact payment normalization wiring
import { AppException } from '../../../common/errors/app.exception';
import { PaymentProvider, PaymentStatus } from './payment.types';
import { WebhookEventCategory, WebhookProcessingStatus } from './webhook.types';
import { stripeMinorUnitsToDecimalString } from './stripe.adapter';
import { WebhookService } from './webhook.service';

type WebhookEvent = Record<string, unknown>;

function nowPaymentsEvent(overrides: Record<string, unknown> = {}): WebhookEvent {
  return {
    payment_id: 'np-payment-123',
    order_id: 'order-123',
    payment_status: 'finished',
    price_amount: '1.230000000000000001',
    price_currency: 'usdt',
    confirmations: 8,
    created_at: '2026-10-08T00:00:00.123456Z',
    ...overrides,
  };
}

function normalizedProviderEvent(
  provider: PaymentProvider,
  overrides: Record<string, unknown> = {},
): Record<string, unknown> {
  return {
    provider,
    providerEventId: provider === PaymentProvider.NOWPAYMENTS ? 'np-payment-123' : 'evt-stripe-123',
    eventType: provider === PaymentProvider.NOWPAYMENTS ? 'finished' : 'checkout.session.completed',
    eventCategory: WebhookEventCategory.PAYMENT_SUCCEEDED,
    paymentStatus: PaymentStatus.PENDING,
    providerPaymentId: provider === PaymentProvider.NOWPAYMENTS ? 'np-payment-123' : 'pi-stripe-123',
    providerCheckoutId: provider === PaymentProvider.STRIPE ? 'cs-stripe-123' : undefined,
    amount: { amount: '1.23', currency: provider === PaymentProvider.NOWPAYMENTS ? 'USDT' : 'USD' },
    metadata: { tenantId: 'tenant-123', orderId: 'order-123' },
    rawEvent: { sanitized: true },
    receivedAt: new Date('2026-10-08T00:00:01.000Z'),
    providerCreatedAt: new Date('2026-10-08T00:00:00.000Z'),
    ...overrides,
  };
}

function buildHarness(options: {
  provider?: PaymentProvider;
  rawEvent?: WebhookEvent;
  verified?: boolean;
  payment?: Record<string, unknown> | null;
  providerNormalizedEvent?: Record<string, unknown>;
} = {}) {
  const provider = options.provider ?? PaymentProvider.NOWPAYMENTS;
  const rawEvent = options.rawEvent ?? nowPaymentsEvent();
  const providerAdapter = {
    normalizeWebhookEvent: jest.fn(async () =>
      options.providerNormalizedEvent ?? normalizedProviderEvent(provider),
    ),
  };
  const signatureService = {
    verifySignature: jest.fn(async () => options.verified === false
      ? {
          verified: false,
          provider,
          providerEventId: 'event-verified-by-signature-service',
          failureReason: 'Invalid signature',
        }
      : {
          verified: true,
          provider,
          providerEventId: provider === PaymentProvider.NOWPAYMENTS ? 'np-payment-123' : 'evt-stripe-123',
          eventType: provider === PaymentProvider.NOWPAYMENTS ? 'finished' : 'checkout.session.completed',
          rawEvent,
        }),
  };
  const eventRecord = { id: 'webhook-record-123' };
  const replayGuard = {
    recordEventReceived: jest.fn(async () => eventRecord),
    markEventVerified: jest.fn(async () => undefined),
    checkReplay: jest.fn(async (_event: unknown) => ({
      isDuplicate: false,
      isReplay: false,
      shouldProcess: true,
      reason: 'new event',
    })),
    markEventProcessing: jest.fn(async () => undefined),
    markEventProcessed: jest.fn(async () => undefined),
    markEventFailed: jest.fn(async () => undefined),
    markEventRejected: jest.fn(async () => undefined),
    markEventDuplicate: jest.fn(async () => undefined),
  };
  const payment = options.payment === undefined
    ? {
        id: 'internal-payment-123',
        tenantId: 'tenant-123',
        planId: 'plan-123',
        subscriptionId: 'subscription-123',
        userId: 'user-123',
        amount: '1.230000000000000001',
        currency: provider === PaymentProvider.NOWPAYMENTS ? 'USDT' : 'USD',
        providerPaymentId: provider === PaymentProvider.NOWPAYMENTS ? 'np-payment-123' : 'pi-stripe-123',
        providerCheckoutId: provider === PaymentProvider.STRIPE ? 'cs-stripe-123' : null,
        providerSessionId: null,
        providerInvoiceId: null,
        idempotencyKey: 'checkout-idempotency-123',
        orderId: 'order-123',
        planCode: 'PRO',
        planName: 'Pro',
        status: PaymentStatus.PENDING,
      }
    : options.payment;
  const paymentService = {
    getPaymentByProviderId: jest.fn(async () => payment),
    getPaymentByCheckoutId: jest.fn(async () => null),
    getPaymentByOrderId: jest.fn(async () => null),
    getPaymentByIdempotencyKey: jest.fn(async () => null),
    applyProviderResult: jest.fn(async (_paymentId: string, result: Record<string, unknown>) => ({
      ...payment,
      status: result.status,
    })),
  };
  const providerFactory = { getProvider: jest.fn(() => providerAdapter) };
  const subscriptionSync = { syncPaymentToSubscription: jest.fn(async () => undefined) };
  const audit = { logWebhookEvent: jest.fn(async () => undefined) };
  const service = new WebhookService(
    signatureService as any,
    replayGuard as any,
    paymentService as any,
    providerFactory as any,
    subscriptionSync as any,
    audit as any,
  );
  const payload = {
    provider,
    rawBody: Buffer.from(JSON.stringify(rawEvent)),
    signature: 'signed-provider-payload',
    headers: {},
  };
  return {
    service,
    payload,
    rawEvent,
    providerAdapter,
    signatureService,
    replayGuard,
    paymentService,
    providerFactory,
    subscriptionSync,
    audit,
  };
}

describe('Billing WebhookService canonical payment normalization contract', () => {
  it('converts safe Stripe minor-unit integers using the currency exponent without floating-point arithmetic', () => {
    expect(stripeMinorUnitsToDecimalString(12345, 'USD')).toBe('123.45');
    expect(stripeMinorUnitsToDecimalString(12345, 'JPY')).toBe('12345');
    expect(stripeMinorUnitsToDecimalString(12345, 'KWD')).toBe('12.345');
    expect(() => stripeMinorUnitsToDecimalString(1.5, 'USD')).toThrow(/safe integer/);
    expect(() => stripeMinorUnitsToDecimalString(100, 'ZZZ')).toThrow(/exponent is not configured/);
  });

  it('normalizes exact NOWPayments values only after signature verification and uses them for state application', async () => {
    const harness = buildHarness();
    const result = await harness.service.processWebhook(harness.payload as any);
    const verifiedAt = harness.signatureService.verifySignature.mock.invocationCallOrder[0];
    const normalizedAt = harness.providerAdapter.normalizeWebhookEvent.mock.invocationCallOrder[0];
    const replayEvent = harness.replayGuard.checkReplay.mock.calls[0][0];

    expect(verifiedAt).toBeLessThan(normalizedAt);
    expect(replayEvent).toMatchObject({
      provider: PaymentProvider.NOWPAYMENTS,
      paymentStatus: PaymentStatus.SUCCEEDED,
      eventCategory: WebhookEventCategory.PAYMENT_SUCCEEDED,
      providerPaymentId: 'np-payment-123',
      amount: { amount: '1.230000000000000001', currency: 'USDT' },
      metadata: {
        canonicalPaymentStatus: 'CONFIRMED',
        paymentConfirmations: 8,
        paymentOccurredAtIso: '2026-10-08T00:00:00.123Z',
      },
    });
    expect(harness.paymentService.applyProviderResult).toHaveBeenCalledWith(
      'internal-payment-123',
      expect.objectContaining({
        status: PaymentStatus.SUCCEEDED,
        amount: '1.230000000000000001',
      }),
    );
    expect(harness.subscriptionSync.syncPaymentToSubscription).toHaveBeenCalledTimes(1);
    expect(result).toMatchObject({
      success: true,
      processingStatus: WebhookProcessingStatus.PROCESSED,
      paymentId: 'internal-payment-123',
    });
  });

  it('converts Stripe integer minor units to exact decimal strings before applying the verified event', async () => {
    const created = Math.floor(Date.parse('2026-10-08T00:00:00.000Z') / 1000);
    const rawEvent = {
      id: 'evt-stripe-123',
      type: 'checkout.session.completed',
      created,
      data: {
        object: {
          id: 'cs-stripe-123',
          payment_intent: { id: 'pi-stripe-123' },
          payment_status: 'paid',
          amount_total: 12345,
          currency: 'usd',
        },
      },
    };
    const harness = buildHarness({
      provider: PaymentProvider.STRIPE,
      rawEvent,
      providerNormalizedEvent: normalizedProviderEvent(PaymentProvider.STRIPE, {
        providerPaymentId: { id: 'pi-stripe-123' },
        paymentStatus: PaymentStatus.PENDING,
        amount: { amount: '123.44999999999999', currency: 'USD' },
      }),
      payment: {
        id: 'internal-payment-123',
        tenantId: 'tenant-123',
        planId: 'plan-123',
        subscriptionId: 'subscription-123',
        userId: 'user-123',
        amount: '123.45',
        currency: 'USD',
        providerPaymentId: 'pi-stripe-123',
        providerCheckoutId: 'cs-stripe-123',
        providerSessionId: 'cs-stripe-123',
        providerInvoiceId: null,
        idempotencyKey: 'checkout-idempotency-123',
        orderId: 'order-123',
        planCode: 'PRO',
        planName: 'Pro',
        status: PaymentStatus.PENDING,
      },
    });

    await harness.service.processWebhook(harness.payload as any);

    const stripeReplayEvent = harness.replayGuard.checkReplay.mock.calls[0][0] as Record<string, unknown>;
    expect(stripeReplayEvent).toMatchObject({
      paymentStatus: PaymentStatus.SUCCEEDED,
      amount: { amount: '123.45', currency: 'USD' },
    });
    expect(stripeReplayEvent.providerCreatedAt).toEqual(new Date('2026-10-08T00:00:00.000Z'));
    expect(harness.paymentService.getPaymentByProviderId).toHaveBeenCalledWith(
      'pi-stripe-123',
      PaymentProvider.STRIPE,
    );
    expect(harness.paymentService.applyProviderResult).toHaveBeenCalledWith(
      'internal-payment-123',
      expect.objectContaining({ status: PaymentStatus.SUCCEEDED }),
    );
  });

  it('withholds a confirmed transition when exact amount or currency differs from the internal payment', async () => {
    const harness = buildHarness({
      payment: {
        id: 'internal-payment-123',
        tenantId: 'tenant-123',
        planId: 'plan-123',
        subscriptionId: 'subscription-123',
        userId: 'user-123',
        amount: '1.230000000000000002',
        currency: 'USDT',
        providerPaymentId: 'np-payment-123',
        providerCheckoutId: null,
        providerSessionId: null,
        providerInvoiceId: null,
        idempotencyKey: 'checkout-idempotency-123',
        orderId: 'order-123',
        planCode: 'PRO',
        planName: 'Pro',
        status: PaymentStatus.PENDING,
      },
    });

    await expect(harness.service.processWebhook(harness.payload as any)).rejects.toBeInstanceOf(AppException);
    expect(harness.paymentService.applyProviderResult).not.toHaveBeenCalled();
    expect(harness.subscriptionSync.syncPaymentToSubscription).not.toHaveBeenCalled();
    expect(harness.replayGuard.markEventFailed).toHaveBeenCalledWith(
      PaymentProvider.NOWPAYMENTS,
      'np-payment-123',
      expect.stringContaining('does not match'),
    );
  });

  it('withholds unknown provider states instead of treating them as pending or successful', async () => {
    const harness = buildHarness({
      rawEvent: nowPaymentsEvent({ payment_status: 'new-provider-state' }),
    });

    await expect(harness.service.processWebhook(harness.payload as any)).rejects.toBeInstanceOf(AppException);
    expect(harness.replayGuard.checkReplay.mock.calls[0][0]).toMatchObject({
      paymentStatus: PaymentStatus.UNKNOWN,
      eventCategory: WebhookEventCategory.UNKNOWN,
      metadata: { canonicalPaymentStatus: 'UNKNOWN' },
    });
    expect(harness.paymentService.getPaymentByProviderId).not.toHaveBeenCalled();
    expect(harness.paymentService.applyProviderResult).not.toHaveBeenCalled();
    expect(harness.replayGuard.markEventFailed).toHaveBeenCalledWith(
      PaymentProvider.NOWPAYMENTS,
      'np-payment-123',
      expect.stringContaining('Unrecognized provider payment status'),
    );
  });

  it('withholds a verified state transition when provider event time is absent', async () => {
    const harness = buildHarness({ rawEvent: nowPaymentsEvent({ created_at: null }) });

    await expect(harness.service.processWebhook(harness.payload as any)).rejects.toMatchObject({
      code: 'VALIDATION_ERROR',
      message: 'Failed to normalize webhook event',
    });
    expect(harness.providerFactory.getProvider).not.toHaveBeenCalled();
    expect(harness.paymentService.applyProviderResult).not.toHaveBeenCalled();
    expect(harness.replayGuard.markEventFailed).toHaveBeenCalledWith(
      PaymentProvider.NOWPAYMENTS,
      'np-payment-123',
      expect.stringContaining('missing provider timestamp'),
    );
  });

  it('does not normalize or dispatch an invalid-signature payload', async () => {
    const harness = buildHarness({
      rawEvent: nowPaymentsEvent({ price_amount: 1.23 }),
      verified: false,
    });

    await expect(harness.service.processWebhook(harness.payload as any)).rejects.toMatchObject({
      code: 'UNAUTHORIZED',
    });
    expect(harness.providerFactory.getProvider).not.toHaveBeenCalled();
    expect(harness.providerAdapter.normalizeWebhookEvent).not.toHaveBeenCalled();
    expect(harness.replayGuard.recordEventReceived).not.toHaveBeenCalled();
    expect(harness.paymentService.applyProviderResult).not.toHaveBeenCalled();
  });

  it('rejects lossy numeric provider amounts after verification rather than coercing them', async () => {
    const harness = buildHarness({ rawEvent: nowPaymentsEvent({ price_amount: 1.23 }) });

    await expect(harness.service.processWebhook(harness.payload as any)).rejects.toMatchObject({
      code: 'VALIDATION_ERROR',
      message: 'Failed to normalize webhook event',
    });
    expect(harness.signatureService.verifySignature).toHaveBeenCalledTimes(1);
    expect(harness.providerAdapter.normalizeWebhookEvent).not.toHaveBeenCalled();
    expect(harness.paymentService.applyProviderResult).not.toHaveBeenCalled();
    expect(harness.replayGuard.markEventFailed).toHaveBeenCalledWith(
      PaymentProvider.NOWPAYMENTS,
      'np-payment-123',
      expect.stringContaining('exact decimal string'),
    );
  });
});

import { Injectable, Logger } from '@nestjs/common';
import { WebhookSignatureService } from './webhook.signature';
import { WebhookReplayGuard } from './webhook.replay-guard';
import { PaymentService } from './payment.service';
import { PaymentProviderFactory } from './payment-provider.factory';
import { PaymentSubscriptionSyncService } from './payment-subscription-sync.service';
import { PaymentEventsAuditService } from './payment-events.audit';
import { PaymentProvider, PaymentStatus } from './payment.types';
import { stripeMinorUnitsToDecimalString } from './stripe.adapter';
import type { WebhookPayload, WebhookProcessingResult, NormalizedWebhookEvent } from './webhook.types';
import { WebhookEventCategory, WebhookProcessingStatus } from './webhook.types';
import { normalizePaymentWebhookPayload } from '../../providers/adapters/payment.adapter';
import type { NormalizedPaymentWebhookEvent } from '../../providers/adapters/payment.adapter';
import { Decimal } from '../../../common/decimal-string';
import { AppException } from '../../../common/errors/app.exception';
import { ErrorCode } from '@wlct/shared-types';

/**
 * Validates, normalizes, deduplicates, and dispatches provider webhooks
 * into payment/subscription state transitions.
 *
 * Flow:
 *  raw body → signature verification → event ID extraction
 *  → replay/idempotency check → event normalization
 *  → state validation → payment update → subscription synchronization
 *
 * Must be idempotent and replay-safe.
 */

@Injectable()
export class WebhookService {
  private readonly logger = new Logger(WebhookService.name);

  constructor(
    private readonly signatureService: WebhookSignatureService,
    private readonly replayGuard: WebhookReplayGuard,
    private readonly paymentService: PaymentService,
    private readonly providerFactory: PaymentProviderFactory,
    private readonly subscriptionSync: PaymentSubscriptionSyncService,
    private readonly audit: PaymentEventsAuditService,
  ) {}

  async processWebhook(payload: WebhookPayload): Promise<WebhookProcessingResult> {
    const provider = payload.provider;
    const startTime = Date.now();

    this.logger.log(`Webhook received: provider=${provider}, signaturePresent=${!!payload.signature}`);

    // Step 1: Verify signature - DO NOT process unverified payloads
    const verificationResult = await this.signatureService.verifySignature(payload);

    if (!verificationResult.verified) {
      this.logger.warn(`Webhook signature verification failed for ${provider}: ${verificationResult.failureReason}`);

      await this.audit.logWebhookEvent({
        provider,
        providerEventId: verificationResult.providerEventId || 'unknown',
        action: 'WEBHOOK_REJECTED',
        result: 'REJECTED',
        error: verificationResult.failureReason,
        metadata: { reason: 'signature_verification_failed' },
      });

      await this.replayGuard.markEventRejected(provider, verificationResult.providerEventId || 'unknown', verificationResult.failureReason || 'Signature verification failed');

      throw new AppException({
        code: ErrorCode.UNAUTHORIZED,
        message: 'Webhook signature verification failed',
        context: { provider, reason: verificationResult.failureReason },
      });
    }

    const providerEventId = verificationResult.providerEventId!;
    const rawEvent = verificationResult.rawEvent;

    await this.audit.logWebhookEvent({
      provider,
      providerEventId,
      action: 'WEBHOOK_RECEIVED',
      result: 'RECEIVED',
      eventType: verificationResult.eventType,
    });

    // Step 2: Record event received
    const eventRecord = await this.replayGuard.recordEventReceived(
      {
        provider,
        providerEventId,
        eventType: verificationResult.eventType || 'unknown',
        eventCategory: 'UNKNOWN' as any,
        paymentStatus: 'UNKNOWN' as any,
        receivedAt: new Date(),
        providerCreatedAt: null,
      } as NormalizedWebhookEvent,
      rawEvent,
      payload.signature,
    );

    // Step 3: Normalize only after signature verification has succeeded.
    let normalizedEvent: NormalizedWebhookEvent;
    let canonicalPaymentEvent: NormalizedPaymentWebhookEvent | undefined;
    try {
      canonicalPaymentEvent = normalizeVerifiedPaymentEvent(provider, rawEvent);
      if (canonicalPaymentEvent && canonicalPaymentEvent.occurredAtIso === null) {
        throw new TypeError('Verified payment event is missing provider timestamp; state update withheld');
      }
      const providerAdapter = this.providerFactory.getProvider(provider);
      normalizedEvent = await providerAdapter.normalizeWebhookEvent({
        rawEvent,
        provider,
      });
      if (canonicalPaymentEvent) {
        normalizedEvent = applyCanonicalPaymentEvent(normalizedEvent, canonicalPaymentEvent);
      }

      await this.replayGuard.markEventVerified(provider, providerEventId);
    } catch (error) {
      this.logger.error(`Webhook event normalization failed for ${provider}:${providerEventId}: ${(error as Error).message}`);

      await this.replayGuard.markEventFailed(provider, providerEventId, (error as Error).message);

      await this.audit.logWebhookEvent({
        provider,
        providerEventId,
        action: 'WEBHOOK_REJECTED',
        result: 'FAILED',
        error: (error as Error).message,
        metadata: { stage: 'normalization' },
      });

      throw new AppException({
        code: ErrorCode.VALIDATION_ERROR,
        message: 'Failed to normalize webhook event',
        context: { provider, providerEventId },
      });
    }

    // Step 4: Replay/idempotency check - same event must not apply transition twice
    const replayCheck = await this.replayGuard.checkReplay(normalizedEvent);

    if (!replayCheck.shouldProcess) {
      if (replayCheck.isDuplicate || replayCheck.isReplay) {
        this.logger.log(`Webhook duplicate/replay rejected: ${provider}:${providerEventId} - ${replayCheck.reason}`);

        await this.replayGuard.markEventDuplicate(provider, providerEventId);

        await this.audit.logWebhookEvent({
          provider,
          providerEventId,
          action: 'WEBHOOK_DUPLICATE',
          result: 'DUPLICATE',
          eventType: normalizedEvent.eventType,
          metadata: { reason: replayCheck.reason },
        });

        return {
          success: true,
          eventId: eventRecord.id,
          providerEventId,
          processingStatus: WebhookProcessingStatus.DUPLICATE,
          isDuplicate: true,
          isReplay: replayCheck.isReplay,
        };
      }

      // Rejected for other reason (too old, etc)
      this.logger.warn(`Webhook rejected: ${provider}:${providerEventId} - ${replayCheck.reason}`);

      await this.audit.logWebhookEvent({
        provider,
        providerEventId,
        action: 'WEBHOOK_REJECTED',
        result: 'REJECTED',
        eventType: normalizedEvent.eventType,
        metadata: { reason: replayCheck.reason },
      });

      return {
        success: false,
        eventId: eventRecord.id,
        providerEventId,
        processingStatus: WebhookProcessingStatus.REJECTED,
        error: replayCheck.reason,
      };
    }

    // Step 5: Mark as processing
    await this.replayGuard.markEventProcessing(provider, providerEventId);

    // Step 6: Find internal payment record
    let internalPaymentId: string | undefined = undefined;
    let tenantId: string | undefined = undefined;

    try {
      if (canonicalPaymentEvent?.status === 'UNKNOWN') {
        throw new AppException({
          code: ErrorCode.VALIDATION_ERROR,
          message: 'Unrecognized provider payment status; payment state update withheld',
          context: { provider, providerEventId },
        });
      }

      const payment = await this.findInternalPayment(normalizedEvent);

      if (!payment) {
        this.logger.warn(`No internal payment found for webhook ${provider}:${providerEventId}, paymentId ${normalizedEvent.providerPaymentId}`);

        // For checkout.session.completed events, we might need to find by checkout ID
        // If still not found, we log and mark as processed but without sync
        await this.replayGuard.markEventProcessed(provider, providerEventId);

        await this.audit.logWebhookEvent({
          provider,
          providerEventId,
          action: 'WEBHOOK_PROCESSED',
          result: 'PROCESSED_NO_PAYMENT',
          eventType: normalizedEvent.eventType,
          metadata: { reason: 'no_internal_payment_found' },
        });

        return {
          success: true,
          eventId: eventRecord.id,
          providerEventId,
          processingStatus: WebhookProcessingStatus.PROCESSED,
        };
      }

      internalPaymentId = payment.id;
      tenantId = payment.tenantId;

      // A provider-confirmed checkout must match the canonical internal amount and currency exactly.
      // The provider amount is evidence only; the internal record remains the amount applied downstream.
      if (
        canonicalPaymentEvent?.status === 'CONFIRMED' &&
        !matchesExpectedPaymentAmount(payment.amount, payment.currency, canonicalPaymentEvent)
      ) {
        throw new AppException({
          code: ErrorCode.VALIDATION_ERROR,
          message: 'Provider-confirmed payment amount or currency does not match the internal payment record',
          context: { provider, providerEventId, paymentId: payment.id },
        });
      }

      // Step 7: Apply normalized payment state with valid transition check
      const updatedPayment = await this.paymentService.applyProviderResult(payment.id, {
        internalPaymentId: payment.id,
        provider,
        status: normalizedEvent.paymentStatus,
        transactionState: this.mapPaymentStatusToTransactionState(normalizedEvent.paymentStatus),
        amount: payment.amount as any,
        providerReference: {
          provider,
          providerPaymentId: normalizedEvent.providerPaymentId || payment.providerPaymentId || '',
          providerCheckoutId: normalizedEvent.providerCheckoutId || payment.providerCheckoutId || undefined,
          providerSessionId: normalizedEvent.providerSessionId || payment.providerSessionId || undefined,
          providerInvoiceId: normalizedEvent.providerInvoiceId || payment.providerInvoiceId || undefined,
        },
        references: {
          tenantId: payment.tenantId,
          planId: payment.planId,
          subscriptionId: payment.subscriptionId || undefined,
          userId: payment.userId || undefined,
          idempotencyKey: payment.idempotencyKey,
          orderId: payment.orderId || undefined,
        },
        metadata: {
          planCode: payment.planCode || undefined,
          planName: payment.planName || undefined,
        },
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        rawProviderStatus: normalizedEvent.eventType,
      } as any);

      // Step 8: Synchronize into TenantSubscription lifecycle
      try {
        await this.subscriptionSync.syncPaymentToSubscription(updatedPayment);

        this.logger.log(`Payment ${payment.id} synced to subscription, new status ${updatedPayment.status}`);
      } catch (syncError) {
        this.logger.error(`Subscription sync failed for payment ${payment.id}: ${(syncError as Error).message}`);
        // Don't fail webhook processing if sync fails - payment is still updated
        // Sync can be retried via reconciliation
      }

      // Step 9: Mark as processed
      await this.replayGuard.markEventProcessed(provider, providerEventId, internalPaymentId, tenantId);

      await this.audit.logWebhookEvent({
        provider,
        providerEventId,
        action: 'WEBHOOK_PROCESSED',
        result: 'PROCESSED',
        eventType: normalizedEvent.eventType,
        paymentId: internalPaymentId,
        tenantId: tenantId,
        status: normalizedEvent.paymentStatus,
        metadata: {
          providerPaymentId: normalizedEvent.providerPaymentId,
          processingTimeMs: Date.now() - startTime,
        },
      });

      this.logger.log(`Webhook processed successfully: ${provider}:${providerEventId} → payment ${internalPaymentId} status ${normalizedEvent.paymentStatus}`);

      return {
        success: true,
        eventId: eventRecord.id,
        providerEventId,
        processingStatus: WebhookProcessingStatus.PROCESSED,
        paymentId: internalPaymentId,
        tenantId: tenantId,
        newPaymentStatus: normalizedEvent.paymentStatus,
      };
    } catch (error) {
      this.logger.error(`Webhook processing failed for ${provider}:${providerEventId}: ${(error as Error).message}`);

      await this.replayGuard.markEventFailed(provider, providerEventId, (error as Error).message);

      await this.audit.logWebhookEvent({
        provider,
        providerEventId,
        action: 'WEBHOOK_REJECTED',
        result: 'FAILED',
        eventType: normalizedEvent.eventType,
        paymentId: internalPaymentId,
        tenantId: tenantId,
        error: (error as Error).message,
        metadata: { stage: 'processing', processingTimeMs: Date.now() - startTime },
      });

      if (error instanceof AppException) {
        throw error;
      }

      throw new AppException({
        code: ErrorCode.INTERNAL_SERVER_ERROR,
        message: 'Webhook processing failed',
        context: { provider, providerEventId },
      });
    }
  }

  private async findInternalPayment(event: NormalizedWebhookEvent): Promise<any | null> {
    // Try to find by provider payment ID
    if (event.providerPaymentId) {
      const byPaymentId = await this.paymentService.getPaymentByProviderId(event.providerPaymentId, event.provider);
      if (byPaymentId) return byPaymentId;
    }

    // Try by checkout ID
    if (event.providerCheckoutId) {
      const byCheckoutId = await this.paymentService.getPaymentByCheckoutId(event.providerCheckoutId, event.provider);
      if (byCheckoutId) return byCheckoutId;
    }

    // Try by order ID from metadata
    if (event.metadata?.orderId) {
      const byOrderId = await this.paymentService.getPaymentByOrderId(event.metadata.orderId);
      if (byOrderId) return byOrderId;
    }

    // Try by idempotency key from metadata
    if (event.metadata?.idempotencyKey && event.metadata?.tenantId) {
      const byIdempotency = await this.paymentService.getPaymentByIdempotencyKey(event.metadata.idempotencyKey, event.metadata.tenantId);
      if (byIdempotency) return byIdempotency;
    }

    return null;
  }

  private mapPaymentStatusToTransactionState(status: any): any {
    // Simplified mapping
    switch (status) {
      case 'SUCCEEDED':
        return 'CAPTURED';
      case 'PENDING':
      case 'PROCESSING':
        return 'AUTHORIZED';
      case 'FAILED':
      case 'EXPIRED':
        return 'FAILED';
      case 'CANCELLED':
        return 'VOIDED';
      case 'REFUNDED':
      case 'PARTIALLY_REFUNDED':
        return 'REFUNDED';
      default:
        return 'INITIALIZED';
    }
  }
}

const STRIPE_PAYMENT_EVENT_TYPES = new Set([
  'checkout.session.completed',
  'checkout.session.expired',
  'checkout.session.async_payment_succeeded',
  'checkout.session.async_payment_failed',
  'payment_intent.created',
  'payment_intent.processing',
  'payment_intent.requires_action',
  'payment_intent.succeeded',
  'payment_intent.payment_failed',
  'payment_intent.canceled',
  'charge.succeeded',
  'charge.failed',
  'charge.refunded',
  'invoice.paid',
  'invoice.payment_succeeded',
  'invoice.payment_failed',
]);

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function readNonEmptyString(value: unknown): string | undefined {
  return typeof value === 'string' && value.trim() !== '' ? value.trim() : undefined;
}

function requireExternalPaymentId(value: unknown): string {
  if (typeof value === 'string' && value.trim() !== '') return value.trim();
  if (typeof value === 'number' && Number.isSafeInteger(value) && value > 0) return String(value);
  throw new TypeError('Verified payment event is missing a valid external payment id');
}

function readExternalReference(value: unknown): string | undefined {
  if (value === null || value === undefined) return undefined;
  if (typeof value === 'string') {
    if (value.trim() === '') throw new TypeError('Stripe payment reference must not be empty');
    return value.trim();
  }
  if (typeof value === 'number') {
    if (!Number.isSafeInteger(value) || value <= 0) {
      throw new TypeError('Stripe numeric payment reference must be a positive safe integer');
    }
    return String(value);
  }
  if (isRecord(value)) return requireExternalPaymentId(value.id);
  throw new TypeError('Stripe payment reference has an unsupported type');
}

function normalizeVerifiedPaymentEvent(
  provider: PaymentProvider,
  rawEvent: unknown,
): NormalizedPaymentWebhookEvent | undefined {
  if (provider === PaymentProvider.NOWPAYMENTS) {
    if (!isRecord(rawEvent)) throw new TypeError('Verified NOWPayments event must be an object');
    return normalizePaymentWebhookPayload({
      provider: 'NOWPAYMENTS',
      id: requireExternalPaymentId(rawEvent.payment_id ?? rawEvent.id),
      status: rawEvent.payment_status as string,
      amount: rawEvent.price_amount as string,
      currency: rawEvent.price_currency as string,
      confirmations: (rawEvent.confirmations ?? null) as number | null,
      timestamp: (rawEvent.created_at ?? rawEvent.timestamp ?? null) as string | null,
    });
  }

  if (provider !== PaymentProvider.STRIPE || !isRecord(rawEvent)) return undefined;
  const eventType = readNonEmptyString(rawEvent.type);
  if (!eventType || !STRIPE_PAYMENT_EVENT_TYPES.has(eventType)) return undefined;

  const data = isRecord(rawEvent.data) ? rawEvent.data : undefined;
  const object = data && isRecord(data.object) ? data.object : undefined;
  if (!object) throw new TypeError('Verified Stripe payment event is missing its data object');

  const paymentReference = readExternalReference(object.payment_intent) ?? readExternalReference(object.id);
  if (!paymentReference) throw new TypeError('Verified Stripe payment event is missing its payment reference');
  const currency = object.currency as string;
  const amount = stripeMinorUnitsToDecimalString(stripeMinorAmount(eventType, object), currency);
  const status = stripePaymentStatus(eventType, object);
  const timestamp = stripeTimestamp(rawEvent.created);
  const confirmations = object.confirmations ?? null;

  return normalizePaymentWebhookPayload({
    provider: 'STRIPE',
    id: paymentReference,
    status,
    amount,
    currency,
    confirmations: confirmations as number | null,
    timestamp,
  });
}

function stripePaymentStatus(eventType: string, object: Record<string, unknown>): string {
  if (eventType === 'checkout.session.completed') {
    const paymentStatus = readNonEmptyString(object.payment_status);
    if (!paymentStatus) throw new TypeError('Completed Stripe checkout event is missing payment_status');
    return paymentStatus;
  }

  const eventStatuses: Record<string, string> = {
    'checkout.session.expired': 'expired',
    'checkout.session.async_payment_succeeded': 'succeeded',
    'checkout.session.async_payment_failed': 'failed',
    'payment_intent.succeeded': 'succeeded',
    'payment_intent.payment_failed': 'failed',
    'payment_intent.canceled': 'cancelled',
    'charge.succeeded': 'succeeded',
    'charge.failed': 'failed',
    'charge.refunded': 'refunded',
    'invoice.paid': 'paid',
    'invoice.payment_succeeded': 'paid',
    'invoice.payment_failed': 'failed',
  };
  const eventStatus = eventStatuses[eventType];
  if (eventStatus) return eventStatus;

  const objectStatus = readNonEmptyString(object.status) ?? readNonEmptyString(object.payment_status);
  if (!objectStatus) throw new TypeError(`Stripe ${eventType} event is missing a payment status`);
  return objectStatus;
}

function stripeMinorAmount(eventType: string, object: Record<string, unknown>): unknown {
  if (eventType.startsWith('checkout.session.')) return object.amount_total;
  if (eventType.startsWith('payment_intent.')) {
    if (eventType === 'payment_intent.succeeded') return object.amount_received ?? object.amount;
    return object.amount;
  }
  if (eventType === 'charge.refunded') return object.amount_refunded;
  if (eventType.startsWith('charge.')) return object.amount;
  if (eventType === 'invoice.paid' || eventType === 'invoice.payment_succeeded') {
    return object.amount_paid ?? object.total;
  }
  if (eventType === 'invoice.payment_failed') return object.amount_due ?? object.total;
  return undefined;
}

function stripeTimestamp(value: unknown): string | null {
  if (value === null || value === undefined) return null;
  if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < 0) {
    throw new TypeError('Stripe event timestamp must be a non-negative safe integer in Unix seconds');
  }
  const milliseconds = value * 1000;
  if (!Number.isSafeInteger(milliseconds)) throw new TypeError('Stripe event timestamp is outside the supported range');
  const date = new Date(milliseconds);
  if (!Number.isFinite(date.getTime())) throw new TypeError('Stripe event timestamp is invalid');
  return date.toISOString();
}

function applyCanonicalPaymentEvent(
  event: NormalizedWebhookEvent,
  canonical: NormalizedPaymentWebhookEvent,
): NormalizedWebhookEvent {
  const paymentStatus = mapCanonicalPaymentStatus(canonical.status, event.paymentStatus);
  const eventCategory = mapCanonicalEventCategory(canonical.status);
  return {
    ...event,
    eventCategory,
    paymentStatus,
    providerPaymentId: canonical.externalPaymentId || event.providerPaymentId,
    amount: { amount: canonical.amount, currency: canonical.currency },
    metadata: {
      ...event.metadata,
      canonicalPaymentStatus: canonical.status,
      paymentConfirmations: canonical.confirmations,
      paymentOccurredAtIso: canonical.occurredAtIso,
    },
    providerCreatedAt: canonical.occurredAtIso === null ? null : new Date(canonical.occurredAtIso),
  };
}

function mapCanonicalPaymentStatus(
  canonicalStatus: NormalizedPaymentWebhookEvent['status'],
  providerAdapterStatus: PaymentStatus,
): PaymentStatus {
  switch (canonicalStatus) {
    case 'CONFIRMED':
      return PaymentStatus.SUCCEEDED;
    case 'PENDING':
      return providerAdapterStatus === PaymentStatus.PROCESSING
        ? PaymentStatus.PROCESSING
        : PaymentStatus.PENDING;
    case 'FAILED':
      return providerAdapterStatus === PaymentStatus.CANCELLED || providerAdapterStatus === PaymentStatus.EXPIRED
        ? providerAdapterStatus
        : PaymentStatus.FAILED;
    case 'REFUNDED':
      return providerAdapterStatus === PaymentStatus.PARTIALLY_REFUNDED
        ? PaymentStatus.PARTIALLY_REFUNDED
        : PaymentStatus.REFUNDED;
    case 'UNKNOWN':
      return PaymentStatus.UNKNOWN;
  }
}

function mapCanonicalEventCategory(
  canonicalStatus: NormalizedPaymentWebhookEvent['status'],
): WebhookEventCategory {
  switch (canonicalStatus) {
    case 'CONFIRMED':
      return WebhookEventCategory.PAYMENT_SUCCEEDED;
    case 'PENDING':
      return WebhookEventCategory.PAYMENT_PENDING;
    case 'FAILED':
      return WebhookEventCategory.PAYMENT_FAILED;
    case 'REFUNDED':
      return WebhookEventCategory.PAYMENT_REFUNDED;
    case 'UNKNOWN':
      return WebhookEventCategory.UNKNOWN;
  }
}

function matchesExpectedPaymentAmount(
  expectedAmount: unknown,
  expectedCurrency: unknown,
  canonicalEvent: NormalizedPaymentWebhookEvent,
): boolean {
  if (typeof expectedAmount !== 'string' || typeof expectedCurrency !== 'string') return false;
  try {
    return Decimal.parse(expectedAmount).eq(Decimal.parse(canonicalEvent.amount)) &&
      expectedCurrency.trim().toUpperCase() === canonicalEvent.currency;
  } catch {
    return false;
  }
}

/**
 * Plan Repository - Data access layer for billing plans
 * 
 * This module handles database operations for plans including
 * CRUD operations, queries, and data persistence.
 */

import { PrismaClient, Prisma } from '@prisma/client';
import { Plan, PlanFilter, PlanSummary, CreatePlanRequest, UpdatePlanRequest } from './plan.types';

export class PlanRepository {
  constructor(private readonly prisma: PrismaClient) {}

  async findById(id: string, tenantId: string): Promise<Plan | null> {
    const plan = await this.prisma.plan.findFirst({
      where: {
        id,
        tenantId,
      },
      include: {
        features: true,
        limits: true,
      },
    });

    if (!plan) {
      return null;
    }

    return this.mapToDomain(plan);
  }

  async findBySlug(slug: string, tenantId: string): Promise<Plan | null> {
    const plan = await this.prisma.plan.findFirst({
      where: {
        slug,
        tenantId,
      },
      include: {
        features: true,
        limits: true,
      },
    });

    if (!plan) {
      return null;
    }

    return this.mapToDomain(plan);
  }

  async findMany(filter: PlanFilter, tenantId: string): Promise<Plan[]> {
    const where: any = { tenantId };

    if (filter.tier) {
      where.tier = filter.tier;
    }

    if (filter.status) {
      where.status = filter.status;
    }

    if (filter.search) {
      where.OR = [
        { name: { contains: filter.search, mode: 'insensitive' } },
        { description: { contains: filter.search, mode: 'insensitive' } },
      ];
    }

    const plans = await this.prisma.plan.findMany({
      where,
      include: {
        features: true,
        limits: true,
      },
      orderBy: { createdAt: 'desc' },
    });

    return plans.map(plan => this.mapToDomain(plan));
  }

  async findSummaries(tenantId: string): Promise<PlanSummary[]> {
    const plans = await this.prisma.plan.findMany({
      where: { tenantId, status: 'active' },
      select: {
        id: true,
        name: true,
        tier: true,
        status: true,
        price: true,
        _count: {
          select: {
            features: true,
            limits: true,
          },
        },
      },
      orderBy: { createdAt: 'asc' },
    });

    return plans.map(plan => ({
      id: plan.id,
      name: plan.name,
      tier: plan.tier as any,
      status: plan.status as any,
      price: plan.price as any,
      featureCount: plan._count.features,
      limitCount: plan._count.limits,
    }));
  }

  async create(data: CreatePlanRequest, tenantId: string, createdBy: string): Promise<Plan> {
    const plan = await this.prisma.plan.create({
      data: {
        tenantId,
        name: data.name,
        slug: data.slug,
        description: data.description,
        tier: data.tier,
        status: 'active',
        price: data.price as any,
        metadata: data.metadata || {},
        createdBy,
        updatedBy: createdBy,
        features: {
          create: data.features.map(feature => ({
            key: feature.key,
            name: feature.name,
            description: feature.description,
            enabled: feature.enabled,
            limit: feature.limit,
            unit: feature.unit,
          })),
        },
        limits: {
          create: data.limits.map(limit => ({
            key: limit.key,
            name: limit.name,
            description: limit.description,
            value: limit.value,
            unit: limit.unit,
            hardLimit: limit.hardLimit,
          })),
        },
      },
      include: {
        features: true,
        limits: true,
      },
    });

    return this.mapToDomain(plan);
  }

  async update(id: string, data: UpdatePlanRequest, tenantId: string, updatedBy: string): Promise<Plan> {
    // features/limits arrive as plain arrays, so they cannot ride the scalar
    // spread: when provided they replace the plan's rows wholesale (nested
    // deleteMany + create inside the same update, which Prisma runs as one
    // transaction).
    const { features, limits, price, ...scalars } = data;
    // Scoped by tenant (Prisma 5 extended unique where): a tenant can neither
    // edit another tenant's plan nor the platform catalogue (tenantId null).
    const plan = await this.prisma.plan.update({
      where: { id, tenantId },
      data: {
        ...scalars,
        ...(price !== undefined
          ? { price: price as unknown as Prisma.InputJsonValue }
          : {}),
        updatedBy,
        updatedAt: new Date(),
        ...(features
          ? {
              features: {
                deleteMany: {},
                create: features.map(feature => ({
                  key: feature.key,
                  name: feature.name,
                  description: feature.description,
                  enabled: feature.enabled,
                  limit: feature.limit,
                  unit: feature.unit,
                })),
              },
            }
          : {}),
        ...(limits
          ? {
              limits: {
                deleteMany: {},
                create: limits.map(limit => ({
                  key: limit.key,
                  name: limit.name,
                  description: limit.description,
                  value: limit.value,
                  unit: limit.unit,
                  hardLimit: limit.hardLimit,
                })),
              },
            }
          : {}),
      },
      include: {
        features: true,
        limits: true,
      },
    });

    return this.mapToDomain(plan);
  }

  async delete(id: string, tenantId: string): Promise<void> {
    // Scoped by tenant: deleting by id alone would let a caller remove another
    // tenant's (or the platform catalogue's) plan.
    const result = await this.prisma.plan.deleteMany({
      where: { id, tenantId },
    });
    if (result.count === 0) {
      throw new Error(`Plan not found: ${id}`);
    }
  }

  async count(tenantId: string): Promise<number> {
    return this.prisma.plan.count({
      where: { tenantId },
    });
  }

  private mapToDomain(plan: any): Plan {
    return {
      id: plan.id,
      tenantId: plan.tenantId,
      name: plan.name,
      slug: plan.slug,
      description: plan.description,
      tier: plan.tier,
      status: plan.status,
      price: plan.price,
      features: plan.features || [],
      limits: plan.limits || [],
      metadata: plan.metadata || {},
      createdAt: plan.createdAt,
      updatedAt: plan.updatedAt,
      createdBy: plan.createdBy,
      updatedBy: plan.updatedBy,
    };
  }
}

import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { InvoiceRepository } from '../finance/invoice.repository';
import { InvoicePdfService } from '../finance/invoice-pdf.service';
import type { PortalInvoiceSummary } from './billing-portal.types';

/**
 * Read-only customer-facing invoice history/details/download metadata
 * using existing finance invoice records. Tenant-scoped, no secrets.
 */
@Injectable()
export class BillingInvoiceQueryService {
  private readonly logger = new Logger(BillingInvoiceQueryService.name);

  constructor(
    private readonly invoiceRepository: InvoiceRepository,
    private readonly invoicePdfService: InvoicePdfService,
  ) {}

  async listInvoices(tenantId: string, filter?: { status?: string; fromDate?: Date; toDate?: Date; limit?: number }): Promise<PortalInvoiceSummary[]> {
    const invoices = await this.invoiceRepository.list({
      tenantId,
      status: filter?.status as any,
      fromDate: filter?.fromDate,
      toDate: filter?.toDate,
    } as any);

    const mapped = invoices.map((inv) => this.mapToSummary(inv));

    // Sort by issue date desc
    mapped.sort((a, b) => new Date(b.issueDate).getTime() - new Date(a.issueDate).getTime());

    if (filter?.limit) {
      return mapped.slice(0, filter.limit);
    }

    return mapped;
  }

  async getInvoiceDetail(tenantId: string, invoiceId: string): Promise<PortalInvoiceSummary & { lines?: any[]; taxSummary?: any[]; paymentReference?: any }> {
    const invoice = await this.invoiceRepository.findById(invoiceId, tenantId);
    if (!invoice) {
      throw new NotFoundException('Invoice not found');
    }

    // Ensure tenant isolation
    if (invoice.tenantId !== tenantId) {
      throw new NotFoundException('Invoice not found');
    }

    const summary = this.mapToSummary(invoice);

    // Try to get detailed data via PDF service (which already handles tenant isolation)
    let lines: any[] | undefined;
    let taxSummary: any[] | undefined;
    let paymentReference: any | undefined;

    try {
      const pdfData = await this.invoicePdfService.generateInvoicePdfData(invoiceId, tenantId);
      lines = pdfData.lineItems as any;
      taxSummary = pdfData.taxSummary as any;
      paymentReference = pdfData.paymentReference;
    } catch {
      // Fallback: no detailed lines
    }

    return {
      ...summary,
      lines,
      taxSummary,
      paymentReference,
    };
  }

  async getInvoicePdfMetadata(tenantId: string, invoiceId: string): Promise<{ available: boolean; invoiceNumber: string; generatedAt?: string }> {
    const invoice = await this.invoiceRepository.findById(invoiceId, tenantId);
    if (!invoice) {
      throw new NotFoundException('Invoice not found');
    }

    if (invoice.tenantId !== tenantId) {
      throw new NotFoundException('Invoice not found');
    }

    // Check if invoice is finalized/paid - only those have PDF
    const pdfAvailableStatuses = ['FINALIZED', 'PAID', 'PARTIALLY_PAID', 'REFUNDED', 'PARTIALLY_REFUNDED', 'OPEN'];
    const available = pdfAvailableStatuses.includes(invoice.status);

    return {
      available,
      invoiceNumber: invoice.invoiceNumber,
      generatedAt: invoice.finalizedAt ? new Date(invoice.finalizedAt).toISOString() : undefined,
    };
  }

  private mapToSummary(invoice: any): PortalInvoiceSummary {
    return {
      id: invoice.id,
      invoiceNumber: invoice.invoiceNumber,
      status: invoice.status,
      issueDate: invoice.issueDate ? new Date(invoice.issueDate).toISOString() : new Date().toISOString(),
      dueDate: invoice.dueDate ? new Date(invoice.dueDate).toISOString() : null,
      currency: invoice.currency,
      subtotal: invoice.subtotal,
      discountTotal: invoice.discountTotal,
      taxTotal: invoice.taxTotal,
      total: invoice.total,
      amountPaid: invoice.amountPaid,
      amountDue: invoice.amountDue,
      amountRefunded: invoice.amountRefunded,
      billingPeriodStart: invoice.billingPeriodStart ? new Date(invoice.billingPeriodStart).toISOString() : null,
      billingPeriodEnd: invoice.billingPeriodEnd ? new Date(invoice.billingPeriodEnd).toISOString() : null,
      planCode: invoice.planCode || null,
      planName: invoice.planName || null,
      pdfAvailable: ['FINALIZED', 'PAID', 'PARTIALLY_PAID', 'REFUNDED', 'PARTIALLY_REFUNDED', 'OPEN'].includes(invoice.status),
    };
  }
}

import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { PaymentService } from '../payments/payment.service';
import type { PortalPaymentSummary } from './billing-portal.types';

/**
 * Read-only tenant-scoped payment history and normalized payment status
 * using existing payment service/repository. No provider secrets.
 */
@Injectable()
export class BillingPaymentHistoryService {
  private readonly logger = new Logger(BillingPaymentHistoryService.name);

  constructor(private readonly paymentService: PaymentService) {}

  async listPayments(tenantId: string, filter?: { status?: string; provider?: string; fromDate?: Date; toDate?: Date; limit?: number }): Promise<PortalPaymentSummary[]> {
    const payments = await this.paymentService.listPaymentsByTenant(tenantId);

    let filtered = payments;

    if (filter?.status) {
      filtered = filtered.filter((p) => p.status === filter.status);
    }

    if (filter?.provider) {
      filtered = filtered.filter((p) => p.provider === filter.provider);
    }

    if (filter?.fromDate) {
      filtered = filtered.filter((p) => new Date(p.createdAt) >= filter.fromDate!);
    }

    if (filter?.toDate) {
      filtered = filtered.filter((p) => new Date(p.createdAt) <= filter.toDate!);
    }

    // Sort by created desc
    filtered.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

    if (filter?.limit) {
      filtered = filtered.slice(0, filter.limit);
    }

    return filtered.map((p) => this.mapToSummary(p));
  }

  async getPaymentDetail(tenantId: string, paymentId: string): Promise<PortalPaymentSummary & { safeMetadata?: any }> {
    const payment = await this.paymentService.getPaymentById(paymentId);

    // Tenant isolation
    if (payment.tenantId !== tenantId) {
      throw new NotFoundException('Payment not found');
    }

    const summary = this.mapToSummary(payment);

    // Safe metadata - exclude secrets
    const safeMetadata = this.extractSafeMetadata(payment);

    return {
      ...summary,
      safeMetadata,
    };
  }

  async getPaymentStatus(tenantId: string, paymentId: string): Promise<{ paymentId: string; status: string; provider: string; amount: string; currency: string; paidAt: string | null; verified: boolean }> {
    const payment = await this.paymentService.getPaymentById(paymentId);

    if (payment.tenantId !== tenantId) {
      throw new NotFoundException('Payment not found');
    }

    // Always verify from backend/provider state, never trust frontend
    let verifiedStatus = payment.status;
    let verified = false;

    try {
      const providerResult = await this.paymentService.retrieveProviderPayment(paymentId);
      verifiedStatus = providerResult.status;
      verified = true;
    } catch {
      // If provider retrieval fails, use internal state but mark unverified
      verified = false;
    }

    return {
      paymentId: payment.id,
      status: verifiedStatus,
      provider: payment.provider,
      amount: payment.amount,
      currency: payment.currency,
      paidAt: payment.paidAt ? payment.paidAt.toISOString() : null,
      verified,
    };
  }

  private mapToSummary(payment: any): PortalPaymentSummary {
    return {
      id: payment.id,
      provider: payment.provider,
      status: payment.status,
      amount: payment.amount,
      currency: payment.currency,
      planId: payment.planId,
      planCode: payment.planCode || (payment.metadata as any)?.planCode || null,
      paidAt: payment.paidAt ? new Date(payment.paidAt).toISOString() : null,
      failedAt: payment.failedAt ? new Date(payment.failedAt).toISOString() : null,
      createdAt: new Date(payment.createdAt).toISOString(),
      checkoutUrl: payment.checkoutUrl || null,
      invoiceUrl: payment.invoiceUrl || null,
      hasInvoice: !!payment.invoiceId || !!(payment.metadata as any)?.invoiceId,
    };
  }

  private extractSafeMetadata(payment: any): any {
    // Only expose safe fields, never secrets
    const metadata = payment.metadata || {};
    const safeFields = ['planCode', 'planName', 'billingInterval', 'orderId', 'description', 'seats'];

    const safe: any = {};
    for (const field of safeFields) {
      if (metadata[field] !== undefined) {
        safe[field] = metadata[field];
      }
    }

    // Include safe references
    safe.orderId = payment.orderId || safe.orderId;
    safe.providerReference = payment.providerReference ? `${payment.providerReference.substring(0, 8)}...` : null;

    return safe;
  }
}

import { Controller, Get, Post, Body, Param, Query, HttpCode, HttpStatus } from '@nestjs/common';
import { ApiTags, ApiOperation, ApiOkResponse, ApiBearerAuth } from '@nestjs/swagger';
import { CurrentUser } from '../../../common/decorators/current-user.decorator';
import { TenantId } from '../../../common/decorators/current-tenant.decorator';
import { RequirePermissions } from '../../../common/decorators/permissions.decorator';
import { RequestMeta, type RequestMetadata } from '../../../common/decorators/request-context.decorator';
import { ApiStandardResponses } from '../../../common/decorators/api-standard-responses.decorator';
import { ParseUuidPipe } from '../../../common/pipes/parse-uuid.pipe';
import { Permission, type AuthenticatedActor, BillingInterval } from '@wlct/shared-types';
import { BillingPortalService } from './billing-portal.service';
import { BillingInvoiceQueryService } from './billing-invoice-query.service';
import { BillingPaymentHistoryService } from './billing-payment-history.service';
import { BillingUsageSummaryService } from './billing-usage-summary.service';
import { SubscriptionManagementService } from './subscription-management.service';
import { PlanChangeService } from './plan-change.service';
import { CheckoutService } from '../payments/checkout.service';
import { CreateCheckoutSessionRequestDto } from './dto/checkout-session.dto';
import { ChangePlanRequestDto, CancelSubscriptionRequestDto, ResumeSubscriptionRequestDto, ChangeIntervalRequestDto } from './dto/subscription-action.dto';

/**
 * Authenticated tenant billing endpoints.
 * All endpoints tenant-scoped, RBAC protected, safe errors.
 * No endpoint exposes another tenant's data.
 */
@ApiTags('Billing - portal')
@ApiBearerAuth()
@Controller({ path: 'billing/portal', version: '1' })
@ApiStandardResponses()
export class BillingPortalController {
  constructor(
    private readonly portalService: BillingPortalService,
    private readonly invoiceQuery: BillingInvoiceQueryService,
    private readonly paymentHistory: BillingPaymentHistoryService,
    private readonly usageSummary: BillingUsageSummaryService,
    private readonly subscriptionMgmt: SubscriptionManagementService,
    private readonly planChangeService: PlanChangeService,
    private readonly checkoutService: CheckoutService,
  ) {}

  @Get('overview')
  @RequirePermissions(Permission.SUBSCRIPTION_READ)
  @ApiOperation({ summary: 'Get billing overview for current tenant' })
  @ApiOkResponse({ description: 'Billing overview' })
  async getOverview(@TenantId() tenantId: string, @CurrentUser() actor: AuthenticatedActor) {
    return this.portalService.getBillingOverview(tenantId, {
      tenantId: actor.tenantId,
      isPlatformUser: actor.isPlatformUser,
      userId: actor.userId,
    });
  }

  @Get('subscription')
  @RequirePermissions(Permission.SUBSCRIPTION_READ)
  @ApiOperation({ summary: 'Get current subscription state' })
  @ApiOkResponse({ description: 'Subscription state' })
  async getSubscription(@TenantId() tenantId: string) {
    return this.subscriptionMgmt.getSubscriptionState(tenantId);
  }

  @Get('plans')
  @RequirePermissions(Permission.SUBSCRIPTION_READ)
  @ApiOperation({ summary: 'Get available plans from canonical catalog' })
  @ApiOkResponse({ description: 'Available plans' })
  async getPlans(@TenantId() tenantId: string, @CurrentUser() actor: AuthenticatedActor) {
    const plans = await this.portalService.getAvailablePlans(tenantId, {
      tenantId: actor.tenantId,
      isPlatformUser: actor.isPlatformUser,
    });
    return { tenantId, plans, fetchedAt: new Date().toISOString() };
  }

  @Get('plans/comparison')
  @RequirePermissions(Permission.SUBSCRIPTION_READ)
  @ApiOperation({ summary: 'Get dynamic plan comparison from canonical catalog' })
  @ApiOkResponse({ description: 'Plan comparison' })
  async getPlanComparison(@TenantId() tenantId: string, @CurrentUser() actor: AuthenticatedActor) {
    return this.portalService.getPlanComparison(tenantId, {
      tenantId: actor.tenantId,
      isPlatformUser: actor.isPlatformUser,
    });
  }

  @Get('usage')
  @RequirePermissions(Permission.SUBSCRIPTION_READ)
  @ApiOperation({ summary: 'Get current usage against canonical limits' })
  @ApiOkResponse({ description: 'Usage summary' })
  async getUsage(@TenantId() tenantId: string) {
    return this.usageSummary.getUsageSummary(tenantId);
  }

  @Get('invoices')
  @RequirePermissions(Permission.SUBSCRIPTION_READ)
  @ApiOperation({ summary: 'List tenant invoices' })
  @ApiOkResponse({ description: 'Invoice list' })
  async listInvoices(
    @TenantId() tenantId: string,
    @Query('status') status?: string,
    @Query('limit') limit?: string,
    @Query('fromDate') fromDate?: string,
    @Query('toDate') toDate?: string,
  ) {
    const invoices = await this.invoiceQuery.listInvoices(tenantId, {
      status,
      limit: limit ? parseInt(limit, 10) : undefined,
      fromDate: fromDate ? new Date(fromDate) : undefined,
      toDate: toDate ? new Date(toDate) : undefined,
    });

    return { tenantId, invoices, total: invoices.length, fetchedAt: new Date().toISOString() };
  }

  @Get('invoices/:id')
  @RequirePermissions(Permission.SUBSCRIPTION_READ)
  @ApiOperation({ summary: 'Get invoice detail' })
  @ApiOkResponse({ description: 'Invoice detail' })
  async getInvoiceDetail(@TenantId() tenantId: string, @Param('id', ParseUuidPipe) id: string) {
    return this.invoiceQuery.getInvoiceDetail(tenantId, id);
  }

  @Get('invoices/:id/pdf-metadata')
  @RequirePermissions(Permission.SUBSCRIPTION_READ)
  @ApiOperation({ summary: 'Get invoice PDF metadata' })
  @ApiOkResponse({ description: 'PDF metadata' })
  async getInvoicePdfMetadata(@TenantId() tenantId: string, @Param('id', ParseUuidPipe) id: string) {
    return this.invoiceQuery.getInvoicePdfMetadata(tenantId, id);
  }

  @Get('payments')
  @RequirePermissions(Permission.SUBSCRIPTION_READ)
  @ApiOperation({ summary: 'List tenant payment history' })
  @ApiOkResponse({ description: 'Payment history' })
  async listPayments(
    @TenantId() tenantId: string,
    @Query('status') status?: string,
    @Query('provider') provider?: string,
    @Query('limit') limit?: string,
    @Query('fromDate') fromDate?: string,
    @Query('toDate') toDate?: string,
  ) {
    const payments = await this.paymentHistory.listPayments(tenantId, {
      status,
      provider,
      limit: limit ? parseInt(limit, 10) : undefined,
      fromDate: fromDate ? new Date(fromDate) : undefined,
      toDate: toDate ? new Date(toDate) : undefined,
    });

    return { tenantId, payments, total: payments.length, fetchedAt: new Date().toISOString() };
  }

  @Get('payments/:id')
  @RequirePermissions(Permission.SUBSCRIPTION_READ)
  @ApiOperation({ summary: 'Get payment detail' })
  @ApiOkResponse({ description: 'Payment detail' })
  async getPaymentDetail(@TenantId() tenantId: string, @Param('id', ParseUuidPipe) id: string) {
    return this.paymentHistory.getPaymentDetail(tenantId, id);
  }

  @Get('payments/:id/status')
  @RequirePermissions(Permission.SUBSCRIPTION_READ)
  @ApiOperation({ summary: 'Get verified payment status from backend/provider' })
  @ApiOkResponse({ description: 'Verified payment status' })
  async getPaymentStatus(@TenantId() tenantId: string, @Param('id', ParseUuidPipe) id: string) {
    return this.paymentHistory.getPaymentStatus(tenantId, id);
  }

  @Post('checkout')
  @HttpCode(HttpStatus.CREATED)
  @RequirePermissions(Permission.SUBSCRIPTION_MANAGE)
  @ApiOperation({ summary: 'Create checkout session - backend decides price/provider' })
  @ApiOkResponse({ description: 'Checkout session with safe data' })
  async createCheckout(
    @TenantId() tenantId: string,
    @CurrentUser() actor: AuthenticatedActor,
    @RequestMeta() meta: RequestMetadata,
    @Body() dto: CreateCheckoutSessionRequestDto,
  ) {
    // Tenant isolation: effective tenant from auth context
    const effectiveTenantId = tenantId;

    const result = await this.checkoutService.createCheckout({
      tenantId: effectiveTenantId,
      userId: actor.userId,
      planId: dto.planId,
      billingInterval: (dto.billingInterval as any) || BillingInterval.MONTHLY,
      currency: dto.currency || 'USD',
      provider: (dto.provider as any) || undefined,
      successUrl: dto.successUrl,
      cancelUrl: dto.cancelUrl,
      idempotencyKey: dto.idempotencyKey || `checkout_${effectiveTenantId}_${dto.planId}_${Date.now()}`,
      seats: dto.seats,
      ipHash: meta.ipHash,
      requestId: meta.requestId,
    } as any);

    // Return only safe data - no provider secrets
    return {
      checkoutId: result.checkoutId,
      paymentId: result.paymentId,
      provider: result.provider,
      status: result.status,
      paymentStatus: result.paymentStatus,
      checkoutUrl: result.checkoutUrl,
      invoiceUrl: result.invoiceUrl,
      providerCheckoutId: result.providerCheckoutId,
      providerSessionId: result.providerSessionId,
      amount: result.amount,
      currency: result.currency,
      planId: result.planId,
      planCode: result.planCode,
      planName: result.planName,
      billingInterval: result.billingInterval,
      expiresAt: result.expiresAt,
      createdAt: result.createdAt,
    };
  }

  @Get('checkout/:id/status')
  @RequirePermissions(Permission.SUBSCRIPTION_READ)
  @ApiOperation({ summary: 'Get checkout status - verified from backend' })
  @ApiOkResponse({ description: 'Checkout status verified' })
  async getCheckoutStatus(@TenantId() tenantId: string, @Param('id', ParseUuidPipe) id: string) {
    const status = await this.checkoutService.getCheckoutStatus(id, tenantId);

    // Also verify via payment history service for double verification
    let verified = false;
    try {
      const paymentStatus = await this.paymentHistory.getPaymentStatus(tenantId, id);
      verified = paymentStatus.verified;
    } catch {
      verified = false;
    }

    return { ...status, verified };
  }

  @Post('subscription/cancel')
  @HttpCode(HttpStatus.OK)
  @RequirePermissions(Permission.SUBSCRIPTION_MANAGE)
  @ApiOperation({ summary: 'Cancel subscription at period end' })
  @ApiOkResponse({ description: 'Cancellation result' })
  async cancelSubscription(
    @TenantId() tenantId: string,
    @CurrentUser() actor: AuthenticatedActor,
    @RequestMeta() meta: RequestMetadata,
    @Body() dto: CancelSubscriptionRequestDto,
  ) {
    const result = await this.subscriptionMgmt.cancelAtPeriodEnd(tenantId, dto.reason, {
      actorId: actor.userId,
      ipHash: meta.ipHash,
      requestId: meta.requestId,
    });

    return {
      tenantId,
      action: 'CANCEL_AT_PERIOD_END',
      subscriptionId: result.subscription.id,
      status: result.subscription.status,
      effectiveAt: result.effectiveAt,
      message: result.message,
      updatedAt: new Date().toISOString(),
    };
  }

  @Post('subscription/resume')
  @HttpCode(HttpStatus.OK)
  @RequirePermissions(Permission.SUBSCRIPTION_MANAGE)
  @ApiOperation({ summary: 'Resume cancelled-at-period-end subscription' })
  @ApiOkResponse({ description: 'Resume result' })
  async resumeSubscription(
    @TenantId() tenantId: string,
    @CurrentUser() actor: AuthenticatedActor,
    @RequestMeta() meta: RequestMetadata,
    @Body() dto: ResumeSubscriptionRequestDto,
  ) {
    const result = await this.subscriptionMgmt.resumeCancelled(tenantId, {
      actorId: actor.userId,
      ipHash: meta.ipHash,
      requestId: meta.requestId,
    });

    return {
      tenantId,
      action: 'RESUME',
      subscriptionId: result.subscription.id,
      status: result.subscription.status,
      effectiveAt: new Date().toISOString(),
      message: result.message,
      updatedAt: new Date().toISOString(),
    };
  }

  @Post('subscription/change-plan')
  @HttpCode(HttpStatus.OK)
  @RequirePermissions(Permission.SUBSCRIPTION_MANAGE)
  @ApiOperation({ summary: 'Change plan - validates via canonical catalog' })
  @ApiOkResponse({ description: 'Plan change result' })
  async changePlan(
    @TenantId() tenantId: string,
    @CurrentUser() actor: AuthenticatedActor,
    @RequestMeta() meta: RequestMetadata,
    @Body() dto: ChangePlanRequestDto,
  ) {
    const result = await this.subscriptionMgmt.changePlan(tenantId, dto.planId, {
      atPeriodEnd: dto.atPeriodEnd,
      actorId: actor.userId,
      ipHash: meta.ipHash,
      requestId: meta.requestId,
      actor: { tenantId: actor.tenantId, isPlatformUser: actor.isPlatformUser },
    });

    return {
      tenantId,
      action: 'CHANGE_PLAN',
      subscriptionId: (result.subscription?.id || result.requestedPlan?.id || dto.planId) as string,
      status: (result.subscription?.status || 'PENDING_CHECKOUT') as string,
      effectiveAt: (result.effectiveAt || null) as string | null,
      message: (result.message || `Plan change to ${result.requestedPlan?.code || dto.planId}`) as string,
      requiresCheckout: (result.requiresCheckout || false) as boolean,
      priceDelta: (result.priceDelta || null) as string | null,
      updatedAt: new Date().toISOString(),
    };
  }

  @Post('subscription/change-interval')
  @HttpCode(HttpStatus.OK)
  @RequirePermissions(Permission.SUBSCRIPTION_MANAGE)
  @ApiOperation({ summary: 'Change billing interval' })
  @ApiOkResponse({ description: 'Interval change result' })
  async changeInterval(
    @TenantId() tenantId: string,
    @CurrentUser() actor: AuthenticatedActor,
    @RequestMeta() meta: RequestMetadata,
    @Body() dto: ChangeIntervalRequestDto,
  ) {
    const result = await this.subscriptionMgmt.changeBillingInterval(tenantId, dto.newInterval as BillingInterval, {
      actorId: actor.userId,
      ipHash: meta.ipHash,
      requestId: meta.requestId,
      actor: { tenantId: actor.tenantId, isPlatformUser: actor.isPlatformUser },
    });

    return {
      tenantId,
      action: 'CHANGE_INTERVAL',
      subscriptionId: (result.subscription?.id || 'pending') as string,
      status: (result.subscription?.status || 'PENDING') as string,
      effectiveAt: (result.effectiveAt || null) as string | null,
      message: (result.message || `Interval change to ${dto.newInterval}`) as string,
      requiresCheckout: (result.requiresCheckout || false) as boolean,
      priceDelta: (result.priceDelta || null) as string | null,
      updatedAt: new Date().toISOString(),
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PlansService } from '../plans.service';
import { SubscriptionsService } from '../subscriptions.service';
import { PaymentService } from '../payments/payment.service';
import { InvoiceRepository } from '../finance/invoice.repository';
import { BillingCustomerService } from '../finance/billing-customer.service';
import { BillingUsageSummaryService } from './billing-usage-summary.service';
import type {
  PortalBillingOverview,
  PortalSubscriptionState,
  PortalCurrentPlan,
  PortalAvailablePlan,
  PortalInvoiceSummary,
  PortalPaymentSummary,
  PortalBillingCustomer,
  PortalPlanComparison,
  PortalFeatureMatrixRow,
  PortalLimitMatrixRow,
} from './billing-portal.types';
import { PortalAvailableAction } from './billing-portal.types';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { BillingInterval, SubscriptionStatus } from '@wlct/shared-types';

/**
 * Main portal aggregation service.
 * Composes canonical billing data into tenant-safe view without duplicating
 * plan/payment/subscription state.
 * Uses existing services as source of truth.
 */
@Injectable()
export class BillingPortalService {
  private readonly logger = new Logger(BillingPortalService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly plansService: PlansService,
    private readonly subscriptionsService: SubscriptionsService,
    private readonly paymentService: PaymentService,
    private readonly invoiceRepository: InvoiceRepository,
    private readonly billingCustomerService: BillingCustomerService,
    private readonly usageSummaryService: BillingUsageSummaryService,
  ) {}

  async getBillingOverview(tenantId: string, actor: { tenantId: string | null; isPlatformUser: boolean; userId: string }): Promise<PortalBillingOverview> {
    // Tenant isolation: resolve tenant from authenticated context, not client input
    const effectiveTenantId = actor.isPlatformUser && actor.tenantId ? actor.tenantId : tenantId;
    if (!actor.isPlatformUser && actor.tenantId !== tenantId) {
      throw new Error('Tenant mismatch');
    }

    const [subscriptionState, availablePlansRaw, usage, latestInvoice, latestPayment, billingCustomer] = await Promise.all([
      this.getCurrentSubscriptionState(effectiveTenantId),
      this.getAvailablePlans(effectiveTenantId, actor),
      this.usageSummaryService.getUsageSummary(effectiveTenantId),
      this.getLatestInvoice(effectiveTenantId),
      this.getLatestPayment(effectiveTenantId),
      this.getBillingCustomerSafe(effectiveTenantId),
    ]);

    const currentPlan = subscriptionState.planId
      ? availablePlansRaw.find((p) => p.id === subscriptionState.planId) || null
      : null;

    const currentPlanMapped: PortalCurrentPlan | null = currentPlan
      ? {
          id: currentPlan.id,
          code: currentPlan.code,
          name: currentPlan.name,
          description: currentPlan.description,
          price: currentPlan.price,
          currency: currentPlan.currency,
          interval: currentPlan.interval as BillingInterval,
          trialDays: currentPlan.trialDays,
          limits: currentPlan.limits as any,
          features: currentPlan.features,
          isActive: currentPlan.isActive,
          sortOrder: currentPlan.sortOrder,
        }
      : null;

    const availablePlans: PortalAvailablePlan[] = availablePlansRaw.map((plan) => ({
      id: plan.id,
      code: plan.code,
      name: plan.name,
      description: plan.description,
      price: plan.price,
      currency: plan.currency,
      interval: plan.interval as BillingInterval,
      trialDays: plan.trialDays,
      limits: plan.limits as any,
      features: plan.features,
      isActive: plan.isActive,
      sortOrder: plan.sortOrder,
      isCurrent: plan.id === subscriptionState.planId,
      upgradeEligible: this.isUpgradeEligible(currentPlan, plan),
      downgradeEligible: this.isDowngradeEligible(currentPlan, plan),
      intervalChangeEligible: this.isIntervalChangeEligible(currentPlan, plan),
    }));

    const availableActions = this.determineAvailableActions(subscriptionState, currentPlanMapped);

    return {
      tenantId: effectiveTenantId,
      subscription: subscriptionState,
      currentPlan: currentPlanMapped,
      availablePlans,
      usage,
      latestInvoice,
      latestPayment,
      billingCustomer,
      availableActions,
      fetchedAt: new Date().toISOString(),
    };
  }

  async getCurrentSubscriptionState(tenantId: string): Promise<PortalSubscriptionState> {
    const subscription = await this.subscriptionsService.getCurrent(tenantId);

    if (!subscription) {
      return {
        id: null,
        tenantId,
        planId: null,
        planCode: null,
        planName: null,
        status: null,
        interval: null,
        currentPeriodStart: null,
        currentPeriodEnd: null,
        trialEndsAt: null,
        cancelAtPeriodEnd: false,
        canceledAt: null,
        seatsPurchased: null,
        renewalDate: null,
        trialActive: false,
        isActive: false,
        isPastDue: false,
        isCanceled: false,
        isTrialing: false,
        willCancelAtPeriodEnd: false,
      };
    }

    const now = new Date();
    const trialEndsAt = subscription.trialEndsAt ? new Date(subscription.trialEndsAt) : null;
    const trialActive = trialEndsAt ? trialEndsAt > now : false;

    return {
      id: subscription.id,
      tenantId: subscription.tenantId,
      planId: subscription.planId,
      planCode: subscription.plan?.code || null,
      planName: subscription.plan?.name || null,
      status: subscription.status as SubscriptionStatus,
      interval: (subscription.plan?.interval as BillingInterval) || null,
      currentPeriodStart: subscription.currentPeriodStart,
      currentPeriodEnd: subscription.currentPeriodEnd,
      trialEndsAt: subscription.trialEndsAt,
      cancelAtPeriodEnd: subscription.cancelAtPeriodEnd,
      canceledAt: subscription.canceledAt,
      seatsPurchased: subscription.seatsPurchased,
      renewalDate: subscription.currentPeriodEnd,
      trialActive,
      isActive: [SubscriptionStatus.ACTIVE, SubscriptionStatus.TRIALING].includes(subscription.status as any),
      isPastDue: subscription.status === SubscriptionStatus.PAST_DUE,
      isCanceled: subscription.status === SubscriptionStatus.CANCELED,
      isTrialing: subscription.status === SubscriptionStatus.TRIALING,
      willCancelAtPeriodEnd: subscription.cancelAtPeriodEnd,
    };
  }

  async getAvailablePlans(tenantId: string, actor: { tenantId: string | null; isPlatformUser: boolean }): Promise<any[]> {
    // Source from canonical plan catalog, never hardcoded
    try {
      const result = await this.plansService.list(
        { includeInactive: false } as any,
        { tenantId: actor.tenantId || tenantId, isPlatformUser: actor.isPlatformUser },
      );
      return result.items.sort((a, b) => a.sortOrder - b.sortOrder);
    } catch {
      // Fallback to platform catalogue cached
      const catalog = await this.plansService.getPlatformCatalogue();
      return catalog.sort((a, b) => a.sortOrder - b.sortOrder);
    }
  }

  async getPlanComparison(tenantId: string, actor: { tenantId: string | null; isPlatformUser: boolean }): Promise<PortalPlanComparison> {
    const plansRaw = await this.getAvailablePlans(tenantId, actor);
    const subscriptionState = await this.getCurrentSubscriptionState(tenantId);

    const plans: PortalAvailablePlan[] = plansRaw.map((plan) => ({
      id: plan.id,
      code: plan.code,
      name: plan.name,
      description: plan.description,
      price: plan.price,
      currency: plan.currency,
      interval: plan.interval as BillingInterval,
      trialDays: plan.trialDays,
      limits: plan.limits as any,
      features: plan.features,
      isActive: plan.isActive,
      sortOrder: plan.sortOrder,
      isCurrent: plan.id === subscriptionState.planId,
      upgradeEligible: this.isUpgradeEligible(
        plansRaw.find((p) => p.id === subscriptionState.planId) || null,
        plan,
      ),
      downgradeEligible: this.isDowngradeEligible(
        plansRaw.find((p) => p.id === subscriptionState.planId) || null,
        plan,
      ),
      intervalChangeEligible: this.isIntervalChangeEligible(
        plansRaw.find((p) => p.id === subscriptionState.planId) || null,
        plan,
      ),
    }));

    // Build features matrix from canonical features
    const allFeatures = new Set<string>();
    for (const plan of plansRaw) {
      for (const f of plan.features || []) allFeatures.add(f);
      // Boolean limits as features
      if ((plan.limits as any)?.customDomain) allFeatures.add('customDomain');
      if ((plan.limits as any)?.whiteLabelMobileApp) allFeatures.add('whiteLabelMobileApp');
      if ((plan.limits as any)?.prioritySupport) allFeatures.add('prioritySupport');
    }

    const featuresMatrix: PortalFeatureMatrixRow[] = Array.from(allFeatures).map((featureKey) => {
      const plansMap: Record<string, boolean> = {};
      for (const plan of plansRaw) {
        const included =
          (plan.features || []).includes(featureKey) ||
          (featureKey === 'customDomain' && !!(plan.limits as any)?.customDomain) ||
          (featureKey === 'whiteLabelMobileApp' && !!(plan.limits as any)?.whiteLabelMobileApp) ||
          (featureKey === 'prioritySupport' && !!(plan.limits as any)?.prioritySupport);
        plansMap[plan.id] = included;
      }
      return { featureKey, label: this.featureLabel(featureKey), plans: plansMap };
    });

    // Build limits matrix
    const limitKeys = ['maxUsers', 'maxTraders', 'maxFollowersPerTrader', 'maxExchangeAccountsPerUser', 'maxCopySubscriptionsPerFollower', 'maxApiRequestsPerMinute', 'websocketConnections'];
    const limitsMatrix: PortalLimitMatrixRow[] = limitKeys.map((limitKey) => {
      const plansMap: Record<string, number | null> = {};
      for (const plan of plansRaw) {
        plansMap[plan.id] = (plan.limits as any)?.[limitKey] ?? null;
      }
      return { limitKey, label: this.limitLabel(limitKey), plans: plansMap };
    });

    return {
      tenantId,
      currentPlanId: subscriptionState.planId,
      plans,
      featuresMatrix,
      limitsMatrix,
      fetchedAt: new Date().toISOString(),
    };
  }

  async getLatestInvoice(tenantId: string): Promise<PortalInvoiceSummary | null> {
    const invoices = await this.invoiceRepository.list({ tenantId } as any);
    if (!invoices || invoices.length === 0) return null;
    const latest = invoices.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())[0];
    return this.mapInvoiceToSummary(latest);
  }

  async getLatestPayment(tenantId: string): Promise<PortalPaymentSummary | null> {
    const payments = await this.paymentService.listPaymentsByTenant(tenantId);
    if (!payments || payments.length === 0) return null;
    const latest = payments.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())[0];
    return {
      id: latest.id,
      provider: latest.provider,
      status: latest.status,
      amount: latest.amount,
      currency: latest.currency,
      planId: latest.planId,
      planCode: (latest as any).planCode || null,
      paidAt: latest.paidAt ? latest.paidAt.toISOString() : null,
      failedAt: latest.failedAt ? latest.failedAt.toISOString() : null,
      createdAt: latest.createdAt.toISOString(),
      checkoutUrl: (latest as any).checkoutUrl || null,
      invoiceUrl: (latest as any).invoiceUrl || null,
      hasInvoice: !!(latest as any).invoiceId,
    };
  }

  private async getBillingCustomerSafe(tenantId: string): Promise<PortalBillingCustomer | null> {
    const customer = await this.billingCustomerService.getBillingCustomer(tenantId);
    if (!customer) return null;
    return {
      tenantId: customer.tenantId,
      billingName: customer.billingName,
      billingEmail: customer.billingEmail,
      billingCountry: customer.billingCountry,
      billingCity: customer.billingCity,
      billingRegion: customer.billingRegion,
      preferredCurrency: customer.preferredCurrency,
      taxId: customer.taxId,
      vatNumber: customer.vatNumber,
      isBusinessCustomer: customer.isBusinessCustomer,
      isTaxExempt: customer.isTaxExempt,
    };
  }

  private mapInvoiceToSummary(invoice: any): PortalInvoiceSummary {
    return {
      id: invoice.id,
      invoiceNumber: invoice.invoiceNumber,
      status: invoice.status,
      issueDate: invoice.issueDate ? new Date(invoice.issueDate).toISOString() : new Date().toISOString(),
      dueDate: invoice.dueDate ? new Date(invoice.dueDate).toISOString() : null,
      currency: invoice.currency,
      subtotal: invoice.subtotal,
      discountTotal: invoice.discountTotal,
      taxTotal: invoice.taxTotal,
      total: invoice.total,
      amountPaid: invoice.amountPaid,
      amountDue: invoice.amountDue,
      amountRefunded: invoice.amountRefunded,
      billingPeriodStart: invoice.billingPeriodStart ? new Date(invoice.billingPeriodStart).toISOString() : null,
      billingPeriodEnd: invoice.billingPeriodEnd ? new Date(invoice.billingPeriodEnd).toISOString() : null,
      planCode: invoice.planCode || null,
      planName: invoice.planName || null,
      pdfAvailable: true,
    };
  }

  private isUpgradeEligible(currentPlan: any | null, targetPlan: any): boolean {
    if (!currentPlan) return true;
    if (currentPlan.id === targetPlan.id) return false;
    const currentPrice = parseFloat(currentPlan.price || '0');
    const targetPrice = parseFloat(targetPlan.price || '0');
    return targetPrice > currentPrice;
  }

  private isDowngradeEligible(currentPlan: any | null, targetPlan: any): boolean {
    if (!currentPlan) return false;
    if (currentPlan.id === targetPlan.id) return false;
    const currentPrice = parseFloat(currentPlan.price || '0');
    const targetPrice = parseFloat(targetPlan.price || '0');
    return targetPrice < currentPrice;
  }

  private isIntervalChangeEligible(currentPlan: any | null, targetPlan: any): boolean {
    if (!currentPlan) return false;
    return currentPlan.code === targetPlan.code && currentPlan.interval !== targetPlan.interval;
  }

  private determineAvailableActions(subscription: PortalSubscriptionState, currentPlan: PortalCurrentPlan | null): PortalAvailableAction[] {
    const actions: PortalAvailableAction[] = [];

    if (!subscription.isActive) {
      actions.push(PortalAvailableAction.CHECKOUT);
      return actions;
    }

    actions.push(PortalAvailableAction.UPGRADE);
    actions.push(PortalAvailableAction.DOWNGRADE);
    actions.push(PortalAvailableAction.CHANGE_INTERVAL);
    actions.push(PortalAvailableAction.VIEW_INVOICES);
    actions.push(PortalAvailableAction.VIEW_PAYMENTS);

    if (subscription.willCancelAtPeriodEnd) {
      actions.push(PortalAvailableAction.RESUME);
    } else {
      actions.push(PortalAvailableAction.CANCEL_AT_PERIOD_END);
    }

    if (subscription.isPastDue) {
      actions.push(PortalAvailableAction.RENEW);
    }

    return actions;
  }

  private featureLabel(key: string): string {
    const labels: Record<string, string> = {
      customDomain: 'Custom Domain',
      whiteLabelMobileApp: 'White-Label Mobile App',
      prioritySupport: 'Priority Support',
      copyTrading: 'Copy Trading',
      apiAccess: 'API Access',
      webhooks: 'Webhooks',
      advancedAnalytics: 'Advanced Analytics',
    };
    return labels[key] || key;
  }

  private limitLabel(key: string): string {
    const labels: Record<string, string> = {
      maxUsers: 'Max Users',
      maxTraders: 'Max Traders',
      maxFollowersPerTrader: 'Max Followers per Trader',
      maxExchangeAccountsPerUser: 'Max Exchange Accounts per User',
      maxCopySubscriptionsPerFollower: 'Max Copy Subscriptions per Follower',
      maxApiRequestsPerMinute: 'API Requests per Minute',
      websocketConnections: 'WebSocket Connections',
    };
    return labels[key] || key;
  }
}

