import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { OverageRecord, OverageStatus } from './overage.types';
import { MeterKey, MeterUnit } from './usage-metering.types';
import { randomUUID } from 'crypto';
import { isRecordNotFound } from '../../../common/errors/prisma-not-found';

/**
 * Persists overage records, period references, quantities, policy references, status, idempotency.
 */
@Injectable()
export class OverageRepository {
  private readonly logger = new Logger(OverageRepository.name);

  constructor(private readonly prisma: PrismaService) {}

  async create(data: {
    tenantId: string;
    meterKey: MeterKey;
    limitKey: string;
    periodId: string;
    periodStart: Date;
    periodEnd: Date;
    allowedQuantity: number;
    actualQuantity: number;
    excessQuantity: number;
    unit: MeterUnit;
    policyReference: string | null;
    rateReference: string | null;
    rateBps: number | null;
    estimatedAmount: string | null;
    currency: string | null;
    status: OverageStatus;
    idempotencyKey: string;
    calculationTimestamp: Date;
    metadata?: Record<string, unknown> | null;
  }): Promise<OverageRecord> {
    // Idempotency check
    const existingByKey = await this.findByIdempotencyKey(data.idempotencyKey, data.tenantId);
    if (existingByKey) {
      this.logger.log(`Idempotent overage return by idempotencyKey: ${data.idempotencyKey}`);
      return existingByKey;
    }

    const existingByPeriodMeter = await this.findByTenantPeriodMeter(data.tenantId, data.periodId, data.meterKey);
    if (existingByPeriodMeter) {
      this.logger.log(`Idempotent overage return by tenant+period+meter: ${data.tenantId} ${data.periodId} ${data.meterKey}`);
      return existingByPeriodMeter;
    }

    const id = randomUUID();
    const now = new Date().toISOString();

    const record: OverageRecord = {
      id,
      tenantId: data.tenantId,
      meterKey: data.meterKey,
      limitKey: data.limitKey,
      periodId: data.periodId,
      periodStart: data.periodStart.toISOString(),
      periodEnd: data.periodEnd.toISOString(),
      allowedQuantity: data.allowedQuantity,
      actualQuantity: data.actualQuantity,
      excessQuantity: data.excessQuantity,
      unit: data.unit,
      policyReference: data.policyReference,
      rateReference: data.rateReference,
      rateBps: data.rateBps,
      estimatedAmount: data.estimatedAmount,
      currency: data.currency,
      status: data.status,
      idempotencyKey: data.idempotencyKey,
      calculationTimestamp: data.calculationTimestamp.toISOString(),
      createdAt: now,
      updatedAt: now,
      metadata: data.metadata || null,
    };

    try {
      const created = await (this.prisma as any).overageRecord?.create({
        data: {
          id: record.id,
          tenantId: record.tenantId,
          meterKey: record.meterKey,
          limitKey: record.limitKey,
          periodId: record.periodId,
          periodStart: data.periodStart,
          periodEnd: data.periodEnd,
          allowedQuantity: record.allowedQuantity,
          actualQuantity: record.actualQuantity,
          excessQuantity: record.excessQuantity,
          unit: record.unit,
          policyReference: record.policyReference,
          rateReference: record.rateReference,
          rateBps: record.rateBps,
          estimatedAmount: record.estimatedAmount,
          currency: record.currency,
          status: record.status,
          idempotencyKey: record.idempotencyKey,
          calculationTimestamp: data.calculationTimestamp,
          createdAt: new Date(record.createdAt),
          updatedAt: new Date(record.updatedAt),
          metadata: record.metadata,
        },
      });

      if (created) {
        return this.mapToDomain(created);
      }
    } catch (error: any) {
      if (error.code === 'P2002') {
        const existing = await this.findByIdempotencyKey(data.idempotencyKey, data.tenantId);
        if (existing) return existing;
      }
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        this.logger.warn(`overageRecord table not found, fallback: ${error.message}`);
        try {
          await (this.prisma as any).auditLog?.create({
            data: {
              id: randomUUID(),
              tenantId: data.tenantId,
              action: 'OVERAGE_DETECTED',
              resourceType: 'OverageRecord',
              resourceId: id,
              metadata: { ...record, fallback: true },
              createdAt: new Date(),
            },
          });
        } catch {}
        return record;
      }
      this.logger.error(`Failed to create overage record: ${error.message}`, error.stack);
      throw error;
    }

    return record;
  }

  async findById(id: string, tenantId?: string): Promise<OverageRecord | null> {
    const result = await (this.prisma as any).overageRecord?.findFirst({
      where: { id, ...(tenantId ? { tenantId } : {}) },
    });
    if (!result) return null;
    return this.mapToDomain(result);
  }

  async findByIdempotencyKey(idempotencyKey: string, tenantId: string): Promise<OverageRecord | null> {
    const result = await (this.prisma as any).overageRecord?.findFirst({
      where: { idempotencyKey, tenantId },
    });
    if (!result) return null;
    return this.mapToDomain(result);
  }

  async findByTenantPeriodMeter(tenantId: string, periodId: string, meterKey: MeterKey): Promise<OverageRecord | null> {
    const result = await (this.prisma as any).overageRecord?.findFirst({
      where: { tenantId, periodId, meterKey },
      orderBy: { createdAt: 'desc' },
    });
    if (!result) return null;
    return this.mapToDomain(result);
  }

  async listByTenant(
    tenantId: string,
    filter?: {
      meterKey?: MeterKey;
      periodId?: string;
      status?: OverageStatus;
      fromDate?: Date;
      toDate?: Date;
      limit?: number;
      offset?: number;
    },
  ): Promise<OverageRecord[]> {
    const where: any = { tenantId };
    if (filter?.meterKey) where.meterKey = filter.meterKey;
    if (filter?.periodId) where.periodId = filter.periodId;
    if (filter?.status) where.status = filter.status;
    if (filter?.fromDate || filter?.toDate) {
      where.periodStart = {};
      if (filter.fromDate) where.periodStart.gte = filter.fromDate;
      if (filter.toDate) where.periodStart.lte = filter.toDate;
    }

    const results = await (this.prisma as any).overageRecord?.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: filter?.limit || 100,
      skip: filter?.offset || 0,
    });

    if (!results) return [];
    return results.map((r: any) => this.mapToDomain(r));
  }

  async updateStatus(id: string, status: OverageStatus, metadata?: Record<string, unknown>): Promise<OverageRecord | null> {
    try {
      const updated = await (this.prisma as any).overageRecord?.update({
        where: { id },
        data: {
          status,
          updatedAt: new Date(),
          ...(metadata ? { metadata } : {}),
        },
      });
      if (!updated) return null;
      return this.mapToDomain(updated);
    } catch (error) {
      if (isRecordNotFound(error)) return null;
      throw error;
    }
  }

  private mapToDomain(raw: any): OverageRecord {
    return {
      id: raw.id,
      tenantId: raw.tenantId,
      meterKey: raw.meterKey as MeterKey,
      limitKey: raw.limitKey,
      periodId: raw.periodId,
      periodStart: raw.periodStart ? new Date(raw.periodStart).toISOString() : new Date().toISOString(),
      periodEnd: raw.periodEnd ? new Date(raw.periodEnd).toISOString() : new Date().toISOString(),
      allowedQuantity: raw.allowedQuantity,
      actualQuantity: raw.actualQuantity,
      excessQuantity: raw.excessQuantity,
      unit: raw.unit as MeterUnit,
      policyReference: raw.policyReference || null,
      rateReference: raw.rateReference || null,
      rateBps: raw.rateBps || null,
      estimatedAmount: raw.estimatedAmount?.toString() || null,
      currency: raw.currency || null,
      status: raw.status as OverageStatus,
      idempotencyKey: raw.idempotencyKey,
      calculationTimestamp: raw.calculationTimestamp ? new Date(raw.calculationTimestamp).toISOString() : new Date().toISOString(),
      createdAt: raw.createdAt ? new Date(raw.createdAt).toISOString() : new Date().toISOString(),
      updatedAt: raw.updatedAt ? new Date(raw.updatedAt).toISOString() : new Date().toISOString(),
      metadata: raw.metadata || null,
    };
  }
}

import { Injectable, Logger, Optional, Inject, forwardRef } from '@nestjs/common';
import { OverageRepository } from './overage.repository';
import { OveragePolicy, OverageStatus, OverageCalculationInput, OverageCalculationResult } from './overage.types';
import { MeterKey, MeterUnit } from './usage-metering.types';
import { parseToMinorUnits, formatFromMinorUnits } from '../finance/money.types';
import { BillingEventService } from '../notifications/billing-event.service';

/**
 * Calculates usage above configured limits ONLY when explicit overage policy exists.
 * Never invents rates, never charges automatically without policy.
 * If no policy, returns NOT_CONFIGURED deterministically.
 */
@Injectable()
export class OverageService {
  private readonly logger = new Logger(OverageService.name);

  constructor(
    private readonly overageRepository: OverageRepository,
    @Optional()
    @Inject(forwardRef(() => BillingEventService))
    private readonly billingEventService?: BillingEventService,
  ) {}

  async calculateOverage(input: OverageCalculationInput): Promise<OverageCalculationResult> {
    const excessQuantity = Math.max(0, input.actualQuantity - input.allowedQuantity);
    const isOverage = excessQuantity > 0;

    const idempotencyKey = input.idempotencyKey || `overage_${input.tenantId}_${input.meterKey}_${input.periodId}`;

    // Check existing
    const existing = await this.overageRepository.findByIdempotencyKey(idempotencyKey, input.tenantId);
    if (existing) {
      this.logger.log(`Idempotent overage return by key: ${idempotencyKey}`);
      return this.mapRecordToResult(existing, isOverage);
    }

    if (!isOverage) {
      // No overage
      const result: OverageCalculationResult = {
        tenantId: input.tenantId,
        meterKey: input.meterKey,
        limitKey: input.limitKey,
        periodId: input.periodId,
        allowedQuantity: input.allowedQuantity,
        actualQuantity: input.actualQuantity,
        excessQuantity: 0,
        unit: input.unit,
        policyReference: input.policy?.policyReference || null,
        rateReference: null,
        rateBps: null,
        estimatedAmount: null,
        currency: null,
        status: OverageStatus.DETECTED,
        calculatedAt: new Date().toISOString(),
        isOverage: false,
        isBillable: false,
        requiresReview: false,
        notConfigured: false,
      };
      return result;
    }

    // Overage detected, check policy
    if (!input.policy) {
      this.logger.log(`Overage detected but no policy configured tenant=${input.tenantId} meter=${input.meterKey} excess=${excessQuantity}`);

      // Persist NOT_CONFIGURED record for audit
      const notConfiguredRecord = await this.overageRepository.create({
        tenantId: input.tenantId,
        meterKey: input.meterKey,
        limitKey: input.limitKey,
        periodId: input.periodId,
        periodStart: new Date(input.periodStart),
        periodEnd: new Date(input.periodEnd),
        allowedQuantity: input.allowedQuantity,
        actualQuantity: input.actualQuantity,
        excessQuantity,
        unit: input.unit,
        policyReference: null,
        rateReference: null,
        rateBps: null,
        estimatedAmount: null,
        currency: null,
        status: OverageStatus.NOT_CONFIGURED,
        idempotencyKey,
        calculationTimestamp: new Date(),
        metadata: input.metadata,
      });

      return {
        tenantId: input.tenantId,
        meterKey: input.meterKey,
        limitKey: input.limitKey,
        periodId: input.periodId,
        allowedQuantity: input.allowedQuantity,
        actualQuantity: input.actualQuantity,
        excessQuantity,
        unit: input.unit,
        policyReference: null,
        rateReference: null,
        rateBps: null,
        estimatedAmount: null,
        currency: null,
        status: OverageStatus.NOT_CONFIGURED,
        calculatedAt: new Date().toISOString(),
        isOverage: true,
        isBillable: false,
        requiresReview: false,
        notConfigured: true,
      };
    }

    // Policy exists - calculate estimated amount with Decimal-safe arithmetic if rate exists
    let estimatedAmount: string | null = null;
    let rateReference: string | null = null;
    let rateBps: number | null = null;
    const currency: string | null = input.policy.currency || null;
    let status: OverageStatus = OverageStatus.DETECTED;

    if (input.policy.overageRateBps && input.policy.overageRateBps > 0) {
      // If policy has BPS rate, calculate amount: excess * rate? But overage for count meters typically per-unit price
      // For count overage, if rateBps is present, we interpret as per-unit price in minor units? No, we need explicit ratePerUnit
      // For this implementation, if overageRateBps exists, we do NOT invent dollar price - we store rate reference
      // Estimated amount calculation only if overageRatePerUnit exists
      rateBps = input.policy.overageRateBps;
      rateReference = `BPS:${rateBps}`;
      status = OverageStatus.CALCULATED;

      if (input.policy.overageRatePerUnit) {
        try {
          // Decimal-safe: estimated = excess * ratePerUnit
          const rateMinor = parseToMinorUnits(input.policy.overageRatePerUnit, currency || 'USD');
          const estimatedMinor = rateMinor * excessQuantity;
          estimatedAmount = formatFromMinorUnits(estimatedMinor, currency || 'USD');
          rateReference = input.policy.overageRatePerUnit;
        } catch (e) {
          this.logger.warn(`Failed to calculate overage amount: ${(e as Error).message}`);
        }
      }
    } else if (input.policy.overageRatePerUnit) {
      // Per-unit rate
      try {
        const rateMinor = parseToMinorUnits(input.policy.overageRatePerUnit, currency || 'USD');
        const estimatedMinor = rateMinor * excessQuantity;
        estimatedAmount = formatFromMinorUnits(estimatedMinor, currency || 'USD');
        rateReference = input.policy.overageRatePerUnit;
        status = OverageStatus.CALCULATED;
      } catch (e) {
        this.logger.warn(`Failed to calculate overage amount: ${(e as Error).message}`);
      }
    }

    if (input.policy.isBillable) {
      status = input.policy.requiresReview ? OverageStatus.REVIEW_REQUIRED : OverageStatus.BILLABLE;
    } else {
      status = OverageStatus.DETECTED;
    }

    // If no rate at all, status is DETECTED but not billable
    if (!input.policy.overageRateBps && !input.policy.overageRatePerUnit) {
      status = OverageStatus.DETECTED;
    }

    const record = await this.overageRepository.create({
      tenantId: input.tenantId,
      meterKey: input.meterKey,
      limitKey: input.limitKey,
      periodId: input.periodId,
      periodStart: new Date(input.periodStart),
      periodEnd: new Date(input.periodEnd),
      allowedQuantity: input.allowedQuantity,
      actualQuantity: input.actualQuantity,
      excessQuantity,
      unit: input.unit,
      policyReference: input.policy.policyReference,
      rateReference,
      rateBps,
      estimatedAmount,
      currency,
      status,
      idempotencyKey,
      calculationTimestamp: new Date(),
      metadata: input.metadata,
    });

    const result: OverageCalculationResult = {
      tenantId: input.tenantId,
      meterKey: input.meterKey,
      limitKey: input.limitKey,
      periodId: input.periodId,
      allowedQuantity: input.allowedQuantity,
      actualQuantity: input.actualQuantity,
      excessQuantity,
      unit: input.unit,
      policyReference: input.policy.policyReference,
      rateReference,
      rateBps,
      estimatedAmount,
      currency,
      status,
      calculatedAt: new Date().toISOString(),
      isOverage: true,
      isBillable: input.policy.isBillable,
      requiresReview: input.policy.requiresReview,
      notConfigured: false,
    };

    this.logger.log(
      `Overage calculated tenant=${input.tenantId} meter=${input.meterKey} allowed=${input.allowedQuantity} actual=${input.actualQuantity} excess=${excessQuantity} status=${status} estimated=${estimatedAmount || 'N/A'}`,
    );

    if (isOverage && this.billingEventService) {
      this.billingEventService.onUsageOverageDetected({
        tenantId: input.tenantId,
        meterKey: input.meterKey,
        limitKey: input.limitKey,
        currentUsage: input.actualQuantity,
        maxLimit: input.allowedQuantity,
        overageQuantity: excessQuantity,
        supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
        appName: process.env.APP_NAME || 'WLCT',
      }).catch((e) => this.logger.warn(`Failed to trigger overage notification: ${e.message}`));
    }

    return result;
  }

  async resolveOveragePolicy(tenantId: string, meterKey: MeterKey, limitKey: string): Promise<OveragePolicy | null> {
    // In real implementation, would check tenant-specific overage policy config or global policy
    // For now, check env or tenant metadata for explicit policy
    // Never invent default dollar price

    // Check if overage policy is configured via env: OVERAGE_POLICY_{METER_KEY}
    // Example: OVERAGE_POLICY_USERS_RATE_PER_UNIT=1.00
    // This is explicit configurable policy, not hardcoded commercial rate

    const envKey = `OVERAGE_POLICY_${meterKey}_RATE_PER_UNIT`;
    const envRate = process.env[envKey];
    const envCurrency = process.env[`OVERAGE_POLICY_${meterKey}_CURRENCY`] || 'USD';
    const envBillable = process.env[`OVERAGE_POLICY_${meterKey}_BILLABLE`] === 'true';

    if (envRate) {
      return {
        meterKey,
        tenantId,
        limitKey,
        allowedQuantity: 0, // Will be overridden by actual limit
        overageRatePerUnit: envRate,
        currency: envCurrency,
        unit: this.getUnitForMeter(meterKey),
        policyReference: `env:${envKey}`,
        isBillable: envBillable,
        requiresReview: true,
      };
    }

    // No policy configured - return null to trigger NOT_CONFIGURED
    return null;
  }

  async detectOverage(params: {
    tenantId: string;
    meterKey: MeterKey;
    limitKey: string;
    periodId: string;
    periodStart: string;
    periodEnd: string;
    allowedQuantity: number;
    actualQuantity: number;
    unit: MeterUnit;
    idempotencyKey?: string;
  }): Promise<OverageCalculationResult> {
    const policy = await this.resolveOveragePolicy(params.tenantId, params.meterKey, params.limitKey);

    return this.calculateOverage({
      tenantId: params.tenantId,
      meterKey: params.meterKey,
      limitKey: params.limitKey,
      periodId: params.periodId,
      periodStart: params.periodStart,
      periodEnd: params.periodEnd,
      allowedQuantity: params.allowedQuantity,
      actualQuantity: params.actualQuantity,
      unit: params.unit,
      policy,
      idempotencyKey: params.idempotencyKey,
    });
  }

  async listOverages(
    tenantId: string,
    filter?: { meterKey?: MeterKey; periodId?: string; status?: OverageStatus; fromDate?: Date; toDate?: Date; limit?: number; offset?: number },
  ): Promise<any[]> {
    return this.overageRepository.listByTenant(tenantId, filter);
  }

  private mapRecordToResult(record: any, isOverage: boolean): OverageCalculationResult {
    return {
      tenantId: record.tenantId,
      meterKey: record.meterKey,
      limitKey: record.limitKey,
      periodId: record.periodId,
      allowedQuantity: record.allowedQuantity,
      actualQuantity: record.actualQuantity,
      excessQuantity: record.excessQuantity,
      unit: record.unit,
      policyReference: record.policyReference,
      rateReference: record.rateReference,
      rateBps: record.rateBps,
      estimatedAmount: record.estimatedAmount,
      currency: record.currency,
      status: record.status,
      calculatedAt: record.calculationTimestamp,
      isOverage,
      isBillable: record.status === OverageStatus.BILLABLE || record.status === OverageStatus.INVOICED,
      requiresReview: record.status === OverageStatus.REVIEW_REQUIRED,
      notConfigured: record.status === OverageStatus.NOT_CONFIGURED,
    };
  }

  private getUnitForMeter(meterKey: MeterKey): MeterUnit {
    switch (meterKey) {
      case MeterKey.USERS:
      case MeterKey.TRADERS:
      case MeterKey.FOLLOWERS:
      case MeterKey.EXCHANGE_ACCOUNTS:
      case MeterKey.COPY_SUBSCRIPTIONS:
      case MeterKey.ORDERS:
      case MeterKey.FILLS:
        return MeterUnit.COUNT;
      case MeterKey.API_REQUESTS:
        return MeterUnit.REQUEST;
      case MeterKey.WEBSOCKET_CONNECTIONS:
        return MeterUnit.CONNECTION;
      case MeterKey.TRADING_VOLUME:
      case MeterKey.COPY_TRADING_VOLUME:
      case MeterKey.PLATFORM_FEE_VOLUME:
      case MeterKey.PERFORMANCE_FEE_VOLUME:
        return MeterUnit.VOLUME_USD;
      default:
        return MeterUnit.COUNT;
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { PlansService } from '../plans.service';
import { SubscriptionsService } from '../subscriptions.service';
import { UsageMeterRepository } from './usage-meter.repository';
import { UsagePeriodService } from './usage-period.service';
import { MeterKey, UsageScope, QuotaSnapshot, ENFORCED_METER_TO_LIMIT_KEY } from './usage-metering.types';

/**
 * Produces authoritative quota snapshots by combining canonical plan limits with metered usage.
 * Do NOT duplicate limit values - always resolve from plan.
 * Aligns with Part 2 enforcement limit keys.
 */
@Injectable()
export class QuotaSnapshotService {
  private readonly logger = new Logger(QuotaSnapshotService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly plansService: PlansService,
    private readonly subscriptionsService: SubscriptionsService,
    private readonly meterRepository: UsageMeterRepository,
    private readonly periodService: UsagePeriodService,
  ) {}

  async getQuotaSnapshot(params: {
    tenantId: string;
    meterKey: MeterKey;
    scope: UsageScope;
    subjectId?: string;
    periodId?: string;
  }): Promise<QuotaSnapshot> {
    const meterDef = this.meterRepository.getMeterDefinition(params.meterKey);
    if (!meterDef) {
      throw new Error(`Invalid meter key: ${params.meterKey}`);
    }

    const limitKey = ENFORCED_METER_TO_LIMIT_KEY[params.meterKey];
    let maximum: number | null = null;
    let planCode: string | null = null;
    const isEnforced = meterDef.isEnforced;

    // Resolve canonical plan limits if enforced meter
    if (limitKey) {
      try {
        const subscription = await this.subscriptionsService.getCurrent(params.tenantId);
        if (subscription) {
          const plan = subscription.plan as any;
          if (plan) {
            planCode = plan.code || null;
            const limits = plan.limits as any;
            if (limits && limits[limitKey] !== undefined) {
              maximum = limits[limitKey];
              // Boolean limits mean unlimited or feature toggle, not numeric
              if (typeof maximum === 'boolean') {
                maximum = null;
              }
            }
          }
        }
      } catch (e) {
        this.logger.warn(`Failed to resolve plan limits for ${params.tenantId} limitKey=${limitKey}: ${(e as Error).message}`);
      }

      // Also check tenant overrides (maxUsers, maxTraders) from tenant table
      if (limitKey === 'maxUsers' || limitKey === 'maxTraders') {
        try {
          const tenant = await this.prisma.tenant.findUnique({
            where: { id: params.tenantId },
            select: { maxUsers: true, maxTraders: true },
          });
          if (tenant) {
            if (limitKey === 'maxUsers' && tenant.maxUsers !== null) {
              maximum = tenant.maxUsers;
            }
            if (limitKey === 'maxTraders' && tenant.maxTraders !== null) {
              maximum = tenant.maxTraders;
            }
          }
        } catch {}
      }
    }

    // Get current usage from durable metering
    let current = 0;
    let periodId = params.periodId;
    let periodStart: string;
    let periodEnd: string;

    if (!periodId) {
      const period = this.periodService.getCurrentCalendarMonthPeriod(params.tenantId);
      periodId = period.id;
      periodStart = period.start;
      periodEnd = period.end;
    } else {
      // Try to parse periodId to get start/end, fallback to current month
      const period = this.periodService.getCurrentCalendarMonthPeriod(params.tenantId);
      periodStart = period.start;
      periodEnd = period.end;
    }

    try {
      const total = await this.meterRepository.getCurrentPeriodTotal({
        tenantId: params.tenantId,
        meterKey: params.meterKey,
        scope: params.scope,
        subjectId: params.subjectId,
        periodId,
      });
      current = total.totalQuantity;

      // For count-based meters that are not period-based (users, traders), get actual DB counts
      // to ensure quota snapshot matches canonical truth, not just metered events
      if ([MeterKey.USERS, MeterKey.TRADERS].includes(params.meterKey) && params.scope === UsageScope.TENANT) {
        // Use actual counts from DB for these meters to align with enforcement
        try {
          if (params.meterKey === MeterKey.USERS) {
            current = await this.prisma.user.count({ where: { tenantId: params.tenantId, deletedAt: null } });
          } else if (params.meterKey === MeterKey.TRADERS) {
            current = await (this.prisma as any).tradingAccount?.count({ where: { tenantId: params.tenantId, deletedAt: null } }) || current;
          }
        } catch {}
      }
    } catch (e) {
      this.logger.warn(`Failed to get current usage for ${params.tenantId} meter=${params.meterKey}: ${(e as Error).message}`);
    }

    // Calculate remaining and utilization
    let remaining: number | null = null;
    let utilizationPercent: number | null = null;
    let status: QuotaSnapshot['status'] = 'OK';

    if (maximum === null) {
      remaining = null;
      utilizationPercent = null;
      status = 'UNLIMITED';
    } else {
      remaining = Math.max(0, maximum - current);
      utilizationPercent = maximum > 0 ? Math.min(100, Math.round((current / maximum) * 100)) : current > 0 ? 100 : 0;

      if (current >= maximum) {
        status = current > maximum ? 'OVER_LIMIT' : 'AT_LIMIT';
      } else if (utilizationPercent >= 90) {
        status = 'APPROACHING';
      } else {
        status = 'OK';
      }
    }

    const period = this.periodService.getCurrentCalendarMonthPeriod(params.tenantId);
    if (!periodId) periodId = period.id;
    if (!periodStart!) periodStart = period.start;
    if (!periodEnd!) periodEnd = period.end;

    const snapshot: QuotaSnapshot = {
      tenantId: params.tenantId,
      meterKey: params.meterKey,
      limitKey: limitKey || params.meterKey,
      scope: params.scope,
      subjectId: params.subjectId,
      maximum,
      current,
      remaining,
      utilizationPercent,
      status,
      periodId,
      periodStart,
      periodEnd,
      fetchedAt: new Date().toISOString(),
      planCode,
      isEnforced,
    };

    this.logger.log(`Quota snapshot tenant=${params.tenantId} meter=${params.meterKey} current=${current} max=${maximum} remaining=${remaining} util=${utilizationPercent}% status=${status}`);

    return snapshot;
  }

  async getTenantQuotaOverview(tenantId: string, periodId?: string): Promise<QuotaSnapshot[]> {
    const snapshots: QuotaSnapshot[] = [];

    // Get snapshots for all enforced meters
    const enforcedMeters = [MeterKey.USERS, MeterKey.TRADERS, MeterKey.FOLLOWERS, MeterKey.EXCHANGE_ACCOUNTS, MeterKey.COPY_SUBSCRIPTIONS, MeterKey.API_REQUESTS, MeterKey.WEBSOCKET_CONNECTIONS];

    for (const meterKey of enforcedMeters) {
      try {
        const meterDef = this.meterRepository.getMeterDefinition(meterKey);
        if (!meterDef) continue;

        // For per-trader/per-user scoped meters, we need to get tenant-level overview
        // For simplicity, get tenant scope snapshot
        const scope = meterKey === MeterKey.FOLLOWERS ? UsageScope.TENANT : meterKey === MeterKey.EXCHANGE_ACCOUNTS ? UsageScope.TENANT : meterKey === MeterKey.COPY_SUBSCRIPTIONS ? UsageScope.TENANT : UsageScope.TENANT;

        const snapshot = await this.getQuotaSnapshot({
          tenantId,
          meterKey,
          scope,
          periodId,
        });

        snapshots.push(snapshot);
      } catch (e) {
        this.logger.warn(`Failed to get quota snapshot for ${meterKey}: ${(e as Error).message}`);
      }
    }

    // Also include informational meters
    const infoMeters = [MeterKey.TRADING_VOLUME, MeterKey.COPY_TRADING_VOLUME, MeterKey.ORDERS, MeterKey.FILLS];
    for (const meterKey of infoMeters) {
      try {
        const snapshot = await this.getQuotaSnapshot({
          tenantId,
          meterKey,
          scope: UsageScope.TENANT,
          periodId,
        });
        snapshots.push(snapshot);
      } catch {}
    }

    return snapshots;
  }

  async getResourceQuotaSnapshot(params: { tenantId: string; scope: UsageScope; subjectId: string; meterKey: MeterKey; periodId?: string }): Promise<QuotaSnapshot> {
    return this.getQuotaSnapshot({
      tenantId: params.tenantId,
      meterKey: params.meterKey,
      scope: params.scope,
      subjectId: params.subjectId,
      periodId: params.periodId,
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { UsageEventRepository } from './usage-event.repository';
import { UsageMeterRepository } from './usage-meter.repository';
import { UsagePeriodService } from './usage-period.service';
import { MeterKey, UsageScope, AggregationWindow, PeriodType, UsageBucket } from './usage-metering.types';
import { randomUUID } from 'crypto';

/**
 * Aggregates raw events into hourly/daily/monthly/period buckets with deterministic totals
 * and safe reprocessing. No double counting, timezone-safe, source-event traceability.
 */
@Injectable()
export class UsageAggregationService {
  private readonly logger = new Logger(UsageAggregationService.name);

  constructor(
    private readonly eventRepository: UsageEventRepository,
    private readonly meterRepository: UsageMeterRepository,
    private readonly periodService: UsagePeriodService,
  ) {}

  async aggregateHourly(tenantId: string, date: Date, meterKey?: MeterKey): Promise<UsageBucket[]> {
    return this.aggregateForWindow(tenantId, date, AggregationWindow.HOURLY, PeriodType.CALENDAR_HOUR, meterKey);
  }

  async aggregateDaily(tenantId: string, date: Date, meterKey?: MeterKey): Promise<UsageBucket[]> {
    return this.aggregateForWindow(tenantId, date, AggregationWindow.DAILY, PeriodType.CALENDAR_DAY, meterKey);
  }

  async aggregateMonthly(tenantId: string, date: Date, meterKey?: MeterKey): Promise<UsageBucket[]> {
    return this.aggregateForWindow(tenantId, date, AggregationWindow.MONTHLY, PeriodType.CALENDAR_MONTH, meterKey);
  }

  async aggregateBillingPeriod(tenantId: string, meterKey?: MeterKey): Promise<UsageBucket[]> {
    const period = await this.periodService.getSubscriptionPeriod(tenantId);
    const start = new Date(period.start);
    const end = new Date(period.end);

    const events = await this.eventRepository.listByTenant(tenantId, {
      meterKey,
      fromDate: start,
      toDate: end,
      limit: 10000,
    });

    return this.buildBucketsFromEvents(tenantId, events, AggregationWindow.BILLING_PERIOD, period.id, start, end);
  }

  async rebuildAggregatesForPeriod(tenantId: string, periodId: string, meterKey?: MeterKey): Promise<UsageBucket[]> {
    // Idempotent rebuild: re-aggregate from durable events
    const events = await this.eventRepository.listByTenant(tenantId, {
      meterKey,
      periodId,
      limit: 10000,
    });

    if (events.length === 0) {
      this.logger.log(`No events to rebuild for tenant=${tenantId} period=${periodId}`);
      return [];
    }

    const firstEvent = events[0];
    const periodStart = new Date(firstEvent.periodStart);
    const periodEnd = new Date(firstEvent.periodEnd);

    // Determine window from period type
    let window: AggregationWindow = AggregationWindow.MONTHLY;
    if (firstEvent.periodType === PeriodType.CALENDAR_DAY) window = AggregationWindow.DAILY;
    if (firstEvent.periodType === PeriodType.CALENDAR_HOUR) window = AggregationWindow.HOURLY;
    if (firstEvent.periodType === PeriodType.SUBSCRIPTION_PERIOD) window = AggregationWindow.BILLING_PERIOD;

    const buckets = await this.buildBucketsFromEvents(tenantId, events, window, periodId, periodStart, periodEnd);

    this.logger.log(`Rebuilt aggregates tenant=${tenantId} period=${periodId} buckets=${buckets.length} events=${events.length}`);

    return buckets;
  }

  async getAggregatedUsage(
    tenantId: string,
    filter: {
      meterKey?: MeterKey;
      scope?: UsageScope;
      subjectId?: string;
      window: AggregationWindow;
      fromDate?: Date;
      toDate?: Date;
      limit?: number;
    },
  ): Promise<UsageBucket[]> {
    try {
      // Get buckets from repository
      const where: any = { tenantId, window: filter.window };
      if (filter.meterKey) where.meterKey = filter.meterKey;
      if (filter.scope) where.scope = filter.scope;
      if (filter.subjectId) where.subjectId = filter.subjectId;
      if (filter.fromDate || filter.toDate) {
        where.periodStart = {};
        if (filter.fromDate) where.periodStart.gte = filter.fromDate;
        if (filter.toDate) where.periodStart.lte = filter.toDate;
      }

      // Use meter repository's getTenantTotals or direct query
      // For simplicity, fetch via event repository aggregation if bucket table missing
      const buckets = await this.meterRepository.getPeriodTotals(tenantId, filter.fromDate ? `cal_${filter.fromDate.toISOString()}` : 'current', filter.meterKey);

      if (buckets.length > 0) {
        return buckets.filter((b) => {
          if (filter.window && b.window !== filter.window) return false;
          if (filter.scope && b.scope !== filter.scope) return false;
          if (filter.subjectId && b.subjectId !== filter.subjectId) return false;
          return true;
        });
      }

      // Fallback: build from events
      const events = await this.eventRepository.listByTenant(tenantId, {
        meterKey: filter.meterKey,
        scope: filter.scope,
        subjectId: filter.subjectId,
        fromDate: filter.fromDate,
        toDate: filter.toDate,
        limit: filter.limit || 1000,
      });

      if (events.length === 0) return [];

      const periodStart = filter.fromDate || new Date(events[events.length - 1].timestamp);
      const periodEnd = filter.toDate || new Date();

      return this.buildBucketsFromEvents(tenantId, events, filter.window, `agg_${Date.now()}`, periodStart, periodEnd);
    } catch (e) {
      this.logger.warn(`Failed to get aggregated usage: ${(e as Error).message}`);
      throw e;
    }
  }

  private async aggregateForWindow(
    tenantId: string,
    date: Date,
    window: AggregationWindow,
    periodType: PeriodType,
    meterKey?: MeterKey,
  ): Promise<UsageBucket[]> {
    const period = this.periodService.getPeriodForTimestamp(tenantId, date, periodType);
    const start = new Date(period.start);
    const end = new Date(period.end);

    const events = await this.eventRepository.listByTenant(tenantId, {
      meterKey,
      fromDate: start,
      toDate: end,
      limit: 10000,
    });

    return this.buildBucketsFromEvents(tenantId, events, window, period.id, start, end);
  }

  private async buildBucketsFromEvents(
    tenantId: string,
    events: any[],
    window: AggregationWindow,
    periodId: string,
    periodStart: Date,
    periodEnd: Date,
  ): Promise<UsageBucket[]> {
    // Deterministic aggregation: group by meterKey + scope + subjectId
    const grouped = new Map<string, { meterKey: MeterKey; scope: UsageScope; subjectId?: string; unit: any; totalQuantity: number; eventCount: number; lastEventAt: string }>();

    for (const event of events) {
      const key = `${event.meterKey}_${event.scope}_${event.subjectId || 'global'}_${event.unit}`;
      const existing = grouped.get(key);
      if (existing) {
        existing.totalQuantity += event.quantity;
        existing.eventCount += 1;
        if (new Date(event.timestamp) > new Date(existing.lastEventAt)) {
          existing.lastEventAt = event.timestamp;
        }
      } else {
        grouped.set(key, {
          meterKey: event.meterKey,
          scope: event.scope,
          subjectId: event.subjectId,
          unit: event.unit,
          totalQuantity: event.quantity,
          eventCount: 1,
          lastEventAt: event.timestamp,
        });
      }
    }

    const buckets: UsageBucket[] = [];
    for (const [groupKey, data] of grouped) {
      buckets.push({
        id: randomUUID(),
        tenantId,
        meterKey: data.meterKey,
        scope: data.scope,
        subjectId: data.subjectId,
        window,
        periodId,
        periodStart: periodStart.toISOString(),
        periodEnd: periodEnd.toISOString(),
        totalQuantity: data.totalQuantity,
        eventCount: data.eventCount,
        unit: data.unit,
        lastEventAt: data.lastEventAt,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      });
    }

    // Sort deterministically by meterKey + scope
    buckets.sort((a, b) => {
      if (a.meterKey !== b.meterKey) return a.meterKey.localeCompare(b.meterKey);
      if (a.scope !== b.scope) return a.scope.localeCompare(b.scope);
      return (a.subjectId || '').localeCompare(b.subjectId || '');
    });

    return buckets;
  }
}

import { Injectable, Logger, Optional, Inject, forwardRef } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { UsageAlertConfig, UsageAlertEvent, AlertThresholdType, AlertSeverity, AlertState } from './usage-alert.types';
import { MeterKey } from './usage-metering.types';
import { BillingEventService } from '../notifications/billing-event.service';
import { randomUUID } from 'crypto';
import { isRecordNotFound } from '../../../common/errors/prisma-not-found';

/**
 * Generates threshold alerts when usage approaches/exceeds limits,
 * with deduplication and cooldown handling. Does NOT reject operations - alerting layer only.
 */
@Injectable()
export class UsageAlertService {
  private readonly logger = new Logger(UsageAlertService.name);

  // Default thresholds for informational alerting (not commercial policy)
  private readonly DEFAULT_THRESHOLDS = [
    { percentage: 50, severity: AlertSeverity.INFO },
    { percentage: 75, severity: AlertSeverity.WARNING },
    { percentage: 90, severity: AlertSeverity.WARNING },
    { percentage: 100, severity: AlertSeverity.CRITICAL },
  ];

  constructor(
    private readonly prisma: PrismaService,
    @Optional()
    @Inject(forwardRef(() => BillingEventService))
    private readonly billingEventService?: BillingEventService,
  ) {}

  async evaluateAndAlert(params: {
    tenantId: string;
    meterKey: MeterKey;
    limitKey: string;
    currentValue: number;
    maximumValue: number | null;
    utilizationPercent: number | null;
    periodId: string;
  }): Promise<UsageAlertEvent[]> {
    if (params.maximumValue === null) {
      // Unlimited - no alerts needed
      return [];
    }

    const configs = await this.getAlertConfigs(params.tenantId, params.meterKey, params.limitKey);

    const triggeredEvents: UsageAlertEvent[] = [];

    for (const config of configs) {
      if (!config.enabled) continue;

      // Cooldown check
      if (config.lastTriggeredAt) {
        const lastTriggered = new Date(config.lastTriggeredAt);
        const cooldownMs = config.cooldownMinutes * 60 * 1000;
        const nextAllowed = new Date(lastTriggered.getTime() + cooldownMs);
        if (new Date() < nextAllowed) {
          this.logger.log(`Alert cooldown active for config ${config.id} tenant=${params.tenantId} meter=${params.meterKey} until ${nextAllowed.toISOString()}`);
          continue;
        }
      }

      let shouldTrigger = false;

      if (config.thresholdType === AlertThresholdType.PERCENTAGE) {
        if (params.utilizationPercent !== null && params.utilizationPercent >= config.thresholdValue) {
          shouldTrigger = true;
        }
      } else if (config.thresholdType === AlertThresholdType.ABSOLUTE) {
        if (params.currentValue >= config.thresholdValue) {
          shouldTrigger = true;
        }
      }

      if (shouldTrigger) {
        const idempotencyKey = `alert_${params.tenantId}_${config.id}_${params.periodId}_${config.thresholdValue}`;

        // Deduplication check
        const existing = await this.findEventByIdempotencyKey(idempotencyKey, params.tenantId);
        if (existing) {
          this.logger.log(`Duplicate alert suppressed by idempotencyKey: ${idempotencyKey}`);
          continue;
        }

        const event = await this.createAlertEvent({
          tenantId: params.tenantId,
          configId: config.id,
          meterKey: params.meterKey,
          limitKey: params.limitKey,
          thresholdType: config.thresholdType,
          thresholdValue: config.thresholdValue,
          currentValue: params.currentValue,
          maximumValue: params.maximumValue,
          utilizationPercent: params.utilizationPercent,
          severity: config.severity,
          periodId: params.periodId,
          idempotencyKey,
          safeMetadata: {
            meterKey: params.meterKey,
            limitKey: params.limitKey,
            currentValue: params.currentValue,
            maximumValue: params.maximumValue,
          },
        });

        triggeredEvents.push(event);

        // Update last triggered
        await this.updateConfigLastTriggered(config.id);

        // Trigger billing notification for usage threshold
        if (this.billingEventService) {
          this.billingEventService.onUsageThresholdReached({
            tenantId: params.tenantId,
            meterKey: params.meterKey,
            limitKey: params.limitKey,
            usagePercentage: params.utilizationPercent || config.thresholdValue,
            currentUsage: params.currentValue,
            maxLimit: params.maximumValue,
            supportEmail: process.env.SUPPORT_EMAIL || 'support@example.com',
            appName: process.env.APP_NAME || 'WLCT',
          }).catch((e) => this.logger.warn(`Failed to trigger usage threshold notification: ${e.message}`));
        }

        this.logger.log(
          `Usage alert triggered tenant=${params.tenantId} meter=${params.meterKey} threshold=${config.thresholdValue}${config.thresholdType === AlertThresholdType.PERCENTAGE ? '%' : ''} current=${params.currentValue} max=${params.maximumValue} severity=${config.severity}`,
        );
      }
    }

    return triggeredEvents;
  }

  async getAlertConfigs(tenantId: string, meterKey?: MeterKey, limitKey?: string): Promise<UsageAlertConfig[]> {
    try {
      const where: any = { tenantId };
      if (meterKey) where.meterKey = meterKey;
      if (limitKey) where.limitKey = limitKey;

      const results = await (this.prisma as any).usageAlertConfig?.findMany({
        where,
        orderBy: { thresholdValue: 'asc' },
      });

      if (results && results.length > 0) {
        return results.map((r: any) => this.mapConfigToDomain(r));
      }

      // Fallback: return default thresholds as configs if none configured
      if (meterKey && limitKey) {
        return this.DEFAULT_THRESHOLDS.map((t) => ({
          id: `default_${tenantId}_${meterKey}_${t.percentage}`,
          tenantId,
          meterKey: meterKey!,
          limitKey: limitKey!,
          thresholdType: AlertThresholdType.PERCENTAGE,
          thresholdValue: t.percentage,
          severity: t.severity,
          enabled: true,
          cooldownMinutes: 60,
          lastTriggeredAt: null,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
          metadata: { default: true },
        }));
      }

      return [];
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        // Return defaults if table missing
        if (meterKey && limitKey) {
          return this.DEFAULT_THRESHOLDS.map((t) => ({
            id: `default_${tenantId}_${meterKey}_${t.percentage}`,
            tenantId,
            meterKey: meterKey!,
            limitKey: limitKey!,
            thresholdType: AlertThresholdType.PERCENTAGE,
            thresholdValue: t.percentage,
            severity: t.severity,
            enabled: true,
            cooldownMinutes: 60,
            lastTriggeredAt: null,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
            metadata: { default: true },
          }));
        }
        return [];
      }
      throw error;
    }
  }

  async createAlertConfig(params: {
    tenantId: string;
    meterKey: MeterKey;
    limitKey: string;
    thresholdType: AlertThresholdType;
    thresholdValue: number;
    severity: AlertSeverity;
    enabled?: boolean;
    cooldownMinutes?: number;
  }): Promise<UsageAlertConfig> {
    // Validate threshold range
    if (params.thresholdType === AlertThresholdType.PERCENTAGE) {
      if (params.thresholdValue < 1 || params.thresholdValue > 200) {
        throw new Error('Percentage threshold must be 1-200');
      }
    } else {
      if (params.thresholdValue < 1) {
        throw new Error('Absolute threshold must be >=1');
      }
    }

    const id = randomUUID();
    const now = new Date().toISOString();

    const config: UsageAlertConfig = {
      id,
      tenantId: params.tenantId,
      meterKey: params.meterKey,
      limitKey: params.limitKey,
      thresholdType: params.thresholdType,
      thresholdValue: params.thresholdValue,
      severity: params.severity,
      enabled: params.enabled ?? true,
      cooldownMinutes: params.cooldownMinutes ?? 60,
      lastTriggeredAt: null,
      createdAt: now,
      updatedAt: now,
      metadata: null,
    };

    try {
      const created = await (this.prisma as any).usageAlertConfig?.create({
        data: {
          id: config.id,
          tenantId: config.tenantId,
          meterKey: config.meterKey,
          limitKey: config.limitKey,
          thresholdType: config.thresholdType,
          thresholdValue: config.thresholdValue,
          severity: config.severity,
          enabled: config.enabled,
          cooldownMinutes: config.cooldownMinutes,
          lastTriggeredAt: null,
          createdAt: new Date(config.createdAt),
          updatedAt: new Date(config.updatedAt),
        },
      });

      if (created) return this.mapConfigToDomain(created);
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        this.logger.warn(`usageAlertConfig table not found, fallback: ${error.message}`);
        return config;
      }
      throw error;
    }

    return config;
  }

  async updateAlertConfig(
    id: string,
    tenantId: string,
    updates: { enabled?: boolean; thresholdValue?: number; severity?: AlertSeverity; cooldownMinutes?: number },
  ): Promise<UsageAlertConfig | null> {
    try {
      const data: any = { updatedAt: new Date() };
      if (updates.enabled !== undefined) data.enabled = updates.enabled;
      if (updates.thresholdValue !== undefined) data.thresholdValue = updates.thresholdValue;
      if (updates.severity !== undefined) data.severity = updates.severity;
      if (updates.cooldownMinutes !== undefined) data.cooldownMinutes = updates.cooldownMinutes;

      const updated = await (this.prisma as any).usageAlertConfig?.update({
        where: { id, tenantId },
        data,
      });

      if (!updated) return null;
      return this.mapConfigToDomain(updated);
    } catch (error) {
      if (isRecordNotFound(error)) return null;
      throw error;
    }
  }

  async listAlertEvents(
    tenantId: string,
    filter?: { meterKey?: MeterKey; severity?: AlertSeverity; state?: AlertState; fromDate?: Date; toDate?: Date; limit?: number; offset?: number },
  ): Promise<UsageAlertEvent[]> {
    const where: any = { tenantId };
    if (filter?.meterKey) where.meterKey = filter.meterKey;
    if (filter?.severity) where.severity = filter.severity;
    if (filter?.state) where.state = filter.state;
    if (filter?.fromDate || filter?.toDate) {
      where.triggeredAt = {};
      if (filter.fromDate) where.triggeredAt.gte = filter.fromDate;
      if (filter.toDate) where.triggeredAt.lte = filter.toDate;
    }

    const results = await (this.prisma as any).usageAlertEvent?.findMany({
      where,
      orderBy: { triggeredAt: 'desc' },
      take: filter?.limit || 100,
      skip: filter?.offset || 0,
    });

    if (!results) return [];
    return results.map((r: any) => this.mapEventToDomain(r));
  }

  private async createAlertEvent(params: {
    tenantId: string;
    configId: string;
    meterKey: MeterKey;
    limitKey: string;
    thresholdType: AlertThresholdType;
    thresholdValue: number;
    currentValue: number;
    maximumValue: number | null;
    utilizationPercent: number | null;
    severity: AlertSeverity;
    periodId: string;
    idempotencyKey: string;
    safeMetadata?: Record<string, unknown> | null;
  }): Promise<UsageAlertEvent> {
    const id = randomUUID();
    const now = new Date().toISOString();

    const event: UsageAlertEvent = {
      id,
      tenantId: params.tenantId,
      configId: params.configId,
      meterKey: params.meterKey,
      limitKey: params.limitKey,
      thresholdType: params.thresholdType,
      thresholdValue: params.thresholdValue,
      currentValue: params.currentValue,
      maximumValue: params.maximumValue,
      utilizationPercent: params.utilizationPercent,
      severity: params.severity,
      state: AlertState.TRIGGERED,
      periodId: params.periodId,
      triggeredAt: now,
      acknowledgedAt: null,
      resolvedAt: null,
      deliveryState: 'PENDING',
      idempotencyKey: params.idempotencyKey,
      safeMetadata: params.safeMetadata || null,
      createdAt: now,
    };

    try {
      const created = await (this.prisma as any).usageAlertEvent?.create({
        data: {
          id: event.id,
          tenantId: event.tenantId,
          configId: event.configId,
          meterKey: event.meterKey,
          limitKey: event.limitKey,
          thresholdType: event.thresholdType,
          thresholdValue: event.thresholdValue,
          currentValue: event.currentValue,
          maximumValue: event.maximumValue,
          utilizationPercent: event.utilizationPercent,
          severity: event.severity,
          state: event.state,
          periodId: event.periodId,
          triggeredAt: new Date(event.triggeredAt),
          deliveryState: event.deliveryState,
          idempotencyKey: event.idempotencyKey,
          safeMetadata: event.safeMetadata,
          createdAt: new Date(event.createdAt),
        },
      });

      if (created) return this.mapEventToDomain(created);
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        this.logger.warn(`usageAlertEvent table not found, fallback: ${error.message}`);
        try {
          await (this.prisma as any).auditLog?.create({
            data: {
              id: randomUUID(),
              tenantId: params.tenantId,
              action: 'USAGE_ALERT_TRIGGERED',
              resourceType: 'UsageAlert',
              resourceId: id,
              metadata: { ...event, fallback: true },
              createdAt: new Date(),
            },
          });
        } catch {}
        return event;
      }
      if (error.code === 'P2002') {
        const existing = await this.findEventByIdempotencyKey(params.idempotencyKey, params.tenantId);
        if (existing) return existing;
      }
      throw error;
    }

    return event;
  }

  private async findEventByIdempotencyKey(idempotencyKey: string, tenantId: string): Promise<UsageAlertEvent | null> {
    const result = await (this.prisma as any).usageAlertEvent?.findFirst({
      where: { idempotencyKey, tenantId },
    });
    if (!result) return null;
    return this.mapEventToDomain(result);
  }

  private async updateConfigLastTriggered(id: string): Promise<void> {
    try {
      await (this.prisma as any).usageAlertConfig?.update({
        where: { id },
        data: { lastTriggeredAt: new Date(), updatedAt: new Date() },
      });
    } catch {}
  }

  private mapConfigToDomain(raw: any): UsageAlertConfig {
    return {
      id: raw.id,
      tenantId: raw.tenantId,
      meterKey: raw.meterKey as MeterKey,
      limitKey: raw.limitKey,
      thresholdType: raw.thresholdType as AlertThresholdType,
      thresholdValue: raw.thresholdValue,
      severity: raw.severity as AlertSeverity,
      enabled: raw.enabled,
      cooldownMinutes: raw.cooldownMinutes,
      lastTriggeredAt: raw.lastTriggeredAt ? new Date(raw.lastTriggeredAt).toISOString() : null,
      createdAt: raw.createdAt ? new Date(raw.createdAt).toISOString() : new Date().toISOString(),
      updatedAt: raw.updatedAt ? new Date(raw.updatedAt).toISOString() : new Date().toISOString(),
      metadata: raw.metadata || null,
    };
  }

  private mapEventToDomain(raw: any): UsageAlertEvent {
    return {
      id: raw.id,
      tenantId: raw.tenantId,
      configId: raw.configId,
      meterKey: raw.meterKey as MeterKey,
      limitKey: raw.limitKey,
      thresholdType: raw.thresholdType as AlertThresholdType,
      thresholdValue: raw.thresholdValue,
      currentValue: raw.currentValue,
      maximumValue: raw.maximumValue,
      utilizationPercent: raw.utilizationPercent,
      severity: raw.severity as AlertSeverity,
      state: raw.state as AlertState,
      periodId: raw.periodId,
      triggeredAt: raw.triggeredAt ? new Date(raw.triggeredAt).toISOString() : new Date().toISOString(),
      acknowledgedAt: raw.acknowledgedAt ? new Date(raw.acknowledgedAt).toISOString() : null,
      resolvedAt: raw.resolvedAt ? new Date(raw.resolvedAt).toISOString() : null,
      deliveryState: raw.deliveryState,
      idempotencyKey: raw.idempotencyKey,
      safeMetadata: raw.safeMetadata || null,
      createdAt: raw.createdAt ? new Date(raw.createdAt).toISOString() : new Date().toISOString(),
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { UsageEventRepository } from './usage-event.repository';
import { UsageMeterRepository } from './usage-meter.repository';
import { UsagePeriodService } from './usage-period.service';
import { QuotaSnapshotService } from './quota-snapshot.service';
import { OverageService } from './overage.service';
import { MeterKey, UsageScope } from './usage-metering.types';

/**
 * Usage analytics for tenants/SaaS admins: period totals, trends, utilization,
 * top meters, limit pressure, overage exposure.
 * All based on canonical durable usage data, no independent counters.
 */
@Injectable()
export class UsageAnalyticsService {
  private readonly logger = new Logger(UsageAnalyticsService.name);

  constructor(
    private readonly eventRepository: UsageEventRepository,
    private readonly meterRepository: UsageMeterRepository,
    private readonly periodService: UsagePeriodService,
    private readonly quotaService: QuotaSnapshotService,
    private readonly overageService: OverageService,
  ) {}

  async getCurrentUsageOverview(tenantId: string, periodId?: string): Promise<any> {
    const quotaOverview = await this.quotaService.getTenantQuotaOverview(tenantId, periodId);
    const tenantTotals = await this.meterRepository.getTenantTotals(tenantId);

    const utilization = quotaOverview.map((q) => ({
      meterKey: q.meterKey,
      limitKey: q.limitKey,
      current: q.current,
      maximum: q.maximum,
      remaining: q.remaining,
      utilizationPercent: q.utilizationPercent,
      status: q.status,
      isEnforced: q.isEnforced,
    }));

    // Calculate limit pressure (how close to limits)
    const pressure = utilization
      .filter((u) => u.maximum !== null && u.utilizationPercent !== null)
      .sort((a, b) => (b.utilizationPercent || 0) - (a.utilizationPercent || 0))
      .slice(0, 5);

    return {
      tenantId,
      periodId: periodId || this.periodService.getCurrentCalendarMonthPeriod(tenantId).id,
      currentUsage: utilization,
      tenantTotals,
      limitPressure: pressure,
      fetchedAt: new Date().toISOString(),
    };
  }

  async getUsageTrends(
    tenantId: string,
    params: { meterKey?: MeterKey; days?: number; fromDate?: Date; toDate?: Date },
  ): Promise<any> {
    const days = params.days || 30;
    const toDate = params.toDate || new Date();
    const fromDate = params.fromDate || new Date(toDate.getTime() - days * 24 * 60 * 60 * 1000);

    const events = await this.eventRepository.listByTenant(tenantId, {
      meterKey: params.meterKey,
      fromDate,
      toDate,
      limit: 10000,
    });

    // Group by day
    const dailyMap = new Map<string, { date: string; totalQuantity: number; eventCount: number; meters: Record<string, number> }>();

    for (const event of events) {
      const dateKey = new Date(event.timestamp).toISOString().split('T')[0];
      const existing = dailyMap.get(dateKey) || { date: dateKey, totalQuantity: 0, eventCount: 0, meters: {} };
      existing.totalQuantity += event.quantity;
      existing.eventCount += 1;
      existing.meters[event.meterKey] = (existing.meters[event.meterKey] || 0) + event.quantity;
      dailyMap.set(dateKey, existing);
    }

    const dailyTrends = Array.from(dailyMap.values()).sort((a, b) => a.date.localeCompare(b.date));

    // Calculate trend direction
    let trend: 'increasing' | 'decreasing' | 'stable' = 'stable';
    if (dailyTrends.length >= 2) {
      const recent = dailyTrends.slice(-7);
      const older = dailyTrends.slice(-14, -7);
      const recentAvg = recent.reduce((sum, d) => sum + d.totalQuantity, 0) / (recent.length || 1);
      const olderAvg = older.length > 0 ? older.reduce((sum, d) => sum + d.totalQuantity, 0) / older.length : recentAvg;
      if (recentAvg > olderAvg * 1.1) trend = 'increasing';
      else if (recentAvg < olderAvg * 0.9) trend = 'decreasing';
    }

    return {
      tenantId,
      meterKey: params.meterKey || 'ALL',
      period: { from: fromDate.toISOString(), to: toDate.toISOString(), days },
      dailyTrends,
      trend,
      totalEvents: events.length,
      totalQuantity: events.reduce((sum, e) => sum + e.quantity, 0),
      fetchedAt: new Date().toISOString(),
    };
  }

  async getTopMeters(tenantId: string, limit: number = 10, fromDate?: Date, toDate?: Date): Promise<any[]> {
    const totals = await this.meterRepository.getTenantTotals(tenantId, undefined, undefined, fromDate, toDate);

    return totals
      .sort((a, b) => b.totalQuantity - a.totalQuantity)
      .slice(0, limit)
      .map((t) => ({
        meterKey: t.meterKey,
        totalQuantity: t.totalQuantity,
        eventCount: t.eventCount,
        averagePerEvent: t.eventCount > 0 ? t.totalQuantity / t.eventCount : 0,
      }));
  }

  async getLimitPressure(tenantId: string): Promise<any[]> {
    const quotaOverview = await this.quotaService.getTenantQuotaOverview(tenantId);

    return quotaOverview
      .filter((q) => q.maximum !== null && q.utilizationPercent !== null)
      .map((q) => ({
        meterKey: q.meterKey,
        limitKey: q.limitKey,
        current: q.current,
        maximum: q.maximum,
        remaining: q.remaining,
        utilizationPercent: q.utilizationPercent,
        status: q.status,
        pressure: q.utilizationPercent || 0,
        isEnforced: q.isEnforced,
      }))
      .sort((a, b) => (b.utilizationPercent || 0) - (a.utilizationPercent || 0));
  }

  async getOverageExposure(tenantId: string, fromDate?: Date, toDate?: Date): Promise<any> {
    const overages = await this.overageService.listOverages(tenantId, {
      fromDate,
      toDate,
      limit: 100,
    });

    const totalExcess = overages.reduce((sum, o) => sum + (o.excessQuantity || 0), 0);
    const byMeter: Record<string, number> = {};
    const byStatus: Record<string, number> = {};

    for (const o of overages) {
      byMeter[o.meterKey] = (byMeter[o.meterKey] || 0) + o.excessQuantity;
      byStatus[o.status] = (byStatus[o.status] || 0) + 1;
    }

    return {
      tenantId,
      totalOverages: overages.length,
      totalExcessQuantity: totalExcess,
      byMeter,
      byStatus,
      overages: overages.slice(0, 20),
      fetchedAt: new Date().toISOString(),
    };
  }

  async getApiUsageAnalytics(tenantId: string, days: number = 7): Promise<any> {
    const toDate = new Date();
    const fromDate = new Date(toDate.getTime() - days * 24 * 60 * 60 * 1000);

    const events = await this.eventRepository.listByTenant(tenantId, {
      meterKey: MeterKey.API_REQUESTS,
      fromDate,
      toDate,
      limit: 10000,
    });

    const byEndpoint: Record<string, number> = {};
    const byIdentity: Record<string, number> = {};
    const hourlyMap = new Map<string, number>();

    for (const event of events) {
      const endpoint = (event.dimensions as any)?.endpoint || 'unknown';
      byEndpoint[endpoint] = (byEndpoint[endpoint] || 0) + 1;

      const identity = event.subjectId || 'unknown';
      byIdentity[identity] = (byIdentity[identity] || 0) + 1;

      const hourKey = new Date(event.timestamp).toISOString().substring(0, 13);
      hourlyMap.set(hourKey, (hourlyMap.get(hourKey) || 0) + event.quantity);
    }

    const hourlyTrends = Array.from(hourlyMap.entries())
      .map(([hour, count]) => ({ hour, count }))
      .sort((a, b) => a.hour.localeCompare(b.hour));

    return {
      tenantId,
      period: { from: fromDate.toISOString(), to: toDate.toISOString(), days },
      totalRequests: events.length,
      byEndpoint: Object.entries(byEndpoint)
        .map(([endpoint, count]) => ({ endpoint, count }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 20),
      byIdentity: Object.entries(byIdentity)
        .map(([identity, count]) => ({ identity, count }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 20),
      hourlyTrends,
      fetchedAt: new Date().toISOString(),
    };
  }

  async getProjectedUsage(tenantId: string, meterKey: MeterKey): Promise<any> {
    const currentPeriod = this.periodService.getCurrentCalendarMonthPeriod(tenantId);
    const start = new Date(currentPeriod.start);
    const now = new Date();
    const end = new Date(currentPeriod.end);

    const events = await this.eventRepository.listByTenant(tenantId, {
      meterKey,
      fromDate: start,
      toDate: now,
      limit: 10000,
    });

    const elapsedMs = now.getTime() - start.getTime();
    const totalPeriodMs = end.getTime() - start.getTime();
    const currentTotal = events.reduce((sum, e) => sum + e.quantity, 0);

    let projectedTotal = currentTotal;
    if (elapsedMs > 0 && totalPeriodMs > 0) {
      const progress = elapsedMs / totalPeriodMs;
      projectedTotal = progress > 0 ? Math.round(currentTotal / progress) : currentTotal;
    }

    const quota = await this.quotaService.getQuotaSnapshot({
      tenantId,
      meterKey,
      scope: UsageScope.TENANT,
      periodId: currentPeriod.id,
    });

    return {
      tenantId,
      meterKey,
      currentPeriod: {
        id: currentPeriod.id,
        start: currentPeriod.start,
        end: currentPeriod.end,
        elapsedDays: Math.floor(elapsedMs / (24 * 60 * 60 * 1000)),
        totalDays: Math.floor(totalPeriodMs / (24 * 60 * 60 * 1000)),
        progressPercent: totalPeriodMs > 0 ? Math.round((elapsedMs / totalPeriodMs) * 100) : 0,
      },
      currentTotal,
      projectedTotal,
      maximum: quota.maximum,
      projectedUtilization: quota.maximum ? Math.round((projectedTotal / quota.maximum) * 100) : null,
      willExceed: quota.maximum ? projectedTotal > quota.maximum : false,
      fetchedAt: new Date().toISOString(),
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { DurableUsageEvent, ProcessingState, MeterKey, UsageScope, MeterUnit, PeriodType } from './usage-metering.types';
import { randomUUID } from 'crypto';
import { isRecordNotFound } from '../../../common/errors/prisma-not-found';

/** Record fields without a UsageEvent column, stored in `metadata` under this key. */
export const USAGE_RECORD_METADATA_KEY = '_usage';

/**
 * Durable event store for metered usage events with idempotency, source references,
 * tenant isolation, and processing state. Safe replay without double counting.
 */
@Injectable()
export class UsageEventRepository {
  private readonly logger = new Logger(UsageEventRepository.name);

  constructor(private readonly prisma: PrismaService) {}

  async create(event: {
    tenantId: string;
    meterKey: MeterKey;
    scope: UsageScope;
    subjectId?: string;
    resourceId?: string;
    quantity: number;
    unit: MeterUnit;
    sourceType: string;
    sourceId: string;
    sourceEventId?: string;
    periodId: string;
    periodType: PeriodType;
    periodStart: Date;
    periodEnd: Date;
    timestamp: Date;
    idempotencyKey: string;
    processingState: ProcessingState;
    dimensions: any;
    safeMetadata?: Record<string, unknown> | null;
  }): Promise<DurableUsageEvent> {
    // Idempotency check
    const existingByKey = await this.findByIdempotencyKey(event.idempotencyKey, event.tenantId);
    if (existingByKey) {
      this.logger.log(`Idempotent event return by idempotencyKey: ${event.idempotencyKey}`);
      return existingByKey;
    }

    const existingBySource = await this.findBySourceId(event.tenantId, event.sourceId, event.meterKey);
    if (existingBySource) {
      this.logger.log(`Idempotent event return by source: ${event.sourceId} meter=${event.meterKey}`);
      return existingBySource;
    }

    const id = randomUUID();
    const now = new Date().toISOString();

    const durableEvent: DurableUsageEvent = {
      id,
      tenantId: event.tenantId,
      meterKey: event.meterKey,
      scope: event.scope,
      subjectId: event.subjectId,
      resourceId: event.resourceId,
      quantity: event.quantity,
      unit: event.unit,
      sourceType: event.sourceType,
      sourceId: event.sourceId,
      sourceEventId: event.sourceEventId,
      periodId: event.periodId,
      periodType: event.periodType,
      periodStart: event.periodStart.toISOString(),
      periodEnd: event.periodEnd.toISOString(),
      timestamp: event.timestamp.toISOString(),
      idempotencyKey: event.idempotencyKey,
      processingState: event.processingState,
      dimensions: event.dimensions,
      safeMetadata: event.safeMetadata || null,
      createdAt: now,
      updatedAt: now,
    };

    try {
      // UsageEvent columns only: status = processing state, createdAt = event
      // time; the remaining record fields live in metadata._usage. Unknown
      // columns (scope, unit, timestamp, ...) made Prisma reject every event.
      const created = await (this.prisma as any).usageEvent?.create({
        data: {
          id: durableEvent.id,
          tenantId: durableEvent.tenantId,
          meterKey: durableEvent.meterKey,
          eventType: durableEvent.scope,
          sourceType: durableEvent.sourceType,
          sourceId: durableEvent.sourceId,
          quantity: Number.isInteger(durableEvent.quantity) ? durableEvent.quantity : Math.round(durableEvent.quantity),
          periodId: durableEvent.periodId,
          idempotencyKey: durableEvent.idempotencyKey,
          status: durableEvent.processingState,
          metadata: {
            [USAGE_RECORD_METADATA_KEY]: {
              scope: durableEvent.scope,
              subjectId: durableEvent.subjectId || null,
              resourceId: durableEvent.resourceId || null,
              quantity: durableEvent.quantity,
              unit: durableEvent.unit,
              sourceEventId: durableEvent.sourceEventId || null,
              periodType: durableEvent.periodType,
              periodStart: event.periodStart.toISOString(),
              periodEnd: event.periodEnd.toISOString(),
              timestamp: event.timestamp.toISOString(),
              dimensions: durableEvent.dimensions,
            },
          } as any,
          safeMetadata: (durableEvent.safeMetadata ?? {}) as any,
          createdAt: event.timestamp,
        },
      });

      if (created) {
        return this.mapToDomain(created);
      }
    } catch (error: any) {
      if (error.code === 'P2002') {
        this.logger.warn(`Duplicate usage event idempotency: ${event.idempotencyKey}`);
        const existing = await this.findByIdempotencyKey(event.idempotencyKey, event.tenantId);
        if (existing) return existing;
        const bySource = await this.findBySourceId(event.tenantId, event.sourceId, event.meterKey);
        if (bySource) return bySource;
      }
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        this.logger.warn(`usageEvent table not found, fallback: ${error.message}`);
        try {
          await (this.prisma as any).auditLog?.create({
            data: {
              id: randomUUID(),
              tenantId: event.tenantId,
              action: 'USAGE_EVENT_RECORDED',
              resourceType: 'UsageEvent',
              resourceId: id,
              metadata: { ...durableEvent, fallback: true },
              createdAt: new Date(),
            },
          });
        } catch {}
        return durableEvent;
      }
      this.logger.error(`Failed to create usage event: ${error.message}`, error.stack);
      throw error;
    }

    return durableEvent;
  }

  async findById(id: string, tenantId?: string): Promise<DurableUsageEvent | null> {
    const result = await (this.prisma as any).usageEvent?.findFirst({
      where: { id, ...(tenantId ? { tenantId } : {}) },
    });
    if (!result) return null;
    return this.mapToDomain(result);
  }

  async findByIdempotencyKey(idempotencyKey: string, tenantId: string): Promise<DurableUsageEvent | null> {
    const result = await (this.prisma as any).usageEvent?.findFirst({
      where: { idempotencyKey, tenantId },
    });
    if (!result) return null;
    return this.mapToDomain(result);
  }

  async findBySourceId(tenantId: string, sourceId: string, meterKey?: MeterKey): Promise<DurableUsageEvent | null> {
    const result = await (this.prisma as any).usageEvent?.findFirst({
      where: {
        tenantId,
        sourceId,
        ...(meterKey ? { meterKey } : {}),
      },
      orderBy: { createdAt: 'desc' },
    });
    if (!result) return null;
    return this.mapToDomain(result);
  }

  async listByTenant(
    tenantId: string,
    filter?: {
      meterKey?: MeterKey;
      scope?: UsageScope;
      subjectId?: string;
      sourceType?: string;
      processingState?: ProcessingState;
      periodId?: string;
      fromDate?: Date;
      toDate?: Date;
      limit?: number;
      offset?: number;
    },
  ): Promise<DurableUsageEvent[]> {
    const where: any = { tenantId };
    if (filter?.meterKey) where.meterKey = filter.meterKey;
    const jsonFilters: any[] = [];
    if (filter?.scope) jsonFilters.push({ metadata: { path: [USAGE_RECORD_METADATA_KEY, 'scope'], equals: filter.scope } });
    if (filter?.subjectId) jsonFilters.push({ metadata: { path: [USAGE_RECORD_METADATA_KEY, 'subjectId'], equals: filter.subjectId } });
    if (jsonFilters.length > 0) where.AND = jsonFilters;
    if (filter?.sourceType) where.sourceType = filter.sourceType;
    if (filter?.processingState) where.status = filter.processingState;
    if (filter?.periodId) where.periodId = filter.periodId;
    if (filter?.fromDate || filter?.toDate) {
      where.createdAt = {};
      if (filter.fromDate) where.createdAt.gte = filter.fromDate;
      if (filter.toDate) where.createdAt.lte = filter.toDate;
    }

    const results = await (this.prisma as any).usageEvent?.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: filter?.limit || 100,
      skip: filter?.offset || 0,
    });

    if (!results) return [];
    return results.map((r: any) => this.mapToDomain(r));
  }

  async updateProcessingState(id: string, state: ProcessingState, error?: string): Promise<DurableUsageEvent | null> {
    try {
      const updated = await (this.prisma as any).usageEvent?.update({
        where: { id },
        data: {
          status: state,
          ...(error ? { safeMetadata: { error } } : {}),
        },
      });
      if (!updated) return null;
      return this.mapToDomain(updated);
    } catch (error) {
      if (isRecordNotFound(error)) return null;
      throw error;
    }
  }

  async countByPeriod(tenantId: string, periodId: string, meterKey?: MeterKey): Promise<number> {
    const count = await (this.prisma as any).usageEvent?.count({
      where: {
        tenantId,
        periodId,
        ...(meterKey ? { meterKey } : {}),
      },
    });
    return count || 0;
  }

  private mapToDomain(raw: any): DurableUsageEvent {
    const metadata = raw.metadata && typeof raw.metadata === 'object' ? raw.metadata : {};
    const record: any = metadata[USAGE_RECORD_METADATA_KEY] && typeof metadata[USAGE_RECORD_METADATA_KEY] === 'object' ? metadata[USAGE_RECORD_METADATA_KEY] : {};
    const iso = (value: unknown, fallback: unknown): string =>
      value ? new Date(value as string).toISOString() : fallback ? new Date(fallback as string).toISOString() : new Date().toISOString();
    const scope = (record.scope ?? raw.eventType) as UsageScope;
    return {
      id: raw.id,
      tenantId: raw.tenantId,
      meterKey: raw.meterKey as MeterKey,
      scope,
      subjectId: record.subjectId || undefined,
      resourceId: record.resourceId || undefined,
      quantity: typeof record.quantity === 'number' ? record.quantity : raw.quantity || 0,
      unit: record.unit as MeterUnit,
      sourceType: raw.sourceType,
      sourceId: raw.sourceId,
      sourceEventId: record.sourceEventId || undefined,
      periodId: raw.periodId,
      periodType: record.periodType as PeriodType,
      periodStart: iso(record.periodStart, raw.createdAt),
      periodEnd: iso(record.periodEnd, raw.createdAt),
      timestamp: iso(record.timestamp, raw.createdAt),
      idempotencyKey: raw.idempotencyKey,
      processingState: raw.status as ProcessingState,
      dimensions: record.dimensions || { tenantId: raw.tenantId, scope },
      safeMetadata: raw.safeMetadata && Object.keys(raw.safeMetadata).length > 0 ? raw.safeMetadata : null,
      createdAt: iso(raw.createdAt, null),
      updatedAt: iso(raw.createdAt, null),
    };
  }

}

import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { UsageEventRepository } from './usage-event.repository';
import { UsageMeterRepository } from './usage-meter.repository';
import { UsagePeriodService } from './usage-period.service';
import { QuotaSnapshotService } from './quota-snapshot.service';
import { MeterKey, UsageScope } from './usage-metering.types';

/**
 * Produces tenant/admin usage exports in safe structured formats using canonical metered data.
 * Safe fields only, no secrets, bounded pagination.
 */
@Injectable()
export class UsageExportService {
  private readonly logger = new Logger(UsageExportService.name);

  constructor(
    private readonly eventRepository: UsageEventRepository,
    private readonly meterRepository: UsageMeterRepository,
    private readonly periodService: UsagePeriodService,
    private readonly quotaService: QuotaSnapshotService,
  ) {}

  async exportUsageJson(params: {
    tenantId: string;
    format: 'json' | 'csv';
    fromDate?: Date;
    toDate?: Date;
    meterKeys?: MeterKey[];
    scope?: UsageScope;
    subjectId?: string;
    includeQuota?: boolean;
    includeOverage?: boolean;
    limit?: number;
  }): Promise<{ format: string; data: any; exportedAt: string; tenantId: string; recordCount: number }> {
    const limit = Math.min(params.limit || 1000, 10000); // Bounded

    let events: any[] = [];

    // Fetch events for each meter key or all
    if (params.meterKeys && params.meterKeys.length > 0) {
      for (const meterKey of params.meterKeys) {
        const meterEvents = await this.eventRepository.listByTenant(params.tenantId, {
          meterKey,
          scope: params.scope,
          subjectId: params.subjectId,
          fromDate: params.fromDate,
          toDate: params.toDate,
          limit,
        });
        events = events.concat(meterEvents);
      }
    } else {
      events = await this.eventRepository.listByTenant(params.tenantId, {
        scope: params.scope,
        subjectId: params.subjectId,
        fromDate: params.fromDate,
        toDate: params.toDate,
        limit,
      });
    }

    // Sort deterministically by timestamp
    events.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());

    // Build safe export records
    const safeRecords = events.map((e) => ({
      id: e.id,
      tenantId: e.tenantId,
      meterKey: e.meterKey,
      scope: e.scope,
      subjectId: e.subjectId || null,
      resourceId: e.resourceId || null,
      quantity: e.quantity,
      unit: e.unit,
      sourceType: e.sourceType,
      sourceId: e.sourceId,
      periodId: e.periodId,
      periodType: e.periodType,
      periodStart: e.periodStart,
      periodEnd: e.periodEnd,
      timestamp: e.timestamp,
      processingState: e.processingState,
      dimensions: this.sanitizeDimensions(e.dimensions),
      createdAt: e.createdAt,
    }));

    let quotaSnapshots: any[] = [];
    if (params.includeQuota) {
      try {
        quotaSnapshots = await this.quotaService.getTenantQuotaOverview(params.tenantId);
        // Sanitize quota snapshots to safe fields
        quotaSnapshots = quotaSnapshots.map((q) => ({
          meterKey: q.meterKey,
          limitKey: q.limitKey,
          scope: q.scope,
          subjectId: q.subjectId || null,
          maximum: q.maximum,
          current: q.current,
          remaining: q.remaining,
          utilizationPercent: q.utilizationPercent,
          status: q.status,
          periodId: q.periodId,
          periodStart: q.periodStart,
          periodEnd: q.periodEnd,
          isEnforced: q.isEnforced,
        }));
      } catch {}
    }

    const exportData = {
      tenantId: params.tenantId,
      exportedAt: new Date().toISOString(),
      period: {
        from: params.fromDate ? params.fromDate.toISOString() : null,
        to: params.toDate ? params.toDate.toISOString() : null,
      },
      filters: {
        meterKeys: params.meterKeys || null,
        scope: params.scope || null,
        subjectId: params.subjectId || null,
      },
      summary: {
        totalEvents: safeRecords.length,
        totalQuantity: safeRecords.reduce((sum, r) => sum + (r.quantity || 0), 0),
        meterBreakdown: this.buildMeterBreakdown(safeRecords),
      },
      events: safeRecords,
      quotaSnapshots: params.includeQuota ? quotaSnapshots : undefined,
    };

    this.logger.log(`Usage export tenant=${params.tenantId} format=${params.format} records=${safeRecords.length}`);

    return {
      format: params.format,
      data: exportData,
      exportedAt: new Date().toISOString(),
      tenantId: params.tenantId,
      recordCount: safeRecords.length,
    };
  }

  async exportUsageCsv(params: {
    tenantId: string;
    fromDate?: Date;
    toDate?: Date;
    meterKeys?: MeterKey[];
    scope?: UsageScope;
    subjectId?: string;
    limit?: number;
  }): Promise<{ format: 'csv'; csv: string; exportedAt: string; tenantId: string; recordCount: number }> {
    const jsonExport = await this.exportUsageJson({
      tenantId: params.tenantId,
      format: 'json',
      fromDate: params.fromDate,
      toDate: params.toDate,
      meterKeys: params.meterKeys,
      scope: params.scope,
      subjectId: params.subjectId,
      limit: params.limit,
    });

    const headers = ['id', 'meterKey', 'scope', 'subjectId', 'quantity', 'unit', 'sourceType', 'sourceId', 'periodId', 'timestamp'];
    const rows = [headers.join(',')];

    for (const event of jsonExport.data.events) {
      const row = [
        event.id,
        event.meterKey,
        event.scope,
        event.subjectId || '',
        event.quantity,
        event.unit,
        event.sourceType,
        event.sourceId,
        event.periodId,
        event.timestamp,
      ]
        .map((v) => `"${String(v).replace(/"/g, '""')}"`)
        .join(',');
      rows.push(row);
    }

    const csv = rows.join('\n');

    return {
      format: 'csv',
      csv,
      exportedAt: new Date().toISOString(),
      tenantId: params.tenantId,
      recordCount: jsonExport.recordCount,
    };
  }

  async getExportStatus(exportId: string, tenantId: string): Promise<{ id: string; status: string; tenantId: string; createdAt: string }> {
    // Exports are produced synchronously (exportJson / exportCsv return the
    // data in the response) and no export job is persisted, so there is no
    // status to report. Answering COMPLETED for any id was a fabricated result.
    throw new NotFoundException(`Usage export ${exportId} is not tracked for tenant ${tenantId}: exports are synchronous and have no stored status`);
  }

  private buildMeterBreakdown(records: any[]): Record<string, { count: number; totalQuantity: number }> {
    const breakdown: Record<string, { count: number; totalQuantity: number }> = {};
    for (const r of records) {
      if (!breakdown[r.meterKey]) {
        breakdown[r.meterKey] = { count: 0, totalQuantity: 0 };
      }
      breakdown[r.meterKey].count += 1;
      breakdown[r.meterKey].totalQuantity += r.quantity || 0;
    }
    return breakdown;
  }

  private sanitizeDimensions(dimensions: any): any {
    if (!dimensions) return null;
    const forbidden = ['secret', 'apiKey', 'privateKey', 'accessToken', 'password', 'exchangeSecret', 'providerSecret', 'credentials', 'apiSecret'];
    const safe: any = {};
    for (const [key, value] of Object.entries(dimensions)) {
      const lowerKey = key.toLowerCase();
      if (forbidden.some((f) => lowerKey.includes(f.toLowerCase()))) {
        safe[key] = '[REDACTED]';
      } else {
        safe[key] = value;
      }
    }
    return safe;
  }
}

import { UsageMeterRepository } from './usage-meter.repository';

const KEY_FIELDS = ['tenantId', 'meterKey', 'scope', 'subjectId', 'periodId'] as const;

/**
 * usageBucket delegate that matches the compound unique key the way
 * PostgreSQL does: by the stored column values, so a row created with a
 * NULL subjectId is never found again by a lookup for ''.
 */
function fakeBuckets() {
  const rows: Array<Record<string, any>> = [];
  const same = (row: Record<string, any>, key: Record<string, any>) =>
    KEY_FIELDS.every((f) => row[f] === key[f]);
  return {
    rows,
    findFirst: jest.fn(async ({ where }: any) => rows.find((r) => same(r, where)) ?? null),
    upsert: jest.fn(async ({ where, create, update }: any) => {
      const key = where.tenantId_meterKey_scope_subjectId_periodId;
      const existing = rows.find((r) => same(r, key));
      if (existing) {
        existing.totalQuantity += update.totalQuantity.increment;
        existing.eventCount += update.eventCount.increment;
        return existing;
      }
      const row = { ...create };
      rows.push(row);
      return row;
    }),
  };
}

const BASE = {
  tenantId: '11111111-1111-1111-1111-111111111111',
  meterKey: 'API_REQUESTS' as any,
  scope: 'TENANT' as any,
  unit: 'request',
  window: 'MONTHLY' as any,
  periodId: '2026-09',
  periodStart: new Date('2026-09-01T00:00:00Z'),
  periodEnd: new Date('2026-10-01T00:00:00Z'),
};

describe('UsageMeterRepository tenant-level buckets', () => {
  let buckets: ReturnType<typeof fakeBuckets>;
  let repo: UsageMeterRepository;

  beforeEach(() => {
    buckets = fakeBuckets();
    const usageEvent = { findFirst: jest.fn(async () => null) };
    repo = new UsageMeterRepository({ usageBucket: buckets, usageEvent } as any);
  });

  it('accumulates repeated tenant-level usage into ONE bucket', async () => {
    await repo.incrementUsageAtomic({
      ...BASE,
      quantity: 2,
      sourceEventId: 's1',
      idempotencyKey: 'k1',
    });
    await repo.incrementUsageAtomic({
      ...BASE,
      quantity: 3,
      sourceEventId: 's2',
      idempotencyKey: 'k2',
    });
    await repo.incrementUsageAtomic({
      ...BASE,
      quantity: 5,
      sourceEventId: 's3',
      idempotencyKey: 'k3',
    });
    expect(buckets.rows).toHaveLength(1);
    expect(buckets.rows[0]).toMatchObject({ totalQuantity: 10, eventCount: 3 });
  });

  it("stores '' (never NULL) as the subject of a tenant-level bucket", async () => {
    await repo.incrementUsageAtomic({
      ...BASE,
      quantity: 1,
      sourceEventId: 's1',
      idempotencyKey: 'k1',
    });
    const call = buckets.upsert.mock.calls[0][0];
    expect(call.create.subjectId).toBe('');
    expect(call.where.tenantId_meterKey_scope_subjectId_periodId.subjectId).toBe('');
  });

  it('reads the running total back through the same key', async () => {
    await repo.incrementUsageAtomic({
      ...BASE,
      quantity: 4,
      sourceEventId: 's1',
      idempotencyKey: 'k1',
    });
    const total = await repo.getCurrentPeriodTotal({ ...BASE });
    expect(total.totalQuantity).toBe(4);
    expect(total.eventCount).toBe(1);
  });

  it('keeps per-subject buckets apart from the tenant-level one', async () => {
    await repo.incrementUsageAtomic({
      ...BASE,
      quantity: 1,
      sourceEventId: 's1',
      idempotencyKey: 'k1',
    });
    await repo.incrementUsageAtomic({
      ...BASE,
      subjectId: 'user-7',
      quantity: 1,
      sourceEventId: 's2',
      idempotencyKey: 'k2',
    });
    expect(buckets.rows.map((r) => r.subjectId).sort()).toEqual(['', 'user-7']);
  });

  it("maps the stored '' back to an absent subjectId in the domain object", async () => {
    const bucket = await repo.incrementUsageAtomic({
      ...BASE,
      quantity: 1,
      sourceEventId: 's1',
      idempotencyKey: 'k1',
    });
    expect(bucket.subjectId).toBeUndefined();
  });
});

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { MeterKey, UsageScope, AggregationWindow, UsageBucket, MeterDefinition, METER_DEFINITIONS } from './usage-metering.types';
import { randomUUID } from 'crypto';

/**
 * Persistence abstraction for meter definitions, tenant-scoped usage totals,
 * period buckets, source event IDs, idempotency keys, aggregation records.
 * No negative usage, no duplicate source event, atomic updates, tenant isolation.
 * Does NOT replace existing runtime counter mechanism.
 */
@Injectable()
export class UsageMeterRepository {
  private readonly logger = new Logger(UsageMeterRepository.name);

  constructor(private readonly prisma: PrismaService) {}

  getMeterDefinition(meterKey: MeterKey): MeterDefinition | null {
    return METER_DEFINITIONS[meterKey] || null;
  }

  listMeterDefinitions(): MeterDefinition[] {
    return Object.values(METER_DEFINITIONS);
  }

  async getCurrentPeriodTotal(params: {
    tenantId: string;
    meterKey: MeterKey;
    scope: UsageScope;
    subjectId?: string;
    periodId: string;
  }): Promise<{ totalQuantity: number; eventCount: number; bucketId: string | null }> {
    try {
      const result = await (this.prisma as any).usageBucket?.findFirst({
        where: {
          tenantId: params.tenantId,
          meterKey: params.meterKey,
          scope: params.scope,
          subjectId: params.subjectId || '',
          periodId: params.periodId,
        },
      });

      if (!result) {
        return { totalQuantity: 0, eventCount: 0, bucketId: null };
      }

      return {
        totalQuantity: result.totalQuantity || 0,
        eventCount: result.eventCount || 0,
        bucketId: result.id,
      };
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        return { totalQuantity: 0, eventCount: 0, bucketId: null };
      }
      throw error;
    }
  }

  async incrementUsageAtomic(params: {
    tenantId: string;
    meterKey: MeterKey;
    scope: UsageScope;
    subjectId?: string;
    quantity: number;
    unit: string;
    window: AggregationWindow;
    periodId: string;
    periodStart: Date;
    periodEnd: Date;
    sourceEventId: string;
    idempotencyKey: string;
  }): Promise<UsageBucket> {
    if (params.quantity < 0) {
      throw new Error('Usage quantity cannot be negative');
    }

    if (params.quantity === 0) {
      // Return current bucket without increment
      const current = await this.getCurrentPeriodTotal({
        tenantId: params.tenantId,
        meterKey: params.meterKey,
        scope: params.scope,
        subjectId: params.subjectId,
        periodId: params.periodId,
      });

      // Try to find bucket
      try {
        const existing = await (this.prisma as any).usageBucket?.findFirst({
          where: {
            tenantId: params.tenantId,
            meterKey: params.meterKey,
            scope: params.scope,
            subjectId: params.subjectId || '',
            periodId: params.periodId,
          },
        });
        if (existing) return this.mapBucketToDomain(existing);
      } catch {}

      // Return synthetic bucket
      return {
        id: current.bucketId || randomUUID(),
        tenantId: params.tenantId,
        meterKey: params.meterKey,
        scope: params.scope,
        subjectId: params.subjectId,
        window: params.window,
        periodId: params.periodId,
        periodStart: params.periodStart.toISOString(),
        periodEnd: params.periodEnd.toISOString(),
        totalQuantity: current.totalQuantity,
        eventCount: current.eventCount,
        unit: params.unit as any,
        lastEventAt: new Date().toISOString(),
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };
    }

    // Idempotency check by source event ID and idempotency key
    try {
      const existingBySource = await (this.prisma as any).usageEvent?.findFirst({
        where: {
          tenantId: params.tenantId,
          sourceId: params.sourceEventId,
          meterKey: params.meterKey,
        },
      });
      if (existingBySource) {
        this.logger.log(`Duplicate source event detected: ${params.sourceEventId} meter=${params.meterKey}`);
        // Return existing bucket
        const bucket = await (this.prisma as any).usageBucket?.findFirst({
          where: {
            tenantId: params.tenantId,
            meterKey: params.meterKey,
            scope: params.scope,
            subjectId: params.subjectId || '',
            periodId: params.periodId,
          },
        });
        if (bucket) return this.mapBucketToDomain(bucket);
      }

      const existingByIdempotency = await (this.prisma as any).usageEvent?.findFirst({
        where: {
          tenantId: params.tenantId,
          idempotencyKey: params.idempotencyKey,
        },
      });
      if (existingByIdempotency) {
        this.logger.log(`Duplicate idempotency key: ${params.idempotencyKey}`);
        const bucket = await (this.prisma as any).usageBucket?.findFirst({
          where: {
            tenantId: params.tenantId,
            meterKey: params.meterKey,
            scope: params.scope,
            subjectId: params.subjectId || '',
            periodId: params.periodId,
          },
        });
        if (bucket) return this.mapBucketToDomain(bucket);
      }
    } catch (e: any) {
      if (e.code !== 'P2021' && !e.message?.includes('does not exist')) {
        this.logger.warn(`Idempotency check failed: ${e.message}`);
      }
    }

    // Atomic increment via transaction or upsert
    try {
      const now = new Date();

      // Use upsert for bucket. subjectId is '' (never NULL) for a tenant-level
      // meter in every read and write: a NULL never equals itself under the
      // unique index, so each event would open a new bucket instead of adding.
      const bucket = await (this.prisma as any).usageBucket?.upsert({
        where: {
          tenantId_meterKey_scope_subjectId_periodId: {
            tenantId: params.tenantId,
            meterKey: params.meterKey,
            scope: params.scope,
            subjectId: params.subjectId || '',
            periodId: params.periodId,
          },
        },
        update: {
          totalQuantity: { increment: params.quantity },
          eventCount: { increment: 1 },
          lastEventAt: now,
          updatedAt: now,
        },
        create: {
          id: randomUUID(),
          tenantId: params.tenantId,
          meterKey: params.meterKey,
          scope: params.scope,
          subjectId: params.subjectId || '',
          window: params.window,
          periodId: params.periodId,
          periodStart: params.periodStart,
          periodEnd: params.periodEnd,
          totalQuantity: params.quantity,
          eventCount: 1,
          unit: params.unit,
          lastEventAt: now,
          createdAt: now,
          updatedAt: now,
        },
      });

      if (bucket) {
        return this.mapBucketToDomain(bucket);
      }
    } catch (error: any) {
      if (error.code === 'P2021' || error.message?.includes('does not exist')) {
        this.logger.warn(`usageBucket table not found, using in-memory fallback: ${error.message}`);
      } else if (error.code === 'P2002') {
        // Race condition, try to fetch and increment again
        try {
          const existing = await (this.prisma as any).usageBucket?.findFirst({
            where: {
              tenantId: params.tenantId,
              meterKey: params.meterKey,
              scope: params.scope,
              subjectId: params.subjectId || '',
              periodId: params.periodId,
            },
          });
          if (existing) {
            const updated = await (this.prisma as any).usageBucket?.update({
              where: { id: existing.id },
              data: {
                totalQuantity: { increment: params.quantity },
                eventCount: { increment: 1 },
                lastEventAt: new Date(),
                updatedAt: new Date(),
              },
            });
            if (updated) return this.mapBucketToDomain(updated);
          }
        } catch {}
      } else {
        this.logger.error(`Atomic increment failed: ${error.message}`, error.stack);
        throw error;
      }
    }

    // Fallback synthetic bucket if table doesn't exist
    const fallbackId = randomUUID();
    return {
      id: fallbackId,
      tenantId: params.tenantId,
      meterKey: params.meterKey,
      scope: params.scope,
      subjectId: params.subjectId,
      window: params.window,
      periodId: params.periodId,
      periodStart: params.periodStart.toISOString(),
      periodEnd: params.periodEnd.toISOString(),
      totalQuantity: params.quantity,
      eventCount: 1,
      unit: params.unit as any,
      lastEventAt: new Date().toISOString(),
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
  }

  async getTenantTotals(
    tenantId: string,
    meterKey?: MeterKey,
    scope?: UsageScope,
    fromDate?: Date,
    toDate?: Date,
  ): Promise<{ meterKey: MeterKey; totalQuantity: number; eventCount: number }[]> {
    const where: any = { tenantId };
    if (meterKey) where.meterKey = meterKey;
    if (scope) where.scope = scope;
    if (fromDate || toDate) {
      where.periodStart = {};
      if (fromDate) where.periodStart.gte = fromDate;
      if (toDate) where.periodStart.lte = toDate;
    }

    const results = await (this.prisma as any).usageBucket?.findMany({
      where,
      orderBy: { periodStart: 'desc' },
    });

    if (!results) return [];

    const grouped = new Map<MeterKey, { totalQuantity: number; eventCount: number }>();
    for (const r of results) {
      const key = r.meterKey as MeterKey;
      const existing = grouped.get(key) || { totalQuantity: 0, eventCount: 0 };
      existing.totalQuantity += r.totalQuantity || 0;
      existing.eventCount += r.eventCount || 0;
      grouped.set(key, existing);
    }

    return Array.from(grouped.entries()).map(([k, v]) => ({
      meterKey: k,
      totalQuantity: v.totalQuantity,
      eventCount: v.eventCount,
    }));
  }

  async getPeriodTotals(
    tenantId: string,
    periodId: string,
    meterKey?: MeterKey,
  ): Promise<UsageBucket[]> {
    const results = await (this.prisma as any).usageBucket?.findMany({
      where: {
        tenantId,
        periodId,
        ...(meterKey ? { meterKey } : {}),
      },
      orderBy: { meterKey: 'asc' },
    });

    if (!results) return [];
    return results.map((r: any) => this.mapBucketToDomain(r));
  }

  async getResourceTotals(
    tenantId: string,
    scope: UsageScope,
    subjectId: string,
    meterKey?: MeterKey,
  ): Promise<UsageBucket[]> {
    const results = await (this.prisma as any).usageBucket?.findMany({
      where: {
        tenantId,
        scope,
        subjectId,
        ...(meterKey ? { meterKey } : {}),
      },
      orderBy: { periodStart: 'desc' },
    });

    if (!results) return [];
    return results.map((r: any) => this.mapBucketToDomain(r));
  }

  async findBySourceEvent(tenantId: string, sourceEventId: string): Promise<any | null> {
    const result = await (this.prisma as any).usageEvent?.findFirst({
      where: { tenantId, sourceId: sourceEventId },
    });
    return result || null;
  }

  async findByIdempotencyKey(idempotencyKey: string, tenantId: string): Promise<any | null> {
    const result = await (this.prisma as any).usageEvent?.findFirst({
      where: { idempotencyKey, tenantId },
    });
    return result || null;
  }

  private mapBucketToDomain(raw: any): UsageBucket {
    return {
      id: raw.id,
      tenantId: raw.tenantId,
      meterKey: raw.meterKey as MeterKey,
      scope: raw.scope as UsageScope,
      subjectId: raw.subjectId || undefined,
      window: raw.window as AggregationWindow,
      periodId: raw.periodId,
      periodStart: raw.periodStart ? new Date(raw.periodStart).toISOString() : new Date().toISOString(),
      periodEnd: raw.periodEnd ? new Date(raw.periodEnd).toISOString() : new Date().toISOString(),
      totalQuantity: raw.totalQuantity || 0,
      eventCount: raw.eventCount || 0,
      unit: raw.unit as any,
      lastEventAt: raw.lastEventAt ? new Date(raw.lastEventAt).toISOString() : new Date().toISOString(),
      createdAt: raw.createdAt ? new Date(raw.createdAt).toISOString() : new Date().toISOString(),
      updatedAt: raw.updatedAt ? new Date(raw.updatedAt).toISOString() : new Date().toISOString(),
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { UsageMeterRepository } from './usage-meter.repository';
import { UsageEventRepository } from './usage-event.repository';
import { UsagePeriodService } from './usage-period.service';
import { MeterKey, UsageScope, MeterUnit, AggregationWindow, ProcessingState, PeriodType, UsageBucket, DurableUsageEvent } from './usage-metering.types';
import { randomUUID } from 'crypto';

/**
 * Main durable metering service: record usage, deduplicate events, update period totals,
 * update dimensions, expose normalized usage snapshots.
 * Does NOT decide whether action is allowed - runtime enforcement already does that.
 * Records what actually happened after successful business operations.
 */
@Injectable()
export class UsageMeterService {
  private readonly logger = new Logger(UsageMeterService.name);

  constructor(
    private readonly meterRepository: UsageMeterRepository,
    private readonly eventRepository: UsageEventRepository,
    private readonly periodService: UsagePeriodService,
  ) {}

  async recordUsage(params: {
    tenantId: string;
    meterKey: MeterKey;
    scope: UsageScope;
    subjectId?: string;
    resourceId?: string;
    quantity: number;
    unit?: MeterUnit;
    sourceType: string;
    sourceId: string;
    sourceEventId?: string;
    idempotencyKey?: string;
    timestamp?: Date;
    dimensions?: any;
    safeMetadata?: Record<string, unknown> | null;
  }): Promise<{ event: DurableUsageEvent; bucket: UsageBucket; isDuplicate: boolean }> {
    // Validate meter key
    const meterDef = this.meterRepository.getMeterDefinition(params.meterKey);
    if (!meterDef) {
      throw new Error(`Invalid meter key: ${params.meterKey}`);
    }

    // Validate scope
    if (!meterDef.scope.includes(params.scope)) {
      throw new Error(`Scope ${params.scope} not allowed for meter ${params.meterKey}. Allowed: ${meterDef.scope.join(',')}`);
    }

    // Validate quantity
    if (typeof params.quantity !== 'number' || isNaN(params.quantity)) {
      throw new Error(`Invalid quantity: ${params.quantity}`);
    }
    if (params.quantity < 0) {
      throw new Error('Usage quantity cannot be negative');
    }

    const idempotencyKey = params.idempotencyKey || this.generateIdempotencyKey(params.tenantId, params.meterKey, params.sourceId, params.scope, params.subjectId);

    // Deduplicate event - check idempotency and source
    const existingByIdempotency = await this.eventRepository.findByIdempotencyKey(idempotencyKey, params.tenantId);
    if (existingByIdempotency) {
      this.logger.log(`Duplicate usage event by idempotencyKey: ${idempotencyKey} - returning existing`);
      const bucket = await this.meterRepository.getCurrentPeriodTotal({
        tenantId: params.tenantId,
        meterKey: params.meterKey,
        scope: params.scope,
        subjectId: params.subjectId,
        periodId: existingByIdempotency.periodId,
      });

      // Map to bucket domain for return
      const bucketDomain: UsageBucket = {
        id: bucket.bucketId || randomUUID(),
        tenantId: params.tenantId,
        meterKey: params.meterKey,
        scope: params.scope,
        subjectId: params.subjectId,
        window: AggregationWindow.MONTHLY,
        periodId: existingByIdempotency.periodId,
        periodStart: existingByIdempotency.periodStart,
        periodEnd: existingByIdempotency.periodEnd,
        totalQuantity: bucket.totalQuantity,
        eventCount: bucket.eventCount,
        unit: existingByIdempotency.unit,
        lastEventAt: existingByIdempotency.timestamp,
        createdAt: existingByIdempotency.createdAt,
        updatedAt: new Date().toISOString(),
      };

      return { event: existingByIdempotency, bucket: bucketDomain, isDuplicate: true };
    }

    const existingBySource = await this.eventRepository.findBySourceId(params.tenantId, params.sourceId, params.meterKey);
    if (existingBySource) {
      this.logger.log(`Duplicate usage event by source: ${params.sourceId} meter=${params.meterKey}`);
      const bucket = await this.meterRepository.getCurrentPeriodTotal({
        tenantId: params.tenantId,
        meterKey: params.meterKey,
        scope: params.scope,
        subjectId: params.subjectId,
        periodId: existingBySource.periodId,
      });

      const bucketDomain: UsageBucket = {
        id: bucket.bucketId || randomUUID(),
        tenantId: params.tenantId,
        meterKey: params.meterKey,
        scope: params.scope,
        subjectId: params.subjectId,
        window: AggregationWindow.MONTHLY,
        periodId: existingBySource.periodId,
        periodStart: existingBySource.periodStart,
        periodEnd: existingBySource.periodEnd,
        totalQuantity: bucket.totalQuantity,
        eventCount: bucket.eventCount,
        unit: existingBySource.unit,
        lastEventAt: existingBySource.timestamp,
        createdAt: existingBySource.createdAt,
        updatedAt: new Date().toISOString(),
      };

      return { event: existingBySource, bucket: bucketDomain, isDuplicate: true };
    }

    // Resolve period
    const timestamp = params.timestamp || new Date();
    const period = this.periodService.getPeriodForTimestamp(params.tenantId, timestamp, PeriodType.CALENDAR_MONTH);

    // Determine aggregation window
    const window = this.determineAggregationWindow(params.meterKey);

    // Write durable event first
    const event = await this.eventRepository.create({
      tenantId: params.tenantId,
      meterKey: params.meterKey,
      scope: params.scope,
      subjectId: params.subjectId,
      resourceId: params.resourceId,
      quantity: params.quantity,
      unit: params.unit || meterDef.unit,
      sourceType: params.sourceType,
      sourceId: params.sourceId,
      sourceEventId: params.sourceEventId,
      periodId: period.id,
      periodType: period.type,
      periodStart: new Date(period.start),
      periodEnd: new Date(period.end),
      timestamp,
      idempotencyKey,
      processingState: ProcessingState.PROCESSED,
      dimensions: {
        tenantId: params.tenantId,
        scope: params.scope,
        subjectId: params.subjectId,
        resourceId: params.resourceId,
        ...params.dimensions,
      },
      safeMetadata: this.sanitizeSafeMetadata(params.safeMetadata),
    });

    // Update durable counter atomically
    const bucket = await this.meterRepository.incrementUsageAtomic({
      tenantId: params.tenantId,
      meterKey: params.meterKey,
      scope: params.scope,
      subjectId: params.subjectId,
      quantity: params.quantity,
      unit: (params.unit || meterDef.unit) as string,
      window,
      periodId: period.id,
      periodStart: new Date(period.start),
      periodEnd: new Date(period.end),
      sourceEventId: params.sourceId,
      idempotencyKey,
    });

    this.logger.log(
      `Usage recorded tenant=${params.tenantId} meter=${params.meterKey} scope=${params.scope} subject=${params.subjectId || 'none'} quantity=${params.quantity} period=${period.id} bucketTotal=${bucket.totalQuantity}`,
    );

    return { event, bucket, isDuplicate: false };
  }

  async getCurrentUsageSnapshot(params: {
    tenantId: string;
    meterKey: MeterKey;
    scope: UsageScope;
    subjectId?: string;
    periodId?: string;
  }): Promise<{ meterKey: MeterKey; current: number; periodId: string; lastEventAt: string | null }> {
    let periodId = params.periodId;
    if (!periodId) {
      const period = this.periodService.getCurrentCalendarMonthPeriod(params.tenantId);
      periodId = period.id;
    }

    const total = await this.meterRepository.getCurrentPeriodTotal({
      tenantId: params.tenantId,
      meterKey: params.meterKey,
      scope: params.scope,
      subjectId: params.subjectId,
      periodId,
    });

    // Try to get last event timestamp
    let lastEventAt: string | null = null;
    try {
      const events = await this.eventRepository.listByTenant(params.tenantId, {
        meterKey: params.meterKey,
        scope: params.scope,
        subjectId: params.subjectId,
        periodId,
        limit: 1,
      });
      if (events.length > 0) {
        lastEventAt = events[0].timestamp;
      }
    } catch {}

    return {
      meterKey: params.meterKey,
      current: total.totalQuantity,
      periodId,
      lastEventAt,
    };
  }

  async getTenantUsageOverview(
    tenantId: string,
    filter?: { meterKey?: MeterKey; fromDate?: Date; toDate?: Date },
  ): Promise<any[]> {
    return this.meterRepository.getTenantTotals(tenantId, filter?.meterKey, undefined, filter?.fromDate, filter?.toDate);
  }

  async getResourceUsage(tenantId: string, scope: UsageScope, subjectId: string, meterKey?: MeterKey): Promise<UsageBucket[]> {
    return this.meterRepository.getResourceTotals(tenantId, scope, subjectId, meterKey);
  }

  private determineAggregationWindow(meterKey: MeterKey): AggregationWindow {
    const def = this.meterRepository.getMeterDefinition(meterKey);
    if (!def) return AggregationWindow.MONTHLY;
    // Prefer monthly for most, minute for API requests
    if (meterKey === MeterKey.API_REQUESTS) return AggregationWindow.MINUTE;
    if (meterKey === MeterKey.WEBSOCKET_CONNECTIONS) return AggregationWindow.HOURLY;
    return AggregationWindow.MONTHLY;
  }

  private generateIdempotencyKey(tenantId: string, meterKey: MeterKey, sourceId: string, scope: UsageScope, subjectId?: string): string {
    return `usage_${tenantId}_${meterKey}_${sourceId}_${scope}_${subjectId || 'global'}`;
  }

  private sanitizeSafeMetadata(metadata?: Record<string, unknown> | null): Record<string, unknown> | null {
    if (!metadata) return null;
    const forbidden = ['secret', 'apiKey', 'privateKey', 'accessToken', 'password', 'exchangeSecret', 'providerSecret', 'bankAccount', 'walletKey', 'private_key', 'credentials', 'exchangeKey', 'apiSecret'];
    const safe: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(metadata)) {
      const lowerKey = key.toLowerCase();
      if (forbidden.some((f) => lowerKey.includes(f.toLowerCase()))) {
        safe[key] = '[REDACTED]';
      } else {
        safe[key] = value;
      }
    }
    return safe;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { UsagePeriod, PeriodType, PeriodStatus } from './usage-metering.types';


/**
 * Resolves billing/measurement periods, period start/end, reset boundaries,
 * timezone-safe date handling, and period status.
 * API rate-limit windows NOT replaced by monthly durable periods - this is for reporting/commercial periods.
 */
@Injectable()
export class UsagePeriodService {
  private readonly logger = new Logger(UsagePeriodService.name);

  constructor(private readonly prisma: PrismaService) {}

  getCurrentCalendarMonthPeriod(tenantId: string, timezone: string = 'UTC'): UsagePeriod {
    const now = new Date();
    const start = this.startOfMonthUTC(now);
    const end = this.endOfMonthUTC(now);

    return {
      id: `cal_month_${tenantId}_${start.getUTCFullYear()}_${start.getUTCMonth() + 1}`,
      tenantId,
      type: PeriodType.CALENDAR_MONTH,
      status: PeriodStatus.CURRENT,
      start: start.toISOString(),
      end: end.toISOString(),
      timezone,
      isCurrent: true,
      subscriptionId: null,
      metadata: { year: start.getUTCFullYear(), month: start.getUTCMonth() + 1 },
    };
  }

  getCurrentCalendarDayPeriod(tenantId: string, timezone: string = 'UTC'): UsagePeriod {
    const now = new Date();
    const start = this.startOfDayUTC(now);
    const end = this.endOfDayUTC(now);

    return {
      id: `cal_day_${tenantId}_${start.toISOString().split('T')[0]}`,
      tenantId,
      type: PeriodType.CALENDAR_DAY,
      status: PeriodStatus.CURRENT,
      start: start.toISOString(),
      end: end.toISOString(),
      timezone,
      isCurrent: true,
      subscriptionId: null,
    };
  }

  getCurrentHourPeriod(tenantId: string, timezone: string = 'UTC'): UsagePeriod {
    const now = new Date();
    const start = this.startOfHourUTC(now);
    const end = new Date(start.getTime() + 3600 * 1000);

    return {
      id: `cal_hour_${tenantId}_${start.toISOString()}`,
      tenantId,
      type: PeriodType.CALENDAR_HOUR,
      status: PeriodStatus.CURRENT,
      start: start.toISOString(),
      end: end.toISOString(),
      timezone,
      isCurrent: true,
      subscriptionId: null,
    };
  }

  async getSubscriptionPeriod(tenantId: string): Promise<UsagePeriod> {
    try {
      const subscription = await (this.prisma as any).tenantSubscription?.findFirst({
        where: {
          tenantId,
          status: { in: ['TRIALING', 'ACTIVE', 'PAST_DUE'] },
        },
        orderBy: { createdAt: 'desc' },
      });

      if (!subscription) {
        // Fallback to calendar month if no subscription
        return this.getCurrentCalendarMonthPeriod(tenantId);
      }

      const start = subscription.currentPeriodStart ? new Date(subscription.currentPeriodStart) : new Date();
      const end = subscription.currentPeriodEnd ? new Date(subscription.currentPeriodEnd) : this.endOfMonthUTC(start);

      const now = new Date();
      const isCurrent = now >= start && now < end;
      const status = isCurrent ? PeriodStatus.CURRENT : now < start ? PeriodStatus.FUTURE : PeriodStatus.CLOSED;

      return {
        id: `sub_period_${subscription.id}`,
        tenantId,
        type: PeriodType.SUBSCRIPTION_PERIOD,
        status,
        start: start.toISOString(),
        end: end.toISOString(),
        timezone: 'UTC',
        isCurrent,
        subscriptionId: subscription.id,
        metadata: {
          subscriptionStatus: subscription.status,
          planId: subscription.planId,
        },
      };
    } catch (error: any) {
      this.logger.warn(`Failed to get subscription period for ${tenantId}: ${error.message}`);
      return this.getCurrentCalendarMonthPeriod(tenantId);
    }
  }

  getRollingMinuteWindow(tenantId: string, windowMinutes: number = 1): UsagePeriod {
    const now = new Date();
    const windowMs = windowMinutes * 60 * 1000;
    const windowEpoch = Math.floor(now.getTime() / windowMs);
    const start = new Date(windowEpoch * windowMs);
    const end = new Date(start.getTime() + windowMs);

    return {
      id: `rolling_${windowMinutes}m_${tenantId}_${windowEpoch}`,
      tenantId,
      type: PeriodType.ROLLING_MINUTE,
      status: PeriodStatus.CURRENT,
      start: start.toISOString(),
      end: end.toISOString(),
      timezone: 'UTC',
      isCurrent: true,
      subscriptionId: null,
      metadata: { windowMinutes, windowEpoch },
    };
  }

  getPeriodForTimestamp(tenantId: string, timestamp: Date, type: PeriodType, timezone: string = 'UTC'): UsagePeriod {
    switch (type) {
      case PeriodType.CALENDAR_DAY:
        return {
          id: `cal_day_${tenantId}_${this.startOfDayUTC(timestamp).toISOString().split('T')[0]}`,
          tenantId,
          type,
          status: this.getPeriodStatus(timestamp, this.startOfDayUTC(timestamp), this.endOfDayUTC(timestamp)),
          start: this.startOfDayUTC(timestamp).toISOString(),
          end: this.endOfDayUTC(timestamp).toISOString(),
          timezone,
          isCurrent: this.isCurrentPeriod(timestamp, this.startOfDayUTC(timestamp), this.endOfDayUTC(timestamp)),
          subscriptionId: null,
        };
      case PeriodType.CALENDAR_MONTH:
        return {
          id: `cal_month_${tenantId}_${timestamp.getUTCFullYear()}_${timestamp.getUTCMonth() + 1}`,
          tenantId,
          type,
          status: this.getPeriodStatus(timestamp, this.startOfMonthUTC(timestamp), this.endOfMonthUTC(timestamp)),
          start: this.startOfMonthUTC(timestamp).toISOString(),
          end: this.endOfMonthUTC(timestamp).toISOString(),
          timezone,
          isCurrent: this.isCurrentPeriod(timestamp, this.startOfMonthUTC(timestamp), this.endOfMonthUTC(timestamp)),
          subscriptionId: null,
        };
      case PeriodType.CALENDAR_HOUR:
        const hourStart = this.startOfHourUTC(timestamp);
        return {
          id: `cal_hour_${tenantId}_${hourStart.toISOString()}`,
          tenantId,
          type,
          status: PeriodStatus.CURRENT,
          start: hourStart.toISOString(),
          end: new Date(hourStart.getTime() + 3600 * 1000).toISOString(),
          timezone,
          isCurrent: true,
          subscriptionId: null,
        };
      default:
        return this.getCurrentCalendarMonthPeriod(tenantId, timezone);
    }
  }

  getPreviousPeriod(currentPeriod: UsagePeriod): UsagePeriod {
    const start = new Date(currentPeriod.start);
    const end = new Date(currentPeriod.end);
    const duration = end.getTime() - start.getTime();
    const prevEnd = new Date(start.getTime());
    const prevStart = new Date(prevEnd.getTime() - duration);

    return {
      id: `${currentPeriod.id}_prev`,
      tenantId: currentPeriod.tenantId,
      type: currentPeriod.type,
      status: PeriodStatus.CLOSED,
      start: prevStart.toISOString(),
      end: prevEnd.toISOString(),
      timezone: currentPeriod.timezone,
      isCurrent: false,
      subscriptionId: currentPeriod.subscriptionId,
    };
  }

  private startOfDayUTC(date: Date): Date {
    return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate(), 0, 0, 0, 0));
  }

  private endOfDayUTC(date: Date): Date {
    return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate(), 23, 59, 59, 999));
  }

  private startOfMonthUTC(date: Date): Date {
    return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), 1, 0, 0, 0, 0));
  }

  private endOfMonthUTC(date: Date): Date {
    const nextMonth = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + 1, 1, 0, 0, 0, 0));
    return new Date(nextMonth.getTime() - 1);
  }

  private startOfHourUTC(date: Date): Date {
    return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate(), date.getUTCHours(), 0, 0, 0));
  }

  private getPeriodStatus(timestamp: Date, start: Date, end: Date): PeriodStatus {
    const now = new Date();
    if (now < start) return PeriodStatus.FUTURE;
    if (now >= start && now < end) return PeriodStatus.CURRENT;
    return PeriodStatus.CLOSED;
  }

  private isCurrentPeriod(timestamp: Date, start: Date, end: Date): boolean {
    const now = new Date();
    return now >= start && now < end;
  }

  normalizeToUTC(date: Date): Date {
    return new Date(date.toISOString());
  }

  isDateInPeriod(date: Date, period: UsagePeriod): boolean {
    const d = date.getTime();
    const s = new Date(period.start).getTime();
    const e = new Date(period.end).getTime();
    return d >= s && d < e;
  }
}

import { forEachTenant, listBillableTenantIds } from '../finance/tenant-iteration';
import { Injectable, Logger } from '@nestjs/common';
import { UsageEventRepository } from './usage-event.repository';
import { UsageMeterRepository } from './usage-meter.repository';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { MeterKey } from './usage-metering.types';

/**
 * Compares runtime counters against durable metering totals and identifies
 * drift, duplicates, missing events, impossible usage, period mismatch, negative usage.
 * Never silently rewrites financial/commercial history.
 */
@Injectable()
export class UsageReconciliationService {
  private readonly logger = new Logger(UsageReconciliationService.name);

  constructor(
    private readonly eventRepository: UsageEventRepository,
    private readonly meterRepository: UsageMeterRepository,
    private readonly prisma: PrismaService,
  ) {}

  async reconcileTenant(
    tenantId: string,
    options?: { meterKey?: MeterKey; periodId?: string; fromDate?: Date; toDate?: Date },
  ): Promise<{
    tenantId: string;
    checkedMeters: number;
    issues: any[];
    summary: { critical: number; high: number; medium: number; low: number };
  }> {
    const issues: any[] = [];
    let checkedMeters = 0;

    const meterKeys = options?.meterKey ? [options.meterKey] : Object.values(MeterKey);

    for (const meterKey of meterKeys) {
      checkedMeters++;

      try {
        // Get durable totals
        const durableTotals = await this.meterRepository.getTenantTotals(tenantId, meterKey, undefined, options?.fromDate, options?.toDate);
        const durableTotal = durableTotals.reduce((sum, t) => sum + t.totalQuantity, 0);

        // Get runtime counter (actual DB counts or Redis) for enforced meters
        let runtimeTotal: number | null = null;

        if ([MeterKey.USERS, MeterKey.TRADERS].includes(meterKey)) {
          try {
            if (meterKey === MeterKey.USERS) {
              runtimeTotal = await this.prisma.user.count({ where: { tenantId, deletedAt: null } });
            } else if (meterKey === MeterKey.TRADERS) {
              runtimeTotal = await (this.prisma as any).tradingAccount?.count({ where: { tenantId, deletedAt: null } }) || null;
            }
          } catch {}
        }

        // For other meters, try to get from events
        if (runtimeTotal === null) {
          const events = await this.eventRepository.listByTenant(tenantId, {
            meterKey,
            fromDate: options?.fromDate,
            toDate: options?.toDate,
            limit: 10000,
          });
          const eventTotal = events.reduce((sum, e) => sum + e.quantity, 0);

          // Compare bucket totals vs event totals for drift
          if (Math.abs(durableTotal - eventTotal) > 0) {
            issues.push({
              severity: 'MEDIUM',
              category: 'AGGREGATE_DRIFT',
              meterKey,
              tenantId,
              detectedValue: durableTotal,
              expectedValue: eventTotal,
              description: `Bucket total ${durableTotal} != event sum ${eventTotal} for meter ${meterKey}`,
              detectedAt: new Date().toISOString(),
            });
          }

          // Check for duplicate events (same sourceId)
          const sourceMap = new Map<string, number>();
          for (const event of events) {
            sourceMap.set(event.sourceId, (sourceMap.get(event.sourceId) || 0) + 1);
          }
          for (const [sourceId, count] of sourceMap) {
            if (count > 1) {
              issues.push({
                severity: 'HIGH',
                category: 'DUPLICATE_EVENT',
                meterKey,
                tenantId,
                sourceId,
                detectedValue: count,
                expectedValue: 1,
                description: `Duplicate usage events for source ${sourceId} meter ${meterKey}: count=${count}`,
                detectedAt: new Date().toISOString(),
              });
            }
          }

          // Check for negative usage
          for (const event of events) {
            if (event.quantity < 0) {
              issues.push({
                severity: 'CRITICAL',
                category: 'NEGATIVE_USAGE',
                meterKey,
                tenantId,
                sourceId: event.sourceId,
                detectedValue: event.quantity,
                expectedValue: 0,
                description: `Negative usage quantity ${event.quantity} for event ${event.id}`,
                detectedAt: new Date().toISOString(),
              });
            }
          }

          // Check for impossible usage (e.g., more users than can exist)
          // For count meters, quantity should be 1 per event typically
          if ([MeterKey.USERS, MeterKey.TRADERS, MeterKey.FOLLOWERS, MeterKey.EXCHANGE_ACCOUNTS, MeterKey.COPY_SUBSCRIPTIONS].includes(meterKey)) {
            for (const event of events) {
              if (event.quantity > 1) {
                issues.push({
                  severity: 'MEDIUM',
                  category: 'IMPOSSIBLE_USAGE',
                  meterKey,
                  tenantId,
                  sourceId: event.sourceId,
                  detectedValue: event.quantity,
                  expectedValue: 1,
                  description: `Count meter ${meterKey} has quantity ${event.quantity} > 1 for single event`,
                  detectedAt: new Date().toISOString(),
                });
              }
            }
          }

          continue;
        }

        // Compare runtime vs durable for count meters
        if (runtimeTotal !== null) {
          const drift = Math.abs(runtimeTotal - durableTotal);
          const threshold = Math.max(1, Math.floor(runtimeTotal * 0.05)); // 5% threshold

          if (drift > threshold) {
            issues.push({
              severity: drift > runtimeTotal * 0.2 ? 'HIGH' : 'MEDIUM',
              category: 'COUNTER_DRIFT',
              meterKey,
              tenantId,
              detectedValue: durableTotal,
              expectedValue: runtimeTotal,
              description: `Counter drift for ${meterKey}: durable=${durableTotal} runtime=${runtimeTotal} drift=${drift}`,
              detectedAt: new Date().toISOString(),
            });
          }
        }

        // Check for missing events (runtime has more than durable)
        if (runtimeTotal !== null && runtimeTotal > durableTotal) {
          const missing = runtimeTotal - durableTotal;
          if (missing > 0) {
            issues.push({
              severity: 'MEDIUM',
              category: 'MISSING_EVENT',
              meterKey,
              tenantId,
              detectedValue: durableTotal,
              expectedValue: runtimeTotal,
              description: `Missing usage events for ${meterKey}: durable=${durableTotal} runtime=${runtimeTotal} missing=${missing}`,
              detectedAt: new Date().toISOString(),
            });
          }
        }

        // Period mismatch check
        const events = await this.eventRepository.listByTenant(tenantId, {
          meterKey,
          fromDate: options?.fromDate,
          toDate: options?.toDate,
          limit: 100,
        });

        for (const event of events) {
          const periodStart = new Date(event.periodStart);
          const periodEnd = new Date(event.periodEnd);
          const eventTime = new Date(event.timestamp);

          if (eventTime < periodStart || eventTime >= periodEnd) {
            issues.push({
              severity: 'LOW',
              category: 'PERIOD_MISMATCH',
              meterKey,
              tenantId,
              sourceId: event.sourceId,
              detectedValue: eventTime.toISOString(),
              expectedValue: `${periodStart.toISOString()} - ${periodEnd.toISOString()}`,
              description: `Event timestamp ${eventTime.toISOString()} outside period ${event.periodId} [${periodStart.toISOString()}, ${periodEnd.toISOString()})`,
              detectedAt: new Date().toISOString(),
            });
          }
        }
      } catch (e) {
        this.logger.warn(`Reconciliation failed for meter ${meterKey}: ${(e as Error).message}`);
        issues.push({
          severity: 'LOW',
          category: 'RECONCILIATION_ERROR',
          meterKey,
          tenantId,
          description: `Reconciliation error for ${meterKey}: ${(e as Error).message}`,
          detectedAt: new Date().toISOString(),
        });
      }
    }

    const summary = {
      critical: issues.filter((i) => i.severity === 'CRITICAL').length,
      high: issues.filter((i) => i.severity === 'HIGH').length,
      medium: issues.filter((i) => i.severity === 'MEDIUM').length,
      low: issues.filter((i) => i.severity === 'LOW').length,
    };

    this.logger.log(`Usage reconciliation tenant=${tenantId} checked=${checkedMeters} issues=${issues.length} critical=${summary.critical} high=${summary.high}`);

    return {
      tenantId,
      checkedMeters,
      issues,
      summary,
    };
  }

  async reconcileAllTenants(options?: { fromDate?: Date; toDate?: Date; limit?: number }): Promise<any[]> {
    const tenantIds = await listBillableTenantIds(this.prisma, options?.limit ?? 1000);
    const results = await forEachTenant(tenantIds, (tenantId) => this.reconcileTenant(tenantId, { fromDate: options?.fromDate, toDate: options?.toDate }));
    this.logger.log(`Usage reconciliation all tenants=${tenantIds.length} failed=${results.filter((r) => r.error).length}`);
    return results.map((r) => (r.error ? { tenantId: r.tenantId, error: r.error } : r.result));
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AccountStateService } from './account-state.service';
import { LifecycleAuditService } from './lifecycle-audit.service';
import { InstitutionalAccountState } from './client-lifecycle.types';

/**
 * Performs a controlled account closure workflow requiring required checks for open exposure,
 * pending orders, pending funding operations, compliance holds, unresolved incidents, and
 * accounting requirements. Closure must preserve historical records.
 */

@Injectable()
export class AccountClosureService {
  private readonly logger = new Logger(AccountClosureService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly accountStateService: AccountStateService,
    private readonly auditService: LifecycleAuditService,
  ) {}

  async initiateClosure(params: {
    tenantId: string;
    accountId: string;
    operatorId: string;
    reason: string;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, accountId, operatorId, reason, correlationId = null } = params;

    const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
    if (!account) throw new BadRequestException('Account not found');

    if (account.state === 'CLOSED') throw new BadRequestException('Account already closed');
    if (account.state === 'CLOSURE_PENDING') throw new BadRequestException('Account closure already pending');

    // Transition to CLOSURE_PENDING
    const pending = await this.accountStateService.transitionAccount({
      tenantId,
      accountId,
      toState: InstitutionalAccountState.CLOSURE_PENDING as any,
      operatorId,
      reason,
      correlationId,
    });

    await this.auditService.log({
      tenantId,
      clientProfileId: account.clientProfileId,
      accountId,
      action: 'ACCOUNT_CLOSURE_INITIATED',
      entityType: 'INSTITUTIONAL_ACCOUNT',
      entityId: accountId,
      actorId: operatorId,
      fromState: account.state,
      toState: 'CLOSURE_PENDING',
      reason,
      correlationId,
      evidence: { reason },
    });

    return pending;
  }

  async validateAndClose(params: {
    tenantId: string;
    accountId: string;
    operatorId: string;
    reason: string;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, accountId, operatorId, reason, correlationId = null } = params;

    const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
    if (!account) throw new BadRequestException('Account not found');

    if (account.state !== 'CLOSURE_PENDING') {
      throw new BadRequestException(`Account must be CLOSURE_PENDING to close, current: ${account.state}`);
    }

    const validationErrors: string[] = [];

    // Check: No prohibited open exposure — delegate to Risk/Position
    try {
      const positions = await (this.prisma as any).position?.findMany?.({ where: { tenantId, accountId } });
      if (positions && positions.length > 0) {
        const openPositions = positions.filter((p: any) => parseFloat(p.quantity ?? '0') !== 0);
        if (openPositions.length > 0) {
          validationErrors.push(`Prohibited open exposure: ${openPositions.length} open positions`);
        }
      }
    } catch {}

    // Check: No unresolved critical OMS reconciliation
    try {
      const omsReconciliations = await (this.prisma as any).omsReconciliation?.findMany?.({
        // OmsReconciliation has resolved + severity (HIGH is the critical level), not status/isCritical.
        where: { tenantId, resolved: false, severity: { in: ['HIGH', 'CRITICAL'] } },
      });
      if (omsReconciliations && omsReconciliations.length > 0) {
        validationErrors.push(`Unresolved critical OMS reconciliation: ${omsReconciliations.length}`);
      }
    } catch {}

    // Check: No unresolved critical compliance hold
    try {
      const complianceHolds = await (this.prisma as any).accountRestriction.findMany({
        where: { tenantId, accountId, status: 'ACTIVE', restrictionType: 'COMPLIANCE_HOLD' },
      });
      if (complianceHolds.length > 0) {
        validationErrors.push(`Unresolved compliance hold: ${complianceHolds.length}`);
      }
    } catch {}

    // Check: No pending withdrawal requiring active account
    try {
      const pendingWithdrawals = await (this.prisma as any).withdrawalRequest.findMany({
        where: { tenantId, accountId, state: { in: ['REQUESTED', 'UNDER_REVIEW', 'APPROVED', 'SUBMITTED'] } },
      });
      if (pendingWithdrawals.length > 0) {
        validationErrors.push(`Pending withdrawals requiring active account: ${pendingWithdrawals.length}`);
      }
    } catch {}

    // Check: No pending funding settlement
    try {
      const pendingFunding = await (this.prisma as any).fundingRequest.findMany({
        where: { tenantId, accountId, state: { in: ['REQUESTED', 'UNDER_REVIEW', 'APPROVED', 'SUBMITTED'] } },
      });
      if (pendingFunding.length > 0) {
        validationErrors.push(`Pending funding settlement: ${pendingFunding.length}`);
      }
    } catch {}

    // Check: Portfolio/accounting period state is valid
    try {
      if (account.portfolioId) {
        const openPeriods = await (this.prisma as any).portfolioAccountingPeriod?.findMany?.({
          where: { tenantId, profileId: account.portfolioId, state: { in: ['OPEN', 'CLOSING'] } },
        });
        if (openPeriods && openPeriods.length > 0) {
          // Allow closure but warn — accounting periods should be closed or handled
          this.logger.warn({ event: 'client.closure.open_accounting_periods', accountId, openPeriods: openPeriods.length });
        }
      }
    } catch {}

    // Check: Required operational incidents handled
    try {
      const criticalIncidents = await (this.prisma as any).operationalIncident?.findMany?.({
        where: { tenantId, state: { in: ['OPEN', 'ACKNOWLEDGED', 'ESCALATED'] }, severity: 'CRITICAL' },
      });
      if (criticalIncidents && criticalIncidents.length > 0) {
        validationErrors.push(`Unresolved critical operational incidents: ${criticalIncidents.length}`);
      }
    } catch {}

    if (validationErrors.length > 0) {
      throw new BadRequestException(`Account closure validation failed: ${validationErrors.join('; ')}`);
    }

    // Closure must preserve historical records — do not delete, only state transition
    const closed = await this.accountStateService.transitionAccount({
      tenantId,
      accountId,
      toState: InstitutionalAccountState.CLOSED as any,
      operatorId,
      reason,
      correlationId,
    });

    await this.auditService.log({
      tenantId,
      clientProfileId: account.clientProfileId,
      accountId,
      action: 'ACCOUNT_CLOSED',
      entityType: 'INSTITUTIONAL_ACCOUNT',
      entityId: accountId,
      actorId: operatorId,
      fromState: 'CLOSURE_PENDING',
      toState: 'CLOSED',
      reason,
      correlationId,
      evidence: { reason, historicalRecordsRetained: true },
    });

    this.logger.log({ event: 'client.account.closed', tenantId, accountId, reason });

    return closed;
  }

  async cancelClosure(params: {
    tenantId: string;
    accountId: string;
    operatorId: string;
    reason: string;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, accountId, operatorId, reason, correlationId = null } = params;

    const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
    if (!account) throw new BadRequestException('Account not found');

    if (account.state !== 'CLOSURE_PENDING') {
      throw new BadRequestException(`Account must be CLOSURE_PENDING to cancel closure, current: ${account.state}`);
    }

    const restored = await this.accountStateService.transitionAccount({
      tenantId,
      accountId,
      toState: InstitutionalAccountState.ACTIVE as any,
      operatorId,
      reason: `Closure cancelled: ${reason}`,
      correlationId,
    });

    await this.auditService.log({
      tenantId,
      clientProfileId: account.clientProfileId,
      accountId,
      action: 'ACCOUNT_CLOSURE_CANCELLED',
      entityType: 'INSTITUTIONAL_ACCOUNT',
      entityId: accountId,
      actorId: operatorId,
      fromState: 'CLOSURE_PENDING',
      toState: 'ACTIVE',
      reason,
      correlationId,
      evidence: { reason },
    });

    return restored;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AccountOwnershipService } from './account-ownership.service';

/**
 * Resolves what a client, trader, follower, operator, compliance reviewer, or platform administrator
 * may perform on an account using existing IAM/RBAC and lifecycle restrictions.
 */

export enum ClientVisibilityRole {
  CLIENT = 'CLIENT',
  TENANT_OWNER = 'TENANT_OWNER',
  TRADER = 'TRADER',
  FOLLOWER = 'FOLLOWER',
  MANAGED_ACCOUNT_OPERATOR = 'MANAGED_ACCOUNT_OPERATOR',
  COMPLIANCE_REVIEWER = 'COMPLIANCE_REVIEWER',
  SECURITY_ADMIN = 'SECURITY_ADMIN',
  PLATFORM_ADMIN = 'PLATFORM_ADMIN',
}

@Injectable()
export class AccountPermissionService {
  private readonly logger = new Logger(AccountPermissionService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly ownershipService: AccountOwnershipService,
  ) {}

  async canPerformAction(params: {
    tenantId: string;
    accountId: string;
    userId: string;
    role: ClientVisibilityRole;
    action: string;
    isPlatformUser?: boolean;
  }): Promise<{ allowed: boolean; reason?: string }> {
    const { tenantId, accountId, userId, role, action, isPlatformUser = false } = params;

    // Platform admin can perform all actions with audit
    if (isPlatformUser && role === ClientVisibilityRole.PLATFORM_ADMIN) {
      return { allowed: true };
    }

    // Compliance reviewer can perform review actions
    if (role === ClientVisibilityRole.COMPLIANCE_REVIEWER) {
      const allowedActions = ['REVIEW', 'VIEW', 'RESTRICT', 'COMPLIANCE_HOLD'];
      if (allowedActions.includes(action)) return { allowed: true };
      return { allowed: false, reason: `Compliance reviewer cannot perform ${action}` };
    }

    // Security admin can perform security-related actions
    if (role === ClientVisibilityRole.SECURITY_ADMIN) {
      const allowedActions = ['VIEW', 'SECURITY_HOLD', 'REVIEW', 'RESTRICT'];
      if (allowedActions.includes(action)) return { allowed: true };
      return { allowed: false, reason: `Security admin cannot perform ${action}` };
    }

    // Tenant owner can perform all actions within tenant
    if (role === ClientVisibilityRole.TENANT_OWNER) {
      try {
        const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
        if (!account) return { allowed: false, reason: 'Account not found or tenant mismatch' };
        return { allowed: true };
      } catch {
        return { allowed: false, reason: 'Failed to verify tenant ownership' };
      }
    }

    // For client/trader/follower/operator, verify ownership
    try {
      const isOwner = await this.ownershipService.verifyOwnership({ tenantId, accountId, ownerId: userId });
      if (!isOwner) {
        // Also check if user is client profile owner
        const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
        if (account?.clientProfileId) {
          const profile = await (this.prisma as any).clientProfile.findFirst({ where: { id: account.clientProfileId, tenantId } });
          if (profile && profile.externalIdentityRef === userId) {
            // Client owns profile, allow limited actions
            const clientAllowedActions = ['VIEW', 'REQUEST_FUNDING', 'REQUEST_WITHDRAWAL', 'VIEW_OWN_FUNDING'];
            if (clientAllowedActions.includes(action)) return { allowed: true };
            return { allowed: false, reason: `Client cannot perform privileged action ${action}` };
          }
        }
        return { allowed: false, reason: 'User does not own account' };
      }

      // Owner can perform most actions except privileged platform actions
      const privilegedActions = ['APPROVE_ONBOARDING', 'ACTIVATE_LIVE', 'BYPASS_COMPLIANCE', 'BYPASS_RISK', 'BYPASS_SECURITY'];
      if (privilegedActions.includes(action)) {
        return { allowed: false, reason: `Owner cannot self-approve privileged action ${action}` };
      }

      return { allowed: true };
    } catch (e) {
      return { allowed: false, reason: `Permission check failed: ${(e as Error).message}` };
    }
  }

  async enforcePermission(params: {
    tenantId: string;
    accountId: string;
    userId: string;
    role: ClientVisibilityRole;
    action: string;
    isPlatformUser?: boolean;
  }): Promise<void> {
    const result = await this.canPerformAction(params);
    if (!result.allowed) {
      throw new Error(`Permission denied: ${result.reason ?? 'not allowed'}`);
    }
  }

  async listPermissionsForRole(role: ClientVisibilityRole): Promise<string[]> {
    switch (role) {
      case ClientVisibilityRole.PLATFORM_ADMIN:
        return ['*'];
      case ClientVisibilityRole.TENANT_OWNER:
        return ['VIEW', 'CREATE', 'UPDATE', 'RESTRICT', 'SUSPEND', 'CLOSE', 'REVIEW', 'FUNDING', 'WITHDRAWAL', 'OWNERSHIP'];
      case ClientVisibilityRole.COMPLIANCE_REVIEWER:
        return ['VIEW', 'REVIEW', 'RESTRICT', 'COMPLIANCE_HOLD'];
      case ClientVisibilityRole.SECURITY_ADMIN:
        return ['VIEW', 'REVIEW', 'RESTRICT', 'SECURITY_HOLD'];
      case ClientVisibilityRole.CLIENT:
        return ['VIEW', 'REQUEST_FUNDING', 'REQUEST_WITHDRAWAL', 'VIEW_OWN_FUNDING'];
      case ClientVisibilityRole.TRADER:
        return ['VIEW', 'TRADE', 'VIEW_OWN_ACCOUNT'];
      case ClientVisibilityRole.FOLLOWER:
        return ['VIEW', 'FOLLOW', 'VIEW_OWN_ACCOUNT'];
      case ClientVisibilityRole.MANAGED_ACCOUNT_OPERATOR:
        return ['VIEW', 'OPERATE', 'VIEW_OWN_ACCOUNT'];
      default:
        return ['VIEW'];
    }
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { LifecycleAuditService } from './lifecycle-audit.service';
import { deterministicIdempotencyKey, ClientReviewType, ClientReviewDecision, redactPiiAndSecrets } from './client-lifecycle.types';

/**
 * Coordinates periodic/manual client-account reviews using Compliance, Risk, Security, Operations,
 * and account activity evidence. Must preserve reviewer identity, decision reason, evidence references,
 * and review timestamp. Do not duplicate KYC/AML or risk scoring algorithms. Reference authoritative decisions.
 */

@Injectable()
export class AccountReviewService {
  private readonly logger = new Logger(AccountReviewService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly auditService: LifecycleAuditService,
  ) {}

  async createReview(params: {
    tenantId: string;
    clientProfileId?: string | null;
    accountId?: string | null;
    reviewType: ClientReviewType;
    reviewerId?: string | null;
    reason?: string | null;
    reviewPeriodStart?: Date | null;
    reviewPeriodEnd?: Date | null;
    evidenceReferences?: string[];
    riskSummaryReference?: string | null;
    complianceSummaryReference?: string | null;
    securitySummaryReference?: string | null;
    activitySummary?: any;
    nextReviewDate?: Date | null;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, clientProfileId = null, accountId = null, reviewType, reviewerId = null, reason = null, reviewPeriodStart = null, reviewPeriodEnd = null, evidenceReferences = [], riskSummaryReference = null, complianceSummaryReference = null, securitySummaryReference = null, activitySummary = null, nextReviewDate = null, correlationId = null } = params;

    if (!clientProfileId && !accountId) throw new BadRequestException('Either clientProfileId or accountId required');

    if (clientProfileId) {
      const profile = await (this.prisma as any).clientProfile.findFirst({ where: { id: clientProfileId, tenantId } });
      if (!profile) throw new BadRequestException('Client profile not found');
    }
    if (accountId) {
      const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
      if (!account) throw new BadRequestException('Account not found');
    }

    const idempotencyKey = deterministicIdempotencyKey({
      type: `client-review:${reviewType}`,
      tenantId,
      clientProfileId: clientProfileId ?? undefined,
      accountId: accountId ?? undefined,
      externalRef: `${reviewType}:${reviewPeriodStart?.toISOString() ?? ''}:${reviewPeriodEnd?.toISOString() ?? ''}`,
    });

    try {
      const existing = await (this.prisma as any).clientReview.findFirst({ where: { tenantId, idempotencyKey } });
      if (existing) return existing;
    } catch {}

    const review = await (this.prisma as any).clientReview.create({
      data: {
        tenantId,
        clientProfileId: clientProfileId ?? null,
        accountId: accountId ?? null,
        reviewType: reviewType as any,
        decision: 'PENDING',
        reviewerId: reviewerId ?? null,
        reason: reason ?? null,
        evidenceReferences: evidenceReferences as any,
        riskSummaryReference: riskSummaryReference ?? null,
        complianceSummaryReference: complianceSummaryReference ?? null,
        securitySummaryReference: securitySummaryReference ?? null,
        activitySummary: activitySummary ? redactPiiAndSecrets(activitySummary) as any : null,
        reviewPeriodStart: reviewPeriodStart ?? null,
        reviewPeriodEnd: reviewPeriodEnd ?? null,
        nextReviewDate: nextReviewDate ?? null,
        idempotencyKey,
      },
    });

    await this.auditService.log({
      tenantId,
      clientProfileId: clientProfileId ?? null,
      accountId: accountId ?? null,
      action: 'REVIEW_CREATED',
      entityType: 'CLIENT_REVIEW',
      entityId: review.id,
      actorId: reviewerId,
      toState: 'PENDING',
      correlationId,
      evidence: { reviewType, reason, evidenceReferences },
    });

    return review;
  }

  async decideReview(params: {
    tenantId: string;
    reviewId: string;
    decision: ClientReviewDecision;
    reviewerId: string;
    reason: string;
    nextReviewDate?: Date | null;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, reviewId, decision, reviewerId, reason, nextReviewDate = null, correlationId = null } = params;

    if (!reason || reason.trim().length < 5) throw new BadRequestException('Review decision reason required');

    const review = await (this.prisma as any).clientReview.findFirst({ where: { id: reviewId, tenantId } });
    if (!review) throw new BadRequestException('Review not found');

    const updated = await (this.prisma as any).clientReview.update({
      where: { id: reviewId },
      data: {
        decision: decision as any,
        reviewerId,
        reason,
        reviewedAt: new Date(),
        ...(nextReviewDate ? { nextReviewDate } : {}),
      },
    });

    await this.auditService.log({
      tenantId,
      clientProfileId: review.clientProfileId,
      accountId: review.accountId,
      action: 'REVIEW_DECIDED',
      entityType: 'CLIENT_REVIEW',
      entityId: reviewId,
      actorId: reviewerId,
      fromState: review.decision,
      toState: decision as any,
      reason,
      correlationId,
      evidence: { decision, reason, reviewerId, riskSummaryReference: review.riskSummaryReference, complianceSummaryReference: review.complianceSummaryReference },
    });

    this.logger.log({ event: 'client.review.decided', reviewId, decision, reviewerId });

    return updated;
  }

  async listReviews(params: {
    tenantId: string;
    clientProfileId?: string;
    accountId?: string;
    reviewType?: string;
    decision?: string;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId, clientProfileId, accountId, reviewType, decision, page = 1, limit = 50 } = params;
    const where: any = { tenantId };
    if (clientProfileId) where.clientProfileId = clientProfileId;
    if (accountId) where.accountId = accountId;
    if (reviewType) where.reviewType = reviewType;
    if (decision) where.decision = decision;

    const [data, total] = await Promise.all([
      (this.prisma as any).clientReview.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).clientReview.count({ where }),
    ]);
    return { data, total, page, limit };
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { LifecycleAuditService } from './lifecycle-audit.service';
import { INSTITUTIONAL_ACCOUNT_VALID_TRANSITIONS, InstitutionalAccountState } from './client-lifecycle.types';

/**
 * Enforces explicit account lifecycle transitions such as PENDING→ACTIVE→RESTRICTED→SUSPENDED→CLOSED
 * and rejects invalid transitions or unauthorized state changes.
 */

@Injectable()
export class AccountStateService {
  private readonly logger = new Logger(AccountStateService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly auditService: LifecycleAuditService,
  ) {}

  async transitionAccount(params: {
    tenantId: string;
    accountId: string;
    toState: InstitutionalAccountState;
    operatorId?: string | null;
    reason?: string;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, accountId, toState, operatorId = null, reason, correlationId = null } = params;

    const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
    if (!account) throw new BadRequestException('Account not found or tenant mismatch');

    const currentState = account.state as InstitutionalAccountState;

    // State-machine validated — do not permit arbitrary client-selected transitions
    const allowed = INSTITUTIONAL_ACCOUNT_VALID_TRANSITIONS[currentState] ?? [];
    if (!allowed.includes(toState)) {
      throw new BadRequestException(`Invalid account transition ${currentState} → ${toState}`);
    }

    // Never trust client-supplied account state — server authoritative
    const updated = await (this.prisma as any).institutionalAccount.update({
      where: { id: accountId },
      data: {
        state: toState as any,
        ...(toState === InstitutionalAccountState.ACTIVE ? { activatedAt: new Date(), isTradingEnabled: true } : {}),
        ...(toState === InstitutionalAccountState.SUSPENDED ? { suspendedAt: new Date(), isTradingEnabled: false } : {}),
        ...(toState === InstitutionalAccountState.CLOSED ? { closedAt: new Date(), isTradingEnabled: false, isFundingEnabled: false, isWithdrawalEnabled: false } : {}),
        ...(toState === InstitutionalAccountState.RESTRICTED ? { isTradingEnabled: false } : {}),
      },
    });

    await this.auditService.log({
      tenantId,
      clientProfileId: account.clientProfileId,
      accountId,
      action: 'ACCOUNT_STATE_CHANGED',
      entityType: 'INSTITUTIONAL_ACCOUNT',
      entityId: accountId,
      actorId: operatorId,
      fromState: currentState,
      toState: toState as any,
      reason: reason ?? null,
      correlationId,
      evidence: { fromState: currentState, toState, reason },
    });

    this.logger.log({ event: 'client.account.state_changed', accountId, from: currentState, to: toState });

    return updated;
  }

  async isAccountActive(params: { tenantId: string; accountId: string }): Promise<boolean> {
    const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: params.accountId, tenantId: params.tenantId } });
    return account?.state === 'ACTIVE';
  }

  async isAccountRestricted(params: { tenantId: string; accountId: string }): Promise<boolean> {
    const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: params.accountId, tenantId: params.tenantId } });
    return account?.state === 'RESTRICTED';
  }

  async isAccountSuspended(params: { tenantId: string; accountId: string }): Promise<boolean> {
    const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: params.accountId, tenantId: params.tenantId } });
    return account?.state === 'SUSPENDED';
  }

  async isAccountClosed(params: { tenantId: string; accountId: string }): Promise<boolean> {
    const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: params.accountId, tenantId: params.tenantId } });
    return account?.state === 'CLOSED';
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AccountStateService } from './account-state.service';
import { AccountRestrictionService } from './account-restriction.service';
import { LifecycleAuditService } from './lifecycle-audit.service';
import { AccountRestrictionType, RestrictionScope, InstitutionalAccountState } from './client-lifecycle.types';

/**
 * Handles controlled account suspension and restoration using explicit authorization, reason codes,
 * effective timestamps, affected capabilities, and verification. Must not silently mutate exchange state.
 */

@Injectable()
export class AccountSuspensionService {
  private readonly logger = new Logger(AccountSuspensionService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly accountStateService: AccountStateService,
    private readonly restrictionService: AccountRestrictionService,
    private readonly auditService: LifecycleAuditService,
  ) {}

  async suspendAccount(params: {
    tenantId: string;
    accountId: string;
    reason: string;
    reasonCode?: string;
    source: string;
    operatorId: string;
    effectiveAt?: Date;
    affectedCapabilities?: string[];
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, accountId, reason, reasonCode = 'MANUAL', source, operatorId, effectiveAt = new Date(), affectedCapabilities = ['TRADING', 'WITHDRAWAL'], correlationId = null } = params;

    if (!reason || reason.trim().length < 5) throw new BadRequestException('Suspension reason required');

    const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
    if (!account) throw new BadRequestException('Account not found');

    // Must not silently mutate exchange state — only administrative state
    // Apply restriction first
    await this.restrictionService.applyRestriction({
      tenantId,
      accountId,
      restrictionType: AccountRestrictionType.ACCOUNT_LOCKED as any,
      scope: RestrictionScope.ACCOUNT as any,
      reason: `SUSPENSION: ${reason} [${reasonCode}]`,
      source,
      createdBy: operatorId,
      effectiveAt,
      correlationId,
    });

    // Transition account state to SUSPENDED
    const suspended = await this.accountStateService.transitionAccount({
      tenantId,
      accountId,
      toState: InstitutionalAccountState.SUSPENDED as any,
      operatorId,
      reason,
      correlationId,
    });

    await this.auditService.log({
      tenantId,
      clientProfileId: account.clientProfileId,
      accountId,
      action: 'ACCOUNT_SUSPENDED',
      entityType: 'INSTITUTIONAL_ACCOUNT',
      entityId: accountId,
      actorId: operatorId,
      fromState: account.state,
      toState: 'SUSPENDED',
      reason,
      correlationId,
      evidence: { reasonCode, source, affectedCapabilities, effectiveAt },
    });

    this.logger.log({ event: 'client.account.suspended', tenantId, accountId, reasonCode, source });

    return suspended;
  }

  async restoreAccount(params: {
    tenantId: string;
    accountId: string;
    reason: string;
    operatorId: string;
    verificationEvidence?: any;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, accountId, reason, operatorId, verificationEvidence = {}, correlationId = null } = params;

    const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
    if (!account) throw new BadRequestException('Account not found');

    if (account.state !== 'SUSPENDED') {
      throw new BadRequestException(`Account must be SUSPENDED to restore, current: ${account.state}`);
    }

    // Verify suspension can be lifted — check compliance, risk, security holds
    const activeRestrictions = await (this.prisma as any).accountRestriction.findMany({
      where: { tenantId, accountId, status: 'ACTIVE', restrictionType: { in: ['COMPLIANCE_HOLD', 'SECURITY_HOLD', 'RISK_HOLD', 'OPERATIONAL_HOLD'] } },
    });

    if (activeRestrictions.length > 0) {
      throw new BadRequestException(`Cannot restore — active holds: ${activeRestrictions.map((r: any) => r.restrictionType).join(',')}`);
    }

    // Revoke ACCOUNT_LOCKED restriction
    const lockedRestrictions = await (this.prisma as any).accountRestriction.findMany({
      where: { tenantId, accountId, status: 'ACTIVE', restrictionType: 'ACCOUNT_LOCKED' },
    });

    for (const restriction of lockedRestrictions) {
      await this.restrictionService.revokeRestriction({
        tenantId,
        restrictionId: restriction.id,
        revokedBy: operatorId,
        reason: `Restoration: ${reason}`,
        correlationId,
      });
    }

    const restored = await this.accountStateService.transitionAccount({
      tenantId,
      accountId,
      toState: InstitutionalAccountState.ACTIVE as any,
      operatorId,
      reason,
      correlationId,
    });

    await this.auditService.log({
      tenantId,
      clientProfileId: account.clientProfileId,
      accountId,
      action: 'ACCOUNT_RESTORED',
      entityType: 'INSTITUTIONAL_ACCOUNT',
      entityId: accountId,
      actorId: operatorId,
      fromState: 'SUSPENDED',
      toState: 'ACTIVE',
      reason,
      correlationId,
      evidence: { reason, verificationEvidence },
    });

    this.logger.log({ event: 'client.account.restored', tenantId, accountId, reason });

    return restored;
  }
}

import { ForbiddenException, NotFoundException } from '@nestjs/common';
import { Permission } from '@wlct/shared-types';
import { ClientLifecycleController } from './client-lifecycle.controller';
import { ClientVisibilityRole } from './account-permission.service';

/**
 * Authorization of the client-lifecycle API (KYC onboarding, institutional
 * accounts, funding and withdrawal requests). Any authenticated user of the
 * tenant reaches these routes, so the controller must keep a client inside
 * their own profile and accounts, and derive administrative roles from the
 * verified JWT permissions.
 */

const TENANT = '11111111-1111-4111-8111-111111111111';
const ALICE = 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
const BOB = 'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb';
const ADMIN = 'cccccccc-cccc-4ccc-8ccc-cccccccccccc';

const PROFILES: Record<string, { id: string; tenantId: string; externalIdentityRef: string }> = {
  'cp-alice': { id: 'cp-alice', tenantId: TENANT, externalIdentityRef: ALICE },
  'cp-bob': { id: 'cp-bob', tenantId: TENANT, externalIdentityRef: BOB },
};

const ACCOUNTS: Record<string, { id: string; tenantId: string; clientProfileId: string; ownerId: string | null }> = {
  'acc-alice': { id: 'acc-alice', tenantId: TENANT, clientProfileId: 'cp-alice', ownerId: null },
  'acc-bob': { id: 'acc-bob', tenantId: TENANT, clientProfileId: 'cp-bob', ownerId: null },
};

function serviceMock(): any {
  const target: Record<string | symbol, jest.Mock> = {};
  return new Proxy(target, {
    get: (store, key) => {
      if (!store[key]) store[key] = jest.fn().mockResolvedValue({ id: 'result', data: [], total: 0, page: 1, limit: 50 });
      return store[key];
    },
  });
}

function client(userId: string) {
  return { user: { userId, tenantId: TENANT, permissions: [Permission.PORTFOLIO_READ], roles: ['FOLLOWER'] }, headers: {} };
}

function tenantAdmin() {
  return { user: { userId: ADMIN, tenantId: TENANT, permissions: [Permission.TENANT_UPDATE, Permission.USER_UPDATE], roles: ['TENANT_ADMIN'] }, headers: {} };
}

function compliance() {
  return { user: { userId: ADMIN, tenantId: TENANT, permissions: [Permission.KYC_READ, Permission.KYC_REVIEW], roles: ['COMPLIANCE'] }, headers: {} };
}

describe('ClientLifecycleController authorization', () => {
  let prisma: any;
  let services: Record<string, any>;
  let controller: ClientLifecycleController;

  beforeEach(() => {
    prisma = {
      accountOwnership: { findMany: jest.fn(async () => []) },
      institutionalAccount: {
        findMany: jest.fn(async ({ where }: any) =>
          Object.values(ACCOUNTS).filter(
            (a) =>
              a.tenantId === where.tenantId &&
              (where.OR ?? []).some(
                (c: any) => (c.ownerId && a.ownerId === c.ownerId) || (c.clientProfileId?.in && c.clientProfileId.in.includes(a.clientProfileId)),
              ),
          ),
        ),
      },
      clientOnboarding: {
        findMany: jest.fn(async () => []),
        count: jest.fn(async () => 0),
      },
    };
    const names = [
      'profileService', 'onboardingService', 'workflowService', 'accountStateService', 'ownershipService', 'permissionService',
      'tradingActivationService', 'restrictionService', 'suspensionService', 'closureService', 'exchangeBindingService',
      'portfolioBindingService', 'fundingRequestService', 'withdrawalRequestService', 'fundingApprovalService',
      'fundingReconciliationService', 'reviewService', 'relationshipService', 'notificationService', 'auditService', 'reconciliationService',
    ];
    services = {};
    for (const name of names) services[name] = serviceMock();
    services.profileRepo = { getProfile: jest.fn(async ({ profileId }: any) => PROFILES[profileId] ?? null) };
    services.accountAdminService = serviceMock();
    services.accountAdminService.getAccount.mockImplementation(async ({ accountId }: any) => ACCOUNTS[accountId] ?? null);
    services.visibilityService = {
      resolveVisibleClientProfiles: jest.fn(async ({ userId, role }: any) =>
        role === ClientVisibilityRole.CLIENT
          ? Object.values(PROFILES)
              .filter((p) => p.externalIdentityRef === userId)
              .map((p) => ({ clientProfileId: p.id }))
          : [],
      ),
      canViewClientProfile: jest.fn(async () => false),
      canViewAccount: jest.fn(async () => false),
    };
    controller = new ClientLifecycleController(
      prisma,
      services.profileService,
      services.profileRepo,
      services.onboardingService,
      services.workflowService,
      services.accountAdminService,
      services.accountStateService,
      services.ownershipService,
      services.permissionService,
      services.tradingActivationService,
      services.restrictionService,
      services.suspensionService,
      services.closureService,
      services.exchangeBindingService,
      services.portfolioBindingService,
      services.fundingRequestService,
      services.withdrawalRequestService,
      services.fundingApprovalService,
      services.fundingReconciliationService,
      services.reviewService,
      services.relationshipService,
      services.notificationService,
      services.auditService,
      services.reconciliationService,
      services.visibilityService,
