    const profile = await this.profileService.createProfile({
      tenantId,
      clientType: dto.clientType,
      legalName: dto.legalName,
      displayName: dto.displayName,
      email: dto.email,
      phone: dto.phone,
      countryCode: dto.countryCode,
      externalIdentityRef: dto.externalIdentityRef,
