    const tenantId = this.getTenantId(req);
    const userId = this.getUserId(req);
    const role = this.getUserRole(req);
    const isPlatform = this.isPlatformUser(req);

    if (query.accountId) await this.assertAccountAccess(req, tenantId, query.accountId);
    if (query.clientProfileId) await this.assertClientProfileAccess(req, tenantId, query.clientProfileId);

    const result = await this.fundingRequestService.listFundingRequests({
      tenantId,
      accountId: query.accountId,
      clientProfileId: query.clientProfileId,
      state: query.state,
      currency: query.currency,
      externalReference: query.externalReference,
      page: query.page,
      limit: query.limit,
    });

    // Client cannot access another client's funding data
    if (!isPlatform && role === ClientVisibilityRole.CLIENT) {
      const visibleProfiles = await this.visibilityService.resolveVisibleClientProfiles({ tenantId, userId, role, isPlatformUser: isPlatform });
      const visibleIds = new Set(visibleProfiles.map((v) => v.clientProfileId));
      const scope = await this.ownScope(req, tenantId);
      result.data = result.data.filter((f: any) => visibleIds.has(f.clientProfileId) || scope.accountIds.has(f.accountId));
      result.total = result.data.length;
    }

    return { ...result, data: result.data.map((d: any) => redactPiiAndSecrets(d)) };
  }

  /**
   * One funding request of the caller's tenant. Platform staff, the tenant
   * owner and compliance see any request of the tenant; every other caller
   * sees only a request on their own account or client profile (the same rule
   * as the list). A request outside that scope is reported exactly like a
   * missing one, so ids of other clients' requests cannot be probed.
   */
  @Get('funding/:fundingRequestId')
  async getFunding(@Req() req: any, @Param('fundingRequestId') fundingRequestId: string) {
    const tenantId = this.getTenantId(req);
    const funding = await this.fundingRequestService.getFundingRequest({ tenantId, fundingRequestId });
    if (!funding) throw new NotFoundException('Funding request not found');
    if (!this.isTenantWide(req)) {
      const scope = await this.ownScope(req, tenantId);
      if (!this.inOwnScope(scope, funding)) throw new NotFoundException('Funding request not found');
    }
    return redactPiiAndSecrets(funding);
  }

  @Post('funding/transition')
  async transitionFunding(@Req() req: any, @Body() dto: TransitionFundingRequestDto) {
    const tenantId = this.getTenantId(req);
    await this.enforcePlatformRBAC(req, 'PLATFORM_MANAGE');

    const updated = await this.fundingRequestService.transitionFundingRequest({
      tenantId,
      fundingRequestId: dto.fundingRequestId,
      toState: dto.toState as any,
      operatorId: this.getUserId(req),
      reason: dto.reason,
      approvedAmount: dto.approvedAmount ?? null,
      submittedAmount: dto.submittedAmount ?? null,
      confirmedAmount: dto.confirmedAmount ?? null,
      settledAmount: dto.settledAmount ?? null,
      externalReference: dto.externalReference ?? null,
      correlationId: req.headers['x-correlation-id'] ?? null,
    });

    if (dto.toState === 'CONFIRMED') {
      await this.notificationService.notifyFundingConfirmed({
        tenantId,
        accountId: updated.accountId,
        fundingRequestId: updated.id,
        confirmedAmount: dto.confirmedAmount ?? updated.confirmedAmount ?? updated.requestedAmount,
        currency: updated.currency,
      });
    }

    return redactPiiAndSecrets(updated);
  }

  // Withdrawals
  @Post('withdrawals')
  async createWithdrawal(@Req() req: any, @Body() dto: CreateWithdrawalRequestDto) {
    const tenantId = this.getTenantId(req);
    await this.assertAccountAccess(req, tenantId, dto.accountId);
    if (dto.clientProfileId) await this.assertClientProfileAccess(req, tenantId, dto.clientProfileId);

    const withdrawal = await this.withdrawalRequestService.createWithdrawalRequest({
      tenantId,
      accountId: dto.accountId,
      clientProfileId: dto.clientProfileId ?? null,
      requestedAmount: dto.requestedAmount,
      currency: dto.currency,
      destinationAddress: dto.destinationAddress ?? null,
      destinationType: dto.destinationType ?? null,
      externalReference: dto.externalReference ?? null,
      requestedBy: this.getUserId(req),
      correlationId: req.headers['x-correlation-id'] ?? null,
      metadata: dto.metadata,
    });

    await this.notificationService.notifyWithdrawalRequested({
      tenantId,
      accountId: dto.accountId,
      withdrawalRequestId: withdrawal.id,
      amount: dto.requestedAmount,
      currency: dto.currency,
    });

    return redactPiiAndSecrets(withdrawal);
  }

  @Get('withdrawals')
  async listWithdrawals(@Req() req: any, @Query() query: WithdrawalRequestQueryDto) {
    const tenantId = this.getTenantId(req);
    const userId = this.getUserId(req);
    const role = this.getUserRole(req);
    const isPlatform = this.isPlatformUser(req);

    if (query.accountId) await this.assertAccountAccess(req, tenantId, query.accountId);
    if (query.clientProfileId) await this.assertClientProfileAccess(req, tenantId, query.clientProfileId);

    const result = await this.withdrawalRequestService.listWithdrawalRequests({
      tenantId,
      accountId: query.accountId,
      clientProfileId: query.clientProfileId,
      state: query.state,
      currency: query.currency,
      page: query.page,
      limit: query.limit,
    });

    if (!isPlatform && role === ClientVisibilityRole.CLIENT) {
      const visibleProfiles = await this.visibilityService.resolveVisibleClientProfiles({ tenantId, userId, role, isPlatformUser: isPlatform });
      const visibleIds = new Set(visibleProfiles.map((v) => v.clientProfileId));
      const scope = await this.ownScope(req, tenantId);
      result.data = result.data.filter((w: any) => visibleIds.has(w.clientProfileId) || scope.accountIds.has(w.accountId));
      result.total = result.data.length;
    }

    return { ...result, data: result.data.map((d: any) => redactPiiAndSecrets(d)) };
  }

  /**
   * One withdrawal request of the caller's tenant. Same rule as
   * `GET funding/:fundingRequestId`: platform staff, the tenant owner and
   * compliance see any request of the tenant; every other caller sees only a
   * request on their own account or client profile. A request outside that
   * scope is reported exactly like a missing one, so ids of other clients'
   * withdrawals cannot be probed. The destination is redacted like the list.
   */
  @Get('withdrawals/:withdrawalRequestId')
  async getWithdrawal(@Req() req: any, @Param('withdrawalRequestId') withdrawalRequestId: string) {
    const tenantId = this.getTenantId(req);
    const withdrawal = await this.withdrawalRequestService.getWithdrawalRequest({ tenantId, withdrawalRequestId });
    if (!withdrawal) throw new NotFoundException('Withdrawal request not found');
    if (!this.isTenantWide(req)) {
      const scope = await this.ownScope(req, tenantId);
      if (!this.inOwnScope(scope, withdrawal)) throw new NotFoundException('Withdrawal request not found');
    }
    return redactPiiAndSecrets(withdrawal);
  }

  @Post('withdrawals/transition')
  async transitionWithdrawal(@Req() req: any, @Body() dto: TransitionWithdrawalRequestDto) {
    const tenantId = this.getTenantId(req);
    await this.enforcePlatformRBAC(req, 'PLATFORM_MANAGE');

    const updated = await this.withdrawalRequestService.transitionWithdrawalRequest({
      tenantId,
      withdrawalRequestId: dto.withdrawalRequestId,
      toState: dto.toState as any,
      operatorId: this.getUserId(req),
      reason: dto.reason,
      approvedAmount: dto.approvedAmount ?? null,
      confirmedAmount: dto.confirmedAmount ?? null,
      externalReference: dto.externalReference ?? null,
      correlationId: req.headers['x-correlation-id'] ?? null,
    });

    return redactPiiAndSecrets(updated);
  }

  // Approvals
  @Post('funding/approve')
  async approveFunding(@Req() req: any, @Body() dto: ApproveFundingDto) {
    const tenantId = this.getTenantId(req);
    const userId = this.getUserId(req);
    const role = this.getUserRole(req);
    const isSelf = role === ClientVisibilityRole.CLIENT;

    await this.enforcePlatformRBAC(req, 'PLATFORM_MANAGE');

    const approval = await this.fundingApprovalService.approveFundingRequest({
      tenantId,
      fundingRequestId: dto.fundingRequestId ?? null,
      withdrawalRequestId: dto.withdrawalRequestId ?? null,
      approverId: userId,
      isSelfApproval: isSelf,
      reason: dto.reason,
      approvedAmount: dto.approvedAmount ?? null,
      correlationId: req.headers['x-correlation-id'] ?? null,
    });

    return redactPiiAndSecrets(approval);
  }

  @Post('funding/reject')
  async rejectFunding(@Req() req: any, @Body() dto: RejectFundingDto) {
    const tenantId = this.getTenantId(req);
    await this.enforcePlatformRBAC(req, 'PLATFORM_MANAGE');

    const rejection = await this.fundingApprovalService.rejectFundingRequest({
      tenantId,
      fundingRequestId: dto.fundingRequestId ?? null,
      withdrawalRequestId: dto.withdrawalRequestId ?? null,
      approverId: this.getUserId(req),
      reason: dto.reason,
      correlationId: req.headers['x-correlation-id'] ?? null,
    });

    return redactPiiAndSecrets(rejection);
  }

  // Reconciliation
  @Post('reconciliation/funding')
  async reconcileFunding(@Req() req: any, @Body() dto: ReconciliationRequestDto) {
    const tenantId = this.getTenantId(req);
    await this.enforcePlatformRBAC(req, 'PLATFORM_MANAGE');

    const reconciliation = await this.fundingReconciliationService.runReconciliation({
      tenantId,
      fundingRequestId: dto.fundingRequestId ?? null,
      withdrawalRequestId: dto.withdrawalRequestId ?? null,
      reconciliationType: dto.reconciliationType,
    });

    return redactPiiAndSecrets(reconciliation);
  }

  @Post('reconciliation/lifecycle')
  async reconcileLifecycle(@Req() req: any, @Body() body: { clientProfileId?: string; accountId?: string }) {
    const tenantId = this.getTenantId(req);
    await this.enforcePlatformRBAC(req, 'PLATFORM_MANAGE');

    const result = await this.reconciliationService.runFullReconciliation({
      tenantId,
      clientProfileId: body.clientProfileId,
      accountId: body.accountId,
    });

    return redactPiiAndSecrets(result);
  }

  // Reviews
  @Post('reviews')
  async createReview(@Req() req: any, @Body() dto: CreateReviewDto) {
    const tenantId = this.getTenantId(req);
    // Reviews are opened by compliance or the tenant owner, never by the reviewed client.
    if (!this.isTenantWide(req)) throw new ForbiddenException('Only compliance or the tenant owner can open a review');
    if (dto.clientProfileId) await this.enforceTenantIsolationForProfile(tenantId, dto.clientProfileId);
    if (dto.accountId) await this.enforceTenantIsolationForAccount(tenantId, dto.accountId);

    const review = await this.reviewService.createReview({
      tenantId,
      clientProfileId: dto.clientProfileId ?? null,
      accountId: dto.accountId ?? null,
      reviewType: dto.reviewType as any,
      reviewerId: this.getUserId(req),
      reason: dto.reason ?? null,
      reviewPeriodStart: dto.reviewPeriodStart ? new Date(dto.reviewPeriodStart) : null,
      reviewPeriodEnd: dto.reviewPeriodEnd ? new Date(dto.reviewPeriodEnd) : null,
      evidenceReferences: dto.evidenceReferences ?? [],
      nextReviewDate: dto.nextReviewDate ? new Date(dto.nextReviewDate) : null,
      correlationId: req.headers['x-correlation-id'] ?? null,
    });

    await this.notificationService.notifyReviewRequired({
      tenantId,
      clientProfileId: dto.clientProfileId ?? null,
      accountId: dto.accountId ?? null,
      reviewType: dto.reviewType,
      reviewId: review.id,
    });

    return redactPiiAndSecrets(review);
  }

  @Post('reviews/decide')
  async decideReview(@Req() req: any, @Body() dto: DecideReviewDto) {
    const tenantId = this.getTenantId(req);
    await this.enforcePlatformRBAC(req, 'PLATFORM_MANAGE');

    const decided = await this.reviewService.decideReview({
      tenantId,
      reviewId: dto.reviewId,
      decision: dto.decision as any,
      reviewerId: this.getUserId(req),
      reason: dto.reason,
      nextReviewDate: dto.nextReviewDate ? new Date(dto.nextReviewDate) : null,
      correlationId: req.headers['x-correlation-id'] ?? null,
    });

    return redactPiiAndSecrets(decided);
  }

  @Get('reviews')
  async listReviews(@Req() req: any, @Query() query: ReviewQueryDto) {
    const tenantId = this.getTenantId(req);
    if (query.clientProfileId) await this.assertClientProfileAccess(req, tenantId, query.clientProfileId);
    if (query.accountId) await this.assertAccountAccess(req, tenantId, query.accountId);

    const result = await this.reviewService.listReviews({
      tenantId,
      clientProfileId: query.clientProfileId,
      accountId: query.accountId,
      reviewType: query.reviewType,
      decision: query.decision,
      page: query.page,
      limit: query.limit,
    });
    return await this.restrictToOwnScope(req, tenantId, result);
  }

  // Audits
  @Get('audits')
  async listAudits(@Req() req: any, @Query() query: LifecycleAuditQueryDto) {
    const tenantId = this.getTenantId(req);
    const userId = this.getUserId(req);
    const role = this.getUserRole(req);
    const isPlatform = this.isPlatformUser(req);

    // Only platform, tenant owner, compliance, security can view lifecycle audits
    if (!isPlatform && ![ClientVisibilityRole.TENANT_OWNER, ClientVisibilityRole.COMPLIANCE_REVIEWER, ClientVisibilityRole.SECURITY_ADMIN, ClientVisibilityRole.PLATFORM_ADMIN].includes(role)) {
      throw new ForbiddenException('Access denied to lifecycle audit');
    }

    return await this.auditService.listAudits({
      tenantId,
      clientProfileId: query.clientProfileId,
      accountId: query.accountId,
      action: query.action,
      entityType: query.entityType,
      from: query.from ? new Date(query.from) : undefined,
      to: query.to ? new Date(query.to) : undefined,
      page: query.page,
      limit: query.limit,
    });
  }
}

import { Injectable, Logger, BadRequestException, ForbiddenException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { ClientProfileRepository } from './client-profile.repository';
import { OnboardingWorkflowService } from './onboarding-workflow.service';
import { LifecycleAuditService } from './lifecycle-audit.service';
import { deterministicIdempotencyKey, ClientOnboardingState } from './client-lifecycle.types';

/**
 * Orchestrates the client onboarding workflow from registration/request through required
 * identity/compliance/security checks and approval. Must delegate KYC/AML truth to ComplianceModule.
 */

@Injectable()
export class ClientOnboardingService {
  private readonly logger = new Logger(ClientOnboardingService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly profileRepo: ClientProfileRepository,
    private readonly workflowService: OnboardingWorkflowService,
    private readonly auditService: LifecycleAuditService,
  ) {}

  async initiateOnboarding(params: {
    tenantId: string;
    clientProfileId: string;
    operatorId?: string | null;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, clientProfileId, operatorId = null, correlationId = null } = params;

    const profile = await this.profileRepo.getProfile({ tenantId, profileId: clientProfileId });
    if (!profile) throw new BadRequestException('Client profile not found');

    // Check existing onboarding
    try {
      const existing = await (this.prisma as any).clientOnboarding.findFirst({
        where: { tenantId, clientProfileId, state: { in: ['NOT_STARTED', 'IN_PROGRESS', 'PENDING_REVIEW'] } },
      });
      if (existing) return existing;
    } catch {}

    const idempotencyKey = deterministicIdempotencyKey({
      type: 'client-onboarding',
      tenantId,
      clientProfileId,
      externalRef: clientProfileId,
    });

    try {
      const existingByKey = await (this.prisma as any).clientOnboarding.findFirst({ where: { tenantId, idempotencyKey } });
      if (existingByKey) return existingByKey;
    } catch {}

    const onboarding = await (this.prisma as any).clientOnboarding.create({
      data: {
        tenantId,
        clientProfileId,
        state: 'IN_PROGRESS',
        requiredSteps: [
          'PROFILE_CREATED',
          'IDENTITY_REQUIRED',
          'KYC_PENDING',
          'AML_PENDING',
          'SECURITY_SETUP_REQUIRED',
          'COMPLIANCE_REVIEW',
          'RISK_REVIEW',
          'ACCOUNT_CONFIGURATION',
          'APPROVAL',
          'ACTIVATION_ELIGIBILITY',
        ],
        completedSteps: ['PROFILE_CREATED'],
        initiatedBy: operatorId,
        idempotencyKey,
        startedAt: new Date(),
      },
    });

    // Create steps
    await this.workflowService.initializeSteps({ tenantId, onboardingId: onboarding.id });

    await this.auditService.log({
      tenantId,
      clientProfileId,
      action: 'ONBOARDING_INITIATED',
      entityType: 'CLIENT_ONBOARDING',
      entityId: onboarding.id,
      actorId: operatorId,
      toState: 'IN_PROGRESS',
      correlationId,
      evidence: { clientProfileId, onboardingId: onboarding.id },
    });

    // Transition client profile to ONBOARDING
    try {
      await (this.prisma as any).clientProfile.update({
        where: { id: clientProfileId },
        data: { status: 'ONBOARDING', onboardingId: onboarding.id },
      });
    } catch {}

    return onboarding;
  }

  async getOnboarding(params: { tenantId: string; onboardingId: string }): Promise<any | null> {
    return await (this.prisma as any).clientOnboarding.findFirst({
      where: { id: params.onboardingId, tenantId: params.tenantId },
      include: { steps: true },
    });
  }

  async getOnboardingByClientProfile(params: { tenantId: string; clientProfileId: string }): Promise<any | null> {
    // Errors propagate: the old catch returned null, so a database failure was
    // shown to the customer as "no onboarding" instead of an error.
    return this.prisma.clientOnboarding.findFirst({
      where: { tenantId: params.tenantId, clientProfileId: params.clientProfileId },
      orderBy: { createdAt: 'desc' },
      include: { steps: { orderBy: { createdAt: 'asc' } } },
    });
  }

  async approveOnboarding(params: {
    tenantId: string;
    onboardingId: string;
    operatorId: string;
    isSelfApproval?: boolean;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, onboardingId, operatorId, isSelfApproval = false, correlationId = null } = params;

    // Never allow a client to self-approve a privileged workflow
    if (isSelfApproval) {
      throw new ForbiddenException('Client cannot self-approve onboarding — privileged workflow requires operator');
    }

    const onboarding = await this.getOnboarding({ tenantId, onboardingId });
    if (!onboarding) throw new BadRequestException('Onboarding not found');

    // Delegate KYC/AML truth to ComplianceModule — check compliance state from authoritative service
    // For now, verify steps are completed via workflow service
    const workflowStatus = await this.workflowService.getWorkflowStatus({ tenantId, onboardingId });

    if (!workflowStatus.canApprove) {
      throw new BadRequestException(`Onboarding cannot be approved — blocking: ${workflowStatus.blockingReasons.join(',')}`);
    }

    // Transition to APPROVED via workflow service
    const approved = await this.workflowService.transitionOnboarding({
      tenantId,
      onboardingId,
      toState: ClientOnboardingState.APPROVED as any,
      operatorId,
      correlationId,
    });

    await this.auditService.log({
      tenantId,
      clientProfileId: onboarding.clientProfileId,
      action: 'ONBOARDING_APPROVED',
      entityType: 'CLIENT_ONBOARDING',
      entityId: onboardingId,
      actorId: operatorId,
      fromState: onboarding.state,
      toState: 'APPROVED',
      correlationId,
      evidence: { onboardingId, approvedBy: operatorId },
    });

    // Transition client profile to APPROVED
    try {
      await (this.prisma as any).clientProfile.update({
        where: { id: onboarding.clientProfileId },
        data: { status: 'APPROVED' },
      });
    } catch {}

    return approved;
  }

  async rejectOnboarding(params: {
    tenantId: string;
    onboardingId: string;
    operatorId: string;
    reason: string;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, onboardingId, operatorId, reason, correlationId = null } = params;

    const onboarding = await this.getOnboarding({ tenantId, onboardingId });
    if (!onboarding) throw new BadRequestException('Onboarding not found');

    const rejected = await this.workflowService.transitionOnboarding({
      tenantId,
      onboardingId,
      toState: ClientOnboardingState.REJECTED as any,
      operatorId,
      reason,
      correlationId,
    });

    await this.auditService.log({
      tenantId,
      clientProfileId: onboarding.clientProfileId,
      action: 'ONBOARDING_REJECTED',
      entityType: 'CLIENT_ONBOARDING',
      entityId: onboardingId,
      actorId: operatorId,
      fromState: onboarding.state,
      toState: 'REJECTED',
      reason,
      correlationId,
      evidence: { reason },
    });

    return rejected;
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { ClientProfileRepository } from './client-profile.repository';
import { ClientPolicyService } from './client-policy.service';
import { LifecycleAuditService } from './lifecycle-audit.service';
import { CLIENT_PROFILE_VALID_TRANSITIONS, ClientProfileStatus, redactPiiAndSecrets } from './client-lifecycle.types';

/**
 * Creates and maintains normalized institutional/client profiles, preserving tenant ownership,
 * external identity references, profile status, and immutable lifecycle history without duplicating KYC truth.
 */

@Injectable()
export class ClientProfileService {
  private readonly logger = new Logger(ClientProfileService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly profileRepo: ClientProfileRepository,
    private readonly policyService: ClientPolicyService,
    private readonly auditService: LifecycleAuditService,
  ) {}

  async createProfile(params: {
    tenantId: string;
    clientType?: string;
    legalName?: string | null;
    displayName?: string | null;
    email?: string | null;
    phone?: string | null;
    countryCode?: string | null;
    externalIdentityRef?: string | null;
    operatorId?: string | null;
    correlationId?: string | null;
  }): Promise<any> {
    const profile = await this.profileRepo.createProfile({
      tenantId: params.tenantId,
      clientType: params.clientType,
      legalName: params.legalName,
      displayName: params.displayName,
      email: params.email,
      phone: params.phone,
      countryCode: params.countryCode,
      externalIdentityRef: params.externalIdentityRef,
    });

    await this.auditService.log({
      tenantId: params.tenantId,
      clientProfileId: profile.id,
      action: 'CLIENT_PROFILE_CREATED',
      entityType: 'CLIENT_PROFILE',
      entityId: profile.id,
      actorId: params.operatorId ?? null,
      toState: 'PENDING',
      correlationId: params.correlationId ?? null,
      evidence: redactPiiAndSecrets({ clientType: params.clientType, externalIdentityRef: params.externalIdentityRef }) as any,
    });

    return profile;
  }

  async transitionProfile(params: {
    tenantId: string;
    profileId: string;
    toStatus: ClientProfileStatus;
    operatorId?: string | null;
    reason?: string;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, profileId, toStatus, operatorId = null, reason, correlationId = null } = params;

    const profile = await this.profileRepo.getProfile({ tenantId, profileId });
    if (!profile) throw new BadRequestException('Client profile not found or tenant mismatch');

    const currentStatus = profile.status as ClientProfileStatus;

    // All sensitive lifecycle transitions must be state-machine validated
    const allowed = CLIENT_PROFILE_VALID_TRANSITIONS[currentStatus] ?? [];
    if (!allowed.includes(toStatus)) {
      throw new BadRequestException(`Invalid client profile transition ${currentStatus} → ${toStatus}`);
    }

    const updated = await (this.prisma as any).clientProfile.update({
      where: { id: profileId },
      data: { status: toStatus as any },
    });

    await this.auditService.log({
      tenantId,
      clientProfileId: profileId,
      action: 'CLIENT_PROFILE_STATUS_CHANGED',
      entityType: 'CLIENT_PROFILE',
      entityId: profileId,
      actorId: operatorId,
      fromState: currentStatus,
      toState: toStatus,
      reason: reason ?? null,
      correlationId,
      evidence: { fromState: currentStatus, toState: toStatus, reason },
    });

    this.logger.log({ event: 'client.profile.transition', profileId, from: currentStatus, to: toStatus });

    return updated;
  }

  async getProfile(params: { tenantId: string; profileId: string }): Promise<any | null> {
    return await this.profileRepo.getProfile(params);
  }

  async listProfiles(params: {
    tenantId: string;
    status?: string;
    clientType?: string;
    search?: string;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    return await this.profileRepo.listProfiles(params);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

/**
 * Resolves tenant-owner, client, trader, follower, managed-account operator, compliance reviewer,
 * security administrator, and platform-admin visibility using existing IAM/RBAC and ownership rules.
 * A client must never be able to view another client's profile, account, funding requests, etc.
 */

export enum ClientVisibilityRole {
  CLIENT = 'CLIENT',
  TENANT_OWNER = 'TENANT_OWNER',
  TRADER = 'TRADER',
  FOLLOWER = 'FOLLOWER',
  MANAGED_ACCOUNT_OPERATOR = 'MANAGED_ACCOUNT_OPERATOR',
  COMPLIANCE_REVIEWER = 'COMPLIANCE_REVIEWER',
  SECURITY_ADMIN = 'SECURITY_ADMIN',
  PLATFORM_ADMIN = 'PLATFORM_ADMIN',
}

@Injectable()
export class ClientVisibilityService {
  private readonly logger = new Logger(ClientVisibilityService.name);

  constructor(private readonly prisma: PrismaService) {}

  async resolveVisibleClientProfiles(params: {
    tenantId: string;
    userId: string;
    role: ClientVisibilityRole;
    isPlatformUser?: boolean;
  }): Promise<Array<{ clientProfileId: string }>> {
    const { tenantId, userId, role, isPlatformUser = false } = params;

    // Platform admin can view all profiles in tenant with audit
    if (isPlatformUser && role === ClientVisibilityRole.PLATFORM_ADMIN) {
      const profiles = await (this.prisma as any).clientProfile.findMany({ where: { tenantId } });
      return profiles.map((p: any) => ({ clientProfileId: p.id }));
    }

    // Compliance reviewer and security admin can view all profiles for compliance/security purposes
    if (role === ClientVisibilityRole.COMPLIANCE_REVIEWER || role === ClientVisibilityRole.SECURITY_ADMIN) {
      const profiles = await (this.prisma as any).clientProfile.findMany({ where: { tenantId } });
      return profiles.map((p: any) => ({ clientProfileId: p.id }));
    }

    // Tenant owner can view all profiles in tenant
    if (role === ClientVisibilityRole.TENANT_OWNER) {
      const profiles = await (this.prisma as any).clientProfile.findMany({ where: { tenantId } });
      return profiles.map((p: any) => ({ clientProfileId: p.id }));
    }

    // Client can view own profile only — based on externalIdentityRef or ownership
    if (role === ClientVisibilityRole.CLIENT) {
      const profiles = await (this.prisma as any).clientProfile.findMany({
        where: { tenantId, OR: [{ externalIdentityRef: userId }, { id: userId }] },
      });
      return profiles.map((p: any) => ({ clientProfileId: p.id }));
    }

    // Trader, follower, managed-account operator — view profiles they are related to via relationships
    if ([ClientVisibilityRole.TRADER, ClientVisibilityRole.FOLLOWER, ClientVisibilityRole.MANAGED_ACCOUNT_OPERATOR].includes(role)) {
      const relationships = await (this.prisma as any).accountRelationship.findMany({
        where: { tenantId, OR: [{ sourceId: userId }, { targetId: userId }], status: 'ACTIVE' },
      });
      const profileIds = new Set<string>();
      for (const rel of relationships) {
        if (rel.clientProfileId) profileIds.add(rel.clientProfileId);
      }
      // Also check ownership
      const ownerships = await (this.prisma as any).accountOwnership.findMany({ where: { tenantId, ownerId: userId, status: 'ACTIVE' } });
      for (const own of ownerships) {
        if (own.clientProfileId) profileIds.add(own.clientProfileId);
      }
      return Array.from(profileIds).map((id) => ({ clientProfileId: id }));
    }

    return [];
  }

  async canViewClientProfile(params: {
    tenantId: string;
    userId: string;
    clientProfileId: string;
    role: ClientVisibilityRole;
    isPlatformUser?: boolean;
  }): Promise<boolean> {
    const visible = await this.resolveVisibleClientProfiles({
      tenantId: params.tenantId,
      userId: params.userId,
      role: params.role,
      isPlatformUser: params.isPlatformUser,
    });
    return visible.some((v) => v.clientProfileId === params.clientProfileId);
  }

  async canViewAccount(params: {
    tenantId: string;
    userId: string;
    accountId: string;
    role: ClientVisibilityRole;
    isPlatformUser?: boolean;
  }): Promise<boolean> {
    const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: params.accountId, tenantId: params.tenantId } });
    if (!account) return false;

    if (params.isPlatformUser && params.role === ClientVisibilityRole.PLATFORM_ADMIN) return true;
    if (params.role === ClientVisibilityRole.TENANT_OWNER) return true;
    if (params.role === ClientVisibilityRole.COMPLIANCE_REVIEWER || params.role === ClientVisibilityRole.SECURITY_ADMIN) return true;

    // Check if user's client profile owns account
    if (account.clientProfileId) {
      return await this.canViewClientProfile({
        tenantId: params.tenantId,
        userId: params.userId,
        clientProfileId: account.clientProfileId,
        role: params.role,
        isPlatformUser: params.isPlatformUser,
      });
    }

    // Check ownership
    const ownership = await (this.prisma as any).accountOwnership.findFirst({
      where: { tenantId: params.tenantId, accountId: params.accountId, ownerId: params.userId, status: 'ACTIVE' },
    });
    return !!ownership;
  }

  async canViewFundingRequest(params: {
    tenantId: string;
    userId: string;
    fundingRequestId: string;
    role: ClientVisibilityRole;
    isPlatformUser?: boolean;
  }): Promise<boolean> {
    const fr = await (this.prisma as any).fundingRequest.findFirst({ where: { id: params.fundingRequestId, tenantId: params.tenantId } });
    if (!fr) return false;
    return await this.canViewAccount({ tenantId: params.tenantId, userId: params.userId, accountId: fr.accountId, role: params.role, isPlatformUser: params.isPlatformUser });
  }

  async enforceClientProfileVisibility(params: {
    tenantId: string;
    userId: string;
    clientProfileId: string;
    role: ClientVisibilityRole;
    isPlatformUser?: boolean;
  }): Promise<void> {
    const canView = await this.canViewClientProfile(params);
    if (!canView) {
      throw new Error(`Access denied: user ${params.userId} cannot view client profile ${params.clientProfileId} as ${params.role}`);
    }
  }

  async enforceAccountVisibility(params: {
    tenantId: string;
    userId: string;
    accountId: string;
    role: ClientVisibilityRole;
    isPlatformUser?: boolean;
  }): Promise<void> {
    const canView = await this.canViewAccount(params);
    if (!canView) {
      throw new Error(`Access denied: user ${params.userId} cannot view account ${params.accountId} as ${params.role}`);
    }
  }
}

