import { Injectable, Logger, BadRequestException, ForbiddenException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { LifecycleAuditService } from './lifecycle-audit.service';
import { deterministicIdempotencyKey } from './client-lifecycle.types';

/**
 * Associates an institutional account with existing ExchangeAccount records while enforcing ownership,
 * tenant isolation, credential-state requirements, and exchange-account uniqueness.
 * Must never store raw exchange credentials.
 */

@Injectable()
export class ExchangeAccountBindingService {
  private readonly logger = new Logger(ExchangeAccountBindingService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly auditService: LifecycleAuditService,
  ) {}

  async bindExchangeAccount(params: {
    tenantId: string;
    accountId: string;
    exchangeAccountId: string;
    operatorId?: string | null;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, accountId, exchangeAccountId, operatorId = null, correlationId = null } = params;

    const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
    if (!account) throw new BadRequestException('Institutional account not found or tenant mismatch');

    // Verify exchange account exists and belongs to same tenant — tenant isolation.
    // Exchange accounts are TradingAccount rows (ExchangesModule). The lookup is
    // tenant-scoped, so an unknown id and another tenant's id are both "not
    // found" - and a binding to an account that does not exist here is refused
    // rather than stored as a dangling reference.
    const exchangeAccount: any = await this.prisma.tradingAccount.findFirst({
      where: { id: exchangeAccountId, tenantId, deletedAt: null },
    });
    if (!exchangeAccount) {
      throw new BadRequestException('Exchange account not found or tenant mismatch');
    }
    if (exchangeAccount.tenantId && exchangeAccount.tenantId !== tenantId) {
      throw new ForbiddenException('Cross-tenant exchange account binding rejected');
    }

    // Check for duplicate exchange-account binding — uniqueness
    try {
      const existingBinding = await (this.prisma as any).institutionalAccount.findFirst({
        where: { tenantId, exchangeAccountId, id: { not: accountId } },
      });
      if (existingBinding) {
        throw new BadRequestException(`Duplicate exchange-account binding rejected — exchange account ${exchangeAccountId} already bound to account ${existingBinding.id}`);
      }
    } catch (e) {
      if (e instanceof BadRequestException || e instanceof ForbiddenException) throw e;
    }

    // Verify credential-state requirements — exchange account must have valid credential state
    // Must never store raw exchange credentials — only reference
    if (exchangeAccount) {
      // TradingAccountStatus carries the credential verdict: invalid keys,
      // a disabled account and a withdrawal-enabled key (refused on
      // principle) are all unusable for trading.
      if (['CREDENTIALS_INVALID', 'DISABLED', 'WITHDRAWAL_ENABLED_REJECTED'].includes(exchangeAccount.status)) {
        throw new BadRequestException(`Exchange account status ${exchangeAccount.status} invalid`);
      }
      // Ensure no raw credentials stored
      if (exchangeAccount.apiKey || exchangeAccount.secret || exchangeAccount.privateKey) {
        this.logger.warn({ event: 'client.binding.raw_credential_detected', exchangeAccountId });
        // Do not store raw credentials — we only store reference ID
      }
    }

    const idempotencyKey = deterministicIdempotencyKey({
      type: 'exchange-binding',
      tenantId,
      accountId,
      externalRef: exchangeAccountId,
    });

    // Idempotency for binding
    try {
      const existing = await (this.prisma as any).accountRelationship.findFirst({ where: { tenantId, idempotencyKey } });
      if (existing) return existing;
    } catch {}

    // Update institutional account with exchangeAccountId
    const updatedAccount = await (this.prisma as any).institutionalAccount.update({
      where: { id: accountId },
      data: { exchangeAccountId },
    });

    // Create relationship record
    const relationship = await (this.prisma as any).accountRelationship.create({
      data: {
        tenantId,
        sourceId: accountId,
        sourceType: 'INSTITUTIONAL_ACCOUNT',
        targetId: exchangeAccountId,
        targetType: 'EXCHANGE_ACCOUNT',
        relationshipType: 'CLIENT_TO_EXCHANGE_ACCOUNT',
        status: 'ACTIVE',
        effectiveAt: new Date(),
        accountId,
        clientProfileId: account.clientProfileId,
        createdBy: operatorId,
        source: 'EXCHANGE_BINDING_SERVICE',
        idempotencyKey,
      },
    });

    await this.auditService.log({
      tenantId,
      clientProfileId: account.clientProfileId,
      accountId,
      action: 'EXCHANGE_ACCOUNT_BOUND',
      entityType: 'INSTITUTIONAL_ACCOUNT',
      entityId: accountId,
      actorId: operatorId,
      correlationId,
      evidence: { exchangeAccountId, relationshipId: relationship.id },
    });

    this.logger.log({ event: 'client.exchange_account.bound', tenantId, accountId, exchangeAccountId });

    return { account: updatedAccount, relationship };
  }

  async unbindExchangeAccount(params: {
    tenantId: string;
    accountId: string;
    operatorId?: string | null;
    reason?: string;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, accountId, operatorId = null, reason, correlationId = null } = params;

    const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
    if (!account) throw new BadRequestException('Account not found');

    if (!account.exchangeAccountId) throw new BadRequestException('No exchange account bound');

    const previousExchangeAccountId = account.exchangeAccountId;

    const updatedAccount = await (this.prisma as any).institutionalAccount.update({
      where: { id: accountId },
      data: { exchangeAccountId: null },
    });

    // Revoke relationship
    try {
      await (this.prisma as any).accountRelationship.updateMany({
        where: { tenantId, accountId, targetId: previousExchangeAccountId, status: 'ACTIVE' },
        data: { status: 'REVOKED', endedAt: new Date() },
      });
    } catch {}

    await this.auditService.log({
      tenantId,
      clientProfileId: account.clientProfileId,
      accountId,
      action: 'EXCHANGE_ACCOUNT_UNBOUND',
      entityType: 'INSTITUTIONAL_ACCOUNT',
      entityId: accountId,
      actorId: operatorId,
      reason: reason ?? null,
      correlationId,
      evidence: { previousExchangeAccountId, reason },
    });

    return updatedAccount;
  }

  async getBinding(params: { tenantId: string; accountId: string }): Promise<any | null> {
    const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: params.accountId, tenantId: params.tenantId } });
    if (!account?.exchangeAccountId) return null;
    return { exchangeAccountId: account.exchangeAccountId, accountId: account.id };
  }
}

/**
 * Client-lifecycle bindings resolve the real models.
 *
 * Exchange accounts are TradingAccount rows and portfolios are
 * PortfolioAccountingProfile rows. The services used to read delegates that do
 * not exist (`exchangeAccount`, `portfolio`) behind `?.`, which made binding
 * accept any id, trading activation fail for every client, and lifecycle
 * reconciliation flag every binding as orphaned.
 */
import { BadRequestException } from '@nestjs/common';

import { ExchangeAccountBindingService } from './exchange-account-binding.service';
import { LifecycleReconciliationService } from './lifecycle-reconciliation.service';
import { PortfolioBindingService } from './portfolio-binding.service';
import { TradingActivationService } from './trading-activation.service';

const TENANT = '11111111-1111-1111-1111-111111111111';

/** A PrismaService stand-in: named delegates as given, every other delegate empty. */
function fakePrisma(delegates: Record<string, Record<string, jest.Mock>>) {
  const empty = () => ({
    findFirst: jest.fn(async () => null),
    findUnique: jest.fn(async () => null),
    findMany: jest.fn(async () => []),
    count: jest.fn(async () => 0),
    create: jest.fn(async ({ data }: any) => ({ id: 'new', ...data })),
    update: jest.fn(async ({ data }: any) => ({ id: 'upd', ...data })),
  });
  const cache: Record<string, unknown> = {};
  return new Proxy(delegates, {
    get(target, prop: string) {
      if (prop in target) {
        return { ...empty(), ...target[prop] };
      }
      cache[prop] ??= empty();
      return cache[prop];
    },
  }) as any;
}

const ACCOUNT = {
  id: 'acc-1',
  tenantId: TENANT,
  clientProfileId: 'cp-1',
  exchangeAccountId: null,
  portfolioId: null,
};

describe('ExchangeAccountBindingService', () => {
  const audit = { log: jest.fn(async () => undefined) };

  function build(tradingAccount: unknown) {
    const tradingAccountFindFirst = jest.fn(async () => tradingAccount);
    const prisma = fakePrisma({
      institutionalAccount: {
        findFirst: jest.fn(async ({ where }: any) => (where.id === ACCOUNT.id ? ACCOUNT : null)),
        update: jest.fn(async () => ACCOUNT),
      },
      tradingAccount: { findFirst: tradingAccountFindFirst },
    });
    return {
      service: new ExchangeAccountBindingService(prisma, audit as any),
      tradingAccountFindFirst,
    };
  }

  const params = { tenantId: TENANT, accountId: ACCOUNT.id, exchangeAccountId: 'ta-1' };

  it('looks the exchange account up as a live TradingAccount in the same tenant', async () => {
    const { service, tradingAccountFindFirst } = build({
      id: 'ta-1',
      tenantId: TENANT,
      status: 'ACTIVE',
    });
    await service.bindExchangeAccount(params);
    expect(tradingAccountFindFirst).toHaveBeenCalledWith({
      where: { id: 'ta-1', tenantId: TENANT, deletedAt: null },
    });
  });

  it('refuses to bind an account that does not exist in this tenant', async () => {
    const { service } = build(null);
    await expect(service.bindExchangeAccount(params)).rejects.toBeInstanceOf(BadRequestException);
  });

  it.each(['CREDENTIALS_INVALID', 'DISABLED', 'WITHDRAWAL_ENABLED_REJECTED'])(
    'refuses a %s account',
    async (status) => {
      const { service } = build({ id: 'ta-1', tenantId: TENANT, status });
      await expect(service.bindExchangeAccount(params)).rejects.toThrow(
        `Exchange account status ${status} invalid`,
      );
    },
  );
});

describe('TradingActivationService exchange-account check', () => {
  const policy = {
    resolvePolicy: jest.fn(async () => ({
      tradingActivationPrerequisites: {
        requireCompliance: false,
        requireKyc: false,
        requireAml: false,
        requireSecurityMfa: false,
        requireRisk: false,
        requireExchangeBinding: true,
        requirePortfolioBinding: false,
        requireCredential: false,
      },
    })),
  };

  async function exchangeCheck(tradingAccount: unknown) {
    const prisma = fakePrisma({
      institutionalAccount: {
        findFirst: jest.fn(async () => ({ ...ACCOUNT, exchangeAccountId: 'ta-1' })),
      },
      tradingAccount: { findFirst: jest.fn(async () => tradingAccount) },
    });
    const service = new TradingActivationService(prisma, policy as any);
    const result = await service.evaluateEligibility({ tenantId: TENANT, accountId: ACCOUNT.id });
    return result.blockingEvidence.find(
      (c: { check: string }) => c.check === 'exchangeAccountState',
    );
  }

  it('passes for a verified ACTIVE trading account', async () => {
    await expect(
      exchangeCheck({ id: 'ta-1', tenantId: TENANT, status: 'ACTIVE' }),
    ).resolves.toMatchObject({ passed: true });
  });

  it.each(['PENDING_VALIDATION', 'CREDENTIALS_INVALID', 'DISABLED', 'WITHDRAWAL_ENABLED_REJECTED'])(
    'fails for %s',
    async (status) => {
      await expect(exchangeCheck({ id: 'ta-1', tenantId: TENANT, status })).resolves.toMatchObject({
        passed: false,
      });
    },
  );

  it('fails when the bound account no longer exists', async () => {
    await expect(exchangeCheck(null)).resolves.toMatchObject({ passed: false });
  });
});

describe('LifecycleReconciliationService exchange bindings', () => {
  async function reconcile(tradingAccount: unknown) {
    const prisma = fakePrisma({
      clientProfile: {
        findFirst: jest.fn(async () => ({ id: 'cp-1', tenantId: TENANT, status: 'PENDING' })),
      },
      institutionalAccount: {
        findMany: jest.fn(async () => [{ ...ACCOUNT, exchangeAccountId: 'ta-1' }]),
      },
      accountOwnership: { findFirst: jest.fn(async () => ({ id: 'own-1' })) },
      tradingAccount: { findFirst: jest.fn(async () => tradingAccount) },
    });
    const service = new LifecycleReconciliationService(prisma);
    const { discrepancies } = await service.reconcileClientProfile({
      tenantId: TENANT,
      clientProfileId: 'cp-1',
    });
    return discrepancies.map((d) => d.type);
  }

  it('does not flag a binding whose trading account exists', async () => {
    await expect(
      reconcile({ id: 'ta-1', tenantId: TENANT, status: 'ACTIVE' }),
    ).resolves.not.toContain('EXCHANGE_BINDING_ORPHANED');
  });

  it('flags a binding whose trading account is gone', async () => {
    await expect(reconcile(null)).resolves.toContain('EXCHANGE_BINDING_ORPHANED');
  });
});

describe('PortfolioBindingService', () => {
  const audit = { log: jest.fn(async () => undefined) };

  function build(portfolio: unknown) {
    const portfolioFindFirst = jest.fn(async () => portfolio);
    const prisma = fakePrisma({
      institutionalAccount: {
        findFirst: jest.fn(async ({ where }: any) => (where.id === ACCOUNT.id ? ACCOUNT : null)),
        update: jest.fn(async () => ACCOUNT),
      },
      portfolioAccountingProfile: { findFirst: portfolioFindFirst },
    });
    return { service: new PortfolioBindingService(prisma, audit as any), portfolioFindFirst };
  }

  const params = { tenantId: TENANT, accountId: ACCOUNT.id, portfolioId: 'pf-1' };

  it('resolves the portfolio as a PortfolioAccountingProfile in the same tenant', async () => {
    const { service, portfolioFindFirst } = build({
      id: 'pf-1',
      tenantId: TENANT,
      clientProfileId: 'cp-1',
    });
    await service.bindPortfolio(params);
    expect(portfolioFindFirst).toHaveBeenCalledWith({ where: { id: 'pf-1', tenantId: TENANT } });
  });

  it('refuses a portfolio that does not exist in this tenant', async () => {
    const { service } = build(null);
    await expect(service.bindPortfolio(params)).rejects.toBeInstanceOf(BadRequestException);
  });
});

import { Injectable, Logger, BadRequestException, ForbiddenException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { ClientPolicyService } from './client-policy.service';
import { LifecycleAuditService } from './lifecycle-audit.service';
import { deterministicIdempotencyKey, FundingApprovalDecision } from './client-lifecycle.types';

/**
 * Evaluates authorization and workflow prerequisites for funding/withdrawal approvals
 * and delegates actual payment/custody/exchange movement to the authoritative external service.
 */

@Injectable()
export class FundingApprovalService {
  private readonly logger = new Logger(FundingApprovalService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: ClientPolicyService,
    private readonly auditService: LifecycleAuditService,
  ) {}

  async approveFundingRequest(params: {
    tenantId: string;
    fundingRequestId?: string | null;
    withdrawalRequestId?: string | null;
    approverId: string;
    isSelfApproval?: boolean;
    reason?: string;
    approvedAmount?: string | null;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, fundingRequestId = null, withdrawalRequestId = null, approverId, isSelfApproval = false, reason, approvedAmount = null, correlationId = null } = params;

    if (!fundingRequestId && !withdrawalRequestId) throw new BadRequestException('Either fundingRequestId or withdrawalRequestId required');

    // Never allow a client to self-approve a privileged workflow
    if (isSelfApproval) {
      throw new ForbiddenException('Client cannot self-approve funding/withdrawal — privileged workflow requires operator approval');
    }

    let request: any = null;
    let requestType = '';

    if (fundingRequestId) {
      request = await (this.prisma as any).fundingRequest.findFirst({ where: { id: fundingRequestId, tenantId } });
      requestType = 'FUNDING';
    } else {
      request = await (this.prisma as any).withdrawalRequest.findFirst({ where: { id: withdrawalRequestId, tenantId } });
      requestType = 'WITHDRAWAL';
    }

    if (!request) throw new BadRequestException(`${requestType} request not found`);

    // Verify approval policy — reuse existing IAM/RBAC
    const policy = await this.policyService.resolvePolicy({ tenantId, accountId: request.accountId, clientProfileId: request.clientProfileId });

    // Check if funding requires approval per policy
    if (requestType === 'FUNDING' && !policy.approvalRequirements.fundingRequiresApproval) {
      // Auto-approval allowed but still needs operator? For safety, still require approver
    }

    const idempotencyKey = deterministicIdempotencyKey({
      type: `funding-approval:${requestType}:${FundingApprovalDecision.APPROVED}`,
      tenantId,
      accountId: request.accountId,
      externalRef: fundingRequestId ?? withdrawalRequestId ?? '',
    });

    try {
      const existing = await (this.prisma as any).fundingApproval.findFirst({ where: { tenantId, idempotencyKey } });
      if (existing) return existing;
    } catch {}

    const approval = await (this.prisma as any).fundingApproval.create({
      data: {
        tenantId,
        fundingRequestId: fundingRequestId ?? null,
        withdrawalRequestId: withdrawalRequestId ?? null,
        decision: 'APPROVED',
        approverId,
        reason: reason ?? null,
        approvalPolicyVersion: policy.policyVersion,
        evidence: { requestType, approvedAmount: approvedAmount ?? request.requestedAmount, policyVersion: policy.policyVersion },
        idempotencyKey,
        decidedAt: new Date(),
      },
    });

    // Update request state to APPROVED — but not CONFIRMED, actual movement delegated to external service
    try {
      if (fundingRequestId) {
        await (this.prisma as any).fundingRequest.update({
          where: { id: fundingRequestId },
          data: { state: 'APPROVED', approvedAt: new Date(), approvedBy: approverId, approvedAmount: approvedAmount ?? request.requestedAmount },
        });
      } else if (withdrawalRequestId) {
        await (this.prisma as any).withdrawalRequest.update({
          where: { id: withdrawalRequestId },
          data: { state: 'APPROVED', approvedAt: new Date(), approvedBy: approverId, approvedAmount: approvedAmount ?? request.requestedAmount },
        });
      }
    } catch {}

    await this.auditService.log({
      tenantId,
      clientProfileId: request.clientProfileId,
      accountId: request.accountId,
      action: `${requestType}_APPROVED`,
      entityType: 'FUNDING_APPROVAL',
      entityId: approval.id,
      actorId: approverId,
      toState: 'APPROVED',
      reason: reason ?? null,
      correlationId,
      evidence: { requestType, fundingRequestId, withdrawalRequestId, approvedAmount },
    });

    this.logger.log({ event: `client.${requestType.toLowerCase()}.approved`, tenantId, requestId: fundingRequestId ?? withdrawalRequestId, approverId, note: 'Approval is workflow record, not proof of movement — settlement delegated to authoritative external service' });

    return approval;
  }

  async rejectFundingRequest(params: {
    tenantId: string;
    fundingRequestId?: string | null;
    withdrawalRequestId?: string | null;
    approverId: string;
    reason: string;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, fundingRequestId = null, withdrawalRequestId = null, approverId, reason, correlationId = null } = params;

    if (!reason || reason.trim().length < 5) throw new BadRequestException('Rejection reason required');

    let request: any = null;
    let requestType = '';

    if (fundingRequestId) {
      request = await (this.prisma as any).fundingRequest.findFirst({ where: { id: fundingRequestId, tenantId } });
      requestType = 'FUNDING';
    } else {
      request = await (this.prisma as any).withdrawalRequest.findFirst({ where: { id: withdrawalRequestId, tenantId } });
      requestType = 'WITHDRAWAL';
    }

    if (!request) throw new BadRequestException('Request not found');

    const policy = await this.policyService.resolvePolicy({ tenantId, accountId: request.accountId });

    const idempotencyKey = deterministicIdempotencyKey({
      type: `funding-approval:${requestType}:${FundingApprovalDecision.REJECTED}`,
      tenantId,
      accountId: request.accountId,
      externalRef: fundingRequestId ?? withdrawalRequestId ?? '',
    });

    const approval = await (this.prisma as any).fundingApproval.create({
      data: {
        tenantId,
        fundingRequestId: fundingRequestId ?? null,
        withdrawalRequestId: withdrawalRequestId ?? null,
        decision: 'REJECTED',
        approverId,
        reason,
        approvalPolicyVersion: policy.policyVersion,
        idempotencyKey,
        decidedAt: new Date(),
      },
    });

    try {
      if (fundingRequestId) {
        await (this.prisma as any).fundingRequest.update({
          where: { id: fundingRequestId },
          data: { state: 'FAILED', failedAt: new Date(), failureReason: reason },
        });
      } else if (withdrawalRequestId) {
        await (this.prisma as any).withdrawalRequest.update({
          where: { id: withdrawalRequestId },
          data: { state: 'FAILED', failedAt: new Date(), failureReason: reason },
        });
      }
    } catch {}

    await this.auditService.log({
      tenantId,
      clientProfileId: request.clientProfileId,
      accountId: request.accountId,
      action: `${requestType}_REJECTED`,
      entityType: 'FUNDING_APPROVAL',
      entityId: approval.id,
      actorId: approverId,
      toState: 'REJECTED',
      reason,
      correlationId,
      evidence: { requestType, reason },
    });

    return approval;
  }

  async listApprovals(params: {
    tenantId: string;
    fundingRequestId?: string;
    withdrawalRequestId?: string;
    decision?: string;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId, fundingRequestId, withdrawalRequestId, decision, page = 1, limit = 50 } = params;
    const where: any = { tenantId };
    if (fundingRequestId) where.fundingRequestId = fundingRequestId;
    if (withdrawalRequestId) where.withdrawalRequestId = withdrawalRequestId;
    if (decision) where.decision = decision;

    const [data, total] = await Promise.all([
      (this.prisma as any).fundingApproval.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).fundingApproval.count({ where }),
    ]);
    return { data, total, page, limit };
  }
}

// # Reconciles deposit/withdrawal requests against provider settlement records
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { deterministicIdempotencyKey } from './client-lifecycle.types';

/**
 * Reconciles requested, approved, submitted, confirmed, failed, reversed, and externally settled
 * funding operations against authoritative payment/custody/exchange records. Must never rewrite external truth.
 */

@Injectable()
export class FundingReconciliationService {
  private readonly logger = new Logger(FundingReconciliationService.name);

  constructor(private readonly prisma: PrismaService) {}

  async reconcileFundingRequest(params: {
    tenantId: string;
    fundingRequestId?: string | null;
    withdrawalRequestId?: string | null;
  }): Promise<{ discrepancies: Array<{ type: string; severity: string; details: any }>; hasCritical: boolean }> {
    const { tenantId, fundingRequestId = null, withdrawalRequestId = null } = params;

    const discrepancies: Array<{ type: string; severity: string; details: any }> = [];

    let request: any = null;
    let requestType = '';

    if (fundingRequestId) {
      try {
        request = await (this.prisma as any).fundingRequest.findFirst({ where: { id: fundingRequestId, tenantId } });
        requestType = 'FUNDING';
      } catch {}
    } else if (withdrawalRequestId) {
      try {
        request = await (this.prisma as any).withdrawalRequest.findFirst({ where: { id: withdrawalRequestId, tenantId } });
        requestType = 'WITHDRAWAL';
      } catch {}
    }

    if (!request) {
      discrepancies.push({ type: 'REQUEST_NOT_FOUND', severity: 'CRITICAL', details: { fundingRequestId, withdrawalRequestId } });
      return { discrepancies, hasCritical: true };
    }

    // Detect: REQUEST_WITHOUT_EXTERNAL_RECORD
    if (['SUBMITTED', 'CONFIRMED'].includes(request.state) && !request.externalReference) {
      discrepancies.push({ type: 'REQUEST_WITHOUT_EXTERNAL_RECORD', severity: 'WARNING', details: { requestId: request.id, state: request.state } });
    }

    // Detect: EXTERNAL_RECORD_WITHOUT_REQUEST — would check external payment records
    // For now, check if externalReference exists but no corresponding external record (simulated)
    if (request.externalReference) {
      try {
        // Check if external record exists in payment ledger or similar
        // Payment has no externalReference column: the reference is the provider payment id or order id.
        const externalRecord = await (this.prisma as any).payment?.findFirst?.({
          where: { tenantId, OR: [{ providerPaymentId: request.externalReference }, { orderId: request.externalReference }] },
        });
        if (!externalRecord) {
          // Could be missing external record — check if state is CONFIRMED but no external proof
          if (request.state === 'CONFIRMED' && !request.confirmedAmount) {
            discrepancies.push({ type: 'SETTLEMENT_MISSING', severity: 'CRITICAL', details: { requestId: request.id, externalReference: request.externalReference } });
          }
        } else {
          // Check amount mismatch
          const externalAmount = externalRecord.amount?.toString() ?? externalRecord.settledAmount?.toString();
          if (externalAmount && request.requestedAmount && externalAmount !== request.requestedAmount) {
            // Allow approvedAmount to differ, but confirmed should match external
            if (request.confirmedAmount && request.confirmedAmount !== externalAmount) {
              discrepancies.push({ type: 'AMOUNT_MISMATCH', severity: 'CRITICAL', details: { requestId: request.id, requested: request.requestedAmount, confirmed: request.confirmedAmount, external: externalAmount } });
            }
          }
          // Currency mismatch
          if (externalRecord.currency && request.currency && externalRecord.currency !== request.currency) {
            discrepancies.push({ type: 'CURRENCY_MISMATCH', severity: 'CRITICAL', details: { requestId: request.id, requestCurrency: request.currency, externalCurrency: externalRecord.currency } });
          }
          // Status mismatch
          if (externalRecord.status === 'FAILED' && request.state === 'CONFIRMED') {
            discrepancies.push({ type: 'STATUS_MISMATCH', severity: 'CRITICAL', details: { requestId: request.id, requestState: request.state, externalStatus: externalRecord.status } });
          }
        }
      } catch {}
    }

    // Detect: DUPLICATE_EXTERNAL_REFERENCE
    if (request.externalReference) {
      try {
        const dupCount = await (this.prisma as any).fundingRequest.count({ where: { tenantId, externalReference: request.externalReference } });
        const dupWithdrawal = await (this.prisma as any).withdrawalRequest.count({ where: { tenantId, externalReference: request.externalReference } });
        const totalDup = dupCount + dupWithdrawal;
        if (totalDup > 1) {
          discrepancies.push({ type: 'DUPLICATE_EXTERNAL_REFERENCE', severity: 'CRITICAL', details: { externalReference: request.externalReference, count: totalDup } });
        }
      } catch {}
    }

    // Detect: DUPLICATE_REQUEST — same idempotencyKey or same amount/currency/destination in short window
    try {
      const recentRequests = await (this.prisma as any).fundingRequest.findMany({
        where: {
          tenantId,
          accountId: request.accountId,
          requestedAmount: request.requestedAmount,
          currency: request.currency,
          createdAt: { gte: new Date(Date.now() - 5 * 60 * 1000) }, // 5 min window
          id: { not: request.id },
        },
      });
      if (recentRequests.length > 0) {
        discrepancies.push({ type: 'DUPLICATE_REQUEST', severity: 'WARNING', details: { requestId: request.id, recentCount: recentRequests.length } });
      }
    } catch {}

    // Detect: UNEXPECTED_REVERSAL
    if (request.state === 'REVERSED' && !request.reversalReason) {
      discrepancies.push({ type: 'UNEXPECTED_REVERSAL', severity: 'WARNING', details: { requestId: request.id, reason: 'Reversal without reason' } });
    }

    // Detect: SETTLEMENT_MISSING — CONFIRMED without confirmedAmount
    if (request.state === 'CONFIRMED' && !request.confirmedAmount) {
      discrepancies.push({ type: 'SETTLEMENT_MISSING', severity: 'CRITICAL', details: { requestId: request.id, state: request.state } });
    }

    const hasCritical = discrepancies.some((d) => d.severity === 'CRITICAL');

    return { discrepancies, hasCritical };
  }

  async runReconciliation(params: {
    tenantId: string;
    fundingRequestId?: string | null;
    withdrawalRequestId?: string | null;
    reconciliationType?: string;
  }): Promise<any> {
    const { tenantId, fundingRequestId = null, withdrawalRequestId = null, reconciliationType = 'FUNDING_SETTLEMENT' } = params;

    const result = await this.reconcileFundingRequest({ tenantId, fundingRequestId, withdrawalRequestId });

    const idempotencyKey = deterministicIdempotencyKey({
      type: `funding-reconciliation:${reconciliationType}`,
      tenantId,
      externalRef: fundingRequestId ?? withdrawalRequestId ?? `${Date.now()}`,
    });

    try {
      const existing = await (this.prisma as any).fundingReconciliation.findFirst({ where: { tenantId, idempotencyKey } });
      if (existing) return existing;
    } catch {}

    const request = fundingRequestId
      ? await (this.prisma as any).fundingRequest.findFirst({ where: { id: fundingRequestId, tenantId } })
      : await (this.prisma as any).withdrawalRequest.findFirst({ where: { id: withdrawalRequestId, tenantId } });

    const reconciliation = await (this.prisma as any).fundingReconciliation.create({
      data: {
        tenantId,
        fundingRequestId: fundingRequestId ?? null,
        withdrawalRequestId: withdrawalRequestId ?? null,
        reconciliationType,
        expected: { requestState: request?.state, requestedAmount: request?.requestedAmount, currency: request?.currency } as any,
        actual: { externalReference: request?.externalReference, confirmedAmount: request?.confirmedAmount } as any,
        discrepancyType: result.discrepancies.length > 0 ? result.discrepancies[0].type : null,
        discrepancyDetails: result.discrepancies as any,
        isCritical: result.hasCritical,
        isResolved: false,
        sourceType: 'FUNDING_RECONCILIATION',
        sourceId: fundingRequestId ?? withdrawalRequestId ?? null,
        externalReference: request?.externalReference ?? null,
        idempotencyKey,
      },
    });

    // Do not silently rewrite funding state from local assumption — only report discrepancies

    return reconciliation;
  }

  async listReconciliations(params: {
    tenantId: string;
    fundingRequestId?: string;
    withdrawalRequestId?: string;
    isCritical?: boolean;
    isResolved?: boolean;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId, fundingRequestId, withdrawalRequestId, isCritical, isResolved, page = 1, limit = 50 } = params;
    const where: any = { tenantId };
    if (fundingRequestId) where.fundingRequestId = fundingRequestId;
    if (withdrawalRequestId) where.withdrawalRequestId = withdrawalRequestId;
    if (isCritical !== undefined) where.isCritical = isCritical;
    if (isResolved !== undefined) where.isResolved = isResolved;

    const [data, total] = await Promise.all([
      (this.prisma as any).fundingReconciliation.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).fundingReconciliation.count({ where }),
    ]);
    return { data, total, page, limit };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { redactPiiAndSecrets } from './client-lifecycle.types';

/**
 * Produces immutable lifecycle audit records for every sensitive client/account/ownership/funding/
 * restriction/review transition and redacts PII/secrets appropriately.
 */

@Injectable()
export class LifecycleAuditService {
  private readonly logger = new Logger(LifecycleAuditService.name);

  constructor(private readonly prisma: PrismaService) {}

  async log(params: {
    tenantId: string;
    clientProfileId?: string | null;
    accountId?: string | null;
    action: string;
    entityType: string;
    entityId?: string | null;
    actorId?: string | null;
    actorType?: string | null;
    fromState?: string | null;
    toState?: string | null;
    reason?: string | null;
    sourceType?: string | null;
    sourceId?: string | null;
    correlationId?: string | null;
    idempotencyKey?: string | null;
    evidence?: Record<string, unknown>;
    metadata?: Record<string, unknown>;
  }): Promise<void> {
    const {
      tenantId,
      clientProfileId = null,
      accountId = null,
      action,
      entityType,
      entityId = null,
      actorId = null,
      actorType = null,
      fromState = null,
      toState = null,
      reason = null,
      sourceType = null,
      sourceId = null,
      correlationId = null,
      idempotencyKey = null,
      evidence = {},
      metadata = {},
    } = params;

    // PII and sensitive account information must be protected and redacted from operational logs
    const scrubbedEvidence = redactPiiAndSecrets(evidence);
    const scrubbedMetadata = redactPiiAndSecrets(metadata);

    try {
      // Immutable audit — no update/delete, only create
      await (this.prisma as any).clientLifecycleAudit.create({
        data: {
          tenantId,
          clientProfileId: clientProfileId ?? null,
          accountId: accountId ?? null,
          action,
          entityType,
          entityId: entityId ?? null,
          actorId: actorId ?? null,
          actorType: actorType ?? null,
          fromState: fromState ?? null,
          toState: toState ?? null,
          reason: reason ?? null,
          sourceType: sourceType ?? null,
          sourceId: sourceId ?? null,
          correlationId: correlationId ?? null,
          idempotencyKey: idempotencyKey ?? null,
          evidence: scrubbedEvidence as any,
          metadata: scrubbedMetadata as any,
        },
      });
    } catch (e) {
      this.logger.warn(`Lifecycle audit log failed: ${(e as Error).message}`);
      // Fallback to logger — still immutable, no secrets
      this.logger.log({
        event: `client.audit.${action}.fallback`,
        tenantId,
        clientProfileId,
        accountId,
        entityType,
        entityId,
        evidence: scrubbedEvidence,
      });
    }

    // Also log to general audit if available
    try {
      if ((this.prisma as any).auditLog?.create) {
        await (this.prisma as any).auditLog.create({
          data: {
            tenantId,
            action: `CLIENT_LIFECYCLE_${action}`,
            resourceType: entityType,
            resourceId: entityId ?? clientProfileId ?? accountId ?? 'UNKNOWN',
            actorId,
            correlationId,
            metadata: {
              clientProfileId,
              accountId,
              fromState,
              toState,
              reason,
              ...scrubbedEvidence,
            } as any,
          },
        });
      }
    } catch {}
  }

  async listAudits(params: {
    tenantId: string;
    clientProfileId?: string;
    accountId?: string;
    action?: string;
    entityType?: string;
    from?: Date;
    to?: Date;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId, clientProfileId, accountId, action, entityType, from, to, page = 1, limit = 50 } = params;
    const where: any = { tenantId };
    if (clientProfileId) where.clientProfileId = clientProfileId;
    if (accountId) where.accountId = accountId;
    if (action) where.action = action;
    if (entityType) where.entityType = entityType;
    if (from || to) {
      where.createdAt = {};
      if (from) where.createdAt.gte = from;
      if (to) where.createdAt.lte = to;
    }

    const [data, total] = await Promise.all([
      (this.prisma as any).clientLifecycleAudit.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).clientLifecycleAudit.count({ where }),
    ]);
    return { data, total, page, limit };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

/** "ONBOARDING_STARTED" -> "Onboarding started". */
export function lifecycleNotificationTitle(type: string): string {
  const words = type.toLowerCase().split('_').filter(Boolean).join(' ');
  return words ? words.charAt(0).toUpperCase() + words.slice(1) : 'Account update';
}

/** Short body text: the reason when present, otherwise a generic account-update line. */
export function lifecycleNotificationBody(type: string, payload: any): string {
  const reason = payload && typeof payload.reason === 'string' && payload.reason.trim() ? payload.reason.trim() : null;
  const base = `${lifecycleNotificationTitle(type)} on your account.`;
  const text = reason ? `${base} Reason: ${reason}` : base;
  return text.length > 1000 ? `${text.slice(0, 997)}...` : text;
}

/**
 * Emits onboarding, approval, restriction, suspension, funding, withdrawal, review, and closure events
 * through existing Billing/Notification infrastructure without implementing a second notification provider.
 */

@Injectable()
export class LifecycleNotificationService {
  private readonly logger = new Logger(LifecycleNotificationService.name);

  constructor(private readonly prisma: PrismaService) {}

  private async emitViaExistingNotification(params: {
    tenantId: string;
    type: string;
    recipientId?: string | null;
    clientProfileId?: string | null;
    accountId?: string | null;
    payload: any;
  }): Promise<void> {
    const { tenantId, type, recipientId = null, clientProfileId = null, accountId = null, payload } = params;

    // Reuse existing NotificationsModule — check if notification model exists
    try {
      // Notification rows need a recipient user (userId is a required FK) plus title/body.
      if (recipientId && (this.prisma as any).notification?.create) {
        await (this.prisma as any).notification.create({
          data: {
            tenantId,
            userId: recipientId,
            type: `CLIENT_LIFECYCLE_${type}`,
            title: lifecycleNotificationTitle(type),
            body: lifecycleNotificationBody(type, payload),
            data: {
              clientProfileId,
              accountId,
              ...payload,
              source: 'ClientLifecycleModule',
            } as any,
          },
        });
      } else {
        // Fallback: log via logger — no second notification provider
        this.logger.log({
          event: `client.notification.${type}`,
          tenantId,
          clientProfileId,
          accountId,
          recipientId,
          payload,
          note: 'Emitted via existing notification infrastructure',
        });
      }
    } catch (e) {
      this.logger.warn(`Failed to emit notification ${type}: ${(e as Error).message}`);
    }
  }

  async notifyOnboardingStarted(params: { tenantId: string; clientProfileId: string; onboardingId: string; recipientId?: string | null }): Promise<void> {
    await this.emitViaExistingNotification({
      tenantId: params.tenantId,
      type: 'ONBOARDING_STARTED',
      clientProfileId: params.clientProfileId,
      payload: { onboardingId: params.onboardingId },
      recipientId: params.recipientId ?? null,
    });
  }

  async notifyOnboardingApproved(params: { tenantId: string; clientProfileId: string; onboardingId: string; recipientId?: string | null }): Promise<void> {
    await this.emitViaExistingNotification({
      tenantId: params.tenantId,
      type: 'ONBOARDING_APPROVED',
      clientProfileId: params.clientProfileId,
      payload: { onboardingId: params.onboardingId },
      recipientId: params.recipientId ?? null,
    });
  }

  async notifyApprovalRequired(params: { tenantId: string; clientProfileId?: string | null; accountId?: string | null; requestType: string; requestId: string; recipientId?: string | null }): Promise<void> {
    await this.emitViaExistingNotification({
      tenantId: params.tenantId,
      type: `${params.requestType}_APPROVAL_REQUIRED`,
      clientProfileId: params.clientProfileId ?? null,
