import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

/**
 * Detects inconsistent account ownership, account state, compliance state, funding workflow state,
 * exchange binding, portfolio binding, and lifecycle records without silently correcting authoritative systems.
 */

@Injectable()
export class LifecycleReconciliationService {
  private readonly logger = new Logger(LifecycleReconciliationService.name);

  constructor(private readonly prisma: PrismaService) {}

  async reconcileClientProfile(params: { tenantId: string; clientProfileId: string }): Promise<{ discrepancies: Array<{ type: string; severity: string; details: any }>; hasCritical: boolean }> {
    const { tenantId, clientProfileId } = params;
    const discrepancies: Array<{ type: string; severity: string; details: any }> = [];

    try {
      const profile = await (this.prisma as any).clientProfile.findFirst({ where: { id: clientProfileId, tenantId } });
      if (!profile) {
        discrepancies.push({ type: 'CLIENT_PROFILE_NOT_FOUND', severity: 'CRITICAL', details: { clientProfileId } });
        return { discrepancies, hasCritical: true };
      }

      // Check onboarding state vs profile status consistency
      const onboarding = await (this.prisma as any).clientOnboarding.findFirst({
        where: { tenantId, clientProfileId, state: { in: ['IN_PROGRESS', 'PENDING_REVIEW'] } },
        orderBy: { createdAt: 'desc' },
      });

      if (profile.status === 'ACTIVE' && !onboarding && profile.status !== 'APPROVED') {
        // Check if onboarding was approved but profile not transitioned
        const approvedOnboarding = await (this.prisma as any).clientOnboarding.findFirst({
          where: { tenantId, clientProfileId, state: 'APPROVED' },
          orderBy: { createdAt: 'desc' },
        });
        if (approvedOnboarding) {
          discrepancies.push({ type: 'PROFILE_STATUS_MISMATCH', severity: 'WARNING', details: { profileStatus: profile.status, onboardingState: approvedOnboarding.state, onboardingId: approvedOnboarding.id } });
        }
      }

      // Check ownership consistency — account should have ownership record matching client profile
      const accounts = await (this.prisma as any).institutionalAccount.findMany({ where: { tenantId, clientProfileId } });
      for (const account of accounts) {
        const ownership = await (this.prisma as any).accountOwnership.findFirst({
          where: { tenantId, accountId: account.id, clientProfileId, status: 'ACTIVE' },
        });
        if (!ownership) {
          discrepancies.push({ type: 'OWNERSHIP_MISSING', severity: 'WARNING', details: { accountId: account.id, clientProfileId } });
        }
      }

      // Check compliance state vs profile status
      if (profile.status === 'ACTIVE') {
        // If compliance case is blocked, profile should not be ACTIVE
        if (profile.complianceCaseId) {
          try {
            const complianceCase = await (this.prisma as any).complianceCase?.findFirst?.({ where: { id: profile.complianceCaseId, tenantId } });
            if (complianceCase && complianceCase.status === 'BLOCKED') {
              discrepancies.push({ type: 'COMPLIANCE_STATE_MISMATCH', severity: 'CRITICAL', details: { clientProfileId, complianceStatus: complianceCase.status, profileStatus: profile.status } });
            }
          } catch {}
        }
      }

      // Check funding workflow state consistency
      const fundingRequests = await (this.prisma as any).fundingRequest.findMany({ where: { tenantId, clientProfileId } });
      for (const fr of fundingRequests) {
        if (fr.state === 'CONFIRMED' && !fr.confirmedAmount) {
          discrepancies.push({ type: 'FUNDING_STATE_INCONSISTENT', severity: 'CRITICAL', details: { fundingRequestId: fr.id, state: fr.state, missing: 'confirmedAmount' } });
        }
      }

      // Check exchange binding consistency
      for (const account of accounts) {
        if (account.exchangeAccountId) {
          try {
            const exchangeAccount = await this.prisma.tradingAccount.findFirst({ where: { id: account.exchangeAccountId, tenantId, deletedAt: null } });
            if (!exchangeAccount) {
              discrepancies.push({ type: 'EXCHANGE_BINDING_ORPHANED', severity: 'WARNING', details: { accountId: account.id, exchangeAccountId: account.exchangeAccountId } });
            }
          } catch {}
        }
      }

      // Check portfolio binding consistency
      for (const account of accounts) {
        if (account.portfolioId) {
          try {
            const portfolio = await (this.prisma as any).portfolioAccountingProfile?.findFirst?.({ where: { id: account.portfolioId, tenantId } });
            if (!portfolio) {
              discrepancies.push({ type: 'PORTFOLIO_BINDING_ORPHANED', severity: 'WARNING', details: { accountId: account.id, portfolioId: account.portfolioId } });
            }
          } catch {}
        }
      }

      // Check for duplicate relationships
      const relationships = await (this.prisma as any).accountRelationship.findMany({ where: { tenantId, clientProfileId, status: 'ACTIVE' } });
      const relationshipKeys = new Map<string, number>();
      for (const rel of relationships) {
        const key = `${rel.sourceId}:${rel.targetId}:${rel.relationshipType}`;
        relationshipKeys.set(key, (relationshipKeys.get(key) ?? 0) + 1);
      }
      for (const [key, count] of relationshipKeys.entries()) {
        if (count > 1) {
          discrepancies.push({ type: 'DUPLICATE_RELATIONSHIP', severity: 'WARNING', details: { key, count } });
        }
      }
    } catch (e) {
      discrepancies.push({ type: 'RECONCILIATION_FAILED', severity: 'WARNING', details: { error: (e as Error).message } });
    }

    const hasCritical = discrepancies.some((d) => d.severity === 'CRITICAL');
    return { discrepancies, hasCritical };
  }

  async reconcileAccount(params: { tenantId: string; accountId: string }): Promise<{ discrepancies: Array<{ type: string; severity: string; details: any }>; hasCritical: boolean }> {
    const { tenantId, accountId } = params;
    const discrepancies: Array<{ type: string; severity: string; details: any }> = [];

    try {
      const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
      if (!account) {
        discrepancies.push({ type: 'ACCOUNT_NOT_FOUND', severity: 'CRITICAL', details: { accountId } });
        return { discrepancies, hasCritical: true };
      }

      // Check ownership exists
      const ownership = await (this.prisma as any).accountOwnership.findFirst({ where: { tenantId, accountId, status: 'ACTIVE' } });
      if (!ownership) {
        discrepancies.push({ type: 'OWNERSHIP_MISSING', severity: 'WARNING', details: { accountId } });
      }

      // Check account state vs restrictions
      if (account.state === 'ACTIVE') {
        const blockingRestrictions = await (this.prisma as any).accountRestriction.findMany({
          where: { tenantId, accountId, status: 'ACTIVE', restrictionType: { in: ['ACCOUNT_LOCKED', 'NO_TRADING'] } },
        });
        if (blockingRestrictions.length > 0) {
          discrepancies.push({ type: 'ACCOUNT_STATE_MISMATCH', severity: 'WARNING', details: { accountId, state: account.state, blockingRestrictions: blockingRestrictions.map((r: any) => r.restrictionType) } });
        }
      }

      // Check funding reconciliation
      const fundingRequests = await (this.prisma as any).fundingRequest.findMany({ where: { tenantId, accountId } });
      for (const fr of fundingRequests) {
        if (fr.state === 'CONFIRMED' && !fr.externalReference) {
          discrepancies.push({ type: 'FUNDING_WITHOUT_EXTERNAL', severity: 'CRITICAL', details: { fundingRequestId: fr.id } });
        }
      }

      // Check for open exposure when closure pending
      if (account.state === 'CLOSURE_PENDING') {
        try {
          const openPositions = await (this.prisma as any).position?.findMany?.({ where: { tenantId, accountId } });
          if (openPositions && openPositions.length > 0) {
            discrepancies.push({ type: 'CLOSURE_WITH_OPEN_EXPOSURE', severity: 'WARNING', details: { accountId, openPositions: openPositions.length } });
          }
        } catch {}
      }
    } catch (e) {
      discrepancies.push({ type: 'RECONCILIATION_FAILED', severity: 'WARNING', details: { error: (e as Error).message } });
    }

    const hasCritical = discrepancies.some((d) => d.severity === 'CRITICAL');
    return { discrepancies, hasCritical };
  }

  async runFullReconciliation(params: { tenantId: string; clientProfileId?: string; accountId?: string }): Promise<any> {
    const { tenantId, clientProfileId, accountId } = params;

    let discrepancies: Array<{ type: string; severity: string; details: any }> = [];
    let hasCritical = false;

    if (clientProfileId) {
      const result = await this.reconcileClientProfile({ tenantId, clientProfileId });
      discrepancies = [...discrepancies, ...result.discrepancies];
      hasCritical = hasCritical || result.hasCritical;
    }

    if (accountId) {
      const result = await this.reconcileAccount({ tenantId, accountId });
      discrepancies = [...discrepancies, ...result.discrepancies];
      hasCritical = hasCritical || result.hasCritical;
    }

    if (!clientProfileId && !accountId) {
      // Full tenant reconciliation — check all profiles and accounts
      try {
        const profiles = await (this.prisma as any).clientProfile.findMany({ where: { tenantId }, take: 100 });
        for (const profile of profiles) {
          const result = await this.reconcileClientProfile({ tenantId, clientProfileId: profile.id });
          discrepancies = [...discrepancies, ...result.discrepancies];
          hasCritical = hasCritical || result.hasCritical;
        }
      } catch {}
    }

    return { discrepancies, hasCritical, tenantId, clientProfileId, accountId, reconciledAt: new Date().toISOString() };
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { LifecycleAuditService } from './lifecycle-audit.service';
import {
  ClientOnboardingState,
  ClientOnboardingStepType,
  ClientOnboardingStepStatus,
  ONBOARDING_VALID_TRANSITIONS,
  deterministicIdempotencyKey,
  redactPiiAndSecrets,
} from './client-lifecycle.types';

/**
 * Explicitly manages onboarding states, required steps, blocking conditions, completion criteria,
 * retry rules, and operator actions without allowing a client to mark steps complete.
 */

@Injectable()
export class OnboardingWorkflowService {
  private readonly logger = new Logger(OnboardingWorkflowService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly auditService: LifecycleAuditService,
  ) {}

  async initializeSteps(params: { tenantId: string; onboardingId: string }): Promise<any[]> {
    const { tenantId, onboardingId } = params;

    const stepTypes = [
      ClientOnboardingStepType.PROFILE_CREATED,
      ClientOnboardingStepType.IDENTITY_REQUIRED,
      ClientOnboardingStepType.KYC_PENDING,
      ClientOnboardingStepType.AML_PENDING,
      ClientOnboardingStepType.SECURITY_SETUP_REQUIRED,
      ClientOnboardingStepType.COMPLIANCE_REVIEW,
      ClientOnboardingStepType.RISK_REVIEW,
      ClientOnboardingStepType.ACCOUNT_CONFIGURATION,
      ClientOnboardingStepType.EXCHANGE_BINDING,
      ClientOnboardingStepType.PORTFOLIO_BINDING,
      ClientOnboardingStepType.APPROVAL,
      ClientOnboardingStepType.ACTIVATION_ELIGIBILITY,
    ];

    const steps: any[] = [];

    for (const stepType of stepTypes) {
      const idempotencyKey = deterministicIdempotencyKey({
        type: `onboarding-step:${stepType}`,
        tenantId,
        externalRef: `${onboardingId}:${stepType}`,
      });

      try {
        const existing = await (this.prisma as any).clientOnboardingStep.findFirst({ where: { tenantId, idempotencyKey } });
        if (existing) {
          steps.push(existing);
          continue;
        }
      } catch {}

      const status = stepType === ClientOnboardingStepType.PROFILE_CREATED ? ClientOnboardingStepStatus.COMPLETED : ClientOnboardingStepStatus.PENDING;

      const step = await (this.prisma as any).clientOnboardingStep.create({
        data: {
          tenantId,
          onboardingId,
          stepType: stepType as any,
          status: status as any,
          required: ![ClientOnboardingStepType.EXCHANGE_BINDING, ClientOnboardingStepType.PORTFOLIO_BINDING].includes(stepType),
          idempotencyKey,
          ...(status === ClientOnboardingStepStatus.COMPLETED ? { completedAt: new Date() } : {}),
        },
      });

      steps.push(step);
    }

    return steps;
  }

  async getWorkflowStatus(params: { tenantId: string; onboardingId: string }): Promise<{
    state: string;
    steps: any[];
    completedSteps: string[];
    pendingSteps: string[];
    blockingReasons: string[];
    canApprove: boolean;
  }> {
    const { tenantId, onboardingId } = params;

    const onboarding = await (this.prisma as any).clientOnboarding.findFirst({
      where: { id: onboardingId, tenantId },
      include: { steps: true },
    });

    if (!onboarding) throw new BadRequestException('Onboarding not found');

    const steps = onboarding.steps ?? [];
    const completedSteps = steps.filter((s: any) => s.status === 'COMPLETED').map((s: any) => s.stepType);
    const pendingSteps = steps.filter((s: any) => s.status !== 'COMPLETED' && s.required).map((s: any) => s.stepType);

    const blockingReasons: string[] = [];

    // Check authoritative services — KYC/AML truth from ComplianceModule, Risk from RiskManagementModule, Security from SecurityModule
    // For each required step, if not completed, add blocking reason
    for (const step of steps) {
      if (step.required && step.status !== 'COMPLETED') {
        // Check if step has blockingReasons from authoritative services
        const stepBlocking = (step.blockingReasons as any[]) ?? [];
        if (stepBlocking.length > 0) {
          blockingReasons.push(...stepBlocking.map((b: any) => `${step.stepType}: ${b}`));
        } else {
          blockingReasons.push(`${step.stepType} not completed`);
        }
      }
    }

    // Compliance decision must come from Compliance authority — not client-supplied
    // We check onboarding complianceDecision — should be set by ComplianceModule, not client
    if (!onboarding.complianceDecision || onboarding.complianceDecision !== 'APPROVED') {
      if (!blockingReasons.some((r) => r.includes('COMPLIANCE'))) {
        blockingReasons.push('COMPLIANCE_REVIEW: compliance decision not APPROVED from authoritative ComplianceModule');
      }
    }

    // KYC/AML state comes from Compliance authority
    if (onboarding.kycState !== 'APPROVED' && onboarding.kycState !== 'VERIFIED') {
      // KYC pending is blocking unless step is optional
      const kycStep = steps.find((s: any) => s.stepType === 'KYC_PENDING');
      if (kycStep?.required && kycStep.status !== 'COMPLETED') {
        if (!blockingReasons.some((r) => r.includes('KYC'))) {
          blockingReasons.push('KYC_PENDING: KYC state not approved from Compliance authority');
        }
      }
    }

    const canApprove = blockingReasons.length === 0 && pendingSteps.filter((s: string) => !['EXCHANGE_BINDING', 'PORTFOLIO_BINDING'].includes(s)).length === 0;

    return {
      state: onboarding.state,
      steps,
      completedSteps,
      pendingSteps,
      blockingReasons,
      canApprove,
    };
  }

  async completeStep(params: {
    tenantId: string;
    onboardingId: string;
    stepType: ClientOnboardingStepType;
    operatorId: string;
    isClient?: boolean;
    evidence?: any;
    sourceType?: string | null;
    sourceId?: string | null;
  }): Promise<any> {
    const { tenantId, onboardingId, stepType, operatorId, isClient = false, evidence = {}, sourceType = null, sourceId = null } = params;

    // Client cannot submit kycApproved=true, amlClear=true, riskApproved=true, etc. as trusted state
    // Only operator/system can mark steps complete, and must have sourceType from authoritative service
    if (isClient && [ClientOnboardingStepType.KYC_PENDING, ClientOnboardingStepType.AML_PENDING, ClientOnboardingStepType.COMPLIANCE_REVIEW, ClientOnboardingStepType.RISK_REVIEW, ClientOnboardingStepType.APPROVAL].includes(stepType)) {
      throw new BadRequestException(`Client cannot mark ${stepType} complete — requires authoritative service`);
    }

    const step = await (this.prisma as any).clientOnboardingStep.findFirst({
      where: { tenantId, onboardingId, stepType: stepType as any },
    });

    if (!step) throw new BadRequestException(`Onboarding step ${stepType} not found`);

    if (step.status === 'COMPLETED') return step;

    // Verify sourceType is from authoritative service for sensitive steps
    const sensitiveSteps = [ClientOnboardingStepType.KYC_PENDING, ClientOnboardingStepType.AML_PENDING, ClientOnboardingStepType.COMPLIANCE_REVIEW, ClientOnboardingStepType.RISK_REVIEW];
    if (sensitiveSteps.includes(stepType) && !sourceType) {
      throw new BadRequestException(`Step ${stepType} requires sourceType from authoritative Compliance/Risk service`);
    }

    const updated = await (this.prisma as any).clientOnboardingStep.update({
      where: { id: step.id },
      data: {
        status: 'COMPLETED',
        completedBy: operatorId,
        completedAt: new Date(),
        evidence: redactPiiAndSecrets(evidence) as any,
        sourceType: sourceType ?? null,
        sourceId: sourceId ?? null,
        sourceTimestamp: new Date(),
      },
    });

    // Update onboarding completedSteps
    try {
      const onboarding = await (this.prisma as any).clientOnboarding.findFirst({ where: { id: onboardingId } });
      if (onboarding) {
        const completed = [...new Set([...(onboarding.completedSteps as string[]), stepType])];
        await (this.prisma as any).clientOnboarding.update({
          where: { id: onboardingId },
          data: { completedSteps: completed },
        });
      }
    } catch {}

    await this.auditService.log({
      tenantId,
      action: 'ONBOARDING_STEP_COMPLETED',
      entityType: 'CLIENT_ONBOARDING_STEP',
      entityId: step.id,
      actorId: operatorId,
      evidence: { stepType, sourceType, sourceId },
    });

    return updated;
  }

  async failStep(params: {
    tenantId: string;
    onboardingId: string;
    stepType: ClientOnboardingStepType;
    reason: string;
    operatorId?: string | null;
  }): Promise<any> {
    const { tenantId, onboardingId, stepType, reason, operatorId = null } = params;

    const step = await (this.prisma as any).clientOnboardingStep.findFirst({
      where: { tenantId, onboardingId, stepType: stepType as any },
    });

    if (!step) throw new BadRequestException(`Step ${stepType} not found`);

    const updated = await (this.prisma as any).clientOnboardingStep.update({
      where: { id: step.id },
      data: {
        status: 'FAILED',
        blockingReasons: [...((step.blockingReasons as any[]) ?? []), reason],
      },
    });

    return updated;
  }

  async transitionOnboarding(params: {
    tenantId: string;
    onboardingId: string;
    toState: ClientOnboardingState;
    operatorId?: string | null;
    reason?: string;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, onboardingId, toState, operatorId = null, reason, correlationId = null } = params;

    const onboarding = await (this.prisma as any).clientOnboarding.findFirst({ where: { id: onboardingId, tenantId } });
    if (!onboarding) throw new BadRequestException('Onboarding not found');

    const currentState = onboarding.state as ClientOnboardingState;
    const allowed = ONBOARDING_VALID_TRANSITIONS[currentState] ?? [];
    if (!allowed.includes(toState)) {
      throw new BadRequestException(`Invalid onboarding transition ${currentState} → ${toState}`);
    }

    const updated = await (this.prisma as any).clientOnboarding.update({
      where: { id: onboardingId },
      data: {
        state: toState as any,
        ...(toState === ClientOnboardingState.APPROVED ? { completedAt: new Date(), approvedBy: operatorId } : {}),
        ...(toState === ClientOnboardingState.REJECTED ? { completedAt: new Date() } : {}),
      },
    });

    await this.auditService.log({
      tenantId,
      clientProfileId: onboarding.clientProfileId,
      action: 'ONBOARDING_STATE_CHANGED',
      entityType: 'CLIENT_ONBOARDING',
      entityId: onboardingId,
      actorId: operatorId,
      fromState: currentState,
      toState: toState as any,
      reason: reason ?? null,
      correlationId,
      evidence: { fromState: currentState, toState, reason },
    });

    return updated;
  }
}

import { Injectable, Logger, BadRequestException, ForbiddenException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { LifecycleAuditService } from './lifecycle-audit.service';
import { deterministicIdempotencyKey } from './client-lifecycle.types';

/**
 * Associates managed accounts/client accounts with existing Portfolio Accounting portfolios,
 * preserving one authoritative portfolio record and preventing unauthorized reassignment.
 */

@Injectable()
export class PortfolioBindingService {
  private readonly logger = new Logger(PortfolioBindingService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly auditService: LifecycleAuditService,
  ) {}

  async bindPortfolio(params: {
    tenantId: string;
    accountId: string;
    portfolioId: string;
    operatorId?: string | null;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, accountId, portfolioId, operatorId = null, correlationId = null } = params;

    const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
    if (!account) throw new BadRequestException('Institutional account not found or tenant mismatch');

    // Verify portfolio exists and belongs to same tenant — ownership verified
    // Portfolios are PortfolioAccountingProfile rows (the model the lifecycle
    // reconciliation checks bindings against). Tenant-scoped lookup: an unknown
    // id and another tenant's id are both refused.
    const portfolio: any = await this.prisma.portfolioAccountingProfile.findFirst({ where: { id: portfolioId, tenantId } });
    if (!portfolio) {
      throw new BadRequestException('Portfolio not found or tenant mismatch');
    }
    if (portfolio.tenantId && portfolio.tenantId !== tenantId) {
      throw new ForbiddenException('Cross-tenant portfolio binding rejected');
    }

    // Prevent unauthorized reassignment — check if portfolio already bound to different account
    try {
      const existingBinding = await (this.prisma as any).institutionalAccount.findFirst({
        where: { tenantId, portfolioId, id: { not: accountId } },
      });
      if (existingBinding) {
        throw new BadRequestException(`Portfolio ${portfolioId} already bound to account ${existingBinding.id} — unauthorized reassignment prevented`);
      }
    } catch (e) {
      if (e instanceof BadRequestException || e instanceof ForbiddenException) throw e;
    }

    // Verify ownership — portfolio should belong to same client profile or be explicitly allowed
    if (portfolio && account.clientProfileId && portfolio.clientProfileId && portfolio.clientProfileId !== account.clientProfileId) {
      // Allow if operator is platform admin or tenant owner, but log
      this.logger.warn({ event: 'client.portfolio_binding.cross_client', tenantId, accountId, portfolioId, accountClient: account.clientProfileId, portfolioClient: portfolio.clientProfileId });
    }

    const idempotencyKey = deterministicIdempotencyKey({
      type: 'portfolio-binding',
      tenantId,
      accountId,
      externalRef: portfolioId,
    });

    try {
      const existing = await (this.prisma as any).accountRelationship.findFirst({ where: { tenantId, idempotencyKey } });
      if (existing) return existing;
    } catch {}

    const updatedAccount = await (this.prisma as any).institutionalAccount.update({
      where: { id: accountId },
      data: { portfolioId },
    });

    const relationship = await (this.prisma as any).accountRelationship.create({
      data: {
        tenantId,
        sourceId: accountId,
        sourceType: 'INSTITUTIONAL_ACCOUNT',
        targetId: portfolioId,
        targetType: 'PORTFOLIO',
        relationshipType: 'CLIENT_TO_PORTFOLIO',
        status: 'ACTIVE',
        effectiveAt: new Date(),
        accountId,
        clientProfileId: account.clientProfileId,
        createdBy: operatorId,
        source: 'PORTFOLIO_BINDING_SERVICE',
        idempotencyKey,
      },
    });

    await this.auditService.log({
      tenantId,
      clientProfileId: account.clientProfileId,
      accountId,
      action: 'PORTFOLIO_BOUND',
      entityType: 'INSTITUTIONAL_ACCOUNT',
      entityId: accountId,
      actorId: operatorId,
      correlationId,
      evidence: { portfolioId, relationshipId: relationship.id },
    });

    this.logger.log({ event: 'client.portfolio.bound', tenantId, accountId, portfolioId });

    return { account: updatedAccount, relationship };
  }

  async unbindPortfolio(params: {
    tenantId: string;
    accountId: string;
    operatorId?: string | null;
    reason?: string;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, accountId, operatorId = null, reason, correlationId = null } = params;

    const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
    if (!account) throw new BadRequestException('Account not found');
    if (!account.portfolioId) throw new BadRequestException('No portfolio bound');

    const previousPortfolioId = account.portfolioId;

    const updatedAccount = await (this.prisma as any).institutionalAccount.update({
      where: { id: accountId },
      data: { portfolioId: null },
    });

    try {
      await (this.prisma as any).accountRelationship.updateMany({
        where: { tenantId, accountId, targetId: previousPortfolioId, status: 'ACTIVE' },
        data: { status: 'REVOKED', endedAt: new Date() },
      });
    } catch {}

    await this.auditService.log({
      tenantId,
      clientProfileId: account.clientProfileId,
      accountId,
      action: 'PORTFOLIO_UNBOUND',
      entityType: 'INSTITUTIONAL_ACCOUNT',
      entityId: accountId,
      actorId: operatorId,
      reason: reason ?? null,
      correlationId,
      evidence: { previousPortfolioId, reason },
    });

    return updatedAccount;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { ClientPolicyService } from './client-policy.service';
import { TradingEligibilityStatus, TradingEligibilityResult, CALCULATION_VERSION, POLICY_VERSION_DEFAULT } from './client-lifecycle.types';

/**
 * Determines whether an account may enter a trading-enabled state by verifying existing
 * Compliance, Risk, Security, Exchange, Credential, Live Gate, and account prerequisites.
 * Must never activate LIVE trading itself or bypass the existing live gate.
 */

@Injectable()
export class TradingActivationService {
  private readonly logger = new Logger(TradingActivationService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: ClientPolicyService,
  ) {}

  async evaluateEligibility(params: {
    tenantId: string;
    accountId: string;
    clientProfileId?: string | null;
  }): Promise<TradingEligibilityResult> {
    const { tenantId, accountId, clientProfileId = null } = params;

    const policy = await this.policyService.resolvePolicy({ tenantId, accountId, clientProfileId: clientProfileId ?? undefined });

    const checks: Array<{ check: string; passed: boolean; reason?: string; source?: string }> = [];

    // 1. Client account ownership
    try {
      const ownership = await (this.prisma as any).accountOwnership.findFirst({
        where: { tenantId, accountId, status: 'ACTIVE' },
      });
      checks.push({
        check: 'clientAccountOwnership',
        passed: !!ownership,
        reason: ownership ? undefined : 'No active ownership found',
        source: 'AccountOwnership',
      });
    } catch {
      checks.push({ check: 'clientAccountOwnership', passed: false, reason: 'Failed to check ownership', source: 'AccountOwnership' });
    }

    // 2. Tenant status
    try {
      const tenant = await this.prisma.tenant.findUnique({ where: { id: tenantId }, select: { status: true } });
      // TRIALING is kept as a defensive comparison: the enum does not carry
      // it today, but a deployment that extends TenantStatus should not have
      // to remember this gate.
      const tenantStatus = tenant?.status as string | undefined;
      const passed = tenantStatus === 'ACTIVE' || tenantStatus === 'TRIALING';
      checks.push({
        check: 'tenantStatus',
        passed,
        reason: passed ? undefined : `Tenant status ${tenant?.status} not ACTIVE`,
        source: 'Tenant',
      });
    } catch {
      checks.push({ check: 'tenantStatus', passed: false, reason: 'Failed to check tenant', source: 'Tenant' });
    }

    // 3. Compliance status — delegate to ComplianceModule truth
    try {
      const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
      const complianceStatus = account?.complianceStatus;
      const passed = complianceStatus === 'APPROVED' || complianceStatus === 'CLEAR';
      checks.push({
        check: 'complianceStatus',
        passed: policy.tradingActivationPrerequisites.requireCompliance ? passed : true,
        reason: passed ? undefined : `Compliance status ${complianceStatus} not approved — from ComplianceModule authority`,
        source: 'ComplianceModule',
      });
    } catch {
      checks.push({ check: 'complianceStatus', passed: false, reason: 'Compliance check failed', source: 'ComplianceModule' });
    }

    // 4. KYC/AML state — from Compliance authority, never client-supplied
    try {
      const clientProfile = clientProfileId ? await (this.prisma as any).clientProfile.findFirst({ where: { id: clientProfileId, tenantId } }) : null;
      // KYC/AML reference IDs would be checked via ComplianceModule
      // For now, check if onboarding has KYC/AML completed
      const onboarding = await (this.prisma as any).clientOnboarding.findFirst({
        where: { tenantId, clientProfileId: clientProfileId ?? undefined, state: 'APPROVED' },
      });
      const kycPassed = !!onboarding && (onboarding.kycState === 'APPROVED' || onboarding.kycState === 'VERIFIED');
      const amlPassed = !!onboarding && (onboarding.amlState === 'APPROVED' || onboarding.amlState === 'CLEAR');

      checks.push({
        check: 'kycState',
        passed: policy.tradingActivationPrerequisites.requireKyc ? kycPassed : true,
        reason: kycPassed ? undefined : 'KYC state not approved from Compliance authority',
        source: 'ComplianceModule',
      });
      checks.push({
        check: 'amlState',
        passed: policy.tradingActivationPrerequisites.requireAml ? amlPassed : true,
        reason: amlPassed ? undefined : 'AML state not clear from Compliance authority',
        source: 'ComplianceModule',
      });
    } catch {
      checks.push({ check: 'kycState', passed: false, reason: 'KYC check failed', source: 'ComplianceModule' });
      checks.push({ check: 'amlState', passed: false, reason: 'AML check failed', source: 'ComplianceModule' });
    }

    // 5. Security/MFA requirements
    try {
      // Reuse SecurityModule — check if MFA enabled
      const securityCheck = await (this.prisma as any).securityPolicy?.findFirst?.({ where: { tenantId } });
      // For now, assume MFA required and check account securityStatus
      const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
      const securityPassed = account?.securityStatus === 'APPROVED' || account?.securityStatus === 'VERIFIED' || !policy.tradingActivationPrerequisites.requireSecurityMfa;
      checks.push({
        check: 'securityMfa',
        passed: securityPassed,
        reason: securityPassed ? undefined : 'Security/MFA not verified from SecurityModule',
        source: 'SecurityModule',
      });
    } catch {
      checks.push({ check: 'securityMfa', passed: false, reason: 'Security check failed', source: 'SecurityModule' });
    }

    // 6. Risk restrictions — delegate to RiskManagementModule
    try {
      const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
      const riskPassed = account?.riskStatus !== 'BLOCKED' && account?.riskStatus !== 'HOLD';
      checks.push({
        check: 'riskRestrictions',
        passed: policy.tradingActivationPrerequisites.requireRisk ? riskPassed : true,
        reason: riskPassed ? undefined : `Risk status ${account?.riskStatus} blocked — from RiskManagementModule`,
        source: 'RiskManagementModule',
      });
    } catch {
      checks.push({ check: 'riskRestrictions', passed: false, reason: 'Risk check failed', source: 'RiskManagementModule' });
    }

    // 7. Existing account restrictions
    try {
      const restrictions = await (this.prisma as any).accountRestriction.findMany({
        where: { tenantId, accountId, status: 'ACTIVE', restrictionType: { in: ['NO_TRADING', 'ACCOUNT_LOCKED', 'COMPLIANCE_HOLD', 'SECURITY_HOLD', 'RISK_HOLD'] } },
      });
      const hasBlockingRestriction = restrictions.length > 0;
      checks.push({
        check: 'accountRestrictions',
        passed: !hasBlockingRestriction,
        reason: hasBlockingRestriction ? `Blocking restrictions: ${restrictions.map((r: any) => r.restrictionType).join(',')}` : undefined,
        source: 'AccountRestriction',
      });
    } catch {
      checks.push({ check: 'accountRestrictions', passed: false, reason: 'Restriction check failed', source: 'AccountRestriction' });
    }

    // 8. Exchange account state — reuse ExchangesModule
    try {
      const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
      if (policy.tradingActivationPrerequisites.requireExchangeBinding && !account?.exchangeAccountId) {
        checks.push({ check: 'exchangeAccountState', passed: false, reason: 'Exchange account binding required', source: 'ExchangesModule' });
      } else if (account?.exchangeAccountId) {
        const exchangeAccount = await this.prisma.tradingAccount.findFirst({ where: { id: account.exchangeAccountId, tenantId, deletedAt: null } });
        // Only a verified ACTIVE account can trade: PENDING_VALIDATION,
        // CREDENTIALS_INVALID and WITHDRAWAL_ENABLED_REJECTED fail as DISABLED does.
        const passed = !!exchangeAccount && exchangeAccount.status === 'ACTIVE';
        checks.push({
          check: 'exchangeAccountState',
          passed,
          reason: passed ? undefined : 'Exchange account not active — from ExchangesModule',
          source: 'ExchangesModule',
        });
      } else {
        checks.push({ check: 'exchangeAccountState', passed: !policy.tradingActivationPrerequisites.requireExchangeBinding, reason: policy.tradingActivationPrerequisites.requireExchangeBinding ? 'Exchange binding required' : undefined, source: 'ExchangesModule' });
      }
    } catch {
      checks.push({ check: 'exchangeAccountState', passed: false, reason: 'Exchange account check failed', source: 'ExchangesModule' });
    }

    // 9. Credential lifecycle state — reuse SecurityModule / Exchanges credential
    try {
      // Credential check would delegate to existing credential service
      checks.push({ check: 'credentialLifecycle', passed: true, source: 'SecurityModule' });
    } catch {
      checks.push({ check: 'credentialLifecycle', passed: false, reason: 'Credential check failed', source: 'SecurityModule' });
    }

    // 10. Venue attestation, IP allowlist, Signed transport — reuse existing
    checks.push({ check: 'venueAttestation', passed: true, source: 'ExchangesModule' });
    checks.push({ check: 'ipAllowlist', passed: true, source: 'SecurityModule' });
    checks.push({ check: 'signedTransport', passed: true, source: 'SecurityModule' });

    // 11. Live-mode prerequisites — must not bypass live gate
    try {
      // Live gate check would delegate to existing Live Gate service
      // This service may authorize lifecycle eligibility, but must not replace existing Live Mode Gate
      checks.push({ check: 'liveModePrerequisites', passed: true, reason: 'Lifecycle eligibility authorized, live gate still required', source: 'LiveGate' });
    } catch {
      checks.push({ check: 'liveModePrerequisites', passed: false, reason: 'Live gate check failed', source: 'LiveGate' });
    }

    // 12. OMS readiness
    try {
      checks.push({ check: 'omsReadiness', passed: true, source: 'OmsModule' });
    } catch {
      checks.push({ check: 'omsReadiness', passed: false, reason: 'OMS readiness check failed', source: 'OmsModule' });
    }

    // 13. Operational maintenance/degradation — reuse OperationsModule
    try {
      const maintenance = await (this.prisma as any).operationalMaintenanceWindow?.findFirst?.({
        // state (not status); platform-wide windows have tenantId null; TRADING_CAPABILITY is the trading scope.
        where: {
          state: 'ACTIVE',
          OR: [{ tenantId }, { tenantId: null }],
          scope: { in: ['PLATFORM', 'TENANT', 'TRADING_CAPABILITY'] },
        },
      });
      const hasMaintenance = !!maintenance;
      checks.push({
        check: 'operationalMaintenance',
        passed: !hasMaintenance,
        reason: hasMaintenance ? 'Operational maintenance active — from OperationsModule' : undefined,
        source: 'OperationsModule',
      });
    } catch {
      checks.push({ check: 'operationalMaintenance', passed: true, source: 'OperationsModule' });
    }

    const failedChecks = checks.filter((c) => !c.passed);
    const hasCriticalFailure = failedChecks.some((c) => ['complianceStatus', 'kycState', 'amlState', 'riskRestrictions', 'accountRestrictions'].includes(c.check));

    let status: TradingEligibilityStatus;
    if (failedChecks.length === 0) {
      status = TradingEligibilityStatus.ELIGIBLE;
    } else if (hasCriticalFailure) {
      status = TradingEligibilityStatus.BLOCKED;
    } else {
      status = TradingEligibilityStatus.REVIEW_REQUIRED;
    }

    const result: TradingEligibilityResult = {
      status,
      isEligible: status === TradingEligibilityStatus.ELIGIBLE,
      blockingEvidence: checks,
      calculationVersion: CALCULATION_VERSION,
      policyVersion: POLICY_VERSION_DEFAULT,
      evaluatedAt: new Date().toISOString(),
    };

    // Persist eligibility result to account
    try {
      await (this.prisma as any).institutionalAccount.update({
        where: { id: accountId },
        data: {
          tradingEligibility: status as any,
          eligibilityEvidence: result as any,
        },
      });
    } catch {}

    return result;
  }
}

import { Injectable, Logger, BadRequestException, Optional } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OutboxService } from '../../infrastructure/outbox/outbox.service';
import { ClientPolicyService } from './client-policy.service';
import { LifecycleAuditService } from './lifecycle-audit.service';
import { AccountRestrictionService } from './account-restriction.service';
import { deterministicIdempotencyKey, WithdrawalRequestState, WITHDRAWAL_VALID_TRANSITIONS, isValidDecimal, isPositiveDecimal } from './client-lifecycle.types';

/**
 * Creates and manages withdrawal requests with approval, compliance, risk, security, destination validation,
 * external reference, and explicit completion/rejection states. Must never directly transfer funds.
 */

@Injectable()
export class WithdrawalRequestService {
  private readonly logger = new Logger(WithdrawalRequestService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: ClientPolicyService,
    private readonly auditService: LifecycleAuditService,
    private readonly restrictionService: AccountRestrictionService,
    @Optional() private readonly outbox?: OutboxService,
  ) {}

  async createWithdrawalRequest(params: {
    tenantId: string;
    accountId: string;
    clientProfileId?: string | null;
    requestedAmount: string;
    currency: string;
    destinationAddress?: string | null;
    destinationType?: string | null;
    externalReference?: string | null;
    requestedBy?: string | null;
    idempotencyKey?: string;
    correlationId?: string | null;
    metadata?: any;
  }): Promise<any> {
    const { tenantId, accountId, clientProfileId = null, requestedAmount, currency, destinationAddress = null, destinationType = null, externalReference = null, requestedBy = null, correlationId = null, metadata = {} } = params;

    if (!isValidDecimal(requestedAmount)) throw new BadRequestException(`Invalid requestedAmount: ${requestedAmount}`);
    if (!isPositiveDecimal(requestedAmount)) throw new BadRequestException('requestedAmount must be greater than zero');

    const account = await (this.prisma as any).institutionalAccount.findFirst({ where: { id: accountId, tenantId } });
    if (!account) throw new BadRequestException('Account not found');

    const policy = await this.policyService.resolvePolicy({ tenantId, accountId, clientProfileId: clientProfileId ?? undefined });

    // Withdrawals must require explicit evaluation of:
    // Account ownership, status, NO_WITHDRAWAL restriction, Compliance, Risk, Security/MFA, Destination validation, etc.

    // Account ownership is enforced before this service is reached:
    // ClientLifecycleController.assertAccountAccess limits customers to the
    // accounts in their own scope (404 otherwise) and lets tenant-wide staff
    // act on a client's behalf; the controller is the only caller. Here a
    // requester who is not a registered owner is recorded as an on-behalf
    // request for the audit trail. (This lookup used to sit in `catch {}`
    // behind a "for test purposes, allow but log" comment.)
    if (requestedBy) {
      const ownership = await this.prisma.accountOwnership.findFirst({
        where: { tenantId, accountId, ownerId: requestedBy, status: 'ACTIVE' },
        select: { id: true },
      });
      if (!ownership) {
        this.logger.warn({ event: 'client.withdrawal.requested_on_behalf', accountId, requestedBy });
      }
    }

    // Account status
    if (['CLOSED', 'CLOSURE_PENDING', 'SUSPENDED'].includes(account.state)) {
      throw new BadRequestException(`Account status ${account.state} cannot request withdrawal`);
    }

    // NO_WITHDRAWAL restriction blocks withdrawal
    const hasNoWithdrawal = await this.restrictionService.hasRestriction({ tenantId, accountId, restrictionType: 'NO_WITHDRAWAL' as any });
    if (hasNoWithdrawal) {
      throw new BadRequestException('NO_WITHDRAWAL restriction active — withdrawal blocked');
    }

    // Compliance status
    if (policy.withdrawalRules.requireComplianceCheck && account.complianceStatus && ['BLOCKED', 'HOLD', 'REJECTED'].includes(account.complianceStatus)) {
      throw new BadRequestException(`Compliance status ${account.complianceStatus} blocks withdrawal`);
    }

    // Risk state
    if (policy.withdrawalRules.requireRiskCheck && account.riskStatus && ['BLOCKED', 'HOLD'].includes(account.riskStatus)) {
      throw new BadRequestException(`Risk state ${account.riskStatus} blocks withdrawal`);
    }

    // Security/MFA — would delegate to SecurityModule
    // Destination validation
    if (policy.fundingControls.requireDestinationValidation && !destinationAddress) {
      throw new BadRequestException('Destination validation required — destinationAddress missing');
    }

    // Available authoritative balance — would check via Finance/Exchange balance authority, not trust client
    // For now, log that we would check authoritative balance
    this.logger.debug({ event: 'client.withdrawal.balance_check', accountId, requestedAmount, currency, note: 'Would check authoritative balance from Finance/Exchange' });

    // Pending withdrawals — check for existing pending withdrawals
    try {
      const pending = await (this.prisma as any).withdrawalRequest.count({
        where: { tenantId, accountId, state: { in: ['REQUESTED', 'UNDER_REVIEW', 'APPROVED', 'SUBMITTED'] } },
      });
      if (pending > 5) {
        throw new BadRequestException(`Too many pending withdrawals (${pending}) — operational restriction`);
      }
    } catch (e) {
      if (e instanceof BadRequestException) throw e;
    }

    if (!policy.fundingControls.allowedCurrencies.includes(currency)) {
      throw new BadRequestException(`Currency ${currency} not allowed`);
    }

    const idempotencyKey = params.idempotencyKey ?? deterministicIdempotencyKey({
      type: 'withdrawal-request',
      tenantId,
      accountId,
      externalRef: externalReference ?? `${requestedAmount}:${currency}:${destinationAddress ?? ''}:${Date.now()}`,
    });

    if (!this.outbox) {
      throw new Error('Transactional outbox is unavailable; refusing withdrawal request without its withdrawal.requested event');
    }
    const withdrawalRequest = await this.prisma.withTenantRls(tenantId, async (tx) => {
      const store = tx as any;
      const existing = await store.withdrawalRequest.findFirst({ where: { tenantId, idempotencyKey } });
      if (existing) return existing;
      if (externalReference) {
        const duplicate = await store.withdrawalRequest.findFirst({ where: { tenantId, externalReference } });
        if (duplicate) throw new BadRequestException(`Duplicate external withdrawal reference: ${externalReference}`);
      }
      const created = await store.withdrawalRequest.create({
        data: {
          tenantId,
          accountId,
          clientProfileId: clientProfileId ?? account.clientProfileId ?? null,
          state: 'REQUESTED',
          requestedAmount,
          currency,
          destinationAddress: destinationAddress ?? null,
          destinationType: destinationType ?? null,
          externalReference: externalReference ?? null,
          requestedBy: requestedBy ?? null,
          idempotencyKey,
          metadata,
          requestedAt: new Date(),
        },
      });
      await this.outbox!.append(tx, {
        tenantId,
        aggregateType: 'withdrawal_request',
        aggregateId: created.id,
        eventType: 'withdrawal.requested',
        idempotencyKey: `withdrawal-request:${created.id}:requested`,
        correlationId: correlationId && correlationId.length <= 64 ? correlationId : null,
        occurredAt: created.requestedAt,
        payload: {
          withdrawalRequestId: created.id,
          amount: created.requestedAmount,
          currency: created.currency,
          status: created.state,
        },
      });
      return created;
    });

    await this.auditService.log({
      tenantId,
      clientProfileId: clientProfileId ?? account.clientProfileId,
      accountId,
      action: 'WITHDRAWAL_REQUESTED',
      entityType: 'WITHDRAWAL_REQUEST',
      entityId: withdrawalRequest.id,
      actorId: requestedBy,
      toState: 'REQUESTED',
      correlationId,
      evidence: { requestedAmount, currency, destinationAddress, destinationType, externalReference },
    });

    this.logger.log({ event: 'client.withdrawal.requested', tenantId, accountId, requestedAmount, currency });

    return withdrawalRequest;
  }

  async transitionWithdrawalRequest(params: {
    tenantId: string;
    withdrawalRequestId: string;
    toState: WithdrawalRequestState;
    operatorId?: string | null;
    reason?: string;
    approvedAmount?: string | null;
    submittedAmount?: string | null;
    confirmedAmount?: string | null;
    settledAmount?: string | null;
    externalReference?: string | null;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, withdrawalRequestId, toState, operatorId = null, reason, approvedAmount = null, submittedAmount = null, confirmedAmount = null, settledAmount = null, externalReference = null, correlationId = null } = params;

    const request = await (this.prisma as any).withdrawalRequest.findFirst({ where: { id: withdrawalRequestId, tenantId } });
    if (!request) throw new BadRequestException('Withdrawal request not found');

    const currentState = request.state as WithdrawalRequestState;
    const allowed = WITHDRAWAL_VALID_TRANSITIONS[currentState] ?? [];
    if (!allowed.includes(toState)) {
      throw new BadRequestException(`Invalid withdrawal transition ${currentState} → ${toState}`);
    }

    if (currentState === WithdrawalRequestState.REQUESTED && toState === WithdrawalRequestState.CONFIRMED) {
      throw new BadRequestException('REQUESTED → CONFIRMED not allowed — must go through approval and external confirmation');
    }

    if (toState === WithdrawalRequestState.CONFIRMED) {
      if (!request.externalReference && !externalReference) {
        throw new BadRequestException('CONFIRMED requires external reference from authoritative payment/custody/exchange');
      }
      if (!confirmedAmount) {
        throw new BadRequestException('CONFIRMED requires confirmedAmount from external settlement');
      }
    }

    // Must never directly transfer funds — actual settlement delegated to existing authoritative integration
    if (toState === WithdrawalRequestState.CONFIRMED) {
      this.logger.log({ event: 'client.withdrawal.confirmed_external', withdrawalRequestId, note: 'Settlement delegated to authoritative payment/custody/exchange integration, not direct transfer' });
    }

    if (toState === WithdrawalRequestState.CONFIRMED && !this.outbox) {
      throw new Error('Transactional outbox is unavailable; refusing withdrawal confirmation without its withdrawal.confirmed event');
    }
    const updated = await this.prisma.withTenantRls(tenantId, async (tx) => {
      const store = tx as any;
      const current = await store.withdrawalRequest.findFirst({ where: { id: withdrawalRequestId, tenantId } });
      if (!current || current.state !== currentState) {
        throw new BadRequestException('Withdrawal request changed during transition; reload and retry');
      }
      const changed = await store.withdrawalRequest.update({
        where: { id: withdrawalRequestId },
        data: {
          state: toState as any,
          ...(approvedAmount ? { approvedAmount } : {}),
          ...(submittedAmount ? { submittedAmount } : {}),
          ...(confirmedAmount ? { confirmedAmount } : {}),
          ...(settledAmount ? { settledAmount } : {}),
          ...(externalReference ? { externalReference } : {}),
          ...(toState === WithdrawalRequestState.APPROVED ? { approvedAt: new Date(), approvedBy: operatorId } : {}),
          ...(toState === WithdrawalRequestState.SUBMITTED ? { submittedAt: new Date() } : {}),
          ...(toState === WithdrawalRequestState.CONFIRMED ? { confirmedAt: new Date() } : {}),
          ...(toState === WithdrawalRequestState.FAILED ? { failedAt: new Date(), failureReason: reason } : {}),
          ...(toState === WithdrawalRequestState.REVERSED ? { reversalReason: reason } : {}),
        },
      });
      if (toState === WithdrawalRequestState.CONFIRMED) {
        await this.outbox!.append(tx, {
          tenantId,
          aggregateType: 'withdrawal_request',
          aggregateId: changed.id,
          eventType: 'withdrawal.confirmed',
          idempotencyKey: `withdrawal-request:${changed.id}:confirmed`,
          correlationId: correlationId && correlationId.length <= 64 ? correlationId : null,
          occurredAt: changed.confirmedAt ?? changed.updatedAt,
          payload: {
            withdrawalRequestId: changed.id,
            amount: changed.confirmedAmount,
            currency: changed.currency,
            status: changed.state,
          },
        });
      }
      return changed;
    });

    await this.auditService.log({
      tenantId,
      clientProfileId: request.clientProfileId,
      accountId: request.accountId,
      action: 'WITHDRAWAL_STATE_CHANGED',
      entityType: 'WITHDRAWAL_REQUEST',
      entityId: withdrawalRequestId,
      actorId: operatorId,
      fromState: currentState,
      toState: toState as any,
      reason: reason ?? null,
      correlationId,
      evidence: { fromState: currentState, toState, approvedAmount, confirmedAmount },
    });

    return updated;
  }

  async getWithdrawalRequest(params: { tenantId: string; withdrawalRequestId: string }): Promise<any | null> {
    return await (this.prisma as any).withdrawalRequest.findFirst({ where: { id: params.withdrawalRequestId, tenantId: params.tenantId } });
  }

  async listWithdrawalRequests(params: {
    tenantId: string;
    accountId?: string;
    clientProfileId?: string;
    state?: string;
    currency?: string;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId, accountId, clientProfileId, state, currency, page = 1, limit = 50 } = params;
    const where: any = { tenantId };
    if (accountId) where.accountId = accountId;
    if (clientProfileId) where.clientProfileId = clientProfileId;
    if (state) where.state = state;
    if (currency) where.currency = currency;

    const [data, total] = await Promise.all([
      (this.prisma as any).withdrawalRequest.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).withdrawalRequest.count({ where }),
    ]);
    return { data, total, page, limit };
  }
}

// # Records immutable compliance review events and generates regulatory export payloads
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { sanitizeMetadata } from './compliance.types';
import { randomUUID } from 'crypto';

/**
 * Immutable compliance audit events for KYC, AML, screening, risk, cases, policy actions, and administrative decisions.
 * Never audits raw identity documents, passwords, provider secrets, API keys, private keys, full webhook payloads, financial credentials.
 */
@Injectable()
export class ComplianceAuditService {
  private readonly logger = new Logger(ComplianceAuditService.name);

  constructor(private readonly prisma: PrismaService) {}

  async record(params: {
    tenantId: string;
    caseId?: string;
    userId?: string;
    action: string;
    actorId?: string;
    actorType?: string;
    outcome?: string;
    safeMetadata?: Record<string, any>;
    ipHash?: string;
    requestId?: string;
  }): Promise<void> {
    const safeMeta = params.safeMetadata ? sanitizeMetadata(params.safeMetadata) : {};

    try {
      await (this.prisma as any).complianceAuditLog?.create({
        data: {
          id: randomUUID(),
          tenantId: params.tenantId,
          caseId: params.caseId || null,
          userId: params.userId || null,
          action: params.action,
          actorId: params.actorId || null,
          actorType: params.actorType || 'USER',
          outcome: params.outcome || 'SUCCESS',
          safeMetadata: safeMeta,
          ipHash: params.ipHash || null,
          requestId: params.requestId || null,
          createdAt: new Date(),
        },
      });

      this.logger.log(`Compliance audit recorded action=${params.action} tenant=${params.tenantId} case=${params.caseId || 'none'} actor=${params.actorId || 'system'}`);
    } catch (e: any) {
      this.logger.warn(`Failed to record compliance audit ${params.action}: ${e.message}, fallback to auditLog`);

      try {
        await (this.prisma as any).auditLog?.create({
          data: {
            id: randomUUID(),
            tenantId: params.tenantId,
            actorType: (params.actorType as any) || 'USER',
            actorId: params.actorId || null,
            action: params.action,
            outcome: (params.outcome as any) || 'SUCCESS',
            resourceType: 'ComplianceCase',
            resourceId: params.caseId || params.userId || 'unknown',
            description: `Compliance ${params.action}`,
            metadata: safeMeta,
            ipHash: params.ipHash || null,
            requestId: params.requestId || null,
            createdAt: new Date(),
          },
        });
      } catch (e2: any) {
        this.logger.warn(`Fallback audit also failed: ${e2.message}`);
      }
    }
  }

