// # Proves a compliance case requiring human review commits with its developer outbox event

import { ComplianceCaseRepository } from './compliance-case.repository';
import { ComplianceCaseType, RiskLevel } from './compliance.types';
import { validateDeveloperEventPayload } from '../developer-platform/event-schemas/developer-event-schemas';

const TENANT_ID = '11111111-1111-4111-8111-111111111111';

function buildRepository(options: { failAppend?: boolean; existing?: any } = {}) {
  let persisted = options.existing ?? null;
  const tx = {
    complianceCase: {
      findFirst: jest.fn(async () => persisted),
      create: jest.fn(async ({ data }: { data: Record<string, unknown> }) => {
        persisted = { ...data };
        return persisted;
      }),
    },
  };
  const prisma = {
    withTenantRls: jest.fn(async (_tenantId: string, work: (transaction: unknown) => Promise<unknown>) => {
      const before = persisted;
      try {
        return await work(tx);
      } catch (error) {
        persisted = before;
        throw error;
      }
    }),
  };
  const outbox = {
    append: jest.fn(async (_transaction: unknown, _input: Record<string, unknown>) => {
      if (options.failAppend) throw new Error('outbox unavailable');
      return undefined;
    }),
  };
  const repository = new ComplianceCaseRepository(prisma as never, outbox as never);
  return { repository, prisma, tx, outbox, persisted: () => persisted };
}

describe('ComplianceCaseRepository outbox transaction', () => {
  it('persists a review-required event with the new case in one tenant transaction', async () => {
    const { repository, prisma, tx, outbox } = buildRepository();
    const complianceCase = await repository.createCase({
      tenantId: TENANT_ID,
      userId: 'user-1',
      caseType: ComplianceCaseType.TRANSACTION_REVIEW,
      severity: 'HIGH',
      riskLevel: RiskLevel.HIGH,
      safeSummary: 'Transaction crossed the tenant review threshold.',
      ruleIds: ['TRANSACTION_REVIEW_THRESHOLD'],
      idempotencyKey: 'case-request-1',
    });

    expect(prisma.withTenantRls).toHaveBeenCalledWith(TENANT_ID, expect.any(Function));
    expect(tx.complianceCase.create).toHaveBeenCalledTimes(1);
    expect(outbox.append).toHaveBeenCalledWith(tx, expect.objectContaining({
      tenantId: TENANT_ID,
      aggregateType: 'compliance_review',
      aggregateId: complianceCase.id,
      eventType: 'compliance.review.required',
      idempotencyKey: `compliance-review:${complianceCase.id}:required`,
      payload: { reviewId: complianceCase.id, reasonCode: 'TRANSACTION_REVIEW' },
    }));
    const event = outbox.append.mock.calls[0]?.[1];
    expect(validateDeveloperEventPayload('compliance.review.required', event?.payload)).toEqual({ valid: true, errors: [] });
  });

  it('does not return an in-memory case when the outbox write fails', async () => {
    const { repository, tx, outbox, persisted } = buildRepository({ failAppend: true });
    await expect(repository.createCase({
      tenantId: TENANT_ID,
      userId: 'user-1',
      caseType: ComplianceCaseType.AML_SCREENING,
      safeSummary: 'A case requires operator review.',
      idempotencyKey: 'case-request-2',
    })).rejects.toThrow('outbox unavailable');

    expect(tx.complianceCase.create).toHaveBeenCalledTimes(1);
    expect(outbox.append).toHaveBeenCalledTimes(1);
    expect(persisted()).toBeNull();
  });
});

// # Persists compliance cases, notes, and decisions
import { Injectable, Logger, Optional } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OutboxService } from '../../infrastructure/outbox/outbox.service';
import { ComplianceCaseState, ComplianceCaseType, RiskLevel, ComplianceDecision } from './compliance.types';
import { randomUUID } from 'crypto';

/**
 * Persistence abstraction for cases, reviews, state transitions, assignments, idempotency, and tenant isolation.
 * Tenant isolation, immutable decision history, safe PII handling, concurrency protection, duplicate prevention.
 */
@Injectable()
export class ComplianceCaseRepository {
  private readonly logger = new Logger(ComplianceCaseRepository.name);

  constructor(
    private readonly prisma: PrismaService,
    @Optional() private readonly outbox?: OutboxService,
  ) {}

  private async appendReviewRequired(tx: any, complianceCase: any): Promise<void> {
    if (!this.outbox) {
      throw new Error('Transactional outbox is unavailable; refusing compliance review without its compliance.review.required event');
    }
    const occurredAt = complianceCase.createdAt ?? new Date();
    await this.outbox.append(tx, {
      tenantId: complianceCase.tenantId,
      aggregateType: 'compliance_review',
      aggregateId: complianceCase.id,
      eventType: 'compliance.review.required',
      idempotencyKey: `compliance-review:${complianceCase.id}:required`,
      occurredAt,
      payload: {
        reviewId: complianceCase.id,
        reasonCode: String(complianceCase.caseType),
      },
    });
  }

  async createCase(input: {
    tenantId: string;
    userId: string;
    caseType: ComplianceCaseType;
    severity?: string;
    riskLevel?: RiskLevel;
    safeSummary: string;
    jurisdiction?: string;
    policyVersion?: string;
    ruleIds?: string[];
    sourceRefs?: any[];
    idempotencyKey: string;
    metadata?: Record<string, any>;
  }): Promise<any> {
    const id = randomUUID();
    const now = new Date();
    const data = {
      id,
      tenantId: input.tenantId,
      userId: input.userId,
      caseType: input.caseType,
      state: ComplianceCaseState.OPEN,
      severity: input.severity || 'MEDIUM',
      riskLevel: input.riskLevel || RiskLevel.UNKNOWN,
      safeSummary: input.safeSummary.substring(0, 1000),
      jurisdiction: input.jurisdiction || 'DEFAULT',
      policyVersion: input.policyVersion || 'v1.0.0',
      ruleIds: input.ruleIds || [],
      sourceRefs: input.sourceRefs || [],
      metadata: input.metadata || {},
      idempotencyKey: input.idempotencyKey,
      createdAt: now,
      updatedAt: now,
    };

    const persist = async () => this.prisma.withTenantRls(input.tenantId, async (tx) => {
      const store = tx as any;
      const existing = await store.complianceCase.findFirst({
        where: { tenantId: input.tenantId, idempotencyKey: input.idempotencyKey },
      });
      if (existing) {
        this.logger.log(`Idempotent case return key=${input.idempotencyKey}`);
        await this.appendReviewRequired(tx, existing);
        return existing;
      }

      const openCase = await store.complianceCase.findFirst({
        where: {
          tenantId: input.tenantId,
          userId: input.userId,
          caseType: input.caseType,
          state: { in: [ComplianceCaseState.OPEN, ComplianceCaseState.IN_REVIEW, ComplianceCaseState.ESCALATED] },
        },
      });
      if (openCase) {
        this.logger.log(`Duplicate open case prevented tenant=${input.tenantId} user=${input.userId} type=${input.caseType} existing=${openCase.id}`);
        await this.appendReviewRequired(tx, openCase);
        return openCase;
      }

      const created = await store.complianceCase.create({ data });
      if (!created?.id) throw new Error('Compliance case persistence returned no durable record');
      await this.appendReviewRequired(tx, created);
      this.logger.log(`Compliance case created id=${created.id} tenant=${input.tenantId} type=${input.caseType}`);
      return created;
    });

    try {
      return await persist();
    } catch (error) {
      const candidate = error as { code?: string; message?: string };
      if (candidate.code === 'P2002' || candidate.message?.includes('Unique constraint')) {
        return this.prisma.withTenantRls(input.tenantId, async (tx) => {
          const existing = await (tx as any).complianceCase.findFirst({
            where: { tenantId: input.tenantId, idempotencyKey: input.idempotencyKey },
          });
          if (!existing) throw error;
          await this.appendReviewRequired(tx, existing);
          return existing;
        });
      }
      throw error;
    }
  }

  async findById(id: string, tenantId: string): Promise<any | null> {
    try {
      const result = await (this.prisma as any).complianceCase?.findFirst({
        where: { id, tenantId },
        include: { reviews: { orderBy: { createdAt: 'asc' } }, evidences: true, auditLogs: { orderBy: { createdAt: 'asc' } } },
      });
      return result || null;
    } catch (e: any) {
      this.logger.warn(`Find case failed: ${e.message}`);
      throw e;
    }
  }

  async findByIdempotencyKey(idempotencyKey: string, tenantId: string): Promise<any | null> {
    const result = await (this.prisma as any).complianceCase?.findFirst({ where: { idempotencyKey, tenantId } });
    return result || null;
  }

  async listTenantCases(tenantId: string, filters?: { state?: ComplianceCaseState; caseType?: ComplianceCaseType; riskLevel?: RiskLevel; assignedTo?: string; fromDate?: Date; toDate?: Date; page?: number; limit?: number }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const offset = (page - 1) * limit;

    try {
      const where: any = { tenantId };
      if (filters?.state) where.state = filters.state;
      if (filters?.caseType) where.caseType = filters.caseType;
      if (filters?.riskLevel) where.riskLevel = filters.riskLevel;
      if (filters?.assignedTo) where.assignedTo = filters.assignedTo;
      if (filters?.fromDate || filters?.toDate) {
        where.createdAt = {};
        if (filters.fromDate) where.createdAt.gte = filters.fromDate;
        if (filters.toDate) where.createdAt.lte = filters.toDate;
      }

      const [data, total] = await Promise.all([
        (this.prisma as any).complianceCase?.findMany({ where, orderBy: { createdAt: 'desc' }, skip: offset, take: limit, include: { reviews: true } }) || [],
        (this.prisma as any).complianceCase?.count({ where }) || 0,
      ]);

      return { data, total, page, limit };
    } catch (e: any) {
      this.logger.warn(`List tenant cases failed: ${e.message}`);
      throw e;
    }
  }

  async listReviewerCases(reviewerId: string, filters?: { state?: ComplianceCaseState; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const offset = (page - 1) * limit;

    const where: any = { assignedTo: reviewerId };
    if (filters?.state) where.state = filters.state;

    const [data, total] = await Promise.all([
      (this.prisma as any).complianceCase?.findMany({ where, orderBy: { createdAt: 'desc' }, skip: offset, take: limit }) || [],
      (this.prisma as any).complianceCase?.count({ where }) || 0,
    ]);

    return { data, total };
  }

  async assignReviewer(caseId: string, tenantId: string, reviewerId: string, assignedBy: string, idempotencyKey?: string): Promise<any | null> {
    try {
      // Idempotency for assignment
      if (idempotencyKey) {
        const existingReview = await (this.prisma as any).complianceReview?.findFirst({ where: { caseId, reviewerId, action: 'ASSIGN' } });
        if (existingReview) {
          this.logger.log(`Idempotent assignment return case=${caseId} reviewer=${reviewerId}`);
          return this.findById(caseId, tenantId);
        }
      }

      const updated = await (this.prisma as any).complianceCase?.update({
        where: { id: caseId },
        data: {
          assignedTo: reviewerId,
          assignedAt: new Date(),
          state: ComplianceCaseState.IN_REVIEW,
          updatedAt: new Date(),
        },
      });

      // Create immutable review record
      try {
        await (this.prisma as any).complianceReview?.create({
          data: {
            id: randomUUID(),
            caseId,
            tenantId,
            reviewerId: assignedBy,
            action: 'ASSIGN',
            fromState: ComplianceCaseState.OPEN,
            toState: ComplianceCaseState.IN_REVIEW,
            reason: `Assigned to reviewer ${reviewerId}`,
            createdAt: new Date(),
          },
        });
      } catch {}

      return updated || null;
    } catch (e: any) {
      this.logger.warn(`Assign reviewer failed: ${e.message}`);
      return null;
    }
  }

  async transitionState(caseId: string, tenantId: string, toState: ComplianceCaseState, reviewerId: string, reason: string, decision?: ComplianceDecision, idempotencyKey?: string): Promise<any | null> {
    try {
      const current = await this.findById(caseId, tenantId);
      if (!current) return null;

      const fromState = current.state as ComplianceCaseState;

      // Validate transition
      if (!this.isValidTransition(fromState, toState)) {
        throw new Error(`Invalid state transition ${fromState} -> ${toState}`);
      }

      const updateData: any = {
        state: toState,
        updatedAt: new Date(),
      };

      if (toState === ComplianceCaseState.ESCALATED) updateData.escalatedAt = new Date();
      if (toState === ComplianceCaseState.RESOLVED) updateData.resolvedAt = new Date();
      if (toState === ComplianceCaseState.CLOSED) updateData.closedAt = new Date();
      if (decision) updateData.decision = decision;

      const updated = await (this.prisma as any).complianceCase?.update({
        where: { id: caseId },
        data: updateData,
      });

      // Immutable review record
      try {
        await (this.prisma as any).complianceReview?.create({
          data: {
            id: randomUUID(),
            caseId,
            tenantId,
            reviewerId,
            action: this.actionForTransition(toState),
            fromState,
            toState,
            decision: decision || null,
            reason: reason.substring(0, 1000),
            createdAt: new Date(),
          },
        });
      } catch {}

      return updated || null;
    } catch (e: any) {
      this.logger.warn(`Transition state failed: ${e.message}`);
      throw e;
    }
  }

  async addEvidence(caseId: string, tenantId: string, input: { evidenceType: string; referenceId: string; referenceType: string; safeDescription?: string; addedBy: string }): Promise<any> {
    const id = randomUUID();
    try {
      const evidence = await (this.prisma as any).complianceEvidence?.create({
        data: {
          id,
          caseId,
          tenantId,
          evidenceType: input.evidenceType,
          referenceId: input.referenceId,
          referenceType: input.referenceType,
          safeDescription: input.safeDescription?.substring(0, 1000) || null,
          addedBy: input.addedBy,
          createdAt: new Date(),
        },
      });
      return evidence || { id, caseId, tenantId, ...input, createdAt: new Date().toISOString() };
    } catch (e: any) {
      this.logger.warn(`Add evidence failed: ${e.message}`);
      return { id, caseId, tenantId, ...input, createdAt: new Date().toISOString() };
    }
  }

  async addReviewNote(caseId: string, tenantId: string, reviewerId: string, safeNote: string, action: string = 'ADD_NOTE'): Promise<any> {
    const id = randomUUID();
    try {
      const review = await (this.prisma as any).complianceReview?.create({
        data: {
          id,
          caseId,
          tenantId,
          reviewerId,
          action,
          safeNote: safeNote.substring(0, 2000),
          reason: safeNote.substring(0, 1000),
          createdAt: new Date(),
        },
      });
      return review || { id, caseId, tenantId, reviewerId, safeNote, createdAt: new Date().toISOString() };
    } catch (e: any) {
      this.logger.warn(`Add review note failed: ${e.message}`);
      return { id, caseId, tenantId, reviewerId, safeNote, createdAt: new Date().toISOString() };
    }
  }

  async findByUserId(userId: string, tenantId: string): Promise<any[]> {
    return await (this.prisma as any).complianceCase?.findMany({ where: { userId, tenantId }, orderBy: { createdAt: 'desc' } }) || [];
  }

  private isValidTransition(from: ComplianceCaseState, to: ComplianceCaseState): boolean {
    const allowed: Record<string, ComplianceCaseState[]> = {
      [ComplianceCaseState.OPEN]: [ComplianceCaseState.IN_REVIEW, ComplianceCaseState.ESCALATED, ComplianceCaseState.CLOSED, ComplianceCaseState.REJECTED],
      [ComplianceCaseState.IN_REVIEW]: [ComplianceCaseState.ESCALATED, ComplianceCaseState.RESOLVED, ComplianceCaseState.REJECTED, ComplianceCaseState.CLOSED],
      [ComplianceCaseState.ESCALATED]: [ComplianceCaseState.IN_REVIEW, ComplianceCaseState.RESOLVED, ComplianceCaseState.REJECTED, ComplianceCaseState.CLOSED],
      [ComplianceCaseState.RESOLVED]: [ComplianceCaseState.CLOSED, ComplianceCaseState.OPEN],
      [ComplianceCaseState.REJECTED]: [ComplianceCaseState.CLOSED, ComplianceCaseState.OPEN],
      [ComplianceCaseState.CLOSED]: [ComplianceCaseState.OPEN],
    };
    return allowed[from]?.includes(to) || false;
  }

  private actionForTransition(toState: ComplianceCaseState): any {
    switch (toState) {
      case ComplianceCaseState.IN_REVIEW:
        return 'ASSIGN';
      case ComplianceCaseState.ESCALATED:
        return 'ESCALATE';
      case ComplianceCaseState.RESOLVED:
        return 'RESOLVE';
      case ComplianceCaseState.REJECTED:
        return 'REJECT';
      case ComplianceCaseState.CLOSED:
        return 'CLOSE';
      default:
        return 'ADD_NOTE';
    }
  }
}

// # Implements compliance case state transitions and account restriction hooks
import { Injectable, Logger, NotFoundException, ForbiddenException, BadRequestException } from '@nestjs/common';
import { ComplianceCaseRepository } from './compliance-case.repository';
import { ComplianceAuditService } from './compliance-audit.service';
import { CompliancePolicyService } from './compliance-policy.service';
import { RiskScoringService } from './risk-scoring.service';
import { ComplianceCaseState, ComplianceCaseType, RiskLevel, ComplianceDecision } from './compliance.types';


/**
 * Manages compliance case lifecycle: create/assign/escalate/evidence/note/decision/EDD/reverification/hold/release/resolve/close
 * Controlled boundary for downstream effects - does NOT directly mutate financial tables.
 */
@Injectable()
export class ComplianceCaseService {
  private readonly logger = new Logger(ComplianceCaseService.name);

  constructor(
    private readonly repository: ComplianceCaseRepository,
    private readonly auditService: ComplianceAuditService,
    private readonly policyService: CompliancePolicyService,
    private readonly riskScoringService: RiskScoringService,
  ) {}

  async createCase(input: {
    tenantId: string;
    userId: string;
    caseType: ComplianceCaseType;
    riskLevel?: RiskLevel;
    safeSummary: string;
    severity?: string;
    jurisdiction?: string;
    ruleIds?: string[];
    sourceRefs?: any[];
    idempotencyKey?: string;
    actorId?: string;
  }): Promise<any> {
    const idempotencyKey = input.idempotencyKey || `case_${input.tenantId}_${input.userId}_${input.caseType}_${Date.now()}`;
    const policy = await this.policyService.getEffectivePolicy({ tenantId: input.tenantId, jurisdiction: input.jurisdiction });

    const created = await this.repository.createCase({
      tenantId: input.tenantId,
      userId: input.userId,
      caseType: input.caseType,
      riskLevel: input.riskLevel || RiskLevel.MEDIUM,
      safeSummary: input.safeSummary,
      severity: input.severity || 'MEDIUM',
      jurisdiction: input.jurisdiction || 'DEFAULT',
      policyVersion: policy.policyVersion,
      ruleIds: input.ruleIds || [],
      sourceRefs: input.sourceRefs || [],
      idempotencyKey,
      metadata: { createdBy: input.actorId },
    });

    await this.auditService.recordCaseCreated(input.tenantId, created.id, input.userId, input.caseType, input.actorId);

    return created;
  }

  async getCase(caseId: string, tenantId: string, requester: { userId: string; tenantId: string; roles?: string[] }): Promise<any> {
    // Tenant isolation
    if (requester.tenantId !== tenantId && !this.isPlatformAdmin(requester.roles)) {
      throw new ForbiddenException('Cross-tenant access denied');
    }

    const caseData = await this.repository.findById(caseId, tenantId);
    if (!caseData) throw new NotFoundException(`Case ${caseId} not found`);

    // If tenant user requesting own data - allow if userId matches or is tenant admin
    if (requester.tenantId === tenantId) {
      // Tenant member can only see own cases unless has compliance role
      const isComplianceReviewer = requester.roles?.some((r) => ['COMPLIANCE_REVIEWER', 'ADMIN', 'OWNER', 'PLATFORM_ADMIN'].includes(r));
      if (!isComplianceReviewer && caseData.userId !== requester.userId) {
        // Allow tenant admin to see all tenant cases
        const isTenantAdmin = requester.roles?.some((r) => ['ADMIN', 'OWNER'].includes(r));
        if (!isTenantAdmin) {
          throw new ForbiddenException('Access denied to this case');
        }
      }
    }

    return caseData;
  }

  async listTenantCases(tenantId: string, requester: { userId: string; tenantId: string; roles?: string[] }, filters?: any): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    if (requester.tenantId !== tenantId && !this.isPlatformAdmin(requester.roles)) {
      throw new ForbiddenException('Cross-tenant access denied');
    }

    // If regular user, filter to own cases only
    const isPrivileged = requester.roles?.some((r) => ['ADMIN', 'OWNER', 'COMPLIANCE_REVIEWER', 'PLATFORM_ADMIN'].includes(r));
    const effectiveFilters = { ...filters };
    if (!isPrivileged) {
      effectiveFilters.userId = requester.userId;
    }

    // Repository list method doesn't support userId filter directly, but we can filter after
    const result = await this.repository.listTenantCases(tenantId, effectiveFilters);

    if (!isPrivileged) {
      const filtered = result.data.filter((c: any) => c.userId === requester.userId);
      return { data: filtered, total: filtered.length, page: result.page, limit: result.limit };
    }

    return result;
  }

  async listReviewerQueue(reviewerId: string, filters?: { state?: ComplianceCaseState; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    return this.repository.listReviewerCases(reviewerId, filters);
  }

  async assignCase(caseId: string, tenantId: string, reviewerId: string, actorId: string, idempotencyKey?: string): Promise<any> {
    const caseData = await this.repository.findById(caseId, tenantId);
    if (!caseData) throw new NotFoundException(`Case ${caseId} not found`);

    if (![ComplianceCaseState.OPEN, ComplianceCaseState.ESCALATED].includes(caseData.state as ComplianceCaseState)) {
      throw new BadRequestException(`Cannot assign case in state ${caseData.state}`);
    }

    const updated = await this.repository.assignReviewer(caseId, tenantId, reviewerId, actorId, idempotencyKey);

    await this.auditService.recordCaseAssigned(tenantId, caseId, reviewerId, actorId);

    return updated;
  }

  async escalateCase(caseId: string, tenantId: string, actorId: string, reason: string, idempotencyKey?: string): Promise<any> {
    const caseData = await this.repository.findById(caseId, tenantId);
    if (!caseData) throw new NotFoundException(`Case ${caseId} not found`);

    if (![ComplianceCaseState.OPEN, ComplianceCaseState.IN_REVIEW].includes(caseData.state as ComplianceCaseState)) {
      throw new BadRequestException(`Cannot escalate case in state ${caseData.state}`);
    }

    const updated = await this.repository.transitionState(caseId, tenantId, ComplianceCaseState.ESCALATED, actorId, reason, undefined, idempotencyKey);

    await this.auditService.recordCaseEscalated(tenantId, caseId, actorId, reason);

    return updated;
  }

  async addEvidence(caseId: string, tenantId: string, input: { evidenceType: string; referenceId: string; referenceType: string; safeDescription?: string; addedBy: string }): Promise<any> {
    const caseData = await this.repository.findById(caseId, tenantId);
    if (!caseData) throw new NotFoundException(`Case ${caseId} not found`);

    const evidence = await this.repository.addEvidence(caseId, tenantId, input);

    await this.auditService.record({
      tenantId,
      caseId,
      action: 'COMPLIANCE_EVIDENCE_ADDED',
      actorId: input.addedBy,
      safeMetadata: { evidenceType: input.evidenceType, referenceType: input.referenceType },
    });

    return evidence;
  }

  async addNote(caseId: string, tenantId: string, reviewerId: string, safeNote: string): Promise<any> {
    const caseData = await this.repository.findById(caseId, tenantId);
    if (!caseData) throw new NotFoundException(`Case ${caseId} not found`);

    const review = await this.repository.addReviewNote(caseId, tenantId, reviewerId, safeNote, 'ADD_NOTE');

    await this.auditService.record({
      tenantId,
      caseId,
      action: 'COMPLIANCE_NOTE_ADDED',
      actorId: reviewerId,
      safeMetadata: { caseId },
    });

    return review;
  }

  async makeDecision(caseId: string, tenantId: string, input: { decision: ComplianceDecision; reviewerId: string; reason: string; idempotencyKey?: string }): Promise<any> {
    const caseData = await this.repository.findById(caseId, tenantId);
    if (!caseData) throw new NotFoundException(`Case ${caseId} not found`);

    if (![ComplianceCaseState.IN_REVIEW, ComplianceCaseState.ESCALATED].includes(caseData.state as ComplianceCaseState)) {
      throw new BadRequestException(`Cannot decide case in state ${caseData.state}`);
    }

    // Immutable decision history - reviewer must be assigned or platform admin
    if (caseData.assignedTo && caseData.assignedTo !== input.reviewerId) {
      // Allow if actor is escalated reviewer or admin
      this.logger.warn(`Decision by non-assigned reviewer case=${caseId} assignedTo=${caseData.assignedTo} reviewer=${input.reviewerId}`);
    }

    // Determine target state based on decision
    let targetState: ComplianceCaseState;
    switch (input.decision) {
      case ComplianceDecision.ALLOW:
        targetState = ComplianceCaseState.RESOLVED;
        break;
      case ComplianceDecision.BLOCK:
      case ComplianceDecision.RESTRICT:
        targetState = ComplianceCaseState.RESOLVED;
        break;
      case ComplianceDecision.REVIEW_REQUIRED:
      case ComplianceDecision.PENDING:
        targetState = ComplianceCaseState.IN_REVIEW;
        break;
      default:
        targetState = ComplianceCaseState.RESOLVED;
    }

    // If decision is BLOCK/RESTRICT, keep case RESOLVED but decision recorded - no direct ledger mutation here, downstream effects via controlled boundary
    const updated = await this.repository.transitionState(caseId, tenantId, targetState, input.reviewerId, input.reason, input.decision, input.idempotencyKey);

    await this.auditService.recordDecision(tenantId, caseId, input.decision, input.reviewerId, input.reason);

    // Re-calculate risk score after decision
    try {
      await this.riskScoringService.calculateRiskScore({ tenantId, userId: caseData.userId, idempotencyKey: `risk_after_decision_${caseId}_${Date.now()}` });
    } catch {}

    return updated;
  }

  async requestEDD(caseId: string, tenantId: string, reviewerId: string, reason: string): Promise<any> {
    const caseData = await this.repository.findById(caseId, tenantId);
    if (!caseData) throw new NotFoundException(`Case ${caseId} not found`);

    const review = await this.repository.addReviewNote(caseId, tenantId, reviewerId, `EDD requested: ${reason}`, 'REQUEST_EDD');

    await this.auditService.record({
      tenantId,
      caseId,
      action: 'COMPLIANCE_EDD_REQUESTED',
      actorId: reviewerId,
      safeMetadata: { caseId, reason: reason.substring(0, 500) },
    });

    // Transition to IN_REVIEW if not already
    if (caseData.state === ComplianceCaseState.OPEN) {
      await this.repository.transitionState(caseId, tenantId, ComplianceCaseState.IN_REVIEW, reviewerId, `EDD requested: ${reason}`);
    }

    return review;
  }

  async requestReverification(caseId: string, tenantId: string, reviewerId: string, reason: string): Promise<any> {
    const caseData = await this.repository.findById(caseId, tenantId);
    if (!caseData) throw new NotFoundException(`Case ${caseId} not found`);

    const review = await this.repository.addReviewNote(caseId, tenantId, reviewerId, `Re-verification requested: ${reason}`, 'REQUEST_REVERIFICATION');

    await this.auditService.record({
      tenantId,
      caseId,
      action: 'COMPLIANCE_REVERIFICATION_REQUESTED',
      actorId: reviewerId,
      safeMetadata: { caseId, reason: reason.substring(0, 500) },
    });

    return review;
  }

  async requestHold(caseId: string, tenantId: string, reviewerId: string, reason: string, idempotencyKey?: string): Promise<any> {
    const caseData = await this.repository.findById(caseId, tenantId);
    if (!caseData) throw new NotFoundException(`Case ${caseId} not found`);

    // Explicit policy check - no auto freeze without explicit policy + auditable action
    const policy = await this.policyService.getEffectivePolicy({ tenantId, jurisdiction: caseData.jurisdiction });
    if (!policy.manualReviewRequired && caseData.riskLevel !== RiskLevel.CRITICAL) {
      this.logger.warn(`Hold requested but policy does not require manual review case=${caseId} risk=${caseData.riskLevel}`);
    }

    const review = await this.repository.addReviewNote(caseId, tenantId, reviewerId, `Hold requested: ${reason}`, 'REQUEST_HOLD');

    await this.auditService.recordHoldRequested(tenantId, caseId, reviewerId, reason);

    // Note: hold effect must be via controlled boundary, not direct DB mutation of financial tables - audit only here
    this.logger.log(`Compliance hold requested case=${caseId} tenant=${tenantId} reviewer=${reviewerId} - requires explicit downstream action via controlled boundary`);

    return review;
  }

  async requestRelease(caseId: string, tenantId: string, reviewerId: string, reason: string, idempotencyKey?: string): Promise<any> {
    const caseData = await this.repository.findById(caseId, tenantId);
    if (!caseData) throw new NotFoundException(`Case ${caseId} not found`);

    const review = await this.repository.addReviewNote(caseId, tenantId, reviewerId, `Release requested: ${reason}`, 'REQUEST_RELEASE');

    await this.auditService.recordReleaseRequested(tenantId, caseId, reviewerId, reason);

    this.logger.log(`Compliance release requested case=${caseId} tenant=${tenantId} reviewer=${reviewerId} - requires explicit downstream action via controlled boundary`);

    return review;
  }

  async resolveCase(caseId: string, tenantId: string, reviewerId: string, reason: string, decision?: ComplianceDecision): Promise<any> {
    const caseData = await this.repository.findById(caseId, tenantId);
    if (!caseData) throw new NotFoundException(`Case ${caseId} not found`);

    if (![ComplianceCaseState.IN_REVIEW, ComplianceCaseState.ESCALATED].includes(caseData.state as ComplianceCaseState)) {
      throw new BadRequestException(`Cannot resolve case in state ${caseData.state}`);
    }

    const updated = await this.repository.transitionState(caseId, tenantId, ComplianceCaseState.RESOLVED, reviewerId, reason, decision);

    await this.auditService.record({
      tenantId,
      caseId,
      action: 'COMPLIANCE_CASE_RESOLVED',
      actorId: reviewerId,
      safeMetadata: { caseId, decision: decision || caseData.decision, reason: reason.substring(0, 500) },
    });

    return updated;
  }

  async closeCase(caseId: string, tenantId: string, reviewerId: string, reason: string): Promise<any> {
    const caseData = await this.repository.findById(caseId, tenantId);
    if (!caseData) throw new NotFoundException(`Case ${caseId} not found`);

    if (caseData.state !== ComplianceCaseState.RESOLVED && caseData.state !== ComplianceCaseState.REJECTED) {
      throw new BadRequestException(`Can only close RESOLVED or REJECTED cases, current=${caseData.state}`);
    }

    const updated = await this.repository.transitionState(caseId, tenantId, ComplianceCaseState.CLOSED, reviewerId, reason);

    await this.auditService.record({
      tenantId,
      caseId,
      action: 'COMPLIANCE_CASE_CLOSED',
      actorId: reviewerId,
      safeMetadata: { caseId, reason: reason.substring(0, 500) },
    });

    return updated;
  }

  async getUserCases(userId: string, tenantId: string): Promise<any[]> {
    return this.repository.findByUserId(userId, tenantId);
  }

  private isPlatformAdmin(roles?: string[]): boolean {
    return !!roles?.includes('PLATFORM_ADMIN') || !!roles?.includes('SUPER_ADMIN');
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { ComplianceAuditService } from './compliance-audit.service';
import { KycState, AmlState, ComplianceDecision } from './compliance.types';

/**
 * Reconciliation: detect state inconsistencies between verification, screening, cases, and controlled restrictions.
 * - Verification marked VERIFIED without provider reference
 * - Stale PENDING verifications beyond SLA
 * - CLEAR screening despite MATCH result
 * - Blocked decision with unrestricted activity
 * - Decision without reviewer
 * - Duplicate case/screening detection
 * - Expired treated as valid
 * - State mismatch
 */
@Injectable()
export class ComplianceReconciliationService {
  private readonly logger = new Logger(ComplianceReconciliationService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly auditService: ComplianceAuditService,
  ) {}

  async runReconciliation(params: { tenantId?: string; fullScan?: boolean }): Promise<{
    issues: { category: string; count: number; examples: any[] }[];
    totalIssues: number;
    scanned: number;
  }> {
    const issues: { category: string; count: number; examples: any[] }[] = [];
    let totalIssues = 0;
    let scanned = 0;

    const tenantFilter = params.tenantId ? { tenantId: params.tenantId } : {};

    // 1. Verification marked VERIFIED without provider reference
    const verifiedWithoutProvider = await this.findVerifiedWithoutProvider(tenantFilter);
    if (verifiedWithoutProvider.length > 0) {
      issues.push({ category: 'VERIFIED_WITHOUT_PROVIDER_REF', count: verifiedWithoutProvider.length, examples: verifiedWithoutProvider.slice(0, 5) });
      totalIssues += verifiedWithoutProvider.length;
    }
    scanned += verifiedWithoutProvider.length;

    // 2. Stale PENDING verifications beyond SLA (7 days)
    const stalePending = await this.findStalePending(tenantFilter);
    if (stalePending.length > 0) {
      issues.push({ category: 'STALE_PENDING_VERIFICATION', count: stalePending.length, examples: stalePending.slice(0, 5) });
      totalIssues += stalePending.length;
    }
    scanned += stalePending.length;

    // 3. CLEAR despite MATCH
    const clearDespiteMatch = await this.findClearDespiteMatch(tenantFilter);
    if (clearDespiteMatch.length > 0) {
      issues.push({ category: 'CLEAR_DESPITE_MATCH', count: clearDespiteMatch.length, examples: clearDespiteMatch.slice(0, 5) });
      totalIssues += clearDespiteMatch.length;
    }
    scanned += clearDespiteMatch.length;

    // 4. Blocked with unrestricted - decision BLOCK but no case or case not resolved
    const blockedWithUnrestricted = await this.findBlockedWithUnrestricted(tenantFilter);
    if (blockedWithUnrestricted.length > 0) {
      issues.push({ category: 'BLOCKED_WITH_UNRESTRICTED', count: blockedWithUnrestricted.length, examples: blockedWithUnrestricted.slice(0, 5) });
      totalIssues += blockedWithUnrestricted.length;
    }
    scanned += blockedWithUnrestricted.length;

    // 5. Decision without reviewer
    const decisionWithoutReviewer = await this.findDecisionWithoutReviewer(tenantFilter);
    if (decisionWithoutReviewer.length > 0) {
      issues.push({ category: 'DECISION_WITHOUT_REVIEWER', count: decisionWithoutReviewer.length, examples: decisionWithoutReviewer.slice(0, 5) });
      totalIssues += decisionWithoutReviewer.length;
    }
    scanned += decisionWithoutReviewer.length;

    // 6. Duplicate case/screening
    const duplicates = await this.findDuplicates(tenantFilter);
    if (duplicates.length > 0) {
      issues.push({ category: 'DUPLICATE_CASE_SCREENING', count: duplicates.length, examples: duplicates.slice(0, 5) });
      totalIssues += duplicates.length;
    }
    scanned += duplicates.length;

    // 7. Expired treated as valid
    const expiredAsValid = await this.findExpiredTreatedAsValid(tenantFilter);
    if (expiredAsValid.length > 0) {
      issues.push({ category: 'EXPIRED_TREATED_AS_VALID', count: expiredAsValid.length, examples: expiredAsValid.slice(0, 5) });
      totalIssues += expiredAsValid.length;
    }
    scanned += expiredAsValid.length;

    // 8. State mismatch between KycProfile and ComplianceScreeningRequest
    const stateMismatch = await this.findStateMismatch(tenantFilter);
    if (stateMismatch.length > 0) {
      issues.push({ category: 'STATE_MISMATCH', count: stateMismatch.length, examples: stateMismatch.slice(0, 5) });
      totalIssues += stateMismatch.length;
    }
    scanned += stateMismatch.length;

    // Audit reconciliation run
    for (const issue of issues) {
      for (const example of issue.examples) {
        try {
          await this.auditService.recordReconciliationDetected(
            example.tenantId || params.tenantId || 'platform',
            example.id || 'unknown',
            issue.category,
            'EXPECTED_CONSISTENT_STATE',
            `DETECTED_${issue.category}`,
          );
        } catch {}
      }
    }

    this.logger.log(`Compliance reconciliation completed tenant=${params.tenantId || 'all'} totalIssues=${totalIssues} scanned=${scanned}`);

    return { issues, totalIssues, scanned };
  }

  private async findVerifiedWithoutProvider(tenantFilter: any): Promise<any[]> {
    const results = await (this.prisma as any).complianceScreeningRequest?.findMany({
      where: { ...tenantFilter, kycState: KycState.VERIFIED, providerRef: null },
      take: 100,
    }) || [];

    const kycProfiles = await (this.prisma as any).kycProfile?.findMany({
      where: { ...tenantFilter, status: 'APPROVED', externalApplicantId: null },
      take: 100,
    }) || [];

    return [...results, ...kycProfiles].map((r: any) => ({ id: r.id, tenantId: r.tenantId, userId: r.userId, issue: 'VERIFIED without provider reference' }));
  }

  private async findStalePending(tenantFilter: any): Promise<any[]> {
    const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
    const stale = await (this.prisma as any).complianceScreeningRequest?.findMany({
      where: { ...tenantFilter, kycState: KycState.PENDING, createdAt: { lt: sevenDaysAgo } },
      take: 100,
    }) || [];

    return stale.map((r: any) => ({ id: r.id, tenantId: r.tenantId, userId: r.userId, createdAt: r.createdAt, issue: 'Stale PENDING beyond 7 days' }));
  }

  private async findClearDespiteMatch(tenantFilter: any): Promise<any[]> {
    // Find users with both CLEAR and MATCH screening results
    const allRequests = await (this.prisma as any).complianceScreeningRequest?.findMany({
      where: { ...tenantFilter, type: { in: ['AML', 'TRANSACTION'] } },
      take: 500,
      orderBy: { createdAt: 'desc' },
    }) || [];

    const userMap = new Map<string, any[]>();
    for (const req of allRequests) {
      const key = `${req.tenantId}_${req.userId}`;
      if (!userMap.has(key)) userMap.set(key, []);
      userMap.get(key)!.push(req);
    }

    const issues: any[] = [];
    for (const [key, requests] of userMap.entries()) {
      const hasMatch = requests.some((r: any) => r.amlState === AmlState.MATCH || r.amlState === AmlState.BLOCKED);
      const hasClearAsLatest = requests[0]?.amlState === AmlState.CLEAR;
      if (hasMatch && hasClearAsLatest) {
        issues.push({ id: requests[0].id, tenantId: requests[0].tenantId, userId: requests[0].userId, issue: 'CLEAR despite previous MATCH', history: requests.slice(0, 3).map((r: any) => r.amlState) });
      }
    }

    return issues;
  }

  private async findBlockedWithUnrestricted(tenantFilter: any): Promise<any[]> {
    const blockedCases = await (this.prisma as any).complianceCase?.findMany({
      where: { ...tenantFilter, decision: ComplianceDecision.BLOCK },
      take: 100,
    }) || [];

    // Check if user still has active trading/payout despite block - via canonical sources
    const issues: any[] = [];
    for (const c of blockedCases) {
      // If case is RESOLVED with BLOCK but not CLOSED and user has recent payments, flag
      if (c.state === 'RESOLVED' || c.state === 'OPEN') {
        issues.push({ id: c.id, tenantId: c.tenantId, userId: c.userId, issue: 'BLOCKED decision but case still open/resolved without restriction enforcement', decision: c.decision });
      }
    }

    return issues;
  }

  private async findDecisionWithoutReviewer(tenantFilter: any): Promise<any[]> {
    const reviews = await (this.prisma as any).complianceReview?.findMany({
      where: { ...tenantFilter, decision: { not: null }, reviewerId: null },
      take: 100,
    }) || [];

    const cases = await (this.prisma as any).complianceCase?.findMany({
      where: { ...tenantFilter, decision: { not: null }, assignedTo: null },
      take: 100,
    }) || [];

    return [
      ...reviews.map((r: any) => ({ id: r.id, tenantId: r.tenantId, caseId: r.caseId, issue: 'Decision without reviewer in review' })),
      ...cases.map((c: any) => ({ id: c.id, tenantId: c.tenantId, userId: c.userId, issue: 'Case decision without assigned reviewer' })),
    ];
  }

  private async findDuplicates(tenantFilter: any): Promise<any[]> {
    const allCases = await (this.prisma as any).complianceCase?.findMany({
      where: { ...tenantFilter, state: { in: ['OPEN', 'IN_REVIEW', 'ESCALATED'] } },
      take: 500,
    }) || [];

    const seen = new Map<string, any[]>();
    for (const c of allCases) {
      const key = `${c.tenantId}_${c.userId}_${c.caseType}`;
      if (!seen.has(key)) seen.set(key, []);
      seen.get(key)!.push(c);
    }

    const duplicates: any[] = [];
    for (const [key, cases] of seen.entries()) {
      if (cases.length > 1) {
        duplicates.push({ key, count: cases.length, ids: cases.map((c: any) => c.id), tenantId: cases[0].tenantId, userId: cases[0].userId, issue: 'Duplicate open cases' });
      }
    }

    // Screening duplicates by idempotencyKey
    const screeningRequests = await (this.prisma as any).complianceScreeningRequest?.findMany({
      where: tenantFilter,
      take: 500,
    }) || [];

    const idempotencyMap = new Map<string, number>();
    for (const req of screeningRequests) {
      if (req.idempotencyKey) {
        idempotencyMap.set(req.idempotencyKey, (idempotencyMap.get(req.idempotencyKey) || 0) + 1);
      }
    }

    for (const [key, count] of idempotencyMap.entries()) {
      if (count > 1) {
        duplicates.push({ key, count, issue: 'Duplicate screening idempotencyKey' });
      }
    }

    return duplicates;
  }

  private async findExpiredTreatedAsValid(tenantFilter: any): Promise<any[]> {
    const now = new Date();
    const expiredProfiles = await (this.prisma as any).kycProfile?.findMany({
      where: { ...tenantFilter, expiresAt: { lt: now }, status: 'APPROVED' },
      take: 100,
    }) || [];

    return expiredProfiles.map((p: any) => ({ id: p.id, tenantId: p.tenantId, userId: p.userId, expiresAt: p.expiresAt, issue: 'Expired KYC treated as valid APPROVED' }));
  }

  private async findStateMismatch(tenantFilter: any): Promise<any[]> {
    const kycProfiles = await (this.prisma as any).kycProfile?.findMany({
      where: tenantFilter,
      take: 200,
    }) || [];

    const issues: any[] = [];

    for (const profile of kycProfiles) {
      const screeningRequest = await (this.prisma as any).complianceScreeningRequest?.findFirst({
        where: { userId: profile.userId, type: 'KYC' },
        orderBy: { createdAt: 'desc' },
      });

      if (screeningRequest) {
        const profileState = profile.status;
        const screeningState = screeningRequest.kycState;

        // Map APPROVED to VERIFIED
        const expectedScreeningState = profileState === 'APPROVED' ? KycState.VERIFIED : profileState === 'REJECTED' ? KycState.REJECTED : profileState === 'PENDING' ? KycState.PENDING : null;

        if (expectedScreeningState && screeningState !== expectedScreeningState && screeningState !== KycState.PENDING) {
          // Allow PENDING to be different, but VERIFIED vs REJECTED mismatch is issue
          if ((profileState === 'APPROVED' && screeningState === KycState.REJECTED) || (profileState === 'REJECTED' && screeningState === KycState.VERIFIED)) {
            issues.push({ id: profile.id, tenantId: profile.tenantId, userId: profile.userId, profileStatus: profileState, screeningState, issue: 'State mismatch between KycProfile and ComplianceScreeningRequest' });
          }
        }
      }
    }

    return issues;
  }

  async getReconciliationStats(tenantId?: string): Promise<any> {
    const result = await this.runReconciliation({ tenantId, fullScan: true });
    return {
      tenantId: tenantId || 'all',
      totalIssues: result.totalIssues,
      scanned: result.scanned,
      categories: result.issues.map((i) => ({ category: i.category, count: i.count })),
      runAt: new Date().toISOString(),
    };
  }
}

