  // ===== Risk Scoring =====

  @Post('risk/calculate')
  @RequirePermissions(Permission.COMPLIANCE_READ, Permission.RISK_READ, Permission.PLATFORM_MANAGE)
  async calculateRisk(@Body() dto: CalculateRiskScoreDto, @CurrentTenant() tenant: any) {
