// # Resolves effective copy policy across platform, tenant, strategy, and follower subscription scopes without weakening safety rules
// # Resolves effective slippage tolerance and execution delay without weakening higher-level caps
// # Resolves stop-copy, TP/SL, and trailing stop policy parameters
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import {
  CopyPolicy,
  CopySizingMode,
  CopyStopExecutionPlan,
  compareDecimalStrings,
  isDecimalString,
  matchesSymbolRule,
} from './copy-trading.types';
import { Decimal, decimalFromScaled12, parseDecimalString } from '../../common/decimal-string';

/**
 * Whether adverse slippage was actually measured, stated explicitly because `slippageBps: null`
 * alone conflates two different situations: a movement too small to round to a displayed number,
 * and a movement nobody has taken yet. The copy record carries whichever it is.
 */
export type SlippageMeasurementState = 'MEASURED' | 'NOT_YET_MEASURED' | 'UNMEASURABLE';

/**
 * Resolves effective copy settings: proportional sizing, fixed sizing, symbol filters, max concurrent copies, slippage tolerance, delay, notional caps, and risk controls.
 * Policy precedence: Platform → Tenant → Trader Strategy → Follower Subscription. Lower-level must never weaken mandatory higher-level safety rule.
 */
@Injectable()
export class CopyPolicyService {
  private readonly logger = new Logger(CopyPolicyService.name);

  // Platform-level mandatory safety rules - never weakened
  private readonly platformPolicy: CopyPolicy = {
    sizingMode: CopySizingMode.PROPORTIONAL,
    proportionalRatio: null,
    fixedQuantity: null,
    fixedNotional: null,
    maxOrderNotional: '100000', // Platform cap 100k
    maxDailyNotional: '500000', // Platform cap 500k
    maxConcurrentCopies: 20,
    slippageToleranceBps: 100, // 1% max slippage at platform level
    executionDelayMs: 0,
    allowedSymbols: null,
    blockedSymbols: ['*WITHDRAWAL*'], // Never allow withdrawal symbols
    allowedSides: ['BUY', 'SELL'],
    leveragePolicy: 'SPOT_ONLY',
    maxLeverage: '10',
    marginMode: 'SPOT',
    reduceOnly: null,
    takeProfitBps: null,
    stopLossBps: null,
    trailingStopBps: null,
    stopCopyConditions: null,
  };

  constructor(private readonly prisma: PrismaService) {}

  async getPlatformPolicy(): Promise<CopyPolicy> {
    return this.platformPolicy;
  }

  // The three lookups below let errors propagate. Lower levels may only
  // tighten the policy, so silently dropping a level on a database error (as
  // they used to, returning null) produced a LOOSER effective policy - e.g.
  // tenant-blocked symbols or the follower's max notional disappeared. The
  // copy engine skips the subscription when resolution fails (no order).

  async getTenantPolicy(tenantId: string): Promise<CopyPolicy | null> {
    const setting = await this.prisma.tenantSetting.findFirst({ where: { tenantId, key: 'copy_trading_policy' } });
    if (setting && setting.value) {
      return setting.value as any as CopyPolicy;
    }
    return null;
  }

  /**
   * `tenantId` scopes the lookup; resolveEffectivePolicy always passes it, so
   * GET copy-trading/policies/effective cannot read another tenant's
   * strategy or subscription policy by id.
   */
  async getTraderStrategyPolicy(strategyId: string, tenantId?: string): Promise<CopyPolicy | null> {
    const strategy = await this.prisma.traderStrategy.findFirst({
      where: { id: strategyId, ...(tenantId ? { tenantId } : {}) },
      select: { riskProfile: true, strategyConfig: true, supportedSymbols: true },
    });
    if (!strategy || !strategy.riskProfile) return null;
    const risk = (strategy.riskProfile ?? {}) as Record<string, any>;
    const config = (strategy.strategyConfig ?? {}) as Record<string, any>;
    // Extract copy policy from riskProfile or strategyConfig
    return {
      sizingMode: config.sizingMode || CopySizingMode.PROPORTIONAL,
      proportionalRatio: config.proportionalRatio || null,
      fixedQuantity: config.fixedQuantity || null,
      fixedNotional: config.fixedNotional || null,
      maxOrderNotional: risk.maxOrderNotional || null,
      maxDailyNotional: risk.maxDailyNotional || null,
      maxConcurrentCopies: risk.maxConcurrentCopies || null,
      slippageToleranceBps: config.slippageToleranceBps ?? null,
      executionDelayMs: config.executionDelayMs ?? null,
      allowedSymbols: strategy.supportedSymbols || null,
      blockedSymbols: risk.blockedSymbols || null,
      allowedSides: config.allowedSides || null,
      leveragePolicy: risk.leveragePolicy || config.leveragePolicy || null,
      maxLeverage: risk.maxLeverage || config.maxLeverage || null,
      marginMode: risk.marginMode || config.marginMode || null,
      reduceOnly: config.reduceOnly ?? null,
      takeProfitBps: config.takeProfitBps ?? risk.takeProfitBps ?? null,
      stopLossBps: config.stopLossBps ?? risk.stopLossBps ?? null,
      trailingStopBps: config.trailingStopBps ?? risk.trailingStopBps ?? null,
      stopCopyConditions: risk.stopCopyConditions || config.stopCopyConditions || null,
    };
  }

  async getSubscriptionPolicy(subscriptionId: string, tenantId?: string): Promise<CopyPolicy | null> {
    const sub = await this.prisma.copySubscription.findFirst({ where: { id: subscriptionId, ...(tenantId ? { tenantId } : {}) } });
    if (sub && sub.copyPolicy) {
      return sub.copyPolicy as unknown as CopyPolicy;
    }
    return null;
  }

  async resolveEffectivePolicy(input: { tenantId: string; strategyId?: string; subscriptionId?: string }): Promise<CopyPolicy> {
    const platform = await this.getPlatformPolicy();
    const tenant = await this.getTenantPolicy(input.tenantId);
    const strategy = input.strategyId ? await this.getTraderStrategyPolicy(input.strategyId, input.tenantId) : null;
    const subscription = input.subscriptionId ? await this.getSubscriptionPolicy(input.subscriptionId, input.tenantId) : null;

    // Precedence: Platform → Tenant → Trader Strategy → Follower Subscription
    // Lower-level must never weaken mandatory higher-level safety rule

    let effective: CopyPolicy = { ...platform };

    const merge = (base: CopyPolicy, override: CopyPolicy | null): CopyPolicy => {
      if (!override) return base;
      const merged: CopyPolicy = { ...base };

      // Sizing mode - lower can override
      if (override.sizingMode) merged.sizingMode = override.sizingMode;
      if (override.proportionalRatio) merged.proportionalRatio = override.proportionalRatio;
      if (override.fixedQuantity) merged.fixedQuantity = override.fixedQuantity;
      if (override.fixedNotional) merged.fixedNotional = override.fixedNotional;

      // Notional caps - lower cannot weaken higher (must be <= higher).
      //
      // Compared as exact decimals. These are money ceilings: deciding with a float means two
      // nearly-equal limits can order differently than they read, and an unparseable override would
      // be a silently-kept base. An override that cannot be parsed is treated as unweakenable too -
      // it is not evidence that the ceiling is safe to move.
      if (override.maxOrderNotional) {
        const baseNotional = Decimal.tryParse(base.maxOrderNotional ?? '1000000') ?? Decimal.parse('1000000');
        const overrideNotional = Decimal.tryParse(override.maxOrderNotional);
        if (!overrideNotional || overrideNotional.gt(baseNotional)) {
          this.logger.warn(`Policy override attempts to weaken maxOrderNotional base=${baseNotional.toString()} override=${override.maxOrderNotional} - keeping base`);
        } else {
          merged.maxOrderNotional = override.maxOrderNotional;
        }
      }

      if (override.maxDailyNotional) {
        const baseDaily = Decimal.tryParse(base.maxDailyNotional ?? '1000000') ?? Decimal.parse('1000000');
        const overrideDaily = Decimal.tryParse(override.maxDailyNotional);
        if (!overrideDaily || overrideDaily.gt(baseDaily)) {
          this.logger.warn(`Policy override attempts to weaken maxDailyNotional base=${baseDaily.toString()} override=${override.maxDailyNotional} - keeping base`);
        } else {
          merged.maxDailyNotional = override.maxDailyNotional;
        }
      }

      if (override.maxConcurrentCopies !== null && override.maxConcurrentCopies !== undefined) {
        const baseVal = base.maxConcurrentCopies || 100;
        if (override.maxConcurrentCopies > baseVal) {
          this.logger.warn(`Policy override attempts to weaken maxConcurrentCopies base=${baseVal} override=${override.maxConcurrentCopies}`);
        } else {
          merged.maxConcurrentCopies = override.maxConcurrentCopies;
        }
      }

      if (override.slippageToleranceBps !== null && override.slippageToleranceBps !== undefined) {
        const baseVal = base.slippageToleranceBps ?? 100;
        if (override.slippageToleranceBps > baseVal || override.slippageToleranceBps < 0) {
          this.logger.warn(`Policy override attempts to weaken slippageTolerance base=${baseVal} override=${override.slippageToleranceBps}`);
        } else {
          merged.slippageToleranceBps = override.slippageToleranceBps;
        }
      }

      // Execution delay: lower level cannot set a negative delay or reduce below a higher-level mandatory floor, and is capped at 60,000ms
      if (override.executionDelayMs !== null && override.executionDelayMs !== undefined) {
        const baseDelay = base.executionDelayMs ?? 0;
        if (override.executionDelayMs < baseDelay) {
          this.logger.warn(`Policy override attempts to reduce executionDelayMs below base=${baseDelay} override=${override.executionDelayMs}`);
        } else {
          merged.executionDelayMs = Math.min(60000, Math.max(baseDelay, override.executionDelayMs));
        }
      }

      // Symbol filters - intersection logic: allowed = intersection of all allowed, blocked = union of all blocked
      if (override.allowedSymbols) {
        if (base.allowedSymbols) {
          merged.allowedSymbols = base.allowedSymbols.filter((s) => override.allowedSymbols!.includes(s));
        } else {
          merged.allowedSymbols = override.allowedSymbols;
        }
      }

      if (override.blockedSymbols) {
        const baseBlocked = base.blockedSymbols || [];
        merged.blockedSymbols = Array.from(new Set([...baseBlocked, ...override.blockedSymbols]));
      }

      if (override.allowedSides) {
        if (base.allowedSides) {
          merged.allowedSides = base.allowedSides.filter((s) => override.allowedSides!.includes(s));
        } else {
          merged.allowedSides = override.allowedSides;
        }
      }

      // Leverage & Margin constraints: lower level cannot exceed higher-level maxLeverage or weaken SPOT_ONLY
      if (override.leveragePolicy) {
        // Both branches of the original condition assigned the same value, so it was dead code
        // dressed as a rule. The rule that matters: SPOT_ONLY stays SPOT_ONLY unless a leverage
        // limit above 1 is actually supplied, and `maxLeverage` may not exceed the level it is
        // overriding.
        const suppliedLeverage = Decimal.tryParse(override.maxLeverage ?? '') ?? Decimal.ZERO;
        merged.leveragePolicy =
          base.leveragePolicy === 'SPOT_ONLY' &&
          override.leveragePolicy !== 'SPOT_ONLY' &&
          suppliedLeverage.lte(Decimal.ONE)
            ? base.leveragePolicy
            : override.leveragePolicy;
      }

      if (override.maxLeverage) {
        const baseMaxLev = Decimal.tryParse(base.maxLeverage ?? '10') ?? Decimal.parse('10');
        const overrideLev = Decimal.tryParse(override.maxLeverage);
        if (!overrideLev || !overrideLev.isPositive()) {
          // An unreadable or non-positive leverage limit is not a limit. Keep the base ceiling and
          // say so, rather than recording a value the venue would reject or read as unlimited.
          this.logger.warn(`Policy override carries an unusable maxLeverage override=${override.maxLeverage} - keeping base=${baseMaxLev.toString()}`);
        } else if (overrideLev.gt(baseMaxLev)) {
          this.logger.warn(`Policy override attempts to weaken maxLeverage base=${baseMaxLev.toString()} override=${overrideLev.toString()}`);
        } else {
          merged.maxLeverage = override.maxLeverage;
        }
      }

      if (override.marginMode) {
        merged.marginMode = override.marginMode;
      }

      if (override.reduceOnly !== null && override.reduceOnly !== undefined) {
        merged.reduceOnly = base.reduceOnly === true ? true : override.reduceOnly;
      }

      // TP/SL and trailing stop parameters: tighter stop-loss / trailing-stop (smaller bps) from higher level cannot be loosened
      if (override.takeProfitBps !== null && override.takeProfitBps !== undefined && override.takeProfitBps > 0) {
        merged.takeProfitBps = override.takeProfitBps;
      }

      if (override.stopLossBps !== null && override.stopLossBps !== undefined && override.stopLossBps > 0) {
        if (base.stopLossBps && override.stopLossBps > base.stopLossBps) {
          this.logger.warn(`Policy override attempts to loosen stopLossBps base=${base.stopLossBps} override=${override.stopLossBps}`);
        } else {
          merged.stopLossBps = override.stopLossBps;
        }
      }

      if (override.trailingStopBps !== null && override.trailingStopBps !== undefined && override.trailingStopBps > 0) {
        if (base.trailingStopBps && override.trailingStopBps > base.trailingStopBps) {
          this.logger.warn(`Policy override attempts to loosen trailingStopBps base=${base.trailingStopBps} override=${override.trailingStopBps}`);
        } else {
          merged.trailingStopBps = override.trailingStopBps;
        }
      }

      if (override.stopCopyConditions) {
        merged.stopCopyConditions = {
          ...(base.stopCopyConditions ?? {}),
          ...override.stopCopyConditions,
        };
      }

      return merged;
    };

    effective = merge(effective, tenant);
    effective = merge(effective, strategy);
    effective = merge(effective, subscription);

    this.logger.log(`Effective copy policy resolved tenant=${input.tenantId} strategy=${input.strategyId} subscription=${input.subscriptionId} maxNotional=${effective.maxOrderNotional} slippage=${effective.slippageToleranceBps}`);

    return effective;
  }

  /**
   * Evaluates slippage tolerance and execution delay deterministically for a copy execution.
   */
  evaluateSlippageAndDelay(input: {
    policy: CopyPolicy;
    leaderPrice: string | null;
    executionPrice?: string | null;
    side: string;
    leaderTimestamp?: string | null;
    nowMs?: number;
  }): {
    allowed: boolean;
    ruleId: string | null;
    reason: string | null;
    slippageBps: number | null;
    slippageState: SlippageMeasurementState;
    effectiveDelayMs: number;
    scheduledReleaseAt: string | null;
  } {
    const now = input.nowMs ?? Date.now();
    const effectiveDelayMs = Math.max(0, Math.min(60000, input.policy.executionDelayMs ?? 0));
    const baseMs = input.leaderTimestamp && Number.isFinite(Date.parse(input.leaderTimestamp)) ? Date.parse(input.leaderTimestamp) : now;
    const scheduledReleaseAt = effectiveDelayMs > 0 ? new Date(baseMs + effectiveDelayMs).toISOString() : null;

    // No reference price means no baseline to measure against. The leader's fill price *is* the
    // slippage reference (see leader-event-source.service.ts), so its absence is a data fault
    // rather than an ordinary market order - and copying blind is the outcome this guardrail exists
    // to prevent. Refuse, and say which input was missing, instead of reporting a pass that was
    // never established.
    if (!input.leaderPrice) {
      return {
        allowed: false,
        ruleId: 'SLIPPAGE_REFERENCE_UNAVAILABLE',
        reason: 'Leader reference price is unavailable, so adverse slippage cannot be measured',
        slippageBps: null,
        slippageState: 'UNMEASURABLE',
        effectiveDelayMs,
        scheduledReleaseAt,
      };
    }

    if (!isDecimalString(input.leaderPrice)) {
      return {
        allowed: false,
        ruleId: 'INVALID_SLIPPAGE_PRICE',
        reason: 'Leader price is not a valid decimal string',
        slippageBps: null,
        slippageState: 'UNMEASURABLE',
        effectiveDelayMs,
        scheduledReleaseAt,
      };
    }

    // The follower's price is not known until it trades. Its absence is not a pass: the measurement
    // has not been taken, and the result says so rather than implying the movement was zero. What
    // constrains the fill in the meantime are the venue-side bounds on the mapped intent
    // (intent.slippageUpper / slippageLower), derived from this same tolerance.
    if (!input.executionPrice) {
      return {
        allowed: true,
        ruleId: null,
        reason: 'Follower execution price is not known yet; adverse slippage is not yet measured',
        slippageBps: null,
        slippageState: 'NOT_YET_MEASURED',
        effectiveDelayMs,
        scheduledReleaseAt,
      };
    }

    if (!isDecimalString(input.executionPrice)) {
      return {
        allowed: false,
        ruleId: 'INVALID_SLIPPAGE_PRICE',
        reason: 'Execution price is not a valid decimal string',
        slippageBps: null,
        slippageState: 'UNMEASURABLE',
        effectiveDelayMs,
        scheduledReleaseAt,
      };
    }

    // Exact decimals from here down. Prices arrive as decimal strings and are parsed into scale-12
    // integers, so the comparison that decides whether a customer's order may proceed is made on
    // exact values. The previous implementation divided IEEE doubles and rounded to two places
    // before comparing, which is not a basis for a verdict expressed in basis points.
    const leader = decimalFromScaled12(parseDecimalString(input.leaderPrice));
    const execution = decimalFromScaled12(parseDecimalString(input.executionPrice));

    if (!leader.isPositive() || !execution.isPositive()) {
      return {
        allowed: false,
        ruleId: 'INVALID_SLIPPAGE_PRICE',
        reason: 'Leader price and execution price must be positive',
        slippageBps: null,
        slippageState: 'UNMEASURABLE',
        effectiveDelayMs,
        scheduledReleaseAt,
      };
    }

    const sideUpper = String(input.side || 'BUY').toUpperCase();
    // Adverse slippage in bps: for BUY, paying higher than leaderPrice; for SELL, receiving lower
    // than leaderPrice. Favourable movement reports zero, never a negative allowance.
    const rawDiff = sideUpper === 'BUY' ? execution.sub(leader) : leader.sub(execution);
    const adverseBpsExact = rawDiff.isPositive()
      ? rawDiff.div(leader, 18, 'HALF_UP').mul(10_000).normalize()
      : Decimal.ZERO;

    // Compared unrounded; rounded only for the response field. Rounding first would let 25.004 bps
    // satisfy a 25 bps tolerance.
    const maxBpsExact = Decimal.parse(input.policy.slippageToleranceBps ?? 100);
    const displayedBps = Number(adverseBpsExact.toFixed(2, 'HALF_UP'));

    if (adverseBpsExact.gt(maxBpsExact)) {
      return {
        allowed: false,
        ruleId: 'SLIPPAGE_TOLERANCE_EXCEEDED',
        reason: `Adverse slippage ${adverseBpsExact.toString()} bps exceeds tolerance ${maxBpsExact.toString()} bps`,
        slippageBps: displayedBps,
        slippageState: 'MEASURED',
        effectiveDelayMs,
        scheduledReleaseAt,
      };
    }

    return {
      allowed: true,
      ruleId: null,
      reason: null,
      slippageBps: displayedBps,
      slippageState: 'MEASURED',
      effectiveDelayMs,
      scheduledReleaseAt,
    };
  }

  /**
   * Computes deterministic TP/SL, trailing stop distance, and stop-copy condition triggers.
   */
  resolveStopPolicy(input: {
    policy: CopyPolicy;
    entryPrice: string | null;
    side: string;
    currentDrawdownPercent?: string | null;
    cumulativeLoss?: string | null;
  }): CopyStopExecutionPlan {
    const { policy, entryPrice, side } = input;
    const sideUpper = String(side || 'BUY').toUpperCase();

    let takeProfitPrice: string | null = null;
    let stopLossPrice: string | null = null;
    let trailingStopDistance: string | null = null;
    let trailingActivationPrice: string | null = null;

    if (entryPrice && isDecimalString(entryPrice)) {
      const entry = decimalFromScaled12(parseDecimalString(entryPrice));
      if (entry.isPositive()) {
        // A bps delta is `entry * bps / 10000`, evaluated exactly at scale 18 and normalised. The
        // exit prices this produces are order instructions, so they are derived the same way the
        // order mapper derives its bounds rather than by scaling a double and trimming its digits.
        const deltaFor = (bps: number): Decimal =>
          entry.mul(Decimal.parse(bps)).div(10_000, 18, 'HALF_UP').normalize();
        const isBuy = sideUpper === 'BUY';

        if (policy.takeProfitBps && policy.takeProfitBps > 0) {
          const delta = deltaFor(policy.takeProfitBps);
          const raw = isBuy ? entry.add(delta) : entry.sub(delta);
          // A non-positive exit price is not a price. Omit it rather than emit 0, which downstream
          // would read as an instruction to exit at zero.
          takeProfitPrice = raw.isPositive() ? raw.toString() : null;
          if (!takeProfitPrice) {
            this.logger.warn(`takeProfitBps=${policy.takeProfitBps} against entry=${entryPrice} yields no positive price for a ${sideUpper}`);
          }
        }

        if (policy.stopLossBps && policy.stopLossBps > 0) {
          const delta = deltaFor(policy.stopLossBps);
          const raw = isBuy ? entry.sub(delta) : entry.add(delta);
          stopLossPrice = raw.isPositive() ? raw.toString() : null;
          if (!stopLossPrice) {
            // A stop-loss that cannot be expressed is a control that will not exist. Loud, not silent.
            this.logger.warn(`stopLossBps=${policy.stopLossBps} against entry=${entryPrice} yields no positive price for a ${sideUpper}; no stop-loss will be attached`);
          }
        }

        if (policy.trailingStopBps && policy.trailingStopBps > 0) {
          trailingStopDistance = deltaFor(policy.trailingStopBps).toString();
          trailingActivationPrice = takeProfitPrice || entryPrice;
        }
      }
    }

    let stopCopyTriggered = false;
    let stopCopyReason: string | null = null;
    const conds = policy.stopCopyConditions || null;
    if (conds) {
      if (conds.maxDrawdownPercent && input.currentDrawdownPercent && isDecimalString(String(conds.maxDrawdownPercent)) && isDecimalString(input.currentDrawdownPercent)) {
        if (compareDecimalStrings(input.currentDrawdownPercent, String(conds.maxDrawdownPercent)) >= 0) {
          stopCopyTriggered = true;
          stopCopyReason = `Stop-copy drawdown threshold ${conds.maxDrawdownPercent}% reached (current ${input.currentDrawdownPercent}%)`;
        }
      }
      if (!stopCopyTriggered && conds.maxCumulativeLoss && input.cumulativeLoss && isDecimalString(String(conds.maxCumulativeLoss)) && isDecimalString(input.cumulativeLoss)) {
        if (compareDecimalStrings(input.cumulativeLoss, String(conds.maxCumulativeLoss)) >= 0) {
          stopCopyTriggered = true;
          stopCopyReason = `Stop-copy cumulative loss threshold ${conds.maxCumulativeLoss} reached (current ${input.cumulativeLoss})`;
        }
      }
    }

    return {
      takeProfitPrice,
      stopLossPrice,
      trailingStopBps: policy.trailingStopBps ?? null,
      trailingStopDistance,
      trailingActivationPrice,
      stopCopyTriggered,
      stopCopyReason,
    };
  }

  /**
   * Validates the allow / deny symbol rules on a policy.
   *
   * Rules are globs (see `matchesSymbolRule`). Two failure modes are worth rejecting loudly because
   * both leave an operator believing in a restriction that does not exist:
   *
   *   - a rule that can never match anything - empty, padded with whitespace, or carrying a
   *     character no symbol contains. `'BTC USDT'` looks like a symbol and matches nothing.
   *   - a rule set that contradicts itself - a literal appearing in both lists, or a blocked glob
   *     that swallows an allowed entry, which makes the allow list unsatisfiable and blocks every
   *     copy the operator expected to permit.
   *
   * The platform's own `*WITHDRAWAL*` deny rule is a valid glob and passes; it is the matcher, not
   * this validator, that had to learn about patterns for that rule to mean anything.
   */
  validateSymbolRules(policy: CopyPolicy): { valid: boolean; errors: string[] } {
    const errors: string[] = [];

    const inspect = (rules: string[] | null | undefined, label: string): void => {
      if (rules === null || rules === undefined) return;
      if (!Array.isArray(rules)) {
        errors.push(`${label} must be an array of symbol rules`);
        return;
      }
      for (const rule of rules) {
        if (typeof rule !== 'string' || rule.trim().length === 0) {
          errors.push(`${label} contains an empty rule`);
          continue;
        }
        if (rule !== rule.trim()) {
          errors.push(`${label} rule "${rule}" has surrounding whitespace and will never match`);
        }
        if (/\s/.test(rule)) {
          errors.push(`${label} rule "${rule}" contains whitespace and will never match a symbol`);
        }
        if (!/^[A-Za-z0-9*._/$:-]+$/.test(rule)) {
          errors.push(`${label} rule "${rule}" contains characters that are not valid in a symbol or glob`);
        }
      }
    };

    inspect(policy.allowedSymbols, 'allowedSymbols');
    inspect(policy.blockedSymbols, 'blockedSymbols');

    const blocked = Array.isArray(policy.blockedSymbols) ? policy.blockedSymbols : [];
    const allowed = Array.isArray(policy.allowedSymbols) ? policy.allowedSymbols : [];

    if (blocked.some((rule) => rule.trim() === '*')) {
      errors.push("blockedSymbols '*' blocks every symbol");
    }

    for (const entry of allowed) {
      if (typeof entry !== 'string' || entry.length === 0) continue;
      const conflicting = blocked.find(
        (rule) => typeof rule === 'string' && !rule.includes('*') && rule.toUpperCase() === entry.toUpperCase(),
      );
      if (conflicting) {
        errors.push(`symbol ${entry} appears in both allowedSymbols and blockedSymbols`);
        continue;
      }
      // Only a literal allow entry can be swallowed unambiguously; comparing two globs would be a
      // claim this validator cannot support.
      if (!entry.includes('*')) {
        const swallower = blocked.find((rule) => typeof rule === 'string' && rule.includes('*') && matchesSymbolRule(rule, entry));
        if (swallower) {
          errors.push(`allowedSymbols entry ${entry} is blocked by rule ${swallower}, so no symbol can satisfy both`);
        }
      }
    }

    return { valid: errors.length === 0, errors };
  }

  validatePolicy(policy: CopyPolicy): { valid: boolean; errors: string[] } {
    const errors: string[] = [];

    if (policy.maxOrderNotional && !isDecimalString(policy.maxOrderNotional)) errors.push('maxOrderNotional must be valid decimal');
    if (policy.maxDailyNotional && !isDecimalString(policy.maxDailyNotional)) errors.push('maxDailyNotional must be valid decimal');
    if (policy.slippageToleranceBps !== null && policy.slippageToleranceBps !== undefined && (policy.slippageToleranceBps < 0 || policy.slippageToleranceBps > 10000)) errors.push('slippageToleranceBps must be 0-10000');
    if (policy.executionDelayMs !== null && policy.executionDelayMs !== undefined && (policy.executionDelayMs < 0 || policy.executionDelayMs > 60000)) errors.push('executionDelayMs must be 0-60000');
    if (policy.maxConcurrentCopies !== null && policy.maxConcurrentCopies !== undefined && policy.maxConcurrentCopies < 1) errors.push('maxConcurrentCopies must be >=1');
    const parsedMaxLeverage = policy.maxLeverage ? Decimal.tryParse(policy.maxLeverage) : null;
    if (policy.maxLeverage && (!parsedMaxLeverage || !parsedMaxLeverage.isPositive())) errors.push('maxLeverage must be > 0');
    if (policy.takeProfitBps !== null && policy.takeProfitBps !== undefined && policy.takeProfitBps < 0) errors.push('takeProfitBps must be >= 0');
    if (policy.stopLossBps !== null && policy.stopLossBps !== undefined && (policy.stopLossBps < 0 || policy.stopLossBps > 10000)) errors.push('stopLossBps must be 0-10000');
    if (policy.trailingStopBps !== null && policy.trailingStopBps !== undefined && (policy.trailingStopBps < 0 || policy.trailingStopBps > 10000)) errors.push('trailingStopBps must be 0-10000');

    // Platform mandatory caps, compared exactly.
    const platformMaxOrder = this.platformPolicy.maxOrderNotional ?? '100000';
    if (policy.maxOrderNotional && compareDecimalStrings(policy.maxOrderNotional, platformMaxOrder) > 0) {
      errors.push(`maxOrderNotional cannot exceed platform cap ${platformMaxOrder}`);
    }

    const platformMaxLev = this.platformPolicy.maxLeverage ?? '10';
    if (parsedMaxLeverage && parsedMaxLeverage.gt(Decimal.parse(platformMaxLev))) {
      errors.push(`maxLeverage cannot exceed platform cap ${platformMaxLev}`);
    }

    return { valid: errors.length === 0, errors };
  }
}

import { Injectable, Logger, Optional } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { CopyExecutionRepository } from './copy-execution.repository';
import { CopySubscriptionRepository } from './copy-subscription.repository';
import { CopyReconciliationCategory, CopyReconciliationSeverity } from './copy-trading.types';
import { randomUUID } from 'crypto';
import { LeaderEventSourceService, subscriptionWasLiveAt } from './leader-event-source.service';

/** Events younger than this are still in flight (ingestion interval + dispatch). */
const MISSING_COPY_GRACE_MS = 60_000;

/**
 * Reconciles leader ↔ copy intent ↔ copy execution ↔ follower order/fill for correctness, detects missing/duplicate/stale/mismatch/slippage/delay anomalies, and produces auditable diffs.
 * Execution after stop-copy must be flagged.
 */
@Injectable()
export class CopyReconciliationService {
  private readonly logger = new Logger(CopyReconciliationService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly executionRepo: CopyExecutionRepository,
    private readonly subscriptionRepo: CopySubscriptionRepository,
    // Phase 3: the leader-event store (leader fills). Optional so a harness
    // without it still reconciles executions; missing-copy detection then
    // reports itself as skipped instead of silently passing.
    @Optional() private readonly leaderEvents?: LeaderEventSourceService,
  ) {}

  async reconcileTenant(tenantId: string, filters?: { strategyId?: string; from?: Date; to?: Date; limit?: number }): Promise<{ records: any[]; summary: Record<string, number> }> {
    const limit = filters?.limit || 100;
    const from = filters?.from || new Date(Date.now() - 24 * 60 * 60 * 1000);
    const to = filters?.to || new Date();

    // Get leader events - from orders/fills? For simplicity, we treat orders as leader events
    // In real system, leader events would be stored in a separate table or derived from trader's orders

    // Get all executions in time range
    const executions = await (this.prisma as any).copyExecution?.findMany({ where: { tenantId, createdAt: { gte: from, lte: to }, ...(filters?.strategyId ? { traderId: filters.strategyId } : {}) }, orderBy: { createdAt: 'desc' }, take: limit }) || [];

    // Get all active subscriptions for tenant
    const { data: subscriptions } = await this.subscriptionRepo.listByTenant(tenantId, { page: 1, limit: 1000 });

    const records: any[] = [];
    const summary: Record<string, number> = {};

    const incrementSummary = (cat: string) => {
      summary[cat] = (summary[cat] || 0) + 1;
    };

    // Check each execution
    for (const exec of executions) {
      try {
        const sub = subscriptions.find((s: any) => s.id === exec.subscriptionId);

        // Execution after stop-copy must be flagged
        if (sub && (sub.state === 'STOPPED' || sub.state === 'CANCELLED')) {
          if (new Date(exec.createdAt) > new Date(sub.stoppedAt || sub.cancelledAt || sub.updatedAt)) {
            const rec = await this.createRecord({
              tenantId,
              leaderEventId: exec.leaderEventId,
              subscriptionId: exec.subscriptionId,
              executionId: exec.id,
              category: CopyReconciliationCategory.EXECUTION_AFTER_STOP,
              severity: CopyReconciliationSeverity.CRITICAL,
              expected: { subscriptionState: sub.state, stoppedAt: sub.stoppedAt || sub.cancelledAt },
              actual: { executionCreatedAt: exec.createdAt, status: exec.status },
              leaderReference: { leaderEventId: exec.leaderEventId, leaderOrderId: exec.leaderOrderId },
              followerReference: { followerOrderId: exec.followerOrderId, followerFillId: exec.followerFillId },
            });
            records.push(rec);
            incrementSummary(CopyReconciliationCategory.EXECUTION_AFTER_STOP);
          }
        }

        // Duplicate copy detection - same leaderEvent + subscription
        const duplicates = executions.filter((e: any) => e.leaderEventId === exec.leaderEventId && e.subscriptionId === exec.subscriptionId && e.id !== exec.id);
        if (duplicates.length > 0) {
          const rec = await this.createRecord({
            tenantId,
            leaderEventId: exec.leaderEventId,
            subscriptionId: exec.subscriptionId,
            executionId: exec.id,
            category: CopyReconciliationCategory.DUPLICATE_COPY,
            severity: CopyReconciliationSeverity.HIGH,
            expected: { count: 1 },
            actual: { count: duplicates.length + 1, duplicateIds: duplicates.map((d: any) => d.id) },
            leaderReference: { leaderEventId: exec.leaderEventId },
            followerReference: null,
          });
          records.push(rec);
          incrementSummary(CopyReconciliationCategory.DUPLICATE_COPY);
        }

        // Stale intent - execution stuck in PENDING/VALIDATED for too long
        if (['PENDING', 'VALIDATED', 'MAPPED', 'RISK_CHECKED', 'ROUTED'].includes(exec.status)) {
          const ageMs = Date.now() - new Date(exec.createdAt).getTime();
          if (ageMs > 5 * 60 * 1000) {
            // 5 minutes stale
            const rec = await this.createRecord({
              tenantId,
              leaderEventId: exec.leaderEventId,
              subscriptionId: exec.subscriptionId,
              executionId: exec.id,
              category: CopyReconciliationCategory.STALE_INTENT,
              severity: ageMs > 30 * 60 * 1000 ? CopyReconciliationSeverity.HIGH : CopyReconciliationSeverity.MEDIUM,
              expected: { status: 'FILLED or FAILED within 5min' },
              actual: { status: exec.status, ageMs },
              leaderReference: null,
              followerReference: null,
            });
            records.push(rec);
            incrementSummary(CopyReconciliationCategory.STALE_INTENT);
          }
        }

        // Order mismatch - follower order not found or mismatched
        if (exec.followerOrderId) {
          try {
            const followerOrder = await this.prisma.order.findFirst({ where: { id: exec.followerOrderId, tenantId } });
            if (!followerOrder) {
              const rec = await this.createRecord({
                tenantId,
                leaderEventId: exec.leaderEventId,
                subscriptionId: exec.subscriptionId,
                executionId: exec.id,
                category: CopyReconciliationCategory.ORDER_MISMATCH,
                severity: CopyReconciliationSeverity.HIGH,
                expected: { followerOrderId: exec.followerOrderId },
                actual: { found: false },
                leaderReference: null,
                followerReference: { followerOrderId: exec.followerOrderId },
              });
              records.push(rec);
              incrementSummary(CopyReconciliationCategory.ORDER_MISMATCH);
            } else {
              // Quantity mismatch
              if (exec.followerQuantity && followerOrder.quantity) {
                const execQty = exec.followerQuantity.toString();
                const orderQty = followerOrder.quantity.toString();
                if (execQty !== orderQty) {
                  const rec = await this.createRecord({
                    tenantId,
                    leaderEventId: exec.leaderEventId,
                    subscriptionId: exec.subscriptionId,
                    executionId: exec.id,
                    category: CopyReconciliationCategory.QUANTITY_MISMATCH,
                    severity: CopyReconciliationSeverity.MEDIUM,
                    expected: { quantity: execQty },
                    actual: { quantity: orderQty },
                    leaderReference: null,
                    followerReference: { orderId: followerOrder.id, quantity: orderQty },
                  });
                  records.push(rec);
                  incrementSummary(CopyReconciliationCategory.QUANTITY_MISMATCH);
                }
              }

              // Price mismatch / slippage
              if (exec.followerPrice && followerOrder.price) {
                const execPrice = parseFloat(exec.followerPrice.toString());
                const orderPrice = parseFloat(followerOrder.price.toString());
                const slippage = Math.abs(execPrice - orderPrice) / execPrice;
                const tolerance = exec.slippageTolerance ? parseFloat(exec.slippageTolerance) / 10000 : 0.01;
                if (slippage > tolerance) {
                  const rec = await this.createRecord({
                    tenantId,
                    leaderEventId: exec.leaderEventId,
                    subscriptionId: exec.subscriptionId,
                    executionId: exec.id,
                    category: CopyReconciliationCategory.SLIPPAGE_EXCEEDED,
                    severity: slippage > tolerance * 2 ? CopyReconciliationSeverity.HIGH : CopyReconciliationSeverity.MEDIUM,
                    expected: { price: exec.followerPrice, slippageTolerance: tolerance },
                    actual: { price: followerOrder.price, slippage },
                    leaderReference: { leaderPrice: exec.leaderPrice },
                    followerReference: { followerPrice: followerOrder.price },
                  });
                  records.push(rec);
                  incrementSummary(CopyReconciliationCategory.SLIPPAGE_EXCEEDED);
                }
              }
            }
          } catch {}
        }

        // Status mismatch - execution FILLED but order not FILLED
        if (exec.status === 'FILLED' && exec.followerOrderId) {
          try {
            const order = await this.prisma.order.findFirst({ where: { id: exec.followerOrderId, tenantId } });
            if (order && order.status !== 'FILLED' && order.status !== 'PARTIALLY_FILLED') {
              const rec = await this.createRecord({
                tenantId,
                leaderEventId: exec.leaderEventId,
                subscriptionId: exec.subscriptionId,
                executionId: exec.id,
                category: CopyReconciliationCategory.STATUS_MISMATCH,
                severity: CopyReconciliationSeverity.MEDIUM,
                expected: { executionStatus: 'FILLED', orderStatus: 'FILLED' },
                actual: { executionStatus: exec.status, orderStatus: order.status },
                leaderReference: null,
                followerReference: { orderId: order.id, status: order.status },
              });
              records.push(rec);
              incrementSummary(CopyReconciliationCategory.STATUS_MISMATCH);
            }
          } catch {}
        }
      } catch (e: any) {
        this.logger.warn(`Reconciliation error for execution=${exec.id} error=${e.message}`);
      }
    }

    // Missing copy detection - every leader event (leader fill) that happened
    // while a subscription was live must have a CopyExecution for that
    // subscription (FILLED, SKIPPED, BLOCKED... any outcome is an answer; no
    // record at all is a silent miss). Events inside the grace window are
    // still in flight and are not judged yet.
    if (!this.leaderEvents) {
      summary.MISSING_COPY_CHECK_SKIPPED = 1;
    } else {
      try {
        const now = Date.now();
        const byStrategy = new Map<string, any[]>();
        for (const sub of subscriptions as any[]) {
          if (filters?.strategyId && sub.strategyId !== filters.strategyId && sub.traderId !== filters.strategyId) continue;
          const list = byStrategy.get(sub.strategyId) ?? [];
          list.push(sub);
          byStrategy.set(sub.strategyId, list);
        }
        const strategies = byStrategy.size > 0 ? await this.leaderEvents.listLeadingStrategies(tenantId, [...byStrategy.keys()]) : [];
        for (const strategy of strategies) {
          const subs = byStrategy.get(strategy.id) ?? [];
          const events = await this.leaderEvents.listForStrategy(tenantId, strategy, from, to, 500);
          if (events.length === 0) continue;
          const copies = (await (this.prisma as any).copyExecution?.findMany({
            where: { tenantId, leaderEventId: { in: events.map((e) => e.event.eventId) } },
            select: { leaderEventId: true, subscriptionId: true },
          })) || [];
          const copied = new Set(copies.map((c: any) => `${c.leaderEventId}|${c.subscriptionId}`));
          for (const record of events) {
            const ageMs = now - record.occurredAt.getTime();
            if (ageMs < MISSING_COPY_GRACE_MS) continue;
            for (const sub of subs) {
              if (!subscriptionWasLiveAt(sub, record.occurredAt)) continue;
              if (copied.has(`${record.event.eventId}|${sub.id}`)) continue;
              const rec = await this.createRecord({
                tenantId,
                leaderEventId: record.event.eventId,
                subscriptionId: sub.id,
                executionId: null,
                category: CopyReconciliationCategory.MISSING_COPY,
                severity: CopyReconciliationSeverity.HIGH,
                expected: { copyExecution: 'one record per live subscription', subscriptionState: sub.state },
                actual: { found: 0, eventAgeMs: ageMs },
                leaderReference: {
                  leaderEventId: record.event.eventId,
                  leaderOrderId: record.event.orderId,
                  leaderFillId: record.event.fillId,
                  symbol: record.event.symbol,
                  side: record.event.side,
                  quantity: record.event.quantity,
                  price: record.event.price,
                  occurredAt: record.occurredAt.toISOString(),
                },
                followerReference: { subscriptionId: sub.id, followerId: sub.followerId, followerAccountId: sub.followerAccountId ?? null },
              });
              records.push(rec);
              incrementSummary(CopyReconciliationCategory.MISSING_COPY);
            }
          }
        }
      } catch (e: any) {
        this.logger.warn(`Missing-copy detection failed tenant=${tenantId} error=${e.message}`);
        summary.MISSING_COPY_CHECK_FAILED = 1;
      }
    }

    this.logger.log(`Reconciliation completed tenant=${tenantId} records=${records.length} summary=${JSON.stringify(summary)}`);

    return { records, summary };
  }

  private async createRecord(input: {
    tenantId: string;
    leaderEventId: string;
    subscriptionId?: string | null;
    executionId?: string | null;
    category: CopyReconciliationCategory;
    severity: CopyReconciliationSeverity;
    expected: Record<string, any> | null;
    actual: Record<string, any> | null;
    leaderReference: Record<string, any> | null;
    followerReference: Record<string, any> | null;
  }): Promise<any> {
    try {
      const existing = await (this.prisma as any).copyReconciliationRecord?.findFirst({ where: { tenantId: input.tenantId, leaderEventId: input.leaderEventId, subscriptionId: input.subscriptionId, category: input.category, resolved: false } });
      if (existing) return existing;

      return await (this.prisma as any).copyReconciliationRecord.create({
        data: {
          id: randomUUID(),
          tenantId: input.tenantId,
          leaderEventId: input.leaderEventId,
          subscriptionId: input.subscriptionId || null,
          executionId: input.executionId || null,
          category: input.category,
          severity: input.severity,
          expected: input.expected,
          actual: input.actual,
          leaderReference: input.leaderReference,
          followerReference: input.followerReference,
          resolved: false,
          createdAt: new Date(),
        },
      });
    } catch (e: any) {
      this.logger.warn(`Failed to create reconciliation record error=${e.message}`);
      return { id: randomUUID(), ...input, resolved: false, createdAt: new Date().toISOString() };
    }
  }

  async resolveRecord(tenantId: string, recordId: string, actorId: string, notes?: string): Promise<any | null> {
    // Tenant check before the write (the old code updated first and checked afterwards).
    const existing = await (this.prisma as any).copyReconciliationRecord.findFirst({ where: { id: recordId, tenantId } });
    if (!existing) return null;
    // Columns: resolved/resolvedAt/resolvedBy. No notes column: kept in actual._resolution.
    const actual = existing.actual && typeof existing.actual === 'object' && !Array.isArray(existing.actual) ? existing.actual : {};
    const updated = await (this.prisma as any).copyReconciliationRecord.update({
      where: { id: recordId },
      data: {
        resolved: true,
        resolvedBy: actorId,
        resolvedAt: new Date(),
        ...(notes ? { actual: { ...actual, _resolution: { notes } } } : {}),
      },
    });
    return updated;
  }

  async listRecords(tenantId: string, filters?: { resolved?: boolean; category?: CopyReconciliationCategory; severity?: CopyReconciliationSeverity; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const skip = (page - 1) * limit;
    const where: any = {
      tenantId,
      ...(filters?.resolved !== undefined ? { resolved: filters.resolved } : {}),
      ...(filters?.category ? { category: filters.category } : {}),
      ...(filters?.severity ? { severity: filters.severity } : {}),
    };
    const [data, total] = await Promise.all([
      (this.prisma as any).copyReconciliationRecord?.findMany({ where, orderBy: { createdAt: 'desc' }, skip, take: limit }) || [],
      (this.prisma as any).copyReconciliationRecord?.count({ where }) || 0,
    ]);
    return { data, total };
  }

  async getCustomerSubscriptionStatus(
    tenantId: string,
    subscriptionId: string,
    followerId?: string | null,
  ): Promise<{
    subscriptionId: string;
    status: 'SYNCED' | 'PENDING_REVIEW' | 'ATTENTION_REQUIRED';
    unresolvedCount: number;
    resolvedCount: number;
    lastCheckedAt: string;
    items: Array<{
      id: string;
      category: CopyReconciliationCategory;
      severity: CopyReconciliationSeverity;
      resolved: boolean;
      createdAt: string;
      leaderEventId: string;
      executionId: string | null;
      customerMessage: string;
    }>;
  } | null> {
    const sub = await this.subscriptionRepo.findById(subscriptionId, tenantId);
    if (!sub) return null;
    if (followerId && sub.followerId !== followerId) return null;

    const rows =
      (await (this.prisma as any).copyReconciliationRecord?.findMany({
        where: { tenantId, subscriptionId },
        orderBy: { createdAt: 'desc' },
        take: 50,
      })) || [];

    let unresolvedCount = 0;
    let resolvedCount = 0;
    let hasCriticalOrHigh = false;

    const items = rows.map((row: any) => {
      const resolved = Boolean(row.resolved);
      if (resolved) resolvedCount += 1;
      else {
        unresolvedCount += 1;
        if (row.severity === CopyReconciliationSeverity.CRITICAL || row.severity === CopyReconciliationSeverity.HIGH) {
          hasCriticalOrHigh = true;
        }
      }
      return {
        id: String(row.id),
        category: row.category as CopyReconciliationCategory,
        severity: row.severity as CopyReconciliationSeverity,
        resolved,
        createdAt: row.createdAt instanceof Date ? row.createdAt.toISOString() : String(row.createdAt),
        leaderEventId: String(row.leaderEventId ?? ''),
        executionId: row.executionId ? String(row.executionId) : null,
        customerMessage: this.describeCustomerAnomaly(row.category as CopyReconciliationCategory, resolved),
      };
    });

    const status =
      unresolvedCount === 0
        ? 'SYNCED'
        : hasCriticalOrHigh
          ? 'ATTENTION_REQUIRED'
          : 'PENDING_REVIEW';

    return {
      subscriptionId,
      status,
      unresolvedCount,
      resolvedCount,
      lastCheckedAt: rows[0]?.createdAt
        ? rows[0].createdAt instanceof Date
          ? rows[0].createdAt.toISOString()
          : String(rows[0].createdAt)
        : new Date().toISOString(),
      items,
    };
  }

  private describeCustomerAnomaly(category: CopyReconciliationCategory, resolved: boolean): string {
    const suffix = resolved ? ' (resolved by reconciliation)' : ' (under automatic reconciliation review)';
    switch (category) {
      case CopyReconciliationCategory.MISSING_COPY:
        return `A leader trade was not copied within the execution window${suffix}.`;
      case CopyReconciliationCategory.DUPLICATE_COPY:
        return `Duplicate copy intent detected and guarded${suffix}.`;
      case CopyReconciliationCategory.STALE_INTENT:
        return `Copy order intent remained pending longer than expected${suffix}.`;
      case CopyReconciliationCategory.QUANTITY_MISMATCH:
        return `Executed quantity differed from mapped copy quantity${suffix}.`;
      case CopyReconciliationCategory.PRICE_MISMATCH:
      case CopyReconciliationCategory.SLIPPAGE_EXCEEDED:
        return `Execution price deviated beyond configured slippage tolerance${suffix}.`;
      case CopyReconciliationCategory.STATUS_MISMATCH:
      case CopyReconciliationCategory.ORDER_MISMATCH:
        return `Order state synchronization check queued${suffix}.`;
      default:
        return `Copy execution verification check recorded${suffix}.`;
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import type { Prisma } from '@prisma/client';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { CopySubscriptionState, CopySizingMode } from './copy-trading.types';
import { randomUUID } from 'crypto';
import { isRecordNotFound } from '../../common/errors/prisma-not-found';

/**
 * Persistence abstraction for trader/follower subscriptions, state, allocation, policy references, idempotency, lifecycle history, and tenant isolation.
 * Enforce tenant isolation. Prevent duplicate active subscription where business rules prohibit it.
 */
@Injectable()
export class CopySubscriptionRepository {
  private readonly logger = new Logger(CopySubscriptionRepository.name);

  constructor(private readonly prisma: PrismaService) {}

  async create(input: {
    tenantId: string;
    followerId: string;
    traderId: string;
    strategyId: string;
    allocationMode: CopySizingMode;
    allocationAmount: string;
    maxAllocation?: string | null;
    minAllocation?: string | null;
    copyPolicy?: Record<string, any>;
    riskPolicy?: Record<string, any>;
    followerAccountId?: string | null;
    idempotencyKey?: string | null;
  }, tx?: Prisma.TransactionClient): Promise<any> {
    const client = (tx ?? this.prisma) as any;

    // Idempotent replay first: a retried request (same tenant, same key) gets
    // its original subscription back. Checked before the duplicate-active rule,
    // because the original subscription IS the active one - checking the rule
    // first turned every retry into a "duplicate" error.
    if (input.idempotencyKey) {
      const existingByKey = await client.copySubscription.findFirst({ where: { tenantId: input.tenantId, idempotencyKey: input.idempotencyKey } });
      if (existingByKey) {
        this.logger.log(`Idempotent subscription return key=${input.idempotencyKey}`);
        return existingByKey;
      }
    }

    // Prevent duplicate active subscription where business rules prohibit it
    const existingActive = await client.copySubscription.findFirst({
      where: { tenantId: input.tenantId, followerId: input.followerId, strategyId: input.strategyId, state: { in: ['PENDING', 'ACTIVE', 'PAUSED'] } },
    });

    if (existingActive) {
      throw new Error(`Duplicate active subscription for follower=${input.followerId} strategy=${input.strategyId} existing=${existingActive.id}`);
    }

    const id = randomUUID();
    const now = new Date();

    const data = {
      id,
      tenantId: input.tenantId,
      followerId: input.followerId,
      traderId: input.traderId,
      strategyId: input.strategyId,
      state: CopySubscriptionState.PENDING,
      allocationMode: input.allocationMode,
      allocationAmount: input.allocationAmount,
      maxAllocation: input.maxAllocation || null,
      minAllocation: input.minAllocation || null,
      copyPolicy: input.copyPolicy || {},
      riskPolicy: input.riskPolicy || {},
      followerAccountId: input.followerAccountId || null,
      startedAt: null,
      pausedAt: null,
      stoppedAt: null,
      totalCopiedVolume: '0',
      totalCopies: 0,
      failedCopies: 0,
      idempotencyKey: input.idempotencyKey || randomUUID(),
      createdAt: now,
      updatedAt: now,
    };

    try {
      const created = await client.copySubscription.create({ data });
      this.logger.log(`Copy subscription created id=${created.id} tenant=${input.tenantId} follower=${input.followerId} trader=${input.traderId} strategy=${input.strategyId}`);
      return created;
    } catch (e: any) {
      if (e.code === 'P2002' && tx) {
        // PostgreSQL marks the surrounding transaction failed after a unique
        // violation; do not attempt a read through the aborted transaction.
        throw e;
      }
      if (e.code === 'P2002') {
        if (input.idempotencyKey) {
          const existing = await client.copySubscription.findFirst({ where: { tenantId: input.tenantId, idempotencyKey: input.idempotencyKey } });
          if (existing) return existing;
        }
        // Unique follower+strategy
        const existing = await client.copySubscription.findFirst({ where: { tenantId: input.tenantId, followerId: input.followerId, strategyId: input.strategyId } });
        if (existing) return existing;
      }
      throw e;
    }
  }

  async findById(id: string, tenantId: string): Promise<any | null> {
    return (this.prisma as any).copySubscription?.findFirst({ where: { id, tenantId } }) || null;
  }

  async findActiveByFollowerAndStrategy(tenantId: string, followerId: string, strategyId: string): Promise<any | null> {
    return (this.prisma as any).copySubscription?.findFirst({ where: { tenantId, followerId, strategyId, state: { in: ['PENDING', 'ACTIVE', 'PAUSED'] } } }) || null;
  }

  async listByFollower(tenantId: string, followerId: string, filters?: { state?: CopySubscriptionState; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const skip = (page - 1) * limit;
    const where: any = { tenantId, followerId, ...(filters?.state ? { state: filters.state } : {}) };
    const [data, total] = await Promise.all([
      (this.prisma as any).copySubscription?.findMany({ where, orderBy: { createdAt: 'desc' }, skip, take: limit }) || [],
      (this.prisma as any).copySubscription?.count({ where }) || 0,
    ]);
    return { data, total };
  }

  async listByTrader(tenantId: string, traderId: string, filters?: { state?: CopySubscriptionState; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const skip = (page - 1) * limit;
    const where: any = { tenantId, traderId, ...(filters?.state ? { state: filters.state } : {}) };
    const [data, total] = await Promise.all([
      (this.prisma as any).copySubscription?.findMany({ where, orderBy: { createdAt: 'desc' }, skip, take: limit }) || [],
      (this.prisma as any).copySubscription?.count({ where }) || 0,
    ]);
    return { data, total };
  }

  async listActive(tenantId: string, filters?: { strategyId?: string; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 100;
    const skip = (page - 1) * limit;
    const where: any = { tenantId, state: 'ACTIVE', ...(filters?.strategyId ? { strategyId: filters.strategyId } : {}) };
    const [data, total] = await Promise.all([
      (this.prisma as any).copySubscription?.findMany({ where, orderBy: { createdAt: 'asc' }, skip, take: limit }) || [],
      (this.prisma as any).copySubscription?.count({ where }) || 0,
    ]);
    return { data, total };
  }

  async listByTenant(tenantId: string, filters?: { state?: CopySubscriptionState; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const skip = (page - 1) * limit;
    const where: any = { tenantId, ...(filters?.state ? { state: filters.state } : {}) };
    const [data, total] = await Promise.all([
      (this.prisma as any).copySubscription?.findMany({ where, orderBy: { createdAt: 'desc' }, skip, take: limit }) || [],
      (this.prisma as any).copySubscription?.count({ where }) || 0,
    ]);
    return { data, total };
  }

  async updateState(
    id: string,
    tenantId: string,
    state: CopySubscriptionState,
    timestamps?: { startedAt?: Date; pausedAt?: Date; stoppedAt?: Date; cancelledAt?: Date },
    options: { tx?: Prisma.TransactionClient; expectedState?: CopySubscriptionState } = {},
  ): Promise<any | null> {
    const client = (options.tx ?? this.prisma) as any;
    const where = {
      id,
      tenantId,
      ...(options.expectedState ? { state: options.expectedState } : {}),
    };
    const result = await client.copySubscription.updateMany({
      where,
      data: { state, ...timestamps, updatedAt: new Date() },
    });
    if (result.count !== 1) return null;
    return client.copySubscription.findFirst({ where: { id, tenantId } });
  }

  async updateAllocation(id: string, tenantId: string, allocation: { allocationAmount?: string; maxAllocation?: string | null; minAllocation?: string | null; allocationMode?: CopySizingMode }): Promise<any | null> {
    try {
      return await (this.prisma as any).copySubscription.update({ where: { id }, data: { ...allocation, updatedAt: new Date() } });
    } catch (error) {
      if (isRecordNotFound(error)) return null;
      throw error;
    }
  }

  async updatePolicy(id: string, tenantId: string, policy: { copyPolicy?: Record<string, any>; riskPolicy?: Record<string, any> }): Promise<any | null> {
    try {
      return await (this.prisma as any).copySubscription.update({ where: { id }, data: { ...policy, updatedAt: new Date() } });
    } catch (error) {
      if (isRecordNotFound(error)) return null;
      throw error;
    }
  }

  async incrementStats(id: string, tenantId: string, stats: { totalCopies?: number; failedCopies?: number; volume?: string }): Promise<void> {
    try {
      const existing = await (this.prisma as any).copySubscription.findFirst({ where: { id, tenantId } });
      if (!existing) return;
      const newTotal = (existing.totalCopies || 0) + (stats.totalCopies || 0);
      const newFailed = (existing.failedCopies || 0) + (stats.failedCopies || 0);
      // Decimal-safe volume addition - preserve as string via BigInt? Simplified: use string addition for integer part
      let newVolume = existing.totalCopiedVolume || '0';
      if (stats.volume) {
        try {
          // Simple decimal addition preserving precision for integer part
          const [aInt, aDec = ''] = newVolume.split('.');
          const [bInt, bDec = ''] = stats.volume.split('.');
          const maxDec = Math.max(aDec.length, bDec.length);
          const aFull = BigInt((aInt || '0') + aDec.padEnd(maxDec, '0'));
          const bFull = BigInt((bInt || '0') + bDec.padEnd(maxDec, '0'));
          const sum = aFull + bFull;
          const sumStr = sum.toString().padStart(maxDec + 1, '0');
          if (maxDec === 0) newVolume = sumStr;
          else {
            const intPart = sumStr.slice(0, -maxDec) || '0';
            const decPart = sumStr.slice(-maxDec).replace(/0+$/, '');
            newVolume = decPart ? `${intPart}.${decPart}` : intPart;
          }
        } catch {
          newVolume = (parseFloat(newVolume) + parseFloat(stats.volume)).toString();
        }
      }

      await (this.prisma as any).copySubscription.update({
        where: { id },
        data: { totalCopies: newTotal, failedCopies: newFailed, totalCopiedVolume: newVolume, updatedAt: new Date() },
      });
    } catch {}
  }

  async countActiveByFollower(tenantId: string, followerId: string): Promise<number> {
    return (this.prisma as any).copySubscription?.count({ where: { tenantId, followerId, state: { in: ['PENDING', 'ACTIVE', 'PAUSED'] } } }) || 0;
  }

  async countActiveByTrader(tenantId: string, traderId: string): Promise<number> {
    return (this.prisma as any).copySubscription?.count({ where: { tenantId, traderId, state: { in: ['PENDING', 'ACTIVE'] } } }) || 0;
  }
}

import { Controller, Get, Post, Put, Delete, Body, Param, Query, Request, BadRequestException, NotFoundException, ForbiddenException } from '@nestjs/common';
import { TraderProfileService } from './trader-profile.service';
import { TraderStrategyService } from './trader-strategy.service';
import { FollowerSubscriptionService } from './follower-subscription.service';
import { CopyExecutionService } from './copy-execution.service';
import { CopyPolicyService } from './copy-policy.service';
import {
  toTraderProfileListingView,
  toTraderProfilePublicView,
} from './trader-profile.public-view';
import { TraderPerformanceService } from './trader-performance.service';
import { TraderRankingService } from './trader-ranking.service';
import { CopyReconciliationService } from './copy-reconciliation.service';
import { CopySubscriptionRepository } from './copy-subscription.repository';
import { CopyExecutionRepository } from './copy-execution.repository';
import { CreateTraderProfileDto, UpdateTraderProfileDto, CreateTraderStrategyDto, UpdateTraderStrategyDto, TraderStrategyFilterDto } from './dto/trader-strategy.dto';
import { CreateFollowerSubscriptionDto, UpdateFollowerSubscriptionDto, FollowerSubscriptionFilterDto, CopyExecutionFilterDto } from './dto/follower-subscription.dto';
import { LeaderEventDto } from './dto/copy-policy.dto';
import { TraderStrategy, TraderStrategyStatus, TraderVerificationState } from './copy-trading.types';
import { Permission } from '@wlct/shared-types';
import { RequireAnyPermission, RequirePermissions } from '../../common/decorators/permissions.decorator';

/** Strategy states a non-owner may see: live, or paused with existing followers. */
const PUBLIC_STRATEGY_STATUSES: TraderStrategyStatus[] = [TraderStrategyStatus.PUBLISHED, TraderStrategyStatus.PAUSED];
import { authRoles, authTenantId, authUserIdOrNull, hasAdminRole } from '../../common/guards/request-principal';
import { limitParam, pageParam } from '../../common/dto/pagination-params';

/**
 * Tenant-protected endpoints for trader/follower/platform capabilities.
 * Marketplace listing, trader profile management, strategy publishing, subscription lifecycle, execution inspection, policy resolution, ranking, performance, and reconciliation.
 */
/**
 * Copy trading. Every route carries explicit permission metadata (it used to
 * carry none, so any authenticated tenant user passed the global guard):
 * - strategy:read            catalogue (traders, strategies, rankings, policies)
 * - strategy:manage          trader side (profiles, strategies, leader events)
 * - copy_subscription:read   own subscriptions and executions
 * - copy_subscription:manage subscribe / pause / resume / stop / cancel
 * The handlers keep their ownership checks on top of that. Non-owners see only
 * published/paused strategies and never a trader's strategyConfig.
 */
@Controller('copy-trading')
export class CopyTradingController {
  constructor(
    private readonly traderProfileService: TraderProfileService,
    private readonly traderStrategyService: TraderStrategyService,
    private readonly followerSubscriptionService: FollowerSubscriptionService,
    private readonly copyExecutionService: CopyExecutionService,
    private readonly copyPolicyService: CopyPolicyService,
    private readonly traderPerformanceService: TraderPerformanceService,
    private readonly traderRankingService: TraderRankingService,
    private readonly reconciliationService: CopyReconciliationService,
    private readonly subscriptionRepo: CopySubscriptionRepository,
    private readonly executionRepo: CopyExecutionRepository,
  ) {}

  private getContext(req: any): { tenantId: string; userId: string; roles: string[] } {
    // Token tenant only; a header can never select the tenant.
    const tenantId = authTenantId(req);
    const userId = authUserIdOrNull(req);
    const roles = authRoles(req);
    if (!userId) throw new BadRequestException('userId required');
    return { tenantId, userId, roles };
  }

  private isAdmin(roles: string[]): boolean {
    return hasAdminRole(roles);
  }

  /** Owner or tenant admin sees drafts and the private strategy configuration. */
  private canSeePrivateStrategy(strategy: TraderStrategy, userId: string, roles: string[]): boolean {
    return strategy.userId === userId || this.isAdmin(roles);
  }

  /** Catalogue view for everyone else: never the trader's strategyConfig. */
  private toPublicStrategy(strategy: TraderStrategy): Omit<TraderStrategy, 'strategyConfig'> {
    const visible: Partial<TraderStrategy> = { ...strategy };
    delete visible.strategyConfig;
    return visible as Omit<TraderStrategy, 'strategyConfig'>;
  }

  /** A non-public trader profile exists only for its owner and tenant admins. */
  private async assertTraderVisible(tenantId: string, traderId: string, userId: string, roles: string[]) {
    const profile = await this.traderProfileService.getProfile(tenantId, traderId);
    if (!profile || (!profile.isPublic && profile.userId !== userId && !this.isAdmin(roles))) {
      throw new NotFoundException('Trader profile not found');
    }
    return profile;
  }

  // Trader Profile
  @Post('traders/profile')
  @RequirePermissions(Permission.STRATEGY_MANAGE)
  async createTraderProfile(@Request() req: any, @Body() dto: CreateTraderProfileDto) {
    const { tenantId, userId } = this.getContext(req);
    // Prevent client-provided verified status/performance
    const safeDto = { ...dto };
    // Do not allow client to set verificationState, followerCount, etc.
    return this.traderProfileService.createProfile({ tenantId, userId, displayName: safeDto.displayName, bio: safeDto.bio || null, avatarUrl: safeDto.avatarUrl || null, supportedVenues: safeDto.supportedVenues, supportedSymbols: safeDto.supportedSymbols, riskProfile: safeDto.riskProfile, isPublic: safeDto.isPublic });
  }

  @Get('traders/profile/me')
  @RequirePermissions(Permission.STRATEGY_READ)
  async getMyProfile(@Request() req: any) {
    const { tenantId, userId } = this.getContext(req);
    const profile = await this.traderProfileService.getProfileByUserId(tenantId, userId);
    if (!profile) throw new NotFoundException('Trader profile not found');
    return profile;
  }

  @Get('traders/:traderId/profile')
  @RequirePermissions(Permission.STRATEGY_READ)
  async getTraderProfile(@Request() req: any, @Param('traderId') traderId: string) {
    const { tenantId, userId, roles } = this.getContext(req);
    const profile = await this.assertTraderVisible(tenantId, traderId, userId, roles);

    // The visibility check above proves the caller may see this profile; this projection decides
    // what they may see of it. Returning the record itself would publish the owner's user id, the
    // tenant id and the platform's internal risk assessment to every tenant member who opened the
    // page, and `viewerIsOwner` is derived from the token rather than from any request field.
    const metrics = await this.traderProfileService.getSafePublicStatistics(tenantId, traderId);
    return toTraderProfilePublicView({ profile, viewerUserId: userId, metrics });
  }

  @Put('traders/:traderId/profile')
  @RequirePermissions(Permission.STRATEGY_MANAGE)
  async updateTraderProfile(@Request() req: any, @Param('traderId') traderId: string, @Body() dto: UpdateTraderProfileDto) {
    const { tenantId, userId } = this.getContext(req);
    const existing = await this.traderProfileService.getProfile(tenantId, traderId);
    if (!existing) throw new NotFoundException('Trader profile not found');
    if (existing.userId !== userId && !this.isAdmin(req.user?.roles || [])) throw new ForbiddenException('Not authorized');
    return this.traderProfileService.updateProfile(tenantId, traderId, dto);
  }

  @Get('traders')
  @RequirePermissions(Permission.STRATEGY_READ)
  async listTraders(@Request() req: any, @Query() query: any) {
    const { tenantId } = this.getContext(req);
    const filters = { verificationState: query.verificationState as TraderVerificationState, isFeatured: query.isFeatured ? query.isFeatured === 'true' : undefined, search: query.search, page: pageParam(query.page), limit: limitParam(query.limit, 20) };
    const { data, total } = await this.traderProfileService.listPublicProfiles(tenantId, filters);
    // Projected per entry: a public listing is read by anyone in the tenant, so each row is reduced
    // to the public shape rather than serialized as stored. Metrics are not fetched here - a list
    // view that resolved statistics per row would be one query per trader on a paged route.
    return { data: data.map((profile) => toTraderProfileListingView(profile)), total };
  }

  @Post('traders/:traderId/verify')
  @RequireAnyPermission(Permission.TENANT_UPDATE, Permission.PLATFORM_MANAGE)
  async verifyTrader(@Request() req: any, @Param('traderId') traderId: string) {
    const { tenantId, userId, roles } = this.getContext(req);
    if (!this.isAdmin(roles)) throw new ForbiddenException('Only admin can verify traders');
    const profile = await this.traderProfileService.verifyTrader(tenantId, traderId, userId);
    if (!profile) throw new NotFoundException('Trader not found');
    return profile;
  }

  // Trader Strategy
  @Post('strategies')
  @RequirePermissions(Permission.STRATEGY_MANAGE)
  async createStrategy(@Request() req: any, @Body() dto: CreateTraderStrategyDto) {
    const { tenantId, userId } = this.getContext(req);
    // Prevent client-provided verified status/performance/execution result
    return this.traderStrategyService.createStrategy({ tenantId, traderId: dto.traderId, userId, name: dto.name, description: dto.description || null, type: dto.type, supportedSymbols: dto.supportedSymbols, supportedVenues: dto.supportedVenues, riskProfile: dto.riskProfile, feePolicy: dto.feePolicy, strategyConfig: dto.strategyConfig, idempotencyKey: dto.idempotencyKey || null });
  }

  @Get('strategies/:strategyId')
  @RequirePermissions(Permission.STRATEGY_READ)
  async getStrategy(@Request() req: any, @Param('strategyId') strategyId: string) {
    const { tenantId, userId, roles } = this.getContext(req);
    const strategy = await this.traderStrategyService.getStrategy(tenantId, strategyId);
    if (!strategy) throw new NotFoundException('Strategy not found');
    if (this.canSeePrivateStrategy(strategy, userId, roles)) return strategy;
    if (!PUBLIC_STRATEGY_STATUSES.includes(strategy.status)) throw new NotFoundException('Strategy not found');
    return this.toPublicStrategy(strategy);
  }

  @Get('strategies')
  @RequirePermissions(Permission.STRATEGY_READ)
  async listStrategies(@Request() req: any, @Query() query: TraderStrategyFilterDto) {
    const { tenantId, roles } = this.getContext(req);
    const filters = { status: query.status as any, traderId: query.traderId, page: pageParam(query.page), limit: limitParam(query.limit, 20) };
    if (this.isAdmin(roles)) return this.traderStrategyService.listByTenant(tenantId, filters);
    const result = await this.traderStrategyService.listByTenant(tenantId, { ...filters, statuses: PUBLIC_STRATEGY_STATUSES });
    return { ...result, data: result.data.map((strategy) => this.toPublicStrategy(strategy)) };
  }

  @Get('traders/:traderId/strategies')
  @RequirePermissions(Permission.STRATEGY_READ)
  async listTraderStrategies(@Request() req: any, @Param('traderId') traderId: string, @Query() query: any) {
    const { tenantId, userId, roles } = this.getContext(req);
    const filters = { status: query.status, page: pageParam(query.page), limit: limitParam(query.limit, 20) };
    const profile = await this.traderProfileService.getProfile(tenantId, traderId);
    if (profile && (profile.userId === userId || this.isAdmin(roles))) return this.traderStrategyService.listByTrader(tenantId, traderId, filters);
    const result = await this.traderStrategyService.listByTrader(tenantId, traderId, { ...filters, statuses: PUBLIC_STRATEGY_STATUSES });
    return { ...result, data: result.data.map((strategy) => this.toPublicStrategy(strategy)) };
  }

  @Put('strategies/:strategyId')
  @RequirePermissions(Permission.STRATEGY_MANAGE)
  async updateStrategy(@Request() req: any, @Param('strategyId') strategyId: string, @Body() dto: UpdateTraderStrategyDto) {
    const { tenantId, userId } = this.getContext(req);
    const updated = await this.traderStrategyService.updateStrategy(tenantId, strategyId, userId, dto);
    if (!updated) throw new NotFoundException('Strategy not found');
    return updated;
  }

  @Post('strategies/:strategyId/publish')
  @RequirePermissions(Permission.STRATEGY_MANAGE)
  async publishStrategy(@Request() req: any, @Param('strategyId') strategyId: string) {
    const { tenantId, userId } = this.getContext(req);
    return this.traderStrategyService.publishStrategy(tenantId, strategyId, userId, userId);
  }

  @Post('strategies/:strategyId/pause')
  @RequirePermissions(Permission.STRATEGY_MANAGE)
  async pauseStrategy(@Request() req: any, @Param('strategyId') strategyId: string) {
    const { tenantId, userId } = this.getContext(req);
    const paused = await this.traderStrategyService.pauseStrategy(tenantId, strategyId, userId, userId);
    if (!paused) throw new NotFoundException('Strategy not found');
    return paused;
  }

  @Post('strategies/:strategyId/resume')
  @RequirePermissions(Permission.STRATEGY_MANAGE)
  async resumeStrategy(@Request() req: any, @Param('strategyId') strategyId: string) {
    const { tenantId, userId } = this.getContext(req);
    const resumed = await this.traderStrategyService.resumeStrategy(tenantId, strategyId, userId, userId);
    if (!resumed) throw new NotFoundException('Strategy not found');
    return resumed;
  }

  @Post('strategies/:strategyId/archive')
  @RequirePermissions(Permission.STRATEGY_MANAGE)
  async archiveStrategy(@Request() req: any, @Param('strategyId') strategyId: string) {
    const { tenantId, userId } = this.getContext(req);
    const archived = await this.traderStrategyService.archiveStrategy(tenantId, strategyId, userId, userId);
    if (!archived) throw new NotFoundException('Strategy not found');
    return archived;
  }

  // Follower Subscription
  @Post('subscriptions')
  @RequirePermissions(Permission.COPY_SUBSCRIPTION_MANAGE)
  async createSubscription(@Request() req: any, @Body() dto: CreateFollowerSubscriptionDto) {
    const { tenantId, userId } = this.getContext(req);
    // Prevent client-provided execution result
    return this.followerSubscriptionService.subscribe({ tenantId, followerId: userId, traderId: dto.traderId, strategyId: dto.strategyId, allocationMode: dto.allocationMode, allocationAmount: dto.allocationAmount, maxAllocation: dto.maxAllocation || null, minAllocation: dto.minAllocation || null, copyPolicy: dto.copyPolicy, riskPolicy: dto.riskPolicy, followerAccountId: dto.followerAccountId || null, idempotencyKey: dto.idempotencyKey || null, actorId: userId, requestId: req.headers['x-request-id'] });
  }

  @Get('subscriptions/me')
  @RequirePermissions(Permission.COPY_SUBSCRIPTION_READ)
  async listMySubscriptions(@Request() req: any, @Query() query: FollowerSubscriptionFilterDto) {
    const { tenantId, userId } = this.getContext(req);
    return this.subscriptionRepo.listByFollower(tenantId, userId, { state: query.state as any, page: pageParam(query.page), limit: limitParam(query.limit, 20) });
  }

  @Get('subscriptions/:subscriptionId')
  @RequirePermissions(Permission.COPY_SUBSCRIPTION_READ)
  async getSubscription(@Request() req: any, @Param('subscriptionId') subscriptionId: string) {
    const { tenantId, userId, roles } = this.getContext(req);
    const sub = await this.subscriptionRepo.findById(subscriptionId, tenantId);
    if (!sub) throw new NotFoundException('Subscription not found');
    if (sub.followerId !== userId && sub.traderId !== userId && !this.isAdmin(roles)) {
      // Check if trader profile belongs to user
      const traderProfile = await this.traderProfileService.getProfile(tenantId, sub.traderId);
      if (!traderProfile || traderProfile.userId !== userId) throw new ForbiddenException('Not authorized');
    }
    return sub;
  }

  @Put('subscriptions/:subscriptionId')
  @RequirePermissions(Permission.COPY_SUBSCRIPTION_MANAGE)
  async updateSubscription(
    @Request() req: any,
    @Param('subscriptionId') subscriptionId: string,
    @Body() dto: UpdateFollowerSubscriptionDto,
  ) {
    const { tenantId, userId, roles } = this.getContext(req);
    const requestId = req?.headers?.['x-request-id'] || req?.id;
    const updated = await this.followerSubscriptionService.updateSubscriptionSettings(
      tenantId,
      subscriptionId,
      dto,
      userId,
      this.isAdmin(roles) ? null : userId,
      requestId,
    );
    if (!updated) throw new NotFoundException('Subscription not found');
    return updated;
  }

  @Get('subscriptions/:subscriptionId/reconciliation-status')
  @RequirePermissions(Permission.COPY_SUBSCRIPTION_READ)
  async getSubscriptionReconciliationStatus(
    @Request() req: any,
    @Param('subscriptionId') subscriptionId: string,
  ) {
    const { tenantId, userId, roles } = this.getContext(req);
    const status = await this.reconciliationService.getCustomerSubscriptionStatus(
      tenantId,
      subscriptionId,
      this.isAdmin(roles) ? null : userId,
    );
    if (!status) throw new NotFoundException('Subscription not found');
    return status;
  }

  @Get('traders/:traderId/subscriptions')
  @RequirePermissions(Permission.COPY_SUBSCRIPTION_READ)
  async listTraderSubscriptions(@Request() req: any, @Param('traderId') traderId: string, @Query() query: any) {
    const { tenantId, userId, roles } = this.getContext(req);
    const profile = await this.traderProfileService.getProfile(tenantId, traderId);
    if (!profile) throw new NotFoundException('Trader not found');
    if (profile.userId !== userId && !this.isAdmin(roles)) throw new ForbiddenException('Not authorized to view trader subscriptions');
    return this.subscriptionRepo.listByTrader(tenantId, traderId, { state: query.state, page: pageParam(query.page), limit: limitParam(query.limit, 20) });
  }

  @Post('subscriptions/:subscriptionId/pause')
  @RequirePermissions(Permission.COPY_SUBSCRIPTION_MANAGE)
  async pauseSubscription(@Request() req: any, @Param('subscriptionId') subscriptionId: string) {
    const { tenantId, userId } = this.getContext(req);
    const paused = await this.followerSubscriptionService.pauseSubscription(tenantId, subscriptionId, userId, userId, req.headers['x-request-id']);
    if (!paused) throw new NotFoundException('Subscription not found');
    return paused;
  }

  @Post('subscriptions/:subscriptionId/resume')
  @RequirePermissions(Permission.COPY_SUBSCRIPTION_MANAGE)
  async resumeSubscription(@Request() req: any, @Param('subscriptionId') subscriptionId: string) {
    const { tenantId, userId } = this.getContext(req);
    const resumed = await this.followerSubscriptionService.resumeSubscription(tenantId, subscriptionId, userId, userId, req.headers['x-request-id']);
    if (!resumed) throw new NotFoundException('Subscription not found');
    return resumed;
  }

  @Post('subscriptions/:subscriptionId/stop')
  @RequirePermissions(Permission.COPY_SUBSCRIPTION_MANAGE)
  async stopSubscription(@Request() req: any, @Param('subscriptionId') subscriptionId: string) {
    const { tenantId, userId } = this.getContext(req);
    const stopped = await this.followerSubscriptionService.stopCopy(tenantId, subscriptionId, userId, userId, req.headers['x-request-id']);
    if (!stopped) throw new NotFoundException('Subscription not found');
    return stopped;
  }

  @Delete('subscriptions/:subscriptionId')
  @RequirePermissions(Permission.COPY_SUBSCRIPTION_MANAGE)
  async cancelSubscription(@Request() req: any, @Param('subscriptionId') subscriptionId: string) {
    const { tenantId, userId } = this.getContext(req);
    const cancelled = await this.followerSubscriptionService.cancelSubscription(tenantId, subscriptionId, userId, userId, req.headers['x-request-id']);
    if (!cancelled) throw new NotFoundException('Subscription not found');
    return cancelled;
  }

  // Copy Execution
  @Post('executions/leader-event')
  @RequirePermissions(Permission.STRATEGY_MANAGE)
  async processLeaderEvent(@Request() req: any, @Body() dto: LeaderEventDto & { traderId: string; strategyId: string }) {
    const { tenantId, userId, roles } = this.getContext(req);
    // Only trader or system can submit leader events
    const strategy = await this.traderStrategyService.getStrategy(tenantId, dto.strategyId);
    if (!strategy) throw new NotFoundException('Strategy not found');
    if (strategy.userId !== userId && !this.isAdmin(roles)) throw new ForbiddenException('Only strategy owner can submit leader events');
    // The trader is the strategy's trader, never a value from the body: a
    // mismatching traderId would attribute the event (and its compliance
    // check) to someone else.
    const traderId = strategy.traderId;
    if (!traderId) throw new NotFoundException('Strategy has no trader');
    if (dto.traderId && dto.traderId !== traderId) throw new BadRequestException('traderId does not match the strategy');

    const leaderEvent = {
      eventId: dto.eventId,
      orderId: dto.orderId || null,
      fillId: dto.fillId || null,
      symbol: dto.symbol,
      exchangeSymbol: dto.exchangeSymbol,
      side: dto.side,
      type: dto.type,
      quantity: dto.quantity,
      price: dto.price || null,
      stopPrice: dto.stopPrice || null,
      venue: dto.venue,
      timestamp: dto.timestamp,
      isSimulated: dto.isSimulated || false,
    };

    return this.copyExecutionService.processLeaderEvent({ tenantId, leaderEvent, traderId, strategyId: dto.strategyId, actorId: userId });
  }

  @Get('executions/:executionId')
  @RequirePermissions(Permission.COPY_SUBSCRIPTION_READ)
  async getExecution(@Request() req: any, @Param('executionId') executionId: string) {
    const { tenantId, userId, roles } = this.getContext(req);
    const exec = await this.executionRepo.findById(executionId, tenantId);
    if (!exec) throw new NotFoundException('Execution not found');
    if (exec.followerId !== userId && exec.traderId !== userId && !this.isAdmin(roles)) {
      const traderProfile = await this.traderProfileService.getProfile(tenantId, exec.traderId);
      if (!traderProfile || traderProfile.userId !== userId) throw new ForbiddenException('Not authorized');
    }
    return exec;
  }

  @Get('executions')
  @RequirePermissions(Permission.COPY_SUBSCRIPTION_READ)
  async listExecutions(@Request() req: any, @Query() query: CopyExecutionFilterDto) {
    const { tenantId, userId } = this.getContext(req);
    // For follower, list own executions
    return this.executionRepo.listByFollower(tenantId, userId, { status: query.status as any, page: pageParam(query.page), limit: limitParam(query.limit, 20) });
  }

  @Get('subscriptions/:subscriptionId/executions')
  @RequirePermissions(Permission.COPY_SUBSCRIPTION_READ)
  async listSubscriptionExecutions(@Request() req: any, @Param('subscriptionId') subscriptionId: string, @Query() query: any) {
    const { tenantId, userId, roles } = this.getContext(req);
    const sub = await this.subscriptionRepo.findById(subscriptionId, tenantId);
    if (!sub) throw new NotFoundException('Subscription not found');
    if (sub.followerId !== userId && sub.traderId !== userId && !this.isAdmin(roles)) {
      const traderProfile = await this.traderProfileService.getProfile(tenantId, sub.traderId);
      if (!traderProfile || traderProfile.userId !== userId) throw new ForbiddenException('Not authorized');
    }
    return this.executionRepo.listBySubscription(tenantId, subscriptionId, { status: query.status, page: pageParam(query.page), limit: limitParam(query.limit, 20) });
  }

  // Policy
  @Get('policies/effective')
  @RequirePermissions(Permission.STRATEGY_READ)
  async getEffectivePolicy(@Request() req: any, @Query() query: { strategyId?: string; subscriptionId?: string }) {
    const { tenantId } = this.getContext(req);
    return this.copyPolicyService.resolveEffectivePolicy({ tenantId, strategyId: query.strategyId, subscriptionId: query.subscriptionId });
  }

  @Get('policies/platform')
  @RequirePermissions(Permission.STRATEGY_READ)
  async getPlatformPolicy(@Request() req: any) {
    this.getContext(req);
    return this.copyPolicyService.getPlatformPolicy();
  }

  // Performance & Ranking
  @Get('traders/:traderId/performance')
  @RequirePermissions(Permission.STRATEGY_READ)
  async getTraderPerformance(@Request() req: any, @Param('traderId') traderId: string) {
    const { tenantId, userId, roles } = this.getContext(req);
    await this.assertTraderVisible(tenantId, traderId, userId, roles);
    const perf = await this.traderPerformanceService.getPerformance(tenantId, traderId);
    if (!perf) throw new NotFoundException('Trader not found');
    return perf;
  }

  @Get('rankings')
  @RequirePermissions(Permission.STRATEGY_READ)
  async getRankings(@Request() req: any, @Query() query: any) {
    const { tenantId } = this.getContext(req);
    // `timeframe` is forwarded. The service accepted it, defaulted it, and reported it back in the
    // response's methodology - but the route never passed it on, so the ranking window was either
    // the default or whatever an unrecognised value happened to fall back to, and the response's
    // own `timeframe` field described a window the caller had not asked for.
    return this.traderRankingService.getRanking(tenantId, { verificationState: query.verificationState, isFeatured: query.isFeatured ? query.isFeatured === 'true' : undefined, search: query.search, page: pageParam(query.page), limit: limitParam(query.limit, 20), sortBy: query.sortBy, timeframe: query.timeframe });
  }

  @Get('rankings/featured')
  @RequirePermissions(Permission.STRATEGY_READ)
  async getFeatured(@Request() req: any, @Query() query: any) {
    const { tenantId } = this.getContext(req);
    return this.traderRankingService.getFeaturedTraders(tenantId, limitParam(query.limit, 10));
  }

  // Reconciliation
  @Post('reconciliation/run')
  @RequirePermissions(Permission.RECONCILIATION_TRIGGER)
  async runReconciliation(@Request() req: any, @Body() body: { strategyId?: string; from?: string; to?: string; limit?: number }) {
    const { tenantId, roles } = this.getContext(req);
    if (!this.isAdmin(roles)) throw new ForbiddenException('Only admin can run reconciliation');
    return this.reconciliationService.reconcileTenant(tenantId, { strategyId: body.strategyId, from: body.from ? new Date(body.from) : undefined, to: body.to ? new Date(body.to) : undefined, limit: body.limit });
  }

  @Get('reconciliation/records')
  @RequireAnyPermission(Permission.RECONCILIATION_TRIGGER, Permission.RECONCILIATION_RESOLVE)
  async listReconciliationRecords(@Request() req: any, @Query() query: any) {
    const { tenantId, roles } = this.getContext(req);
    if (!this.isAdmin(roles)) throw new ForbiddenException('Only admin can view reconciliation');
    return this.reconciliationService.listRecords(tenantId, { resolved: query.resolved !== undefined ? query.resolved === 'true' : undefined, category: query.category, severity: query.severity, page: pageParam(query.page), limit: limitParam(query.limit, 20) });
  }

  @Post('reconciliation/:recordId/resolve')
  @RequirePermissions(Permission.RECONCILIATION_RESOLVE)
  async resolveReconciliation(@Request() req: any, @Param('recordId') recordId: string, @Body() body: { notes?: string }) {
    const { tenantId, userId, roles } = this.getContext(req);
    if (!this.isAdmin(roles)) throw new ForbiddenException('Only admin can resolve reconciliation');
    const resolved = await this.reconciliationService.resolveRecord(tenantId, recordId, userId, body.notes);
    if (!resolved) throw new NotFoundException('Record not found');
    return resolved;
  }
}

