import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { CopySizingMode, isDecimalString, compareDecimalStrings } from './copy-trading.types';

/**
 * Manages follower capital/allocation policy, percentage/fixed allocation, maximum exposure, allocation bounds, and available-capital validation from canonical account data.
 * All values must come from canonical follower exchange-account/balance data. Do not trust frontend balances. Precision must be safe.
 */
@Injectable()
export class FollowerAllocationService {
  private readonly logger = new Logger(FollowerAllocationService.name);

  constructor(private readonly prisma: PrismaService) {}

  async validateAllocation(input: {
    tenantId: string;
    followerId: string;
    followerAccountId: string | null;
    allocationMode: CopySizingMode;
    allocationAmount: string;
    maxAllocation?: string | null;
    minAllocation?: string | null;
  }): Promise<{ valid: boolean; availableBalance: string | null; reason?: string }> {
    if (!isDecimalString(input.allocationAmount)) {
      return { valid: false, availableBalance: null, reason: 'allocationAmount must be valid decimal string' };
    }

    if (compareDecimalStrings(input.allocationAmount, '0') <= 0) {
      return { valid: false, availableBalance: null, reason: 'allocationAmount must be positive' };
    }

    if (input.maxAllocation && !isDecimalString(input.maxAllocation)) {
      return { valid: false, availableBalance: null, reason: 'maxAllocation must be valid decimal string' };
    }

    if (input.minAllocation && !isDecimalString(input.minAllocation)) {
      return { valid: false, availableBalance: null, reason: 'minAllocation must be valid decimal string' };
    }

    if (input.maxAllocation && compareDecimalStrings(input.allocationAmount, input.maxAllocation) > 0) {
      return { valid: false, availableBalance: null, reason: 'allocationAmount exceeds maxAllocation' };
    }

    if (input.minAllocation && compareDecimalStrings(input.allocationAmount, input.minAllocation) < 0) {
      return { valid: false, availableBalance: null, reason: 'allocationAmount below minAllocation' };
    }

    // All values must come from canonical follower exchange-account/balance data - do not trust frontend balances
    let availableBalance: string | null = null;

    if (input.followerAccountId) {
      try {
        const account = await this.prisma.tradingAccount.findFirst({ where: { id: input.followerAccountId, tenantId: input.tenantId, userId: input.followerId, deletedAt: null } });
        if (!account) {
          return { valid: false, availableBalance: null, reason: 'Follower account not found or not owned by follower' };
        }

        // Get canonical balances from AccountBalanceSnapshot
        const balances = await this.prisma.accountBalanceSnapshot.findMany({ where: { accountId: input.followerAccountId, tenantId: input.tenantId } });

        // For simplicity, assume USDT or USD as quote - sum free balances
        // In real implementation, would check specific asset
        let totalFree = '0';
        for (const b of balances) {
          try {
            const free = b.free.toString();
            if (isDecimalString(free)) {
              // Add using string addition preserving precision
              const [aInt, aDec = ''] = totalFree.split('.');
              const [bInt, bDec = ''] = free.split('.');
              const maxDec = Math.max(aDec.length, bDec.length);
              const aFull = BigInt((aInt || '0') + aDec.padEnd(maxDec, '0'));
              const bFull = BigInt((bInt || '0') + bDec.padEnd(maxDec, '0'));
              const sum = aFull + bFull;
              const sumStr = sum.toString().padStart(maxDec + 1, '0');
              if (maxDec === 0) totalFree = sumStr;
              else {
                const intPart = sumStr.slice(0, -maxDec) || '0';
                const decPart = sumStr.slice(-maxDec).replace(/0+$/, '');
                totalFree = decPart ? `${intPart}.${decPart}` : intPart;
              }
            }
          } catch {}
        }

        availableBalance = totalFree;

        // For percentage mode, allocationAmount is percentage (e.g. 10 for 10%)
        if (input.allocationMode === CopySizingMode.PERCENTAGE_BALANCE) {
          const percent = parseFloat(input.allocationAmount);
          if (isNaN(percent) || percent <= 0 || percent > 100) {
            return { valid: false, availableBalance, reason: 'Percentage allocation must be between 0 and 100' };
          }
          // Validate percentage does not exceed available
          // We don't need to check exact amount here, just that available >0
          if (compareDecimalStrings(availableBalance, '0') <= 0) {
            return { valid: false, availableBalance, reason: 'No available balance for percentage allocation' };
          }
        } else {
          // Fixed or proportional - check allocationAmount <= availableBalance
          if (availableBalance && compareDecimalStrings(input.allocationAmount, availableBalance) > 0) {
            return { valid: false, availableBalance, reason: `Allocation ${input.allocationAmount} exceeds available balance ${availableBalance}` };
          }
        }
      } catch (e: any) {
        this.logger.warn(`Failed to validate allocation from canonical data tenant=${input.tenantId} follower=${input.followerId} error=${e.message}`);
        return { valid: false, availableBalance: null, reason: 'Failed to validate from canonical balance data' };
      }
    } else {
      // No account provided - warn but allow? Per spec, allocation should use canonical data, so if no account, we cannot validate
      this.logger.warn(`No follower account provided for allocation validation tenant=${input.tenantId} follower=${input.followerId}`);
      // For draft subscriptions without account yet, allow but mark available as null
      availableBalance = null;
    }

    return { valid: true, availableBalance };
  }

  async getAvailableBalance(tenantId: string, followerId: string, followerAccountId: string): Promise<string> {
    const balances = await this.prisma.accountBalanceSnapshot.findMany({ where: { tenantId, accountId: followerAccountId } });
    let totalFree = '0';
    for (const b of balances) {
      try {
        const free = b.free.toString();
        const [aInt, aDec = ''] = totalFree.split('.');
        const [bInt, bDec = ''] = free.split('.');
        const maxDec = Math.max(aDec.length, bDec.length);
        const aFull = BigInt((aInt || '0') + aDec.padEnd(maxDec, '0'));
        const bFull = BigInt((bInt || '0') + bDec.padEnd(maxDec, '0'));
        const sum = aFull + bFull;
        const sumStr = sum.toString().padStart(maxDec + 1, '0');
        if (maxDec === 0) totalFree = sumStr;
        else {
          const intPart = sumStr.slice(0, -maxDec) || '0';
          const decPart = sumStr.slice(-maxDec).replace(/0+$/, '');
          totalFree = decPart ? `${intPart}.${decPart}` : intPart;
        }
      } catch {}
    }
    return totalFree;
  }

  calculateProportionalAllocation(leaderNotional: string, followerAllocation: string, leaderTotalBalance: string): string {
    // proportional = leaderNotional * (followerAllocation / leaderTotalBalance) - Decimal-safe
    // For simplicity, use integer arithmetic with 8 decimals
    try {
      const scale = 8;
      const parse = (s: string): bigint => {
        const [intPart, decPart = ''] = s.split('.');
        const padded = decPart.padEnd(scale, '0').slice(0, scale);
        return BigInt((intPart || '0') + padded);
      };
      const leaderNotionalBig = parse(leaderNotional);
      const followerAllocBig = parse(followerAllocation);
      const leaderTotalBig = parse(leaderTotalBalance);

      if (leaderTotalBig === BigInt(0)) return '0';

      const result = (leaderNotionalBig * followerAllocBig) / leaderTotalBig;
      const resultStr = result.toString().padStart(scale + 1, '0');
      const intPart = resultStr.slice(0, -scale) || '0';
      const decPart = resultStr.slice(-scale).replace(/0+$/, '');
      return decPart ? `${intPart}.${decPart}` : intPart;
    } catch {
      return '0';
    }
  }
}

// # Enforces follower-specific risk rules, notional caps, symbol filters, and emergency stop-copy decisions
// # Enforces follower leverage caps and margin requirement checks
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import {
  CopyPolicy,
  CopyRiskDecision,
  FollowerRiskPolicy,
  isDecimalString,
  compareDecimalStrings,
  matchesAnySymbolRule,
} from './copy-trading.types';

export interface RiskCheckInput {
  tenantId: string;
  followerId: string;
  subscriptionId: string;
  traderId: string;
  followerAccountId: string | null;
  symbol: string;
  side: string;
  quantity: string;
  price: string | null;
  notional: string | null;
  riskPolicy: FollowerRiskPolicy;
  copyPolicy?: Partial<CopyPolicy> | null;
  currentExposure?: string | null;
  dailyLoss?: string | null;
  totalLoss?: string | null;
  currentDrawdown?: string | null;
  dailyNotionalUsed?: string | null;
  concurrentOpenCopies?: number | null;
  requestedLeverage?: string | null;
  marginMode?: string | null;
  availableMarginRatio?: string | null;
}

export interface RiskCheckResult {
  decision: CopyRiskDecision;
  allowed: boolean;
  ruleId: string | null;
  reason: string | null;
  reducedQuantity?: string | null;
}

/**
 * Applies follower-specific risk rules: max loss, max drawdown, max exposure, daily limits, stop-copy conditions, concentration, leverage/margin constraints, and emergency pause.
 * Risk decision states: ALLOW, REDUCE, BLOCK, PAUSE, STOP_COPY. Every rejection must identify its policy/rule.
 */
@Injectable()
export class FollowerRiskService {
  private readonly logger = new Logger(FollowerRiskService.name);

  constructor(private readonly prisma: PrismaService) {}

  async checkRisk(input: RiskCheckInput): Promise<RiskCheckResult> {
    const policy = input.riskPolicy;
    const copyPolicy = input.copyPolicy ?? null;

    // Emergency stop-copy
    if (policy.emergencyStopCopy) {
      return { decision: CopyRiskDecision.STOP_COPY, allowed: false, ruleId: 'EMERGENCY_STOP_COPY', reason: 'Emergency stop-copy triggered' };
    }

    // Copy policy symbol, side, and notional enforcement when provided
    if (copyPolicy) {
      if (matchesAnySymbolRule(copyPolicy.blockedSymbols, input.symbol)) {
        return {
          decision: CopyRiskDecision.BLOCK,
          allowed: false,
          ruleId: 'BLOCKED_SYMBOL',
          reason: `Symbol ${input.symbol} is blocked by copy policy`,
        };
      }
      if (Array.isArray(copyPolicy.allowedSymbols) && copyPolicy.allowedSymbols.length > 0 && !matchesAnySymbolRule(copyPolicy.allowedSymbols, input.symbol)) {
        return {
          decision: CopyRiskDecision.BLOCK,
          allowed: false,
          ruleId: 'UNALLOWED_SYMBOL',
          reason: `Symbol ${input.symbol} is not in allowedSymbols`,
        };
      }
      if (Array.isArray(copyPolicy.allowedSides) && copyPolicy.allowedSides.length > 0 && !copyPolicy.allowedSides.includes(input.side)) {
        return {
          decision: CopyRiskDecision.BLOCK,
          allowed: false,
          ruleId: 'UNALLOWED_SIDE',
          reason: `Side ${input.side} is not in allowedSides`,
        };
      }
      if (copyPolicy.maxOrderNotional && input.notional) {
        if (!isDecimalString(copyPolicy.maxOrderNotional) || !isDecimalString(input.notional)) {
          return { decision: CopyRiskDecision.BLOCK, allowed: false, ruleId: 'INVALID_DECIMAL', reason: 'Invalid decimal for order notional check - fail closed' };
        }
        if (compareDecimalStrings(input.notional, copyPolicy.maxOrderNotional) > 0) {
          return {
            decision: CopyRiskDecision.BLOCK,
            allowed: false,
            ruleId: 'MAX_ORDER_NOTIONAL',
            reason: `Order notional ${input.notional} exceeds maxOrderNotional ${copyPolicy.maxOrderNotional}`,
          };
        }
      }
      if (copyPolicy.maxDailyNotional && input.dailyNotionalUsed && input.notional) {
        if (!isDecimalString(copyPolicy.maxDailyNotional) || !isDecimalString(input.dailyNotionalUsed) || !isDecimalString(input.notional)) {
          return { decision: CopyRiskDecision.BLOCK, allowed: false, ruleId: 'INVALID_DECIMAL', reason: 'Invalid decimal for daily notional check - fail closed' };
        }
        const projectedDaily = this.addDecimals(input.dailyNotionalUsed, input.notional);
        if (compareDecimalStrings(projectedDaily, copyPolicy.maxDailyNotional) > 0) {
          return {
            decision: CopyRiskDecision.BLOCK,
            allowed: false,
            ruleId: 'MAX_DAILY_NOTIONAL',
            reason: `Projected daily notional ${projectedDaily} exceeds maxDailyNotional ${copyPolicy.maxDailyNotional}`,
          };
        }
      }
      if (copyPolicy.maxConcurrentCopies !== null && copyPolicy.maxConcurrentCopies !== undefined && input.concurrentOpenCopies !== null && input.concurrentOpenCopies !== undefined) {
        if (input.concurrentOpenCopies >= copyPolicy.maxConcurrentCopies) {
          return {
            decision: CopyRiskDecision.BLOCK,
            allowed: false,
            ruleId: 'MAX_CONCURRENT_COPIES',
            reason: `Concurrent open copies ${input.concurrentOpenCopies} reaches max ${copyPolicy.maxConcurrentCopies}`,
          };
        }
      }
    }

    // Leverage cap enforcement (GAP-16)
    const maxLeverageCap = policy.maxLeverage ?? copyPolicy?.maxLeverage ?? null;
    if (maxLeverageCap && input.requestedLeverage) {
      if (!isDecimalString(maxLeverageCap) || !isDecimalString(input.requestedLeverage)) {
        return {
          decision: CopyRiskDecision.BLOCK,
          allowed: false,
          ruleId: 'INVALID_LEVERAGE_DECIMAL',
          reason: 'Invalid leverage decimal string - fail closed',
        };
      }
      if (compareDecimalStrings(input.requestedLeverage, maxLeverageCap) > 0) {
        return {
          decision: CopyRiskDecision.BLOCK,
          allowed: false,
          ruleId: 'MAX_LEVERAGE',
          reason: `Requested leverage ${input.requestedLeverage}x exceeds follower max leverage ${maxLeverageCap}x`,
        };
      }
    }

    if (copyPolicy?.leveragePolicy === 'SPOT_ONLY' && input.requestedLeverage && isDecimalString(input.requestedLeverage)) {
      if (compareDecimalStrings(input.requestedLeverage, '1') > 0) {
        return {
          decision: CopyRiskDecision.BLOCK,
          allowed: false,
          ruleId: 'SPOT_ONLY_LEVERAGE_FORBIDDEN',
          reason: `Leverage ${input.requestedLeverage}x is forbidden under SPOT_ONLY leverage policy`,
        };
      }
    }

    // Margin mode constraint enforcement (GAP-16)
    if (Array.isArray(policy.allowedMarginModes) && policy.allowedMarginModes.length > 0 && input.marginMode) {
      const normalizedAllowed = policy.allowedMarginModes.map((m) => m.toUpperCase());
      if (!normalizedAllowed.includes(input.marginMode.toUpperCase())) {
        return {
          decision: CopyRiskDecision.BLOCK,
          allowed: false,
          ruleId: 'UNSUPPORTED_MARGIN_MODE',
          reason: `Margin mode ${input.marginMode} is not permitted (${normalizedAllowed.join(', ')})`,
        };
      }
    }

    // Minimum margin ratio check (GAP-16)
    if (policy.minMarginRatio && input.availableMarginRatio) {
      if (!isDecimalString(policy.minMarginRatio) || !isDecimalString(input.availableMarginRatio)) {
        return {
          decision: CopyRiskDecision.BLOCK,
          allowed: false,
          ruleId: 'INVALID_MARGIN_DECIMAL',
          reason: 'Invalid margin ratio decimal string - fail closed',
        };
      }
      if (compareDecimalStrings(input.availableMarginRatio, policy.minMarginRatio) < 0) {
        return {
          decision: CopyRiskDecision.BLOCK,
          allowed: false,
          ruleId: 'INSUFFICIENT_MARGIN_RATIO',
          reason: `Available margin ratio ${input.availableMarginRatio} is below required ${policy.minMarginRatio}`,
        };
      }
    }

    // Max daily loss - fail closed where required
    if (policy.maxDailyLoss && input.dailyLoss) {
      if (!isDecimalString(policy.maxDailyLoss) || !isDecimalString(input.dailyLoss)) {
        return { decision: CopyRiskDecision.BLOCK, allowed: false, ruleId: 'INVALID_DECIMAL', reason: 'Invalid decimal for loss check - fail closed' };
      }
      if (compareDecimalStrings(input.dailyLoss, policy.maxDailyLoss) >= 0) {
        return { decision: CopyRiskDecision.BLOCK, allowed: false, ruleId: 'MAX_DAILY_LOSS', reason: `Daily loss ${input.dailyLoss} exceeds max ${policy.maxDailyLoss}` };
      }
    }

    // Max total loss
    if (policy.maxTotalLoss && input.totalLoss) {
      if (compareDecimalStrings(input.totalLoss, policy.maxTotalLoss) >= 0) {
        return { decision: CopyRiskDecision.STOP_COPY, allowed: false, ruleId: 'MAX_TOTAL_LOSS', reason: `Total loss ${input.totalLoss} exceeds max ${policy.maxTotalLoss}` };
      }
    }

    // Max drawdown
    if (policy.maxDrawdown && input.currentDrawdown) {
      if (compareDecimalStrings(input.currentDrawdown, policy.maxDrawdown) >= 0) {
        return { decision: CopyRiskDecision.PAUSE, allowed: false, ruleId: 'MAX_DRAWDOWN', reason: `Drawdown ${input.currentDrawdown} exceeds max ${policy.maxDrawdown}` };
      }
    }

    // Max exposure
    if (policy.maxExposure && input.currentExposure) {
      if (compareDecimalStrings(input.currentExposure, policy.maxExposure) >= 0) {
        return { decision: CopyRiskDecision.BLOCK, allowed: false, ruleId: 'MAX_EXPOSURE', reason: `Exposure ${input.currentExposure} exceeds max ${policy.maxExposure}` };
      }
      // Check if new order would exceed exposure
      if (input.notional) {
        const newExposure = this.addDecimals(input.currentExposure, input.notional);
        if (compareDecimalStrings(newExposure, policy.maxExposure) > 0) {
          // Try to reduce quantity
          const allowedNotional = this.subtractDecimals(policy.maxExposure, input.currentExposure);
          if (compareDecimalStrings(allowedNotional, '0') <= 0) {
            return { decision: CopyRiskDecision.BLOCK, allowed: false, ruleId: 'MAX_EXPOSURE', reason: `New exposure ${newExposure} would exceed max ${policy.maxExposure}` };
          }
          // Calculate reduced quantity proportionally
          const reduceRatio = parseFloat(allowedNotional) / parseFloat(input.notional);
          const reducedQty = (parseFloat(input.quantity) * reduceRatio).toString();
          return { decision: CopyRiskDecision.REDUCE, allowed: true, ruleId: 'MAX_EXPOSURE_REDUCE', reason: `Reducing quantity to fit max exposure`, reducedQuantity: reducedQty };
        }
      }
    }

    // Max position size
    if (policy.maxPositionSize) {
      if (compareDecimalStrings(input.quantity, policy.maxPositionSize) > 0) {
        return { decision: CopyRiskDecision.REDUCE, allowed: true, ruleId: 'MAX_POSITION_SIZE', reason: `Quantity ${input.quantity} exceeds max position size ${policy.maxPositionSize}`, reducedQuantity: policy.maxPositionSize };
      }
    }

    // Max symbol exposure
    if (policy.maxSymbolExposure) {
      try {
        const symbolPositions = await this.prisma.position.findMany({ where: { tenantId: input.tenantId, accountId: input.followerAccountId || undefined, symbol: input.symbol } });
        let symbolQty = '0';
        for (const p of symbolPositions) {
          symbolQty = this.addDecimals(symbolQty, p.quantity.toString());
        }
        const newSymbolQty = this.addDecimals(symbolQty, input.quantity);
        if (compareDecimalStrings(newSymbolQty, policy.maxSymbolExposure) > 0) {
          return { decision: CopyRiskDecision.BLOCK, allowed: false, ruleId: 'MAX_SYMBOL_EXPOSURE', reason: `Symbol exposure ${newSymbolQty} exceeds max ${policy.maxSymbolExposure} for ${input.symbol}` };
        }
      } catch (e) {
        return this.ruleUnavailable('MAX_SYMBOL_EXPOSURE', e);
      }
    }

    // Maximum copy count
    if (policy.maxCopyCount) {
      try {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const copyCount = await (this.prisma as any).copyExecution?.count({ where: { tenantId: input.tenantId, subscriptionId: input.subscriptionId, createdAt: { gte: today } } }) || 0;
        if (copyCount >= policy.maxCopyCount) {
          return { decision: CopyRiskDecision.BLOCK, allowed: false, ruleId: 'MAX_COPY_COUNT', reason: `Daily copy count ${copyCount} exceeds max ${policy.maxCopyCount}` };
        }
      } catch (e) {
        return this.ruleUnavailable('MAX_COPY_COUNT', e);
      }
    }

    // Daily pause check
    if (policy.dailyPauseEnabled) {
      try {
        const subscription = await (this.prisma as any).copySubscription?.findFirst({ where: { id: input.subscriptionId, tenantId: input.tenantId } });
        if (subscription && subscription.state === 'PAUSED') {
          return { decision: CopyRiskDecision.PAUSE, allowed: false, ruleId: 'DAILY_PAUSE', reason: 'Subscription is paused' };
        }
      } catch (e) {
        return this.ruleUnavailable('DAILY_PAUSE', e);
      }
    }

    // Concentration check - e.g. single symbol > 80% of exposure
    if (input.currentExposure && input.notional) {
      const newExposure = this.addDecimals(input.currentExposure, input.notional);
      if (compareDecimalStrings(newExposure, '0') > 0) {
        try {
          const symbolNotional = await this.calculateSymbolNotional(input.tenantId, input.followerAccountId, input.symbol);
          const newSymbolNotional = this.addDecimals(symbolNotional, input.notional);
          const ratio = parseFloat(newSymbolNotional) / parseFloat(newExposure);
          if (ratio > 0.8) {
            return { decision: CopyRiskDecision.BLOCK, allowed: false, ruleId: 'CONCENTRATION', reason: `Symbol ${input.symbol} would be ${(ratio * 100).toFixed(1)}% of exposure - concentration limit` };
          }
        } catch (e) {
          return this.ruleUnavailable('CONCENTRATION', e);
        }
      }
    }

    return { decision: CopyRiskDecision.ALLOW, allowed: true, ruleId: null, reason: null };
  }

  /**
   * A rule whose data cannot be read blocks the copy and names the rule. The
   * four database-backed rules (symbol exposure, daily copy count, daily
   * pause, concentration) used to swallow the error and fall through to
   * ALLOW - a database hiccup silently disabled them.
   */
  private ruleUnavailable(ruleId: string, error: unknown): RiskCheckResult {
    const message = error instanceof Error ? error.message : String(error);
    this.logger.warn(`Risk rule ${ruleId} could not be evaluated, blocking: ${message}`);
    return {
      decision: CopyRiskDecision.BLOCK,
      allowed: false,
      ruleId: `${ruleId}_UNAVAILABLE`,
      reason: `Risk rule ${ruleId} could not be evaluated`,
    };
  }

  private addDecimals(a: string, b: string): string {
    try {
      const [aInt, aDec = ''] = a.split('.');
      const [bInt, bDec = ''] = b.split('.');
      const maxDec = Math.max(aDec.length, bDec.length);
      const aFull = BigInt((aInt || '0') + aDec.padEnd(maxDec, '0'));
      const bFull = BigInt((bInt || '0') + bDec.padEnd(maxDec, '0'));
      const sum = aFull + bFull;
      const sumStr = sum.toString().padStart(maxDec + 1, '0');
      if (maxDec === 0) return sumStr;
      const intPart = sumStr.slice(0, -maxDec) || '0';
      const decPart = sumStr.slice(-maxDec).replace(/0+$/, '');
      return decPart ? `${intPart}.${decPart}` : intPart;
    } catch {
      return (parseFloat(a) + parseFloat(b)).toString();
    }
  }

  private subtractDecimals(a: string, b: string): string {
    try {
      const [aInt, aDec = ''] = a.split('.');
      const [bInt, bDec = ''] = b.split('.');
      const maxDec = Math.max(aDec.length, bDec.length);
      const aFull = BigInt((aInt || '0') + aDec.padEnd(maxDec, '0'));
      const bFull = BigInt((bInt || '0') + bDec.padEnd(maxDec, '0'));
      const diff = aFull - bFull;
      if (diff <= BigInt(0)) return '0';
      const diffStr = diff.toString().padStart(maxDec + 1, '0');
      if (maxDec === 0) return diffStr;
      const intPart = diffStr.slice(0, -maxDec) || '0';
      const decPart = diffStr.slice(-maxDec).replace(/0+$/, '');
      return decPart ? `${intPart}.${decPart}` : intPart;
    } catch {
      return Math.max(0, parseFloat(a) - parseFloat(b)).toString();
    }
  }

  /**
   * Errors propagate: this used to return '0' on failure, which understated
   * the symbol's share and let the concentration limit pass. checkRisk turns
   * a failure into a BLOCK.
   */
  private async calculateSymbolNotional(tenantId: string, accountId: string | null, symbol: string): Promise<string> {
    if (!accountId) return '0';
    const positions = await this.prisma.position.findMany({ where: { tenantId, accountId, symbol } });
    let total = '0';
    for (const p of positions) {
      const qty = p.quantity.toString();
      const mark = p.markPrice?.toString() || '0';
      if (isDecimalString(qty) && isDecimalString(mark)) {
        const notional = (parseFloat(qty) * parseFloat(mark)).toString();
        total = this.addDecimals(total, notional);
      }
    }
    return total;
  }
}

import {
  ForbiddenException,
  Injectable,
  Logger,
  NotFoundException,
  UnprocessableEntityException,
  ConflictException,
} from '@nestjs/common';
import { CopySubscriptionRepository } from './copy-subscription.repository';
import { FollowerAllocationService } from './follower-allocation.service';
import { CopyPolicyService } from './copy-policy.service';
import { TraderProfileService } from './trader-profile.service';
import { TraderStrategyService } from './trader-strategy.service';
import { CopySubscriptionState, CopySizingMode } from './copy-trading.types';
import { PlanLimitFollowersGuard } from '../billing/enforcement/plan-limit-followers.guard';
import { PlanLimitCopySubscriptionsGuard } from '../billing/enforcement/plan-limit-copy-subscriptions.guard';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OutboxService } from '../../infrastructure/outbox/outbox.service';
import { MaintenanceModeService } from '../operations/maintenance-mode.service';
import { OperationalMaintenanceScope } from '../operations/operations.types';
import { randomUUID } from 'crypto';

export interface SubscribeInput {
  tenantId: string;
  followerId: string;
  traderId: string;
  strategyId: string;
  allocationMode: CopySizingMode;
  allocationAmount: string;
  maxAllocation?: string | null;
  minAllocation?: string | null;
  copyPolicy?: Record<string, any>;
  riskPolicy?: Record<string, any>;
  followerAccountId?: string | null;
  idempotencyKey?: string | null;
  actorId: string;
  requestId?: string;
}

/**
 * Follower lifecycle: subscribe, activate, pause, resume, stop-copy, cancel, and retrieve subscription state while enforcing existing plan limits and subscription rules.
 * Must enforce maxCopySubscriptionsPerFollower using existing Part 2 enforcement, and maxFollowersPerTrader using existing system. Do not duplicate numeric limits.
 */
@Injectable()
export class FollowerSubscriptionService {
  private readonly logger = new Logger(FollowerSubscriptionService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly subscriptionRepo: CopySubscriptionRepository,
    private readonly allocationService: FollowerAllocationService,
    private readonly policyService: CopyPolicyService,
    private readonly traderProfileService: TraderProfileService,
    private readonly traderStrategyService: TraderStrategyService,
    private readonly followersGuard: PlanLimitFollowersGuard,
    private readonly copySubsGuard: PlanLimitCopySubscriptionsGuard,
    private readonly maintenance: MaintenanceModeService,
    private readonly outbox: OutboxService,
  ) {}

  /**
   * Starting or resuming copying is a new trading action, so it is refused
   * (503) while a PLATFORM, tenant or TRADING_CAPABILITY maintenance window is
   * active - the same rule the customer web uses to disable the copy button
   * (`blocksTrading` on GET /operations/maintenance/current). Pause and stop
   * stay available: reducing exposure must always work.
   */
  private assertTradingOpen(tenantId: string, operation: string): Promise<void> {
    return this.maintenance.enforceMaintenanceGate({
      tenantId,
      scope: OperationalMaintenanceScope.TRADING_CAPABILITY,
      operation,
    });
  }

  private async transitionWithOutbox(input: {
    tenantId: string;
    subscription: Record<string, any>;
    expectedState: CopySubscriptionState;
    nextState: CopySubscriptionState;
    eventType: string;
    timestamps?: { startedAt?: Date; pausedAt?: Date; stoppedAt?: Date; cancelledAt?: Date };
  }): Promise<any> {
    const subscriptionId =
      typeof input.subscription.id === 'string' ? input.subscription.id : input.subscription.subscriptionId;
    if (typeof subscriptionId !== 'string' || subscriptionId.length === 0) {
      throw new ConflictException('Copy subscription id is unavailable; refusing to record a lifecycle event');
    }

    const transitionEventId = randomUUID();
    return this.prisma.withTenantRls(input.tenantId, async (tx) => {
      const updated = await this.subscriptionRepo.updateState(
        subscriptionId,
        input.tenantId,
        input.nextState,
        input.timestamps,
        { tx, expectedState: input.expectedState },
      );
      if (!updated) {
        throw new ConflictException('Copy subscription state changed concurrently; reload and retry');
      }

      const updatedId = typeof updated.id === 'string' ? updated.id : subscriptionId;
      await this.outbox.append(tx, {
        tenantId: input.tenantId,
        aggregateType: 'copy.subscription',
        aggregateId: updatedId,
        eventType: input.eventType,
        idempotencyKey: `copy-subscription:${updatedId}:${input.eventType}:${transitionEventId}`,
        payload: {
          subscriptionId: updatedId,
          followerId: updated.followerId ?? input.subscription.followerId ?? null,
          traderId: updated.traderId ?? input.subscription.traderId ?? null,
          strategyId: updated.strategyId ?? input.subscription.strategyId ?? null,
          state: input.nextState,
        },
      });
      return updated;
    });
  }

  async subscribe(input: SubscribeInput): Promise<any> {
    await this.assertTradingOpen(input.tenantId, 'copy_trading.subscribe');

    // Validate trader/strategy
    const trader = await this.traderProfileService.getProfile(input.tenantId, input.traderId);
    // Business-rule failures are HTTP exceptions: plain Errors surfaced to the
    // follower as a generic 500 instead of the actual reason.
    if (!trader) throw new NotFoundException(`Trader ${input.traderId} not found`);

    const strategy = await this.traderStrategyService.getStrategy(input.tenantId, input.strategyId);
    if (!strategy) throw new NotFoundException(`Strategy ${input.strategyId} not found`);
    if (strategy.traderId !== input.traderId) throw new UnprocessableEntityException('Strategy does not belong to trader');
    if (strategy.status !== 'PUBLISHED') {
      throw new UnprocessableEntityException(`Strategy must be PUBLISHED to subscribe, current=${strategy.status}`);
    }

    // Validate follower eligibility - check compliance BLOCK
    // Fail closed: this used an untyped query inside a catch that swallowed
    // every error except its own, so any database failure skipped the block.
    const complianceCase = await this.prisma.complianceCase.findFirst({
      where: {
        tenantId: input.tenantId,
        userId: input.followerId,
        decision: 'BLOCK',
        state: { in: ['OPEN', 'IN_REVIEW', 'ESCALATED'] },
      },
      select: { id: true },
    });
    if (complianceCase) throw new ForbiddenException('Follower account is blocked by compliance');

    // Enforce existing plan limits - maxCopySubscriptionsPerFollower
    const actor = { tenantId: input.tenantId, userId: input.actorId } as any;
    try {
      await this.copySubsGuard.reserve(actor, input.followerId);
    } catch (e: any) {
      this.logger.warn(`Copy subscription limit exceeded follower=${input.followerId} tenant=${input.tenantId}`);
      throw e;
    }

    // Enforce maxFollowersPerTrader
    try {
      await this.followersGuard.reserve(actor, input.traderId);
    } catch (e: any) {
      // Release copy sub slot if follower limit fails
      try {
        await this.copySubsGuard.release(actor, input.followerId);
      } catch {}
      this.logger.warn(`Follower limit exceeded trader=${input.traderId} tenant=${input.tenantId}`);
      throw e;
    }

    let subscription;
    try {
      // Validate allocation uses canonical follower balance
      const allocationValidation = await this.allocationService.validateAllocation({
        tenantId: input.tenantId,
        followerId: input.followerId,
        followerAccountId: input.followerAccountId || null,
        allocationMode: input.allocationMode,
        allocationAmount: input.allocationAmount,
        maxAllocation: input.maxAllocation || null,
        minAllocation: input.minAllocation || null,
      });

      if (!allocationValidation.valid) {
        throw new UnprocessableEntityException(
          `Allocation validation failed: ${allocationValidation.reason} available=${allocationValidation.availableBalance}`,
        );
      }

      // Creation, activation and the durable domain event share one tenant-RLS
      // transaction. A commit cannot expose ACTIVE without its outbox row.
      subscription = await this.prisma.withTenantRls(input.tenantId, async (tx) => {
        const created = await this.subscriptionRepo.create(
          {
            tenantId: input.tenantId,
            followerId: input.followerId,
            traderId: input.traderId,
            strategyId: input.strategyId,
            allocationMode: input.allocationMode,
            allocationAmount: input.allocationAmount,
            maxAllocation: input.maxAllocation || null,
            minAllocation: input.minAllocation || null,
            copyPolicy: input.copyPolicy || {},
            riskPolicy: input.riskPolicy || {},
            followerAccountId: input.followerAccountId || null,
            idempotencyKey: input.idempotencyKey || null,
          },
          tx,
        );
        const activatedAt = new Date();
        const expectedState = (created.state as CopySubscriptionState | undefined) ?? CopySubscriptionState.PENDING;
        const activated = await this.subscriptionRepo.updateState(
          created.id,
          input.tenantId,
          CopySubscriptionState.ACTIVE,
          { startedAt: activatedAt },
          { tx, expectedState },
        );
        if (!activated) {
          throw new ConflictException('Copy subscription could not be activated from its current state');
        }

        await this.outbox.append(tx, {
          tenantId: input.tenantId,
          aggregateType: 'copy.subscription',
          aggregateId: activated.id,
          eventType: 'copy.subscription.created',
          idempotencyKey: `copy-subscription:${activated.id}:copy.subscription.created`,
          payload: {
            subscriptionId: activated.id,
            followerId: activated.followerId,
            traderId: activated.traderId,
            strategyId: activated.strategyId,
            state: CopySubscriptionState.ACTIVE,
          },
        });
        return activated;
      });

      // Increment trader follower count
      await this.traderProfileService.incrementFollowerCount(input.tenantId, input.traderId);

      // Audit
      await (this.prisma as any).copyTradingAuditLog?.create({
        data: {
          id: randomUUID(),
          tenantId: input.tenantId,
          event: 'SUBSCRIPTION_CREATED',
          actorId: input.actorId,
          traderId: input.traderId,
          followerId: input.followerId,
          strategyId: input.strategyId,
          subscriptionId: subscription.id,
          result: 'SUCCESS',
          safeMetadata: { allocationMode: input.allocationMode, allocationAmount: input.allocationAmount, followerAccountId: input.followerAccountId },
          requestId: input.requestId,
          createdAt: new Date(),
        },
      });

      this.logger.log(`Subscription created and activated id=${subscription.id} tenant=${input.tenantId} follower=${input.followerId} trader=${input.traderId}`);

      return subscription;
    } catch (e: any) {
      // Release both slots on failure
      try {
        await this.copySubsGuard.release(actor, input.followerId);
      } catch {}
      try {
        await this.followersGuard.release(actor, input.traderId);
      } catch {}

      if (subscription) {
        try {
          await this.transitionWithOutbox({
            tenantId: input.tenantId,
            subscription,
            expectedState: subscription.state as CopySubscriptionState,
            nextState: CopySubscriptionState.CANCELLED,
            eventType: 'copy.subscription.cancelled',
            timestamps: { cancelledAt: new Date() },
          });
        } catch {
          // Preserve the original subscribe failure. The failed transaction
          // remains visible through its own error and is never marked cancelled
          // unless the state transition and event committed together.
        }
      }

      throw e;
    }
  }

  async getSubscription(tenantId: string, subscriptionId: string, followerId?: string | null): Promise<any | null> {
    const sub = await this.subscriptionRepo.findById(subscriptionId, tenantId);
    if (!sub) return null;
    if (followerId && sub.followerId !== followerId) {
      // Check if privileged? For now, enforce follower ownership
      const isTrader = sub.traderId === followerId; // trader can view own followers? Simplified
      if (!isTrader) return null;
    }
    return sub;
  }

  async listByFollower(tenantId: string, followerId: string, filters?: { state?: CopySubscriptionState; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    return this.subscriptionRepo.listByFollower(tenantId, followerId, filters);
  }

  async listByTrader(tenantId: string, traderId: string, filters?: { state?: CopySubscriptionState; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    return this.subscriptionRepo.listByTrader(tenantId, traderId, filters);
  }

  async pauseSubscription(tenantId: string, subscriptionId: string, actorId: string, followerId?: string | null, requestId?: string): Promise<any | null> {
    const sub = await this.subscriptionRepo.findById(subscriptionId, tenantId);
    if (!sub) return null;
    if (followerId && sub.followerId !== followerId) throw new ForbiddenException('Not authorized to pause this subscription');

    if (sub.state !== CopySubscriptionState.ACTIVE) throw new ConflictException(`Only ACTIVE subscription can be paused, current=${sub.state}`);

    const updated = await this.transitionWithOutbox({
      tenantId,
      subscription: sub,
      expectedState: CopySubscriptionState.ACTIVE,
      nextState: CopySubscriptionState.PAUSED,
      eventType: 'copy.subscription.paused',
      timestamps: { pausedAt: new Date() },
    });

    await (this.prisma as any).copyTradingAuditLog?.create({
      data: { id: randomUUID(), tenantId, event: 'SUBSCRIPTION_PAUSED', actorId, traderId: sub.traderId, followerId: sub.followerId, strategyId: sub.strategyId, subscriptionId, result: 'SUCCESS', safeMetadata: {}, requestId, createdAt: new Date() },
    });

    this.logger.log(`Subscription paused id=${subscriptionId} tenant=${tenantId}`);

    return updated;
  }

  async resumeSubscription(tenantId: string, subscriptionId: string, actorId: string, followerId?: string | null, requestId?: string): Promise<any | null> {
    const sub = await this.subscriptionRepo.findById(subscriptionId, tenantId);
    if (!sub) return null;
    if (followerId && sub.followerId !== followerId) throw new ForbiddenException('Not authorized');

    if (sub.state !== CopySubscriptionState.PAUSED) throw new ConflictException(`Only PAUSED subscription can be resumed, current=${sub.state}`);
    await this.assertTradingOpen(tenantId, 'copy_trading.resume');

    const updated = await this.transitionWithOutbox({
      tenantId,
      subscription: sub,
      expectedState: CopySubscriptionState.PAUSED,
      nextState: CopySubscriptionState.ACTIVE,
      eventType: 'copy.subscription.resumed',
      timestamps: { startedAt: new Date() },
    });

    await (this.prisma as any).copyTradingAuditLog?.create({
      data: { id: randomUUID(), tenantId, event: 'SUBSCRIPTION_RESUMED', actorId, traderId: sub.traderId, followerId: sub.followerId, strategyId: sub.strategyId, subscriptionId, result: 'SUCCESS', safeMetadata: {}, requestId, createdAt: new Date() },
    });

    return updated;
  }

  async stopCopy(tenantId: string, subscriptionId: string, actorId: string, followerId?: string | null, requestId?: string): Promise<any | null> {
    const sub = await this.subscriptionRepo.findById(subscriptionId, tenantId);
    if (!sub) return null;
    if (followerId && sub.followerId !== followerId) throw new ForbiddenException('Not authorized');

    // Pausing/stopping copy must prevent future copy actions without corrupting already-executed orders
    if (sub.state === CopySubscriptionState.STOPPED || sub.state === CopySubscriptionState.CANCELLED) throw new ConflictException(`Subscription already ${sub.state}`);

    const updated = await this.transitionWithOutbox({
      tenantId,
      subscription: sub,
      expectedState: sub.state as CopySubscriptionState,
      nextState: CopySubscriptionState.STOPPED,
      eventType: 'copy.subscription.stopped',
      timestamps: { stoppedAt: new Date() },
    });

    // Release plan limits
    try {
      const actor = { tenantId, userId: actorId } as any;
      await this.copySubsGuard.release(actor, sub.followerId);
      await this.followersGuard.release(actor, sub.traderId);
      await this.traderProfileService.decrementFollowerCount(tenantId, sub.traderId);
    } catch {}

    await (this.prisma as any).copyTradingAuditLog?.create({
      data: { id: randomUUID(), tenantId, event: 'SUBSCRIPTION_STOPPED', actorId, traderId: sub.traderId, followerId: sub.followerId, strategyId: sub.strategyId, subscriptionId, result: 'SUCCESS', safeMetadata: {}, requestId, createdAt: new Date() },
    });

    this.logger.log(`Subscription stopped id=${subscriptionId} tenant=${tenantId}`);

    return updated;
  }

  async cancelSubscription(tenantId: string, subscriptionId: string, actorId: string, followerId?: string | null, requestId?: string): Promise<any | null> {
    const sub = await this.subscriptionRepo.findById(subscriptionId, tenantId);
    if (!sub) return null;
    if (followerId && sub.followerId !== followerId) throw new ForbiddenException('Not authorized');

    const updated = await this.transitionWithOutbox({
      tenantId,
      subscription: sub,
      expectedState: sub.state as CopySubscriptionState,
      nextState: CopySubscriptionState.CANCELLED,
      eventType: 'copy.subscription.cancelled',
      timestamps: { cancelledAt: new Date() },
    });

    try {
      const actor = { tenantId, userId: actorId } as any;
      await this.copySubsGuard.release(actor, sub.followerId);
      await this.followersGuard.release(actor, sub.traderId);
      await this.traderProfileService.decrementFollowerCount(tenantId, sub.traderId);
    } catch {}

    await (this.prisma as any).copyTradingAuditLog?.create({
      data: { id: randomUUID(), tenantId, event: 'SUBSCRIPTION_CANCELLED', actorId, traderId: sub.traderId, followerId: sub.followerId, strategyId: sub.strategyId, subscriptionId, result: 'SUCCESS', safeMetadata: {}, requestId, createdAt: new Date() },
    });

    return updated;
  }

  async updateSubscriptionSettings(
    tenantId: string,
    subscriptionId: string,
    dto: {
      allocationAmount?: string;
      maxAllocation?: string | null;
      minAllocation?: string | null;
      allocationMode?: CopySizingMode;
      copyPolicy?: Record<string, any>;
      riskPolicy?: Record<string, any>;
      followerAccountId?: string | null;
    },
    actorId: string,
    followerId?: string | null,
    requestId?: string,
  ): Promise<any | null> {
    const sub = await this.subscriptionRepo.findById(subscriptionId, tenantId);
    if (!sub) return null;
    if (followerId && sub.followerId !== followerId) {
      throw new ForbiddenException('Not authorized to update this subscription');
    }

    const nextCopyPolicy = dto.copyPolicy
      ? { ...(sub.copyPolicy || {}), ...dto.copyPolicy }
      : (sub.copyPolicy || {});
    const nextRiskPolicy = dto.riskPolicy
      ? { ...(sub.riskPolicy || {}), ...dto.riskPolicy }
      : (sub.riskPolicy || {});

    const policyValidation = this.policyService.validatePolicy(nextCopyPolicy as any);
    if (!policyValidation.valid) {
      throw new UnprocessableEntityException(`Invalid copy policy: ${policyValidation.errors.join(', ')}`);
    }

    if (dto.allocationAmount !== undefined || dto.maxAllocation !== undefined || dto.minAllocation !== undefined || dto.allocationMode !== undefined) {
      await this.subscriptionRepo.updateAllocation(subscriptionId, tenantId, {
        ...(dto.allocationAmount !== undefined ? { allocationAmount: dto.allocationAmount } : {}),
        ...(dto.maxAllocation !== undefined ? { maxAllocation: dto.maxAllocation } : {}),
        ...(dto.minAllocation !== undefined ? { minAllocation: dto.minAllocation } : {}),
        ...(dto.allocationMode !== undefined ? { allocationMode: dto.allocationMode } : {}),
      });
    }

    const updated = await this.subscriptionRepo.updatePolicy(subscriptionId, tenantId, {
      copyPolicy: nextCopyPolicy,
      riskPolicy: nextRiskPolicy,
    });

    await (this.prisma as any).copyTradingAuditLog?.create({
      data: {
        id: randomUUID(),
        tenantId,
        event: 'SUBSCRIPTION_SETTINGS_UPDATED',
        actorId,
        traderId: sub.traderId,
        followerId: sub.followerId,
        strategyId: sub.strategyId,
        subscriptionId,
        result: 'SUCCESS',
        safeMetadata: {
          allocationMode: dto.allocationMode ?? sub.allocationMode,
          allocationAmount: dto.allocationAmount ?? sub.allocationAmount,
        },
        requestId,
        createdAt: new Date(),
      },
    });

    return updated || (await this.subscriptionRepo.findById(subscriptionId, tenantId));
  }
}

// # Polls and dispatches leader events idempotently with staleness and duplicate-event guards
import { Injectable, Logger, OnModuleDestroy, OnModuleInit } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { CopyExecutionService } from './copy-execution.service';
import { LeaderEventRecord, LeaderEventSourceService, subscriptionWasLiveAt } from './leader-event-source.service';

export interface IngestionResult {
  events: number;
  dispatched: number;
  alreadyCopied: number;
  expired: number;
}

const DEFAULT_INTERVAL_MS = 5_000;
const DEFAULT_MAX_AGE_MS = 30_000;

function positiveInt(raw: string | undefined, fallback: number): number {
  const n = Number(raw);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : fallback;
}

/**
 * Phase 3: automatic leader-event ingestion.
 *
 * Safety properties:
 *  - Idempotent: event ids are stable (`fill:<id>`) and CopyExecution is
 *    unique per (tenant, leaderEvent, subscription); events every live
 *    subscription already has an execution for are not re-processed at all.
 *  - In-batch duplicate protection: duplicate records for the same eventId in
 *    one ingestion pass are deduplicated and counted as alreadyCopied.
 *  - Bounded staleness: a fill older than COPY_LEADER_EVENT_MAX_AGE_MS
 *    (default 30s) is never copied - the market has moved - and is left for
 *    reconciliation to report as MISSING_COPY instead of being filled late.
 *  - No history replay: a subscription is only eligible for events that
 *    happened while it was live (subscriptionWasLiveAt).
 *  - Off in tests; COPY_LEADER_INGESTION_ENABLED=false disables it.
 */
@Injectable()
export class LeaderEventIngestionService implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(LeaderEventIngestionService.name);
  private timer: NodeJS.Timeout | null = null;
  private running = false;

  readonly intervalMs = positiveInt(process.env.COPY_LEADER_INGESTION_INTERVAL_MS, DEFAULT_INTERVAL_MS);
  readonly maxAgeMs = positiveInt(process.env.COPY_LEADER_EVENT_MAX_AGE_MS, DEFAULT_MAX_AGE_MS);

  constructor(
    private readonly prisma: PrismaService,
    private readonly source: LeaderEventSourceService,
    private readonly copyExecution: CopyExecutionService,
  ) {}

  onModuleInit(): void {
    if (process.env.NODE_ENV === 'test' || (process.env.COPY_LEADER_INGESTION_ENABLED ?? '').toLowerCase() === 'false') {
      this.logger.log('Leader-event ingestion disabled');
      return;
    }
    this.timer = setInterval(() => {
      void this.sweep().catch((error: Error) => this.logger.warn(`Leader-event sweep failed: ${error.message}`));
    }, this.intervalMs);
    this.timer.unref?.();
    this.logger.log(`Leader-event ingestion every ${this.intervalMs}ms (max event age ${this.maxAgeMs}ms)`);
  }

  onModuleDestroy(): void {
    if (this.timer) clearInterval(this.timer);
    this.timer = null;
  }

  /** One pass over every tenant with at least one ACTIVE subscription. */
  async sweep(now: Date = new Date()): Promise<IngestionResult> {
    const total: IngestionResult = { events: 0, dispatched: 0, alreadyCopied: 0, expired: 0 };
    if (this.running) return total; // never overlap passes in one process
    this.running = true;
    try {
      const tenants = await this.prisma.copySubscription.findMany({ where: { state: 'ACTIVE' }, distinct: ['tenantId'], select: { tenantId: true } });
      for (const { tenantId } of tenants) {
        try {
          const r = await this.ingestTenant(tenantId, now);
          total.events += r.events;
          total.dispatched += r.dispatched;
          total.alreadyCopied += r.alreadyCopied;
          total.expired += r.expired;
        } catch (error) {
          this.logger.warn(`Leader-event ingestion failed tenant=${tenantId}: ${(error as Error).message}`);
        }
      }
    } finally {
      this.running = false;
    }
    return total;
  }

  async ingestTenant(tenantId: string, now: Date = new Date()): Promise<IngestionResult> {
    const result: IngestionResult = { events: 0, dispatched: 0, alreadyCopied: 0, expired: 0 };
    const subscriptions = await this.prisma.copySubscription.findMany({ where: { tenantId, state: 'ACTIVE' } });
    if (subscriptions.length === 0) return result;

    const byStrategy = new Map<string, any[]>();
    for (const sub of subscriptions) {
      const list = byStrategy.get(sub.strategyId) ?? [];
      list.push(sub);
      byStrategy.set(sub.strategyId, list);
    }

    const strategies = await this.source.listLeadingStrategies(tenantId, [...byStrategy.keys()]);
    const from = new Date(now.getTime() - this.maxAgeMs - this.intervalMs);
    const seenInPass = new Set<string>();

    for (const strategy of strategies) {
      const subs = byStrategy.get(strategy.id) ?? [];
      const records = await this.source.listForStrategy(tenantId, strategy, from, now);
      if (records.length === 0) continue;

      const existing = await this.prisma.copyExecution.findMany({
        where: { tenantId, leaderEventId: { in: records.map((r) => r.event.eventId) } },
        select: { leaderEventId: true, subscriptionId: true },
      });
      const copied = new Set(existing.map((e) => `${e.leaderEventId}|${e.subscriptionId}`));

      for (const record of records) {
        result.events += 1;
        const passKey = `${tenantId}|${strategy.id}|${record.event.eventId}`;
        if (seenInPass.has(passKey)) {
          result.alreadyCopied += 1;
          continue;
        }
        seenInPass.add(passKey);

        const eligible = subs.filter((s) => subscriptionWasLiveAt(s, record.occurredAt));
        if (eligible.length === 0 || eligible.every((s) => copied.has(`${record.event.eventId}|${s.id}`))) {
          result.alreadyCopied += 1;
          continue;
        }
        if (now.getTime() - record.occurredAt.getTime() > this.maxAgeMs) {
          result.expired += 1;
          continue;
        }
        await this.dispatch(tenantId, record);
        for (const s of eligible) {
          copied.add(`${record.event.eventId}|${s.id}`);
        }
        result.dispatched += 1;
      }
    }
    if (result.dispatched > 0 || result.expired > 0) {
      this.logger.log(`Leader events tenant=${tenantId} seen=${result.events} dispatched=${result.dispatched} expired=${result.expired}`);
    }
    return result;
  }

  private async dispatch(tenantId: string, record: LeaderEventRecord): Promise<void> {
    await this.copyExecution.processLeaderEvent({
      tenantId,
      leaderEvent: record.event,
      traderId: record.traderId,
      strategyId: record.strategyId,
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { LeaderEvent } from './copy-order-mapper.service';

/**
 * Phase 3: the leader-event store.
 *
 * A leader event is a FILL on one of the strategy owner's own trading accounts.
 * Fills (not orders) are the unit because they are what actually changed the
 * leader's position: a partially filled leader order produces one event per
 * fill, so followers mirror exactly what executed, and an order that never
 * fills produces nothing to copy.
 *
 * Nothing new is persisted: the canonical `fills` table (written by the
 * execution engine / private streams, unique on (orderId, venueTradeId)) is
 * the store, and the event id `fill:<fillId>` is stable, so CopyExecution's
 * unique (tenantId, leaderEventId, subscriptionId) makes ingestion idempotent
 * across sweeps and across API instances.
 *
 * Follower orders are excluded: the OMS stamps every copy order's metadata
 * with `copyExecutionId`, so a follower who is also a leader never has a copy
 * re-copied as if it were their own decision (no copy loops). Dry-run orders
 * are excluded too - they were never transmitted.
 */

export interface LeaderStrategyRef {
  id: string;
  traderId: string;
  userId: string;
  supportedSymbols?: string[] | null;
  supportedVenues?: string[] | null;
  strategyConfig?: Record<string, unknown> | null;
}

export interface LeaderEventRecord {
  event: LeaderEvent;
  strategyId: string;
  traderId: string;
  /** When the fill happened (exchange time when known). */
  occurredAt: Date;
}

interface FillWithOrder {
  id: string;
  price: unknown;
  quantity: unknown;
  isSimulated: boolean;
  exchangeTimestampMicros: bigint | number | null;
  createdAt: Date;
  order: {
    id: string;
    tenantId: string;
    accountId: string;
    symbol: string;
    side: string;
    venue: string;
    isSimulated: boolean;
    wasDryRun: boolean;
    metadata: unknown;
  };
}

function decimalString(value: unknown): string {
  if (value === null || value === undefined) return '0';
  return typeof value === 'string' ? value : String((value as { toString(): string }).toString());
}

function occurredAt(fill: FillWithOrder): Date {
  const micros = fill.exchangeTimestampMicros;
  if (micros !== null && micros !== undefined) {
    const ms = Number(BigInt(micros) / 1000n);
    if (Number.isFinite(ms) && ms > 0) return new Date(ms);
  }
  return new Date(fill.createdAt);
}

/** True when the order was placed by copy trading (never a leader decision). */
export function isCopyOrder(metadata: unknown): boolean {
  return typeof metadata === 'object' && metadata !== null && typeof (metadata as Record<string, unknown>).copyExecutionId === 'string';
}

/** Pure: one leader fill → the LeaderEvent the copy pipeline consumes. */
export function leaderEventFromFill(fill: FillWithOrder): { event: LeaderEvent; occurredAt: Date } {
  const at = occurredAt(fill);
  return {
    occurredAt: at,
    event: {
      eventId: `fill:${fill.id}`,
      orderId: fill.order.id,
      fillId: fill.id,
      symbol: fill.order.symbol,
      exchangeSymbol: fill.order.symbol,
      side: fill.order.side,
      // A follower mirrors an execution that already happened, so it follows
      // at market; the leader's fill price is the slippage reference.
      type: 'MARKET',
      quantity: decimalString(fill.quantity),
      price: decimalString(fill.price),
      stopPrice: null,
      venue: fill.order.venue,
      timestamp: at.toISOString(),
      isSimulated: fill.isSimulated === true || fill.order.isSimulated === true,
    },
  };
}

@Injectable()
export class LeaderEventSourceService {
  private readonly logger = new Logger(LeaderEventSourceService.name);

  constructor(private readonly prisma: PrismaService) {}

  /** Leader fills of one strategy in [from, to], oldest first. */
  async listForStrategy(tenantId: string, strategy: LeaderStrategyRef, from: Date, to: Date, limit = 500): Promise<LeaderEventRecord[]> {
    const pinnedAccount = typeof strategy.strategyConfig?.leaderAccountId === 'string' ? (strategy.strategyConfig.leaderAccountId as string) : null;
    const accounts = await this.prisma.tradingAccount.findMany({
      where: { tenantId, userId: strategy.userId, ...(pinnedAccount ? { id: pinnedAccount } : {}) },
      select: { id: true },
    });
    if (accounts.length === 0) return [];

    const fills = (await this.prisma.fill.findMany({
      where: {
        createdAt: { gte: from, lte: to },
        order: { tenantId, accountId: { in: accounts.map((a) => a.id) } },
      },
      include: {
        order: {
          select: { id: true, tenantId: true, accountId: true, symbol: true, side: true, venue: true, isSimulated: true, wasDryRun: true, metadata: true },
        },
      },
      orderBy: { createdAt: 'asc' },
      take: limit,
    })) as unknown as FillWithOrder[];

    const symbols = (strategy.supportedSymbols ?? []).map((s) => s.toUpperCase());
    const venues = (strategy.supportedVenues ?? []).map((v) => v.toUpperCase());
    const records: LeaderEventRecord[] = [];
    for (const fill of fills) {
      if (!fill.order || fill.order.tenantId !== tenantId) continue;
      if (isCopyOrder(fill.order.metadata) || fill.order.wasDryRun) continue;
      if (symbols.length > 0 && !symbols.includes(String(fill.order.symbol).toUpperCase())) continue;
      if (venues.length > 0 && !venues.includes(String(fill.order.venue).toUpperCase())) continue;
      const { event, occurredAt: at } = leaderEventFromFill(fill);
      records.push({ event, strategyId: strategy.id, traderId: strategy.traderId, occurredAt: at });
    }
    if (fills.length >= limit) {
      this.logger.warn(`Leader fill window truncated tenant=${tenantId} strategy=${strategy.id} limit=${limit}`);
    }
    return records;
  }

  /** Strategies that can currently lead (published) with their copy fields. */
  async listLeadingStrategies(tenantId: string, strategyIds?: string[]): Promise<LeaderStrategyRef[]> {
    const rows = await this.prisma.traderStrategy.findMany({
      where: { tenantId, deletedAt: null, ...(strategyIds ? { id: { in: strategyIds } } : { status: 'PUBLISHED' }) },
      select: { id: true, traderId: true, userId: true, supportedSymbols: true, supportedVenues: true, strategyConfig: true },
    });
    return rows.map((r) => ({ ...r, strategyConfig: (r.strategyConfig ?? {}) as Record<string, unknown> }));
  }
}

/**
 * Whether a subscription was live when a leader event happened: started at or
 * before it, and not stopped/cancelled/expired/paused before it. Shared by
 * ingestion (never copy history into a new subscription) and reconciliation
 * (only a subscription that was live can have MISSED a copy).
 */
export function subscriptionWasLiveAt(sub: Record<string, any>, at: Date): boolean {
  const t = at.getTime();
  const before = (value: unknown) => value !== null && value !== undefined && new Date(value as string).getTime() <= t;
  if (!sub.startedAt || !before(sub.startedAt)) return false;
  if (before(sub.stoppedAt) || before(sub.cancelledAt)) return false;
  if (sub.expiresAt && new Date(sub.expiresAt).getTime() <= t) return false;
  if (sub.state === 'PAUSED' && before(sub.pausedAt)) return false;
  return true;
}

