import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { NetworkIdentity } from './custody.types';

/**
 * Maintains supported blockchain-network metadata including chainId, network identifier, native asset,
 * explorer information, finality model, provider capabilities, status, and confirmation policy.
 * Network identity must always be explicit.
 */

@Injectable()
export class NetworkRegistryService {
  private readonly logger = new Logger(NetworkRegistryService.name);

  constructor(private readonly prisma: PrismaService) {}

  async registerNetwork(params: {
    networkId: string;
    chainId?: string | null;
    name: string;
    nativeAssetId?: string | null;
    nativeAssetSymbol?: string | null;
    explorerUrl?: string | null;
    rpcUrl?: string | null;
    finalityModel?: string | null;
    confirmationPolicy?: any;
    status?: string;
    providerCapabilities?: string[];
    metadata?: any;
  }): Promise<any> {
    const { networkId, chainId = null, name, nativeAssetId = null, nativeAssetSymbol = null, explorerUrl = null, rpcUrl = null, finalityModel = null, confirmationPolicy = null, status = 'ACTIVE', providerCapabilities = [], metadata = {} } = params;

    if (!networkId || !name) throw new BadRequestException('networkId and name required');

    // Network identity must always be explicit — reject ambiguous
    if (!networkId.trim()) throw new BadRequestException('networkId must be explicit');

    try {
      const existing = await (this.prisma as any).custodyNetwork.findFirst({ where: { networkId } });
      if (existing) {
        return await (this.prisma as any).custodyNetwork.update({
          where: { id: existing.id },
          data: {
            chainId,
            name,
            nativeAssetId,
            nativeAssetSymbol,
            explorerUrl,
            rpcUrl,
            finalityModel,
            confirmationPolicy,
            status,
            providerCapabilities,
            metadata,
          },
        });
      }
    } catch {}

    const network = await (this.prisma as any).custodyNetwork.create({
      data: {
        networkId,
        chainId,
        name,
        nativeAssetId,
        nativeAssetSymbol,
        explorerUrl,
        rpcUrl,
        finalityModel,
        confirmationPolicy,
        status,
        providerCapabilities,
        metadata,
      },
    });

    this.logger.log({ event: 'custody.network.registered', networkId, chainId, name });

    return network;
  }

  async getNetwork(params: { networkId: string }): Promise<any | null> {
    return await (this.prisma as any).custodyNetwork.findFirst({ where: { networkId: params.networkId } });
  }

  async getNetworkByChainId(params: { chainId: string }): Promise<any | null> {
    return await (this.prisma as any).custodyNetwork.findFirst({ where: { chainId: params.chainId } });
  }

  async listNetworks(params: { status?: string; page?: number; limit?: number }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { status, page = 1, limit = 100 } = params;
    const where: any = {};
    if (status) where.status = status;

    const [data, total] = await Promise.all([
      (this.prisma as any).custodyNetwork.findMany({ where, orderBy: { name: 'asc' }, skip: (page - 1) * limit, take: limit }),
      (this.prisma as any).custodyNetwork.count({ where }),
    ]);
    return { data, total, page, limit };
  }

  async isNetworkSupported(params: { networkId: string }): Promise<boolean> {
    const network = await (this.prisma as any).custodyNetwork.findFirst({ where: { networkId: params.networkId, status: 'ACTIVE' } });
    return !!network;
  }

  async validateNetworkIdentity(identity: NetworkIdentity): Promise<void> {
    if (!identity.networkId) throw new BadRequestException('Network identity must include networkId explicit');
    const supported = await this.isNetworkSupported({ networkId: identity.networkId });
    if (!supported) {
      throw new BadRequestException(`Unsupported network ${identity.networkId} — explicit capability error`);
    }
  }

  async getRequiredConfirmations(params: { networkId: string }): Promise<number> {
    const network = await this.getNetwork({ networkId: params.networkId });
    if (!network) throw new BadRequestException(`Unsupported network ${params.networkId}`);
    const policy = network.confirmationPolicy as any;
    if (policy?.requiredConfirmations) return policy.requiredConfirmations;
    // Default confirmation policy per network — explicit, not invented
    const defaults: Record<string, number> = {
      bitcoin: 3,
      ethereum: 12,
      bsc: 15,
      solana: 32,
      polygon: 128,
      arbitrum: 12,
      base: 12,
      avalanche: 12,
    };
    return defaults[params.networkId] ?? 12;
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { BlockchainProviderFactory } from './blockchain-provider.factory';
import { TransactionService } from './transaction.service';
import { ConfirmationService } from './confirmation.service';
import { CustodyAuditService } from './custody-audit.service';
import { CustodyTransactionState, redactSecrets } from './custody.types';

/**
 * Polls/subscribes to authoritative provider transaction observations, detects pending/confirmed/failed/replaced/dropped/reorged states,
 * stores raw-provider-safe metadata, and never fabricates blockchain status.
 */

@Injectable()
export class TransactionMonitoringService {
  private readonly logger = new Logger(TransactionMonitoringService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly providerFactory: BlockchainProviderFactory,
    private readonly transactionService: TransactionService,
    private readonly confirmationService: ConfirmationService,
    private readonly auditService: CustodyAuditService,
  ) {}

  async pollTransaction(params: { tenantId: string; transactionId: string }): Promise<any> {
    const { tenantId, transactionId } = params;

    const tx = await (this.prisma as any).custodyTransaction.findFirst({ where: { id: transactionId, tenantId } });
    if (!tx) throw new BadRequestException('Transaction not found');

    if (!tx.transactionHash) {
      // No hash yet — still pending submission
      return tx;
    }

    let provider: any = null;
    try {
      provider = await this.providerFactory.getProviderForNetwork({ networkId: tx.networkId, assetId: tx.assetId });
    } catch {
      throw new BadRequestException('Provider unavailable for transaction polling');
    }

    let observation: any = null;
    try {
      observation = await provider.getTransaction({ transactionHash: tx.transactionHash, networkId: tx.networkId, assetId: tx.assetId });
    } catch (e) {
      this.logger.warn(`Provider getTransaction failed for ${tx.transactionHash}: ${(e as Error).message}`);
      return tx;
    }

    if (!observation) {
      // Transaction not yet observed on chain — could be pending or dropped
      // Check if it's been pending too long — might be dropped
      const ageMs = Date.now() - new Date(tx.createdAt).getTime();
      if (ageMs > 30 * 60 * 1000 && tx.status === 'SUBMITTED') {
        // After 30 min, mark as possibly dropped — but need provider evidence
        // For now, keep as SUBMITTED
      }
      return tx;
    }

    // Update transaction with provider observation — never fabricate blockchain status
    const newStatus = observation.status as CustodyTransactionState;
    const currentStatus = tx.status as CustodyTransactionState;

    if (newStatus !== currentStatus) {
      try {
        await this.transactionService.transitionTransaction({
          tenantId,
          transactionId,
          toState: newStatus,
          blockHash: observation.blockHash ?? null,
          blockNumber: observation.blockNumber ?? null,
          confirmationCount: observation.confirmationCount ?? null,
          actualFee: observation.fee ?? null,
        });
      } catch (e) {
        this.logger.warn(`Failed to transition transaction ${transactionId} ${currentStatus}→${newStatus}: ${(e as Error).message}`);
      }
    } else {
      // Update confirmation count even if status same
      if (observation.confirmationCount !== undefined && observation.confirmationCount !== tx.confirmationCount) {
        try {
          await (this.prisma as any).custodyTransaction.update({
            where: { id: transactionId },
            data: { confirmationCount: observation.confirmationCount, blockHash: observation.blockHash ?? tx.blockHash, blockNumber: observation.blockNumber ?? tx.blockNumber },
          });
        } catch {}
      }
    }

    // Store raw-provider-safe metadata
    try {
      await (this.prisma as any).custodyTransaction.update({
        where: { id: transactionId },
        data: { evidence: redactSecrets({ ...(tx.evidence as any), providerObservation: observation, lastPolledAt: new Date().toISOString() }) as any },
      });
    } catch {}

    // If transaction is confirmed, observe confirmation
    if (observation.confirmationCount > 0) {
      try {
        await this.confirmationService.observeConfirmation({
          tenantId,
          transactionId,
          blockHash: observation.blockHash ?? null,
          blockNumber: observation.blockNumber ?? null,
          confirmationCount: observation.confirmationCount,
          requiredConfirmationCount: tx.requiredConfirmationCount ?? 6,
          providerReference: observation.providerReference ?? null,
        });
      } catch {}
    }

    const updated = await (this.prisma as any).custodyTransaction.findFirst({ where: { id: transactionId, tenantId } });
    return updated;
  }

  async handleReorg(params: { tenantId: string; transactionId: string; reason: string; newBlockHash?: string | null; newBlockNumber?: string | null }): Promise<any> {
    const { tenantId, transactionId, reason, newBlockHash = null, newBlockNumber = null } = params;

    const tx = await (this.prisma as any).custodyTransaction.findFirst({ where: { id: transactionId, tenantId } });
    if (!tx) throw new BadRequestException('Transaction not found');

    // For transactions previously observed as confirmed but later invalidated: CONFIRMED → REORGED → CONFIRMING
    const currentState = tx.status as CustodyTransactionState;
    if (!['CONFIRMED', 'FINAL', 'CONFIRMING'].includes(currentState)) {
      throw new BadRequestException(`Reorg handling only for CONFIRMED/FINAL/CONFIRMING, current: ${currentState}`);
    }

    const reorged = await this.transactionService.transitionTransaction({
      tenantId,
      transactionId,
      toState: CustodyTransactionState.REORGED as any,
      blockHash: newBlockHash,
      blockNumber: newBlockNumber,
    });

    // Trigger reconciliation, audit, operations incident as appropriate
    await this.auditService.log({
      tenantId,
      walletId: tx.walletId,
      action: 'TRANSACTION_REORGED' as any,
      entityType: 'CUSTODY_TRANSACTION',
      entityId: transactionId,
      evidence: { transactionHash: tx.transactionHash, reason, newBlockHash, newBlockNumber, previousState: currentState },
    });

    this.logger.warn({ event: 'custody.transaction.reorged', tenantId, transactionId, transactionHash: tx.transactionHash, reason });

    return reorged;
  }

  async listPendingTransactions(params: { tenantId: string; page?: number; limit?: number }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId, page = 1, limit = 50 } = params;
    const where: any = { tenantId, status: { in: ['PENDING', 'SUBMITTED', 'OBSERVED', 'CONFIRMING'] } };

    const [data, total] = await Promise.all([
      (this.prisma as any).custodyTransaction.findMany({ where, orderBy: { createdAt: 'asc' }, skip: (page - 1) * limit, take: limit }),
      (this.prisma as any).custodyTransaction.count({ where }),
    ]);
    return { data, total, page, limit };
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { CustodyAuditService } from './custody-audit.service';
import { deterministicIdempotencyKey, CustodyTransactionState, TRANSACTION_VALID_TRANSITIONS, isValidDecimal, redactSecrets } from './custody.types';

/**
 * Persists canonical custody transaction records including transaction hash where authoritative,
 * wallet references, asset/network, amount, fee, provider reference, direction, state, timestamps,
 * and source workflow references. Duplicate transaction observations must be idempotent.
 */

@Injectable()
export class TransactionService {
  private readonly logger = new Logger(TransactionService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly auditService: CustodyAuditService,
  ) {}

  async createTransaction(params: {
    tenantId: string;
    walletId?: string | null;
    assetId: string;
    networkId: string;
    direction: string;
    amount: string;
    transactionHash?: string | null;
    blockHash?: string | null;
    blockNumber?: string | null;
    providerReference?: string | null;
    providerMetadata?: any;
    status?: string;
    confirmationCount?: number;
    requiredConfirmationCount?: number;
    estimatedFee?: string | null;
    actualFee?: string | null;
    feeAsset?: string | null;
    feeReference?: string | null;
    sourceWorkflowType?: string | null;
    sourceWorkflowId?: string | null;
    depositId?: string | null;
    withdrawalId?: string | null;
    observedAt?: Date | null;
    submittedAt?: Date | null;
    confirmedAt?: Date | null;
    failedAt?: Date | null;
    evidence?: any;
    idempotencyKey?: string;
  }): Promise<any> {
    const { tenantId, walletId = null, assetId, networkId, direction, amount, transactionHash = null, blockHash = null, blockNumber = null, providerReference = null, providerMetadata = null, status = 'PENDING', confirmationCount = 0, requiredConfirmationCount = 6, estimatedFee = null, actualFee = null, feeAsset = null, feeReference = null, sourceWorkflowType = null, sourceWorkflowId = null, depositId = null, withdrawalId = null, observedAt = null, submittedAt = null, confirmedAt = null, failedAt = null, evidence = {}, idempotencyKey: providedKey } = params;

    if (!assetId || !networkId) throw new BadRequestException('assetId and networkId must be explicit');
    if (!isValidDecimal(amount)) throw new BadRequestException(`Invalid amount decimal: ${amount}`);
    if (!['IN', 'OUT', 'INTERNAL'].includes(direction)) throw new BadRequestException('Invalid direction');

    // Never invent transaction hashes — transactionHash must be from authoritative provider/chain evidence if provided
    // But allow null for PENDING transactions before submission

    const idempotencyKey = providedKey ?? deterministicIdempotencyKey({
      type: `custody-tx:${direction}:${assetId}:${networkId}`,
      tenantId,
      walletId: walletId ?? undefined,
      assetId,
      networkId,
      externalRef: transactionHash ?? `${sourceWorkflowType ?? ''}:${sourceWorkflowId ?? ''}:${Date.now()}`,
    });

    try {
      const existing = await (this.prisma as any).custodyTransaction.findFirst({ where: { tenantId: params.tenantId, idempotencyKey } });
      if (existing) {
        this.logger.log({ event: 'custody.transaction.idempotent_hit', idempotencyKey, transactionHash });
        return existing;
      }
    } catch {}

    // Duplicate transaction hash detection — network-aware uniqueness
    if (transactionHash) {
      try {
        const dup = await (this.prisma as any).custodyTransaction.findFirst({ where: { tenantId, networkId, transactionHash } });
        if (dup) {
          // If same hash already exists, return existing — idempotent provider observation
          this.logger.log({ event: 'custody.transaction.duplicate_hash', transactionHash, networkId });
          return dup;
        }
      } catch {}
    }

    const transaction = await (this.prisma as any).custodyTransaction.create({
      data: {
        tenantId,
        walletId: walletId ?? null,
        assetId,
        networkId,
        direction,
        amount,
        transactionHash: transactionHash ?? null,
        blockHash: blockHash ?? null,
        blockNumber: blockNumber ?? null,
        providerReference: providerReference ?? null,
        providerMetadata: providerMetadata ? redactSecrets(providerMetadata) as any : null,
        status: status as any,
        confirmationCount,
        requiredConfirmationCount,
        estimatedFee: estimatedFee ?? null,
        actualFee: actualFee ?? null,
        feeAsset: feeAsset ?? null,
        feeReference: feeReference ?? null,
        sourceWorkflowType: sourceWorkflowType ?? null,
        sourceWorkflowId: sourceWorkflowId ?? null,
        depositId: depositId ?? null,
        withdrawalId: withdrawalId ?? null,
        observedAt: observedAt ?? null,
        submittedAt: submittedAt ?? null,
        confirmedAt: confirmedAt ?? null,
        failedAt: failedAt ?? null,
        evidence: redactSecrets(evidence) as any,
        idempotencyKey,
      },
    });

    await this.auditService.log({
      tenantId,
      walletId: walletId ?? null,
      action: 'TRANSACTION_CREATED' as any,
      entityType: 'CUSTODY_TRANSACTION',
      entityId: transaction.id,
      evidence: { transactionHash, assetId, networkId, amount, direction, status },
    });

    return transaction;
  }

  async transitionTransaction(params: {
    tenantId: string;
    transactionId: string;
    toState: CustodyTransactionState;
    blockHash?: string | null;
    blockNumber?: string | null;
    confirmationCount?: number | null;
    actualFee?: string | null;
    failureReason?: string | null;
    operatorId?: string | null;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, transactionId, toState, blockHash = null, blockNumber = null, confirmationCount = null, actualFee = null, failureReason = null, operatorId = null, correlationId = null } = params;

    const tx = await (this.prisma as any).custodyTransaction.findFirst({ where: { id: transactionId, tenantId } });
    if (!tx) throw new BadRequestException('Transaction not found');

    const currentState = tx.status as CustodyTransactionState;
    const allowed = TRANSACTION_VALID_TRANSITIONS[currentState] ?? [];
    if (!allowed.includes(toState)) {
      throw new BadRequestException(`Invalid transaction transition ${currentState} → ${toState}`);
    }

    // Never mark CONFIRMED without authoritative provider/chain evidence
    if (toState === CustodyTransactionState.CONFIRMED || toState === CustodyTransactionState.FINAL) {
      if (!tx.transactionHash) {
        throw new BadRequestException('Cannot mark CONFIRMED without authoritative transaction hash from provider/chain evidence');
      }
      if (!blockHash && !tx.blockHash) {
        throw new BadRequestException('Cannot mark CONFIRMED without blockHash from provider evidence');
      }
    }

    const updated = await (this.prisma as any).custodyTransaction.update({
      where: { id: transactionId },
      data: {
        status: toState as any,
        ...(blockHash ? { blockHash } : {}),
        ...(blockNumber ? { blockNumber } : {}),
        ...(confirmationCount !== null ? { confirmationCount } : {}),
        ...(actualFee ? { actualFee } : {}),
        ...(failureReason ? { failureReason } : {}),
        ...(toState === CustodyTransactionState.CONFIRMED ? { confirmedAt: new Date() } : {}),
        ...(toState === CustodyTransactionState.FINAL ? { confirmedAt: new Date() } : {}),
        ...(toState === CustodyTransactionState.FAILED ? { failedAt: new Date() } : {}),
        ...(toState === CustodyTransactionState.REORGED ? { isReorged: true, reorgedAt: new Date() } : {}),
      },
    });

    await this.auditService.log({
      tenantId,
      walletId: tx.walletId,
      action: `TRANSACTION_${toState}` as any,
      entityType: 'CUSTODY_TRANSACTION',
      entityId: transactionId,
      actorId: operatorId,
      fromState: currentState,
      toState: toState as any,
      correlationId,
      evidence: { transactionHash: tx.transactionHash, blockHash, blockNumber, confirmationCount, actualFee },
    });

    return updated;
  }

  async getTransaction(params: { tenantId: string; transactionId: string }): Promise<any | null> {
    return await (this.prisma as any).custodyTransaction.findFirst({ where: { id: params.transactionId, tenantId: params.tenantId } });
  }

  async getTransactionByHash(params: { tenantId: string; transactionHash: string; networkId: string }): Promise<any | null> {
    return await (this.prisma as any).custodyTransaction.findFirst({ where: { tenantId: params.tenantId, transactionHash: params.transactionHash, networkId: params.networkId } });
  }

  async listTransactions(params: {
    tenantId: string;
    walletId?: string;
    assetId?: string;
    networkId?: string;
    status?: string;
    direction?: string;
    sourceWorkflowId?: string;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId, walletId, assetId, networkId, status, direction, sourceWorkflowId, page = 1, limit = 50 } = params;
    const where: any = { tenantId };
    if (walletId) where.walletId = walletId;
    if (assetId) where.assetId = assetId;
    if (networkId) where.networkId = networkId;
    if (status) where.status = status;
    if (direction) where.direction = direction;
    if (sourceWorkflowId) where.sourceWorkflowId = sourceWorkflowId;

    const [data, total] = await Promise.all([
      (this.prisma as any).custodyTransaction.findMany({ where, orderBy: { createdAt: 'desc' }, skip: (page - 1) * limit, take: limit }),
      (this.prisma as any).custodyTransaction.count({ where }),
    ]);
    return { data, total, page, limit };
  }
}

import { Injectable, Logger, BadRequestException, ForbiddenException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { CustodyAuditService } from './custody-audit.service';
import { deterministicIdempotencyKey, CustodyWalletAddressState, ADDRESS_VALID_TRANSITIONS, redactSecrets } from './custody.types';

/**
 * Manages wallet addresses, address status, ownership, network/asset binding, labels, creation source,
 * verification, and lifecycle. Prevents the same address from being ambiguously assigned across
 * incompatible tenant/account contexts.
 */

@Injectable()
export class WalletAddressService {
  private readonly logger = new Logger(WalletAddressService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly auditService: CustodyAuditService,
  ) {}

  async createAddress(params: {
    tenantId: string;
    walletId: string;
    assetId: string;
    networkId: string;
    address: string;
    providerReference?: string | null;
    creationSource?: string | null;
    label?: string | null;
    isDepositAddress?: boolean;
    clientProfileId?: string | null;
    accountId?: string | null;
    operatorId?: string | null;
    correlationId?: string | null;
    metadata?: any;
  }): Promise<any> {
    const { tenantId, walletId, assetId, networkId, address, providerReference = null, creationSource = null, label = null, isDepositAddress = false, clientProfileId = null, accountId = null, operatorId = null, correlationId = null, metadata = {} } = params;

    if (!assetId || !networkId || !address) throw new BadRequestException('assetId, networkId, address must be explicit');

    // Verify wallet belongs to tenant
    const wallet = await (this.prisma as any).custodyWallet.findFirst({ where: { id: walletId, tenantId } });
    if (!wallet) throw new BadRequestException('Wallet not found or tenant mismatch');

    // Prevent same address from being ambiguously assigned across incompatible tenant/account contexts
    try {
      const existing = await (this.prisma as any).custodyWalletAddress.findFirst({
        where: { address, networkId, tenantId: { not: tenantId } },
      });
      if (existing) {
        throw new ForbiddenException('Address already assigned to different tenant — ambiguous assignment prevented');
      }

      // Same tenant but different wallet? Check if address already active for same network
      const sameTenantSameAddress = await (this.prisma as any).custodyWalletAddress.findFirst({
        where: { tenantId, networkId, address, status: { in: ['ACTIVE', 'RESERVED'] } },
      });
      if (sameTenantSameAddress && sameTenantSameAddress.walletId !== walletId) {
        // Allow if same account, but prevent ambiguous across incompatible account contexts
        if (sameTenantSameAddress.accountId && accountId && sameTenantSameAddress.accountId !== accountId) {
          throw new BadRequestException(`Address ${address} already assigned to different account context — ambiguous assignment prevented`);
        }
      }
    } catch (e) {
      if (e instanceof BadRequestException || e instanceof ForbiddenException) throw e;
    }

    const idempotencyKey = deterministicIdempotencyKey({
      type: `wallet-address:${assetId}:${networkId}`,
      tenantId,
      walletId,
      assetId,
      networkId,
      externalRef: address,
    });

    try {
      const existingByKey = await (this.prisma as any).custodyWalletAddress.findFirst({ where: { tenantId: params.tenantId, idempotencyKey } });
      if (existingByKey) return existingByKey;
    } catch {}

    const walletAddress = await (this.prisma as any).custodyWalletAddress.create({
      data: {
        tenantId,
        walletId,
        assetId,
        networkId,
        address,
        providerReference: providerReference ?? null,
        creationSource: creationSource ?? null,
        status: 'GENERATING',
        label: label ?? null,
        isDepositAddress,
        clientProfileId: clientProfileId ?? null,
        accountId: accountId ?? null,
        verified: false,
        idempotencyKey,
        metadata: redactSecrets(metadata) as any,
      },
    });

    // Transition to ACTIVE after creation — address ownership must be explicit
    const active = await this.transitionAddress({
      tenantId,
      addressId: walletAddress.id,
      toState: CustodyWalletAddressState.ACTIVE as any,
      operatorId,
      correlationId,
    });

    await this.auditService.log({
      tenantId,
      walletId,
      action: 'ADDRESS_GENERATED' as any,
      entityType: 'CUSTODY_WALLET_ADDRESS',
      entityId: walletAddress.id,
      actorId: operatorId,
      toState: 'ACTIVE',
      correlationId,
      evidence: { address, assetId, networkId, providerReference, creationSource, walletId },
    });

    this.logger.log({ event: 'custody.address.created', tenantId, walletId, address, assetId, networkId });

    return active;
  }

  async transitionAddress(params: {
    tenantId: string;
    addressId: string;
    toState: CustodyWalletAddressState;
    operatorId?: string | null;
    reason?: string;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, addressId, toState, operatorId = null, reason, correlationId = null } = params;

    const address = await (this.prisma as any).custodyWalletAddress.findFirst({ where: { id: addressId, tenantId } });
    if (!address) throw new BadRequestException('Address not found');

    const currentState = address.status as CustodyWalletAddressState;
    const allowed = ADDRESS_VALID_TRANSITIONS[currentState] ?? [];
    if (!allowed.includes(toState)) {
      throw new BadRequestException(`Invalid address transition ${currentState} → ${toState}`);
    }

    const updated = await (this.prisma as any).custodyWalletAddress.update({
      where: { id: addressId },
      data: {
        status: toState as any,
        ...(toState === CustodyWalletAddressState.ACTIVE ? { activatedAt: new Date() } : {}),
        ...(toState === CustodyWalletAddressState.DEPRECATED ? { deprecatedAt: new Date() } : {}),
        ...(toState === CustodyWalletAddressState.ACTIVE ? { verified: true, verifiedAt: new Date() } : {}),
      },
    });

    await this.auditService.log({
      tenantId,
      walletId: address.walletId,
      action: 'ADDRESS_STATUS_CHANGED' as any,
      entityType: 'CUSTODY_WALLET_ADDRESS',
      entityId: addressId,
      actorId: operatorId,
      fromState: currentState,
      toState: toState as any,
      reason: reason ?? null,
      correlationId,
      evidence: { fromState: currentState, toState, address: address.address },
    });

    return updated;
  }

  async getAddress(params: { tenantId: string; addressId: string }): Promise<any | null> {
    return await (this.prisma as any).custodyWalletAddress.findFirst({ where: { id: params.addressId, tenantId: params.tenantId } });
  }

  async getAddressByAddress(params: { tenantId: string; address: string; networkId: string }): Promise<any | null> {
    return await (this.prisma as any).custodyWalletAddress.findFirst({ where: { tenantId: params.tenantId, address: params.address, networkId: params.networkId } });
  }

  async listAddresses(params: {
    tenantId: string;
    walletId?: string;
    assetId?: string;
    networkId?: string;
    status?: string;
    accountId?: string;
    clientProfileId?: string;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId, walletId, assetId, networkId, status, accountId, clientProfileId, page = 1, limit = 50 } = params;
    const where: any = { tenantId };
    if (walletId) where.walletId = walletId;
    if (assetId) where.assetId = assetId;
    if (networkId) where.networkId = networkId;
    if (status) where.status = status;
    if (accountId) where.accountId = accountId;
    if (clientProfileId) where.clientProfileId = clientProfileId;

    const [data, total] = await Promise.all([
      (this.prisma as any).custodyWalletAddress.findMany({ where, orderBy: { createdAt: 'desc' }, skip: (page - 1) * limit, take: limit }),
      (this.prisma as any).custodyWalletAddress.count({ where }),
    ]);
    return { data, total, page, limit };
  }
}

// # Enforces withdrawal state machine (REQUESTED -> RISK_CHECK -> COMPLIANCE_CHECK -> APPROVED -> BROADCAST -> CONFIRMED/REJECTED)
import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { WithdrawalPolicyService } from './withdrawal-policy.service';
import { BlockchainProviderFactory } from './blockchain-provider.factory';
import { TransactionService } from './transaction.service';
import { CustodyAuditService } from './custody-audit.service';
import { CustodyPolicyService } from './custody-policy.service';
import { deterministicIdempotencyKey, CustodyWithdrawalState, WITHDRAWAL_VALID_TRANSITIONS, redactSecrets } from './custody.types';

/**
 * Coordinates approved withdrawal workflows into custody-provider submission while preserving existing
 * client/funding workflow state. Must verify all prerequisites again immediately before submission
 * and must never bypass approval, compliance, risk, security, or operational restrictions.
 */

@Injectable()
export class WithdrawalOrchestrationService {
  private readonly logger = new Logger(WithdrawalOrchestrationService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly withdrawalPolicyService: WithdrawalPolicyService,
    private readonly providerFactory: BlockchainProviderFactory,
    private readonly transactionService: TransactionService,
    private readonly auditService: CustodyAuditService,
    private readonly custodyPolicyService: CustodyPolicyService,
  ) {}

  async submitWithdrawal(params: {
    tenantId: string;
    custodyWithdrawalId: string;
    operatorId?: string | null;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, custodyWithdrawalId, operatorId = null, correlationId = null } = params;

    const withdrawal = await (this.prisma as any).custodyWithdrawal.findFirst({ where: { id: custodyWithdrawalId, tenantId } });
    if (!withdrawal) throw new BadRequestException('Custody withdrawal not found');

    const currentState = withdrawal.state as CustodyWithdrawalState;

    // Must be APPROVED or QUEUED to submit
    if (![CustodyWithdrawalState.APPROVED, CustodyWithdrawalState.QUEUED].includes(currentState)) {
      throw new BadRequestException(`Withdrawal must be APPROVED/QUEUED to submit, current: ${currentState}`);
    }

    // Before provider submission, re-check all safety gates
    const eligibility = await this.withdrawalPolicyService.evaluateWithdrawalEligibility({
      tenantId,
      accountId: withdrawal.accountId,
      walletId: withdrawal.walletId,
      assetId: withdrawal.assetId,
      networkId: withdrawal.networkId,
      amount: withdrawal.amount,
      destinationAddress: withdrawal.destinationAddress,
      operatorId,
    });

    if (!eligibility.eligible) {
      // DO NOT SUBMIT if any mandatory gate fails
      throw new BadRequestException(`Withdrawal safety gates failed — DO NOT SUBMIT: ${eligibility.blockingReasons.join(', ')}`);
    }

    // Check approval exists — existing withdrawal approval requirements must not be bypassed
    try {
      const approval = await (this.prisma as any).fundingApproval.findFirst({
        where: { tenantId, withdrawalRequestId: withdrawal.withdrawalRequestId, decision: 'APPROVED' },
      });
      if (!approval && withdrawal.withdrawalRequestId) {
        // Also check fundingRequest approval
        const fundingApproval = await (this.prisma as any).fundingApproval.findFirst({
          where: { tenantId, fundingRequestId: withdrawal.fundingRequestId, decision: 'APPROVED' },
        });
        if (!fundingApproval && !withdrawal.fundingRequestId) {
          // For custody withdrawal directly, require operator approval
          if (!operatorId) throw new BadRequestException('Withdrawal approval required — existing approval requirements must not be bypassed');
        }
      }
    } catch (e) {
      if (e instanceof BadRequestException) throw e;
    }

    // Check provider available
    let provider: any = null;
    try {
      provider = await this.providerFactory.getProviderForNetwork({ networkId: withdrawal.networkId, assetId: withdrawal.assetId });
      const health = await provider.isHealthy?.();
      if (health && !health.healthy) {
        throw new BadRequestException(`Provider unavailable — prevents submission: ${health.reason}`);
      }
    } catch (e) {
      throw new BadRequestException(`Provider unavailable prevents submission: ${(e as Error).message}`);
    }

    // Transition to SUBMITTED
    const allowed = WITHDRAWAL_VALID_TRANSITIONS[currentState] ?? [];
    if (!allowed.includes(CustodyWithdrawalState.SUBMITTED as any)) {
      throw new BadRequestException(`Invalid transition ${currentState} → SUBMITTED`);
    }

    const submitted = await (this.prisma as any).custodyWithdrawal.update({
      where: { id: custodyWithdrawalId },
      data: { state: 'SUBMITTED', submittedAt: new Date(), submittedBy: operatorId },
    });

    // Submit to provider — must be idempotent where supported
    let providerResult: any = null;
    try {
      if (provider.submitTransaction) {
        // Convert amount to base-unit integer using token decimals from authoritative asset metadata
        const decimals = await this.getDecimalsForAsset(withdrawal.assetId);
        const baseUnitAmount = this.toBaseUnit(withdrawal.amount, decimals);

        const idempotencyKey = deterministicIdempotencyKey({
          type: `withdrawal-submit:${withdrawal.assetId}:${withdrawal.networkId}`,
          tenantId,
          walletId: withdrawal.walletId ?? undefined,
          assetId: withdrawal.assetId,
          networkId: withdrawal.networkId,
          externalRef: `${withdrawal.destinationAddress}:${baseUnitAmount}`,
        });

        providerResult = await provider.submitTransaction({
          assetId: withdrawal.assetId,
          networkId: withdrawal.networkId,
          fromAddress: (withdrawal as any).fromAddress ?? 'unknown',
          toAddress: withdrawal.destinationAddress,
          amount: baseUnitAmount,
          walletId: withdrawal.walletId ?? undefined,
          idempotencyKey,
        });

        // Update withdrawal with transaction hash from provider — never invent transaction hashes
        if (providerResult.transactionHash) {
          await (this.prisma as any).custodyWithdrawal.update({
            where: { id: custodyWithdrawalId },
            data: { transactionHash: providerResult.transactionHash, providerReference: providerResult.providerReference, estimatedFee: providerResult.estimatedFee ?? null },
          });

          // Create custody transaction record
          await this.transactionService.createTransaction({
            tenantId,
            walletId: withdrawal.walletId,
            assetId: withdrawal.assetId,
            networkId: withdrawal.networkId,
            direction: 'OUT',
            amount: withdrawal.amount,
            transactionHash: providerResult.transactionHash,
            providerReference: providerResult.providerReference,
            status: 'SUBMITTED',
            estimatedFee: providerResult.estimatedFee ?? null,
            sourceWorkflowType: 'CUSTODY_WITHDRAWAL',
            sourceWorkflowId: custodyWithdrawalId,
            withdrawalId: custodyWithdrawalId,
            submittedAt: new Date(),
            evidence: { destinationAddress: withdrawal.destinationAddress, providerResult: redactSecrets(providerResult) },
          });
        }
      }
    } catch (e) {
      // If provider submission fails, transition to FAILED — never silently succeed
      await (this.prisma as any).custodyWithdrawal.update({
        where: { id: custodyWithdrawalId },
        data: { state: 'FAILED', failedAt: new Date(), failureReason: `Provider submission failed: ${(e as Error).message}` },
      });
      throw new BadRequestException(`Withdrawal provider submission failed: ${(e as Error).message}`);
    }

    await this.auditService.log({
      tenantId,
      walletId: withdrawal.walletId,
      action: 'WITHDRAWAL_SUBMITTED' as any,
      entityType: 'CUSTODY_WITHDRAWAL',
      entityId: custodyWithdrawalId,
      actorId: operatorId,
      fromState: currentState,
      toState: 'SUBMITTED',
      correlationId,
      evidence: { transactionHash: providerResult?.transactionHash, providerReference: providerResult?.providerReference, destinationAddress: withdrawal.destinationAddress },
    });

    this.logger.log({ event: 'custody.withdrawal.submitted', tenantId, custodyWithdrawalId, transactionHash: providerResult?.transactionHash });

    return submitted;
  }

  private async getDecimalsForAsset(assetId: string): Promise<number> {
    try {
      const asset = await (this.prisma as any).custodyAsset.findFirst({ where: { assetId } });
      if (asset) return asset.decimals;
    } catch {}
    return 18; // default, but should be from authoritative metadata
  }

  private toBaseUnit(amount: string, decimals: number): string {
    // Convert decimal string to base-unit integer string — Decimal-safe
    try {
      const [intPart, fracPart = ''] = amount.split('.');
      const paddedFrac = (fracPart + '0'.repeat(decimals)).slice(0, decimals);
      const combined = intPart + paddedFrac;
      return combined.replace(/^0+/, '') || '0';
    } catch {
      return amount;
    }
  }
}

// # Shared request signing, timeout, rate-limit, and error normalization helpers
import { Logger } from '@nestjs/common';
import {
  ExchangeVenue,
  ExchangeEnvironment,
  ExchangeCapability,
  ExchangeBalance,
  ExchangePosition,
  ExchangeOrder,
  ExchangeFill,
  ExchangeSymbol,
  ExchangeCapabilityDiscovery,
  ExchangeConnectivityResult,
  ExchangeConnectionState,
} from './exchange.types';
import {
  ExchangeProvider,
  ExchangeProviderError,
  ExchangeProviderErrorCode,
  ExchangeProviderContext,
  ExchangeServerTime,
  ExchangeAccountMetadata,
} from './exchange-provider.interface';

// ---------------------------------------------------------------------------
// Base provider with common HTTP and safety utilities - no secret logging.
//
// Lives in its own module (it used to be private to exchange-provider.factory.ts)
// so that the per-venue providers under ./venues can extend it without an
// import cycle through the factory that registers them.
// ---------------------------------------------------------------------------

export interface ProviderHttpRequest {
  method: 'GET' | 'POST' | 'DELETE';
  url: string;
  headers?: Record<string, string>;
  body?: string;
  timeoutMs?: number;
}

/** Epoch microseconds for "now", as the decimal string every DTO carries. */
export function nowMicros(): string {
  return (BigInt(Date.now()) * 1000n).toString();
}

/** Converts epoch milliseconds (number or numeric string) to an epoch-micros string. */
export function msToMicros(ms: number | string | null | undefined): string | null {
  if (ms === null || ms === undefined || ms === '') return null;
  const text = typeof ms === 'number' ? Math.trunc(ms).toString() : String(ms).trim();
  if (!/^\d+$/.test(text)) return null;
  return (BigInt(text) * 1000n).toString();
}

/** Converts epoch seconds with an optional fraction ("1700000000.1234") to an epoch-micros string. */
export function secondsToMicros(seconds: number | string | null | undefined): string | null {
  if (seconds === null || seconds === undefined || seconds === '') return null;
  const text = typeof seconds === 'number' ? seconds.toFixed(6) : String(seconds).trim();
  const match = /^(\d+)(?:\.(\d+))?$/.exec(text);
  if (!match) return null;
  const whole = BigInt(match[1]);
  const frac = BigInt(((match[2] ?? '') + '000000').slice(0, 6));
  return (whole * 1_000_000n + frac).toString();
}

/** Converts an ISO-8601 timestamp to an epoch-micros string (millisecond resolution). */
export function isoToMicros(iso: string | null | undefined): string | null {
  if (!iso) return null;
  const ms = Date.parse(iso);
  if (Number.isNaN(ms)) return null;
  return (BigInt(ms) * 1000n).toString();
}

const DECIMAL_RE = /^-?\d+(\.\d+)?$/;

/** True when the value is a plain decimal string ("12", "-0.5"); no exponent, no whitespace. */
export function isDecimalString(value: unknown): value is string {
  return typeof value === 'string' && DECIMAL_RE.test(value);
}

function splitDecimal(value: string): { units: bigint; scale: number } {
  const negative = value.startsWith('-');
  const clean = negative ? value.slice(1) : value;
  const [whole, frac = ''] = clean.split('.');
  const units = BigInt(`${whole}${frac}` || '0');
  return { units: negative ? -units : units, scale: frac.length };
}

function joinDecimal(units: bigint, scale: number): string {
  const negative = units < 0n;
  let digits = (negative ? -units : units).toString();
  if (scale > 0) {
    digits = digits.padStart(scale + 1, '0');
    const whole = digits.slice(0, digits.length - scale);
    const frac = digits.slice(digits.length - scale).replace(/0+$/, '');
    digits = frac ? `${whole}.${frac}` : whole;
  }
  if (digits === '0') return '0';
  return negative ? `-${digits}` : digits;
}

/**
 * Exact decimal addition over strings. Venue amounts are decimal strings and
 * must stay exact: `parseFloat('0.1') + parseFloat('0.2')` is not 0.3, and a
 * balance total that drifts in the 17th digit is a reconciliation break.
 * A non-decimal operand is a venue payload we do not understand - it throws
 * rather than being treated as zero.
 */
export function addDecimalStrings(...values: string[]): string {
  let scale = 0;
  const parts = values.map((value) => {
    if (!isDecimalString(value)) throw new Error(`not a decimal string: ${JSON.stringify(value)}`);
    const part = splitDecimal(value);
    scale = Math.max(scale, part.scale);
    return part;
  });
  let total = 0n;
  for (const part of parts) total += part.units * 10n ** BigInt(scale - part.scale);
  return joinDecimal(total, scale);
}

/** `a - b` over decimal strings, exact. */
export function subtractDecimalStrings(a: string, b: string): string {
  if (!isDecimalString(b)) throw new Error(`not a decimal string: ${JSON.stringify(b)}`);
  return addDecimalStrings(a, b.startsWith('-') ? b.slice(1) : `-${b}`);
}

/** Absolute value of a decimal string. */
export function absDecimalString(value: string): string {
  if (!isDecimalString(value)) throw new Error(`not a decimal string: ${JSON.stringify(value)}`);
  return value.startsWith('-') ? value.slice(1) : value;
}

/** Sign of a decimal string: -1, 0 or 1. */
export function signOfDecimalString(value: string): -1 | 0 | 1 {
  if (!isDecimalString(value)) throw new Error(`not a decimal string: ${JSON.stringify(value)}`);
  const { units } = splitDecimal(value);
  return units < 0n ? -1 : units > 0n ? 1 : 0;
}

/** Number of fractional digits a step/tick string implies ("0.001" -> 3, "1" -> 0, "1e-8" -> 8). */
export function precisionOfStep(step: string | null | undefined, fallback = 8): number {
  if (!step) return fallback;
  const text = String(step).trim();
  const exp = /^\d+(?:\.\d+)?e-(\d+)$/i.exec(text);
  if (exp) return Number(exp[1]);
  if (!isDecimalString(text)) return fallback;
  const frac = text.split('.')[1];
  if (!frac) return 0;
  const trimmed = frac.replace(/0+$/, '');
  return trimmed.length;
}

/**
 * Quote assets recognised when a venue reports a concatenated symbol
 * ("BTCUSDT"), longest first so "USDT" wins over "USD". A symbol with no
 * recognised quote is returned unchanged rather than split at a guess.
 */
const KNOWN_QUOTES = ['FDUSD', 'USDT', 'USDC', 'USDE', 'TUSD', 'BUSD', 'EUR', 'USD', 'GBP', 'TRY', 'BRL', 'JPY', 'AUD', 'BTC', 'ETH', 'DAI', 'BNB', 'SOL'];

export function canonicalFromConcatenated(exchangeSymbol: string): string {
  const upper = String(exchangeSymbol || '').toUpperCase();
  for (const quote of KNOWN_QUOTES) {
    if (upper.length > quote.length && upper.endsWith(quote)) {
      return `${upper.slice(0, upper.length - quote.length)}-${quote}`;
    }
  }
  return upper;
}

export abstract class BaseExchangeProvider implements ExchangeProvider {
  abstract readonly venue: ExchangeVenue;
  abstract readonly displayName: string;
  abstract readonly supportedEnvironments: ExchangeEnvironment[];
  abstract readonly supportedCapabilities: ExchangeCapability[];

  protected readonly logger = new Logger(this.constructor.name);

  protected getRestBaseUrlForEnv(environment: ExchangeEnvironment): string {
    switch (environment) {
      case ExchangeEnvironment.LIVE:
        return this.getLiveRestUrl();
      case ExchangeEnvironment.TESTNET:
        return this.getTestnetRestUrl();
      case ExchangeEnvironment.SANDBOX:
        return this.getSandboxRestUrl();
      default:
        return this.getLiveRestUrl();
    }
  }

  protected abstract getLiveRestUrl(): string;
  protected abstract getTestnetRestUrl(): string;
  protected abstract getSandboxRestUrl(): string;
  protected abstract getLiveWsUrl(): string;
  protected abstract getTestnetWsUrl(): string;
  protected abstract getSandboxWsUrl(): string;

  validateEnvironmentBinding(environment: ExchangeEnvironment, isSandbox: boolean): boolean {
    if (environment === ExchangeEnvironment.LIVE && isSandbox) return false;
    if ((environment === ExchangeEnvironment.TESTNET || environment === ExchangeEnvironment.SANDBOX) && !isSandbox) return false;
    return this.supportedEnvironments.includes(environment);
  }

  getRestBaseUrl(environment: ExchangeEnvironment): string {
    return this.getRestBaseUrlForEnv(environment);
  }

  getWebsocketBaseUrl(environment: ExchangeEnvironment): string {
    switch (environment) {
      case ExchangeEnvironment.LIVE:
        return this.getLiveWsUrl();
      case ExchangeEnvironment.TESTNET:
        return this.getTestnetWsUrl();
      case ExchangeEnvironment.SANDBOX:
        return this.getSandboxWsUrl();
      default:
        return this.getLiveWsUrl();
    }
  }

  protected async httpGet(url: string, headers: Record<string, string> = {}, timeoutMs = 5000): Promise<any> {
    return this.httpRequest({ method: 'GET', url, headers, timeoutMs });
  }

  /**
   * One HTTP exchange with a hard timeout. A non-2xx answer throws an Error
   * carrying `status`, `headers` and the parsed `data`, which is exactly the
   * shape {@link normalizeError} classifies. Nothing about the request
   * (headers carry signatures and keys) is ever put on the error message.
   */
  protected async httpRequest(request: ProviderHttpRequest): Promise<any> {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), request.timeoutMs ?? 5000);
    try {
      const res = await fetch(request.url, {
        method: request.method,
        headers: request.headers ?? {},
        body: request.body,
        signal: controller.signal,
      });
      const text = await res.text();
      let data: any;
      try {
        data = JSON.parse(text);
      } catch {
        data = text;
      }
      if (!res.ok) {
        const err: any = new Error(`HTTP ${res.status} ${res.statusText}`);
        err.status = res.status;
        err.headers = Object.fromEntries(res.headers.entries());
        err.data = data;
        throw err;
      }
      return data;
    } finally {
      clearTimeout(timeout);
    }
  }

  /** Throws AUTH_FAILED when the context carries no key material at all. */
  protected requireCredentials(context: ExchangeProviderContext, needPassphrase = false): void {
    if (!context.credentials?.apiKey || !context.credentials?.apiSecret) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.AUTH_FAILED, 'Missing credentials', context.venue, context.environment, false);
    }
    if (needPassphrase && !context.credentials.passphrase) {
      throw new ExchangeProviderError(
        ExchangeProviderErrorCode.INVALID_CREDENTIALS,
        `${this.venue} requires an API passphrase in addition to key and secret`,
        context.venue,
        context.environment,
        false,
      );
    }
  }

  protected normalizeError(e: any, venue: ExchangeVenue, environment: ExchangeEnvironment): ExchangeProviderError {
    if (e instanceof ExchangeProviderError) return e;
    const status = e.status || 0;
    const msg = (e.message || '').toLowerCase();
    const data = e.data;

    if (status === 401 || status === 403 || msg.includes('api key') || msg.includes('signature') || msg.includes('auth') || (data && (data.code === -2015 || data.code === -2014))) {
      return new ExchangeProviderError(ExchangeProviderErrorCode.AUTH_FAILED, `Authentication failed for ${venue}`, venue, environment, false, null, e);
    }
    if (status === 429 || msg.includes('rate limit') || msg.includes('too many requests') || (data && data.code === -1003)) {
      const retryAfter = e.headers?.['retry-after'] ? parseInt(e.headers['retry-after'], 10) * 1000 : 1000;
      return new ExchangeProviderError(ExchangeProviderErrorCode.RATE_LIMITED, `Rate limited for ${venue}`, venue, environment, true, retryAfter, e);
    }
    if (msg.includes('timeout') || msg.includes('aborted') || status === 504) {
      return new ExchangeProviderError(ExchangeProviderErrorCode.TIMEOUT, `Timeout for ${venue}`, venue, environment, true, 1000, e);
    }
    if (status >= 500) {
      return new ExchangeProviderError(ExchangeProviderErrorCode.SERVER_ERROR, `Server error for ${venue}: ${status}`, venue, environment, true, 1000, e);
    }
    return new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, e.message || `Unknown error for ${venue}`, venue, environment, false, null, e);
  }

  /**
   * The shared connectivity proof for venues that expose key permissions:
   * server time (clock drift), one authenticated read (the key works), and a
   * refusal when the key can withdraw - the platform never accepts a key that
   * could move funds off the venue, whatever else it can do.
   */
  protected async connectivityFromMetadata(context: ExchangeProviderContext): Promise<ExchangeConnectivityResult> {
    const start = Date.now();
    try {
      const serverTime = await this.getServerTime(context);
      const metadata = await this.getAccountMetadata(context);
      if (metadata.canWithdraw) {
        throw new ExchangeProviderError(ExchangeProviderErrorCode.WITHDRAWAL_NOT_ALLOWED, 'Withdrawal permission detected', context.venue, context.environment, false);
      }
      return {
        connected: true,
        degraded: !metadata.canTrade,
        state: metadata.canTrade ? ExchangeConnectionState.CONNECTED : ExchangeConnectionState.DEGRADED,
        latencyMs: Date.now() - start,
        serverTimeMicros: serverTime.serverTimeMicros,
        clockDriftMs: serverTime.driftMs,
        capabilities: this.supportedCapabilities,
        failureCode: null,
        failureReason: metadata.canTrade ? null : 'API key is read-only: balances and history sync, order placement will be refused by the venue',
        isSimulated: context.isSandbox,
        environment: context.environment,
      };
    } catch (e: any) {
      throw this.normalizeError(e, context.venue, context.environment);
    }
  }

  protected serverTimeFromMs(serverTimeMs: number): ExchangeServerTime {
    const localMs = Date.now();
    return {
      serverTimeMicros: (BigInt(Math.trunc(serverTimeMs)) * 1000n).toString(),
      localTimeMicros: (BigInt(localMs) * 1000n).toString(),
      driftMs: localMs - Math.trunc(serverTimeMs),
    };
  }

  abstract testConnectivity(context: ExchangeProviderContext): Promise<any>;
  abstract getServerTime(context: ExchangeProviderContext): Promise<ExchangeServerTime>;
  abstract getAccountMetadata(context: ExchangeProviderContext): Promise<ExchangeAccountMetadata>;
  abstract getCapabilities(context: ExchangeProviderContext): Promise<ExchangeCapabilityDiscovery>;
  abstract getBalances(context: ExchangeProviderContext): Promise<ExchangeBalance[]>;
  abstract getPositions(context: ExchangeProviderContext): Promise<ExchangePosition[]>;
  abstract getOpenOrders(context: ExchangeProviderContext, symbol?: string): Promise<ExchangeOrder[]>;
  abstract getOrderHistory(context: ExchangeProviderContext, symbol?: string, limit?: number): Promise<ExchangeOrder[]>;
  abstract getTradeHistory(context: ExchangeProviderContext, symbol?: string, limit?: number): Promise<ExchangeFill[]>;
  abstract getSymbols(context: ExchangeProviderContext): Promise<ExchangeSymbol[]>;
}

import { HttpException, Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { ExchangeAccountRepository } from './exchange-account.repository';
import { ExchangeCredentialService } from './exchange-credential.service';
import { ExchangeRegistryService } from './exchange-registry.service';
import { ExchangeProviderFactory } from './exchange-provider.factory';
import { ExchangeConnectivityService } from './exchange-connectivity.service';
import { ExchangeAuditService } from './exchange-audit.service';
import { ExchangeHealthService } from './exchange-health.service';
import { ExchangeSymbolService } from './exchange-symbol.service';
import { ExchangeVenue, ExchangeEnvironment, ExchangeAccountState, ExchangeSafeReference, maskApiKey } from './exchange.types';
import { ExchangeProviderError, ExchangeProviderErrorCode } from './exchange-provider.interface';
import { PlanLimitExchangeAccountsGuard } from '../billing/enforcement/plan-limit-exchange-accounts.guard';
import { ExecutionSafetyService } from '../execution/execution-safety.service';

export interface ConnectAccountInput {
  tenantId: string;
  userId: string;
  venue: ExchangeVenue;
  environment: ExchangeEnvironment;
  label: string;
  apiKey: string;
  apiSecret: string;
  passphrase?: string;
  credentialSource: 'ENVELOPE_DB' | 'SECRET_MANAGER' | 'ENVIRONMENT';
  credentialRef?: string | null;
  idempotencyKey?: string | null;
  ipAllowlist?: string[];
  actorId: string;
  requestId?: string;
}

export interface EnableAccountInput {
  tenantId: string;
  accountId: string;
  actorId: string;
  requestId?: string;
  liveTradingRequested?: boolean;
}

/**
 * Main exchange-account orchestration: connect, validate, enable/disable, rotate credentials, capability discovery, health state, and account lifecycle.
 * Flow: Request → entitlement/plan limit check → secure credential reference → provider validation → capability discovery → health check → activate
 * Important: A connected account must NOT automatically receive live trading permission.
 */
@Injectable()
export class ExchangeAccountService {
  private readonly logger = new Logger(ExchangeAccountService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly accountRepo: ExchangeAccountRepository,
    private readonly credentialService: ExchangeCredentialService,
    private readonly registry: ExchangeRegistryService,
    private readonly providerFactory: ExchangeProviderFactory,
    private readonly connectivityService: ExchangeConnectivityService,
    private readonly auditService: ExchangeAuditService,
    private readonly healthService: ExchangeHealthService,
    private readonly symbolService: ExchangeSymbolService,
    private readonly limitGuard: PlanLimitExchangeAccountsGuard,
    private readonly safetyService: ExecutionSafetyService,
  ) {}

  private async resolveExchangeId(venue: ExchangeVenue): Promise<string> {
    // Find or create Exchange entry in Prisma
    let exchange = await this.prisma.exchange.findFirst({ where: { venue: venue as any } });
    if (!exchange) {
      // Create exchange entry if not exists - safe metadata only
      const registryEntry = this.registry.getVenue(venue);
      if (!registryEntry) {
        throw new ExchangeProviderError(ExchangeProviderErrorCode.PROVIDER_UNAVAILABLE, `Venue ${venue} not in registry`, venue, ExchangeEnvironment.LIVE, false);
      }
      exchange = await this.prisma.exchange.create({
        data: {
          venue: venue as any,
          name: registryEntry.displayName,
          isEnabled: true,
          tradingEnabled: false, // Must be explicitly enabled by operator
          supportedMarketTypes: ['SPOT'] as any,
          restBaseUrl: registryEntry.baseRestUrlLive,
          wsBaseUrl: registryEntry.baseWsUrlLive,
          requiresPassphrase: registryEntry.requiresPassphrase,
          supportsSandbox: true,
          weightLimitPerMinute: 1200,
          maxOrdersPerSecond: 5,
          maxLeverage: 1,
          defaultBookDepth: 50,
        },
      });
    }
    return exchange.id;
  }

  async connectAccount(input: ConnectAccountInput): Promise<ExchangeSafeReference> {
    // 1. Validate venue and environment
    if (!this.registry.isVenueSupported(input.venue) && input.venue !== ExchangeVenue.OTHER_CONFIGURED) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.PROVIDER_UNAVAILABLE, `Unknown venue ${input.venue}`, input.venue, input.environment, false);
    }

    if (!this.registry.isEnvironmentSupported(input.venue, input.environment)) {
      throw new ExchangeProviderError(
        ExchangeProviderErrorCode.NOT_SUPPORTED,
        `Environment ${input.environment} not supported for ${input.venue}`,
        input.venue,
        input.environment,
        false,
      );
    }

    // 2. Environment binding validation - LIVE vs TESTNET fail closed
    const isSandbox = input.environment !== ExchangeEnvironment.LIVE;
    if (!this.registry.validateEnvironmentBinding(input.venue, input.environment, isSandbox)) {
      throw new ExchangeProviderError(
        ExchangeProviderErrorCode.ENVIRONMENT_MISMATCH,
        `Environment mismatch: ${input.environment} isSandbox=${isSandbox}`,
        input.venue,
        input.environment,
        false,
      );
    }

    // 3. Entitlement/plan limit check - use existing maxExchangeAccountsPerUser
    const enforcementActor = { tenantId: input.tenantId, userId: input.actorId } as any;
    try {
      await this.limitGuard.reserve(enforcementActor, input.userId);
    } catch (e: any) {
      this.logger.warn(`Plan limit exceeded tenant=${input.tenantId} user=${input.userId} venue=${input.venue}`);
      throw e;
    }

    let accountRecord;
    try {
      // 4. Resolve exchangeId
      const exchangeId = await this.resolveExchangeId(input.venue);

      // 5. Create account metadata first (without secrets)
      accountRecord = await this.accountRepo.create({
        tenantId: input.tenantId,
        userId: input.userId,
        exchangeId,
        venue: input.venue,
        label: input.label,
        environment: input.environment,
        isSandbox,
        credentialSource: input.credentialSource,
        credentialRef: input.credentialRef || null,
        apiKeyLastFour: input.apiKey.slice(-4),
        idempotencyKey: input.idempotencyKey || null,
      });

      // 6. Secure credential reference - never store plaintext
      await this.credentialService.createCredentialReference({
        tenantId: input.tenantId,
        userId: input.userId,
        accountId: accountRecord.id,
        venue: input.venue,
        environment: input.environment,
        apiKey: input.apiKey,
        apiSecret: input.apiSecret,
        passphrase: input.passphrase,
        credentialSource: input.credentialSource,
        credentialRef: input.credentialRef || null,
      });

      // 7. Provider validation - connectivity check without placing orders
      const connectivityResult = await this.connectivityService.checkConnectivity({
        tenantId: input.tenantId,
        accountId: accountRecord.id,
        venue: input.venue,
        environment: input.environment,
      });

      if (!connectivityResult.connected) {
        await this.accountRepo.updateStatus(accountRecord.id, input.tenantId, ExchangeAccountState.ERROR, connectivityResult.failureCode, connectivityResult.failureReason);
        await this.auditService.record({
          tenantId: input.tenantId,
          accountId: accountRecord.id,
          venue: input.venue,
          environment: input.environment,
          event: 'EXCHANGE_ACCOUNT_CONNECTED' as any,
          result: 'FAILURE',
          actorId: input.actorId,
          safeMetadata: { failureCode: connectivityResult.failureCode, latencyMs: connectivityResult.latencyMs },
          requestId: input.requestId,
        });
        // Keep the connectivity check's own classification: an unreachable
        // venue is not a refused key, and the client message depends on it.
        const knownFailure = Object.values(ExchangeProviderErrorCode).includes(connectivityResult.failureCode as ExchangeProviderErrorCode)
          ? (connectivityResult.failureCode as ExchangeProviderErrorCode)
          : ExchangeProviderErrorCode.AUTH_FAILED;
        throw new ExchangeProviderError(
          knownFailure,
          `Connectivity check failed: ${connectivityResult.failureReason || connectivityResult.failureCode}`,
          input.venue,
          input.environment,
          false,
        );
      }

      // 8. Capability discovery
      const capabilities = await this.connectivityService.discoverCapabilities({
        tenantId: input.tenantId,
        accountId: accountRecord.id,
        venue: input.venue,
        environment: input.environment,
      });

      // 9. Health check
      await this.healthService.checkHealth({
        tenantId: input.tenantId,
        accountId: accountRecord.id,
        venue: input.venue,
        environment: input.environment,
      });

      // 10. Activate - but NOT live trading
      const activated = await this.accountRepo.enableAccount(accountRecord.id, input.tenantId);
      if (!activated) {
        throw new ExchangeProviderError(ExchangeProviderErrorCode.SERVER_ERROR, 'Failed to activate account', input.venue, input.environment, false);
      }

      await this.accountRepo.updateSyncMetadata(accountRecord.id, input.tenantId, {
        lastSyncAt: new Date(),
        capabilities: capabilities.capabilities,
      });

      await this.auditService.record({
        tenantId: input.tenantId,
        accountId: accountRecord.id,
        venue: input.venue,
        environment: input.environment,
        event: 'EXCHANGE_ACCOUNT_CONNECTED',
        result: 'SUCCESS',
        actorId: input.actorId,
        safeMetadata: { capabilities: capabilities.capabilities, latencyMs: connectivityResult.latencyMs, isSandbox },
        requestId: input.requestId,
      });

      await this.auditService.record({
        tenantId: input.tenantId,
        accountId: accountRecord.id,
        venue: input.venue,
        environment: input.environment,
        event: 'EXCHANGE_ACCOUNT_ACTIVATED',
        result: 'SUCCESS',
        actorId: input.actorId,
        safeMetadata: { venue: input.venue, environment: input.environment },
        requestId: input.requestId,
      });

      this.logger.log(`Account connected and activated id=${accountRecord.id} tenant=${input.tenantId} venue=${input.venue} env=${input.environment}`);

      return this.toSafeReference(activated);
    } catch (e: any) {
      // Release slot on failure
      try {
        await this.limitGuard.release(enforcementActor, input.userId);
      } catch {}

      // If the account row was created but the connect failed later, discard
      // it: never leave it ACTIVE, and never let it keep holding the key.
      if (accountRecord) {
        try {
          await this.accountRepo.discardFailedConnection(accountRecord.id, input.tenantId, String(e?.code || 'CONNECT_FAILED'));
        } catch (discardError: any) {
          this.logger.error(`Failed to discard failed connection id=${accountRecord.id} tenant=${input.tenantId} error=${discardError?.message}`);
        }
      }

      if (e instanceof ExchangeProviderError || e instanceof HttpException) throw e;
      this.logger.error(`Failed to connect account tenant=${input.tenantId} venue=${input.venue} error=${e.message}`);
      throw new ExchangeProviderError(ExchangeProviderErrorCode.SERVER_ERROR, `Failed to connect account: ${e.message}`, input.venue, input.environment, false);
    }
  }

  async getAccount(tenantId: string, accountId: string, userId?: string | null): Promise<ExchangeSafeReference | null> {
    const record = await this.accountRepo.findByIdWithUserCheck(accountId, tenantId, userId);
    if (!record) return null;
    return this.toSafeReference(record);
  }

  async listAccounts(
    tenantId: string,
    filters: { userId?: string; venue?: ExchangeVenue; environment?: ExchangeEnvironment; status?: ExchangeAccountState; page?: number; limit?: number; search?: string },
    requesterUserId?: string | null,
    isPrivileged?: boolean,
  ): Promise<{ data: ExchangeSafeReference[]; total: number }> {
    // Tenant isolation + user isolation for non-privileged
    const effectiveUserId = isPrivileged ? filters.userId : requesterUserId || filters.userId;
    const result = await this.accountRepo.listByTenant(tenantId, { ...filters, userId: effectiveUserId || undefined });
    return { data: result.data.map((r) => this.toSafeReference(r)), total: result.total };
  }

  async disableAccount(tenantId: string, accountId: string, actorId: string, reason?: string, requestId?: string): Promise<ExchangeSafeReference | null> {
    const record = await this.accountRepo.findById(accountId, tenantId);
    if (!record) return null;

    const disabled = await this.accountRepo.disableAccount(accountId, tenantId, reason);
    if (!disabled) return null;

    await this.auditService.record({
      tenantId,
      accountId,
      venue: record.venue,
      environment: record.environment,
      event: 'EXCHANGE_ACCOUNT_DISABLED',
      result: 'SUCCESS',
      actorId,
      safeMetadata: { reason: reason?.substring(0, 200) },
      requestId,
    });

    return this.toSafeReference(disabled);
  }

  async revokeAccount(tenantId: string, accountId: string, actorId: string, requestId?: string): Promise<ExchangeSafeReference | null> {
    const record = await this.accountRepo.findById(accountId, tenantId);
    if (!record) return null;

    // Revoke credential first
    await this.credentialService.revokeCredential(tenantId, accountId, record.venue, record.environment);

    const revoked = await this.accountRepo.revokeAccount(accountId, tenantId);
    if (!revoked) return null;

    // Release plan limit slot
    if (record.userId) {
      try {
        const actor = { tenantId, userId: actorId } as any;
        await this.limitGuard.release(actor, record.userId);
      } catch {}
    }

    await this.auditService.record({
      tenantId,
      accountId,
      venue: record.venue,
      environment: record.environment,
      event: 'EXCHANGE_ACCOUNT_REVOKED',
      result: 'SUCCESS',
      actorId,
      safeMetadata: { venue: record.venue },
      requestId,
    });

    return this.toSafeReference(revoked);
  }

  async rotateCredentials(input: {
    tenantId: string;
    accountId: string;
    venue: ExchangeVenue;
    environment: ExchangeEnvironment;
    apiKey: string;
    apiSecret: string;
    passphrase?: string;
    credentialSource: 'ENVELOPE_DB' | 'SECRET_MANAGER' | 'ENVIRONMENT';
    credentialRef?: string | null;
    actorId: string;
    requestId?: string;
  }): Promise<ExchangeSafeReference | null> {
    const record = await this.accountRepo.findById(input.accountId, input.tenantId);
    if (!record) return null;

    // Environment mismatch must fail closed
    if (record.environment !== input.environment) {
      throw new ExchangeProviderError(
        ExchangeProviderErrorCode.ENVIRONMENT_MISMATCH,
        `Cannot rotate with different environment: existing=${record.environment} new=${input.environment}`,
        input.venue,
        input.environment,
        false,
      );
    }

    const rotated = await this.credentialService.rotateCredential({
      tenantId: input.tenantId,
      userId: record.userId,
      accountId: input.accountId,
      venue: input.venue,
      environment: input.environment,
      apiKey: input.apiKey,
      apiSecret: input.apiSecret,
      passphrase: input.passphrase,
      credentialSource: input.credentialSource,
      credentialRef: input.credentialRef || null,
    });

    // Re-validate connectivity after rotation
    const connectivity = await this.connectivityService.checkConnectivity({
      tenantId: input.tenantId,
      accountId: input.accountId,
      venue: input.venue,
      environment: input.environment,
    });

    if (!connectivity.connected) {
      await this.accountRepo.updateStatus(input.accountId, input.tenantId, ExchangeAccountState.ERROR, connectivity.failureCode, connectivity.failureReason);
      throw new ExchangeProviderError(ExchangeProviderErrorCode.AUTH_FAILED, `Post-rotation connectivity failed: ${connectivity.failureReason}`, input.venue, input.environment, false);
    }

    await this.auditService.record({
      tenantId: input.tenantId,
      accountId: input.accountId,
      venue: input.venue,
      environment: input.environment,
      event: 'CREDENTIAL_ROTATED',
      result: 'SUCCESS',
      actorId: input.actorId,
      safeMetadata: { apiKeyLastFour: rotated.apiKeyLastFour },
      requestId: input.requestId,
    });

    const updated = await this.accountRepo.findById(input.accountId, input.tenantId);
    return updated ? this.toSafeReference(updated) : null;
  }

  async enableLiveTrading(input: EnableAccountInput): Promise<ExchangeSafeReference | null> {
    // CRITICAL: Must call existing live safety gate
    const safety = await this.safetyService.safetySummary(input.tenantId);
    if (!safety.wouldTransmitLiveOrder) {
      this.logger.warn(`Live trading enable blocked by safety gate tenant=${input.tenantId} account=${input.accountId} reasons=${safety.blockingReasons.join(', ')}`);
      throw new ExchangeProviderError(
        ExchangeProviderErrorCode.PERMISSION_DENIED,
        `Live trading blocked by safety gate: ${safety.blockingReasons.join(', ')}`,
        ExchangeVenue.BINANCE,
        ExchangeEnvironment.LIVE,
        false,
      );
    }

    const record = await this.accountRepo.findById(input.accountId, input.tenantId);
    if (!record) return null;

    if (record.environment !== ExchangeEnvironment.LIVE) {
      throw new ExchangeProviderError(
        ExchangeProviderErrorCode.ENVIRONMENT_MISMATCH,
        'Live trading can only be enabled for LIVE environment accounts',
        record.venue,
        record.environment,
        false,
      );
    }

    if (record.status !== ExchangeAccountState.ACTIVE) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.PERMISSION_DENIED, 'Account must be ACTIVE to enable live trading', record.venue, record.environment, false);
    }

    const updated = await this.accountRepo.updateLiveTradingEnabled(input.accountId, input.tenantId, true);
    if (!updated) return null;

    await this.auditService.record({
      tenantId: input.tenantId,
      accountId: input.accountId,
      venue: updated.venue,
      environment: updated.environment,
      event: 'EXCHANGE_ACCOUNT_ACTIVATED',
      result: 'SUCCESS',
      actorId: input.actorId,
      safeMetadata: { liveTradingEnabled: true, safetyGatePassed: true },
      requestId: input.requestId,
    });

    return this.toSafeReference(updated);
  }

  async refreshCapabilities(tenantId: string, accountId: string, actorId: string, requestId?: string): Promise<ExchangeSafeReference | null> {
    const record = await this.accountRepo.findById(accountId, tenantId);
    if (!record) return null;

    const capabilities = await this.connectivityService.discoverCapabilities({
      tenantId,
      accountId,
      venue: record.venue,
      environment: record.environment,
    });

    await this.accountRepo.updateSyncMetadata(accountId, tenantId, { capabilities: capabilities.capabilities, lastSyncAt: new Date() });

    await this.auditService.record({
      tenantId,
      accountId,
      venue: record.venue,
      environment: record.environment,
      event: 'CAPABILITIES_DISCOVERED',
      result: 'SUCCESS',
      actorId,
      safeMetadata: { capabilities: capabilities.capabilities },
      requestId,
    });

    const updated = await this.accountRepo.findById(accountId, tenantId);
    return updated ? this.toSafeReference(updated) : null;
  }

  private toSafeReference(record: any): ExchangeSafeReference {
    return {
      accountId: record.id,
      tenantId: record.tenantId,
      userId: record.userId,
      venue: record.venue,
      environment: record.environment,
      label: record.label,
      maskedApiKey: record.apiKeyLastFour ? maskApiKey(`****${record.apiKeyLastFour}`) : '****',
      status: record.status,
      connectionState: record.connectionState,
      healthState: record.healthState,
      capabilities: record.capabilities || [],
      isSandbox: record.isSandbox,
      liveTradingEnabled: record.liveTradingEnabled,
      credentialRef: record.credentialRef,
      credentialSource: record.credentialSource,
      lastVerifiedAt: record.lastVerifiedAt ? new Date(record.lastVerifiedAt).toISOString() : null,
      lastSyncAt: record.lastSyncAt ? new Date(record.lastSyncAt).toISOString() : null,
      lastErrorCode: record.lastErrorCode,
      createdAt: new Date(record.createdAt).toISOString(),
      updatedAt: new Date(record.updatedAt).toISOString(),
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { ExchangeVenue, ExchangeEnvironment, sanitizeExchangeMetadata } from './exchange.types';
import { randomUUID } from 'crypto';

export enum ExchangeAuditEvent {
  EXCHANGE_ACCOUNT_CONNECTED = 'EXCHANGE_ACCOUNT_CONNECTED',
  EXCHANGE_ACCOUNT_ACTIVATED = 'EXCHANGE_ACCOUNT_ACTIVATED',
  EXCHANGE_ACCOUNT_DISABLED = 'EXCHANGE_ACCOUNT_DISABLED',
  EXCHANGE_ACCOUNT_REVOKED = 'EXCHANGE_ACCOUNT_REVOKED',
  CREDENTIAL_CREATED = 'CREDENTIAL_CREATED',
  CREDENTIAL_ROTATED = 'CREDENTIAL_ROTATED',
  CREDENTIAL_REVOKED = 'CREDENTIAL_REVOKED',
  CONNECTIVITY_CHECKED = 'CONNECTIVITY_CHECKED',
  CAPABILITIES_DISCOVERED = 'CAPABILITIES_DISCOVERED',
  BALANCE_SYNCED = 'BALANCE_SYNCED',
  POSITION_SYNCED = 'POSITION_SYNCED',
  ORDER_SYNCED = 'ORDER_SYNCED',
  EXCHANGE_HEALTH_CHANGED = 'EXCHANGE_HEALTH_CHANGED',
  RATE_LIMIT_TRIGGERED = 'RATE_LIMIT_TRIGGERED',
  ROUTING_DECISION = 'ROUTING_DECISION',
}

export interface ExchangeAuditInput {
  tenantId: string;
  accountId: string;
  venue: ExchangeVenue;
  environment: ExchangeEnvironment;
  event: ExchangeAuditEvent | string;
  result: 'SUCCESS' | 'FAILURE';
  actorId?: string | null;
  targetType?: string | null;
  targetId?: string | null;
  safeMetadata?: Record<string, any> | null;
  ipHash?: string | null;
  requestId?: string | null;
}

/**
 * Structured audit events for account connection, credential lifecycle, sync, health failures, routing decisions, and privileged exchange operations without secrets.
 * Never log API key, secret, passphrase, private key, withdrawal credential, authentication token.
 */
@Injectable()
export class ExchangeAuditService {
  private readonly logger = new Logger(ExchangeAuditService.name);

  constructor(private readonly prisma: PrismaService) {}

  async record(input: ExchangeAuditInput): Promise<void> {
    const safeMeta = input.safeMetadata ? sanitizeExchangeMetadata(input.safeMetadata) : {};

    try {
      // Try to persist to AuditLog with safe metadata
      await this.prisma.auditLog.create({
        data: {
          id: randomUUID(),
          tenantId: input.tenantId,
          actorType: input.actorId ? 'USER' : 'SYSTEM',
          actorId: input.actorId || null,
          action: input.event,
          outcome: input.result === 'SUCCESS' ? 'SUCCESS' : 'FAILURE',
          resourceType: input.targetType || 'ExchangeAccount',
          resourceId: input.targetId || input.accountId,
          description: `${input.event} venue=${input.venue} env=${input.environment} account=${input.accountId} result=${input.result}`.substring(0, 500),
          metadata: {
            venue: input.venue,
            environment: input.environment,
            accountId: input.accountId,
            ...safeMeta,
          },
          ipHash: input.ipHash || null,
          requestId: input.requestId || null,
          createdAt: new Date(),
        },
      });

      // Log structured without secrets
      const logPayload = {
        event: 'exchange.audit',
        auditEvent: input.event,
        tenantId: input.tenantId,
        accountId: input.accountId,
        venue: input.venue,
        environment: input.environment,
        result: input.result,
        actorId: input.actorId,
        requestId: input.requestId,
      };

      if (input.result === 'FAILURE') {
        this.logger.warn(logPayload, `${input.event} failed tenant=${input.tenantId} account=${input.accountId}`);
      } else {
        this.logger.log(`${input.event} tenant=${input.tenantId} account=${input.accountId} venue=${input.venue} env=${input.environment}`);
      }
    } catch (e: any) {
      this.logger.error(`Failed to record exchange audit event ${input.event}: ${e.message}`);
    }
  }

  async listAuditLogs(tenantId: string, filters?: { accountId?: string; venue?: ExchangeVenue; event?: string; fromDate?: Date; toDate?: Date; page?: number; limit?: number }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const skip = (page - 1) * limit;

    const where: any = { tenantId };
    if (filters?.accountId) where.resourceId = filters.accountId;
    if (filters?.event) where.action = filters.event;
    if (filters?.venue) where.metadata = { path: ['venue'], equals: filters.venue };
    if (filters?.fromDate || filters?.toDate) {
      where.createdAt = {};
      if (filters.fromDate) where.createdAt.gte = filters.fromDate;
      if (filters.toDate) where.createdAt.lte = filters.toDate;
    }

    const [data, total] = await this.prisma.$transaction([
      this.prisma.auditLog.findMany({ where, orderBy: { createdAt: 'desc' }, skip, take: limit }),
      this.prisma.auditLog.count({ where }),
    ]);

    return { data, total, page, limit };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { ExchangeVenue, ExchangeEnvironment, ExchangeSyncState, ExchangeBalance, normalizeTimestampMicros } from './exchange.types';
import { ExchangeProviderFactory } from './exchange-provider.factory';
import { ExchangeCredentialService } from './exchange-credential.service';
import { ExchangeAccountRepository } from './exchange-account.repository';
import { ExchangeAuditService } from './exchange-audit.service';
import { ExchangeProviderContext } from './exchange-provider.interface';
import { CacheService } from '../../infrastructure/redis/cache.service';

/**
 * Idempotent balances synchronization from exchange into existing account/read-model architecture with Decimal-safe quantities.
 * Do not use JavaScript floating-point arithmetic for monetary quantities. If exchange returns amount as string, preserve precision.
 */
@Injectable()
export class ExchangeBalanceSyncService {
  private readonly logger = new Logger(ExchangeBalanceSyncService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly providerFactory: ExchangeProviderFactory,
    private readonly credentialService: ExchangeCredentialService,
    private readonly accountRepo: ExchangeAccountRepository,
    private readonly auditService: ExchangeAuditService,
    private readonly cache: CacheService,
  ) {}

  private toDecimalString(value: string | number | null | undefined): string {
    if (value === null || value === undefined) return '0';
    if (typeof value === 'string') {
      // Validate decimal string - preserve precision, no float conversion
      if (!/^-?\d+(\.\d+)?$/.test(value.trim())) {
        // If not valid decimal, try to parse but log warning
        this.logger.warn(`Invalid decimal string received: ${value}`);
        return '0';
      }
      return value.trim();
    }
    // If number, convert to string preserving as much as possible - but warn that precision may be lost
    // For financial quantities, provider should return string per spec
    this.logger.warn(`Balance amount received as number ${value} - should be string for precision`);
    return value.toString();
  }

  private addDecimalStrings(a: string, b: string): string {
    // Decimal-safe addition without float - use BigInt for integer part and handle decimals
    // Simplified: use decimal.js-like logic with string manipulation
    try {
      const [aInt, aDec = ''] = a.split('.');
      const [bInt, bDec = ''] = b.split('.');
      const maxDec = Math.max(aDec.length, bDec.length);
      const aPadded = aDec.padEnd(maxDec, '0');
      const bPadded = bDec.padEnd(maxDec, '0');

      const aFull = BigInt(aInt + aPadded);
      const bFull = BigInt(bInt + bPadded);
      const sum = aFull + bFull;
      const sumStr = sum.toString().padStart(maxDec + 1, '0');
      if (maxDec === 0) return sumStr;
      const intPart = sumStr.slice(0, -maxDec) || '0';
      const decPart = sumStr.slice(-maxDec).replace(/0+$/, '') || '0';
      // Return with preserved decimals if needed, but for total we need sum
      // For simplicity, if decPart is 0, return intPart
      if (decPart === '0') return intPart;
      return `${intPart}.${decPart}`;
    } catch {
      // Fallback - should not happen, but avoid float
      return (BigInt(a.split('.')[0] || '0') + BigInt(b.split('.')[0] || '0')).toString();
    }
  }

  async syncBalances(input: { tenantId: string; accountId: string; venue: ExchangeVenue; environment: ExchangeEnvironment; actorId?: string; requestId?: string }): Promise<{ state: ExchangeSyncState; processed: number; created: number; updated: number; skipped: number; durationMs: number }> {
    const start = Date.now();
    const isSandbox = input.environment !== ExchangeEnvironment.LIVE;

    const account = await this.accountRepo.findById(input.accountId, input.tenantId);
    if (!account) {
      throw new Error(`Account ${input.accountId} not found for tenant ${input.tenantId}`);
    }

    let provider;
    try {
      provider = this.providerFactory.getProvider(input.venue, input.environment);
    } catch (e: any) {
      this.logger.warn(`Provider unavailable for balance sync tenant=${input.tenantId} account=${input.accountId} error=${e.message}`);
      return { state: ExchangeSyncState.FAILED, processed: 0, created: 0, updated: 0, skipped: 0, durationMs: Date.now() - start };
    }

    let credentials;
    try {
      credentials = await this.credentialService.getDecryptedCredentialsForProvider(input.tenantId, input.accountId, input.venue, input.environment);
    } catch (e: any) {
      this.logger.warn(`Credential unavailable for balance sync tenant=${input.tenantId} account=${input.accountId} error=${e.message}`);
      return { state: ExchangeSyncState.FAILED, processed: 0, created: 0, updated: 0, skipped: 0, durationMs: Date.now() - start };
    }

    const context: ExchangeProviderContext = {
      tenantId: input.tenantId,
      accountId: input.accountId,
      venue: input.venue,
      environment: input.environment,
      isSandbox,
      credentials: {
        apiKey: credentials.apiKey,
        apiSecret: credentials.apiSecret,
        passphrase: credentials.passphrase,
        environment: input.environment,
        isSandbox,
      },
      credentialRef: null,
    };

    let balances: ExchangeBalance[];
    try {
      balances = await provider.getBalances(context);
    } catch (e: any) {
      this.logger.error(`Failed to fetch balances tenant=${input.tenantId} account=${input.accountId} venue=${input.venue} error=${e.message}`);
      await this.auditService.record({
        tenantId: input.tenantId,
        accountId: input.accountId,
        venue: input.venue,
        environment: input.environment,
        event: 'BALANCE_SYNCED',
        result: 'FAILURE',
        actorId: input.actorId,
        safeMetadata: { errorCode: e.code || 'FETCH_FAILED', isSandbox },
        requestId: input.requestId,
      });
      return { state: ExchangeSyncState.FAILED, processed: 0, created: 0, updated: 0, skipped: 0, durationMs: Date.now() - start };
    }

    // Idempotent upsert - tenant/account scoped, provider reference based, timestamp-aware
    let created = 0;
    let updated = 0;
    let skipped = 0;

    for (const balance of balances) {
      try {
        const free = this.toDecimalString(balance.free);
        const locked = this.toDecimalString(balance.locked);
        const total = this.toDecimalString(balance.total);

        // Validate free+locked ≈ total within small tolerance? We preserve provider values, do not recalculate
        // But we ensure total is at least free if provider gives inconsistent data
        const observedAtMicros = BigInt(normalizeTimestampMicros(balance.timestampMicros));
        const venueUpdatedAtMicros = balance.providerReference ? observedAtMicros : null;

        // Use idempotency key: tenantId + accountId + asset + providerReference
        const existing = await this.prisma.accountBalanceSnapshot.findFirst({
          where: { tenantId: input.tenantId, accountId: input.accountId, asset: balance.asset },
        });

        if (existing) {
          // Check if same timestamp and same values - skip duplicate
          const existingObserved = existing.observedAtMicros ? BigInt(existing.observedAtMicros.toString()) : BigInt(0);
          if (existingObserved === observedAtMicros && existing.free.toString() === free && existing.locked.toString() === locked) {
            skipped++;
            continue;
          }

          // Update with timestamp awareness - only update if newer
          if (observedAtMicros >= existingObserved) {
            await this.prisma.accountBalanceSnapshot.update({
              where: { id: existing.id },
              data: {
                free: free as any,
                locked: locked as any,
                total: total as any,
                observedAtMicros: observedAtMicros as any,
                venueUpdatedAtMicros: venueUpdatedAtMicros as any,
                isSimulated: balance.isSimulated,
                updatedAt: new Date(),
              },
            });
            updated++;
          } else {
            skipped++;
          }
        } else {
          await this.prisma.accountBalanceSnapshot.create({
            data: {
              id: this.generateId(),
              tenantId: input.tenantId,
              accountId: input.accountId,
              asset: balance.asset,
              free: free as any,
              locked: locked as any,
              total: total as any,
              observedAtMicros: observedAtMicros as any,
              venueUpdatedAtMicros: venueUpdatedAtMicros as any,
              isSimulated: balance.isSimulated,
              createdAt: new Date(),
              updatedAt: new Date(),
            },
          });
          created++;
        }

        // Cache latest balance for fast reads - idempotent
        try {
          await this.cache.set(`balance:${input.tenantId}:${input.accountId}:${balance.asset}`, { free, locked, total, observedAtMicros: observedAtMicros.toString() }, 300);
        } catch {}
      } catch (e: any) {
        this.logger.warn(`Failed to sync balance asset=${balance.asset} tenant=${input.tenantId} account=${input.accountId} error=${e.message}`);
        skipped++;
      }
    }

    const durationMs = Date.now() - start;

    // Update last sync metadata
    await this.accountRepo.updateSyncMetadata(input.accountId, input.tenantId, { lastSyncAt: new Date() });

    await this.auditService.record({
      tenantId: input.tenantId,
      accountId: input.accountId,
      venue: input.venue,
      environment: input.environment,
      event: 'BALANCE_SYNCED',
      result: 'SUCCESS',
      actorId: input.actorId,
      safeMetadata: { processed: balances.length, created, updated, skipped, durationMs, isSandbox },
      requestId: input.requestId,
    });

    this.logger.log(`Balance sync completed tenant=${input.tenantId} account=${input.accountId} processed=${balances.length} created=${created} updated=${updated} skipped=${skipped} duration=${durationMs}ms`);

    return { state: ExchangeSyncState.COMPLETED, processed: balances.length, created, updated, skipped, durationMs };
  }

  private generateId(): string {
    return `${Date.now().toString(36)}-${Math.random().toString(36).substring(2, 10)}-${Math.random().toString(36).substring(2, 10)}`;
  }
}

/**
 * Connectivity checks name the real secret-manager failure.
 *
 * Every PROVIDER_UNAVAILABLE failure from a SECRET_MANAGER credential used to
 * be reported as "Secret manager vault not configured or fetch not
 * implemented", although the Vault and AWS stores are implemented. A store
 * that was only down (HTTP 503) therefore told the operator to reconfigure it.
 * The degraded, never-fake-success behaviour is unchanged; only the reason is
 * now the actual cause. These tests run the real ExchangeCredentialService.
 */
import { ExchangeConnectivityService } from './exchange-connectivity.service';
import { ExchangeCredentialService } from './exchange-credential.service';
import { ExchangeProviderErrorCode } from './exchange-provider.interface';
import { SecretStore, SecretStoreError } from './secret-store';
import { ExchangeConnectionState, ExchangeEnvironment, ExchangeVenue } from './exchange.types';

const TENANT = '11111111-1111-1111-1111-111111111111';
const ACCOUNT = '22222222-2222-2222-2222-222222222222';

const SECRET_ENV_KEYS = [
  'SECRET_MANAGER_PROVIDER',
  'VAULT_ADDR',
  'VAULT_TOKEN',
  'VAULT_TOKEN_FILE',
  'AWS_SECRETS_MANAGER_ENABLED',
] as const;

function storeThatFails(error: unknown): SecretStore {
  return {
    kind: 'vault-kv2',
    referenceFor: () => 'vault:secret/wlct/t/a/binance',
    write: async () => undefined,
    read: async () => {
      throw error;
    },
    exists: async () => false,
    destroy: async () => undefined,
  };
}

function build(store: SecretStore | null) {
  const prisma = {
    tradingAccount: {
      findFirst: jest.fn(async () => ({
        apiKeyCiphertext: null,
        apiSecretCiphertext: null,
        passphraseCiphertext: null,
        credentialSource: 'SECRET_MANAGER',
        credentialRef: 'vault:secret/wlct/t/a/binance',
      })),
    },
  };
  const credentials = new ExchangeCredentialService(prisma as any, {} as any, {} as any, store);
  const providerFactory = {
    validateEnvironmentBinding: jest.fn(),
    getProvider: jest.fn(() => ({})),
  };
  const service = new ExchangeConnectivityService(
    providerFactory as any,
    {} as any,
    credentials,
    {} as any,
    {} as any,
  );
  return { service };
}

const check = (service: ExchangeConnectivityService) =>
  service.checkConnectivity({
    tenantId: TENANT,
    accountId: ACCOUNT,
    venue: ExchangeVenue.BINANCE,
    environment: ExchangeEnvironment.TESTNET,
  });

describe('ExchangeConnectivityService - secret manager failure reasons', () => {
  const saved: Record<string, string | undefined> = {};

  beforeEach(() => {
    for (const key of SECRET_ENV_KEYS) {
      saved[key] = process.env[key];
      delete process.env[key];
    }
  });

  afterEach(() => {
    for (const key of SECRET_ENV_KEYS) {
      if (saved[key] === undefined) delete process.env[key];
      else process.env[key] = saved[key];
    }
  });

  it('reports a store outage as unavailable with its HTTP status, not as unimplemented', async () => {
    const { service } = build(
      storeThatFails(
        new SecretStoreError('UNAVAILABLE', 'read: secret manager unavailable (HTTP 503)', true),
      ),
    );

    const result = await check(service);

    expect(result.connected).toBe(false);
    expect(result.degraded).toBe(true);
    expect(result.state).toBe(ExchangeConnectionState.FAILED);
    expect(result.failureCode).toBe(ExchangeProviderErrorCode.PROVIDER_UNAVAILABLE);
    expect(result.failureReason).toMatch(/^Secret manager unavailable: /);
    expect(result.failureReason).toContain('HTTP 503');
    expect(result.failureReason).not.toMatch(/not implemented/i);
  });

  it('reports a store that is not configured at all as not configured', async () => {
    const { service } = build(null);

    const result = await check(service);

    expect(result.connected).toBe(false);
    expect(result.degraded).toBe(true);
    expect(result.failureCode).toBe(ExchangeProviderErrorCode.PROVIDER_UNAVAILABLE);
    expect(result.failureReason).toMatch(/^Secret manager unavailable: /);
    expect(result.failureReason).toContain('is not configured');
    expect(result.failureReason).not.toMatch(/not implemented/i);
  });

  it('reports a Vault selection without a token as misconfigured', async () => {
    process.env.SECRET_MANAGER_PROVIDER = 'vault';
    process.env.VAULT_ADDR = 'https://vault.example.internal';
    const { service } = build(null);

    const result = await check(service);

    expect(result.degraded).toBe(true);
    expect(result.failureCode).toBe(ExchangeProviderErrorCode.PROVIDER_UNAVAILABLE);
    expect(result.failureReason).toContain('SECRET_MANAGER misconfigured');
    expect(result.failureReason).toContain('VAULT_TOKEN');
  });

  it('keeps a missing secret on the AUTH_FAILED path, not the degraded one', async () => {
    const { service } = build(
      storeThatFails(new SecretStoreError('NOT_FOUND', 'read: secret not found')),
    );

    const result = await check(service);

    expect(result.connected).toBe(false);
    expect(result.degraded).toBe(false);
    expect(result.failureCode).toBe(ExchangeProviderErrorCode.AUTH_FAILED);
    expect(result.failureReason).toContain('secret not found');
  });

  it('never copies an unexpected error message into the reason', async () => {
    const { service } = build(
      storeThatFails(new TypeError('socket closed; token=hvs.CANARY-do-not-leak')),
    );

    const result = await check(service);

    expect(result.degraded).toBe(true);
    expect(result.failureReason).toContain('TypeError');
    expect(result.failureReason).not.toContain('CANARY');
    expect(result.failureReason).not.toContain('hvs.');
  });
});

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { ExchangeVenue, ExchangeEnvironment, ExchangeSyncState, ExchangePosition, normalizeTimestampMicros } from './exchange.types';
import { ExchangeProviderFactory } from './exchange-provider.factory';
import { ExchangeCredentialService } from './exchange-credential.service';
import { ExchangeAccountRepository } from './exchange-account.repository';
import { ExchangeAuditService } from './exchange-audit.service';
import { ExchangeProviderContext } from './exchange-provider.interface';
import { randomUUID } from 'crypto';

/**
 * Idempotent position synchronization with symbol, side, quantity, entry price, mark price, leverage, unrealized PnL, and exchange timestamp handling.
 * Normalize exchange-specific position models into platform's internal representation. Do not invent PnL when exchange provides validated values.
 */
@Injectable()
export class ExchangePositionSyncService {
  private readonly logger = new Logger(ExchangePositionSyncService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly providerFactory: ExchangeProviderFactory,
    private readonly credentialService: ExchangeCredentialService,
    private readonly accountRepo: ExchangeAccountRepository,
    private readonly auditService: ExchangeAuditService,
  ) {}

  private toDecimalString(value: string | number | null | undefined): string | null {
    if (value === null || value === undefined) return null;
    if (typeof value === 'string') {
      if (!/^-?\d+(\.\d+)?$/.test(value.trim())) {
        if (value.trim() === '') return null;
        this.logger.warn(`Invalid decimal string for position: ${value}`);
        return null;
      }
      return value.trim();
    }
    this.logger.warn(`Position amount as number ${value} - should be string`);
    return value.toString();
  }

  async syncPositions(input: { tenantId: string; accountId: string; venue: ExchangeVenue; environment: ExchangeEnvironment; actorId?: string; requestId?: string }): Promise<{ state: ExchangeSyncState; processed: number; created: number; updated: number; skipped: number; durationMs: number }> {
    const start = Date.now();
    const isSandbox = input.environment !== ExchangeEnvironment.LIVE;

    const account = await this.accountRepo.findById(input.accountId, input.tenantId);
    if (!account) throw new Error(`Account ${input.accountId} not found`);

    let provider;
    try {
      provider = this.providerFactory.getProvider(input.venue, input.environment);
    } catch (e: any) {
      this.logger.warn(`Provider unavailable for position sync tenant=${input.tenantId} account=${input.accountId} error=${e.message}`);
      return { state: ExchangeSyncState.FAILED, processed: 0, created: 0, updated: 0, skipped: 0, durationMs: Date.now() - start };
    }

    let credentials;
    try {
      credentials = await this.credentialService.getDecryptedCredentialsForProvider(input.tenantId, input.accountId, input.venue, input.environment);
    } catch (e: any) {
      this.logger.warn(`Credential unavailable for position sync tenant=${input.tenantId} account=${input.accountId} error=${e.message}`);
      return { state: ExchangeSyncState.FAILED, processed: 0, created: 0, updated: 0, skipped: 0, durationMs: Date.now() - start };
    }

    const context: ExchangeProviderContext = {
      tenantId: input.tenantId,
      accountId: input.accountId,
      venue: input.venue,
      environment: input.environment,
      isSandbox,
      credentials: {
        apiKey: credentials.apiKey,
        apiSecret: credentials.apiSecret,
        passphrase: credentials.passphrase,
        environment: input.environment,
        isSandbox,
      },
      credentialRef: null,
    };

    let positions: ExchangePosition[];
    try {
      positions = await provider.getPositions(context);
    } catch (e: any) {
      this.logger.error(`Failed to fetch positions tenant=${input.tenantId} account=${input.accountId} venue=${input.venue} error=${e.message}`);
      await this.auditService.record({
        tenantId: input.tenantId,
        accountId: input.accountId,
        venue: input.venue,
        environment: input.environment,
        event: 'POSITION_SYNCED',
        result: 'FAILURE',
        actorId: input.actorId,
        safeMetadata: { errorCode: e.code || 'FETCH_FAILED', isSandbox },
        requestId: input.requestId,
      });
      return { state: ExchangeSyncState.FAILED, processed: 0, created: 0, updated: 0, skipped: 0, durationMs: Date.now() - start };
    }

    let created = 0;
    let updated = 0;
    let skipped = 0;

    // For idempotency, we need to track providerPositionId or symbol+side
    for (const pos of positions) {
      try {
        const quantity = this.toDecimalString(pos.quantity);
        if (!quantity) {
          skipped++;
          continue;
        }

        const timestampMicros = normalizeTimestampMicros(pos.timestampMicros);

        // Find existing position by accountId + symbol (unique per account+symbol per schema)
        // TradingSymbol lookup required for position's symbolId
        const symbolRecord = await this.prisma.tradingSymbol.findFirst({
          where: { tenantId: input.tenantId, symbol: pos.symbol },
          select: { id: true },
        });

        if (!symbolRecord) {
          // If symbol not found, skip - do not create fake symbol
          this.logger.warn(`Symbol not found for position sync tenant=${input.tenantId} symbol=${pos.symbol}`);
          skipped++;
          continue;
        }

        const existing = await this.prisma.position.findFirst({
          where: { accountId: input.accountId, symbolId: symbolRecord.id },
        });

        const positionData = {
          quantity: quantity as any,
          side: pos.side as any,
          averageEntryPrice: this.toDecimalString(pos.entryPrice) as any,
          markPrice: this.toDecimalString(pos.markPrice) as any,
          realisedPnl: this.toDecimalString(pos.realizedPnl) as any,
          unrealisedPnl: this.toDecimalString(pos.unrealizedPnl) as any,
          // cumulativeFee not in exchange position, keep existing or 0
          containsSimulatedFills: pos.isSimulated,
          lastFillAt: new Date(Number(BigInt(timestampMicros) / BigInt(1000))),
          updatedAt: new Date(),
        };

        if (existing) {
          // Idempotent: check if same timestamp and same quantity - skip
          const existingQty = existing.quantity.toString();
          if (existingQty === quantity && existing.side === pos.side) {
            // Check timestamp awareness - only update if newer
            const existingLastFill = existing.lastFillAt ? existing.lastFillAt.getTime() : 0;
            const newTime = Number(BigInt(timestampMicros) / BigInt(1000));
            if (newTime <= existingLastFill) {
              skipped++;
              continue;
            }
          }

          await this.prisma.position.update({
            where: { id: existing.id },
            data: positionData,
          });
          updated++;
        } else {
          // Only create if quantity non-zero (FLAT positions may be skipped per business rule, but we create for completeness)
          if (quantity === '0' || pos.side === 'FLAT') {
            skipped++;
            continue;
          }

          await this.prisma.position.create({
            data: {
              id: randomUUID(),
              tenantId: input.tenantId,
              accountId: input.accountId,
              symbolId: symbolRecord.id,
              venue: input.venue as any,
              symbol: pos.symbol,
              quantity: quantity as any,
              side: pos.side as any,
              averageEntryPrice: this.toDecimalString(pos.entryPrice) as any,
              markPrice: this.toDecimalString(pos.markPrice) as any,
              realisedPnl: this.toDecimalString(pos.realizedPnl) as any || (0 as any),
              unrealisedPnl: this.toDecimalString(pos.unrealizedPnl) as any,
              cumulativeFee: 0 as any,
              containsSimulatedFills: pos.isSimulated,
              fillCount: 0,
              openedAt: new Date(),
              lastFillAt: new Date(Number(BigInt(timestampMicros) / BigInt(1000))),
              createdAt: new Date(),
              updatedAt: new Date(),
            },
          });
          created++;
        }
      } catch (e: any) {
        this.logger.warn(`Failed to sync position symbol=${pos.symbol} tenant=${input.tenantId} account=${input.accountId} error=${e.message}`);
        skipped++;
      }
    }

    const durationMs = Date.now() - start;

    await this.accountRepo.updateSyncMetadata(input.accountId, input.tenantId, { lastSyncAt: new Date() });

    await this.auditService.record({
      tenantId: input.tenantId,
      accountId: input.accountId,
      venue: input.venue,
      environment: input.environment,
      event: 'POSITION_SYNCED',
      result: 'SUCCESS',
      actorId: input.actorId,
      safeMetadata: { processed: positions.length, created, updated, skipped, durationMs, isSandbox },
      requestId: input.requestId,
    });

    this.logger.log(`Position sync completed tenant=${input.tenantId} account=${input.accountId} processed=${positions.length} created=${created} updated=${updated} skipped=${skipped}`);

    return { state: ExchangeSyncState.COMPLETED, processed: positions.length, created, updated, skipped, durationMs };
  }
}

// # Adds getCapabilities() contract
/**
 * Provider-neutral exchange contract for authentication test, metadata, balances, positions, orders, market data, capabilities, account sync, and optional trading operations.
 * Each method must clearly distinguish: read-only, simulated/testnet, live. Never allow generic interface to bypass existing live gate.
 */

import {
  ExchangeVenue,
  ExchangeEnvironment,
  ExchangeCapability,
  ExchangeConnectivityResult,
  ExchangeBalance,
  ExchangePosition,
  ExchangeOrder,
  ExchangeFill,
  ExchangeSymbol,
  ExchangeCapabilityDiscovery,
} from './exchange.types';

export enum ExchangeProviderErrorCode {
  AUTH_FAILED = 'AUTH_FAILED',
  INVALID_CREDENTIALS = 'INVALID_CREDENTIALS',
  PERMISSION_DENIED = 'PERMISSION_DENIED',
  RATE_LIMITED = 'RATE_LIMITED',
  NETWORK_ERROR = 'NETWORK_ERROR',
  TIMEOUT = 'TIMEOUT',
  SERVER_ERROR = 'SERVER_ERROR',
  SYMBOL_NOT_FOUND = 'SYMBOL_NOT_FOUND',
  INSUFFICIENT_BALANCE = 'INSUFFICIENT_BALANCE',
  INVALID_ORDER = 'INVALID_ORDER',
  ENVIRONMENT_MISMATCH = 'ENVIRONMENT_MISMATCH',
  WITHDRAWAL_NOT_ALLOWED = 'WITHDRAWAL_NOT_ALLOWED',
  CLOCK_DRIFT = 'CLOCK_DRIFT',
  PROVIDER_UNAVAILABLE = 'PROVIDER_UNAVAILABLE',
  NOT_SUPPORTED = 'NOT_SUPPORTED',
  UNKNOWN = 'UNKNOWN',
}

export class ExchangeProviderError extends Error {
  constructor(
    public readonly code: ExchangeProviderErrorCode,
    message: string,
    public readonly venue: ExchangeVenue,
    public readonly environment: ExchangeEnvironment,
    public readonly isRetryable: boolean = false,
    public readonly retryAfterMs: number | null = null,
    public readonly originalError?: any,
  ) {
    super(message);
    this.name = 'ExchangeProviderError';
  }

  toSafeObject(): Record<string, any> {
    return {
      code: this.code,
      message: this.message,
      venue: this.venue,
      environment: this.environment,
      isRetryable: this.isRetryable,
      retryAfterMs: this.retryAfterMs,
    };
  }
}

export interface ExchangeCredentials {
  apiKey: string;
  apiSecret: string;
  passphrase?: string;
  environment: ExchangeEnvironment;
  isSandbox: boolean;
}

export interface ExchangeProviderContext {
  tenantId: string;
  accountId: string;
  venue: ExchangeVenue;
  environment: ExchangeEnvironment;
  isSandbox: boolean;
  credentials: ExchangeCredentials;
  credentialRef: string | null;
  ipAllowlist?: string[];
}

export interface ExchangeServerTime {
  serverTimeMicros: string;
  localTimeMicros: string;
  driftMs: number;
}

export interface ExchangeAccountMetadata {
  accountId: string;
  venue: ExchangeVenue;
  environment: ExchangeEnvironment;
  isSandbox: boolean;
  canTrade: boolean;
  canRead: boolean;
  canWithdraw: boolean;
  ipRestricted: boolean;
  permissions: string[];
  uid: string | null;
  email: string | null;
}

export interface ExchangeProvider {
  readonly venue: ExchangeVenue;
  readonly displayName: string;
  readonly supportedEnvironments: ExchangeEnvironment[];
  readonly supportedCapabilities: ExchangeCapability[];

  /**
   * Read-only connectivity check - never places orders.
   * Validates credential validity, reachability, server time, clock drift, account identity, basic permissions.
   */
  testConnectivity(context: ExchangeProviderContext): Promise<ExchangeConnectivityResult>;

  /**
   * Read-only server time for clock drift detection.
   */
  getServerTime(context: ExchangeProviderContext): Promise<ExchangeServerTime>;

  /**
   * Read-only account metadata.
   */
  getAccountMetadata(context: ExchangeProviderContext): Promise<ExchangeAccountMetadata>;

  /**
   * Read-only capability discovery - authoritative and provider-specific.
   */
  getCapabilities(context: ExchangeProviderContext): Promise<ExchangeCapabilityDiscovery>;

  /**
   * Read-only balances - Decimal-safe strings.
   */
  getBalances(context: ExchangeProviderContext): Promise<ExchangeBalance[]>;

  /**
   * Read-only positions.
   */
  getPositions(context: ExchangeProviderContext): Promise<ExchangePosition[]>;

  /**
   * Read-only open orders.
   */
  getOpenOrders(context: ExchangeProviderContext, symbol?: string): Promise<ExchangeOrder[]>;

  /**
   * Read-only order history.
   */
  getOrderHistory(context: ExchangeProviderContext, symbol?: string, limit?: number): Promise<ExchangeOrder[]>;

  /**
   * Read-only trade/fill history.
   */
  getTradeHistory(context: ExchangeProviderContext, symbol?: string, limit?: number): Promise<ExchangeFill[]>;

  /**
   * Read-only symbol information - authoritative from exchange.
   */
  getSymbols(context: ExchangeProviderContext): Promise<ExchangeSymbol[]>;

  /**
   * Optional: create order - must be gated by existing live enablement outside this interface.
   * This method itself must NOT bypass live gate; caller must verify gate before invoking.
   * Simulated/testnet vs live must be explicit.
   */
  createOrder?(
    context: ExchangeProviderContext,
    order: {
      symbol: string;
      side: string;
      type: string;
      quantity: string;
      price?: string;
      stopPrice?: string;
      clientOrderId: string;
      isSimulated: boolean;
    },
  ): Promise<ExchangeOrder>;

  /**
   * Optional: cancel order - same live-gate requirement.
   */
  cancelOrder?(context: ExchangeProviderContext, orderId: string, symbol?: string): Promise<ExchangeOrder>;

  /**
   * Validates environment binding - LIVE credential must never be used against testnet URL and vice versa.
   * Must fail closed on mismatch.
   */
  validateEnvironmentBinding(environment: ExchangeEnvironment, isSandbox: boolean): boolean;

  /**
   * Returns safe REST base URL for given environment without exposing secrets.
   */
  getRestBaseUrl(environment: ExchangeEnvironment): string;

  /**
   * Returns safe WebSocket base URL for given environment without exposing secrets.
   */
  getWebsocketBaseUrl(environment: ExchangeEnvironment): string;
}

export interface ExchangeProviderConstructor {
  new (): ExchangeProvider;
}

// # Responsibility: verifies atomic tenant-isolated exchange request reservations and fail-closed routing decisions.
import { ExchangeEnvironment, ExchangeVenue } from './exchange.types';
import { ExchangeRateLimitService } from './exchange-rate-limit.service';

describe('ExchangeRateLimitService', () => {
  const baseInput = {
    tenantId: 'tenant-a',
    venue: ExchangeVenue.BINANCE,
    environment: ExchangeEnvironment.LIVE,
    accountId: 'account-a',
    endpointClass: 'ORDER',
  };

  function buildService(reservedUsage: number | Error, expectedWeight = 1) {
    const cache = {
      incrementBy: jest.fn(async (key: string, weight: number, ttlSeconds: number) => {
        expect(key).toBe('exchange:ratelimit:tenant-a:BINANCE:LIVE:account-a:ORDER');
        expect(weight).toBe(expectedWeight);
        expect(ttlSeconds).toBe(60);
        if (reservedUsage instanceof Error) throw reservedUsage;
        return reservedUsage;
      }),
    };
    const registry = {};
    const auditService = { record: jest.fn(async () => undefined) };
    const service = new ExchangeRateLimitService(cache as any, registry as any, auditService as any);
    return { service, cache, auditService };
  }

  test('atomically reserves and allows a request at the configured order ceiling', async () => {
    const { service, cache, auditService } = buildService(600);

    await expect(service.checkRateLimit(baseInput)).resolves.toMatchObject({
      allowed: true,
      remaining: 0,
      pressure: 100,
    });
    expect(cache.incrementBy).toHaveBeenCalledTimes(1);
    expect(auditService.record).not.toHaveBeenCalled();
  });

  test('denies and audits a weighted request that exceeds the order ceiling', async () => {
    const { service, cache, auditService } = buildService(601, 3);

    await expect(service.checkRateLimit({ ...baseInput, weight: 3 })).resolves.toMatchObject({
      allowed: false,
      remaining: 0,
      retryAfterMs: 1000,
      reason: expect.stringContaining('Rate limit exceeded'),
    });
    expect(cache.incrementBy).toHaveBeenCalledWith(
      'exchange:ratelimit:tenant-a:BINANCE:LIVE:account-a:ORDER',
      3,
      60,
    );
    expect(auditService.record).toHaveBeenCalledWith(expect.objectContaining({
      tenantId: 'tenant-a',
      accountId: 'account-a',
      event: 'RATE_LIMIT_TRIGGERED',
      result: 'SUCCESS',
    }));
  });

  test('fails closed and audits when Redis cannot reserve the request budget', async () => {
    const { service, cache, auditService } = buildService(new Error('redis unavailable'));

    await expect(service.checkRateLimit(baseInput)).resolves.toMatchObject({
      allowed: false,
      remaining: null,
      retryAfterMs: 1000,
      pressure: 100,
      reason: expect.stringContaining('unavailable'),
    });
    expect(cache.incrementBy).toHaveBeenCalledTimes(1);
    expect(auditService.record).toHaveBeenCalledWith(expect.objectContaining({
      tenantId: 'tenant-a',
      accountId: 'account-a',
      event: 'RATE_LIMIT_STATE_UNAVAILABLE',
      result: 'FAILURE',
    }));
  });

  test('rejects a zero or fractional request weight without touching Redis', async () => {
    const { service, cache } = buildService(1);

    await expect(service.checkRateLimit({ ...baseInput, weight: 0 })).resolves.toMatchObject({
      allowed: false,
      reason: 'Rate-limit request weight is invalid',
    });
    await expect(service.checkRateLimit({ ...baseInput, weight: 1.5 })).resolves.toMatchObject({
      allowed: false,
      reason: 'Rate-limit request weight is invalid',
    });
    expect(cache.incrementBy).not.toHaveBeenCalled();
  });
});

import { Injectable, Logger } from '@nestjs/common';
import { CacheService } from '../../infrastructure/redis/cache.service';
import { ExchangeVenue, ExchangeEnvironment } from './exchange.types';
import { ExchangeRegistryService } from './exchange-registry.service';
import { ExchangeAuditService } from './exchange-audit.service';

export interface RateLimitState {
  venue: ExchangeVenue;
  environment: ExchangeEnvironment;
  accountId: string | null;
  endpointClass: string;
  requestsPerInterval: number;
  intervalMs: number;
  weightPerRequest: number;
  remaining: number | null;
  resetAtMs: number | null;
  retryAfterMs: number | null;
  isWeightBased: boolean;
  scope: string;
  currentUsage: number;
  pressure: number; // 0-100
}

export interface RateLimitCheckResult {
  allowed: boolean;
  remaining: number | null;
  retryAfterMs: number | null;
  pressure: number;
  reason?: string;
}

/**
 * Normalizes exchange-specific rate limits and coordinates requests with existing rate-limit infrastructure without bypassing venue protections.
 * Do not replace existing Part 2 API rate-limit enforcement.
 */
@Injectable()
export class ExchangeRateLimitService {
  private readonly logger = new Logger(ExchangeRateLimitService.name);

  // Venue-specific rate limit configs - authoritative
  private readonly venueLimits: Map<ExchangeVenue, { requestsPerSecond: number; weightLimitPerMinute: number; isWeightBased: boolean }> = new Map([
    [ExchangeVenue.BINANCE, { requestsPerSecond: 10, weightLimitPerMinute: 1200, isWeightBased: true }],
    [ExchangeVenue.BYBIT, { requestsPerSecond: 10, weightLimitPerMinute: 600, isWeightBased: false }],
    [ExchangeVenue.OKX, { requestsPerSecond: 10, weightLimitPerMinute: 600, isWeightBased: false }],
    [ExchangeVenue.KRAKEN, { requestsPerSecond: 1, weightLimitPerMinute: 60, isWeightBased: false }],
    [ExchangeVenue.COINBASE, { requestsPerSecond: 10, weightLimitPerMinute: 600, isWeightBased: false }],
    [ExchangeVenue.OTHER_CONFIGURED, { requestsPerSecond: 5, weightLimitPerMinute: 300, isWeightBased: false }],
  ]);

  constructor(
    private readonly cache: CacheService,
    private readonly registry: ExchangeRegistryService,
    private readonly auditService: ExchangeAuditService,
  ) {}

  /**
   * The budget key names the tenant first.
   *
   * It did not, so two tenants routing to the same venue with no account selected shared one
   * `global` bucket: one tenant's traffic consumed another tenant's budget, and a busy tenant could
   * rate-limit a quiet one out of its own orders. In a white-label deployment that is a
   * cross-tenant defect, not a tuning detail.
   */
  private getCacheKey(
    tenantId: string,
    venue: ExchangeVenue,
    environment: ExchangeEnvironment,
    accountId: string | null,
    endpointClass: string,
  ): string {
    return `exchange:ratelimit:${tenantId}:${venue}:${environment}:${accountId || 'global'}:${endpointClass}`;
  }

  private getVenueLimit(venue: ExchangeVenue): { requestsPerSecond: number; weightLimitPerMinute: number; isWeightBased: boolean } {
    return this.venueLimits.get(venue) || { requestsPerSecond: 5, weightLimitPerMinute: 300, isWeightBased: false };
  }

  async checkRateLimit(input: {
    tenantId: string;
    venue: ExchangeVenue;
    environment: ExchangeEnvironment;
    accountId?: string | null;
    endpointClass: string;
    weight?: number;
  }): Promise<RateLimitCheckResult> {
    const venueLimit = this.getVenueLimit(input.venue);
    const weight = input.weight === undefined || input.weight === null ? 1 : input.weight;

    // A weight that is not a positive integer is not a request. It used to be coerced with `|| 1`,
    // which turned 0 into 1 and silently dropped the fractional part of 1.5, so a caller asking for a
    // heavier endpoint was charged for a lighter one and the budget under-counted.
    if (!Number.isInteger(weight) || weight < 1) {
      return { allowed: false, remaining: null, retryAfterMs: null, pressure: 100, reason: 'Rate-limit request weight is invalid' };
    }

    const key = this.getCacheKey(input.tenantId, input.venue, input.environment, input.accountId || null, input.endpointClass);
    const maxRequests = this.maxRequestsFor(venueLimit, input.endpointClass);
    const windowSeconds = 60;

    let reservedUsage: number;
    try {
      // Reserve first, decide second, in one atomic increment. Checking and then recording is two
      // steps with a gap: concurrent requests all read the same usage, all conclude they fit, and the
      // venue is the one that finds out otherwise.
      reservedUsage = await this.cache.incrementBy(key, weight, windowSeconds);
    } catch (e: any) {
      // Fail closed. The budget could not be read, so whether this request is within the venue's
      // limit is unknown - and the consequence of guessing "yes" is the venue throttling or banning
      // the API key, which stops every copy for every follower on that account. A refusal that is
      // retried costs a moment; a ban costs the account.
      this.logger.error(`Rate limit reservation failed venue=${input.venue} tenant=${input.tenantId} error=${e.message} - denying request`);
      await this.auditService.record({
        tenantId: input.tenantId,
        accountId: input.accountId || 'global',
        venue: input.venue,
        environment: input.environment,
        event: 'RATE_LIMIT_STATE_UNAVAILABLE',
        result: 'FAILURE',
        safeMetadata: { endpointClass: input.endpointClass, weight, maxRequests },
      });
      return { allowed: false, remaining: null, retryAfterMs: 1000, pressure: 100, reason: `Rate limit state unavailable for ${input.venue} ${input.endpointClass}` };
    }

    const pressure = Math.min(100, Math.floor((reservedUsage / maxRequests) * 100));

    if (reservedUsage > maxRequests) {
      // Hand the reservation back. The request is refused, so it did not consume budget, and leaving
      // the weight charged would let one burst of refusals exhaust the window for the requests that
      // are still allowed.
      try {
        await this.cache.incrementBy(key, -weight, windowSeconds);
      } catch (e: any) {
        this.logger.warn(`Rate limit refund failed venue=${input.venue} tenant=${input.tenantId} error=${e.message}`);
      }

      this.logger.warn(`Rate limit exceeded venue=${input.venue} env=${input.environment} account=${input.accountId} endpoint=${input.endpointClass} usage=${reservedUsage}/${maxRequests}`);

      await this.auditService.record({
        tenantId: input.tenantId,
        accountId: input.accountId || 'global',
        venue: input.venue,
        environment: input.environment,
        event: 'RATE_LIMIT_TRIGGERED',
        result: 'SUCCESS',
        safeMetadata: { endpointClass: input.endpointClass, currentUsage: reservedUsage, maxRequests, pressure, retryAfterMs: 1000 },
      });

      return { allowed: false, remaining: 0, retryAfterMs: 1000, pressure, reason: `Rate limit exceeded for ${input.venue} ${input.endpointClass}` };
    }

    const remaining = Math.max(0, maxRequests - reservedUsage);
    return { allowed: true, remaining, retryAfterMs: null, pressure };
  }

  /**
   * The per-minute budget for an endpoint class: the venue's own limit, halved for order placement
   * and reduced to 80% for private endpoints, so the account keeps headroom for cancellations and
   * reconciliation instead of spending the venue's whole allowance on new orders.
   */
  private maxRequestsFor(
    venueLimit: { requestsPerSecond: number; weightLimitPerMinute: number; isWeightBased: boolean },
    endpointClass: string,
  ): number {
    const base = venueLimit.isWeightBased ? venueLimit.weightLimitPerMinute : venueLimit.requestsPerSecond * 60;
    if (endpointClass === 'ORDER') return Math.max(1, Math.floor(base * 0.5));
    if (endpointClass === 'PRIVATE') return Math.max(1, Math.floor(base * 0.8));
    return base;
  }

  async recordRequest(input: {
    tenantId: string;
    venue: ExchangeVenue;
    environment: ExchangeEnvironment;
    accountId?: string | null;
    endpointClass: string;
    weight?: number;
    responseHeaders?: Record<string, string>;
  }): Promise<void> {
    const weight = input.weight || 1;
    const key = this.getCacheKey(input.tenantId, input.venue, input.environment, input.accountId || null, input.endpointClass);

    try {
      // Increment usage counter with TTL
      await this.cache.increment(key, 60);

      // Parse response headers for remaining allowance if provided
      if (input.responseHeaders) {
        const remaining = this.parseRemainingFromHeaders(input.venue, input.responseHeaders);
        const resetAt = this.parseResetFromHeaders(input.venue, input.responseHeaders);
        const retryAfter = this.parseRetryAfterFromHeaders(input.responseHeaders);

        if (remaining !== null || resetAt !== null || retryAfter !== null) {
          const stateKey = `${key}:state`;
          await this.cache.set(
            stateKey,
            {
              remaining,
              resetAtMs: resetAt,
              retryAfterMs: retryAfter,
              lastUpdated: Date.now(),
            },
            60,
          );
        }
      }
    } catch (e: any) {
      this.logger.warn(`Failed to record rate limit request venue=${input.venue} error=${e.message}`);
    }
  }

  private parseRemainingFromHeaders(venue: ExchangeVenue, headers: Record<string, string>): number | null {
    // Venue-specific header parsing
    const lowerHeaders: Record<string, string> = {};
    for (const [k, v] of Object.entries(headers)) {
      lowerHeaders[k.toLowerCase()] = v;
    }

    if (venue === ExchangeVenue.BINANCE) {
      const usedWeight = lowerHeaders['x-mbx-used-weight'] || lowerHeaders['x-mbx-used-weight-1m'];
      if (usedWeight) {
        const limit = this.getVenueLimit(venue).weightLimitPerMinute;
        return Math.max(0, limit - parseInt(usedWeight, 10));
      }
    }

    if (venue === ExchangeVenue.BYBIT || venue === ExchangeVenue.OKX) {
      // Bybit/OKX don't typically return remaining in headers, use our own tracking
      return null;
    }

    // Generic fallback
    const remaining = lowerHeaders['x-ratelimit-remaining'] || lowerHeaders['x-rate-limit-remaining'];
    if (remaining) {
      return parseInt(remaining, 10);
    }

    return null;
  }

  private parseResetFromHeaders(venue: ExchangeVenue, headers: Record<string, string>): number | null {
    const lowerHeaders: Record<string, string> = {};
    for (const [k, v] of Object.entries(headers)) {
      lowerHeaders[k.toLowerCase()] = v;
    }

    const reset = lowerHeaders['x-ratelimit-reset'] || lowerHeaders['x-rate-limit-reset'] || lowerHeaders['retry-after'];
    if (reset) {
      const resetSec = parseInt(reset, 10);
      if (!isNaN(resetSec)) {
        // If reset is seconds from now or timestamp
        if (resetSec < 1000000000) {
          return Date.now() + resetSec * 1000;
        }
        return resetSec * 1000;
      }
    }
    return null;
  }

  private parseRetryAfterFromHeaders(headers: Record<string, string>): number | null {
    const lowerHeaders: Record<string, string> = {};
    for (const [k, v] of Object.entries(headers)) {
      lowerHeaders[k.toLowerCase()] = v;
    }

    const retryAfter = lowerHeaders['retry-after'];
    if (retryAfter) {
      const seconds = parseInt(retryAfter, 10);
      if (!isNaN(seconds)) {
        return seconds * 1000;
      }
    }
    return null;
  }

  /**
   * The current budget state for an account. Requires the tenant: without it the key fell back to the
   * shared `global` bucket, so an operator reading one tenant's pressure was reading every tenant's
   * combined usage - and the number would have been wrong in whichever direction the neighbours were
   * busier.
   */
  async getRateLimitState(input: { tenantId: string; venue: ExchangeVenue; environment: ExchangeEnvironment; accountId?: string | null; endpointClass: string }): Promise<RateLimitState | null> {
    const key = this.getCacheKey(input.tenantId, input.venue, input.environment, input.accountId || null, input.endpointClass);
    const stateKey = `${key}:state`;

    try {
      const currentUsage = (await this.cache.get<number>(key)) || 0;
      const state = (await this.cache.get<any>(stateKey)) || {};

      const venueLimit = this.getVenueLimit(input.venue);
      const maxRequests = venueLimit.isWeightBased ? venueLimit.weightLimitPerMinute : venueLimit.requestsPerSecond * 60;
      const pressure = Math.min(100, Math.floor((currentUsage / maxRequests) * 100));

      return {
        venue: input.venue,
        environment: input.environment,
        accountId: input.accountId || null,
        endpointClass: input.endpointClass,
        requestsPerInterval: venueLimit.requestsPerSecond,
        intervalMs: 60000,
        weightPerRequest: 1,
        remaining: state.remaining ?? Math.max(0, maxRequests - currentUsage),
        resetAtMs: state.resetAtMs || null,
        retryAfterMs: state.retryAfterMs || null,
        isWeightBased: venueLimit.isWeightBased,
        scope: input.accountId ? 'ACCOUNT' : 'GLOBAL',
        currentUsage,
        pressure,
      };
    } catch {
      return null;
    }
  }

  normalizeRateLimitResponse(venue: ExchangeVenue, error: any): { code: string; retryAfterMs: number | null; pressure: number } {
    // Normalize venue-specific rate limit errors into safe internal format
    const message = error.message?.toLowerCase() || '';
    const status = error.status || error.statusCode || 0;

    if (status === 429 || message.includes('rate limit') || message.includes('too many requests')) {
      const retryAfter = error.retryAfterMs || this.parseRetryAfterFromHeaders(error.headers || {}) || 1000;
      return { code: 'RATE_LIMITED', retryAfterMs: retryAfter, pressure: 90 };
    }

    if (status === 418 && venue === ExchangeVenue.BINANCE) {
      // Binance IP ban
      return { code: 'IP_BANNED', retryAfterMs: 60000, pressure: 100 };
    }

    return { code: 'UNKNOWN', retryAfterMs: null, pressure: 0 };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { ExchangeVenue, ExchangeEnvironment, ExchangeCapability, ExchangeHealthState, ExchangeAccountState, ExchangeRoutingDecision } from './exchange.types';
import { ExchangeAccountRepository } from './exchange-account.repository';
import { ExchangeHealthService } from './exchange-health.service';
import { ExchangeRateLimitService } from './exchange-rate-limit.service';
import { ExchangeRegistryService } from './exchange-registry.service';
import { ExchangeAuditService } from './exchange-audit.service';
import { ExecutionSafetyService } from '../execution/execution-safety.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

export interface RoutingInput {
  tenantId: string;
  userId: string;
  operation: 'READ' | 'MARKET_DATA' | 'TRADE' | 'WITHDRAWAL';
  symbol?: string;
  requiredCapability: ExchangeCapability;
  environment: ExchangeEnvironment;
  accountId?: string | null; // specific account requested
  complianceAllowed?: boolean;
  riskAllowed?: boolean;
  actorId?: string;
  requestId?: string;
}

/**
 * Determines eligible venue/account for read/market/trading operations based on capabilities, account state, environment, tenant policy, and existing live-mode safety gates.
 * CRITICAL: This service MUST call existing live safety gate for live trading. It must never independently decide "live=true → place order"
 */
@Injectable()
export class ExchangeRoutingService {
  private readonly logger = new Logger(ExchangeRoutingService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly accountRepo: ExchangeAccountRepository,
    private readonly healthService: ExchangeHealthService,
    private readonly rateLimitService: ExchangeRateLimitService,
    private readonly registry: ExchangeRegistryService,
    private readonly safetyService: ExecutionSafetyService,
    private readonly auditService: ExchangeAuditService,
  ) {}

  async route(input: RoutingInput): Promise<ExchangeRoutingDecision> {
    // 1. Tenant cannot access another tenant's exchange account - enforced via repo tenantId filter
    // 2. List eligible accounts for tenant
    const { data: accounts } = await this.accountRepo.listByTenant(input.tenantId, {
      userId: input.userId,
      environment: input.environment,
      status: ExchangeAccountState.ACTIVE,
      limit: 100,
    });

    // If specific account requested, filter to that account and verify ownership
    let eligible = accounts;
    if (input.accountId) {
      eligible = accounts.filter((a) => a.id === input.accountId);
      if (eligible.length === 0) {
        // Check if account exists in other tenant - if so, reject with generic not found to avoid enumeration
        const exists = await this.prisma.tradingAccount.findFirst({ where: { id: input.accountId } });
        if (exists && exists.tenantId !== input.tenantId) {
          this.logger.warn(`Cross-tenant access attempt tenant=${input.tenantId} requestedAccount=${input.accountId} actualTenant=${exists.tenantId}`);
          await this.auditService.record({
            tenantId: input.tenantId,
            accountId: input.accountId,
            venue: ExchangeVenue.BINANCE,
            environment: input.environment,
            event: 'ROUTING_DECISION',
            result: 'FAILURE',
            actorId: input.actorId,
            safeMetadata: { reason: 'CROSS_TENANT_ACCESS_DENIED', requestedAccountId: input.accountId },
            requestId: input.requestId,
          });
          return {
            selectedAccountId: null,
            selectedVenue: null,
            environment: input.environment,
            eligibleAccounts: [],
            routingReason: 'CROSS_TENANT_ACCESS_DENIED',
            capabilities: [],
            health: null,
            liveExecutionPermitted: false,
            liveGateBlockingReasons: ['Cross-tenant access denied'],
            complianceAllowed: false,
            riskAllowed: false,
          };
        }

        return {
          selectedAccountId: null,
          selectedVenue: null,
          environment: input.environment,
          eligibleAccounts: [],
          routingReason: 'ACCOUNT_NOT_FOUND_OR_NOT_ACTIVE',
          capabilities: [],
          health: null,
          liveExecutionPermitted: false,
          liveGateBlockingReasons: ['Account not found or not active'],
          complianceAllowed: input.complianceAllowed ?? true,
          riskAllowed: input.riskAllowed ?? true,
        };
      }
    }

    // 3. Routing respects capability requirements
    const capabilityFiltered = eligible.filter((a) => {
      // Check if account capabilities include required capability
      // If capabilities empty (not yet discovered), fallback to registry
      if (a.capabilities && a.capabilities.length > 0) {
        return a.capabilities.includes(input.requiredCapability);
      }
      const registryCaps = this.registry.listCapabilities(a.venue);
      return registryCaps.includes(input.requiredCapability);
    });

    if (capabilityFiltered.length === 0) {
      return {
        selectedAccountId: null,
        selectedVenue: null,
        environment: input.environment,
        eligibleAccounts: eligible.map((a) => a.id),
        routingReason: `NO_ACCOUNT_WITH_CAPABILITY_${input.requiredCapability}`,
        capabilities: [],
        health: null,
        liveExecutionPermitted: false,
        liveGateBlockingReasons: [`No account with capability ${input.requiredCapability}`],
        complianceAllowed: input.complianceAllowed ?? true,
        riskAllowed: input.riskAllowed ?? true,
      };
    }

    // 4. Environment separation: testnet cannot route to live, live cannot route to testnet - fail closed
    const envFiltered = capabilityFiltered.filter((a) => {
      if (input.environment === ExchangeEnvironment.LIVE) {
        return a.environment === ExchangeEnvironment.LIVE && !a.isSandbox;
      } else {
        return a.environment !== ExchangeEnvironment.LIVE && a.isSandbox;
      }
    });

    if (envFiltered.length === 0) {
      const reason = input.environment === ExchangeEnvironment.LIVE ? 'LIVE_CANNOT_ROUTE_TO_TESTNET' : 'TESTNET_CANNOT_ROUTE_TO_LIVE';
      return {
        selectedAccountId: null,
        selectedVenue: null,
        environment: input.environment,
        eligibleAccounts: capabilityFiltered.map((a) => a.id),
        routingReason: reason,
        capabilities: [],
        health: null,
        liveExecutionPermitted: false,
        liveGateBlockingReasons: [reason],
        complianceAllowed: input.complianceAllowed ?? true,
        riskAllowed: input.riskAllowed ?? true,
      };
    }

    // 5. Routing respects account health
    const healthyAccounts: { account: any; health: any }[] = [];
    for (const account of envFiltered) {
      try {
        const health = await this.healthService.getHealth(input.tenantId, account.id);
        if (!health) continue;

        // Skip AUTH_FAILED, UNAVAILABLE, STALE for live operations
        if (input.operation === 'TRADE') {
          if (!this.healthService.isStaleHealthAllowsLiveTrading(health)) {
            this.logger.warn(`Account unhealthy for live trading tenant=${input.tenantId} account=${account.id} health=${health.state}`);
            continue;
          }
        } else {
          // For read operations, allow DEGRADED but not AUTH_FAILED/UNAVAILABLE
          if (health.state === ExchangeHealthState.AUTH_FAILED || health.state === ExchangeHealthState.UNAVAILABLE) {
            continue;
          }
        }

        healthyAccounts.push({ account, health });
      } catch (e: any) {
        this.logger.warn(`Health check failed for routing tenant=${input.tenantId} account=${account.id} error=${e.message}`);
      }
    }

    if (healthyAccounts.length === 0) {
      return {
        selectedAccountId: null,
        selectedVenue: null,
        environment: input.environment,
        eligibleAccounts: envFiltered.map((a) => a.id),
        routingReason: 'NO_HEALTHY_ACCOUNT',
        capabilities: [],
        health: null,
        liveExecutionPermitted: false,
        liveGateBlockingReasons: ['No healthy account available'],
        complianceAllowed: input.complianceAllowed ?? true,
        riskAllowed: input.riskAllowed ?? true,
      };
    }

    // 6. Routing respects compliance restrictions
    if (input.complianceAllowed === false) {
      return {
        selectedAccountId: null,
        selectedVenue: null,
        environment: input.environment,
        eligibleAccounts: healthyAccounts.map((h) => h.account.id),
        routingReason: 'COMPLIANCE_BLOCKED',
        capabilities: [],
        health: null,
        liveExecutionPermitted: false,
        liveGateBlockingReasons: ['Compliance blocked'],
        complianceAllowed: false,
        riskAllowed: input.riskAllowed ?? true,
      };
    }

    if (input.riskAllowed === false) {
      return {
        selectedAccountId: null,
        selectedVenue: null,
        environment: input.environment,
        eligibleAccounts: healthyAccounts.map((h) => h.account.id),
        routingReason: 'RISK_BLOCKED',
        capabilities: [],
        health: null,
        liveExecutionPermitted: false,
        liveGateBlockingReasons: ['Risk blocked'],
        complianceAllowed: true,
        riskAllowed: false,
      };
    }

    // 7. Rate-limit availability
    //
    // Two different refusals arrive here and they are not the same news. A budget that is spent says
    // "wait"; a budget that could not be read says "we do not know", and the difference decides
    // whether an operator should expect traffic to resume on its own. The reason is carried out in
    // the routing decision instead of being flattened into "rate limited".
    const rateLimitEligible: { account: any; health: any }[] = [];
    let rateLimitStateUnavailable = false;
    for (const { account, health } of healthyAccounts) {
      try {
        const rateLimitCheck = await this.rateLimitService.checkRateLimit({
          tenantId: input.tenantId,
          venue: account.venue,
          environment: account.environment,
          accountId: account.id,
          endpointClass: input.operation === 'TRADE' ? 'ORDER' : input.operation === 'READ' ? 'PRIVATE' : 'PUBLIC',
        });

        if (!rateLimitCheck.allowed) {
          // `remaining === null` is the rate-limit service saying it could not establish the budget.
          if (rateLimitCheck.remaining === null) {
            rateLimitStateUnavailable = true;
            this.logger.warn(`Rate limit state unavailable for routing tenant=${input.tenantId} account=${account.id} reason=${rateLimitCheck.reason}`);
          } else {
            this.logger.warn(`Rate limited for routing tenant=${input.tenantId} account=${account.id} pressure=${rateLimitCheck.pressure}`);
          }
          continue;
        }

        rateLimitEligible.push({ account, health });
      } catch (error: any) {
        // Fail closed. An account whose exchange budget could not be established is not a safe target:
        // routing to it risks the venue throttling or banning the API key, which stops every copy on
        // that account rather than one request. It used to be pushed into the eligible list here.
        rateLimitStateUnavailable = true;
        this.logger.warn(`Rate-limit evaluation failed for routing tenant=${input.tenantId} account=${account.id} error=${error?.message} - account excluded`);
      }
    }

    if (rateLimitEligible.length === 0) {
      return {
        selectedAccountId: null,
        selectedVenue: null,
        environment: input.environment,
        eligibleAccounts: healthyAccounts.map((h) => h.account.id),
        routingReason: rateLimitStateUnavailable ? 'RATE_LIMIT_STATE_UNAVAILABLE' : 'ALL_ACCOUNTS_RATE_LIMITED',
        capabilities: [],
        health: null,
        liveExecutionPermitted: false,
        liveGateBlockingReasons: [
          rateLimitStateUnavailable
            ? 'Exchange rate-limit state unavailable; refusing to route rather than risk a venue ban'
            : 'All accounts rate limited',
        ],
        complianceAllowed: true,
        riskAllowed: true,
      };
    }

    // 8. Select best account - lowest latency, healthy, etc.
    // Sort by health state HEALTHY first, then latency, then last verified
    rateLimitEligible.sort((a, b) => {
      const healthOrder: Record<string, number> = {
        [ExchangeHealthState.HEALTHY]: 0,
        [ExchangeHealthState.DEGRADED]: 1,
        [ExchangeHealthState.RATE_LIMITED]: 2,
        [ExchangeHealthState.STALE]: 3,
        [ExchangeHealthState.UNAVAILABLE]: 4,
        [ExchangeHealthState.AUTH_FAILED]: 5,
      };
      const aOrder = healthOrder[a.health.state] ?? 10;
      const bOrder = healthOrder[b.health.state] ?? 10;
      if (aOrder !== bOrder) return aOrder - bOrder;
      const aLatency = a.health.latencyMs || 9999;
      const bLatency = b.health.latencyMs || 9999;
      return aLatency - bLatency;
    });

    const selected = rateLimitEligible[0];
    const selectedAccount = selected.account;
    const selectedHealth = selected.health;

    // 9. Routing invokes existing live enablement gate for live trading
    let liveExecutionPermitted = false;
    let liveGateBlockingReasons: string[] = [];

    if (input.environment === ExchangeEnvironment.LIVE && input.operation === 'TRADE') {
      try {
        const safety = await this.safetyService.safetySummary(input.tenantId);
        liveExecutionPermitted = safety.wouldTransmitLiveOrder && selectedAccount.liveTradingEnabled;
        liveGateBlockingReasons = safety.blockingReasons;
        if (!selectedAccount.liveTradingEnabled) {
          liveGateBlockingReasons.push('Account liveTradingEnabled is false');
          liveExecutionPermitted = false;
        }
        if (!liveExecutionPermitted) {
          this.logger.warn(`Live execution not permitted tenant=${input.tenantId} account=${selectedAccount.id} reasons=${liveGateBlockingReasons.join(', ')}`);
        }
      } catch (e: any) {
        this.logger.error(`Failed to check live gate tenant=${input.tenantId} error=${e.message}`);
        liveExecutionPermitted = false;
        liveGateBlockingReasons = ['Live gate check failed - fail closed'];
      }
    } else if (input.environment !== ExchangeEnvironment.LIVE) {
      // Testnet/sandbox never permits live execution
      liveExecutionPermitted = false;
      liveGateBlockingReasons = [`Environment ${input.environment} is not LIVE - live execution never permitted`];
    } else if (input.operation !== 'TRADE') {
      // Read operations don't need live gate
      liveExecutionPermitted = false;
      liveGateBlockingReasons = ['Read operation - live execution not applicable'];
    }

    const decision: ExchangeRoutingDecision = {
      selectedAccountId: selectedAccount.id,
      selectedVenue: selectedAccount.venue,
      environment: selectedAccount.environment,
      eligibleAccounts: rateLimitEligible.map((r) => r.account.id),
      routingReason: `SELECTED_${selectedAccount.venue}_HEALTH_${selectedHealth.state}_LATENCY_${selectedHealth.latencyMs || 'unknown'}`,
      capabilities: selectedAccount.capabilities || this.registry.listCapabilities(selectedAccount.venue),
      health: selectedHealth.state,
      liveExecutionPermitted,
      liveGateBlockingReasons,
      complianceAllowed: true,
      riskAllowed: true,
    };

    await this.auditService.record({
      tenantId: input.tenantId,
      accountId: selectedAccount.id,
      venue: selectedAccount.venue,
      environment: selectedAccount.environment,
      event: 'ROUTING_DECISION',
      result: 'SUCCESS',
      actorId: input.actorId,
      safeMetadata: {
        operation: input.operation,
        symbol: input.symbol,
        requiredCapability: input.requiredCapability,
        selectedAccountId: selectedAccount.id,
        selectedVenue: selectedAccount.venue,
        routingReason: decision.routingReason,
        liveExecutionPermitted,
        liveGateBlockingReasons,
        eligibleCount: eligible.length,
        healthyCount: healthyAccounts.length,
        rateLimitEligibleCount: rateLimitEligible.length,
      },
      requestId: input.requestId,
    });

    this.logger.log(`Routing decision tenant=${input.tenantId} operation=${input.operation} selected=${selectedAccount.id} venue=${selectedAccount.venue} livePermitted=${liveExecutionPermitted}`);

    return decision;
  }

  async getEligibleAccountsForSymbol(tenantId: string, userId: string, symbol: string, environment: ExchangeEnvironment): Promise<string[]> {
    const { data } = await this.accountRepo.listByTenant(tenantId, { userId, environment, status: ExchangeAccountState.ACTIVE, limit: 100 });
    // Further filter by symbol support - would check TradingSymbol table
    const eligible: string[] = [];
    for (const account of data) {
      try {
        const symbolExists = await this.prisma.tradingSymbol.findFirst({ where: { tenantId, symbol } });
        if (symbolExists) eligible.push(account.id);
      } catch {}
    }
    return eligible;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { ExchangeVenue, ExchangeEnvironment, ExchangeSymbol } from './exchange.types';
import { ExchangeProviderFactory } from './exchange-provider.factory';
import { ExchangeCredentialService } from './exchange-credential.service';
import { ExchangeAccountRepository } from './exchange-account.repository';
import { ExchangeProviderContext } from './exchange-provider.interface';
import { CacheService } from '../../infrastructure/redis/cache.service';
import { randomUUID } from 'crypto';
import { krakenPairParts } from './providers/kraken.provider';

/**
 * Symbol/instrument normalization: base/quote, precision, quantity step, tick size, min/max quantity/notional, contract type, and canonical internal symbol mapping.
 * Use exchange-provided metadata. Never guess exchange precision.
 */
@Injectable()
export class ExchangeSymbolService {
  private readonly logger = new Logger(ExchangeSymbolService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly providerFactory: ExchangeProviderFactory,
    private readonly credentialService: ExchangeCredentialService,
    private readonly accountRepo: ExchangeAccountRepository,
    private readonly cache: CacheService,
  ) {}

  private toCanonicalSymbol(base: string, quote: string): string {
    // Canonical format: BTC-USDT
    return `${base.toUpperCase()}-${quote.toUpperCase()}`;
  }

  private parseSymbolFromExchangeFormat(venue: ExchangeVenue, exchangeSymbol: string): { base: string; quote: string } | null {
    // Venue-specific parsing - must use provider metadata, never guess blindly
    // But we implement basic parsing as fallback when provider metadata unavailable
    try {
      if (venue === ExchangeVenue.BINANCE || venue === ExchangeVenue.BYBIT) {
        // BTCUSDT -> BTC + USDT (need to know quote assets)
        const quotes = ['USDT', 'BUSD', 'USDC', 'BTC', 'ETH', 'BNB', 'USD', 'EUR'];
        for (const q of quotes) {
          if (exchangeSymbol.endsWith(q)) {
            const base = exchangeSymbol.slice(0, -q.length);
            if (base) return { base, quote: q };
          }
        }
        return null;
      }

      if (venue === ExchangeVenue.OKX || venue === ExchangeVenue.COINBASE) {
        // BTC-USDT or BTC-USD
        const parts = exchangeSymbol.split('-');
        if (parts.length === 2) return { base: parts[0], quote: parts[1] };
        return null;
      }

      if (venue === ExchangeVenue.KRAKEN) {
        // XBT/USD, XXBTZUSD or the altname XBTUSD; legacy asset codes are
        // normalized (XBT -> BTC, ZUSD -> USD) so the canonical symbol matches
        // the other venues.
        return krakenPairParts(exchangeSymbol);
      }

      // Generic fallback: try dash, slash, then assume last 4 chars are quote
      if (exchangeSymbol.includes('-')) {
        const [b, q] = exchangeSymbol.split('-');
        return { base: b, quote: q };
      }
      if (exchangeSymbol.includes('/')) {
        const [b, q] = exchangeSymbol.split('/');
        return { base: b, quote: q };
      }
      return null;
    } catch {
      return null;
    }
  }

  async syncSymbols(input: { tenantId: string; accountId: string; venue: ExchangeVenue; environment: ExchangeEnvironment }): Promise<{ synced: number; created: number; updated: number }> {
    const isSandbox = input.environment !== ExchangeEnvironment.LIVE;

    let provider;
    try {
      provider = this.providerFactory.getProvider(input.venue, input.environment);
    } catch (e: any) {
      this.logger.warn(`Provider unavailable for symbol sync tenant=${input.tenantId} venue=${input.venue} error=${e.message}`);
      return { synced: 0, created: 0, updated: 0 };
    }

    let credentials;
    try {
      credentials = await this.credentialService.getDecryptedCredentialsForProvider(input.tenantId, input.accountId, input.venue, input.environment);
    } catch {
      // Symbols can often be fetched without auth - try with empty creds
      credentials = { apiKey: '', apiSecret: '' } as any;
    }

    const context: ExchangeProviderContext = {
      tenantId: input.tenantId,
      accountId: input.accountId,
      venue: input.venue,
      environment: input.environment,
      isSandbox,
      credentials: {
        apiKey: credentials.apiKey,
        apiSecret: credentials.apiSecret,
        passphrase: (credentials as any).passphrase,
        environment: input.environment,
        isSandbox,
      },
      credentialRef: null,
    };

    let symbols: ExchangeSymbol[];
    try {
      symbols = await provider.getSymbols(context);
    } catch (e: any) {
      this.logger.error(`Failed to fetch symbols tenant=${input.tenantId} venue=${input.venue} error=${e.message}`);
      return { synced: 0, created: 0, updated: 0 };
    }

    let created = 0;
    let updated = 0;

    for (const sym of symbols) {
      try {
        // Symbol precision comes from provider metadata - never guess
        if (!sym.tickSize || !sym.quantityStep) {
          this.logger.warn(`Skipping symbol with missing precision tenant=${input.tenantId} symbol=${sym.exchangeSymbol}`);
          continue;
        }

        const existing = await this.prisma.tradingSymbol.findFirst({
          where: { tenantId: input.tenantId, exchangeId: (await this.getExchangeId(input.venue)), symbol: sym.canonicalSymbol },
        });

        if (existing) {
          await this.prisma.tradingSymbol.update({
            where: { id: existing.id },
            data: {
              venueSymbol: sym.exchangeSymbol,
              baseAsset: sym.baseAsset,
              quoteAsset: sym.quoteAsset,
              priceTick: sym.tickSize as any,
              quantityStep: sym.quantityStep as any,
              minQuantity: sym.minQuantity as any,
              maxQuantity: sym.maxQuantity as any,
              minNotional: sym.minNotional as any,
              pricePrecision: sym.pricePrecision,
              quantityPrecision: sym.quantityPrecision,
              isTradeable: sym.isTradeable,
              updatedAt: new Date(),
            },
          });
          updated++;
        } else {
          const exchangeId = await this.getExchangeId(input.venue);
          await this.prisma.tradingSymbol.create({
            data: {
              id: randomUUID(),
              tenantId: input.tenantId,
              exchangeId,
              symbol: sym.canonicalSymbol,
              venueSymbol: sym.exchangeSymbol,
              baseAsset: sym.baseAsset,
              quoteAsset: sym.quoteAsset,
              marketType: (sym.contractType as any) || 'SPOT',
              isTradeable: sym.isTradeable,
              isSubscribed: false,
              priceTick: sym.tickSize as any,
              quantityStep: sym.quantityStep as any,
              minQuantity: sym.minQuantity as any || (0 as any),
              maxQuantity: sym.maxQuantity as any,
              minNotional: sym.minNotional as any || (0 as any),
              pricePrecision: sym.pricePrecision,
              quantityPrecision: sym.quantityPrecision,
              createdAt: new Date(),
              updatedAt: new Date(),
            },
          });
          created++;
        }

        // Cache symbol for fast lookup
        try {
          await this.cache.set(`symbol:${input.tenantId}:${sym.canonicalSymbol}`, sym, 3600);
          await this.cache.set(`symbol:${input.tenantId}:${sym.exchangeSymbol}`, sym, 3600);
        } catch {}
      } catch (e: any) {
        this.logger.warn(`Failed to sync symbol ${sym.exchangeSymbol} tenant=${input.tenantId} error=${e.message}`);
      }
    }

    this.logger.log(`Symbol sync completed tenant=${input.tenantId} venue=${input.venue} synced=${symbols.length} created=${created} updated=${updated}`);

    return { synced: symbols.length, created, updated };
  }

  async getSymbol(tenantId: string, canonicalSymbol: string): Promise<ExchangeSymbol | null> {
    try {
      const cached = await this.cache.get<ExchangeSymbol>(`symbol:${tenantId}:${canonicalSymbol}`);
      if (cached) return cached;
    } catch {}

    const record = await this.prisma.tradingSymbol.findFirst({
      where: { tenantId, symbol: canonicalSymbol },
    });

    if (!record) return null;

    return {
      canonicalSymbol: record.symbol,
      exchangeSymbol: record.venueSymbol,
      baseAsset: record.baseAsset,
      quoteAsset: record.quoteAsset,
      contractType: record.marketType as any,
      tickSize: record.priceTick.toString(),
      quantityStep: record.quantityStep.toString(),
      minQuantity: record.minQuantity?.toString() || null,
      maxQuantity: record.maxQuantity?.toString() || null,
      minNotional: record.minNotional?.toString() || null,
      maxNotional: (record as any).maxOrderNotional?.toString() || null,
      pricePrecision: record.pricePrecision,
      quantityPrecision: record.quantityPrecision,
      minLeverage: null,
      maxLeverage: null,
      isTradeable: record.isTradeable,
    };
  }

  async listSymbols(tenantId: string, filters?: { baseAsset?: string; quoteAsset?: string; isTradeable?: boolean; search?: string; page?: number; limit?: number }): Promise<{ data: ExchangeSymbol[]; total: number }> {
    const page = filters?.page || 1;
    const limit = Math.min(filters?.limit || 50, 200);
    const skip = (page - 1) * limit;

    const where: any = {
      tenantId,
      ...(filters?.baseAsset ? { baseAsset: filters.baseAsset } : {}),
      ...(filters?.quoteAsset ? { quoteAsset: filters.quoteAsset } : {}),
      ...(filters?.isTradeable !== undefined ? { isTradeable: filters.isTradeable } : {}),
      ...(filters?.search ? { symbol: { contains: filters.search, mode: 'insensitive' } } : {}),
    };

    const [rows, total] = await this.prisma.$transaction([
      this.prisma.tradingSymbol.findMany({ where, orderBy: { symbol: 'asc' }, skip, take: limit }),
      this.prisma.tradingSymbol.count({ where }),
    ]);

    const data = rows.map((r) => ({
      canonicalSymbol: r.symbol,
      exchangeSymbol: r.venueSymbol,
      baseAsset: r.baseAsset,
      quoteAsset: r.quoteAsset,
      contractType: r.marketType as any,
      tickSize: r.priceTick.toString(),
      quantityStep: r.quantityStep.toString(),
      minQuantity: r.minQuantity?.toString() || null,
      maxQuantity: r.maxQuantity?.toString() || null,
      minNotional: r.minNotional?.toString() || null,
      maxNotional: (r as any).maxOrderNotional?.toString() || null,
      pricePrecision: r.pricePrecision,
      quantityPrecision: r.quantityPrecision,
      minLeverage: null,
      maxLeverage: null,
      isTradeable: r.isTradeable,
    }));

    return { data, total };
  }

  private async getExchangeId(venue: ExchangeVenue): Promise<string> {
    const exchange = await this.prisma.exchange.findFirst({ where: { venue: venue as any } });
    if (!exchange) throw new Error(`Exchange ${venue} not found`);
    return exchange.id;
  }
}

// # Implements signed V5 live REST/account/symbol/health probes when live trading enabled
import * as crypto from 'crypto';
import {
  ExchangeVenue,
  ExchangeEnvironment,
  ExchangeCapability,
  ExchangeOrderType,
  ExchangeBalance,
  ExchangePosition,
  ExchangeOrder,
  ExchangeFill,
  ExchangeSymbol,
  ExchangeCapabilityDiscovery,
  ExchangePositionSide,
  ExchangeOrderStatus,
  ExchangeOrderSide,
  ExchangeConnectivityResult,
} from '../exchange.types';
import {
  ExchangeProviderError,
  ExchangeProviderErrorCode,
  ExchangeProviderContext,
  ExchangeServerTime,
  ExchangeAccountMetadata,
} from '../exchange-provider.interface';
import {
  BaseExchangeProvider,
  subtractDecimalStrings,
  absDecimalString,
  isDecimalString,
  msToMicros,
  nowMicros,
  precisionOfStep,
  canonicalFromConcatenated,
} from '../base-exchange-provider';

/** Categories this provider reads. Spot plus USDT/USDC-settled linear contracts. */
type BybitCategory = 'spot' | 'linear';

const RECV_WINDOW = '5000';
const MAX_PAGES = 10;

function dec(value: unknown): string {
  return isDecimalString(value) ? value : '0';
}

function decOrNull(value: unknown): string | null {
  return isDecimalString(value) && value !== '' ? value : null;
}

/**
 * Bybit V5 unified API, read side: server time, key permissions, wallet,
 * positions, open orders, order history, executions and instruments.
 *
 * Authentication (V5): `X-BAPI-SIGN = hex(HMAC_SHA256(secret, timestamp + apiKey + recvWindow + queryString))`.
 * Every response is an envelope `{ retCode, retMsg, result }`; a non-zero
 * retCode is a venue refusal and is classified, never read as an empty list.
 * This provider places no orders - order transmission belongs to the execution
 * engine behind the live-mode gate.
 */
export class BybitProvider extends BaseExchangeProvider {
  readonly venue = ExchangeVenue.BYBIT;
  readonly displayName: string;
  readonly supportedEnvironments: ExchangeEnvironment[] = [ExchangeEnvironment.LIVE, ExchangeEnvironment.TESTNET, ExchangeEnvironment.SANDBOX];
  readonly supportedCapabilities: ExchangeCapability[] = [
    ExchangeCapability.SPOT,
    ExchangeCapability.PERPETUALS,
    ExchangeCapability.MARKET_DATA,
    ExchangeCapability.BALANCES,
    ExchangeCapability.POSITIONS,
    ExchangeCapability.ORDERS,
    ExchangeCapability.TRADES,
    ExchangeCapability.TESTNET,
  ];

  constructor(
    private readonly urls: { liveRest: string; testnetRest: string; sandboxRest: string; liveWs: string; testnetWs: string; sandboxWs: string },
    displayName = 'Bybit',
  ) {
    super();
    this.displayName = displayName;
  }

  protected getLiveRestUrl(): string {
    return this.urls.liveRest;
  }
  protected getTestnetRestUrl(): string {
    return this.urls.testnetRest;
  }
  protected getSandboxRestUrl(): string {
    return this.urls.sandboxRest;
  }
  protected getLiveWsUrl(): string {
    return this.urls.liveWs;
  }
  protected getTestnetWsUrl(): string {
    return this.urls.testnetWs;
  }
  protected getSandboxWsUrl(): string {
    return this.urls.sandboxWs;
  }

  /** Exposed for tests: the exact V5 signature over the canonical payload. */
  static sign(secret: string, timestamp: string, apiKey: string, recvWindow: string, queryString: string): string {
    return crypto.createHmac('sha256', secret).update(timestamp + apiKey + recvWindow + queryString).digest('hex');
  }

  private buildQuery(params: Record<string, string | number | undefined>): string {
    return Object.entries(params)
      .filter(([, v]) => v !== undefined && v !== '')
      .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
      .join('&');
  }

  private unwrap(context: ExchangeProviderContext, data: any): any {
    if (!data || typeof data !== 'object') {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, 'Bybit returned a non-JSON body', context.venue, context.environment, true);
    }
    const code = Number(data.retCode);
    if (code === 0) return data.result ?? {};
    const message = `Bybit retCode ${data.retCode}: ${String(data.retMsg ?? '').slice(0, 200)}`;
    if ([10003, 10004, 33004, 10007].includes(code)) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.AUTH_FAILED, message, context.venue, context.environment, false);
    }
    if ([10005, 10010].includes(code)) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.PERMISSION_DENIED, message, context.venue, context.environment, false);
    }
    if (code === 10002) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.CLOCK_DRIFT, message, context.venue, context.environment, true, 1000);
    }
    if ([10006, 10018, 10429].includes(code)) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.RATE_LIMITED, message, context.venue, context.environment, true, 1000);
    }
    if (code === 10001) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.INVALID_ORDER, message, context.venue, context.environment, false);
    }
    if (code === 10016) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.SERVER_ERROR, message, context.venue, context.environment, true, 1000);
    }
    throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, message, context.venue, context.environment, false);
  }

  private async publicGet(context: ExchangeProviderContext, path: string, params: Record<string, string | number | undefined> = {}): Promise<any> {
    const query = this.buildQuery(params);
    const url = `${this.getRestBaseUrlForEnv(context.environment)}${path}${query ? `?${query}` : ''}`;
    try {
      return this.unwrap(context, await this.httpGet(url));
    } catch (e: any) {
      throw this.normalizeError(e, context.venue, context.environment);
    }
  }

  private async privateGet(context: ExchangeProviderContext, path: string, params: Record<string, string | number | undefined> = {}): Promise<any> {
    this.requireCredentials(context);
    const query = this.buildQuery(params);
    const timestamp = Date.now().toString();
    const signature = BybitProvider.sign(context.credentials.apiSecret, timestamp, context.credentials.apiKey, RECV_WINDOW, query);
    const url = `${this.getRestBaseUrlForEnv(context.environment)}${path}${query ? `?${query}` : ''}`;
    try {
      const data = await this.httpGet(url, {
        'X-BAPI-API-KEY': context.credentials.apiKey,
        'X-BAPI-TIMESTAMP': timestamp,
        'X-BAPI-RECV-WINDOW': RECV_WINDOW,
        'X-BAPI-SIGN': signature,
      });
      return this.unwrap(context, data);
    } catch (e: any) {
      throw this.normalizeError(e, context.venue, context.environment);
    }
  }

  /** Follows `nextPageCursor` up to MAX_PAGES pages, concatenating `result.list`. */
  private async privateList(context: ExchangeProviderContext, path: string, params: Record<string, string | number | undefined>, maxItems: number): Promise<any[]> {
    const rows: any[] = [];
    let cursor: string | undefined;
    for (let page = 0; page < MAX_PAGES && rows.length < maxItems; page += 1) {
      const result = await this.privateGet(context, path, { ...params, cursor });
      const list = Array.isArray(result?.list) ? result.list : [];
      rows.push(...list);
      cursor = typeof result?.nextPageCursor === 'string' && result.nextPageCursor !== '' ? result.nextPageCursor : undefined;
      if (!cursor || list.length === 0) break;
    }
    return rows.slice(0, maxItems);
  }

  async getServerTime(context: ExchangeProviderContext): Promise<ExchangeServerTime> {
    const result = await this.publicGet(context, '/v5/market/time');
    const nano = typeof result?.timeNano === 'string' && /^\d+$/.test(result.timeNano) ? BigInt(result.timeNano) : null;
    const seconds = Number(result?.timeSecond);
    const serverMs = nano !== null ? Number(nano / 1_000_000n) : seconds * 1000;
    if (!Number.isFinite(serverMs) || serverMs <= 0) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, 'Bybit server time missing from response', context.venue, context.environment, true);
    }
    return this.serverTimeFromMs(serverMs);
  }

  async testConnectivity(context: ExchangeProviderContext): Promise<ExchangeConnectivityResult> {
    return this.connectivityFromMetadata(context);
  }

  async getAccountMetadata(context: ExchangeProviderContext): Promise<ExchangeAccountMetadata> {
    const info = await this.privateGet(context, '/v5/user/query-api');
    const permissions: Record<string, string[]> = info?.permissions && typeof info.permissions === 'object' ? info.permissions : {};
    const flat = Object.entries(permissions).flatMap(([group, values]) => (Array.isArray(values) ? values.map((v) => `${group}:${v}`) : []));
    const readOnly = Number(info?.readOnly) === 1;
    const canWithdraw = (permissions['Wallet'] ?? []).some((p) => /withdraw/i.test(p));
    const canTrade =
      !readOnly &&
      ((permissions['Spot'] ?? []).includes('SpotTrade') ||
        (permissions['ContractTrade'] ?? []).length > 0 ||
        (permissions['Derivatives'] ?? []).length > 0 ||
        (permissions['Options'] ?? []).length > 0);
    const ips: string[] = Array.isArray(info?.ips) ? info.ips : [];
    return {
      accountId: context.accountId,
      venue: context.venue,
      environment: context.environment,
      isSandbox: context.isSandbox,
      canTrade,
      canRead: true,
      canWithdraw,
      ipRestricted: ips.length > 0 && !ips.includes('*'),
      permissions: flat,
      uid: info?.userID !== undefined && info?.userID !== null ? String(info.userID) : null,
      email: null,
    };
  }

  async getCapabilities(context: ExchangeProviderContext): Promise<ExchangeCapabilityDiscovery> {
    return {
      venue: context.venue,
      environment: context.environment,
      capabilities: this.supportedCapabilities,
      supportedOrderTypes: [ExchangeOrderType.MARKET, ExchangeOrderType.LIMIT, ExchangeOrderType.STOP, ExchangeOrderType.STOP_LIMIT],
      supportedEnvironments: this.supportedEnvironments,
      apiVersion: 'v5',
      restAvailable: true,
      websocketAvailable: true,
      rateLimitModel: 'REQUEST_COUNT',
      authenticationModel: 'HMAC_SHA256',
      symbolFormat: 'BTCUSDT',
      timestamp: new Date().toISOString(),
    };
  }

  async getBalances(context: ExchangeProviderContext): Promise<ExchangeBalance[]> {
    const result = await this.privateGet(context, '/v5/account/wallet-balance', { accountType: 'UNIFIED' });
    const account = Array.isArray(result?.list) ? result.list[0] : undefined;
    const coins: any[] = Array.isArray(account?.coin) ? account.coin : [];
    const timestampMicros = nowMicros();
    return coins
      .map((c) => {
        const total = dec(c.walletBalance);
        const locked = dec(c.locked);
        let free = subtractDecimalStrings(total, locked);
        if (free.startsWith('-')) free = '0';
        return {
          asset: String(c.coin),
          free,
          locked,
          total,
          providerReference: account?.accountType ? String(account.accountType) : null,
          timestampMicros,
          source: 'REST',
          isSimulated: context.isSandbox,
        };
      })
      .filter((b) => b.total !== '0' || b.locked !== '0');
  }

  async getPositions(context: ExchangeProviderContext): Promise<ExchangePosition[]> {
    const rows: any[] = [];
    for (const settleCoin of ['USDT', 'USDC']) {
      rows.push(...(await this.privateList(context, '/v5/position/list', { category: 'linear', settleCoin, limit: 200 }, 1000)));
    }
    return rows
      .filter((p) => isDecimalString(p.size) && p.size !== '0' && !/^0(\.0+)?$/.test(p.size))
      .map((p) => ({
        providerPositionId: p.positionIdx !== undefined ? `${p.symbol}:${p.positionIdx}` : null,
        symbol: canonicalFromConcatenated(p.symbol),
        exchangeSymbol: String(p.symbol),
        side: p.side === 'Buy' ? ExchangePositionSide.LONG : p.side === 'Sell' ? ExchangePositionSide.SHORT : ExchangePositionSide.FLAT,
        quantity: absDecimalString(p.size),
        entryPrice: decOrNull(p.avgPrice),
        markPrice: decOrNull(p.markPrice),
        liquidationPrice: decOrNull(p.liqPrice),
        leverage: decOrNull(p.leverage),
        unrealizedPnl: decOrNull(p.unrealisedPnl),
        realizedPnl: decOrNull(p.cumRealisedPnl),
        timestampMicros: msToMicros(p.updatedTime) ?? nowMicros(),
        isSimulated: context.isSandbox,
      }));
  }

  private categoriesFor(symbol?: string): Array<{ category: BybitCategory; settleCoin?: string }> {
    if (symbol) return [{ category: 'spot' }, { category: 'linear' }];
    return [{ category: 'spot' }, { category: 'linear', settleCoin: 'USDT' }, { category: 'linear', settleCoin: 'USDC' }];
  }

  async getOpenOrders(context: ExchangeProviderContext, symbol?: string): Promise<ExchangeOrder[]> {
    const exchangeSymbol = symbol ? symbol.replace(/[-/]/g, '').toUpperCase() : undefined;
    const rows: any[] = [];
    for (const scope of this.categoriesFor(exchangeSymbol)) {
      rows.push(...(await this.privateList(context, '/v5/order/realtime', { ...scope, symbol: exchangeSymbol, limit: 50 }, 500)));
    }
    return rows.map((o) => this.mapOrder(context, o));
  }

  async getOrderHistory(context: ExchangeProviderContext, symbol?: string, limit = 50): Promise<ExchangeOrder[]> {
    const exchangeSymbol = symbol ? symbol.replace(/[-/]/g, '').toUpperCase() : undefined;
    const rows: any[] = [];
    for (const scope of this.categoriesFor(exchangeSymbol)) {
      rows.push(...(await this.privateList(context, '/v5/order/history', { ...scope, symbol: exchangeSymbol, limit: Math.min(limit, 50) }, limit)));
    }
    return rows
      .map((o) => this.mapOrder(context, o))
      .sort((a, b) => Number(BigInt(b.createdAtMicros ?? '0') - BigInt(a.createdAtMicros ?? '0')))
      .slice(0, limit);
  }

  async getTradeHistory(context: ExchangeProviderContext, symbol?: string, limit = 50): Promise<ExchangeFill[]> {
    const exchangeSymbol = symbol ? symbol.replace(/[-/]/g, '').toUpperCase() : undefined;
    const rows: any[] = [];
    for (const scope of this.categoriesFor(exchangeSymbol)) {
      rows.push(...(await this.privateList(context, '/v5/execution/list', { ...scope, symbol: exchangeSymbol, limit: Math.min(limit, 100) }, limit)));
    }
    return rows
      .map((t) => ({
        providerTradeId: String(t.execId),
        providerOrderId: t.orderId ? String(t.orderId) : null,
        clientOrderId: t.orderLinkId ? String(t.orderLinkId) : null,
        symbol: canonicalFromConcatenated(t.symbol),
        side: t.side === 'Buy' ? ExchangeOrderSide.BUY : ExchangeOrderSide.SELL,
        price: dec(t.execPrice),
        quantity: dec(t.execQty),
        quoteQuantity: decOrNull(t.execValue),
        fee: decOrNull(t.execFee),
        feeCurrency: t.feeCurrency ? String(t.feeCurrency) : null,
        isMaker: typeof t.isMaker === 'boolean' ? t.isMaker : null,
        timestampMicros: msToMicros(t.execTime) ?? nowMicros(),
        isSimulated: context.isSandbox,
      }))
      .sort((a, b) => Number(BigInt(b.timestampMicros) - BigInt(a.timestampMicros)))
      .slice(0, limit);
  }

  async getSymbols(context: ExchangeProviderContext): Promise<ExchangeSymbol[]> {
    const result = await this.publicGet(context, '/v5/market/instruments-info', { category: 'spot', limit: 1000 });
    const list: any[] = Array.isArray(result?.list) ? result.list : [];
    return list
      .filter((s) => s.status === 'Trading')
      .map((s) => {
        const tick = s.priceFilter?.tickSize ?? '0.00000001';
        const step = s.lotSizeFilter?.basePrecision ?? s.lotSizeFilter?.qtyStep ?? '0.00000001';
        return {
          canonicalSymbol: `${s.baseCoin}-${s.quoteCoin}`,
          exchangeSymbol: String(s.symbol),
          baseAsset: String(s.baseCoin),
          quoteAsset: String(s.quoteCoin),
          contractType: 'SPOT',
          tickSize: String(tick),
          quantityStep: String(step),
          minQuantity: decOrNull(s.lotSizeFilter?.minOrderQty),
          maxQuantity: decOrNull(s.lotSizeFilter?.maxOrderQty),
          minNotional: decOrNull(s.lotSizeFilter?.minOrderAmt),
          maxNotional: decOrNull(s.lotSizeFilter?.maxOrderAmt),
          pricePrecision: precisionOfStep(String(tick)),
          quantityPrecision: precisionOfStep(String(step)),
          minLeverage: null,
          maxLeverage: null,
          isTradeable: true,
        };
      });
  }

  private mapOrder(context: ExchangeProviderContext, o: any): ExchangeOrder {
    const hasTrigger = isDecimalString(o.triggerPrice) && !/^0(\.0+)?$/.test(o.triggerPrice);
    const isLimit = String(o.orderType) === 'Limit';
    const type = hasTrigger ? (isLimit ? ExchangeOrderType.STOP_LIMIT : ExchangeOrderType.STOP) : isLimit ? ExchangeOrderType.LIMIT : ExchangeOrderType.MARKET;
    return {
      clientOrderId: o.orderLinkId ? String(o.orderLinkId) : String(o.orderId),
      providerOrderId: o.orderId ? String(o.orderId) : null,
      symbol: canonicalFromConcatenated(o.symbol),
      exchangeSymbol: String(o.symbol),
      side: o.side === 'Buy' ? ExchangeOrderSide.BUY : ExchangeOrderSide.SELL,
      type,
      status: BybitProvider.mapOrderStatus(String(o.orderStatus)),
      providerRawStatus: o.orderStatus ? String(o.orderStatus) : null,
      quantity: dec(o.qty),
      price: isLimit ? decOrNull(o.price) : null,
      stopPrice: hasTrigger ? String(o.triggerPrice) : null,
      filledQuantity: dec(o.cumExecQty),
      averagePrice: decOrNull(o.avgPrice) === '0' ? null : decOrNull(o.avgPrice),
      fee: decOrNull(o.cumExecFee),
      feeCurrency: null,
      createdAtMicros: msToMicros(o.createdTime),
      updatedAtMicros: msToMicros(o.updatedTime),
      isSimulated: context.isSandbox,
    };
  }

  static mapOrderStatus(status: string): ExchangeOrderStatus {
    switch (status) {
      case 'New':
      case 'Created':
      case 'Untriggered':
      case 'Triggered':
      case 'Active':
        return ExchangeOrderStatus.NEW;
      case 'PartiallyFilled':
        return ExchangeOrderStatus.PARTIALLY_FILLED;
      case 'Filled':
        return ExchangeOrderStatus.FILLED;
      case 'Cancelled':
      case 'PartiallyFilledCanceled':
      case 'Deactivated':
        return ExchangeOrderStatus.CANCELED;
      case 'Rejected':
        return ExchangeOrderStatus.REJECTED;
      default:
        return ExchangeOrderStatus.NEW;
    }
  }
}

// # Implements signed Advanced Trade live REST/account/symbol/health probes when live trading enabled
import * as crypto from 'crypto';
import {
  ExchangeVenue,
  ExchangeEnvironment,
  ExchangeCapability,
  ExchangeOrderType,
  ExchangeBalance,
  ExchangePosition,
  ExchangeOrder,
  ExchangeFill,
  ExchangeSymbol,
  ExchangeCapabilityDiscovery,
  ExchangePositionSide,
  ExchangeOrderStatus,
  ExchangeOrderSide,
  ExchangeConnectivityResult,
} from '../exchange.types';
import {
  ExchangeProviderError,
  ExchangeProviderErrorCode,
  ExchangeProviderContext,
  ExchangeServerTime,
  ExchangeAccountMetadata,
} from '../exchange-provider.interface';
import {
  BaseExchangeProvider,
  addDecimalStrings,
  isDecimalString,
  isoToMicros,
  nowMicros,
  precisionOfStep,
} from '../base-exchange-provider';

function dec(value: unknown): string {
  return isDecimalString(value) ? value : '0';
}

function decOrNull(value: unknown): string | null {
  return isDecimalString(value) ? value : null;
}

const MAX_PAGES = 10;
/** PKCS#8 DER prefix for a raw 32-byte Ed25519 seed. */
const ED25519_PKCS8_PREFIX = Buffer.from('302e020100300506032b657004220420', 'hex');

function base64url(input: Buffer | string): string {
  return Buffer.from(input).toString('base64').replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_');
}

/**
 * Loads a Coinbase Developer Platform (CDP) API secret as a private key.
 * Accepts both key families CDP issues: an EC P-256 PEM ("-----BEGIN EC PRIVATE
 * KEY-----", often stored with literal "\n" escapes) and an Ed25519 secret
 * delivered as base64 of 64 bytes (seed || public key).
 */
export function loadCoinbaseKey(secret: string): { key: crypto.KeyObject; alg: 'ES256' | 'EdDSA' } {
  const normalized = secret.includes('\\n') ? secret.replace(/\\n/g, '\n') : secret;
  if (normalized.includes('-----BEGIN')) {
    const key = crypto.createPrivateKey(normalized);
    const type = key.asymmetricKeyType;
    if (type === 'ec') return { key, alg: 'ES256' };
    if (type === 'ed25519') return { key, alg: 'EdDSA' };
    throw new Error(`unsupported Coinbase key type ${type}`);
  }
  const raw = Buffer.from(normalized.trim(), 'base64');
  if (raw.length !== 64 && raw.length !== 32) throw new Error('Coinbase Ed25519 secret must be base64 of 32 or 64 bytes');
  const key = crypto.createPrivateKey({ key: Buffer.concat([ED25519_PKCS8_PREFIX, raw.subarray(0, 32)]), format: 'der', type: 'pkcs8' });
  return { key, alg: 'EdDSA' };
}

/**
 * Builds the short-lived bearer JWT Coinbase Advanced Trade requires on every
 * private request: `sub`/`kid` = API key name, `iss` = "cdp", a two-minute
 * validity window, and `uri` = "METHOD host/path" binding the token to exactly
 * one endpoint (query string excluded, as the venue specifies).
 */
export function buildCoinbaseJwt(keyName: string, secret: string, method: string, host: string, path: string, nowSeconds = Math.floor(Date.now() / 1000)): string {
  const { key, alg } = loadCoinbaseKey(secret);
  const header = { alg, kid: keyName, nonce: crypto.randomBytes(16).toString('hex'), typ: 'JWT' };
  const payload = { iss: 'cdp', sub: keyName, nbf: nowSeconds, exp: nowSeconds + 120, uri: `${method.toUpperCase()} ${host}${path}` };
  const signingInput = `${base64url(JSON.stringify(header))}.${base64url(JSON.stringify(payload))}`;
  const signature =
    alg === 'ES256'
      ? crypto.sign('sha256', Buffer.from(signingInput), { key, dsaEncoding: 'ieee-p1363' })
      : crypto.sign(null, Buffer.from(signingInput), key);
  return `${signingInput}.${base64url(signature)}`;
}

/**
 * Coinbase Advanced Trade API (v3 brokerage), read side.
 *
 * Authentication is a per-request ES256/EdDSA JWT built from a CDP API key
 * (key name + private key); there is no passphrase. The sandbox
 * (api-sandbox.coinbase.com) serves static responses and accepts no
 * authentication, so sandbox calls are sent without a token rather than with
 * a token signed by a key the sandbox cannot verify.
 */
export class CoinbaseProvider extends BaseExchangeProvider {
  readonly venue = ExchangeVenue.COINBASE;
  readonly displayName: string;
  readonly supportedEnvironments: ExchangeEnvironment[] = [ExchangeEnvironment.LIVE, ExchangeEnvironment.SANDBOX];
  readonly supportedCapabilities: ExchangeCapability[] = [
    ExchangeCapability.SPOT,
    ExchangeCapability.FUTURES,
    ExchangeCapability.MARKET_DATA,
    ExchangeCapability.BALANCES,
    ExchangeCapability.POSITIONS,
    ExchangeCapability.ORDERS,
    ExchangeCapability.TRADES,
  ];

  constructor(
    private readonly urls: { liveRest: string; sandboxRest: string; liveWs: string; sandboxWs: string },
    displayName = 'Coinbase Advanced Trade',
  ) {
    super();
    this.displayName = displayName;
  }

  protected getLiveRestUrl(): string {
    return this.urls.liveRest;
  }
  protected getTestnetRestUrl(): string {
    return this.urls.sandboxRest;
  }
  protected getSandboxRestUrl(): string {
    return this.urls.sandboxRest;
  }
  protected getLiveWsUrl(): string {
    return this.urls.liveWs;
  }
  protected getTestnetWsUrl(): string {
    return this.urls.sandboxWs;
  }
  protected getSandboxWsUrl(): string {
    return this.urls.sandboxWs;
  }

  private buildQuery(params: Record<string, string | number | undefined>): string {
    return Object.entries(params)
      .filter(([, v]) => v !== undefined && v !== '')
      .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
      .join('&');
  }

  private async privateGet(context: ExchangeProviderContext, path: string, params: Record<string, string | number | undefined> = {}): Promise<any> {
    const base = this.getRestBaseUrlForEnv(context.environment);
    const query = this.buildQuery(params);
    const headers: Record<string, string> = { Accept: 'application/json' };
    if (context.environment === ExchangeEnvironment.LIVE) {
      this.requireCredentials(context);
      let token: string;
      try {
        token = buildCoinbaseJwt(context.credentials.apiKey, context.credentials.apiSecret, 'GET', new URL(base).host, path);
      } catch (e: any) {
        throw new ExchangeProviderError(
          ExchangeProviderErrorCode.INVALID_CREDENTIALS,
          `Coinbase API secret is not a usable CDP private key (${String(e?.message ?? e).slice(0, 120)})`,
          context.venue,
          context.environment,
          false,
        );
      }
      headers.Authorization = `Bearer ${token}`;
    }
    try {
      return await this.httpGet(`${base}${path}${query ? `?${query}` : ''}`, headers);
    } catch (e: any) {
      throw this.normalizeError(e, context.venue, context.environment);
    }
  }

  async getServerTime(context: ExchangeProviderContext): Promise<ExchangeServerTime> {
    let data: any;
    try {
      data = await this.httpGet(`${this.getRestBaseUrlForEnv(context.environment)}/api/v3/brokerage/time`, { Accept: 'application/json' });
    } catch (e: any) {
      throw this.normalizeError(e, context.venue, context.environment);
    }
    const ms = Number(data?.epochMillis ?? (data?.epochSeconds !== undefined ? Number(data.epochSeconds) * 1000 : NaN));
    if (!Number.isFinite(ms) || ms <= 0) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, 'Coinbase server time missing from response', context.venue, context.environment, true);
    }
    return this.serverTimeFromMs(ms);
  }

  async testConnectivity(context: ExchangeProviderContext): Promise<ExchangeConnectivityResult> {
    return this.connectivityFromMetadata(context);
  }

  async getAccountMetadata(context: ExchangeProviderContext): Promise<ExchangeAccountMetadata> {
    const data = await this.privateGet(context, '/api/v3/brokerage/key_permissions');
    const permissions: string[] = [];
    if (data?.can_view) permissions.push('view');
    if (data?.can_trade) permissions.push('trade');
    if (data?.can_transfer) permissions.push('transfer');
    return {
      accountId: context.accountId,
      venue: context.venue,
      environment: context.environment,
      isSandbox: context.isSandbox,
      canTrade: data?.can_trade === true,
      canRead: data?.can_view === true,
      // `can_transfer` is Coinbase's "move funds out" permission; anything but
      // an explicit false is treated as present (fail closed).
      canWithdraw: data?.can_transfer !== false,
      ipRestricted: false,
      permissions,
      uid: data?.portfolio_uuid ? String(data.portfolio_uuid) : null,
      email: null,
    };
  }

  async getCapabilities(context: ExchangeProviderContext): Promise<ExchangeCapabilityDiscovery> {
    return {
      venue: context.venue,
      environment: context.environment,
      capabilities: this.supportedCapabilities,
      supportedOrderTypes: [ExchangeOrderType.MARKET, ExchangeOrderType.LIMIT, ExchangeOrderType.STOP_LIMIT],
      supportedEnvironments: this.supportedEnvironments,
      apiVersion: 'v3',
      restAvailable: true,
      websocketAvailable: true,
      rateLimitModel: 'REQUEST_COUNT',
      authenticationModel: 'JWT_ES256',
      symbolFormat: 'BTC-USD',
      timestamp: new Date().toISOString(),
    };
  }

  async getBalances(context: ExchangeProviderContext): Promise<ExchangeBalance[]> {
    const rows: any[] = [];
    let cursor: string | undefined;
    for (let page = 0; page < MAX_PAGES; page += 1) {
      const data = await this.privateGet(context, '/api/v3/brokerage/accounts', { limit: 250, cursor });
      rows.push(...(Array.isArray(data?.accounts) ? data.accounts : []));
      if (!data?.has_next || !data?.cursor) break;
      cursor = String(data.cursor);
    }
    const timestampMicros = nowMicros();
    return rows
      .map((a) => {
        const free = dec(a?.available_balance?.value);
        const locked = dec(a?.hold?.value);
        return {
          asset: String(a?.currency ?? a?.available_balance?.currency ?? ''),
          free,
          locked,
          total: addDecimalStrings(free, locked),
          providerReference: a?.uuid ? String(a.uuid) : null,
          timestampMicros,
          source: 'REST',
          isSimulated: context.isSandbox,
        };
      })
      .filter((b) => b.asset !== '' && (!/^0(\.0+)?$/.test(b.total)));
  }

  /**
   * Coinbase spot holds balances, not positions, so a spot-only portfolio
   * truthfully has none. Futures (CFM) positions are read when the portfolio
   * has a futures account; the venue answers 4xx for one that does not, which
   * is the "no futures account" fact, not an error to surface.
   */
  async getPositions(context: ExchangeProviderContext): Promise<ExchangePosition[]> {
    let data: any;
    try {
      data = await this.privateGet(context, '/api/v3/brokerage/cfm/positions');
    } catch (e: any) {
      const status = e?.originalError?.status;
      if (e instanceof ExchangeProviderError && [400, 404].includes(status)) return [];
      throw e;
    }
    const positions: any[] = Array.isArray(data?.positions) ? data.positions : [];
    return positions
      .filter((p) => isDecimalString(p?.number_of_contracts) && !/^0(\.0+)?$/.test(p.number_of_contracts))
      .map((p) => ({
        providerPositionId: p?.product_id ? String(p.product_id) : null,
        symbol: String(p?.product_id ?? ''),
        exchangeSymbol: String(p?.product_id ?? ''),
        side: String(p?.side).toUpperCase() === 'SHORT' ? ExchangePositionSide.SHORT : ExchangePositionSide.LONG,
        quantity: String(p.number_of_contracts).replace(/^-/, ''),
        entryPrice: decOrNull(p?.avg_entry_price),
        markPrice: decOrNull(p?.current_price),
        liquidationPrice: null,
        leverage: null,
        unrealizedPnl: decOrNull(p?.unrealized_pnl),
        realizedPnl: decOrNull(p?.daily_realized_pnl),
        timestampMicros: nowMicros(),
        isSimulated: context.isSandbox,
      }));
  }

  private async listOrders(context: ExchangeProviderContext, params: Record<string, string | number | undefined>, maxItems: number): Promise<any[]> {
    const rows: any[] = [];
    let cursor: string | undefined;
    for (let page = 0; page < MAX_PAGES && rows.length < maxItems; page += 1) {
      const data = await this.privateGet(context, '/api/v3/brokerage/orders/historical/batch', { ...params, cursor });
      rows.push(...(Array.isArray(data?.orders) ? data.orders : []));
      if (!data?.has_next || !data?.cursor) break;
      cursor = String(data.cursor);
    }
    return rows.slice(0, maxItems);
  }

  async getOpenOrders(context: ExchangeProviderContext, symbol?: string): Promise<ExchangeOrder[]> {
    const rows = await this.listOrders(context, { order_status: 'OPEN', product_ids: symbol?.toUpperCase(), limit: 100 }, 1000);
    return rows.map((o) => this.mapOrder(context, o));
  }

  async getOrderHistory(context: ExchangeProviderContext, symbol?: string, limit = 50): Promise<ExchangeOrder[]> {
    const rows = await this.listOrders(context, { product_ids: symbol?.toUpperCase(), limit: Math.min(limit, 100) }, limit);
    return rows.map((o) => this.mapOrder(context, o));
  }

  async getTradeHistory(context: ExchangeProviderContext, symbol?: string, limit = 50): Promise<ExchangeFill[]> {
    const data = await this.privateGet(context, '/api/v3/brokerage/orders/historical/fills', { product_ids: symbol?.toUpperCase(), limit: Math.min(limit, 100) });
    const fills: any[] = Array.isArray(data?.fills) ? data.fills : [];
    return fills.slice(0, limit).map((f) => {
      const product = String(f?.product_id ?? '');
      return {
        providerTradeId: String(f?.trade_id ?? f?.entry_id),
        providerOrderId: f?.order_id ? String(f.order_id) : null,
        clientOrderId: null,
        symbol: product,
        side: String(f?.side).toUpperCase() === 'SELL' ? ExchangeOrderSide.SELL : ExchangeOrderSide.BUY,
        price: dec(f?.price),
        quantity: dec(f?.size),
        quoteQuantity: f?.size_in_quote === true ? dec(f?.size) : null,
        fee: decOrNull(f?.commission),
        feeCurrency: product.includes('-') ? product.split('-')[1] : null,
        isMaker: f?.liquidity_indicator === 'MAKER' ? true : f?.liquidity_indicator === 'TAKER' ? false : null,
        timestampMicros: isoToMicros(f?.trade_time) ?? nowMicros(),
        isSimulated: context.isSandbox,
      };
    });
  }

  async getSymbols(context: ExchangeProviderContext): Promise<ExchangeSymbol[]> {
    const data = await this.privateGet(context, '/api/v3/brokerage/products', { product_type: 'SPOT' });
    const products: any[] = Array.isArray(data?.products) ? data.products : [];
    return products
      .filter((p) => p?.status === 'online' && !p?.trading_disabled && !p?.is_disabled && !p?.cancel_only)
      .map((p) => {
        const tick = String(p?.price_increment ?? p?.quote_increment ?? '0.01');
        const step = String(p?.base_increment ?? '0.00000001');
        return {
          canonicalSymbol: `${p.base_currency_id}-${p.quote_currency_id}`,
          exchangeSymbol: String(p.product_id),
          baseAsset: String(p.base_currency_id),
          quoteAsset: String(p.quote_currency_id),
          contractType: 'SPOT',
          tickSize: tick,
          quantityStep: step,
          minQuantity: decOrNull(p?.base_min_size),
          maxQuantity: decOrNull(p?.base_max_size),
          minNotional: decOrNull(p?.quote_min_size),
          maxNotional: decOrNull(p?.quote_max_size),
          pricePrecision: precisionOfStep(tick),
          quantityPrecision: precisionOfStep(step),
          minLeverage: null,
          maxLeverage: null,
          isTradeable: true,
        };
      });
  }

  private mapOrder(context: ExchangeProviderContext, o: any): ExchangeOrder {
    const config = o?.order_configuration ?? {};
    const variant: any = Object.values(config)[0] ?? {};
    const orderType = String(o?.order_type ?? '');
    let type: ExchangeOrderType;
    if (orderType === 'MARKET') type = ExchangeOrderType.MARKET;
    else if (orderType === 'STOP_LIMIT') type = ExchangeOrderType.STOP_LIMIT;
    else if (orderType === 'STOP') type = ExchangeOrderType.STOP;
    else if (variant?.post_only === true) type = ExchangeOrderType.LIMIT_MAKER;
    else type = ExchangeOrderType.LIMIT;
    const product = String(o?.product_id ?? '');
    return {
      clientOrderId: o?.client_order_id ? String(o.client_order_id) : String(o?.order_id),
      providerOrderId: o?.order_id ? String(o.order_id) : null,
      symbol: product,
      exchangeSymbol: product,
      side: String(o?.side).toUpperCase() === 'SELL' ? ExchangeOrderSide.SELL : ExchangeOrderSide.BUY,
      type,
      status: CoinbaseProvider.mapOrderStatus(String(o?.status ?? ''), dec(o?.filled_size)),
      providerRawStatus: o?.status ? String(o.status) : null,
      quantity: decOrNull(variant?.base_size) ?? decOrNull(variant?.quote_size) ?? dec(o?.filled_size),
      price: decOrNull(variant?.limit_price),
      stopPrice: decOrNull(variant?.stop_price),
      filledQuantity: dec(o?.filled_size),
      averagePrice: isDecimalString(o?.average_filled_price) && !/^0(\.0+)?$/.test(o.average_filled_price) ? o.average_filled_price : null,
      fee: decOrNull(o?.total_fees),
      feeCurrency: product.includes('-') ? product.split('-')[1] : null,
      createdAtMicros: isoToMicros(o?.created_time),
      updatedAtMicros: isoToMicros(o?.last_fill_time) ?? isoToMicros(o?.created_time),
      isSimulated: context.isSandbox,
    };
  }

  static mapOrderStatus(status: string, filled = '0'): ExchangeOrderStatus {
    const executed = !/^0(\.0+)?$/.test(filled);
    switch (status) {
      case 'PENDING':
      case 'QUEUED':
      case 'OPEN':
        return executed ? ExchangeOrderStatus.PARTIALLY_FILLED : ExchangeOrderStatus.NEW;
      case 'FILLED':
        return ExchangeOrderStatus.FILLED;
      case 'CANCELLED':
        return ExchangeOrderStatus.CANCELED;
      case 'CANCEL_QUEUED':
        return ExchangeOrderStatus.PENDING_CANCEL;
      case 'EXPIRED':
        return ExchangeOrderStatus.EXPIRED;
      case 'FAILED':
        return ExchangeOrderStatus.REJECTED;
      default:
        return ExchangeOrderStatus.NEW;
    }
  }
}

// # Implements signed live REST/account/symbol/health probes when live trading enabled
import * as crypto from 'crypto';
import {
  ExchangeVenue,
  ExchangeEnvironment,
  ExchangeCapability,
  ExchangeOrderType,
  ExchangeBalance,
  ExchangePosition,
  ExchangeOrder,
  ExchangeFill,
  ExchangeSymbol,
  ExchangeCapabilityDiscovery,
  ExchangePositionSide,
  ExchangeOrderStatus,
  ExchangeOrderSide,
  ExchangeConnectivityResult,
} from '../exchange.types';
import {
  ExchangeProviderError,
  ExchangeProviderErrorCode,
  ExchangeProviderContext,
  ExchangeServerTime,
  ExchangeAccountMetadata,
} from '../exchange-provider.interface';
import {
  BaseExchangeProvider,
  subtractDecimalStrings,
  isDecimalString,
  secondsToMicros,
  nowMicros,
} from '../base-exchange-provider';

function dec(value: unknown): string {
  return isDecimalString(value) ? value : '0';
}

function decOrNull(value: unknown): string | null {
  return isDecimalString(value) ? value : null;
}

/**
 * Kraken's legacy asset codes ("XXBT", "ZUSD", "XETH") to the platform's
 * conventional tickers. Codes outside this table are returned unchanged -
 * newer Kraken assets already use plain tickers, and a staked/earn suffix
 * (".S", ".F", ".B") is kept because it is a different balance, not a typo.
 */
const KRAKEN_ASSETS: Record<string, string> = {
  XXBT: 'BTC',
  XBT: 'BTC',
  XXDG: 'DOGE',
  XDG: 'DOGE',
  XETH: 'ETH',
  XETC: 'ETC',
  XLTC: 'LTC',
  XXLM: 'XLM',
  XXMR: 'XMR',
  XXRP: 'XRP',
  XZEC: 'ZEC',
  XMLN: 'MLN',
  XREP: 'REP',
  ZUSD: 'USD',
  ZEUR: 'EUR',
  ZGBP: 'GBP',
  ZCAD: 'CAD',
  ZJPY: 'JPY',
  ZAUD: 'AUD',
  ZCHF: 'CHF',
};

export function krakenAsset(code: string): string {
  const upper = String(code || '').toUpperCase();
  const [base, ...suffix] = upper.split('.');
  const mapped = KRAKEN_ASSETS[base] ?? base;
  return suffix.length > 0 ? `${mapped}.${suffix.join('.')}` : mapped;
}

/**
 * Splits a Kraken pair in any of its three spellings - websocket "XBT/USD",
 * legacy "XXBTZUSD" and altname "XBTUSD" - into normalized base/quote
 * tickers. Returns null when no known quote suffix matches.
 */
export function krakenPairParts(pair: string): { base: string; quote: string } | null {
  const upper = String(pair || '').toUpperCase();
  if (upper.includes('/')) {
    const [b, q] = upper.split('/');
    return b && q ? { base: krakenAsset(b), quote: krakenAsset(q) } : null;
  }
  if (upper.length === 8 && /^[XZ]/.test(upper) && /^[XZ]/.test(upper.slice(4)) && KRAKEN_ASSETS[upper.slice(4)] !== undefined) {
    return { base: krakenAsset(upper.slice(0, 4)), quote: krakenAsset(upper.slice(4)) };
  }
  for (const quote of ['USDT', 'USDC', 'ZUSD', 'ZEUR', 'ZGBP', 'ZCAD', 'ZJPY', 'USD', 'EUR', 'GBP', 'CAD', 'JPY', 'XBT', 'ETH']) {
    if (upper.length > quote.length && upper.endsWith(quote)) {
      return { base: krakenAsset(upper.slice(0, upper.length - quote.length)), quote: krakenAsset(quote) };
    }
  }
  return null;
}

/** The probe key name used to learn whether a key may withdraw. No such key exists by construction. */
export const KRAKEN_WITHDRAW_PROBE_KEY = '__wlct_permission_probe_no_such_key__';

/**
 * Kraken Spot REST API, read side.
 *
 * Authentication: `API-Sign = base64(HMAC_SHA512(base64decode(secret), uriPath || SHA256(nonce + postData)))`,
 * where `||` is byte concatenation of the path and the raw SHA-256 digest. The
 * nonce must strictly increase per key; this provider derives it from
 * microsecond wall time and never reuses one inside the process.
 *
 * Kraken has no spot sandbox, so only LIVE is supported. Kraken exposes no
 * endpoint that lists a key's permissions, so {@link getAccountMetadata}
 * PROBES them with two calls that cannot move funds or place an order:
 * `WithdrawInfo` for a withdrawal key that does not exist (answers
 * "Permission denied" only when the key lacks withdraw rights) and `AddOrder`
 * with `validate=true` (validated, never submitted). A probe that returns
 * anything other than a clean permission refusal is treated as "has the
 * permission" - fail closed, so a key we cannot prove safe is refused.
 */
export class KrakenProvider extends BaseExchangeProvider {
  readonly venue = ExchangeVenue.KRAKEN;
  readonly displayName: string;
  readonly supportedEnvironments: ExchangeEnvironment[] = [ExchangeEnvironment.LIVE];
  readonly supportedCapabilities: ExchangeCapability[] = [
    ExchangeCapability.SPOT,
    ExchangeCapability.MARGIN,
    ExchangeCapability.MARKET_DATA,
    ExchangeCapability.BALANCES,
    ExchangeCapability.POSITIONS,
    ExchangeCapability.ORDERS,
    ExchangeCapability.TRADES,
  ];

  private lastNonce = 0n;

  constructor(
    private readonly urls: { liveRest: string; liveWs: string },
    displayName = 'Kraken',
  ) {
    super();
    this.displayName = displayName;
  }

  protected getLiveRestUrl(): string {
    return this.urls.liveRest;
  }
  protected getTestnetRestUrl(): string {
    return this.urls.liveRest;
  }
  protected getSandboxRestUrl(): string {
    return this.urls.liveRest;
  }
  protected getLiveWsUrl(): string {
    return this.urls.liveWs;
  }
  protected getTestnetWsUrl(): string {
    return this.urls.liveWs;
  }
  protected getSandboxWsUrl(): string {
    return this.urls.liveWs;
  }

  /** Exposed for tests: the exact Kraken signature. */
  static sign(secretBase64: string, uriPath: string, nonce: string, postData: string): string {
    const digest = crypto.createHash('sha256').update(nonce + postData).digest();
    return crypto
      .createHmac('sha512', Buffer.from(secretBase64, 'base64'))
      .update(Buffer.concat([Buffer.from(uriPath, 'utf8'), digest]))
      .digest('base64');
  }

  private nextNonce(): string {
    const candidate = BigInt(Date.now()) * 1000n;
    this.lastNonce = candidate > this.lastNonce ? candidate : this.lastNonce + 1n;
    return this.lastNonce.toString();
  }

  private assertLive(context: ExchangeProviderContext): void {
    if (context.environment !== ExchangeEnvironment.LIVE) {
      throw new ExchangeProviderError(
        ExchangeProviderErrorCode.NOT_SUPPORTED,
        'Kraken has no spot sandbox or testnet; only LIVE accounts can be connected',
        context.venue,
        context.environment,
        false,
      );
    }
  }

  private classify(context: ExchangeProviderContext, errors: string[]): ExchangeProviderError {
    const joined = errors.join('; ').slice(0, 300);
    const has = (needle: string) => errors.some((e) => e.includes(needle));
    if (has('EAPI:Invalid key') || has('EAPI:Invalid signature')) {
      return new ExchangeProviderError(ExchangeProviderErrorCode.AUTH_FAILED, `Kraken: ${joined}`, context.venue, context.environment, false);
    }
    if (has('EAPI:Invalid nonce')) {
      return new ExchangeProviderError(ExchangeProviderErrorCode.CLOCK_DRIFT, `Kraken: ${joined}`, context.venue, context.environment, true, 1000);
    }
    if (has('EGeneral:Permission denied')) {
      return new ExchangeProviderError(ExchangeProviderErrorCode.PERMISSION_DENIED, `Kraken: ${joined}`, context.venue, context.environment, false);
    }
    if (has('Rate limit exceeded') || has('EGeneral:Too many requests')) {
      return new ExchangeProviderError(ExchangeProviderErrorCode.RATE_LIMITED, `Kraken: ${joined}`, context.venue, context.environment, true, 2000);
    }
    if (has('EService:Unavailable') || has('EService:Busy') || has('EService:Market in cancel_only mode')) {
      return new ExchangeProviderError(ExchangeProviderErrorCode.SERVER_ERROR, `Kraken: ${joined}`, context.venue, context.environment, true, 2000);
    }
    if (has('EQuery:Unknown asset pair')) {
      return new ExchangeProviderError(ExchangeProviderErrorCode.SYMBOL_NOT_FOUND, `Kraken: ${joined}`, context.venue, context.environment, false);
    }
    return new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, `Kraken: ${joined}`, context.venue, context.environment, false);
  }

  private unwrap(context: ExchangeProviderContext, data: any): any {
    if (!data || typeof data !== 'object') {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, 'Kraken returned a non-JSON body', context.venue, context.environment, true);
    }
    const errors: string[] = Array.isArray(data.error) ? data.error.map(String) : [];
    if (errors.length > 0) throw this.classify(context, errors);
    return data.result ?? {};
  }

  private async publicGet(context: ExchangeProviderContext, path: string, query = ''): Promise<any> {
    this.assertLive(context);
    try {
      return this.unwrap(context, await this.httpGet(`${this.getLiveRestUrl()}${path}${query ? `?${query}` : ''}`));
    } catch (e: any) {
      throw this.normalizeError(e, context.venue, context.environment);
    }
  }

  private async privatePost(context: ExchangeProviderContext, path: string, params: Record<string, string> = {}): Promise<any> {
    this.assertLive(context);
    this.requireCredentials(context);
    const nonce = this.nextNonce();
    const postData = new URLSearchParams({ nonce, ...params }).toString();
    const signature = KrakenProvider.sign(context.credentials.apiSecret, path, nonce, postData);
    try {
      const data = await this.httpRequest({
        method: 'POST',
        url: `${this.getLiveRestUrl()}${path}`,
        headers: {
          'API-Key': context.credentials.apiKey,
          'API-Sign': signature,
          'Content-Type': 'application/x-www-form-urlencoded; charset=utf-8',
        },
        body: postData,
      });
      return this.unwrap(context, data);
    } catch (e: any) {
      throw this.normalizeError(e, context.venue, context.environment);
    }
  }

  async getServerTime(context: ExchangeProviderContext): Promise<ExchangeServerTime> {
    const result = await this.publicGet(context, '/0/public/Time');
    const seconds = Number(result?.unixtime);
    if (!Number.isFinite(seconds) || seconds <= 0) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, 'Kraken server time missing from response', context.venue, context.environment, true);
    }
    // Kraken's clock has one-second resolution; drift below a second is noise.
    return this.serverTimeFromMs(seconds * 1000);
  }

  async testConnectivity(context: ExchangeProviderContext): Promise<ExchangeConnectivityResult> {
    return this.connectivityFromMetadata(context);
  }

  /** true = the probe proved the permission is ABSENT; false = present or unprovable. */
  private async probeRefused(context: ExchangeProviderContext, path: string, params: Record<string, string>): Promise<boolean> {
    try {
      await this.privatePost(context, path, params);
      return false;
    } catch (e: any) {
      if (e instanceof ExchangeProviderError && e.code === ExchangeProviderErrorCode.PERMISSION_DENIED) return true;
      if (e instanceof ExchangeProviderError && (e.code === ExchangeProviderErrorCode.AUTH_FAILED || e.code === ExchangeProviderErrorCode.RATE_LIMITED)) throw e;
      return false;
    }
  }

  async getAccountMetadata(context: ExchangeProviderContext): Promise<ExchangeAccountMetadata> {
    // The read permission is proven by an ordinary balance read (throws on a bad key).
    await this.privatePost(context, '/0/private/Balance');
    const withdrawRefused = await this.probeRefused(context, '/0/private/WithdrawInfo', {
      asset: 'XBT',
      key: KRAKEN_WITHDRAW_PROBE_KEY,
      amount: '0.0001',
    });
    const tradeRefused = await this.probeRefused(context, '/0/private/AddOrder', {
      pair: 'XBTUSD',
      type: 'buy',
      ordertype: 'limit',
      price: '1',
      volume: '0.0001',
      validate: 'true',
    });
    const permissions = ['query_funds'];
    if (!tradeRefused) permissions.push('create_modify_orders');
    if (!withdrawRefused) permissions.push('withdraw_funds_or_unproven');
    return {
      accountId: context.accountId,
      venue: context.venue,
      environment: context.environment,
      isSandbox: context.isSandbox,
      canTrade: !tradeRefused,
      canRead: true,
      canWithdraw: !withdrawRefused,
      ipRestricted: false,
      permissions,
      uid: null,
      email: null,
    };
  }

  async getCapabilities(context: ExchangeProviderContext): Promise<ExchangeCapabilityDiscovery> {
    return {
      venue: context.venue,
      environment: context.environment,
      capabilities: this.supportedCapabilities,
      supportedOrderTypes: [ExchangeOrderType.MARKET, ExchangeOrderType.LIMIT, ExchangeOrderType.STOP, ExchangeOrderType.STOP_LIMIT, ExchangeOrderType.TAKE_PROFIT, ExchangeOrderType.TAKE_PROFIT_LIMIT],
      supportedEnvironments: this.supportedEnvironments,
      apiVersion: '0',
      restAvailable: true,
      websocketAvailable: true,
      rateLimitModel: 'TOKEN_BUCKET',
      authenticationModel: 'HMAC_SHA512',
      symbolFormat: 'XBTUSD',
      timestamp: new Date().toISOString(),
    };
  }

  async getBalances(context: ExchangeProviderContext): Promise<ExchangeBalance[]> {
    const result = await this.privatePost(context, '/0/private/BalanceEx');
    const timestampMicros = nowMicros();
    return Object.entries(result as Record<string, any>)
      .map(([code, row]) => {
        const total = dec(row?.balance);
        const locked = dec(row?.hold_trade);
        let free = subtractDecimalStrings(total, locked);
        if (free.startsWith('-')) free = '0';
        return {
          asset: krakenAsset(code),
          free,
          locked,
          total,
          providerReference: code,
          timestampMicros,
          source: 'REST',
          isSimulated: false,
        };
      })
      .filter((b) => !/^0(\.0+)?$/.test(b.total) || !/^0(\.0+)?$/.test(b.locked));
  }

  async getPositions(context: ExchangeProviderContext): Promise<ExchangePosition[]> {
    const result = await this.privatePost(context, '/0/private/OpenPositions', { docalcs: 'true' });
    return Object.entries(result as Record<string, any>).map(([posId, p]) => {
      const vol = dec(p?.vol);
      const closed = dec(p?.vol_closed);
      const open = subtractDecimalStrings(vol, closed);
      return {
        providerPositionId: posId,
        symbol: this.canonicalPair(String(p?.pair ?? '')),
        exchangeSymbol: String(p?.pair ?? ''),
        side: p?.type === 'sell' ? ExchangePositionSide.SHORT : ExchangePositionSide.LONG,
        quantity: open.startsWith('-') ? '0' : open,
        entryPrice: null,
        markPrice: null,
        liquidationPrice: null,
        leverage: decOrNull(p?.leverage),
        unrealizedPnl: decOrNull(p?.net),
        realizedPnl: null,
        timestampMicros: secondsToMicros(p?.time) ?? nowMicros(),
        isSimulated: false,
      };
    });
  }

  async getOpenOrders(context: ExchangeProviderContext, symbol?: string): Promise<ExchangeOrder[]> {
    const result = await this.privatePost(context, '/0/private/OpenOrders');
    const orders = Object.entries((result?.open ?? {}) as Record<string, any>).map(([txid, o]) => this.mapOrder(txid, o));
    return symbol ? orders.filter((o) => o.symbol === symbol.toUpperCase() || o.exchangeSymbol === symbol.toUpperCase()) : orders;
  }

  async getOrderHistory(context: ExchangeProviderContext, symbol?: string, limit = 50): Promise<ExchangeOrder[]> {
    const result = await this.privatePost(context, '/0/private/ClosedOrders');
    const orders = Object.entries((result?.closed ?? {}) as Record<string, any>)
      .map(([txid, o]) => this.mapOrder(txid, o))
      .filter((o) => !symbol || o.symbol === symbol.toUpperCase() || o.exchangeSymbol === symbol.toUpperCase())
      .sort((a, b) => Number(BigInt(b.createdAtMicros ?? '0') - BigInt(a.createdAtMicros ?? '0')));
    return orders.slice(0, limit);
  }

  async getTradeHistory(context: ExchangeProviderContext, symbol?: string, limit = 50): Promise<ExchangeFill[]> {
    const result = await this.privatePost(context, '/0/private/TradesHistory');
    return Object.entries((result?.trades ?? {}) as Record<string, any>)
      .map(([tradeId, t]) => ({
        providerTradeId: tradeId,
        providerOrderId: t?.ordertxid ? String(t.ordertxid) : null,
        clientOrderId: null,
        symbol: this.canonicalPair(String(t?.pair ?? '')),
        side: t?.type === 'sell' ? ExchangeOrderSide.SELL : ExchangeOrderSide.BUY,
        price: dec(t?.price),
        quantity: dec(t?.vol),
        quoteQuantity: decOrNull(t?.cost),
        fee: decOrNull(t?.fee),
        feeCurrency: null,
        isMaker: typeof t?.maker === 'boolean' ? t.maker : null,
        timestampMicros: secondsToMicros(t?.time) ?? nowMicros(),
        isSimulated: false,
      }))
      .filter((f) => !symbol || f.symbol === symbol.toUpperCase())
      .sort((a, b) => Number(BigInt(b.timestampMicros) - BigInt(a.timestampMicros)))
      .slice(0, limit);
  }

  async getSymbols(context: ExchangeProviderContext): Promise<ExchangeSymbol[]> {
    const result = await this.publicGet(context, '/0/public/AssetPairs');
    return Object.entries(result as Record<string, any>)
      .filter(([, p]) => (p?.status ?? 'online') === 'online' && typeof p?.wsname === 'string')
      .map(([pairKey, p]) => {
        const [wsBase, wsQuote] = String(p.wsname).split('/');
        const base = krakenAsset(wsBase);
        const quote = krakenAsset(wsQuote);
        const pairDecimals = Number(p.pair_decimals ?? 8);
        const lotDecimals = Number(p.lot_decimals ?? 8);
        return {
          canonicalSymbol: `${base}-${quote}`,
          exchangeSymbol: String(p.altname ?? pairKey),
          baseAsset: base,
          quoteAsset: quote,
          contractType: 'SPOT',
          tickSize: isDecimalString(p.tick_size) ? p.tick_size : lotStep(pairDecimals),
          quantityStep: lotStep(lotDecimals),
          minQuantity: decOrNull(p.ordermin),
          maxQuantity: null,
          minNotional: decOrNull(p.costmin),
          maxNotional: null,
          pricePrecision: pairDecimals,
          quantityPrecision: lotDecimals,
          minLeverage: null,
          maxLeverage: Array.isArray(p.leverage_buy) && p.leverage_buy.length > 0 ? Math.max(...p.leverage_buy.map(Number)) : null,
          isTradeable: true,
        };
      });
  }

  /** "XXBTZUSD" / "XBTUSD" / "XBT/USD" -> "BTC-USD" using the legacy asset table. */
  canonicalPair(pair: string): string {
    const parts = krakenPairParts(pair);
    return parts ? `${parts.base}-${parts.quote}` : pair.toUpperCase();
  }

  private mapOrder(txid: string, o: any): ExchangeOrder {
    const descr = o?.descr ?? {};
    const ordertype = String(descr.ordertype ?? '');
    const typeMap: Record<string, ExchangeOrderType> = {
      market: ExchangeOrderType.MARKET,
      limit: ExchangeOrderType.LIMIT,
      'stop-loss': ExchangeOrderType.STOP,
      'stop-loss-limit': ExchangeOrderType.STOP_LIMIT,
      'take-profit': ExchangeOrderType.TAKE_PROFIT,
      'take-profit-limit': ExchangeOrderType.TAKE_PROFIT_LIMIT,
    };
    const type = typeMap[ordertype] ?? ExchangeOrderType.LIMIT;
    const isStopFamily = type === ExchangeOrderType.STOP || type === ExchangeOrderType.STOP_LIMIT || type === ExchangeOrderType.TAKE_PROFIT || type === ExchangeOrderType.TAKE_PROFIT_LIMIT;
    const pair = String(descr.pair ?? '');
    const volExec = dec(o?.vol_exec);
    return {
      clientOrderId: o?.cl_ord_id ? String(o.cl_ord_id) : o?.userref ? String(o.userref) : txid,
      providerOrderId: txid,
      symbol: this.canonicalPair(pair),
      exchangeSymbol: pair,
      side: descr.type === 'sell' ? ExchangeOrderSide.SELL : ExchangeOrderSide.BUY,
      type,
      status: KrakenProvider.mapOrderStatus(String(o?.status ?? ''), volExec),
      providerRawStatus: o?.status ? String(o.status) : null,
      quantity: dec(o?.vol),
      price: type === ExchangeOrderType.MARKET ? null : isStopFamily ? decOrNull(descr.price2) : decOrNull(descr.price),
      stopPrice: isStopFamily ? decOrNull(descr.price) : null,
      filledQuantity: volExec,
      averagePrice: isDecimalString(o?.price) && !/^0(\.0+)?$/.test(o.price) ? o.price : null,
      fee: decOrNull(o?.fee),
      feeCurrency: null,
      createdAtMicros: secondsToMicros(o?.opentm),
      updatedAtMicros: secondsToMicros(o?.closetm) ?? secondsToMicros(o?.opentm),
      isSimulated: false,
    };
  }

  static mapOrderStatus(status: string, volExec = '0'): ExchangeOrderStatus {
    const executed = !/^0(\.0+)?$/.test(volExec);
    switch (status) {
      case 'pending':
      case 'open':
        return executed ? ExchangeOrderStatus.PARTIALLY_FILLED : ExchangeOrderStatus.NEW;
      case 'closed':
        return ExchangeOrderStatus.FILLED;
      case 'canceled':
        return ExchangeOrderStatus.CANCELED;
      case 'expired':
        return ExchangeOrderStatus.EXPIRED;
      default:
        return ExchangeOrderStatus.NEW;
    }
  }
}

function lotStep(decimals: number): string {
  if (!Number.isInteger(decimals) || decimals <= 0) return '1';
  return `0.${'0'.repeat(decimals - 1)}1`;
}

// # Implements signed V5 live REST/account/symbol/health probes when live trading enabled
import * as crypto from 'crypto';
import {
  ExchangeVenue,
  ExchangeEnvironment,
  ExchangeCapability,
  ExchangeOrderType,
  ExchangeBalance,
  ExchangePosition,
  ExchangeOrder,
  ExchangeFill,
  ExchangeSymbol,
  ExchangeCapabilityDiscovery,
  ExchangePositionSide,
  ExchangeOrderStatus,
  ExchangeOrderSide,
  ExchangeConnectivityResult,
} from '../exchange.types';
import {
  ExchangeProviderError,
  ExchangeProviderErrorCode,
  ExchangeProviderContext,
  ExchangeServerTime,
  ExchangeAccountMetadata,
} from '../exchange-provider.interface';
import {
  BaseExchangeProvider,
  addDecimalStrings,
  absDecimalString,
  signOfDecimalString,
  isDecimalString,
  msToMicros,
  nowMicros,
  precisionOfStep,
} from '../base-exchange-provider';

function dec(value: unknown): string {
  return isDecimalString(value) ? value : '0';
}

function decOrNull(value: unknown): string | null {
  return isDecimalString(value) ? value : null;
}

/** "BTC-USDT-SWAP" -> "BTC-USDT"; spot ids are already canonical. */
export function okxCanonical(instId: string): string {
  const parts = String(instId || '').toUpperCase().split('-');
  return parts.length >= 2 ? `${parts[0]}-${parts[1]}` : String(instId || '').toUpperCase();
}

function instTypeOf(instId: string): 'SPOT' | 'SWAP' | 'FUTURES' | 'OPTION' {
  const parts = String(instId).toUpperCase().split('-');
  if (parts.length === 2) return 'SPOT';
  if (parts[2] === 'SWAP') return 'SWAP';
  if (parts.length >= 5) return 'OPTION';
  return 'FUTURES';
}

/**
 * OKX V5 API, read side.
 *
 * Authentication: `OK-ACCESS-SIGN = base64(HMAC_SHA256(secret, timestamp + METHOD + requestPath + body))`
 * where `requestPath` includes the query string and `timestamp` is ISO-8601 with
 * milliseconds; the passphrase chosen at key creation rides in
 * `OK-ACCESS-PASSPHRASE`. OKX's demo trading uses the same host with
 * `x-simulated-trading: 1`, so TESTNET/SANDBOX differ from LIVE by that header,
 * which is added for every non-LIVE environment - a demo key sent without it
 * is rejected by the venue, and a live key sent with it is too.
 */
export class OkxProvider extends BaseExchangeProvider {
  readonly venue = ExchangeVenue.OKX;
  readonly displayName: string;
  readonly supportedEnvironments: ExchangeEnvironment[] = [ExchangeEnvironment.LIVE, ExchangeEnvironment.TESTNET, ExchangeEnvironment.SANDBOX];
  readonly supportedCapabilities: ExchangeCapability[] = [
    ExchangeCapability.SPOT,
    ExchangeCapability.MARGIN,
    ExchangeCapability.FUTURES,
    ExchangeCapability.PERPETUALS,
    ExchangeCapability.MARKET_DATA,
    ExchangeCapability.BALANCES,
    ExchangeCapability.POSITIONS,
    ExchangeCapability.ORDERS,
    ExchangeCapability.TRADES,
    ExchangeCapability.TESTNET,
  ];

  constructor(
    private readonly urls: { liveRest: string; testnetRest: string; sandboxRest: string; liveWs: string; testnetWs: string; sandboxWs: string },
    displayName = 'OKX',
  ) {
    super();
    this.displayName = displayName;
  }

  protected getLiveRestUrl(): string {
    return this.urls.liveRest;
  }
  protected getTestnetRestUrl(): string {
    return this.urls.testnetRest;
  }
  protected getSandboxRestUrl(): string {
    return this.urls.sandboxRest;
  }
  protected getLiveWsUrl(): string {
    return this.urls.liveWs;
  }
  protected getTestnetWsUrl(): string {
    return this.urls.testnetWs;
  }
  protected getSandboxWsUrl(): string {
    return this.urls.sandboxWs;
  }

  /** Exposed for tests: the exact V5 prehash signature. */
  static sign(secret: string, timestamp: string, method: string, requestPath: string, body = ''): string {
    return crypto.createHmac('sha256', secret).update(timestamp + method.toUpperCase() + requestPath + body).digest('base64');
  }

  private buildQuery(params: Record<string, string | number | undefined>): string {
    return Object.entries(params)
      .filter(([, v]) => v !== undefined && v !== '')
      .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
      .join('&');
  }

  private demoHeaders(context: ExchangeProviderContext): Record<string, string> {
    return context.environment === ExchangeEnvironment.LIVE ? {} : { 'x-simulated-trading': '1' };
  }

  private unwrap(context: ExchangeProviderContext, data: any): any[] {
    if (!data || typeof data !== 'object') {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, 'OKX returned a non-JSON body', context.venue, context.environment, true);
    }
    const code = String(data.code);
    if (code === '0') return Array.isArray(data.data) ? data.data : [];
    const message = `OKX code ${code}: ${String(data.msg ?? '').slice(0, 200)}`;
    if (['50111', '50113', '50105', '50100', '50101', '50114'].includes(code)) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.AUTH_FAILED, message, context.venue, context.environment, false);
    }
    if (['50110', '50120', '50121'].includes(code)) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.PERMISSION_DENIED, message, context.venue, context.environment, false);
    }
    if (['50102', '50112'].includes(code)) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.CLOCK_DRIFT, message, context.venue, context.environment, true, 1000);
    }
    if (['50011', '50061'].includes(code)) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.RATE_LIMITED, message, context.venue, context.environment, true, 1000);
    }
    if (['50001', '50004', '50013', '50026'].includes(code)) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.SERVER_ERROR, message, context.venue, context.environment, true, 1000);
    }
    throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, message, context.venue, context.environment, false);
  }

  private async publicGet(context: ExchangeProviderContext, path: string, params: Record<string, string | number | undefined> = {}): Promise<any[]> {
    const query = this.buildQuery(params);
    const url = `${this.getRestBaseUrlForEnv(context.environment)}${path}${query ? `?${query}` : ''}`;
    try {
      return this.unwrap(context, await this.httpGet(url, this.demoHeaders(context)));
    } catch (e: any) {
      throw this.normalizeError(e, context.venue, context.environment);
    }
  }

  private async privateGet(context: ExchangeProviderContext, path: string, params: Record<string, string | number | undefined> = {}): Promise<any[]> {
    this.requireCredentials(context, true);
    const query = this.buildQuery(params);
    const requestPath = `${path}${query ? `?${query}` : ''}`;
    const timestamp = new Date().toISOString();
    const signature = OkxProvider.sign(context.credentials.apiSecret, timestamp, 'GET', requestPath);
    try {
      const data = await this.httpGet(`${this.getRestBaseUrlForEnv(context.environment)}${requestPath}`, {
        'OK-ACCESS-KEY': context.credentials.apiKey,
        'OK-ACCESS-SIGN': signature,
        'OK-ACCESS-TIMESTAMP': timestamp,
        'OK-ACCESS-PASSPHRASE': context.credentials.passphrase as string,
        ...this.demoHeaders(context),
      });
      return this.unwrap(context, data);
    } catch (e: any) {
      throw this.normalizeError(e, context.venue, context.environment);
    }
  }

  async getServerTime(context: ExchangeProviderContext): Promise<ExchangeServerTime> {
    const data = await this.publicGet(context, '/api/v5/public/time');
    const ts = Number(data[0]?.ts);
    if (!Number.isFinite(ts) || ts <= 0) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, 'OKX server time missing from response', context.venue, context.environment, true);
    }
    return this.serverTimeFromMs(ts);
  }

  async testConnectivity(context: ExchangeProviderContext): Promise<ExchangeConnectivityResult> {
    return this.connectivityFromMetadata(context);
  }

  async getAccountMetadata(context: ExchangeProviderContext): Promise<ExchangeAccountMetadata> {
    const data = await this.privateGet(context, '/api/v5/account/config');
    const config = data[0] ?? {};
    const perms = String(config.perm ?? '')
      .split(',')
      .map((p: string) => p.trim())
      .filter(Boolean);
    const ip = String(config.ip ?? '').trim();
    return {
      accountId: context.accountId,
      venue: context.venue,
      environment: context.environment,
      isSandbox: context.isSandbox,
      canTrade: perms.includes('trade'),
      canRead: perms.includes('read_only') || perms.includes('trade'),
      canWithdraw: perms.includes('withdraw'),
      ipRestricted: ip.length > 0,
      permissions: perms,
      uid: config.uid ? String(config.uid) : null,
      email: null,
    };
  }

  async getCapabilities(context: ExchangeProviderContext): Promise<ExchangeCapabilityDiscovery> {
    return {
      venue: context.venue,
      environment: context.environment,
      capabilities: this.supportedCapabilities,
      supportedOrderTypes: [ExchangeOrderType.MARKET, ExchangeOrderType.LIMIT, ExchangeOrderType.LIMIT_MAKER, ExchangeOrderType.STOP, ExchangeOrderType.STOP_LIMIT],
      supportedEnvironments: this.supportedEnvironments,
      apiVersion: 'v5',
      restAvailable: true,
      websocketAvailable: true,
      rateLimitModel: 'REQUEST_COUNT',
      authenticationModel: 'HMAC_SHA256_PASSPHRASE',
      symbolFormat: 'BTC-USDT',
      timestamp: new Date().toISOString(),
    };
  }

  async getBalances(context: ExchangeProviderContext): Promise<ExchangeBalance[]> {
    const data = await this.privateGet(context, '/api/v5/account/balance');
    const details: any[] = Array.isArray(data[0]?.details) ? data[0].details : [];
    const timestampMicros = msToMicros(data[0]?.uTime) ?? nowMicros();
    return details
      .map((d) => {
        const free = dec(d.availBal);
        const locked = dec(d.frozenBal);
        const total = isDecimalString(d.cashBal) ? d.cashBal : addDecimalStrings(free, locked);
        return {
          asset: String(d.ccy),
          free,
          locked,
          total,
          providerReference: null,
          timestampMicros,
          source: 'REST',
          isSimulated: context.isSandbox,
        };
      })
      .filter((b) => b.total !== '0' || b.locked !== '0');
  }

  async getPositions(context: ExchangeProviderContext): Promise<ExchangePosition[]> {
    const data = await this.privateGet(context, '/api/v5/account/positions');
    return data
      .filter((p) => isDecimalString(p.pos) && signOfDecimalString(p.pos) !== 0)
      .map((p) => {
        let side: ExchangePositionSide;
        if (p.posSide === 'long') side = ExchangePositionSide.LONG;
        else if (p.posSide === 'short') side = ExchangePositionSide.SHORT;
        else side = signOfDecimalString(p.pos) > 0 ? ExchangePositionSide.LONG : ExchangePositionSide.SHORT;
        return {
          providerPositionId: p.posId ? String(p.posId) : null,
          symbol: okxCanonical(p.instId),
          exchangeSymbol: String(p.instId),
          side,
          quantity: absDecimalString(p.pos),
          entryPrice: decOrNull(p.avgPx),
          markPrice: decOrNull(p.markPx),
          liquidationPrice: decOrNull(p.liqPx),
          leverage: decOrNull(p.lever),
          unrealizedPnl: decOrNull(p.upl),
          realizedPnl: decOrNull(p.realizedPnl),
          timestampMicros: msToMicros(p.uTime) ?? nowMicros(),
          isSimulated: context.isSandbox,
        };
      });
  }

  async getOpenOrders(context: ExchangeProviderContext, symbol?: string): Promise<ExchangeOrder[]> {
    const params: Record<string, string | number | undefined> = { limit: 100 };
    if (symbol) {
      params.instId = symbol.toUpperCase();
      params.instType = instTypeOf(symbol);
    }
    const data = await this.privateGet(context, '/api/v5/trade/orders-pending', params);
    return data.map((o) => this.mapOrder(context, o));
  }

  async getOrderHistory(context: ExchangeProviderContext, symbol?: string, limit = 50): Promise<ExchangeOrder[]> {
    const instTypes: Array<'SPOT' | 'SWAP' | 'FUTURES' | 'OPTION'> = symbol ? [instTypeOf(symbol)] : ['SPOT', 'SWAP'];
    const rows: any[] = [];
    for (const instType of instTypes) {
      rows.push(...(await this.privateGet(context, '/api/v5/trade/orders-history', { instType, instId: symbol?.toUpperCase(), limit: Math.min(limit, 100) })));
    }
    return rows
      .map((o) => this.mapOrder(context, o))
      .sort((a, b) => Number(BigInt(b.createdAtMicros ?? '0') - BigInt(a.createdAtMicros ?? '0')))
      .slice(0, limit);
  }

  async getTradeHistory(context: ExchangeProviderContext, symbol?: string, limit = 50): Promise<ExchangeFill[]> {
    const params: Record<string, string | number | undefined> = { limit: Math.min(limit, 100) };
    if (symbol) {
      params.instId = symbol.toUpperCase();
      params.instType = instTypeOf(symbol);
    }
    const data = await this.privateGet(context, '/api/v5/trade/fills', params);
    return data.slice(0, limit).map((t) => ({
      providerTradeId: String(t.tradeId),
      providerOrderId: t.ordId ? String(t.ordId) : null,
      clientOrderId: t.clOrdId ? String(t.clOrdId) : null,
      symbol: okxCanonical(t.instId),
      side: t.side === 'buy' ? ExchangeOrderSide.BUY : ExchangeOrderSide.SELL,
      price: dec(t.fillPx),
      quantity: dec(t.fillSz),
      quoteQuantity: null,
      // OKX reports fees as negative numbers (a charge) and rebates as positive;
      // the platform's convention is a positive fee paid, so the sign flips.
      fee: isDecimalString(t.fee) ? (t.fee.startsWith('-') ? t.fee.slice(1) : t.fee === '0' ? '0' : `-${t.fee}`) : null,
      feeCurrency: t.feeCcy ? String(t.feeCcy) : null,
      isMaker: t.execType === 'M' ? true : t.execType === 'T' ? false : null,
      timestampMicros: msToMicros(t.ts) ?? nowMicros(),
      isSimulated: context.isSandbox,
    }));
  }

  async getSymbols(context: ExchangeProviderContext): Promise<ExchangeSymbol[]> {
    const data = await this.publicGet(context, '/api/v5/public/instruments', { instType: 'SPOT' });
    return data
      .filter((s) => s.state === 'live')
      .map((s) => ({
        canonicalSymbol: `${s.baseCcy}-${s.quoteCcy}`,
        exchangeSymbol: String(s.instId),
        baseAsset: String(s.baseCcy),
        quoteAsset: String(s.quoteCcy),
        contractType: 'SPOT',
        tickSize: String(s.tickSz),
        quantityStep: String(s.lotSz),
        minQuantity: decOrNull(s.minSz),
        maxQuantity: decOrNull(s.maxLmtSz),
        minNotional: null,
        maxNotional: null,
        pricePrecision: precisionOfStep(String(s.tickSz)),
        quantityPrecision: precisionOfStep(String(s.lotSz)),
        minLeverage: null,
        maxLeverage: null,
        isTradeable: true,
      }));
  }

  private mapOrder(context: ExchangeProviderContext, o: any): ExchangeOrder {
    const ordType = String(o.ordType);
    let type: ExchangeOrderType;
    if (ordType === 'market') type = ExchangeOrderType.MARKET;
    else if (ordType === 'post_only') type = ExchangeOrderType.LIMIT_MAKER;
    else type = ExchangeOrderType.LIMIT;
    const fee = isDecimalString(o.fee) ? (o.fee.startsWith('-') ? o.fee.slice(1) : o.fee === '0' ? '0' : `-${o.fee}`) : null;
    return {
      clientOrderId: o.clOrdId ? String(o.clOrdId) : String(o.ordId),
      providerOrderId: o.ordId ? String(o.ordId) : null,
      symbol: okxCanonical(o.instId),
      exchangeSymbol: String(o.instId),
      side: o.side === 'buy' ? ExchangeOrderSide.BUY : ExchangeOrderSide.SELL,
      type,
      status: OkxProvider.mapOrderStatus(String(o.state)),
      providerRawStatus: o.state ? String(o.state) : null,
      quantity: dec(o.sz),
      price: type === ExchangeOrderType.MARKET ? null : decOrNull(o.px),
      stopPrice: null,
      filledQuantity: dec(o.accFillSz),
      averagePrice: decOrNull(o.avgPx),
      fee,
      feeCurrency: o.feeCcy ? String(o.feeCcy) : null,
      createdAtMicros: msToMicros(o.cTime),
      updatedAtMicros: msToMicros(o.uTime),
      isSimulated: context.isSandbox,
    };
  }

  static mapOrderStatus(state: string): ExchangeOrderStatus {
    switch (state) {
      case 'live':
        return ExchangeOrderStatus.NEW;
      case 'partially_filled':
        return ExchangeOrderStatus.PARTIALLY_FILLED;
      case 'filled':
        return ExchangeOrderStatus.FILLED;
      case 'canceled':
      case 'mmp_canceled':
        return ExchangeOrderStatus.CANCELED;
      default:
        return ExchangeOrderStatus.NEW;
    }
  }
}

