  ExchangeAccountMetadata,
} from '../exchange-provider.interface';
import {
  BaseExchangeProvider,
  subtractDecimalStrings,
  absDecimalString,
  isDecimalString,
  msToMicros,
  nowMicros,
  precisionOfStep,
  canonicalFromConcatenated,
} from '../base-exchange-provider';

/** Categories this provider reads. Spot plus USDT/USDC-settled linear contracts. */
type BybitCategory = 'spot' | 'linear';

const RECV_WINDOW = '5000';
const MAX_PAGES = 10;

function dec(value: unknown): string {
  return isDecimalString(value) ? value : '0';
}

function decOrNull(value: unknown): string | null {
  return isDecimalString(value) && value !== '' ? value : null;
}

/**
 * Bybit V5 unified API, read side: server time, key permissions, wallet,
 * positions, open orders, order history, executions and instruments.
 *
 * Authentication (V5): `X-BAPI-SIGN = hex(HMAC_SHA256(secret, timestamp + apiKey + recvWindow + queryString))`.
 * Every response is an envelope `{ retCode, retMsg, result }`; a non-zero
 * retCode is a venue refusal and is classified, never read as an empty list.
 * This provider places no orders - order transmission belongs to the execution
 * engine behind the live-mode gate.
 */
export class BybitProvider extends BaseExchangeProvider {
  readonly venue = ExchangeVenue.BYBIT;
  readonly displayName: string;
  readonly supportedEnvironments: ExchangeEnvironment[] = [ExchangeEnvironment.LIVE, ExchangeEnvironment.TESTNET, ExchangeEnvironment.SANDBOX];
  readonly supportedCapabilities: ExchangeCapability[] = [
    ExchangeCapability.SPOT,
    ExchangeCapability.PERPETUALS,
    ExchangeCapability.MARKET_DATA,
    ExchangeCapability.BALANCES,
    ExchangeCapability.POSITIONS,
    ExchangeCapability.ORDERS,
    ExchangeCapability.TRADES,
    ExchangeCapability.TESTNET,
  ];

  constructor(
    private readonly urls: { liveRest: string; testnetRest: string; sandboxRest: string; liveWs: string; testnetWs: string; sandboxWs: string },
    displayName = 'Bybit',
  ) {
    super();
    this.displayName = displayName;
  }

  protected getLiveRestUrl(): string {
    return this.urls.liveRest;
  }
  protected getTestnetRestUrl(): string {
    return this.urls.testnetRest;
  }
  protected getSandboxRestUrl(): string {
    return this.urls.sandboxRest;
  }
  protected getLiveWsUrl(): string {
    return this.urls.liveWs;
  }
  protected getTestnetWsUrl(): string {
    return this.urls.testnetWs;
  }
  protected getSandboxWsUrl(): string {
    return this.urls.sandboxWs;
  }

  /** Exposed for tests: the exact V5 signature over the canonical payload. */
  static sign(secret: string, timestamp: string, apiKey: string, recvWindow: string, queryString: string): string {
    return crypto.createHmac('sha256', secret).update(timestamp + apiKey + recvWindow + queryString).digest('hex');
  }

  private buildQuery(params: Record<string, string | number | undefined>): string {
    return Object.entries(params)
      .filter(([, v]) => v !== undefined && v !== '')
      .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
      .join('&');
  }

  private unwrap(context: ExchangeProviderContext, data: any): any {
    if (!data || typeof data !== 'object') {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, 'Bybit returned a non-JSON body', context.venue, context.environment, true);
    }
    const code = Number(data.retCode);
    if (code === 0) return data.result ?? {};
    const message = `Bybit retCode ${data.retCode}: ${String(data.retMsg ?? '').slice(0, 200)}`;
    if ([10003, 10004, 33004, 10007].includes(code)) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.AUTH_FAILED, message, context.venue, context.environment, false);
    }
    if ([10005, 10010].includes(code)) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.PERMISSION_DENIED, message, context.venue, context.environment, false);
    }
    if (code === 10002) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.CLOCK_DRIFT, message, context.venue, context.environment, true, 1000);
    }
    if ([10006, 10018, 10429].includes(code)) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.RATE_LIMITED, message, context.venue, context.environment, true, 1000);
    }
    if (code === 10001) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.INVALID_ORDER, message, context.venue, context.environment, false);
    }
    if (code === 10016) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.SERVER_ERROR, message, context.venue, context.environment, true, 1000);
    }
    throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, message, context.venue, context.environment, false);
  }

  private async publicGet(context: ExchangeProviderContext, path: string, params: Record<string, string | number | undefined> = {}): Promise<any> {
    const query = this.buildQuery(params);
    const url = `${this.getRestBaseUrlForEnv(context.environment)}${path}${query ? `?${query}` : ''}`;
    try {
      return this.unwrap(context, await this.httpGet(url));
    } catch (e: any) {
      throw this.normalizeError(e, context.venue, context.environment);
    }
  }

  private async privateGet(context: ExchangeProviderContext, path: string, params: Record<string, string | number | undefined> = {}): Promise<any> {
    this.requireCredentials(context);
    const query = this.buildQuery(params);
    const timestamp = Date.now().toString();
    const signature = BybitProvider.sign(context.credentials.apiSecret, timestamp, context.credentials.apiKey, RECV_WINDOW, query);
    const url = `${this.getRestBaseUrlForEnv(context.environment)}${path}${query ? `?${query}` : ''}`;
    try {
      const data = await this.httpGet(url, {
        'X-BAPI-API-KEY': context.credentials.apiKey,
        'X-BAPI-TIMESTAMP': timestamp,
        'X-BAPI-RECV-WINDOW': RECV_WINDOW,
        'X-BAPI-SIGN': signature,
      });
      return this.unwrap(context, data);
    } catch (e: any) {
      throw this.normalizeError(e, context.venue, context.environment);
    }
  }

  /** Follows `nextPageCursor` up to MAX_PAGES pages, concatenating `result.list`. */
  private async privateList(context: ExchangeProviderContext, path: string, params: Record<string, string | number | undefined>, maxItems: number): Promise<any[]> {
    const rows: any[] = [];
    let cursor: string | undefined;
    for (let page = 0; page < MAX_PAGES && rows.length < maxItems; page += 1) {
      const result = await this.privateGet(context, path, { ...params, cursor });
      const list = Array.isArray(result?.list) ? result.list : [];
      rows.push(...list);
      cursor = typeof result?.nextPageCursor === 'string' && result.nextPageCursor !== '' ? result.nextPageCursor : undefined;
      if (!cursor || list.length === 0) break;
    }
    return rows.slice(0, maxItems);
  }

  async getServerTime(context: ExchangeProviderContext): Promise<ExchangeServerTime> {
    const result = await this.publicGet(context, '/v5/market/time');
    const nano = typeof result?.timeNano === 'string' && /^\d+$/.test(result.timeNano) ? BigInt(result.timeNano) : null;
    const seconds = Number(result?.timeSecond);
    const serverMs = nano !== null ? Number(nano / 1_000_000n) : seconds * 1000;
    if (!Number.isFinite(serverMs) || serverMs <= 0) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, 'Bybit server time missing from response', context.venue, context.environment, true);
    }
    return this.serverTimeFromMs(serverMs);
  }

  async testConnectivity(context: ExchangeProviderContext): Promise<ExchangeConnectivityResult> {
    return this.connectivityFromMetadata(context);
  }

  async getAccountMetadata(context: ExchangeProviderContext): Promise<ExchangeAccountMetadata> {
    const info = await this.privateGet(context, '/v5/user/query-api');
    const permissions: Record<string, string[]> = info?.permissions && typeof info.permissions === 'object' ? info.permissions : {};
    const flat = Object.entries(permissions).flatMap(([group, values]) => (Array.isArray(values) ? values.map((v) => `${group}:${v}`) : []));
    const readOnly = Number(info?.readOnly) === 1;
    const canWithdraw = (permissions['Wallet'] ?? []).some((p) => /withdraw/i.test(p));
    const canTrade =
      !readOnly &&
      ((permissions['Spot'] ?? []).includes('SpotTrade') ||
        (permissions['ContractTrade'] ?? []).length > 0 ||
        (permissions['Derivatives'] ?? []).length > 0 ||
        (permissions['Options'] ?? []).length > 0);
    const ips: string[] = Array.isArray(info?.ips) ? info.ips : [];
    return {
      accountId: context.accountId,
      venue: context.venue,
      environment: context.environment,
      isSandbox: context.isSandbox,
      canTrade,
      canRead: true,
      canWithdraw,
      ipRestricted: ips.length > 0 && !ips.includes('*'),
      permissions: flat,
      uid: info?.userID !== undefined && info?.userID !== null ? String(info.userID) : null,
      email: null,
    };
  }

  async getCapabilities(context: ExchangeProviderContext): Promise<ExchangeCapabilityDiscovery> {
    return {
      venue: context.venue,
      environment: context.environment,
      capabilities: this.supportedCapabilities,
      supportedOrderTypes: [ExchangeOrderType.MARKET, ExchangeOrderType.LIMIT, ExchangeOrderType.STOP, ExchangeOrderType.STOP_LIMIT],
      supportedEnvironments: this.supportedEnvironments,
      apiVersion: 'v5',
      restAvailable: true,
      websocketAvailable: true,
      rateLimitModel: 'REQUEST_COUNT',
      authenticationModel: 'HMAC_SHA256',
      symbolFormat: 'BTCUSDT',
      timestamp: new Date().toISOString(),
    };
  }

  async getBalances(context: ExchangeProviderContext): Promise<ExchangeBalance[]> {
    const result = await this.privateGet(context, '/v5/account/wallet-balance', { accountType: 'UNIFIED' });
    const account = Array.isArray(result?.list) ? result.list[0] : undefined;
    const coins: any[] = Array.isArray(account?.coin) ? account.coin : [];
    const timestampMicros = nowMicros();
    return coins
      .map((c) => {
        const total = dec(c.walletBalance);
        const locked = dec(c.locked);
        let free = subtractDecimalStrings(total, locked);
        if (free.startsWith('-')) free = '0';
        return {
          asset: String(c.coin),
          free,
          locked,
          total,
          providerReference: account?.accountType ? String(account.accountType) : null,
          timestampMicros,
          source: 'REST',
          isSimulated: context.isSandbox,
        };
      })
      .filter((b) => b.total !== '0' || b.locked !== '0');
  }

  async getPositions(context: ExchangeProviderContext): Promise<ExchangePosition[]> {
    const rows: any[] = [];
    for (const settleCoin of ['USDT', 'USDC']) {
      rows.push(...(await this.privateList(context, '/v5/position/list', { category: 'linear', settleCoin, limit: 200 }, 1000)));
    }
    return rows
      .filter((p) => isDecimalString(p.size) && p.size !== '0' && !/^0(\.0+)?$/.test(p.size))
      .map((p) => ({
        providerPositionId: p.positionIdx !== undefined ? `${p.symbol}:${p.positionIdx}` : null,
        symbol: canonicalFromConcatenated(p.symbol),
        exchangeSymbol: String(p.symbol),
        side: p.side === 'Buy' ? ExchangePositionSide.LONG : p.side === 'Sell' ? ExchangePositionSide.SHORT : ExchangePositionSide.FLAT,
        quantity: absDecimalString(p.size),
        entryPrice: decOrNull(p.avgPrice),
        markPrice: decOrNull(p.markPrice),
        liquidationPrice: decOrNull(p.liqPrice),
        leverage: decOrNull(p.leverage),
        unrealizedPnl: decOrNull(p.unrealisedPnl),
        realizedPnl: decOrNull(p.cumRealisedPnl),
        timestampMicros: msToMicros(p.updatedTime) ?? nowMicros(),
        isSimulated: context.isSandbox,
      }));
  }

  private categoriesFor(symbol?: string): Array<{ category: BybitCategory; settleCoin?: string }> {
    if (symbol) return [{ category: 'spot' }, { category: 'linear' }];
    return [{ category: 'spot' }, { category: 'linear', settleCoin: 'USDT' }, { category: 'linear', settleCoin: 'USDC' }];
  }

  async getOpenOrders(context: ExchangeProviderContext, symbol?: string): Promise<ExchangeOrder[]> {
    const exchangeSymbol = symbol ? symbol.replace(/[-/]/g, '').toUpperCase() : undefined;
    const rows: any[] = [];
    for (const scope of this.categoriesFor(exchangeSymbol)) {
      rows.push(...(await this.privateList(context, '/v5/order/realtime', { ...scope, symbol: exchangeSymbol, limit: 50 }, 500)));
    }
    return rows.map((o) => this.mapOrder(context, o));
  }

  async getOrderHistory(context: ExchangeProviderContext, symbol?: string, limit = 50): Promise<ExchangeOrder[]> {
    const exchangeSymbol = symbol ? symbol.replace(/[-/]/g, '').toUpperCase() : undefined;
    const rows: any[] = [];
    for (const scope of this.categoriesFor(exchangeSymbol)) {
      rows.push(...(await this.privateList(context, '/v5/order/history', { ...scope, symbol: exchangeSymbol, limit: Math.min(limit, 50) }, limit)));
    }
    return rows
      .map((o) => this.mapOrder(context, o))
      .sort((a, b) => Number(BigInt(b.createdAtMicros ?? '0') - BigInt(a.createdAtMicros ?? '0')))
      .slice(0, limit);
  }

  async getTradeHistory(context: ExchangeProviderContext, symbol?: string, limit = 50): Promise<ExchangeFill[]> {
    const exchangeSymbol = symbol ? symbol.replace(/[-/]/g, '').toUpperCase() : undefined;
    const rows: any[] = [];
    for (const scope of this.categoriesFor(exchangeSymbol)) {
      rows.push(...(await this.privateList(context, '/v5/execution/list', { ...scope, symbol: exchangeSymbol, limit: Math.min(limit, 100) }, limit)));
    }
    return rows
      .map((t) => ({
        providerTradeId: String(t.execId),
        providerOrderId: t.orderId ? String(t.orderId) : null,
        clientOrderId: t.orderLinkId ? String(t.orderLinkId) : null,
        symbol: canonicalFromConcatenated(t.symbol),
        side: t.side === 'Buy' ? ExchangeOrderSide.BUY : ExchangeOrderSide.SELL,
        price: dec(t.execPrice),
        quantity: dec(t.execQty),
        quoteQuantity: decOrNull(t.execValue),
        fee: decOrNull(t.execFee),
        feeCurrency: t.feeCurrency ? String(t.feeCurrency) : null,
        isMaker: typeof t.isMaker === 'boolean' ? t.isMaker : null,
        timestampMicros: msToMicros(t.execTime) ?? nowMicros(),
        isSimulated: context.isSandbox,
      }))
      .sort((a, b) => Number(BigInt(b.timestampMicros) - BigInt(a.timestampMicros)))
      .slice(0, limit);
  }

  async getSymbols(context: ExchangeProviderContext): Promise<ExchangeSymbol[]> {
    const result = await this.publicGet(context, '/v5/market/instruments-info', { category: 'spot', limit: 1000 });
    const list: any[] = Array.isArray(result?.list) ? result.list : [];
    return list
      .filter((s) => s.status === 'Trading')
      .map((s) => {
        const tick = s.priceFilter?.tickSize ?? '0.00000001';
        const step = s.lotSizeFilter?.basePrecision ?? s.lotSizeFilter?.qtyStep ?? '0.00000001';
        return {
          canonicalSymbol: `${s.baseCoin}-${s.quoteCoin}`,
          exchangeSymbol: String(s.symbol),
          baseAsset: String(s.baseCoin),
          quoteAsset: String(s.quoteCoin),
          contractType: 'SPOT',
          tickSize: String(tick),
          quantityStep: String(step),
          minQuantity: decOrNull(s.lotSizeFilter?.minOrderQty),
          maxQuantity: decOrNull(s.lotSizeFilter?.maxOrderQty),
          minNotional: decOrNull(s.lotSizeFilter?.minOrderAmt),
          maxNotional: decOrNull(s.lotSizeFilter?.maxOrderAmt),
          pricePrecision: precisionOfStep(String(tick)),
          quantityPrecision: precisionOfStep(String(step)),
          minLeverage: null,
          maxLeverage: null,
          isTradeable: true,
        };
      });
  }

  private mapOrder(context: ExchangeProviderContext, o: any): ExchangeOrder {
    const hasTrigger = isDecimalString(o.triggerPrice) && !/^0(\.0+)?$/.test(o.triggerPrice);
    const isLimit = String(o.orderType) === 'Limit';
    const type = hasTrigger ? (isLimit ? ExchangeOrderType.STOP_LIMIT : ExchangeOrderType.STOP) : isLimit ? ExchangeOrderType.LIMIT : ExchangeOrderType.MARKET;
    return {
      clientOrderId: o.orderLinkId ? String(o.orderLinkId) : String(o.orderId),
      providerOrderId: o.orderId ? String(o.orderId) : null,
      symbol: canonicalFromConcatenated(o.symbol),
      exchangeSymbol: String(o.symbol),
      side: o.side === 'Buy' ? ExchangeOrderSide.BUY : ExchangeOrderSide.SELL,
      type,
      status: BybitProvider.mapOrderStatus(String(o.orderStatus)),
      providerRawStatus: o.orderStatus ? String(o.orderStatus) : null,
      quantity: dec(o.qty),
      price: isLimit ? decOrNull(o.price) : null,
      stopPrice: hasTrigger ? String(o.triggerPrice) : null,
      filledQuantity: dec(o.cumExecQty),
      averagePrice: decOrNull(o.avgPrice) === '0' ? null : decOrNull(o.avgPrice),
      fee: decOrNull(o.cumExecFee),
      feeCurrency: null,
      createdAtMicros: msToMicros(o.createdTime),
      updatedAtMicros: msToMicros(o.updatedTime),
      isSimulated: context.isSandbox,
    };
  }

  static mapOrderStatus(status: string): ExchangeOrderStatus {
    switch (status) {
      case 'New':
      case 'Created':
      case 'Untriggered':
      case 'Triggered':
      case 'Active':
        return ExchangeOrderStatus.NEW;
      case 'PartiallyFilled':
        return ExchangeOrderStatus.PARTIALLY_FILLED;
      case 'Filled':
        return ExchangeOrderStatus.FILLED;
      case 'Cancelled':
      case 'PartiallyFilledCanceled':
      case 'Deactivated':
        return ExchangeOrderStatus.CANCELED;
      case 'Rejected':
        return ExchangeOrderStatus.REJECTED;
      default:
        return ExchangeOrderStatus.NEW;
    }
  }
}

// # Implements signed Advanced Trade live REST/account/symbol/health probes when live trading enabled
import * as crypto from 'crypto';
import {
  ExchangeVenue,
  ExchangeEnvironment,
  ExchangeCapability,
  ExchangeOrderType,
  ExchangeBalance,
  ExchangePosition,
  ExchangeOrder,
  ExchangeFill,
  ExchangeSymbol,
  ExchangeCapabilityDiscovery,
  ExchangePositionSide,
  ExchangeOrderStatus,
  ExchangeOrderSide,
  ExchangeConnectivityResult,
} from '../exchange.types';
import {
  ExchangeProviderError,
  ExchangeProviderErrorCode,
  ExchangeProviderContext,
  ExchangeServerTime,
  ExchangeAccountMetadata,
} from '../exchange-provider.interface';
import {
  BaseExchangeProvider,
  addDecimalStrings,
  isDecimalString,
  isoToMicros,
  nowMicros,
  precisionOfStep,
} from '../base-exchange-provider';

function dec(value: unknown): string {
  return isDecimalString(value) ? value : '0';
}

function decOrNull(value: unknown): string | null {
  return isDecimalString(value) ? value : null;
}

const MAX_PAGES = 10;
/** PKCS#8 DER prefix for a raw 32-byte Ed25519 seed. */
const ED25519_PKCS8_PREFIX = Buffer.from('302e020100300506032b657004220420', 'hex');

function base64url(input: Buffer | string): string {
  return Buffer.from(input).toString('base64').replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_');
}

/**
 * Loads a Coinbase Developer Platform (CDP) API secret as a private key.
 * Accepts both key families CDP issues: an EC P-256 PEM ("-----BEGIN EC PRIVATE
 * KEY-----", often stored with literal "\n" escapes) and an Ed25519 secret
 * delivered as base64 of 64 bytes (seed || public key).
 */
export function loadCoinbaseKey(secret: string): { key: crypto.KeyObject; alg: 'ES256' | 'EdDSA' } {
  const normalized = secret.includes('\\n') ? secret.replace(/\\n/g, '\n') : secret;
  if (normalized.includes('-----BEGIN')) {
    const key = crypto.createPrivateKey(normalized);
    const type = key.asymmetricKeyType;
    if (type === 'ec') return { key, alg: 'ES256' };
    if (type === 'ed25519') return { key, alg: 'EdDSA' };
    throw new Error(`unsupported Coinbase key type ${type}`);
  }
  const raw = Buffer.from(normalized.trim(), 'base64');
  if (raw.length !== 64 && raw.length !== 32) throw new Error('Coinbase Ed25519 secret must be base64 of 32 or 64 bytes');
  const key = crypto.createPrivateKey({ key: Buffer.concat([ED25519_PKCS8_PREFIX, raw.subarray(0, 32)]), format: 'der', type: 'pkcs8' });
  return { key, alg: 'EdDSA' };
}

/**
 * Builds the short-lived bearer JWT Coinbase Advanced Trade requires on every
 * private request: `sub`/`kid` = API key name, `iss` = "cdp", a two-minute
 * validity window, and `uri` = "METHOD host/path" binding the token to exactly
 * one endpoint (query string excluded, as the venue specifies).
 */
export function buildCoinbaseJwt(keyName: string, secret: string, method: string, host: string, path: string, nowSeconds = Math.floor(Date.now() / 1000)): string {
  const { key, alg } = loadCoinbaseKey(secret);
  const header = { alg, kid: keyName, nonce: crypto.randomBytes(16).toString('hex'), typ: 'JWT' };
  const payload = { iss: 'cdp', sub: keyName, nbf: nowSeconds, exp: nowSeconds + 120, uri: `${method.toUpperCase()} ${host}${path}` };
  const signingInput = `${base64url(JSON.stringify(header))}.${base64url(JSON.stringify(payload))}`;
  const signature =
    alg === 'ES256'
      ? crypto.sign('sha256', Buffer.from(signingInput), { key, dsaEncoding: 'ieee-p1363' })
      : crypto.sign(null, Buffer.from(signingInput), key);
  return `${signingInput}.${base64url(signature)}`;
}

/**
 * Coinbase Advanced Trade API (v3 brokerage), read side.
 *
 * Authentication is a per-request ES256/EdDSA JWT built from a CDP API key
 * (key name + private key); there is no passphrase. The sandbox
 * (api-sandbox.coinbase.com) serves static responses and accepts no
 * authentication, so sandbox calls are sent without a token rather than with
 * a token signed by a key the sandbox cannot verify.
 */
export class CoinbaseProvider extends BaseExchangeProvider {
  readonly venue = ExchangeVenue.COINBASE;
  readonly displayName: string;
  readonly supportedEnvironments: ExchangeEnvironment[] = [ExchangeEnvironment.LIVE, ExchangeEnvironment.SANDBOX];
  readonly supportedCapabilities: ExchangeCapability[] = [
    ExchangeCapability.SPOT,
    ExchangeCapability.FUTURES,
    ExchangeCapability.MARKET_DATA,
    ExchangeCapability.BALANCES,
    ExchangeCapability.POSITIONS,
    ExchangeCapability.ORDERS,
    ExchangeCapability.TRADES,
  ];

  constructor(
    private readonly urls: { liveRest: string; sandboxRest: string; liveWs: string; sandboxWs: string },
    displayName = 'Coinbase Advanced Trade',
  ) {
    super();
    this.displayName = displayName;
  }

  protected getLiveRestUrl(): string {
    return this.urls.liveRest;
  }
  protected getTestnetRestUrl(): string {
    return this.urls.sandboxRest;
  }
  protected getSandboxRestUrl(): string {
    return this.urls.sandboxRest;
  }
  protected getLiveWsUrl(): string {
    return this.urls.liveWs;
  }
  protected getTestnetWsUrl(): string {
    return this.urls.sandboxWs;
  }
  protected getSandboxWsUrl(): string {
    return this.urls.sandboxWs;
  }

  private buildQuery(params: Record<string, string | number | undefined>): string {
    return Object.entries(params)
      .filter(([, v]) => v !== undefined && v !== '')
      .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
      .join('&');
  }

  private async privateGet(context: ExchangeProviderContext, path: string, params: Record<string, string | number | undefined> = {}): Promise<any> {
    const base = this.getRestBaseUrlForEnv(context.environment);
    const query = this.buildQuery(params);
    const headers: Record<string, string> = { Accept: 'application/json' };
    if (context.environment === ExchangeEnvironment.LIVE) {
      this.requireCredentials(context);
      let token: string;
      try {
        token = buildCoinbaseJwt(context.credentials.apiKey, context.credentials.apiSecret, 'GET', new URL(base).host, path);
      } catch (e: any) {
        throw new ExchangeProviderError(
          ExchangeProviderErrorCode.INVALID_CREDENTIALS,
          `Coinbase API secret is not a usable CDP private key (${String(e?.message ?? e).slice(0, 120)})`,
          context.venue,
          context.environment,
          false,
        );
      }
      headers.Authorization = `Bearer ${token}`;
    }
    try {
      return await this.httpGet(`${base}${path}${query ? `?${query}` : ''}`, headers);
    } catch (e: any) {
      throw this.normalizeError(e, context.venue, context.environment);
    }
  }

  async getServerTime(context: ExchangeProviderContext): Promise<ExchangeServerTime> {
    let data: any;
    try {
      data = await this.httpGet(`${this.getRestBaseUrlForEnv(context.environment)}/api/v3/brokerage/time`, { Accept: 'application/json' });
    } catch (e: any) {
      throw this.normalizeError(e, context.venue, context.environment);
    }
    const ms = Number(data?.epochMillis ?? (data?.epochSeconds !== undefined ? Number(data.epochSeconds) * 1000 : NaN));
    if (!Number.isFinite(ms) || ms <= 0) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, 'Coinbase server time missing from response', context.venue, context.environment, true);
    }
    return this.serverTimeFromMs(ms);
  }

  async testConnectivity(context: ExchangeProviderContext): Promise<ExchangeConnectivityResult> {
    return this.connectivityFromMetadata(context);
  }

  async getAccountMetadata(context: ExchangeProviderContext): Promise<ExchangeAccountMetadata> {
    const data = await this.privateGet(context, '/api/v3/brokerage/key_permissions');
    const permissions: string[] = [];
    if (data?.can_view) permissions.push('view');
    if (data?.can_trade) permissions.push('trade');
    if (data?.can_transfer) permissions.push('transfer');
    return {
      accountId: context.accountId,
      venue: context.venue,
      environment: context.environment,
      isSandbox: context.isSandbox,
      canTrade: data?.can_trade === true,
      canRead: data?.can_view === true,
      // `can_transfer` is Coinbase's "move funds out" permission; anything but
      // an explicit false is treated as present (fail closed).
      canWithdraw: data?.can_transfer !== false,
      ipRestricted: false,
      permissions,
      uid: data?.portfolio_uuid ? String(data.portfolio_uuid) : null,
      email: null,
    };
  }

  async getCapabilities(context: ExchangeProviderContext): Promise<ExchangeCapabilityDiscovery> {
    return {
      venue: context.venue,
      environment: context.environment,
      capabilities: this.supportedCapabilities,
      supportedOrderTypes: [ExchangeOrderType.MARKET, ExchangeOrderType.LIMIT, ExchangeOrderType.STOP_LIMIT],
      supportedEnvironments: this.supportedEnvironments,
      apiVersion: 'v3',
      restAvailable: true,
      websocketAvailable: true,
      rateLimitModel: 'REQUEST_COUNT',
      authenticationModel: 'JWT_ES256',
      symbolFormat: 'BTC-USD',
      timestamp: new Date().toISOString(),
    };
  }

  async getBalances(context: ExchangeProviderContext): Promise<ExchangeBalance[]> {
    const rows: any[] = [];
    let cursor: string | undefined;
    for (let page = 0; page < MAX_PAGES; page += 1) {
      const data = await this.privateGet(context, '/api/v3/brokerage/accounts', { limit: 250, cursor });
      rows.push(...(Array.isArray(data?.accounts) ? data.accounts : []));
      if (!data?.has_next || !data?.cursor) break;
      cursor = String(data.cursor);
    }
    const timestampMicros = nowMicros();
    return rows
      .map((a) => {
        const free = dec(a?.available_balance?.value);
        const locked = dec(a?.hold?.value);
        return {
          asset: String(a?.currency ?? a?.available_balance?.currency ?? ''),
          free,
          locked,
          total: addDecimalStrings(free, locked),
          providerReference: a?.uuid ? String(a.uuid) : null,
          timestampMicros,
          source: 'REST',
          isSimulated: context.isSandbox,
        };
      })
      .filter((b) => b.asset !== '' && (!/^0(\.0+)?$/.test(b.total)));
  }

  /**
   * Coinbase spot holds balances, not positions, so a spot-only portfolio
   * truthfully has none. Futures (CFM) positions are read when the portfolio
   * has a futures account; the venue answers 4xx for one that does not, which
   * is the "no futures account" fact, not an error to surface.
   */
  async getPositions(context: ExchangeProviderContext): Promise<ExchangePosition[]> {
    let data: any;
    try {
      data = await this.privateGet(context, '/api/v3/brokerage/cfm/positions');
    } catch (e: any) {
      const status = e?.originalError?.status;
      if (e instanceof ExchangeProviderError && [400, 404].includes(status)) return [];
      throw e;
    }
    const positions: any[] = Array.isArray(data?.positions) ? data.positions : [];
    return positions
      .filter((p) => isDecimalString(p?.number_of_contracts) && !/^0(\.0+)?$/.test(p.number_of_contracts))
      .map((p) => ({
        providerPositionId: p?.product_id ? String(p.product_id) : null,
        symbol: String(p?.product_id ?? ''),
        exchangeSymbol: String(p?.product_id ?? ''),
        side: String(p?.side).toUpperCase() === 'SHORT' ? ExchangePositionSide.SHORT : ExchangePositionSide.LONG,
        quantity: String(p.number_of_contracts).replace(/^-/, ''),
        entryPrice: decOrNull(p?.avg_entry_price),
        markPrice: decOrNull(p?.current_price),
        liquidationPrice: null,
        leverage: null,
        unrealizedPnl: decOrNull(p?.unrealized_pnl),
        realizedPnl: decOrNull(p?.daily_realized_pnl),
        timestampMicros: nowMicros(),
        isSimulated: context.isSandbox,
      }));
  }

  private async listOrders(context: ExchangeProviderContext, params: Record<string, string | number | undefined>, maxItems: number): Promise<any[]> {
    const rows: any[] = [];
    let cursor: string | undefined;
    for (let page = 0; page < MAX_PAGES && rows.length < maxItems; page += 1) {
      const data = await this.privateGet(context, '/api/v3/brokerage/orders/historical/batch', { ...params, cursor });
      rows.push(...(Array.isArray(data?.orders) ? data.orders : []));
      if (!data?.has_next || !data?.cursor) break;
      cursor = String(data.cursor);
    }
    return rows.slice(0, maxItems);
  }

  async getOpenOrders(context: ExchangeProviderContext, symbol?: string): Promise<ExchangeOrder[]> {
    const rows = await this.listOrders(context, { order_status: 'OPEN', product_ids: symbol?.toUpperCase(), limit: 100 }, 1000);
    return rows.map((o) => this.mapOrder(context, o));
  }

  async getOrderHistory(context: ExchangeProviderContext, symbol?: string, limit = 50): Promise<ExchangeOrder[]> {
    const rows = await this.listOrders(context, { product_ids: symbol?.toUpperCase(), limit: Math.min(limit, 100) }, limit);
    return rows.map((o) => this.mapOrder(context, o));
  }

  async getTradeHistory(context: ExchangeProviderContext, symbol?: string, limit = 50): Promise<ExchangeFill[]> {
    const data = await this.privateGet(context, '/api/v3/brokerage/orders/historical/fills', { product_ids: symbol?.toUpperCase(), limit: Math.min(limit, 100) });
    const fills: any[] = Array.isArray(data?.fills) ? data.fills : [];
    return fills.slice(0, limit).map((f) => {
      const product = String(f?.product_id ?? '');
      return {
        providerTradeId: String(f?.trade_id ?? f?.entry_id),
        providerOrderId: f?.order_id ? String(f.order_id) : null,
        clientOrderId: null,
        symbol: product,
        side: String(f?.side).toUpperCase() === 'SELL' ? ExchangeOrderSide.SELL : ExchangeOrderSide.BUY,
        price: dec(f?.price),
        quantity: dec(f?.size),
        quoteQuantity: f?.size_in_quote === true ? dec(f?.size) : null,
        fee: decOrNull(f?.commission),
        feeCurrency: product.includes('-') ? product.split('-')[1] : null,
        isMaker: f?.liquidity_indicator === 'MAKER' ? true : f?.liquidity_indicator === 'TAKER' ? false : null,
        timestampMicros: isoToMicros(f?.trade_time) ?? nowMicros(),
        isSimulated: context.isSandbox,
      };
    });
  }

  async getSymbols(context: ExchangeProviderContext): Promise<ExchangeSymbol[]> {
    const data = await this.privateGet(context, '/api/v3/brokerage/products', { product_type: 'SPOT' });
    const products: any[] = Array.isArray(data?.products) ? data.products : [];
    return products
      .filter((p) => p?.status === 'online' && !p?.trading_disabled && !p?.is_disabled && !p?.cancel_only)
      .map((p) => {
        const tick = String(p?.price_increment ?? p?.quote_increment ?? '0.01');
        const step = String(p?.base_increment ?? '0.00000001');
        return {
          canonicalSymbol: `${p.base_currency_id}-${p.quote_currency_id}`,
          exchangeSymbol: String(p.product_id),
          baseAsset: String(p.base_currency_id),
          quoteAsset: String(p.quote_currency_id),
          contractType: 'SPOT',
          tickSize: tick,
          quantityStep: step,
          minQuantity: decOrNull(p?.base_min_size),
          maxQuantity: decOrNull(p?.base_max_size),
          minNotional: decOrNull(p?.quote_min_size),
          maxNotional: decOrNull(p?.quote_max_size),
          pricePrecision: precisionOfStep(tick),
          quantityPrecision: precisionOfStep(step),
          minLeverage: null,
          maxLeverage: null,
          isTradeable: true,
        };
      });
  }

  private mapOrder(context: ExchangeProviderContext, o: any): ExchangeOrder {
    const config = o?.order_configuration ?? {};
    const variant: any = Object.values(config)[0] ?? {};
    const orderType = String(o?.order_type ?? '');
    let type: ExchangeOrderType;
    if (orderType === 'MARKET') type = ExchangeOrderType.MARKET;
    else if (orderType === 'STOP_LIMIT') type = ExchangeOrderType.STOP_LIMIT;
    else if (orderType === 'STOP') type = ExchangeOrderType.STOP;
    else if (variant?.post_only === true) type = ExchangeOrderType.LIMIT_MAKER;
    else type = ExchangeOrderType.LIMIT;
    const product = String(o?.product_id ?? '');
    return {
      clientOrderId: o?.client_order_id ? String(o.client_order_id) : String(o?.order_id),
      providerOrderId: o?.order_id ? String(o.order_id) : null,
      symbol: product,
      exchangeSymbol: product,
      side: String(o?.side).toUpperCase() === 'SELL' ? ExchangeOrderSide.SELL : ExchangeOrderSide.BUY,
      type,
      status: CoinbaseProvider.mapOrderStatus(String(o?.status ?? ''), dec(o?.filled_size)),
      providerRawStatus: o?.status ? String(o.status) : null,
      quantity: decOrNull(variant?.base_size) ?? decOrNull(variant?.quote_size) ?? dec(o?.filled_size),
      price: decOrNull(variant?.limit_price),
      stopPrice: decOrNull(variant?.stop_price),
      filledQuantity: dec(o?.filled_size),
      averagePrice: isDecimalString(o?.average_filled_price) && !/^0(\.0+)?$/.test(o.average_filled_price) ? o.average_filled_price : null,
      fee: decOrNull(o?.total_fees),
      feeCurrency: product.includes('-') ? product.split('-')[1] : null,
      createdAtMicros: isoToMicros(o?.created_time),
      updatedAtMicros: isoToMicros(o?.last_fill_time) ?? isoToMicros(o?.created_time),
      isSimulated: context.isSandbox,
    };
  }

  static mapOrderStatus(status: string, filled = '0'): ExchangeOrderStatus {
    const executed = !/^0(\.0+)?$/.test(filled);
    switch (status) {
      case 'PENDING':
      case 'QUEUED':
      case 'OPEN':
        return executed ? ExchangeOrderStatus.PARTIALLY_FILLED : ExchangeOrderStatus.NEW;
      case 'FILLED':
        return ExchangeOrderStatus.FILLED;
      case 'CANCELLED':
        return ExchangeOrderStatus.CANCELED;
      case 'CANCEL_QUEUED':
        return ExchangeOrderStatus.PENDING_CANCEL;
      case 'EXPIRED':
        return ExchangeOrderStatus.EXPIRED;
      case 'FAILED':
        return ExchangeOrderStatus.REJECTED;
      default:
        return ExchangeOrderStatus.NEW;
    }
  }
}

// # Implements signed live REST/account/symbol/health probes when live trading enabled
import * as crypto from 'crypto';
import {
  ExchangeVenue,
  ExchangeEnvironment,
  ExchangeCapability,
  ExchangeOrderType,
  ExchangeBalance,
  ExchangePosition,
  ExchangeOrder,
  ExchangeFill,
  ExchangeSymbol,
  ExchangeCapabilityDiscovery,
  ExchangePositionSide,
  ExchangeOrderStatus,
  ExchangeOrderSide,
  ExchangeConnectivityResult,
} from '../exchange.types';
import {
  ExchangeProviderError,
  ExchangeProviderErrorCode,
  ExchangeProviderContext,
  ExchangeServerTime,
  ExchangeAccountMetadata,
} from '../exchange-provider.interface';
import {
  BaseExchangeProvider,
  subtractDecimalStrings,
  isDecimalString,
  secondsToMicros,
  nowMicros,
} from '../base-exchange-provider';

function dec(value: unknown): string {
  return isDecimalString(value) ? value : '0';
}

function decOrNull(value: unknown): string | null {
  return isDecimalString(value) ? value : null;
}

/**
 * Kraken's legacy asset codes ("XXBT", "ZUSD", "XETH") to the platform's
 * conventional tickers. Codes outside this table are returned unchanged -
 * newer Kraken assets already use plain tickers, and a staked/earn suffix
 * (".S", ".F", ".B") is kept because it is a different balance, not a typo.
 */
const KRAKEN_ASSETS: Record<string, string> = {
  XXBT: 'BTC',
  XBT: 'BTC',
  XXDG: 'DOGE',
  XDG: 'DOGE',
  XETH: 'ETH',
  XETC: 'ETC',
  XLTC: 'LTC',
  XXLM: 'XLM',
  XXMR: 'XMR',
  XXRP: 'XRP',
  XZEC: 'ZEC',
  XMLN: 'MLN',
  XREP: 'REP',
  ZUSD: 'USD',
  ZEUR: 'EUR',
  ZGBP: 'GBP',
  ZCAD: 'CAD',
  ZJPY: 'JPY',
  ZAUD: 'AUD',
  ZCHF: 'CHF',
};

export function krakenAsset(code: string): string {
  const upper = String(code || '').toUpperCase();
  const [base, ...suffix] = upper.split('.');
  const mapped = KRAKEN_ASSETS[base] ?? base;
  return suffix.length > 0 ? `${mapped}.${suffix.join('.')}` : mapped;
}

/**
 * Splits a Kraken pair in any of its three spellings - websocket "XBT/USD",
 * legacy "XXBTZUSD" and altname "XBTUSD" - into normalized base/quote
 * tickers. Returns null when no known quote suffix matches.
 */
export function krakenPairParts(pair: string): { base: string; quote: string } | null {
  const upper = String(pair || '').toUpperCase();
  if (upper.includes('/')) {
    const [b, q] = upper.split('/');
    return b && q ? { base: krakenAsset(b), quote: krakenAsset(q) } : null;
  }
  if (upper.length === 8 && /^[XZ]/.test(upper) && /^[XZ]/.test(upper.slice(4)) && KRAKEN_ASSETS[upper.slice(4)] !== undefined) {
    return { base: krakenAsset(upper.slice(0, 4)), quote: krakenAsset(upper.slice(4)) };
  }
  for (const quote of ['USDT', 'USDC', 'ZUSD', 'ZEUR', 'ZGBP', 'ZCAD', 'ZJPY', 'USD', 'EUR', 'GBP', 'CAD', 'JPY', 'XBT', 'ETH']) {
    if (upper.length > quote.length && upper.endsWith(quote)) {
      return { base: krakenAsset(upper.slice(0, upper.length - quote.length)), quote: krakenAsset(quote) };
    }
  }
  return null;
}

/** The probe key name used to learn whether a key may withdraw. No such key exists by construction. */
export const KRAKEN_WITHDRAW_PROBE_KEY = '__wlct_permission_probe_no_such_key__';

/**
 * Kraken Spot REST API, read side.
 *
 * Authentication: `API-Sign = base64(HMAC_SHA512(base64decode(secret), uriPath || SHA256(nonce + postData)))`,
 * where `||` is byte concatenation of the path and the raw SHA-256 digest. The
 * nonce must strictly increase per key; this provider derives it from
 * microsecond wall time and never reuses one inside the process.
 *
 * Kraken has no spot sandbox, so only LIVE is supported. Kraken exposes no
 * endpoint that lists a key's permissions, so {@link getAccountMetadata}
 * PROBES them with two calls that cannot move funds or place an order:
 * `WithdrawInfo` for a withdrawal key that does not exist (answers
 * "Permission denied" only when the key lacks withdraw rights) and `AddOrder`
 * with `validate=true` (validated, never submitted). A probe that returns
 * anything other than a clean permission refusal is treated as "has the
 * permission" - fail closed, so a key we cannot prove safe is refused.
 */
export class KrakenProvider extends BaseExchangeProvider {
  readonly venue = ExchangeVenue.KRAKEN;
  readonly displayName: string;
  readonly supportedEnvironments: ExchangeEnvironment[] = [ExchangeEnvironment.LIVE];
  readonly supportedCapabilities: ExchangeCapability[] = [
    ExchangeCapability.SPOT,
    ExchangeCapability.MARGIN,
    ExchangeCapability.MARKET_DATA,
    ExchangeCapability.BALANCES,
    ExchangeCapability.POSITIONS,
    ExchangeCapability.ORDERS,
    ExchangeCapability.TRADES,
  ];

  private lastNonce = 0n;

  constructor(
    private readonly urls: { liveRest: string; liveWs: string },
    displayName = 'Kraken',
  ) {
    super();
    this.displayName = displayName;
  }

  protected getLiveRestUrl(): string {
    return this.urls.liveRest;
  }
  protected getTestnetRestUrl(): string {
    return this.urls.liveRest;
  }
  protected getSandboxRestUrl(): string {
    return this.urls.liveRest;
  }
  protected getLiveWsUrl(): string {
    return this.urls.liveWs;
  }
  protected getTestnetWsUrl(): string {
    return this.urls.liveWs;
  }
  protected getSandboxWsUrl(): string {
    return this.urls.liveWs;
  }

  /** Exposed for tests: the exact Kraken signature. */
  static sign(secretBase64: string, uriPath: string, nonce: string, postData: string): string {
    const digest = crypto.createHash('sha256').update(nonce + postData).digest();
    return crypto
      .createHmac('sha512', Buffer.from(secretBase64, 'base64'))
      .update(Buffer.concat([Buffer.from(uriPath, 'utf8'), digest]))
      .digest('base64');
  }

  private nextNonce(): string {
    const candidate = BigInt(Date.now()) * 1000n;
    this.lastNonce = candidate > this.lastNonce ? candidate : this.lastNonce + 1n;
    return this.lastNonce.toString();
  }

  private assertLive(context: ExchangeProviderContext): void {
    if (context.environment !== ExchangeEnvironment.LIVE) {
      throw new ExchangeProviderError(
        ExchangeProviderErrorCode.NOT_SUPPORTED,
        'Kraken has no spot sandbox or testnet; only LIVE accounts can be connected',
        context.venue,
        context.environment,
        false,
      );
    }
  }

  private classify(context: ExchangeProviderContext, errors: string[]): ExchangeProviderError {
    const joined = errors.join('; ').slice(0, 300);
    const has = (needle: string) => errors.some((e) => e.includes(needle));
    if (has('EAPI:Invalid key') || has('EAPI:Invalid signature')) {
      return new ExchangeProviderError(ExchangeProviderErrorCode.AUTH_FAILED, `Kraken: ${joined}`, context.venue, context.environment, false);
    }
    if (has('EAPI:Invalid nonce')) {
      return new ExchangeProviderError(ExchangeProviderErrorCode.CLOCK_DRIFT, `Kraken: ${joined}`, context.venue, context.environment, true, 1000);
    }
    if (has('EGeneral:Permission denied')) {
      return new ExchangeProviderError(ExchangeProviderErrorCode.PERMISSION_DENIED, `Kraken: ${joined}`, context.venue, context.environment, false);
    }
    if (has('Rate limit exceeded') || has('EGeneral:Too many requests')) {
      return new ExchangeProviderError(ExchangeProviderErrorCode.RATE_LIMITED, `Kraken: ${joined}`, context.venue, context.environment, true, 2000);
    }
    if (has('EService:Unavailable') || has('EService:Busy') || has('EService:Market in cancel_only mode')) {
      return new ExchangeProviderError(ExchangeProviderErrorCode.SERVER_ERROR, `Kraken: ${joined}`, context.venue, context.environment, true, 2000);
    }
    if (has('EQuery:Unknown asset pair')) {
      return new ExchangeProviderError(ExchangeProviderErrorCode.SYMBOL_NOT_FOUND, `Kraken: ${joined}`, context.venue, context.environment, false);
    }
    return new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, `Kraken: ${joined}`, context.venue, context.environment, false);
  }

  private unwrap(context: ExchangeProviderContext, data: any): any {
    if (!data || typeof data !== 'object') {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, 'Kraken returned a non-JSON body', context.venue, context.environment, true);
    }
    const errors: string[] = Array.isArray(data.error) ? data.error.map(String) : [];
    if (errors.length > 0) throw this.classify(context, errors);
    return data.result ?? {};
  }

  private async publicGet(context: ExchangeProviderContext, path: string, query = ''): Promise<any> {
    this.assertLive(context);
    try {
      return this.unwrap(context, await this.httpGet(`${this.getLiveRestUrl()}${path}${query ? `?${query}` : ''}`));
    } catch (e: any) {
      throw this.normalizeError(e, context.venue, context.environment);
    }
  }

  private async privatePost(context: ExchangeProviderContext, path: string, params: Record<string, string> = {}): Promise<any> {
    this.assertLive(context);
    this.requireCredentials(context);
    const nonce = this.nextNonce();
    const postData = new URLSearchParams({ nonce, ...params }).toString();
    const signature = KrakenProvider.sign(context.credentials.apiSecret, path, nonce, postData);
    try {
      const data = await this.httpRequest({
        method: 'POST',
        url: `${this.getLiveRestUrl()}${path}`,
        headers: {
          'API-Key': context.credentials.apiKey,
          'API-Sign': signature,
          'Content-Type': 'application/x-www-form-urlencoded; charset=utf-8',
        },
        body: postData,
      });
      return this.unwrap(context, data);
    } catch (e: any) {
      throw this.normalizeError(e, context.venue, context.environment);
    }
  }

  async getServerTime(context: ExchangeProviderContext): Promise<ExchangeServerTime> {
    const result = await this.publicGet(context, '/0/public/Time');
    const seconds = Number(result?.unixtime);
    if (!Number.isFinite(seconds) || seconds <= 0) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, 'Kraken server time missing from response', context.venue, context.environment, true);
    }
    // Kraken's clock has one-second resolution; drift below a second is noise.
    return this.serverTimeFromMs(seconds * 1000);
  }

  async testConnectivity(context: ExchangeProviderContext): Promise<ExchangeConnectivityResult> {
    return this.connectivityFromMetadata(context);
  }

  /** true = the probe proved the permission is ABSENT; false = present or unprovable. */
  private async probeRefused(context: ExchangeProviderContext, path: string, params: Record<string, string>): Promise<boolean> {
    try {
      await this.privatePost(context, path, params);
      return false;
    } catch (e: any) {
      if (e instanceof ExchangeProviderError && e.code === ExchangeProviderErrorCode.PERMISSION_DENIED) return true;
      if (e instanceof ExchangeProviderError && (e.code === ExchangeProviderErrorCode.AUTH_FAILED || e.code === ExchangeProviderErrorCode.RATE_LIMITED)) throw e;
      return false;
    }
  }

  async getAccountMetadata(context: ExchangeProviderContext): Promise<ExchangeAccountMetadata> {
    // The read permission is proven by an ordinary balance read (throws on a bad key).
    await this.privatePost(context, '/0/private/Balance');
    const withdrawRefused = await this.probeRefused(context, '/0/private/WithdrawInfo', {
      asset: 'XBT',
      key: KRAKEN_WITHDRAW_PROBE_KEY,
      amount: '0.0001',
    });
    const tradeRefused = await this.probeRefused(context, '/0/private/AddOrder', {
      pair: 'XBTUSD',
      type: 'buy',
      ordertype: 'limit',
      price: '1',
      volume: '0.0001',
      validate: 'true',
    });
    const permissions = ['query_funds'];
    if (!tradeRefused) permissions.push('create_modify_orders');
    if (!withdrawRefused) permissions.push('withdraw_funds_or_unproven');
    return {
      accountId: context.accountId,
      venue: context.venue,
      environment: context.environment,
      isSandbox: context.isSandbox,
      canTrade: !tradeRefused,
      canRead: true,
      canWithdraw: !withdrawRefused,
      ipRestricted: false,
      permissions,
      uid: null,
      email: null,
    };
  }

  async getCapabilities(context: ExchangeProviderContext): Promise<ExchangeCapabilityDiscovery> {
    return {
      venue: context.venue,
      environment: context.environment,
      capabilities: this.supportedCapabilities,
      supportedOrderTypes: [ExchangeOrderType.MARKET, ExchangeOrderType.LIMIT, ExchangeOrderType.STOP, ExchangeOrderType.STOP_LIMIT, ExchangeOrderType.TAKE_PROFIT, ExchangeOrderType.TAKE_PROFIT_LIMIT],
      supportedEnvironments: this.supportedEnvironments,
      apiVersion: '0',
      restAvailable: true,
      websocketAvailable: true,
      rateLimitModel: 'TOKEN_BUCKET',
      authenticationModel: 'HMAC_SHA512',
      symbolFormat: 'XBTUSD',
      timestamp: new Date().toISOString(),
    };
  }

  async getBalances(context: ExchangeProviderContext): Promise<ExchangeBalance[]> {
    const result = await this.privatePost(context, '/0/private/BalanceEx');
    const timestampMicros = nowMicros();
    return Object.entries(result as Record<string, any>)
      .map(([code, row]) => {
        const total = dec(row?.balance);
        const locked = dec(row?.hold_trade);
        let free = subtractDecimalStrings(total, locked);
        if (free.startsWith('-')) free = '0';
        return {
          asset: krakenAsset(code),
          free,
          locked,
          total,
          providerReference: code,
          timestampMicros,
          source: 'REST',
          isSimulated: false,
        };
      })
      .filter((b) => !/^0(\.0+)?$/.test(b.total) || !/^0(\.0+)?$/.test(b.locked));
  }

  async getPositions(context: ExchangeProviderContext): Promise<ExchangePosition[]> {
    const result = await this.privatePost(context, '/0/private/OpenPositions', { docalcs: 'true' });
    return Object.entries(result as Record<string, any>).map(([posId, p]) => {
      const vol = dec(p?.vol);
      const closed = dec(p?.vol_closed);
      const open = subtractDecimalStrings(vol, closed);
      return {
        providerPositionId: posId,
        symbol: this.canonicalPair(String(p?.pair ?? '')),
        exchangeSymbol: String(p?.pair ?? ''),
        side: p?.type === 'sell' ? ExchangePositionSide.SHORT : ExchangePositionSide.LONG,
        quantity: open.startsWith('-') ? '0' : open,
        entryPrice: null,
        markPrice: null,
        liquidationPrice: null,
        leverage: decOrNull(p?.leverage),
        unrealizedPnl: decOrNull(p?.net),
        realizedPnl: null,
        timestampMicros: secondsToMicros(p?.time) ?? nowMicros(),
        isSimulated: false,
      };
    });
  }

  async getOpenOrders(context: ExchangeProviderContext, symbol?: string): Promise<ExchangeOrder[]> {
    const result = await this.privatePost(context, '/0/private/OpenOrders');
    const orders = Object.entries((result?.open ?? {}) as Record<string, any>).map(([txid, o]) => this.mapOrder(txid, o));
    return symbol ? orders.filter((o) => o.symbol === symbol.toUpperCase() || o.exchangeSymbol === symbol.toUpperCase()) : orders;
  }

  async getOrderHistory(context: ExchangeProviderContext, symbol?: string, limit = 50): Promise<ExchangeOrder[]> {
    const result = await this.privatePost(context, '/0/private/ClosedOrders');
    const orders = Object.entries((result?.closed ?? {}) as Record<string, any>)
      .map(([txid, o]) => this.mapOrder(txid, o))
      .filter((o) => !symbol || o.symbol === symbol.toUpperCase() || o.exchangeSymbol === symbol.toUpperCase())
      .sort((a, b) => Number(BigInt(b.createdAtMicros ?? '0') - BigInt(a.createdAtMicros ?? '0')));
    return orders.slice(0, limit);
  }

  async getTradeHistory(context: ExchangeProviderContext, symbol?: string, limit = 50): Promise<ExchangeFill[]> {
    const result = await this.privatePost(context, '/0/private/TradesHistory');
    return Object.entries((result?.trades ?? {}) as Record<string, any>)
      .map(([tradeId, t]) => ({
        providerTradeId: tradeId,
        providerOrderId: t?.ordertxid ? String(t.ordertxid) : null,
        clientOrderId: null,
        symbol: this.canonicalPair(String(t?.pair ?? '')),
        side: t?.type === 'sell' ? ExchangeOrderSide.SELL : ExchangeOrderSide.BUY,
        price: dec(t?.price),
        quantity: dec(t?.vol),
        quoteQuantity: decOrNull(t?.cost),
        fee: decOrNull(t?.fee),
        feeCurrency: null,
        isMaker: typeof t?.maker === 'boolean' ? t.maker : null,
        timestampMicros: secondsToMicros(t?.time) ?? nowMicros(),
        isSimulated: false,
      }))
      .filter((f) => !symbol || f.symbol === symbol.toUpperCase())
      .sort((a, b) => Number(BigInt(b.timestampMicros) - BigInt(a.timestampMicros)))
      .slice(0, limit);
  }

  async getSymbols(context: ExchangeProviderContext): Promise<ExchangeSymbol[]> {
    const result = await this.publicGet(context, '/0/public/AssetPairs');
    return Object.entries(result as Record<string, any>)
      .filter(([, p]) => (p?.status ?? 'online') === 'online' && typeof p?.wsname === 'string')
      .map(([pairKey, p]) => {
        const [wsBase, wsQuote] = String(p.wsname).split('/');
        const base = krakenAsset(wsBase);
        const quote = krakenAsset(wsQuote);
        const pairDecimals = Number(p.pair_decimals ?? 8);
        const lotDecimals = Number(p.lot_decimals ?? 8);
        return {
          canonicalSymbol: `${base}-${quote}`,
          exchangeSymbol: String(p.altname ?? pairKey),
          baseAsset: base,
          quoteAsset: quote,
          contractType: 'SPOT',
          tickSize: isDecimalString(p.tick_size) ? p.tick_size : lotStep(pairDecimals),
          quantityStep: lotStep(lotDecimals),
          minQuantity: decOrNull(p.ordermin),
          maxQuantity: null,
          minNotional: decOrNull(p.costmin),
          maxNotional: null,
          pricePrecision: pairDecimals,
          quantityPrecision: lotDecimals,
          minLeverage: null,
          maxLeverage: Array.isArray(p.leverage_buy) && p.leverage_buy.length > 0 ? Math.max(...p.leverage_buy.map(Number)) : null,
          isTradeable: true,
        };
      });
  }

  /** "XXBTZUSD" / "XBTUSD" / "XBT/USD" -> "BTC-USD" using the legacy asset table. */
  canonicalPair(pair: string): string {
    const parts = krakenPairParts(pair);
    return parts ? `${parts.base}-${parts.quote}` : pair.toUpperCase();
  }

  private mapOrder(txid: string, o: any): ExchangeOrder {
    const descr = o?.descr ?? {};
    const ordertype = String(descr.ordertype ?? '');
    const typeMap: Record<string, ExchangeOrderType> = {
      market: ExchangeOrderType.MARKET,
      limit: ExchangeOrderType.LIMIT,
      'stop-loss': ExchangeOrderType.STOP,
      'stop-loss-limit': ExchangeOrderType.STOP_LIMIT,
      'take-profit': ExchangeOrderType.TAKE_PROFIT,
      'take-profit-limit': ExchangeOrderType.TAKE_PROFIT_LIMIT,
    };
    const type = typeMap[ordertype] ?? ExchangeOrderType.LIMIT;
    const isStopFamily = type === ExchangeOrderType.STOP || type === ExchangeOrderType.STOP_LIMIT || type === ExchangeOrderType.TAKE_PROFIT || type === ExchangeOrderType.TAKE_PROFIT_LIMIT;
    const pair = String(descr.pair ?? '');
    const volExec = dec(o?.vol_exec);
    return {
      clientOrderId: o?.cl_ord_id ? String(o.cl_ord_id) : o?.userref ? String(o.userref) : txid,
      providerOrderId: txid,
      symbol: this.canonicalPair(pair),
      exchangeSymbol: pair,
      side: descr.type === 'sell' ? ExchangeOrderSide.SELL : ExchangeOrderSide.BUY,
      type,
      status: KrakenProvider.mapOrderStatus(String(o?.status ?? ''), volExec),
      providerRawStatus: o?.status ? String(o.status) : null,
      quantity: dec(o?.vol),
      price: type === ExchangeOrderType.MARKET ? null : isStopFamily ? decOrNull(descr.price2) : decOrNull(descr.price),
      stopPrice: isStopFamily ? decOrNull(descr.price) : null,
      filledQuantity: volExec,
      averagePrice: isDecimalString(o?.price) && !/^0(\.0+)?$/.test(o.price) ? o.price : null,
      fee: decOrNull(o?.fee),
      feeCurrency: null,
      createdAtMicros: secondsToMicros(o?.opentm),
      updatedAtMicros: secondsToMicros(o?.closetm) ?? secondsToMicros(o?.opentm),
      isSimulated: false,
    };
  }

  static mapOrderStatus(status: string, volExec = '0'): ExchangeOrderStatus {
    const executed = !/^0(\.0+)?$/.test(volExec);
    switch (status) {
      case 'pending':
      case 'open':
        return executed ? ExchangeOrderStatus.PARTIALLY_FILLED : ExchangeOrderStatus.NEW;
      case 'closed':
        return ExchangeOrderStatus.FILLED;
      case 'canceled':
        return ExchangeOrderStatus.CANCELED;
      case 'expired':
        return ExchangeOrderStatus.EXPIRED;
      default:
        return ExchangeOrderStatus.NEW;
    }
  }
}

function lotStep(decimals: number): string {
  if (!Number.isInteger(decimals) || decimals <= 0) return '1';
  return `0.${'0'.repeat(decimals - 1)}1`;
}

// # Implements signed V5 live REST/account/symbol/health probes when live trading enabled
import * as crypto from 'crypto';
import {
  ExchangeVenue,
  ExchangeEnvironment,
  ExchangeCapability,
  ExchangeOrderType,
  ExchangeBalance,
  ExchangePosition,
  ExchangeOrder,
  ExchangeFill,
  ExchangeSymbol,
  ExchangeCapabilityDiscovery,
  ExchangePositionSide,
  ExchangeOrderStatus,
  ExchangeOrderSide,
  ExchangeConnectivityResult,
} from '../exchange.types';
import {
  ExchangeProviderError,
  ExchangeProviderErrorCode,
  ExchangeProviderContext,
  ExchangeServerTime,
  ExchangeAccountMetadata,
} from '../exchange-provider.interface';
import {
  BaseExchangeProvider,
  addDecimalStrings,
  absDecimalString,
  signOfDecimalString,
  isDecimalString,
  msToMicros,
  nowMicros,
  precisionOfStep,
} from '../base-exchange-provider';

function dec(value: unknown): string {
  return isDecimalString(value) ? value : '0';
}

function decOrNull(value: unknown): string | null {
  return isDecimalString(value) ? value : null;
}

/** "BTC-USDT-SWAP" -> "BTC-USDT"; spot ids are already canonical. */
export function okxCanonical(instId: string): string {
  const parts = String(instId || '').toUpperCase().split('-');
  return parts.length >= 2 ? `${parts[0]}-${parts[1]}` : String(instId || '').toUpperCase();
}

function instTypeOf(instId: string): 'SPOT' | 'SWAP' | 'FUTURES' | 'OPTION' {
  const parts = String(instId).toUpperCase().split('-');
  if (parts.length === 2) return 'SPOT';
  if (parts[2] === 'SWAP') return 'SWAP';
  if (parts.length >= 5) return 'OPTION';
  return 'FUTURES';
}

/**
 * OKX V5 API, read side.
 *
 * Authentication: `OK-ACCESS-SIGN = base64(HMAC_SHA256(secret, timestamp + METHOD + requestPath + body))`
 * where `requestPath` includes the query string and `timestamp` is ISO-8601 with
 * milliseconds; the passphrase chosen at key creation rides in
 * `OK-ACCESS-PASSPHRASE`. OKX's demo trading uses the same host with
 * `x-simulated-trading: 1`, so TESTNET/SANDBOX differ from LIVE by that header,
 * which is added for every non-LIVE environment - a demo key sent without it
 * is rejected by the venue, and a live key sent with it is too.
 */
export class OkxProvider extends BaseExchangeProvider {
  readonly venue = ExchangeVenue.OKX;
  readonly displayName: string;
  readonly supportedEnvironments: ExchangeEnvironment[] = [ExchangeEnvironment.LIVE, ExchangeEnvironment.TESTNET, ExchangeEnvironment.SANDBOX];
  readonly supportedCapabilities: ExchangeCapability[] = [
    ExchangeCapability.SPOT,
    ExchangeCapability.MARGIN,
    ExchangeCapability.FUTURES,
    ExchangeCapability.PERPETUALS,
    ExchangeCapability.MARKET_DATA,
    ExchangeCapability.BALANCES,
    ExchangeCapability.POSITIONS,
    ExchangeCapability.ORDERS,
    ExchangeCapability.TRADES,
    ExchangeCapability.TESTNET,
  ];

  constructor(
    private readonly urls: { liveRest: string; testnetRest: string; sandboxRest: string; liveWs: string; testnetWs: string; sandboxWs: string },
    displayName = 'OKX',
  ) {
    super();
    this.displayName = displayName;
  }

  protected getLiveRestUrl(): string {
    return this.urls.liveRest;
  }
  protected getTestnetRestUrl(): string {
    return this.urls.testnetRest;
  }
  protected getSandboxRestUrl(): string {
    return this.urls.sandboxRest;
  }
  protected getLiveWsUrl(): string {
    return this.urls.liveWs;
  }
  protected getTestnetWsUrl(): string {
    return this.urls.testnetWs;
  }
  protected getSandboxWsUrl(): string {
    return this.urls.sandboxWs;
  }

  /** Exposed for tests: the exact V5 prehash signature. */
  static sign(secret: string, timestamp: string, method: string, requestPath: string, body = ''): string {
    return crypto.createHmac('sha256', secret).update(timestamp + method.toUpperCase() + requestPath + body).digest('base64');
  }

  private buildQuery(params: Record<string, string | number | undefined>): string {
    return Object.entries(params)
      .filter(([, v]) => v !== undefined && v !== '')
      .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
      .join('&');
  }

  private demoHeaders(context: ExchangeProviderContext): Record<string, string> {
    return context.environment === ExchangeEnvironment.LIVE ? {} : { 'x-simulated-trading': '1' };
  }

  private unwrap(context: ExchangeProviderContext, data: any): any[] {
    if (!data || typeof data !== 'object') {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, 'OKX returned a non-JSON body', context.venue, context.environment, true);
    }
    const code = String(data.code);
    if (code === '0') return Array.isArray(data.data) ? data.data : [];
    const message = `OKX code ${code}: ${String(data.msg ?? '').slice(0, 200)}`;
    if (['50111', '50113', '50105', '50100', '50101', '50114'].includes(code)) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.AUTH_FAILED, message, context.venue, context.environment, false);
    }
    if (['50110', '50120', '50121'].includes(code)) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.PERMISSION_DENIED, message, context.venue, context.environment, false);
    }
    if (['50102', '50112'].includes(code)) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.CLOCK_DRIFT, message, context.venue, context.environment, true, 1000);
    }
    if (['50011', '50061'].includes(code)) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.RATE_LIMITED, message, context.venue, context.environment, true, 1000);
    }
    if (['50001', '50004', '50013', '50026'].includes(code)) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.SERVER_ERROR, message, context.venue, context.environment, true, 1000);
    }
    throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, message, context.venue, context.environment, false);
  }

  private async publicGet(context: ExchangeProviderContext, path: string, params: Record<string, string | number | undefined> = {}): Promise<any[]> {
    const query = this.buildQuery(params);
    const url = `${this.getRestBaseUrlForEnv(context.environment)}${path}${query ? `?${query}` : ''}`;
    try {
      return this.unwrap(context, await this.httpGet(url, this.demoHeaders(context)));
    } catch (e: any) {
      throw this.normalizeError(e, context.venue, context.environment);
    }
  }

  private async privateGet(context: ExchangeProviderContext, path: string, params: Record<string, string | number | undefined> = {}): Promise<any[]> {
    this.requireCredentials(context, true);
    const query = this.buildQuery(params);
    const requestPath = `${path}${query ? `?${query}` : ''}`;
    const timestamp = new Date().toISOString();
    const signature = OkxProvider.sign(context.credentials.apiSecret, timestamp, 'GET', requestPath);
    try {
      const data = await this.httpGet(`${this.getRestBaseUrlForEnv(context.environment)}${requestPath}`, {
        'OK-ACCESS-KEY': context.credentials.apiKey,
        'OK-ACCESS-SIGN': signature,
        'OK-ACCESS-TIMESTAMP': timestamp,
        'OK-ACCESS-PASSPHRASE': context.credentials.passphrase as string,
        ...this.demoHeaders(context),
      });
      return this.unwrap(context, data);
    } catch (e: any) {
      throw this.normalizeError(e, context.venue, context.environment);
    }
  }

  async getServerTime(context: ExchangeProviderContext): Promise<ExchangeServerTime> {
    const data = await this.publicGet(context, '/api/v5/public/time');
    const ts = Number(data[0]?.ts);
    if (!Number.isFinite(ts) || ts <= 0) {
      throw new ExchangeProviderError(ExchangeProviderErrorCode.UNKNOWN, 'OKX server time missing from response', context.venue, context.environment, true);
    }
    return this.serverTimeFromMs(ts);
  }

  async testConnectivity(context: ExchangeProviderContext): Promise<ExchangeConnectivityResult> {
    return this.connectivityFromMetadata(context);
  }

  async getAccountMetadata(context: ExchangeProviderContext): Promise<ExchangeAccountMetadata> {
    const data = await this.privateGet(context, '/api/v5/account/config');
    const config = data[0] ?? {};
    const perms = String(config.perm ?? '')
      .split(',')
      .map((p: string) => p.trim())
      .filter(Boolean);
    const ip = String(config.ip ?? '').trim();
    return {
      accountId: context.accountId,
      venue: context.venue,
      environment: context.environment,
      isSandbox: context.isSandbox,
      canTrade: perms.includes('trade'),
      canRead: perms.includes('read_only') || perms.includes('trade'),
      canWithdraw: perms.includes('withdraw'),
      ipRestricted: ip.length > 0,
      permissions: perms,
      uid: config.uid ? String(config.uid) : null,
      email: null,
    };
  }

  async getCapabilities(context: ExchangeProviderContext): Promise<ExchangeCapabilityDiscovery> {
    return {
      venue: context.venue,
      environment: context.environment,
      capabilities: this.supportedCapabilities,
      supportedOrderTypes: [ExchangeOrderType.MARKET, ExchangeOrderType.LIMIT, ExchangeOrderType.LIMIT_MAKER, ExchangeOrderType.STOP, ExchangeOrderType.STOP_LIMIT],
      supportedEnvironments: this.supportedEnvironments,
      apiVersion: 'v5',
      restAvailable: true,
      websocketAvailable: true,
      rateLimitModel: 'REQUEST_COUNT',
      authenticationModel: 'HMAC_SHA256_PASSPHRASE',
      symbolFormat: 'BTC-USDT',
      timestamp: new Date().toISOString(),
    };
  }

  async getBalances(context: ExchangeProviderContext): Promise<ExchangeBalance[]> {
    const data = await this.privateGet(context, '/api/v5/account/balance');
    const details: any[] = Array.isArray(data[0]?.details) ? data[0].details : [];
    const timestampMicros = msToMicros(data[0]?.uTime) ?? nowMicros();
    return details
      .map((d) => {
        const free = dec(d.availBal);
        const locked = dec(d.frozenBal);
        const total = isDecimalString(d.cashBal) ? d.cashBal : addDecimalStrings(free, locked);
        return {
          asset: String(d.ccy),
          free,
          locked,
          total,
          providerReference: null,
          timestampMicros,
          source: 'REST',
          isSimulated: context.isSandbox,
        };
      })
      .filter((b) => b.total !== '0' || b.locked !== '0');
  }

  async getPositions(context: ExchangeProviderContext): Promise<ExchangePosition[]> {
    const data = await this.privateGet(context, '/api/v5/account/positions');
    return data
      .filter((p) => isDecimalString(p.pos) && signOfDecimalString(p.pos) !== 0)
      .map((p) => {
        let side: ExchangePositionSide;
        if (p.posSide === 'long') side = ExchangePositionSide.LONG;
        else if (p.posSide === 'short') side = ExchangePositionSide.SHORT;
        else side = signOfDecimalString(p.pos) > 0 ? ExchangePositionSide.LONG : ExchangePositionSide.SHORT;
        return {
          providerPositionId: p.posId ? String(p.posId) : null,
          symbol: okxCanonical(p.instId),
          exchangeSymbol: String(p.instId),
          side,
          quantity: absDecimalString(p.pos),
          entryPrice: decOrNull(p.avgPx),
          markPrice: decOrNull(p.markPx),
          liquidationPrice: decOrNull(p.liqPx),
          leverage: decOrNull(p.lever),
          unrealizedPnl: decOrNull(p.upl),
          realizedPnl: decOrNull(p.realizedPnl),
          timestampMicros: msToMicros(p.uTime) ?? nowMicros(),
          isSimulated: context.isSandbox,
        };
      });
  }

  async getOpenOrders(context: ExchangeProviderContext, symbol?: string): Promise<ExchangeOrder[]> {
    const params: Record<string, string | number | undefined> = { limit: 100 };
    if (symbol) {
      params.instId = symbol.toUpperCase();
      params.instType = instTypeOf(symbol);
    }
    const data = await this.privateGet(context, '/api/v5/trade/orders-pending', params);
    return data.map((o) => this.mapOrder(context, o));
  }

  async getOrderHistory(context: ExchangeProviderContext, symbol?: string, limit = 50): Promise<ExchangeOrder[]> {
    const instTypes: Array<'SPOT' | 'SWAP' | 'FUTURES' | 'OPTION'> = symbol ? [instTypeOf(symbol)] : ['SPOT', 'SWAP'];
    const rows: any[] = [];
    for (const instType of instTypes) {
      rows.push(...(await this.privateGet(context, '/api/v5/trade/orders-history', { instType, instId: symbol?.toUpperCase(), limit: Math.min(limit, 100) })));
    }
    return rows
      .map((o) => this.mapOrder(context, o))
      .sort((a, b) => Number(BigInt(b.createdAtMicros ?? '0') - BigInt(a.createdAtMicros ?? '0')))
      .slice(0, limit);
  }

  async getTradeHistory(context: ExchangeProviderContext, symbol?: string, limit = 50): Promise<ExchangeFill[]> {
    const params: Record<string, string | number | undefined> = { limit: Math.min(limit, 100) };
    if (symbol) {
      params.instId = symbol.toUpperCase();
      params.instType = instTypeOf(symbol);
    }
    const data = await this.privateGet(context, '/api/v5/trade/fills', params);
    return data.slice(0, limit).map((t) => ({
      providerTradeId: String(t.tradeId),
      providerOrderId: t.ordId ? String(t.ordId) : null,
      clientOrderId: t.clOrdId ? String(t.clOrdId) : null,
      symbol: okxCanonical(t.instId),
      side: t.side === 'buy' ? ExchangeOrderSide.BUY : ExchangeOrderSide.SELL,
      price: dec(t.fillPx),
      quantity: dec(t.fillSz),
      quoteQuantity: null,
      // OKX reports fees as negative numbers (a charge) and rebates as positive;
      // the platform's convention is a positive fee paid, so the sign flips.
      fee: isDecimalString(t.fee) ? (t.fee.startsWith('-') ? t.fee.slice(1) : t.fee === '0' ? '0' : `-${t.fee}`) : null,
      feeCurrency: t.feeCcy ? String(t.feeCcy) : null,
      isMaker: t.execType === 'M' ? true : t.execType === 'T' ? false : null,
      timestampMicros: msToMicros(t.ts) ?? nowMicros(),
      isSimulated: context.isSandbox,
    }));
  }

  async getSymbols(context: ExchangeProviderContext): Promise<ExchangeSymbol[]> {
    const data = await this.publicGet(context, '/api/v5/public/instruments', { instType: 'SPOT' });
    return data
      .filter((s) => s.state === 'live')
      .map((s) => ({
        canonicalSymbol: `${s.baseCcy}-${s.quoteCcy}`,
        exchangeSymbol: String(s.instId),
        baseAsset: String(s.baseCcy),
        quoteAsset: String(s.quoteCcy),
        contractType: 'SPOT',
        tickSize: String(s.tickSz),
        quantityStep: String(s.lotSz),
        minQuantity: decOrNull(s.minSz),
        maxQuantity: decOrNull(s.maxLmtSz),
        minNotional: null,
        maxNotional: null,
        pricePrecision: precisionOfStep(String(s.tickSz)),
        quantityPrecision: precisionOfStep(String(s.lotSz)),
        minLeverage: null,
        maxLeverage: null,
        isTradeable: true,
      }));
  }

  private mapOrder(context: ExchangeProviderContext, o: any): ExchangeOrder {
    const ordType = String(o.ordType);
    let type: ExchangeOrderType;
    if (ordType === 'market') type = ExchangeOrderType.MARKET;
    else if (ordType === 'post_only') type = ExchangeOrderType.LIMIT_MAKER;
    else type = ExchangeOrderType.LIMIT;
    const fee = isDecimalString(o.fee) ? (o.fee.startsWith('-') ? o.fee.slice(1) : o.fee === '0' ? '0' : `-${o.fee}`) : null;
    return {
      clientOrderId: o.clOrdId ? String(o.clOrdId) : String(o.ordId),
      providerOrderId: o.ordId ? String(o.ordId) : null,
      symbol: okxCanonical(o.instId),
      exchangeSymbol: String(o.instId),
      side: o.side === 'buy' ? ExchangeOrderSide.BUY : ExchangeOrderSide.SELL,
      type,
      status: OkxProvider.mapOrderStatus(String(o.state)),
      providerRawStatus: o.state ? String(o.state) : null,
      quantity: dec(o.sz),
      price: type === ExchangeOrderType.MARKET ? null : decOrNull(o.px),
      stopPrice: null,
      filledQuantity: dec(o.accFillSz),
      averagePrice: decOrNull(o.avgPx),
      fee,
      feeCurrency: o.feeCcy ? String(o.feeCcy) : null,
      createdAtMicros: msToMicros(o.cTime),
      updatedAtMicros: msToMicros(o.uTime),
      isSimulated: context.isSandbox,
    };
  }

  static mapOrderStatus(state: string): ExchangeOrderStatus {
    switch (state) {
      case 'live':
        return ExchangeOrderStatus.NEW;
      case 'partially_filled':
        return ExchangeOrderStatus.PARTIALLY_FILLED;
      case 'filled':
        return ExchangeOrderStatus.FILLED;
      case 'canceled':
      case 'mmp_canceled':
        return ExchangeOrderStatus.CANCELED;
      default:
        return ExchangeOrderStatus.NEW;
    }
  }
}

// # Responsibility: verifies live/paper mode selection, signing, and fail-closed behavior across venue adapters.
/**
 * Deterministic contract tests for the per-venue exchange providers
 * (Bybit, OKX, Kraken, Coinbase) and the provider factory registration.
 *
 * `fetch` is replaced by a routing fake, so every test exercises the real
 * signing, envelope classification, pagination and DTO mapping code without
 * network access. Signatures are checked against independent re-computations
 * of each venue's published algorithm.
 */
import { afterEach, describe, expect, jest, test } from '@jest/globals';
import * as crypto from 'crypto';
import { ExchangeEnvironment, ExchangeVenue, ExchangeOrderStatus, ExchangePositionSide, ExchangeOrderSide, ExchangeConnectionState, ExchangeOrderType } from '../exchange.types';
import { ExchangeProviderContext, ExchangeProviderError, ExchangeProviderErrorCode } from '../exchange-provider.interface';
import { BybitProvider } from './bybit.provider';
import { OkxProvider, okxCanonical } from './okx.provider';
import { KrakenProvider, krakenAsset, krakenPairParts, KRAKEN_WITHDRAW_PROBE_KEY } from './kraken.provider';
import { CoinbaseProvider, buildCoinbaseJwt, loadCoinbaseKey } from './coinbase.provider';
import { BybitProvider as RegisteredBybitProvider } from '../providers/bybit.provider';
import { OkxProvider as RegisteredOkxProvider } from '../providers/okx.provider';
import { KrakenProvider as RegisteredKrakenProvider } from '../providers/kraken.provider';
import { CoinbaseProvider as RegisteredCoinbaseProvider } from '../providers/coinbase.provider';
import { canonicalFromConcatenated, addDecimalStrings, subtractDecimalStrings } from '../base-exchange-provider';
import { ExchangeProviderFactory } from '../exchange-provider.factory';
import { ExchangeRegistryService } from '../exchange-registry.service';

type Route = (url: string, init: any) => { status?: number; body: any } | undefined;

interface FetchCall {
  url: string;
  method: string;
  headers: Record<string, string>;
  body?: string;
}

function installFetch(route: Route): FetchCall[] {
  const calls: FetchCall[] = [];
  jest.spyOn(global as any, 'fetch').mockImplementation(async (...args: any[]) => {
    const url = String(args[0]);
    const init = args[1] ?? {};
    calls.push({ url, method: init.method ?? 'GET', headers: init.headers ?? {}, body: init.body });
    const answer = route(url, init);
    if (!answer) throw new Error(`unrouted fetch ${url}`);
    const status = answer.status ?? 200;
    const text = typeof answer.body === 'string' ? answer.body : JSON.stringify(answer.body);
    return {
      ok: status >= 200 && status < 300,
      status,
      statusText: String(status),
      headers: new Map<string, string>(),
      text: async () => text,
    } as any;
  });
  return calls;
}

function ctx(venue: ExchangeVenue, environment: ExchangeEnvironment, passphrase?: string, secret = 'test-secret'): ExchangeProviderContext {
  return {
    tenantId: 'tenant-1',
    accountId: 'acct-1',
    venue,
    environment,
    isSandbox: environment !== ExchangeEnvironment.LIVE,
    credentials: { apiKey: 'test-key', apiSecret: secret, passphrase } as any,
    credentialRef: null,
  };
}

async function expectCode(promise: Promise<unknown>, code: ExchangeProviderErrorCode): Promise<void> {
  let caught: unknown;
  try {
    await promise;
  } catch (e) {
    caught = e;
  }
  expect(caught).toBeInstanceOf(ExchangeProviderError);
  expect((caught as ExchangeProviderError).code).toBe(code);
}

