import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { GovernancePolicyService } from './governance-policy.service';
import { REPORT_DEFINITIONS } from './templates/report-definitions';

export interface ReportTemplate {
  reportType: string;
  jurisdiction: string;
  templateVersion: string;
  schemaVersion: string;
  requiredFields: string[];
  sourceSystems: string[];
  periodType: 'DAILY' | 'MONTHLY' | 'QUARTERLY' | 'YEARLY' | 'ADHOC';
  methodology: string;
  calculationVersion: string;
  requiresCertification: boolean;
  requiresApproval: boolean;
  deliveryChannels: string[];
  policyVersion: string;
  validationRules: string[];
}

@Injectable()
export class ComplianceReportTemplateService {
  private readonly logger = new Logger(ComplianceReportTemplateService.name);

  constructor(
    private readonly policyService: GovernancePolicyService,
    private readonly config: ConfigService,
  ) {}

  getTemplate(reportType: string, jurisdiction: string): ReportTemplate {
    this.policyService.validateJurisdiction(jurisdiction);
    const j = jurisdiction.toUpperCase();
    const key = `${reportType}_${j}`;
    const specific = (REPORT_DEFINITIONS as any)[key];
    const generic = (REPORT_DEFINITIONS as any)[reportType];

    const def = specific ?? generic;
    if (!def) throw new BadRequestException(`no template for reportType ${reportType} jurisdiction ${j}`);

    const policy = this.policyService.buildPolicy(null, j);
    const requirement = policy.reportRequirements.find((r) => r.reportType === reportType);

    return {
      reportType,
      jurisdiction: j,
      templateVersion: def.templateVersion ?? `1.0.0_${policy.policyVersion}`,
      schemaVersion: def.schemaVersion ?? '2026-01',
      requiredFields: requirement?.requiredFields ?? def.requiredFields ?? ['tenantId', 'periodStart', 'periodEnd', 'sourceReferences', 'methodology', 'policyVersion'],
      sourceSystems: requirement?.sourceSystems ?? def.sourceSystems ?? ['Audit'],
      periodType: def.periodType ?? 'MONTHLY',
      methodology: def.methodology ?? `AUTHORITATIVE_AGGREGATION_FROM_${(requirement?.sourceSystems ?? def.sourceSystems ?? ['Audit']).join('_')}_POLICY_${policy.policyVersion}`,
      calculationVersion: def.calculationVersion ?? `calc_${policy.policyVersion}`,
      requiresCertification: requirement?.requiresCertification ?? def.requiresCertification ?? true,
      requiresApproval: requirement?.requiresApproval ?? true,
      deliveryChannels: requirement?.deliveryChannels ?? def.deliveryChannels ?? ['INTERNAL_STORAGE'],
      policyVersion: policy.policyVersion,
      validationRules: def.validationRules ?? ['SOURCE_COMPLETENESS', 'PERIOD_COMPLETENESS', 'RECONCILIATION_RESOLVED', 'FINGERPRINT_DETERMINISTIC'],
    };
  }

  listTemplates(jurisdiction?: string): ReportTemplate[] {
    const jurisdictions = jurisdiction ? [jurisdiction.toUpperCase()] : this.policyService.getSupportedJurisdictions();
    const templates: ReportTemplate[] = [];
    for (const defKey of Object.keys(REPORT_DEFINITIONS)) {
      // defKey may be reportType or reportType_JURISDICTION
      const parts = defKey.split('_');
      const reportType = parts[0].includes('REPORT') || parts[0].includes('SUMMARY') || parts[0].includes('STATEMENT') || parts[0].includes('TRAIL') || parts[0].includes('INCIDENT') || parts[0].includes('GOVERNANCE') ? defKey : parts[0];
      // Actually REPORT_DEFINITIONS keys are report types, not composite. Simplify:
    }
    for (const rt of Object.keys(REPORT_DEFINITIONS)) {
      for (const j of jurisdictions) {
        try {
          templates.push(this.getTemplate(rt, j));
        } catch {
          /* ignore */
        }
      }
    }
    return templates;
  }

  validateTemplate(reportType: string, jurisdiction: string): boolean {
    try {
      this.getTemplate(reportType, jurisdiction);
      return true;
    } catch {
      return false;
    }
  }
}

// # Responsibility: verifies consent capture and withdrawal are durable before success or audit events are returned.
import { ServiceUnavailableException } from '@nestjs/common';
import { ConsentService } from './consent.service';
import { ConsentState, GovernanceActionType } from './governance.types';

describe('ConsentService durable consent lifecycle', () => {
  function buildService(options?: {
    create?: jest.Mock;
    findUnique?: jest.Mock;
    findMany?: jest.Mock;
    update?: jest.Mock;
  }) {
    const consentRecord = {
      create: options?.create ?? jest.fn(async ({ data }) => data),
      findUnique: options?.findUnique ?? jest.fn(async () => null),
      findMany: options?.findMany ?? jest.fn(async () => []),
      update: options?.update ?? jest.fn(async ({ where, data }) => ({ id: where.id, ...data })),
    };
    const prisma = { consentRecord };
    const policyService = { assertTenantIsolation: jest.fn() };
    const audit = { recordEvent: jest.fn(async () => undefined) };
    const service = new ConsentService(policyService as any, audit as any, prisma as any);
    return { service, prisma, policyService, audit };
  }

  function captureInput() {
    return {
      tenantId: 'tenant-a',
      subjectUserId: 'user-a',
      purpose: 'COPY_TRADING_RISK_DISCLOSURE',
      version: '2026-10-v1',
      policyReference: 'sha256:document-hash',
      source: 'WEB_CHECKBOX',
      correlationId: 'consent-correlation-a',
      capturedBy: 'user-a',
      evidenceReference: 'consent-page-v1',
    };
  }

  test('captures and audits a consent only after the database insert returns a durable row', async () => {
    const { service, prisma, audit } = buildService();

    const result = await service.captureConsent(captureInput());

    expect(prisma.consentRecord.create).toHaveBeenCalledWith(expect.objectContaining({
      data: expect.objectContaining({
        tenantId: 'tenant-a',
        subjectUserId: 'user-a',
        purpose: 'COPY_TRADING_RISK_DISCLOSURE',
        version: '2026-10-v1',
        policyReference: 'sha256:document-hash',
      }),
    }));
    expect(result).toMatchObject({
      tenantId: 'tenant-a',
      subjectUserId: 'user-a',
      version: '2026-10-v1',
      status: ConsentState.ACTIVE,
    });
    expect(audit.recordEvent).toHaveBeenCalledWith(expect.objectContaining({
      actionType: GovernanceActionType.CONSENT_CAPTURE,
      consentId: result.id,
      result: 'CAPTURED',
    }));
  });

  test('does not return, cache, or audit consent success when persistence fails', async () => {
    const create = jest.fn(async () => { throw new Error('database unavailable'); });
    const findMany = jest.fn(async () => []);
    const { service, audit } = buildService({ create, findMany });

    await expect(service.captureConsent(captureInput())).rejects.toBeInstanceOf(ServiceUnavailableException);
    expect(audit.recordEvent).not.toHaveBeenCalled();
    await expect(service.listConsents('tenant-a', 'user-a')).resolves.toEqual([]);
  });

  test('does not claim consent withdrawal when the durable update fails', async () => {
    const capturedAt = new Date('2026-10-01T00:00:00.000Z');
    const activeRow = {
      id: 'consent-existing',
      tenantId: 'tenant-a',
      subjectUserId: 'user-a',
      purpose: 'COPY_TRADING_RISK_DISCLOSURE',
      version: '2026-10-v1',
      policyReference: 'sha256:document-hash',
      source: 'WEB_CHECKBOX',
      capturedAt,
      withdrawnAt: null,
      status: ConsentState.ACTIVE,
      evidenceReference: 'consent-page-v1',
      correlationId: 'consent-correlation-a',
    };
    const findUnique = jest.fn(async () => activeRow);
    const findMany = jest.fn(async () => [activeRow]);
    const update = jest.fn(async () => { throw new Error('database unavailable'); });
    const { service, audit } = buildService({ findUnique, findMany, update });

    await expect(service.withdrawConsent({
      tenantId: 'tenant-a',
      consentId: 'consent-existing',
      subjectUserId: 'user-a',
      correlationId: 'withdraw-correlation-a',
      withdrawnBy: 'user-a',
      reason: 'User withdrew consent',
    })).rejects.toBeInstanceOf(ServiceUnavailableException);

    expect(update).toHaveBeenCalledWith(expect.objectContaining({
      where: expect.objectContaining({
        id: 'consent-existing',
        tenantId: 'tenant-a',
        subjectUserId: 'user-a',
        status: ConsentState.ACTIVE,
      }),
      data: expect.objectContaining({ status: ConsentState.WITHDRAWN }),
    }));
    expect(audit.recordEvent).not.toHaveBeenCalled();
    await expect(service.listConsents('tenant-a', 'user-a')).resolves.toEqual([
      expect.objectContaining({ id: 'consent-existing', status: ConsentState.ACTIVE }),
    ]);
  });

  test('fails closed when the durable withdrawal lookup is unavailable', async () => {
    const findUnique = jest.fn(async () => { throw new Error('database unavailable'); });
    const update = jest.fn();
    const { service, audit } = buildService({ findUnique, update });

    await expect(service.withdrawConsent({
      tenantId: 'tenant-a',
      consentId: 'consent-existing',
      subjectUserId: 'user-a',
      correlationId: 'withdraw-correlation-b',
      withdrawnBy: 'user-a',
    })).rejects.toBeInstanceOf(ServiceUnavailableException);

    expect(findUnique).toHaveBeenCalledWith({ where: { id: 'consent-existing', tenantId: 'tenant-a' } });
    expect(update).not.toHaveBeenCalled();
    expect(audit.recordEvent).not.toHaveBeenCalled();
  });

  test('does not return an in-memory consent list when durable listing fails', async () => {
    const findMany = jest.fn(async () => { throw new Error('database unavailable'); });
    const { service } = buildService({ findMany });

    await expect(service.listConsents('tenant-a', 'user-a')).rejects.toBeInstanceOf(ServiceUnavailableException);
  });
});

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { DataClassification } from './governance.types';
import { GovernancePolicyService } from './governance-policy.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

export interface DataClassificationRecord {
  id: string;
  tenantId: string;
  sourceSystem: string;
  sourceTable: string;
  sourceField: string;
  dataClass: DataClassification;
  jurisdiction: string;
  sensitivityScore: number;
  piiFlag: boolean;
  regulatedFlag: boolean;
  classifiedAt: string;
  classifiedBy: string;
  policyVersion: string;
  correlationId: string;
}

@Injectable()
export class DataClassificationService {
  private readonly logger = new Logger(DataClassificationService.name);
  private readonly classificationRules: Map<string, DataClassification>;

  constructor(
    private readonly config: ConfigService,
    private readonly policyService: GovernancePolicyService,
    private readonly prisma: PrismaService,
  ) {
    this.classificationRules = this.buildRules();
  }

  private buildRules(): Map<string, DataClassification> {
    const map = new Map<string, DataClassification>();
    map.set('email', DataClassification.PII);
    map.set('phone', DataClassification.PII);
    map.set('address', DataClassification.PII);
    map.set('government_id_reference', DataClassification.KYC_SENSITIVE);
    map.set('identity_reference', DataClassification.KYC_SENSITIVE);
    map.set('kyc_metadata', DataClassification.KYC_SENSITIVE);
    map.set('kyc_document_reference', DataClassification.KYC_SENSITIVE);
    map.set('aml_evidence', DataClassification.REGULATED);
    map.set('compliance_case_reference', DataClassification.REGULATED);
    map.set('transaction_reference', DataClassification.FINANCIAL);
    map.set('invoice_reference', DataClassification.FINANCIAL);
    map.set('billing_ledger_reference', DataClassification.FINANCIAL);
    map.set('portfolio_position', DataClassification.FINANCIAL);
    map.set('balance_reference', DataClassification.FINANCIAL);
    map.set('payment_metadata', DataClassification.FINANCIAL);
    map.set('password_hash', DataClassification.SECURITY_SENSITIVE);
    map.set('secret_reference', DataClassification.SECURITY_SENSITIVE);
    map.set('api_key_reference', DataClassification.SECURITY_SENSITIVE);
    map.set('session_information', DataClassification.SECURITY_SENSITIVE);
    map.set('device_information', DataClassification.SECURITY_SENSITIVE);
    map.set('ip_address', DataClassification.PII);
    map.set('withdrawal_destination', DataClassification.FINANCIAL);
    return map;
  }

  classifyField(fieldName: string, sourceSystem: string): DataClassification {
    if (!fieldName) throw new BadRequestException('fieldName required');
    const normalized = fieldName.toLowerCase().trim();
    if (this.classificationRules.has(normalized)) {
      return this.classificationRules.get(normalized)!;
    }
    if (normalized.includes('email') || normalized.includes('phone') || normalized.includes('pii')) return DataClassification.PII;
    if (normalized.includes('kyc') || normalized.includes('government') || normalized.includes('identity')) return DataClassification.KYC_SENSITIVE;
    if (normalized.includes('transaction') || normalized.includes('balance') || normalized.includes('invoice') || normalized.includes('ledger') || normalized.includes('portfolio')) return DataClassification.FINANCIAL;
    if (normalized.includes('aml') || normalized.includes('compliance') || normalized.includes('audit') || normalized.includes('regulatory')) return DataClassification.REGULATED;
    if (normalized.includes('password') || normalized.includes('secret') || normalized.includes('key') || normalized.includes('token') || normalized.includes('credential')) return DataClassification.SECURITY_SENSITIVE;
    return DataClassification.INTERNAL;
  }

  async classifyRecord(params: {
    tenantId: string;
    sourceSystem: string;
    sourceTable: string;
    sourceField: string;
    jurisdiction: string;
    correlationId: string;
    classifiedBy: string;
  }): Promise<DataClassificationRecord> {
    this.policyService.validateJurisdiction(params.jurisdiction);
    if (!params.tenantId) throw new BadRequestException('tenantId required');
    const dataClass = this.classifyField(params.sourceField, params.sourceSystem);
    const record: DataClassificationRecord = {
      id: `dcls_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      tenantId: params.tenantId,
      sourceSystem: params.sourceSystem,
      sourceTable: params.sourceTable,
      sourceField: params.sourceField,
      dataClass,
      jurisdiction: params.jurisdiction.toUpperCase(),
      sensitivityScore: this.sensitivityScore(dataClass),
      piiFlag: dataClass === DataClassification.PII || dataClass === DataClassification.KYC_SENSITIVE,
      regulatedFlag: [DataClassification.FINANCIAL, DataClassification.REGULATED, DataClassification.KYC_SENSITIVE].includes(dataClass),
      classifiedAt: new Date().toISOString(),
      classifiedBy: params.classifiedBy,
      policyVersion: this.policyService.getPolicyVersion(),
      correlationId: params.correlationId,
    };

    try {
      await (this.prisma as any).governanceDataClassification?.create?.({
        data: {
          id: record.id,
          tenantId: record.tenantId,
          sourceSystem: record.sourceSystem,
          sourceTable: record.sourceTable,
          sourceField: record.sourceField,
          dataClass: record.dataClass,
          jurisdiction: record.jurisdiction,
          sensitivityScore: record.sensitivityScore,
          piiFlag: record.piiFlag,
          regulatedFlag: record.regulatedFlag,
          classifiedAt: new Date(record.classifiedAt),
          classifiedBy: record.classifiedBy,
          policyVersion: record.policyVersion,
          correlationId: record.correlationId,
        },
      });
    } catch {
      this.logger.debug(`classification persist skipped id=${record.id}`);
    }

    this.logger.log(`classified tenant=${params.tenantId} field=${params.sourceField} class=${dataClass} corr=${params.correlationId}`);
    return record;
  }

  private sensitivityScore(dc: DataClassification): number {
    switch (dc) {
      case DataClassification.PUBLIC:
        return 10;
      case DataClassification.INTERNAL:
        return 30;
      case DataClassification.CONFIDENTIAL:
        return 60;
      case DataClassification.PII:
        return 80;
      case DataClassification.FINANCIAL:
        return 85;
      case DataClassification.KYC_SENSITIVE:
        return 90;
      case DataClassification.SECURITY_SENSITIVE:
        return 95;
      case DataClassification.REGULATED:
        return 90;
      case DataClassification.RESTRICTED:
        return 95;
      default:
        return 50;
    }
  }

  async listClassifications(tenantId: string): Promise<DataClassificationRecord[]> {
    if (!tenantId) throw new BadRequestException('tenantId required');
    try {
      const rows = await (this.prisma as any).governanceDataClassification?.findMany?.({
        where: { tenantId },
        orderBy: { classifiedAt: 'desc' },
        take: 500,
      });
      if (rows) {
        return rows.map((r: any) => ({
          id: r.id,
          tenantId: r.tenantId,
          sourceSystem: r.sourceSystem,
          sourceTable: r.sourceTable,
          sourceField: r.sourceField,
          dataClass: r.dataClass,
          jurisdiction: r.jurisdiction,
          sensitivityScore: r.sensitivityScore,
          piiFlag: r.piiFlag,
          regulatedFlag: r.regulatedFlag,
          classifiedAt: r.classifiedAt instanceof Date ? r.classifiedAt.toISOString() : r.classifiedAt,
          classifiedBy: r.classifiedBy,
          policyVersion: r.policyVersion,
          correlationId: r.correlationId,
        }));
      }
    } catch {
      this.logger.debug(`listClassifications fallback tenant=${tenantId}`);
    }
    return [];
  }

  isExportAllowed(dataClass: DataClassification, policy: { exportEligibility: Record<DataClassification, boolean> }): boolean {
    return policy.exportEligibility[dataClass] ?? false;
  }

  isDeletionConstrained(dataClass: DataClassification, policy: { deletionConstraints: Record<DataClassification, boolean> }): boolean {
    return policy.deletionConstraints[dataClass] ?? true;
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { DataClassification } from './governance.types';
import { DataClassificationService } from './data-classification.service';
import { GovernancePolicyService } from './governance-policy.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

export interface DataInventoryRecord {
  id: string;
  tenantId: string;
  subjectUserId?: string | null;
  sourceSystem: string;
  sourceTable: string;
  sourceId: string;
  dataClasses: DataClassification[];
  jurisdiction: string;
  retentionStartAt: string;
  locationReference: string;
  recordHash: string;
  correlationId: string;
  lastSeenAt: string;
  policyVersion: string;
}

@Injectable()
export class DataInventoryService {
  private readonly logger = new Logger(DataInventoryService.name);

  constructor(
    private readonly classificationService: DataClassificationService,
    private readonly policyService: GovernancePolicyService,
    private readonly prisma: PrismaService,
  ) {}

  async upsertInventory(params: {
    tenantId: string;
    subjectUserId?: string;
    sourceSystem: string;
    sourceTable: string;
    sourceId: string;
    fields: string[];
    jurisdiction: string;
    locationReference: string;
    correlationId: string;
  }): Promise<DataInventoryRecord> {
    if (!params.tenantId) throw new BadRequestException('tenantId required');
    if (!params.sourceId) throw new BadRequestException('sourceId required');
    this.policyService.validateJurisdiction(params.jurisdiction);

    const dataClasses = params.fields.map((f) => this.classificationService.classifyField(f, params.sourceSystem));
    const unique = [...new Set(dataClasses)];

    const record: DataInventoryRecord = {
      id: `dinv_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      tenantId: params.tenantId,
      subjectUserId: params.subjectUserId ?? null,
      sourceSystem: params.sourceSystem,
      sourceTable: params.sourceTable,
      sourceId: params.sourceId,
      dataClasses: unique,
      jurisdiction: params.jurisdiction.toUpperCase(),
      retentionStartAt: new Date().toISOString(),
      locationReference: params.locationReference,
      recordHash: this.hashLocation(params.locationReference + params.sourceId),
      correlationId: params.correlationId,
      lastSeenAt: new Date().toISOString(),
      policyVersion: this.policyService.getPolicyVersion(),
    };

    try {
      await (this.prisma as any).governanceDataInventory?.upsert?.({
        where: { tenantId_sourceSystem_sourceId: { tenantId: params.tenantId, sourceSystem: params.sourceSystem, sourceId: params.sourceId } },
        create: {
          id: record.id,
          tenantId: record.tenantId,
          subjectUserId: record.subjectUserId,
          sourceSystem: record.sourceSystem,
          sourceTable: record.sourceTable,
          sourceId: record.sourceId,
          dataClasses: record.dataClasses,
          jurisdiction: record.jurisdiction,
          retentionStartAt: new Date(record.retentionStartAt),
          locationReference: record.locationReference,
          recordHash: record.recordHash,
          correlationId: record.correlationId,
          lastSeenAt: new Date(record.lastSeenAt),
          policyVersion: record.policyVersion,
        },
        update: {
          dataClasses: record.dataClasses,
          jurisdiction: record.jurisdiction,
          lastSeenAt: new Date(record.lastSeenAt),
          correlationId: record.correlationId,
        },
      });
    } catch {
      this.logger.debug(`inventory persist skipped tenant=${params.tenantId} sourceId=${params.sourceId}`);
    }

    this.logger.log(`inventory upsert tenant=${params.tenantId} source=${params.sourceSystem}/${params.sourceTable} corr=${params.correlationId}`);
    return record;
  }

  private hashLocation(input: string): string {
    let hash = 0;
    for (let i = 0; i < input.length; i++) {
      hash = (hash * 31 + input.charCodeAt(i)) >>> 0;
    }
    return `sha_${hash.toString(16)}`;
  }

  async listForSubject(tenantId: string, subjectUserId: string): Promise<DataInventoryRecord[]> {
    if (!tenantId || !subjectUserId) throw new BadRequestException('tenantId and subjectUserId required');
    try {
      const rows = await (this.prisma as any).governanceDataInventory?.findMany?.({
        where: { tenantId, subjectUserId },
        take: 1000,
        orderBy: { lastSeenAt: 'desc' },
      });
      if (rows) {
        return rows.map((r: any) => ({
          id: r.id,
          tenantId: r.tenantId,
          subjectUserId: r.subjectUserId,
          sourceSystem: r.sourceSystem,
          sourceTable: r.sourceTable,
          sourceId: r.sourceId,
          dataClasses: r.dataClasses,
          jurisdiction: r.jurisdiction,
          retentionStartAt: r.retentionStartAt instanceof Date ? r.retentionStartAt.toISOString() : r.retentionStartAt,
          locationReference: r.locationReference,
          recordHash: r.recordHash,
          correlationId: r.correlationId,
          lastSeenAt: r.lastSeenAt instanceof Date ? r.lastSeenAt.toISOString() : r.lastSeenAt,
          policyVersion: r.policyVersion,
        }));
      }
    } catch {
      this.logger.debug(`listForSubject fallback tenant=${tenantId}`);
    }
    return [];
  }

  async listForTenant(tenantId: string, filters?: { dataClass?: DataClassification; sourceSystem?: string }): Promise<DataInventoryRecord[]> {
    if (!tenantId) throw new BadRequestException('tenantId required');
    try {
      const where: any = { tenantId };
      if (filters?.sourceSystem) where.sourceSystem = filters.sourceSystem;
      const rows = await (this.prisma as any).governanceDataInventory?.findMany?.({
        where,
        take: 1000,
        orderBy: { lastSeenAt: 'desc' },
      });
      if (rows) {
        let mapped = rows.map((r: any) => ({
          id: r.id,
          tenantId: r.tenantId,
          subjectUserId: r.subjectUserId,
          sourceSystem: r.sourceSystem,
          sourceTable: r.sourceTable,
          sourceId: r.sourceId,
          dataClasses: r.dataClasses,
          jurisdiction: r.jurisdiction,
          retentionStartAt: r.retentionStartAt instanceof Date ? r.retentionStartAt.toISOString() : r.retentionStartAt,
          locationReference: r.locationReference,
          recordHash: r.recordHash,
          correlationId: r.correlationId,
          lastSeenAt: r.lastSeenAt instanceof Date ? r.lastSeenAt.toISOString() : r.lastSeenAt,
          policyVersion: r.policyVersion,
        }));
        if (filters?.dataClass) {
          mapped = mapped.filter((m: DataInventoryRecord) => m.dataClasses.includes(filters.dataClass!));
        }
        return mapped;
      }
    } catch {
      this.logger.debug(`listForTenant fallback tenant=${tenantId}`);
    }
    return [];
  }
}

import { Injectable, Logger, BadRequestException, NotFoundException } from '@nestjs/common';
import { EvidencePackage, EvidenceState, GovernanceActionType, AUTHORITATIVE_SOURCE_SYSTEMS } from './governance.types';
import { GovernancePolicyService } from './governance-policy.service';
import { GovernanceAuditService } from './governance-audit.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import * as crypto from 'crypto';

@Injectable()
export class EvidencePackageService {
  private readonly logger = new Logger(EvidencePackageService.name);
  private readonly inMemory: Map<string, EvidencePackage> = new Map();

  constructor(
    private readonly policyService: GovernancePolicyService,
    private readonly audit: GovernanceAuditService,
    private readonly prisma: PrismaService,
  ) {}

  async createPackage(params: {
    tenantId: string;
    caseReference: string;
    evidenceType: string;
    sourceRecords: string[];
    sourceReferences: string[];
    redactionPolicy: string;
    generator: string;
    correlationId: string;
    createdBy: string;
    auditReference?: string;
  }): Promise<EvidencePackage> {
    if (!params.tenantId || !params.caseReference || !params.evidenceType) throw new BadRequestException('tenantId, caseReference, evidenceType required');
    if (!params.sourceRecords || params.sourceRecords.length === 0) throw new BadRequestException('sourceRecords required');

    // Validate source references come from authoritative systems
    for (const ref of params.sourceReferences) {
      const system = ref.split(':')[0];
      if (system && !AUTHORITATIVE_SOURCE_SYSTEMS.includes(system as any) && system !== 'ClientProfile' && system !== 'Users') {
        // Allow any prefix that is in authoritative list, but log warning for unknown
        this.logger.warn(`evidence source reference ${ref} not in authoritative list corr=${params.correlationId}`);
      }
    }

    const fingerprint = crypto
      .createHash('sha256')
      .update(JSON.stringify({ tenantId: params.tenantId, caseReference: params.caseReference, sourceRecords: [...params.sourceRecords].sort(), policyVersion: this.policyService.getPolicyVersion() }))
      .digest('hex');

    const pkg: EvidencePackage = {
      id: `evp_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      tenantId: params.tenantId,
      caseReference: params.caseReference,
      evidenceType: params.evidenceType,
      state: EvidenceState.DRAFT,
      sourceRecords: params.sourceRecords,
      sourceReferences: params.sourceReferences,
      recordCount: params.sourceRecords.length,
      generatedAt: new Date().toISOString(),
      finalizedAt: null,
      fileLocation: `governance/evidence/${params.tenantId}/${params.caseReference}/${Date.now()}.json`,
      fileHash: fingerprint,
      fingerprint,
      redactionPolicy: params.redactionPolicy,
      generator: params.generator,
      auditReference: params.auditReference ?? null,
      policyVersion: this.policyService.getPolicyVersion(),
      correlationId: params.correlationId,
      isImmutable: false,
    };

    this.inMemory.set(pkg.id, pkg);
    try {
      await (this.prisma as any).evidencePackage?.create?.({
        data: {
          id: pkg.id,
          tenantId: pkg.tenantId,
          caseReference: pkg.caseReference,
          evidenceType: pkg.evidenceType,
          state: pkg.state,
          sourceRecords: pkg.sourceRecords,
          sourceReferences: pkg.sourceReferences,
          recordCount: pkg.recordCount,
          generatedAt: new Date(pkg.generatedAt),
          fileLocation: pkg.fileLocation,
          fileHash: pkg.fileHash,
          fingerprint: pkg.fingerprint,
          redactionPolicy: pkg.redactionPolicy,
          generator: pkg.generator,
          auditReference: pkg.auditReference,
          policyVersion: pkg.policyVersion,
          correlationId: pkg.correlationId,
          isImmutable: pkg.isImmutable,
        },
      });
    } catch {
      this.logger.debug(`evidence persist skipped id=${pkg.id}`);
    }

    await this.audit.recordEvent({
      tenantId: params.tenantId,
      actionType: GovernanceActionType.EVIDENCE_PACKAGE_CREATE,
      evidencePackageId: pkg.id,
      state: pkg.state,
      result: 'CREATED',
      correlationId: params.correlationId,
      createdBy: params.createdBy,
      safeEvidence: { caseReference: params.caseReference, evidenceType: params.evidenceType, recordCount: pkg.recordCount, fingerprint },
    });

    this.logger.log(`evidence package created id=${pkg.id} case=${params.caseReference} corr=${params.correlationId}`);
    return pkg;
  }

  async finalizePackage(params: { tenantId: string; packageId: string; correlationId: string; operatorId: string }): Promise<EvidencePackage> {
    const pkg = await this.getPackage(params.tenantId, params.packageId);
    if (pkg.isImmutable) throw new BadRequestException('evidence package already immutable');
    if (pkg.state === EvidenceState.FINALIZED) throw new BadRequestException('already finalized');

    pkg.state = EvidenceState.FINALIZED;
    pkg.finalizedAt = new Date().toISOString();
    pkg.isImmutable = true;

    this.inMemory.set(pkg.id, pkg);
    try {
      await (this.prisma as any).evidencePackage?.update?.({
        where: { id: pkg.id },
        data: { state: pkg.state, finalizedAt: new Date(pkg.finalizedAt), isImmutable: true },
      });
    } catch {
      this.logger.debug(`evidence finalize persist skipped id=${pkg.id}`);
    }

    await this.audit.recordEvent({
      tenantId: params.tenantId,
      actionType: GovernanceActionType.EVIDENCE_PACKAGE_FINALIZE,
      evidencePackageId: pkg.id,
      state: pkg.state,
      result: 'FINALIZED',
      correlationId: params.correlationId,
      createdBy: params.operatorId,
      safeEvidence: { caseReference: pkg.caseReference, fingerprint: pkg.fingerprint, recordCount: pkg.recordCount },
    });

    this.logger.log(`evidence package finalized id=${pkg.id} corr=${params.correlationId}`);
    return pkg;
  }

  async getPackage(tenantId: string, packageId: string): Promise<EvidencePackage> {
    const mem = this.inMemory.get(packageId);
    if (mem) {
      this.policyService.assertTenantIsolation(tenantId, mem.tenantId);
      return mem;
    }
    try {
      const row = await (this.prisma as any).evidencePackage?.findUnique?.({ where: { id: packageId } });
      if (row) {
        this.policyService.assertTenantIsolation(tenantId, row.tenantId);
        const mapped = this.mapRow(row);
        this.inMemory.set(mapped.id, mapped);
        return mapped;
      }
    } catch {
      /* ignore */
    }
    throw new NotFoundException(`evidence package ${packageId} not found`);
  }

  async listPackages(tenantId: string, filters?: { caseReference?: string; evidenceType?: string; state?: EvidenceState }): Promise<EvidencePackage[]> {
    let list = [...this.inMemory.values()].filter((p) => p.tenantId === tenantId);
    if (filters?.caseReference) list = list.filter((p) => p.caseReference === filters.caseReference);
    if (filters?.evidenceType) list = list.filter((p) => p.evidenceType === filters.evidenceType);
    if (filters?.state) list = list.filter((p) => p.state === filters.state);
    try {
      const where: any = { tenantId };
      if (filters?.caseReference) where.caseReference = filters.caseReference;
      if (filters?.evidenceType) where.evidenceType = filters.evidenceType;
      if (filters?.state) where.state = filters.state;
      const rows = await (this.prisma as any).evidencePackage?.findMany?.({ where, take: 500, orderBy: { generatedAt: 'desc' } });
      if (rows && rows.length > 0) list = rows.map((r: any) => this.mapRow(r));
    } catch {
      /* ignore */
    }
    return list;
  }

  async assertImmutable(tenantId: string, packageId: string): Promise<void> {
    const pkg = await this.getPackage(tenantId, packageId);
    if (!pkg.isImmutable) throw new BadRequestException('evidence package not immutable yet');
  }

  private mapRow(row: any): EvidencePackage {
    return {
      id: row.id,
      tenantId: row.tenantId,
      caseReference: row.caseReference,
      evidenceType: row.evidenceType,
      state: row.state,
      sourceRecords: row.sourceRecords ?? [],
      sourceReferences: row.sourceReferences ?? [],
      recordCount: row.recordCount ?? 0,
      generatedAt: row.generatedAt instanceof Date ? row.generatedAt.toISOString() : row.generatedAt,
      finalizedAt: row.finalizedAt ? (row.finalizedAt instanceof Date ? row.finalizedAt.toISOString() : row.finalizedAt) : null,
      fileLocation: row.fileLocation ?? null,
      fileHash: row.fileHash ?? null,
      fingerprint: row.fingerprint,
      redactionPolicy: row.redactionPolicy,
      generator: row.generator,
      auditReference: row.auditReference ?? null,
      policyVersion: row.policyVersion,
      correlationId: row.correlationId,
      isImmutable: !!row.isImmutable,
    };
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { GovernanceActionType } from './governance.types';
import { GovernanceAuditService } from './governance-audit.service';
import { GovernancePolicyService } from './governance-policy.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

export interface GovernanceAction {
  id: string;
  tenantId: string;
  actionType: GovernanceActionType;
  entityId?: string;
  requestedBy: string;
  approvedBy?: string | null;
  state: 'REQUESTED' | 'APPROVED' | 'REJECTED' | 'EXECUTED' | 'FAILED';
  reason?: string | null;
  correlationId: string;
  createdAt: string;
  updatedAt: string;
  safeParams: Record<string, unknown>;
}

@Injectable()
export class GovernanceActionService {
  private readonly logger = new Logger(GovernanceActionService.name);
  private readonly inMemory: Map<string, GovernanceAction> = new Map();

  constructor(
    private readonly audit: GovernanceAuditService,
    private readonly policyService: GovernancePolicyService,
    private readonly prisma: PrismaService,
  ) {}

  async requestAction(params: {
    tenantId: string;
    actionType: GovernanceActionType;
    entityId?: string;
    requestedBy: string;
    correlationId: string;
    reason?: string;
    safeParams?: Record<string, unknown>;
  }): Promise<GovernanceAction> {
    if (!params.tenantId || !params.actionType || !params.requestedBy || !params.correlationId) {
      throw new BadRequestException('tenantId, actionType, requestedBy, correlationId required');
    }

    const policy = this.policyService.buildPolicy(params.tenantId, 'US');
    const approvalReq = policy.approvalRequirements.find((a) => a.actionType === params.actionType);

    const action: GovernanceAction = {
      id: `gact_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      tenantId: params.tenantId,
      actionType: params.actionType,
      entityId: params.entityId,
      requestedBy: params.requestedBy,
      approvedBy: null,
      state: approvalReq ? 'REQUESTED' : 'APPROVED',
      reason: params.reason ?? null,
      correlationId: params.correlationId,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      safeParams: params.safeParams ? this.policyService.sanitizeLogEvidence(params.safeParams) : {},
    };

    this.inMemory.set(action.id, action);
    try {
      await (this.prisma as any).governanceAction?.create?.({
        data: {
          id: action.id,
          tenantId: action.tenantId,
          actionType: action.actionType,
          entityId: action.entityId,
          requestedBy: action.requestedBy,
          state: action.state,
          reason: action.reason,
          correlationId: action.correlationId,
          createdAt: new Date(action.createdAt),
          updatedAt: new Date(action.updatedAt),
          safeParams: action.safeParams as any,
        },
      });
    } catch {
      this.logger.debug(`governanceAction persist skipped id=${action.id}`);
    }

    await this.audit.recordEvent({
      tenantId: params.tenantId,
      actionType: params.actionType,
      state: action.state,
      result: 'REQUESTED',
      correlationId: params.correlationId,
      createdBy: params.requestedBy,
      safeEvidence: { actionId: action.id, requiresApproval: !!approvalReq },
    });

    this.logger.log(`governance action requested id=${action.id} type=${params.actionType} corr=${params.correlationId}`);
    return action;
  }

  async approveAction(params: {
    tenantId: string;
    actionId: string;
    approvedBy: string;
    correlationId: string;
    approverRole: string;
  }): Promise<GovernanceAction> {
    const action = await this.getAction(params.tenantId, params.actionId);
    if (action.state !== 'REQUESTED') throw new BadRequestException(`cannot approve from state ${action.state}`);

    const policy = this.policyService.buildPolicy(params.tenantId, 'US');
    const approvalReq = policy.approvalRequirements.find((a) => a.actionType === action.actionType);
    if (approvalReq && !approvalReq.requiredRoles.includes(params.approverRole.toUpperCase())) {
      throw new BadRequestException(`approver role ${params.approverRole} not allowed, required ${approvalReq.requiredRoles.join(',')}`);
    }

    action.state = 'APPROVED';
    action.approvedBy = params.approvedBy;
    action.updatedAt = new Date().toISOString();
    this.inMemory.set(action.id, action);
    try {
      await (this.prisma as any).governanceAction?.update?.({ where: { id: action.id }, data: { state: action.state, approvedBy: action.approvedBy, updatedAt: new Date(action.updatedAt) } });
    } catch {
      this.logger.debug(`approve persist skipped id=${action.id}`);
    }

    await this.audit.recordEvent({
      tenantId: params.tenantId,
      actionType: action.actionType,
      state: action.state,
      result: 'APPROVED',
      correlationId: params.correlationId,
      createdBy: params.approvedBy,
      safeEvidence: { actionId: action.id, approverRole: params.approverRole },
    });

    return action;
  }

  async rejectAction(params: { tenantId: string; actionId: string; rejectedBy: string; correlationId: string; reason: string }): Promise<GovernanceAction> {
    const action = await this.getAction(params.tenantId, params.actionId);
    if (action.state !== 'REQUESTED') throw new BadRequestException(`cannot reject from state ${action.state}`);
    action.state = 'REJECTED';
    action.reason = params.reason;
    action.updatedAt = new Date().toISOString();
    this.inMemory.set(action.id, action);
    try {
      await (this.prisma as any).governanceAction?.update?.({ where: { id: action.id }, data: { state: action.state, reason: action.reason, updatedAt: new Date(action.updatedAt) } });
    } catch {
      this.logger.debug(`reject persist skipped id=${action.id}`);
    }
    await this.audit.recordEvent({
      tenantId: params.tenantId,
      actionType: action.actionType,
      state: action.state,
      result: 'REJECTED',
      reason: params.reason,
      correlationId: params.correlationId,
      createdBy: params.rejectedBy,
      safeEvidence: { actionId: action.id },
    });
    return action;
  }

  async markExecuted(params: { tenantId: string; actionId: string; correlationId: string; operatorId: string }): Promise<GovernanceAction> {
    const action = await this.getAction(params.tenantId, params.actionId);
    if (action.state !== 'APPROVED') throw new BadRequestException(`must be APPROVED to execute, current ${action.state}`);
    action.state = 'EXECUTED';
    action.updatedAt = new Date().toISOString();
    this.inMemory.set(action.id, action);
    try {
      await (this.prisma as any).governanceAction?.update?.({ where: { id: action.id }, data: { state: action.state, updatedAt: new Date(action.updatedAt) } });
    } catch {
      this.logger.debug(`executed persist skipped id=${action.id}`);
    }
    await this.audit.recordEvent({
      tenantId: params.tenantId,
      actionType: action.actionType,
      state: action.state,
      result: 'EXECUTED',
      correlationId: params.correlationId,
      createdBy: params.operatorId,
      safeEvidence: { actionId: action.id },
    });
    return action;
  }

  async getAction(tenantId: string, actionId: string): Promise<GovernanceAction> {
    const mem = this.inMemory.get(actionId);
    if (mem) {
      this.policyService.assertTenantIsolation(tenantId, mem.tenantId);
      return mem;
    }
    try {
      const row = await (this.prisma as any).governanceAction?.findUnique?.({ where: { id: actionId } });
      if (row) {
        this.policyService.assertTenantIsolation(tenantId, row.tenantId);
        return {
          id: row.id,
          tenantId: row.tenantId,
          actionType: row.actionType,
          entityId: row.entityId ?? undefined,
          requestedBy: row.requestedBy,
          approvedBy: row.approvedBy ?? null,
          state: row.state,
          reason: row.reason ?? null,
          correlationId: row.correlationId,
          createdAt: row.createdAt instanceof Date ? row.createdAt.toISOString() : row.createdAt,
          updatedAt: row.updatedAt instanceof Date ? row.updatedAt.toISOString() : row.updatedAt,
          safeParams: row.safeParams ?? {},
        };
      }
    } catch {
      /* ignore */
    }
    throw new BadRequestException(`governance action ${actionId} not found`);
  }

  async listActions(tenantId: string, filters?: { actionType?: GovernanceActionType; state?: string }): Promise<GovernanceAction[]> {
    let list = [...this.inMemory.values()].filter((a) => a.tenantId === tenantId);
    if (filters?.actionType) list = list.filter((a) => a.actionType === filters.actionType);
    if (filters?.state) list = list.filter((a) => a.state === filters.state);
    try {
      const where: any = { tenantId };
      if (filters?.actionType) where.actionType = filters.actionType;
      if (filters?.state) where.state = filters.state;
      const rows = await (this.prisma as any).governanceAction?.findMany?.({ where, take: 500, orderBy: { createdAt: 'desc' } });
      if (rows && rows.length > 0) {
        list = rows.map((r: any) => ({
          id: r.id,
          tenantId: r.tenantId,
          actionType: r.actionType,
          entityId: r.entityId ?? undefined,
          requestedBy: r.requestedBy,
          approvedBy: r.approvedBy ?? null,
          state: r.state,
          reason: r.reason ?? null,
          correlationId: r.correlationId,
          createdAt: r.createdAt instanceof Date ? r.createdAt.toISOString() : r.createdAt,
          updatedAt: r.updatedAt instanceof Date ? r.updatedAt.toISOString() : r.updatedAt,
          safeParams: r.safeParams ?? {},
        }));
      }
    } catch {
      /* ignore */
    }
    return list;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { GovernancePolicyService } from './governance-policy.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

export interface GovernanceMetrics {
  tenantId: string;
  generatedAt: string;
  policyVersion: string;
  privacyRequests: { total: number; byState: Record<string, number>; byType: Record<string, number> };
  retention: { total: number; byState: Record<string, number>; blockedByLegalHold: number };
  legalHolds: { total: number; active: number; byJurisdiction: Record<string, number> };
  reports: { total: number; byState: Record<string, number>; byType: Record<string, number>; certified: number; delivered: number };
  evidencePackages: { total: number; byState: Record<string, number>; immutable: number };
  consents: { total: number; active: number; withdrawn: number };
  reconciliation: { openMismatches: number; byType: Record<string, number>; bySeverity: Record<string, number> };
  audit: { totalEvents: number; byAction: Record<string, number> };
  correlationId: string;
}

@Injectable()
export class GovernanceMetricsService {
  private readonly logger = new Logger(GovernanceMetricsService.name);

  constructor(
    private readonly policyService: GovernancePolicyService,
    private readonly prisma: PrismaService,
  ) {}

  async getMetrics(tenantId: string, correlationId: string): Promise<GovernanceMetrics> {
    const metrics: GovernanceMetrics = {
      tenantId,
      generatedAt: new Date().toISOString(),
      policyVersion: this.policyService.getPolicyVersion(),
      privacyRequests: { total: 0, byState: {}, byType: {} },
      retention: { total: 0, byState: {}, blockedByLegalHold: 0 },
      legalHolds: { total: 0, active: 0, byJurisdiction: {} },
      reports: { total: 0, byState: {}, byType: {}, certified: 0, delivered: 0 },
      evidencePackages: { total: 0, byState: {}, immutable: 0 },
      consents: { total: 0, active: 0, withdrawn: 0 },
      reconciliation: { openMismatches: 0, byType: {}, bySeverity: {} },
      audit: { totalEvents: 0, byAction: {} },
      correlationId,
    };

    try {
      const pr = await (this.prisma as any).privacyRequest?.groupBy?.({ by: ['state'], where: { tenantId }, _count: { _all: true } });
      if (pr) {
        for (const g of pr) {
          metrics.privacyRequests.byState[g.state] = g._count._all;
          metrics.privacyRequests.total += g._count._all;
        }
      }
      const prType = await (this.prisma as any).privacyRequest?.groupBy?.({ by: ['requestType'], where: { tenantId }, _count: { _all: true } });
      if (prType) {
        for (const g of prType) metrics.privacyRequests.byType[g.requestType] = g._count._all;
      }
    } catch {
      this.logger.debug('metrics privacy fallback');
    }

    try {
      const ret = await (this.prisma as any).retentionCandidate?.groupBy?.({ by: ['state'], where: { tenantId }, _count: { _all: true } });
      if (ret) {
        for (const g of ret) {
          metrics.retention.byState[g.state] = g._count._all;
          metrics.retention.total += g._count._all;
        }
      }
      const blocked = await (this.prisma as any).retentionCandidate?.count?.({ where: { tenantId, blockedByLegalHold: true } });
      if (typeof blocked === 'number') metrics.retention.blockedByLegalHold = blocked;
    } catch {
      this.logger.debug('metrics retention fallback');
    }

    try {
      const lhTotal = await (this.prisma as any).legalHold?.count?.({ where: { OR: [{ tenantId }, { tenantId: null }] } });
      const lhActive = await (this.prisma as any).legalHold?.count?.({ where: { state: 'ACTIVE', OR: [{ tenantId }, { tenantId: null }] } });
      if (typeof lhTotal === 'number') metrics.legalHolds.total = lhTotal;
      if (typeof lhActive === 'number') metrics.legalHolds.active = lhActive;
    } catch {
      this.logger.debug('metrics legalHold fallback');
    }

    try {
      const rep = await (this.prisma as any).complianceReport?.groupBy?.({ by: ['state'], where: { tenantId }, _count: { _all: true } });
      if (rep) {
        for (const g of rep) {
          metrics.reports.byState[g.state] = g._count._all;
          metrics.reports.total += g._count._all;
        }
      }
      const repType = await (this.prisma as any).complianceReport?.groupBy?.({ by: ['reportType'], where: { tenantId }, _count: { _all: true } });
      if (repType) for (const g of repType) metrics.reports.byType[g.reportType] = g._count._all;
      const certified = await (this.prisma as any).complianceReport?.count?.({ where: { tenantId, certificationStatus: 'APPROVED' } });
      const delivered = await (this.prisma as any).complianceReport?.count?.({ where: { tenantId, deliveryStatus: 'DELIVERED' } });
      if (typeof certified === 'number') metrics.reports.certified = certified;
      if (typeof delivered === 'number') metrics.reports.delivered = delivered;
    } catch {
      this.logger.debug('metrics report fallback');
    }

    try {
      const ev = await (this.prisma as any).evidencePackage?.groupBy?.({ by: ['state'], where: { tenantId }, _count: { _all: true } });
      if (ev) {
        for (const g of ev) {
          metrics.evidencePackages.byState[g.state] = g._count._all;
          metrics.evidencePackages.total += g._count._all;
        }
      }
      const imm = await (this.prisma as any).evidencePackage?.count?.({ where: { tenantId, isImmutable: true } });
      if (typeof imm === 'number') metrics.evidencePackages.immutable = imm;
    } catch {
      this.logger.debug('metrics evidence fallback');
    }

    try {
      const cons = await (this.prisma as any).consentRecord?.groupBy?.({ by: ['status'], where: { tenantId }, _count: { _all: true } });
      if (cons) {
        for (const g of cons) {
          if (g.status === 'ACTIVE') metrics.consents.active = g._count._all;
          if (g.status === 'WITHDRAWN') metrics.consents.withdrawn = g._count._all;
          metrics.consents.total += g._count._all;
        }
      }
    } catch {
      this.logger.debug('metrics consent fallback');
    }

    try {
      const recon = await (this.prisma as any).governanceReconciliation?.groupBy?.({ by: ['type'], where: { tenantId }, _count: { _all: true } });
      if (recon) {
        for (const g of recon) {
          metrics.reconciliation.byType[g.type] = g._count._all;
          metrics.reconciliation.openMismatches += g._count._all;
        }
      }
      const sev = await (this.prisma as any).governanceReconciliation?.groupBy?.({ by: ['severity'], where: { tenantId }, _count: { _all: true } });
      if (sev) for (const g of sev) metrics.reconciliation.bySeverity[g.severity] = g._count._all;
    } catch {
      this.logger.debug('metrics reconciliation fallback');
    }

    try {
      const auditTotal = await (this.prisma as any).governanceAudit?.count?.({ where: { tenantId } });
      if (typeof auditTotal === 'number') metrics.audit.totalEvents = auditTotal;
      const auditBy = await (this.prisma as any).governanceAudit?.groupBy?.({ by: ['actionType'], where: { tenantId }, _count: { _all: true } });
      if (auditBy) for (const g of auditBy) metrics.audit.byAction[g.actionType] = g._count._all;
    } catch {
      this.logger.debug('metrics audit fallback');
    }

    this.logger.log(`metrics generated tenant=${tenantId} corr=${correlationId}`);
    return metrics;
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import {
  GovernancePolicy,
  DataClassification,
  PrivacyRequestType,
  PrivacyRequestState,
  RetentionRule,
  GovernanceActionType,
} from './governance.types';

@Injectable()
export class GovernancePolicyService {
  private readonly logger = new Logger(GovernancePolicyService.name);

  private readonly defaultPolicyVersion: string;
  private readonly supportedJurisdictions: string[];
  private readonly retentionDefaults: Record<string, number>;

  constructor(private readonly config: ConfigService) {
    this.defaultPolicyVersion = this.config.get<string>('GOVERNANCE_POLICY_VERSION', '2026-01');
    const jurisdictionsRaw = this.config.get<string>('GOVERNANCE_JURISDICTIONS', 'US,EU,UK,SG,AE');
    this.supportedJurisdictions = jurisdictionsRaw
      .split(',')
      .map((j) => j.trim().toUpperCase())
      .filter(Boolean);

    const retentionRaw = this.config.get<string>('GOVERNANCE_RETENTION_DAYS_DEFAULTS', '');
    this.retentionDefaults = this.parseRetentionDefaults(retentionRaw);
  }

  private parseRetentionDefaults(raw: string): Record<string, number> {
    const defaults: Record<string, number> = {
      [DataClassification.PUBLIC]: 365,
      [DataClassification.INTERNAL]: 1095,
      [DataClassification.CONFIDENTIAL]: 2555,
      [DataClassification.PII]: 1095,
      [DataClassification.FINANCIAL]: 2555,
      [DataClassification.SECURITY_SENSITIVE]: 2555,
      [DataClassification.KYC_SENSITIVE]: 2555,
      [DataClassification.REGULATED]: 2555,
      [DataClassification.RESTRICTED]: 2555,
    };
    if (!raw) return defaults;
    for (const pair of raw.split(',')) {
      const [k, v] = pair.split('=').map((s) => s.trim());
      if (k && v) {
        const n = Number(v);
        if (Number.isFinite(n) && n > 0) defaults[k.toUpperCase()] = n;
      }
    }
    return defaults;
  }

  validateJurisdiction(jurisdiction: string): void {
    if (!jurisdiction) throw new BadRequestException('jurisdiction required');
    const upper = jurisdiction.toUpperCase();
    if (!this.supportedJurisdictions.includes(upper)) {
      throw new BadRequestException(`unsupported jurisdiction ${jurisdiction}, supported: ${this.supportedJurisdictions.join(',')}`);
    }
  }

  getPolicyVersion(): string {
    return this.defaultPolicyVersion;
  }

  getSupportedJurisdictions(): string[] {
    return [...this.supportedJurisdictions];
  }

  buildPolicy(tenantId: string | null, jurisdiction: string): GovernancePolicy {
    this.validateJurisdiction(jurisdiction);
    const j = jurisdiction.toUpperCase();

    const retentionRules: RetentionRule[] = Object.values(DataClassification).map((dc) => {
      const days = this.retentionDefaults[dc] ?? 1095;
      let eligible: RetentionRule['eligibleAction'] = 'REVIEW';
      if (dc === DataClassification.PUBLIC) eligible = 'DELETE';
      else if (dc === DataClassification.PII) eligible = 'ANONYMIZE';
      else if (dc === DataClassification.FINANCIAL || dc === DataClassification.REGULATED || dc === DataClassification.KYC_SENSITIVE) eligible = 'PRESERVE';

      return {
        dataClass: dc as DataClassification,
        jurisdiction: j,
        retentionPeriodDays: days,
        retentionStartEvent: this.getRetentionStartEvent(dc as DataClassification),
        eligibleAction: eligible,
        policyVersion: this.defaultPolicyVersion,
        legalHoldOverride: true,
        requiresApproval: dc === DataClassification.FINANCIAL || dc === DataClassification.REGULATED || dc === DataClassification.KYC_SENSITIVE,
      };
    });

    return {
      tenantId: tenantId ?? null,
      jurisdiction: j,
      policyVersion: this.defaultPolicyVersion,
      dataClassifications: Object.values(DataClassification) as DataClassification[],
      retentionRules,
      privacyWorkflows: this.buildPrivacyWorkflows(j),
      reportRequirements: this.buildReportRequirements(j),
      evidenceRequirements: this.buildEvidenceRequirements(j),
      legalHoldPrecedence: true,
      approvalRequirements: this.buildApprovalRequirements(),
      piiFields: ['email', 'phone', 'address', 'government_id_reference', 'kyc_metadata'],
      sensitiveFields: ['password', 'secret', 'privateKey', 'apiKey', 'token', 'card', 'cvv', 'ssn'],
      exportEligibility: {
        [DataClassification.PUBLIC]: true,
        [DataClassification.INTERNAL]: true,
        [DataClassification.CONFIDENTIAL]: false,
        [DataClassification.PII]: true,
        [DataClassification.FINANCIAL]: true,
        [DataClassification.SECURITY_SENSITIVE]: false,
        [DataClassification.KYC_SENSITIVE]: false,
        [DataClassification.REGULATED]: true,
        [DataClassification.RESTRICTED]: false,
      },
      deletionConstraints: {
        [DataClassification.PUBLIC]: false,
        [DataClassification.INTERNAL]: true,
        [DataClassification.CONFIDENTIAL]: true,
        [DataClassification.PII]: true,
        [DataClassification.FINANCIAL]: true,
        [DataClassification.SECURITY_SENSITIVE]: true,
        [DataClassification.KYC_SENSITIVE]: true,
        [DataClassification.REGULATED]: true,
        [DataClassification.RESTRICTED]: true,
      },
    };
  }

  private getRetentionStartEvent(dc: DataClassification): string {
    switch (dc) {
      case DataClassification.PII:
        return 'ACCOUNT_CLOSURE_OR_LAST_INTERACTION';
      case DataClassification.FINANCIAL:
        return 'TRANSACTION_COMPLETION_OR_FISCAL_YEAR_END';
      case DataClassification.KYC_SENSITIVE:
        return 'KYC_COMPLETION_OR_ACCOUNT_CLOSURE';
      case DataClassification.REGULATED:
        return 'REGULATORY_EVENT_OR_ACCOUNT_CLOSURE';
      case DataClassification.SECURITY_SENSITIVE:
        return 'SECURITY_EVENT_OR_ACCOUNT_CLOSURE';
      default:
        return 'CREATION_OR_LAST_MODIFICATION';
    }
  }

  private buildPrivacyWorkflows(jurisdiction: string) {
    const base = [
      { type: PrivacyRequestType.ACCESS, sla: 30 * 24 },
      { type: PrivacyRequestType.EXPORT, sla: 30 * 24 },
      { type: PrivacyRequestType.CORRECTION, sla: 30 * 24 },
      { type: PrivacyRequestType.DELETION, sla: 30 * 24 },
      { type: PrivacyRequestType.RESTRICTION, sla: 30 * 24 },
      { type: PrivacyRequestType.OBJECTION, sla: 30 * 24 },
    ];
    return base.map((b) => ({
      requestType: b.type,
      jurisdiction,
      requiresIdentityVerification: true,
      requiresApproval: b.type === PrivacyRequestType.DELETION || b.type === PrivacyRequestType.EXPORT,
      allowedStates: Object.values(PrivacyRequestState),
      slaHours: b.sla,
      policyVersion: this.defaultPolicyVersion,
    }));
  }

  private buildReportRequirements(jurisdiction: string) {
    const types = ['TRANSACTION_REPORT', 'TAX_SUMMARY', 'AUDIT_TRAIL', 'KYC_SUMMARY', 'AML_SUMMARY', 'FINANCIAL_STATEMENT', 'OPERATIONS_INCIDENT', 'DATA_GOVERNANCE'];
    return types.map((rt) => ({
      reportType: rt,
      jurisdiction,
      requiredFields: ['tenantId', 'periodStart', 'periodEnd', 'sourceReferences', 'methodology', 'policyVersion'],
      sourceSystems: this.getSourceSystemsForReport(rt),
      periodType: 'MONTHLY' as const,
      requiresCertification: rt !== 'DATA_GOVERNANCE',
      requiresApproval: true,
      deliveryChannels: ['INTERNAL_STORAGE', 'REGULATOR_PORTAL'],
      policyVersion: this.defaultPolicyVersion,
    }));
  }

  private getSourceSystemsForReport(reportType: string): string[] {
    switch (reportType) {
      case 'TRANSACTION_REPORT':
        return ['PortfolioAccounting', 'Finance', 'OMS', 'Billing'];
      case 'TAX_SUMMARY':
        return ['Finance', 'PortfolioAccounting', 'Billing'];
      case 'AUDIT_TRAIL':
        return ['Audit', 'Operations', 'Security', 'Compliance'];
      case 'KYC_SUMMARY':
        return ['Compliance', 'ClientProfile', 'Audit'];
      case 'AML_SUMMARY':
        return ['Compliance', 'ClientLifecycle', 'Audit'];
      case 'FINANCIAL_STATEMENT':
        return ['Finance', 'Billing', 'PortfolioAccounting'];
      case 'OPERATIONS_INCIDENT':
        return ['Operations', 'Audit'];
      case 'DATA_GOVERNANCE':
        return ['Audit', 'Security', 'Compliance'];
      default:
        return ['Audit'];
    }
  }

  private buildEvidenceRequirements(jurisdiction: string) {
    const types = ['KYC_EVIDENCE', 'AML_EVIDENCE', 'TRANSACTION_EVIDENCE', 'AUDIT_EVIDENCE', 'INCIDENT_EVIDENCE', 'CONSENT_EVIDENCE', 'REPORT_EVIDENCE'];
    return types.map((et) => ({
      evidenceType: et,
      requiredSources: ['Audit', 'Compliance', 'Operations'],
      retentionDays: this.retentionDefaults[DataClassification.REGULATED] ?? 2555,
      requiresRedaction: et.includes('KYC') || et.includes('PII'),
      policyVersion: this.defaultPolicyVersion,
    }));
  }

  private buildApprovalRequirements() {
    return [
      { actionType: GovernanceActionType.PRIVACY_REQUEST_APPROVE, requiredRoles: ['ADMIN', 'COMPLIANCE'], minApprovals: 1, requiresMfa: false },
      { actionType: GovernanceActionType.PRIVACY_DELETION, requiredRoles: ['ADMIN', 'COMPLIANCE'], minApprovals: 1, requiresMfa: true },
      { actionType: GovernanceActionType.LEGAL_HOLD_CREATE, requiredRoles: ['ADMIN', 'LEGAL', 'COMPLIANCE'], minApprovals: 1, requiresMfa: false },
      { actionType: GovernanceActionType.LEGAL_HOLD_RELEASE, requiredRoles: ['ADMIN', 'LEGAL'], minApprovals: 2, requiresMfa: true },
      { actionType: GovernanceActionType.REPORT_CERTIFY, requiredRoles: ['ADMIN', 'COMPLIANCE', 'FINANCE'], minApprovals: 1, requiresMfa: true },
      { actionType: GovernanceActionType.RETENTION_ACTION, requiredRoles: ['ADMIN', 'COMPLIANCE'], minApprovals: 1, requiresMfa: false },
      { actionType: GovernanceActionType.EVIDENCE_PACKAGE_FINALIZE, requiredRoles: ['ADMIN', 'COMPLIANCE'], minApprovals: 1, requiresMfa: false },
      { actionType: GovernanceActionType.AUDIT_EXPORT, requiredRoles: ['ADMIN', 'COMPLIANCE', 'AUDIT'], minApprovals: 1, requiresMfa: false },
    ];
  }

  assertTenantIsolation(requestTenantId: string, recordTenantId: string): void {
    if (requestTenantId !== recordTenantId) {
      this.logger.warn(`tenant isolation violation attempt requestTenant=${requestTenantId} recordTenant=${recordTenantId}`);
      throw new BadRequestException('tenant isolation violation');
    }
  }

  sanitizeLogEvidence(evidence: Record<string, unknown>): Record<string, unknown> {
    const redactedKeys = ['password', 'secret', 'privateKey', 'apiKey', 'token', 'card', 'cvv', 'ssn', 'email', 'phone', 'address', 'government_id', 'kyc_doc', 'credential', 'signingSecret', 'private_key', 'jwt', 'bearer'];
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(evidence)) {
      const lower = k.toLowerCase();
      const isSensitive = redactedKeys.some((rk) => lower.includes(rk.toLowerCase()));
      if (isSensitive) {
        out[k] = '***REDACTED***';
      } else if (typeof v === 'string' && v.length > 500) {
        out[k] = v.slice(0, 500) + '...TRUNCATED';
      } else {
        out[k] = v;
      }
    }
    return out;
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { ComplianceReportService } from './compliance-report.service';
import { GovernanceAuditService } from './governance-audit.service';
import { GovernanceMetricsService } from './governance-metrics.service';
import { EvidencePackageService } from './evidence-package.service';
import { PrivacyRequestService } from './privacy-request.service';
import { GovernancePolicyService } from './governance-policy.service';
import { ReportState, PrivacyRequestState } from './governance.types';

@Injectable()
export class GovernanceReportQueryService {
  private readonly logger = new Logger(GovernanceReportQueryService.name);

  constructor(
    private readonly reportService: ComplianceReportService,
    private readonly audit: GovernanceAuditService,
    private readonly metrics: GovernanceMetricsService,
    private readonly evidence: EvidencePackageService,
    private readonly privacy: PrivacyRequestService,
    private readonly policyService: GovernancePolicyService,
  ) {}

  async queryReports(params: {
    tenantId: string;
    reportType?: string;
    jurisdiction?: string;
    state?: ReportState;
    periodStart?: string;
    periodEnd?: string;
    correlationId: string;
  }) {
    if (!params.tenantId) throw new BadRequestException('tenantId required');
    if (params.jurisdiction) this.policyService.validateJurisdiction(params.jurisdiction);
    const reports = await this.reportService.listReports(params.tenantId, {
      reportType: params.reportType,
      state: params.state,
      jurisdiction: params.jurisdiction,
    });

    let filtered = reports;
    if (params.periodStart) {
      const ps = new Date(params.periodStart);
      filtered = filtered.filter((r) => new Date(r.periodStart) >= ps);
    }
    if (params.periodEnd) {
      const pe = new Date(params.periodEnd);
      filtered = filtered.filter((r) => new Date(r.periodEnd) <= pe);
    }

    // Deterministic sort
    filtered.sort((a, b) => {
      if (a.generatedAt !== b.generatedAt) return b.generatedAt.localeCompare(a.generatedAt);
      return a.id.localeCompare(b.id);
    });

    this.logger.log(`queryReports tenant=${params.tenantId} count=${filtered.length} corr=${params.correlationId}`);
    return {
      tenantId: params.tenantId,
      count: filtered.length,
      reports: filtered,
      correlationId: params.correlationId,
      generatedAt: new Date().toISOString(),
      isDeterministic: true,
    };
  }

  async queryPrivacyRequests(params: {
    tenantId: string;
    subjectUserId?: string;
    state?: PrivacyRequestState;
    correlationId: string;
  }) {
    if (!params.tenantId) throw new BadRequestException('tenantId required');
    const requests = await this.privacy.listRequests(params.tenantId, {
      subjectUserId: params.subjectUserId,
      state: params.state,
    });
    requests.sort((a, b) => b.requestedAt.localeCompare(a.requestedAt));
    return {
      tenantId: params.tenantId,
      count: requests.length,
      requests,
      correlationId: params.correlationId,
      generatedAt: new Date().toISOString(),
      isDeterministic: true,
    };
  }

  async queryEvidence(params: {
    tenantId: string;
    caseReference?: string;
    evidenceType?: string;
    correlationId: string;
  }) {
    if (!params.tenantId) throw new BadRequestException('tenantId required');
    const packages = await this.evidence.listPackages(params.tenantId, {
      caseReference: params.caseReference,
      evidenceType: params.evidenceType,
    });
    packages.sort((a, b) => b.generatedAt.localeCompare(a.generatedAt));
    return {
      tenantId: params.tenantId,
      count: packages.length,
      evidencePackages: packages,
      correlationId: params.correlationId,
      generatedAt: new Date().toISOString(),
      isDeterministic: true,
    };
  }

  async queryAudit(params: {
    tenantId: string;
    correlationId: string;
    filters?: { actionType?: any; subjectUserId?: string; take?: number };
  }) {
    if (!params.tenantId) throw new BadRequestException('tenantId required');
    const events = await this.audit.listEvents(params.tenantId, params.filters);
    return {
      tenantId: params.tenantId,
      count: events.length,
      events,
      correlationId: params.correlationId,
      generatedAt: new Date().toISOString(),
      isDeterministic: true,
    };
  }

  async queryMetrics(params: { tenantId: string; correlationId: string }) {
    if (!params.tenantId) throw new BadRequestException('tenantId required');
    const metrics = await this.metrics.getMetrics(params.tenantId, params.correlationId);
    return metrics;
  }

  async queryGovernanceOverview(params: { tenantId: string; correlationId: string }) {
    const [reports, privacy, evidence, metrics] = await Promise.all([
      this.queryReports({ tenantId: params.tenantId, correlationId: params.correlationId }),
      this.queryPrivacyRequests({ tenantId: params.tenantId, correlationId: params.correlationId }),
      this.queryEvidence({ tenantId: params.tenantId, correlationId: params.correlationId }),
      this.queryMetrics({ tenantId: params.tenantId, correlationId: params.correlationId }),
    ]);
    return {
      tenantId: params.tenantId,
      reports: { count: reports.count },
      privacyRequests: { count: privacy.count },
      evidencePackages: { count: evidence.count },
      metrics,
      correlationId: params.correlationId,
      generatedAt: new Date().toISOString(),
      isDeterministic: true,
    };
  }
}

import { Injectable, Logger, BadRequestException, NotFoundException } from '@nestjs/common';
import { LegalHold, LegalHoldState, DataClassification, GovernanceActionType } from './governance.types';
import { GovernancePolicyService } from './governance-policy.service';
import { GovernanceAuditService } from './governance-audit.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

@Injectable()
export class LegalHoldService {
  private readonly logger = new Logger(LegalHoldService.name);
  private readonly inMemory: Map<string, LegalHold> = new Map();

  constructor(
    private readonly policyService: GovernancePolicyService,
    private readonly audit: GovernanceAuditService,
    private readonly prisma: PrismaService,
  ) {}

  async createHold(params: {
    tenantId?: string | null;
    caseReference: string;
    reason: string;
    affectedDataClasses: DataClassification[];
    affectedJurisdictions: string[];
    affectedSubjects?: string[];
    createdBy: string;
    correlationId: string;
    expiresAt?: string | null;
  }): Promise<LegalHold> {
    if (!params.caseReference || !params.reason) throw new BadRequestException('caseReference and reason required');
    if (params.affectedJurisdictions && params.affectedJurisdictions.length > 0) {
      for (const j of params.affectedJurisdictions) this.policyService.validateJurisdiction(j);
    }
    if (params.tenantId) {
      // tenant isolation check implicit
    }

    const hold: LegalHold = {
      id: `lh_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      tenantId: params.tenantId ?? null,
      caseReference: params.caseReference,
      reason: params.reason,
      state: LegalHoldState.DRAFT,
      affectedDataClasses: params.affectedDataClasses ?? [],
      affectedJurisdictions: params.affectedJurisdictions.map((j) => j.toUpperCase()),
      affectedSubjects: params.affectedSubjects ?? [],
      createdBy: params.createdBy,
      activatedBy: null,
      releasedBy: null,
      createdAt: new Date().toISOString(),
      activatedAt: null,
      releasedAt: null,
      expiresAt: params.expiresAt ?? null,
      correlationId: params.correlationId,
      policyVersion: this.policyService.getPolicyVersion(),
    };

    this.inMemory.set(hold.id, hold);
    try {
      await (this.prisma as any).legalHold?.create?.({
        data: {
          id: hold.id,
          tenantId: hold.tenantId,
          caseReference: hold.caseReference,
          reason: hold.reason,
          state: hold.state,
          affectedDataClasses: hold.affectedDataClasses,
          affectedJurisdictions: hold.affectedJurisdictions,
          affectedSubjects: hold.affectedSubjects,
          createdBy: hold.createdBy,
          createdAt: new Date(hold.createdAt),
          expiresAt: hold.expiresAt ? new Date(hold.expiresAt) : null,
          correlationId: hold.correlationId,
          policyVersion: hold.policyVersion,
        },
      });
    } catch {
      this.logger.debug(`legalHold persist skipped id=${hold.id}`);
    }

    await this.audit.recordEvent({
      tenantId: params.tenantId ?? 'PLATFORM',
      actionType: GovernanceActionType.LEGAL_HOLD_CREATE,
      legalHoldId: hold.id,
      state: hold.state,
      result: 'CREATED',
      correlationId: params.correlationId,
      createdBy: params.createdBy,
      safeEvidence: { caseReference: hold.caseReference, affectedDataClasses: hold.affectedDataClasses },
    });

    this.logger.log(`legal hold created id=${hold.id} case=${hold.caseReference} corr=${params.correlationId}`);
    return hold;
  }

  async activateHold(params: { holdId: string; tenantId?: string | null; activatedBy: string; correlationId: string }): Promise<LegalHold> {
    const hold = await this.getHold(params.holdId, params.tenantId);
    if (hold.state !== LegalHoldState.DRAFT) throw new BadRequestException(`cannot activate from state ${hold.state}`);
    hold.state = LegalHoldState.ACTIVE;
    hold.activatedBy = params.activatedBy;
    hold.activatedAt = new Date().toISOString();

    this.inMemory.set(hold.id, hold);
    try {
      await (this.prisma as any).legalHold?.update?.({
        where: { id: hold.id },
        data: { state: hold.state, activatedBy: hold.activatedBy, activatedAt: new Date(hold.activatedAt) },
      });
    } catch {
      this.logger.debug(`activate persist skipped id=${hold.id}`);
    }

    await this.audit.recordEvent({
      tenantId: hold.tenantId ?? 'PLATFORM',
      actionType: GovernanceActionType.LEGAL_HOLD_ACTIVATE,
      legalHoldId: hold.id,
      state: hold.state,
      result: 'ACTIVATED',
      correlationId: params.correlationId,
      createdBy: params.activatedBy,
      safeEvidence: { caseReference: hold.caseReference },
    });

    this.logger.log(`legal hold activated id=${hold.id} corr=${params.correlationId}`);
    return hold;
  }

  async releaseHold(params: { holdId: string; tenantId?: string | null; releasedBy: string; correlationId: string; reason: string }): Promise<LegalHold> {
    const hold = await this.getHold(params.holdId, params.tenantId);
    if (hold.state !== LegalHoldState.ACTIVE) throw new BadRequestException(`cannot release from state ${hold.state}`);
    hold.state = LegalHoldState.RELEASED;
    hold.releasedBy = params.releasedBy;
    hold.releasedAt = new Date().toISOString();

    this.inMemory.set(hold.id, hold);
    try {
      await (this.prisma as any).legalHold?.update?.({
        where: { id: hold.id },
        data: { state: hold.state, releasedBy: hold.releasedBy, releasedAt: new Date(hold.releasedAt) },
      });
    } catch {
      this.logger.debug(`release persist skipped id=${hold.id}`);
    }

    await this.audit.recordEvent({
      tenantId: hold.tenantId ?? 'PLATFORM',
      actionType: GovernanceActionType.LEGAL_HOLD_RELEASE,
      legalHoldId: hold.id,
      state: hold.state,
      result: 'RELEASED',
      reason: params.reason,
      correlationId: params.correlationId,
      createdBy: params.releasedBy,
      safeEvidence: { caseReference: hold.caseReference },
    });

    this.logger.log(`legal hold released id=${hold.id} corr=${params.correlationId}`);
    return hold;
  }

  async getHold(holdId: string, tenantId?: string | null): Promise<LegalHold> {
    const mem = this.inMemory.get(holdId);
    if (mem) {
      if (tenantId && mem.tenantId && mem.tenantId !== tenantId) {
        throw new BadRequestException('tenant isolation violation');
      }
      return mem;
    }
    try {
      const row = await (this.prisma as any).legalHold?.findUnique?.({ where: { id: holdId } });
      if (row) {
        if (tenantId && row.tenantId && row.tenantId !== tenantId) throw new BadRequestException('tenant isolation violation');
        const mapped = this.mapRow(row);
        this.inMemory.set(mapped.id, mapped);
        return mapped;
      }
    } catch {
      /* ignore */
    }
    throw new NotFoundException(`legal hold ${holdId} not found`);
  }

  async listActiveHolds(tenantId?: string | null): Promise<LegalHold[]> {
    let list = [...this.inMemory.values()].filter((h) => h.state === LegalHoldState.ACTIVE);
    if (tenantId) list = list.filter((h) => !h.tenantId || h.tenantId === tenantId);
    try {
      const where: any = { state: LegalHoldState.ACTIVE };
      if (tenantId) where.OR = [{ tenantId }, { tenantId: null }];
      const rows = await (this.prisma as any).legalHold?.findMany?.({ where, take: 500, orderBy: { createdAt: 'desc' } });
      if (rows && rows.length > 0) list = rows.map((r: any) => this.mapRow(r));
    } catch {
      /* ignore */
    }
    return list;
  }

  async listHolds(tenantId?: string | null, filters?: { state?: LegalHoldState }): Promise<LegalHold[]> {
    let list = [...this.inMemory.values()];
    if (tenantId) list = list.filter((h) => !h.tenantId || h.tenantId === tenantId);
    if (filters?.state) list = list.filter((h) => h.state === filters.state);
    try {
      const where: any = {};
      if (tenantId) where.OR = [{ tenantId }, { tenantId: null }];
      if (filters?.state) where.state = filters.state;
      const rows = await (this.prisma as any).legalHold?.findMany?.({ where, take: 500, orderBy: { createdAt: 'desc' } });
      if (rows && rows.length > 0) list = rows.map((r: any) => this.mapRow(r));
    } catch {
      /* ignore */
    }
    return list;
  }

  isBlockedByHold(params: { dataClass: DataClassification; subjectUserId?: string; tenantId: string }): boolean {
    const active = [...this.inMemory.values()].filter((h) => h.state === LegalHoldState.ACTIVE);
    for (const hold of active) {
      if (hold.tenantId && hold.tenantId !== params.tenantId) continue;
      if (hold.affectedDataClasses.length > 0 && !hold.affectedDataClasses.includes(params.dataClass)) continue;
      if (hold.affectedSubjects && hold.affectedSubjects.length > 0 && params.subjectUserId && !hold.affectedSubjects.includes(params.subjectUserId)) continue;
      return true;
    }
    return false;
  }

  private mapRow(row: any): LegalHold {
    return {
      id: row.id,
      tenantId: row.tenantId ?? null,
      caseReference: row.caseReference,
      reason: row.reason,
      state: row.state,
      affectedDataClasses: row.affectedDataClasses ?? [],
      affectedJurisdictions: row.affectedJurisdictions ?? [],
      affectedSubjects: row.affectedSubjects ?? [],
      createdBy: row.createdBy,
      activatedBy: row.activatedBy ?? null,
      releasedBy: row.releasedBy ?? null,
      createdAt: row.createdAt instanceof Date ? row.createdAt.toISOString() : row.createdAt,
      activatedAt: row.activatedAt ? (row.activatedAt instanceof Date ? row.activatedAt.toISOString() : row.activatedAt) : null,
      releasedAt: row.releasedAt ? (row.releasedAt instanceof Date ? row.releasedAt.toISOString() : row.releasedAt) : null,
      expiresAt: row.expiresAt ? (row.expiresAt instanceof Date ? row.expiresAt.toISOString() : row.expiresAt) : null,
      correlationId: row.correlationId,
      policyVersion: row.policyVersion,
    };
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { GovernancePolicyService } from './governance-policy.service';
import { DataInventoryService } from './data-inventory.service';
import { DataClassificationService } from './data-classification.service';
import { DataClassification } from './governance.types';

export interface DiscoveryResult {
  tenantId: string;
  subjectUserId: string;
  correlationId: string;
  generatedAt: string;
  totalRecords: number;
  recordsBySystem: Record<string, number>;
  recordsByClass: Record<DataClassification, number>;
  locations: Array<{ sourceSystem: string; sourceTable: string; sourceId: string; dataClasses: DataClassification[]; jurisdiction: string }>;
  policyVersion: string;
  isDeterministic: boolean;
  sourceReferences: string[];
}

@Injectable()
export class PrivacyDiscoveryService {
  private readonly logger = new Logger(PrivacyDiscoveryService.name);

  constructor(
    private readonly inventory: DataInventoryService,
    private readonly classification: DataClassificationService,
    private readonly policyService: GovernancePolicyService,
  ) {}

  async discoverForSubject(params: {
    tenantId: string;
    subjectUserId: string;
    jurisdiction: string;
    correlationId: string;
  }): Promise<DiscoveryResult> {
    if (!params.tenantId || !params.subjectUserId) throw new BadRequestException('tenantId and subjectUserId required');
    this.policyService.validateJurisdiction(params.jurisdiction);

    const inventoryRecords = await this.inventory.listForSubject(params.tenantId, params.subjectUserId);

    const recordsBySystem: Record<string, number> = {};
    const recordsByClass: Record<string, number> = {} as any;
    const locations: DiscoveryResult['locations'] = [];
    const sourceReferences: string[] = [];

    for (const rec of inventoryRecords) {
      recordsBySystem[rec.sourceSystem] = (recordsBySystem[rec.sourceSystem] ?? 0) + 1;
      for (const dc of rec.dataClasses) {
        recordsByClass[dc] = (recordsByClass[dc] ?? 0) + 1;
      }
      locations.push({
        sourceSystem: rec.sourceSystem,
        sourceTable: rec.sourceTable,
        sourceId: rec.sourceId,
        dataClasses: rec.dataClasses,
        jurisdiction: rec.jurisdiction,
      });
      sourceReferences.push(`${rec.sourceSystem}:${rec.sourceTable}:${rec.sourceId}`);
    }

    // Deterministic sort for reproducibility
    locations.sort((a, b) => {
      if (a.sourceSystem !== b.sourceSystem) return a.sourceSystem.localeCompare(b.sourceSystem);
      if (a.sourceTable !== b.sourceTable) return a.sourceTable.localeCompare(b.sourceTable);
      return a.sourceId.localeCompare(b.sourceId);
    });
    sourceReferences.sort();

    const result: DiscoveryResult = {
      tenantId: params.tenantId,
      subjectUserId: params.subjectUserId,
      correlationId: params.correlationId,
      generatedAt: new Date().toISOString(),
      totalRecords: inventoryRecords.length,
      recordsBySystem,
      recordsByClass: recordsByClass as any,
      locations,
      policyVersion: this.policyService.getPolicyVersion(),
      isDeterministic: true,
      sourceReferences,
    };

    this.logger.log(`discovery tenant=${params.tenantId} subject=${params.subjectUserId} total=${result.totalRecords} corr=${params.correlationId}`);
    return result;
  }

  assertAuthorizedForSubject(requestTenantId: string, recordTenantId: string, requestSubject: string, recordSubject: string): void {
    this.policyService.assertTenantIsolation(requestTenantId, recordTenantId);
    if (requestSubject !== recordSubject) {
      throw new BadRequestException('subject isolation violation');
    }
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { PrivacyExport, GovernanceActionType, DataClassification } from './governance.types';
import { PrivacyDiscoveryService, DiscoveryResult } from './privacy-discovery.service';
import { GovernancePolicyService } from './governance-policy.service';
import { GovernanceAuditService } from './governance-audit.service';
import { DataClassificationService } from './data-classification.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import * as crypto from 'crypto';

@Injectable()
export class PrivacyExportService {
  private readonly logger = new Logger(PrivacyExportService.name);
  private readonly inMemory: Map<string, PrivacyExport> = new Map();

  constructor(
    private readonly discovery: PrivacyDiscoveryService,
    private readonly policyService: GovernancePolicyService,
    private readonly audit: GovernanceAuditService,
    private readonly classification: DataClassificationService,
    private readonly prisma: PrismaService,
    private readonly config: ConfigService,
  ) {}

  async generateExport(params: {
    tenantId: string;
    requestId: string;
    subjectUserId: string;
    jurisdiction: string;
    correlationId: string;
    operatorId: string;
    discoveryResult?: DiscoveryResult;
  }): Promise<PrivacyExport> {
    if (!params.tenantId || !params.subjectUserId || !params.requestId) {
      throw new BadRequestException('tenantId, subjectUserId, requestId required');
    }
    this.policyService.validateJurisdiction(params.jurisdiction);

    const discovery = params.discoveryResult ?? (await this.discovery.discoverForSubject({
      tenantId: params.tenantId,
      subjectUserId: params.subjectUserId,
      jurisdiction: params.jurisdiction,
      correlationId: params.correlationId,
    }));

    const policy = this.policyService.buildPolicy(params.tenantId, params.jurisdiction);
    const eligibleClasses: DataClassification[] = [];
    for (const dc of discovery.locations.flatMap((l) => l.dataClasses)) {
      if (this.classification.isExportAllowed(dc, policy)) {
        if (!eligibleClasses.includes(dc)) eligibleClasses.push(dc);
      }
    }

    const exportRecord: PrivacyExport = {
      id: `pex_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      tenantId: params.tenantId,
      requestId: params.requestId,
      subjectUserId: params.subjectUserId,
      exportVersion: `v${policy.policyVersion}_${new Date().toISOString().slice(0, 10)}`,
      dataAsOf: discovery.generatedAt,
      generatedAt: new Date().toISOString(),
      dataCategories: eligibleClasses,
      sourceReferences: discovery.sourceReferences,
      recordCount: discovery.totalRecords,
      fileLocation: null,
      fileHash: null,
      methodology: `AUTHORITATIVE_SOURCE_AGGREGATION: inventory discovery deterministic sorted, export eligibility filtered by policy ${policy.policyVersion}`,
      policyVersion: policy.policyVersion,
      correlationId: params.correlationId,
      isDeterministic: true,
    };

    // Deterministic hash of content (not including actual PII, only references)
    const contentForHash = JSON.stringify({
      tenantId: exportRecord.tenantId,
      subjectUserId: exportRecord.subjectUserId,
      dataAsOf: exportRecord.dataAsOf,
      sourceReferences: [...exportRecord.sourceReferences].sort(),
      dataCategories: [...exportRecord.dataCategories].sort(),
      policyVersion: exportRecord.policyVersion,
    });
    exportRecord.fileHash = crypto.createHash('sha256').update(contentForHash).digest('hex');
    exportRecord.fileLocation = `governance/exports/${params.tenantId}/${exportRecord.id}.json`;

    this.inMemory.set(exportRecord.id, exportRecord);
    try {
      await (this.prisma as any).privacyExport?.create?.({
        data: {
          id: exportRecord.id,
          tenantId: exportRecord.tenantId,
          requestId: exportRecord.requestId,
          subjectUserId: exportRecord.subjectUserId,
          exportVersion: exportRecord.exportVersion,
          dataAsOf: new Date(exportRecord.dataAsOf),
          generatedAt: new Date(exportRecord.generatedAt),
          dataCategories: exportRecord.dataCategories,
          sourceReferences: exportRecord.sourceReferences,
          recordCount: exportRecord.recordCount,
          fileLocation: exportRecord.fileLocation,
          fileHash: exportRecord.fileHash,
          methodology: exportRecord.methodology,
          policyVersion: exportRecord.policyVersion,
          correlationId: exportRecord.correlationId,
          isDeterministic: exportRecord.isDeterministic,
        },
      });
    } catch {
      this.logger.debug(`privacyExport persist skipped id=${exportRecord.id}`);
    }

    await this.audit.recordEvent({
      tenantId: params.tenantId,
      actionType: GovernanceActionType.PRIVACY_EXPORT,
      subjectUserId: params.subjectUserId,
      requestId: params.requestId,
      state: 'EXPORT_GENERATED',
      result: 'SUCCESS',
      correlationId: params.correlationId,
      createdBy: params.operatorId,
      safeEvidence: { exportId: exportRecord.id, recordCount: exportRecord.recordCount, fileHash: exportRecord.fileHash },
    });

    this.logger.log(`export generated id=${exportRecord.id} tenant=${params.tenantId} records=${exportRecord.recordCount} corr=${params.correlationId}`);
    return exportRecord;
  }

  async getExport(tenantId: string, exportId: string): Promise<PrivacyExport> {
    const mem = this.inMemory.get(exportId);
    if (mem) {
      this.policyService.assertTenantIsolation(tenantId, mem.tenantId);
      return mem;
    }
    try {
      const row = await (this.prisma as any).privacyExport?.findUnique?.({ where: { id: exportId } });
      if (row) {
        this.policyService.assertTenantIsolation(tenantId, row.tenantId);
        return this.mapRow(row);
      }
    } catch {
      /* ignore */
    }
    throw new BadRequestException(`export ${exportId} not found`);
  }

  async listExports(tenantId: string, requestId?: string): Promise<PrivacyExport[]> {
    let list = [...this.inMemory.values()].filter((r) => r.tenantId === tenantId);
    if (requestId) list = list.filter((r) => r.requestId === requestId);
    try {
      const where: any = { tenantId };
      if (requestId) where.requestId = requestId;
      const rows = await (this.prisma as any).privacyExport?.findMany?.({ where, take: 200, orderBy: { generatedAt: 'desc' } });
      if (rows && rows.length > 0) list = rows.map((r: any) => this.mapRow(r));
    } catch {
      /* ignore */
    }
    return list;
  }

  private mapRow(row: any): PrivacyExport {
    return {
      id: row.id,
      tenantId: row.tenantId,
      requestId: row.requestId,
      subjectUserId: row.subjectUserId,
      exportVersion: row.exportVersion,
      dataAsOf: row.dataAsOf instanceof Date ? row.dataAsOf.toISOString() : row.dataAsOf,
      generatedAt: row.generatedAt instanceof Date ? row.generatedAt.toISOString() : row.generatedAt,
      dataCategories: row.dataCategories,
      sourceReferences: row.sourceReferences,
      recordCount: row.recordCount,
      fileLocation: row.fileLocation ?? null,
      fileHash: row.fileHash ?? null,
      methodology: row.methodology,
      policyVersion: row.policyVersion,
      correlationId: row.correlationId,
      isDeterministic: !!row.isDeterministic,
    };
  }
}

import { Injectable, Logger, BadRequestException, NotFoundException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import {
  PrivacyRequest,
  PrivacyRequestType,
  PrivacyRequestState,
  PRIVACY_REQUEST_TRANSITIONS,
  GovernanceActionType,
} from './governance.types';
import { GovernancePolicyService } from './governance-policy.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { GovernanceAuditService } from './governance-audit.service';

@Injectable()
export class PrivacyRequestService {
  private readonly logger = new Logger(PrivacyRequestService.name);
  private readonly inMemory: Map<string, PrivacyRequest> = new Map();

  constructor(
    private readonly config: ConfigService,
    private readonly policyService: GovernancePolicyService,
    private readonly prisma: PrismaService,
    private readonly audit: GovernanceAuditService,
  ) {}

  async createRequest(params: {
    tenantId: string;
    subjectUserId: string;
    subjectType: 'USER' | 'CUSTOMER';
    requestType: PrivacyRequestType;
    jurisdiction: string;
    reason?: string;
    idempotencyKey: string;
    correlationId: string;
    createdBy: string;
  }): Promise<PrivacyRequest> {
    if (!params.tenantId || !params.subjectUserId || !params.requestType || !params.idempotencyKey) {
      throw new BadRequestException('tenantId, subjectUserId, requestType, idempotencyKey required');
    }
    this.policyService.validateJurisdiction(params.jurisdiction);
    if (!Object.values(PrivacyRequestType).includes(params.requestType)) throw new BadRequestException('invalid requestType');

    const existing = await this.findByIdempotency(params.tenantId, params.idempotencyKey);
    if (existing) {
      this.logger.log(`privacy request idempotent hit tenant=${params.tenantId} key=${params.idempotencyKey} corr=${params.correlationId}`);
      return existing;
    }

    const policy = this.policyService.buildPolicy(params.tenantId, params.jurisdiction);
    const workflow = policy.privacyWorkflows.find((w) => w.requestType === params.requestType);
    const initialState = workflow?.requiresIdentityVerification
      ? PrivacyRequestState.IDENTITY_VERIFICATION_REQUIRED
      : PrivacyRequestState.UNDER_REVIEW;

    const record: PrivacyRequest = {
      id: `prq_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      tenantId: params.tenantId,
      subjectUserId: params.subjectUserId,
      subjectType: params.subjectType,
      requestType: params.requestType,
      state: initialState,
      jurisdiction: params.jurisdiction.toUpperCase(),
      reason: params.reason,
      idempotencyKey: params.idempotencyKey,
      correlationId: params.correlationId,
      requestedAt: new Date().toISOString(),
      verifiedAt: null,
      completedAt: null,
      blockedReason: null,
      retentionBlock: false,
      legalHoldBlock: false,
      sourceReferences: [],
      createdBy: params.createdBy,
      updatedAt: new Date().toISOString(),
    };

    this.inMemory.set(record.id, record);
    try {
      await (this.prisma as any).privacyRequest?.create?.({
        data: {
          id: record.id,
          tenantId: record.tenantId,
          subjectUserId: record.subjectUserId,
          subjectType: record.subjectType,
          requestType: record.requestType,
          state: record.state,
          jurisdiction: record.jurisdiction,
          reason: record.reason,
          idempotencyKey: record.idempotencyKey,
          correlationId: record.correlationId,
          requestedAt: new Date(record.requestedAt),
          createdBy: record.createdBy,
          updatedAt: new Date(record.updatedAt),
        },
      });
    } catch {
      this.logger.debug(`privacyRequest persist skipped id=${record.id}`);
    }

    await this.audit.recordEvent({
      tenantId: params.tenantId,
      actionType: GovernanceActionType.PRIVACY_REQUEST_CREATE,
      subjectUserId: params.subjectUserId,
      requestId: record.id,
      state: record.state,
      result: 'CREATED',
      correlationId: params.correlationId,
      createdBy: params.createdBy,
      safeEvidence: { requestType: record.requestType, jurisdiction: record.jurisdiction },
    });

    this.logger.log(`privacy request created id=${record.id} type=${record.requestType} tenant=${params.tenantId} corr=${params.correlationId}`);
    return record;
  }

  async transitionRequest(params: {
    tenantId: string;
    requestId: string;
    targetState: PrivacyRequestState;
    correlationId: string;
    operatorId: string;
    reason?: string;
    verificationEvidence?: string;
  }): Promise<PrivacyRequest> {
    const existing = await this.getRequest(params.tenantId, params.requestId);
    const allowed = PRIVACY_REQUEST_TRANSITIONS[existing.state];
    if (!allowed.includes(params.targetState)) {
      throw new BadRequestException(`invalid transition ${existing.state} -> ${params.targetState}`);
    }

    if (params.targetState === PrivacyRequestState.UNDER_REVIEW && existing.state === PrivacyRequestState.IDENTITY_VERIFICATION_REQUIRED) {
      if (!params.verificationEvidence) {
        throw new BadRequestException('identity verification evidence required before UNDER_REVIEW');
      }
      existing.verifiedAt = new Date().toISOString();
    }

    if (params.targetState === PrivacyRequestState.COMPLETED) {
      if (existing.retentionBlock || existing.legalHoldBlock) {
        throw new BadRequestException('cannot complete while blocked by retention or legal hold');
      }
      existing.completedAt = new Date().toISOString();
    }

    existing.state = params.targetState;
    existing.updatedAt = new Date().toISOString();
    if (params.reason) existing.blockedReason = params.reason;

    this.inMemory.set(existing.id, existing);
    try {
      await (this.prisma as any).privacyRequest?.update?.({
        where: { id: existing.id },
        data: {
          state: existing.state,
          verifiedAt: existing.verifiedAt ? new Date(existing.verifiedAt) : null,
          completedAt: existing.completedAt ? new Date(existing.completedAt) : null,
          blockedReason: existing.blockedReason,
          retentionBlock: existing.retentionBlock,
          legalHoldBlock: existing.legalHoldBlock,
          updatedAt: new Date(existing.updatedAt),
        },
      });
    } catch {
      this.logger.debug(`privacyRequest update skipped id=${existing.id}`);
    }

    await this.audit.recordEvent({
      tenantId: params.tenantId,
      actionType: this.mapTransitionToAction(params.targetState),
      subjectUserId: existing.subjectUserId,
      requestId: existing.id,
      state: existing.state,
      result: 'TRANSITIONED',
      reason: params.reason,
      correlationId: params.correlationId,
      createdBy: params.operatorId,
      safeEvidence: { from: existing.state, to: params.targetState },
    });

    this.logger.log(`privacy request transition id=${existing.id} -> ${params.targetState} corr=${params.correlationId}`);
    return existing;
  }

  private mapTransitionToAction(target: PrivacyRequestState): GovernanceActionType {
    if (target === PrivacyRequestState.COMPLETED) return GovernanceActionType.PRIVACY_REQUEST_APPROVE;
    if (target === PrivacyRequestState.REJECTED) return GovernanceActionType.PRIVACY_REQUEST_REJECT;
    if (target === PrivacyRequestState.READY) return GovernanceActionType.PRIVACY_EXPORT;
    return GovernanceActionType.PRIVACY_REQUEST_APPROVE;
  }

  async getRequest(tenantId: string, requestId: string): Promise<PrivacyRequest> {
    if (!tenantId || !requestId) throw new BadRequestException('tenantId and requestId required');
    const mem = this.inMemory.get(requestId);
    if (mem) {
      this.policyService.assertTenantIsolation(tenantId, mem.tenantId);
      return mem;
    }
    try {
      const row = await (this.prisma as any).privacyRequest?.findUnique?.({ where: { id: requestId } });
      if (row) {
        this.policyService.assertTenantIsolation(tenantId, row.tenantId);
        const mapped = this.mapRow(row);
        this.inMemory.set(mapped.id, mapped);
        return mapped;
      }
    } catch {
      this.logger.debug(`getRequest fallback id=${requestId}`);
    }
    throw new NotFoundException(`privacy request ${requestId} not found`);
  }

  async findByIdempotency(tenantId: string, idempotencyKey: string): Promise<PrivacyRequest | null> {
    for (const r of this.inMemory.values()) {
      if (r.tenantId === tenantId && r.idempotencyKey === idempotencyKey) return r;
    }
    try {
      const row = await (this.prisma as any).privacyRequest?.findFirst?.({ where: { tenantId, idempotencyKey } });
      if (row) return this.mapRow(row);
    } catch {
      /* ignore */
    }
    return null;
  }

  async listRequests(tenantId: string, filters?: { subjectUserId?: string; state?: PrivacyRequestState }): Promise<PrivacyRequest[]> {
    if (!tenantId) throw new BadRequestException('tenantId required');
    let list = [...this.inMemory.values()].filter((r) => r.tenantId === tenantId);
    if (filters?.subjectUserId) list = list.filter((r) => r.subjectUserId === filters.subjectUserId);
    if (filters?.state) list = list.filter((r) => r.state === filters.state);
    try {
      const where: any = { tenantId };
      if (filters?.subjectUserId) where.subjectUserId = filters.subjectUserId;
      if (filters?.state) where.state = filters.state;
      const rows = await (this.prisma as any).privacyRequest?.findMany?.({ where, take: 500, orderBy: { requestedAt: 'desc' } });
      if (rows && rows.length > 0) {
        list = rows.map((r: any) => this.mapRow(r));
      }
    } catch {
      /* ignore */
    }
    return list;
  }

  async markBlocked(params: { tenantId: string; requestId: string; blockedBy: 'RETENTION' | 'LEGAL_HOLD'; reason: string; correlationId: string; operatorId: string }): Promise<PrivacyRequest> {
    const existing = await this.getRequest(params.tenantId, params.requestId);
    if (params.blockedBy === 'RETENTION') {
      existing.retentionBlock = true;
      existing.state = PrivacyRequestState.BLOCKED_BY_RETENTION;
    } else {
      existing.legalHoldBlock = true;
      existing.state = PrivacyRequestState.BLOCKED_BY_LEGAL_HOLD;
    }
    existing.blockedReason = params.reason;
    existing.updatedAt = new Date().toISOString();
    this.inMemory.set(existing.id, existing);
    try {
      await (this.prisma as any).privacyRequest?.update?.({
        where: { id: existing.id },
        data: {
          state: existing.state,
          blockedReason: existing.blockedReason,
          retentionBlock: existing.retentionBlock,
          legalHoldBlock: existing.legalHoldBlock,
          updatedAt: new Date(existing.updatedAt),
        },
      });
    } catch {
      this.logger.debug(`markBlocked persist skipped id=${existing.id}`);
    }
    return existing;
  }

  async unblock(params: { tenantId: string; requestId: string; correlationId: string; operatorId: string }): Promise<PrivacyRequest> {
    const existing = await this.getRequest(params.tenantId, params.requestId);
    existing.retentionBlock = false;
    existing.legalHoldBlock = false;
    existing.blockedReason = null;
    existing.state = PrivacyRequestState.UNDER_REVIEW;
    existing.updatedAt = new Date().toISOString();
    this.inMemory.set(existing.id, existing);
    try {
      await (this.prisma as any).privacyRequest?.update?.({
        where: { id: existing.id },
        data: {
          state: existing.state,
          blockedReason: null,
          retentionBlock: false,
          legalHoldBlock: false,
          updatedAt: new Date(existing.updatedAt),
        },
      });
    } catch {
      this.logger.debug(`unblock persist skipped id=${existing.id}`);
    }
    return existing;
  }

  private mapRow(row: any): PrivacyRequest {
    return {
      id: row.id,
      tenantId: row.tenantId,
      subjectUserId: row.subjectUserId,
      subjectType: row.subjectType,
      requestType: row.requestType,
      state: row.state,
      jurisdiction: row.jurisdiction,
      reason: row.reason ?? undefined,
      idempotencyKey: row.idempotencyKey,
      correlationId: row.correlationId,
      requestedAt: row.requestedAt instanceof Date ? row.requestedAt.toISOString() : row.requestedAt,
      verifiedAt: row.verifiedAt ? (row.verifiedAt instanceof Date ? row.verifiedAt.toISOString() : row.verifiedAt) : null,
      completedAt: row.completedAt ? (row.completedAt instanceof Date ? row.completedAt.toISOString() : row.completedAt) : null,
      blockedReason: row.blockedReason ?? null,
      retentionBlock: !!row.retentionBlock,
      legalHoldBlock: !!row.legalHoldBlock,
      sourceReferences: row.sourceReferences ?? [],
      createdBy: row.createdBy,
      updatedAt: row.updatedAt instanceof Date ? row.updatedAt.toISOString() : row.updatedAt,
    };
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { RetentionCandidate, RetentionState, DataClassification, GovernanceActionType } from './governance.types';
import { RetentionPolicyService } from './retention-policy.service';
import { GovernancePolicyService } from './governance-policy.service';
import { GovernanceAuditService } from './governance-audit.service';
import { LegalHoldService } from './legal-hold.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

@Injectable()
export class RetentionEngineService {
  private readonly logger = new Logger(RetentionEngineService.name);
  private readonly inMemory: Map<string, RetentionCandidate> = new Map();

  constructor(
    private readonly retentionPolicy: RetentionPolicyService,
    private readonly policyService: GovernancePolicyService,
    private readonly audit: GovernanceAuditService,
    private readonly legalHold: LegalHoldService,
    private readonly prisma: PrismaService,
  ) {}

  async evaluateCandidate(params: {
    tenantId: string;
    dataClass: DataClassification;
    sourceSystem: string;
    sourceId: string;
    jurisdiction: string;
    retentionStartAt: string;
    correlationId: string;
    operatorId: string;
  }): Promise<RetentionCandidate> {
    if (!params.tenantId || !params.sourceId) throw new BadRequestException('tenantId and sourceId required');
    this.policyService.validateJurisdiction(params.jurisdiction);

    const policy = await this.retentionPolicy.getPolicyForClass(params.tenantId, params.dataClass, params.jurisdiction);
    const retentionEndAt = this.retentionPolicy.calculateRetentionEnd(params.retentionStartAt, policy.retentionPeriodDays);

    const holds = await this.legalHold.listActiveHolds(params.tenantId);
    const blockingHolds = holds.filter((h) => h.affectedDataClasses.length === 0 || h.affectedDataClasses.includes(params.dataClass));
    const hasLegalHold = blockingHolds.length > 0;

    const state = this.retentionPolicy.evaluateRetentionState({
      retentionEndAt,
      hasLegalHold,
      eligibleAction: policy.eligibleAction,
    });

    const candidate: RetentionCandidate = {
      id: `retc_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      tenantId: params.tenantId,
      dataClass: params.dataClass,
      sourceSystem: params.sourceSystem,
      sourceId: params.sourceId,
      jurisdiction: params.jurisdiction.toUpperCase(),
      retentionStartAt: params.retentionStartAt,
      retentionEndAt,
      state,
      eligibleAction: policy.eligibleAction,
      blockedByLegalHold: hasLegalHold,
      legalHoldIds: blockingHolds.map((h) => h.id),
      policyVersion: policy.policyVersion,
      correlationId: params.correlationId,
      createdAt: new Date().toISOString(),
    };

    this.inMemory.set(candidate.id, candidate);
    try {
      await (this.prisma as any).retentionCandidate?.create?.({
        data: {
          id: candidate.id,
          tenantId: candidate.tenantId,
          dataClass: candidate.dataClass,
          sourceSystem: candidate.sourceSystem,
          sourceId: candidate.sourceId,
          jurisdiction: candidate.jurisdiction,
          retentionStartAt: new Date(candidate.retentionStartAt),
          retentionEndAt: new Date(candidate.retentionEndAt),
          state: candidate.state,
          eligibleAction: candidate.eligibleAction,
          blockedByLegalHold: candidate.blockedByLegalHold,
          legalHoldIds: candidate.legalHoldIds,
          policyVersion: candidate.policyVersion,
          correlationId: candidate.correlationId,
          createdAt: new Date(candidate.createdAt),
        },
      });
    } catch {
      this.logger.debug(`retentionCandidate persist skipped id=${candidate.id}`);
    }

    await this.audit.recordEvent({
      tenantId: params.tenantId,
      actionType: GovernanceActionType.RETENTION_EVALUATE,
      retentionCandidateId: candidate.id,
      state: candidate.state,
      result: 'EVALUATED',
      correlationId: params.correlationId,
      createdBy: params.operatorId,
      safeEvidence: { dataClass: params.dataClass, state, retentionEndAt, blockedByLegalHold: hasLegalHold },
    });

    this.logger.log(`retention evaluated id=${candidate.id} tenant=${params.tenantId} state=${state} corr=${params.correlationId}`);
    return candidate;
  }

  async findCandidate(tenantId: string, sourceSystem: string, sourceId: string): Promise<RetentionCandidate | null> {
    for (const c of this.inMemory.values()) {
      if (c.tenantId === tenantId && c.sourceSystem === sourceSystem && c.sourceId === sourceId) return c;
    }
    try {
      const row = await (this.prisma as any).retentionCandidate?.findFirst?.({ where: { tenantId, sourceSystem, sourceId }, orderBy: { createdAt: 'desc' } });
      if (row) return this.mapRow(row);
    } catch {
      /* ignore */
    }
    return null;
  }

  async listCandidates(tenantId: string, filters?: { state?: RetentionState; dataClass?: DataClassification }): Promise<RetentionCandidate[]> {
    let list = [...this.inMemory.values()].filter((c) => c.tenantId === tenantId);
    if (filters?.state) list = list.filter((c) => c.state === filters.state);
    if (filters?.dataClass) list = list.filter((c) => c.dataClass === filters.dataClass);
    try {
      const where: any = { tenantId };
      if (filters?.state) where.state = filters.state;
      if (filters?.dataClass) where.dataClass = filters.dataClass;
      const rows = await (this.prisma as any).retentionCandidate?.findMany?.({ where, take: 500, orderBy: { createdAt: 'desc' } });
      if (rows && rows.length > 0) list = rows.map((r: any) => this.mapRow(r));
    } catch {
      /* ignore */
    }
    return list;
  }

  async executeAction(params: {
    tenantId: string;
    candidateId: string;
    action: 'DELETE' | 'ANONYMIZE' | 'REVIEW' | 'PRESERVE';
    correlationId: string;
    operatorId: string;
    reason: string;
  }): Promise<RetentionCandidate> {
    const candidate = this.inMemory.get(params.candidateId) ?? (await this.getCandidate(params.tenantId, params.candidateId));
    if (candidate.blockedByLegalHold) throw new BadRequestException(`candidate blocked by legal hold ${candidate.legalHoldIds.join(',')}`);
    if (candidate.eligibleAction !== params.action && params.action !== 'REVIEW' && params.action !== 'PRESERVE') {
      throw new BadRequestException(`action ${params.action} not eligible, expected ${candidate.eligibleAction}`);
    }
    if (candidate.state === RetentionState.RETENTION_REQUIRED) throw new BadRequestException('retention still required, cannot execute deletion/anonymization');

    let newState: RetentionState;
    switch (params.action) {
      case 'DELETE':
        newState = RetentionState.DELETED;
        break;
      case 'ANONYMIZE':
        newState = RetentionState.ANONYMIZED;
        break;
      case 'PRESERVE':
        newState = RetentionState.PRESERVED;
        break;
      default:
        newState = RetentionState.ELIGIBLE_FOR_REVIEW;
    }

    candidate.state = newState;
    this.inMemory.set(candidate.id, candidate);
    try {
      await (this.prisma as any).retentionCandidate?.update?.({ where: { id: candidate.id }, data: { state: newState } });
    } catch {
      this.logger.debug(`retention execute persist skipped id=${candidate.id}`);
    }

    await this.audit.recordEvent({
      tenantId: params.tenantId,
      actionType: GovernanceActionType.RETENTION_ACTION,
      retentionCandidateId: candidate.id,
      state: newState,
      result: params.action,
      reason: params.reason,
      correlationId: params.correlationId,
      createdBy: params.operatorId,
      safeEvidence: { action: params.action, previousEligible: candidate.eligibleAction },
    });

    this.logger.log(`retention action id=${candidate.id} action=${params.action} -> ${newState} corr=${params.correlationId}`);
    return candidate;
  }

  private async getCandidate(tenantId: string, candidateId: string): Promise<RetentionCandidate> {
    const mem = this.inMemory.get(candidateId);
    if (mem) {
      this.policyService.assertTenantIsolation(tenantId, mem.tenantId);
      return mem;
    }
    try {
      const row = await (this.prisma as any).retentionCandidate?.findUnique?.({ where: { id: candidateId } });
      if (row) {
        this.policyService.assertTenantIsolation(tenantId, row.tenantId);
        return this.mapRow(row);
      }
    } catch {
      /* ignore */
    }
    throw new BadRequestException(`retention candidate ${candidateId} not found`);
  }

  private mapRow(row: any): RetentionCandidate {
    return {
      id: row.id,
      tenantId: row.tenantId,
      dataClass: row.dataClass,
      sourceSystem: row.sourceSystem,
      sourceId: row.sourceId,
      jurisdiction: row.jurisdiction,
      retentionStartAt: row.retentionStartAt instanceof Date ? row.retentionStartAt.toISOString() : row.retentionStartAt,
      retentionEndAt: row.retentionEndAt instanceof Date ? row.retentionEndAt.toISOString() : row.retentionEndAt,
      state: row.state,
      eligibleAction: row.eligibleAction,
      blockedByLegalHold: !!row.blockedByLegalHold,
      legalHoldIds: row.legalHoldIds ?? [],
      policyVersion: row.policyVersion,
      correlationId: row.correlationId,
      createdAt: row.createdAt instanceof Date ? row.createdAt.toISOString() : row.createdAt,
    };
  }
}

