            engagedAt: new Date('2026-10-01T10:00:00.000Z'),
            releasedByUserId: null,
            releasedAt: null,
            updatedAt: new Date('2026-10-01T10:00:00.000Z'),
          },
          {
            id: 'ks-2',
            scope: 'SYMBOL',
            target: 'BTC-USDT',
            isEngaged: true,
            reason: 'Volatility halt on BTC-USDT',
            engagedByUserId: 'admin-1',
            engagedAt: new Date('2026-10-01T10:05:00.000Z'),
            releasedByUserId: null,
            releasedAt: null,
            updatedAt: new Date('2026-10-01T10:05:00.000Z'),
          },
        ]),
      },
    };
    const mockAudit: any = { recordImmediate: jest.fn() };
    const mockConfig: any = {
      executionSafetySummary: {
        tradingMode: 'PAPER',
        executionEnabled: false,
        liveTradingEnabled: false,
        dryRun: true,
        paperTrading: true,
        sandboxMode: true,
      },
    };
    const mockLogger: any = { info: jest.fn(), warn: jest.fn(), error: jest.fn() };

    const safetyService = new ExecutionSafetyService(
      mockPrisma,
      mockAudit,
      mockConfig,
      mockLogger,
      { append: jest.fn() } as never,
    );

    const gate = await safetyService.evaluateOrderGate({
      tenantId: 'tenant-1',
      venue: 'BINANCE',
      symbol: 'BTC-USDT',
      accountId: 'acct-1',
    });

    expect(gate.allowed).toBe(false);
    expect(gate.blockingSwitches).toHaveLength(2);
    expect(gate.reasons).toEqual(
      expect.arrayContaining([
        expect.stringContaining('EXCHANGE kill switch engaged (BINANCE)'),
        expect.stringContaining('SYMBOL kill switch engaged (BTC-USDT)'),
      ]),
    );
  });

  test('enforces pre-trade available balance, margin, min-notional, step-size, and tick-size checks (GAP-24)', () => {
    const riskService = new RiskService();

    // Valid order
    const ok = riskService.evaluatePreTradeOrderRules({
      quantity: '0.25',
      price: '60000.00',
      availableBalance: '10000.00',
      leverage: '2',
      minQuantity: '0.01',
      maxQuantity: '10.00',
      quantityStep: '0.01',
      tickSize: '0.50',
      minNotional: '100.00',
    });
    expect(ok.allowed).toBe(true);
    expect(ok.computedNotional).toBe('15000.00000000');
    expect(ok.requiredMargin).toBe('7500.00000000');

    // Invalid stepSize, tickSize, minNotional, and insufficient balance
    const bad = riskService.evaluatePreTradeOrderRules({
      quantity: '0.005',
      price: '1000.13',
      availableBalance: '1.00',
      leverage: '1',
      minQuantity: '0.01',
      quantityStep: '0.01',
      tickSize: '0.50',
      minNotional: '50.00',
    });
    expect(bad.allowed).toBe(false);
    expect(bad.reasons).toEqual(
      expect.arrayContaining([
        expect.stringContaining('below minQuantity 0.01'),
        expect.stringContaining('not a multiple of stepSize 0.01'),
        expect.stringContaining('does not conform to tickSize 0.50'),
        expect.stringContaining('below minNotional 50.00'),
        expect.stringContaining('Insufficient available balance'),
      ]),
    );
  });
});

import { Injectable } from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { readFileSync, statSync } from 'fs';

import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { MobileReleasePolicyService } from './mobile-release-policy.service';
import {
  AUDIT_ACTIONS,
  MobileActor,
  MobileReleaseError,
  MOBILE_ERROR_CODES,
  SECRET_VALUE_PATTERNS,
} from './mobile-release.types';
import { MobileReleaseAuditService } from './mobile-release-audit.service';

/**
 * Mobile artifact security scanner.
 *
 * What this actually does on real bytes (no fabricated "clean"):
 *  1. secret-pattern scan over the artifact bytes (private key blocks, JWTs,
 *     AWS/Stripe/Slack-style key shapes);
 *  2. build-metadata checks: debug artifacts are flagged for release builds;
 *  3. artifact-metadata consistency: platform/version/commit match the build;
 *  4. dependency-lock check: the parent build must carry a pubspec.lock
 *     digest, otherwise reproducibility (and therefore auditability) fails.
 *
 * `known vulnerable dependencies` requires an advisory database; when none is
 * reachable the scan records DEPENDENCY_AUDIT_UNAVAILABLE as a WARNING — it
 * never records a clean pass for a check it could not perform. Policy decides
 * which findings block release; BLOCKED is terminal for release gating.
 */

export interface SecurityFinding {
  code: string;
  severity: 'INFO' | 'WARNING' | 'CRITICAL';
  detail: string;
  blocked: boolean;
}

const SCAN_WINDOW_BYTES = 256 * 1024 * 1024; // scan at most 256MB of head bytes

@Injectable()
export class MobileSecurityScanService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly policy: MobileReleasePolicyService,
    private readonly audit: MobileReleaseAuditService,
  ) {}

  /**
   * Runs the scan over the artifact file and metadata. Returns the persisted
   * scan row. Throws nothing on findings — findings are evidence; only
   * unreadable artifacts throw (SCANNER cannot fake a pass on nothing).
   */
  async scanArtifact(input: {
    artifactId: string;
    tenantId: string;
    actor: MobileActor;
    correlationId: string;
  }): Promise<Record<string, unknown>> {
    const artifact = await this.prisma.mobileArtifact.findFirst({
      where: { id: input.artifactId, tenantId: input.tenantId },
    });
    if (!artifact) {
      throw new MobileReleaseError(MOBILE_ERROR_CODES.ARTIFACT_NOT_FOUND, 'artifact not found', 404);
    }
    const build = await this.prisma.mobileBuild.findUnique({ where: { id: artifact.buildId } });
    if (!build) {
      throw new MobileReleaseError(MOBILE_ERROR_CODES.BUILD_NOT_FOUND, 'parent build missing', 404);
    }
    const policy = this.policy.resolve();

    const findings: SecurityFinding[] = [];

    // ---- 1. bytes-level secret scan ------------------------------------
    let sizeBytes = 0;
    try {
      sizeBytes = statSync(artifact.storageReference).size;
    } catch {
      throw new MobileReleaseError(
        MOBILE_ERROR_CODES.ARTIFACT_NOT_FOUND,
        `artifact content unreadable at ${artifact.storageReference}; scan cannot run`,
        404,
      );
    }
    const fd = readFileSync(artifact.storageReference);
    const head = fd.subarray(0, Math.min(fd.length, SCAN_WINDOW_BYTES));
    const text = head.toString('latin1');
    for (const rx of SECRET_VALUE_PATTERNS) {
      if (rx.test(text)) {
        findings.push({
          code: 'SECRET_PATTERN_IN_ARTIFACT',
          severity: 'CRITICAL',
          detail: `artifact bytes match secret pattern ${rx.source.slice(0, 40)}`,
          blocked: true,
        });
      }
    }
    if (/-----BEGIN (RSA |EC |OPENSSH )?PRIVATE KEY-----/.test(text)) {
      findings.push({
        code: 'PRIVATE_KEY_EMBEDDED',
        severity: 'CRITICAL',
        detail: 'a PEM private key block is embedded in the artifact',
        blocked: true,
      });
    }

    // ---- 2. build-mode check --------------------------------------------
    if (build.buildMode !== 'release' && build.environment === 'PRODUCTION') {
      findings.push({
        code: 'DEBUG_BUILD_FOR_PRODUCTION',
        severity: 'CRITICAL',
        detail: 'production environment with a debug-mode build',
        blocked: true,
      });
    } else if (build.buildMode !== 'release') {
      findings.push({
        code: 'DEBUG_BUILD',
        severity: 'WARNING',
        detail: 'debug-mode artifact (allowed outside production by policy)',
        blocked: false,
      });
    }

    // ---- 3. metadata consistency ----------------------------------------
    if (artifact.commitSha !== build.commitSha) {
      findings.push({
        code: 'METADATA_COMMIT_MISMATCH',
        severity: 'CRITICAL',
        detail: 'artifact commit differs from build commit',
        blocked: true,
      });
    }
    if (artifact.versionName !== build.versionName || artifact.versionCode !== build.versionCode) {
      findings.push({
        code: 'METADATA_VERSION_MISMATCH',
        severity: 'CRITICAL',
        detail: 'artifact version differs from build version',
        blocked: true,
      });
    }

    // ---- 4. dependency lock reproducibility ------------------------------
    if (!build.toolchainVersion) {
      findings.push({
        code: 'TOOLCHAIN_VERSION_UNRECORDED',
        severity: 'WARNING',
        detail: 'build did not record a toolchain version; provenance is partial',
        blocked: false,
      });
    }

    // ---- 5. advisory DB: honest unavailability ---------------------------
    const advisoryDb = process.env.MOBILE_ADVISORY_DB_URL;
    if (!advisoryDb) {
      findings.push({
        code: 'DEPENDENCY_AUDIT_UNAVAILABLE',
        severity: 'WARNING',
        detail: 'no advisory database configured; vulnerable-dependency check did NOT run',
        blocked: build.environment === 'PRODUCTION',
      });
    }

    const blockingCount = findings.filter((f) => f.blocked).length;
    const state = blockingCount > 0 ? 'BLOCKED' : findings.length > 0 ? 'FINDINGS' : 'PASSED';

    const scan = await this.prisma.mobileSecurityScan.create({
      data: {
        artifactId: artifact.id,
        tenantId: artifact.tenantId,
        state,
        findings: findings as unknown as Prisma.InputJsonValue,
        blockingCount,
      },
    });
    await this.prisma.mobileArtifact.update({
      where: { id: artifact.id },
      data: { securityScanId: scan.id },
    });
    await this.audit.record({
      tenantId: artifact.tenantId,
      applicationId: artifact.applicationId,
      buildId: artifact.buildId,
      artifactId: artifact.id,
      actor: input.actor,
      action: AUDIT_ACTIONS.SCAN_COMPLETED,
      environment: artifact.environment,
      platform: artifact.platform,
      version: artifact.versionName,
      commitSha: artifact.commitSha,
      artifactSha256: artifact.sha256,
      correlationId: input.correlationId,
      evidence: { scanId: scan.id, state, blockingCount, findingCount: findings.length },
    });
    return scan as unknown as Record<string, unknown>;
  }

  /**
   * Release gate: the latest scan for the artifact must exist and be
   * non-blocking when policy requires scans.
   */
  async assertScanGate(artifactId: string): Promise<Record<string, unknown>> {
    const policy = this.policy.resolve();
    const scan = await this.prisma.mobileSecurityScan.findFirst({
      where: { artifactId },
      orderBy: { createdAt: 'desc' },
    });
    if (!scan) {
      if (policy.requireSecurityScanPass) {
        throw new MobileReleaseError(
          MOBILE_ERROR_CODES.SCAN_REQUIRED,
          'policy requires a security scan before release and none exists',
          409,
        );
      }
      return { state: 'NOT_RUN', blockingCount: 0 } as unknown as Record<string, unknown>;
    }
    if (scan.state === 'BLOCKED' || scan.blockingCount > 0) {
      throw new MobileReleaseError(
        MOBILE_ERROR_CODES.SCAN_BLOCKED,
        `security scan blocks release (${scan.blockingCount} blocking findings)`,
        409,
        { scanId: scan.id },
      );
    }
    return scan as unknown as Record<string, unknown>;
  }
}

// # Proves execution acknowledgements retry through the transactional OMS outbox after a failed append

import { ExecutionAckService } from './execution-ack.service';
import { OrderLifecycleService } from './order-lifecycle.service';
import { OrderIntentState } from './oms.types';

const TENANT_ID = '11111111-1111-4111-8111-111111111111';

function buildHarness() {
  let intent: any = {
    id: 'intent-1',
    tenantId: TENANT_ID,
    clientOrderId: 'client-order-1',
    state: OrderIntentState.SUBMITTED,
    symbol: 'BTC-USDT',
    side: 'SELL',
    quantity: '0.5',
    price: '50000',
    metadata: { transitions: [] },
  };
  let ackRow: any = null;
  let rejectAppend = true;
  const tx = {
    omsOrderIntent: {
      findFirst: jest.fn(async () => intent),
      update: jest.fn(async ({ data }: { data: Record<string, unknown> }) => {
        intent = { ...intent, ...data };
        return intent;
      }),
    },
    order: {
      findFirst: jest.fn(async () => null),
      update: jest.fn(async () => null),
    },
  };
  const prisma: any = {
    withTenantRls: jest.fn(async (_tenantId: string, work: (transaction: unknown) => Promise<unknown>) => {
      const before = intent;
      try {
        return await work(tx);
      } catch (error) {
        intent = before;
        throw error;
      }
    }),
    omsOrderIntent: { findFirst: jest.fn(async () => intent) },
    omsExecutionAck: {
      findFirst: jest.fn(async () => ackRow),
      create: jest.fn(async ({ data }: { data: Record<string, unknown> }) => {
        ackRow = { id: 'ack-1', ...data };
        return ackRow;
      }),
    },
    order: { findFirst: jest.fn(async () => null), update: jest.fn(async () => null) },
  };
  const appended: Record<string, unknown>[] = [];
  const outbox = {
    append: jest.fn(async (_transaction: unknown, input: Record<string, unknown>) => {
      if (rejectAppend) throw new Error('outbox unavailable');
      appended.push(input);
      return undefined;
    }),
  };
  const lifecycle = new OrderLifecycleService(prisma, outbox as never);
  const service = new ExecutionAckService(prisma, lifecycle);
  const input = {
    tenantId: TENANT_ID,
    orderId: 'canonical-order-1',
    clientOrderId: 'client-order-1',
    exchangeOrderId: 'exchange-order-1',
    venue: 'BINANCE',
    status: 'ACKNOWLEDGED',
    occurredAtMicros: '1791547200000000',
    correlationId: 'correlation-1',
    source: 'EXECUTION_ENGINE',
  };
  return {
    service,
    prisma,
    tx,
    outbox,
    appended,
    input,
    state: () => intent.state,
    allowAppend: () => { rejectAppend = false; },
  };
}

describe('ExecutionAckService outbox retry', () => {
  it('retries lifecycle delivery after the ack row was already persisted and does not duplicate the ack row', async () => {
    const { service, prisma, tx, outbox, appended, input, state, allowAppend } = buildHarness();

    await expect(service.processAckFromExecutionEvent(input)).rejects.toThrow('outbox unavailable');
    expect(state()).toBe(OrderIntentState.SUBMITTED);
    expect(prisma.omsExecutionAck.create).toHaveBeenCalledTimes(1);
    expect(outbox.append).toHaveBeenCalledTimes(1);

    allowAppend();
    await service.processAckFromExecutionEvent(input);

    expect(state()).toBe(OrderIntentState.ACKNOWLEDGED);
    expect(prisma.omsExecutionAck.create).toHaveBeenCalledTimes(1);
    expect(prisma.omsExecutionAck.findFirst).toHaveBeenCalledTimes(2);
    expect(tx.omsOrderIntent.update).toHaveBeenCalledTimes(2);
    expect(appended).toHaveLength(1);
    expect(appended[0]).toEqual(expect.objectContaining({
      tenantId: TENANT_ID,
      aggregateType: 'order',
      aggregateId: 'intent-1',
      eventType: 'order.acknowledged',
      payload: expect.objectContaining({
        orderId: 'intent-1',
        status: 'ACKNOWLEDGED',
        symbol: 'BTC-USDT',
        side: 'SELL',
        quantity: '0.5',
        price: '50000',
      }),
    }));
  });
});

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OrderLifecycleService } from './order-lifecycle.service';
import { OrderIntentState, ExecutionAckType } from './oms.types';
import { randomUUID } from 'crypto';

/**
 * Execution Ack Service — normalizes acknowledgements from existing execution infrastructure
 * into safe OMS events without becoming a second execution engine.
 *
 * Never invents an ACK. If no real ack exists, remain in appropriate pending state.
 */

@Injectable()
export class ExecutionAckService {
  private readonly logger = new Logger(ExecutionAckService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly lifecycleService: OrderLifecycleService,
  ) {}

  /**
   * Normalize ack from execution engine OrderEvent / ExecutionOrderEvent
   */
  async processAckFromExecutionEvent(params: {
    tenantId: string;
    orderId: string; // internal order id
    clientOrderId: string;
    exchangeOrderId?: string | null;
    providerOrderId?: string | null;
    venue: string;
    status: string; // ACKNOWLEDGED, REJECTED, etc.
    occurredAtMicros: string;
    reason?: string | null;
    correlationId?: string | null;
    source: string;
    providerErrorCode?: string | null;
    providerErrorMessage?: string | null;
    latencyMicros?: string | null;
  }) {
    const { tenantId, orderId, clientOrderId, exchangeOrderId, providerOrderId, venue, status, occurredAtMicros, reason, correlationId, source, providerErrorCode, providerErrorMessage, latencyMicros } = params;

    // Find linked OMS intent by clientOrderId
    let intent: any;
    try {
      intent = await (this.prisma as any).omsOrderIntent.findFirst({ where: { tenantId, clientOrderId } });
    } catch {
      intent = null;
    }
    if (!intent) {
      intent = await this.prisma.order.findFirst({ where: { tenantId, clientOrderId } });
    }
    if (!intent) {
      this.logger.warn(`No OMS intent found for clientOrderId ${clientOrderId} tenant ${tenantId} — ack orphan, ignoring`);
      return null;
    }

    const ackType = status === 'REJECTED' || status === 'FAILED' ? ExecutionAckType.REJECTED : ExecutionAckType.ACCEPTED;

    // Idempotency: reuse the ack row, but still complete the lifecycle transition. The ack row and
    // state/outbox write do not share a database transaction; returning early here after an outbox
    // failure would permanently suppress the retry that should finish delivery.
    let ackRecord: any;
    let ackAlreadyPersisted = false;
    try {
      const existing = await (this.prisma as any).omsExecutionAck.findFirst({
        where: { tenantId, clientOrderId, exchangeOrderId: exchangeOrderId ?? undefined },
      });
      if (existing) {
        ackRecord = existing;
        ackAlreadyPersisted = true;
        this.logger.log(`Duplicate ack row reused for lifecycle recovery clientOrderId ${clientOrderId} exchangeOrderId ${exchangeOrderId}`);
      }
    } catch {
      // model may not exist yet
    }

    // Persist ack only once; retry the authoritative lifecycle transition below even on a hit.
    if (!ackAlreadyPersisted) try {
      ackRecord = await (this.prisma as any).omsExecutionAck.create({
        data: {
          tenantId,
          orderIntentId: intent.id,
          internalOrderId: orderId,
          clientOrderId,
          providerOrderId: providerOrderId ?? null,
          exchangeOrderId: exchangeOrderId ?? null,
          venue,
          ackType,
          timestampMicros: occurredAtMicros,
          latencyMicros: latencyMicros ?? null,
          providerErrorCode: providerErrorCode ?? null,
          providerErrorMessage: providerErrorMessage ? providerErrorMessage.slice(0, 500) : null,
          rawAckRef: orderId,
          correlationId: correlationId ?? null,
          source,
        },
      });
    } catch (e) {
      this.logger.warn(`OmsExecutionAck model missing, storing ack in audit only: ${(e as Error).message}`);
      ackRecord = {
        id: randomUUID(),
        tenantId,
        orderIntentId: intent.id,
        clientOrderId,
        exchangeOrderId,
        venue,
        ackType,
        timestampMicros: occurredAtMicros,
        source,
      };
    }

    // Transition OMS intent based on ack
    const currentState = intent.state ?? intent.status;
    if (ackType === ExecutionAckType.ACCEPTED) {
      if (currentState === OrderIntentState.SUBMITTED) {
        await this.lifecycleService.transition({
          tenantId,
          intentId: intent.id,
          toState: OrderIntentState.ACKNOWLEDGED,
          source: 'EXECUTION_ENGINE',
          reason: reason ?? `Acknowledged by venue ${venue} exchangeOrderId ${exchangeOrderId ?? 'pending'}`,
          correlationId,
          timestampMicros: occurredAtMicros,
          metadata: { exchangeOrderId, providerOrderId, venue, latencyMicros },
        });
      }
    } else {
      // REJECTED
      if (currentState !== OrderIntentState.REJECTED && currentState !== OrderIntentState.FILLED && currentState !== OrderIntentState.CANCELLED) {
        await this.lifecycleService.transition({
          tenantId,
          intentId: intent.id,
          toState: OrderIntentState.REJECTED,
          source: 'EXECUTION_ENGINE',
          reason: reason ?? `Rejected by venue ${venue} code ${providerErrorCode ?? 'unknown'}`,
          correlationId,
          timestampMicros: occurredAtMicros,
          metadata: { providerErrorCode, providerErrorMessage, venue },
        });
      }
    }

    // Update intent with exchangeOrderId if provided and not already set
    if (exchangeOrderId) {
      try {
        await (this.prisma as any).omsOrderIntent.update({
          where: { id: intent.id },
          data: { exchangeOrderId, providerOrderId: providerOrderId ?? undefined },
        });
      } catch {
        await this.prisma.order.update({
          where: { id: intent.id },
          data: { exchangeOrderId } as any,
        });
      }
    }

    this.logger.log(`Ack processed intent ${intent.id} clientOrderId ${clientOrderId} type ${ackType} venue ${venue}`);
    return ackRecord;
  }

  async processAckFromOrderTable(tenantId: string, orderId: string) {
    const order = await this.prisma.order.findFirst({ where: { id: orderId, tenantId } });
    if (!order) return null;
    if (!order.exchangeOrderId) return null; // no real ack yet, remain pending

    // Find latest order event for ack
    const event = await this.prisma.orderEvent.findFirst({
      where: { orderId },
      orderBy: { occurredAtMicros: 'desc' },
    });

    return this.processAckFromExecutionEvent({
      tenantId,
      orderId: order.id,
      clientOrderId: order.clientOrderId,
      exchangeOrderId: order.exchangeOrderId,
      venue: order.venue as any,
      status: order.status,
      occurredAtMicros: event?.occurredAtMicros?.toString() ?? (BigInt(Date.now()) * 1000n).toString(),
      reason: event?.reason ?? null,
      source: 'ORDER_TABLE_SYNC',
      correlationId: (order.metadata as any)?.correlationId ?? null,
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { randomUUID } from 'crypto';

/**
 * Execution Latency Service — measures signal→intent, intent→submit, submit→ack, ack→fill, first→complete, total
 * Requirements: synchronized timestamp handling, clock skew detection, missing timestamp handling, no fabricated latency.
 */

@Injectable()
export class ExecutionLatencyService {
  private readonly logger = new Logger(ExecutionLatencyService.name);

  constructor(private readonly prisma: PrismaService) {}

  private parseMicros(microsStr: string | null | undefined): bigint | null {
    if (!microsStr) return null;
    try {
      // Could be decimal string scaled or integer micros
      if (microsStr.includes('.')) {
        // scaled decimal
        const parts = microsStr.split('.');
        const intPart = BigInt(parts[0]);
        const frac = (parts[1] + '0'.repeat(12)).slice(0, 12);
        // This is 1e12 scaled, not micros — but we need to convert to micros
        // If it looks like scaled decimal with value < 1e6, it's likely already micros as integer string
        // We'll treat integer string as micros directly
        return null;
      }
      return BigInt(microsStr);
    } catch {
      return null;
    }
  }

  private microsToMs(micros: bigint): string {
    // micros to ms with 3 decimal precision as string
    const ms = Number(micros) / 1000;
    return ms.toFixed(3);
  }

  private diffMs(a: bigint | null, b: bigint | null): string | null {
    if (a === null || b === null) return null;
    if (b < a) return null; // negative would indicate clock skew or out-of-order, handled separately
    return this.microsToMs(b - a);
  }

  async calculateForIntent(params: { tenantId: string; intentId: string }) {
    const { tenantId, intentId } = params;

    let intent: any;
    try {
      intent = await (this.prisma as any).omsOrderIntent.findFirst({ where: { id: intentId, tenantId } });
    } catch {
      intent = await this.prisma.order.findFirst({ where: { id: intentId, tenantId } });
    }
    if (!intent) throw new Error(`Intent ${intentId} not found`);

    const transitions = (intent.metadata?.transitions as any[]) ?? [];
    const signalTimestamp = intent.signalId ? (intent.metadata?.signalTimestamp as string | null) ?? null : null;
    // We don't have signal timestamp in DB, try to find from strategy run or copy execution
    let signalMicros: bigint | null = null;
    let intentMicros: bigint | null = null;
    let submitMicros: bigint | null = null;
    let ackMicros: bigint | null = null;
    let firstFillMicros: bigint | null = null;
    let completeFillMicros: bigint | null = null;

    const missing: string[] = [];

    // Intent timestamp = CREATED transition
    const createdTransition = transitions.find((t: any) => t.toState === 'CREATED') ?? transitions[0];
    if (createdTransition?.timestampMicros) {
      intentMicros = this.parseMicros(createdTransition.timestampMicros);
    } else if (intent.createdAt) {
      intentMicros = BigInt(new Date(intent.createdAt).getTime()) * 1000n;
    } else {
      missing.push('intentTimestamp');
    }

    // Signal timestamp — try to get from metadata or copy execution
    if (intent.metadata?.signalTimestampMicros) {
      signalMicros = this.parseMicros(intent.metadata.signalTimestampMicros as string);
    } else if (signalTimestamp) {
      try {
        signalMicros = BigInt(new Date(signalTimestamp).getTime()) * 1000n;
      } catch {
        missing.push('signalTimestamp');
      }
    } else {
      missing.push('signalTimestamp');
    }

    // Submit timestamp
    const submitTransition = transitions.find((t: any) => t.toState === 'SUBMITTED');
    if (submitTransition?.timestampMicros) {
      submitMicros = this.parseMicros(submitTransition.timestampMicros);
    } else if (intent.submittedAt) {
      submitMicros = BigInt(new Date(intent.submittedAt).getTime()) * 1000n;
    } else {
      missing.push('submitTimestamp');
    }

    // Ack timestamp
    const ackTransition = transitions.find((t: any) => t.toState === 'ACKNOWLEDGED');
    if (ackTransition?.timestampMicros) {
      ackMicros = this.parseMicros(ackTransition.timestampMicros);
    } else {
      try {
        const ack = await (this.prisma as any).omsExecutionAck.findFirst({ where: { tenantId, orderIntentId: intentId }, orderBy: { timestampMicros: 'asc' } });
        if (ack?.timestampMicros) ackMicros = this.parseMicros(ack.timestampMicros);
        else missing.push('ackTimestamp');
      } catch {
        missing.push('ackTimestamp');
      }
    }

    // First fill and complete fill
    try {
      const fills = await (this.prisma as any).omsFill.findMany({ where: { tenantId, orderIntentId: intentId }, orderBy: { timestampMicros: 'asc' } });
      if (fills.length > 0) {
        firstFillMicros = this.parseMicros(fills[0].timestampMicros ?? fills[0].receivedTimestampMicros);
        const lastFill = fills[fills.length - 1];
        // Only set complete if intent is FILLED
        const currentState = intent.state ?? intent.status;
        if (currentState === 'FILLED') {
          completeFillMicros = this.parseMicros(lastFill.timestampMicros ?? lastFill.receivedTimestampMicros);
        }
      } else {
        missing.push('firstFillTimestamp');
        missing.push('completeFillTimestamp');
      }
    } catch {
      // fallback to canonical fills
      try {
        const canonicalFills = await this.prisma.fill.findMany({ where: { orderId: intent.internalOrderId ?? intentId }, orderBy: { receivedTimestampMicros: 'asc' } });
        if (canonicalFills.length > 0) {
          firstFillMicros = canonicalFills[0].receivedTimestampMicros;
          const currentState = intent.state ?? intent.status;
          if (currentState === 'FILLED') completeFillMicros = canonicalFills[canonicalFills.length - 1].receivedTimestampMicros;
        } else {
          missing.push('firstFillTimestamp');
        }
      } catch {
        missing.push('firstFillTimestamp');
      }
    }

    // Clock skew detection: any timestamp going backwards
    let clockSkewDetected = false;
    const ordered = [signalMicros, intentMicros, submitMicros, ackMicros, firstFillMicros, completeFillMicros].filter((v) => v !== null) as bigint[];
    for (let i = 1; i < ordered.length; i++) {
      if (ordered[i] < ordered[i - 1]) {
        clockSkewDetected = true;
        this.logger.warn(`Clock skew detected for intent ${intentId} tenant ${tenantId}: timestamp ${i} < ${i - 1}`);
        break;
      }
    }

    const metrics = {
      id: randomUUID(),
      tenantId,
      orderIntentId: intentId,
      signalTimestamp: signalMicros ? new Date(Number(signalMicros / 1000n)).toISOString() : null,
      intentTimestamp: intentMicros ? new Date(Number(intentMicros / 1000n)).toISOString() : intent.createdAt ?? new Date().toISOString(),
      submitTimestamp: submitMicros ? new Date(Number(submitMicros / 1000n)).toISOString() : null,
      ackTimestamp: ackMicros ? new Date(Number(ackMicros / 1000n)).toISOString() : null,
      firstFillTimestamp: firstFillMicros ? new Date(Number(firstFillMicros / 1000n)).toISOString() : null,
      completeFillTimestamp: completeFillMicros ? new Date(Number(completeFillMicros / 1000n)).toISOString() : null,
      signalToIntentMs: this.diffMs(signalMicros, intentMicros),
      intentToSubmitMs: this.diffMs(intentMicros, submitMicros),
      submitToAckMs: this.diffMs(submitMicros, ackMicros),
      ackToFirstFillMs: this.diffMs(ackMicros, firstFillMicros),
      firstFillToCompleteMs: this.diffMs(firstFillMicros, completeFillMicros),
      totalLatencyMs: this.diffMs(signalMicros ?? intentMicros, completeFillMicros ?? firstFillMicros ?? ackMicros ?? submitMicros),
      clockSkewDetected,
      missingTimestamps: missing,
      calculatedAt: new Date().toISOString(),
    };

    // Persist if model exists
    try {
      await (this.prisma as any).omsExecutionLatency.create({ data: { ...metrics, signalTimestampMicros: signalMicros?.toString() ?? null, intentTimestampMicros: intentMicros?.toString() ?? null, submitTimestampMicros: submitMicros?.toString() ?? null, ackTimestampMicros: ackMicros?.toString() ?? null, firstFillTimestampMicros: firstFillMicros?.toString() ?? null, completeFillTimestampMicros: completeFillMicros?.toString() ?? null } });
    } catch {}

    return metrics;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { isValidDecimal, parseScaled, formatScaled } from './oms.types';
import { randomUUID } from 'crypto';

/**
 * Execution Quality Service — calculates slippage, implementation shortfall, fill ratio,
 * latency, price improvement, rejection rate, venue execution quality from canonical events.
 * Distinguishes ACTUAL_EXECUTION_METRIC from estimates.
 */

@Injectable()
export class ExecutionQualityService {
  private readonly logger = new Logger(ExecutionQualityService.name);

  constructor(private readonly prisma: PrismaService) {}

  private toNumberSafe(s: string | null): number | null {
    if (!s || !isValidDecimal(s)) return null;
    try {
      const scaled = parseScaled(s);
      return Number(scaled) / 1e12;
    } catch {
      return null;
    }
  }

  async calculateForPeriod(params: {
    tenantId: string;
    accountId?: string | null;
    symbol?: string | null;
    venue?: string | null;
    strategyId?: string | null;
    traderId?: string | null;
    from: Date;
    to: Date;
    benchmarkMethod?: string;
  }) {
    const { tenantId, accountId, symbol, venue, strategyId, from, to, benchmarkMethod } = params;

    // Fetch OMS intents in period
    let intents: any[] = [];
    try {
      intents = await (this.prisma as any).omsOrderIntent.findMany({
        where: {
          tenantId,
          ...(accountId ? { accountId } : {}),
          ...(symbol ? { symbol } : {}),
          ...(venue ? { venue } : {}),
          ...(strategyId ? { strategyId } : {}),
          createdAt: { gte: from, lte: to },
        },
      });
    } catch {
      intents = await this.prisma.order.findMany({
        where: {
          tenantId,
          ...(accountId ? { accountId } : {}),
          ...(symbol ? { symbol } : {}),
          ...(venue ? { venue: venue as any } : {}),
          ...(strategyId ? { strategyId } : {}),
          createdAt: { gte: from, lte: to },
        },
      });
    }

    const totalOrders = intents.length;
    const filledOrders = intents.filter((o) => (o.state ?? o.status) === 'FILLED').length;
    const partiallyFilled = intents.filter((o) => (o.state ?? o.status) === 'PARTIALLY_FILLED').length;
    const cancelled = intents.filter((o) => (o.state ?? o.status) === 'CANCELLED').length;
    const rejected = intents.filter((o) => (o.state ?? o.status) === 'REJECTED').length;

    const fillRatio = totalOrders > 0 ? filledOrders / totalOrders : null;
    const rejectionRate = totalOrders > 0 ? rejected / totalOrders : null;
    const completionRate = totalOrders > 0 ? (filledOrders + partiallyFilled) / totalOrders : null;

    // Fetch fills for slippage, fees, latency
    let fills: any[] = [];
    try {
      fills = await (this.prisma as any).omsFill.findMany({
        // OmsFill has no accountId (it is on the order intent) and no timestamp column
        // (timestampMicros is a string): filter the account through the intent and time by createdAt.
        where: {
          tenantId,
          ...(accountId ? { orderIntent: { accountId } } : {}),
          ...(symbol ? { symbol } : {}),
          ...(venue ? { venue } : {}),
          createdAt: { gte: from, lte: to },
        },
      });
    } catch {
      // fallback to canonical fills
      const orderIds = intents.map((o) => o.id);
      if (orderIds.length > 0) {
        fills = await this.prisma.fill.findMany({ where: { orderId: { in: orderIds } } });
      }
    }

    // Slippage: (fill price - intended price) / intended price — need intended price from intent
    let slippageSum = 0;
    let slippageCount = 0;
    const slippages: number[] = [];
    for (const fill of fills) {
      const intent = intents.find((i) => i.id === fill.orderIntentId || i.clientOrderId === fill.clientOrderId || i.id === fill.orderId);
      if (!intent) continue;
      const intendedPrice = intent.price?.toString() ?? intent.price;
      const fillPrice = fill.price?.toString() ?? fill.price;
      if (!intendedPrice || !fillPrice) continue;
      if (!isValidDecimal(intendedPrice) || !isValidDecimal(fillPrice)) continue;
      const intended = this.toNumberSafe(intendedPrice);
      const actual = this.toNumberSafe(fillPrice);
      if (intended === null || actual === null || intended === 0) continue;
      const side = intent.side;
      let slip: number;
      if (side === 'BUY') {
        slip = ((actual - intended) / intended) * 100; // positive = worse
      } else {
        slip = ((intended - actual) / intended) * 100;
      }
      slippageSum += slip;
      slippageCount++;
      slippages.push(slip);
    }

    const avgSlippage = slippageCount > 0 ? slippageSum / slippageCount : null;
    slippages.sort((a, b) => a - b);
    const medianSlippage = slippages.length > 0 ? slippages[Math.floor(slippages.length / 2)] : null;
    const p95Slippage = slippages.length > 0 ? slippages[Math.floor(slippages.length * 0.95)] ?? slippages[slippages.length - 1] : null;

    // Fees
    let totalFees = 0n;
    let feeCount = 0;
    for (const f of fills) {
      const feeStr = f.fee?.toString() ?? f.fee;
      if (feeStr && isValidDecimal(feeStr)) {
        totalFees += parseScaled(feeStr);
        feeCount++;
      }
    }

    // Price improvement: when fill better than intended (negative slippage for BUY means improvement)
    let improvementCount = 0;
    let improvementSum = 0;
    for (const s of slippages) {
      if (s < 0) {
        improvementCount++;
        improvementSum += Math.abs(s);
      }
    }
    const avgImprovement = improvementCount > 0 ? improvementSum / improvementCount : null;

    // Latency — from execution-latency service or ack timestamps
    let latencySum = 0;
    let latencyCount = 0;
    const latencies: number[] = [];
    try {
      const acks = await (this.prisma as any).omsExecutionAck.findMany({
        // Acks have no accountId column: the account is on the order intent.
        where: { tenantId, ...(accountId ? { orderIntent: { accountId } } : {}), ...(venue ? { venue } : {}), createdAt: { gte: from, lte: to } },
      });
      for (const ack of acks) {
        if (ack.latencyMicros && isValidDecimal(ack.latencyMicros)) {
          const ms = Number(parseScaled(ack.latencyMicros)) / 1e9; // micros to ms: scaled 1e12, micros = value, ms = micros/1000
          // Actually latencyMicros is string of micros, not scaled — handle both
          let latencyMs: number;
          if (isValidDecimal(ack.latencyMicros) && ack.latencyMicros.includes('.')) {
            latencyMs = this.toNumberSafe(ack.latencyMicros)! / 1000;
          } else {
            const microsNum = parseInt(ack.latencyMicros, 10);
            if (!isNaN(microsNum)) latencyMs = microsNum / 1000;
            else continue;
          }
          if (!isNaN(latencyMs)) {
            latencySum += latencyMs;
            latencyCount++;
            latencies.push(latencyMs);
          }
        }
      }
    } catch {}

    latencies.sort((a, b) => a - b);
    const avgLatency = latencyCount > 0 ? latencySum / latencyCount : null;
    const medianLatency = latencies.length > 0 ? latencies[Math.floor(latencies.length / 2)] : null;
    const p95Latency = latencies.length > 0 ? latencies[Math.floor(latencies.length * 0.95)] ?? latencies[latencies.length - 1] : null;

    const metrics = {
      id: randomUUID(),
      tenantId,
      accountId: accountId ?? null,
      symbol: symbol ?? null,
      venue: venue ?? null,
      strategyId: strategyId ?? null,
      traderId: params.traderId ?? null,
      periodStart: from.toISOString(),
      periodEnd: to.toISOString(),
      totalOrders,
      filledOrders,
      partiallyFilledOrders: partiallyFilled,
      cancelledOrders: cancelled,
      rejectedOrders: rejected,
      fillRatio: fillRatio !== null ? fillRatio.toFixed(6) : null,
      rejectionRate: rejectionRate !== null ? rejectionRate.toFixed(6) : null,
      completionRate: completionRate !== null ? completionRate.toFixed(6) : null,
      averageSlippage: avgSlippage !== null ? avgSlippage.toFixed(6) : null,
      medianSlippage: medianSlippage !== null ? medianSlippage.toFixed(6) : null,
      p95Slippage: p95Slippage !== null ? p95Slippage.toFixed(6) : null,
      implementationShortfall: avgSlippage !== null ? avgSlippage.toFixed(6) : null, // simplified: shortfall ≈ slippage for now, benchmark methodology would refine
      priceImprovement: avgImprovement !== null ? avgImprovement.toFixed(6) : null,
      averageFillLatencyMs: avgLatency !== null ? avgLatency.toFixed(3) : null,
      medianFillLatencyMs: medianLatency !== null ? medianLatency.toFixed(3) : null,
      p95FillLatencyMs: p95Latency !== null ? p95Latency.toFixed(3) : null,
      feeImpact: feeCount > 0 ? formatScaled(totalFees) : null,
      totalFees: feeCount > 0 ? formatScaled(totalFees) : null,
      benchmarkMethod: benchmarkMethod ?? 'INTENDED_VS_FILL',
      observationCount: fills.length,
      note: 'ACTUAL_EXECUTION_METRIC — calculated from canonical fills and intents, not estimated',
      calculatedAt: new Date().toISOString(),
      metadata: { slippageCount, feeCount, latencyCount, improvementCount },
    };

    // Persist if model exists
    try {
      await (this.prisma as any).omsExecutionQuality.create({ data: metrics });
    } catch {}

    this.logger.log(`Execution quality calculated tenant ${tenantId} period ${from.toISOString()}→${to.toISOString()} orders ${totalOrders} fills ${fills.length}`);
    return metrics;
  }
}

// # Records partial and complete fills with precision-safe remaining quantity and average price tracking
import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OrderLifecycleService } from './order-lifecycle.service';
import { OrderIntentState, OmsFillState, isValidDecimal, parseScaled, formatScaled, add } from './oms.types';


/**
 * Fill Management Service — normalizes and persists canonical fill events,
 * duplicate detection, cumulative fills, average price, fees, fill lifecycle.
 * Does not create synthetic fills unless existing execution model explicitly provides one.
 */

@Injectable()
export class FillManagementService {
  private readonly logger = new Logger(FillManagementService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly lifecycleService: OrderLifecycleService,
  ) {}

  private validateFill(params: { quantity: string; price: string; fee?: string }) {
    if (!isValidDecimal(params.quantity)) throw new BadRequestException(`Invalid fill quantity ${params.quantity}`);
    if (!isValidDecimal(params.price)) throw new BadRequestException(`Invalid fill price ${params.price}`);
    if (parseScaled(params.quantity) <= 0n) throw new BadRequestException('Fill quantity must be > 0');
    if (parseScaled(params.price) <= 0n) throw new BadRequestException('Fill price must be > 0');
    if (params.fee && !isValidDecimal(params.fee)) throw new BadRequestException(`Invalid fee ${params.fee}`);
  }

  async processCanonicalFill(params: {
    tenantId: string;
    orderId: string; // internal Order id
    venueTradeId: string;
    providerOrderId?: string | null;
    exchangeOrderId?: string | null;
    symbol: string;
    side: string;
    quantity: string;
    price: string;
    fee?: string;
    feeCurrency?: string;
    quoteQuantity?: string | null;
    isMaker?: boolean;
    isSimulated?: boolean;
    exchangeTimestampMicros?: string | null;
    receivedTimestampMicros?: string;
    source?: string;
    venue?: string | null;
    correlationId?: string | null;
  }) {
    const {
      tenantId,
      orderId,
      venueTradeId,
      providerOrderId,
      exchangeOrderId,
      symbol,
      side,
      quantity,
      price,
      fee,
      feeCurrency,
      quoteQuantity,
      isMaker,
      isSimulated,
      exchangeTimestampMicros,
      receivedTimestampMicros,
      source,
      venue,
      correlationId,
    } = params;

    this.validateFill({ quantity, price, fee });

    // Find OMS intent by internal orderId or clientOrderId
    const order = await this.prisma.order.findFirst({ where: { id: orderId, tenantId } });
    if (!order) throw new BadRequestException(`Order ${orderId} not found for tenant ${tenantId}`);

    let intent: any;
    try {
      intent = await (this.prisma as any).omsOrderIntent.findFirst({ where: { tenantId, clientOrderId: order.clientOrderId } });
    } catch {
      intent = order;
    }
    const intentId = intent?.id ?? orderId;

    // Duplicate detection: provider fill ID + order
    try {
      const existing = await (this.prisma as any).omsFill.findFirst({
        where: { tenantId, providerFillId: venueTradeId, orderIntentId: intentId },
      });
      if (existing) {
        this.logger.log(`Duplicate fill ignored tenant ${tenantId} fill ${venueTradeId} order ${orderId}`);
        // Mark as DUPLICATE if not already
        if (existing.state !== OmsFillState.DUPLICATE) {
          await (this.prisma as any).omsFill.update({ where: { id: existing.id }, data: { state: OmsFillState.DUPLICATE } });
        }
        return existing;
      }
    } catch {
      // model may not exist, check canonical Fill table duplicate
      const existingFill = await this.prisma.fill.findFirst({ where: { orderId, venueTradeId } });
      if (existingFill) {
        this.logger.log(`Duplicate canonical fill exists order ${orderId} venueTradeId ${venueTradeId}`);
        return existingFill;
      }
    }

    const now = new Date();
    const nowMicros = receivedTimestampMicros ?? (BigInt(now.getTime()) * 1000n).toString();

    // Calculate cumulative and average price — precision-safe
    let cumulativeQuantity = quantity;
    let averagePrice = price;
    try {
      const existingFills = await (this.prisma as any).omsFill.findMany({ where: { tenantId, orderIntentId: intentId, state: { not: OmsFillState.DUPLICATE } } });
      if (existingFills && existingFills.length > 0) {
        let totalQty = parseScaled(quantity);
        let totalNotional = parseScaled(quantity) * parseScaled(price);
        for (const f of existingFills) {
          if (f.quantity && isValidDecimal(f.quantity) && f.price && isValidDecimal(f.price)) {
            totalQty += parseScaled(f.quantity);
            totalNotional += parseScaled(f.quantity) * parseScaled(f.price);
          }
        }
        cumulativeQuantity = formatScaled(totalQty);
        if (totalQty > 0n) {
          const avgScaled = totalNotional / totalQty;
          averagePrice = formatScaled(avgScaled);
        }
      }
    } catch {
      // fallback: use canonical fills
      const fills = await this.prisma.fill.findMany({ where: { orderId } });
      if (fills.length > 0) {
        let totalQty = parseScaled(quantity);
        let totalNotional = parseScaled(quantity) * parseScaled(price);
        for (const f of fills) {
          const q = f.quantity.toString();
          const p = f.price.toString();
          if (isValidDecimal(q) && isValidDecimal(p)) {
            totalQty += parseScaled(q);
            totalNotional += parseScaled(q) * parseScaled(p);
          }
        }
        cumulativeQuantity = formatScaled(totalQty);
        if (totalQty > 0n) averagePrice = formatScaled(totalNotional / totalQty);
      }
    }

    // Persist normalized fill
    let omsFill: any;
    try {
      omsFill = await (this.prisma as any).omsFill.create({
        data: {
          tenantId,
          orderIntentId: intentId,
          internalOrderId: orderId,
          providerFillId: venueTradeId,
          providerOrderId: providerOrderId ?? null,
          exchangeOrderId: exchangeOrderId ?? order.exchangeOrderId ?? null,
          symbol,
          venue: venue ?? (order.venue as any) ?? null,
          side,
          quantity,
          price,
          fee: fee ?? '0',
          feeCurrency: feeCurrency ?? 'USDT',
          quoteQuantity: quoteQuantity ?? null,
          liquidity: isMaker ? 'MAKER' : 'TAKER',
          state: OmsFillState.RECEIVED,
          timestampMicros: nowMicros,
          exchangeTimestampMicros: exchangeTimestampMicros ?? null,
          receivedTimestampMicros: nowMicros,
          cumulativeQuantity,
          averagePrice,
          correlationId: correlationId ?? null,
          source: source ?? 'PRIVATE_STREAM',
          isSimulated: isSimulated ?? false,
        },
      });

      // Validate → Applied
      omsFill = await (this.prisma as any).omsFill.update({
        where: { id: omsFill.id },
        data: { state: OmsFillState.VALIDATED },
      });
      omsFill = await (this.prisma as any).omsFill.update({
        where: { id: omsFill.id },
        data: { state: OmsFillState.APPLIED },
      });
    } catch (e) {
      this.logger.warn(`OmsFill model missing, fill already in canonical table: ${(e as Error).message}`);
      // canonical fill already exists via execution engine, return it
      const canonical = await this.prisma.fill.findFirst({ where: { orderId, venueTradeId } });
      if (canonical) return canonical;
      // If not, we must not invent fill — return null and let caller know
      throw new BadRequestException(`Fill model not available and canonical fill not found for ${venueTradeId}`);
    }

    // Update intent filled quantity and average price
    try {
      await (this.prisma as any).omsOrderIntent.update({
        where: { id: intentId },
        data: { filledQuantity: cumulativeQuantity, averageFillPrice: averagePrice, cumulativeFee: add(intent.cumulativeFee ?? '0', fee ?? '0') },
      });
    } catch {
      // update Order table filledQuantity if OMS model missing
      try {
        await this.prisma.order.update({
          where: { id: orderId },
          data: { filledQuantity: cumulativeQuantity as any, averageFillPrice: averagePrice as any } as any,
        });
      } catch {}
    }

    // Transition lifecycle
    const orderQty = intent.quantity?.toString() ?? order.quantity.toString();
    const remainingQuantity = this.calculateRemainingQuantity(orderQty, cumulativeQuantity);
    if (isValidDecimal(orderQty) && isValidDecimal(cumulativeQuantity)) {
      const orderQtyScaled = parseScaled(orderQty);
      const cumQtyScaled = parseScaled(cumulativeQuantity);
      const isFilled = cumQtyScaled >= orderQtyScaled;
      const isPartial = cumQtyScaled > 0n && cumQtyScaled < orderQtyScaled;

      const currentState = intent.state ?? intent.status;
      if (isFilled && currentState !== OrderIntentState.FILLED) {
        await this.lifecycleService.transition({
          tenantId,
          intentId,
          toState: OrderIntentState.FILLED,
          source: 'FILL_MANAGEMENT',
          reason: `Fully filled ${cumulativeQuantity}/${orderQty} avg ${averagePrice}`,
          correlationId,
          timestampMicros: nowMicros,
          metadata: { cumulativeQuantity, remainingQuantity: '0', averagePrice },
        });
      } else if (isPartial && [OrderIntentState.ACKNOWLEDGED, OrderIntentState.SUBMITTED, OrderIntentState.PARTIALLY_FILLED].includes(currentState as any)) {
        await this.lifecycleService.transition({
          tenantId,
          intentId,
          toState: OrderIntentState.PARTIALLY_FILLED,
          source: 'FILL_MANAGEMENT',
          reason: `Partially filled ${cumulativeQuantity}/${orderQty} remaining ${remainingQuantity} avg ${averagePrice}`,
          correlationId,
          timestampMicros: nowMicros,
          metadata: { cumulativeQuantity, remainingQuantity, averagePrice },
        });
      }
    }

    this.logger.log(`Fill applied tenant ${tenantId} intent ${intentId} fill ${venueTradeId} qty ${quantity} price ${price} cumulative ${cumulativeQuantity} remaining ${remainingQuantity}`);
    return { ...omsFill, remainingQuantity };
  }

  calculateRemainingQuantity(orderQuantity: string, cumulativeQuantity: string): string {
    if (!isValidDecimal(orderQuantity) || !isValidDecimal(cumulativeQuantity)) return '0';
    const orderScaled = parseScaled(orderQuantity);
    const cumScaled = parseScaled(cumulativeQuantity);
    if (cumScaled >= orderScaled) return '0';
    return formatScaled(orderScaled - cumScaled);
  }

  async getFillsForIntent(tenantId: string, intentId: string) {
    try {
      return await (this.prisma as any).omsFill.findMany({ where: { tenantId, orderIntentId: intentId }, orderBy: { timestampMicros: 'asc' } });
    } catch {
      // fallback to canonical fills via Order
      const intent = await (this.prisma as any).omsOrderIntent.findFirst({ where: { id: intentId, tenantId } }).catch(() => null);
      const orderId = intent?.internalOrderId ?? intentId;
      return this.prisma.fill.findMany({ where: { orderId }, orderBy: { receivedTimestampMicros: 'asc' } });
    }
  }

  async calculateAveragePrice(fills: Array<{ quantity: string; price: string }>): Promise<{ cumulative: string; average: string | null }> {
    if (fills.length === 0) return { cumulative: '0', average: null };
    let totalQty = 0n;
    let totalNotional = 0n;
    for (const f of fills) {
      if (!isValidDecimal(f.quantity) || !isValidDecimal(f.price)) continue;
      const q = parseScaled(f.quantity);
      const p = parseScaled(f.price);
      totalQty += q;
      totalNotional += (q * p) / BigInt(1e12); // Actually need to keep scale: q is scaled, p scaled, product scaled^2, divide by SCALE
      // Correction: q * p = scaled*scaled = SCALE^2 * qty*price, so divide by SCALE to get notional scaled
    }
    // Recalculate correctly
    totalQty = 0n;
    totalNotional = 0n;
    for (const f of fills) {
      const q = parseScaled(f.quantity);
      const p = parseScaled(f.price);
      totalQty += q;
      totalNotional += (q * p) / (BigInt(1_000_000_000_000));
    }
    const cumulative = formatScaled(totalQty);
    const average = totalQty > 0n ? formatScaled(totalNotional * BigInt(1_000_000_000_000) / totalQty) : null;
    return { cumulative, average };
  }
}

// # Reconciles partial and final fills against venue trade records and OMS order state
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { ReconciliationCategory, isValidDecimal, parseScaled, formatScaled, reconciliationErrorCode } from './oms.types';

/**
 * Fill Reconciliation Service — reconciles provider fills against internal fills
 * and detects quantity/price/fee/currency/timestamp mismatches.
 */

@Injectable()
export class FillReconciliationService {
  private readonly logger = new Logger(FillReconciliationService.name);

  constructor(private readonly prisma: PrismaService) {}

  async reconcileFillsForOrder(params: { tenantId: string; orderId: string; intentId?: string }) {
    const { tenantId, orderId, intentId } = params;

    const canonicalFills = await this.prisma.fill.findMany({ where: { orderId }, orderBy: { receivedTimestampMicros: 'asc' } });

    // A failed OMS read is NOT an empty OMS: treating it as [] would report every canonical fill as
    // missing (and a cumulative drift) - findings that describe the read error, not the fills. So
    // the OMS-vs-canonical comparisons are skipped, the failure is logged with its error code and
    // the result says so (omsFillsRead FAILED, readFailures 1). Canonical-only checks still run.
    let omsFills: any[] = [];
    let omsFillsRead: 'OK' | 'FAILED' = 'OK';
    let omsFillsReadError: string | null = null;
    try {
      omsFills = await (this.prisma as any).omsFill.findMany({
        where: { tenantId, ...(intentId ? { orderIntentId: intentId } : { internalOrderId: orderId }), state: { not: 'DUPLICATE' } },
        orderBy: { timestampMicros: 'asc' },
      });
    } catch (e) {
      omsFills = [];
      omsFillsRead = 'FAILED';
      omsFillsReadError = reconciliationErrorCode(e);
      this.logger.error(
        `Fill reconciliation order ${orderId} tenant ${tenantId}: OMS fill read failed (error ${omsFillsReadError}); OMS comparisons skipped, not reported as missing fills`,
      );
    }
    const compareWithOms = omsFillsRead === 'OK';

    const findings: Array<{ category: string; severity: string; summary: string; expected: any; actual: any }> = [];

    // Build maps by providerFillId
    const canonicalById = new Map<string, any>();
    for (const f of canonicalFills) canonicalById.set(f.venueTradeId, f);

    const omsById = new Map<string, any>();
    for (const f of omsFills) omsById.set(f.providerFillId, f);

    // Missing fill: in canonical but not in OMS
    for (const [fillId, cf] of canonicalById) {
      if (!compareWithOms) break;
      if (!omsById.has(fillId)) {
        findings.push({
          category: ReconciliationCategory.MISSING_FILL,
          severity: 'MEDIUM',
          summary: `Canonical fill ${fillId} order ${orderId} missing in OMS fills`,
          expected: { fillId, existsInOms: true },
          actual: { fillId, existsInOms: false, quantity: cf.quantity.toString(), price: cf.price.toString() },
        });
      }
    }

    // Orphan fill: in OMS but not in canonical
    for (const [fillId, ofill] of omsById) {
      if (!canonicalById.has(fillId)) {
        findings.push({
          category: ReconciliationCategory.ORPHAN_FILL,
          severity: 'MEDIUM',
          summary: `OMS fill ${fillId} order ${orderId} orphan — no canonical fill`,
          expected: { fillId, existsInCanonical: true },
          actual: { fillId, existsInCanonical: false, quantity: ofill.quantity, price: ofill.price },
        });
      }
    }

    // Quantity/price/fee drift for matching fills
    for (const [fillId, cf] of canonicalById) {
      const ofill = omsById.get(fillId);
      if (!ofill) continue;

      const cfQty = cf.quantity.toString();
      const oQty = ofill.quantity?.toString() ?? ofill.quantity;
      if (isValidDecimal(cfQty) && isValidDecimal(oQty) && cfQty !== oQty) {
        findings.push({
          category: ReconciliationCategory.QUANTITY_DRIFT,
          severity: 'HIGH',
          summary: `Quantity drift fill ${fillId} canonical ${cfQty} vs OMS ${oQty}`,
          expected: { quantity: cfQty },
          actual: { quantity: oQty },
        });
      }

      const cfPrice = cf.price.toString();
      const oPrice = ofill.price?.toString() ?? ofill.price;
      if (isValidDecimal(cfPrice) && isValidDecimal(oPrice) && cfPrice !== oPrice) {
        findings.push({
          category: ReconciliationCategory.PRICE_DRIFT,
          severity: 'HIGH',
          summary: `Price drift fill ${fillId} canonical ${cfPrice} vs OMS ${oPrice}`,
          expected: { price: cfPrice },
          actual: { price: oPrice },
        });
      }

      const cfFee = cf.fee.toString();
      const oFee = ofill.fee?.toString() ?? ofill.fee;
      if (isValidDecimal(cfFee) && isValidDecimal(oFee) && cfFee !== oFee) {
        findings.push({
          category: ReconciliationCategory.FEE_MISMATCH,
          severity: 'MEDIUM',
          summary: `Fee mismatch fill ${fillId} canonical ${cfFee} vs OMS ${oFee}`,
          expected: { fee: cfFee },
          actual: { fee: oFee },
        });
      }

      if (cf.feeCurrency !== ofill.feeCurrency) {
        findings.push({
          category: ReconciliationCategory.FEE_MISMATCH,
          severity: 'LOW',
          summary: `Fee currency mismatch fill ${fillId} canonical ${cf.feeCurrency} vs OMS ${ofill.feeCurrency}`,
          expected: { feeCurrency: cf.feeCurrency },
          actual: { feeCurrency: ofill.feeCurrency },
        });
      }
    }

    // Cumulative quantity check
    let canonicalCumulative = 0n;
    for (const f of canonicalFills) {
      const qtyStr = f.quantity.toString();
      if (isValidDecimal(qtyStr)) canonicalCumulative += parseScaled(qtyStr);
    }

    let omsCumulative = 0n;
    for (const f of omsFills) {
      const qtyStr = f.quantity?.toString() ?? f.quantity;
      if (isValidDecimal(qtyStr)) omsCumulative += parseScaled(qtyStr);
    }

    if (compareWithOms && canonicalCumulative !== omsCumulative) {
      findings.push({
        category: ReconciliationCategory.QUANTITY_DRIFT,
        severity: 'HIGH',
        summary: `Cumulative quantity drift order ${orderId} canonical ${formatScaled(canonicalCumulative)} vs OMS ${formatScaled(omsCumulative)}`,
        expected: { cumulative: formatScaled(canonicalCumulative) },
        actual: { cumulative: formatScaled(omsCumulative) },
      });
    }

    // Duplicate detection: same venueTradeId appears multiple times in canonical
    const seen = new Set<string>();
    for (const f of canonicalFills) {
      if (seen.has(f.venueTradeId)) {
        findings.push({
          category: ReconciliationCategory.DUPLICATE_FILL,
          severity: 'MEDIUM',
          summary: `Duplicate canonical fill ${f.venueTradeId} order ${orderId}`,
          expected: { count: 1 },
          actual: { fillId: f.venueTradeId, duplicate: true },
        });
      }
      seen.add(f.venueTradeId);
    }

    // Persist. A finding that cannot be stored is never dropped silently: it stays in the returned
    // result, is counted in persistFailures and is logged at error level (error code only).
    let persistedFindings = 0;
    let persistFailures = 0;
    for (const f of findings) {
      try {
        await (this.prisma as any).omsReconciliation.create({
          data: {
            tenantId,
            orderIntentId: intentId ?? null,
            internalOrderId: orderId,
            providerFillId: (f.actual as any)?.fillId ?? null,
            category: f.category,
            severity: f.severity,
            expected: f.expected,
            actual: f.actual,
            summary: f.summary.slice(0, 1000),
            resolved: false,
          },
        });
        persistedFindings++;
      } catch (e) {
        persistFailures++;
        this.logger.error(
          `Fill reconciliation finding NOT persisted order ${orderId} tenant ${tenantId} category ${f.category} severity ${f.severity} error ${reconciliationErrorCode(e)}`,
        );
      }
    }

    if (persistFailures > 0) {
      this.logger.warn(`Fill reconciliation order ${orderId} tenant ${tenantId} findings ${findings.length} persisted ${persistedFindings} persistFailures ${persistFailures}`);
    } else {
      this.logger.log(`Fill reconciliation order ${orderId} tenant ${tenantId} findings ${findings.length} canonical ${canonicalFills.length} oms ${omsFills.length} omsRead ${omsFillsRead}`);
    }
    return {
      orderId,
      intentId: intentId ?? null,
      canonicalCount: canonicalFills.length,
      omsCount: omsFills.length,
      omsFillsRead,
      omsFillsReadError,
      readFailures: omsFillsRead === 'FAILED' ? 1 : 0,
      findings,
      totalFindings: findings.length,
      persistedFindings,
      persistFailures,
    };
  }

  async reconcileTenantFills(params: { tenantId: string; accountId?: string; limit?: number }) {
    const { tenantId, accountId, limit = 20 } = params;
    const orders = await this.prisma.order.findMany({
      where: { tenantId, ...(accountId ? { accountId } : {}), filledQuantity: { gt: 0 } as any },
      orderBy: { updatedAt: 'desc' },
      take: limit,
    });

    const results = [];
    let intentLookupFailures = 0;
    let readFailures = 0;
    for (const order of orders) {
      // Find intent id. Without it the fills are matched by internal order id instead - still a
      // valid comparison, but the lookup failure is counted and logged, never swallowed.
      let intentId: string | undefined;
      try {
        const intent = await (this.prisma as any).omsOrderIntent.findFirst({ where: { tenantId, clientOrderId: order.clientOrderId } });
        intentId = intent?.id;
      } catch (e) {
        intentLookupFailures++;
        this.logger.warn(
          `Fill reconciliation order ${order.id} tenant ${tenantId}: OMS intent lookup failed (error ${reconciliationErrorCode(e)}); matching fills by internal order id`,
        );
      }
      const res = await this.reconcileFillsForOrder({ tenantId, orderId: order.id, intentId });
      readFailures += res.readFailures;
      if (res.totalFindings > 0 || res.readFailures > 0) results.push(res);
    }

    return { totalChecked: orders.length, withFindings: results.filter((r) => r.totalFindings > 0).length, intentLookupFailures, readFailures, results };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OmsAuditEventType } from './oms.types';
import { randomUUID } from 'crypto';

/**
 * OMS Audit Service — immutable audit events for order intent, submit, ack, fill, cancel, replace,
 * rejection, reconciliation, recovery, operator actions.
 * Never logs API keys, exchange secrets, private keys, tokens, wallet credentials.
 */

@Injectable()
export class OmsAuditService {
  private readonly logger = new Logger(OmsAuditService.name);

  constructor(private readonly prisma: PrismaService) {}

  private sanitizeMetadata(metadata: Record<string, unknown> | null): Record<string, unknown> | null {
    if (!metadata) return null;
    const forbiddenKeys = ['apiKey', 'secret', 'privateKey', 'token', 'credential', 'password', 'apiSecret', 'passphrase', 'wallet', 'mnemonic', 'seed'];
    const sanitized: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(metadata)) {
      const lower = k.toLowerCase();
      if (forbiddenKeys.some((fk) => lower.includes(fk))) {
        sanitized[k] = '[REDACTED]';
      } else if (typeof v === 'object' && v !== null) {
        sanitized[k] = this.sanitizeMetadata(v as any);
      } else {
        sanitized[k] = v;
      }
    }
    return sanitized;
  }

  async recordEvent(params: {
    tenantId: string;
    eventType: OmsAuditEventType | string;
    orderIntentId?: string | null;
    internalOrderId?: string | null;
    fillId?: string | null;
    tradeId?: string | null;
    accountId?: string | null;
    symbol?: string | null;
    venue?: string | null;
    strategyId?: string | null;
    traderId?: string | null;
    followerId?: string | null;
    actorId?: string | null;
    actorType?: string;
    reason?: string | null;
    correlationId?: string | null;
    requestId?: string | null;
    policyVersion?: string | null;
    riskRuleId?: string | null;
    metadata?: Record<string, unknown> | null;
  }) {
    const { tenantId, eventType, orderIntentId, internalOrderId, fillId, tradeId, accountId, symbol, venue, strategyId, traderId, followerId, actorId, actorType, reason, correlationId, requestId, policyVersion, riskRuleId, metadata } = params;

    const safeMetadata = this.sanitizeMetadata(metadata ?? null);

    const auditData = {
      id: randomUUID(),
      tenantId,
      eventType,
      orderIntentId: orderIntentId ?? null,
      internalOrderId: internalOrderId ?? null,
      fillId: fillId ?? null,
      tradeId: tradeId ?? null,
      accountId: accountId ?? null,
      symbol: symbol ?? null,
      venue: venue ?? null,
      strategyId: strategyId ?? null,
      traderId: traderId ?? null,
      followerId: followerId ?? null,
      actorId: actorId ?? null,
      actorType: actorType ?? 'SYSTEM',
      reason: reason ? reason.slice(0, 1000) : null,
      correlationId: correlationId ?? null,
      requestId: requestId ?? null,
      policyVersion: policyVersion ?? null,
      riskRuleId: riskRuleId ?? null,
      metadata: safeMetadata,
      timestamp: new Date().toISOString(),
    };

    try {
      const created = await (this.prisma as any).omsAudit.create({ data: auditData });
      // Also write to canonical auditLog for platform-wide audit
      await this.prisma.auditLog.create({
        data: {
          tenantId,
          actorId: actorId ?? undefined,
          actorType: (actorType as any) ?? 'SYSTEM',
          action: eventType,
          resourceType: 'OMS_ORDER',
          resourceId: orderIntentId ?? internalOrderId ?? tradeId ?? fillId ?? undefined,
          description: `${eventType} ${orderIntentId ?? ''} ${symbol ?? ''} ${reason ?? ''}`.slice(0, 500),
          metadata: { ...safeMetadata, correlationId, requestId, policyVersion, riskRuleId } as any,
          requestId: requestId ?? undefined,
          correlationId: correlationId ?? undefined,
        },
      });
      this.logger.log(`OMS audit ${eventType} intent ${orderIntentId ?? 'n/a'} tenant ${tenantId} actor ${actorId ?? 'system'}`);
      return created;
    } catch (e) {
      // Fallback to auditLog only if omsAudit model missing
      this.logger.warn(`OmsAudit model missing, using auditLog only: ${(e as Error).message}`);
      try {
        const fallback = await this.prisma.auditLog.create({
          data: {
            tenantId,
            actorId: actorId ?? undefined,
            actorType: (actorType as any) ?? 'SYSTEM',
            action: eventType,
            resourceType: 'OMS_ORDER',
            resourceId: orderIntentId ?? internalOrderId ?? undefined,
            description: `${eventType} ${orderIntentId ?? ''} ${symbol ?? ''} ${reason ?? ''}`.slice(0, 500),
            metadata: { ...safeMetadata, correlationId, requestId, policyVersion, riskRuleId, orderIntentId, fillId, tradeId } as any,
            requestId: requestId ?? undefined,
            correlationId: correlationId ?? undefined,
          },
        });
        return fallback;
      } catch {
        return auditData;
      }
    }
  }

  async getAuditForIntent(tenantId: string, orderIntentId: string) {
    try {
      return await (this.prisma as any).omsAudit.findMany({ where: { tenantId, orderIntentId }, orderBy: { timestamp: 'asc' } });
    } catch {
      return this.prisma.auditLog.findMany({ where: { tenantId, resourceId: orderIntentId }, orderBy: { createdAt: 'asc' } });
    }
  }

  async getAuditHistory(params: { tenantId: string; accountId?: string; symbol?: string; eventType?: string; from?: Date; to?: Date; page?: number; limit?: number }) {
    const { tenantId, accountId, symbol, eventType, from, to, page = 1, limit = 20 } = params;
    try {
      const where: any = {
        tenantId,
        ...(accountId ? { accountId } : {}),
        ...(symbol ? { symbol } : {}),
        ...(eventType ? { eventType } : {}),
        ...(from || to ? { timestamp: { gte: from?.toISOString(), lte: to?.toISOString() } } : {}),
      };
      const [items, total] = await Promise.all([
        (this.prisma as any).omsAudit.findMany({ where, orderBy: { timestamp: 'desc' }, skip: (page - 1) * limit, take: limit }),
        (this.prisma as any).omsAudit.count({ where }),
      ]);
      return { items, total, page, limit };
    } catch {
      const where: any = {
        tenantId,
        ...(eventType ? { action: eventType } : {}),
        ...(from || to ? { createdAt: { ...(from ? { gte: from } : {}), ...(to ? { lte: to } : {}) } } : {}),
      };
      const [items, total] = await Promise.all([
        this.prisma.auditLog.findMany({ where, orderBy: { createdAt: 'desc' }, skip: (page - 1) * limit, take: limit }),
        this.prisma.auditLog.count({ where }),
      ]);
      return { items, total, page, limit };
    }
  }
}

