  }

  @Get('reconciliation/queue')
  @RequireAnyPermission(Permission.TRADING_READ, Permission.COMPLIANCE_READ)
  async getReconQueue(@Req() req: any, @Query() query: OmsReconciliationQueryDto) {
    const tenantId = this.getTenantId(req);
    if (!this.isOperator(req)) throw new ForbiddenException('Operator required');
    return this.opsService.getReconciliationQueue({ tenantId, accountId: query.accountId });
  }

  // ---------- Operational ----------

  @Get('operational/stale-orders')
  @RequireAnyPermission(Permission.TRADING_READ, Permission.COMPLIANCE_READ)
  async getStaleOrders(@Req() req: any, @Query('accountId') accountId?: string) {
    const tenantId = this.getTenantId(req);
    if (!this.isOperator(req)) throw new ForbiddenException('Operator required');
    return this.opsService.getStaleOrders({ tenantId, accountId });
  }

  @Get('operational/rejected-orders')
  @RequireAnyPermission(Permission.TRADING_READ, Permission.COMPLIANCE_READ)
  async getRejectedOperational(@Req() req: any, @Query('accountId') accountId?: string) {
    const tenantId = this.getTenantId(req);
    if (!this.isOperator(req)) throw new ForbiddenException('Operator required');
    return this.opsService.getRejectedOrders({ tenantId, accountId });
  }

  @Post('operational/retry')
  async requestRetry(@Req() req: any, @Body() dto: RetryOrderDto) {
    const tenantId = this.getTenantId(req);
    if (!this.isOperator(req)) throw new ForbiddenException('Operator required');
    const userId = this.getUserId(req);
    const result = await this.opsService.requestRetry({ tenantId, intentId: dto.intentId, userId, reason: dto.reason });
    await this.auditService.recordEvent({ tenantId, eventType: OmsAuditEventType.RECOVERY_REQUESTED, orderIntentId: dto.intentId, actorId: userId, actorType: 'USER', reason: dto.reason, metadata: { type: 'RETRY' } });
    return result;
  }

  @Post('operational/recovery')
  async requestRecovery(@Req() req: any, @Body() dto: RecoveryOrderDto) {
    const tenantId = this.getTenantId(req);
    if (!this.isOperator(req)) throw new ForbiddenException('Operator required');
    const userId = this.getUserId(req);
    const result = await this.opsService.requestRecovery({ tenantId, intentId: dto.intentId, userId, reason: dto.reason, recoveryType: dto.recoveryType });
    await this.auditService.recordEvent({ tenantId, eventType: OmsAuditEventType.RECOVERY_REQUESTED, orderIntentId: dto.intentId, actorId: userId, actorType: 'USER', reason: dto.reason, metadata: { recoveryType: dto.recoveryType } });
    return result;
  }

  @Post('operational/acknowledge-exception')
  async acknowledgeException(@Req() req: any, @Body() dto: AcknowledgeExceptionDto) {
    const tenantId = this.getTenantId(req);
    if (!this.isOperator(req)) throw new ForbiddenException('Operator required');
    const userId = this.getUserId(req);
    const result = await this.opsService.acknowledgeException({ tenantId, operationalId: dto.operationalId, userId, note: dto.note });
    await this.auditService.recordEvent({ tenantId, eventType: OmsAuditEventType.OPERATOR_ACTION, actorId: userId, actorType: 'USER', reason: dto.note, metadata: { operationalId: dto.operationalId, action: 'ACKNOWLEDGE_EXCEPTION' } });
    return result;
  }

  @Post('operational/note')
  async addOperatorNote(@Req() req: any, @Body() dto: OperatorNoteDto) {
    const tenantId = this.getTenantId(req);
    if (!this.isOperator(req)) throw new ForbiddenException('Operator required');
    const userId = this.getUserId(req);
    return this.opsService.addOperatorNote({ tenantId, operationalId: dto.operationalId, userId, note: dto.note });
  }

  @Post('reconciliation/acknowledge')
  async acknowledgeReconciliation(@Req() req: any, @Body() dto: AcknowledgeReconciliationDto) {
    const tenantId = this.getTenantId(req);
    if (!this.isOperator(req)) throw new ForbiddenException('Operator required');
    const userId = this.getUserId(req);
    // Mark reconciliation as resolved
    try {
      const prisma = (this as any).prisma ?? null;
      // Use direct prisma from service if available — fallback
      const { PrismaService } = await import('../../infrastructure/prisma/prisma.service');
    } catch {}
    // Simplified: we don't have prisma here, use audit service to record
    await this.auditService.recordEvent({
      tenantId,
      eventType: OmsAuditEventType.OPERATOR_ACTION,
      actorId: userId,
      actorType: 'USER',
      reason: dto.resolutionNote,
      metadata: { reconciliationId: dto.reconciliationId, resolution: dto.resolution ?? 'RESOLVED' },
    });
    return { reconciliationId: dto.reconciliationId, resolvedBy: userId, resolutionNote: dto.resolutionNote };
  }

  // ---------- Allocation ----------

  @Get('allocations')
  @RequireAnyPermission(Permission.TRADING_READ, Permission.COMPLIANCE_READ)
  async getAllocations(@Req() req: any, @Query('accountId') accountId?: string, @Query('strategyId') strategyId?: string, @Query('traderId') traderId?: string, @Query('followerId') followerId?: string, @Query('symbol') symbol?: string) {
    const tenantId = this.getTenantId(req);
    this.checkTenantAccess(req, tenantId);
    return this.allocationService.getAllocations({ tenantId, accountId, strategyId, traderId, followerId, symbol });
  }

  @Get('allocations/summary')
  @RequireAnyPermission(Permission.TRADING_READ, Permission.COMPLIANCE_READ)
  async getAllocationSummary(@Req() req: any, @Query('strategyId') strategyId?: string, @Query('traderId') traderId?: string, @Query('followerId') followerId?: string) {
    const tenantId = this.getTenantId(req);
    this.checkTenantAccess(req, tenantId);
    return this.allocationService.getAllocationSummary({ tenantId, strategyId, traderId, followerId });
  }

  // ---------- Post-Trade ----------

  @Post('post-trade/:intentId')
  async processPostTrade(@Req() req: any, @Param('intentId') intentId: string) {
    const tenantId = this.getTenantId(req);
    if (!this.isOperator(req)) throw new ForbiddenException('Operator required');
    // Fetch intent to get account/symbol
    const intent = await this.intentService.getIntent(tenantId, intentId);
    if (!intent) throw new BadRequestException(`Intent ${intentId} not found`);
    return this.postTradeService.processPostTrade({
      tenantId,
      intentId,
      accountId: intent.accountId,
      symbol: intent.symbol,
      venue: intent.venue ?? null,
      strategyId: intent.strategyId ?? null,
      traderId: intent.traderId ?? null,
      followerId: intent.followerId ?? null,
      correlationId: intent.correlationId ?? null,
    });
  }

  // ---------- Audit ----------

  @Get('audit/:intentId')
  @RequireAnyPermission(Permission.TRADING_READ, Permission.COMPLIANCE_READ)
  async getAuditForIntent(@Req() req: any, @Param('intentId') intentId: string) {
    const tenantId = this.getTenantId(req);
    this.checkTenantAccess(req, tenantId);
    return this.auditService.getAuditForIntent(tenantId, intentId);
  }

  @Get('audit')
  @RequireAnyPermission(Permission.TRADING_READ, Permission.COMPLIANCE_READ)
  async getAuditHistory(@Req() req: any, @Query() query: OmsAuditQueryDto) {
    const tenantId = this.getTenantId(req);
    this.checkTenantAccess(req, tenantId);
    return this.auditService.getAuditHistory({
      tenantId,
      accountId: query.accountId,
      symbol: query.symbol,
      eventType: query.eventType,
      from: query.from ? new Date(query.from) : undefined,
      to: query.to ? new Date(query.to) : undefined,
      page: query.page,
      limit: query.limit,
    });
  }

  // ---------- Search (generic) ----------

  @Get('orders')
  @RequireAnyPermission(Permission.TRADING_READ, Permission.COMPLIANCE_READ)
  async searchOrders(@Req() req: any, @Query() query: OmsOrdersQueryDto) {
    const tenantId = this.getTenantId(req);
    this.checkTenantAccess(req, tenantId);
    return this.opsService.searchOrders({
      tenantId,
      accountId: query.accountId,
      strategyId: query.strategyId,
      traderId: query.traderId,
      followerId: query.followerId,
      symbol: query.symbol,
      venue: query.venue,
      state: query.state,
      from: query.from ? new Date(query.from) : undefined,
      to: query.to ? new Date(query.to) : undefined,
      page: query.page,
      limit: query.limit,
      search: query.search,
    });
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OrderLifecycleService } from './order-lifecycle.service';
import { OrderIntentState, isTerminalState } from './oms.types';
import { ExecutionOrdersService } from '../execution/execution-orders.service';
import { RiskDecisionService } from '../risk-management/risk-decision.service';

/**
 * Order Cancel Service — coordinates cancellation through existing execution infrastructure
 * and validates cancellability against current order state.
 * Never marks CANCELLED before authoritative confirmation unless provider semantics says request itself is terminal.
 */

@Injectable()
export class OrderCancelService {
  private readonly logger = new Logger(OrderCancelService.name);

  private static readonly CANCELLABLE_STATES = new Set<string>([
    OrderIntentState.SUBMITTED,
    OrderIntentState.ACKNOWLEDGED,
    OrderIntentState.PARTIALLY_FILLED,
    OrderIntentState.CREATED,
    OrderIntentState.VALIDATING,
    OrderIntentState.APPROVED,
  ]);

  constructor(
    private readonly prisma: PrismaService,
    private readonly lifecycleService: OrderLifecycleService,
    private readonly executionOrdersService: ExecutionOrdersService,
    private readonly riskDecisionService: RiskDecisionService,
  ) {}

  async requestCancel(params: {
    tenantId: string;
    intentId: string;
    userId?: string | null;
    reason: string;
    correlationId?: string | null;
  }) {
    const { tenantId, intentId, userId, reason, correlationId } = params;

    let intent: any;
    try {
      intent = await (this.prisma as any).omsOrderIntent.findFirst({ where: { id: intentId, tenantId } });
    } catch {
      intent = await this.prisma.order.findFirst({ where: { id: intentId, tenantId } });
    }
    if (!intent) throw new BadRequestException(`Intent ${intentId} not found`);

    const currentState = intent.state ?? intent.status;
    if (isTerminalState(currentState)) {
      throw new BadRequestException(`Cannot cancel terminal order ${intentId} state ${currentState}`);
    }
    if (currentState === OrderIntentState.CANCEL_REQUESTED) {
      this.logger.log(`Cancel already requested for ${intentId}, idempotent`);
      return intent;
    }
    if (!OrderCancelService.CANCELLABLE_STATES.has(currentState)) {
      throw new BadRequestException(`Order ${intentId} not cancellable in state ${currentState}`);
    }
    if (currentState === OrderIntentState.FILLED) {
      throw new BadRequestException(`Cannot cancel already FILLED order ${intentId}`);
    }

    // Risk/compliance/security checks if policy requires — for cancel, usually allowed as risk-reducing
    // But check if account is blocked for security
    const threat = await this.prisma.securityThreatSignal.findFirst({
      where: { tenantId, resolved: false, riskLevel: { in: ['HIGH', 'CRITICAL'] as any } },
      orderBy: { createdAt: 'desc' },
    });
    if (threat && threat.decision === 'DENY') {
      // Even cancel should be allowed? For safety, allow cancel as risk-reducing unless policy explicitly blocks
      this.logger.warn(`Security threat exists but allowing cancel as risk-reducing for ${intentId}`);
    }

    // Transition to CANCEL_REQUESTED
    await this.lifecycleService.transition({
      tenantId,
      intentId,
      toState: OrderIntentState.CANCEL_REQUESTED,
      source: 'OMS_CANCEL',
      reason: `Cancel requested: ${reason}`,
      correlationId,
      actorId: userId ?? null,
      actorType: userId ? 'USER' : 'SYSTEM',
    });

    // Call existing execution cancel boundary — ExecutionOrdersService.requestCancel
    try {
      const canonicalOrder = await this.prisma.order.findFirst({ where: { tenantId, clientOrderId: intent.clientOrderId } });
      const orderIdToCancel = canonicalOrder?.id ?? intent.id;

      const result = await this.executionOrdersService.requestCancel(
        tenantId,
        orderIdToCancel,
        { userId: userId ?? 'system', requestId: correlationId ?? null },
        reason,
      );

      this.logger.log(`Cancel command accepted for intent ${intentId} order ${orderIdToCancel} via ExecutionOrdersService`);
      return { intentId, orderId: orderIdToCancel, state: OrderIntentState.CANCEL_REQUESTED, order: result };
    } catch (e) {
      this.logger.warn(`Cancel command failed for ${intentId}: ${(e as Error).message}`);
      throw new BadRequestException(`Cancel request failed: ${(e as Error).message}`);
    }
  }

  async confirmCancelled(params: {
    tenantId: string;
    intentId: string;
    exchangeOrderId?: string | null;
    reason?: string | null;
    timestampMicros?: string | null;
    correlationId?: string | null;
  }) {
    const { tenantId, intentId, exchangeOrderId, reason, timestampMicros, correlationId } = params;

    let intent: any;
    try {
      intent = await (this.prisma as any).omsOrderIntent.findFirst({ where: { id: intentId, tenantId } });
    } catch {
      intent = await this.prisma.order.findFirst({ where: { id: intentId, tenantId } });
    }
    if (!intent) throw new BadRequestException(`Intent ${intentId} not found`);

    const currentState = intent.state ?? intent.status;
    if (currentState === OrderIntentState.CANCELLED) return intent;
    if (currentState === OrderIntentState.FILLED) throw new BadRequestException(`Cannot confirm CANCELLED for already FILLED order ${intentId}`);

    await this.lifecycleService.transition({
      tenantId,
      intentId,
      toState: OrderIntentState.CANCELLED,
      source: 'EXECUTION_ENGINE',
      reason: reason ?? `Cancelled confirmed by provider exchangeOrderId ${exchangeOrderId ?? 'unknown'}`,
      correlationId,
      timestampMicros,
    });

    this.logger.log(`Intent ${intentId} confirmed CANCELLED tenant ${tenantId}`);
    return intent;
  }
}

// # Validates order intent against symbol trading rules and account balance
import { Injectable, Logger, BadRequestException, ForbiddenException, Optional } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OutboxService } from '../../infrastructure/outbox/outbox.service';
import { RiskDecisionService } from '../risk-management/risk-decision.service';
import { OrderIntentState, isValidDecimal, parseScaled } from './oms.types';
import { PositionLimitService } from '../risk/position-limit.service';
import { randomUUID } from 'crypto';

/**
 * Order Intent Service — creates/validates normalized order intents from strategy/copy/risk-approved requests
 * without placing orders directly.
 *
 * Before creating an intent verify:
 * - strategy state, account state, symbol, quantity/price precision, risk decision, compliance, security, exchange capability, env, live gate
 * MUST NOT place order.
 */

@Injectable()
export class OrderIntentService {
  private readonly logger = new Logger(OrderIntentService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly riskDecisionService: RiskDecisionService,
    // Every intent is reserved under the user's own concurrent-position and open-order ceilings.
    // This reaches the canonical limiter rather than a copy of it, so the count a customer reads
    // from their settings page is the count this path enforces.
    private readonly positionLimitService: PositionLimitService,
    @Optional() private readonly outbox?: OutboxService,
  ) {}

  private async appendOrderCreated(tx: any, created: any, input: {
    tenantId: string;
    symbol: string;
    side: string;
    quantity: string;
    price?: string | null;
    correlationId?: string | null;
  }): Promise<void> {
    if (!this.outbox) {
      throw new Error('Transactional outbox is unavailable; refusing order intent without its order.created event');
    }
    await this.outbox.append(tx, {
      tenantId: input.tenantId,
      aggregateType: 'order',
      aggregateId: created.id,
      eventType: 'order.created',
      idempotencyKey: `order:${created.id}:created`,
      correlationId: input.correlationId && input.correlationId.length <= 64 ? input.correlationId : null,
      occurredAt: created.createdAt ?? new Date(),
      payload: {
        orderId: created.id,
        status: 'CREATED',
        symbol: input.symbol,
        side: input.side,
        quantity: input.quantity,
        price: input.price ?? null,
      },
    });
  }

  private async validateAccountOwnership(params: { tenantId: string; accountId: string; userId?: string | null }) {
    const account = await this.prisma.tradingAccount.findFirst({
      where: { id: params.accountId, tenantId: params.tenantId },
    });
    if (!account) throw new ForbiddenException(`Account ${params.accountId} not found for tenant ${params.tenantId}`);
    if (account.status === 'DISABLED') throw new BadRequestException(`Account ${params.accountId} is DISABLED`);
    if (account.status === 'CREDENTIALS_INVALID') throw new BadRequestException(`Account credentials invalid`);
    return account;
  }

  private async validateSymbol(params: { tenantId: string; symbol: string; venue?: string | null }) {
    // Check trading symbol exists and is tradeable
    const symbolRecord = await this.prisma.tradingSymbol.findFirst({
      where: {
        tenantId: params.tenantId,
        symbol: params.symbol,
        isTradeable: true,
        ...(params.venue ? { exchange: { venue: params.venue as any } } : {}),
      },
      include: { exchange: true },
    });
    if (!symbolRecord) throw new BadRequestException(`Symbol ${params.symbol} not tradeable for tenant ${params.tenantId}`);
    return symbolRecord;
  }

  private validatePrecision(params: { quantity: string; price?: string | null; symbol: any }) {
    if (!isValidDecimal(params.quantity)) throw new BadRequestException(`Invalid quantity decimal: ${params.quantity}`);
    const qty = parseScaled(params.quantity);
    if (qty <= 0n) throw new BadRequestException('Quantity must be > 0');

    const minQty = params.symbol.minQuantity ? parseScaled(params.symbol.minQuantity.toString()) : 0n;
    if (qty < minQty) throw new BadRequestException(`Quantity ${params.quantity} below min ${params.symbol.minQuantity}`);

    if (params.symbol.maxQuantity) {
      const maxQty = parseScaled(params.symbol.maxQuantity.toString());
      if (qty > maxQty) throw new BadRequestException(`Quantity ${params.quantity} above max ${params.symbol.maxQuantity}`);
    }

    if (params.price) {
      if (!isValidDecimal(params.price)) throw new BadRequestException(`Invalid price decimal: ${params.price}`);
      const price = parseScaled(params.price);
      if (price <= 0n) throw new BadRequestException('Price must be > 0');

      if (params.symbol.tickSize) {
        const tick = parseScaled(params.symbol.tickSize.toString());
        if (tick > 0n && price % tick !== 0n) {
          throw new BadRequestException(`Price ${params.price} does not match tickSize ${params.symbol.tickSize}`);
        }
      }

      if (params.symbol.minNotional) {
        const minNotional = parseScaled(params.symbol.minNotional.toString());
        const notional = (qty * price) / 100000000n;
        if (notional < minNotional) {
          throw new BadRequestException(`Order notional below minNotional ${params.symbol.minNotional}`);
        }
      }
    }

    if (params.symbol.quantityStep) {
      const step = parseScaled(params.symbol.quantityStep.toString());
      if (step > 0n && qty % step !== 0n) {
        throw new BadRequestException(`Quantity ${params.quantity} does not match quantityStep ${params.symbol.quantityStep}`);
      }
    }
  }

  private async checkStrategyState(params: { tenantId: string; strategyId?: string | null }) {
    if (!params.strategyId) return null;
    const strategy = await this.prisma.strategy.findFirst({
      where: { id: params.strategyId, tenantId: params.tenantId },
    });
    if (!strategy) throw new BadRequestException(`Strategy ${params.strategyId} not found`);
    if (strategy.status === 'DISABLED') throw new BadRequestException(`Strategy ${params.strategyId} DISABLED`);
    if (strategy.status === 'ERROR') throw new BadRequestException(`Strategy ${params.strategyId} in ERROR state`);
    return strategy;
  }

  async createIntent(params: {
    tenantId: string;
    accountId: string;
    symbol: string;
    side: string;
    orderType: string;
    quantity: string;
    price?: string | null;
    stopPrice?: string | null;
    timeInForce?: string;
    reduceOnly?: boolean;
    strategyId?: string | null;
    traderId?: string | null;
    followerId?: string | null;
    subscriptionId?: string | null;
    environment: string;
    source: string;
    signalId?: string | null;
    correlationId?: string | null;
    requestId?: string | null;
    userId?: string | null;
    venue?: string | null;
    /** Phase 3: producer links carried on the intent (e.g. copyExecutionId),
     * forwarded by routeIntent onto the canonical order and the SUBMIT_ORDER
     * job. String values only; never used for any decision. */
    metadata?: Record<string, string> | null;
  }) {
    const {
      tenantId,
      accountId,
      symbol,
      side,
      orderType,
      quantity,
      price,
      stopPrice,
      timeInForce,
      reduceOnly,
      strategyId,
      traderId,
      followerId,
      subscriptionId,
      environment,
      source,
      signalId,
      correlationId,
      requestId,
      userId,
      venue,
      metadata: producerMetadata,
    } = params;

    // Tenant ownership validation
    await this.validateAccountOwnership({ tenantId, accountId, userId });
    const symbolRecord = await this.validateSymbol({ tenantId, symbol, venue });
    this.validatePrecision({ quantity, price, symbol: symbolRecord });
    await this.checkStrategyState({ tenantId, strategyId });

    if (!['BUY', 'SELL'].includes(side)) throw new BadRequestException(`Invalid side ${side}`);
    if (!['MARKET', 'LIMIT', 'STOP', 'STOP_LIMIT'].includes(orderType)) throw new BadRequestException(`Invalid orderType ${orderType}`);
    if (orderType === 'LIMIT' && !price) throw new BadRequestException('LIMIT order requires price');
    if (['STOP', 'STOP_LIMIT'].includes(orderType) && !stopPrice) throw new BadRequestException(`${orderType} requires stopPrice`);
    if (!['PAPER', 'LIVE'].includes(environment)) throw new BadRequestException(`Invalid environment ${environment}`);
    if (!['STRATEGY', 'COPY_TRADING', 'MANUAL', 'RESEARCH_PROMOTION'].includes(source)) throw new BadRequestException(`Invalid source ${source}`);

    // Risk decision — must be APPROVED before intent creation if policy requires
    // We do a pre-check via RiskDecisionService but do not trust client-supplied risk approval
    let riskDecisionId: string | null = null;
    let riskPolicyVersion: string | null = null;
    try {
      const riskResult = await this.riskDecisionService.evaluateUnifiedRisk({
        tenantId,
        userId: (userId ?? undefined) as any,
        accountId,
        symbol,
        traderId: traderId as any,
        followerId: followerId as any,
        strategyId: strategyId as any,
        orderIntent: { side: side as any, quantity, price: price ?? null, orderType: orderType as any } as any,
        environment: environment as any,
        requestId: requestId as any,
      } as any);
      riskDecisionId = riskResult.id;
      riskPolicyVersion = riskResult.policyVersion;
      if (riskResult.decision === 'BLOCK' || riskResult.decision === 'KILL_SWITCH_REQUIRED') {
        throw new BadRequestException(`Risk blocked: ${riskResult.blockingReasons.join(', ')}`);
      }
    } catch (e) {
      if (e instanceof BadRequestException) throw e;
      this.logger.warn(`Risk check failed for intent creation tenant ${tenantId} symbol ${symbol}: ${(e as Error).message}`);
      // Fail closed if risk unavailable for LIVE
      if (environment === 'LIVE') throw new BadRequestException(`Risk check unavailable for LIVE order: ${(e as Error).message}`);
    }

    // Compliance check — reuse compliance screening
    const complianceScreen = await this.prisma.complianceScreeningRequest.findFirst({
      where: { tenantId, status: 'BLOCKED' as any },
      orderBy: { createdAt: 'desc' },
    });
    if (complianceScreen) {
      // If tenant has active compliance block, prevent
      const isBlocked = complianceScreen.decision === 'BLOCK';
      if (isBlocked) throw new ForbiddenException(`Compliance BLOCK prevents order intent`);
    }

    // Security state — check threat signals
    const threat = await this.prisma.securityThreatSignal.findFirst({
      where: { tenantId, resolved: false, riskLevel: { in: ['HIGH', 'CRITICAL'] as any } },
      orderBy: { createdAt: 'desc' },
    });
    if (threat && threat.decision === 'DENY') {
      throw new ForbiddenException(`Security BLOCK prevents order intent: ${threat.safeSummary}`);
    }

    // Exchange capability check
    const exchange = symbolRecord.exchange;
    if (!exchange.isEnabled) throw new BadRequestException(`Exchange ${exchange.venue} not enabled`);
    if (environment === 'LIVE' && !exchange.tradingEnabled) throw new BadRequestException(`Exchange ${exchange.venue} trading not enabled for LIVE`);

    // Live gate requirements — check account liveTradingEnabled for LIVE
    const account = await this.prisma.tradingAccount.findUnique({ where: { id: accountId } });
    if (environment === 'LIVE' && !account?.liveTradingEnabled) {
      throw new ForbiddenException(`Live trading not enabled for account ${accountId}`);
    }

    // 35 characters of [A-Za-z0-9]: fits Order.clientOrderId (VarChar(36)) and
    // the execution core's CLIENT_ORDER_ID_PATTERN ([A-Za-z0-9_-]{1,36}). The
    // previous `oms-${uuid}` form was 40 characters and could not be stored on
    // the canonical order row nor accepted by the engine.
    const clientOrderId = `oms${randomUUID().replace(/-/g, '')}`;
    const safeProducerMetadata: Record<string, string> = {};
    for (const [key, value] of Object.entries(producerMetadata ?? {})) {
      if (typeof value === 'string' && value.length <= 128 && /^[A-Za-z][A-Za-z0-9_]{0,63}$/.test(key)) {
        safeProducerMetadata[key] = value;
      }
    }
    const now = new Date();
    const nowIso = now.toISOString();
    const micros = (BigInt(now.getTime()) * 1000n).toString();

    const transition = {
      eventId: randomUUID(),
      fromState: null,
      toState: OrderIntentState.CREATED,
      timestamp: nowIso,
      timestampMicros: micros,
      source: 'OMS',
      reason: `Order intent created from ${source} symbol ${symbol} side ${side} qty ${quantity}`,
      correlationId: correlationId ?? null,
      policyVersion: riskPolicyVersion,
      riskRuleId: null,
      actorId: userId ?? null,
      actorType: userId ? 'USER' : 'SYSTEM',
      metadata: { strategyId, traderId, followerId, subscriptionId, environment, signalId },
    };

    // The ceiling check and the write are one atomic unit: the limiter takes the per-user
    // advisory lock, measures canonical active reservations, and only then runs this callback.
    // The callback must write through the supplied client - a write on `this.prisma` would commit
    // outside the lock, and two intents racing would both observe the pre-insert count and pass a
    // ceiling they jointly exceed.
    return this.positionLimitService.persistOrderIntentWithLimits({
      tenantId,
      accountId,
      symbol,
      persist: async (tx) => {
        // The write is wrapped in a savepoint because it has a fallback. A failed statement aborts
        // the surrounding transaction in PostgreSQL, so without the savepoint the fallback insert
        // would run inside an aborted transaction and fail too - the fallback would look defensive
        // and be unreachable. Rolling back to the savepoint restores the transaction to a usable
        // state first.
        await (tx as any).$executeRaw`SAVEPOINT oms_order_intent_persist`;
        // Persist as OmsOrderIntent if model exists, else fallback to Order with metadata
        try {
          const created = await (tx as any).omsOrderIntent.create({
            data: {
              tenantId,
              accountId,
              strategyId: strategyId ?? undefined,
              traderId: traderId ?? undefined,
              followerId: followerId ?? undefined,
              subscriptionId: subscriptionId ?? undefined,
              symbol,
              venue: exchange.venue,
              side,
              orderType,
              timeInForce: timeInForce ?? 'GTC',
              quantity,
              price: price ?? undefined,
              stopPrice: stopPrice ?? undefined,
              reduceOnly: reduceOnly ?? false,
              environment,
              state: OrderIntentState.CREATED,
              clientOrderId,
              signalId: signalId ?? undefined,
              riskDecisionId,
              riskPolicyVersion: riskPolicyVersion ?? undefined,
              correlationId: correlationId ?? undefined,
              requestId: requestId ?? undefined,
              source,
              metadata: { ...safeProducerMetadata, transitions: [transition], symbolId: symbolRecord.id },
              filledQuantity: '0',
              cumulativeFee: '0',
              isSimulated: environment === 'PAPER',
              wasDryRun: false,
            },
          });
          await this.appendOrderCreated(tx, created, { tenantId, symbol, side, quantity, price, correlationId });
          await (tx as any).$executeRaw`RELEASE SAVEPOINT oms_order_intent_persist`;
          this.logger.log(`OMS intent ${created.id} CREATED tenant ${tenantId} symbol ${symbol} qty ${quantity}`);
          return created;
        } catch (e) {
          await (tx as any).$executeRaw`ROLLBACK TO SAVEPOINT oms_order_intent_persist`;
          const error = e as { code?: string; meta?: { modelName?: string }; message?: string };
          const missingIntentModel = !(tx as any).omsOrderIntent?.create ||
            ((error.code === 'P2021' || error.code === 'P2022') && error.meta?.modelName === 'OmsOrderIntent');
          if (!missingIntentModel) throw e;
          // Fallback only when the OmsOrderIntent model/table is unavailable; event validation and
          // outbox failures must never be mistaken for a persistence-model migration gap.
          this.logger.warn(`OmsOrderIntent model missing, falling back to Order table: ${error.message ?? 'model unavailable'}`);
          const created = await (tx as any).order.create({
            data: {
              tenantId,
              accountId,
              strategyId: strategyId ?? undefined,
              symbolId: symbolRecord.id,
              clientOrderId,
              venue: exchange.venue,
              symbol,
              side: side as any,
              orderType: orderType as any,
              timeInForce: (timeInForce as any) ?? 'GTC',
              status: 'PENDING' as any,
              quantity: quantity as any,
              price: price as any,
              stopPrice: stopPrice as any,
              reduceOnly: reduceOnly ?? false,
              isSimulated: environment === 'PAPER',
              wasDryRun: false,
              metadata: { ...safeProducerMetadata, omsIntent: true, transitions: [transition], source, correlationId, riskDecisionId, environment, signalId } as any,
            },
          });
          await this.appendOrderCreated(tx, created, { tenantId, symbol, side, quantity, price, correlationId });
          return created;
        }
      },
    });
  }

  async getIntent(tenantId: string, intentId: string) {
    try {
      const intent = await (this.prisma as any).omsOrderIntent.findFirst({ where: { id: intentId, tenantId } });
      if (intent) return intent;
    } catch {}
    return this.prisma.order.findFirst({ where: { id: intentId, tenantId } });
  }

  async listIntents(params: { tenantId: string; accountId?: string; strategyId?: string; symbol?: string; state?: string; page?: number; limit?: number }) {
    const { tenantId, accountId, strategyId, symbol, state, page = 1, limit = 20 } = params;
    try {
      return await (this.prisma as any).omsOrderIntent.findMany({
        where: { tenantId, ...(accountId ? { accountId } : {}), ...(strategyId ? { strategyId } : {}), ...(symbol ? { symbol } : {}), ...(state ? { state } : {}) },
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      });
    } catch {
      return this.prisma.order.findMany({
        where: { tenantId, ...(accountId ? { accountId } : {}), ...(strategyId ? { strategyId } : {}), ...(symbol ? { symbol } : {}), ...(state ? { status: state as any } : {}) },
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      });
    }
  }
}

// # Proves OMS acknowledgement, fill, and rejection transitions commit with distinct outbox events

import { OrderLifecycleService } from './order-lifecycle.service';
import { OrderIntentState } from './oms.types';
import { validateDeveloperEventPayload } from '../developer-platform/event-schemas/developer-event-schemas';

const TENANT_ID = '11111111-1111-4111-8111-111111111111';

function buildHarness(initialState: string, failAppend = false) {
  let current: any = {
    id: 'order-aggregate-1',
    tenantId: TENANT_ID,
    state: initialState,
    symbol: 'BTC-USDT',
    side: 'BUY',
    quantity: '0.25',
    filledQuantity: '0.25',
    price: '60000.00',
    averageFillPrice: '59999.50',
    correlationId: 'correlation-1',
    metadata: { transitions: [] },
  };
  const tx = {
    omsOrderIntent: {
      findFirst: jest.fn(async () => current),
      update: jest.fn(async ({ data }: { data: Record<string, unknown> }) => {
        current = { ...current, ...data };
        return current;
      }),
    },
    order: {
      findFirst: jest.fn(async () => current),
      update: jest.fn(async ({ data }: { data: Record<string, unknown> }) => {
        current = { ...current, ...data, state: data.status };
        return current;
      }),
    },
  };
  const prisma = {
    withTenantRls: jest.fn(async (_tenantId: string, work: (transaction: unknown) => Promise<unknown>) => {
      const before = current;
      try {
        return await work(tx);
      } catch (error) {
        current = before;
        throw error;
      }
    }),
  };
  const appended: Record<string, unknown>[] = [];
  const outbox = {
    append: jest.fn(async (_transaction: unknown, input: Record<string, unknown>) => {
      if (failAppend) throw new Error('outbox unavailable');
      appended.push(input);
      return undefined;
    }),
  };
  const service = new OrderLifecycleService(prisma as never, outbox as never);
  return { service, prisma, tx, outbox, appended, current: () => current };
}

describe('OrderLifecycleService developer events', () => {
  it('emits schema-valid acknowledgement, then a separately idempotent fill event on the same aggregate', async () => {
    const { service, prisma, tx, outbox, appended } = buildHarness(OrderIntentState.SUBMITTED);
    await service.transition({
      tenantId: TENANT_ID,
      intentId: 'order-aggregate-1',
      toState: OrderIntentState.ACKNOWLEDGED,
      source: 'EXECUTION_ENGINE',
      reason: 'Venue acknowledged the order.',
    });
    await service.transition({
      tenantId: TENANT_ID,
      intentId: 'order-aggregate-1',
      toState: OrderIntentState.FILLED,
      source: 'FILL_MANAGEMENT',
      reason: 'Venue fill completed the order.',
    });

    expect(prisma.withTenantRls).toHaveBeenCalledTimes(2);
    expect(tx.omsOrderIntent.update).toHaveBeenCalledTimes(2);
    expect(outbox.append).toHaveBeenCalledTimes(2);
    expect(appended.map((event) => event.eventType)).toEqual(['order.acknowledged', 'order.filled']);
    for (const event of appended) {
      expect(validateDeveloperEventPayload(String(event.eventType), event.payload)).toEqual({ valid: true, errors: [] });
    }
    expect(appended.map((event) => event.aggregateId)).toEqual(['order-aggregate-1', 'order-aggregate-1']);
    expect(appended[0]?.idempotencyKey).not.toBe(appended[1]?.idempotencyKey);
    expect(appended[0]?.payload).toEqual(expect.objectContaining({
      orderId: 'order-aggregate-1',
      status: 'ACKNOWLEDGED',
      symbol: 'BTC-USDT',
      side: 'BUY',
      quantity: '0.25',
      price: '60000.00',
    }));
    expect(appended[1]?.payload).toEqual(expect.objectContaining({
      orderId: 'order-aggregate-1',
      status: 'FILLED',
      symbol: 'BTC-USDT',
      side: 'BUY',
      quantity: '0.25',
      price: '59999.50',
    }));
    expect(appended[0]?.idempotencyKey).toContain('transition:');
    expect(appended[1]?.idempotencyKey).toContain('transition:');
  });

  it('emits a rejection event through the same state-and-event transaction', async () => {
    const { service, tx, outbox } = buildHarness(OrderIntentState.SUBMITTED);
    await service.transition({
      tenantId: TENANT_ID,
      intentId: 'order-aggregate-1',
      toState: OrderIntentState.REJECTED,
      source: 'EXECUTION_ENGINE',
      reason: 'Venue rejected the order.',
    });

    expect(tx.omsOrderIntent.update).toHaveBeenCalledTimes(1);
    expect(outbox.append).toHaveBeenCalledWith(tx, expect.objectContaining({
      aggregateId: 'order-aggregate-1',
      eventType: 'order.rejected',
      payload: expect.objectContaining({ orderId: 'order-aggregate-1', status: 'REJECTED' }),
    }));
  });

  it('rolls the lifecycle write back when the event cannot be appended', async () => {
    const { service, tx, outbox, current } = buildHarness(OrderIntentState.SUBMITTED, true);
    await expect(service.transition({
      tenantId: TENANT_ID,
      intentId: 'order-aggregate-1',
      toState: OrderIntentState.ACKNOWLEDGED,
      source: 'EXECUTION_ENGINE',
      reason: 'Venue acknowledged the order.',
    })).rejects.toThrow('outbox unavailable');

    expect(tx.omsOrderIntent.update).toHaveBeenCalledTimes(1);
    expect(outbox.append).toHaveBeenCalledTimes(1);
    expect(current().state).toBe(OrderIntentState.SUBMITTED);
  });
});

// # Manages canonical OMS order state transitions including PARTIALLY_FILLED and FILLED
import { Injectable, Logger, BadRequestException, Optional } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OutboxService } from '../../infrastructure/outbox/outbox.service';
import { OrderIntentState, VALID_TRANSITIONS, isValidTransition, isTerminalState, TERMINAL_STATES } from './oms.types';
import { randomUUID } from 'crypto';

/**
 * Order Lifecycle Service — controls valid state transitions, idempotency, event ordering,
 * terminal-state protection, and lifecycle history.
 */

@Injectable()
export class OrderLifecycleService {
  private readonly logger = new Logger(OrderLifecycleService.name);

  constructor(
    private readonly prisma: PrismaService,
    @Optional() private readonly outbox?: OutboxService,
  ) {}

  private isMissingIntentModel(error: unknown): boolean {
    const candidate = error as { code?: string; message?: string; meta?: { modelName?: string } };
    if (candidate.code !== 'P2021' && candidate.code !== 'P2022') return false;
    return candidate.meta?.modelName === 'OmsOrderIntent' || /OmsOrderIntent/.test(candidate.message ?? '');
  }

  async transition(params: {
    tenantId: string;
    intentId: string;
    toState: OrderIntentState | string;
    source: string;
    reason: string;
    correlationId?: string | null;
    policyVersion?: string | null;
    riskRuleId?: string | null;
    actorId?: string | null;
    actorType?: string;
    metadata?: Record<string, unknown> | null;
    timestampMicros?: string | null;
  }) {
    const { tenantId, intentId, toState, source, reason, correlationId, policyVersion, riskRuleId, actorId, actorType, metadata, timestampMicros } = params;
    const now = new Date();
    const nowIso = now.toISOString();
    const micros = timestampMicros ?? (BigInt(now.getTime()) * 1000n).toString();

    return this.prisma.withTenantRls(tenantId, async (tx) => {
      const store = tx as any;
      const intentDelegate = store.omsOrderIntent;
      let useIntentModel = typeof intentDelegate?.findFirst === 'function';
      let intent: any = null;
      if (useIntentModel) {
        try {
          intent = await intentDelegate.findFirst({ where: { id: intentId, tenantId } });
        } catch (error) {
          if (!this.isMissingIntentModel(error)) throw error;
          useIntentModel = false;
        }
      }
      if (!useIntentModel) {
        intent = await store.order.findFirst({ where: { id: intentId, tenantId } });
      }
      if (!intent) throw new BadRequestException(`Intent ${intentId} not found for tenant ${tenantId}`);

      const currentState = intent.state ?? intent.status;
      if (!currentState) throw new BadRequestException(`Intent ${intentId} has no state`);

      // Idempotency: same-state transition is allowed and is no-op.
      if (currentState === toState) {
        this.logger.log(`Idempotent transition ${intentId} ${currentState} → ${toState} source ${source}`);
        return intent;
      }
      if (isTerminalState(currentState)) {
        throw new BadRequestException(`Cannot transition from terminal state ${currentState} to ${toState} for intent ${intentId}`);
      }
      if (!isValidTransition(currentState, toState)) {
        throw new BadRequestException(`Invalid transition ${currentState} → ${toState} for intent ${intentId}. Allowed: ${(VALID_TRANSITIONS[currentState] || []).join(', ')}`);
      }

      const developerEventType = toState === OrderIntentState.ACKNOWLEDGED
        ? 'order.acknowledged'
        : toState === OrderIntentState.FILLED
          ? 'order.filled'
          : toState === OrderIntentState.REJECTED
            ? 'order.rejected'
            : null;
      if (developerEventType && !this.outbox) {
        throw new Error(`Transactional outbox is unavailable; refusing ${toState} order transition without ${developerEventType}`);
      }

      const transitions = (intent.metadata?.transitions as any[]) ?? [];
      if (transitions.length > 0) {
        const last = transitions[transitions.length - 1];
        if (last?.timestampMicros) {
          const lastMicros = BigInt(last.timestampMicros);
          const newMicros = BigInt(micros);
          if (newMicros < lastMicros) {
            this.logger.warn(`Out-of-order event detected for intent ${intentId}: last ${last.timestampMicros} new ${micros} transition ${currentState}→${toState}`);
          }
        }
      }

      const event = {
        eventId: randomUUID(),
        fromState: currentState,
        toState,
        timestamp: nowIso,
        timestampMicros: micros,
        source,
        reason: reason.slice(0, 1000),
        correlationId: correlationId ?? intent.correlationId ?? null,
        policyVersion: policyVersion ?? null,
        riskRuleId: riskRuleId ?? null,
        actorId: actorId ?? null,
        actorType: actorType ?? 'SYSTEM',
        metadata: metadata ?? null,
      };
      const newMetadata = {
        ...(intent.metadata as any),
        transitions: [...transitions, event],
      };
      const omsData = {
        state: toState,
        metadata: newMetadata,
        ...(toState === OrderIntentState.SUBMITTED ? { submittedAt: now } : {}),
        ...(toState === OrderIntentState.ACKNOWLEDGED ? { acknowledgedAt: now } : {}),
        ...(TERMINAL_STATES.has(toState) ? { terminalAt: now } : {}),
        updatedAt: now,
      };

      let updated: any;
      if (useIntentModel) {
        try {
          updated = await intentDelegate.update({ where: { id: intentId }, data: omsData });
        } catch (error) {
          if (!this.isMissingIntentModel(error)) throw error;
          useIntentModel = false;
        }
      }
      if (!useIntentModel) {
        updated = await store.order.update({
          where: { id: intentId },
          data: {
            status: toState as any,
            metadata: newMetadata as any,
            ...(TERMINAL_STATES.has(toState) ? { terminalAt: now } : {}),
            updatedAt: now,
          },
        });
      }

      if (developerEventType) {
        const decimalString = (value: unknown): string | null => {
          if (value === null || value === undefined) return null;
          return typeof value === 'string' ? value : String(value);
        };
        const orderId = intent.id;
        const rawQuantity = toState === OrderIntentState.FILLED
          ? (intent.filledQuantity ?? intent.quantity)
          : intent.quantity;
        const rawPrice = toState === OrderIntentState.FILLED
          ? (intent.averageFillPrice ?? intent.price)
          : intent.price;
        const side = intent.side === 'BUY' || intent.side === 'SELL' ? intent.side : null;
        const outboxPayload = {
          orderId,
          status: toState,
          symbol: typeof intent.symbol === 'string' ? intent.symbol : null,
          side,
          quantity: decimalString(rawQuantity),
          price: decimalString(rawPrice),
        };
        await this.outbox!.append(tx, {
          tenantId,
          aggregateType: 'order',
          aggregateId: orderId,
          eventType: developerEventType,
          idempotencyKey: `order:${orderId}:transition:${event.eventId}`,
          correlationId: event.correlationId && event.correlationId.length <= 64 ? event.correlationId : null,
          occurredAt: now,
          payload: outboxPayload,
        });
      }

      this.logger.log(`Intent ${intentId} transitioned ${currentState} → ${toState} via ${source} reason ${reason}`);
      return updated;
    });
  }

  async getHistory(tenantId: string, intentId: string) {
    let intent: any;
    try {
      intent = await (this.prisma as any).omsOrderIntent.findFirst({ where: { id: intentId, tenantId } });
    } catch {
      intent = await this.prisma.order.findFirst({ where: { id: intentId, tenantId } });
    }
    if (!intent) throw new BadRequestException(`Intent ${intentId} not found`);
    return (intent.metadata?.transitions as any[]) ?? [];
  }

  async isTerminal(tenantId: string, intentId: string): Promise<boolean> {
    let intent: any;
    try {
      intent = await (this.prisma as any).omsOrderIntent.findFirst({ where: { id: intentId, tenantId } });
    } catch {
      intent = await this.prisma.order.findFirst({ where: { id: intentId, tenantId } });
    }
    if (!intent) return false;
    return isTerminalState(intent.state ?? intent.status);
  }
}

// # Responsibility: reconcile OMS intent, exchange order, fills, and lifecycle history without rewriting truth.
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { ReconciliationCategory, isTerminalState, isValidDecimal, isValidTransition, reconciliationErrorCode } from './oms.types';


/**
 * Order Reconciliation Service — reconciles OMS intent ↔ execution engine ↔ exchange order ↔ fills ↔ positions
 * and identifies missing/duplicate/stale/mismatched state.
 * Never silently rewrites order history.
 */

@Injectable()
export class OrderReconciliationService {
  private readonly logger = new Logger(OrderReconciliationService.name);

  constructor(private readonly prisma: PrismaService) {}

  async reconcileOrder(params: { tenantId: string; intentId: string }) {
    const { tenantId, intentId } = params;

    // The OMS intent table is the source of truth. If reading it fails, the canonical order row is
    // used instead - and that substitution is never silent: it is logged with the error code and
    // reported as intentSource / intentReadError in the result.
    let intent: any;
    let intentSource: 'OMS_INTENT' | 'CANONICAL_ORDER_FALLBACK' = 'OMS_INTENT';
    let intentReadError: string | null = null;
    try {
      intent = await (this.prisma as any).omsOrderIntent.findFirst({ where: { id: intentId, tenantId } });
    } catch (e) {
      intentSource = 'CANONICAL_ORDER_FALLBACK';
      intentReadError = reconciliationErrorCode(e);
      this.logger.warn(
        `Order reconciliation intent ${intentId} tenant ${tenantId}: OMS intent read failed (error ${intentReadError}); reconciling from the canonical order row`,
      );
      intent = await this.prisma.order.findFirst({ where: { id: intentId, tenantId } });
    }
    if (!intent) throw new Error(`Intent ${intentId} not found`);

    const findings: Array<{ category: string; severity: string; summary: string; expected: any; actual: any }> = [];

    const clientOrderId = intent.clientOrderId;
    const exchangeOrderId = intent.exchangeOrderId ?? intent.exchangeOrderId;
    const currentState = intent.state ?? intent.status;

    // Fetch canonical order by clientOrderId
    const canonicalOrder = await this.prisma.order.findFirst({ where: { tenantId, clientOrderId } });
    if (!canonicalOrder) {
      findings.push({
        category: ReconciliationCategory.MISSING_EXCHANGE_ORDER,
        severity: 'HIGH',
        summary: `OMS intent ${intentId} clientOrderId ${clientOrderId} has no canonical Order record`,
        expected: { canonicalOrderExists: true },
        actual: { clientOrderId, found: false },
      });
    } else {
      // Check exchangeOrderId presence
      if (!canonicalOrder.exchangeOrderId && ['ACKNOWLEDGED', 'PARTIALLY_FILLED', 'FILLED'].includes(currentState)) {
        findings.push({
          category: ReconciliationCategory.MISSING_EXCHANGE_ORDER,
          severity: 'MEDIUM',
          summary: `Intent ${intentId} state ${currentState} but canonical order ${canonicalOrder.id} has no exchangeOrderId`,
          expected: { exchangeOrderIdExists: true },
          actual: { state: currentState, exchangeOrderId: null },
        });
      }

      // Check ack
      if (!canonicalOrder.exchangeOrderId && currentState === 'SUBMITTED') {
        // Check if ack exists in execution events
        const ackEvent = await this.prisma.orderEvent.findFirst({ where: { orderId: canonicalOrder.id, status: { in: ['ACKNOWLEDGED', 'PARTIALLY_FILLED', 'FILLED'] as any } } });
        if (!ackEvent) {
          findings.push({
            category: ReconciliationCategory.MISSING_ACK,
            severity: 'MEDIUM',
            summary: `Intent ${intentId} SUBMITTED but no ack event for canonical order ${canonicalOrder.id}`,
            expected: { ackExists: true },
            actual: { state: currentState, ackFound: false },
          });
        }
      }

      // Provider status mismatch
      if (canonicalOrder && (canonicalOrder.status as any) !== currentState) {
        // Allow some valid differences: OMS SUBMITTED vs canonical ACKNOWLEDGED is okay (timing)
        const validMismatch = (currentState === 'SUBMITTED' && ['ACKNOWLEDGED', 'PARTIALLY_FILLED', 'FILLED'].includes(canonicalOrder.status as any)) ||
          (currentState === 'ACKNOWLEDGED' && ['PARTIALLY_FILLED', 'FILLED'].includes(canonicalOrder.status as any));
        if (!validMismatch) {
          findings.push({
            category: ReconciliationCategory.PROVIDER_STATUS_MISMATCH,
            severity: currentState === 'FILLED' || canonicalOrder.status === 'FILLED' ? 'HIGH' : 'MEDIUM',
            summary: `Status mismatch intent ${intentId} OMS ${currentState} vs canonical ${canonicalOrder.status}`,
            expected: { omsState: currentState },
            actual: { canonicalStatus: canonicalOrder.status },
          });
        }
      }

      // Quantity mismatch
      const intentQty = intent.quantity?.toString() ?? intent.quantity;
      const canonicalQty = canonicalOrder.quantity.toString();
      if (isValidDecimal(intentQty) && isValidDecimal(canonicalQty) && intentQty !== canonicalQty) {
        findings.push({
          category: ReconciliationCategory.ORDER_QUANTITY_MISMATCH,
          severity: 'HIGH',
          summary: `Quantity mismatch intent ${intentId} OMS ${intentQty} vs canonical ${canonicalQty}`,
          expected: { quantity: intentQty },
          actual: { quantity: canonicalQty },
        });
      }

      // Terminal state mismatch
      const omsTerminal = isTerminalState(currentState);
      const canonicalTerminal = ['FILLED', 'CANCELLED', 'REJECTED', 'EXPIRED', 'FAILED'].includes(canonicalOrder.status as any);
      if (omsTerminal !== canonicalTerminal) {
        findings.push({
          category: ReconciliationCategory.TERMINAL_STATE_MISMATCH,
          severity: 'MEDIUM',
          summary: `Terminal mismatch intent ${intentId} OMS terminal ${omsTerminal} state ${currentState} vs canonical terminal ${canonicalTerminal} state ${canonicalOrder.status}`,
          expected: { omsTerminal },
          actual: { canonicalTerminal, canonicalStatus: canonicalOrder.status },
        });
      }

      // Stale order detection: SUBMITTED/ACKNOWLEDGED for > 5 minutes without update
      if (['SUBMITTED', 'ACKNOWLEDGED', 'PARTIALLY_FILLED', 'CANCEL_REQUESTED'].includes(currentState)) {
        const updatedAt = intent.updatedAt ? new Date(intent.updatedAt) : new Date(intent.createdAt);
        const ageMs = Date.now() - updatedAt.getTime();
        if (ageMs > 5 * 60 * 1000) {
          findings.push({
            category: ReconciliationCategory.STALE_ORDER,
            severity: ageMs > 30 * 60 * 1000 ? 'HIGH' : 'MEDIUM',
            summary: `Stale order intent ${intentId} state ${currentState} age ${Math.floor(ageMs / 1000)}s`,
            expected: { maxAgeMs: 5 * 60 * 1000 },
            actual: { ageMs, state: currentState },
          });
        }
      }

      // Duplicate provider order: same clientOrderId appears multiple times
      const dupOrders = await this.prisma.order.findMany({ where: { tenantId, clientOrderId } });
      if (dupOrders.length > 1) {
        findings.push({
          category: ReconciliationCategory.DUPLICATE_PROVIDER_ORDER,
          severity: 'HIGH',
          summary: `Duplicate provider orders for clientOrderId ${clientOrderId} count ${dupOrders.length}`,
          expected: { count: 1 },
          actual: { count: dupOrders.length, orderIds: dupOrders.map((o) => o.id) },
        });
      }

      // Impossible lifecycle transition check via transitions
      const transitions = (intent.metadata?.transitions as any[]) ?? [];
      for (let i = 1; i < transitions.length; i++) {
        const from = transitions[i - 1].toState;
        const to = transitions[i].toState;
        // Use same VALID_TRANSITIONS check
        if (!isValidTransition(from, to)) {
          findings.push({
            category: ReconciliationCategory.IMPOSSIBLE_LIFECYCLE_TRANSITION,
            severity: 'HIGH',
            summary: `Impossible transition ${from} → ${to} in intent ${intentId} at ${transitions[i].timestamp}`,
            expected: { valid: true },
            actual: { from, to, eventId: transitions[i].eventId },
          });
        }
      }
    }

    // Persist findings. A finding that cannot be stored is never dropped silently: it stays in the
    // returned result, is counted in persistFailures and is logged at error level (error code only,
    // never row values).
    let persistedFindings = 0;
    let persistFailures = 0;
    for (const f of findings) {
      try {
        await (this.prisma as any).omsReconciliation.create({
          data: {
            tenantId,
            orderIntentId: intentId,
            internalOrderId: canonicalOrder?.id ?? null,
            providerOrderId: exchangeOrderId ?? null,
            category: f.category,
            severity: f.severity,
            expected: f.expected,
            actual: f.actual,
            summary: f.summary.slice(0, 1000),
            resolved: false,
          },
        });
        persistedFindings++;
      } catch (e) {
        persistFailures++;
        this.logger.error(
          `Order reconciliation finding NOT persisted intent ${intentId} tenant ${tenantId} category ${f.category} severity ${f.severity} error ${reconciliationErrorCode(e)}`,
        );
      }
    }

    if (persistFailures > 0) {
      this.logger.warn(`Order reconciliation intent ${intentId} tenant ${tenantId} findings ${findings.length} persisted ${persistedFindings} persistFailures ${persistFailures} source ${intentSource}`);
    } else {
      this.logger.log(`Order reconciliation intent ${intentId} tenant ${tenantId} findings ${findings.length} source ${intentSource}`);
    }
    return {
      intentId,
      intentSource,
      intentReadError,
      findings,
      totalFindings: findings.length,
      persistedFindings,
      persistFailures,
      timestamp: new Date().toISOString(),
    };
  }

  async reconcileTenant(params: { tenantId: string; accountId?: string; limit?: number }) {
    const { tenantId, accountId, limit = 20 } = params;
    let intents: any[] = [];
    let intentSource: 'OMS_INTENT' | 'CANONICAL_ORDER_FALLBACK' = 'OMS_INTENT';
    let intentReadError: string | null = null;
    try {
      intents = await (this.prisma as any).omsOrderIntent.findMany({
        where: { tenantId, ...(accountId ? { accountId } : {}), state: { in: ['SUBMITTED', 'ACKNOWLEDGED', 'PARTIALLY_FILLED', 'CANCEL_REQUESTED', 'RECONCILIATION_REQUIRED'] } },
        orderBy: { updatedAt: 'asc' },
        take: limit,
      });
    } catch (e) {
      intentSource = 'CANONICAL_ORDER_FALLBACK';
      intentReadError = reconciliationErrorCode(e);
      this.logger.warn(
        `Order reconciliation tenant ${tenantId}: OMS intent list read failed (error ${intentReadError}); selecting open canonical orders instead`,
      );
      intents = await this.prisma.order.findMany({
        where: { tenantId, ...(accountId ? { accountId } : {}), status: { in: ['SUBMITTED', 'ACKNOWLEDGED', 'PARTIALLY_FILLED'] as any } },
        orderBy: { updatedAt: 'asc' },
        take: limit,
      });
    }

    const results = [];
    for (const intent of intents) {
      const res = await this.reconcileOrder({ tenantId, intentId: intent.id });
      results.push(res);
    }
    return {
      totalChecked: intents.length,
      totalFindings: results.reduce((s, r) => s + r.totalFindings, 0),
      intentSource,
      intentReadError,
      readFallbacks: results.filter((r) => r.intentSource === 'CANONICAL_ORDER_FALLBACK').length,
      results,
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { RejectionCategory } from './oms.types';
import { randomUUID } from 'crypto';

/**
 * Order Rejection Service — normalizes provider/execution/risk/compliance rejections,
 * categorizes reasons, exposes safe operational diagnostics.
 */

@Injectable()
export class OrderRejectionService {
  private readonly logger = new Logger(OrderRejectionService.name);

  constructor(private readonly prisma: PrismaService) {}

  private categorizeRejection(params: { code?: string | null; message?: string | null; source: string }): RejectionCategory {
    const { code, message, source } = params;
    const text = `${code ?? ''} ${message ?? ''} ${source}`.toUpperCase();

    if (source === 'RISK' || text.includes('RISK') || text.includes('LIMIT') || text.includes('EXPOSURE') || text.includes('LEVERAGE') || text.includes('MARGIN_WARNING') || text.includes('DRAWDOWN') || text.includes('CONCENTRATION')) return RejectionCategory.RISK_BLOCK;
    if (source === 'COMPLIANCE' || text.includes('COMPLIANCE') || text.includes('KYC') || text.includes('AML') || text.includes('SANCTION')) return RejectionCategory.COMPLIANCE_BLOCK;
    if (source === 'SECURITY' || text.includes('SECURITY') || text.includes('THREAT') || text.includes('BLOCKED_IP')) return RejectionCategory.SECURITY_BLOCK;
    if (text.includes('SYMBOL') && (text.includes('INVALID') || text.includes('UNKNOWN') || text.includes('NOT_FOUND'))) return RejectionCategory.INVALID_SYMBOL;
    if (text.includes('PRECISION') || text.includes('LOT_SIZE') || text.includes('TICK_SIZE') || text.includes('MIN_NOTIONAL') || text.includes('STEP')) return RejectionCategory.INVALID_PRECISION;
    if (text.includes('BALANCE') || text.includes('INSUFFICIENT_FUNDS') || text.includes('FUNDS')) return RejectionCategory.INSUFFICIENT_BALANCE;
    if (text.includes('MARGIN') && text.includes('INSUFFICIENT')) return RejectionCategory.INSUFFICIENT_MARGIN;
    if (text.includes('RATE_LIMIT') || text.includes('TOO_MANY_REQUESTS') || text.includes('429')) return RejectionCategory.RATE_LIMITED;
    if (text.includes('STALE') || text.includes('MARKET_DATA')) return RejectionCategory.MARKET_DATA_STALE;
    if (text.includes('LIVE_GATE') || text.includes('LIVE_TRADING_DISABLED') || text.includes('NOT_LIVE_ENABLED')) return RejectionCategory.LIVE_GATE_BLOCK;
    if (text.includes('CREDENTIAL') || text.includes('API_KEY') || text.includes('SIGNATURE') || text.includes('AUTH')) return RejectionCategory.CREDENTIAL_FAILURE;
    if (text.includes('EXCHANGE') || text.includes('VENUE') || text.includes('BINANCE') || text.includes('BYBIT') || text.includes('REJECTED_BY_VENUE')) return RejectionCategory.EXCHANGE_REJECT;
    return RejectionCategory.UNKNOWN;
  }

  private isRetriable(category: RejectionCategory): boolean {
    return [RejectionCategory.RATE_LIMITED, RejectionCategory.MARKET_DATA_STALE, RejectionCategory.UNKNOWN].includes(category);
  }

  async recordRejection(params: {
    tenantId: string;
    orderIntentId: string;
    source: string;
    providerCode?: string | null;
    providerMessage?: string | null;
    riskRuleId?: string | null;
    complianceRuleId?: string | null;
    venue?: string | null;
    symbol?: string | null;
    accountId?: string | null;
    strategyId?: string | null;
    correlationId?: string | null;
    reason: string;
  }) {
    const { tenantId, orderIntentId, source, providerCode, providerMessage, riskRuleId, complianceRuleId, venue, symbol, accountId, strategyId, correlationId, reason } = params;

    const category = this.categorizeRejection({ code: providerCode, message: providerMessage ?? reason, source });

    // Safe reason — never expose secrets, truncate
    const safeReason = reason.slice(0, 1000);
    const safeProviderMessage = providerMessage ? providerMessage.slice(0, 500) : null;

    const record = {
      id: randomUUID(),
      tenantId,
      orderIntentId,
      category,
      reason: safeReason,
      providerCode: providerCode ? providerCode.slice(0, 100) : null,
      providerMessage: safeProviderMessage,
      riskRuleId: riskRuleId ?? null,
      complianceRuleId: complianceRuleId ?? null,
      venue: venue ?? null,
      symbol: symbol ?? null,
      accountId: accountId ?? null,
      strategyId: strategyId ?? null,
      timestamp: new Date().toISOString(),
      correlationId: correlationId ?? null,
      isRetriable: this.isRetriable(category),
      metadata: { source },
    };

    try {
      const created = await (this.prisma as any).omsRejection.create({ data: record });
      this.logger.log(`Rejection recorded intent ${orderIntentId} category ${category} reason ${safeReason} tenant ${tenantId}`);
      return created;
    } catch (e) {
      this.logger.warn(`OmsRejection model missing, logging only: ${(e as Error).message}`);
      return record;
    }
  }

  async getRejections(params: { tenantId: string; accountId?: string; symbol?: string; category?: string; from?: Date; to?: Date; page?: number; limit?: number }) {
    const { tenantId, accountId, symbol, category, from, to, page = 1, limit = 20 } = params;
    return await (this.prisma as any).omsRejection.findMany({
      where: {
        tenantId,
        ...(accountId ? { accountId } : {}),
        ...(symbol ? { symbol } : {}),
        ...(category ? { category } : {}),
        ...(from || to ? { timestamp: { gte: from?.toISOString(), lte: to?.toISOString() } as any } : {}),
      },
      orderBy: { timestamp: 'desc' },
      skip: (page - 1) * limit,
      take: limit,
    });
  }

  async getRejectionStats(tenantId: string, from?: Date, to?: Date) {
    const rejections = await this.getRejections({ tenantId, from, to, page: 1, limit: 1000 });
    const byCategory: Record<string, number> = {};
    for (const r of rejections) {
      byCategory[r.category] = (byCategory[r.category] ?? 0) + 1;
    }
    return { total: rejections.length, byCategory, retriable: rejections.filter((r: any) => r.isRetriable).length };
  }
}

import { Injectable, Logger, BadRequestException, ForbiddenException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OrderLifecycleService } from './order-lifecycle.service';
import { OrderIntentService } from './order-intent.service';
import { RiskDecisionService } from '../risk-management/risk-decision.service';
import { OrderIntentState, REPLACEABLE_STATES, isValidDecimal, parseScaled } from './oms.types';
import { ExchangeSymbolService } from '../exchanges/exchange-symbol.service';

/**
 * Order Replace/Amend Service — coordinates replace/amend requests where venue/execution engine supports them
 * without bypassing risk validation.
 * Requirements: re-run risk, re-run precision, preserve original identity/reference, preserve audit trail, never mutate filled data.
 */

@Injectable()
export class OrderReplaceService {
  private readonly logger = new Logger(OrderReplaceService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly lifecycleService: OrderLifecycleService,
    private readonly intentService: OrderIntentService,
    private readonly riskDecisionService: RiskDecisionService,
    private readonly symbolService: ExchangeSymbolService,
  ) {}

  async requestReplace(params: {
    tenantId: string;
    intentId: string;
    userId?: string | null;
    newQuantity?: string | null;
    newPrice?: string | null;
    newStopPrice?: string | null;
    reason: string;
    correlationId?: string | null;
    requestId?: string | null;
  }) {
    const { tenantId, intentId, userId, newQuantity, newPrice, newStopPrice, reason, correlationId, requestId } = params;

    let intent: any;
    try {
      intent = await (this.prisma as any).omsOrderIntent.findFirst({ where: { id: intentId, tenantId } });
    } catch {
      intent = await this.prisma.order.findFirst({ where: { id: intentId, tenantId } });
    }
    if (!intent) throw new BadRequestException(`Intent ${intentId} not found`);

    const currentState = intent.state ?? intent.status;
    if (!REPLACEABLE_STATES.has(currentState)) {
      throw new BadRequestException(`Order ${intentId} not replaceable in state ${currentState}`);
    }

    // Validate provider capability — check if venue supports amend
    const symbolRecord = await this.prisma.tradingSymbol.findFirst({
      where: { tenantId, symbol: intent.symbol, isTradeable: true },
      include: { exchange: true },
    });
    if (!symbolRecord) throw new BadRequestException(`Symbol ${intent.symbol} not found`);

    // Some venues don't support amend — we must check via symbol service or exchange metadata
    // For now, we assume cancel-replace is supported if exchange is enabled
    if (!symbolRecord.exchange.isEnabled) throw new BadRequestException(`Exchange ${symbolRecord.exchange.venue} not enabled for replace`);

    // Re-run precision validation
    if (newQuantity) {
      if (!isValidDecimal(newQuantity)) throw new BadRequestException(`Invalid newQuantity ${newQuantity}`);
      if (parseScaled(newQuantity) <= 0n) throw new BadRequestException('newQuantity must be > 0');
      // Cannot reduce below already filled quantity
      const filledQty = intent.filledQuantity?.toString() ?? '0';
      if (isValidDecimal(filledQty) && parseScaled(newQuantity) < parseScaled(filledQty)) {
        throw new BadRequestException(`newQuantity ${newQuantity} cannot be less than already filled ${filledQty}`);
      }
    }
    if (newPrice && !isValidDecimal(newPrice)) throw new BadRequestException(`Invalid newPrice ${newPrice}`);
    if (newStopPrice && !isValidDecimal(newStopPrice)) throw new BadRequestException(`Invalid newStopPrice ${newStopPrice}`);

    // Re-run risk validation with new qty/price
    const riskResult = await this.riskDecisionService.evaluateUnifiedRisk({
      tenantId,
      userId: userId ?? null,
      accountId: intent.accountId,
      symbol: intent.symbol,
      traderId: intent.traderId as any,
      followerId: intent.followerId as any,
      strategyId: intent.strategyId as any,
      orderIntent: {
        side: intent.side,
        quantity: newQuantity ?? intent.quantity?.toString() ?? intent.quantity,
        price: newPrice ?? intent.price?.toString() ?? intent.price ?? null,
        orderType: intent.orderType,
      } as any,
      environment: intent.environment ?? 'PAPER',
      requestId: requestId as any,
    } as any);

    if (riskResult.decision === 'BLOCK' || riskResult.decision === 'KILL_SWITCH_REQUIRED') {
      throw new ForbiddenException(`Risk BLOCK prevents replace for intent ${intentId}: ${riskResult.blockingReasons.join(', ')}`);
    }

    // Preserve original identity/reference — create new intent that references original
    const newIntent = await this.intentService.createIntent({
      tenantId,
      accountId: intent.accountId,
      symbol: intent.symbol,
      side: intent.side,
      orderType: intent.orderType,
      quantity: newQuantity ?? intent.quantity?.toString() ?? intent.quantity,
      price: newPrice ?? intent.price?.toString() ?? intent.price ?? null,
      stopPrice: newStopPrice ?? intent.stopPrice?.toString() ?? intent.stopPrice ?? null,
      timeInForce: intent.timeInForce ?? 'GTC',
      reduceOnly: intent.reduceOnly ?? false,
      strategyId: intent.strategyId ?? undefined,
      traderId: intent.traderId ?? undefined,
      followerId: intent.followerId ?? undefined,
      subscriptionId: intent.subscriptionId ?? undefined,
      environment: intent.environment ?? 'PAPER',
      source: intent.source ?? 'MANUAL',
      signalId: intent.signalId ?? undefined,
      correlationId: correlationId ?? intent.correlationId ?? undefined,
      requestId: requestId ?? undefined,
      userId: userId ?? undefined,
      venue: intent.venue ?? undefined,
    });

    // Mark original as REPLACED — preserve audit trail
    await this.lifecycleService.transition({
      tenantId,
      intentId,
      toState: OrderIntentState.REPLACED,
      source: 'OMS_REPLACE',
      reason: `Replaced by new intent ${newIntent.id} reason ${reason}`,
      correlationId,
      policyVersion: riskResult.policyVersion,
      actorId: userId ?? null,
      actorType: userId ? 'USER' : 'SYSTEM',
      metadata: { newIntentId: newIntent.id, newQuantity, newPrice, newStopPrice },
    });

    // Link replacement in new intent metadata
    try {
      await (this.prisma as any).omsOrderIntent.update({
        where: { id: newIntent.id },
        data: { metadata: { ...(newIntent.metadata as any), replacedFrom: intentId, replaceReason: reason } },
      });
    } catch {}

    this.logger.log(`Intent ${intentId} REPLACED by ${newIntent.id} tenant ${tenantId} qty ${newQuantity ?? 'same'} price ${newPrice ?? 'same'}`);
    return { originalIntentId: intentId, newIntentId: newIntent.id, riskDecisionId: riskResult.id };
  }
}

import { Injectable, Logger, BadRequestException, ForbiddenException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OrderIntentService } from './order-intent.service';
import { OrderLifecycleService } from './order-lifecycle.service';
import { RiskDecisionService } from '../risk-management/risk-decision.service';
import { OrderIntentState } from './oms.types';
import { ExchangeRoutingService } from '../exchanges/exchange-routing.service';
import { ExchangeAccountService } from '../exchanges/exchange-account.service';
import { ExecutionSafetyService } from '../execution/execution-safety.service';
import { QueueService } from '../queue/queue.service';
import { JOB_NAMES, QUEUE_NAMES } from '@wlct/config';
import {
  SubmitOrderRefused,
  buildSubmitOrderJob,
  buildSubmitSpecification,
  computeSubmitExposure,
  submitOrderJobId,
} from './order-submission.payload';

/**
 * Order Routing Service — coordinates approved intents with:
 * ExchangeRoutingService, ExchangeAccountService, RiskDecisionService, Compliance, Live Gate, Execution Engine
 *
 * Flow: Approved Intent → Final Risk Check → Compliance Check → Exchange Routing → Live Safety Gate → Existing Execution Engine
 * Never directly call raw exchange REST endpoint here.
 */

@Injectable()
export class OrderRoutingService {
  private readonly logger = new Logger(OrderRoutingService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly intentService: OrderIntentService,
    private readonly lifecycleService: OrderLifecycleService,
    private readonly riskDecisionService: RiskDecisionService,
    private readonly routingService: ExchangeRoutingService,
    private readonly accountService: ExchangeAccountService,
    private readonly safetyService: ExecutionSafetyService,
    private readonly queueService: QueueService,
  ) {}

  async routeIntent(params: {
    tenantId: string;
    intentId: string;
    userId?: string | null;
    correlationId?: string | null;
    requestId?: string | null;
  }) {
    const { tenantId, intentId, userId, correlationId, requestId } = params;

    let intent: any;
    try {
      intent = await (this.prisma as any).omsOrderIntent.findFirst({ where: { id: intentId, tenantId } });
    } catch {
      intent = await this.prisma.order.findFirst({ where: { id: intentId, tenantId } });
    }
    if (!intent) throw new BadRequestException(`Intent ${intentId} not found`);

    const currentState = intent.state ?? intent.status;
    if (currentState !== OrderIntentState.APPROVED && currentState !== OrderIntentState.CREATED && currentState !== OrderIntentState.VALIDATING) {
      throw new BadRequestException(`Intent ${intentId} not in routable state, current ${currentState}`);
    }

    // Step 1: VALIDATING
    if (currentState === OrderIntentState.CREATED) {
      await this.lifecycleService.transition({
        tenantId,
        intentId,
        toState: OrderIntentState.VALIDATING,
        source: 'OMS_ROUTING',
        reason: 'Starting final validation before routing',
        correlationId,
      });
    }

    // Step 2: Final Risk Check — must not trust client-supplied risk approval
    const riskResult = await this.riskDecisionService.evaluateUnifiedRisk({
      tenantId,
      userId: userId ?? null,
      accountId: intent.accountId,
      symbol: intent.symbol,
      traderId: intent.traderId as any,
      followerId: intent.followerId as any,
      strategyId: intent.strategyId as any,
      orderIntent: { side: intent.side, quantity: intent.quantity?.toString() ?? intent.quantity, price: intent.price?.toString() ?? intent.price ?? null, orderType: intent.orderType } as any,
      environment: intent.environment ?? 'PAPER',
      requestId: requestId as any,
    } as any);

    if (riskResult.decision === 'BLOCK' || riskResult.decision === 'KILL_SWITCH_REQUIRED') {
      await this.lifecycleService.transition({
        tenantId,
        intentId,
        toState: OrderIntentState.REJECTED,
        source: 'RISK',
        reason: `Risk blocked: ${riskResult.blockingReasons.join(', ')}`,
        correlationId,
        policyVersion: riskResult.policyVersion,
      });
      throw new ForbiddenException(`Risk blocked routing for intent ${intentId}: ${riskResult.blockingReasons.join(', ')}`);
    }

    // APPROVED
    await this.lifecycleService.transition({
      tenantId,
      intentId,
      toState: OrderIntentState.APPROVED,
      source: 'RISK',
      reason: `Risk approved: ${riskResult.decision} rules ${riskResult.ruleIds.join(',')}`,
      correlationId,
      policyVersion: riskResult.policyVersion,
    });

    // Step 3: Compliance Check
    const complianceBlocked = await this.prisma.complianceScreeningRequest.findFirst({
      where: { tenantId, userId: userId ?? undefined, status: { in: ['BLOCKED', 'REVIEW_REQUIRED'] as any } },
      orderBy: { createdAt: 'desc' },
    });
    if (complianceBlocked && complianceBlocked.decision === 'BLOCK') {
      await this.lifecycleService.transition({
        tenantId,
        intentId,
        toState: OrderIntentState.REJECTED,
        source: 'COMPLIANCE',
        reason: `Compliance BLOCK: ${complianceBlocked.id}`,
        correlationId,
      });
      throw new ForbiddenException(`Compliance BLOCK prevents routing for intent ${intentId}`);
    }

    // Step 4: Exchange Routing — use existing ExchangeRoutingService
    let routingResult: any;
    try {
      routingResult = await this.routingService.route({
        tenantId,
        accountId: intent.accountId,
        symbol: intent.symbol,
        side: intent.side,
        orderType: intent.orderType,
        environment: intent.environment ?? 'PAPER',
      } as any);
    } catch (e) {
      this.logger.warn(`Routing failed for intent ${intentId}: ${(e as Error).message}`);
      await this.lifecycleService.transition({
        tenantId,
        intentId,
        toState: OrderIntentState.FAILED,
        source: 'EXCHANGE_ROUTING',
        reason: `Routing failed: ${(e as Error).message}`,
        correlationId,
      });
      throw new BadRequestException(`Exchange routing failed for intent ${intentId}`);
    }

    // Step 5: Live Safety Gate — existing ExecutionSafetyService
    if (intent.environment === 'LIVE') {
      const safety = await this.safetyService.safetySummary(tenantId);
      if (!safety.wouldTransmitLiveOrder) {
        await this.lifecycleService.transition({
          tenantId,
          intentId,
          toState: OrderIntentState.REJECTED,
          source: 'LIVE_GATE',
          reason: `Live gate BLOCK: ${safety.blockingReasons.join(', ')}`,
          correlationId,
        });
        throw new ForbiddenException(`Live gate BLOCK: ${safety.blockingReasons.join(', ')}`);
      }
    }

    // Step 6: Existing Execution Engine — create canonical Order and hand to worker via queue
    // Never directly call raw exchange REST endpoint here
    await this.lifecycleService.transition({
      tenantId,
      intentId,
      toState: OrderIntentState.SUBMITTED,
      source: 'OMS_ROUTING',
      reason: `Routed to execution engine via ${routingResult?.venue ?? intent.venue ?? 'unknown'} venue`,
      correlationId,
      metadata: { routing: routingResult },
    });

    let canonicalOrderId: string | null = null;
    try {
      // Resolve the symbol WITH its trading rules: the engine validates the
      // order against exactly these before any gate runs.
      const symbolRecord = await this.prisma.tradingSymbol.findFirst({ where: { tenantId, symbol: intent.symbol } });
      if (!symbolRecord) throw new BadRequestException(`Symbol ${intent.symbol} not found for canonical order creation`);

      const intentMetadata = (intent.metadata ?? {}) as Record<string, unknown>;
      const copyExecutionId = typeof intentMetadata.copyExecutionId === 'string' ? intentMetadata.copyExecutionId : null;

      // Create canonical Order if not exists — existing execution engine remains authoritative
      let canonicalOrder = await this.prisma.order.findFirst({ where: { tenantId, clientOrderId: intent.clientOrderId } });
      if (!canonicalOrder) {
        canonicalOrder = await this.prisma.order.create({
          data: {
            tenantId,
            accountId: intent.accountId,
            strategyId: intent.strategyId ?? undefined,
            symbolId: symbolRecord.id,
            clientOrderId: intent.clientOrderId,
            venue: (routingResult?.venue ?? intent.venue ?? symbolRecord.exchangeId) as any,
            symbol: intent.symbol,
            side: intent.side as any,
            orderType: intent.orderType as any,
            timeInForce: (intent.timeInForce as any) ?? 'GTC',
            status: 'SUBMITTED' as any,
            quantity: intent.quantity as any,
            price: intent.price as any,
            stopPrice: intent.stopPrice as any,
            reduceOnly: intent.reduceOnly ?? false,
            isSimulated: intent.environment === 'PAPER',
            riskDecisionId: riskResult.id ?? undefined,
            submittedAt: new Date(),
            metadata: {
              omsIntentId: intentId,
              correlationId,
              riskDecisionId: riskResult.id,
              source: intent.source,
              ...(copyExecutionId ? { copyExecutionId } : {}),
            } as any,
          },
        });
      }
      canonicalOrderId = canonicalOrder.id;

      // Exposure from the canonical ledger; incomplete marks make the engine refuse.
      const positions = await this.prisma.position.findMany({
        where: { tenantId, accountId: intent.accountId },
        select: { symbolId: true, quantity: true, markPrice: true },
      });

      const jobData = buildSubmitOrderJob({
        tenantId,
        accountId: intent.accountId,
        orderId: canonicalOrder.id,
        clientOrderId: intent.clientOrderId,
        symbol: intent.symbol,
        side: intent.side,
        orderType: intent.orderType,
        quantity: intent.quantity,
        price: intent.price,
        timeInForce: intent.timeInForce,
        reduceOnly: intent.reduceOnly,
        strategyId: intent.strategyId,
        riskDecisionId: riskResult.id,
        environment: intent.environment ?? 'PAPER',
        specification: buildSubmitSpecification(symbolRecord as any),
        exposure: computeSubmitExposure(positions as any, symbolRecord.id),
        omsIntentId: intentId,
        metadata: {
          ...(copyExecutionId ? { copyExecutionId } : {}),
          ...(correlationId ? { correlationId: String(correlationId).slice(0, 128) } : {}),
          source: String(intent.source ?? 'OMS'),
        },
        requestedByUserId: userId ?? null,
      });

      // Enqueue to trade-execution under the job name the worker actually
      // consumes (JOB_NAMES.SUBMIT_ORDER). A failed enqueue is a FAILED
      // submission, not a silent success: nothing else would ever pick the
      // order up, so swallowing the error here would strand it in SUBMITTED.
      const deterministicJobId = submitOrderJobId(intent.clientOrderId);
      const enqueued = await this.queueService.enqueueOrThrow(
        QUEUE_NAMES.TRADE_EXECUTION,
        JOB_NAMES.SUBMIT_ORDER,
        jobData,
        { jobId: deterministicJobId, attempts: 3, backoff: { type: 'exponential', delay: 2000 } },
      );
      const jobId = enqueued || deterministicJobId;

      this.logger.log(`Intent ${intentId} submitted to execution engine job ${jobId} tenant ${tenantId} canonicalOrder ${canonicalOrder.id}`);
      return { intentId, jobId, routing: routingResult, riskDecisionId: riskResult.id, canonicalOrderId: canonicalOrder.id };
    } catch (e) {
      const refusal = e instanceof SubmitOrderRefused ? e : null;
      this.logger.warn(`Execution engine submission failed for intent ${intentId}: ${(e as Error).message}`);
      if (canonicalOrderId) {
        await this.prisma.order
          .update({
            where: { id: canonicalOrderId },
            data: {
              status: (refusal ? 'REJECTED' : 'FAILED') as any,
              rejectionCode: refusal ? refusal.code : 'SUBMISSION_ENQUEUE_FAILED',
              rejectionReason: (e as Error).message.slice(0, 500),
              terminalAt: new Date(),
            },
          })
          .catch((updateErr: Error) => this.logger.warn(`Could not mark order ${canonicalOrderId} failed: ${updateErr.message}`));
      }
      await this.lifecycleService.transition({
        tenantId,
        intentId,
        toState: refusal ? OrderIntentState.REJECTED : OrderIntentState.FAILED,
        source: 'EXECUTION_ENGINE',
        reason: `Execution submission ${refusal ? 'refused' : 'failed'}: ${(e as Error).message}`,
        correlationId,
      });
      if (refusal) throw new ForbiddenException(`${refusal.code}: ${refusal.message}`);
      throw e;
    }
  }
}

import { Injectable, Logger, OnApplicationBootstrap, OnModuleDestroy, Optional } from '@nestjs/common';
import { QueueEvents } from 'bullmq';
import { JOB_NAMES, QUEUE_NAMES } from '@wlct/config';

import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AppConfigService } from '../../config/app-config.service';
import { QueueService } from '../queue/queue.service';
import { ExecutionAckService } from './execution-ack.service';
import { OrderLifecycleService } from './order-lifecycle.service';
import { OrderIntentState } from './oms.types';
import { clientOrderIdFromJobId } from './order-submission.payload';

/**
 * Phase 3 — records what the execution engine decided about a SUBMIT_ORDER
 * job back onto the platform's own records.
 *
 * The worker holds no database (worker.module.ts), so the verdict travels as
 * the job's return value: the engine's SubmitOrderResponse plus the platform
 * ids the worker echoes (platformOrderId, omsIntentId, tenantId). This
 * service reads it from BullMQ's own event stream - the truth BullMQ reports,
 * not a guess - and applies it to three records:
 *
 *   1. the canonical `order` row (status, fills summary, rejection);
 *   2. the OMS intent, via ExecutionAckService (ACK/REJECT) and the lifecycle
 *      service (FILLED / PARTIALLY_FILLED);
 *   3. the copy execution the order was created for, when there is one.
 *
 * Every write is idempotent: a replayed event (two API replicas, a restart
 * sweep) re-applies the same terminal facts. Events missed while the API was
 * down are recovered by {@link sweepPending}, which asks BullMQ for the job by
 * its deterministic id.
 */

export type SubmissionVerdict =
  | { kind: 'accepted'; orderStatus: 'ACKNOWLEDGED' | 'PARTIALLY_FILLED' | 'FILLED' }
  | { kind: 'rejected'; code: string; reason: string }
  | { kind: 'unknown'; reason: string };

export interface SubmissionResultView {
  tenantId: string;
  platformOrderId: string;
  omsIntentId: string | null;
  clientOrderId: string;
  outcome: string;
  engineOrderId: string | null;
  exchangeOrderId: string | null;
  orderStatus: string;
  filledQuantity: string;
  averageFillPrice: string | null;
  cumulativeFee: string;
  feeCurrency: string | null;
  errorCode: string | null;
  message: string | null;
  latencyMicros: number | null;
  isSimulated: boolean;
}

const DECIMAL = /^-?\d+(\.\d+)?$/;

function str(value: unknown): string | null {
  return typeof value === 'string' && value.length > 0 ? value : null;
}

function decimalOr(value: unknown, fallback: string): string {
  return typeof value === 'string' && DECIMAL.test(value) ? value : fallback;
}

/** Parse a SUBMIT_ORDER job's return value. Returns null for anything that is
 * not one (another command's receipt, a truncated value) so the caller
 * ignores it instead of writing guesses. */
export function parseSubmissionResult(raw: unknown): SubmissionResultView | null {
  let value: unknown = raw;
  if (typeof value === 'string') {
    try {
      value = JSON.parse(value);
    } catch {
      return null;
    }
  }
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return null;
  const record = value as Record<string, unknown>;
  const tenantId = str(record.tenantId);
  const platformOrderId = str(record.platformOrderId);
  const clientOrderId = str(record.clientOrderId);
  const outcome = str(record.outcome);
  if (!tenantId || !platformOrderId || !clientOrderId || !outcome) return null;
  return {
    tenantId,
    platformOrderId,
    omsIntentId: str(record.omsIntentId),
    clientOrderId,
    outcome,
    engineOrderId: str(record.engineOrderId),
    exchangeOrderId: str(record.exchangeOrderId),
    orderStatus: str(record.orderStatus) ?? 'UNKNOWN',
    filledQuantity: decimalOr(record.filledQuantity, '0'),
    averageFillPrice: typeof record.averageFillPrice === 'string' && DECIMAL.test(record.averageFillPrice) ? record.averageFillPrice : null,
    cumulativeFee: decimalOr(record.cumulativeFee, '0'),
    feeCurrency: str(record.feeCurrency),
    errorCode: str(record.errorCode),
    message: typeof record.message === 'string' ? record.message : null,
    latencyMicros: typeof record.latencyMicros === 'number' && Number.isFinite(record.latencyMicros) ? record.latencyMicros : null,
    isSimulated: record.isSimulated === true,
  };
}

/** The engine's outcome vocabulary mapped onto the platform's order states.
 * UNKNOWN (an ambiguous venue answer) is deliberately NOT mapped to a
 * rejection: the order may exist, so it stays SUBMITTED and is flagged for
 * reconciliation. */
export function interpretSubmission(result: SubmissionResultView): SubmissionVerdict {
  switch (result.outcome) {
    case 'ACCEPTED':
    case 'DUPLICATE': {
      if (result.orderStatus === 'FILLED') return { kind: 'accepted', orderStatus: 'FILLED' };
      if (result.orderStatus === 'PARTIALLY_FILLED') return { kind: 'accepted', orderStatus: 'PARTIALLY_FILLED' };
      if (result.orderStatus === 'REJECTED') {
        return { kind: 'rejected', code: result.errorCode ?? 'REJECTED', reason: result.message ?? 'Rejected' };
      }
      if (result.outcome === 'DUPLICATE' && result.orderStatus === 'UNKNOWN') {
        return { kind: 'unknown', reason: 'Duplicate submission; original order state not visible to the engine' };
      }
      return { kind: 'accepted', orderStatus: 'ACKNOWLEDGED' };
    }
    case 'REJECTED_LOCALLY':
    case 'REJECTED_BY_EXCHANGE':
      return { kind: 'rejected', code: result.errorCode ?? result.outcome, reason: result.message ?? result.outcome };
    case 'DRY_RUN':
      return { kind: 'rejected', code: 'DRY_RUN', reason: 'Engine is in dry-run mode; the order was not transmitted' };
    default:
      return { kind: 'unknown', reason: result.message ?? `Engine outcome ${result.outcome}` };
  }
}

@Injectable()
export class OrderSubmissionResultService implements OnApplicationBootstrap, OnModuleDestroy {
  private readonly logger = new Logger(OrderSubmissionResultService.name);
  private events: QueueEvents | null = null;
  private sweepTimer: NodeJS.Timeout | null = null;

  constructor(
    private readonly prisma: PrismaService,
    private readonly ackService: ExecutionAckService,
    private readonly lifecycleService: OrderLifecycleService,
    private readonly queueService: QueueService,
    @Optional() private readonly config?: AppConfigService,
  ) {}

  async onApplicationBootstrap(): Promise<void> {
    // Test harnesses and queue-less tools construct the module without Redis
    // settings; the recorder is then inert and says so once.
    const connection = (this.config as any)?.queueRedisOptions;
    if (!connection || process.env.NODE_ENV === 'test') {
      this.logger.log('Submission result listener not started (no queue connection or test environment)');
      return;
    }
    try {
      this.events = new QueueEvents(QUEUE_NAMES.TRADE_EXECUTION, { connection });
      this.events.on('completed', ({ jobId, returnvalue }) => {
        void this.onCompleted(jobId, returnvalue).catch((error: Error) =>
          this.logger.warn(`Recording submission result for job ${jobId} failed: ${error.message}`),
        );
      });
      this.events.on('failed', ({ jobId, failedReason }) => {
        void this.onFailed(jobId, failedReason).catch((error: Error) =>
          this.logger.warn(`Recording submission failure for job ${jobId} failed: ${error.message}`),
        );
      });
      this.sweepTimer = setInterval(() => {
        void this.sweepPending().catch((error: Error) => this.logger.warn(`Submission sweep failed: ${error.message}`));
      }, 60_000);
      this.sweepTimer.unref?.();
      void this.sweepPending().catch((error: Error) => this.logger.warn(`Initial submission sweep failed: ${error.message}`));
    } catch (error) {
      this.logger.warn(`Submission result listener could not start: ${(error as Error).message}`);
    }
  }

  async onModuleDestroy(): Promise<void> {
    if (this.sweepTimer) clearInterval(this.sweepTimer);
    this.sweepTimer = null;
    if (this.events) await this.events.close().catch(() => undefined);
    this.events = null;
  }

  private async onCompleted(jobId: string, returnvalue: unknown): Promise<void> {
    if (!clientOrderIdFromJobId(jobId)) return; // not a submission job
    const result = parseSubmissionResult(returnvalue);
    if (!result) {
      this.logger.warn(`Submission job ${jobId} completed without a parseable result; leaving order for reconciliation`);
      return;
    }
    await this.recordResult(result);
  }

  private async onFailed(jobId: string, failedReason: string): Promise<void> {
    const clientOrderId = clientOrderIdFromJobId(jobId);
    if (!clientOrderId) return;
    // A 'failed' event fires for every failed attempt; only the final one is
    // terminal. Ask BullMQ whether retries remain before recording anything.
    const job = await this.queueService.getQueue(QUEUE_NAMES.TRADE_EXECUTION).getJob(jobId).catch(() => null);
    if (job) {
      const attempts = typeof job.opts?.attempts === 'number' ? job.opts.attempts : 1;
      const unrecoverable = /Unrecoverable|payload rejected|ENGINE_|HTTP_4/.test(failedReason ?? '');
      if (job.attemptsMade < attempts && !unrecoverable) return;
      const data = (job.data ?? {}) as Record<string, unknown>;
      await this.recordFailure({
        tenantId: typeof data.tenantId === 'string' ? data.tenantId : null,
        clientOrderId,
        reason: failedReason ?? 'Submission job failed',
      });
      return;
    }
    await this.recordFailure({ tenantId: null, clientOrderId, reason: failedReason ?? 'Submission job failed' });
  }

  /** Re-read every order still SUBMITTED by the OMS and apply the job's
   * outcome if BullMQ has one. Covers events missed while the API was down. */
  async sweepPending(limit = 200): Promise<number> {
    const pending = await this.prisma.order.findMany({
      where: { status: 'SUBMITTED' as any, exchangeOrderId: null },
      orderBy: { createdAt: 'asc' },
      take: limit,
      select: { id: true, tenantId: true, clientOrderId: true, metadata: true },
    });
    let applied = 0;
    const queue = this.queueService.getQueue(QUEUE_NAMES.TRADE_EXECUTION);
    for (const order of pending) {
      const metadata = (order.metadata ?? {}) as Record<string, unknown>;
      if (typeof metadata.omsIntentId !== 'string') continue;
      const job = await queue.getJob(`oms-submit-${order.clientOrderId}`).catch(() => null);
      if (!job || job.name !== JOB_NAMES.SUBMIT_ORDER) continue;
      if (job.finishedOn && job.returnvalue) {
        const result = parseSubmissionResult(job.returnvalue);
        if (result) {
          await this.recordResult(result);
          applied += 1;
        }
      } else if (job.finishedOn && job.failedReason) {
        await this.recordFailure({ tenantId: order.tenantId, clientOrderId: order.clientOrderId, reason: job.failedReason });
        applied += 1;
      }
    }
    return applied;
  }

  async recordResult(result: SubmissionResultView): Promise<SubmissionVerdict> {
    const verdict = interpretSubmission(result);
    const order = await this.prisma.order.findFirst({ where: { id: result.platformOrderId, tenantId: result.tenantId } });
    if (!order) {
      this.logger.warn(`Submission result for unknown order ${result.platformOrderId} tenant ${result.tenantId}; ignoring`);
      return verdict;
    }
    const existingMetadata = (order.metadata ?? {}) as Record<string, unknown>;
    const engineMetadata = {
      engineOutcome: result.outcome,
      engineOrderId: result.engineOrderId,
      engineOrderStatus: result.orderStatus,
      engineErrorCode: result.errorCode,
      engineRecordedAt: new Date().toISOString(),
    };
    const now = new Date();

    if (verdict.kind === 'accepted') {
      await this.prisma.order.update({
        where: { id: order.id },
        data: {
          status: verdict.orderStatus as any,
          exchangeOrderId: result.exchangeOrderId ? result.exchangeOrderId.slice(0, 64) : undefined,
          filledQuantity: result.filledQuantity as any,
          averageFillPrice: (result.averageFillPrice ?? undefined) as any,
          cumulativeFee: result.cumulativeFee as any,
          feeCurrency: result.feeCurrency ?? undefined,
          submitLatencyMicros: result.latencyMicros ?? undefined,
          terminalAt: verdict.orderStatus === 'FILLED' ? now : undefined,
          metadata: { ...existingMetadata, ...engineMetadata } as any,
        },
      });
    } else if (verdict.kind === 'rejected') {
      await this.prisma.order.update({
        where: { id: order.id },
        data: {
          status: 'REJECTED' as any,
          rejectionCode: verdict.code.slice(0, 64),
          rejectionReason: verdict.reason.slice(0, 500),
          wasDryRun: verdict.code === 'DRY_RUN' ? true : undefined,
          terminalAt: now,
          metadata: { ...existingMetadata, ...engineMetadata } as any,
        },
      });
    } else {
      await this.prisma.order.update({
        where: { id: order.id },
        data: {
          reconciliationState: 'UNKNOWN' as any,
          reconciliationDetail: verdict.reason.slice(0, 500),
          metadata: { ...existingMetadata, ...engineMetadata } as any,
        },
      });
    }

    await this.applyToIntent(result, verdict, order.venue as unknown as string);
    await this.applyToCopyExecution(result, verdict, existingMetadata);
    return verdict;
  }

  async recordFailure(input: { tenantId: string | null; clientOrderId: string; reason: string }): Promise<void> {
    const order = await this.prisma.order.findFirst({
      where: { clientOrderId: input.clientOrderId, ...(input.tenantId ? { tenantId: input.tenantId } : {}) },
    });
    if (!order) return;
    if (!['SUBMITTED', 'PENDING'].includes(order.status as unknown as string)) return; // already resolved
    const metadata = (order.metadata ?? {}) as Record<string, unknown>;
    await this.prisma.order.update({
      where: { id: order.id },
      data: {
        status: 'FAILED' as any,
        rejectionCode: 'SUBMISSION_JOB_FAILED',
        rejectionReason: input.reason.slice(0, 500),
        terminalAt: new Date(),
      },
    });
    const omsIntentId = typeof metadata.omsIntentId === 'string' ? metadata.omsIntentId : null;
    if (omsIntentId) {
      await this.lifecycleService
        .transition({
          tenantId: order.tenantId,
          intentId: omsIntentId,
          toState: OrderIntentState.FAILED,
          source: 'EXECUTION_ENGINE',
          reason: `Submission job failed: ${input.reason}`.slice(0, 500),
        })
        .catch((error: Error) => this.logger.warn(`Intent ${omsIntentId} failure transition skipped: ${error.message}`));
    }
    const copyExecutionId = typeof metadata.copyExecutionId === 'string' ? metadata.copyExecutionId : null;
    if (copyExecutionId) {
      await this.updateCopyExecution(order.tenantId, copyExecutionId, 'FAILED', {
        followerOrderId: order.id,
        failureReason: `Submission failed: ${input.reason}`.slice(0, 500),
      });
    }
  }

  private async applyToIntent(result: SubmissionResultView, verdict: SubmissionVerdict, venue: string): Promise<void> {
    if (verdict.kind === 'unknown') return;
    await this.ackService.processAckFromExecutionEvent({
      tenantId: result.tenantId,
      orderId: result.platformOrderId,
      clientOrderId: result.clientOrderId,
      exchangeOrderId: result.exchangeOrderId,
      providerOrderId: result.engineOrderId,
      venue,
      status: verdict.kind === 'accepted' ? 'ACKNOWLEDGED' : 'REJECTED',
      occurredAtMicros: (BigInt(Date.now()) * 1000n).toString(),
      reason: verdict.kind === 'rejected' ? `${verdict.code}: ${verdict.reason}` : null,
      source: result.isSimulated ? 'EXECUTION_ENGINE_SIMULATED' : 'EXECUTION_ENGINE',
      providerErrorCode: verdict.kind === 'rejected' ? verdict.code : null,
      providerErrorMessage: verdict.kind === 'rejected' ? verdict.reason : null,
      latencyMicros: result.latencyMicros !== null ? String(result.latencyMicros) : null,
    });
    if (verdict.kind === 'accepted' && verdict.orderStatus !== 'ACKNOWLEDGED' && result.omsIntentId) {
      const toState = verdict.orderStatus === 'FILLED' ? OrderIntentState.FILLED : OrderIntentState.PARTIALLY_FILLED;
      await this.lifecycleService
        .transition({
          tenantId: result.tenantId,
          intentId: result.omsIntentId,
          toState,
          source: 'EXECUTION_ENGINE',
          reason: `Engine reported ${verdict.orderStatus} filled ${result.filledQuantity}${result.isSimulated ? ' (simulated)' : ''}`,
          metadata: { filledQuantity: result.filledQuantity, averageFillPrice: result.averageFillPrice, isSimulated: result.isSimulated },
        })
        .catch((error: Error) => this.logger.warn(`Intent ${result.omsIntentId} fill transition skipped: ${error.message}`));
    }
  }

  private async applyToCopyExecution(
    result: SubmissionResultView,
    verdict: SubmissionVerdict,
    metadata: Record<string, unknown>,
  ): Promise<void> {
    const copyExecutionId = typeof metadata.copyExecutionId === 'string' ? metadata.copyExecutionId : null;
    if (!copyExecutionId) return;
    if (verdict.kind === 'accepted') {
      await this.updateCopyExecution(result.tenantId, copyExecutionId, verdict.orderStatus === 'FILLED' ? 'FILLED' : 'SUBMITTED', {
        followerOrderId: result.platformOrderId,
        providerOrderId: result.exchangeOrderId ?? result.engineOrderId ?? undefined,
        followerPrice: result.averageFillPrice ?? undefined,
      });
    } else if (verdict.kind === 'rejected') {
      await this.updateCopyExecution(result.tenantId, copyExecutionId, 'REJECTED', {
        followerOrderId: result.platformOrderId,
        failureReason: `${verdict.code}: ${verdict.reason}`.slice(0, 500),
      });
    }
  }

  private async updateCopyExecution(
    tenantId: string,
    copyExecutionId: string,
    status: 'SUBMITTED' | 'FILLED' | 'FAILED' | 'REJECTED',
    extra: { followerOrderId?: string; providerOrderId?: string; followerPrice?: string; failureReason?: string },
  ): Promise<void> {
    try {
      await (this.prisma as any).copyExecution.updateMany({
        // FILLED is terminal for a copy execution: a late or replayed event
        // must never move it backwards (same law as CopyExecutionRepository).
        where: { id: copyExecutionId, tenantId, ...(status === 'FILLED' ? {} : { NOT: { status: 'FILLED' } }) },
        data: {
          status,
          ...(extra.followerOrderId ? { followerOrderId: extra.followerOrderId } : {}),
          ...(extra.providerOrderId ? { providerOrderId: extra.providerOrderId } : {}),
          ...(extra.followerPrice ? { followerPrice: extra.followerPrice } : {}),
          ...(extra.failureReason ? { failureReason: extra.failureReason } : {}),
          updatedAt: new Date(),
        },
      });
    } catch (error) {
      this.logger.warn(`Copy execution ${copyExecutionId} status update failed: ${(error as Error).message}`);
    }
  }
}

// # Verifies partial fill progression, remaining quantity calculation, and terminal state transitions
/**
 * Phase 3: the OMS producer half of SUBMIT_ORDER, and the result recorder.
 *
 * Pinned here:
 *  - the job id is deterministic and legal for BullMQ (no single ':');
 *  - exposure is computed from the canonical ledger and is INCOMPLETE when a
 *    non-flat position has no mark;
 *  - LIVE / stop orders are refused with a typed reason, never enqueued;
 *  - the engine's outcome vocabulary maps onto platform order states, with
 *    UNKNOWN left for reconciliation rather than guessed;
 *  - the recorder writes the order, the intent and the copy execution, and a
 *    FILLED copy execution is never moved backwards.
 */

import { Prisma } from '@prisma/client';

import {
  SubmitOrderRefused,
  buildSubmitOrderJob,
  buildSubmitSpecification,
  clientOrderIdFromJobId,
  computeSubmitExposure,
  submitOrderJobId,
  type SubmitOrderJobInput,
} from './order-submission.payload';
import {
  OrderSubmissionResultService,
  interpretSubmission,
  parseSubmissionResult,
  type SubmissionResultView,
} from './order-submission-result.service';
import { OrderIntentState } from './oms.types';
import { FillManagementService } from './fill-management.service';
import { OrderLifecycleService } from './order-lifecycle.service';

const SPEC = buildSubmitSpecification({
  baseAsset: 'BTC',
  quoteAsset: 'USDT',
  marketType: 'SPOT',
  priceTick: new Prisma.Decimal('0.010000000000'),
  quantityStep: new Prisma.Decimal('0.000010000000'),
  minQuantity: new Prisma.Decimal('0.00001'),
  maxQuantity: null,
  minNotional: new Prisma.Decimal('10.000000'),
  isTradeable: true,
  pricePrecision: 2,
  quantityPrecision: 5,
});

function jobInput(overrides: Partial<SubmitOrderJobInput> = {}): SubmitOrderJobInput {
  return {
    tenantId: 't-1',
    accountId: 'a-1',
    orderId: 'o-1',
    clientOrderId: 'oms0123456789abcdef0123456789abcdef',
    symbol: 'BTC-USDT',
    side: 'BUY',
    orderType: 'LIMIT',
    quantity: new Prisma.Decimal('0.010000000000'),
    price: new Prisma.Decimal('50000.000000000000'),
    timeInForce: 'GTC',
    reduceOnly: false,
    strategyId: null,
    riskDecisionId: 'r-1',
    environment: 'PAPER',
    specification: SPEC,
    exposure: { positionQuantity: '0', symbolExposureNotional: '0', accountExposureNotional: '0', complete: true },
    omsIntentId: 'i-1',
    metadata: { copyExecutionId: 'c-1', 'bad.key': 'x' },
    ...overrides,
  };
}

describe('SUBMIT_ORDER producer helpers', () => {
  it('job ids are deterministic, reversible and contain no colon', () => {
    const id = submitOrderJobId('oms0123');
    expect(id).toBe('oms-submit-oms0123');
    expect(id.includes(':')).toBe(false);
    expect(clientOrderIdFromJobId(id)).toBe('oms0123');
    expect(clientOrderIdFromJobId('other-job')).toBeNull();
    expect(clientOrderIdFromJobId(undefined)).toBeNull();
  });

  it('specification decimals are plain strings (no exponent, no float)', () => {
    expect(SPEC).toMatchObject({ priceTick: '0.01', quantityStep: '0.00001', minQuantity: '0.00001', minNotional: '10', maxQuantity: null });
    expect(() => buildSubmitSpecification({ ...(SPEC as any), marketType: 'OPTIONS' })).toThrow(/Unsupported market type/);
  });

  it('exposure sums marked positions and flags an unmarked one as incomplete', () => {
    const exposure = computeSubmitExposure(
      [
        { symbolId: 's-btc', quantity: '0.5', markPrice: '50000' },
        { symbolId: 's-btc', quantity: '-0.2', markPrice: '50000' },
        { symbolId: 's-eth', quantity: '-2', markPrice: '3000' },
        { symbolId: 's-sol', quantity: '0', markPrice: null },
      ],
      's-btc',
    );
    expect(exposure).toEqual({
      positionQuantity: '0.3',
      symbolExposureNotional: '35000',
      accountExposureNotional: '41000',
      complete: true,
    });
    const incomplete = computeSubmitExposure([{ symbolId: 's-eth', quantity: '1', markPrice: null }], 's-btc');
    expect(incomplete.complete).toBe(false);
  });

  it('builds a PAPER job with plain decimals and filtered metadata', () => {
    const job = buildSubmitOrderJob(jobInput());
    expect(job).toMatchObject({
      quantity: '0.01',
      price: '50000',
      environment: 'PAPER',
      riskDecisionId: 'r-1',
      omsIntentId: 'i-1',
      metadata: { copyExecutionId: 'c-1' },
    });
    expect((job.metadata as Record<string, string>)['bad.key']).toBeUndefined();
  });

  it.each([
    [{ environment: 'LIVE' }, 'LIVE_SUBMISSION_NOT_WIRED'],
    [{ orderType: 'STOP' }, 'ORDER_TYPE_NOT_SUPPORTED'],
    [{ side: 'HOLD' }, 'SIDE_INVALID'],
    [{ timeInForce: 'DAY' }, 'TIME_IN_FORCE_NOT_SUPPORTED'],
    [{ price: null }, 'PRICE_REQUIRED'],
  ] as Array<[Partial<SubmitOrderJobInput>, string]>)('refuses %j with %s', (patch, code) => {
    try {
      buildSubmitOrderJob(jobInput(patch));
      throw new Error('expected refusal');
    } catch (error) {
      expect(error).toBeInstanceOf(SubmitOrderRefused);
      expect((error as SubmitOrderRefused).code).toBe(code);
    }
  });
});

function result(overrides: Partial<SubmissionResultView> = {}): SubmissionResultView {
  return {
    tenantId: 't-1',
    platformOrderId: 'o-1',
    omsIntentId: 'i-1',
    clientOrderId: 'oms0123456789abcdef0123456789abcdef',
    outcome: 'ACCEPTED',
    engineOrderId: 'eng-1',
    exchangeOrderId: 'paper-1',
    orderStatus: 'FILLED',
    filledQuantity: '0.01',
    averageFillPrice: '50000',
    cumulativeFee: '0.5',
    feeCurrency: 'USDT',
    errorCode: null,
    message: null,
    latencyMicros: 42,
    isSimulated: true,
    ...overrides,
  };
}

describe('submission result interpretation', () => {
  it('parses a worker receipt (object or JSON string) and ignores anything else', () => {
    const raw = { ...result(), platformOrderId: 'o-1', tenantId: 't-1' };
    expect(parseSubmissionResult(raw)?.platformOrderId).toBe('o-1');
    expect(parseSubmissionResult(JSON.stringify(raw))?.outcome).toBe('ACCEPTED');
    expect(parseSubmissionResult({ verified: true })).toBeNull();
    expect(parseSubmissionResult('not json')).toBeNull();
    expect(parseSubmissionResult({ ...raw, filledQuantity: '1e3' })?.filledQuantity).toBe('0');
  });

  it.each([
    [{ outcome: 'ACCEPTED', orderStatus: 'FILLED' }, { kind: 'accepted', orderStatus: 'FILLED' }],
    [{ outcome: 'ACCEPTED', orderStatus: 'PARTIALLY_FILLED' }, { kind: 'accepted', orderStatus: 'PARTIALLY_FILLED' }],
    [{ outcome: 'ACCEPTED', orderStatus: 'ACKNOWLEDGED' }, { kind: 'accepted', orderStatus: 'ACKNOWLEDGED' }],
    [{ outcome: 'DUPLICATE', orderStatus: 'FILLED' }, { kind: 'accepted', orderStatus: 'FILLED' }],
    [{ outcome: 'DUPLICATE', orderStatus: 'UNKNOWN' }, { kind: 'unknown' }],
    [{ outcome: 'REJECTED_LOCALLY', errorCode: 'VALIDATION_FAILED', message: 'bad tick' }, { kind: 'rejected', code: 'VALIDATION_FAILED', reason: 'bad tick' }],
    [{ outcome: 'REJECTED_BY_EXCHANGE' }, { kind: 'rejected', code: 'REJECTED_BY_EXCHANGE' }],
    [{ outcome: 'DRY_RUN' }, { kind: 'rejected', code: 'DRY_RUN' }],
    [{ outcome: 'UNKNOWN' }, { kind: 'unknown' }],
  ] as Array<[Partial<SubmissionResultView>, Record<string, unknown>]>)('%j -> %j', (patch, expected) => {
    expect(interpretSubmission(result(patch))).toMatchObject(expected);
  });
});

function fakeRecorder(order: Record<string, unknown> | null) {
  const orderUpdates: any[] = [];
  const copyUpdates: any[] = [];
  const transitions: any[] = [];
  const acks: any[] = [];
  const prisma = {
    order: {
      findFirst: jest.fn(async () => order),
      update: jest.fn(async (args: any) => {
        orderUpdates.push(args);
        return { ...order, ...args.data };
      }),
      findMany: jest.fn(async () => []),
    },
    copyExecution: {
      updateMany: jest.fn(async (args: any) => {
        copyUpdates.push(args);
        return { count: 1 };
      }),
    },
  };
  const ackService = { processAckFromExecutionEvent: jest.fn(async (args: any) => acks.push(args)) };
  const lifecycle = { transition: jest.fn(async (args: any) => transitions.push(args)) };
  const queue = { getQueue: jest.fn(() => ({ getJob: jest.fn(async () => null) })) };
  const service = new OrderSubmissionResultService(prisma as any, ackService as any, lifecycle as any, queue as any);
  return { service, prisma, orderUpdates, copyUpdates, transitions, acks };
}

const ORDER = {
  id: 'o-1',
  tenantId: 't-1',
  clientOrderId: 'oms0123456789abcdef0123456789abcdef',
  status: 'SUBMITTED',
  venue: 'PAPER',
  metadata: { omsIntentId: 'i-1', copyExecutionId: 'c-1' },
};

describe('OrderSubmissionResultService', () => {
  it('a filled result updates the order, acks and fills the intent, and fills the copy execution', async () => {
    const { service, orderUpdates, copyUpdates, transitions, acks } = fakeRecorder(ORDER);
    const verdict = await service.recordResult(result());
    expect(verdict).toEqual({ kind: 'accepted', orderStatus: 'FILLED' });
    expect(orderUpdates[0].data).toMatchObject({ status: 'FILLED', exchangeOrderId: 'paper-1', filledQuantity: '0.01', averageFillPrice: '50000' });
    expect(orderUpdates[0].data.metadata).toMatchObject({ omsIntentId: 'i-1', engineOutcome: 'ACCEPTED', engineOrderId: 'eng-1' });
    expect(acks[0]).toMatchObject({ status: 'ACKNOWLEDGED', clientOrderId: ORDER.clientOrderId, source: 'EXECUTION_ENGINE_SIMULATED' });
    expect(transitions[0]).toMatchObject({ intentId: 'i-1', toState: OrderIntentState.FILLED });
    expect(copyUpdates[0]).toMatchObject({ where: { id: 'c-1', tenantId: 't-1' }, data: { status: 'FILLED', followerOrderId: 'o-1' } });
  });

  it('a rejection marks the order REJECTED, rejects the intent via ack, and the copy execution never regresses from FILLED', async () => {
    const { service, orderUpdates, copyUpdates, acks, transitions } = fakeRecorder(ORDER);
    await service.recordResult(result({ outcome: 'REJECTED_LOCALLY', orderStatus: 'UNKNOWN', errorCode: 'VALIDATION_FAILED', message: 'tick' }));
    expect(orderUpdates[0].data).toMatchObject({ status: 'REJECTED', rejectionCode: 'VALIDATION_FAILED', rejectionReason: 'tick' });
    expect(acks[0]).toMatchObject({ status: 'REJECTED', providerErrorCode: 'VALIDATION_FAILED' });
    expect(transitions).toHaveLength(0);
    expect(copyUpdates[0].where).toMatchObject({ id: 'c-1', NOT: { status: 'FILLED' } });
    expect(copyUpdates[0].data.status).toBe('REJECTED');
  });

  it('an UNKNOWN outcome leaves the order SUBMITTED and flags reconciliation - nothing is guessed', async () => {
    const { service, orderUpdates, acks, copyUpdates } = fakeRecorder(ORDER);
    await service.recordResult(result({ outcome: 'UNKNOWN', orderStatus: 'UNKNOWN' }));
    expect(orderUpdates[0].data.status).toBeUndefined();
    expect(orderUpdates[0].data).toMatchObject({ reconciliationState: 'UNKNOWN' });
    expect(acks).toHaveLength(0);
    expect(copyUpdates).toHaveLength(0);
  });

  it('a result for an order this tenant does not have is ignored', async () => {
    const { service, orderUpdates } = fakeRecorder(null);
    await service.recordResult(result());
    expect(orderUpdates).toHaveLength(0);
  });

  it('a terminal job failure marks order FAILED, intent FAILED and copy execution FAILED', async () => {
    const { service, orderUpdates, transitions, copyUpdates } = fakeRecorder(ORDER);
    await service.recordFailure({ tenantId: 't-1', clientOrderId: ORDER.clientOrderId, reason: 'ENGINE_UNREACHABLE' });
    expect(orderUpdates[0].data).toMatchObject({ status: 'FAILED', rejectionCode: 'SUBMISSION_JOB_FAILED' });
    expect(transitions[0]).toMatchObject({ intentId: 'i-1', toState: OrderIntentState.FAILED });
    expect(copyUpdates[0].data).toMatchObject({ status: 'FAILED' });
  });

  it('a failure for an already-resolved order changes nothing', async () => {
    const { service, orderUpdates } = fakeRecorder({ ...ORDER, status: 'FILLED' });
    await service.recordFailure({ tenantId: 't-1', clientOrderId: ORDER.clientOrderId, reason: 'late' });
    expect(orderUpdates).toHaveLength(0);
  });
});

