// # Proves the order path enforces the user's position and open-order ceilings
//
// The ceiling service was complete, tested and correct, and it was in no module's `providers`;
// `UserPositionLimitController` was in no module's `controllers`; and nothing on the order path
// called `persistOrderIntentWithLimits`. A customer could set a limit, read it back from the API,
// and have it never consulted when an order was placed.
//
// This file is the evidence that the wiring exists, and it is written so that removing the wiring
// fails it. Two independent angles:
//
// 1. Behaviour - `createIntent` is driven with a limiter whose reservation refuses, and with a
//    limiter that hands back a transaction client. If `createIntent` stops routing through the
//    limiter, the refusal is never seen and the intent is written on the plain client: both halves
//    of that are asserted, so either change fails here.
// 2. Structure - the module metadata is read directly, so deleting `PositionLimitService` from
//    `RiskManagementModule` or the controller from `controllers` fails a test even if some other
//    path kept the behaviour alive.
import 'reflect-metadata';
import { MODULE_METADATA } from '@nestjs/common/constants';
import { RiskManagementModule } from '../risk-management/risk-management.module';
import { UserPositionLimitController } from '../risk-management/user-position-limit.controller';
import { PositionLimitService } from '../risk/position-limit.service';
import { OrderIntentService } from './order-intent.service';
import { OrderIntentState } from './oms.types';

const TENANT_ID = 'tenant-1';
const ACCOUNT_ID = 'account-1';
const SYMBOL = 'BTC-USDT';

/**
 * A limiter that records every reservation it is asked to make and answers with the given verdict.
 * `verified` is what an intent must reach when the reservation is allowed, so a test can tell a
 * written intent from a refused one.
 */
function limiterThat(verdict: 'ALLOW' | 'REFUSE') {
  const reservations: { tenantId: string; accountId: string; symbol: string }[] = [];
  const tx = {
    // Tagged-template call, matching how the service issues its savepoint statements.
    $executeRaw: jest.fn(async (_strings: TemplateStringsArray) => 1),
    omsOrderIntent: {
      create: jest.fn(async ({ data }: { data: Record<string, unknown> }) => ({
        id: 'intent-1',
        ...data,
        state: OrderIntentState.CREATED,
      })),
    },
    order: { create: jest.fn() },
  };
  const service = {
    persistOrderIntentWithLimits: jest.fn(
      async (params: {
        tenantId: string;
        accountId: string;
        symbol: string;
        persist: (client: unknown) => Promise<unknown>;
      }) => {
        reservations.push({ tenantId: params.tenantId, accountId: params.accountId, symbol: params.symbol });
        if (verdict === 'REFUSE') {
          const refusal = new Error('USER_CONCURRENT_POSITION_LIMIT_EXCEEDED');
          (refusal as Error & { code?: string }).code = 'USER_CONCURRENT_POSITION_LIMIT_EXCEEDED';
          throw refusal;
        }
        return params.persist(tx);
      },
    ),
  };
  return { service, reservations, tx };
}

function buildService(limiter: { persistOrderIntentWithLimits: jest.Mock }, prismaOverrides: Record<string, unknown> = {}) {
  const prisma = {
    tradingAccount: {
      findFirst: jest.fn(async () => ({ id: ACCOUNT_ID, userId: 'user-1', status: 'ACTIVE', liveTradingEnabled: true })),
      findUnique: jest.fn(async () => ({ id: ACCOUNT_ID, userId: 'user-1', status: 'ACTIVE', liveTradingEnabled: true })),
    },
    tradingSymbol: {
      findFirst: jest.fn(async () => ({
        id: 'symbol-1',
        symbol: SYMBOL,
        minQuantity: '0.0001',
        maxQuantity: '100',
        quantityStep: '0.0001',
        priceStep: '0.01',
        exchange: { id: 'exchange-1', venue: 'BINANCE', isEnabled: true, tradingEnabled: true },
      })),
    },
    exchangeCredential: { findFirst: jest.fn(async () => ({ id: 'cred-1' })) },
    complianceScreeningRequest: { findFirst: jest.fn(async () => null) },
    securityThreatSignal: { findFirst: jest.fn(async () => null) },
    ...prismaOverrides,
  };
  const riskDecisionService = {
    evaluateUnifiedRisk: jest.fn(async () => ({ decision: 'ALLOW', blockingReasons: [], policyVersion: 'v1' })),
  };
  const outbox = { append: jest.fn(async () => undefined) };
  const service = new OrderIntentService(
    prisma as never,
    riskDecisionService as never,
    limiter as unknown as PositionLimitService,
    outbox as never,
  );
  return { service, prisma, riskDecisionService, outbox };
}

function intentParams() {
  return {
    tenantId: TENANT_ID,
    accountId: ACCOUNT_ID,
    symbol: SYMBOL,
    side: 'BUY',
    orderType: 'LIMIT',
    quantity: '0.5',
    price: '60000',
    environment: 'PAPER',
    source: 'MANUAL',
    userId: 'user-1',
  } as never;
}

describe('OrderIntentService routes every intent through the position-limit reservation', () => {
  it('asks the limiter to reserve before it writes anything', async () => {
    const limiter = limiterThat('ALLOW');
    const { service } = buildService(limiter.service);

    await service.createIntent(intentParams());

    expect(limiter.service.persistOrderIntentWithLimits).toHaveBeenCalledTimes(1);
    expect(limiter.reservations).toEqual([
      { tenantId: TENANT_ID, accountId: ACCOUNT_ID, symbol: SYMBOL },
    ]);
  });

  it('writes the intent on the limiter\'s client, not on this.prisma', async () => {
    // The lock only means anything if the insert commits inside it. A write on the plain client
    // would slip past the reservation and two concurrent intents could both pass a ceiling they
    // jointly exceed, so the client identity is asserted rather than assumed.
    const limiter = limiterThat('ALLOW');
    const plainCreate = jest.fn(async () => ({ id: 'wrong-client' }));
    const { service, prisma } = buildService(limiter.service, {
      omsOrderIntent: { create: plainCreate },
      order: { create: plainCreate },
    });

    const created = await service.createIntent(intentParams());

    expect(limiter.tx.omsOrderIntent.create).toHaveBeenCalledTimes(1);
    expect(plainCreate).not.toHaveBeenCalled();
    expect((created as { id: string }).id).toBe('intent-1');
  });

  it('surfaces the limiter\'s refusal instead of placing the order', async () => {
    const limiter = limiterThat('REFUSE');
    const omsCreate = jest.fn();
    const orderCreate = jest.fn();
    const { service } = buildService(limiter.service, {
      omsOrderIntent: { create: omsCreate },
      order: { create: orderCreate },
    });

    await expect(service.createIntent(intentParams())).rejects.toThrow(
      'USER_CONCURRENT_POSITION_LIMIT_EXCEEDED',
    );
    // Nothing was written anywhere: the refusal is a refusal, not a warning.
    expect(omsCreate).not.toHaveBeenCalled();
    expect(orderCreate).not.toHaveBeenCalled();
  });

  it('reserves against the account the intent names, not a caller-supplied owner', async () => {
    // The limiter derives the user from the TradingAccount owner row internally; this asserts the
    // order path hands it the account identity to do that with, so a caller cannot nominate which
    // user's ceiling applies.
    const limiter = limiterThat('ALLOW');
    const { service } = buildService(limiter.service);

    await service.createIntent(intentParams());

    const call = limiter.service.persistOrderIntentWithLimits.mock.calls[0]?.[0] as {
      tenantId: string;
      accountId: string;
    };
    expect(call.tenantId).toBe(TENANT_ID);
    expect(call.accountId).toBe(ACCOUNT_ID);
  });
});

describe('the ceiling is registered where Nest can mount and inject it', () => {
  it('mounts the settings controller', () => {
    // Without this the routes do not exist and a customer has nowhere to set the limit that the
    // order path enforces. Read through Reflect because that is where @Module records the arrays
    // Nest builds the module from - a static property would prove nothing.
    const controllers = Reflect.getMetadata(MODULE_METADATA.CONTROLLERS, RiskManagementModule) as unknown[];
    expect(controllers).toContain(UserPositionLimitController);
  });

  it('provides and exports one PositionLimitService for both the settings route and the order path', () => {
    const providers = Reflect.getMetadata(MODULE_METADATA.PROVIDERS, RiskManagementModule) as unknown[];
    const exports = Reflect.getMetadata(MODULE_METADATA.EXPORTS, RiskManagementModule) as unknown[];
    expect(providers).toContain(PositionLimitService);
    // Exported, so the order path resolves the same instance the settings route writes to.
    expect(exports).toContain(PositionLimitService);
  });
});

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { ReconciliationCategory, isValidDecimal, parseScaled, formatScaled, reconciliationErrorCode } from './oms.types';

/**
 * Position Reconciliation Service — cross-checks cumulative fills ↔ canonical position ↔ exchange snapshot
 * without becoming a position source. Does not directly overwrite authoritative position source.
 */

@Injectable()
export class PositionReconciliationService {
  private readonly logger = new Logger(PositionReconciliationService.name);

  constructor(private readonly prisma: PrismaService) {}

  async reconcilePosition(params: { tenantId: string; accountId: string; symbol: string }) {
    const { tenantId, accountId, symbol } = params;

    const position = await this.prisma.position.findFirst({ where: { tenantId, accountId, symbol } });
    const orders = await this.prisma.order.findMany({ where: { tenantId, accountId, symbol } });
    const orderIds = orders.map((o) => o.id);
    const fills = orderIds.length > 0 ? await this.prisma.fill.findMany({ where: { orderId: { in: orderIds } }, orderBy: { receivedTimestampMicros: 'asc' } }) : [];

    const findings: Array<{ category: string; severity: string; summary: string; expected: any; actual: any }> = [];

    // Calculate net quantity from fills
    let netQty = 0n;
    for (const fill of fills) {
      const qtyStr = fill.quantity.toString();
      const side = fill.side ?? orders.find((o) => o.id === fill.orderId)?.side;
      if (!isValidDecimal(qtyStr)) continue;
      const qty = parseScaled(qtyStr);
      if (side === 'BUY') netQty += qty;
      else if (side === 'SELL') netQty -= qty;
    }

    if (position) {
      const posQtyStr = position.quantity.toString();
      if (isValidDecimal(posQtyStr)) {
        const posQty = parseScaled(posQtyStr);
        if (posQty !== netQty) {
          findings.push({
            category: ReconciliationCategory.POSITION_QUANTITY_MISMATCH,
            severity: 'HIGH',
            summary: `Position quantity mismatch ${symbol} account ${accountId}: position ${posQtyStr} vs net fills ${formatScaled(netQty)}`,
            expected: { netFills: formatScaled(netQty) },
            actual: { positionQuantity: posQtyStr },
          });
        }

        // Side mismatch
        const expectedSide = netQty > 0n ? 'LONG' : netQty < 0n ? 'SHORT' : 'FLAT';
        if (position.side !== expectedSide) {
          findings.push({
            category: ReconciliationCategory.SIDE_MISMATCH,
            severity: 'MEDIUM',
            summary: `Side mismatch ${symbol} account ${accountId}: position side ${position.side} vs expected ${expectedSide} from fills`,
            expected: { side: expectedSide },
            actual: { side: position.side },
          });
        }

        // Position without fills
        if (fills.length === 0 && posQty !== 0n) {
          findings.push({
            category: ReconciliationCategory.POSITION_WITHOUT_FILLS,
            severity: 'MEDIUM',
            summary: `Position ${symbol} account ${accountId} qty ${posQtyStr} exists but no fills found`,
            expected: { fillsExist: true },
            actual: { fillCount: 0, positionQuantity: posQtyStr },
          });
        }

        // Stale position
        const ageMs = Date.now() - new Date(position.updatedAt).getTime();
        if (ageMs > 24 * 60 * 60 * 1000) {
          findings.push({
            category: ReconciliationCategory.STALE_POSITION,
            severity: 'LOW',
            summary: `Stale position ${symbol} account ${accountId} age ${Math.floor(ageMs / 1000 / 60)}m`,
            expected: { maxAgeMs: 24 * 60 * 60 * 1000 },
            actual: { ageMs, updatedAt: position.updatedAt.toISOString() },
          });
        }
      }
    } else {
      // No position but fills exist
      if (netQty !== 0n) {
        findings.push({
          category: ReconciliationCategory.FILLS_WITHOUT_POSITION,
          severity: 'MEDIUM',
          summary: `Fills exist for ${symbol} account ${accountId} net ${formatScaled(netQty)} but no position record`,
          expected: { positionExists: true },
          actual: { netFills: formatScaled(netQty), fillCount: fills.length },
        });
      }
    }

    // Compare with exchange position snapshot if available (from exchange-position-sync)
    // We don't have a dedicated snapshot table in this schema, but we can check accountBalanceSnapshot as proxy for health
    // For now, we skip exchange snapshot unless model exists

    // Persist findings. A finding that cannot be stored is never dropped silently: it stays in the
    // returned result, is counted in persistFailures and is logged at error level (error code only,
    // never row values) - the same contract as order and fill reconciliation.
    let persistedFindings = 0;
    let persistFailures = 0;
    for (const f of findings) {
      try {
        await (this.prisma as any).omsReconciliation.create({
          data: {
            tenantId,
            internalOrderId: null,
            providerOrderId: null,
            category: f.category,
            severity: f.severity,
            expected: f.expected,
            actual: f.actual,
            summary: f.summary.slice(0, 1000),
            resolved: false,
          },
        });
        persistedFindings++;
      } catch (e) {
        persistFailures++;
        this.logger.error(
          `Position reconciliation finding NOT persisted ${symbol} account ${accountId} tenant ${tenantId} category ${f.category} severity ${f.severity} error ${reconciliationErrorCode(e)}`,
        );
      }
    }

    if (persistFailures > 0) {
      this.logger.warn(
        `Position reconciliation ${symbol} account ${accountId} tenant ${tenantId} findings ${findings.length} persisted ${persistedFindings} persistFailures ${persistFailures}`,
      );
    } else {
      this.logger.log(`Position reconciliation ${symbol} account ${accountId} tenant ${tenantId} findings ${findings.length} netFills ${formatScaled(netQty)} pos ${position?.quantity.toString() ?? 'none'}`);
    }
    return {
      accountId,
      symbol,
      position: position ? { quantity: position.quantity.toString(), side: position.side } : null,
      netFills: formatScaled(netQty),
      fillCount: fills.length,
      findings,
      totalFindings: findings.length,
      persistedFindings,
      persistFailures,
    };
  }

  async reconcileAccountPositions(params: { tenantId: string; accountId: string }) {
    const { tenantId, accountId } = params;
    const positions = await this.prisma.position.findMany({ where: { tenantId, accountId } });
    const results = [];
    for (const pos of positions) {
      const res = await this.reconcilePosition({ tenantId, accountId, symbol: pos.symbol });
      results.push(res);
    }

    // Also check symbols that have fills but no position
    const orders = await this.prisma.order.findMany({ where: { tenantId, accountId } });
    const symbolsWithFills = new Set<string>();
    for (const order of orders) {
      const fills = await this.prisma.fill.findMany({ where: { orderId: order.id } });
      if (fills.length > 0) symbolsWithFills.add(order.symbol);
    }
    const positionSymbols = new Set(positions.map((p) => p.symbol));
    for (const sym of symbolsWithFills) {
      if (!positionSymbols.has(sym)) {
        const res = await this.reconcilePosition({ tenantId, accountId, symbol: sym });
        results.push(res);
      }
    }

    return { accountId, totalPositions: positions.length, totalFindings: results.reduce((s, r) => s + r.totalFindings, 0), results };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { TradeLifecycleService } from './trade-lifecycle.service';
import { isValidDecimal, parseScaled, formatScaled } from './oms.types';
import { randomUUID } from 'crypto';

/**
 * Post-Trade Service — coordinates post-trade completion, fee/fill aggregation,
 * settlement references, and downstream fee/usage/audit events.
 * Does NOT duplicate Part 7 fee calculation.
 */

@Injectable()
export class PostTradeService {
  private readonly logger = new Logger(PostTradeService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly tradeLifecycleService: TradeLifecycleService,
  ) {}

  async processPostTrade(params: {
    tenantId: string;
    intentId: string;
    accountId: string;
    symbol: string;
    venue?: string | null;
    strategyId?: string | null;
    traderId?: string | null;
    followerId?: string | null;
    correlationId?: string | null;
  }) {
    const { tenantId, intentId, accountId, symbol, venue, strategyId, traderId, followerId, correlationId } = params;

    let intent: any;
    try {
      intent = await (this.prisma as any).omsOrderIntent.findFirst({ where: { id: intentId, tenantId } });
    } catch {
      intent = await this.prisma.order.findFirst({ where: { id: intentId, tenantId } });
    }
    if (!intent) throw new Error(`Intent ${intentId} not found`);

    const currentState = intent.state ?? intent.status;
    if (!['FILLED', 'PARTIALLY_FILLED', 'CANCELLED'].includes(currentState)) {
      this.logger.warn(`Post-trade called for intent ${intentId} in state ${currentState}, skipping`);
      return null;
    }

    // Aggregate execution results from fills
    let fills: any[] = [];
    try {
      fills = await (this.prisma as any).omsFill.findMany({ where: { tenantId, orderIntentId: intentId, state: { not: 'DUPLICATE' } } });
    } catch {
      const order = await this.prisma.order.findFirst({ where: { tenantId, clientOrderId: intent.clientOrderId } });
      if (order) fills = await this.prisma.fill.findMany({ where: { orderId: order.id } });
    }

    if (fills.length === 0) {
      this.logger.warn(`No fills for post-trade intent ${intentId}`);
      return null;
    }

    let totalQty = 0n;
    let totalNotional = 0n;
    let totalFee = 0n;
    let feeCurrency: string | null = null;
    for (const f of fills) {
      const qtyStr = f.quantity?.toString() ?? f.quantity;
      const priceStr = f.price?.toString() ?? f.price;
      const feeStr = f.fee?.toString() ?? f.fee ?? '0';
      if (isValidDecimal(qtyStr) && isValidDecimal(priceStr)) {
        const qty = parseScaled(qtyStr);
        const price = parseScaled(priceStr);
        totalQty += qty;
        totalNotional += (qty * price) / BigInt(1_000_000_000_000);
      }
      if (isValidDecimal(feeStr)) totalFee += parseScaled(feeStr);
      if (!feeCurrency && f.feeCurrency) feeCurrency = f.feeCurrency;
    }

    const avgPrice = totalQty > 0n ? formatScaled((totalNotional * BigInt(1_000_000_000_000)) / totalQty) : null;

    // Link fee references — check if fee accrual already exists (idempotency)
    let feeAccrualRef: string | null = null;
    try {
      const existingAccrual = await (this.prisma as any).feeAccrual.findFirst({ where: { tenantId, sourceId: intentId } });
      if (existingAccrual) {
        feeAccrualRef = existingAccrual.id;
        this.logger.log(`Fee accrual already exists for intent ${intentId}: ${feeAccrualRef}, not duplicating`);
      } else if (totalFee > 0n) {
        // Create fee accrual when existing commercial policy requires it — simplified: create if fee >0 and env LIVE
        if (intent.environment === 'LIVE') {
          const accrual = await (this.prisma as any).feeAccrual.create({
            data: {
              tenantId,
              feeType: 'TRADING',
              feeSourceType: 'ORDER_FILL',
              sourceId: intentId,
              sourceAmount: formatScaled(totalQty),
              feeAmount: formatScaled(totalFee),
              currency: feeCurrency ?? 'USDT',
              status: 'ACCRUED',
              settlementState: 'DRAFT',
              idempotencyKey: `fee-${intentId}`,
              metadata: { symbol, venue, accountId, fillCount: fills.length } as any,
              safeMetadata: { symbol, fillCount: fills.length } as any,
            },
          });
          feeAccrualRef = accrual.id;
          this.logger.log(`Fee accrual created ${feeAccrualRef} for intent ${intentId} fee ${formatScaled(totalFee)}`);
        }
      }
    } catch (e) {
      this.logger.warn(`Fee accrual check failed for ${intentId}: ${(e as Error).message}`);
    }

    // Usage event — idempotent
    let usageEventRef: string | null = null;
    try {
      const existingUsage = await (this.prisma as any).usageEvent.findFirst({ where: { tenantId, sourceId: intentId } });
      if (existingUsage) {
        usageEventRef = existingUsage.id;
        this.logger.log(`Usage event already exists for intent ${intentId}: ${usageEventRef}, not duplicating`);
      } else {
        const periodId = new Date().toISOString().slice(0, 7); // YYYY-MM
        const usage = await (this.prisma as any).usageEvent.create({
          data: {
            tenantId,
            meterKey: 'order_fills',
            eventType: 'ORDER_FILLED',
            sourceId: intentId,
            sourceType: 'OMS_ORDER',
            quantity: fills.length,
            periodId,
            idempotencyKey: `usage-${intentId}`,
            status: 'RECEIVED',
            metadata: { symbol, venue, accountId } as any,
            safeMetadata: { symbol, fillCount: fills.length } as any,
          },
        });
        usageEventRef = usage.id;
      }
    } catch (e) {
      this.logger.warn(`Usage event check failed for ${intentId}: ${(e as Error).message}`);
    }

    // Trade lifecycle already updated via FillManagementService, but ensure
    // For each fill, buildOrUpdateTradeFromFill already called, we can fetch latest trade
    let tradeLifecycleRef: string | null = null;
    try {
      const trades = await this.tradeLifecycleService.getOpenTrades({ tenantId, accountId, symbol, strategyId: strategyId as any });
      // Also include recently closed trades
      const history = await this.tradeLifecycleService.getTradeHistory({ tenantId, accountId, symbol, limit: 5 });
      const allTrades = [...trades, ...history];
      const related = allTrades.find((t: any) => t.orderIds?.includes(intentId) || t.fillIds?.some((fid: string) => fills.map((f: any) => f.id).includes(fid)));
      if (related) tradeLifecycleRef = related.id;
    } catch {}

    // Settlement reference — simplified: use fill aggregation as settlement evidence
    const settlementRef = `settlement-${intentId}-${randomUUID().slice(0, 8)}`;

    // Notifications — emit where applicable, but don't duplicate
    let notificationRef: string | null = null;
    try {
      // Check if notification already sent for this intent
      const existingNotif = await this.prisma.notification.findFirst({ where: { tenantId, type: 'ORDER_FILLED' } as any });
      if (existingNotif) {
        notificationRef = existingNotif.id;
      } else if (intent.environment === 'LIVE') {
        // Only notify for LIVE filled orders
        const notif = await this.prisma.notification.create({
          data: {
            tenantId,
            userId: intent.followerId ?? intent.traderId ?? accountId, // simplified
            channel: 'IN_APP' as any,
            type: 'ORDER_FILLED',
            title: `Order ${intent.symbol} ${intent.side} filled`,
            body: `Order ${intent.symbol} ${intent.side} qty ${formatScaled(totalQty)} avg ${avgPrice ?? 'unknown'} filled`,
            data: { orderIntentId: intentId, symbol, side: intent.side, quantity: formatScaled(totalQty), averagePrice: avgPrice, fee: formatScaled(totalFee) } as any,
          },
        });
        notificationRef = notif.id;
      }
    } catch (e) {
      this.logger.warn(`Notification failed for ${intentId}: ${(e as Error).message}`);
    }

    // Determine if reconciliation should be triggered — e.g., if filled qty != order qty
    const orderQtyStr = intent.quantity?.toString() ?? intent.quantity;
    let reconciliationTriggered = false;
    if (isValidDecimal(orderQtyStr)) {
      const orderQty = parseScaled(orderQtyStr);
      if (totalQty !== orderQty && currentState === 'FILLED') {
        reconciliationTriggered = true;
        this.logger.warn(`Post-trade quantity mismatch intent ${intentId} order ${orderQtyStr} vs filled ${formatScaled(totalQty)}, triggering reconciliation`);
        // Would enqueue reconciliation job via queue — simplified log
      }
    }

    const result = {
      id: randomUUID(),
      tenantId,
      orderIntentId: intentId,
      tradeId: tradeLifecycleRef,
      accountId,
      symbol,
      venue: venue ?? null,
      totalFilledQuantity: formatScaled(totalQty),
      averageFillPrice: avgPrice,
      totalFees: formatScaled(totalFee),
      feeCurrency,
      settlementRef,
      feeAccrualRef,
      usageEventRef,
      notificationRef,
      tradeLifecycleRef,
      reconciliationTriggered,
      completedAt: new Date().toISOString(),
      metadata: { fillCount: fills.length, correlationId },
    };

    // Persist post-trade result if model exists
    try {
      await (this.prisma as any).omsPostTrade.create({ data: result });
    } catch {}

    // Audit
    try {
      await this.prisma.auditLog.create({
        data: {
          tenantId,
          actorType: 'SYSTEM',
          action: 'POST_TRADE_COMPLETED',
          resourceType: 'OMS_ORDER',
          resourceId: intentId,
          description: `Post-trade completed intent ${intentId} ${symbol} qty ${formatScaled(totalQty)} avg ${avgPrice ?? 'n/a'} fee ${formatScaled(totalFee)}`.slice(0, 500),
          metadata: { settlementRef, feeAccrualRef, usageEventRef, tradeLifecycleRef, reconciliationTriggered } as any,
        },
      });
    } catch {}

    this.logger.log(`Post-trade completed intent ${intentId} tenant ${tenantId} qty ${formatScaled(totalQty)} avg ${avgPrice} fee ${formatScaled(totalFee)}`);
    return result;
  }
}

import { Logger } from '@nestjs/common';
import { OrderReconciliationService } from './order-reconciliation.service';
import { FillReconciliationService } from './fill-reconciliation.service';
import { reconciliationErrorCode } from './oms.types';

/**
 * Reconciliation findings that cannot be stored are never dropped silently:
 * they stay in the returned result, are counted (persistedFindings /
 * persistFailures) and are logged at error level with the error code only,
 * never with the row values that a Prisma error message can echo.
 */

const TENANT = '11111111-1111-4111-8111-111111111111';
const SECRET_LOOKING_VALUE = 'row-value-that-must-not-be-logged';

function storeFailure(): Error {
  return Object.assign(new Error(`Foreign key constraint failed ... ${SECRET_LOOKING_VALUE}`), { code: 'P2003' });
}

describe('reconciliationErrorCode', () => {
  it('prefers the Prisma error code, then the error class name, never the message', () => {
    expect(reconciliationErrorCode(Object.assign(new Error('secret'), { code: 'P2002' }))).toBe('P2002');
    expect(reconciliationErrorCode(new TypeError('secret'))).toBe('TypeError');
    expect(reconciliationErrorCode(null)).toBe('UNKNOWN');
    expect(reconciliationErrorCode('secret')).toBe('UNKNOWN');
  });
});

describe('OMS reconciliation persistence observability', () => {
  let errorSpy: jest.SpyInstance;
  let warnSpy: jest.SpyInstance;

  beforeEach(() => {
    errorSpy = jest.spyOn(Logger.prototype, 'error').mockImplementation(() => undefined);
    warnSpy = jest.spyOn(Logger.prototype, 'warn').mockImplementation(() => undefined);
    jest.spyOn(Logger.prototype, 'log').mockImplementation(() => undefined);
  });

  afterEach(() => jest.restoreAllMocks());

  function orderPrisma(create: jest.Mock) {
    return {
      omsOrderIntent: { findFirst: jest.fn(async () => ({ id: 'intent-1', tenantId: TENANT, clientOrderId: 'c-1', state: 'SUBMITTED', metadata: {} })) },
      order: { findFirst: jest.fn(async () => null), findMany: jest.fn(async () => []) },
      orderEvent: { findFirst: jest.fn(async () => null) },
      omsReconciliation: { create },
    };
  }

  it('order reconciliation: counts and logs a finding that could not be stored', async () => {
    const service = new OrderReconciliationService(orderPrisma(jest.fn(async () => { throw storeFailure(); })) as any);
    const result = await service.reconcileOrder({ tenantId: TENANT, intentId: 'intent-1' });

    expect(result.totalFindings).toBe(1);
    expect(result.findings[0].category).toBe('MISSING_EXCHANGE_ORDER');
    expect(result.persistedFindings).toBe(0);
    expect(result.persistFailures).toBe(1);
    expect(errorSpy).toHaveBeenCalledTimes(1);
    const logged = String(errorSpy.mock.calls[0][0]);
    expect(logged).toContain('NOT persisted');
    expect(logged).toContain(TENANT);
    expect(logged).toContain('P2003');
    expect(logged).not.toContain(SECRET_LOOKING_VALUE);
    expect(warnSpy).toHaveBeenCalledWith(expect.stringContaining('persistFailures 1'));
  });

  it('order reconciliation: reports every stored finding as persisted', async () => {
    const create = jest.fn(async ({ data }: any) => ({ id: 'rec-1', ...data }));
    const service = new OrderReconciliationService(orderPrisma(create) as any);
    const result = await service.reconcileOrder({ tenantId: TENANT, intentId: 'intent-1' });

    expect(create).toHaveBeenCalledTimes(1);
    expect(result.persistedFindings).toBe(1);
    expect(result.persistFailures).toBe(0);
    expect(errorSpy).not.toHaveBeenCalled();
  });

  function fillPrisma(create: jest.Mock) {
    return {
      fill: { findMany: jest.fn(async () => [{ venueTradeId: 'trade-1', quantity: '1', price: '100' }]) },
      omsFill: { findMany: jest.fn(async () => []) },
      omsReconciliation: { create },
    };
  }

  it('fill reconciliation: counts and logs a finding that could not be stored', async () => {
    const service = new FillReconciliationService(fillPrisma(jest.fn(async () => { throw storeFailure(); })) as any);
    const result = await service.reconcileFillsForOrder({ tenantId: TENANT, orderId: 'order-1' });

    // One canonical fill with no OMS fill: MISSING_FILL plus the cumulative QUANTITY_DRIFT (1 vs 0).
    expect(result.findings.map((f: any) => f.category)).toEqual(['MISSING_FILL', 'QUANTITY_DRIFT']);
    expect(result.persistedFindings).toBe(0);
    expect(result.persistFailures).toBe(2);
    expect(errorSpy).toHaveBeenCalledTimes(2);
    expect(warnSpy).toHaveBeenCalledWith(expect.stringContaining('persistFailures 2'));
    const logged = String(errorSpy.mock.calls[0][0]);
    expect(logged).toContain('order-1');
    expect(logged).toContain('P2003');
    expect(logged).not.toContain(SECRET_LOOKING_VALUE);
  });

  it('fill reconciliation: reports every stored finding as persisted', async () => {
    const service = new FillReconciliationService(fillPrisma(jest.fn(async ({ data }: any) => ({ id: 'rec-1', ...data }))) as any);
    const result = await service.reconcileFillsForOrder({ tenantId: TENANT, orderId: 'order-1' });

    expect(result.totalFindings).toBe(2);
    expect(result.persistedFindings).toBe(2);
    expect(result.persistFailures).toBe(0);
    expect(errorSpy).not.toHaveBeenCalled();
  });
});

import { Logger } from '@nestjs/common';
import { OrderReconciliationService } from './order-reconciliation.service';
import { FillReconciliationService } from './fill-reconciliation.service';
import { PositionReconciliationService } from './position-reconciliation.service';

/**
 * Reconciliation read fallbacks are observable (round 7):
 *  - order reconciliation that cannot read the OMS intent table reconciles from the canonical
 *    order row, and says so (intentSource CANONICAL_ORDER_FALLBACK + intentReadError, warn log);
 *  - fill reconciliation whose OMS fill read fails does NOT turn the failure into "every
 *    canonical fill is missing": the OMS comparisons are skipped, the failure is logged and
 *    reported (omsFillsRead FAILED, readFailures 1); canonical-only checks still run;
 *  - the tenant-wide fill run counts intent lookup failures instead of swallowing them;
 *  - position reconciliation counts and logs findings that could not be stored, like order and
 *    fill reconciliation already did.
 * Logs carry the error code only, never the Prisma message (it can echo row values).
 */

const TENANT = '11111111-1111-4111-8111-111111111111';
const SECRET_LOOKING_VALUE = 'row-value-that-must-not-be-logged';

function readFailure(): Error {
  return Object.assign(new Error(`relation does not exist ${SECRET_LOOKING_VALUE}`), { code: 'P2021' });
}

describe('OMS reconciliation read fallbacks', () => {
  let errorSpy: jest.SpyInstance;
  let warnSpy: jest.SpyInstance;

  beforeEach(() => {
    errorSpy = jest.spyOn(Logger.prototype, 'error').mockImplementation(() => undefined);
    warnSpy = jest.spyOn(Logger.prototype, 'warn').mockImplementation(() => undefined);
    jest.spyOn(Logger.prototype, 'log').mockImplementation(() => undefined);
  });

  afterEach(() => jest.restoreAllMocks());

  describe('order reconciliation', () => {
    const canonical = { id: 'intent-1', tenantId: TENANT, clientOrderId: 'c-1', status: 'SUBMITTED', exchangeOrderId: null, quantity: '1', metadata: {} };

    function prisma(intentRead: jest.Mock) {
      return {
        omsOrderIntent: { findFirst: intentRead, findMany: intentRead },
        order: {
          findFirst: jest.fn(async () => canonical),
          findMany: jest.fn(async () => [canonical]),
        },
        orderEvent: { findFirst: jest.fn(async () => ({ id: 'ack' })) },
        omsReconciliation: { create: jest.fn(async ({ data }: any) => ({ id: 'rec', ...data })) },
      };
    }

    it('reports the OMS intent as the source when the read works', async () => {
      const service = new OrderReconciliationService(
        prisma(jest.fn(async () => ({ ...canonical, state: 'SUBMITTED' }))) as any,
      );
      const result = await service.reconcileOrder({ tenantId: TENANT, intentId: 'intent-1' });

      expect(result).toMatchObject({ intentSource: 'OMS_INTENT', intentReadError: null });
      expect(warnSpy).not.toHaveBeenCalled();
    });

    it('falls back to the canonical order visibly when the OMS intent read fails', async () => {
      const service = new OrderReconciliationService(prisma(jest.fn(async () => { throw readFailure(); })) as any);
      const result = await service.reconcileOrder({ tenantId: TENANT, intentId: 'intent-1' });

      expect(result).toMatchObject({ intentSource: 'CANONICAL_ORDER_FALLBACK', intentReadError: 'P2021' });
      const warned = JSON.stringify(warnSpy.mock.calls);
      expect(warned).toContain('OMS intent read failed');
      expect(warned).toContain('P2021');
      expect(warned).not.toContain(SECRET_LOOKING_VALUE);
    });

    it('tenant run: reports the list fallback and counts per-order fallbacks', async () => {
      const service = new OrderReconciliationService(prisma(jest.fn(async () => { throw readFailure(); })) as any);
      const result = await service.reconcileTenant({ tenantId: TENANT });

      expect(result).toMatchObject({ totalChecked: 1, intentSource: 'CANONICAL_ORDER_FALLBACK', intentReadError: 'P2021', readFallbacks: 1 });
      expect(JSON.stringify(warnSpy.mock.calls)).toContain('OMS intent list read failed');
    });
  });

  describe('fill reconciliation', () => {
    function prisma(omsRead: jest.Mock, create = jest.fn(async ({ data }: any) => ({ id: 'rec', ...data }))) {
      return {
        fill: {
          findMany: jest.fn(async () => [
            { venueTradeId: 'trade-1', quantity: '1', price: '100', fee: '0', feeCurrency: 'USDT' },
            { venueTradeId: 'trade-1', quantity: '1', price: '100', fee: '0', feeCurrency: 'USDT' },
          ]),
        },
        omsFill: { findMany: omsRead },
        omsOrderIntent: { findFirst: jest.fn(async () => { throw readFailure(); }) },
        order: { findMany: jest.fn(async () => [{ id: 'order-1', clientOrderId: 'c-1' }]) },
        omsReconciliation: { create },
      };
    }

    it('does not report a failed OMS read as missing fills; reports the read failure instead', async () => {
      const create = jest.fn(async ({ data }: any) => ({ id: 'rec', ...data }));
      const service = new FillReconciliationService(prisma(jest.fn(async () => { throw readFailure(); }), create) as any);
      const result = await service.reconcileFillsForOrder({ tenantId: TENANT, orderId: 'order-1' });

      expect(result).toMatchObject({ omsFillsRead: 'FAILED', omsFillsReadError: 'P2021', readFailures: 1 });
      // Only the canonical-only check (the duplicated canonical fill) produced a finding.
      expect(result.findings.map((f: any) => f.category)).toEqual(['DUPLICATE_FILL']);
      expect(create).toHaveBeenCalledTimes(1);
      const logged = JSON.stringify(errorSpy.mock.calls);
      expect(logged).toContain('OMS fill read failed');
      expect(logged).toContain('P2021');
      expect(logged).not.toContain(SECRET_LOOKING_VALUE);
    });

    it('still compares against OMS fills when the read works', async () => {
      const service = new FillReconciliationService(prisma(jest.fn(async () => [])) as any);
      const result = await service.reconcileFillsForOrder({ tenantId: TENANT, orderId: 'order-1' });

      expect(result).toMatchObject({ omsFillsRead: 'OK', omsFillsReadError: null, readFailures: 0 });
      expect(result.findings.map((f: any) => f.category)).toEqual(['MISSING_FILL', 'QUANTITY_DRIFT', 'DUPLICATE_FILL']);
    });

    it('tenant run: counts intent lookup failures and read failures', async () => {
      const service = new FillReconciliationService(prisma(jest.fn(async () => { throw readFailure(); })) as any);
      const result = await service.reconcileTenantFills({ tenantId: TENANT });

      expect(result).toMatchObject({ totalChecked: 1, intentLookupFailures: 1, readFailures: 1, withFindings: 1 });
      expect(result.results).toHaveLength(1);
      expect(JSON.stringify(warnSpy.mock.calls)).toContain('OMS intent lookup failed');
    });
  });

  describe('position reconciliation persistence', () => {
    function prisma(create: jest.Mock) {
      return {
        position: { findFirst: jest.fn(async () => null) },
        order: { findMany: jest.fn(async () => [{ id: 'order-1', side: 'BUY', symbol: 'BTCUSDT' }]) },
        fill: { findMany: jest.fn(async () => [{ orderId: 'order-1', quantity: '1', price: '100', fee: '0' }]) },
        omsReconciliation: { create },
      };
    }

    it('counts and logs a finding that could not be stored (error code only)', async () => {
      const create = jest.fn(async () => {
        throw Object.assign(new Error(`Foreign key constraint failed ${SECRET_LOOKING_VALUE}`), { code: 'P2003' });
      });
      const service = new PositionReconciliationService(prisma(create) as any);
      const result = await service.reconcilePosition({ tenantId: TENANT, accountId: 'acct-1', symbol: 'BTCUSDT' });

      expect(result.totalFindings).toBeGreaterThan(0);
      expect(result.persistedFindings).toBe(0);
      expect(result.persistFailures).toBe(result.totalFindings);
      const logged = JSON.stringify(errorSpy.mock.calls);
      expect(logged).toContain('NOT persisted');
      expect(logged).toContain('P2003');
      expect(logged).not.toContain(SECRET_LOOKING_VALUE);
      expect(JSON.stringify(warnSpy.mock.calls)).toContain(`persistFailures ${result.totalFindings}`);
    });

    it('reports stored findings as persisted', async () => {
      const service = new PositionReconciliationService(prisma(jest.fn(async ({ data }: any) => ({ id: 'rec', ...data }))) as any);
      const result = await service.reconcilePosition({ tenantId: TENANT, accountId: 'acct-1', symbol: 'BTCUSDT' });

      expect(result.totalFindings).toBeGreaterThan(0);
      expect(result.persistedFindings).toBe(result.totalFindings);
      expect(result.persistFailures).toBe(0);
      expect(errorSpy).not.toHaveBeenCalled();
    });
  });
});

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OrderIntentState } from './oms.types';
import { randomUUID } from 'crypto';

/**
 * Trade Operations Service — operational control plane for search, filtering,
 * retry/recovery requests, stale-order handling, exception queues, operator workflows.
 * Retry/recovery must re-enter existing execution boundaries. Do not directly alter final exchange execution state.
 */

@Injectable()
export class TradeOperationsService {
  private readonly logger = new Logger(TradeOperationsService.name);

  constructor(private readonly prisma: PrismaService) {}

  async searchOrders(params: {
    tenantId: string;
    accountId?: string;
    strategyId?: string;
    traderId?: string;
    followerId?: string;
    symbol?: string;
    venue?: string;
    state?: string;
    from?: Date;
    to?: Date;
    page?: number;
    limit?: number;
    search?: string;
  }) {
    const { tenantId, accountId, strategyId, traderId, followerId, symbol, venue, state, from, to, page = 1, limit = 20, search } = params;

    try {
      const where: any = {
        tenantId,
        ...(accountId ? { accountId } : {}),
        ...(strategyId ? { strategyId } : {}),
        ...(traderId ? { traderId } : {}),
        ...(followerId ? { followerId } : {}),
        ...(symbol ? { symbol } : {}),
        ...(venue ? { venue } : {}),
        ...(state ? { state } : {}),
        ...(from || to ? { createdAt: { ...(from ? { gte: from } : {}), ...(to ? { lte: to } : {}) } } : {}),
        ...(search ? { OR: [{ symbol: { contains: search, mode: 'insensitive' } }, { clientOrderId: { contains: search } }] } : {}),
      };
      const [items, total] = await Promise.all([
        (this.prisma as any).omsOrderIntent.findMany({ where, orderBy: { createdAt: 'desc' }, skip: (page - 1) * limit, take: limit }),
        (this.prisma as any).omsOrderIntent.count({ where }),
      ]);
      return { items, total, page, limit };
    } catch {
      // Fallback to Order table
      const where: any = {
        tenantId,
        ...(accountId ? { accountId } : {}),
        ...(strategyId ? { strategyId } : {}),
        ...(symbol ? { symbol } : {}),
        ...(venue ? { venue } : {}),
        ...(state ? { status: state } : {}),
        ...(from || to ? { createdAt: { ...(from ? { gte: from } : {}), ...(to ? { lte: to } : {}) } } : {}),
      };
      const [items, total] = await Promise.all([
        this.prisma.order.findMany({ where, orderBy: { createdAt: 'desc' }, skip: (page - 1) * limit, take: limit }),
        this.prisma.order.count({ where }),
      ]);
      return { items, total, page, limit };
    }
  }

  async searchFills(params: {
    tenantId: string;
    accountId?: string;
    symbol?: string;
    venue?: string;
    orderIntentId?: string;
    from?: Date;
    to?: Date;
    page?: number;
    limit?: number;
  }) {
    const { tenantId, accountId, symbol, venue, orderIntentId, from, to, page = 1, limit = 20 } = params;
    const where: any = {
      tenantId,
      ...(accountId ? { accountId } : {}),
      ...(symbol ? { symbol } : {}),
      ...(venue ? { venue } : {}),
      ...(orderIntentId ? { orderIntentId } : {}),
      ...(from || to ? { timestamp: { gte: from?.toISOString(), lte: to?.toISOString() } } : {}),
    };
    const [items, total] = await Promise.all([
      (this.prisma as any).omsFill.findMany({ where, orderBy: { timestampMicros: 'desc' }, skip: (page - 1) * limit, take: limit }),
      (this.prisma as any).omsFill.count({ where }),
    ]);
    return { items, total, page, limit };
  }

  async searchTrades(params: {
    tenantId: string;
    accountId?: string;
    symbol?: string;
    strategyId?: string;
    state?: string;
    from?: Date;
    to?: Date;
    page?: number;
    limit?: number;
  }) {
    const { tenantId, accountId, symbol, strategyId, state, from, to, page = 1, limit = 20 } = params;
    const where: any = {
      tenantId,
      ...(accountId ? { accountId } : {}),
      ...(symbol ? { symbol } : {}),
      ...(strategyId ? { strategyId } : {}),
      ...(state ? { state } : {}),
      ...(from || to ? { openedAt: { ...(from ? { gte: from } : {}), ...(to ? { lte: to } : {}) } } : {}),
    };
    const [items, total] = await Promise.all([
      (this.prisma as any).omsTrade.findMany({ where, orderBy: { openedAt: 'desc' }, skip: (page - 1) * limit, take: limit }),
      (this.prisma as any).omsTrade.count({ where }),
    ]);
    return { items, total, page, limit };
  }

  async getStaleOrders(params: { tenantId: string; accountId?: string; thresholdMs?: number }) {
    const { tenantId, accountId, thresholdMs = 5 * 60 * 1000 } = params;
    const cutoff = new Date(Date.now() - thresholdMs);
    try {
      return await (this.prisma as any).omsOrderIntent.findMany({
        where: { tenantId, ...(accountId ? { accountId } : {}), state: { in: [OrderIntentState.SUBMITTED, OrderIntentState.ACKNOWLEDGED, OrderIntentState.PARTIALLY_FILLED, OrderIntentState.CANCEL_REQUESTED] }, updatedAt: { lt: cutoff } },
        orderBy: { updatedAt: 'asc' },
        take: 100,
      });
    } catch {
      return await this.prisma.order.findMany({
        where: { tenantId, ...(accountId ? { accountId } : {}), status: { in: ['SUBMITTED', 'ACKNOWLEDGED', 'PARTIALLY_FILLED'] as any }, updatedAt: { lt: cutoff } },
        orderBy: { updatedAt: 'asc' },
        take: 100,
      });
    }
  }

  async getReconciliationQueue(params: { tenantId: string; accountId?: string }) {
    const { tenantId, accountId } = params;
    return await (this.prisma as any).omsReconciliation.findMany({
      // OmsReconciliation has no accountId column: filter through the (optional) order intent.
      where: { tenantId, ...(accountId ? { orderIntent: { is: { accountId } } } : {}), resolved: false },
      orderBy: { createdAt: 'desc' },
      take: 100,
    });
  }

  async getRejectedOrders(params: { tenantId: string; accountId?: string }) {
    const { tenantId, accountId } = params;
    return await (this.prisma as any).omsRejection.findMany({
      where: { tenantId, ...(accountId ? { accountId } : {}), isRetriable: false },
      orderBy: { timestamp: 'desc' },
      take: 100,
    });
  }

  async acknowledgeException(params: { tenantId: string; operationalId: string; userId: string; note: string }) {
    const { tenantId, operationalId, userId, note } = params;
    try {
      const record = await (this.prisma as any).omsOperational.findFirst({ where: { id: operationalId, tenantId } });
      if (!record) throw new BadRequestException(`Operational record ${operationalId} not found`);
      const updated = await (this.prisma as any).omsOperational.update({
        where: { id: operationalId },
        data: { state: 'ACKNOWLEDGED', acknowledgedBy: userId, acknowledgedAt: new Date(), operatorNotes: { push: note } as any },
      });
      this.logger.log(`Operational ${operationalId} acknowledged by ${userId} tenant ${tenantId}`);
      return updated;
    } catch (e) {
      if ((e as any).message?.includes('not found')) throw e;
      // Fallback: create operational record as acknowledged
      return { id: operationalId, state: 'ACKNOWLEDGED', acknowledgedBy: userId, note };
    }
  }

  async requestRetry(params: { tenantId: string; intentId: string; userId: string; reason: string }) {
    const { tenantId, intentId, userId, reason } = params;

    let intent: any;
    try {
      intent = await (this.prisma as any).omsOrderIntent.findFirst({ where: { id: intentId, tenantId } });
    } catch {
      intent = await this.prisma.order.findFirst({ where: { id: intentId, tenantId } });
    }
    if (!intent) throw new BadRequestException(`Intent ${intentId} not found`);

    const currentState = intent.state ?? intent.status;
    if (!['REJECTED', 'FAILED', 'RECONCILIATION_REQUIRED'].includes(currentState)) {
      throw new BadRequestException(`Retry only allowed for REJECTED/FAILED/RECONCILIATION_REQUIRED, current ${currentState}`);
    }

    // Retry must re-enter existing execution boundaries — create new intent that references original
    // Do NOT directly alter final exchange execution state
    const operational = {
      id: randomUUID(),
      tenantId,
      type: 'RETRY_REQUESTED',
      state: 'PENDING',
      orderIntentId: intentId,
      internalOrderId: intent.internalOrderId ?? null,
      symbol: intent.symbol,
      venue: intent.venue ?? null,
      accountId: intent.accountId,
      summary: `Retry requested for intent ${intentId} reason ${reason}`,
      retryCount: 0,
      operatorNotes: [reason],
      correlationId: intent.correlationId ?? null,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };

    try {
      await (this.prisma as any).omsOperational.create({ data: { ...operational, requestedBy: userId, reason } });
    } catch {}

    this.logger.log(`Retry requested intent ${intentId} tenant ${tenantId} by ${userId} reason ${reason}`);
    return operational;
  }

  async requestRecovery(params: { tenantId: string; intentId: string; userId: string; reason: string; recoveryType: string }) {
    const { tenantId, intentId, userId, reason, recoveryType } = params;

    let intent: any;
    try {
      intent = await (this.prisma as any).omsOrderIntent.findFirst({ where: { id: intentId, tenantId } });
    } catch {
      intent = await this.prisma.order.findFirst({ where: { id: intentId, tenantId } });
    }
    if (!intent) throw new BadRequestException(`Intent ${intentId} not found`);

    // Recovery cannot bypass execution engine/live gate — it must re-enter boundaries
    // We only allow recovery for RECONCILIATION_REQUIRED or stale orders
    const currentState = intent.state ?? intent.status;
    if (!['RECONCILIATION_REQUIRED', 'SUBMITTED', 'ACKNOWLEDGED', 'PARTIALLY_FILLED', 'CANCEL_REQUESTED', 'FAILED'].includes(currentState)) {
      throw new BadRequestException(`Recovery not allowed for state ${currentState}`);
    }

    const operational = {
      id: randomUUID(),
      tenantId,
      type: 'RECOVERY_REQUESTED',
      state: 'PENDING',
      orderIntentId: intentId,
      internalOrderId: intent.internalOrderId ?? null,
      symbol: intent.symbol,
      venue: intent.venue ?? null,
      accountId: intent.accountId,
      summary: `Recovery ${recoveryType} requested for intent ${intentId} reason ${reason}`,
      retryCount: 0,
      operatorNotes: [reason],
      correlationId: intent.correlationId ?? null,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };

    try {
      await (this.prisma as any).omsOperational.create({ data: { ...operational, requestedBy: userId, reason, recoveryType } });
    } catch {}

    // Audit recovery request
    try {
      await this.prisma.auditLog.create({
        data: {
          tenantId,
          actorId: userId,
          actorType: 'USER',
          action: 'OMS_RECOVERY_REQUESTED',
          resourceType: 'OMS_ORDER',
          resourceId: intentId,
          description: `Recovery ${recoveryType} requested for intent ${intentId} reason ${reason}`.slice(0, 500),
          metadata: { recoveryType, reason } as any,
        },
      });
    } catch {}

    this.logger.log(`Recovery requested intent ${intentId} type ${recoveryType} tenant ${tenantId} by ${userId}`);
    return operational;
  }

  async addOperatorNote(params: { tenantId: string; operationalId: string; userId: string; note: string }) {
    const { tenantId, operationalId, userId, note } = params;
    try {
      const updated = await (this.prisma as any).omsOperational.update({
        where: { id: operationalId },
        data: { operatorNotes: { push: `${userId}: ${note}` } as any, updatedAt: new Date() },
      });
      return updated;
    } catch {
      return { id: operationalId, note: `${userId}: ${note}` };
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { isValidDecimal, parseScaled } from './oms.types';
import { randomUUID } from 'crypto';

/**
 * Venue Execution Score Service — creates explainable venue performance metrics.
 * Inputs: latency, fill ratio, slippage, rejection rate, provider errors, rate limits, stale data.
 * No subjective hidden scoring. Output contains metric values, methodology, observation count, period, venue.
 */

@Injectable()
export class VenueExecutionScoreService {
  private readonly logger = new Logger(VenueExecutionScoreService.name);

  constructor(private readonly prisma: PrismaService) {}

  async calculateForVenue(params: {
    tenantId: string;
    venue: string;
    from: Date;
    to: Date;
    accountId?: string | null;
  }) {
    const { tenantId, venue, from, to, accountId } = params;

    let intents: any[] = [];
    try {
      intents = await (this.prisma as any).omsOrderIntent.findMany({
        where: { tenantId, venue, ...(accountId ? { accountId } : {}), createdAt: { gte: from, lte: to } },
      });
    } catch {
      intents = await this.prisma.order.findMany({
        where: { tenantId, venue: venue as any, ...(accountId ? { accountId } : {}), createdAt: { gte: from, lte: to } },
      });
    }

    const totalOrders = intents.length;
    const filledOrders = intents.filter((o) => (o.state ?? o.status) === 'FILLED').length;
    const rejectedOrders = intents.filter((o) => (o.state ?? o.status) === 'REJECTED').length;

    const fillRatio = totalOrders > 0 ? filledOrders / totalOrders : null;
    const rejectionRate = totalOrders > 0 ? rejectedOrders / totalOrders : null;

    // Latency
    let latencySum = 0;
    let latencyCount = 0;
    const latencies: number[] = [];
    try {
      const acks = await (this.prisma as any).omsExecutionAck.findMany({ where: { tenantId, venue, createdAt: { gte: from, lte: to } } });
      for (const ack of acks) {
        if (ack.latencyMicros) {
          const micros = parseInt(ack.latencyMicros, 10);
          if (!isNaN(micros)) {
            const ms = micros / 1000;
            latencySum += ms;
            latencyCount++;
            latencies.push(ms);
          }
        }
      }
    } catch {}

    latencies.sort((a, b) => a - b);
    const avgLatency = latencyCount > 0 ? latencySum / latencyCount : null;
    const medianLatency = latencies.length > 0 ? latencies[Math.floor(latencies.length / 2)] : null;
    const p95Latency = latencies.length > 0 ? latencies[Math.floor(latencies.length * 0.95)] ?? latencies[latencies.length - 1] : null;

    // Slippage
    let slippageSum = 0;
    let slippageCount = 0;
    try {
      // OmsFill has no timestamp column (timestampMicros is a string): filter by createdAt.
      const fills = await (this.prisma as any).omsFill.findMany({ where: { tenantId, venue, createdAt: { gte: from, lte: to } } });
      for (const fill of fills) {
        const intent = intents.find((i) => i.id === fill.orderIntentId);
        if (!intent) continue;
        const intendedPriceStr = intent.price?.toString() ?? intent.price;
        const fillPriceStr = fill.price?.toString() ?? fill.price;
        if (!intendedPriceStr || !fillPriceStr) continue;
        if (!isValidDecimal(intendedPriceStr) || !isValidDecimal(fillPriceStr)) continue;
        const intended = Number(parseScaled(intendedPriceStr)) / 1e12;
        const actual = Number(parseScaled(fillPriceStr)) / 1e12;
        if (intended === 0) continue;
        const slip = intent.side === 'BUY' ? ((actual - intended) / intended) * 100 : ((intended - actual) / intended) * 100;
        slippageSum += slip;
        slippageCount++;
      }
    } catch {}

    const avgSlippage = slippageCount > 0 ? slippageSum / slippageCount : null;

    // Provider errors, rate limits, stale data from rejection records
    let providerErrorCount = 0;
    let rateLimitCount = 0;
    let staleDataCount = 0;
    try {
      const rejections = await (this.prisma as any).omsRejection.findMany({ where: { tenantId, venue, timestamp: { gte: from.toISOString(), lte: to.toISOString() } as any } });
      for (const r of rejections) {
        if (r.category === 'EXCHANGE_REJECT') providerErrorCount++;
        if (r.category === 'RATE_LIMITED') rateLimitCount++;
        if (r.category === 'MARKET_DATA_STALE') staleDataCount++;
      }
    } catch {
      // fallback to Order rejectionCode
      for (const intent of intents) {
        if ((intent.state ?? intent.status) === 'REJECTED') {
          const cat = (intent.metadata as any)?.rejectionCategory ?? intent.rejectionCategory;
          if (cat === 'EXCHANGE_REJECT') providerErrorCount++;
          if (cat === 'RATE_LIMITED') rateLimitCount++;
          if (cat === 'MARKET_DATA_STALE') staleDataCount++;
        }
      }
    }

    const score = {
      id: randomUUID(),
      tenantId,
      venue,
      periodStart: from.toISOString(),
      periodEnd: to.toISOString(),
      totalOrders,
      filledOrders,
      rejectedOrders,
      averageLatencyMs: avgLatency !== null ? avgLatency.toFixed(3) : null,
      medianLatencyMs: medianLatency !== null ? medianLatency.toFixed(3) : null,
      p95LatencyMs: p95Latency !== null ? p95Latency.toFixed(3) : null,
      fillRatio: fillRatio !== null ? fillRatio.toFixed(6) : null,
      rejectionRate: rejectionRate !== null ? rejectionRate.toFixed(6) : null,
      averageSlippage: avgSlippage !== null ? avgSlippage.toFixed(6) : null,
      providerErrorCount,
      rateLimitCount,
      staleDataCount,
      methodology: 'EXPLAINABLE_METRICS: fillRatio = filled/total, rejectionRate = rejected/total, latency = submit→ack micros, slippage = (fill-intended)/intended*100 per side, errors counted from rejection categories',
      observationCount: totalOrders,
      scoreComponents: {
        fillRatio: fillRatio !== null ? fillRatio.toFixed(6) : null,
        rejectionRate: rejectionRate !== null ? rejectionRate.toFixed(6) : null,
        avgLatencyMs: avgLatency !== null ? avgLatency.toFixed(3) : null,
        avgSlippage: avgSlippage !== null ? avgSlippage.toFixed(6) : null,
        providerErrorCount: providerErrorCount.toString(),
        rateLimitCount: rateLimitCount.toString(),
        staleDataCount: staleDataCount.toString(),
      },
      note: 'Venue execution score is measurable and explainable, not subjective. Higher fillRatio and lower latency/slippage/rejection indicate better execution. Observation count shows sample size.',
      calculatedAt: new Date().toISOString(),
    };

    try {
      await (this.prisma as any).omsVenueScore.create({ data: score });
    } catch {}

    this.logger.log(`Venue score calculated venue ${venue} tenant ${tenantId} orders ${totalOrders} fillRatio ${fillRatio} avgLatency ${avgLatency}`);
    return score;
  }

  async listVenueScores(params: { tenantId: string; from?: Date; to?: Date }) {
    const { tenantId, from, to } = params;
    return await (this.prisma as any).omsVenueScore.findMany({
      where: { tenantId, ...(from || to ? { periodStart: { gte: from?.toISOString(), lte: to?.toISOString() } as any } : {}) },
      orderBy: { calculatedAt: 'desc' },
      take: 100,
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { RedisService } from '../../infrastructure/redis/redis.service';
import { QueueService } from '../queue/queue.service';
import { AppConfigService } from '../../config/app-config.service';
import {
  OperationalDependencyType,
  OperationalDependencyState,
  DependencyHealthResult,
  redactSecrets,
} from './operations.types';
import { OperationsPolicyService } from './operations-policy.service';

/**
 * Performs authoritative dependency health checks for infrastructure and application dependencies.
 * Must distinguish HEALTHY, DEGRADED, UNAVAILABLE, MISCONFIGURED, and UNKNOWN and must never
 * treat missing credentials/configuration as healthy.
 */

@Injectable()
export class DependencyHealthService {
  private readonly logger = new Logger(DependencyHealthService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly redis: RedisService,
    private readonly queueService: QueueService,
    private readonly config: AppConfigService,
    private readonly policyService: OperationsPolicyService,
  ) {}

  async checkAll(tenantId?: string | null): Promise<DependencyHealthResult[]> {
    const checks: Promise<DependencyHealthResult>[] = [
      this.checkDatabase(),
      this.checkRedis(),
      this.checkQueues(),
      this.checkConfiguration(),
      this.checkSecurityControls(tenantId),
      this.checkLiveGate(tenantId),
      this.checkOms(tenantId),
      this.checkRisk(tenantId),
      this.checkCompliance(tenantId),
      this.checkBilling(tenantId),
      this.checkExchangeConnectivity(tenantId),
      this.checkCredentialSource(tenantId),
      this.checkDistributedLock(),
      this.checkExecutionEngine(tenantId),
    ];

    const results = await Promise.allSettled(checks);
    return results.map((r, idx) => {
      if (r.status === 'fulfilled') return r.value;
      const type = [
        OperationalDependencyType.DATABASE,
        OperationalDependencyType.REDIS,
        OperationalDependencyType.QUEUE,
        OperationalDependencyType.CONFIGURATION,
        OperationalDependencyType.SECURITY,
        OperationalDependencyType.LIVE_GATE,
        OperationalDependencyType.OMS,
        OperationalDependencyType.RISK,
        OperationalDependencyType.COMPLIANCE,
        OperationalDependencyType.BILLING,
        OperationalDependencyType.EXCHANGE,
        OperationalDependencyType.CREDENTIAL_SOURCE,
        OperationalDependencyType.DISTRIBUTED_LOCK,
        OperationalDependencyType.EXECUTION_ENGINE,
      ][idx] ?? OperationalDependencyType.EXTERNAL_PROVIDER;
      return {
        dependencyType: type,
        dependencyName: type,
        state: OperationalDependencyState.UNKNOWN,
        latencyMs: null,
        errorCode: 'CHECK_FAILED',
        errorMessage: r.reason instanceof Error ? r.reason.message : String(r.reason),
        evidence: redactSecrets({ error: r.reason instanceof Error ? r.reason.message : String(r.reason) }),
        checkedAt: new Date().toISOString(),
        isCritical: this.policyService.getReadinessPolicy(tenantId).criticalDependencies.includes(type),
      };
    });
  }

  async checkDatabase(): Promise<DependencyHealthResult> {
    const start = Date.now();
    try {
      // Authoritative check: actual query, not config presence
      await this.prisma.$queryRaw`SELECT 1 as ok`;
      const latency = Date.now() - start;
      return {
        dependencyType: OperationalDependencyType.DATABASE,
        dependencyName: 'postgresql-primary',
        state: OperationalDependencyState.HEALTHY,
        latencyMs: latency,
        evidence: { latencyMs: latency, checkedAt: new Date().toISOString() },
        checkedAt: new Date().toISOString(),
        isCritical: true,
      };
    } catch (e) {
      const msg = (e as Error).message;
      const state = msg.includes('configuration') || msg.includes('DATABASE_URL') ? OperationalDependencyState.MISCONFIGURED : OperationalDependencyState.UNAVAILABLE;
      return {
        dependencyType: OperationalDependencyType.DATABASE,
        dependencyName: 'postgresql-primary',
        state,
        latencyMs: Date.now() - start,
        errorCode: 'DATABASE_UNAVAILABLE',
        errorMessage: msg.slice(0, 500),
        evidence: redactSecrets({ error: msg }),
        checkedAt: new Date().toISOString(),
        isCritical: true,
      };
    }
  }

  async checkRedis(): Promise<DependencyHealthResult> {
    const start = Date.now();
    try {
      const result = await this.redis.healthCheck();
      if (!result.ok) {
        return {
          dependencyType: OperationalDependencyType.REDIS,
          dependencyName: 'redis-primary',
          state: OperationalDependencyState.UNAVAILABLE,
          latencyMs: result.latencyMs,
          errorCode: 'REDIS_PING_FAILED',
          errorMessage: 'PING did not return PONG',
          evidence: { latencyMs: result.latencyMs },
          checkedAt: new Date().toISOString(),
          isCritical: true,
        };
      }
      const state = result.latencyMs > 500 ? OperationalDependencyState.DEGRADED : OperationalDependencyState.HEALTHY;
      return {
        dependencyType: OperationalDependencyType.REDIS,
        dependencyName: 'redis-primary',
        state,
        latencyMs: result.latencyMs,
        evidence: { latencyMs: result.latencyMs },
        checkedAt: new Date().toISOString(),
        isCritical: true,
      };
    } catch (e) {
      const msg = (e as Error).message;
      const state = msg.toLowerCase().includes('config') || msg.toLowerCase().includes('url') ? OperationalDependencyState.MISCONFIGURED : OperationalDependencyState.UNAVAILABLE;
      return {
        dependencyType: OperationalDependencyType.REDIS,
        dependencyName: 'redis-primary',
        state,
        latencyMs: Date.now() - start,
        errorCode: 'REDIS_UNAVAILABLE',
        errorMessage: msg.slice(0, 500),
        evidence: redactSecrets({ error: msg }),
        checkedAt: new Date().toISOString(),
        isCritical: true,
      };
    }
  }

  async checkQueues(): Promise<DependencyHealthResult> {
    const start = Date.now();
    try {
      const depths = await this.queueService.getDepths();
      const totalFailed = depths.reduce((acc, d) => acc + d.failed, 0);
      const totalWaiting = depths.reduce((acc, d) => acc + d.waiting, 0);
      const hasPaused = depths.some((d) => d.paused);
      let state = OperationalDependencyState.HEALTHY;
      if (hasPaused) state = OperationalDependencyState.DEGRADED;
      if (totalFailed > 100) state = OperationalDependencyState.DEGRADED;
      if (totalFailed > 1000) state = OperationalDependencyState.UNAVAILABLE;
      return {
        dependencyType: OperationalDependencyType.QUEUE,
        dependencyName: 'bullmq-queues',
        state,
        latencyMs: Date.now() - start,
        evidence: {
          totalWaiting,
          totalFailed,
          hasPaused,
          queues: depths.map((d) => ({ name: d.name, waiting: d.waiting, failed: d.failed, paused: d.paused })),
        },
        checkedAt: new Date().toISOString(),
        isCritical: true,
      };
    } catch (e) {
      const msg = (e as Error).message;
      return {
        dependencyType: OperationalDependencyType.QUEUE,
        dependencyName: 'bullmq-queues',
        state: OperationalDependencyState.UNAVAILABLE,
        latencyMs: Date.now() - start,
        errorCode: 'QUEUE_CHECK_FAILED',
        errorMessage: msg.slice(0, 500),
        evidence: redactSecrets({ error: msg }),
        checkedAt: new Date().toISOString(),
        isCritical: true,
      };
    }
  }

  async checkConfiguration(): Promise<DependencyHealthResult> {
    try {
      // Missing credentials/config must NOT be reported healthy
      // The variables the API itself connects and decrypts with. (REDIS_URL was
      // checked here before, but the API reads REDIS_HOST/PORT/PASSWORD/TLS -
      // REDIS_URL is only used by the Python services - so a correctly
      // configured API was reported MISCONFIGURED and a broken one healthy.)
      const requiredEnv = ['DATABASE_URL', 'REDIS_HOST', 'ENCRYPTION_MASTER_KEY_BASE64', 'BLIND_INDEX_KEY_BASE64'];
      const missing: string[] = [];
      for (const key of requiredEnv) {
        const val = process.env[key];
        if (!val) missing.push(key);
      }
      // REDIS_HOST defaults to localhost in the env schema; in production that
      // is always a deployment mistake (Redis runs as a managed service).
      if (process.env.NODE_ENV === 'production' && ['localhost', '127.0.0.1', '::1'].includes((process.env.REDIS_HOST ?? '').trim())) {
        missing.push('REDIS_HOST (localhost in production)');
      }
      if (missing.length > 0) {
        return {
          dependencyType: OperationalDependencyType.CONFIGURATION,
          dependencyName: 'env-configuration',
          state: OperationalDependencyState.MISCONFIGURED,
          errorCode: 'MISSING_CONFIGURATION',
          errorMessage: `Missing required configuration: ${missing.join(', ')}`,
          evidence: { missingKeys: missing },
          checkedAt: new Date().toISOString(),
          isCritical: true,
        };
      }
      return {
        dependencyType: OperationalDependencyType.CONFIGURATION,
        dependencyName: 'env-configuration',
        state: OperationalDependencyState.HEALTHY,
        evidence: { checkedKeys: requiredEnv.length },
        checkedAt: new Date().toISOString(),
        isCritical: true,
      };
    } catch (e) {
      return {
        dependencyType: OperationalDependencyType.CONFIGURATION,
        dependencyName: 'env-configuration',
        state: OperationalDependencyState.UNKNOWN,
        errorCode: 'CONFIG_CHECK_FAILED',
        errorMessage: (e as Error).message.slice(0, 500),
        evidence: {},
        checkedAt: new Date().toISOString(),
        isCritical: true,
      };
    }
  }

  async checkSecurityControls(tenantId?: string | null): Promise<DependencyHealthResult> {
    try {
      // Check security policy exists for tenant, otherwise MISCONFIGURED
      if (tenantId) {
        const policy = await this.policyService.getTenantSecurityPolicy(tenantId);
        if (!policy) {
          return {
            dependencyType: OperationalDependencyType.SECURITY,
            dependencyName: `security-policy-${tenantId}`,
            state: OperationalDependencyState.MISCONFIGURED,
            errorCode: 'SECURITY_POLICY_MISSING',
            errorMessage: `Security policy not configured for tenant ${tenantId}`,
            evidence: { tenantId },
            checkedAt: new Date().toISOString(),
            isCritical: true,
          };
        }
      }
      // Check encryption key config
      const hasEncryptionKey = !!process.env['ENCRYPTION_KEY'] || !!process.env['MASTER_KEY'] || !!(this.config as any).encryptionMasterKeyBase64;
      if (!hasEncryptionKey) {
        return {
          dependencyType: OperationalDependencyType.SECURITY,
          dependencyName: 'security-encryption',
          state: OperationalDependencyState.MISCONFIGURED,
          errorCode: 'ENCRYPTION_KEY_MISSING',
          errorMessage: 'Encryption key not configured',
          evidence: {},
          checkedAt: new Date().toISOString(),
          isCritical: true,
        };
      }
      return {
        dependencyType: OperationalDependencyType.SECURITY,
        dependencyName: 'security-controls',
        state: OperationalDependencyState.HEALTHY,
        evidence: { tenantId: tenantId ?? 'platform' },
        checkedAt: new Date().toISOString(),
        isCritical: true,
      };
    } catch (e) {
      return {
        dependencyType: OperationalDependencyType.SECURITY,
        dependencyName: 'security-controls',
        state: OperationalDependencyState.UNKNOWN,
        errorCode: 'SECURITY_CHECK_FAILED',
