import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import {
  deterministicIncidentFingerprint,
  OperationalIncidentSeverity,
  redactSecrets,
} from './operations.types';

/**
 * Produces deterministic incident fingerprints from normalized incident attributes,
 * correlates repeated failures, increments occurrence metadata, and prevents duplicate
 * incident storms without hiding materially different failures.
 */

@Injectable()
export class IncidentDeduplicationService {
  private readonly logger = new Logger(IncidentDeduplicationService.name);

  constructor(private readonly prisma: PrismaService) {}

  generateFingerprint(params: {
    type: string;
    severity: OperationalIncidentSeverity | string;
    affectedComponent: string;
    affectedCapability?: string | null;
    tenantId?: string | null;
    scopeTarget?: string | null;
  }): string {
    return deterministicIncidentFingerprint({
      type: params.type,
      severity: params.severity as string,
      affectedComponent: params.affectedComponent,
      affectedCapability: params.affectedCapability ?? null,
      tenantId: params.tenantId ?? null,
      scopeTarget: params.scopeTarget ?? null,
    });
  }

  async findExistingIncident(params: {
    fingerprint: string;
    tenantId?: string | null;
  }): Promise<any | null> {
    const where: any = { fingerprint: params.fingerprint };
    if (params.tenantId !== undefined) {
      where.tenantId = params.tenantId;
    }
    return await (this.prisma as any).operationalIncident.findFirst({
      where,
      orderBy: { lastSeenAt: 'desc' },
    });
  }

  async deduplicateOrCreate(params: {
    tenantId?: string | null;
    type: string;
    severity: OperationalIncidentSeverity | string;
    title: string;
    summary: string;
    source: string;
    affectedComponent: string;
    affectedCapability?: string | null;
    scopeTarget?: string | null;
    evidence: Record<string, unknown>;
    correlationId?: string | null;
    requestId?: string | null;
    idempotencyKey: string;
    actorId?: string | null;
  }): Promise<{ incident: any; isDuplicate: boolean }> {
    const fingerprint = this.generateFingerprint({
      type: params.type,
      severity: params.severity,
      affectedComponent: params.affectedComponent,
      affectedCapability: params.affectedCapability ?? null,
      tenantId: params.tenantId ?? null,
      scopeTarget: params.scopeTarget ?? null,
    });

    const existing = await this.findExistingIncident({ fingerprint, tenantId: params.tenantId ?? null });

    if (existing) {
      // Check if existing is resolved/suppressed — if so, don't deduplicate, allow reopen via separate flow
      if (existing.state === 'RESOLVED' || existing.state === 'SUPPRESSED') {
        // Create new incident with same fingerprint but new occurrence
        // However we preserve fingerprint uniqueness per tenant+state? We use tenant+fingerprint unique,
        // so we cannot create duplicate with same fingerprint while old exists. We must handle by reopening or creating new with different idempotency.
        // For resolved incidents, we will create a new incident with same fingerprint but we need to allow it — so we will reopen logic elsewhere.
        // Here we increment occurrence if not resolved, else we return existing to be reopened by caller.
        if (existing.state === 'RESOLVED' || existing.state === 'SUPPRESSED') {
          // Caller should reopen; we return existing as duplicate false to signal need to reopen
          return { incident: existing, isDuplicate: false };
        }
      }

      // Increment occurrence metadata — deterministic, no hiding materially different failures because fingerprint includes component/capability/tenant/scopeTarget
      try {
        const updated = await (this.prisma as any).operationalIncident.update({
          where: { id: existing.id },
          data: {
            lastSeenAt: new Date(),
            occurrenceCount: { increment: 1 },
            evidence: redactSecrets({
              ...(existing.evidence as any),
              lastEvidence: redactSecrets(params.evidence),
              occurrenceCount: existing.occurrenceCount + 1,
            }) as any,
            correlationId: params.correlationId ?? existing.correlationId,
          },
        });

        // Record deduplication event
        try {
          await (this.prisma as any).operationalIncidentEvent.create({
            data: {
              tenantId: params.tenantId ?? null,
              incidentId: existing.id,
              eventType: 'DEDUPLICATED',
              reason: `Duplicate incident deduplicated, occurrence ${existing.occurrenceCount + 1}`,
              evidence: redactSecrets({ fingerprint, correlationId: params.correlationId }) as any,
              actorId: params.actorId ?? null,
              actorType: 'SYSTEM',
            },
          });
        } catch {}

        this.logger.log({
          event: 'operations.incident.deduplicated',
          fingerprint,
          incidentId: existing.id,
          occurrenceCount: existing.occurrenceCount + 1,
        });

        return { incident: updated, isDuplicate: true };
      } catch (e) {
        this.logger.warn(`Failed to deduplicate incident ${existing.id}: ${(e as Error).message}`);
        return { incident: existing, isDuplicate: true };
      }
    }

    // No existing — create new incident
    try {
      const incident = await (this.prisma as any).operationalIncident.create({
        data: {
          tenantId: params.tenantId ?? null,
          fingerprint,
          type: params.type,
          severity: params.severity as any,
          state: 'OPEN',
          title: params.title.slice(0, 255),
          summary: params.summary.slice(0, 1000),
          source: params.source,
          affectedComponent: params.affectedComponent,
          affectedCapability: params.affectedCapability ?? null,
          evidence: redactSecrets(params.evidence) as any,
          correlationId: params.correlationId ?? null,
          requestId: params.requestId ?? null,
          idempotencyKey: params.idempotencyKey,
          firstSeenAt: new Date(),
          lastSeenAt: new Date(),
          occurrenceCount: 1,
        },
      });

      // Create creation event
      try {
        await (this.prisma as any).operationalIncidentEvent.create({
          data: {
            tenantId: params.tenantId ?? null,
            incidentId: incident.id,
            eventType: 'CREATED',
            toState: 'OPEN',
            reason: params.summary.slice(0, 500),
            evidence: redactSecrets(params.evidence) as any,
            actorId: params.actorId ?? null,
            actorType: params.actorId ? 'USER' : 'SYSTEM',
          },
        });
      } catch {}

      return { incident, isDuplicate: false };
    } catch (e) {
      // Handle race condition: unique constraint violation means another process created same fingerprint concurrently
      const msg = (e as Error).message;
      if (msg.includes('Unique constraint') || msg.includes('idempotency_key') || msg.includes('fingerprint')) {
        const retryExisting = await this.findExistingIncident({ fingerprint, tenantId: params.tenantId ?? null });
        if (retryExisting) {
          return { incident: retryExisting, isDuplicate: true };
        }
      }
      throw e;
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OperationsPolicyService } from './operations-policy.service';
import { OperationalAuditService } from './operational-audit.service';
import { IncidentService } from './incident.service';
import { OperationalIncidentState, redactSecrets } from './operations.types';

/**
 * Applies explicit escalation policy based on incident severity, dependency criticality,
 * recurrence, age, and existing operator policy. Must integrate with existing notification
 * delivery infrastructure rather than implementing a second notification provider.
 */

@Injectable()
export class IncidentEscalationService {
  private readonly logger = new Logger(IncidentEscalationService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: OperationsPolicyService,
    private readonly auditService: OperationalAuditService,
    private readonly incidentService: IncidentService,
  ) {}

  async evaluateAndEscalate(params: {
    tenantId?: string | null;
    incidentId: string;
    triggeredBy?: string | null;
    correlationId?: string | null;
  }): Promise<any | null> {
    const { tenantId = null, incidentId, triggeredBy = null, correlationId = null } = params;

    const incident = await this.incidentService.getIncident(tenantId, incidentId);

    if (incident.state === OperationalIncidentState.RESOLVED || incident.state === OperationalIncidentState.SUPPRESSED) {
      return null; // Do not escalate resolved/suppressed
    }

    const rules = this.policyService.getEscalationRules();
    const rule = rules.find((r) => r.severity === incident.severity);
    if (!rule) return null;

    const now = new Date();
    const firstSeen = new Date(incident.firstSeenAt);
    const ageMinutes = (now.getTime() - firstSeen.getTime()) / 60000;

    const shouldEscalateByAge = ageMinutes >= rule.maxAgeMinutes;
    const shouldEscalateByOccurrence = incident.occurrenceCount >= rule.maxOccurrences;
    const shouldEscalate = shouldEscalateByAge || shouldEscalateByOccurrence;

    if (!shouldEscalate) {
      this.logger.debug({
        event: 'operations.escalation.not_required',
        incidentId,
        ageMinutes: Math.round(ageMinutes),
        occurrenceCount: incident.occurrenceCount,
        severity: incident.severity,
      });
      return null;
    }

    // Apply escalation — transition to ESCALATED if valid
    try {
      const escalated = await this.incidentService.transitionIncident({
        tenantId: tenantId ?? null,
        incidentId,
        toState: OperationalIncidentState.ESCALATED,
        actorId: triggeredBy ?? null,
        actorType: triggeredBy ? 'USER' : 'SYSTEM',
        reason: `Escalated by policy: severity ${incident.severity} age ${Math.round(ageMinutes)}min occurrences ${incident.occurrenceCount}`,
        evidence: redactSecrets({
          rule,
          ageMinutes: Math.round(ageMinutes),
          occurrenceCount: incident.occurrenceCount,
          escalateTo: rule.escalateTo,
        }),
        correlationId: correlationId ?? null,
      });

      // Integrate with existing notification delivery infrastructure (do not implement second provider)
      await this.sendEscalationNotification({
        tenantId: tenantId ?? null,
        incident: escalated,
        escalateTo: rule.escalateTo,
        correlationId: correlationId ?? null,
      });

      await this.auditService.record({
        tenantId: tenantId ?? null,
        eventType: 'ESCALATION_TRIGGERED' as any,
        actorId: triggeredBy ?? null,
        actorType: triggeredBy ? 'USER' : 'SYSTEM',
        targetType: 'INCIDENT',
        targetId: incidentId,
        evidence: redactSecrets({
          severity: incident.severity,
          ageMinutes: Math.round(ageMinutes),
          occurrenceCount: incident.occurrenceCount,
          escalateTo: rule.escalateTo,
        }),
        correlationId: correlationId ?? null,
      });

      return escalated;
    } catch (e) {
      this.logger.warn(`Escalation failed for incident ${incidentId}: ${(e as Error).message}`);
      return null;
    }
  }

  private async sendEscalationNotification(params: {
    tenantId: string | null;
    incident: any;
    escalateTo: string[];
    correlationId: string | null;
  }): Promise<void> {
    // Reuse existing notification infrastructure via Prisma notification table or queue
    // Do not implement second provider
    try {
      // Try to enqueue notification job if queue service available via Prisma fallback
      const title = `Incident escalated: ${params.incident.title}`;
      const body = `Incident ${params.incident.id} severity ${params.incident.severity} escalated to ${params.escalateTo.join(', ')}`;

      // If tenantId present, create in-app notification for operators
      if (params.tenantId) {
        // Find tenant operators/admins
        const operators = await this.prisma.user.findMany({
          where: {
            tenantId: params.tenantId,
            status: 'ACTIVE' as any,
          },
          take: 10,
          select: { id: true },
        });
        for (const op of operators) {
          try {
            await this.prisma.notification.create({
              data: {
                tenantId: params.tenantId,
                userId: op.id,
                channel: 'IN_APP' as any,
                type: 'INCIDENT_ESCALATION',
                title: title.slice(0, 160),
                body: body.slice(0, 1000),
                data: redactSecrets({
                  incidentId: params.incident.id,
                  severity: params.incident.severity,
                  fingerprint: params.incident.fingerprint,
                  correlationId: params.correlationId,
                }) as any,
              } as any,
            });
          } catch {}
        }
      } else {
        // Platform incident: log and audit, notification via existing system would be platform-wide
        this.logger.log({
          event: 'operations.incident.escalation_notification_platform',
          incidentId: params.incident.id,
          escalateTo: params.escalateTo,
        });
      }
    } catch (e) {
      this.logger.warn(`Failed to send escalation notification: ${(e as Error).message}`);
    }
  }

  async checkAllPendingEscalations(): Promise<number> {
    try {
      const now = new Date();
      // Find open incidents that may need escalation
      const incidents = await (this.prisma as any).operationalIncident.findMany({
        where: {
          state: { in: ['OPEN', 'ACKNOWLEDGED'] },
        },
        take: 100,
        orderBy: { firstSeenAt: 'asc' },
      });

      let escalatedCount = 0;
      for (const incident of incidents) {
        const result = await this.evaluateAndEscalate({
          tenantId: incident.tenantId ?? null,
          incidentId: incident.id,
          triggeredBy: null,
          correlationId: null,
        });
        if (result) escalatedCount++;
      }
      return escalatedCount;
    } catch (e) {
      this.logger.warn(`Failed to check pending escalations: ${(e as Error).message}`);
      return 0;
    }
  }
}

import { Injectable, Logger, BadRequestException, ForbiddenException, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OperationalAuditService } from './operational-audit.service';
import { IncidentDeduplicationService } from './incident-deduplication.service';
import {
  OperationalIncidentState,
  OperationalIncidentSeverity,
  INCIDENT_VALID_TRANSITIONS,
  isValidTransition,
  deterministicIdempotencyKey,
  redactSecrets,
} from './operations.types';


/**
 * Creates, updates, acknowledges, resolves, suppresses, and reopens operational incidents.
 * Must enforce explicit state transitions, tenant/platform scope, severity, evidence, timestamps,
 * ownership, and idempotent creation.
 */

@Injectable()
export class IncidentService {
  private readonly logger = new Logger(IncidentService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly auditService: OperationalAuditService,
    private readonly deduplicationService: IncidentDeduplicationService,
  ) {}

  async createIncident(params: {
    tenantId?: string | null;
    type: string;
    severity: OperationalIncidentSeverity | string;
    title: string;
    summary: string;
    source: string;
    affectedComponent: string;
    affectedCapability?: string | null;
    scopeTarget?: string | null;
    evidence: Record<string, unknown>;
    correlationId?: string | null;
    requestId?: string | null;
    actorId?: string | null;
    actorType?: string;
  }): Promise<any> {
    // Secret redaction enforced
    const evidence = redactSecrets(params.evidence);

    const idempotencyKey = deterministicIdempotencyKey({
      type: `incident:${params.type}`,
      tenantId: params.tenantId ?? null,
      fingerprint: this.deduplicationService.generateFingerprint({
        type: params.type,
        severity: params.severity,
        affectedComponent: params.affectedComponent,
        affectedCapability: params.affectedCapability ?? null,
        tenantId: params.tenantId ?? null,
        scopeTarget: params.scopeTarget ?? null,
      }),
      correlationId: params.correlationId ?? null,
      timestampBucket: new Date().toISOString().slice(0, 13), // hourly dedup bucket
    });

    // Check idempotency key first
    try {
      const existingByIdempotency = await (this.prisma as any).operationalIncident.findFirst({
        where: { tenantId: params.tenantId ?? null, idempotencyKey },
      });
      if (existingByIdempotency) {
        return existingByIdempotency;
      }
    } catch {}

    const { incident, isDuplicate } = await this.deduplicationService.deduplicateOrCreate({
      tenantId: params.tenantId ?? null,
      type: params.type,
      severity: params.severity,
      title: params.title,
      summary: params.summary,
      source: params.source,
      affectedComponent: params.affectedComponent,
      affectedCapability: params.affectedCapability ?? null,
      scopeTarget: params.scopeTarget ?? null,
      evidence,
      correlationId: params.correlationId ?? null,
      requestId: params.requestId ?? null,
      idempotencyKey,
      actorId: params.actorId ?? null,
    });

    const auditRef = await this.auditService.record({
      tenantId: params.tenantId ?? null,
      eventType: isDuplicate ? 'INCIDENT_DEDUPLICATED' : 'INCIDENT_CREATED',
      actorId: params.actorId ?? null,
      actorType: params.actorType ?? (params.actorId ? 'USER' : 'SYSTEM'),
      targetType: 'INCIDENT',
      targetId: incident.id,
      evidence: redactSecrets({
        fingerprint: incident.fingerprint,
        type: params.type,
        severity: params.severity,
        affectedComponent: params.affectedComponent,
        isDuplicate,
        correlationId: params.correlationId,
      }),
      correlationId: params.correlationId ?? null,
      requestId: params.requestId ?? null,
    });

    if (!isDuplicate) {
      try {
        await (this.prisma as any).operationalIncident.update({
          where: { id: incident.id },
          data: { auditReference: auditRef ?? undefined },
        });
      } catch {}
    }

    return incident;
  }

  async getIncident(tenantId: string | null, incidentId: string): Promise<any> {
    // Tenant isolation enforced
    const where: any = { id: incidentId };
    if (tenantId !== null) {
      where.tenantId = tenantId;
    } else {
      // Platform request: allow platform incidents (tenantId null) OR require platform RBAC elsewhere (controller)
      // Here we don't filter if tenantId null means platform scope, but controller must enforce RBAC
    }
    try {
      const incident = await (this.prisma as any).operationalIncident.findFirst({ where });
      if (!incident) throw new NotFoundException(`Incident ${incidentId} not found`);
      // Tenant isolation: if requesting tenantId is set, incident must belong to that tenant or be platform-wide readable only with platform RBAC
      if (tenantId !== null && incident.tenantId !== null && incident.tenantId !== tenantId) {
        throw new ForbiddenException('Tenant isolation violation');
      }
      return incident;
    } catch (e) {
      if (e instanceof NotFoundException || e instanceof ForbiddenException) throw e;
      throw new NotFoundException(`Incident ${incidentId} not found`);
    }
  }

  async listIncidents(params: {
    tenantId?: string | null;
    state?: string;
    severity?: string;
    type?: string;
    affectedComponent?: string;
    correlationId?: string;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId = null, state, severity, type, affectedComponent, correlationId, page = 1, limit = 20 } = params;
    const where: any = {};
    if (tenantId !== undefined) {
      if (tenantId === null) {
        // Platform query: controller enforces RBAC, we return platform + all? For platform visibility, allow all when tenantId null and platform RBAC passed
        // For safety, when tenantId null we return only platform incidents unless explicitly platform admin
        // Here we keep where empty to allow platform to see all, but tenant isolation is enforced in controller
      } else {
        where.tenantId = tenantId;
      }
    }
    if (state) where.state = state;
    if (severity) where.severity = severity;
    if (type) where.type = type;
    if (affectedComponent) where.affectedComponent = affectedComponent;
    if (correlationId) where.correlationId = correlationId;

    const [data, total] = await Promise.all([
      (this.prisma as any).operationalIncident.findMany({
        where,
        orderBy: { lastSeenAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).operationalIncident.count({ where }),
    ]);
    return { data, total, page, limit };
  }

  async transitionIncident(params: {
    tenantId: string | null;
    incidentId: string;
    toState: OperationalIncidentState;
    actorId?: string | null;
    actorType?: string;
    reason?: string | null;
    evidence?: Record<string, unknown>;
    correlationId?: string | null;
    requestId?: string | null;
  }): Promise<any> {
    const incident = await this.getIncident(params.tenantId, params.incidentId);

    const fromState = incident.state as OperationalIncidentState;
    const toState = params.toState;

    if (!isValidTransition(INCIDENT_VALID_TRANSITIONS, fromState, toState)) {
      throw new BadRequestException(`Invalid incident transition ${fromState} -> ${toState}`);
    }

    const now = new Date();
    const data: any = {
      state: toState,
      updatedAt: now,
    };

    // State-specific timestamp handling
    if (toState === OperationalIncidentState.ACKNOWLEDGED) {
      data.acknowledgedAt = now;
      data.acknowledgedBy = params.actorId ?? null;
    } else if (toState === OperationalIncidentState.ESCALATED) {
      data.escalatedAt = now;
      const history = (incident.escalationHistory as any[]) ?? [];
      history.push({
        timestamp: now.toISOString(),
        actorId: params.actorId ?? null,
        reason: params.reason ?? null,
        correlationId: params.correlationId ?? null,
      });
      data.escalationHistory = history;
    } else if (toState === OperationalIncidentState.RESOLVED) {
      data.resolvedAt = now;
      data.resolvedBy = params.actorId ?? null;
      data.resolutionNote = params.reason?.slice(0, 1000) ?? null;
    } else if (toState === OperationalIncidentState.SUPPRESSED) {
      data.suppressedAt = now;
      data.suppressedBy = params.actorId ?? null;
      data.suppressionReason = params.reason?.slice(0, 500) ?? null;
    } else if (toState === OperationalIncidentState.REOPENED) {
      data.reopenedAt = now;
      data.reopenedBy = params.actorId ?? null;
      data.reopenReason = params.reason?.slice(0, 500) ?? null;
    }

    const updated = await (this.prisma as any).operationalIncident.update({
      where: { id: incident.id },
      data,
    });

    // Record transition event
    try {
      await (this.prisma as any).operationalIncidentEvent.create({
        data: {
          tenantId: params.tenantId ?? null,
          incidentId: incident.id,
          eventType: 'STATE_TRANSITION',
          fromState: fromState as any,
          toState: toState as any,
          actorId: params.actorId ?? null,
          actorType: params.actorType ?? (params.actorId ? 'USER' : 'SYSTEM'),
          reason: params.reason?.slice(0, 1000) ?? null,
          evidence: redactSecrets(params.evidence ?? {}) as any,
        },
      });
    } catch {}

    const auditEventMap: Record<string, string> = {
      [OperationalIncidentState.ACKNOWLEDGED]: 'INCIDENT_ACKNOWLEDGED',
      [OperationalIncidentState.ESCALATED]: 'INCIDENT_ESCALATED',
      [OperationalIncidentState.MITIGATING]: 'INCIDENT_MITIGATING',
      [OperationalIncidentState.RESOLVED]: 'INCIDENT_RESOLVED',
      [OperationalIncidentState.SUPPRESSED]: 'INCIDENT_SUPPRESSED',
      [OperationalIncidentState.REOPENED]: 'INCIDENT_REOPENED',
    };

    await this.auditService.record({
      tenantId: params.tenantId ?? null,
      eventType: (auditEventMap[toState] ?? 'INCIDENT_CREATED') as any,
      actorId: params.actorId ?? null,
      actorType: params.actorType ?? (params.actorId ? 'USER' : 'SYSTEM'),
      targetType: 'INCIDENT',
      targetId: incident.id,
      evidence: redactSecrets({
        fromState,
        toState,
        reason: params.reason,
        correlationId: params.correlationId,
      }),
      correlationId: params.correlationId ?? null,
      requestId: params.requestId ?? null,
    });

    return updated;
  }

  async acknowledge(params: {
    tenantId: string | null;
    incidentId: string;
    actorId?: string | null;
    reason?: string | null;
    correlationId?: string | null;
    requestId?: string | null;
  }) {
    return this.transitionIncident({
      tenantId: params.tenantId,
      incidentId: params.incidentId,
      toState: OperationalIncidentState.ACKNOWLEDGED,
      actorId: params.actorId ?? null,
      reason: params.reason ?? null,
      correlationId: params.correlationId ?? null,
      requestId: params.requestId ?? null,
    });
  }

  async resolve(params: {
    tenantId: string | null;
    incidentId: string;
    actorId?: string | null;
    reason: string;
    correlationId?: string | null;
    requestId?: string | null;
  }) {
    if (!params.reason) throw new BadRequestException('Resolution reason required');
    return this.transitionIncident({
      tenantId: params.tenantId,
      incidentId: params.incidentId,
      toState: OperationalIncidentState.RESOLVED,
      actorId: params.actorId ?? null,
      reason: params.reason,
      correlationId: params.correlationId ?? null,
      requestId: params.requestId ?? null,
    });
  }

  async suppress(params: {
    tenantId: string | null;
    incidentId: string;
    actorId?: string | null;
    reason: string;
    suppressUntil?: Date | null;
    correlationId?: string | null;
    requestId?: string | null;
  }) {
    const incident = await this.getIncident(params.tenantId, params.incidentId);
    if (!isValidTransition(INCIDENT_VALID_TRANSITIONS, incident.state as any, OperationalIncidentState.SUPPRESSED)) {
      throw new BadRequestException(`Cannot suppress incident in state ${incident.state}`);
    }
    const updated = await (this.prisma as any).operationalIncident.update({
      where: { id: incident.id },
      data: {
        state: OperationalIncidentState.SUPPRESSED,
        suppressedAt: new Date(),
        suppressedBy: params.actorId ?? null,
        suppressionReason: params.reason.slice(0, 500),
        suppressUntil: params.suppressUntil ?? null,
      },
    });
    await this.auditService.record({
      tenantId: params.tenantId ?? null,
      eventType: 'INCIDENT_SUPPRESSED' as any,
      actorId: params.actorId ?? null,
      actorType: params.actorId ? 'USER' : 'SYSTEM',
      targetType: 'INCIDENT',
      targetId: incident.id,
      evidence: redactSecrets({ reason: params.reason, suppressUntil: params.suppressUntil }),
      correlationId: params.correlationId ?? null,
      requestId: params.requestId ?? null,
    });
    return updated;
  }

  async reopen(params: {
    tenantId: string | null;
    incidentId: string;
    actorId?: string | null;
    reason: string;
    correlationId?: string | null;
    requestId?: string | null;
  }) {
    const incident = await this.getIncident(params.tenantId, params.incidentId);
    if (!isValidTransition(INCIDENT_VALID_TRANSITIONS, incident.state as any, OperationalIncidentState.REOPENED)) {
      throw new BadRequestException(`Cannot reopen incident in state ${incident.state}`);
    }
    return this.transitionIncident({
      tenantId: params.tenantId,
      incidentId: params.incidentId,
      toState: OperationalIncidentState.REOPENED,
      actorId: params.actorId ?? null,
      reason: params.reason,
      correlationId: params.correlationId ?? null,
      requestId: params.requestId ?? null,
    });
  }

  async assignOperator(params: { tenantId: string | null; incidentId: string; operatorId: string; actorId?: string | null }) {
    const incident = await this.getIncident(params.tenantId, params.incidentId);
    const updated = await (this.prisma as any).operationalIncident.update({
      where: { id: incident.id },
      data: { assignedOperatorId: params.operatorId },
    });
    await this.auditService.record({
      tenantId: params.tenantId ?? null,
      eventType: 'INCIDENT_ACKNOWLEDGED' as any,
      actorId: params.actorId ?? null,
      actorType: 'USER',
      targetType: 'INCIDENT',
      targetId: incident.id,
      evidence: { assignedOperatorId: params.operatorId },
      correlationId: null,
    });
    return updated;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { QueueService } from '../queue/queue.service';
import { OperationalAuditService } from './operational-audit.service';
import { JobHealthResult, redactSecrets } from './operations.types';

/**
 * Tracks operational health of scheduled/background jobs, detects stale or repeatedly failing jobs,
 * records execution metadata, and exposes safe diagnostics without changing business truth.
 */

@Injectable()
export class JobHealthService {
  private readonly logger = new Logger(JobHealthService.name);

  private readonly STALE_JOB_MS = 10 * 60 * 1000; // 10 minutes without heartbeat is stale
  private readonly FAILING_THRESHOLD = 5; // 5 failures in a row is repeatedly failing

  constructor(
    private readonly prisma: PrismaService,
    private readonly queueService: QueueService,
    private readonly auditService: OperationalAuditService,
  ) {}

  async evaluate(): Promise<JobHealthResult[]> {
    const checkedAt = new Date().toISOString();
    const results: JobHealthResult[] = [];

    try {
      // Check BullMQ jobs for staleness and repeated failures
      const depths = await this.queueService.getDepths().catch(() => []);
      // For each queue, we would inspect jobs - but to avoid heavy scan, we use depth metadata
      // and supplement with known scheduled jobs from existing infrastructure

      // Known operational jobs from existing scheduler/queue infrastructure
      const knownJobs = [
        { jobName: 'reconciliation-scheduler', queueName: 'MAINTENANCE' },
        { jobName: 'risk-snapshot', queueName: 'RISK_CONTROL' },
        { jobName: 'market-snapshot', queueName: 'MARKET_SNAPSHOT' },
        { jobName: 'trade-signal', queueName: 'TRADE_SIGNAL' },
        { jobName: 'trade-execution', queueName: 'TRADE_EXECUTION' },
        { jobName: 'billing-cycle', queueName: 'BILLING' },
        { jobName: 'audit-flush', queueName: 'AUDIT' },
        { jobName: 'notification-delivery', queueName: 'NOTIFICATION' },
      ];

      for (const known of knownJobs) {
        const queueDepth = depths.find((d) => (d.name as string).toLowerCase().includes(known.queueName.toLowerCase()));
        const isStale = queueDepth ? (queueDepth.oldestWaitingAgeMs ?? 0) > this.STALE_JOB_MS : false;
        const failureCount = queueDepth?.failed ?? 0;
        const isRepeatedlyFailing = failureCount >= this.FAILING_THRESHOLD;

        results.push({
          jobName: known.jobName,
          queueName: known.queueName,
          lastRunAt: null, // Would be populated from job execution metadata if available
          lastSuccessAt: null,
          lastFailureAt: isRepeatedlyFailing ? checkedAt : null,
          failureCount,
          isStale,
          isRepeatedlyFailing,
          executionMetadata: redactSecrets({
            waiting: queueDepth?.waiting ?? 0,
            active: queueDepth?.active ?? 0,
            failed: failureCount,
            oldestWaitingAgeMs: queueDepth?.oldestWaitingAgeMs ?? null,
          }),
          checkedAt,
        });
      }

      // Check for stale reconciliation runs that never finished
      try {
        const staleThreshold = new Date(Date.now() - this.STALE_JOB_MS);
        const staleRecons = await (this.prisma as any).operationalReconciliationRun.findMany({
          where: {
            status: 'RUNNING',
            startTime: { lt: staleThreshold },
          },
          take: 20,
        });
        for (const stale of staleRecons) {
          results.push({
            jobName: `reconciliation-${stale.reconciliationType}`,
            queueName: 'RECONCILIATION',
            lastRunAt: stale.startTime?.toISOString() ?? null,
            lastSuccessAt: null,
            lastFailureAt: null,
            failureCount: 0,
            isStale: true,
            isRepeatedlyFailing: false,
            executionMetadata: redactSecrets({
              runId: stale.id,
              type: stale.reconciliationType,
              durationMs: stale.durationMs,
              status: stale.status,
            }),
            checkedAt,
          });
        }
      } catch {}

      await this.auditService.record({
        tenantId: null,
        eventType: 'JOB_HEALTH_CHECK' as any,
        actorId: null,
        actorType: 'SYSTEM',
        targetType: 'JOB',
        targetId: 'all',
        evidence: redactSecrets({
          jobCount: results.length,
          staleCount: results.filter((r) => r.isStale).length,
          failingCount: results.filter((r) => r.isRepeatedlyFailing).length,
        }),
        correlationId: null,
      });

      return results;
    } catch (e) {
      const msg = (e as Error).message;
      this.logger.error(`Job health evaluation failed: ${msg}`);
      await this.auditService.record({
        tenantId: null,
        eventType: 'JOB_HEALTH_CHECK' as any,
        actorId: null,
        actorType: 'SYSTEM',
        targetType: 'JOB',
        targetId: 'all',
        evidence: redactSecrets({ error: msg }),
        correlationId: null,
      });
      return [];
    }
  }

  async getStaleJobs(): Promise<JobHealthResult[]> {
    const all = await this.evaluate();
    return all.filter((j) => j.isStale);
  }

  async getFailingJobs(): Promise<JobHealthResult[]> {
    const all = await this.evaluate();
    return all.filter((j) => j.isRepeatedlyFailing);
  }
}

import { Injectable, Logger, BadRequestException, ServiceUnavailableException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { MaintenanceWindowService } from './maintenance-window.service';
import { OperationalAuditService } from './operational-audit.service';
import { OperationsPolicyService } from './operations-policy.service';
import { RedisService } from '../../infrastructure/redis/redis.service';
import {
  OperationalMaintenanceScope,
  OperationalMaintenanceState,
  activeMaintenanceWhere,
  redactSecrets,
} from './operations.types';

/**
 * Enforces operational maintenance state for supported scopes.
 * Must integrate with existing trading/live-gate/execution boundaries so maintenance mode
 * can restrict new actions without directly rewriting authoritative execution state.
 */

@Injectable()
export class MaintenanceModeService {
  private readonly logger = new Logger(MaintenanceModeService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly maintenanceWindowService: MaintenanceWindowService,
    private readonly auditService: OperationalAuditService,
    private readonly policyService: OperationsPolicyService,
    private readonly redis: RedisService,
  ) {}

  private getMaintenanceKey(scope: OperationalMaintenanceScope, scopeTarget?: string | null, tenantId?: string | null): string {
    const parts = ['ops', 'maintenance', scope.toLowerCase()];
    if (tenantId) parts.push(`tenant:${tenantId}`);
    if (scopeTarget) parts.push(`target:${scopeTarget}`);
    return parts.join(':');
  }

  /**
   * Whether an active maintenance window covers `scope` for this tenant (see
   * activeMaintenanceWhere). Redis is an advisory fast path set by
   * enterMaintenance; the database is authoritative. A database failure is
   * not swallowed: this used to return false on any error, so an outage of
   * the check silently lifted maintenance.
   */
  async isInMaintenance(params: {
    scope: OperationalMaintenanceScope;
    scopeTarget?: string | null;
    tenantId?: string | null;
  }): Promise<boolean> {
    const { scope, scopeTarget = null, tenantId = null } = params;

    try {
      const val = await this.redis.client.get(this.getMaintenanceKey(scope, scopeTarget, tenantId));
      if (val === 'ACTIVE') return true;
    } catch (err) {
      this.logger.warn(`Maintenance fast path unavailable, using the database: ${(err as Error).message}`);
    }

    const active = await this.prisma.operationalMaintenanceWindow.findFirst({
      where: activeMaintenanceWhere({ scope, scopeTarget, tenantId, now: new Date() }),
      select: { id: true },
    });
    return active !== null;
  }

  async enterMaintenance(params: {
    tenantId?: string | null;
    scope: OperationalMaintenanceScope;
    scopeTarget?: string | null;
    title: string;
    description?: string | null;
    scheduledStart?: Date;
    scheduledEnd?: Date;
    requestedBy?: string | null;
    correlationId?: string | null;
    isEmergency?: boolean;
  }): Promise<any> {
    const { tenantId = null, scope, scopeTarget = null, title, description = null, requestedBy = null, correlationId = null, isEmergency = false } = params;

    // Maintenance must be conflict-checked, time-bounded, auditable, authorization-controlled
    // Entering maintenance must not automatically cancel or mutate existing live orders unless existing authoritative service explicitly performs that operation

    const start = params.scheduledStart ?? new Date();
    const end = params.scheduledEnd ?? new Date(Date.now() + 60 * 60 * 1000); // default 1h

    // Create window via maintenance window service (which does conflict check)
    const window = await this.maintenanceWindowService.createWindow({
      tenantId: tenantId ?? null,
      scope,
      scopeTarget: scopeTarget ?? null,
      title,
      description,
      scheduledStart: start,
      scheduledEnd: end,
      requestedBy: requestedBy ?? null,
      correlationId: correlationId ?? null,
      isEmergency,
    });

    // Immediately transition to ACTIVE
    const activeWindow = await this.maintenanceWindowService.transitionWindow({
      tenantId: tenantId ?? null,
      windowId: window.id,
      toState: OperationalMaintenanceState.ACTIVE,
      actorId: requestedBy ?? null,
      reason: 'Enter maintenance mode',
      correlationId: correlationId ?? null,
    });

    // Set Redis flag for fast enforcement (does not rewrite execution state)
    try {
      const key = this.getMaintenanceKey(scope, scopeTarget, tenantId);
      await this.redis.client.set(key, 'ACTIVE', 'PX', end.getTime() - Date.now());
    } catch (e) {
      this.logger.warn(`Failed to set maintenance flag in Redis: ${(e as Error).message}`);
    }

    await this.auditService.record({
      tenantId: tenantId ?? null,
      eventType: 'MAINTENANCE_STARTED' as any,
      actorId: requestedBy ?? null,
      actorType: requestedBy ? 'USER' : 'SYSTEM',
      targetType: 'MAINTENANCE_WINDOW',
      targetId: activeWindow.id,
      evidence: redactSecrets({
        scope,
        scopeTarget,
        title,
        scheduledStart: start.toISOString(),
        scheduledEnd: end.toISOString(),
      }),
      correlationId: correlationId ?? null,
    });

    this.logger.log({
      event: 'operations.maintenance.entered',
      scope,
      scopeTarget,
      tenantId: tenantId ?? 'platform',
      windowId: activeWindow.id,
    });

    return activeWindow;
  }

  async exitMaintenance(params: {
    tenantId?: string | null;
    scope: OperationalMaintenanceScope;
    scopeTarget?: string | null;
    windowId?: string | null;
    requestedBy?: string | null;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId = null, scope, scopeTarget = null, windowId = null, requestedBy = null, correlationId = null } = params;

    let win: any;
    if (windowId) {
      win = await this.maintenanceWindowService.getWindow(tenantId, windowId);
    } else {
      // Find active window for scope
      try {
        const where: any = {
          state: OperationalMaintenanceState.ACTIVE as any,
          scope: scope as any,
        };
        if (scopeTarget) where.scopeTarget = scopeTarget;
        if (tenantId !== null) where.tenantId = tenantId;
        win = await (this.prisma as any).operationalMaintenanceWindow.findFirst({
          where,
          orderBy: { scheduledStart: 'desc' },
        });
      } catch {}
      if (!win) throw new BadRequestException(`No active maintenance window found for scope ${scope}`);
    }

    const completed = await this.maintenanceWindowService.transitionWindow({
      tenantId: tenantId ?? null,
      windowId: win.id,
      toState: OperationalMaintenanceState.COMPLETED,
      actorId: requestedBy ?? null,
      reason: 'Exit maintenance mode',
      correlationId: correlationId ?? null,
    });

    // Clear Redis flag
    try {
      const key = this.getMaintenanceKey(scope, scopeTarget, tenantId);
      await this.redis.client.del(key);
    } catch (e) {
      this.logger.warn(`Failed to clear maintenance flag in Redis: ${(e as Error).message}`);
    }

    await this.auditService.record({
      tenantId: tenantId ?? null,
      eventType: 'MAINTENANCE_COMPLETED' as any,
      actorId: requestedBy ?? null,
      actorType: requestedBy ? 'USER' : 'SYSTEM',
      targetType: 'MAINTENANCE_WINDOW',
      targetId: completed.id,
      evidence: redactSecrets({ scope, scopeTarget }),
      correlationId: correlationId ?? null,
    });

    return completed;
  }

  async enforceMaintenanceGate(params: {
    tenantId?: string | null;
    scope: OperationalMaintenanceScope;
    scopeTarget?: string | null;
    operation: string;
  }): Promise<void> {
    const inMaintenance = await this.isInMaintenance({
      scope: params.scope,
      scopeTarget: params.scopeTarget ?? null,
      tenantId: params.tenantId ?? null,
    });
    if (inMaintenance) {
      // Restricts new actions only; running executions are left to their own
      // state machines. 503: the operation is temporarily unavailable, the
      // request itself is fine.
      throw new ServiceUnavailableException(
        `Operation ${params.operation} blocked: maintenance active for ${params.scope}${params.scopeTarget ? `:${params.scopeTarget}` : ''}`,
      );
    }
  }
}

import { Injectable, Logger, BadRequestException, ForbiddenException, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OperationalAuditService } from './operational-audit.service';
import { OperationsPolicyService } from './operations-policy.service';
import {
  OperationalMaintenanceState,
  OperationalMaintenanceScope,
  MAINTENANCE_VALID_TRANSITIONS,
  isValidTransition,
  deterministicIdempotencyKey,
  activeMaintenanceWhere,
  redactSecrets,
} from './operations.types';


/**
 * Creates, validates, schedules, updates, and closes maintenance windows with
 * platform/tenant/venue/service scope, UTC-safe time handling, conflict detection,
 * authorization, and audit history.
 */

/** Customer-safe view of the maintenance currently affecting a tenant. */
export interface CustomerMaintenanceNotice {
  active: boolean;
  title: string | null;
  message: string | null;
  scope: string | null;
  scopeTarget: string | null;
  isEmergency: boolean;
  startedAt: string | null;
  endsAt: string | null;
  /**
   * True when an active window covers trading for this tenant (PLATFORM,
   * this TENANT, or TRADING_CAPABILITY - see activeMaintenanceWhere). The API
   * then rejects copy subscribe/resume with 503; the web disables copying.
   */
  blocksTrading: boolean;
}

@Injectable()
export class MaintenanceWindowService {
  private readonly logger = new Logger(MaintenanceWindowService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly auditService: OperationalAuditService,
    private readonly policyService: OperationsPolicyService,
  ) {}

  private ensureUtc(date: Date | string): Date {
    const d = typeof date === 'string' ? new Date(date) : date;
    if (isNaN(d.getTime())) throw new BadRequestException(`Invalid date: ${date}`);
    return d;
  }

  private async checkConflicts(params: {
    tenantId?: string | null;
    scope: OperationalMaintenanceScope;
    scopeTarget?: string | null;
    scheduledStart: Date;
    scheduledEnd: Date;
    excludeId?: string;
  }): Promise<void> {
    // Conflict detection: overlapping windows for same scope/target
    const where: any = {
      state: { in: [OperationalMaintenanceState.SCHEDULED, OperationalMaintenanceState.ACTIVE] },
      scope: params.scope,
      scheduledStart: { lt: params.scheduledEnd },
      scheduledEnd: { gt: params.scheduledStart },
    };
    if (params.scopeTarget) {
      where.scopeTarget = params.scopeTarget;
    }
    if (params.tenantId !== undefined) {
      where.tenantId = params.tenantId;
    }
    if (params.excludeId) {
      where.id = { not: params.excludeId };
    }

    try {
      const conflicting = await (this.prisma as any).operationalMaintenanceWindow.findFirst({ where });
      if (conflicting) {
        throw new BadRequestException(
          `Maintenance conflict: existing window ${conflicting.id} (${conflicting.title}) overlaps with requested time`,
        );
      }
    } catch (e) {
      if (e instanceof BadRequestException) throw e;
      // If table not exists yet, no conflict
    }
  }

  async createWindow(params: {
    tenantId?: string | null;
    scope: OperationalMaintenanceScope;
    scopeTarget?: string | null;
    title: string;
    description?: string | null;
    scheduledStart: Date | string;
    scheduledEnd: Date | string;
    requestedBy?: string | null;
    correlationId?: string | null;
    isEmergency?: boolean;
  }): Promise<any> {
    const start = this.ensureUtc(params.scheduledStart);
    const end = this.ensureUtc(params.scheduledEnd);

    if (start >= end) throw new BadRequestException('scheduledStart must be before scheduledEnd');
    if (start < new Date(Date.now() - 60000)) {
      // Allow slight past for emergency but not far past
      if (!params.isEmergency) throw new BadRequestException('scheduledStart cannot be in the past');
    }

    const durationHours = (end.getTime() - start.getTime()) / (1000 * 60 * 60);
    const restrictions = this.policyService.getMaintenanceRestrictions();
    const restriction = restrictions.find((r) => r.scope === params.scope);
    if (restriction && durationHours > restriction.maxDurationHours && !params.isEmergency) {
      throw new BadRequestException(`Maintenance window exceeds max duration ${restriction.maxDurationHours}h for scope ${params.scope}`);
    }

    // Authorization check: platform scopes require platform role (enforced in controller via RBAC, but also here)
    if (restriction?.requiresPlatformRole && params.tenantId !== null && params.scope === OperationalMaintenanceScope.PLATFORM) {
      throw new ForbiddenException('Platform maintenance requires platform role');
    }

    await this.checkConflicts({
      tenantId: params.tenantId ?? null,
      scope: params.scope,
      scopeTarget: params.scopeTarget ?? null,
      scheduledStart: start,
      scheduledEnd: end,
    });

    const idempotencyKey = deterministicIdempotencyKey({
      type: `maintenance:${params.scope}`,
      tenantId: params.tenantId ?? null,
      scope: params.scopeTarget ?? params.scope,
      correlationId: params.correlationId ?? null,
      timestampBucket: start.toISOString(),
    });

    // Idempotency: check existing by key
    try {
      const existing = await (this.prisma as any).operationalMaintenanceWindow.findFirst({
        where: { tenantId: params.tenantId ?? null, idempotencyKey },
      });
      if (existing) return existing;
    } catch {}

    const created = await (this.prisma as any).operationalMaintenanceWindow.create({
      data: {
        tenantId: params.tenantId ?? null,
        scope: params.scope as any,
        scopeTarget: params.scopeTarget ?? null,
        state: OperationalMaintenanceState.SCHEDULED as any,
        title: params.title.slice(0, 255),
        description: params.description?.slice(0, 2000) ?? null,
        scheduledStart: start,
        scheduledEnd: end,
        requestedBy: params.requestedBy ?? null,
        isEmergency: params.isEmergency ?? false,
        conflictChecked: true,
        idempotencyKey,
        correlationId: params.correlationId ?? null,
        metadata: redactSecrets({ scope: params.scope, scopeTarget: params.scopeTarget }) as any,
      },
    });

    await this.auditService.record({
      tenantId: params.tenantId ?? null,
      eventType: 'MAINTENANCE_CREATED' as any,
      actorId: params.requestedBy ?? null,
      actorType: params.requestedBy ? 'USER' : 'SYSTEM',
      targetType: 'MAINTENANCE_WINDOW',
      targetId: created.id,
      evidence: redactSecrets({
        scope: params.scope,
        scopeTarget: params.scopeTarget,
        scheduledStart: start.toISOString(),
        scheduledEnd: end.toISOString(),
        title: params.title,
      }),
      correlationId: params.correlationId ?? null,
    });

    return created;
  }

  /**
   * The maintenance a signed-in customer should be told about: the ACTIVE
   * window covering now that applies to their tenant or to the whole platform
   * (the one ending last, if several overlap). Only banner fields leave this
   * method: no operator identities, metadata or audit references. Database
   * errors propagate; the caller must not read "no maintenance" from a failure.
   */
  async getCurrentForTenant(tenantId: string): Promise<CustomerMaintenanceNotice> {
    const now = new Date();
    const select = {
      title: true,
      description: true,
      scope: true,
      scopeTarget: true,
      isEmergency: true,
      scheduledStart: true,
      scheduledEnd: true,
    } as const;
    // A window that stops trading is reported first, so a concurrent billing
    // or venue notice cannot hide it.
    const blocking = await this.prisma.operationalMaintenanceWindow.findFirst({
      where: activeMaintenanceWhere({ scope: OperationalMaintenanceScope.TRADING_CAPABILITY, tenantId, now }),
      orderBy: { scheduledEnd: 'desc' },
      select,
    });
    const window =
      blocking ??
      (await this.prisma.operationalMaintenanceWindow.findFirst({
        where: {
          state: 'ACTIVE',
          scheduledStart: { lte: now },
          scheduledEnd: { gte: now },
          OR: [{ tenantId }, { tenantId: null }],
        },
        orderBy: { scheduledEnd: 'desc' },
        select,
      }));
    if (!window) {
      return {
        active: false,
        title: null,
        message: null,
        scope: null,
        scopeTarget: null,
        isEmergency: false,
        startedAt: null,
        endsAt: null,
        blocksTrading: false,
      };
    }
    return {
      active: true,
      title: window.title,
      message: window.description ?? window.title,
      scope: window.scope,
      scopeTarget: window.scopeTarget,
      isEmergency: window.isEmergency,
      startedAt: window.scheduledStart.toISOString(),
      endsAt: window.scheduledEnd.toISOString(),
      blocksTrading: blocking !== null,
    };
  }

  async getWindow(tenantId: string | null, windowId: string): Promise<any> {
    const where: any = { id: windowId };
    if (tenantId !== null) {
      where.tenantId = tenantId;
    }
    try {
      const win = await (this.prisma as any).operationalMaintenanceWindow.findFirst({ where });
      if (!win) throw new NotFoundException(`Maintenance window ${windowId} not found`);
      if (tenantId !== null && win.tenantId !== null && win.tenantId !== tenantId) {
        throw new ForbiddenException('Tenant isolation violation');
      }
      return win;
    } catch (e) {
      if (e instanceof NotFoundException || e instanceof ForbiddenException || e instanceof BadRequestException) throw e;
      throw new NotFoundException(`Maintenance window ${windowId} not found`);
    }
  }

  async listWindows(params: {
    tenantId?: string | null;
    scope?: string;
    state?: string;
    from?: Date;
    to?: Date;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId = null, scope, state, from, to, page = 1, limit = 20 } = params;
    const where: any = {};
    if (tenantId !== undefined && tenantId !== null) where.tenantId = tenantId;
    if (scope) where.scope = scope;
    if (state) where.state = state;
    if (from || to) {
      where.scheduledStart = {};
      if (from) where.scheduledStart.gte = from;
      if (to) where.scheduledStart.lte = to;
    }

    const [data, total] = await Promise.all([
      (this.prisma as any).operationalMaintenanceWindow.findMany({
        where,
        orderBy: { scheduledStart: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).operationalMaintenanceWindow.count({ where }),
    ]);
    return { data, total, page, limit };
  }

  async transitionWindow(params: {
    tenantId: string | null;
    windowId: string;
    toState: OperationalMaintenanceState;
    actorId?: string | null;
    reason?: string | null;
    correlationId?: string | null;
  }): Promise<any> {
    const win = await this.getWindow(params.tenantId, params.windowId);
    const fromState = win.state as OperationalMaintenanceState;
    if (!isValidTransition(MAINTENANCE_VALID_TRANSITIONS, fromState, params.toState)) {
      throw new BadRequestException(`Invalid maintenance transition ${fromState} -> ${params.toState}`);
    }

    const data: any = { state: params.toState };
    const now = new Date();
    if (params.toState === OperationalMaintenanceState.ACTIVE) {
      data.actualStart = now;
    } else if (params.toState === OperationalMaintenanceState.COMPLETED) {
      data.actualEnd = now;
    } else if (params.toState === OperationalMaintenanceState.CANCELLED) {
      data.cancelledBy = params.actorId ?? null;
      data.cancellationReason = params.reason?.slice(0, 500) ?? null;
    }

    const updated = await (this.prisma as any).operationalMaintenanceWindow.update({
      where: { id: win.id },
      data,
    });

    const auditMap: Record<string, string> = {
      [OperationalMaintenanceState.ACTIVE]: 'MAINTENANCE_STARTED',
      [OperationalMaintenanceState.COMPLETED]: 'MAINTENANCE_COMPLETED',
      [OperationalMaintenanceState.CANCELLED]: 'MAINTENANCE_CANCELLED',
    };

    await this.auditService.record({
      tenantId: params.tenantId ?? null,
      eventType: (auditMap[params.toState] ?? 'MAINTENANCE_UPDATED') as any,
      actorId: params.actorId ?? null,
      actorType: params.actorId ? 'USER' : 'SYSTEM',
      targetType: 'MAINTENANCE_WINDOW',
      targetId: win.id,
      evidence: redactSecrets({ fromState, toState: params.toState, reason: params.reason }),
      correlationId: params.correlationId ?? null,
    });

    return updated;
  }

  async cancelWindow(params: {
    tenantId: string | null;
    windowId: string;
    actorId?: string | null;
    reason: string;
    correlationId?: string | null;
  }) {
    return this.transitionWindow({
      tenantId: params.tenantId,
      windowId: params.windowId,
      toState: OperationalMaintenanceState.CANCELLED,
      actorId: params.actorId ?? null,
      reason: params.reason,
      correlationId: params.correlationId ?? null,
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OperationalAuditEventType, redactSecrets } from './operations.types';

/**
 * Produces immutable operational audit records for readiness checks, dependency transitions,
 * incidents, escalations, maintenance changes, reconciliation runs, recovery actions,
 * and operator actions. Never store secrets or sensitive credential material.
 * Immutable: no update or delete methods exposed.
 */

@Injectable()
export class OperationalAuditService {
  private readonly logger = new Logger(OperationalAuditService.name);

  constructor(private readonly prisma: PrismaService) {}

  async record(params: {
    tenantId: string | null;
    eventType: OperationalAuditEventType | string;
    actorId: string | null;
    actorType: string;
    targetType?: string | null;
    targetId?: string | null;
    evidence: Record<string, unknown>;
    correlationId?: string | null;
    requestId?: string | null;
  }): Promise<string | null> {
    const sanitizedEvidence = redactSecrets(params.evidence);

    try {
      const record = await (this.prisma as any).operationalAuditLog.create({
        data: {
          tenantId: params.tenantId ?? null,
          eventType: params.eventType as any,
          actorId: params.actorId ?? null,
          actorType: params.actorType,
          targetType: params.targetType ?? null,
          targetId: params.targetId ?? null,
          evidence: sanitizedEvidence as any,
          correlationId: params.correlationId ?? null,
          requestId: params.requestId ?? null,
        },
      });
      return record.id;
    } catch (e) {
      this.logger.warn(`Failed to write operational audit log: ${(e as Error).message}`);
      // Fallback to general audit log if operational table not available
      try {
        await this.prisma.auditLog.create({
          data: {
            tenantId: params.tenantId ?? null,
            actorType: (params.actorType as any) ?? 'SYSTEM',
            actorId: params.actorId ?? null,
            action: `OPERATIONAL_${params.eventType}`,
            outcome: 'SUCCESS' as any,
            resourceType: params.targetType ?? null,
            resourceId: params.targetId ?? null,
            description: `Operational audit ${params.eventType}`,
            metadata: sanitizedEvidence as any,
            requestId: params.requestId ?? null,
            correlationId: params.correlationId ?? null,
          } as any,
        });
      } catch {}
      return null;
    }
  }

  async list(params: {
    tenantId?: string | null;
    eventType?: string;
    targetType?: string;
    targetId?: string;
    correlationId?: string;
    from?: Date;
    to?: Date;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId, eventType, targetType, targetId, correlationId, from, to, page = 1, limit = 20 } = params;
    const where: any = {};
    if (tenantId !== undefined) {
      where.tenantId = tenantId;
    }
    if (eventType) where.eventType = eventType;
    if (targetType) where.targetType = targetType;
    if (targetId) where.targetId = targetId;
    if (correlationId) where.correlationId = correlationId;
    if (from || to) {
      where.createdAt = {};
      if (from) where.createdAt.gte = from;
      if (to) where.createdAt.lte = to;
    }

    const [data, total] = await Promise.all([
      (this.prisma as any).operationalAuditLog.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).operationalAuditLog.count({ where }),
    ]);
    return { data, total, page, limit };
  }

  async getByCorrelationId(correlationId: string, tenantId?: string | null): Promise<any[]> {
    const where: any = { correlationId };
    if (tenantId !== undefined) where.tenantId = tenantId;
    return await (this.prisma as any).operationalAuditLog.findMany({
      where,
      orderBy: { createdAt: 'asc' },
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OperationalMetrics, redactSecrets } from './operations.types';

/**
 * Calculates deterministic operational metrics from actual observations:
 * availability windows, incident counts, MTTA, MTTR, reconciliation success/failure,
 * queue backlog, stale job counts, dependency health, recovery success, and operational action outcomes.
 * No subjective scoring or fabricated observations.
 */

@Injectable()
export class OperationalMetricsService {
  private readonly logger = new Logger(OperationalMetricsService.name);

  constructor(private readonly prisma: PrismaService) {}

  async calculateMetrics(params: {
    tenantId?: string | null;
    from: Date;
    to: Date;
  }): Promise<OperationalMetrics> {
    const { tenantId = null, from, to } = params;

    const periodStart = from.toISOString();
    const periodEnd = to.toISOString();
    const methodology = 'Deterministic calculation from actual observations: count of persisted records, no synthetic data, no subjective scoring. MTTA = avg(firstSeen->acknowledged), MTTR = avg(firstSeen->resolved). Availability = (total minutes - downtime minutes)/total minutes where downtime = sum of active maintenance windows + degradation DISABLED periods.';

    let incidentCount = 0;
    const incidentsBySeverity: Record<string, number> = { INFO: 0, WARNING: 0, ERROR: 0, CRITICAL: 0 };
    let mttrMinutes: number | null = null;
    let mttaMinutes: number | null = null;

    let reconciliationSuccess = 0;
    let reconciliationFailure = 0;

    let queueBacklogMax = 0;
    let staleJobCount = 0;

    let dependencyHealthy = 0;
    let dependencyDegraded = 0;
    let dependencyUnavailable = 0;

    let recoverySuccess = 0;
    let recoveryFailure = 0;

    let operatorActionCount = 0;
    let operatorActionSuccess = 0;

    let availabilityPercent: number | null = null;

    let observationCount = 0;

    try {
      // Incidents
      const whereIncident: any = {
        createdAt: { gte: from, lte: to },
      };
      if (tenantId !== null) whereIncident.tenantId = tenantId;

      const incidents = await (this.prisma as any).operationalIncident.findMany({
        where: whereIncident,
        select: { severity: true, firstSeenAt: true, acknowledgedAt: true, resolvedAt: true },
      });

      incidentCount = incidents.length;
      observationCount += incidents.length;

      for (const inc of incidents) {
        const sev = (inc.severity as string) ?? 'INFO';
        incidentsBySeverity[sev] = (incidentsBySeverity[sev] ?? 0) + 1;
      }

      // MTTA and MTTR deterministic from actual timestamps
      const acknowledged = incidents.filter((i: any) => i.acknowledgedAt && i.firstSeenAt);
      if (acknowledged.length > 0) {
        const totalMtta = acknowledged.reduce((acc: number, i: any) => {
          return acc + (new Date(i.acknowledgedAt).getTime() - new Date(i.firstSeenAt).getTime()) / 60000;
        }, 0);
        mttaMinutes = totalMtta / acknowledged.length;
      }

      const resolved = incidents.filter((i: any) => i.resolvedAt && i.firstSeenAt);
      if (resolved.length > 0) {
        const totalMttr = resolved.reduce((acc: number, i: any) => {
          return acc + (new Date(i.resolvedAt).getTime() - new Date(i.firstSeenAt).getTime()) / 60000;
        }, 0);
        mttrMinutes = totalMttr / resolved.length;
      }

      // Reconciliation
      const whereRecon: any = {
        createdAt: { gte: from, lte: to },
      };
      if (tenantId !== null) whereRecon.tenantId = tenantId;

      const reconRuns = await (this.prisma as any).operationalReconciliationRun.findMany({
        where: whereRecon,
        select: { status: true },
      });

      reconciliationSuccess = reconRuns.filter((r: any) => r.status === 'SUCCEEDED').length;
      reconciliationFailure = reconRuns.filter((r: any) => r.status === 'FAILED').length;
      observationCount += reconRuns.length;

      // Dependency checks
      const whereDep: any = {
        checkedAt: { gte: from, lte: to },
      };
      if (tenantId !== null) whereDep.tenantId = tenantId;

      const depChecks = await (this.prisma as any).operationalDependencyCheck.findMany({
        where: whereDep,
        select: { state: true },
      });

      dependencyHealthy = depChecks.filter((d: any) => d.state === 'HEALTHY').length;
      dependencyDegraded = depChecks.filter((d: any) => d.state === 'DEGRADED').length;
      dependencyUnavailable = depChecks.filter((d: any) => d.state === 'UNAVAILABLE' || d.state === 'MISCONFIGURED').length;
      observationCount += depChecks.length;

      // Recovery runs
      const whereRecovery: any = {
        createdAt: { gte: from, lte: to },
      };
      if (tenantId !== null) whereRecovery.tenantId = tenantId;

      const recoveryRuns = await (this.prisma as any).operationalRecoveryRun.findMany({
        where: whereRecovery,
        select: { state: true },
      });

      recoverySuccess = recoveryRuns.filter((r: any) => r.state === 'SUCCEEDED').length;
      recoveryFailure = recoveryRuns.filter((r: any) => r.state === 'FAILED').length;
      observationCount += recoveryRuns.length;

      // Operator actions
      const whereAction: any = {
        createdAt: { gte: from, lte: to },
      };
      if (tenantId !== null) whereAction.tenantId = tenantId;

      const actions = await (this.prisma as any).operationalAction.findMany({
        where: whereAction,
        select: { status: true },
      });

      operatorActionCount = actions.length;
      operatorActionSuccess = actions.filter((a: any) => a.status === 'SUCCEEDED').length;
      observationCount += actions.length;

      // Availability — deterministic from maintenance windows and degradations
      const totalMinutes = (to.getTime() - from.getTime()) / 60000;
      let downtimeMinutes = 0;

      const maintenanceWindows = await (this.prisma as any).operationalMaintenanceWindow.findMany({
        where: {
          tenantId: tenantId ?? undefined,
          state: { in: ['ACTIVE', 'COMPLETED'] as any },
          scheduledStart: { lte: to },
          scheduledEnd: { gte: from },
        },
        select: { scheduledStart: true, scheduledEnd: true, actualStart: true, actualEnd: true },
      });

      for (const mw of maintenanceWindows) {
        const mwStart = mw.actualStart ? new Date(mw.actualStart) : new Date(mw.scheduledStart);
        const mwEnd = mw.actualEnd ? new Date(mw.actualEnd) : new Date(mw.scheduledEnd);
        const overlapStart = mwStart < from ? from : mwStart;
        const overlapEnd = mwEnd > to ? to : mwEnd;
        if (overlapEnd > overlapStart) {
          downtimeMinutes += (overlapEnd.getTime() - overlapStart.getTime()) / 60000;
        }
      }

      const degradations = await (this.prisma as any).operationalServiceDegradation.findMany({
        where: {
          tenantId: tenantId ?? undefined,
          level: 'DISABLED' as any,
          startsAt: { lte: to },
          OR: [{ endsAt: null }, { endsAt: { gte: from } }],
        },
        select: { startsAt: true, endsAt: true },
      });

      for (const deg of degradations) {
        const degStart = new Date(deg.startsAt);
        const degEnd = deg.endsAt ? new Date(deg.endsAt) : to;
        const overlapStart = degStart < from ? from : degStart;
        const overlapEnd = degEnd > to ? to : degEnd;
        if (overlapEnd > overlapStart) {
          downtimeMinutes += (overlapEnd.getTime() - overlapStart.getTime()) / 60000;
        }
      }

      if (totalMinutes > 0) {
        availabilityPercent = Math.max(0, Math.min(100, ((totalMinutes - downtimeMinutes) / totalMinutes) * 100));
      }

      // Queue backlog max — would come from queue health history if persisted, fallback to 0 for now
      queueBacklogMax = 0;
      staleJobCount = 0;

    } catch (e) {
      // Zeros here would be reported as measured observations (see methodology); a failed read is an error.
      this.logger.warn(`Failed to calculate metrics: ${(e as Error).message}`);
      throw e;
    }

    const metrics: OperationalMetrics = {
      periodStart,
      periodEnd,
      tenantId: tenantId ?? null,
      availabilityPercent,
      incidentCount,
      incidentsBySeverity,
      mttrMinutes,
      mttaMinutes,
      reconciliationSuccess,
      reconciliationFailure,
      queueBacklogMax,
      staleJobCount,
      dependencyHealthy,
      dependencyDegraded,
      dependencyUnavailable,
      recoverySuccess,
      recoveryFailure,
      operatorActionCount,
      operatorActionSuccess,
      observationCount,
      methodology,
      calculatedAt: new Date().toISOString(),
    };

    return redactSecrets(metrics) as OperationalMetrics;
  }

  async getCurrentMetrics(tenantId?: string | null): Promise<OperationalMetrics> {
    const now = new Date();
    const from = new Date(now.getTime() - 24 * 60 * 60 * 1000); // last 24h
    return this.calculateMetrics({ tenantId: tenantId ?? null, from, to: now });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AppConfigService } from '../../config/app-config.service';
import { OperationalDependencyType, OperationalIncidentSeverity, OperationalMaintenanceScope, OperationalDegradationLevel, OperationalReconciliationType } from './operations.types';

/**
 * Central operational policy resolver for readiness requirements, critical dependencies,
 * escalation rules, maintenance restrictions, recovery permissions, and platform-vs-tenant scope.
 * Reuses existing configuration and security policy sources instead of inventing duplicate storage.
 */

export interface ReadinessPolicy {
  requiredDependencies: OperationalDependencyType[];
  criticalDependencies: OperationalDependencyType[];
  failClosedOn: OperationalDependencyType[];
  allowedDegraded: OperationalDependencyType[];
}

export interface EscalationRule {
  severity: OperationalIncidentSeverity;
  maxAgeMinutes: number;
  maxOccurrences: number;
  escalateTo: string[]; // role or channel identifiers
  requiresAcknowledgement: boolean;
}

export interface MaintenanceRestriction {
  scope: OperationalMaintenanceScope;
  requiresPlatformRole: boolean;
  requiresTenantOwnership: boolean;
  maxDurationHours: number;
  disallowedScopesDuringLiveTrading: OperationalMaintenanceScope[];
  requiresApprovalForEmergency: boolean;
}

export interface RecoveryPermission {
  requiresPlatformRole: boolean;
  requiresExplicitApproval: boolean;
  allowedRecoveryTypes: string[];
  forbiddenBypasses: string[]; // risk, compliance, live-gate, etc
}

@Injectable()
export class OperationsPolicyService {
  private readonly logger = new Logger(OperationsPolicyService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly config: AppConfigService,
  ) {}

  // Configuration precedence explicit and auditable: env > tenant setting > default

  getReadinessPolicy(tenantId?: string | null): ReadinessPolicy {
    // Reuse existing config sources; do not invent duplicate storage
    const required: OperationalDependencyType[] = [
      OperationalDependencyType.DATABASE,
      OperationalDependencyType.REDIS,
      OperationalDependencyType.QUEUE,
      OperationalDependencyType.CONFIGURATION,
      OperationalDependencyType.SECURITY,
    ];

    const critical: OperationalDependencyType[] = [
      OperationalDependencyType.DATABASE,
      OperationalDependencyType.REDIS,
      OperationalDependencyType.QUEUE,
      OperationalDependencyType.SECURITY,
      OperationalDependencyType.DISTRIBUTED_LOCK,
      OperationalDependencyType.DURABLE_STORE,
    ];

    const failClosed: OperationalDependencyType[] = [
      OperationalDependencyType.DATABASE,
      OperationalDependencyType.REDIS,
      OperationalDependencyType.SECURITY,
      OperationalDependencyType.LIVE_GATE,
      OperationalDependencyType.CREDENTIAL_SOURCE,
      OperationalDependencyType.DISTRIBUTED_LOCK,
    ];

    // Non-critical degraded allowed: e.g., notifications can be degraded but platform still READY
    const allowedDegraded: OperationalDependencyType[] = [
      OperationalDependencyType.NOTIFICATION,
      OperationalDependencyType.OBSERVABILITY,
      OperationalDependencyType.RESEARCH,
      OperationalDependencyType.MARKET_DATA,
    ];

    this.logger.debug({
      event: 'operations.policy.readiness_resolved',
      tenantId: tenantId ?? 'platform',
      required: required.length,
      critical: critical.length,
    });

    return {
      requiredDependencies: required,
      criticalDependencies: critical,
      failClosedOn: failClosed,
      allowedDegraded,
    };
  }

  getEscalationRules(): EscalationRule[] {
    // Policy-driven, explicit thresholds from existing config where available, not invented
    return [
      {
        severity: OperationalIncidentSeverity.INFO,
        maxAgeMinutes: 240,
        maxOccurrences: 100,
        escalateTo: ['OPERATOR'],
        requiresAcknowledgement: false,
      },
      {
        severity: OperationalIncidentSeverity.WARNING,
        maxAgeMinutes: 120,
        maxOccurrences: 20,
        escalateTo: ['OPERATOR', 'TEAM_LEAD'],
        requiresAcknowledgement: true,
      },
      {
        severity: OperationalIncidentSeverity.ERROR,
        maxAgeMinutes: 30,
        maxOccurrences: 5,
        escalateTo: ['OPERATOR', 'TEAM_LEAD', 'ONCALL'],
        requiresAcknowledgement: true,
      },
      {
        severity: OperationalIncidentSeverity.CRITICAL,
        maxAgeMinutes: 10,
        maxOccurrences: 2,
        escalateTo: ['OPERATOR', 'TEAM_LEAD', 'ONCALL', 'PLATFORM_ADMIN'],
        requiresAcknowledgement: true,
      },
    ];
  }

  getMaintenanceRestrictions(): MaintenanceRestriction[] {
    return [
      {
        scope: OperationalMaintenanceScope.PLATFORM,
        requiresPlatformRole: true,
        requiresTenantOwnership: false,
        maxDurationHours: 8,
        disallowedScopesDuringLiveTrading: [],
        requiresApprovalForEmergency: true,
      },
      {
        scope: OperationalMaintenanceScope.TENANT,
        requiresPlatformRole: false,
        requiresTenantOwnership: true,
        maxDurationHours: 4,
        disallowedScopesDuringLiveTrading: [],
        requiresApprovalForEmergency: false,
      },
      {
        scope: OperationalMaintenanceScope.SERVICE,
        requiresPlatformRole: true,
        requiresTenantOwnership: false,
        maxDurationHours: 2,
        disallowedScopesDuringLiveTrading: [],
        requiresApprovalForEmergency: true,
      },
      {
        scope: OperationalMaintenanceScope.VENUE,
        requiresPlatformRole: true,
        requiresTenantOwnership: false,
        maxDurationHours: 2,
        disallowedScopesDuringLiveTrading: [],
        requiresApprovalForEmergency: true,
      },
      {
        scope: OperationalMaintenanceScope.TRADING_CAPABILITY,
        requiresPlatformRole: true,
        requiresTenantOwnership: false,
        maxDurationHours: 2,
        disallowedScopesDuringLiveTrading: [OperationalMaintenanceScope.TRADING_CAPABILITY],
        requiresApprovalForEmergency: true,
      },
      {
        scope: OperationalMaintenanceScope.BILLING_CAPABILITY,
        requiresPlatformRole: true,
        requiresTenantOwnership: false,
        maxDurationHours: 2,
        disallowedScopesDuringLiveTrading: [],
        requiresApprovalForEmergency: true,
      },
    ];
  }

  getRecoveryPermissions(): RecoveryPermission {
    return {
      requiresPlatformRole: false, // some recoveries tenant-scoped, but critical ones require platform
      requiresExplicitApproval: true,
      allowedRecoveryTypes: [
        'RETRY_QUEUE',
        'RERUN_RECONCILIATION',
        'RESTART_STREAM',
        'RECONNECT_EXCHANGE',
        'CLEAR_STALE_LOCK',
        'RESYNC_OMS',
        'RETRY_BILLING',
        'RETRY_NOTIFICATION',
        'RECOVER_SUBSCRIPTION',
      ],
      forbiddenBypasses: [
        'RISK',
        'COMPLIANCE',
        'LIVE_GATE',
        'CREDENTIAL_CONTROLS',
        'VENUE_ATTESTATION',
        'IP_ALLOWLIST',
        'SIGNED_TRANSPORT',
        'OMS',
        'EXECUTION_ENGINE',
        'DISTRIBUTED_LOCK',
        'DIRECT_DB_PATCH',
        'FAKE_FILL',
        'FAKE_ORDER_FILLED',
        'FAKE_PAYMENT_SUCCESS',
      ],
    };
  }

  isPlatformScoped(scope: OperationalMaintenanceScope, tenantId?: string | null): boolean {
    if (scope === OperationalMaintenanceScope.PLATFORM) return true;
    if (scope === OperationalMaintenanceScope.SERVICE) return true;
    if (scope === OperationalMaintenanceScope.VENUE) return true;
    if (!tenantId) return true; // null tenantId means platform
    return false;
  }

  getDegradationAllowedOperations(level: OperationalDegradationLevel): { allowed: string[]; blocked: string[] } {
    switch (level) {
      case OperationalDegradationLevel.NORMAL:
        return {
          allowed: ['READ', 'WRITE', 'TRADE', 'BILLING', 'ADMIN'],
          blocked: [],
        };
      case OperationalDegradationLevel.DEGRADED:
        return {
          allowed: ['READ', 'WRITE', 'TRADE', 'BILLING'],
          blocked: ['ADMIN_CRITICAL'],
        };
      case OperationalDegradationLevel.READ_ONLY:
        return {
          allowed: ['READ'],
          blocked: ['WRITE', 'TRADE', 'BILLING', 'ADMIN'],
        };
      case OperationalDegradationLevel.PAUSED:
        return {
          allowed: ['READ'],
          blocked: ['WRITE', 'TRADE', 'BILLING'],
        };
      case OperationalDegradationLevel.DISABLED:
        return {
          allowed: [],
          blocked: ['READ', 'WRITE', 'TRADE', 'BILLING', 'ADMIN'],
        };
      default:
        return { allowed: [], blocked: ['READ', 'WRITE', 'TRADE', 'BILLING', 'ADMIN'] };
    }
  }

  getCriticalReconciliationTypes(): OperationalReconciliationType[] {
    return [
      OperationalReconciliationType.OMS_ORDER,
      OperationalReconciliationType.OMS_FILL,
      OperationalReconciliationType.OMS_POSITION,
      OperationalReconciliationType.EXCHANGE_ACCOUNT,
      OperationalReconciliationType.RISK,
      OperationalReconciliationType.COMPLIANCE,
    ];
  }

  // Resolve policy version for auditability
  getPolicyVersion(): string {
    return `ops-policy-v1-${this.config.nodeEnv ?? 'production'}`;
  }

  async getTenantSecurityPolicy(tenantId: string) {
    const policy = await (this.prisma as any).securityPolicy.findFirst({
      where: { tenantId, isActive: true },
      orderBy: { createdAt: 'desc' },
    });
    return policy;
  }
}

// # Responsibility: use typed verified-principal tenant scope and userId for operations; deny tenantless ordinary callers instead of widening to platform reads.
import { Controller, Get, Post, Param, Body, Query, Req, ForbiddenException, BadRequestException } from '@nestjs/common';
import { Permission } from '@wlct/shared-types';
import { AllowAnyAuthenticated, RequirePermissions } from '../../common/decorators/permissions.decorator';
import { SystemReadinessService } from './system-readiness.service';
import { DependencyHealthService } from './dependency-health.service';
import { QueueHealthService } from './queue-health.service';
import { JobHealthService } from './job-health.service';
import { ReconciliationOrchestratorService } from './reconciliation-orchestrator.service';
import { ReconciliationScheduleService } from './reconciliation-schedule.service';
import { IncidentService } from './incident.service';
import { IncidentEscalationService } from './incident-escalation.service';
import { MaintenanceWindowService } from './maintenance-window.service';
import { MaintenanceModeService } from './maintenance-mode.service';
import { ServiceDegradationService } from './service-degradation.service';
import { RecoveryPlanService } from './recovery-plan.service';
import { OperatorActionService } from './operator-action.service';
import { RunbookService } from './runbook.service';
import { OperationalAuditService } from './operational-audit.service';
import { OperationalMetricsService } from './operational-metrics.service';
import { OperationsPolicyService } from './operations-policy.service';

import { CreateIncidentDto, AcknowledgeIncidentDto, ResolveIncidentDto, SuppressIncidentDto, ReopenIncidentDto, EscalateIncidentDto, AssignIncidentDto, OperatorActionDto, ExecuteRecoveryDto } from './dto/incident-action.dto';
import {
  CreateMaintenanceWindowDto,
  CancelMaintenanceWindowDto,
  EnterMaintenanceDto,
  ExitMaintenanceDto,
  SetDegradationDto,
  ClearDegradationDto,
} from './dto/maintenance-window.dto';
import {
  IncidentQueryDto,
  DependencyQueryDto,
  ReconciliationQueryDto,
  MaintenanceQueryDto,
  RecoveryQueryDto,
  ActionQueryDto,
  DegradationQueryDto,
  AuditQueryDto,
  MetricsQueryDto,
  ReadinessQueryDto,
} from './dto/operations-query.dto';
import {
  TriggerReadinessCheckDto,
  TriggerDependencyCheckDto,
  TriggerReconciliationDto,
  TriggerQueueCheckDto,
  TriggerJobCheckDto,
  RequestRecoveryDto,
  ApproveRecoveryDto,
  OperatorDiagnosticDto,
} from './dto/readiness-action.dto';

import { OperationalMaintenanceScope, OperationalTriggerType, OperationalAuditEventType } from './operations.types';
import { authTenantIdOrNull, isPlatformPrincipal } from '../../common/guards/request-principal';

type OperationsRequest = NonNullable<Parameters<typeof authTenantIdOrNull>[0]> & { requestId?: string; correlationId?: string };

/**
 * Tenant-safe and platform-safe API controller exposing operational status, readiness,
 * dependencies, incidents, reconciliation runs, maintenance windows, metrics, recovery,
 * and operator actions. Enforce existing RBAC/security policies and never expose secrets.
 */

/**
 * Operations console: readiness, incidents, reconciliations, maintenance,
 * degradations, recovery runs and operator actions.
 *
 * The handlers enforce tenant isolation and platform-only operations, but the
 * controller carried no permission metadata, so any tenant user (a follower)
 * could open incidents, put the tenant into maintenance, or approve and
 * execute recovery runs. Reads now need operations:read; every change needs
 * operations:alerts_update (class default). GET maintenance/current is the
 * customer banner and is open to any signed-in user of the tenant.
 */
@RequirePermissions(Permission.OPERATIONS_ALERTS_UPDATE)
@Controller('operations')
export class OperationsController {
  constructor(
    private readonly readinessService: SystemReadinessService,
    private readonly dependencyHealthService: DependencyHealthService,
    private readonly queueHealthService: QueueHealthService,
    private readonly jobHealthService: JobHealthService,
    private readonly reconciliationOrchestrator: ReconciliationOrchestratorService,
    private readonly reconciliationSchedule: ReconciliationScheduleService,
    private readonly incidentService: IncidentService,
    private readonly escalationService: IncidentEscalationService,
    private readonly maintenanceWindowService: MaintenanceWindowService,
    private readonly maintenanceModeService: MaintenanceModeService,
    private readonly degradationService: ServiceDegradationService,
    private readonly recoveryPlanService: RecoveryPlanService,
    private readonly operatorActionService: OperatorActionService,
    private readonly runbookService: RunbookService,
    private readonly auditService: OperationalAuditService,
    private readonly metricsService: OperationalMetricsService,
    private readonly policyService: OperationsPolicyService,
  ) {}

  private getTenantIdFromRequest(req: OperationsRequest): string | null {
    // Tenant of the verified token only (never a header or other request field).
    const tenantId = authTenantIdOrNull(req);
    if (!tenantId && !isPlatformPrincipal(req)) throw new ForbiddenException('Tenant context required');
    return tenantId;
  }

  private getActorIdFromRequest(req: OperationsRequest): string | null {
    const userId = req.user?.userId;
    if (typeof userId !== 'string' || !userId.trim()) throw new ForbiddenException('Authenticated userId required');
    return userId;
  }

  private isPlatformUser(req: OperationsRequest): boolean {
    // Server-side platform flag only. The previous role-name match treated any
    // key containing "admin" (e.g. TENANT_ADMIN) as platform, which let a
    // tenant administrator pass another tenant's id and read its operations
    // data. Role keys are tenant-editable and never grant cross-tenant reach.
    return isPlatformPrincipal(req);
  }

  private enforceTenantIsolation(requestedTenantId: string | null, req: OperationsRequest): void {
    const userTenantId = this.getTenantIdFromRequest(req);
    const isPlatform = this.isPlatformUser(req);
    if (isPlatform) return; // platform can access all with RBAC
    if (userTenantId && requestedTenantId && userTenantId !== requestedTenantId) {
      throw new ForbiddenException('Tenant isolation violation');
    }
    if (!isPlatform && !userTenantId && requestedTenantId) {
      // Non-platform user without tenant trying to access tenant data
      throw new ForbiddenException('Tenant context required');
    }
  }

  private enforcePlatformRBAC(req: OperationsRequest): void {
    if (!this.isPlatformUser(req)) {
      throw new ForbiddenException('Platform operation requires platform RBAC');
    }
  }

  // --- Readiness ---

  @Get('readiness')
  @RequirePermissions(Permission.OPERATIONS_READ)
  async getReadiness(@Query() query: ReadinessQueryDto, @Req() req: OperationsRequest) {
    const tenantId = query.tenantId ?? this.getTenantIdFromRequest(req);
    this.enforceTenantIsolation(tenantId ?? null, req);
    // If tenantId null and not platform user, forbid platform visibility
    if (tenantId === null && !this.isPlatformUser(req)) {
      // Allow tenant to check own readiness via inferred tenantId
      const inferred = this.getTenantIdFromRequest(req);
      if (!inferred) throw new ForbiddenException('Platform readiness requires platform RBAC');
      return this.readinessService.evaluate({ tenantId: inferred, correlationId: null });
    }
    return this.readinessService.evaluate({ tenantId: tenantId ?? null, correlationId: null });
  }

  @Post('readiness/check')
  async triggerReadinessCheck(@Body() dto: TriggerReadinessCheckDto, @Req() req: OperationsRequest) {
    const tenantId = dto.tenantId ?? this.getTenantIdFromRequest(req);
    this.enforceTenantIsolation(tenantId ?? null, req);
    if (tenantId === null && !this.isPlatformUser(req)) throw new ForbiddenException('Platform readiness check requires platform RBAC');
    const actorId = this.getActorIdFromRequest(req);
    return this.readinessService.evaluate({ tenantId: tenantId ?? null, requestedBy: actorId, correlationId: dto.correlationId ?? null });
  }

  @Get('readiness/latest')
  @RequirePermissions(Permission.OPERATIONS_READ)
  async getLatestReadiness(@Query() query: ReadinessQueryDto, @Req() req: OperationsRequest) {
    const tenantId = query.tenantId ?? this.getTenantIdFromRequest(req);
    this.enforceTenantIsolation(tenantId ?? null, req);
    return this.readinessService.getLatest(tenantId ?? null);
  }

  // --- Dependencies ---

  @Get('dependencies')
  @RequirePermissions(Permission.OPERATIONS_READ)
  async getDependencies(@Query() query: DependencyQueryDto, @Req() req: OperationsRequest) {
    const tenantId = this.getTenantIdFromRequest(req);
    // Platform-only operations remain protected — but dependency health can be tenant-scoped
    const results = await this.dependencyHealthService.checkAll(tenantId);
    return { data: results, total: results.length };
  }

  @Post('dependencies/check')
  async triggerDependencyCheck(@Body() dto: TriggerDependencyCheckDto, @Req() req: OperationsRequest) {
    const tenantId = dto.tenantId ?? this.getTenantIdFromRequest(req);
    this.enforceTenantIsolation(tenantId ?? null, req);
    const results = await this.dependencyHealthService.checkAll(tenantId ?? null);
    return { data: results, total: results.length };
  }

  // --- Queues ---

  @Get('queues/health')
  @RequirePermissions(Permission.OPERATIONS_READ)
  async getQueueHealth(@Req() req: OperationsRequest) {
    // Platform operation — but allow tenant to see own queue health if needed
    const results = await this.queueHealthService.evaluate();
    return { data: results, total: results.length };
  }

  @Post('queues/check')
  async triggerQueueCheck(@Body() dto: TriggerQueueCheckDto, @Req() req: OperationsRequest) {
    const results = await this.queueHealthService.evaluate();
    if (dto.queueName) {
      const filtered = results.filter((r) => r.queueName === dto.queueName);
      return { data: filtered, total: filtered.length };
    }
    return { data: results, total: results.length };
  }

  // --- Jobs ---

  @Get('jobs/health')
  @RequirePermissions(Permission.OPERATIONS_READ)
  async getJobHealth(@Req() req: OperationsRequest) {
    const results = await this.jobHealthService.evaluate();
    return { data: results, total: results.length };
  }

  @Post('jobs/check')
  async triggerJobCheck(@Body() dto: TriggerJobCheckDto, @Req() req: OperationsRequest) {
    const results = await this.jobHealthService.evaluate();
    if (dto.jobName) {
      const filtered = results.filter((r) => r.jobName === dto.jobName);
      return { data: filtered, total: filtered.length };
    }
    return { data: results, total: results.length };
  }

  // --- Incidents ---

  @Get('incidents')
  @RequirePermissions(Permission.OPERATIONS_READ)
  async listIncidents(@Query() query: IncidentQueryDto, @Req() req: OperationsRequest) {
    const tenantId = this.getTenantIdFromRequest(req);
    const isPlatform = this.isPlatformUser(req);
    // Tenant isolation: tenant cannot read another tenant's incidents
    const effectiveTenantId = isPlatform ? query.tenantId ?? null : tenantId;
    if (!isPlatform && tenantId === null) throw new ForbiddenException('Tenant context required');
    return this.incidentService.listIncidents({
      tenantId: effectiveTenantId ?? null,
      state: query.state,
      severity: query.severity,
      type: query.type,
      affectedComponent: query.affectedComponent,
      correlationId: query.correlationId,
      page: query.page,
      limit: query.limit,
    });
  }

  @Get('incidents/:id')
  @RequirePermissions(Permission.OPERATIONS_READ)
  async getIncident(@Param('id') id: string, @Req() req: OperationsRequest) {
    const tenantId = this.getTenantIdFromRequest(req);
    const isPlatform = this.isPlatformUser(req);
    const effectiveTenantId = isPlatform ? null : tenantId;
    // For platform user with null tenantId, we allow reading any incident, but for tenant we enforce isolation inside service
    return this.incidentService.getIncident(effectiveTenantId ?? null, id);
  }

  @Post('incidents')
  async createIncident(@Body() dto: CreateIncidentDto, @Req() req: OperationsRequest) {
    const actorId = this.getActorIdFromRequest(req);
    const tenantId = dto.tenantId ?? this.getTenantIdFromRequest(req);
    this.enforceTenantIsolation(tenantId ?? null, req);
    // Platform incidents require platform RBAC
    if (tenantId === null && !this.isPlatformUser(req)) throw new ForbiddenException('Platform incident creation requires platform RBAC');
    return this.incidentService.createIncident({
