      const res = await this.runReconciliation({
        tenantId: tenantId ?? null,
        type,
        requestedBy: requestedBy ?? null,
        triggerType: OperationalTriggerType.MANUAL,
        correlationId: correlationId ?? null,
      });
      results.push(res);
    }
    return results;
  }

  async getRun(tenantId: string | null, runId: string): Promise<any> {
    const where: any = { id: runId };
    if (tenantId !== null) where.tenantId = tenantId;
    try {
      const run = await (this.prisma as any).operationalReconciliationRun.findFirst({ where });
      if (!run) throw new BadRequestException(`Reconciliation run ${runId} not found`);
      if (tenantId !== null && run.tenantId !== null && run.tenantId !== tenantId) {
        throw new BadRequestException('Tenant isolation violation');
      }
      return run;
    } catch (e) {
      if (e instanceof BadRequestException) throw e;
      throw new BadRequestException(`Reconciliation run ${runId} not found`);
    }
  }

  async listRuns(params: {
    tenantId?: string | null;
    type?: string;
    status?: string;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId = null, type, status, page = 1, limit = 20 } = params;
    const where: any = {};
    if (tenantId !== undefined && tenantId !== null) where.tenantId = tenantId;
    if (type) where.reconciliationType = type;
    if (status) where.status = status;

    const [data, total] = await Promise.all([
      (this.prisma as any).operationalReconciliationRun.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).operationalReconciliationRun.count({ where }),
    ]);
    return { data, total, page, limit };
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { RedisService } from '../../infrastructure/redis/redis.service';
import { QueueService } from '../queue/queue.service';
import { ReconciliationOrchestratorService } from './reconciliation-orchestrator.service';
import { OperationalAuditService } from './operational-audit.service';
import {
  OperationalReconciliationType,
  OperationalTriggerType,
  deterministicIdempotencyKey,
  redactSecrets,
} from './operations.types';

/**
 * Defines and executes reconciliation schedules using existing scheduler/queue infrastructure.
 * Must support tenant-scoped and platform-scoped runs, idempotency, lock protection, retry policy,
 * and safe failure handling.
 */

@Injectable()
export class ReconciliationScheduleService {
  private readonly logger = new Logger(ReconciliationScheduleService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly redis: RedisService,
    private readonly queueService: QueueService,
    private readonly orchestrator: ReconciliationOrchestratorService,
    private readonly auditService: OperationalAuditService,
  ) {}

  // Schedule definitions — reuse existing scheduler/queue infrastructure
  private readonly SCHEDULES: Array<{
    type: OperationalReconciliationType;
    cron: string;
    scope: 'PLATFORM' | 'TENANT';
    description: string;
  }> = [
    { type: OperationalReconciliationType.OMS_ORDER, cron: '*/15 * * * *', scope: 'TENANT', description: 'OMS order reconciliation every 15m per tenant' },
    { type: OperationalReconciliationType.OMS_FILL, cron: '*/15 * * * *', scope: 'TENANT', description: 'OMS fill reconciliation every 15m per tenant' },
    { type: OperationalReconciliationType.OMS_POSITION, cron: '*/30 * * * *', scope: 'TENANT', description: 'OMS position reconciliation every 30m' },
    { type: OperationalReconciliationType.EXCHANGE_ACCOUNT, cron: '0 * * * *', scope: 'TENANT', description: 'Exchange account reconciliation hourly' },
    { type: OperationalReconciliationType.RISK, cron: '*/30 * * * *', scope: 'TENANT', description: 'Risk reconciliation every 30m' },
    { type: OperationalReconciliationType.COMPLIANCE, cron: '0 */6 * * *', scope: 'TENANT', description: 'Compliance reconciliation every 6h' },
    { type: OperationalReconciliationType.COPY_TRADING, cron: '*/30 * * * *', scope: 'TENANT', description: 'Copy trading reconciliation every 30m' },
    { type: OperationalReconciliationType.PAYMENT, cron: '0 */2 * * *', scope: 'PLATFORM', description: 'Payment reconciliation every 2h platform' },
    { type: OperationalReconciliationType.BILLING_FINANCE, cron: '0 2 * * *', scope: 'PLATFORM', description: 'Billing finance reconciliation daily 2am' },
    { type: OperationalReconciliationType.FEE, cron: '0 */4 * * *', scope: 'TENANT', description: 'Fee reconciliation every 4h' },
    { type: OperationalReconciliationType.USAGE, cron: '0 * * * *', scope: 'TENANT', description: 'Usage reconciliation hourly' },
    { type: OperationalReconciliationType.NOTIFICATION, cron: '*/30 * * * *', scope: 'PLATFORM', description: 'Notification reconciliation every 30m platform' },
    { type: OperationalReconciliationType.SUBSCRIPTION, cron: '0 */6 * * *', scope: 'PLATFORM', description: 'Subscription reconciliation every 6h platform' },
  ];

  getSchedules() {
    return this.SCHEDULES;
  }

  async scheduleAll(): Promise<void> {
    // Use existing queue scheduler — do not create second queue implementation
    for (const sched of this.SCHEDULES) {
      try {
        await this.queueService.schedule(
          'MAINTENANCE' as any,
          `reconciliation-${sched.type.toLowerCase()}`,
          {
            type: sched.type,
            scope: sched.scope,
            triggerType: OperationalTriggerType.SCHEDULED,
            correlationId: `sched-${sched.type}-${Date.now()}`,
          },
          sched.cron,
        );
        this.logger.log({
          event: 'operations.reconciliation.scheduled',
          type: sched.type,
          cron: sched.cron,
          scope: sched.scope,
        });
      } catch (e) {
        this.logger.warn(`Failed to schedule ${sched.type}: ${(e as Error).message}`);
      }
    }
  }

  async executeScheduledRun(params: {
    type: OperationalReconciliationType;
    scope: 'PLATFORM' | 'TENANT';
    tenantId?: string | null;
    correlationId?: string | null;
  }): Promise<any> {
    const { type, scope, tenantId = null, correlationId = null } = params;

    const idempotencyKey = deterministicIdempotencyKey({
      type: `scheduled-reconciliation:${type}`,
      tenantId: scope === 'PLATFORM' ? null : tenantId ?? null,
      scope,
      correlationId: correlationId ?? null,
      timestampBucket: new Date().toISOString().slice(0, 13), // hourly bucket
    });

    // Lock protection
    const lockKey = `ops:scheduled-reconciliation:${type}:${scope === 'PLATFORM' ? 'platform' : tenantId ?? 'all'}`;
    const token = `sched-${Date.now()}`;
    const release = await this.redis.acquireLock(lockKey, 10 * 60 * 1000, token).catch(() => null);
    if (!release) {
      this.logger.log({ event: 'operations.reconciliation.scheduled_skipped_lock', type, scope });
      return null;
    }

    try {
      if (scope === 'PLATFORM') {
        return await this.orchestrator.runReconciliation({
          tenantId: null,
          type,
          requestedBy: null,
          triggerType: OperationalTriggerType.SCHEDULED,
          correlationId: correlationId ?? null,
        });
      } else {
        // TENANT scope — if tenantId provided, run for that tenant, else run for all tenants with recent activity
        if (tenantId) {
          return await this.orchestrator.runReconciliation({
            tenantId,
            type,
            requestedBy: null,
            triggerType: OperationalTriggerType.SCHEDULED,
            correlationId: correlationId ?? null,
          });
        } else {
          // Find active tenants
          const tenants = await this.prisma.tenant.findMany({
            where: { status: 'ACTIVE' as any },
            select: { id: true },
            take: 100,
          });
          const results = [];
          for (const t of tenants) {
            const res = await this.orchestrator.runReconciliation({
              tenantId: t.id,
              type,
              requestedBy: null,
              triggerType: OperationalTriggerType.SCHEDULED,
              correlationId: correlationId ?? null,
            }).catch((e) => {
              this.logger.warn(`Scheduled reconciliation failed for tenant ${t.id} type ${type}: ${(e as Error).message}`);
              return null;
            });
            if (res) results.push(res);
          }
          return results;
        }
      }
    } finally {
      try {
        await release();
      } catch {}
    }
  }

  async triggerManualRun(params: {
    tenantId?: string | null;
    type: OperationalReconciliationType;
    requestedBy?: string | null;
    correlationId?: string | null;
  }): Promise<any> {
    if (!Object.values(OperationalReconciliationType).includes(params.type)) {
      throw new BadRequestException(`Invalid reconciliation type ${params.type}`);
    }

    await this.auditService.record({
      tenantId: params.tenantId ?? null,
      eventType: 'RECONCILIATION_RUN_STARTED' as any,
      actorId: params.requestedBy ?? null,
      actorType: params.requestedBy ? 'USER' : 'SYSTEM',
      targetType: 'RECONCILIATION_RUN',
      targetId: params.type,
      evidence: redactSecrets({
        type: params.type,
        triggerType: 'MANUAL',
        correlationId: params.correlationId,
      }),
      correlationId: params.correlationId ?? null,
    });

    return this.orchestrator.runReconciliation({
      tenantId: params.tenantId ?? null,
      type: params.type,
      requestedBy: params.requestedBy ?? null,
      triggerType: OperationalTriggerType.MANUAL,
      correlationId: params.correlationId ?? null,
    });
  }

  async handleJob(jobData: { type: OperationalReconciliationType; scope: string; tenantId?: string; correlationId?: string }): Promise<void> {
    try {
      await this.executeScheduledRun({
        type: jobData.type,
        scope: jobData.scope as any,
        tenantId: jobData.tenantId ?? null,
        correlationId: jobData.correlationId ?? null,
      });
    } catch (e) {
      this.logger.error(`Reconciliation scheduled job failed: ${(e as Error).message}`);
      // Safe failure handling — do not crash worker, record audit
      await this.auditService.record({
        tenantId: jobData.tenantId ?? null,
        eventType: 'RECONCILIATION_RUN_FAILED' as any,
        actorId: null,
        actorType: 'SYSTEM',
        targetType: 'RECONCILIATION_RUN',
        targetId: jobData.type,
        evidence: redactSecrets({ error: (e as Error).message, type: jobData.type }),
        correlationId: jobData.correlationId ?? null,
      });
    }
  }
}

import { Injectable, Logger, BadRequestException, ForbiddenException, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { RedisService } from '../../infrastructure/redis/redis.service';
import { OperationalAuditService } from './operational-audit.service';
import { OperationsPolicyService } from './operations-policy.service';
import { OperationalRecoveryState, deterministicIdempotencyKey, redactSecrets } from './operations.types';
import { randomUUID } from 'crypto';

/**
 * Stores and executes structured recovery procedures referencing existing authoritative services.
 * Recovery must be step-based, idempotent where possible, auditable, and incapable of bypassing
 * risk, compliance, live-gate, credential, OMS, or execution controls.
 */

export interface RecoveryStep {
  stepId: string;
  name: string;
  description: string;
  service: string; // e.g., 'queue', 'exchange', 'oms', 'risk', etc
  action: string; // e.g., 'retry', 'reconnect', 'resync'
  preconditions?: string[];
  isIdempotent?: boolean;
  requiresApproval?: boolean;
  forbiddenBypasses?: string[];
}

export interface RecoveryPlanDefinition {
  planId: string;
  name: string;
  description: string;
  applicableIncidentTypes: string[];
  steps: RecoveryStep[];
  requiresPlatformRole?: boolean;
  estimatedDurationMinutes?: number;
}

@Injectable()
export class RecoveryPlanService {
  private readonly logger = new Logger(RecoveryPlanService.name);

  private readonly PLANS: RecoveryPlanDefinition[] = [
    {
      planId: 'queue-retry',
      name: 'Queue Retry Recovery',
      description: 'Retry failed jobs in queue using existing queue infrastructure',
      applicableIncidentTypes: ['QUEUE_FAILURE', 'JOB_FAILURE', 'STALE_JOB'],
      steps: [
        { stepId: 'check-queue-health', name: 'Check queue health', description: 'Verify queue connectivity', service: 'queue', action: 'health-check', isIdempotent: true },
        { stepId: 'retry-failed-jobs', name: 'Retry failed jobs', description: 'Retry failed jobs via existing queue service', service: 'queue', action: 'retry-failed', isIdempotent: true },
        { stepId: 'verify-recovery', name: 'Verify recovery', description: 'Run reconciliation to verify', service: 'reconciliation', action: 'verify', isIdempotent: true },
      ],
    },
    {
      planId: 'exchange-reconnect',
      name: 'Exchange Reconnect Recovery',
      description: 'Reconnect exchange streams using existing execution safety boundaries',
      applicableIncidentTypes: ['EXCHANGE_DISCONNECT', 'STREAM_FAILURE', 'CREDENTIAL_FAILURE'],
      steps: [
        { stepId: 'check-credential', name: 'Check credential', description: 'Verify credential source via existing service', service: 'credential', action: 'verify', isIdempotent: true, preconditions: ['credential exists'] },
        { stepId: 'check-live-gate', name: 'Check live gate', description: 'Verify live gate prerequisites', service: 'live-gate', action: 'check', isIdempotent: true },
        { stepId: 'reconnect-stream', name: 'Reconnect stream', description: 'Reconnect via existing execution service', service: 'execution', action: 'reconnect', isIdempotent: false },
        { stepId: 'reconcile-orders', name: 'Reconcile orders', description: 'Run OMS order reconciliation', service: 'oms', action: 'reconcile-orders', isIdempotent: true },
      ],
      requiresPlatformRole: true,
    },
    {
      planId: 'oms-resync',
      name: 'OMS Resync Recovery',
      description: 'Resync OMS state via existing OMS reconciliation, never direct DB patch',
      applicableIncidentTypes: ['OMS_STALE', 'POSITION_MISMATCH', 'FILL_MISMATCH'],
      steps: [
        { stepId: 'check-oms-health', name: 'Check OMS health', description: 'Verify OMS tables accessible', service: 'oms', action: 'health-check', isIdempotent: true },
        { stepId: 'run-order-reconciliation', name: 'Run order reconciliation', description: 'Delegate to OMS order reconciliation service', service: 'oms', action: 'reconcile-orders', isIdempotent: true },
        { stepId: 'run-fill-reconciliation', name: 'Run fill reconciliation', description: 'Delegate to OMS fill reconciliation', service: 'oms', action: 'reconcile-fills', isIdempotent: true },
        { stepId: 'run-position-reconciliation', name: 'Run position reconciliation', description: 'Delegate to position reconciliation', service: 'oms', action: 'reconcile-positions', isIdempotent: true },
        { stepId: 'verify-post-trade', name: 'Verify post-trade', description: 'Run post-trade verification', service: 'oms', action: 'post-trade-verify', isIdempotent: true },
      ],
    },
    {
      planId: 'risk-compliance-recovery',
      name: 'Risk Compliance Recovery',
      description: 'Recover risk/compliance blocks via existing authoritative services, never bypass',
      applicableIncidentTypes: ['RISK_BLOCK', 'COMPLIANCE_BLOCK', 'SECURITY_BLOCK'],
      steps: [
        { stepId: 'check-risk-policy', name: 'Check risk policy', description: 'Verify risk policy via existing risk service', service: 'risk', action: 'check-policy', isIdempotent: true },
        { stepId: 'check-compliance-case', name: 'Check compliance case', description: 'Check compliance case via compliance service', service: 'compliance', action: 'check-case', isIdempotent: true },
        { stepId: 'request-review', name: 'Request review', description: 'Request manual review via existing compliance flow', service: 'compliance', action: 'request-review', isIdempotent: false, requiresApproval: true },
      ],
      requiresPlatformRole: true,
    },
  ];

  constructor(
    private readonly prisma: PrismaService,
    private readonly redis: RedisService,
    private readonly auditService: OperationalAuditService,
    private readonly policyService: OperationsPolicyService,
  ) {}

  getPlans(): RecoveryPlanDefinition[] {
    return this.PLANS;
  }

  getPlan(planId: string): RecoveryPlanDefinition | null {
    return this.PLANS.find((p) => p.planId === planId) ?? null;
  }

  async createRecoveryRun(params: {
    tenantId?: string | null;
    planId: string;
    incidentId?: string | null;
    maintenanceWindowId?: string | null;
    requestedBy?: string | null;
    correlationId?: string | null;
    requiresApproval?: boolean;
  }): Promise<any> {
    const plan = this.getPlan(params.planId);
    if (!plan) throw new BadRequestException(`Recovery plan ${params.planId} not found`);

    // Recovery requires authorization — check policy
    const permissions = this.policyService.getRecoveryPermissions();
    if (plan.requiresPlatformRole && params.tenantId !== null) {
      // Platform role required — will be enforced in controller RBAC, but also check here for safety
      // For tenant-scoped recovery that requires platform, we still allow creation but state will be REQUIRES_APPROVAL
    }

    // Validate no forbidden bypasses in plan steps
    for (const step of plan.steps) {
      const forbidden = step.forbiddenBypasses ?? permissions.forbiddenBypasses;
      if (forbidden) {
        for (const fb of forbidden) {
          if (permissions.forbiddenBypasses.includes(fb)) {
            throw new BadRequestException(`Recovery plan step ${step.stepId} attempts forbidden bypass ${fb}`);
          }
        }
      }
    }

    const idempotencyKey = deterministicIdempotencyKey({
      type: `recovery:${params.planId}`,
      tenantId: params.tenantId ?? null,
      scope: params.incidentId ?? params.maintenanceWindowId ?? params.planId,
      correlationId: params.correlationId ?? null,
      timestampBucket: new Date().toISOString().slice(0, 13),
    });

    // Idempotency check
    try {
      const existing = await (this.prisma as any).operationalRecoveryRun.findFirst({
        where: { idempotencyKey, tenantId: params.tenantId ?? null },
      });
      if (existing) return existing;
    } catch {}

    const initialState = params.requiresApproval || plan.requiresPlatformRole ? OperationalRecoveryState.REQUIRES_APPROVAL : OperationalRecoveryState.PENDING;

    const created = await (this.prisma as any).operationalRecoveryRun.create({
      data: {
        tenantId: params.tenantId ?? null,
        planId: params.planId,
        incidentId: params.incidentId ?? null,
        maintenanceWindowId: params.maintenanceWindowId ?? null,
        state: initialState as any,
        requestedBy: params.requestedBy ?? null,
        steps: plan.steps as any,
        currentStep: 0,
        totalSteps: plan.steps.length,
        result: {} as any,
        correlationId: params.correlationId ?? null,
        idempotencyKey,
      },
    });

    await this.auditService.record({
      tenantId: params.tenantId ?? null,
      eventType: 'RECOVERY_STARTED' as any,
      actorId: params.requestedBy ?? null,
      actorType: params.requestedBy ? 'USER' : 'SYSTEM',
      targetType: 'RECOVERY_RUN',
      targetId: created.id,
      evidence: redactSecrets({
        planId: params.planId,
        incidentId: params.incidentId,
        state: initialState,
        totalSteps: plan.steps.length,
      }),
      correlationId: params.correlationId ?? null,
    });

    return created;
  }

  async approveRecoveryRun(params: {
    tenantId: string | null;
    recoveryRunId: string;
    approvedBy: string;
    correlationId?: string | null;
  }): Promise<any> {
    const run = await this.getRecoveryRun(params.tenantId, params.recoveryRunId);
    if (run.state !== OperationalRecoveryState.REQUIRES_APPROVAL && run.state !== OperationalRecoveryState.PENDING) {
      throw new BadRequestException(`Cannot approve recovery run in state ${run.state}`);
    }

    const updated = await (this.prisma as any).operationalRecoveryRun.update({
      where: { id: run.id },
      data: {
        state: OperationalRecoveryState.APPROVED as any,
        approvedBy: params.approvedBy,
      },
    });

    await this.auditService.record({
      tenantId: params.tenantId ?? null,
      eventType: 'RECOVERY_STARTED' as any,
      actorId: params.approvedBy,
      actorType: 'USER',
      targetType: 'RECOVERY_RUN',
      targetId: run.id,
      evidence: { approvedBy: params.approvedBy },
      correlationId: params.correlationId ?? null,
    });

    return updated;
  }

  async executeRecoveryRun(params: {
    tenantId: string | null;
    recoveryRunId: string;
    actorId?: string | null;
    correlationId?: string | null;
  }): Promise<any> {
    const run = await this.getRecoveryRun(params.tenantId, params.recoveryRunId);

    // Precondition Check → Authorization → Distributed Lock → Existing Authoritative Service → Result Verification → Reconciliation → Audit
    if (run.state !== OperationalRecoveryState.PENDING && run.state !== OperationalRecoveryState.APPROVED) {
      throw new BadRequestException(`Recovery run must be PENDING or APPROVED to execute, current ${run.state}`);
    }

    // Authorization already checked via RBAC in controller; here we ensure approval if required
    if (run.state === OperationalRecoveryState.REQUIRES_APPROVAL) {
      throw new BadRequestException('Recovery run requires approval before execution');
    }

    // Distributed Lock
    const lockKey = `ops:recovery:${run.id}`;
    const token = randomUUID();
    const release = await this.redis.acquireLock(lockKey, 10 * 60 * 1000, token).catch(() => null);
    if (!release) throw new BadRequestException('Recovery run already executing (lock held)');

    try {
      // Transition to RUNNING
      await (this.prisma as any).operationalRecoveryRun.update({
        where: { id: run.id },
        data: {
          state: OperationalRecoveryState.RUNNING as any,
          startedAt: new Date(),
        },
      });

      const steps = (run.steps as any[]) ?? [];
      const results: any[] = [];
      let currentStep = 0;
      let failed = false;
      let failureReason: string | null = null;

      for (const step of steps) {
        currentStep++;
        // Precondition Check
        if (step.preconditions) {
          for (const precondition of step.preconditions) {
            // Simulate precondition check — in real implementation, would call existing service
            this.logger.debug(`Checking precondition ${precondition} for step ${step.stepId}`);
          }
        }

        // Authorization — step-level
        if (step.requiresApproval && !run.approvedBy) {
          failed = true;
          failureReason = `Step ${step.stepId} requires approval`;
          results.push({ stepId: step.stepId, status: 'FAILED', error: failureReason });
          break;
        }

        // Existing Authoritative Service — recovery must re-enter existing service boundary, never direct DB patch
        try {
          const stepResult = await this.executeRecoveryStep({
            tenantId: params.tenantId ?? null,
            runId: run.id,
            step,
            correlationId: params.correlationId ?? null,
          });
          results.push({ stepId: step.stepId, status: 'SUCCEEDED', result: stepResult });

          // Update current step
          await (this.prisma as any).operationalRecoveryRun.update({
            where: { id: run.id },
            data: { currentStep, result: { steps: results } as any },
          });
        } catch (e) {
          failed = true;
          failureReason = (e as Error).message.slice(0, 1000);
          results.push({ stepId: step.stepId, status: 'FAILED', error: failureReason });
          break;
        }
      }

      const finishTime = new Date();
      const startTime = run.startedAt ? new Date(run.startedAt) : new Date(run.createdAt);
      const durationMs = finishTime.getTime() - startTime.getTime();

      const finalState = failed ? OperationalRecoveryState.FAILED : OperationalRecoveryState.SUCCEEDED;

      const updated = await (this.prisma as any).operationalRecoveryRun.update({
        where: { id: run.id },
        data: {
          state: finalState as any,
          finishedAt: finishTime,
          durationMs,
          result: { steps: results, totalSteps: steps.length, completedSteps: currentStep } as any,
          failureReason: failed ? failureReason : null,
        },
      });

      const auditEvent = failed ? 'RECOVERY_FAILED' : 'RECOVERY_COMPLETED';
      await this.auditService.record({
        tenantId: params.tenantId ?? null,
        eventType: auditEvent as any,
        actorId: params.actorId ?? null,
        actorType: params.actorId ? 'USER' : 'SYSTEM',
        targetType: 'RECOVERY_RUN',
        targetId: run.id,
        evidence: redactSecrets({
          planId: run.planId,
          state: finalState,
          durationMs,
          failureReason,
          stepsCompleted: currentStep,
        }),
        correlationId: params.correlationId ?? null,
      });

      // Reconciliation verification after recovery
      if (!failed) {
        // Trigger reconciliation verification — safe, does not bypass controls
        this.logger.log({ event: 'operations.recovery.trigger_reconciliation_verification', runId: run.id });
      }

      return updated;
    } finally {
      try {
        await release();
      } catch {}
    }
  }

  private async executeRecoveryStep(params: {
    tenantId: string | null;
    runId: string;
    step: RecoveryStep;
    correlationId: string | null;
  }): Promise<any> {
    // No recovery procedure may directly patch database state to simulate
    // success, and (Phase 3) no step may REPORT success it did not verify.
    // Each step either performs a real read-only verification against the
    // authoritative stores (DB, Redis) and throws when the system is not in
    // the required state, or - where the action belongs to a boundary this
    // service cannot drive (stream reconnect, queue replay, manual review) -
    // throws RECOVERY_MANUAL_ACTION_REQUIRED so the run stops as FAILED with
    // an explicit reason instead of pretending the action happened.
    const { step, tenantId } = params;
    const tenantWhere = tenantId ? { tenantId } : {};
    const manual = (what: string): never => {
      throw new BadRequestException(`RECOVERY_MANUAL_ACTION_REQUIRED: ${what}`);
    };

    const unsyncedOrders = () =>
      this.prisma.order.count({ where: { ...tenantWhere, reconciliationState: { not: 'IN_SYNC' } as any } });

    switch (step.service) {
      case 'queue':
        if (step.action === 'health-check') {
          const health = await this.redis.healthCheck().catch(() => ({ ok: false, latencyMs: -1 }));
          if (!health.ok) throw new BadRequestException('Queue backend (Redis) is not reachable');
          return { checked: true, healthy: true, latencyMs: health.latencyMs };
        }
        if (step.action === 'retry-failed') {
          return manual('replay failed jobs from the queue admin (BullMQ) after the root cause is fixed; replay is not automated because non-idempotent jobs must be reviewed');
        }
        break;
      case 'credential':
        if (step.action === 'verify') {
          if (!tenantId) throw new BadRequestException('Credential verification requires a tenant');
          const accounts = await this.prisma.tradingAccount.findMany({
            where: { tenantId },
            select: { id: true, credentialSource: true, credentialRef: true, apiKeyCiphertext: true, apiSecretCiphertext: true },
            take: 1000,
          });
          if (accounts.length === 0) throw new BadRequestException('No trading accounts for credential verification');
          const broken = accounts.filter((a: any) =>
            a.credentialSource === 'SECRET_MANAGER' ? !a.credentialRef : a.credentialSource ? !(a.apiKeyCiphertext && a.apiSecretCiphertext) : false,
          );
          if (broken.length > 0) throw new BadRequestException(`${broken.length} trading account(s) have an incomplete credential record`);
          return { verified: true, accountsChecked: accounts.length };
        }
        break;
      case 'live-gate':
        if (step.action === 'check') {
          const engaged = await this.prisma.killSwitch.count({ where: { isEngaged: true, OR: [{ tenantId: tenantId ?? undefined }, { tenantId: null }] } });
          if (engaged > 0) throw new BadRequestException(`${engaged} kill switch(es) engaged - live gate closed`);
          const unsynced = await unsyncedOrders();
          if (unsynced > 0) throw new BadRequestException(`${unsynced} order(s) not reconciled - live gate stays closed until they are`);
          return { killSwitchEngaged: false, unreconciledOrders: 0 };
        }
        break;
      case 'execution':
        if (step.action === 'reconnect') {
          return manual('restart/reconnect the execution-engine private stream (the engine owns venue connections; the API cannot reconnect them)');
        }
        break;
      case 'oms':
        if (step.action === 'health-check') {
          await this.prisma.$queryRaw`SELECT 1`;
          return { healthy: true };
        }
        if (step.action === 'reconcile-orders' || step.action === 'post-trade-verify') {
          const unsynced = await unsyncedOrders();
          if (unsynced > 0) throw new BadRequestException(`${unsynced} order(s) are not IN_SYNC with the venue`);
          return { verified: true, unsyncedOrders: 0, type: step.action };
        }
        if (step.action === 'reconcile-fills') {
          const filledWithoutFills = await this.prisma.order.count({
            where: { ...tenantWhere, status: { in: ['FILLED', 'PARTIALLY_FILLED'] as any }, fills: { none: {} } },
          });
          if (filledWithoutFills > 0) throw new BadRequestException(`${filledWithoutFills} filled order(s) have no fill records`);
          return { verified: true, filledWithoutFills: 0 };
        }
        if (step.action === 'reconcile-positions') {
          const open = await this.prisma.reconciliationDiscrepancy.count({ where: { ...tenantWhere, repaired: false } });
          if (open > 0) throw new BadRequestException(`${open} unrepaired reconciliation discrepancy(ies)`);
          return { verified: true, openDiscrepancies: 0 };
        }
        break;
      case 'risk':
        if (step.action === 'check-policy') {
          // Verification only: the risk engine still decides every order.
          const engaged = await this.prisma.killSwitch.count({ where: { isEngaged: true, OR: [{ tenantId: tenantId ?? undefined }, { tenantId: null }] } });
          return { policyChecked: true, killSwitchEngaged: engaged > 0, note: 'Risk decisions still require the risk engine, not bypassed' };
        }
        break;
      case 'compliance':
        if (step.action === 'check-case') {
          const blocking = await this.prisma.complianceCase.count({
            where: { ...tenantWhere, decision: 'BLOCK' as any, state: { in: ['OPEN', 'IN_REVIEW', 'ESCALATED'] as any } },
          });
          if (blocking > 0) throw new BadRequestException(`${blocking} open compliance BLOCK case(s) - recovery cannot proceed`);
          return { complianceChecked: true, blockingCases: 0 };
        }
        if (step.action === 'request-review') {
          return manual('open a compliance review through the compliance case workflow');
        }
        break;
      case 'reconciliation':
        if (step.action === 'verify') {
          const unsynced = await unsyncedOrders();
          const open = await this.prisma.reconciliationDiscrepancy.count({ where: { ...tenantWhere, repaired: false } });
          if (unsynced > 0 || open > 0) {
            throw new BadRequestException(`Reconciliation not clean: unsyncedOrders=${unsynced} openDiscrepancies=${open}`);
          }
          return { verified: true, unsyncedOrders: 0, openDiscrepancies: 0 };
        }
        break;
      default:
        break;
    }

    // Unknown service/action: never a silent success.
    throw new BadRequestException(`Unsupported recovery step ${step.service}:${step.action}`);
  }

  async getRecoveryRun(tenantId: string | null, recoveryRunId: string): Promise<any> {
    const where: any = { id: recoveryRunId };
    if (tenantId !== null) where.tenantId = tenantId;
    try {
      const run = await (this.prisma as any).operationalRecoveryRun.findFirst({ where });
      if (!run) throw new NotFoundException(`Recovery run ${recoveryRunId} not found`);
      if (tenantId !== null && run.tenantId !== null && run.tenantId !== tenantId) {
        throw new ForbiddenException('Tenant isolation violation');
      }
      return run;
    } catch (e) {
      if (e instanceof NotFoundException || e instanceof ForbiddenException || e instanceof BadRequestException) throw e;
      throw new NotFoundException(`Recovery run ${recoveryRunId} not found`);
    }
  }

  async listRecoveryRuns(params: {
    tenantId?: string | null;
    planId?: string;
    state?: string;
    incidentId?: string;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId = null, planId, state, incidentId, page = 1, limit = 20 } = params;
    const where: any = {};
    if (tenantId !== undefined && tenantId !== null) where.tenantId = tenantId;
    if (planId) where.planId = planId;
    if (state) where.state = state;
    if (incidentId) where.incidentId = incidentId;

    const [data, total] = await Promise.all([
      (this.prisma as any).operationalRecoveryRun.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).operationalRecoveryRun.count({ where }),
    ]);
    return { data, total, page, limit };
  }
}

/**
 * Phase 3: recovery steps verify real state or stop; they never report a
 * success they did not observe.
 */

import { RecoveryPlanService } from './recovery-plan.service';

function build(overrides: { unsynced?: number; engaged?: number; openDiscrepancies?: number; filledNoFills?: number; blocking?: number; redisOk?: boolean; accounts?: any[] } = {}) {
  const prisma = {
    order: {
      count: jest.fn(async ({ where }: any) => (where.fills ? overrides.filledNoFills ?? 0 : overrides.unsynced ?? 0)),
    },
    killSwitch: { count: jest.fn(async () => overrides.engaged ?? 0) },
    reconciliationDiscrepancy: { count: jest.fn(async () => overrides.openDiscrepancies ?? 0) },
    complianceCase: { count: jest.fn(async () => overrides.blocking ?? 0) },
    tradingAccount: { findMany: jest.fn(async () => overrides.accounts ?? [{ id: 'a', credentialSource: 'ENVELOPE_DB', apiKeyCiphertext: 'x', apiSecretCiphertext: 'y' }]) },
    $queryRaw: jest.fn(async () => [{ '?column?': 1 }]),
  };
  const redis = { healthCheck: jest.fn(async () => ({ ok: overrides.redisOk ?? true, latencyMs: 2 })) };
  const svc = new RecoveryPlanService(prisma as any, redis as any, {} as any, {} as any);
  const step = (service: string, action: string) =>
    (svc as any).executeRecoveryStep({ tenantId: 't1', runId: 'r1', correlationId: null, step: { stepId: 's', name: 's', description: '', service, action, isIdempotent: true } });
  return { step, prisma };
}

describe('RecoveryPlanService.executeRecoveryStep', () => {
  it('queue health reflects Redis', async () => {
    await expect(build().step('queue', 'health-check')).resolves.toMatchObject({ healthy: true });
    await expect(build({ redisOk: false }).step('queue', 'health-check')).rejects.toThrow(/not reachable/);
  });

  it('actions this service cannot drive stop the run as manual', async () => {
    await expect(build().step('queue', 'retry-failed')).rejects.toThrow(/RECOVERY_MANUAL_ACTION_REQUIRED/);
    await expect(build().step('execution', 'reconnect')).rejects.toThrow(/RECOVERY_MANUAL_ACTION_REQUIRED/);
    await expect(build().step('compliance', 'request-review')).rejects.toThrow(/RECOVERY_MANUAL_ACTION_REQUIRED/);
  });

  it('order reconciliation passes only when every order is IN_SYNC', async () => {
    await expect(build().step('oms', 'reconcile-orders')).resolves.toMatchObject({ verified: true });
    await expect(build({ unsynced: 3 }).step('oms', 'reconcile-orders')).rejects.toThrow('3 order(s) are not IN_SYNC with the venue');
    await expect(build({ filledNoFills: 2 }).step('oms', 'reconcile-fills')).rejects.toThrow(/2 filled order/);
    await expect(build({ openDiscrepancies: 1 }).step('oms', 'reconcile-positions')).rejects.toThrow(/unrepaired/);
  });

  it('live gate is closed by an engaged kill switch or unreconciled orders', async () => {
    await expect(build({ engaged: 1 }).step('live-gate', 'check')).rejects.toThrow(/kill switch/);
    await expect(build({ unsynced: 1 }).step('live-gate', 'check')).rejects.toThrow(/not reconciled/);
    await expect(build().step('live-gate', 'check')).resolves.toEqual({ killSwitchEngaged: false, unreconciledOrders: 0 });
  });

  it('credential verification detects incomplete credential records', async () => {
    await expect(build({ accounts: [{ id: 'a', credentialSource: 'SECRET_MANAGER', credentialRef: null }] }).step('credential', 'verify')).rejects.toThrow(/incomplete credential/);
    await expect(build().step('credential', 'verify')).resolves.toMatchObject({ verified: true, accountsChecked: 1 });
  });

  it('compliance BLOCK cases stop recovery; unknown steps are never a silent success', async () => {
    await expect(build({ blocking: 1 }).step('compliance', 'check-case')).rejects.toThrow(/BLOCK/);
    await expect(build().step('mystery', 'do-it')).rejects.toThrow('Unsupported recovery step mystery:do-it');
  });
});

import { Injectable, Logger, BadRequestException, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OperationalAuditService } from './operational-audit.service';
import { OperationsPolicyService } from './operations-policy.service';
import {
  OperationalDegradationLevel,
  deterministicIdempotencyKey,
  redactSecrets,
} from './operations.types';

/**
 * Represents controlled DEGRADED/READ_ONLY/PAUSED states for individual services or capabilities.
 * Must define allowed operations in each state and integrate with existing safety boundaries
 * instead of bypassing them.
 */

@Injectable()
export class ServiceDegradationService {
  private readonly logger = new Logger(ServiceDegradationService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly auditService: OperationalAuditService,
    private readonly policyService: OperationsPolicyService,
  ) {}

  async setDegradation(params: {
    tenantId?: string | null;
    serviceName: string;
    capability?: string | null;
    level: OperationalDegradationLevel;
    reason: string;
    requestedBy?: string | null;
    approvedBy?: string | null;
    correlationId?: string | null;
    startsAt?: Date;
    endsAt?: Date | null;
  }): Promise<any> {
    const { tenantId = null, serviceName, capability = null, level, reason, requestedBy = null, approvedBy = null, correlationId = null } = params;

    if (!serviceName) throw new BadRequestException('serviceName required');
    if (!Object.values(OperationalDegradationLevel).includes(level)) throw new BadRequestException(`Invalid degradation level ${level}`);

    const { allowed, blocked } = this.policyService.getDegradationAllowedOperations(level);

    const idempotencyKey = deterministicIdempotencyKey({
      type: `degradation:${serviceName}`,
      tenantId: tenantId ?? null,
      scope: capability ?? serviceName,
      correlationId: correlationId ?? null,
      timestampBucket: new Date().toISOString().slice(0, 13),
    });

    // Check existing active degradation for same service
    try {
      const existing = await (this.prisma as any).operationalServiceDegradation.findFirst({
        where: {
          tenantId: tenantId ?? null,
          serviceName,
          capability: capability ?? null,
          endsAt: null,
        },
        orderBy: { createdAt: 'desc' },
      });
      if (existing && existing.level === level) {
        return existing; // idempotent
      }
      if (existing) {
        // Close previous
        await (this.prisma as any).operationalServiceDegradation.update({
          where: { id: existing.id },
          data: { endsAt: new Date() },
        });
      }
    } catch {}

    const created = await (this.prisma as any).operationalServiceDegradation.create({
      data: {
        tenantId: tenantId ?? null,
        serviceName,
        capability: capability ?? null,
        level: level as any,
        previousLevel: null,
        reason: reason.slice(0, 1000),
        requestedBy: requestedBy ?? null,
        approvedBy: approvedBy ?? null,
        allowedOperations: allowed,
        blockedOperations: blocked,
        startsAt: params.startsAt ?? new Date(),
        endsAt: params.endsAt ?? null,
        correlationId: correlationId ?? null,
        idempotencyKey,
      },
    });

    await this.auditService.record({
      tenantId: tenantId ?? null,
      eventType: 'DEGRADATION_CHANGED' as any,
      actorId: requestedBy ?? null,
      actorType: requestedBy ? 'USER' : 'SYSTEM',
      targetType: 'SERVICE_DEGRADATION',
      targetId: created.id,
      evidence: redactSecrets({
        serviceName,
        capability,
        level,
        allowed,
        blocked,
        reason,
      }),
      correlationId: correlationId ?? null,
    });

    this.logger.log({
      event: 'operations.degradation.changed',
      serviceName,
      level,
      tenantId: tenantId ?? 'platform',
    });

    return created;
  }

  async getCurrentDegradation(params: {
    tenantId?: string | null;
    serviceName: string;
    capability?: string | null;
  }): Promise<any | null> {
    const where: any = {
      serviceName: params.serviceName,
      endsAt: null,
    };
    if (params.tenantId !== undefined) where.tenantId = params.tenantId;
    if (params.capability) where.capability = params.capability;
    return await (this.prisma as any).operationalServiceDegradation.findFirst({
      where,
      orderBy: { createdAt: 'desc' },
    });
  }

  async listDegradations(params: {
    tenantId?: string | null;
    serviceName?: string;
    level?: string;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId = null, serviceName, level, page = 1, limit = 20 } = params;
    const where: any = {};
    if (tenantId !== undefined && tenantId !== null) where.tenantId = tenantId;
    if (serviceName) where.serviceName = serviceName;
    if (level) where.level = level;

    const [data, total] = await Promise.all([
      (this.prisma as any).operationalServiceDegradation.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).operationalServiceDegradation.count({ where }),
    ]);
    return { data, total, page, limit };
  }

  async enforceAllowedOperation(params: {
    tenantId?: string | null;
    serviceName: string;
    capability?: string | null;
    operation: string;
  }): Promise<void> {
    const degradation = await this.getCurrentDegradation({
      tenantId: params.tenantId ?? null,
      serviceName: params.serviceName,
      capability: params.capability ?? null,
    });
    if (!degradation) return; // NORMAL

    const allowed = (degradation.allowedOperations as string[]) ?? [];
    const blocked = (degradation.blockedOperations as string[]) ?? [];

    if (blocked.includes(params.operation) || (allowed.length > 0 && !allowed.includes(params.operation))) {
      throw new BadRequestException(
        `Operation ${params.operation} blocked for service ${params.serviceName} in degradation level ${degradation.level}`,
      );
    }
  }

  async clearDegradation(params: {
    tenantId?: string | null;
    serviceName: string;
    capability?: string | null;
    actorId?: string | null;
    correlationId?: string | null;
  }): Promise<any> {
    const current = await this.getCurrentDegradation({
      tenantId: params.tenantId ?? null,
      serviceName: params.serviceName,
      capability: params.capability ?? null,
    });
    if (!current) throw new NotFoundException(`No active degradation for ${params.serviceName}`);

    const updated = await (this.prisma as any).operationalServiceDegradation.update({
      where: { id: current.id },
      data: { endsAt: new Date() },
    });

    await this.auditService.record({
      tenantId: params.tenantId ?? null,
      eventType: 'DEGRADATION_CHANGED' as any,
      actorId: params.actorId ?? null,
      actorType: params.actorId ? 'USER' : 'SYSTEM',
      targetType: 'SERVICE_DEGRADATION',
      targetId: current.id,
      evidence: redactSecrets({ serviceName: params.serviceName, previousLevel: current.level, newLevel: 'NORMAL' }),
      correlationId: params.correlationId ?? null,
    });

    return updated;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { DependencyHealthService } from './dependency-health.service';
import { OperationsPolicyService } from './operations-policy.service';
import { OperationalAuditService } from './operational-audit.service';
import {
  OperationalReadinessState,
  OperationalDependencyState,
  ReadinessResult,
  redactSecrets,
} from './operations.types';

/**
 * Evaluates platform readiness across database, Redis, queues, required configuration,
 * security controls, live-gate prerequisites, exchanges, compliance, risk, OMS, billing,
 * and other critical dependencies. Must return structured blocking reasons and evidence.
 * Never fabricate readiness.
 */

@Injectable()
export class SystemReadinessService {
  private readonly logger = new Logger(SystemReadinessService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly dependencyHealth: DependencyHealthService,
    private readonly policyService: OperationsPolicyService,
    private readonly auditService: OperationalAuditService,
  ) {}

  async evaluate(params: {
    tenantId?: string | null;
    requestedBy?: string | null;
    correlationId?: string | null;
  }): Promise<ReadinessResult> {
    const { tenantId = null, requestedBy = null, correlationId = null } = params;
    const checkedAt = new Date().toISOString();
    const policy = this.policyService.getReadinessPolicy(tenantId);

    const dependencyResults = await this.dependencyHealth.checkAll(tenantId);

    const blockingReasons: string[] = [];
    const degradedComponents: string[] = [];

    // Fail closed for unavailable critical dependencies where safety requires it
    for (const dep of dependencyResults) {
      if (dep.state === OperationalDependencyState.UNAVAILABLE || dep.state === OperationalDependencyState.MISCONFIGURED) {
        if (policy.criticalDependencies.includes(dep.dependencyType) || policy.failClosedOn.includes(dep.dependencyType)) {
          blockingReasons.push(`${dep.dependencyType}:${dep.dependencyName} is ${dep.state} ${dep.errorCode ?? ''}`.trim());
        } else if (!policy.allowedDegraded.includes(dep.dependencyType)) {
          degradedComponents.push(`${dep.dependencyType}:${dep.dependencyName}`);
        }
      } else if (dep.state === OperationalDependencyState.DEGRADED) {
        if (policy.criticalDependencies.includes(dep.dependencyType) && !policy.allowedDegraded.includes(dep.dependencyType)) {
          // Critical degraded is blocking unless explicitly allowed
          degradedComponents.push(`${dep.dependencyType}:${dep.dependencyName}`);
          if (policy.failClosedOn.includes(dep.dependencyType)) {
            blockingReasons.push(`${dep.dependencyType} degraded and fail-closed required`);
          }
        } else {
          degradedComponents.push(`${dep.dependencyType}:${dep.dependencyName}`);
        }
      } else if (dep.state === OperationalDependencyState.UNKNOWN) {
        if (policy.failClosedOn.includes(dep.dependencyType)) {
          blockingReasons.push(`${dep.dependencyType}:${dep.dependencyName} UNKNOWN and fail-closed required`);
        }
      }
    }

    // Check maintenance windows
    try {
      const now = new Date();
      const activeMaintenance = await (this.prisma as any).operationalMaintenanceWindow.findMany({
        where: {
          state: 'ACTIVE',
          scheduledStart: { lte: now },
          scheduledEnd: { gte: now },
          OR: [{ tenantId: tenantId ?? undefined }, { tenantId: null }, { scope: 'PLATFORM' }],
        },
      });
      if (activeMaintenance.length > 0) {
        blockingReasons.push(`Maintenance active: ${activeMaintenance.map((m: any) => m.title).join(', ')}`);
      }
    } catch {
      // If maintenance check fails, do not fabricate readiness — treat as degraded evidence
      degradedComponents.push('MAINTENANCE_CHECK_UNAVAILABLE');
    }

    // Check degradation
    try {
      const degradations = await (this.prisma as any).operationalServiceDegradation.findMany({
        where: {
          tenantId: tenantId ?? undefined,
          endsAt: null,
        },
        orderBy: { createdAt: 'desc' },
        take: 10,
      });
      const blockingDegradation = degradations.filter((d: any) => d.level === 'DISABLED' || d.level === 'PAUSED');
      if (blockingDegradation.length > 0) {
        blockingReasons.push(`Service degradation active: ${blockingDegradation.map((d: any) => `${d.serviceName}:${d.level}`).join(', ')}`);
      }
      degradations.forEach((d: any) => {
        if (d.level !== 'NORMAL') degradedComponents.push(`${d.serviceName}:${d.level}`);
      });
    } catch {
      // No degradation table yet is not blocking
    }

    let state: OperationalReadinessState;
    let isReady: boolean;

    if (blockingReasons.length > 0) {
      state = OperationalReadinessState.NOT_READY;
      isReady = false;
    } else if (degradedComponents.length > 0) {
      state = OperationalReadinessState.DEGRADED;
      isReady = true; // Degraded but still ready for limited operations
    } else {
      state = OperationalReadinessState.READY;
      isReady = true;
    }

    // If maintenance is active for this tenant/platform, override to MAINTENANCE unless NOT_READY already
    if (state !== OperationalReadinessState.NOT_READY) {
      try {
        const maintenanceActive = await (this.prisma as any).operationalMaintenanceWindow.findFirst({
          where: {
            state: 'ACTIVE',
            OR: [{ tenantId: tenantId ?? undefined }, { tenantId: null }],
          },
        });
        if (maintenanceActive) {
          state = OperationalReadinessState.MAINTENANCE;
          isReady = false;
        }
      } catch {}
    }

    const result: ReadinessResult = {
      state,
      isReady,
      blockingReasons,
      degradedComponents,
      evidence: redactSecrets({
        policyVersion: this.policyService.getPolicyVersion(),
        dependencyCount: dependencyResults.length,
        blockingCount: blockingReasons.length,
        degradedCount: degradedComponents.length,
        tenantId: tenantId ?? 'platform',
      }),
      dependencyResults,
      checkedAt,
      tenantId: tenantId ?? null,
      correlationId: correlationId ?? null,
    };

    // Audit immutable record
    await this.auditService.record({
      tenantId: tenantId ?? null,
      eventType: 'READINESS_CHECK' as any,
      actorId: requestedBy ?? null,
      actorType: requestedBy ? 'USER' : 'SYSTEM',
      targetType: 'READINESS',
      targetId: tenantId ?? 'platform',
      evidence: redactSecrets({
        state,
        isReady,
        blockingReasons,
        degradedComponents,
        dependencyResults: dependencyResults.map((d) => ({ type: d.dependencyType, state: d.state, isCritical: d.isCritical })),
        correlationId,
      }),
      correlationId: correlationId ?? null,
    });

    // Persist readiness check history
    try {
      await (this.prisma as any).operationalReadinessCheck.create({
        data: {
          tenantId: tenantId ?? null,
          state: state as any,
          isReady,
          blockingReasons,
          degradedComponents,
          evidence: redactSecrets(result.evidence) as any,
          requestedBy: requestedBy ?? null,
          correlationId: correlationId ?? null,
          checkedAt: new Date(checkedAt),
        },
      });
    } catch (e) {
      this.logger.warn(`Failed to persist readiness check: ${(e as Error).message}`);
    }

    this.logger.log({
      event: 'operations.readiness.evaluated',
      tenantId: tenantId ?? 'platform',
      state,
      isReady,
      blockingReasons: blockingReasons.length,
    });

    return result;
  }

  async getLatest(tenantId?: string | null): Promise<any | null> {
    const where = tenantId ? { tenantId } : { tenantId: null };
    return await (this.prisma as any).operationalReadinessCheck.findFirst({
      where,
      orderBy: { checkedAt: 'desc' },
    });
  }
}

