import { Injectable, Logger, BadRequestException, NotFoundException } from '@nestjs/common';
import { PartnerAgreement, PartnerAgreementState, PARTNER_AGREEMENT_TRANSITIONS, PartnerAuditAction, PartnerPolicy } from './partner.types';
import { PartnerPolicyService } from './partner-policy.service';
import { PartnerAuditService } from './partner-audit.service';
import { PartnerProfileService } from './partner-profile.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

@Injectable()
export class PartnerAgreementService {
  private readonly logger = new Logger(PartnerAgreementService.name);
  private readonly inMemory: Map<string, PartnerAgreement> = new Map();

  constructor(
    private readonly policyService: PartnerPolicyService,
    private readonly audit: PartnerAuditService,
    private readonly profileService: PartnerProfileService,
    private readonly prisma: PrismaService,
  ) {}

  async createAgreement(params: {
    partnerId: string;
    commissionPolicy: PartnerPolicy;
    pricingRules: any[];
    payoutTerms: any;
    attributionRules: any[];
    effectiveFrom: string;
    effectiveTo?: string | null;
    jurisdiction?: string | null;
    responsibilities: string[];
    terminationClause?: string | null;
    createdBy: string;
    correlationId: string;
  }): Promise<PartnerAgreement> {
    if (!params.partnerId || !params.commissionPolicy || !params.effectiveFrom) {
      throw new BadRequestException('partnerId, commissionPolicy, effectiveFrom required');
    }

    const profile = await this.profileService.getProfile(params.partnerId);
    // Historical agreements immutable - new version
    const existingActive = [...this.inMemory.values()].filter(a => a.partnerId === params.partnerId && a.state === PartnerAgreementState.ACTIVE);
    const nextVersion = existingActive.length > 0 ? Math.max(...[...this.inMemory.values()].filter(a => a.partnerId === params.partnerId).map(a => a.version), 0) + 1 : 1;

    try {
      const rows = await (this.prisma as any).partnerAgreement?.findMany?.({ where: { partnerId: params.partnerId }, orderBy: { version: 'desc' }, take: 1 });
      if (rows && rows.length > 0) {
        const maxV = rows[0].version;
        if (maxV >= nextVersion) {
          // adjust
        }
      }
    } catch {}

    const effectiveFrom = new Date(params.effectiveFrom);
    if (isNaN(effectiveFrom.getTime())) throw new BadRequestException('invalid effectiveFrom');
    if (params.effectiveTo) {
      const effectiveTo = new Date(params.effectiveTo);
      if (isNaN(effectiveTo.getTime()) || effectiveTo <= effectiveFrom) throw new BadRequestException('effectiveTo must be after effectiveFrom');
    }

    if (!params.commissionPolicy.commissionRates || params.commissionPolicy.commissionRates.length === 0) {
      throw new BadRequestException('commissionRates required - never invent rates');
    }

    const agreement: PartnerAgreement = {
      id: `pagr_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      partnerId: params.partnerId,
      version: nextVersion,
      state: PartnerAgreementState.DRAFT,
      commissionPolicy: params.commissionPolicy,
      pricingRules: params.pricingRules ?? [],
      payoutTerms: params.payoutTerms,
      attributionRules: params.attributionRules ?? [],
      effectiveFrom: effectiveFrom.toISOString(),
      effectiveTo: params.effectiveTo ? new Date(params.effectiveTo).toISOString() : null,
      jurisdiction: params.jurisdiction ?? null,
      responsibilities: params.responsibilities,
      terminationClause: params.terminationClause ?? null,
      createdBy: params.createdBy,
      approvedBy: null,
      activatedAt: null,
      supersededAt: null,
      terminatedAt: null,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      previousVersionId: existingActive.length > 0 ? existingActive[0].id : null,
      isImmutable: false,
    };

    this.inMemory.set(agreement.id, agreement);
    try {
      await (this.prisma as any).partnerAgreement?.create?.({
        data: {
          id: agreement.id,
          partnerId: agreement.partnerId,
          version: agreement.version,
          state: agreement.state,
          commissionPolicy: agreement.commissionPolicy as any,
          pricingRules: agreement.pricingRules as any,
          payoutTerms: agreement.payoutTerms as any,
          attributionRules: agreement.attributionRules as any,
          effectiveFrom: new Date(agreement.effectiveFrom),
          effectiveTo: agreement.effectiveTo ? new Date(agreement.effectiveTo) : null,
          jurisdiction: agreement.jurisdiction,
          responsibilities: agreement.responsibilities,
          terminationClause: agreement.terminationClause,
          createdBy: agreement.createdBy,
          createdAt: new Date(agreement.createdAt),
          updatedAt: new Date(agreement.updatedAt),
          previousVersionId: agreement.previousVersionId,
          isImmutable: false,
        },
      });
    } catch {
      this.logger.debug(`agreement persist skipped id=${agreement.id}`);
    }

    await this.audit.recordEvent({
      partnerId: params.partnerId,
      actorId: params.createdBy,
      action: PartnerAuditAction.AGREEMENT_CREATED,
      source: 'PARTNER_AGREEMENT_SERVICE',
      correlationId: params.correlationId,
      agreementVersion: `v${agreement.version}`,
      policyVersion: params.commissionPolicy.policyVersion,
      safeEvidence: { version: agreement.version, state: agreement.state },
    });

    this.logger.log(`agreement created id=${agreement.id} partner=${params.partnerId} v=${agreement.version} corr=${params.correlationId}`);
    return agreement;
  }

  async transitionState(params: {
    agreementId: string;
    partnerId: string;
    targetState: PartnerAgreementState;
    correlationId: string;
    actorId: string;
    actorRole?: string;
  }): Promise<PartnerAgreement> {
    const agreement = await this.getAgreement(params.agreementId, params.partnerId);
    if (agreement.isImmutable && params.targetState !== PartnerAgreementState.TERMINATED && params.targetState !== PartnerAgreementState.SUPERSEDED) {
      throw new BadRequestException('historical agreement immutable');
    }
    const allowed = PARTNER_AGREEMENT_TRANSITIONS[agreement.state];
    if (!allowed.includes(params.targetState)) throw new BadRequestException(`invalid transition ${agreement.state} -> ${params.targetState}`);

    const prev = agreement.state;
    agreement.state = params.targetState;
    agreement.updatedAt = new Date().toISOString();

    if (params.targetState === PartnerAgreementState.APPROVED) agreement.approvedBy = params.actorId;
    if (params.targetState === PartnerAgreementState.ACTIVE) {
      agreement.activatedAt = new Date().toISOString();
      agreement.isImmutable = false;
      // Supersede previous active agreements
      for (const other of [...this.inMemory.values()].filter(a => a.partnerId === params.partnerId && a.id !== agreement.id && a.state === PartnerAgreementState.ACTIVE)) {
        other.state = PartnerAgreementState.SUPERSEDED;
        other.supersededAt = new Date().toISOString();
        other.isImmutable = true;
        other.updatedAt = new Date().toISOString();
        this.inMemory.set(other.id, other);
        try {
          await (this.prisma as any).partnerAgreement?.update?.({ where: { id: other.id }, data: { state: other.state, supersededAt: new Date(other.supersededAt), isImmutable: true, updatedAt: new Date(other.updatedAt) } });
        } catch {}
      }
    }
    if (params.targetState === PartnerAgreementState.SUPERSEDED) {
      agreement.supersededAt = new Date().toISOString();
      agreement.isImmutable = true;
    }
    if (params.targetState === PartnerAgreementState.TERMINATED) {
      agreement.terminatedAt = new Date().toISOString();
      agreement.isImmutable = true;
    }

    this.inMemory.set(agreement.id, agreement);
    try {
      await (this.prisma as any).partnerAgreement?.update?.({
        where: { id: agreement.id },
        data: {
          state: agreement.state,
          approvedBy: agreement.approvedBy,
          activatedAt: agreement.activatedAt ? new Date(agreement.activatedAt) : null,
          supersededAt: agreement.supersededAt ? new Date(agreement.supersededAt) : null,
          terminatedAt: agreement.terminatedAt ? new Date(agreement.terminatedAt) : null,
          isImmutable: agreement.isImmutable,
          updatedAt: new Date(agreement.updatedAt),
        },
      });
    } catch {
      this.logger.debug(`agreement transition persist skipped id=${agreement.id}`);
    }

    const auditMap: Record<PartnerAgreementState, PartnerAuditAction> = {
      [PartnerAgreementState.DRAFT]: PartnerAuditAction.AGREEMENT_CREATED,
      [PartnerAgreementState.REVIEW]: PartnerAuditAction.AGREEMENT_CREATED,
      [PartnerAgreementState.APPROVED]: PartnerAuditAction.AGREEMENT_APPROVED,
      [PartnerAgreementState.ACTIVE]: PartnerAuditAction.AGREEMENT_ACTIVATED,
      [PartnerAgreementState.SUPERSEDED]: PartnerAuditAction.AGREEMENT_SUPERSEDED,
      [PartnerAgreementState.TERMINATED]: PartnerAuditAction.AGREEMENT_TERMINATED,
    };

    await this.audit.recordEvent({
      partnerId: params.partnerId,
      actorId: params.actorId,
      actorRole: params.actorRole,
      action: auditMap[params.targetState],
      source: 'PARTNER_AGREEMENT_SERVICE',
      correlationId: params.correlationId,
      agreementVersion: `v${agreement.version}`,
      policyVersion: agreement.commissionPolicy.policyVersion,
      safeEvidence: { from: prev, to: params.targetState, version: agreement.version },
    });

    this.logger.log(`agreement transition id=${agreement.id} ${prev} -> ${params.targetState} corr=${params.correlationId}`);
    return agreement;
  }

  async getAgreement(agreementId: string, partnerId: string): Promise<PartnerAgreement> {
    const mem = this.inMemory.get(agreementId);
    if (mem) {
      if (mem.partnerId !== partnerId) throw new BadRequestException('partner isolation violation');
      return mem;
    }
    try {
      const row = await (this.prisma as any).partnerAgreement?.findUnique?.({ where: { id: agreementId } });
      if (row) {
        if (row.partnerId !== partnerId) throw new BadRequestException('partner isolation violation');
        const mapped = this.mapRow(row);
        this.inMemory.set(mapped.id, mapped);
        return mapped;
      }
    } catch {}
    throw new NotFoundException(`agreement ${agreementId} not found`);
  }

  async getActiveAgreement(partnerId: string): Promise<PartnerAgreement | null> {
    const active = [...this.inMemory.values()].find(a => a.partnerId === partnerId && a.state === PartnerAgreementState.ACTIVE);
    if (active) return active;
    try {
      const row = await (this.prisma as any).partnerAgreement?.findFirst?.({ where: { partnerId, state: 'ACTIVE' }, orderBy: { version: 'desc' } });
      if (row) return this.mapRow(row);
    } catch {}
    return null;
  }

  async listAgreements(partnerId: string): Promise<PartnerAgreement[]> {
    let list = [...this.inMemory.values()].filter(a => a.partnerId === partnerId);
    list = list.sort((a, b) => b.version - a.version);
    try {
      const rows = await (this.prisma as any).partnerAgreement?.findMany?.({ where: { partnerId }, orderBy: { version: 'desc' }, take: 100 });
      if (rows && rows.length > 0) list = rows.map((r: any) => this.mapRow(r));
    } catch {}
    return list;
  }

  private mapRow(row: any): PartnerAgreement {
    return {
      id: row.id,
      partnerId: row.partnerId,
      version: row.version,
      state: row.state,
      commissionPolicy: row.commissionPolicy,
      pricingRules: row.pricingRules ?? [],
      payoutTerms: row.payoutTerms,
      attributionRules: row.attributionRules ?? [],
      effectiveFrom: row.effectiveFrom instanceof Date ? row.effectiveFrom.toISOString() : row.effectiveFrom,
      effectiveTo: row.effectiveTo ? (row.effectiveTo instanceof Date ? row.effectiveTo.toISOString() : row.effectiveTo) : null,
      jurisdiction: row.jurisdiction ?? null,
      responsibilities: row.responsibilities ?? [],
      terminationClause: row.terminationClause ?? null,
      createdBy: row.createdBy,
      approvedBy: row.approvedBy ?? null,
      activatedAt: row.activatedAt ? (row.activatedAt instanceof Date ? row.activatedAt.toISOString() : row.activatedAt) : null,
      supersededAt: row.supersededAt ? (row.supersededAt instanceof Date ? row.supersededAt.toISOString() : row.supersededAt) : null,
      terminatedAt: row.terminatedAt ? (row.terminatedAt instanceof Date ? row.terminatedAt.toISOString() : row.terminatedAt) : null,
      createdAt: row.createdAt instanceof Date ? row.createdAt.toISOString() : row.createdAt,
      updatedAt: row.updatedAt instanceof Date ? row.updatedAt.toISOString() : row.updatedAt,
      previousVersionId: row.previousVersionId ?? null,
      isImmutable: !!row.isImmutable,
    };
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PartnerProfileService } from './partner-profile.service';
import { PartnerTenantService } from './partner-tenant.service';
import { PartnerCommissionLedgerService } from './partner-commission-ledger.service';
import { PartnerPerformanceService } from './partner-performance.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

export interface TimeSeriesPoint {
  period: string;
  periodStart: string;
  periodEnd: string;
  grossRevenue: string;
  netEligibleRevenue: string;
  commissionAccrued: string;
  commissionReversed: string;
  commissionPayable: string;
  newTenants: number;
  activeTenants: number;
  churnedTenants: number;
  activeSubscriptions: number;
  refunds: number;
  chargebacks: number;
}

export interface PartnerAnalytics {
  partnerId: string;
  granularity: 'DAILY' | 'WEEKLY' | 'MONTHLY' | 'QUARTERLY' | 'LIFETIME';
  currency: string;
  periodStart: string;
  periodEnd: string;
  timeSeries: TimeSeriesPoint[];
  cohortByPlan: Array<{ planCode: string; tenantCount: number; revenue: string; commission: string }>;
  cohortByCampaign: Array<{ campaignId: string; tenantCount: number; revenue: string; commission: string }>;
  generatedAt: string;
  calculationVersion: string;
}

@Injectable()
export class PartnerAnalyticsService {
  private readonly logger = new Logger(PartnerAnalyticsService.name);

  constructor(
    private readonly profileService: PartnerProfileService,
    private readonly tenantService: PartnerTenantService,
    private readonly commissionLedger: PartnerCommissionLedgerService,
    private readonly performanceService: PartnerPerformanceService,
    private readonly prisma: PrismaService,
  ) {}

  async getAnalytics(params: {
    partnerId: string;
    granularity: 'DAILY' | 'WEEKLY' | 'MONTHLY' | 'QUARTERLY' | 'LIFETIME';
    periodStart: string;
    periodEnd: string;
    currency?: string;
    correlationId: string;
  }): Promise<PartnerAnalytics> {
    if (!params.partnerId || !params.periodStart || !params.periodEnd) throw new BadRequestException('partnerId, periodStart, periodEnd required');
    await this.profileService.getProfile(params.partnerId);

    const currency = (params.currency ?? 'USD').toUpperCase();
    const periodStart = new Date(params.periodStart);
    const periodEnd = new Date(params.periodEnd);
    if (isNaN(periodStart.getTime()) || isNaN(periodEnd.getTime()) || periodStart >= periodEnd) throw new BadRequestException('invalid period');

    // No floating-point financial aggregation, no silent cross-currency summation
    const commissions = await this.commissionLedger.listCommissions(params.partnerId, { currency });
    const relationships = await this.tenantService.listTenantsForPartner(params.partnerId);

    const timeSeries = this.buildTimeSeries({
      granularity: params.granularity,
      periodStart,
      periodEnd,
      commissions,
      relationships,
      currency,
    });

    const cohortByPlan = await this.buildPlanCohort(params.partnerId, commissions, relationships, currency);
    const cohortByCampaign = await this.buildCampaignCohort(params.partnerId, commissions, relationships, currency);

    const analytics: PartnerAnalytics = {
      partnerId: params.partnerId,
      granularity: params.granularity,
      currency,
      periodStart: periodStart.toISOString(),
      periodEnd: periodEnd.toISOString(),
      timeSeries,
      cohortByPlan,
      cohortByCampaign,
      generatedAt: new Date().toISOString(),
      calculationVersion: '2026-01',
    };

    this.logger.log(`analytics generated partner=${params.partnerId} granularity=${params.granularity} points=${timeSeries.length} corr=${params.correlationId}`);
    return analytics;
  }

  private buildTimeSeries(params: {
    granularity: string;
    periodStart: Date;
    periodEnd: Date;
    commissions: any[];
    relationships: any[];
    currency: string;
  }): TimeSeriesPoint[] {
    const points: TimeSeriesPoint[] = [];
    const intervals = this.generateIntervals(params.granularity as any, params.periodStart, params.periodEnd);

    for (const interval of intervals) {
      const commissionsInInterval = params.commissions.filter(c => {
        const accrued = new Date(c.accruedAt);
        return accrued >= interval.start && accrued <= interval.end && c.currency.toUpperCase() === params.currency;
      });

      let gross = '0';
      let netEligible = '0';
      let accrued = '0';
      let reversed = '0';
      let refunds = 0;
      let chargebacks = 0;

      for (const com of commissionsInInterval) {
        gross = this.addDecimal(gross, com.grossRevenue, params.currency);
        netEligible = this.addDecimal(netEligible, com.netEligibleRevenue, params.currency);
        if (['ACCRUED', 'SETTLED', 'PAID', 'PAYOUT_PENDING'].includes(com.state)) {
          accrued = this.addDecimal(accrued, com.commissionAmount, params.currency);
        } else if (com.state === 'REVERSED') {
          reversed = this.addDecimal(reversed, com.commissionAmount, params.currency);
          if (com.sourceEventType === 'REFUND') refunds++;
          if (com.sourceEventType === 'CHARGEBACK') chargebacks++;
        }
      }

      const payable = this.addDecimal(accrued, reversed, params.currency);

      const newTenants = params.relationships.filter(r => {
        const assigned = new Date(r.assignedAt);
        return assigned >= interval.start && assigned <= interval.end;
      }).length;

      const activeTenants = params.relationships.filter(r => {
        const assigned = new Date(r.assignedAt);
        const terminated = r.terminatedAt ? new Date(r.terminatedAt) : null;
        return assigned <= interval.end && (!terminated || terminated > interval.end) && r.state === 'ACTIVE';
      }).length;

      const churnedTenants = params.relationships.filter(r => {
        if (!r.terminatedAt) return false;
        const terminated = new Date(r.terminatedAt);
        return terminated >= interval.start && terminated <= interval.end;
      }).length;

      points.push({
        period: interval.label,
        periodStart: interval.start.toISOString(),
        periodEnd: interval.end.toISOString(),
        grossRevenue: gross,
        netEligibleRevenue: netEligible,
        commissionAccrued: accrued,
        commissionReversed: reversed,
        commissionPayable: payable,
        newTenants,
        activeTenants,
        churnedTenants,
        activeSubscriptions: activeTenants, // simplified
        refunds,
        chargebacks,
      });
    }

    return points;
  }

  private async buildPlanCohort(partnerId: string, commissions: any[], relationships: any[], currency: string) {
    const map = new Map<string, { tenantCount: Set<string>; revenue: string; commission: string }>();
    for (const com of commissions) {
      if (com.currency.toUpperCase() !== currency) continue; // no silent cross-currency summation
      // Try to resolve plan from subscription
      const planCode = 'UNKNOWN';
      if (!map.has(planCode)) map.set(planCode, { tenantCount: new Set(), revenue: '0', commission: '0' });
      const entry = map.get(planCode)!;
      entry.tenantCount.add(com.tenantId);
      entry.revenue = this.addDecimal(entry.revenue, com.netEligibleRevenue, currency);
      if (['ACCRUED', 'SETTLED', 'PAID'].includes(com.state)) {
        entry.commission = this.addDecimal(entry.commission, com.commissionAmount, currency);
      }
    }
    return [...map.entries()].map(([planCode, data]) => ({
      planCode,
      tenantCount: data.tenantCount.size,
      revenue: data.revenue,
      commission: data.commission,
    }));
  }

  private async buildCampaignCohort(partnerId: string, commissions: any[], relationships: any[], currency: string) {
    const map = new Map<string, { tenantCount: Set<string>; revenue: string; commission: string }>();
    for (const rel of relationships) {
      const campaignId = rel.campaignId ?? 'DIRECT';
      if (!map.has(campaignId)) map.set(campaignId, { tenantCount: new Set(), revenue: '0', commission: '0' });
      map.get(campaignId)!.tenantCount.add(rel.tenantId);
    }
    for (const com of commissions) {
      if (com.currency.toUpperCase() !== currency) continue;
      // Find relationship for tenant to get campaign
      const rel = relationships.find(r => r.tenantId === com.tenantId);
      const campaignId = rel?.campaignId ?? 'DIRECT';
      if (!map.has(campaignId)) map.set(campaignId, { tenantCount: new Set(), revenue: '0', commission: '0' });
      const entry = map.get(campaignId)!;
      entry.revenue = this.addDecimal(entry.revenue, com.netEligibleRevenue, currency);
      if (['ACCRUED', 'SETTLED', 'PAID'].includes(com.state)) {
        entry.commission = this.addDecimal(entry.commission, com.commissionAmount, currency);
      }
    }
    return [...map.entries()].map(([campaignId, data]) => ({
      campaignId,
      tenantCount: data.tenantCount.size,
      revenue: data.revenue,
      commission: data.commission,
    }));
  }

  private generateIntervals(granularity: 'DAILY' | 'WEEKLY' | 'MONTHLY' | 'QUARTERLY' | 'LIFETIME', start: Date, end: Date): Array<{ start: Date; end: Date; label: string }> {
    const intervals: Array<{ start: Date; end: Date; label: string }> = [];
    if (granularity === 'LIFETIME') {
      intervals.push({ start, end, label: 'LIFETIME' });
      return intervals;
    }

    let current = new Date(start);
    while (current < end) {
      let next: Date;
      let label: string;
      switch (granularity) {
        case 'DAILY':
          next = new Date(current.getTime() + 24 * 3600000);
          label = current.toISOString().slice(0, 10);
          break;
        case 'WEEKLY':
          next = new Date(current.getTime() + 7 * 24 * 3600000);
          label = `W${current.toISOString().slice(0, 10)}`;
          break;
        case 'MONTHLY':
          next = new Date(current.getFullYear(), current.getMonth() + 1, 1);
          label = `${current.getFullYear()}-${String(current.getMonth() + 1).padStart(2, '0')}`;
          break;
        case 'QUARTERLY':
          const quarter = Math.floor(current.getMonth() / 3) + 1;
          next = new Date(current.getFullYear(), quarter * 3, 1);
          label = `${current.getFullYear()}-Q${quarter}`;
          break;
        default:
          next = new Date(current.getTime() + 24 * 3600000);
          label = current.toISOString().slice(0, 10);
      }
      if (next > end) next = new Date(end);
      intervals.push({ start: new Date(current), end: new Date(next), label });
      current = next;
    }
    return intervals;
  }

  private getMinorUnit(currency: string): number {
    const map: Record<string, number> = { USD: 2, EUR: 2, GBP: 2, JPY: 0, USDT: 6, USDC: 6 };
    return map[currency.toUpperCase()] ?? 2;
  }

  private toMinorUnits(amount: string, currency: string): bigint {
    const minor = this.getMinorUnit(currency);
    const factor = Math.pow(10, minor);
    const parts = amount.toString().split('.');
    const intPart = BigInt(parts[0] || '0');
    let frac = parts[1] || '';
    if (frac.length > minor) frac = frac.slice(0, minor);
    while (frac.length < minor) frac += '0';
    const fracPart = BigInt(frac || '0');
    if (intPart < BigInt(0)) return intPart * BigInt(factor) - fracPart;
    return intPart * BigInt(factor) + fracPart;
  }

  private fromMinorUnits(minor: bigint, currency: string): string {
    const minorUnit = this.getMinorUnit(currency);
    const factor = BigInt(Math.pow(10, minorUnit));
    const isNegative = minor < BigInt(0);
    const abs = isNegative ? -minor : minor;
    const intPart = abs / factor;
    const fracPart = abs % factor;
    let fracStr = fracPart.toString().padStart(minorUnit, '0');
    if (minorUnit > 0) {
      fracStr = fracStr.replace(/0+$/, '');
      if (fracStr === '') fracStr = '0'.repeat(Math.min(2, minorUnit));
    }
    const result = minorUnit === 0 ? intPart.toString() : `${intPart.toString()}.${fracStr}`;
    return isNegative ? `-${result}` : result;
  }

  private addDecimal(a: string, b: string, currency: string): string {
    return this.fromMinorUnits(this.toMinorUnits(a, currency) + this.toMinorUnits(b, currency), currency);
  }
}

// # Responsibility: verifies attribution idempotency, durable persistence, and fail-closed handling of storage failures.
import { ServiceUnavailableException } from '@nestjs/common';
import { PartnerAttributionService } from './partner-attribution.service';
import { PartnerAttributionState } from './partner.types';

describe('PartnerAttributionService durable attribution', () => {
  function buildService(options?: { findFirst?: jest.Mock; findMany?: jest.Mock; create?: jest.Mock }) {
    const prisma = {
      partnerAttribution: {
        findFirst: options?.findFirst ?? jest.fn(async () => null),
        findMany: options?.findMany ?? jest.fn(async () => []),
        create: options?.create ?? jest.fn(async ({ data }) => data),
      },
    };
    const policyService = {};
    const agreementService = {
      getActiveAgreement: jest.fn(async () => ({
        version: 2,
        commissionPolicy: { attributionWindowHours: 720, policyVersion: 'policy-v2' },
      })),
    };
    const audit = { recordEvent: jest.fn(async () => undefined) };
    const profileService = { getProfile: jest.fn(async () => ({ ownerUserId: 'partner-owner' })) };
    const referralService = {};
    const tenantService = { getPrimaryPartnerForTenant: jest.fn(async () => null) };
    const service = new PartnerAttributionService(
      policyService as any,
      agreementService as any,
      audit as any,
      profileService as any,
      referralService as any,
      tenantService as any,
      prisma as any,
    );
    return { service, prisma, agreementService, audit };
  }

  function input(idempotencyKey = 'attrib-idem-1') {
    return {
      partnerId: 'partner-a',
      tenantId: 'tenant-a',
      attributionSource: 'TENANT_PROVISIONING',
      capturedAt: new Date().toISOString(),
      createdBy: 'operator-a',
      correlationId: 'corr-a',
      idempotencyKey,
    };
  }

  test('returns an attribution only after the canonical database row is created', async () => {
    const { service, prisma, audit } = buildService();

    const result = await service.attributeTenant(input());

    expect(prisma.partnerAttribution.create).toHaveBeenCalledWith(expect.objectContaining({
      data: expect.objectContaining({
        partnerId: 'partner-a',
        tenantId: 'tenant-a',
        state: PartnerAttributionState.ACTIVE,
        idempotencyKey: 'attrib-idem-1',
      }),
    }));
    expect(result).toMatchObject({
      partnerId: 'partner-a',
      tenantId: 'tenant-a',
      state: PartnerAttributionState.ACTIVE,
      idempotencyKey: 'attrib-idem-1',
    });
    expect(audit.recordEvent).toHaveBeenCalledWith(expect.objectContaining({
      action: 'REFERRAL_ATTRIBUTED',
      tenantId: 'tenant-a',
      safeEvidence: expect.objectContaining({ attributionId: result.id }),
    }));
  });

  test('returns a prior durable attribution for an idempotent retry without creating a duplicate', async () => {
    const now = new Date();
    const persisted = {
      id: 'persisted-attribution',
      partnerId: 'partner-a',
      tenantId: 'tenant-a',
      campaignId: null,
      referralCode: null,
      referralToken: null,
      attributionSource: 'TENANT_PROVISIONING',
      attributionWindowHours: 720,
      capturedAt: now,
      effectiveAt: now,
      expiresAt: new Date(now.getTime() + 60_000),
      agreementVersion: 'v2',
      policyVersion: 'policy-v2',
      state: PartnerAttributionState.ACTIVE,
      isPrimary: true,
      createdAt: now,
      updatedAt: now,
      idempotencyKey: 'attrib-idem-1',
    };
    const findFirst = jest.fn(async () => persisted);
    const create = jest.fn();
    const { service, audit } = buildService({ findFirst, create });

    const result = await service.attributeTenant(input());

    expect(findFirst).toHaveBeenCalledWith({ where: { tenantId: 'tenant-a', idempotencyKey: 'attrib-idem-1' } });
    expect(result.id).toBe('persisted-attribution');
    expect(create).not.toHaveBeenCalled();
    expect(audit.recordEvent).not.toHaveBeenCalled();
  });

  test('resolves a concurrent same-tenant insert conflict as an idempotent replay', async () => {
    const now = new Date();
    const persisted = {
      id: 'concurrent-attribution',
      partnerId: 'partner-a',
      tenantId: 'tenant-a',
      campaignId: null,
      referralCode: null,
      referralToken: null,
      attributionSource: 'TENANT_PROVISIONING',
      attributionWindowHours: 720,
      capturedAt: now,
      effectiveAt: now,
      expiresAt: new Date(now.getTime() + 60_000),
      agreementVersion: 'v2',
      policyVersion: 'policy-v2',
      state: PartnerAttributionState.ACTIVE,
      isPrimary: true,
      createdAt: now,
      updatedAt: now,
      idempotencyKey: 'race-idem-key',
    };
    const findFirst = jest.fn()
      .mockResolvedValueOnce(null)
      .mockResolvedValueOnce(persisted);
    const create = jest.fn(async () => { throw Object.assign(new Error('unique conflict'), { code: 'P2002' }); });
    const { service, audit } = buildService({ findFirst, create });

    const result = await service.attributeTenant(input('race-idem-key'));

    expect(findFirst).toHaveBeenNthCalledWith(1, { where: { tenantId: 'tenant-a', idempotencyKey: 'race-idem-key' } });
    expect(findFirst).toHaveBeenNthCalledWith(2, { where: { tenantId: 'tenant-a', idempotencyKey: 'race-idem-key' } });
    expect(result.id).toBe('concurrent-attribution');
    expect(audit.recordEvent).not.toHaveBeenCalled();
  });

  test('does not return another tenant attribution for the same client idempotency key', async () => {
    const findFirst = jest.fn(async ({ where }: { where: { tenantId: string } }) => (
      where.tenantId === 'tenant-a' ? { id: 'foreign-attribution', partnerId: 'partner-a', tenantId: 'tenant-a' } : null
    ));
    const create = jest.fn(async ({ data }) => data);
    const { service } = buildService({ findFirst, create });

    const result = await service.attributeTenant({ ...input('shared-client-key'), tenantId: 'tenant-b' });

    expect(findFirst).toHaveBeenCalledWith({ where: { tenantId: 'tenant-b', idempotencyKey: 'shared-client-key' } });
    expect(create).toHaveBeenCalledWith(expect.objectContaining({ data: expect.objectContaining({ tenantId: 'tenant-b' }) }));
    expect(result.tenantId).toBe('tenant-b');
  });

  test('fails closed without audit success when idempotency storage is unavailable', async () => {
    const findFirst = jest.fn(async () => { throw new Error('database unavailable'); });
    const create = jest.fn();
    const { service, audit } = buildService({ findFirst, create });

    await expect(service.attributeTenant(input())).rejects.toBeInstanceOf(ServiceUnavailableException);
    expect(create).not.toHaveBeenCalled();
    expect(audit.recordEvent).not.toHaveBeenCalled();
  });

  test('fails closed when attribution insert is unavailable and does not cache an unpersisted claim', async () => {
    const create = jest.fn(async () => { throw new Error('database unavailable'); });
    const findMany = jest.fn(async () => []);
    const { service, audit } = buildService({ create, findMany });

    await expect(service.attributeTenant(input())).rejects.toBeInstanceOf(ServiceUnavailableException);
    expect(audit.recordEvent).not.toHaveBeenCalled();
    await expect(service.listAttributionsForPartner('partner-a')).resolves.toEqual([]);
  });
});

import { Injectable, Logger } from '@nestjs/common';
import { PartnerAuditAction, PartnerAuditEvent } from './partner.types';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

@Injectable()
export class PartnerAuditService {
  private readonly logger = new Logger(PartnerAuditService.name);
  private readonly inMemory: PartnerAuditEvent[] = [];

  constructor(private readonly prisma: PrismaService) {}

  async recordEvent(params: {
    partnerId: string;
    tenantId?: string | null;
    actorId: string;
    actorRole?: string | null;
    action: PartnerAuditAction;
    source: string;
    correlationId: string;
    agreementVersion?: string | null;
    policyVersion?: string | null;
    safeEvidence?: Record<string, unknown>;
  }): Promise<PartnerAuditEvent> {
    const redacted = this.redactEvidence(params.safeEvidence ?? {});

    const event: PartnerAuditEvent = {
      id: `paud_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      partnerId: params.partnerId,
      tenantId: params.tenantId ?? null,
      actorId: params.actorId,
      actorRole: params.actorRole ?? null,
      action: params.action,
      source: params.source,
      correlationId: params.correlationId,
      agreementVersion: params.agreementVersion ?? null,
      policyVersion: params.policyVersion ?? null,
      timestamp: new Date().toISOString(),
      safeEvidence: redacted,
      createdAt: new Date().toISOString(),
    };

    this.inMemory.push(event);
    if (this.inMemory.length > 5000) this.inMemory.splice(0, 1000);

    try {
      await (this.prisma as any).partnerAudit?.create?.({
        data: {
          id: event.id,
          partnerId: event.partnerId,
          tenantId: event.tenantId,
          actorId: event.actorId,
          actorRole: event.actorRole,
          action: event.action,
          source: event.source,
          correlationId: event.correlationId,
          agreementVersion: event.agreementVersion,
          policyVersion: event.policyVersion,
          timestamp: new Date(event.timestamp),
          safeEvidence: redacted as any,
          createdAt: new Date(event.createdAt),
        },
      });
    } catch {
      this.logger.debug(`partner audit persist skipped id=${event.id}`);
    }

    this.logger.log(`audit partner=${params.partnerId} action=${params.action} corr=${params.correlationId}`);
    return event;
  }

  private redactEvidence(evidence: Record<string, unknown>): Record<string, unknown> {
    const sensitive = ['password', 'secret', 'privateKey', 'apiKey', 'token', 'card', 'cvv', 'ssn', 'email', 'phone', 'address', 'government_id', 'kyc_doc', 'credential', 'signingSecret', 'private_key', 'jwt', 'bearer', 'iban', 'accountNumber'];
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(evidence)) {
      const lower = k.toLowerCase();
      const isSensitive = sensitive.some(s => lower.includes(s.toLowerCase()));
      if (isSensitive) out[k] = '***REDACTED***';
      else if (typeof v === 'string' && v.length > 500) out[k] = v.slice(0, 500) + '...TRUNCATED';
      else out[k] = v;
    }
    return out;
  }

  async listEvents(partnerId: string, filters?: { tenantId?: string; action?: PartnerAuditAction; correlationId?: string; take?: number }): Promise<PartnerAuditEvent[]> {
    let list = this.inMemory.filter(e => e.partnerId === partnerId);
    if (filters?.tenantId) list = list.filter(e => e.tenantId === filters.tenantId);
    if (filters?.action) list = list.filter(e => e.action === filters.action);
    if (filters?.correlationId) list = list.filter(e => e.correlationId === filters.correlationId);
    list = list.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    if (filters?.take) list = list.slice(0, filters.take);

    try {
      const where: any = { partnerId };
      if (filters?.tenantId) where.tenantId = filters.tenantId;
      if (filters?.action) where.action = filters.action;
      if (filters?.correlationId) where.correlationId = filters.correlationId;
      const rows = await (this.prisma as any).partnerAudit?.findMany?.({ where, take: filters?.take ?? 200, orderBy: { timestamp: 'desc' } });
      if (rows && rows.length > 0) {
        list = rows.map((r: any) => ({
          id: r.id,
          partnerId: r.partnerId,
          tenantId: r.tenantId ?? null,
          actorId: r.actorId,
          actorRole: r.actorRole ?? null,
          action: r.action,
          source: r.source,
          correlationId: r.correlationId,
          agreementVersion: r.agreementVersion ?? null,
          policyVersion: r.policyVersion ?? null,
          timestamp: r.timestamp instanceof Date ? r.timestamp.toISOString() : r.timestamp,
          safeEvidence: r.safeEvidence ?? {},
          createdAt: r.createdAt instanceof Date ? r.createdAt.toISOString() : r.createdAt,
        }));
      }
    } catch { /* fallback */ }
    return list;
  }
}

// # Exposes paginated, filterable commission ledger entries per partner
import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PartnerCommission, PartnerCommissionState, PartnerAuditAction } from './partner.types';
import { PartnerAuditService } from './partner-audit.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

@Injectable()
export class PartnerCommissionLedgerService {
  private readonly logger = new Logger(PartnerCommissionLedgerService.name);
  private readonly inMemory: Map<string, PartnerCommission> = new Map();
  private readonly idemIndex: Map<string, string> = new Map(); // idempotencyKey -> id
  private readonly sourceEventIndex: Map<string, string> = new Map(); // sourceEventId+partnerId -> id

  constructor(
    private readonly audit: PartnerAuditService,
    private readonly prisma: PrismaService,
  ) {}

  async accrueCommission(commission: PartnerCommission, actorId: string): Promise<PartnerCommission> {
    if (!commission) throw new BadRequestException('commission required');

    // Idempotency: duplicate billing/payment/fee events must not double-commission
    const idemKey = commission.idempotencyKey;
    if (this.idemIndex.has(idemKey)) {
      const existingId = this.idemIndex.get(idemKey)!;
      const existing = this.inMemory.get(existingId);
      if (existing) {
        this.logger.log(`commission ledger idempotent hit key=${idemKey}`);
        return existing;
      }
    }

    const sourceKey = `${commission.partnerId}:${commission.sourceEventId}`;
    if (this.sourceEventIndex.has(sourceKey)) {
      const existingId = this.sourceEventIndex.get(sourceKey)!;
      const existing = this.inMemory.get(existingId);
      if (existing) {
        this.logger.log(`commission duplicate source event blocked partner=${commission.partnerId} sourceEvent=${commission.sourceEventId}`);
        return existing;
      }
    }

    try {
      const existing = await (this.prisma as any).partnerCommission?.findFirst?.({ where: { idempotencyKey: idemKey } });
      if (existing) {
        this.logger.log(`commission ledger DB idempotent hit key=${idemKey}`);
        return this.mapRow(existing);
      }
      const existingSource = await (this.prisma as any).partnerCommission?.findFirst?.({ where: { partnerId: commission.partnerId, sourceEventId: commission.sourceEventId } });
      if (existingSource) {
        this.logger.log(`commission duplicate source event DB blocked partner=${commission.partnerId} sourceEvent=${commission.sourceEventId}`);
        return this.mapRow(existingSource);
      }
    } catch {}

    this.inMemory.set(commission.id, commission);
    this.idemIndex.set(idemKey, commission.id);
    this.sourceEventIndex.set(sourceKey, commission.id);

    try {
      await (this.prisma as any).partnerCommission?.create?.({
        data: {
          id: commission.id,
          partnerId: commission.partnerId,
          tenantId: commission.tenantId,
          sourcePaymentId: commission.sourcePaymentId,
          sourceInvoiceId: commission.sourceInvoiceId,
          sourceSubscriptionId: commission.sourceSubscriptionId,
          sourceFeeId: commission.sourceFeeId,
          sourceEventId: commission.sourceEventId,
          sourceEventType: commission.sourceEventType,
          grossRevenue: commission.grossRevenue,
          discountAmount: commission.discountAmount,
          netEligibleRevenue: commission.netEligibleRevenue,
          commissionRate: commission.commissionRate,
          commissionBasis: commission.commissionBasis,
          commissionModel: commission.commissionModel,
          commissionAmount: commission.commissionAmount,
          currency: commission.currency,
          sourceCurrency: commission.sourceCurrency,
          commissionCurrency: commission.commissionCurrency,
          fxRequired: commission.fxRequired,
          fxRate: commission.fxRate,
          fxTimestamp: commission.fxTimestamp ? new Date(commission.fxTimestamp) : null,
          fxSource: commission.fxSource,
          agreementVersion: commission.agreementVersion,
          policyVersion: commission.policyVersion,
          calculationVersion: commission.calculationVersion,
          state: commission.state,
          settlementId: commission.settlementId,
          payoutId: commission.payoutId,
          reversalOfId: commission.reversalOfId,
          createdAt: new Date(commission.createdAt),
          updatedAt: new Date(commission.updatedAt),
          accruedAt: new Date(commission.accruedAt),
          idempotencyKey: commission.idempotencyKey,
          correlationId: commission.correlationId,
        },
      });
    } catch {
      this.logger.debug(`commission ledger persist skipped id=${commission.id}`);
    }

    await this.audit.recordEvent({
      partnerId: commission.partnerId,
      tenantId: commission.tenantId,
      actorId,
      action: PartnerAuditAction.COMMISSION_ACCRUED,
      source: 'PARTNER_COMMISSION_LEDGER',
      correlationId: commission.correlationId,
      agreementVersion: commission.agreementVersion,
      policyVersion: commission.policyVersion,
      safeEvidence: {
        commissionId: commission.id,
        amount: commission.commissionAmount,
        currency: commission.currency,
        basis: commission.commissionBasis,
        model: commission.commissionModel,
        sourceEventId: commission.sourceEventId,
      },
    });

    this.logger.log(`commission accrued id=${commission.id} partner=${commission.partnerId} amount=${commission.commissionAmount} ${commission.currency} corr=${commission.correlationId}`);
    return commission;
  }

  async reverseCommission(params: {
    originalCommissionId: string;
    partnerId: string;
    tenantId: string;
    reversalReason: string;
    reversalType: 'REFUND' | 'CHARGEBACK' | 'CANCELLATION';
    reversalAmount?: string; // if proportional
    correlationId: string;
    actorId: string;
    idempotencyKey: string;
  }): Promise<PartnerCommission> {
    const original = await this.getCommission(params.originalCommissionId, params.partnerId);
    if (original.state === PartnerCommissionState.REVERSED) throw new BadRequestException('already reversed');

    // Idempotency for reversal
    if (this.idemIndex.has(params.idempotencyKey)) {
      const existingId = this.idemIndex.get(params.idempotencyKey)!;
      const existing = this.inMemory.get(existingId);
      if (existing) return existing;
    }

    const reversalAmount = params.reversalAmount ?? original.commissionAmount;
    // Never delete original - create reversal linked
    const reversal: PartnerCommission = {
      id: `pcom_rev_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      partnerId: params.partnerId,
      tenantId: params.tenantId,
      sourcePaymentId: original.sourcePaymentId,
      sourceInvoiceId: original.sourceInvoiceId,
      sourceSubscriptionId: original.sourceSubscriptionId,
      sourceFeeId: original.sourceFeeId,
      sourceEventId: `${original.sourceEventId}_reversal_${params.reversalType}`,
      sourceEventType: original.sourceEventType,
      grossRevenue: `-${original.grossRevenue}`,
      discountAmount: original.discountAmount,
      netEligibleRevenue: `-${original.netEligibleRevenue}`,
      commissionRate: original.commissionRate,
      commissionBasis: original.commissionBasis,
      commissionModel: original.commissionModel,
      commissionAmount: `-${reversalAmount}`,
      currency: original.currency,
      sourceCurrency: original.sourceCurrency,
      commissionCurrency: original.commissionCurrency,
      fxRequired: original.fxRequired,
      fxRate: original.fxRate,
      fxTimestamp: original.fxTimestamp,
      fxSource: original.fxSource,
      agreementVersion: original.agreementVersion,
      policyVersion: original.policyVersion,
      calculationVersion: original.calculationVersion,
      state: PartnerCommissionState.REVERSED,
      settlementId: null,
      payoutId: null,
      reversalOfId: original.id,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      accruedAt: new Date().toISOString(),
      idempotencyKey: params.idempotencyKey,
      correlationId: params.correlationId,
    };

    this.inMemory.set(reversal.id, reversal);
    this.idemIndex.set(params.idempotencyKey, reversal.id);

    // Mark original as reversed
    original.state = PartnerCommissionState.REVERSED;
    original.updatedAt = new Date().toISOString();
    this.inMemory.set(original.id, original);

    try {
      await (this.prisma as any).$transaction?.(async (tx: any) => {
        await tx.partnerCommission?.create?.({
          data: {
            id: reversal.id,
            partnerId: reversal.partnerId,
            tenantId: reversal.tenantId,
            sourcePaymentId: reversal.sourcePaymentId,
            sourceInvoiceId: reversal.sourceInvoiceId,
            sourceSubscriptionId: reversal.sourceSubscriptionId,
            sourceFeeId: reversal.sourceFeeId,
            sourceEventId: reversal.sourceEventId,
            sourceEventType: reversal.sourceEventType,
            grossRevenue: reversal.grossRevenue,
            discountAmount: reversal.discountAmount,
            netEligibleRevenue: reversal.netEligibleRevenue,
            commissionRate: reversal.commissionRate,
            commissionBasis: reversal.commissionBasis,
            commissionModel: reversal.commissionModel,
            commissionAmount: reversal.commissionAmount,
            currency: reversal.currency,
            sourceCurrency: reversal.sourceCurrency,
            commissionCurrency: reversal.commissionCurrency,
            fxRequired: reversal.fxRequired,
            fxRate: reversal.fxRate,
            fxTimestamp: reversal.fxTimestamp ? new Date(reversal.fxTimestamp) : null,
            fxSource: reversal.fxSource,
            agreementVersion: reversal.agreementVersion,
            policyVersion: reversal.policyVersion,
            calculationVersion: reversal.calculationVersion,
            state: reversal.state,
            reversalOfId: reversal.reversalOfId,
            createdAt: new Date(reversal.createdAt),
            updatedAt: new Date(reversal.updatedAt),
            accruedAt: new Date(reversal.accruedAt),
            idempotencyKey: reversal.idempotencyKey,
            correlationId: reversal.correlationId,
          },
        });
        await tx.partnerCommission?.update?.({ where: { id: original.id }, data: { state: 'REVERSED', updatedAt: new Date() } });
      });
    } catch {
      this.logger.debug(`reversal persist skipped id=${reversal.id}`);
      try {
        await (this.prisma as any).partnerCommission?.create?.({
          data: {
            id: reversal.id,
            partnerId: reversal.partnerId,
            tenantId: reversal.tenantId,
            sourceEventId: reversal.sourceEventId,
            sourceEventType: reversal.sourceEventType,
            grossRevenue: reversal.grossRevenue,
            commissionAmount: reversal.commissionAmount,
            currency: reversal.currency,
            commissionBasis: reversal.commissionBasis,
            commissionModel: reversal.commissionModel,
            commissionRate: reversal.commissionRate,
            sourceCurrency: reversal.sourceCurrency,
            commissionCurrency: reversal.commissionCurrency,
            fxRequired: reversal.fxRequired,
            agreementVersion: reversal.agreementVersion,
            policyVersion: reversal.policyVersion,
            calculationVersion: reversal.calculationVersion,
            state: reversal.state,
            reversalOfId: reversal.reversalOfId,
            createdAt: new Date(reversal.createdAt),
            updatedAt: new Date(reversal.updatedAt),
            accruedAt: new Date(reversal.accruedAt),
            idempotencyKey: reversal.idempotencyKey,
            correlationId: reversal.correlationId,
            netEligibleRevenue: reversal.netEligibleRevenue,
            discountAmount: reversal.discountAmount,
          },
        });
        await (this.prisma as any).partnerCommission?.update?.({ where: { id: original.id }, data: { state: 'REVERSED' } });
      } catch {}
    }

    await this.audit.recordEvent({
      partnerId: params.partnerId,
      tenantId: params.tenantId,
      actorId: params.actorId,
      action: PartnerAuditAction.COMMISSION_REVERSED,
      source: 'PARTNER_COMMISSION_LEDGER',
      correlationId: params.correlationId,
      agreementVersion: original.agreementVersion,
      policyVersion: original.policyVersion,
      safeEvidence: { originalCommissionId: original.id, reversalId: reversal.id, reason: params.reversalReason, type: params.reversalType, amount: reversalAmount },
    });

    this.logger.log(`commission reversed original=${original.id} reversal=${reversal.id} reason=${params.reversalReason} corr=${params.correlationId}`);
    return reversal;
  }

  async getCommission(commissionId: string, partnerId: string): Promise<PartnerCommission> {
    const mem = this.inMemory.get(commissionId);
    if (mem) {
      if (mem.partnerId !== partnerId) throw new BadRequestException('partner isolation violation');
      return mem;
    }
    try {
      const row = await (this.prisma as any).partnerCommission?.findUnique?.({ where: { id: commissionId } });
      if (row) {
        if (row.partnerId !== partnerId) throw new BadRequestException('partner isolation violation');
        const mapped = this.mapRow(row);
        this.inMemory.set(mapped.id, mapped);
        return mapped;
      }
    } catch {}
    throw new BadRequestException(`commission ${commissionId} not found`);
  }

  async listCommissions(partnerId: string, filters?: { tenantId?: string; state?: PartnerCommissionState; settlementId?: string; currency?: string }): Promise<PartnerCommission[]> {
    let list = [...this.inMemory.values()].filter(c => c.partnerId === partnerId);
    if (filters?.tenantId) list = list.filter(c => c.tenantId === filters.tenantId);
    if (filters?.state) list = list.filter(c => c.state === filters.state);
    if (filters?.settlementId) list = list.filter(c => c.settlementId === filters.settlementId);
    if (filters?.currency) {
      const curUpper = filters.currency.toUpperCase();
      list = list.filter(c => c.currency === curUpper);
    }
    try {
      const where: any = { partnerId };
      if (filters?.tenantId) where.tenantId = filters.tenantId;
      if (filters?.state) where.state = filters.state;
      if (filters?.settlementId) where.settlementId = filters.settlementId;
      if (filters?.currency) where.currency = filters.currency.toUpperCase();
      const rows = await (this.prisma as any).partnerCommission?.findMany?.({ where, take: 1000, orderBy: { accruedAt: 'desc' } });
      if (rows && rows.length > 0) list = rows.map((r: any) => this.mapRow(r));
    } catch {}
    return list;
  }

  private mapRow(row: any): PartnerCommission {
    return {
      id: row.id,
      partnerId: row.partnerId,
      tenantId: row.tenantId,
      sourcePaymentId: row.sourcePaymentId ?? null,
      sourceInvoiceId: row.sourceInvoiceId ?? null,
      sourceSubscriptionId: row.sourceSubscriptionId ?? null,
      sourceFeeId: row.sourceFeeId ?? null,
      sourceEventId: row.sourceEventId,
      sourceEventType: row.sourceEventType,
      grossRevenue: row.grossRevenue,
      discountAmount: row.discountAmount,
      netEligibleRevenue: row.netEligibleRevenue,
      commissionRate: row.commissionRate,
      commissionBasis: row.commissionBasis,
      commissionModel: row.commissionModel,
      commissionAmount: row.commissionAmount,
      currency: row.currency,
      sourceCurrency: row.sourceCurrency,
      commissionCurrency: row.commissionCurrency,
      fxRequired: !!row.fxRequired,
      fxRate: row.fxRate ?? null,
      fxTimestamp: row.fxTimestamp ? (row.fxTimestamp instanceof Date ? row.fxTimestamp.toISOString() : row.fxTimestamp) : null,
      fxSource: row.fxSource ?? null,
      agreementVersion: row.agreementVersion,
      policyVersion: row.policyVersion,
      calculationVersion: row.calculationVersion,
      state: row.state,
      settlementId: row.settlementId ?? null,
      payoutId: row.payoutId ?? null,
      reversalOfId: row.reversalOfId ?? null,
      createdAt: row.createdAt instanceof Date ? row.createdAt.toISOString() : row.createdAt,
      updatedAt: row.updatedAt instanceof Date ? row.updatedAt.toISOString() : row.updatedAt,
      accruedAt: row.accruedAt instanceof Date ? row.accruedAt.toISOString() : row.accruedAt,
      idempotencyKey: row.idempotencyKey,
      correlationId: row.correlationId,
    };
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PartnerCommission, PartnerCommissionState, PartnerCommissionModel, PartnerCommissionBasis } from './partner.types';
import { PartnerPolicyService } from './partner-policy.service';
import { PartnerAgreementService } from './partner-agreement.service';
import { PartnerAuditService } from './partner-audit.service';
import { PartnerAttributionService } from './partner-attribution.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

@Injectable()
export class PartnerCommissionService {
  private readonly logger = new Logger(PartnerCommissionService.name);
  private readonly calculationVersion = '2026-01';

  constructor(
    private readonly policyService: PartnerPolicyService,
    private readonly agreementService: PartnerAgreementService,
    private readonly audit: PartnerAuditService,
    private readonly attributionService: PartnerAttributionService,
    private readonly prisma: PrismaService,
  ) {}

  /**
   * Calculates commission from authoritative payments/invoices/subscriptions/fees
   * Supports revenue-share, fixed-fee, percentage, first-period, recurring-period
   * No hardcoded rates, Decimal-safe
   */
  async calculateCommission(params: {
    partnerId: string;
    tenantId: string;
    sourcePaymentId?: string | null;
    sourceInvoiceId?: string | null;
    sourceSubscriptionId?: string | null;
    sourceFeeId?: string | null;
    sourceEventId: string;
    sourceEventType: 'PAYMENT' | 'INVOICE' | 'SUBSCRIPTION' | 'FEE' | 'REFUND' | 'CHARGEBACK';
    grossRevenue: string;
    discountAmount: string;
    currency: string;
    sourceCurrency?: string;
    correlationId: string;
    idempotencyKey: string;
    createdBy: string;
    isTrial?: boolean;
    isLifetime?: boolean;
    isFirstPeriod?: boolean;
    periodNumber?: number;
    planCode?: string;
    paymentStatus?: string;
    invoiceStatus?: string;
  }): Promise<PartnerCommission | null> {
    if (!params.partnerId || !params.tenantId || !params.sourceEventId || !params.grossRevenue || !params.currency) {
      throw new BadRequestException('partnerId, tenantId, sourceEventId, grossRevenue, currency required');
    }

    // Commission must NOT be generated from unpaid/failed/cancelled/unconfirmed/fake/test/unverified
    if (params.paymentStatus) {
      const invalidPaymentStatuses = ['FAILED', 'CANCELLED', 'UNCONFIRMED', 'FAKE', 'TEST', 'PENDING', 'UNPAID'];
      if (invalidPaymentStatuses.includes(params.paymentStatus.toUpperCase())) {
        this.logger.log(`commission blocked - invalid payment status ${params.paymentStatus} event=${params.sourceEventId} corr=${params.correlationId}`);
        return null;
      }
    }
    if (params.invoiceStatus) {
      const invalidInvoiceStatuses = ['DRAFT', 'VOID', 'UNPAID', 'UNCOLLECTED', 'FAILED'];
      if (invalidInvoiceStatuses.includes(params.invoiceStatus.toUpperCase())) {
        this.logger.log(`commission blocked - invalid invoice status ${params.invoiceStatus} event=${params.sourceEventId} corr=${params.correlationId}`);
        return null;
      }
    }

    const agreement = await this.agreementService.getActiveAgreement(params.partnerId);
    if (!agreement) {
      this.logger.warn(`no active agreement for partner ${params.partnerId}, commission blocked`);
      return null;
    }

    const policy = agreement.commissionPolicy;

    // Trial handling
    if (params.isTrial && !policy.trialCommissionEligible) {
      this.logger.log(`trial commission not eligible per policy partner=${params.partnerId} corr=${params.correlationId}`);
      return null;
    }

    // Lifetime handling
    let commissionModel = policy.commissionModels[0] ?? PartnerCommissionModel.PERCENTAGE_REVENUE;
    if (params.isLifetime) {
      commissionModel = policy.lifetimeCommissionModel;
    } else if (params.isFirstPeriod) {
      // Prefer FIRST_PERIOD if configured
      const firstPeriodModel = policy.commissionModels.find(m => m === PartnerCommissionModel.FIRST_PERIOD);
      if (firstPeriodModel) commissionModel = firstPeriodModel;
    }

    // Find applicable rate config
    const rateConfig = this.findApplicableRate(policy, commissionModel, params.planCode, params.grossRevenue);
    if (!rateConfig) {
      this.logger.warn(`no applicable commission rate for partner=${params.partnerId} model=${commissionModel} plan=${params.planCode}`);
      return null;
    }

    // Validate attribution exists
    const attribution = await this.attributionService.getPrimaryAttributionForTenant(params.tenantId);
    if (!attribution || attribution.partnerId !== params.partnerId) {
      this.logger.warn(`no valid attribution for tenant=${params.tenantId} partner=${params.partnerId}, commission blocked`);
      return null;
    }
    if (new Date(attribution.expiresAt) < new Date()) {
      this.logger.warn(`attribution expired for tenant=${params.tenantId}, commission blocked`);
      return null;
    }

    // Resolve commission basis
    const basis = rateConfig.basis ?? policy.commissionBasis;
    let netEligibleRevenue: string;
    switch (basis) {
      case PartnerCommissionBasis.LIST_PRICE:
        netEligibleRevenue = params.grossRevenue;
        break;
      case PartnerCommissionBasis.DISCOUNTED_PRICE:
      case PartnerCommissionBasis.NET_REVENUE:
        netEligibleRevenue = this.subtractDecimal(params.grossRevenue, params.discountAmount, params.currency);
        break;
      case PartnerCommissionBasis.COLLECTED_REVENUE:
        // For collected revenue, use gross - discount as eligible (actual collected)
        netEligibleRevenue = this.subtractDecimal(params.grossRevenue, params.discountAmount, params.currency);
        break;
      default:
        netEligibleRevenue = this.subtractDecimal(params.grossRevenue, params.discountAmount, params.currency);
    }

    // Check min eligible amount
    if (rateConfig.minEligibleAmount) {
      if (this.compareDecimal(netEligibleRevenue, rateConfig.minEligibleAmount, params.currency) < 0) {
        this.logger.log(`net eligible ${netEligibleRevenue} below min ${rateConfig.minEligibleAmount}, commission blocked`);
        return null;
      }
    }

    // Calculate commission amount Decimal-safe
    let commissionAmount: string;
    let commissionRateStr: string;

    if (rateConfig.rateBasisPoints !== undefined) {
      commissionRateStr = `${rateConfig.rateBasisPoints}bps`;
      commissionAmount = this.calculatePercentage(netEligibleRevenue, rateConfig.rateBasisPoints, params.currency);
    } else if (rateConfig.fixedAmount) {
      commissionRateStr = `fixed:${rateConfig.fixedAmount}`;
      commissionAmount = rateConfig.fixedAmount;
      // Ensure fixed amount currency matches or FX required
      if (rateConfig.currency && rateConfig.currency.toUpperCase() !== params.currency.toUpperCase()) {
        // FX required - if unavailable, settlement blocked, but we still accrue with fxRequired=true
      }
    } else {
      throw new BadRequestException('commission rate config must have rateBasisPoints or fixedAmount');
    }

    // Apply max commission cap
    if (rateConfig.maxCommissionAmount) {
      if (this.compareDecimal(commissionAmount, rateConfig.maxCommissionAmount, params.currency) > 0) {
        commissionAmount = rateConfig.maxCommissionAmount;
      }
    }

    // Multi-currency handling
    const sourceCurrency = (params.sourceCurrency ?? params.currency).toUpperCase();
    const commissionCurrency = (rateConfig.currency ?? policy.currencyPolicy.settlementCurrency ?? params.currency).toUpperCase();
    const fxRequired = sourceCurrency !== commissionCurrency;
    let fxRate: string | null = null;
    let fxTimestamp: string | null = null;
    let fxSource: string | null = null;

    if (fxRequired) {
      // Try to fetch FX rate - if unavailable, mark fxRequired but keep commission for later settlement blocking
      try {
        const fx = await this.getFxRate(sourceCurrency, commissionCurrency);
        if (fx) {
          fxRate = fx.rate;
          fxTimestamp = fx.timestamp;
          fxSource = fx.source;
          // Convert commission amount if needed - here we assume commissionAmount is already in source currency, need conversion
          // For simplicity, if fixed amount in different currency, we keep as is and settlement will handle FX
        } else {
          this.logger.warn(`FX rate unavailable ${sourceCurrency}->${commissionCurrency}, commission accrued with fxRequired=true`);
        }
      } catch {
        this.logger.warn(`FX fetch failed ${sourceCurrency}->${commissionCurrency}`);
      }
    }

    const commission: PartnerCommission = {
      id: `pcom_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      partnerId: params.partnerId,
      tenantId: params.tenantId,
      sourcePaymentId: params.sourcePaymentId ?? null,
      sourceInvoiceId: params.sourceInvoiceId ?? null,
      sourceSubscriptionId: params.sourceSubscriptionId ?? null,
      sourceFeeId: params.sourceFeeId ?? null,
      sourceEventId: params.sourceEventId,
      sourceEventType: params.sourceEventType,
      grossRevenue: params.grossRevenue,
      discountAmount: params.discountAmount,
      netEligibleRevenue,
      commissionRate: commissionRateStr,
      commissionBasis: basis,
      commissionModel,
      commissionAmount,
      currency: params.currency.toUpperCase(),
      sourceCurrency,
      commissionCurrency,
      fxRequired,
      fxRate,
      fxTimestamp,
      fxSource,
      agreementVersion: `v${agreement.version}`,
      policyVersion: policy.policyVersion,
      calculationVersion: this.calculationVersion,
      state: PartnerCommissionState.ACCRUED,
      settlementId: null,
      payoutId: null,
      reversalOfId: null,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      accruedAt: new Date().toISOString(),
      idempotencyKey: params.idempotencyKey,
      correlationId: params.correlationId,
    };

    // Idempotency check via ledger service will be done there, but also check here
    try {
      const existing = await (this.prisma as any).partnerCommission?.findFirst?.({ where: { idempotencyKey: params.idempotencyKey } });
      if (existing) {
        this.logger.log(`commission idempotent hit key=${params.idempotencyKey}`);
        return this.mapRow(existing);
      }
    } catch {}

    this.logger.log(`commission calculated partner=${params.partnerId} amount=${commissionAmount} ${params.currency} model=${commissionModel} basis=${basis} corr=${params.correlationId}`);
    return commission;
  }

  private findApplicableRate(policy: any, model: PartnerCommissionModel, planCode?: string, grossRevenue?: string): any {
    // Find rate matching model and planCode, with effective dates
    const now = new Date();
    const candidates = policy.commissionRates.filter((r: any) => {
      if (r.model !== model) return false;
      const from = new Date(r.effectiveFrom);
      if (from > now) return false;
      if (r.effectiveTo) {
        const to = new Date(r.effectiveTo);
        if (to < now) return false;
      }
      if (r.planCodes && r.planCodes.length > 0 && planCode) {
        if (!r.planCodes.includes(planCode)) return false;
      }
      return true;
    });
    // Prefer most specific (with planCodes) then highest rate
    candidates.sort((a: any, b: any) => {
      const aSpecific = a.planCodes?.length ? 1 : 0;
      const bSpecific = b.planCodes?.length ? 1 : 0;
      if (aSpecific !== bSpecific) return bSpecific - aSpecific;
      return (b.rateBasisPoints ?? 0) - (a.rateBasisPoints ?? 0);
    });
    return candidates[0] ?? policy.commissionRates.find((r: any) => r.model === model) ?? policy.commissionRates[0] ?? null;
  }

  private async getFxRate(from: string, to: string): Promise<{ rate: string; timestamp: string; source: string } | null> {
    // In production, this would call FX provider - here we return null to trigger SETTLEMENT_BLOCKED if FX required
    // Never invent FX
    return null;
  }

  // Decimal-safe helpers using BigInt minor units
  private getMinorUnit(currency: string): number {
    const map: Record<string, number> = { USD: 2, EUR: 2, GBP: 2, JPY: 0, USDT: 6, USDC: 6, BTC: 8, ETH: 18 };
    return map[currency.toUpperCase()] ?? 2;
  }

  private toMinorUnits(amount: string, currency: string): bigint {
    const minor = this.getMinorUnit(currency);
    const factor = Math.pow(10, minor);
    const parts = amount.toString().split('.');
    const integerPart = BigInt(parts[0] || '0');
    let fractional = parts[1] || '';
    if (fractional.length > minor) fractional = fractional.slice(0, minor);
    while (fractional.length < minor) fractional += '0';
    const fractionalPart = BigInt(fractional || '0');
    if (integerPart < BigInt(0)) return integerPart * BigInt(factor) - fractionalPart;
    return integerPart * BigInt(factor) + fractionalPart;
  }

  private fromMinorUnits(minor: bigint, currency: string): string {
    const minorUnit = this.getMinorUnit(currency);
    const factor = BigInt(Math.pow(10, minorUnit));
    const isNegative = minor < BigInt(0);
    const abs = isNegative ? -minor : minor;
    const integerPart = abs / factor;
    const fractionalPart = abs % factor;
    let fractionalStr = fractionalPart.toString().padStart(minorUnit, '0');
    if (minorUnit > 0) {
      fractionalStr = fractionalStr.replace(/0+$/, '');
      if (fractionalStr === '') fractionalStr = '0'.repeat(Math.min(2, minorUnit));
    }
    const result = minorUnit === 0 ? integerPart.toString() : `${integerPart.toString()}.${fractionalStr}`;
    return isNegative ? `-${result}` : result;
  }

  private subtractDecimal(a: string, b: string, currency: string): string {
    const aMinor = this.toMinorUnits(a, currency);
    const bMinor = this.toMinorUnits(b, currency);
    return this.fromMinorUnits(aMinor - bMinor, currency);
  }

  private calculatePercentage(amount: string, basisPoints: number, currency: string): string {
    const minor = this.toMinorUnits(amount, currency);
    const result = (minor * BigInt(basisPoints)) / BigInt(10000);
    return this.fromMinorUnits(result, currency);
  }

  private compareDecimal(a: string, b: string, currency: string): number {
    const aMinor = this.toMinorUnits(a, currency);
    const bMinor = this.toMinorUnits(b, currency);
    if (aMinor < bMinor) return -1;
    if (aMinor > bMinor) return 1;
    return 0;
  }

  private mapRow(row: any): PartnerCommission {
    return {
      id: row.id,
      partnerId: row.partnerId,
      tenantId: row.tenantId,
      sourcePaymentId: row.sourcePaymentId ?? null,
      sourceInvoiceId: row.sourceInvoiceId ?? null,
      sourceSubscriptionId: row.sourceSubscriptionId ?? null,
      sourceFeeId: row.sourceFeeId ?? null,
      sourceEventId: row.sourceEventId,
      sourceEventType: row.sourceEventType,
      grossRevenue: row.grossRevenue,
      discountAmount: row.discountAmount,
      netEligibleRevenue: row.netEligibleRevenue,
      commissionRate: row.commissionRate,
      commissionBasis: row.commissionBasis,
      commissionModel: row.commissionModel,
      commissionAmount: row.commissionAmount,
      currency: row.currency,
      sourceCurrency: row.sourceCurrency,
      commissionCurrency: row.commissionCurrency,
      fxRequired: !!row.fxRequired,
      fxRate: row.fxRate ?? null,
      fxTimestamp: row.fxTimestamp ? (row.fxTimestamp instanceof Date ? row.fxTimestamp.toISOString() : row.fxTimestamp) : null,
      fxSource: row.fxSource ?? null,
      agreementVersion: row.agreementVersion,
      policyVersion: row.policyVersion,
      calculationVersion: row.calculationVersion,
      state: row.state,
      settlementId: row.settlementId ?? null,
      payoutId: row.payoutId ?? null,
      reversalOfId: row.reversalOfId ?? null,
      createdAt: row.createdAt instanceof Date ? row.createdAt.toISOString() : row.createdAt,
      updatedAt: row.updatedAt instanceof Date ? row.updatedAt.toISOString() : row.updatedAt,
      accruedAt: row.accruedAt instanceof Date ? row.accruedAt.toISOString() : row.accruedAt,
      idempotencyKey: row.idempotencyKey,
      correlationId: row.correlationId,
    };
  }
}

import { Injectable, Logger, BadRequestException, NotFoundException } from '@nestjs/common';
import { PartnerCampaign, PartnerCampaignState, PartnerDiscountType, PartnerAuditAction } from './partner.types';
import { PartnerPolicyService } from './partner-policy.service';
import { PartnerAgreementService } from './partner-agreement.service';
import { PartnerAuditService } from './partner-audit.service';
import { PartnerProfileService } from './partner-profile.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

@Injectable()
export class PartnerDiscountService {
  private readonly logger = new Logger(PartnerDiscountService.name);
  private readonly inMemory: Map<string, PartnerCampaign> = new Map();

  constructor(
    private readonly policyService: PartnerPolicyService,
    private readonly agreementService: PartnerAgreementService,
    private readonly audit: PartnerAuditService,
    private readonly profileService: PartnerProfileService,
    private readonly prisma: PrismaService,
  ) {}

  async createCampaign(params: {
    partnerId: string;
    name: string;
    code: string;
    discountType?: PartnerDiscountType;
    discountValue?: string;
    discountCurrency?: string;
    maxUses?: number;
    allowedPlans?: string[];
    attributionWindowHours: number;
    startsAt: string;
    endsAt?: string | null;
    createdBy: string;
    correlationId: string;
    idempotencyKey: string;
  }): Promise<PartnerCampaign> {
    if (!params.partnerId || !params.name || !params.code || !params.startsAt || !params.idempotencyKey) {
      throw new BadRequestException('partnerId, name, code, startsAt, idempotencyKey required');
    }

    await this.profileService.getProfile(params.partnerId);
    const agreement = await this.agreementService.getActiveAgreement(params.partnerId);
    if (!agreement) throw new BadRequestException(`no active agreement for partner ${params.partnerId}`);

    // Idempotency
    const existingByIdem = [...this.inMemory.values()].find(c => c.idempotencyKey === params.idempotencyKey);
    if (existingByIdem) return existingByIdem;

    // Code uniqueness per partner
    const existingByCode = [...this.inMemory.values()].find(c => c.partnerId === params.partnerId && c.code === params.code);
    if (existingByCode) throw new BadRequestException(`campaign code ${params.code} already exists for partner ${params.partnerId}`);

    const startsAt = new Date(params.startsAt);
    if (isNaN(startsAt.getTime())) throw new BadRequestException('invalid startsAt');
    if (params.endsAt) {
      const endsAt = new Date(params.endsAt);
      if (isNaN(endsAt.getTime()) || endsAt <= startsAt) throw new BadRequestException('endsAt must be after startsAt');
    }

    if (params.discountType && params.discountValue) {
      if (params.discountType === PartnerDiscountType.PERCENTAGE) {
        const bps = Math.round(parseFloat(params.discountValue) * 100);
        if (isNaN(bps) || bps <= 0 || bps > 10000) throw new BadRequestException('invalid percentage discount');
        this.policyService.validateDiscount(agreement.commissionPolicy, bps, params.discountCurrency ?? 'USD');
      } else if (params.discountType === PartnerDiscountType.FIXED_AMOUNT) {
        const amt = parseFloat(params.discountValue);
        if (isNaN(amt) || amt <= 0) throw new BadRequestException('invalid fixed discount amount');
        this.policyService.validateDiscount(agreement.commissionPolicy, 0, params.discountCurrency ?? 'USD', params.discountValue);
      }
      if (params.discountCurrency) {
        this.policyService.validateCurrency(agreement.commissionPolicy, params.discountCurrency);
      }
    }

    if (params.attributionWindowHours <= 0 || params.attributionWindowHours > 8760) {
      throw new BadRequestException('attributionWindowHours must be 1-8760');
    }

    const campaign: PartnerCampaign = {
      id: `pcamp_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      partnerId: params.partnerId,
      name: params.name,
      code: params.code.toUpperCase(),
      state: PartnerCampaignState.DRAFT,
      discountType: params.discountType ?? null,
      discountValue: params.discountValue ?? null,
      discountCurrency: params.discountCurrency ? params.discountCurrency.toUpperCase() : null,
      maxUses: params.maxUses ?? null,
      currentUses: 0,
      allowedPlans: params.allowedPlans ?? null,
      attributionWindowHours: params.attributionWindowHours,
      startsAt: startsAt.toISOString(),
      endsAt: params.endsAt ? new Date(params.endsAt).toISOString() : null,
      createdBy: params.createdBy,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      idempotencyKey: params.idempotencyKey,
    };

    this.inMemory.set(campaign.id, campaign);
    try {
      await (this.prisma as any).partnerCampaign?.create?.({
        data: {
          id: campaign.id,
          partnerId: campaign.partnerId,
          name: campaign.name,
          code: campaign.code,
          state: campaign.state,
          discountType: campaign.discountType,
          discountValue: campaign.discountValue,
          discountCurrency: campaign.discountCurrency,
          maxUses: campaign.maxUses,
          currentUses: campaign.currentUses,
          allowedPlans: campaign.allowedPlans as any,
          attributionWindowHours: campaign.attributionWindowHours,
          startsAt: new Date(campaign.startsAt),
          endsAt: campaign.endsAt ? new Date(campaign.endsAt) : null,
          createdBy: campaign.createdBy,
          createdAt: new Date(campaign.createdAt),
          updatedAt: new Date(campaign.updatedAt),
          idempotencyKey: campaign.idempotencyKey,
        },
      });
    } catch {
      this.logger.debug(`campaign persist skipped id=${campaign.id}`);
    }

    await this.audit.recordEvent({
      partnerId: params.partnerId,
      actorId: params.createdBy,
      action: PartnerAuditAction.CAMPAIGN_CREATED,
      source: 'PARTNER_DISCOUNT_SERVICE',
      correlationId: params.correlationId,
      agreementVersion: `v${agreement.version}`,
      policyVersion: agreement.commissionPolicy.policyVersion,
      safeEvidence: { campaignId: campaign.id, code: campaign.code, discountType: campaign.discountType, discountValue: campaign.discountValue },
    });

    this.logger.log(`campaign created id=${campaign.id} partner=${params.partnerId} code=${campaign.code} corr=${params.correlationId}`);
    return campaign;
  }

  async activateCampaign(params: { campaignId: string; partnerId: string; activatedBy: string; correlationId: string }): Promise<PartnerCampaign> {
    const camp = await this.getCampaign(params.campaignId, params.partnerId);
    if (camp.state !== PartnerCampaignState.DRAFT && camp.state !== PartnerCampaignState.PAUSED) throw new BadRequestException(`cannot activate from state ${camp.state}`);
    camp.state = PartnerCampaignState.ACTIVE;
    camp.updatedAt = new Date().toISOString();
    this.inMemory.set(camp.id, camp);
    try {
      await (this.prisma as any).partnerCampaign?.update?.({ where: { id: camp.id }, data: { state: camp.state, updatedAt: new Date(camp.updatedAt) } });
    } catch {}
    return camp;
  }

  async pauseCampaign(params: { campaignId: string; partnerId: string; pausedBy: string; correlationId: string }): Promise<PartnerCampaign> {
    const camp = await this.getCampaign(params.campaignId, params.partnerId);
    if (camp.state !== PartnerCampaignState.ACTIVE) throw new BadRequestException(`cannot pause from state ${camp.state}`);
    camp.state = PartnerCampaignState.PAUSED;
    camp.updatedAt = new Date().toISOString();
    this.inMemory.set(camp.id, camp);
    try {
      await (this.prisma as any).partnerCampaign?.update?.({ where: { id: camp.id }, data: { state: camp.state, updatedAt: new Date(camp.updatedAt) } });
    } catch {}
    return camp;
  }

  async getCampaign(campaignId: string, partnerId: string): Promise<PartnerCampaign> {
    const mem = this.inMemory.get(campaignId);
    if (mem) {
      if (mem.partnerId !== partnerId) throw new BadRequestException('partner isolation violation');
      return mem;
    }
    try {
      const row = await (this.prisma as any).partnerCampaign?.findUnique?.({ where: { id: campaignId } });
      if (row) {
        if (row.partnerId !== partnerId) throw new BadRequestException('partner isolation violation');
        const mapped = this.mapRow(row);
        this.inMemory.set(mapped.id, mapped);
        return mapped;
      }
    } catch {}
    throw new NotFoundException(`campaign ${campaignId} not found`);
  }

  async listCampaigns(partnerId: string, filters?: { state?: PartnerCampaignState }): Promise<PartnerCampaign[]> {
    let list = [...this.inMemory.values()].filter(c => c.partnerId === partnerId);
    if (filters?.state) list = list.filter(c => c.state === filters.state);
    try {
      const where: any = { partnerId };
      if (filters?.state) where.state = filters.state;
      const rows = await (this.prisma as any).partnerCampaign?.findMany?.({ where, take: 200, orderBy: { createdAt: 'desc' } });
      if (rows && rows.length > 0) list = rows.map((r: any) => this.mapRow(r));
    } catch {}
    return list;
  }

  async incrementUsage(campaignId: string, partnerId: string): Promise<PartnerCampaign> {
    const camp = await this.getCampaign(campaignId, partnerId);
    if (camp.maxUses && camp.currentUses >= camp.maxUses) throw new BadRequestException('campaign max uses reached');
    camp.currentUses += 1;
    camp.updatedAt = new Date().toISOString();
    if (camp.maxUses && camp.currentUses >= camp.maxUses) {
      camp.state = PartnerCampaignState.EXPIRED;
    }
    this.inMemory.set(camp.id, camp);
    try {
      await (this.prisma as any).partnerCampaign?.update?.({ where: { id: camp.id }, data: { currentUses: camp.currentUses, state: camp.state, updatedAt: new Date(camp.updatedAt) } });
    } catch {}
    return camp;
  }

  private mapRow(row: any): PartnerCampaign {
    return {
      id: row.id,
      partnerId: row.partnerId,
      name: row.name,
      code: row.code,
      state: row.state,
      discountType: row.discountType ?? null,
      discountValue: row.discountValue ?? null,
      discountCurrency: row.discountCurrency ?? null,
      maxUses: row.maxUses ?? null,
      currentUses: row.currentUses ?? 0,
      allowedPlans: row.allowedPlans ?? null,
      attributionWindowHours: row.attributionWindowHours,
      startsAt: row.startsAt instanceof Date ? row.startsAt.toISOString() : row.startsAt,
      endsAt: row.endsAt ? (row.endsAt instanceof Date ? row.endsAt.toISOString() : row.endsAt) : null,
      createdBy: row.createdBy,
      createdAt: row.createdAt instanceof Date ? row.createdAt.toISOString() : row.createdAt,
      updatedAt: row.updatedAt instanceof Date ? row.updatedAt.toISOString() : row.updatedAt,
      idempotencyKey: row.idempotencyKey,
    };
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PartnerProfileService } from './partner-profile.service';
import { PartnerCommissionLedgerService } from './partner-commission-ledger.service';
import { PartnerSettlementService } from './partner-settlement.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

/**
 * Provides partner-facing invoice/revenue statements from persisted billing/finance/commission records
 * Does not create a second invoice authority - references authoritative billing truth only
 * Never mutates invoice directly - derivative statement layer
 */
export interface PartnerInvoiceStatement {
  id: string;
  partnerId: string;
  settlementId?: string | null;
  periodStart: string;
  periodEnd: string;
  currency: string;
  grossRevenue: string;
  discount: string;
  netEligibleRevenue: string;
  commissionAccrued: string;
  commissionReversed: string;
  commissionPayable: string;
  commissionCount: number;
  invoiceReferences: string[];
  paymentReferences: string[];
  subscriptionReferences: string[];
  generatedAt: string;
  calculationVersion: string;
  policyVersion: string;
  agreementVersion: string;
  isImmutable: boolean;
}

@Injectable()
export class PartnerInvoiceService {
  private readonly logger = new Logger(PartnerInvoiceService.name);

  constructor(
    private readonly profileService: PartnerProfileService,
    private readonly commissionLedger: PartnerCommissionLedgerService,
    private readonly settlementService: PartnerSettlementService,
    private readonly prisma: PrismaService,
  ) {}

  async generateStatement(params: {
    partnerId: string;
    periodStart: string;
    periodEnd: string;
    currency: string;
    settlementId?: string;
    correlationId: string;
  }): Promise<PartnerInvoiceStatement> {
    if (!params.partnerId || !params.periodStart || !params.periodEnd || !params.currency) {
      throw new BadRequestException('partnerId, periodStart, periodEnd, currency required');
    }

    await this.profileService.getProfile(params.partnerId);

    const periodStart = new Date(params.periodStart);
    const periodEnd = new Date(params.periodEnd);
    if (isNaN(periodStart.getTime()) || isNaN(periodEnd.getTime()) || periodStart >= periodEnd) {
      throw new BadRequestException('invalid period');
    }

    let settlement: any = null;
    if (params.settlementId) {
      settlement = await this.settlementService.getSettlement(params.settlementId, params.partnerId);
    }

    const commissions = await this.commissionLedger.listCommissions(params.partnerId, { currency: params.currency });
    const inPeriod = commissions.filter(c => {
      const accrued = new Date(c.accruedAt);
      return accrued >= periodStart && accrued <= periodEnd;
    });

    let gross = '0';
    let discount = '0';
    let netEligible = '0';
    let accrued = '0';
    let reversed = '0';
    const invoiceRefs: string[] = [];
    const paymentRefs: string[] = [];
    const subRefs: string[] = [];

    for (const com of inPeriod) {
      gross = this.addDecimal(gross, com.grossRevenue, params.currency);
      discount = this.addDecimal(discount, com.discountAmount, params.currency);
      netEligible = this.addDecimal(netEligible, com.netEligibleRevenue, params.currency);
      if (com.state === 'ACCRUED' || com.state === 'SETTLED' || com.state === 'PAID') {
        accrued = this.addDecimal(accrued, com.commissionAmount, params.currency);
      } else if (com.state === 'REVERSED') {
        reversed = this.addDecimal(reversed, com.commissionAmount, params.currency);
      }
      if (com.sourceInvoiceId) invoiceRefs.push(com.sourceInvoiceId);
      if (com.sourcePaymentId) paymentRefs.push(com.sourcePaymentId);
      if (com.sourceSubscriptionId) subRefs.push(com.sourceSubscriptionId);
    }

    const payable = this.addDecimal(accrued, reversed, params.currency);

    const statement: PartnerInvoiceStatement = {
      id: `pstmt_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      partnerId: params.partnerId,
      settlementId: settlement?.id ?? null,
      periodStart: periodStart.toISOString(),
      periodEnd: periodEnd.toISOString(),
      currency: params.currency.toUpperCase(),
      grossRevenue: gross,
      discount,
      netEligibleRevenue: netEligible,
      commissionAccrued: accrued,
      commissionReversed: reversed,
      commissionPayable: payable,
      commissionCount: inPeriod.length,
      invoiceReferences: [...new Set(invoiceRefs)],
      paymentReferences: [...new Set(paymentRefs)],
      subscriptionReferences: [...new Set(subRefs)],
      generatedAt: new Date().toISOString(),
      calculationVersion: '2026-01',
      policyVersion: settlement?.policyVersion ?? '2026-01',
      agreementVersion: settlement?.agreementVersion ?? 'v1',
      isImmutable: false,
    };

    this.logger.log(`partner invoice statement generated partner=${params.partnerId} payable=${payable} corr=${params.correlationId}`);
    return statement;
  }

  async listStatements(partnerId: string, filters?: { currency?: string }): Promise<PartnerInvoiceStatement[]> {
    // In production, this would query persisted statements
    // For now, generate from settlements
    const settlements = await this.settlementService.listSettlements(partnerId, { currency: filters?.currency });
    return settlements.map(s => ({
      id: `pstmt_${s.id}`,
      partnerId: s.partnerId,
      settlementId: s.id,
      periodStart: s.periodStart,
      periodEnd: s.periodEnd,
      currency: s.currency,
      grossRevenue: s.totalGrossRevenue,
      discount: s.totalDiscount,
      netEligibleRevenue: s.totalNetEligibleRevenue,
      commissionAccrued: s.totalCommissionAccrued,
      commissionReversed: s.totalCommissionReversed,
      commissionPayable: s.totalCommissionPayable,
      commissionCount: s.commissionCount,
      invoiceReferences: [],
      paymentReferences: [],
      subscriptionReferences: [],
      generatedAt: s.createdAt,
      calculationVersion: s.calculationVersion,
      policyVersion: s.policyVersion,
      agreementVersion: s.agreementVersion,
      isImmutable: true,
    }));
  }

  private getMinorUnit(currency: string): number {
    const map: Record<string, number> = { USD: 2, EUR: 2, GBP: 2, JPY: 0, USDT: 6, USDC: 6 };
    return map[currency.toUpperCase()] ?? 2;
  }

  private toMinorUnits(amount: string, currency: string): bigint {
    const minor = this.getMinorUnit(currency);
    const factor = Math.pow(10, minor);
    const parts = amount.toString().split('.');
    const intPart = BigInt(parts[0] || '0');
    let frac = parts[1] || '';
    if (frac.length > minor) frac = frac.slice(0, minor);
    while (frac.length < minor) frac += '0';
    const fracPart = BigInt(frac || '0');
    if (intPart < BigInt(0)) return intPart * BigInt(factor) - fracPart;
    return intPart * BigInt(factor) + fracPart;
  }

  private fromMinorUnits(minor: bigint, currency: string): string {
    const minorUnit = this.getMinorUnit(currency);
    const factor = BigInt(Math.pow(10, minorUnit));
    const isNegative = minor < BigInt(0);
    const abs = isNegative ? -minor : minor;
    const intPart = abs / factor;
    const fracPart = abs % factor;
    let fracStr = fracPart.toString().padStart(minorUnit, '0');
    if (minorUnit > 0) {
      fracStr = fracStr.replace(/0+$/, '');
      if (fracStr === '') fracStr = '0'.repeat(Math.min(2, minorUnit));
    }
    const result = minorUnit === 0 ? intPart.toString() : `${intPart.toString()}.${fracStr}`;
    return isNegative ? `-${result}` : result;
  }

  private addDecimal(a: string, b: string, currency: string): string {
    return this.fromMinorUnits(this.toMinorUnits(a, currency) + this.toMinorUnits(b, currency), currency);
  }
}

// # Enforces minimum payout thresholds, hold periods, and idempotent settlement
import { Injectable, Logger, BadRequestException, NotFoundException } from '@nestjs/common';
import { PartnerPayout, PartnerPayoutState, PARTNER_PAYOUT_TRANSITIONS, PartnerAuditAction, PartnerSettlementState } from './partner.types';
import { PartnerAuditService } from './partner-audit.service';
import { PartnerProfileService } from './partner-profile.service';
import { PartnerSettlementService } from './partner-settlement.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

@Injectable()
export class PartnerPayoutService {
  private readonly logger = new Logger(PartnerPayoutService.name);
  private readonly inMemory: Map<string, PartnerPayout> = new Map();
  private readonly idemIndex: Map<string, string> = new Map();

  constructor(
    private readonly audit: PartnerAuditService,
    private readonly profileService: PartnerProfileService,
    private readonly settlementService: PartnerSettlementService,
    private readonly prisma: PrismaService,
  ) {}

  async requestPayout(params: {
    partnerId: string;
    settlementId: string;
    amount: string;
    currency: string;
    method: string;
    requestedBy: string;
    correlationId: string;
    idempotencyKey: string;
  }): Promise<PartnerPayout> {
    if (!params.partnerId || !params.settlementId || !params.amount || !params.currency || !params.idempotencyKey) {
      throw new BadRequestException('partnerId, settlementId, amount, currency, idempotencyKey required');
    }

    await this.profileService.getProfile(params.partnerId);

    // Idempotency
    if (this.idemIndex.has(params.idempotencyKey)) {
      const existingId = this.idemIndex.get(params.idempotencyKey)!;
      const existing = this.inMemory.get(existingId);
      if (existing) return existing;
    }

    // Settlement must exist and be in appropriate state
    const settlement = await this.settlementService.getSettlement(params.settlementId, params.partnerId);
    if (settlement.state !== PartnerSettlementState.LOCKED && settlement.state !== PartnerSettlementState.PAYOUT_REQUESTED && settlement.state !== PartnerSettlementState.COMPLETED) {
      throw new BadRequestException(`settlement must be LOCKED to request payout, current ${settlement.state}`);
    }

    if (settlement.totalCommissionPayable !== params.amount && this.compareDecimal(settlement.totalCommissionPayable, params.amount, params.currency) !== 0) {
      // Allow but warn if mismatch - should match
      this.logger.warn(`payout amount ${params.amount} differs from settlement payable ${settlement.totalCommissionPayable}`);
    }

    if (settlement.currency.toUpperCase() !== params.currency.toUpperCase()) {
      throw new BadRequestException(`currency mismatch settlement ${settlement.currency} vs payout ${params.currency}`);
    }

    const payout: PartnerPayout = {
      id: `ppay_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      partnerId: params.partnerId,
      settlementId: params.settlementId,
      amount: params.amount,
      currency: params.currency.toUpperCase(),
      state: PartnerPayoutState.REQUESTED,
      method: params.method,
      providerPayoutId: null,
      providerReference: null,
      failureReason: null,
      requestedAt: new Date().toISOString(),
      requestedBy: params.requestedBy,
      approvedAt: null,
      approvedBy: null,
      submittedAt: null,
      completedAt: null,
      failedAt: null,
      reversedAt: null,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      idempotencyKey: params.idempotencyKey,
      correlationId: params.correlationId,
    };

    this.inMemory.set(payout.id, payout);
    this.idemIndex.set(params.idempotencyKey, payout.id);

    try {
      await (this.prisma as any).partnerPayout?.create?.({
        data: {
          id: payout.id,
          partnerId: payout.partnerId,
          settlementId: payout.settlementId,
          amount: payout.amount,
          currency: payout.currency,
          state: payout.state,
          method: payout.method,
          requestedAt: new Date(payout.requestedAt),
          requestedBy: payout.requestedBy,
          createdAt: new Date(payout.createdAt),
          updatedAt: new Date(payout.updatedAt),
          idempotencyKey: payout.idempotencyKey,
          correlationId: payout.correlationId,
        },
      });
    } catch {
      this.logger.debug(`payout persist skipped id=${payout.id}`);
    }

    await this.audit.recordEvent({
      partnerId: params.partnerId,
      actorId: params.requestedBy,
      action: PartnerAuditAction.PAYOUT_REQUESTED,
      source: 'PARTNER_PAYOUT_SERVICE',
      correlationId: params.correlationId,
      safeEvidence: { payoutId: payout.id, settlementId: params.settlementId, amount: payout.amount, currency: payout.currency },
    });

    this.logger.log(`payout requested id=${payout.id} partner=${params.partnerId} amount=${params.amount} corr=${params.correlationId}`);
    return payout;
  }

  async transitionState(params: {
    payoutId: string;
    partnerId: string;
    targetState: PartnerPayoutState;
    correlationId: string;
    actorId: string;
    providerPayoutId?: string;
    providerReference?: string;
    failureReason?: string;
  }): Promise<PartnerPayout> {
    const payout = await this.getPayout(params.payoutId, params.partnerId);
    const allowed = PARTNER_PAYOUT_TRANSITIONS[payout.state];
    if (!allowed.includes(params.targetState)) throw new BadRequestException(`invalid transition ${payout.state} -> ${params.targetState}`);

    // COMPLETED requires authoritative payout evidence
    if (params.targetState === PartnerPayoutState.COMPLETED) {
      if (!params.providerPayoutId || !params.providerReference) {
        throw new BadRequestException('COMPLETED requires authoritative payout evidence providerPayoutId and providerReference');
      }
      payout.providerPayoutId = params.providerPayoutId;
      payout.providerReference = params.providerReference;
      payout.completedAt = new Date().toISOString();
    }

    if (params.targetState === PartnerPayoutState.APPROVED) {
      payout.approvedAt = new Date().toISOString();
      payout.approvedBy = params.actorId;
    }
    if (params.targetState === PartnerPayoutState.SUBMITTED) payout.submittedAt = new Date().toISOString();
    if (params.targetState === PartnerPayoutState.FAILED) {
      if (!params.failureReason) throw new BadRequestException('failureReason required for FAILED');
      payout.failureReason = params.failureReason;
      payout.failedAt = new Date().toISOString();
    }
    if (params.targetState === PartnerPayoutState.REVERSED) payout.reversedAt = new Date().toISOString();

    const prev = payout.state;
    payout.state = params.targetState;
    payout.updatedAt = new Date().toISOString();

    this.inMemory.set(payout.id, payout);
    try {
      await (this.prisma as any).partnerPayout?.update?.({
        where: { id: payout.id },
        data: {
          state: payout.state,
          providerPayoutId: payout.providerPayoutId,
          providerReference: payout.providerReference,
          failureReason: payout.failureReason,
          approvedAt: payout.approvedAt ? new Date(payout.approvedAt) : null,
          approvedBy: payout.approvedBy,
          submittedAt: payout.submittedAt ? new Date(payout.submittedAt) : null,
          completedAt: payout.completedAt ? new Date(payout.completedAt) : null,
          failedAt: payout.failedAt ? new Date(payout.failedAt) : null,
          reversedAt: payout.reversedAt ? new Date(payout.reversedAt) : null,
          updatedAt: new Date(payout.updatedAt),
        },
      });
    } catch {
      this.logger.debug(`payout transition persist skipped id=${payout.id}`);
    }

    const auditAction = params.targetState === PartnerPayoutState.COMPLETED ? PartnerAuditAction.PAYOUT_COMPLETED
      : params.targetState === PartnerPayoutState.FAILED ? PartnerAuditAction.PAYOUT_FAILED
      : params.targetState === PartnerPayoutState.REVERSED ? PartnerAuditAction.PAYOUT_REVERSED
      : PartnerAuditAction.PAYOUT_REQUESTED;

    await this.audit.recordEvent({
      partnerId: params.partnerId,
      actorId: params.actorId,
      action: auditAction,
      source: 'PARTNER_PAYOUT_SERVICE',
      correlationId: params.correlationId,
      safeEvidence: { payoutId: payout.id, from: prev, to: params.targetState, providerPayoutId: payout.providerPayoutId },
    });

    this.logger.log(`payout transition id=${payout.id} ${prev} -> ${params.targetState} corr=${params.correlationId}`);
    return payout;
  }

  async getPayout(payoutId: string, partnerId: string): Promise<PartnerPayout> {
    const mem = this.inMemory.get(payoutId);
    if (mem) {
      if (mem.partnerId !== partnerId) throw new BadRequestException('partner isolation violation');
      return mem;
    }
    try {
      const row = await (this.prisma as any).partnerPayout?.findUnique?.({ where: { id: payoutId } });
      if (row) {
        if (row.partnerId !== partnerId) throw new BadRequestException('partner isolation violation');
        const mapped = this.mapRow(row);
        this.inMemory.set(mapped.id, mapped);
        return mapped;
      }
    } catch {}
    throw new NotFoundException(`payout ${payoutId} not found`);
  }

  async listPayouts(partnerId: string, filters?: { settlementId?: string; state?: PartnerPayoutState }): Promise<PartnerPayout[]> {
    let list = [...this.inMemory.values()].filter(p => p.partnerId === partnerId);
    if (filters?.settlementId) list = list.filter(p => p.settlementId === filters.settlementId);
    if (filters?.state) list = list.filter(p => p.state === filters.state);
    try {
      const where: any = { partnerId };
      if (filters?.settlementId) where.settlementId = filters.settlementId;
      if (filters?.state) where.state = filters.state;
      const rows = await (this.prisma as any).partnerPayout?.findMany?.({ where, take: 500, orderBy: { createdAt: 'desc' } });
      if (rows && rows.length > 0) list = rows.map((r: any) => this.mapRow(r));
    } catch {}
    return list;
  }

  private compareDecimal(a: string, b: string, currency: string): number {
    const getMinor = (c: string) => {
      const map: Record<string, number> = { USD: 2, EUR: 2, GBP: 2, JPY: 0, USDT: 6, USDC: 6 };
      return map[c.toUpperCase()] ?? 2;
    };
    const toMinor = (amt: string, curr: string) => {
      const minor = getMinor(curr);
      const factor = Math.pow(10, minor);
      const parts = amt.toString().split('.');
      const intPart = BigInt(parts[0] || '0');
      let frac = parts[1] || '';
      if (frac.length > minor) frac = frac.slice(0, minor);
      while (frac.length < minor) frac += '0';
      const fracPart = BigInt(frac || '0');
      return intPart * BigInt(factor) + fracPart;
    };
    const aMinor = toMinor(a, currency);
    const bMinor = toMinor(b, currency);
    if (aMinor < bMinor) return -1;
    if (aMinor > bMinor) return 1;
    return 0;
  }

  private mapRow(row: any): PartnerPayout {
    return {
      id: row.id,
      partnerId: row.partnerId,
      settlementId: row.settlementId,
      amount: row.amount,
      currency: row.currency,
      state: row.state,
      method: row.method,
      providerPayoutId: row.providerPayoutId ?? null,
      providerReference: row.providerReference ?? null,
      failureReason: row.failureReason ?? null,
      requestedAt: row.requestedAt instanceof Date ? row.requestedAt.toISOString() : row.requestedAt,
      requestedBy: row.requestedBy,
      approvedAt: row.approvedAt ? (row.approvedAt instanceof Date ? row.approvedAt.toISOString() : row.approvedAt) : null,
      approvedBy: row.approvedBy ?? null,
      submittedAt: row.submittedAt ? (row.submittedAt instanceof Date ? row.submittedAt.toISOString() : row.submittedAt) : null,
      completedAt: row.completedAt ? (row.completedAt instanceof Date ? row.completedAt.toISOString() : row.completedAt) : null,
      failedAt: row.failedAt ? (row.failedAt instanceof Date ? row.failedAt.toISOString() : row.failedAt) : null,
      reversedAt: row.reversedAt ? (row.reversedAt instanceof Date ? row.reversedAt.toISOString() : row.reversedAt) : null,
      createdAt: row.createdAt instanceof Date ? row.createdAt.toISOString() : row.createdAt,
      updatedAt: row.updatedAt instanceof Date ? row.updatedAt.toISOString() : row.updatedAt,
      idempotencyKey: row.idempotencyKey,
      correlationId: row.correlationId,
    };
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PartnerProfileService } from './partner-profile.service';
import { PartnerTenantService } from './partner-tenant.service';
import { PartnerCommissionLedgerService } from './partner-commission-ledger.service';
import { PartnerSettlementService } from './partner-settlement.service';
import { PartnerPayoutService } from './partner-payout.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

export interface PartnerPerformance {
  partnerId: string;
  periodStart?: string;
  periodEnd?: string;
  referredTenants: number;
  activeTenants: number;
  conversionRate: string;
  mrrAttributed: string;
  grossAttributedRevenue: string;
  netEligibleRevenue: string;
  commissionAccrued: string;
  commissionReversed: string;
  commissionPayable: string;
  commissionPaid: string;
  pendingSettlement: string;
  pendingPayout: string;
  refunds: number;
  chargebacks: number;
  churnRate: string;
  activeSubscriptions: number;
  customerRetentionRate: string;
  generatedAt: string;
  currency: string;
  calculationVersion: string;
}

@Injectable()
export class PartnerPerformanceService {
  private readonly logger = new Logger(PartnerPerformanceService.name);

  constructor(
    private readonly profileService: PartnerProfileService,
    private readonly tenantService: PartnerTenantService,
    private readonly commissionLedger: PartnerCommissionLedgerService,
    private readonly settlementService: PartnerSettlementService,
    private readonly payoutService: PartnerPayoutService,
    private readonly prisma: PrismaService,
  ) {}

  async calculatePerformance(params: {
    partnerId: string;
    periodStart?: string;
    periodEnd?: string;
    currency?: string;
    correlationId: string;
  }): Promise<PartnerPerformance> {
    if (!params.partnerId) throw new BadRequestException('partnerId required');
    await this.profileService.getProfile(params.partnerId);

    const currency = (params.currency ?? 'USD').toUpperCase();
    const periodStart = params.periodStart ? new Date(params.periodStart) : null;
    const periodEnd = params.periodEnd ? new Date(params.periodEnd) : null;

    const relationships = await this.tenantService.listTenantsForPartner(params.partnerId);
    const referredTenants = relationships.length;
    const activeTenants = relationships.filter(r => r.state === 'ACTIVE').length;

    const commissions = await this.commissionLedger.listCommissions(params.partnerId, { currency });
    let filteredCommissions = commissions;
    if (periodStart && periodEnd) {
      filteredCommissions = commissions.filter(c => {
        const accrued = new Date(c.accruedAt);
        return accrued >= periodStart && accrued <= periodEnd;
      });
    }

    let grossAttributed = '0';
    let netEligible = '0';
    let commissionAccrued = '0';
    let commissionReversed = '0';
    let refunds = 0;
    let chargebacks = 0;

    for (const com of filteredCommissions) {
      grossAttributed = this.addDecimal(grossAttributed, com.grossRevenue, currency);
      netEligible = this.addDecimal(netEligible, com.netEligibleRevenue, currency);
      if (com.state === 'ACCRUED' || com.state === 'SETTLED' || com.state === 'PAID' || com.state === 'PAYOUT_PENDING') {
        commissionAccrued = this.addDecimal(commissionAccrued, com.commissionAmount, currency);
      } else if (com.state === 'REVERSED') {
        commissionReversed = this.addDecimal(commissionReversed, com.commissionAmount, currency);
        if (com.sourceEventType === 'REFUND') refunds++;
        if (com.sourceEventType === 'CHARGEBACK') chargebacks++;
      }
    }

    const commissionPayable = this.addDecimal(commissionAccrued, commissionReversed, currency);

    const settlements = await this.settlementService.listSettlements(params.partnerId, { currency });
    let pendingSettlement = '0';
    for (const s of settlements.filter(s => s.state === 'OPEN' || s.state === 'RECONCILED' || s.state === 'VALIDATED')) {
      pendingSettlement = this.addDecimal(pendingSettlement, s.totalCommissionPayable, currency);
    }

    const payouts = await this.payoutService.listPayouts(params.partnerId);
    let commissionPaid = '0';
    let pendingPayout = '0';
    for (const p of payouts) {
      if (p.currency.toUpperCase() !== currency) continue;
      if (p.state === 'COMPLETED') commissionPaid = this.addDecimal(commissionPaid, p.amount, currency);
      else if (['REQUESTED', 'APPROVED', 'SUBMITTED', 'PROCESSING'].includes(p.state)) pendingPayout = this.addDecimal(pendingPayout, p.amount, currency);
    }

    // MRR attributed - from subscriptions
    let mrrAttributed = '0';
    let activeSubscriptions = 0;
    try {
      const tenantIds = relationships.filter(r => r.state === 'ACTIVE').map(r => r.tenantId);
      for (const tenantId of tenantIds) {
        const subs = await (this.prisma as any).tenantSubscription?.findMany?.({ where: { tenantId, status: { in: ['ACTIVE', 'TRIALING'] } }, include: { plan: true } }) ?? [];
        activeSubscriptions += subs.length;
        for (const sub of subs) {
          const planPrice = sub.plan?.price ?? sub.plan?.amount ?? '0';
          // MRR approximation: if yearly, divide by 12 - Decimal-safe
          if (sub.plan?.interval === 'YEARLY') {
            const yearlyMinor = this.toMinorUnits(planPrice.toString(), currency);
            const monthlyMinor = yearlyMinor / BigInt(12);
            mrrAttributed = this.addDecimal(mrrAttributed, this.fromMinorUnits(monthlyMinor, currency), currency);
          } else {
            mrrAttributed = this.addDecimal(mrrAttributed, planPrice.toString(), currency);
          }
        }
      }
    } catch {
      this.logger.debug(`MRR calculation fallback partner=${params.partnerId}`);
    }

    const conversionRate = referredTenants > 0 ? ((activeTenants / referredTenants) * 100).toFixed(2) : '0.00';
    const churnRate = referredTenants > 0 ? (((referredTenants - activeTenants) / referredTenants) * 100).toFixed(2) : '0.00';
    const retentionRate = (100 - parseFloat(churnRate)).toFixed(2);

    const performance: PartnerPerformance = {
      partnerId: params.partnerId,
      periodStart: periodStart?.toISOString(),
      periodEnd: periodEnd?.toISOString(),
      referredTenants,
      activeTenants,
      conversionRate,
      mrrAttributed,
      grossAttributedRevenue: grossAttributed,
      netEligibleRevenue: netEligible,
      commissionAccrued,
      commissionReversed,
      commissionPayable,
      commissionPaid,
      pendingSettlement,
      pendingPayout,
      refunds,
      chargebacks,
      churnRate,
      activeSubscriptions,
      customerRetentionRate: retentionRate,
      generatedAt: new Date().toISOString(),
      currency,
      calculationVersion: '2026-01',
    };

    this.logger.log(`performance calculated partner=${params.partnerId} MRR=${mrrAttributed} payable=${commissionPayable} corr=${params.correlationId}`);
    return performance;
  }

  private getMinorUnit(currency: string): number {
    const map: Record<string, number> = { USD: 2, EUR: 2, GBP: 2, JPY: 0, USDT: 6, USDC: 6 };
    return map[currency.toUpperCase()] ?? 2;
  }

  private toMinorUnits(amount: string, currency: string): bigint {
    const minor = this.getMinorUnit(currency);
    const factor = Math.pow(10, minor);
    const parts = amount.toString().split('.');
    const intPart = BigInt(parts[0] || '0');
    let frac = parts[1] || '';
    if (frac.length > minor) frac = frac.slice(0, minor);
    while (frac.length < minor) frac += '0';
    const fracPart = BigInt(frac || '0');
    if (intPart < BigInt(0)) return intPart * BigInt(factor) - fracPart;
    return intPart * BigInt(factor) + fracPart;
  }

  private fromMinorUnits(minor: bigint, currency: string): string {
    const minorUnit = this.getMinorUnit(currency);
    const factor = BigInt(Math.pow(10, minorUnit));
    const isNegative = minor < BigInt(0);
    const abs = isNegative ? -minor : minor;
    const intPart = abs / factor;
    const fracPart = abs % factor;
    let fracStr = fracPart.toString().padStart(minorUnit, '0');
    if (minorUnit > 0) {
      fracStr = fracStr.replace(/0+$/, '');
      if (fracStr === '') fracStr = '0'.repeat(Math.min(2, minorUnit));
    }
    const result = minorUnit === 0 ? intPart.toString() : `${intPart.toString()}.${fracStr}`;
    return isNegative ? `-${result}` : result;
  }

  private addDecimal(a: string, b: string, currency: string): string {
    return this.fromMinorUnits(this.toMinorUnits(a, currency) + this.toMinorUnits(b, currency), currency);
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PartnerProfileService } from './partner-profile.service';
import { PartnerAgreementService } from './partner-agreement.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

@Injectable()
export class PartnerPlanService {
  private readonly logger = new Logger(PartnerPlanService.name);

  constructor(
    private readonly profileService: PartnerProfileService,
    private readonly agreementService: PartnerAgreementService,
    private readonly prisma: PrismaService,
  ) {}

  /**
   * Resolves which existing subscription plans a partner may sell
   * Never duplicates plan definitions, never hardcodes prices
   */
  async getEligiblePlans(partnerId: string): Promise<any[]> {
    const profile = await this.profileService.getProfile(partnerId);
    const agreement = await this.agreementService.getActiveAgreement(partnerId);
    if (!agreement) throw new BadRequestException(`partner ${partnerId} has no active agreement`);

    // Fetch canonical plans from existing catalog
    let canonicalPlans: any[] = [];
    try {
      canonicalPlans = await (this.prisma as any).subscriptionPlan?.findMany?.({
        where: { deletedAt: null, isActive: true },
        take: 200,
        orderBy: { createdAt: 'asc' },
      }) ?? [];
    } catch {
      this.logger.debug('canonical plans fetch fallback');
    }

    if (canonicalPlans.length === 0) {
      this.logger.warn(`no canonical plans found for partner ${partnerId}`);
      return [];
    }

    // Filter by pricingRules from agreement
    const allowedPlanCodes = new Set(
      agreement.pricingRules.filter(r => r.allowed).map(r => r.planCode)
    );

    // If pricingRules empty, allow all (policy-driven)
    const eligible = allowedPlanCodes.size === 0
      ? canonicalPlans
      : canonicalPlans.filter((p: any) => allowedPlanCodes.has(p.code) || allowedPlanCodes.has(p.id));

    this.logger.log(`eligible plans partner=${partnerId} total=${eligible.length} corr=plan-eligibility`);
    return eligible.map((p: any) => ({
      id: p.id,
      code: p.code,
      name: p.name,
      interval: p.interval,
      isActive: p.isActive,
      trialDays: p.trialDays,
      // Never expose hardcoded prices from partner module - return from canonical source
      price: p.price ?? p.amount ?? null,
      currency: p.currency ?? 'USD',
      limits: p.limits,
      features: p.features,
      agreementVersion: `v${agreement.version}`,
      policyVersion: agreement.commissionPolicy.policyVersion,
    }));
  }

  async isPlanEligible(partnerId: string, planCode: string): Promise<boolean> {
    const eligible = await this.getEligiblePlans(partnerId);
    return eligible.some(p => p.code === planCode || p.id === planCode);
  }

  async assertPlanEligible(partnerId: string, planCode: string): Promise<void> {
    const eligible = await this.isPlanEligible(partnerId, planCode);
    if (!eligible) throw new BadRequestException(`plan ${planCode} not eligible for partner ${partnerId}`);
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import {
  PartnerPolicy,
  PartnerType,
  PartnerCommissionModel,
  PartnerCommissionBasis,
  PartnerDiscountType,
  CommissionRateConfig,
} from './partner.types';

/**
 * Environment values always arrive as strings - `config.get<number>()` only
 * changes the static type, it does not convert. Without this the policy would
 * carry "3000" / "720" as strings into persisted JSON and Int columns.
 * A malformed value is a misconfiguration and fails loudly.
 */
function envInteger(raw: unknown, fallback: number, name: string, min: number, max: number): number {
  if (raw === undefined || raw === null || (typeof raw === 'string' && raw.trim() === '')) return fallback;
  const n = typeof raw === 'number' ? raw : Number(String(raw).trim());
  if (!Number.isInteger(n) || n < min || n > max) {
    throw new Error(`partner policy: ${name} must be an integer between ${min} and ${max}, got ${JSON.stringify(raw)}`);
  }
  return n;
}

@Injectable()
export class PartnerPolicyService {
  private readonly logger = new Logger(PartnerPolicyService.name);
  private readonly policyVersion: string;
  private readonly defaultCommissionBasis: PartnerCommissionBasis;
  private readonly settlementCurrency: string;
  private readonly allowedCurrencies: string[];
  private readonly maxDiscountBasisPoints: number;
  private readonly attributionWindowHours: number;

  constructor(private readonly config: ConfigService) {
    this.policyVersion = this.config.get<string>('PARTNER_POLICY_VERSION', '2026-01') ?? '2026-01';
    const basisRaw = this.config.get<string>('PARTNER_COMMISSION_BASIS', PartnerCommissionBasis.COLLECTED_REVENUE);
    this.defaultCommissionBasis = (basisRaw as PartnerCommissionBasis) ?? PartnerCommissionBasis.COLLECTED_REVENUE;
    this.settlementCurrency = this.config.get<string>('PARTNER_SETTLEMENT_CURRENCY', 'USD') ?? 'USD';
    const currenciesRaw = this.config.get<string>('PARTNER_ALLOWED_CURRENCIES', 'USD,EUR,GBP,USDT,USDC') ?? 'USD,EUR,GBP,USDT,USDC';
    this.allowedCurrencies = currenciesRaw.split(',').map(c => c.trim().toUpperCase()).filter(Boolean);
    this.maxDiscountBasisPoints = envInteger(
      this.config.get<unknown>('PARTNER_MAX_DISCOUNT_BPS'), 3000, 'PARTNER_MAX_DISCOUNT_BPS', 0, 10000,
    );
    this.attributionWindowHours = envInteger(
      this.config.get<unknown>('PARTNER_ATTRIBUTION_WINDOW_HOURS'), 720, 'PARTNER_ATTRIBUTION_WINDOW_HOURS', 1, 8760,
    );
  }

  getPolicyVersion(): string {
    return this.policyVersion;
  }

  /**
   * Resolves partner policy from platform/tenant configuration.
   * Never invents values - all rates come from config/database.
   */
  resolvePolicy(params: {
    partnerType: PartnerType;
    tenantId?: string | null;
    agreementVersion?: string;
    storedPolicy?: Partial<PartnerPolicy>;
  }): PartnerPolicy {
    if (!params.partnerType) throw new BadRequestException('partnerType required');
    if (!Object.values(PartnerType).includes(params.partnerType)) {
      throw new BadRequestException(`invalid partnerType ${params.partnerType}`);
    }

    // Base policy from configuration - never hardcoded percentages
    const baseRates = this.getCommissionRatesFromConfig(params.partnerType);

    const policy: PartnerPolicy = {
      partnerType: params.partnerType,
      allowedPartnerTypes: this.getAllowedTypes(params.partnerType),
      onboardingRequirements: this.getOnboardingRequirements(params.partnerType),
      commissionBasis: params.storedPolicy?.commissionBasis ?? this.defaultCommissionBasis,
      commissionModels: params.storedPolicy?.commissionModels ?? this.getCommissionModels(params.partnerType),
      commissionRates: params.storedPolicy?.commissionRates ?? baseRates,
      discountRules: params.storedPolicy?.discountRules ?? {
        maxDiscountBasisPoints: this.maxDiscountBasisPoints,
        allowedDiscountTypes: [PartnerDiscountType.PERCENTAGE, PartnerDiscountType.FIXED_AMOUNT, PartnerDiscountType.CAMPAIGN],
        stackingAllowed: false,
        requiresApproval: true,
        allowedCurrencies: this.allowedCurrencies,
        maxActiveDiscounts: 10,
      },
      attributionWindowHours: params.storedPolicy?.attributionWindowHours ?? this.attributionWindowHours,
      settlementSchedule: params.storedPolicy?.settlementSchedule ?? {
        frequency: 'MONTHLY',
        dayOfMonth: 1,
        minPayoutAmount: this.config.get<string>('PARTNER_MIN_PAYOUT_AMOUNT', '50.00') ?? '50.00',
        currency: this.settlementCurrency,
        autoSettlement: false,
      },
      payoutRequirements: params.storedPolicy?.payoutRequirements ?? {
        minPayoutAmount: this.config.get<string>('PARTNER_MIN_PAYOUT_AMOUNT', '50.00') ?? '50.00',
        allowedMethods: ['BANK_TRANSFER', 'CRYPTO', 'PAYPAL'],
        requiresApproval: true,
        kycRequired: true,
      },
      subPartnerAllowed: params.storedPolicy?.subPartnerAllowed ?? (params.partnerType === PartnerType.INSTITUTIONAL_DISTRIBUTOR),
      currencyPolicy: params.storedPolicy?.currencyPolicy ?? {
        allowedCurrencies: this.allowedCurrencies,
        settlementCurrency: this.settlementCurrency,
        fxRequired: false,
        allowMultiCurrency: false,
      },
      terminationRules: params.storedPolicy?.terminationRules ?? {
        noticePeriodDays: 30,
        settlementOnTermination: true,
        commissionForfeiture: false,
      },
      policyVersion: this.policyVersion,
      agreementVersion: params.agreementVersion ?? 'v1',
      trialCommissionEligible: params.storedPolicy?.trialCommissionEligible ?? false,
      lifetimeCommissionModel: params.storedPolicy?.lifetimeCommissionModel ?? PartnerCommissionModel.FIXED_AMOUNT,
      refundPolicy: params.storedPolicy?.refundPolicy ?? {
        reversalRequired: true,
        reversalBasis: 'PROPORTIONAL',
        deductionFromFutureSettlement: true,
      },
      chargebackPolicy: params.storedPolicy?.chargebackPolicy ?? {
        reversalRequired: true,
        recoveryRequired: true,
        deductionFromFutureSettlement: true,
        createsOutstandingBalance: true,
      },
    };

    this.validatePolicy(policy);
    return policy;
  }

  private getAllowedTypes(partnerType: PartnerType): PartnerType[] {
    // Policy-driven allowed sub-types
    switch (partnerType) {
      case PartnerType.INSTITUTIONAL_DISTRIBUTOR:
        return [PartnerType.RESELLER, PartnerType.AGENCY, PartnerType.AFFILIATE, PartnerType.REFERRAL_PARTNER];
      case PartnerType.MANAGED_SERVICE_PROVIDER:
        return [PartnerType.RESELLER, PartnerType.AGENCY];
      default:
        return [];
    }
  }

  private getOnboardingRequirements(partnerType: PartnerType): string[] {
    const base = ['KYC', 'BUSINESS_VERIFICATION', 'TAX_FORM'];
    if ([PartnerType.WHITE_LABEL_PARTNER, PartnerType.INSTITUTIONAL_DISTRIBUTOR].includes(partnerType)) {
      return [...base, 'AGREEMENT_SIGNED', 'TECHNICAL_REVIEW'];
    }
    return base;
  }

  private getCommissionModels(partnerType: PartnerType): PartnerCommissionModel[] {
    switch (partnerType) {
      case PartnerType.AFFILIATE:
      case PartnerType.REFERRAL_PARTNER:
        return [PartnerCommissionModel.PERCENTAGE_REVENUE, PartnerCommissionModel.FIRST_PERIOD];
      case PartnerType.RESELLER:
      case PartnerType.AGENCY:
        return [PartnerCommissionModel.PERCENTAGE_REVENUE, PartnerCommissionModel.RECURRING_PERIOD, PartnerCommissionModel.FIXED_AMOUNT];
      case PartnerType.WHITE_LABEL_PARTNER:
      case PartnerType.MANAGED_SERVICE_PROVIDER:
      case PartnerType.INSTITUTIONAL_DISTRIBUTOR:
        return [PartnerCommissionModel.PERCENTAGE_REVENUE, PartnerCommissionModel.RECURRING_PERIOD, PartnerCommissionModel.HYBRID];
      default:
        return [PartnerCommissionModel.PERCENTAGE_REVENUE];
    }
  }

  private getCommissionRatesFromConfig(partnerType: PartnerType): CommissionRateConfig[] {
    // Rates must come from config/database, never hardcoded
    // We read from env var PARTNER_COMMISSION_RATES_JSON if provided, else empty - caller must provide via agreement
    const raw = this.config.get<string>('PARTNER_COMMISSION_RATES_JSON', '');
    if (raw) {
      try {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) {
          return parsed.map((r: any) => ({
            model: r.model,
            basis: r.basis ?? this.defaultCommissionBasis,
            rateBasisPoints: r.rateBasisPoints,
            fixedAmount: r.fixedAmount,
            currency: r.currency ?? this.settlementCurrency,
            firstPeriodOnly: r.firstPeriodOnly,
            recurringPeriods: r.recurringPeriods,
            minEligibleAmount: r.minEligibleAmount,
            maxCommissionAmount: r.maxCommissionAmount,
            planCodes: r.planCodes,
            effectiveFrom: r.effectiveFrom ?? new Date().toISOString(),
            effectiveTo: r.effectiveTo ?? null,
          }));
        }
      } catch {
        this.logger.warn('Failed to parse PARTNER_COMMISSION_RATES_JSON, using empty rates - agreement must provide rates');
      }
    }
    // Return empty - forces agreement to provide explicit rates, never invent
    return [];
  }

  private validatePolicy(policy: PartnerPolicy): void {
    if (!policy.commissionBasis) throw new BadRequestException('commissionBasis required');
    if (!Object.values(PartnerCommissionBasis).includes(policy.commissionBasis)) {
      throw new BadRequestException(`invalid commissionBasis ${policy.commissionBasis}`);
    }
    if (policy.attributionWindowHours <= 0 || policy.attributionWindowHours > 8760 * 2) {
      throw new BadRequestException('attributionWindowHours must be 1-17520');
    }
    if (policy.commissionRates.length > 0) {
      for (const rate of policy.commissionRates) {
        if (rate.rateBasisPoints !== undefined && (rate.rateBasisPoints < 0 || rate.rateBasisPoints > 10000)) {
          throw new BadRequestException(`invalid rateBasisPoints ${rate.rateBasisPoints}`);
        }
        if (rate.fixedAmount !== undefined) {
          const amt = parseFloat(rate.fixedAmount);
          if (isNaN(amt) || amt < 0) throw new BadRequestException(`invalid fixedAmount ${rate.fixedAmount}`);
        }
      }
    }
    if (!policy.currencyPolicy.allowedCurrencies.includes(policy.currencyPolicy.settlementCurrency)) {
      throw new BadRequestException('settlementCurrency must be in allowedCurrencies');
    }
  }

  resolveCommissionBasis(policy: PartnerPolicy): PartnerCommissionBasis {
    return policy.commissionBasis;
  }

  isTrialCommissionEligible(policy: PartnerPolicy): boolean {
    return policy.trialCommissionEligible;
  }

  getAttributionWindowHours(policy: PartnerPolicy): number {
    return policy.attributionWindowHours;
  }

  isSubPartnerAllowed(policy: PartnerPolicy): boolean {
    return policy.subPartnerAllowed;
  }

  validateDiscount(policy: PartnerPolicy, discountBasisPoints: number, currency: string, fixedAmount?: string): void {
    if (discountBasisPoints > policy.discountRules.maxDiscountBasisPoints) {
      throw new BadRequestException(`discount ${discountBasisPoints}bps exceeds max ${policy.discountRules.maxDiscountBasisPoints}bps`);
    }
    if (!policy.discountRules.allowedCurrencies.includes(currency.toUpperCase())) {
      throw new BadRequestException(`currency ${currency} not allowed for discounts`);
    }
    if (fixedAmount) {
      const amt = parseFloat(fixedAmount);
      if (isNaN(amt) || amt < 0) throw new BadRequestException('invalid fixed discount amount');
      if (policy.discountRules.maxDiscountFixedAmount) {
        const max = parseFloat(policy.discountRules.maxDiscountFixedAmount);
        if (amt > max) throw new BadRequestException(`fixed discount ${amt} exceeds max ${max}`);
      }
    }
  }

  validateCurrency(policy: PartnerPolicy, currency: string): void {
    if (!policy.currencyPolicy.allowedCurrencies.includes(currency.toUpperCase())) {
      throw new BadRequestException(`currency ${currency} not allowed`);
    }
  }

  getSettlementCurrency(policy: PartnerPolicy): string {
    return policy.currencyPolicy.settlementCurrency;
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PartnerAgreementService } from './partner-agreement.service';
import { PartnerPolicyService } from './partner-policy.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

export interface EffectivePrice {
  platformListPrice: string;
  partnerDiscount: string;
  customerNetPrice: string;
  currency: string;
  pricingPolicyVersion: string;
  agreementVersion: string;
  planCode: string;
  discountBasisPoints?: number;
  calculationVersion: string;
}

@Injectable()
export class PartnerPricingService {
  private readonly logger = new Logger(PartnerPricingService.name);

  constructor(
    private readonly agreementService: PartnerAgreementService,
    private readonly policyService: PartnerPolicyService,
    private readonly prisma: PrismaService,
  ) {}

  /**
   * Resolves effective customer price from canonical SubscriptionPlan + approved partner pricing/discount policy
   * Uses Decimal-safe arithmetic and preserves original platform price, discount, net customer price
   */
  async resolveEffectivePrice(params: {
    partnerId: string;
    planCode: string;
    currency?: string;
    campaignId?: string;
    discountCode?: string;
  }): Promise<EffectivePrice> {
    if (!params.partnerId || !params.planCode) throw new BadRequestException('partnerId and planCode required');

    const agreement = await this.agreementService.getActiveAgreement(params.partnerId);
    if (!agreement) throw new BadRequestException(`no active agreement for partner ${params.partnerId}`);

    // Fetch canonical plan price - never hardcode
    let canonicalPlan: any = null;
    try {
      canonicalPlan = await (this.prisma as any).subscriptionPlan?.findFirst?.({ where: { code: params.planCode, deletedAt: null } })
        ?? await (this.prisma as any).subscriptionPlan?.findFirst?.({ where: { id: params.planCode } });
    } catch {
      this.logger.debug(`canonical plan fetch fallback planCode=${params.planCode}`);
    }

    if (!canonicalPlan) throw new BadRequestException(`canonical plan ${params.planCode} not found`);

    const platformListPrice = (canonicalPlan.price ?? canonicalPlan.amount ?? '0').toString();
    const planCurrency = (canonicalPlan.currency ?? 'USD').toUpperCase();
    const targetCurrency = (params.currency ?? planCurrency).toUpperCase();

    if (targetCurrency !== planCurrency) {
      // Multi-currency must remain explicit - check policy
      this.policyService.validateCurrency(agreement.commissionPolicy, targetCurrency);
    }

    // Resolve pricing rule from agreement
    const pricingRule = agreement.pricingRules.find(r => r.planCode === params.planCode || r.planCode === canonicalPlan.code);
    let partnerDiscount = '0';
    let discountBps = 0;

    if (pricingRule) {
      if (!pricingRule.allowed) throw new BadRequestException(`plan ${params.planCode} not allowed per agreement`);
      if (pricingRule.partnerPriceOverride) {
        // Partner price override - calculate discount as difference
        const override = pricingRule.partnerPriceOverride;
        partnerDiscount = this.subtractDecimal(platformListPrice, override, planCurrency);
        if (this.isNegative(partnerDiscount)) partnerDiscount = '0';
      } else if (pricingRule.discountBasisPoints) {
        discountBps = pricingRule.discountBasisPoints;
        this.policyService.validateDiscount(agreement.commissionPolicy, discountBps, targetCurrency);
        partnerDiscount = this.calculatePercentage(platformListPrice, discountBps, planCurrency);
      }
    }

    // Campaign discount if provided - must not mutate invoice directly
    if (params.campaignId) {
      try {
        const campaign = await (this.prisma as any).partnerCampaign?.findUnique?.({ where: { id: params.campaignId } });
        if (campaign && campaign.partnerId === params.partnerId && campaign.state === 'ACTIVE') {
          const now = new Date();
          const startsAt = new Date(campaign.startsAt);
          const endsAt = campaign.endsAt ? new Date(campaign.endsAt) : null;
          if (now >= startsAt && (!endsAt || now <= endsAt)) {
            if (campaign.discountType === 'PERCENTAGE' && campaign.discountValue) {
              const campBps = Math.round(parseFloat(campaign.discountValue) * 100);
              if (!agreement.commissionPolicy.discountRules.stackingAllowed && discountBps > 0) {
                throw new BadRequestException('discount stacking not allowed per policy');
              }
              const campDiscount = this.calculatePercentage(platformListPrice, campBps, planCurrency);
              partnerDiscount = this.addDecimal(partnerDiscount, campDiscount, planCurrency);
              discountBps += campBps;
            } else if (campaign.discountType === 'FIXED_AMOUNT' && campaign.discountValue) {
              if (!agreement.commissionPolicy.discountRules.stackingAllowed && this.compareDecimal(partnerDiscount, '0', planCurrency) > 0) {
                throw new BadRequestException('discount stacking not allowed');
              }
              partnerDiscount = this.addDecimal(partnerDiscount, campaign.discountValue, planCurrency);
            }
          }
        }
      } catch (e) {
        if (e instanceof BadRequestException) throw e;
        this.logger.debug(`campaign discount lookup skipped campaignId=${params.campaignId}`);
      }
    }

    const customerNetPrice = this.subtractDecimal(platformListPrice, partnerDiscount, planCurrency);
    if (this.isNegative(customerNetPrice)) throw new BadRequestException('discount exceeds platform price');

    const effective: EffectivePrice = {
      platformListPrice,
      partnerDiscount,
      customerNetPrice,
      currency: targetCurrency,
      pricingPolicyVersion: agreement.commissionPolicy.policyVersion,
      agreementVersion: `v${agreement.version}`,
      planCode: canonicalPlan.code ?? params.planCode,
      discountBasisPoints: discountBps || undefined,
      calculationVersion: `calc_${agreement.commissionPolicy.policyVersion}_${agreement.version}`,
    };

    this.logger.log(`effective price partner=${params.partnerId} plan=${params.planCode} list=${platformListPrice} discount=${partnerDiscount} net=${customerNetPrice} corr=pricing`);
    return effective;
  }

  // Decimal-safe arithmetic using minor units to avoid floating point
  private getMinorUnit(currency: string): number {
    const map: Record<string, number> = { USD: 2, EUR: 2, GBP: 2, JPY: 0, USDT: 6, USDC: 6, BTC: 8, ETH: 18 };
    return map[currency.toUpperCase()] ?? 2;
  }

  private toMinorUnits(amount: string, currency: string): bigint {
    const minor = this.getMinorUnit(currency);
    const factor = Math.pow(10, minor);
    // Parse string safely
    const parts = amount.toString().split('.');
    const integerPart = BigInt(parts[0] || '0');
    let fractional = parts[1] || '';
    if (fractional.length > minor) fractional = fractional.slice(0, minor);
    while (fractional.length < minor) fractional += '0';
    const fractionalPart = BigInt(fractional || '0');
    if (integerPart < BigInt(0)) {
      return integerPart * BigInt(factor) - fractionalPart;
    }
    return integerPart * BigInt(factor) + fractionalPart;
  }

  private fromMinorUnits(minor: bigint, currency: string): string {
    const minorUnit = this.getMinorUnit(currency);
    const factor = BigInt(Math.pow(10, minorUnit));
    const isNegative = minor < BigInt(0);
    const abs = isNegative ? -minor : minor;
    const integerPart = abs / factor;
    const fractionalPart = abs % factor;
    let fractionalStr = fractionalPart.toString().padStart(minorUnit, '0');
    // Trim trailing zeros but keep at least 2 decimals for USD-like
    if (minorUnit > 0) {
      fractionalStr = fractionalStr.replace(/0+$/, '');
      if (fractionalStr === '') fractionalStr = '0'.repeat(Math.min(2, minorUnit));
      else if (fractionalStr.length < 2 && ['USD', 'EUR', 'GBP'].includes(currency.toUpperCase())) {
        fractionalStr = fractionalStr.padEnd(2, '0');
      }
    }
    const result = minorUnit === 0 ? integerPart.toString() : `${integerPart.toString()}.${fractionalStr}`;
    return isNegative ? `-${result}` : result;
  }

  private addDecimal(a: string, b: string, currency: string): string {
    const aMinor = this.toMinorUnits(a, currency);
    const bMinor = this.toMinorUnits(b, currency);
    return this.fromMinorUnits(aMinor + bMinor, currency);
  }

  private subtractDecimal(a: string, b: string, currency: string): string {
    const aMinor = this.toMinorUnits(a, currency);
    const bMinor = this.toMinorUnits(b, currency);
    return this.fromMinorUnits(aMinor - bMinor, currency);
  }

  private calculatePercentage(amount: string, basisPoints: number, currency: string): string {
    const minor = this.toMinorUnits(amount, currency);
    // basisPoints / 10000
    const result = (minor * BigInt(basisPoints)) / BigInt(10000);
    return this.fromMinorUnits(result, currency);
  }

  private isNegative(amount: string): boolean {
    return amount.trim().startsWith('-');
  }

  private compareDecimal(a: string, b: string, currency: string): number {
    const aMinor = this.toMinorUnits(a, currency);
    const bMinor = this.toMinorUnits(b, currency);
    if (aMinor < bMinor) return -1;
    if (aMinor > bMinor) return 1;
    return 0;
  }
}

import { Injectable, Logger, BadRequestException, NotFoundException, ConflictException } from '@nestjs/common';
import { PartnerProfile, PartnerState, PartnerType, PARTNER_STATE_TRANSITIONS, PartnerAuditAction } from './partner.types';
import { PartnerPolicyService } from './partner-policy.service';
import { PartnerAuditService } from './partner-audit.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

@Injectable()
export class PartnerProfileService {
  private readonly logger = new Logger(PartnerProfileService.name);
  private readonly inMemory: Map<string, PartnerProfile> = new Map();
  private readonly codeIndex: Map<string, string> = new Map(); // code -> id

  constructor(
    private readonly policyService: PartnerPolicyService,
    private readonly audit: PartnerAuditService,
    private readonly prisma: PrismaService,
  ) {}

  async createProfile(params: {
    name: string;
    legalName?: string;
    type: PartnerType;
    ownerUserId: string;
    contactEmail: string;
    contactName?: string;
    website?: string;
    countryCode?: string;
    taxId?: string;
    billingEmail?: string;
    currency: string;
    idempotencyKey: string;
    correlationId: string;
    createdBy: string;
    code?: string;
    metadata?: Record<string, unknown>;
  }): Promise<PartnerProfile> {
    if (!params.name || !params.type || !params.ownerUserId || !params.contactEmail || !params.idempotencyKey) {
      throw new BadRequestException('name, type, ownerUserId, contactEmail, idempotencyKey required');
    }
    if (!Object.values(PartnerType).includes(params.type)) throw new BadRequestException(`invalid partner type ${params.type}`);

    // Idempotency check
    const existingByIdem = [...this.inMemory.values()].find(p => p.idempotencyKey === params.idempotencyKey);
    if (existingByIdem) {
      this.logger.log(`partner create idempotent hit key=${params.idempotencyKey}`);
      return existingByIdem;
    }
    try {
      const row = await (this.prisma as any).partnerProfile?.findFirst?.({ where: { idempotencyKey: params.idempotencyKey } });
      if (row) return this.mapRow(row);
    } catch {}

    const code = params.code ?? this.generateCode(params.name);
    if (this.codeIndex.has(code)) throw new ConflictException(`partner code ${code} already exists`);

    const profile: PartnerProfile = {
      id: `part_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      code,
      name: params.name,
      legalName: params.legalName ?? null,
      type: params.type,
      state: PartnerState.PENDING,
      ownerUserId: params.ownerUserId,
      contactEmail: params.contactEmail,
      contactName: params.contactName ?? null,
      website: params.website ?? null,
      countryCode: params.countryCode ?? null,
      taxId: params.taxId ?? null,
      billingEmail: params.billingEmail ?? null,
      currency: params.currency.toUpperCase(),
      idempotencyKey: params.idempotencyKey,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      activatedAt: null,
      suspendedAt: null,
      terminatedAt: null,
      metadata: params.metadata ?? null,
      policyVersion: this.policyService.getPolicyVersion(),
      agreementVersion: null,
    };

    this.inMemory.set(profile.id, profile);
    this.codeIndex.set(code, profile.id);

    try {
      await (this.prisma as any).partnerProfile?.create?.({
        data: {
          id: profile.id,
          code: profile.code,
          name: profile.name,
          legalName: profile.legalName,
          type: profile.type,
          state: profile.state,
          ownerUserId: profile.ownerUserId,
          contactEmail: profile.contactEmail,
          contactName: profile.contactName,
          website: profile.website,
          countryCode: profile.countryCode,
          taxId: profile.taxId,
          billingEmail: profile.billingEmail,
          currency: profile.currency,
          idempotencyKey: profile.idempotencyKey,
          createdAt: new Date(profile.createdAt),
          updatedAt: new Date(profile.updatedAt),
          policyVersion: profile.policyVersion,
          metadata: profile.metadata as any,
        },
      });
    } catch {
      this.logger.debug(`partner persist skipped id=${profile.id}`);
    }

    await this.audit.recordEvent({
      partnerId: profile.id,
      actorId: params.createdBy,
      action: PartnerAuditAction.PARTNER_CREATED,
      source: 'PARTNER_PROFILE_SERVICE',
      correlationId: params.correlationId,
      policyVersion: profile.policyVersion,
      safeEvidence: { code: profile.code, type: profile.type, state: profile.state },
    });

    this.logger.log(`partner created id=${profile.id} code=${code} corr=${params.correlationId}`);
    return profile;
  }

  async transitionState(params: {
    partnerId: string;
    targetState: PartnerState;
    correlationId: string;
    actorId: string;
    actorRole?: string;
    reason?: string;
  }): Promise<PartnerProfile> {
    const profile = await this.getProfile(params.partnerId);
    const allowed = PARTNER_STATE_TRANSITIONS[profile.state];
    if (!allowed.includes(params.targetState)) {
      throw new BadRequestException(`invalid transition ${profile.state} -> ${params.targetState}`);
    }

    const prevState = profile.state;
    profile.state = params.targetState;
    profile.updatedAt = new Date().toISOString();
    if (params.targetState === PartnerState.ACTIVE) profile.activatedAt = new Date().toISOString();
    if (params.targetState === PartnerState.SUSPENDED) profile.suspendedAt = new Date().toISOString();
    if (params.targetState === PartnerState.TERMINATED) profile.terminatedAt = new Date().toISOString();

    this.inMemory.set(profile.id, profile);
    try {
      await (this.prisma as any).partnerProfile?.update?.({
        where: { id: profile.id },
        data: {
          state: profile.state,
          updatedAt: new Date(profile.updatedAt),
          activatedAt: profile.activatedAt ? new Date(profile.activatedAt) : null,
          suspendedAt: profile.suspendedAt ? new Date(profile.suspendedAt) : null,
          terminatedAt: profile.terminatedAt ? new Date(profile.terminatedAt) : null,
        },
      });
    } catch {
      this.logger.debug(`partner transition persist skipped id=${profile.id}`);
    }

    const auditAction = this.mapStateToAudit(params.targetState);
    await this.audit.recordEvent({
      partnerId: profile.id,
      actorId: params.actorId,
      actorRole: params.actorRole,
      action: auditAction,
      source: 'PARTNER_PROFILE_SERVICE',
      correlationId: params.correlationId,
      policyVersion: profile.policyVersion,
      safeEvidence: { from: prevState, to: params.targetState, reason: params.reason },
    });

    this.logger.log(`partner transition id=${profile.id} ${prevState} -> ${params.targetState} corr=${params.correlationId}`);
    return profile;
  }

  private mapStateToAudit(state: PartnerState): PartnerAuditAction {
    switch (state) {
      case PartnerState.ACTIVE: return PartnerAuditAction.PARTNER_APPROVED;
      case PartnerState.SUSPENDED: return PartnerAuditAction.PARTNER_SUSPENDED;
      case PartnerState.TERMINATED: return PartnerAuditAction.PARTNER_TERMINATED;
      case PartnerState.REACTIVATION_REVIEW: return PartnerAuditAction.PARTNER_REACTIVATED;
      default: return PartnerAuditAction.PARTNER_APPROVED;
    }
  }

  async getProfile(partnerId: string): Promise<PartnerProfile> {
    const mem = this.inMemory.get(partnerId);
    if (mem) return mem;
    try {
      const row = await (this.prisma as any).partnerProfile?.findUnique?.({ where: { id: partnerId } });
      if (row) {
        const mapped = this.mapRow(row);
        this.inMemory.set(mapped.id, mapped);
        this.codeIndex.set(mapped.code, mapped.id);
        return mapped;
      }
    } catch {}
    throw new NotFoundException(`partner ${partnerId} not found`);
  }

  async getByCode(code: string): Promise<PartnerProfile> {
    const id = this.codeIndex.get(code);
    if (id) {
      const mem = this.inMemory.get(id);
      if (mem) return mem;
    }
    try {
      const row = await (this.prisma as any).partnerProfile?.findFirst?.({ where: { code } });
      if (row) return this.mapRow(row);
    } catch {}
    throw new NotFoundException(`partner code ${code} not found`);
  }

  async listProfiles(filters?: { state?: PartnerState; type?: PartnerType; ownerUserId?: string }): Promise<PartnerProfile[]> {
    let list = [...this.inMemory.values()];
    if (filters?.state) list = list.filter(p => p.state === filters.state);
    if (filters?.type) list = list.filter(p => p.type === filters.type);
    if (filters?.ownerUserId) list = list.filter(p => p.ownerUserId === filters.ownerUserId);
    try {
      const where: any = {};
      if (filters?.state) where.state = filters.state;
      if (filters?.type) where.type = filters.type;
      if (filters?.ownerUserId) where.ownerUserId = filters.ownerUserId;
      const rows = await (this.prisma as any).partnerProfile?.findMany?.({ where, take: 500, orderBy: { createdAt: 'desc' } });
      if (rows && rows.length > 0) list = rows.map((r: any) => this.mapRow(r));
    } catch {}
    return list;
  }

  async updateProfile(partnerId: string, updates: { name?: string; legalName?: string; contactEmail?: string; contactName?: string; website?: string; billingEmail?: string; metadata?: Record<string, unknown> }, correlationId: string, actorId: string): Promise<PartnerProfile> {
    const profile = await this.getProfile(partnerId);
    if (profile.state === PartnerState.TERMINATED) throw new BadRequestException('cannot update terminated partner');

    if (updates.name) profile.name = updates.name;
    if (updates.legalName !== undefined) profile.legalName = updates.legalName || null;
    if (updates.contactEmail) profile.contactEmail = updates.contactEmail;
    if (updates.contactName !== undefined) profile.contactName = updates.contactName || null;
    if (updates.website !== undefined) profile.website = updates.website || null;
    if (updates.billingEmail !== undefined) profile.billingEmail = updates.billingEmail || null;
    if (updates.metadata) profile.metadata = { ...(profile.metadata ?? {}), ...updates.metadata };
    profile.updatedAt = new Date().toISOString();

    this.inMemory.set(profile.id, profile);
    try {
      await (this.prisma as any).partnerProfile?.update?.({
        where: { id: profile.id },
        data: {
          name: profile.name,
          legalName: profile.legalName,
          contactEmail: profile.contactEmail,
          contactName: profile.contactName,
          website: profile.website,
          billingEmail: profile.billingEmail,
          metadata: profile.metadata as any,
          updatedAt: new Date(profile.updatedAt),
        },
      });
    } catch {
      this.logger.debug(`partner update persist skipped id=${profile.id}`);
    }

    return profile;
  }

  private generateCode(name: string): string {
    const base = name.toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 8);
    const suffix = Math.random().toString(36).slice(2, 6).toUpperCase();
    return `${base}_${suffix}`.toUpperCase();
  }

  private mapRow(row: any): PartnerProfile {
    return {
      id: row.id,
      code: row.code,
      name: row.name,
      legalName: row.legalName ?? null,
      type: row.type,
      state: row.state,
      ownerUserId: row.ownerUserId,
      contactEmail: row.contactEmail,
      contactName: row.contactName ?? null,
      website: row.website ?? null,
      countryCode: row.countryCode ?? null,
      taxId: row.taxId ?? null,
      billingEmail: row.billingEmail ?? null,
      currency: row.currency,
      idempotencyKey: row.idempotencyKey,
      createdAt: row.createdAt instanceof Date ? row.createdAt.toISOString() : row.createdAt,
      updatedAt: row.updatedAt instanceof Date ? row.updatedAt.toISOString() : row.updatedAt,
      activatedAt: row.activatedAt ? (row.activatedAt instanceof Date ? row.activatedAt.toISOString() : row.activatedAt) : null,
      suspendedAt: row.suspendedAt ? (row.suspendedAt instanceof Date ? row.suspendedAt.toISOString() : row.suspendedAt) : null,
      terminatedAt: row.terminatedAt ? (row.terminatedAt instanceof Date ? row.terminatedAt.toISOString() : row.terminatedAt) : null,
      metadata: row.metadata ?? null,
      policyVersion: row.policyVersion,
      agreementVersion: row.agreementVersion ?? null,
    };
  }
}

// # Reconciles partner commission accruals against fee ledger and payout records
import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PartnerReconciliationMismatchType } from './partner.types';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

export interface ReconciliationMismatch {
  type: PartnerReconciliationMismatchType;
  partnerId: string;
  tenantId?: string | null;
  entityId: string;
  severity: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
  description: string;
  detectedAt: string;
  correlationId: string;
  sourceReferences?: string[];
}

@Injectable()
export class PartnerReconciliationService {
  private readonly logger = new Logger(PartnerReconciliationService.name);
  private readonly inMemory: Map<string, ReconciliationMismatch> = new Map();

  constructor(private readonly prisma: PrismaService) {}

  async reconcilePartner(partnerId: string, correlationId: string): Promise<ReconciliationMismatch[]> {
    if (!partnerId) throw new BadRequestException('partnerId required');
    const mismatches: ReconciliationMismatch[] = [];
    const now = new Date().toISOString();

    try {
      // PARTNER_WITHOUT_AGREEMENT
      const agreements = await (this.prisma as any).partnerAgreement?.findMany?.({ where: { partnerId } }) ?? [];
      if (agreements.length === 0) {
        mismatches.push({
          type: PartnerReconciliationMismatchType.PARTNER_WITHOUT_AGREEMENT,
          partnerId,
          entityId: partnerId,
          severity: 'HIGH',
          description: `partner ${partnerId} has no agreement`,
          detectedAt: now,
          correlationId,
        });
      }

      // TENANT_WITHOUT_VALID_PARTNER_RELATION
      const relationships = await (this.prisma as any).partnerTenantRelationship?.findMany?.({ where: { partnerId } }) ?? [];
      for (const rel of relationships) {
        if (!rel.tenantId) {
          mismatches.push({
            type: PartnerReconciliationMismatchType.TENANT_WITHOUT_VALID_PARTNER_RELATION,
            partnerId,
            entityId: rel.id,
            severity: 'MEDIUM',
            description: `relationship ${rel.id} missing tenantId`,
            detectedAt: now,
            correlationId,
          });
        }
      }

      // MULTIPLE_PRIMARY_PARTNERS
      const tenantGroups = new Map<string, any[]>();
      for (const rel of relationships.filter((r: any) => r.isPrimary && r.state === 'ACTIVE')) {
        if (!tenantGroups.has(rel.tenantId)) tenantGroups.set(rel.tenantId, []);
        tenantGroups.get(rel.tenantId)!.push(rel);
      }
      for (const [tenantId, rels] of tenantGroups.entries()) {
        if (rels.length > 1) {
          mismatches.push({
            type: PartnerReconciliationMismatchType.MULTIPLE_PRIMARY_PARTNERS,
            partnerId,
            tenantId,
            entityId: tenantId,
            severity: 'CRITICAL',
            description: `tenant ${tenantId} has ${rels.length} primary partners`,
            detectedAt: now,
            correlationId,
            sourceReferences: rels.map((r: any) => r.id),
          });
        }
      }

      // ATTRIBUTION_CONFLICT and ATTRIBUTION_EXPIRED
      const attributions = await (this.prisma as any).partnerAttribution?.findMany?.({ where: { partnerId } }) ?? [];
      const attributionByTenant = new Map<string, any[]>();
      for (const attr of attributions) {
        if (!attributionByTenant.has(attr.tenantId)) attributionByTenant.set(attr.tenantId, []);
        attributionByTenant.get(attr.tenantId)!.push(attr);
        if (attr.expiresAt && new Date(attr.expiresAt) < new Date() && attr.state === 'ACTIVE') {
          mismatches.push({
            type: PartnerReconciliationMismatchType.ATTRIBUTION_EXPIRED,
            partnerId,
            tenantId: attr.tenantId,
            entityId: attr.id,
            severity: 'MEDIUM',
            description: `attribution ${attr.id} expired but still ACTIVE`,
            detectedAt: now,
            correlationId,
          });
        }
      }
      for (const [tenantId, attrs] of attributionByTenant.entries()) {
        const activePrimary = attrs.filter((a: any) => a.isPrimary && a.state === 'ACTIVE');
        if (activePrimary.length > 1) {
          mismatches.push({
            type: PartnerReconciliationMismatchType.ATTRIBUTION_CONFLICT,
            partnerId,
            tenantId,
            entityId: tenantId,
            severity: 'CRITICAL',
            description: `tenant ${tenantId} has ${activePrimary.length} active primary attributions`,
            detectedAt: now,
            correlationId,
            sourceReferences: activePrimary.map((a: any) => a.id),
          });
        }
      }

      // COMMISSION checks
      const commissions = await (this.prisma as any).partnerCommission?.findMany?.({ where: { partnerId }, take: 1000 }) ?? [];
      const sourceEventIds = new Set<string>();
      for (const com of commissions) {
        if (!com.sourceEventId) {
          mismatches.push({
            type: PartnerReconciliationMismatchType.COMMISSION_WITHOUT_SOURCE_PAYMENT,
            partnerId,
            tenantId: com.tenantId,
            entityId: com.id,
            severity: 'HIGH',
            description: `commission ${com.id} missing source event`,
            detectedAt: now,
            correlationId,
          });
        }
        const key = `${com.partnerId}:${com.sourceEventId}`;
        if (sourceEventIds.has(key)) {
          mismatches.push({
            type: PartnerReconciliationMismatchType.COMMISSION_DUPLICATE,
            partnerId,
            tenantId: com.tenantId,
            entityId: com.id,
            severity: 'HIGH',
            description: `duplicate commission for source event ${com.sourceEventId}`,
            detectedAt: now,
            correlationId,
          });
        }
        sourceEventIds.add(key);

        // COMMISSION_AMOUNT_MISMATCH - check if calculation matches expected
        // For now, check if amount is zero when gross is positive
        try {
          const gross = parseFloat(com.grossRevenue);
          const amount = parseFloat(com.commissionAmount);
          if (gross > 0 && amount === 0 && com.state !== 'REVERSED') {
            mismatches.push({
              type: PartnerReconciliationMismatchType.COMMISSION_AMOUNT_MISMATCH,
              partnerId,
              tenantId: com.tenantId,
              entityId: com.id,
              severity: 'MEDIUM',
              description: `commission ${com.id} has zero amount but gross ${com.grossRevenue} positive`,
              detectedAt: now,
              correlationId,
            });
          }
        } catch {}

        // CURRENCY_MISMATCH and MISSING_FX
        if (com.sourceCurrency && com.commissionCurrency && com.sourceCurrency !== com.commissionCurrency) {
          if (com.fxRequired && !com.fxRate) {
            mismatches.push({
              type: PartnerReconciliationMismatchType.MISSING_FX,
              partnerId,
              tenantId: com.tenantId,
              entityId: com.id,
              severity: 'HIGH',
              description: `commission ${com.id} requires FX ${com.sourceCurrency}->${com.commissionCurrency} but rate missing`,
              detectedAt: now,
              correlationId,
            });
          }
          if (com.currency !== com.commissionCurrency && com.currency !== com.sourceCurrency) {
            mismatches.push({
              type: PartnerReconciliationMismatchType.CURRENCY_MISMATCH,
              partnerId,
              tenantId: com.tenantId,
              entityId: com.id,
              severity: 'MEDIUM',
              description: `commission ${com.id} currency ${com.currency} mismatches source ${com.sourceCurrency} and commission ${com.commissionCurrency}`,
              detectedAt: now,
              correlationId,
            });
          }
        }
      }

      // REFUND_WITHOUT_COMMISSION_REVERSAL and CHARGEBACK_WITHOUT_REVERSAL
      // Check refunds/chargebacks without corresponding reversals
      const refunds = commissions.filter((c: any) => c.sourceEventType === 'REFUND' || c.sourceEventType === 'CHARGEBACK');
      for (const refund of refunds) {
        const hasReversal = commissions.some((c: any) => c.reversalOfId && c.sourceEventId.includes(refund.sourceEventId));
        if (!hasReversal) {
          const type = refund.sourceEventType === 'REFUND' ? PartnerReconciliationMismatchType.REFUND_WITHOUT_COMMISSION_REVERSAL : PartnerReconciliationMismatchType.CHARGEBACK_WITHOUT_REVERSAL;
          mismatches.push({
            type,
            partnerId,
            tenantId: refund.tenantId,
            entityId: refund.id,
            severity: 'HIGH',
            description: `${refund.sourceEventType} ${refund.id} without commission reversal`,
            detectedAt: now,
            correlationId,
          });
        }
      }

      // SETTLEMENT_WITHOUT_RECONCILIATION
      const settlements = await (this.prisma as any).partnerSettlement?.findMany?.({ where: { partnerId }, take: 500 }) ?? [];
      for (const set of settlements) {
        if ((set.state === 'LOCKED' || set.state === 'COMPLETED') && !set.reconciledAt) {
          mismatches.push({
            type: PartnerReconciliationMismatchType.SETTLEMENT_WITHOUT_RECONCILIATION,
            partnerId,
            entityId: set.id,
            severity: 'HIGH',
            description: `settlement ${set.id} locked/completed without reconciliation`,
            detectedAt: now,
            correlationId,
          });
        }
      }

      // PAYOUT checks
      const payouts = await (this.prisma as any).partnerPayout?.findMany?.({ where: { partnerId }, take: 500 }) ?? [];
      for (const payout of payouts) {
        const settlementExists = settlements.some((s: any) => s.id === payout.settlementId);
        if (!settlementExists) {
          mismatches.push({
            type: PartnerReconciliationMismatchType.PAYOUT_WITHOUT_SETTLEMENT,
            partnerId,
            entityId: payout.id,
            severity: 'CRITICAL',
            description: `payout ${payout.id} without settlement ${payout.settlementId}`,
            detectedAt: now,
            correlationId,
          });
        }
        if (payout.state === 'COMPLETED' && !payout.providerPayoutId) {
          mismatches.push({
            type: PartnerReconciliationMismatchType.PAYOUT_STATUS_MISMATCH,
            partnerId,
            entityId: payout.id,
            severity: 'HIGH',
            description: `payout ${payout.id} COMPLETED without provider evidence`,
            detectedAt: now,
            correlationId,
          });
        }
      }

    } catch (e) {
      this.logger.debug(`reconciliation fallback partner=${partnerId} err=${(e as Error).message}`);
    }

    for (const m of mismatches) {
      this.inMemory.set(`${m.entityId}_${m.type}`, m);
    }

    this.logger.log(`reconciliation partner=${partnerId} mismatches=${mismatches.length} corr=${correlationId}`);
    return mismatches;
  }

  async listMismatches(partnerId: string, filters?: { type?: PartnerReconciliationMismatchType; severity?: string }): Promise<ReconciliationMismatch[]> {
    let list = [...this.inMemory.values()].filter(m => m.partnerId === partnerId);
    if (filters?.type) list = list.filter(m => m.type === filters.type);
    if (filters?.severity) list = list.filter(m => m.severity === filters.severity);
    return list;
  }

  async resolveMismatch(entityId: string, type: PartnerReconciliationMismatchType, partnerId: string, correlationId: string, resolution: string): Promise<void> {
    const key = `${entityId}_${type}`;
    this.inMemory.delete(key);
    this.logger.log(`mismatch resolved entity=${entityId} type=${type} partner=${partnerId} corr=${correlationId} resolution=${resolution}`);
  }
}

import { Injectable, Logger, BadRequestException, NotFoundException, ConflictException } from '@nestjs/common';
import { PartnerReferral, PartnerReferralState, PartnerAuditAction } from './partner.types';
import { PartnerAuditService } from './partner-audit.service';
import { PartnerProfileService } from './partner-profile.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import * as crypto from 'crypto';

@Injectable()
export class PartnerReferralService {
  private readonly logger = new Logger(PartnerReferralService.name);
  private readonly inMemory: Map<string, PartnerReferral> = new Map();
  private readonly codeIndex: Map<string, string> = new Map(); // code -> id
  private readonly tokenIndex: Map<string, string> = new Map(); // token -> id

  constructor(
    private readonly audit: PartnerAuditService,
    private readonly profileService: PartnerProfileService,
    private readonly prisma: PrismaService,
  ) {}

  async createReferral(params: {
    partnerId: string;
    campaignId?: string;
    code?: string;
    maxUses?: number;
    expiresAt?: string | null;
    createdBy: string;
    correlationId: string;
    idempotencyKey: string;
  }): Promise<PartnerReferral> {
    if (!params.partnerId || !params.idempotencyKey) throw new BadRequestException('partnerId, idempotencyKey required');
    await this.profileService.getProfile(params.partnerId);

    const existingByIdem = [...this.inMemory.values()].find(r => r.idempotencyKey === params.idempotencyKey);
    if (existingByIdem) return existingByIdem;

    const code = params.code ? params.code.toUpperCase() : this.generateCode();
    const token = this.generateToken(params.partnerId, code);

    if (this.codeIndex.has(code)) throw new ConflictException(`referral code ${code} already exists`);
    if (this.tokenIndex.has(token)) throw new ConflictException(`referral token collision`);

    if (params.expiresAt) {
      const exp = new Date(params.expiresAt);
      if (isNaN(exp.getTime()) || exp <= new Date()) throw new BadRequestException('expiresAt must be future');
    }

    const referral: PartnerReferral = {
      id: `pref_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      partnerId: params.partnerId,
      campaignId: params.campaignId ?? null,
      code,
      token,
      state: PartnerReferralState.ACTIVE,
      createdBy: params.createdBy,
      expiresAt: params.expiresAt ? new Date(params.expiresAt).toISOString() : null,
      convertedAt: null,
      convertedTenantId: null,
      maxUses: params.maxUses ?? null,
      currentUses: 0,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      idempotencyKey: params.idempotencyKey,
    };

    this.inMemory.set(referral.id, referral);
    this.codeIndex.set(code, referral.id);
    this.tokenIndex.set(token, referral.id);

    try {
      await (this.prisma as any).partnerReferral?.create?.({
        data: {
          id: referral.id,
          partnerId: referral.partnerId,
          campaignId: referral.campaignId,
          code: referral.code,
          token: referral.token,
          state: referral.state,
          createdBy: referral.createdBy,
          expiresAt: referral.expiresAt ? new Date(referral.expiresAt) : null,
          maxUses: referral.maxUses,
          currentUses: referral.currentUses,
          createdAt: new Date(referral.createdAt),
          updatedAt: new Date(referral.updatedAt),
          idempotencyKey: referral.idempotencyKey,
        },
      });
    } catch {
      this.logger.debug(`referral persist skipped id=${referral.id}`);
    }

    await this.audit.recordEvent({
      partnerId: params.partnerId,
      actorId: params.createdBy,
      action: PartnerAuditAction.REFERRAL_CREATED,
      source: 'PARTNER_REFERRAL_SERVICE',
      correlationId: params.correlationId,
      safeEvidence: { referralId: referral.id, code: referral.code, campaignId: referral.campaignId },
    });

    this.logger.log(`referral created id=${referral.id} partner=${params.partnerId} code=${code} corr=${params.correlationId}`);
    return referral;
  }

  async getByCode(code: string): Promise<PartnerReferral> {
    const upper = code.toUpperCase();
    const id = this.codeIndex.get(upper);
    if (id) {
      const mem = this.inMemory.get(id);
      if (mem) return mem;
    }
    try {
      const row = await (this.prisma as any).partnerReferral?.findFirst?.({ where: { code: upper } });
      if (row) return this.mapRow(row);
    } catch {}
    throw new NotFoundException(`referral code ${code} not found`);
  }

  async getByToken(token: string): Promise<PartnerReferral> {
    const id = this.tokenIndex.get(token);
    if (id) {
      const mem = this.inMemory.get(id);
      if (mem) return mem;
    }
    try {
      const row = await (this.prisma as any).partnerReferral?.findFirst?.({ where: { token } });
      if (row) return this.mapRow(row);
    } catch {}
    throw new NotFoundException(`referral token not found`);
  }

  async getReferral(referralId: string, partnerId: string): Promise<PartnerReferral> {
    const mem = this.inMemory.get(referralId);
    if (mem) {
      if (mem.partnerId !== partnerId) throw new BadRequestException('partner isolation violation');
      return mem;
    }
    try {
      const row = await (this.prisma as any).partnerReferral?.findUnique?.({ where: { id: referralId } });
      if (row) {
        if (row.partnerId !== partnerId) throw new BadRequestException('partner isolation violation');
        return this.mapRow(row);
      }
    } catch {}
    throw new NotFoundException(`referral ${referralId} not found`);
  }

  async listReferrals(partnerId: string): Promise<PartnerReferral[]> {
    let list = [...this.inMemory.values()].filter(r => r.partnerId === partnerId);
    try {
      const rows = await (this.prisma as any).partnerReferral?.findMany?.({ where: { partnerId }, take: 500 });
      if (rows && rows.length > 0) list = rows.map((r: any) => this.mapRow(r));
    } catch {}
    return list;
  }

  async markConverted(params: { referralId: string; partnerId: string; tenantId: string; correlationId: string }): Promise<PartnerReferral> {
    const referral = await this.getReferral(params.referralId, params.partnerId);
    if (referral.state !== PartnerReferralState.ACTIVE) throw new BadRequestException(`cannot convert from state ${referral.state}`);
    if (referral.expiresAt && new Date(referral.expiresAt) < new Date()) throw new BadRequestException('referral expired');
    if (referral.maxUses && referral.currentUses >= referral.maxUses) throw new BadRequestException('referral max uses reached');

    referral.currentUses += 1;
    if (referral.maxUses && referral.currentUses >= referral.maxUses) {
      referral.state = PartnerReferralState.CONVERTED;
    }
    referral.convertedAt = new Date().toISOString();
    referral.convertedTenantId = params.tenantId;
    referral.updatedAt = new Date().toISOString();

    this.inMemory.set(referral.id, referral);
    try {
      await (this.prisma as any).partnerReferral?.update?.({
        where: { id: referral.id },
        data: {
          currentUses: referral.currentUses,
          state: referral.state,
          convertedAt: new Date(referral.convertedAt),
          convertedTenantId: referral.convertedTenantId,
          updatedAt: new Date(referral.updatedAt),
        },
      });
    } catch {}

    return referral;
  }

  async revokeReferral(params: { referralId: string; partnerId: string; revokedBy: string; correlationId: string }): Promise<PartnerReferral> {
    const referral = await this.getReferral(params.referralId, params.partnerId);
    if (referral.state !== PartnerReferralState.ACTIVE) throw new BadRequestException(`cannot revoke from state ${referral.state}`);
    referral.state = PartnerReferralState.REVOKED;
    referral.updatedAt = new Date().toISOString();
    this.inMemory.set(referral.id, referral);
    try {
      await (this.prisma as any).partnerReferral?.update?.({ where: { id: referral.id }, data: { state: referral.state, updatedAt: new Date(referral.updatedAt) } });
    } catch {}
    return referral;
  }

  private generateCode(): string {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let code = '';
    for (let i = 0; i < 8; i++) code += chars[Math.floor(Math.random() * chars.length)];
    return code;
  }

  private generateToken(partnerId: string, code: string): string {
    const raw = `${partnerId}:${code}:${Date.now()}:${Math.random()}`;
    return crypto.createHash('sha256').update(raw).digest('hex').slice(0, 32);
  }

  private mapRow(row: any): PartnerReferral {
    return {
      id: row.id,
      partnerId: row.partnerId,
      campaignId: row.campaignId ?? null,
      code: row.code,
      token: row.token,
      state: row.state,
      createdBy: row.createdBy,
      expiresAt: row.expiresAt ? (row.expiresAt instanceof Date ? row.expiresAt.toISOString() : row.expiresAt) : null,
      convertedAt: row.convertedAt ? (row.convertedAt instanceof Date ? row.convertedAt.toISOString() : row.convertedAt) : null,
      convertedTenantId: row.convertedTenantId ?? null,
      maxUses: row.maxUses ?? null,
      currentUses: row.currentUses ?? 0,
      createdAt: row.createdAt instanceof Date ? row.createdAt.toISOString() : row.createdAt,
      updatedAt: row.updatedAt instanceof Date ? row.updatedAt.toISOString() : row.updatedAt,
      idempotencyKey: row.idempotencyKey,
    };
  }
}

/**
 * Partner Settlement Contract Spec - deterministic settlement-focused tests
 */



function toMinorUnits(amount: string, minorUnit: number): bigint {
  const parts = amount.split('.');
  const intPart = BigInt(parts[0] || '0');
  let frac = parts[1] || '';
  if (frac.length > minorUnit) frac = frac.slice(0, minorUnit);
  while (frac.length < minorUnit) frac += '0';
  const fracPart = BigInt(frac || '0');
  return intPart * BigInt(Math.pow(10, minorUnit)) + fracPart;
}

function fromMinorUnits(minor: bigint, minorUnit: number): string {
  const factor = BigInt(Math.pow(10, minorUnit));
  const intPart = minor / factor;
  const fracPart = minor % factor;
  let fracStr = fracPart.toString().padStart(minorUnit, '0').replace(/0+$/, '');
  if (fracStr === '') fracStr = '00';
  return `${intPart.toString()}.${fracStr}`;
}

function addDecimal(a: string, b: string, minorUnit: number): string {
  return fromMinorUnits(toMinorUnits(a, minorUnit) + toMinorUnits(b, minorUnit), minorUnit);
}

describe('Settlement Period Isolation Contract', () => {
  it('settlement period isolation - different periods different fingerprints', () => {
    const fp1 = `partner_a:2026-01-01:2026-01-31:USD:hash1`;
    const fp2 = `partner_a:2026-02-01:2026-02-28:USD:hash1`;
    expect(fp1).not.toBe(fp2);
  });

  it('settlement excludes reversed commission from payable', () => {
    const accrued = '100.00';
    const reversed = '-20.00';
    const payable = addDecimal(accrued, reversed, 2);
    expect(payable).toBe('80.00');
  });

  it('settlement duplicate prevented via fingerprint', () => {
    const fingerprint = 'abc123';
    const seen = new Set([fingerprint]);
    expect(seen.has(fingerprint)).toBe(true);
  });

  it('settlement reconciliation required - critical mismatch blocks', () => {
    const mismatches = [{ severity: 'CRITICAL', type: 'MULTIPLE_PRIMARY_PARTNERS' }];
    const critical = mismatches.filter(m => m.severity === 'CRITICAL' || m.severity === 'HIGH');
    expect(critical.length).toBe(1);
  });

  it('settlement excludes commissions outside period', () => {
    const periodStart = new Date('2026-01-01');
    const periodEnd = new Date('2026-01-31');
    const commissions = [
      { accruedAt: '2026-01-15T00:00:00Z', amount: '20.00' },
      { accruedAt: '2026-02-15T00:00:00Z', amount: '30.00' },
    ];
    const inPeriod = commissions.filter(c => {
      const d = new Date(c.accruedAt);
      return d >= periodStart && d <= periodEnd;
    });
    expect(inPeriod.length).toBe(1);
  });

  it('settlement currency validation - mismatch rejected', () => {
    const settlementCurrency = 'USD';
    const commissionCurrency = 'EUR';
    expect(settlementCurrency).not.toBe(commissionCurrency);
  });

  it('FX missing blocks settlement', () => {
    const commission = { fxRequired: true, fxRate: null };
    const blocked = commission.fxRequired && !commission.fxRate;
    expect(blocked).toBe(true);
  });

  it('refund adjustment reduces payable', () => {
    const payableBefore = '100.00';
    const refundReversal = '-10.00';
    const after = addDecimal(payableBefore, refundReversal, 2);
    expect(after).toBe('90.00');
  });

  it('chargeback adjustment reduces payable and creates outstanding if needed', () => {
    const payableBefore = '100.00';
    const chargebackReversal = '-100.00';
    const after = addDecimal(payableBefore, chargebackReversal, 2);
    expect(after).toBe('0.00');
  });

  it('settlement idempotency - same idempotencyKey same settlement', () => {
    const idemKey = 'idem_settle_123';
    const s1 = { id: 'set_1', idempotencyKey: idemKey };
    const s2 = { id: 'set_1', idempotencyKey: idemKey };
    expect(s1.id).toBe(s2.id);
  });

  it('settlement fingerprint deterministic', () => {
    const input = { partnerId: 'p1', periodStart: '2026-01-01', periodEnd: '2026-01-31', currency: 'USD', commissionIds: ['c1', 'c2'].sort() };
    const fp1 = JSON.stringify(input);
    const fp2 = JSON.stringify(input);
    expect(fp1).toBe(fp2);
  });

  it('settlement total payable calculation', () => {
    const accrued = '200.00';
    const reversed = '-30.00';
    const payable = addDecimal(accrued, reversed, 2);
    expect(payable).toBe('170.00');
  });
});

describe('Payout Contract', () => {
  it('payout requires authorized settlement - settlement must be LOCKED', () => {
    const settlementState = 'LOCKED';
    const allowed = ['LOCKED', 'PAYOUT_REQUESTED', 'COMPLETED'];
    expect(allowed.includes(settlementState)).toBe(true);
  });

  it('payout submission does not mean completion', () => {
    const state = 'SUBMITTED';
    expect(state).not.toBe('COMPLETED');
  });

  it('payout provider evidence required for COMPLETED', () => {
    const payout = { state: 'COMPLETED', providerPayoutId: null };
    const valid = payout.state === 'COMPLETED' ? !!payout.providerPayoutId : true;
    expect(valid).toBe(false);
  });

  it('payout duplicate prevented via idempotencyKey', () => {
    const idemKey = 'idem_payout_123';
    const seen = new Set([idemKey]);
    expect(seen.has(idemKey)).toBe(true);
  });

  it('payout completion evidence - providerPayoutId and reference required', () => {
    const payout = { providerPayoutId: 'prov_123', providerReference: 'ref_123' };
    expect(payout.providerPayoutId).toBeTruthy();
    expect(payout.providerReference).toBeTruthy();
  });

  it('failed payout preserved', () => {
    const payout = { state: 'FAILED', failureReason: 'Insufficient funds' };
    expect(payout.state).toBe('FAILED');
    expect(payout.failureReason).toBeTruthy();
  });

  it('reversed payout preserved', () => {
    const payout = { state: 'REVERSED', reversedAt: new Date().toISOString() };
    expect(payout.state).toBe('REVERSED');
  });

  it('payout amount matches settlement payable', () => {
    const settlementPayable = '150.00';
    const payoutAmount = '150.00';
    expect(settlementPayable).toBe(payoutAmount);
  });

  it('payout idempotency - same key same payout', () => {
    const key = 'idem_payout_456';
    const p1 = { id: 'pay_1', idempotencyKey: key };
    const p2 = { id: 'pay_1', idempotencyKey: key };
    expect(p1.id).toBe(p2.id);
  });

  it('payout authorization - requires approval if policy says', () => {
    const policy = { requiresApproval: true };
    const state = 'REQUESTED';
    const needsApproval = policy.requiresApproval && state === 'REQUESTED';
    expect(needsApproval).toBe(true);
  });
});

describe('Settlement Audit & Isolation Contract', () => {
  it('settlement audit - every settlement creation audited', () => {
    const auditEvents = [{ action: 'SETTLEMENT_CREATED', settlementId: 'set_1' }];
    expect(auditEvents.length).toBe(1);
  });

  it('tenant isolation - settlement only includes partner tenants', () => {
    const partnerId = 'partner_a';
    const commissions = [
      { partnerId: 'partner_a', tenantId: 'tenant_1' },
      { partnerId: 'partner_b', tenantId: 'tenant_2' },
    ];
    const filtered = commissions.filter(c => c.partnerId === partnerId);
    expect(filtered.length).toBe(1);
  });

  it('partner isolation - partner cannot see another partner settlement', () => {
    const partnerA = 'partner_a';
    const partnerB = 'partner_b';
    const settlements = [{ partnerId: 'partner_a', id: 'set_1' }];
    const bSettlements = settlements.filter(s => s.partnerId === partnerB);
    expect(bSettlements.length).toBe(0);
  });

  it('Decimal precision exact in settlement', () => {
    const a = '100.00';
