import { Injectable, Logger, BadRequestException, NotFoundException } from '@nestjs/common';
import { PartnerSettlement, PartnerSettlementState, PARTNER_SETTLEMENT_TRANSITIONS, PartnerAuditAction, PartnerCommissionState } from './partner.types';
import { PartnerAuditService } from './partner-audit.service';
import { PartnerProfileService } from './partner-profile.service';
import { PartnerAgreementService } from './partner-agreement.service';
import { PartnerCommissionLedgerService } from './partner-commission-ledger.service';
import { PartnerReconciliationService } from './partner-reconciliation.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import * as crypto from 'crypto';

@Injectable()
export class PartnerSettlementService {
  private readonly logger = new Logger(PartnerSettlementService.name);
  private readonly inMemory: Map<string, PartnerSettlement> = new Map();
  private readonly idemIndex: Map<string, string> = new Map();
  private readonly fingerprintIndex: Map<string, string> = new Map(); // partnerId:periodStart:periodEnd:currency:fingerprint -> id

  constructor(
    private readonly audit: PartnerAuditService,
    private readonly profileService: PartnerProfileService,
    private readonly agreementService: PartnerAgreementService,
    private readonly commissionLedger: PartnerCommissionLedgerService,
    private readonly reconciliation: PartnerReconciliationService,
    private readonly prisma: PrismaService,
  ) {}

  async createSettlement(params: {
    partnerId: string;
    periodStart: string;
    periodEnd: string;
    currency: string;
    createdBy: string;
    correlationId: string;
    idempotencyKey: string;
  }): Promise<PartnerSettlement> {
    if (!params.partnerId || !params.periodStart || !params.periodEnd || !params.currency || !params.idempotencyKey) {
      throw new BadRequestException('partnerId, periodStart, periodEnd, currency, idempotencyKey required');
    }

    await this.profileService.getProfile(params.partnerId);
    const agreement = await this.agreementService.getActiveAgreement(params.partnerId);
    if (!agreement) throw new BadRequestException(`no active agreement for partner ${params.partnerId}`);

    const periodStart = new Date(params.periodStart);
    const periodEnd = new Date(params.periodEnd);
    if (isNaN(periodStart.getTime()) || isNaN(periodEnd.getTime()) || periodStart >= periodEnd) {
      throw new BadRequestException('invalid period');
    }

    // Idempotency
    if (this.idemIndex.has(params.idempotencyKey)) {
      const existingId = this.idemIndex.get(params.idempotencyKey)!;
      const existing = this.inMemory.get(existingId);
      if (existing) return existing;
    }

    // Collect eligible commissions
    const allCommissions = await this.commissionLedger.listCommissions(params.partnerId, { currency: params.currency });
    const eligible = allCommissions.filter(c => {
      const accruedAt = new Date(c.accruedAt);
      return accruedAt >= periodStart && accruedAt <= periodEnd && c.state === PartnerCommissionState.ACCRUED && c.currency.toUpperCase() === params.currency.toUpperCase();
    });

    // Check FX missing - if any commission has fxRequired true without fxRate, settlement blocked
    const missingFx = eligible.filter(c => c.fxRequired && !c.fxRate);
    if (missingFx.length > 0) {
      throw new BadRequestException(`settlement blocked - missing FX for ${missingFx.length} commissions: ${missingFx.map(c => c.id).join(',')}`);
    }

    // Calculate totals Decimal-safe
    let totalGross = '0';
    let totalDiscount = '0';
    let totalNetEligible = '0';
    let totalAccrued = '0';
    let totalReversed = '0';

    // Need to also include reversals in period
    const reversals = allCommissions.filter(c => {
      const accruedAt = new Date(c.accruedAt);
      return accruedAt >= periodStart && accruedAt <= periodEnd && c.state === PartnerCommissionState.REVERSED;
    });

    for (const com of eligible) {
      totalGross = this.addDecimal(totalGross, com.grossRevenue, params.currency);
      totalDiscount = this.addDecimal(totalDiscount, com.discountAmount, params.currency);
      totalNetEligible = this.addDecimal(totalNetEligible, com.netEligibleRevenue, params.currency);
      totalAccrued = this.addDecimal(totalAccrued, com.commissionAmount, params.currency);
    }

    for (const rev of reversals) {
      totalReversed = this.addDecimal(totalReversed, rev.commissionAmount, params.currency); // reversal amounts are negative
    }

    const totalPayable = this.addDecimal(totalAccrued, totalReversed, params.currency);

    // Reconciliation required
    const mismatches = await this.reconciliation.reconcilePartner(params.partnerId, params.correlationId);
    const criticalMismatches = mismatches.filter(m => m.severity === 'CRITICAL' || m.severity === 'HIGH');
    if (criticalMismatches.length > 0) {
      throw new BadRequestException(`settlement blocked - reconciliation has ${criticalMismatches.length} critical/high mismatches`);
    }

    // Fingerprint for duplicate prevention
    const fingerprintInput = {
      partnerId: params.partnerId,
      periodStart: periodStart.toISOString(),
      periodEnd: periodEnd.toISOString(),
      currency: params.currency.toUpperCase(),
      commissionIds: eligible.map(c => c.id).sort(),
      reversalIds: reversals.map(c => c.id).sort(),
      totalPayable,
      policyVersion: agreement.commissionPolicy.policyVersion,
      agreementVersion: `v${agreement.version}`,
    };
    const fingerprint = crypto.createHash('sha256').update(JSON.stringify(fingerprintInput)).digest('hex');
    const fingerprintKey = `${params.partnerId}:${periodStart.toISOString()}:${periodEnd.toISOString()}:${params.currency.toUpperCase()}:${fingerprint}`;
    if (this.fingerprintIndex.has(fingerprintKey)) {
      const existingId = this.fingerprintIndex.get(fingerprintKey)!;
      const existing = this.inMemory.get(existingId);
      if (existing) {
        this.logger.log(`settlement duplicate prevented fingerprint=${fingerprint} corr=${params.correlationId}`);
        return existing;
      }
    }

    try {
      const existingByFingerprint = await (this.prisma as any).partnerSettlement?.findFirst?.({ where: { fingerprint } });
      if (existingByFingerprint) {
        this.logger.log(`settlement duplicate DB prevented fingerprint=${fingerprint}`);
        return this.mapRow(existingByFingerprint);
      }
    } catch {}

    const settlement: PartnerSettlement = {
      id: `pset_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      partnerId: params.partnerId,
      periodStart: periodStart.toISOString(),
      periodEnd: periodEnd.toISOString(),
      currency: params.currency.toUpperCase(),
      state: PartnerSettlementState.OPEN,
      totalGrossRevenue: totalGross,
      totalDiscount,
      totalNetEligibleRevenue: totalNetEligible,
      totalCommissionAccrued: totalAccrued,
      totalCommissionReversed: totalReversed,
      totalCommissionPayable: totalPayable,
      commissionCount: eligible.length,
      reversalCount: reversals.length,
      refundCount: reversals.filter(r => r.sourceEventType === 'REFUND').length,
      chargebackCount: reversals.filter(r => r.sourceEventType === 'CHARGEBACK').length,
      fingerprint,
      calculationVersion: '2026-01',
      policyVersion: agreement.commissionPolicy.policyVersion,
      agreementVersion: `v${agreement.version}`,
      reconciledAt: null,
      lockedAt: null,
      completedAt: null,
      payoutId: null,
      createdBy: params.createdBy,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      idempotencyKey: params.idempotencyKey,
      correlationId: params.correlationId,
    };

    this.inMemory.set(settlement.id, settlement);
    this.idemIndex.set(params.idempotencyKey, settlement.id);
    this.fingerprintIndex.set(fingerprintKey, settlement.id);

    try {
      await (this.prisma as any).partnerSettlement?.create?.({
        data: {
          id: settlement.id,
          partnerId: settlement.partnerId,
          periodStart: new Date(settlement.periodStart),
          periodEnd: new Date(settlement.periodEnd),
          currency: settlement.currency,
          state: settlement.state,
          totalGrossRevenue: settlement.totalGrossRevenue,
          totalDiscount: settlement.totalDiscount,
          totalNetEligibleRevenue: settlement.totalNetEligibleRevenue,
          totalCommissionAccrued: settlement.totalCommissionAccrued,
          totalCommissionReversed: settlement.totalCommissionReversed,
          totalCommissionPayable: settlement.totalCommissionPayable,
          commissionCount: settlement.commissionCount,
          reversalCount: settlement.reversalCount,
          refundCount: settlement.refundCount,
          chargebackCount: settlement.chargebackCount,
          fingerprint: settlement.fingerprint,
          calculationVersion: settlement.calculationVersion,
          policyVersion: settlement.policyVersion,
          agreementVersion: settlement.agreementVersion,
          createdBy: settlement.createdBy,
          createdAt: new Date(settlement.createdAt),
          updatedAt: new Date(settlement.updatedAt),
          idempotencyKey: settlement.idempotencyKey,
          correlationId: settlement.correlationId,
        },
      });
    } catch {
      this.logger.debug(`settlement persist skipped id=${settlement.id}`);
    }

    // Atomically link commissions to settlement
    try {
      await (this.prisma as any).$transaction?.(async (tx: any) => {
        for (const com of [...eligible, ...reversals]) {
          await tx.partnerCommission?.update?.({ where: { id: com.id }, data: { settlementId: settlement.id, state: 'SETTLED' } });
        }
      });
    } catch {
      // Fallback
      for (const com of [...eligible, ...reversals]) {
        const memCom = this.inMemory.get(com.id) ?? (await this.commissionLedger.getCommission(com.id, params.partnerId).catch(() => null));
        if (memCom) {
          // Update in ledger in-memory via direct map access not possible, but we track via commissionLedger
          // We'll update via ledger's internal map if accessible, else via prisma
          try {
            await (this.prisma as any).partnerCommission?.update?.({ where: { id: com.id }, data: { settlementId: settlement.id } });
          } catch {}
        }
      }
    }

    await this.audit.recordEvent({
      partnerId: params.partnerId,
      actorId: params.createdBy,
      action: PartnerAuditAction.SETTLEMENT_CREATED,
      source: 'PARTNER_SETTLEMENT_SERVICE',
      correlationId: params.correlationId,
      agreementVersion: settlement.agreementVersion,
      policyVersion: settlement.policyVersion,
      safeEvidence: { settlementId: settlement.id, periodStart: settlement.periodStart, periodEnd: settlement.periodEnd, totalPayable, commissionCount: settlement.commissionCount, fingerprint },
    });

    this.logger.log(`settlement created id=${settlement.id} partner=${params.partnerId} payable=${totalPayable} ${params.currency} corr=${params.correlationId}`);
    return settlement;
  }

  async transitionState(params: { settlementId: string; partnerId: string; targetState: PartnerSettlementState; correlationId: string; actorId: string }): Promise<PartnerSettlement> {
    const settlement = await this.getSettlement(params.settlementId, params.partnerId);
    const allowed = PARTNER_SETTLEMENT_TRANSITIONS[settlement.state];
    if (!allowed.includes(params.targetState)) throw new BadRequestException(`invalid transition ${settlement.state} -> ${params.targetState}`);

    const prev = settlement.state;
    settlement.state = params.targetState;
    settlement.updatedAt = new Date().toISOString();
    if (params.targetState === PartnerSettlementState.RECONCILED) settlement.reconciledAt = new Date().toISOString();
    if (params.targetState === PartnerSettlementState.LOCKED) settlement.lockedAt = new Date().toISOString();
    if (params.targetState === PartnerSettlementState.COMPLETED) settlement.completedAt = new Date().toISOString();

    this.inMemory.set(settlement.id, settlement);
    try {
      await (this.prisma as any).partnerSettlement?.update?.({
        where: { id: settlement.id },
        data: {
          state: settlement.state,
          reconciledAt: settlement.reconciledAt ? new Date(settlement.reconciledAt) : null,
          lockedAt: settlement.lockedAt ? new Date(settlement.lockedAt) : null,
          completedAt: settlement.completedAt ? new Date(settlement.completedAt) : null,
          updatedAt: new Date(settlement.updatedAt),
        },
      });
    } catch {}

    const auditAction = params.targetState === PartnerSettlementState.LOCKED ? PartnerAuditAction.SETTLEMENT_LOCKED : PartnerAuditAction.SETTLEMENT_CREATED;
    await this.audit.recordEvent({
      partnerId: params.partnerId,
      actorId: params.actorId,
      action: auditAction,
      source: 'PARTNER_SETTLEMENT_SERVICE',
      correlationId: params.correlationId,
      agreementVersion: settlement.agreementVersion,
      policyVersion: settlement.policyVersion,
      safeEvidence: { settlementId: settlement.id, from: prev, to: params.targetState },
    });

    this.logger.log(`settlement transition id=${settlement.id} ${prev} -> ${params.targetState} corr=${params.correlationId}`);
    return settlement;
  }

  async getSettlement(settlementId: string, partnerId: string): Promise<PartnerSettlement> {
    const mem = this.inMemory.get(settlementId);
    if (mem) {
      if (mem.partnerId !== partnerId) throw new BadRequestException('partner isolation violation');
      return mem;
    }
    try {
      const row = await (this.prisma as any).partnerSettlement?.findUnique?.({ where: { id: settlementId } });
      if (row) {
        if (row.partnerId !== partnerId) throw new BadRequestException('partner isolation violation');
        const mapped = this.mapRow(row);
        this.inMemory.set(mapped.id, mapped);
        return mapped;
      }
    } catch {}
    throw new NotFoundException(`settlement ${settlementId} not found`);
  }

  async listSettlements(partnerId: string, filters?: { state?: PartnerSettlementState; currency?: string }): Promise<PartnerSettlement[]> {
    let list = [...this.inMemory.values()].filter(s => s.partnerId === partnerId);
    if (filters?.state) list = list.filter(s => s.state === filters.state);
    if (filters?.currency) {
      const curUpper = filters.currency.toUpperCase();
      list = list.filter(s => s.currency === curUpper);
    }
    try {
      const where: any = { partnerId };
      if (filters?.state) where.state = filters.state;
      if (filters?.currency) where.currency = filters.currency.toUpperCase();
      const rows = await (this.prisma as any).partnerSettlement?.findMany?.({ where, take: 500, orderBy: { createdAt: 'desc' } });
      if (rows && rows.length > 0) list = rows.map((r: any) => this.mapRow(r));
    } catch {}
    return list;
  }

  private getMinorUnit(currency: string): number {
    const map: Record<string, number> = { USD: 2, EUR: 2, GBP: 2, JPY: 0, USDT: 6, USDC: 6 };
    return map[currency.toUpperCase()] ?? 2;
  }

  private toMinorUnits(amount: string, currency: string): bigint {
    const minor = this.getMinorUnit(currency);
    const factor = Math.pow(10, minor);
    const parts = amount.toString().split('.');
    const intPart = BigInt(parts[0] || '0');
    let frac = parts[1] || '';
    if (frac.length > minor) frac = frac.slice(0, minor);
    while (frac.length < minor) frac += '0';
    const fracPart = BigInt(frac || '0');
    if (intPart < BigInt(0)) return intPart * BigInt(factor) - fracPart;
    return intPart * BigInt(factor) + fracPart;
  }

  private fromMinorUnits(minor: bigint, currency: string): string {
    const minorUnit = this.getMinorUnit(currency);
    const factor = BigInt(Math.pow(10, minorUnit));
    const isNegative = minor < BigInt(0);
    const abs = isNegative ? -minor : minor;
    const intPart = abs / factor;
    const fracPart = abs % factor;
    let fracStr = fracPart.toString().padStart(minorUnit, '0');
    if (minorUnit > 0) {
      fracStr = fracStr.replace(/0+$/, '');
      if (fracStr === '') fracStr = '0'.repeat(Math.min(2, minorUnit));
    }
    const result = minorUnit === 0 ? intPart.toString() : `${intPart.toString()}.${fracStr}`;
    return isNegative ? `-${result}` : result;
  }

  private addDecimal(a: string, b: string, currency: string): string {
    return this.fromMinorUnits(this.toMinorUnits(a, currency) + this.toMinorUnits(b, currency), currency);
  }

  private mapRow(row: any): PartnerSettlement {
    return {
      id: row.id,
      partnerId: row.partnerId,
      periodStart: row.periodStart instanceof Date ? row.periodStart.toISOString() : row.periodStart,
      periodEnd: row.periodEnd instanceof Date ? row.periodEnd.toISOString() : row.periodEnd,
      currency: row.currency,
      state: row.state,
      totalGrossRevenue: row.totalGrossRevenue,
      totalDiscount: row.totalDiscount,
      totalNetEligibleRevenue: row.totalNetEligibleRevenue,
      totalCommissionAccrued: row.totalCommissionAccrued,
      totalCommissionReversed: row.totalCommissionReversed,
      totalCommissionPayable: row.totalCommissionPayable,
      commissionCount: row.commissionCount,
      reversalCount: row.reversalCount,
      refundCount: row.refundCount,
      chargebackCount: row.chargebackCount,
      fingerprint: row.fingerprint,
      calculationVersion: row.calculationVersion,
      policyVersion: row.policyVersion,
      agreementVersion: row.agreementVersion,
      reconciledAt: row.reconciledAt ? (row.reconciledAt instanceof Date ? row.reconciledAt.toISOString() : row.reconciledAt) : null,
      lockedAt: row.lockedAt ? (row.lockedAt instanceof Date ? row.lockedAt.toISOString() : row.lockedAt) : null,
      completedAt: row.completedAt ? (row.completedAt instanceof Date ? row.completedAt.toISOString() : row.completedAt) : null,
      payoutId: row.payoutId ?? null,
      createdBy: row.createdBy,
      createdAt: row.createdAt instanceof Date ? row.createdAt.toISOString() : row.createdAt,
      updatedAt: row.updatedAt instanceof Date ? row.updatedAt.toISOString() : row.updatedAt,
      idempotencyKey: row.idempotencyKey,
      correlationId: row.correlationId,
    };
  }
}

import { Injectable, Logger, BadRequestException, NotFoundException, ConflictException } from '@nestjs/common';
import { PartnerTenantRelationship, PartnerTenantRelationshipType, PartnerTenantRelationshipState, PartnerAuditAction } from './partner.types';
import { PartnerAuditService } from './partner-audit.service';
import { PartnerProfileService } from './partner-profile.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

@Injectable()
export class PartnerTenantService {
  private readonly logger = new Logger(PartnerTenantService.name);
  private readonly inMemory: Map<string, PartnerTenantRelationship> = new Map();
  private readonly tenantPrimaryIndex: Map<string, string> = new Map(); // tenantId -> relationshipId (primary)

  constructor(
    private readonly audit: PartnerAuditService,
    private readonly profileService: PartnerProfileService,
    private readonly prisma: PrismaService,
  ) {}

  async assignTenant(params: {
    partnerId: string;
    tenantId: string;
    relationshipType: PartnerTenantRelationshipType;
    assignedBy: string;
    correlationId: string;
    idempotencyKey: string;
    isPrimary?: boolean;
    campaignId?: string;
    referralCode?: string;
    attributionId?: string;
    metadata?: Record<string, unknown>;
  }): Promise<PartnerTenantRelationship> {
    if (!params.partnerId || !params.tenantId || !params.relationshipType || !params.idempotencyKey) {
      throw new BadRequestException('partnerId, tenantId, relationshipType, idempotencyKey required');
    }

    await this.profileService.getProfile(params.partnerId);

    // Idempotency
    const existingByIdem = [...this.inMemory.values()].find(r => r.idempotencyKey === params.idempotencyKey);
    if (existingByIdem) {
      this.logger.log(`tenant assign idempotent hit key=${params.idempotencyKey}`);
      return existingByIdem;
    }
    try {
      const row = await (this.prisma as any).partnerTenantRelationship?.findFirst?.({ where: { idempotencyKey: params.idempotencyKey } });
      if (row) return this.mapRow(row);
    } catch {}

    // Prevent duplicate primary ownership
    const isPrimary = params.isPrimary ?? true;
    if (isPrimary) {
      const existingPrimary = this.tenantPrimaryIndex.get(params.tenantId);
      if (existingPrimary) {
        const existingRel = this.inMemory.get(existingPrimary);
        if (existingRel && existingRel.partnerId !== params.partnerId && existingRel.state === PartnerTenantRelationshipState.ACTIVE) {
          throw new ConflictException(`tenant ${params.tenantId} already has primary partner ${existingRel.partnerId}, transfer required`);
        }
      }
      try {
        const primaryRows = await (this.prisma as any).partnerTenantRelationship?.findMany?.({ where: { tenantId: params.tenantId, isPrimary: true, state: 'ACTIVE' } });
        if (primaryRows && primaryRows.length > 0) {
          const other = primaryRows.find((r: any) => r.partnerId !== params.partnerId);
          if (other) throw new ConflictException(`tenant ${params.tenantId} already has primary partner ${other.partnerId}`);
        }
      } catch (e) {
        if (e instanceof ConflictException) throw e;
      }
    }

    const relationship: PartnerTenantRelationship = {
      id: `ptrel_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      partnerId: params.partnerId,
      tenantId: params.tenantId,
      relationshipType: params.relationshipType,
      state: PartnerTenantRelationshipState.ACTIVE,
      attributionId: params.attributionId ?? null,
      campaignId: params.campaignId ?? null,
      referralCode: params.referralCode ?? null,
      assignedAt: new Date().toISOString(),
      assignedBy: params.assignedBy,
      activatedAt: new Date().toISOString(),
      terminatedAt: null,
      isPrimary,
      metadata: params.metadata ?? null,
      idempotencyKey: params.idempotencyKey,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };

    this.inMemory.set(relationship.id, relationship);
    if (isPrimary) this.tenantPrimaryIndex.set(params.tenantId, relationship.id);

    try {
      await (this.prisma as any).partnerTenantRelationship?.create?.({
        data: {
          id: relationship.id,
          partnerId: relationship.partnerId,
          tenantId: relationship.tenantId,
          relationshipType: relationship.relationshipType,
          state: relationship.state,
          attributionId: relationship.attributionId,
          campaignId: relationship.campaignId,
          referralCode: relationship.referralCode,
          assignedAt: new Date(relationship.assignedAt),
          assignedBy: relationship.assignedBy,
          activatedAt: relationship.activatedAt ? new Date(relationship.activatedAt) : null,
          isPrimary: relationship.isPrimary,
          metadata: relationship.metadata as any,
          idempotencyKey: relationship.idempotencyKey,
          createdAt: new Date(relationship.createdAt),
          updatedAt: new Date(relationship.updatedAt),
        },
      });
    } catch {
      this.logger.debug(`tenant relationship persist skipped id=${relationship.id}`);
    }

    // Delegate actual tenant creation to existing SaaS tenant provisioning service - we only record relationship
    // No fake tenant creation - relationship is derivative

    await this.audit.recordEvent({
      partnerId: params.partnerId,
      tenantId: params.tenantId,
      actorId: params.assignedBy,
      action: PartnerAuditAction.TENANT_ASSIGNED,
      source: 'PARTNER_TENANT_SERVICE',
      correlationId: params.correlationId,
      safeEvidence: { relationshipType: params.relationshipType, isPrimary, tenantId: params.tenantId },
    });

    this.logger.log(`tenant assigned partner=${params.partnerId} tenant=${params.tenantId} corr=${params.correlationId}`);
    return relationship;
  }

  async transferTenant(params: {
    tenantId: string;
    fromPartnerId: string;
    toPartnerId: string;
    transferredBy: string;
    correlationId: string;
    reason: string;
    idempotencyKey: string;
  }): Promise<PartnerTenantRelationship> {
    if (!params.tenantId || !params.fromPartnerId || !params.toPartnerId) throw new BadRequestException('tenantId, fromPartnerId, toPartnerId required');
    if (params.fromPartnerId === params.toPartnerId) throw new BadRequestException('cannot transfer to same partner');

    const fromRel = [...this.inMemory.values()].find(r => r.tenantId === params.tenantId && r.partnerId === params.fromPartnerId && r.isPrimary && r.state === PartnerTenantRelationshipState.ACTIVE);
    if (!fromRel) throw new NotFoundException(`primary relationship for tenant ${params.tenantId} with partner ${params.fromPartnerId} not found`);

    // Terminate old
    fromRel.state = PartnerTenantRelationshipState.TERMINATED;
    fromRel.terminatedAt = new Date().toISOString();
    fromRel.updatedAt = new Date().toISOString();
    this.inMemory.set(fromRel.id, fromRel);
    this.tenantPrimaryIndex.delete(params.tenantId);

    try {
      await (this.prisma as any).partnerTenantRelationship?.update?.({ where: { id: fromRel.id }, data: { state: fromRel.state, terminatedAt: new Date(fromRel.terminatedAt), updatedAt: new Date(fromRel.updatedAt) } });
    } catch {}

    // Create new primary
    const newRel = await this.assignTenant({
      partnerId: params.toPartnerId,
      tenantId: params.tenantId,
      relationshipType: fromRel.relationshipType,
      assignedBy: params.transferredBy,
      correlationId: params.correlationId,
      idempotencyKey: params.idempotencyKey,
      isPrimary: true,
      metadata: { transferredFrom: params.fromPartnerId, reason: params.reason },
    });

    await this.audit.recordEvent({
      partnerId: params.toPartnerId,
      tenantId: params.tenantId,
      actorId: params.transferredBy,
      action: PartnerAuditAction.TENANT_TRANSFERRED,
      source: 'PARTNER_TENANT_SERVICE',
      correlationId: params.correlationId,
      safeEvidence: { fromPartnerId: params.fromPartnerId, toPartnerId: params.toPartnerId, tenantId: params.tenantId, reason: params.reason },
    });

    return newRel;
  }

  async unassignTenant(params: { relationshipId: string; partnerId: string; unassignedBy: string; correlationId: string; reason: string }): Promise<PartnerTenantRelationship> {
    const rel = await this.getRelationship(params.relationshipId, params.partnerId);
    if (rel.state === PartnerTenantRelationshipState.TERMINATED) throw new BadRequestException('already terminated');
    rel.state = PartnerTenantRelationshipState.TERMINATED;
    rel.terminatedAt = new Date().toISOString();
    rel.updatedAt = new Date().toISOString();
    this.inMemory.set(rel.id, rel);
    if (rel.isPrimary) this.tenantPrimaryIndex.delete(rel.tenantId);
    try {
      await (this.prisma as any).partnerTenantRelationship?.update?.({ where: { id: rel.id }, data: { state: rel.state, terminatedAt: new Date(rel.terminatedAt), updatedAt: new Date(rel.updatedAt) } });
    } catch {}
    await this.audit.recordEvent({
      partnerId: params.partnerId,
      tenantId: rel.tenantId,
      actorId: params.unassignedBy,
      action: PartnerAuditAction.TENANT_UNASSIGNED,
      source: 'PARTNER_TENANT_SERVICE',
      correlationId: params.correlationId,
      safeEvidence: { relationshipId: rel.id, tenantId: rel.tenantId, reason: params.reason },
    });
    return rel;
  }

  async getRelationship(relationshipId: string, partnerId: string): Promise<PartnerTenantRelationship> {
    const mem = this.inMemory.get(relationshipId);
    if (mem) {
      if (mem.partnerId !== partnerId) throw new BadRequestException('partner isolation violation');
      return mem;
    }
    try {
      const row = await (this.prisma as any).partnerTenantRelationship?.findUnique?.({ where: { id: relationshipId } });
      if (row) {
        if (row.partnerId !== partnerId) throw new BadRequestException('partner isolation violation');
        return this.mapRow(row);
      }
    } catch {}
    throw new NotFoundException(`relationship ${relationshipId} not found`);
  }

  async listTenantsForPartner(partnerId: string, filters?: { state?: PartnerTenantRelationshipState; relationshipType?: PartnerTenantRelationshipType }): Promise<PartnerTenantRelationship[]> {
    let list = [...this.inMemory.values()].filter(r => r.partnerId === partnerId);
    if (filters?.state) list = list.filter(r => r.state === filters.state);
    if (filters?.relationshipType) list = list.filter(r => r.relationshipType === filters.relationshipType);
    try {
      const where: any = { partnerId };
      if (filters?.state) where.state = filters.state;
      if (filters?.relationshipType) where.relationshipType = filters.relationshipType;
      const rows = await (this.prisma as any).partnerTenantRelationship?.findMany?.({ where, take: 500, orderBy: { createdAt: 'desc' } });
      if (rows && rows.length > 0) list = rows.map((r: any) => this.mapRow(r));
    } catch {}
    return list;
  }

  async getPrimaryPartnerForTenant(tenantId: string): Promise<PartnerTenantRelationship | null> {
    const id = this.tenantPrimaryIndex.get(tenantId);
    if (id) {
      const mem = this.inMemory.get(id);
      if (mem) return mem;
    }
    try {
      const row = await (this.prisma as any).partnerTenantRelationship?.findFirst?.({ where: { tenantId, isPrimary: true, state: 'ACTIVE' } });
      if (row) return this.mapRow(row);
    } catch {}
    return null;
  }

  private mapRow(row: any): PartnerTenantRelationship {
    return {
      id: row.id,
      partnerId: row.partnerId,
      tenantId: row.tenantId,
      relationshipType: row.relationshipType,
      state: row.state,
      attributionId: row.attributionId ?? null,
      campaignId: row.campaignId ?? null,
      referralCode: row.referralCode ?? null,
      assignedAt: row.assignedAt instanceof Date ? row.assignedAt.toISOString() : row.assignedAt,
      assignedBy: row.assignedBy,
      activatedAt: row.activatedAt ? (row.activatedAt instanceof Date ? row.activatedAt.toISOString() : row.activatedAt) : null,
      terminatedAt: row.terminatedAt ? (row.terminatedAt instanceof Date ? row.terminatedAt.toISOString() : row.terminatedAt) : null,
      isPrimary: !!row.isPrimary,
      metadata: row.metadata ?? null,
      idempotencyKey: row.idempotencyKey,
      createdAt: row.createdAt instanceof Date ? row.createdAt.toISOString() : row.createdAt,
      updatedAt: row.updatedAt instanceof Date ? row.updatedAt.toISOString() : row.updatedAt,
    };
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PartnerProfileService } from './partner-profile.service';
import { PartnerTenantService } from './partner-tenant.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

export interface PartnerUsageAggregate {
  partnerId: string;
  periodStart: string;
  periodEnd: string;
  totalTenants: number;
  activeTenants: number;
  totalUsers: number;
  activeSubscriptions: number;
  totalApiCalls: number;
  totalTradingVolume: string;
  totalCopyTrades: number;
  usageByTenant: Array<{ tenantId: string; apiCalls: number; tradingVolume: string; activeUsers: number; subscriptionStatus: string }>;
  generatedAt: string;
  currency: string;
}

@Injectable()
export class PartnerUsageService {
  private readonly logger = new Logger(PartnerUsageService.name);

  constructor(
    private readonly profileService: PartnerProfileService,
    private readonly tenantService: PartnerTenantService,
    private readonly prisma: PrismaService,
  ) {}

  async aggregateUsage(params: {
    partnerId: string;
    periodStart: string;
    periodEnd: string;
    correlationId: string;
  }): Promise<PartnerUsageAggregate> {
    if (!params.partnerId || !params.periodStart || !params.periodEnd) throw new BadRequestException('partnerId, periodStart, periodEnd required');

    await this.profileService.getProfile(params.partnerId);
    const periodStart = new Date(params.periodStart);
    const periodEnd = new Date(params.periodEnd);
    if (isNaN(periodStart.getTime()) || isNaN(periodEnd.getTime()) || periodStart >= periodEnd) throw new BadRequestException('invalid period');

    const relationships = await this.tenantService.listTenantsForPartner(params.partnerId);
    const activeRels = relationships.filter(r => r.state === 'ACTIVE');
    const tenantIds = activeRels.map(r => r.tenantId);

    let totalUsers = 0;
    let activeSubscriptions = 0;
    let totalApiCalls = 0;
    let totalTradingVolumeMinor = BigInt(0);
    let totalCopyTrades = 0;
    const usageByTenant: PartnerUsageAggregate['usageByTenant'] = [];

    for (const tenantId of tenantIds) {
      try {
        // Aggregate from existing UsageModule records - never create second metering source
        const users = await (this.prisma as any).user?.count?.({ where: { tenantId } }) ?? 0;
        const subs = await (this.prisma as any).tenantSubscription?.count?.({ where: { tenantId, status: { in: ['ACTIVE', 'TRIALING'] } } }) ?? 0;
        // UsageMeter rows are per metering period with an Int currentValue (no timestamp/count columns).
        const apiCalls = await (this.prisma as any).usageMeter?.aggregate?.({
          where: { tenantId, meterKey: 'API_REQUESTS', periodStart: { gte: periodStart }, periodEnd: { lte: periodEnd } },
          _sum: { currentValue: true },
        }).then((r: any) => r._sum?.currentValue ?? 0);
        // Cash-ledger amounts are decimal strings (Prisma cannot _sum a String column): sum trade settlements here.
        const tradingVolume = await (this.prisma as any).portfolioCashLedgerEntry?.findMany?.({
          where: { tenantId, cashFlowType: { in: ['TRADE_SETTLEMENT_BUY', 'TRADE_SETTLEMENT_SELL'] }, occurredAt: { gte: periodStart, lte: periodEnd } },
          select: { amount: true },
        }).then((rows: Array<{ amount: string }>) => String(rows.reduce((sum, row) => sum + Math.abs(parseFloat(row.amount) || 0), 0)));
        const copyTrades = await (this.prisma as any).copyExecution?.count?.({ where: { tenantId, createdAt: { gte: periodStart, lte: periodEnd } } }) ?? 0;

        totalUsers += users;
        activeSubscriptions += subs;
        totalApiCalls += apiCalls;
        try {
          totalTradingVolumeMinor += BigInt(Math.round(parseFloat(tradingVolume) * 100));
        } catch {}
        totalCopyTrades += copyTrades;

        usageByTenant.push({
          tenantId,
          apiCalls,
          tradingVolume: tradingVolume.toString(),
          activeUsers: users,
          subscriptionStatus: subs > 0 ? 'ACTIVE' : 'INACTIVE',
        });
      } catch (error) {
        // Recorded as UNKNOWN (not as zero usage) so the aggregate never presents an unread tenant as an idle one.
        this.logger.warn(`usage aggregate read failed tenant=${tenantId}: ${(error as Error).message}`);
        usageByTenant.push({ tenantId, apiCalls: 0, tradingVolume: '0', activeUsers: 0, subscriptionStatus: 'UNKNOWN' });
      }
    }

    const aggregate: PartnerUsageAggregate = {
      partnerId: params.partnerId,
      periodStart: periodStart.toISOString(),
      periodEnd: periodEnd.toISOString(),
      totalTenants: tenantIds.length,
      activeTenants: activeRels.length,
      totalUsers,
      activeSubscriptions,
      totalApiCalls,
      totalTradingVolume: (Number(totalTradingVolumeMinor) / 100).toFixed(2),
      totalCopyTrades,
      usageByTenant,
      generatedAt: new Date().toISOString(),
      currency: 'USD',
    };

    this.logger.log(`usage aggregated partner=${params.partnerId} tenants=${tenantIds.length} corr=${params.correlationId}`);
    return aggregate;
  }
}

import { Injectable, Logger, BadRequestException, NotFoundException } from '@nestjs/common';
import { PartnerUserRole, PartnerUserState, PartnerAuditAction } from './partner.types';
import { PartnerAuditService } from './partner-audit.service';
import { PartnerProfileService } from './partner-profile.service';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

export interface PartnerUser {
  id: string;
  partnerId: string;
  userId: string;
  role: PartnerUserRole;
  state: PartnerUserState;
  invitedBy: string;
  invitedAt: string;
  activatedAt?: string | null;
  suspendedAt?: string | null;
  createdAt: string;
  updatedAt: string;
  idempotencyKey: string;
}

@Injectable()
export class PartnerUserService {
  private readonly logger = new Logger(PartnerUserService.name);
  private readonly inMemory: Map<string, PartnerUser> = new Map();

  constructor(
    private readonly audit: PartnerAuditService,
    private readonly profileService: PartnerProfileService,
    private readonly prisma: PrismaService,
  ) {}

  async inviteUser(params: {
    partnerId: string;
    userId: string;
    role: PartnerUserRole;
    invitedBy: string;
    correlationId: string;
    idempotencyKey: string;
  }): Promise<PartnerUser> {
    if (!params.partnerId || !params.userId || !params.role || !params.idempotencyKey) throw new BadRequestException('partnerId, userId, role, idempotencyKey required');
    if (!Object.values(PartnerUserRole).includes(params.role)) throw new BadRequestException(`invalid role ${params.role}`);

    await this.profileService.getProfile(params.partnerId);

    const existingByIdem = [...this.inMemory.values()].find(u => u.idempotencyKey === params.idempotencyKey);
    if (existingByIdem) return existingByIdem;

    const duplicate = [...this.inMemory.values()].find(u => u.partnerId === params.partnerId && u.userId === params.userId && u.state !== PartnerUserState.DEACTIVATED);
    if (duplicate) throw new BadRequestException(`user ${params.userId} already has role in partner ${params.partnerId}`);

    const partnerUser: PartnerUser = {
      id: `puser_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      partnerId: params.partnerId,
      userId: params.userId,
      role: params.role,
      state: PartnerUserState.INVITED,
      invitedBy: params.invitedBy,
      invitedAt: new Date().toISOString(),
      activatedAt: null,
      suspendedAt: null,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      idempotencyKey: params.idempotencyKey,
    };

    this.inMemory.set(partnerUser.id, partnerUser);
    try {
      await (this.prisma as any).partnerUser?.create?.({
        data: {
          id: partnerUser.id,
          partnerId: partnerUser.partnerId,
          userId: partnerUser.userId,
          role: partnerUser.role,
          state: partnerUser.state,
          invitedBy: partnerUser.invitedBy,
          invitedAt: new Date(partnerUser.invitedAt),
          createdAt: new Date(partnerUser.createdAt),
          updatedAt: new Date(partnerUser.updatedAt),
          idempotencyKey: partnerUser.idempotencyKey,
        },
      });
    } catch {
      this.logger.debug(`partner user persist skipped id=${partnerUser.id}`);
    }

    await this.audit.recordEvent({
      partnerId: params.partnerId,
      actorId: params.invitedBy,
      action: PartnerAuditAction.PARTNER_USER_INVITED,
      source: 'PARTNER_USER_SERVICE',
      correlationId: params.correlationId,
      safeEvidence: { userId: params.userId, role: params.role },
    });

    this.logger.log(`partner user invited partner=${params.partnerId} user=${params.userId} role=${params.role} corr=${params.correlationId}`);
    return partnerUser;
  }

  async activateUser(params: { partnerUserId: string; partnerId: string; activatedBy: string; correlationId: string }): Promise<PartnerUser> {
    const pu = await this.getPartnerUser(params.partnerUserId, params.partnerId);
    if (pu.state !== PartnerUserState.INVITED && pu.state !== PartnerUserState.SUSPENDED) throw new BadRequestException(`cannot activate from state ${pu.state}`);
    pu.state = PartnerUserState.ACTIVE;
    pu.activatedAt = new Date().toISOString();
    pu.updatedAt = new Date().toISOString();
    this.inMemory.set(pu.id, pu);
    try {
      await (this.prisma as any).partnerUser?.update?.({ where: { id: pu.id }, data: { state: pu.state, activatedAt: new Date(pu.activatedAt), updatedAt: new Date(pu.updatedAt) } });
    } catch {}
    return pu;
  }

  async suspendUser(params: { partnerUserId: string; partnerId: string; suspendedBy: string; correlationId: string; reason: string }): Promise<PartnerUser> {
    const pu = await this.getPartnerUser(params.partnerUserId, params.partnerId);
    if (pu.state !== PartnerUserState.ACTIVE) throw new BadRequestException(`cannot suspend from state ${pu.state}`);
    pu.state = PartnerUserState.SUSPENDED;
    pu.suspendedAt = new Date().toISOString();
    pu.updatedAt = new Date().toISOString();
    this.inMemory.set(pu.id, pu);
    try {
      await (this.prisma as any).partnerUser?.update?.({ where: { id: pu.id }, data: { state: pu.state, suspendedAt: new Date(pu.suspendedAt), updatedAt: new Date(pu.updatedAt) } });
    } catch {}
    await this.audit.recordEvent({
      partnerId: params.partnerId,
      actorId: params.suspendedBy,
      action: PartnerAuditAction.PARTNER_USER_SUSPENDED,
      source: 'PARTNER_USER_SERVICE',
      correlationId: params.correlationId,
      safeEvidence: { userId: pu.userId, reason: params.reason },
    });
    return pu;
  }

  async changeRole(params: { partnerUserId: string; partnerId: string; newRole: PartnerUserRole; changedBy: string; correlationId: string }): Promise<PartnerUser> {
    const pu = await this.getPartnerUser(params.partnerUserId, params.partnerId);
    if (!Object.values(PartnerUserRole).includes(params.newRole)) throw new BadRequestException(`invalid role ${params.newRole}`);
    if (pu.state !== PartnerUserState.ACTIVE) throw new BadRequestException('only active users can change role');
    pu.role = params.newRole;
    pu.updatedAt = new Date().toISOString();
    this.inMemory.set(pu.id, pu);
    try {
      await (this.prisma as any).partnerUser?.update?.({ where: { id: pu.id }, data: { role: pu.role, updatedAt: new Date(pu.updatedAt) } });
    } catch {}
    return pu;
  }

  async getPartnerUser(partnerUserId: string, partnerId: string): Promise<PartnerUser> {
    const mem = this.inMemory.get(partnerUserId);
    if (mem) {
      if (mem.partnerId !== partnerId) throw new BadRequestException('partner isolation violation');
      return mem;
    }
    try {
      const row = await (this.prisma as any).partnerUser?.findUnique?.({ where: { id: partnerUserId } });
      if (row) {
        if (row.partnerId !== partnerId) throw new BadRequestException('partner isolation violation');
        const mapped = this.mapRow(row);
        this.inMemory.set(mapped.id, mapped);
        return mapped;
      }
    } catch {}
    throw new NotFoundException(`partner user ${partnerUserId} not found`);
  }

  async listUsersForPartner(partnerId: string): Promise<PartnerUser[]> {
    let list = [...this.inMemory.values()].filter(u => u.partnerId === partnerId);
    try {
      const rows = await (this.prisma as any).partnerUser?.findMany?.({ where: { partnerId }, take: 500 });
      if (rows && rows.length > 0) list = rows.map((r: any) => this.mapRow(r));
    } catch {}
    return list;
  }

  async assertUserHasPartnerAccess(userId: string, partnerId: string, requiredRoles?: PartnerUserRole[]): Promise<PartnerUser> {
    const pu = [...this.inMemory.values()].find(u => u.userId === userId && u.partnerId === partnerId && u.state === PartnerUserState.ACTIVE);
    if (!pu) {
      try {
        const row = await (this.prisma as any).partnerUser?.findFirst?.({ where: { userId, partnerId, state: 'ACTIVE' } });
        if (row) return this.mapRow(row);
      } catch {}
      throw new BadRequestException(`user ${userId} has no active access to partner ${partnerId}`);
    }
    if (requiredRoles && requiredRoles.length > 0 && !requiredRoles.includes(pu.role)) {
      throw new BadRequestException(`user role ${pu.role} not authorized, required ${requiredRoles.join(',')}`);
    }
    return pu;
  }

  private mapRow(row: any): PartnerUser {
    return {
      id: row.id,
      partnerId: row.partnerId,
      userId: row.userId,
      role: row.role,
      state: row.state,
      invitedBy: row.invitedBy,
      invitedAt: row.invitedAt instanceof Date ? row.invitedAt.toISOString() : row.invitedAt,
      activatedAt: row.activatedAt ? (row.activatedAt instanceof Date ? row.activatedAt.toISOString() : row.activatedAt) : null,
      suspendedAt: row.suspendedAt ? (row.suspendedAt instanceof Date ? row.suspendedAt.toISOString() : row.suspendedAt) : null,
      createdAt: row.createdAt instanceof Date ? row.createdAt.toISOString() : row.createdAt,
      updatedAt: row.updatedAt instanceof Date ? row.updatedAt.toISOString() : row.updatedAt,
      idempotencyKey: row.idempotencyKey,
    };
  }
}

