import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AccountingPolicyService } from './accounting-policy.service';
import {
  PortfolioAdjustmentType,
  deterministicIdempotencyKey,
  redactSecrets,
  isValidDecimal,
} from './portfolio-accounting.types';

/** True when an adjustment row has been reversed (the reversal is recorded in adjustedValues.reversal). */
export function isAdjustmentReversed(row: any): boolean {
  const values = row?.adjustedValues;
  return Boolean(values && typeof values === 'object' && values.reversal);
}

/**
 * API view of a PortfolioAccountingAdjustment row: keeps the response fields
 * (adjustedAmount, adjustedQuantity, asset, operatorId, evidence, isReversed…)
 * that are stored in the amount/requestedBy columns and adjustedValues Json.
 */
export function toAdjustmentView(row: any): any {
  if (!row) return row;
  const values = row.adjustedValues && typeof row.adjustedValues === 'object' ? row.adjustedValues : {};
  const reversal = values.reversal && typeof values.reversal === 'object' ? values.reversal : null;
  return {
    ...row,
    adjustedAmount: values.amount ?? row.amount ?? null,
    adjustedQuantity: values.quantity ?? null,
    asset: values.asset ?? null,
    operatorId: row.requestedBy ?? null,
    evidence: values.evidence ?? {},
    isReversed: Boolean(reversal),
    reversedAt: reversal?.reversedAt ?? null,
    reversedBy: reversal?.reversedBy ?? null,
    reversalReason: reversal?.reason ?? null,
  };
}

/**
 * Creates auditable adjustments/reversals referencing original event, reason, operator,
 * policy/version, preserves immutable history. Never mutate history — corrections via reversal only.
 */

@Injectable()
export class AccountingAdjustmentService {
  private readonly logger = new Logger(AccountingAdjustmentService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: AccountingPolicyService,
  ) {}

  async createAdjustment(params: {
    tenantId: string;
    profileId: string;
    originalEventId?: string | null;
    adjustmentType: PortfolioAdjustmentType;
    reason: string;
    adjustedAmount?: string | null;
    adjustedQuantity?: string | null;
    asset?: string | null;
    operatorId: string;
    evidence?: Record<string, unknown>;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, profileId, originalEventId = null, adjustmentType, reason, adjustedAmount = null, adjustedQuantity = null, asset = null, operatorId, correlationId = null } = params;

    if (!reason || reason.trim().length < 5) throw new BadRequestException('Reason required (min 5 chars) for adjustment');

    if (adjustedAmount && !isValidDecimal(adjustedAmount)) throw new BadRequestException(`Invalid adjustedAmount: ${adjustedAmount}`);
    if (adjustedQuantity && !isValidDecimal(adjustedQuantity)) throw new BadRequestException(`Invalid adjustedQuantity: ${adjustedQuantity}`);

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });

    const idempotencyKey = deterministicIdempotencyKey({
      type: `adjustment:${adjustmentType}:${originalEventId ?? 'manual'}`,
      tenantId,
      profileId,
      sourceId: originalEventId ?? `${adjustmentType}:${Date.now()}`,
    });

    try {
      const existing = await (this.prisma as any).portfolioAccountingAdjustment.findFirst({ where: { tenantId, idempotencyKey } });
      if (existing) return toAdjustmentView(existing);
    } catch {}

    // If originalEventId provided, verify it exists and belongs to tenant/profile
    if (originalEventId) {
      try {
        const original = await (this.prisma as any).portfolioAccountingEvent.findFirst({
          where: { id: originalEventId, tenantId, profileId },
        });
        if (!original) throw new BadRequestException('Original event not found or tenant mismatch');

        // Check if period is closed — closed periods immutable, corrections via reversal only (allowed but audited)
        // We allow adjustment but must note it is post-close
        const period = await (this.prisma as any).portfolioAccountingPeriod.findFirst({
          where: {
            tenantId,
            profileId,
            periodStart: { lte: original.sourceTimestamp },
            periodEnd: { gte: original.sourceTimestamp },
            state: 'CLOSED',
          },
        });
        if (period) {
          this.logger.warn({ event: 'portfolio.adjustment.post_close', tenantId, profileId, periodId: period.id, originalEventId });
        }
      } catch (e) {
        if (e instanceof BadRequestException) throw e;
      }
    }

    const adjustment = await (this.prisma as any).portfolioAccountingAdjustment.create({
      data: {
        tenantId,
        profileId,
        originalEventId: originalEventId ?? null,
        adjustmentType: adjustmentType as any,
        reason,
        // Model columns: amount + requestedBy; the adjusted values (required Json) carry the rest.
        amount: adjustedAmount ?? null,
        requestedBy: operatorId,
        adjustedValues: {
          amount: adjustedAmount ?? null,
          quantity: adjustedQuantity ?? null,
          asset: asset ?? null,
          evidence: redactSecrets(params.evidence ?? {}),
        } as any,
        calculationVersion: policy.calculationVersion,
        policyVersion: policy.policyVersion,
        idempotencyKey,
        correlationId: correlationId ?? null,
      },
    });

    // If reversal, mark original as reversed — preserve history, never mutate history destructively
    if (adjustmentType === PortfolioAdjustmentType.REVERSAL && originalEventId) {
      try {
        const originalEvent = await (this.prisma as any).portfolioAccountingEvent.findFirst({ where: { id: originalEventId } });
        const eventMetadata = originalEvent?.metadata && typeof originalEvent.metadata === 'object' ? originalEvent.metadata : {};
        await (this.prisma as any).portfolioAccountingEvent.update({
          where: { id: originalEventId },
          data: {
            isReversed: true,
            metadata: {
              ...eventMetadata,
              reversal: { reversedAt: new Date().toISOString(), reversedBy: operatorId, reason, adjustmentId: adjustment.id },
            } as any,
          },
        });
      } catch {}
    }

    // For correction, create a new accounting event that is the correction — original stays
    if (adjustmentType === PortfolioAdjustmentType.CORRECTION && originalEventId) {
      try {
        const original = await (this.prisma as any).portfolioAccountingEvent.findFirst({ where: { id: originalEventId } });
        if (original) {
          // Create reversal of original + new corrected event — both preserved
          const reversalKey = deterministicIdempotencyKey({
            type: `reversal_for_correction:${originalEventId}`,
            tenantId,
            profileId,
            sourceId: originalEventId,
          });

          await (this.prisma as any).portfolioAccountingEvent.create({
            data: {
              tenantId,
              profileId,
              eventType: 'REVERSAL',
              cashFlowType: original.cashFlowType,
              sourceType: 'ADJUSTMENT_REVERSAL',
              sourceId: `reversal_${originalEventId}_${Date.now()}`,
              sourceTimestamp: new Date(),
              asset: asset ?? original.asset,
              quantity: adjustedQuantity ?? original.quantity,
              amount: adjustedAmount ?? original.amount,
              currency: original.currency,
              baseCurrency: original.baseCurrency,
              calculationVersion: policy.calculationVersion,
              policyVersion: policy.policyVersion,
              idempotencyKey: reversalKey,
              fingerprint: `reversal_${originalEventId}`,
              correlationId,
              metadata: redactSecrets({ originalEventId, adjustmentId: adjustment.id, reason }) as any,
              evidence: redactSecrets({ originalEventId, reason, operatorId }) as any,
            },
          });
        }
      } catch {}
    }

    this.logger.log({ event: 'portfolio.adjustment.created', tenantId, profileId, adjustmentType, originalEventId });

    return toAdjustmentView(adjustment);
  }

  async listAdjustments(params: {
    tenantId: string;
    profileId?: string;
    originalEventId?: string;
    adjustmentType?: string;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId, profileId, originalEventId, adjustmentType, page = 1, limit = 50 } = params;
    const where: any = { tenantId };
    if (profileId) where.profileId = profileId;
    if (originalEventId) where.originalEventId = originalEventId;
    if (adjustmentType) where.adjustmentType = adjustmentType;

    const [data, total] = await Promise.all([
      (this.prisma as any).portfolioAccountingAdjustment.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).portfolioAccountingAdjustment.count({ where }),
    ]);
    return { data: data.map(toAdjustmentView), total, page, limit };
  }

  async reverseAdjustment(params: { tenantId: string; adjustmentId: string; operatorId: string; reason: string }): Promise<any> {
    const { tenantId, adjustmentId, operatorId, reason } = params;

    const adjustment = await (this.prisma as any).portfolioAccountingAdjustment.findFirst({ where: { id: adjustmentId, tenantId } });
    if (!adjustment) throw new BadRequestException('Adjustment not found');

    if (toAdjustmentView(adjustment).isReversed) throw new BadRequestException('Adjustment already reversed');

    const adjustedValues = adjustment.adjustedValues && typeof adjustment.adjustedValues === 'object' ? adjustment.adjustedValues : {};
    const updated = await (this.prisma as any).portfolioAccountingAdjustment.update({
      where: { id: adjustmentId },
      data: {
        adjustedValues: {
          ...adjustedValues,
          reversal: { reversedAt: new Date().toISOString(), reversedBy: operatorId, reason },
        } as any,
      },
    });

    return toAdjustmentView(updated);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { deterministicAccountingFingerprint, redactSecrets } from './portfolio-accounting.types';

/**
 * Persists immutable normalized accounting events with uniqueness and tenant isolation.
 * Must support deterministic replay and period reconstruction without destructive mutation.
 * Immutable: no update/delete that mutates historical truth — only reversal via adjustment.
 */

@Injectable()
export class AccountingEventRepository {
  private readonly logger = new Logger(AccountingEventRepository.name);

  constructor(private readonly prisma: PrismaService) {}

  async createEvent(params: {
    tenantId: string;
    profileId: string;
    eventType: string;
    cashFlowType?: string | null;
    sourceType: string;
    sourceId: string;
    sourceTimestamp: Date;
    asset?: string | null;
    quantity?: string | null;
    price?: string | null;
    amount?: string | null;
    feeAmount?: string | null;
    currency?: string | null;
    orderId?: string | null;
    fillId?: string | null;
    tradeId?: string | null;
    feeAccrualId?: string | null;
    financeLedgerId?: string | null;
    copyAllocationId?: string | null;
    baseCurrency?: string | null;
    conversionRate?: string | null;
    conversionSource?: string | null;
    conversionTimestamp?: Date | null;
    conversionStatus?: string | null;
    calculationVersion: string;
    policyVersion: string;
    idempotencyKey: string;
    correlationId?: string | null;
    requestId?: string | null;
    metadata?: Record<string, unknown>;
    evidence?: Record<string, unknown>;
  }): Promise<any> {
    // Idempotency mandatory — re-running same event must not double-count
    try {
      const existing = await (this.prisma as any).portfolioAccountingEvent.findFirst({
        where: { tenantId: params.tenantId, idempotencyKey: params.idempotencyKey },
      });
      if (existing) {
        this.logger.log({ event: 'portfolio.event.idempotent_hit', idempotencyKey: params.idempotencyKey });
        return existing;
      }
    } catch {}

    const fingerprint = deterministicAccountingFingerprint({
      sourceType: params.sourceType,
      sourceId: params.sourceId,
      tenantId: params.tenantId,
      profileId: params.profileId,
      asset: params.asset ?? undefined,
      quantity: params.quantity ?? undefined,
    });

    // Check fingerprint duplicate as secondary guard
    try {
      const existingByFingerprint = await (this.prisma as any).portfolioAccountingEvent.findFirst({
        where: { tenantId: params.tenantId, fingerprint, sourceType: params.sourceType, sourceId: params.sourceId },
      });
      if (existingByFingerprint) {
        this.logger.log({ event: 'portfolio.event.fingerprint_duplicate', fingerprint });
        return existingByFingerprint;
      }
    } catch {}

    const created = await (this.prisma as any).portfolioAccountingEvent.create({
      data: {
        tenantId: params.tenantId,
        profileId: params.profileId,
        eventType: params.eventType,
        cashFlowType: params.cashFlowType ? (params.cashFlowType as any) : null,
        sourceType: params.sourceType,
        sourceId: params.sourceId,
        sourceTimestamp: params.sourceTimestamp,
        asset: params.asset ?? null,
        quantity: params.quantity ?? null,
        price: params.price ?? null,
        amount: params.amount ?? null,
        feeAmount: params.feeAmount ?? null,
        currency: params.currency ?? null,
        orderId: params.orderId ?? null,
        fillId: params.fillId ?? null,
        tradeId: params.tradeId ?? null,
        feeAccrualId: params.feeAccrualId ?? null,
        financeLedgerId: params.financeLedgerId ?? null,
        copyAllocationId: params.copyAllocationId ?? null,
        baseCurrency: params.baseCurrency ?? null,
        conversionRate: params.conversionRate ?? null,
        conversionSource: params.conversionSource ?? null,
        conversionTimestamp: params.conversionTimestamp ?? null,
        conversionStatus: params.conversionStatus ?? null,
        calculationVersion: params.calculationVersion,
        policyVersion: params.policyVersion,
        idempotencyKey: params.idempotencyKey,
        fingerprint,
        correlationId: params.correlationId ?? null,
        requestId: params.requestId ?? null,
        metadata: redactSecrets(params.metadata ?? {}) as any,
        evidence: redactSecrets(params.evidence ?? {}) as any,
      },
    });

    return created;
  }

  async listEvents(params: {
    tenantId: string;
    profileId?: string;
    eventType?: string;
    sourceType?: string;
    from?: Date;
    to?: Date;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId, profileId, eventType, sourceType, from, to, page = 1, limit = 50 } = params;
    const where: any = { tenantId };
    if (profileId) where.profileId = profileId;
    if (eventType) where.eventType = eventType;
    if (sourceType) where.sourceType = sourceType;
    if (from || to) {
      where.sourceTimestamp = {};
      if (from) where.sourceTimestamp.gte = from;
      if (to) where.sourceTimestamp.lte = to;
    }

    const [data, total] = await Promise.all([
      (this.prisma as any).portfolioAccountingEvent.findMany({
        where,
        orderBy: { sourceTimestamp: 'asc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).portfolioAccountingEvent.count({ where }),
    ]);
    return { data, total, page, limit };
  }

  async getEventsForPeriod(params: {
    tenantId: string;
    profileId: string;
    periodStart: Date;
    periodEnd: Date;
  }): Promise<any[]> {
    return await (this.prisma as any).portfolioAccountingEvent.findMany({
      where: {
        tenantId: params.tenantId,
        profileId: params.profileId,
        sourceTimestamp: { gte: params.periodStart, lte: params.periodEnd },
        isReversed: false,
      },
      orderBy: { sourceTimestamp: 'asc' },
    });
  }

  async replayEvents(params: {
    tenantId: string;
    profileId: string;
    from?: Date;
    to?: Date;
  }): Promise<any[]> {
    // Deterministic replay for period reconstruction
    const where: any = { tenantId: params.tenantId, profileId: params.profileId, isReversed: false };
    if (params.from || params.to) {
      where.sourceTimestamp = {};
      if (params.from) where.sourceTimestamp.gte = params.from;
      if (params.to) where.sourceTimestamp.lte = params.to;
    }
    return await (this.prisma as any).portfolioAccountingEvent.findMany({
      where,
      orderBy: [{ sourceTimestamp: 'asc' }, { createdAt: 'asc' }],
    });
  }

  async findBySource(params: { tenantId: string; sourceType: string; sourceId: string }): Promise<any | null> {
    return await (this.prisma as any).portfolioAccountingEvent.findFirst({
      where: { tenantId: params.tenantId, sourceType: params.sourceType, sourceId: params.sourceId },
    });
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AccountingEventRepository } from './accounting-event.repository';
import { AccountingPolicyService } from './accounting-policy.service';
import { PortfolioCashFlowType, deterministicIdempotencyKey, redactSecrets, parseScaled, formatScaled, SCALE_FACTOR } from './portfolio-accounting.types';

/**
 * Converts authoritative OMS fills, trade lifecycle events, balances, positions, fees,
 * deposits, withdrawals, transfers, and copy allocations into normalized immutable
 * accounting events. Every event must preserve sourceType/sourceId/sourceTimestamp
 * and deterministic idempotency.
 *
 * Source-of-truth rules enforced:
 * - Exchange balance = authoritative for exchange balance truth (we reference, not overwrite)
 * - Exchange position / existing position service = authoritative for live position state
 * - OMS fill = authoritative execution event
 * - Fees module = authoritative platform/performance fee accounting
 * - Finance ledger = authoritative billing/financial ledger
 * - Portfolio Accounting = authoritative accounting/reporting interpretation
 */

@Injectable()
export class AccountingEventService {
  private readonly logger = new Logger(AccountingEventService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventRepo: AccountingEventRepository,
    private readonly policyService: AccountingPolicyService,
  ) {}

  async ingestFromOmsFill(params: {
    tenantId: string;
    profileId: string;
    fill: any;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, profileId, fill, correlationId = null } = params;

    if (!fill) throw new BadRequestException('Fill required');
    // Authoritative OMS fill is used as source — must have providerFillId, qty, price, timestamp
    const sourceType = 'OMS_FILL';
    const sourceId = fill.providerFillId ?? fill.id ?? fill.fillId;
    if (!sourceId) throw new BadRequestException('Fill missing providerFillId');

    const quantity = fill.quantity?.toString() ?? fill.qty?.toString();
    const price = fill.price?.toString();
    const fee = fill.fee?.toString() ?? '0';
    const symbol = fill.symbol;
    const side = fill.side;

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });

    const idempotencyKey = deterministicIdempotencyKey({
      type: `accounting:${sourceType}`,
      tenantId,
      profileId,
      sourceId,
      timestampBucket: new Date(fill.timestampMicros ? Number(fill.timestampMicros) / 1000 : Date.now()).toISOString().slice(0, 10),
    });

    const cashFlowType = side === 'BUY' ? PortfolioCashFlowType.TRADE_SETTLEMENT_BUY : PortfolioCashFlowType.TRADE_SETTLEMENT_SELL;

    const amount = this.calculateTradeAmount(quantity, price);

    const event = await this.eventRepo.createEvent({
      tenantId,
      profileId,
      eventType: 'TRADE_FILL',
      cashFlowType: cashFlowType as any,
      sourceType,
      sourceId,
      sourceTimestamp: fill.timestampMicros ? new Date(Number(fill.timestampMicros) / 1000) : fill.createdAt ? new Date(fill.createdAt) : new Date(),
      asset: symbol,
      quantity,
      price,
      amount,
      feeAmount: fee,
      currency: fill.feeCurrency ?? 'USDT',
      orderId: fill.orderIntentId ?? fill.orderId ?? null,
      fillId: sourceId,
      baseCurrency: policy.baseCurrency,
      calculationVersion: policy.calculationVersion,
      policyVersion: policy.policyVersion,
      idempotencyKey,
      correlationId,
      metadata: redactSecrets({ symbol, side, venue: fill.venue }) as any,
      evidence: redactSecrets({
        providerFillId: fill.providerFillId,
        providerOrderId: fill.providerOrderId,
        quantity,
        price,
        fee,
        timestamp: fill.timestampMicros,
        source: 'OMS_FILL authoritative',
      }) as any,
    });

    this.logger.log({ event: 'portfolio.event.ingested_fill', tenantId, profileId, sourceId, idempotencyKey });
    return event;
  }

  async ingestFromFeeAccrual(params: {
    tenantId: string;
    profileId: string;
    feeAccrual: any;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, profileId, feeAccrual, correlationId = null } = params;

    if (!feeAccrual) throw new BadRequestException('Fee accrual required');
    // Authoritative fee record is not duplicated — we reference it, not duplicate calculation
    const sourceType = 'FEE_ACCRUAL';
    const sourceId = feeAccrual.id;

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });

    const idempotencyKey = deterministicIdempotencyKey({
      type: `accounting:${sourceType}`,
      tenantId,
      profileId,
      sourceId,
    });

    const cashFlowType = feeAccrual.feeType === 'PERFORMANCE' ? PortfolioCashFlowType.PERFORMANCE_FEE : PortfolioCashFlowType.PLATFORM_FEE;

    const event = await this.eventRepo.createEvent({
      tenantId,
      profileId,
      eventType: 'FEE',
      cashFlowType: cashFlowType as any,
      sourceType,
      sourceId,
      sourceTimestamp: feeAccrual.createdAt ? new Date(feeAccrual.createdAt) : new Date(),
      asset: feeAccrual.currency ?? 'USD',
      amount: feeAccrual.feeAmount?.toString() ?? '0',
      feeAmount: feeAccrual.feeAmount?.toString() ?? '0',
      currency: feeAccrual.currency ?? 'USD',
      feeAccrualId: sourceId,
      baseCurrency: policy.baseCurrency,
      calculationVersion: policy.calculationVersion,
      policyVersion: policy.policyVersion,
      idempotencyKey,
      correlationId,
      metadata: redactSecrets({ feeType: feeAccrual.feeType, sourceId }) as any,
      evidence: redactSecrets({
        feeAccrualId: feeAccrual.id,
        feeAmount: feeAccrual.feeAmount,
        feeType: feeAccrual.feeType,
        source: 'Fees module authoritative',
      }) as any,
    });

    return event;
  }

  async ingestFromFinanceLedger(params: {
    tenantId: string;
    profileId: string;
    ledgerEntry: any;
    cashFlowType: PortfolioCashFlowType;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, profileId, ledgerEntry, cashFlowType, correlationId = null } = params;

    const sourceType = 'FINANCE_LEDGER';
    const sourceId = ledgerEntry.id ?? ledgerEntry.ledgerId ?? `${Date.now()}`;

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });

    const idempotencyKey = deterministicIdempotencyKey({
      type: `accounting:${sourceType}`,
      tenantId,
      profileId,
      sourceId,
    });

    const event = await this.eventRepo.createEvent({
      tenantId,
      profileId,
      eventType: 'CASH_MOVEMENT',
      cashFlowType: cashFlowType as any,
      sourceType,
      sourceId,
      sourceTimestamp: ledgerEntry.createdAt ? new Date(ledgerEntry.createdAt) : new Date(),
      asset: ledgerEntry.currency ?? ledgerEntry.asset ?? 'USD',
      amount: ledgerEntry.amount?.toString() ?? '0',
      currency: ledgerEntry.currency ?? 'USD',
      financeLedgerId: sourceId,
      baseCurrency: policy.baseCurrency,
      calculationVersion: policy.calculationVersion,
      policyVersion: policy.policyVersion,
      idempotencyKey,
      correlationId,
      metadata: redactSecrets({ cashFlowType, sourceId }) as any,
      evidence: redactSecrets({
        ledgerId: sourceId,
        amount: ledgerEntry.amount,
        source: 'Finance ledger authoritative',
      }) as any,
    });

    return event;
  }

  async ingestFromCopyAllocation(params: {
    tenantId: string;
    profileId: string;
    allocation: any;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, profileId, allocation, correlationId = null } = params;

    const sourceType = 'COPY_ALLOCATION';
    const sourceId = allocation.id;

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });

    const idempotencyKey = deterministicIdempotencyKey({
      type: `accounting:${sourceType}`,
      tenantId,
      profileId,
      sourceId,
    });

    const event = await this.eventRepo.createEvent({
      tenantId,
      profileId,
      eventType: 'COPY_ALLOCATION',
      sourceType,
      sourceId,
      sourceTimestamp: allocation.createdAt ? new Date(allocation.createdAt) : new Date(),
      asset: allocation.symbol ?? allocation.asset ?? 'UNKNOWN',
      quantity: allocation.executedQuantity ?? allocation.intendedQuantity ?? '0',
      amount: allocation.executedNotional ?? allocation.intendedNotional ?? '0',
      currency: 'USDT',
      copyAllocationId: sourceId,
      baseCurrency: policy.baseCurrency,
      calculationVersion: policy.calculationVersion,
      policyVersion: policy.policyVersion,
      idempotencyKey,
      correlationId,
      metadata: redactSecrets({ traderId: allocation.traderId, followerId: allocation.followerId }) as any,
      evidence: redactSecrets({
        allocationId: allocation.id,
        intendedQty: allocation.intendedQuantity,
        executedQty: allocation.executedQuantity,
        source: 'Copy-trading allocation authoritative',
      }) as any,
    });

    return event;
  }

  async ingestFromPositionSnapshot(params: {
    tenantId: string;
    profileId: string;
    position: any;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, profileId, position, correlationId = null } = params;

    const sourceType = 'POSITION_SNAPSHOT';
    const sourceId = position.id;

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });

    const idempotencyKey = deterministicIdempotencyKey({
      type: `accounting:${sourceType}`,
      tenantId,
      profileId,
      sourceId,
      timestampBucket: new Date().toISOString().slice(0, 10),
    });

    const event = await this.eventRepo.createEvent({
      tenantId,
      profileId,
      eventType: 'POSITION_SNAPSHOT',
      sourceType,
      sourceId,
      sourceTimestamp: position.updatedAt ? new Date(position.updatedAt) : new Date(),
      asset: position.symbol ?? position.asset,
      quantity: position.quantity?.toString() ?? '0',
      currency: 'USDT',
      baseCurrency: policy.baseCurrency,
      calculationVersion: policy.calculationVersion,
      policyVersion: policy.policyVersion,
      idempotencyKey,
      correlationId,
      metadata: redactSecrets({ symbol: position.symbol, side: position.side }) as any,
      evidence: redactSecrets({
        positionId: position.id,
        quantity: position.quantity,
        side: position.side,
        source: 'Position service authoritative, not rewritten',
      }) as any,
    });

    return event;
  }

  private calculateTradeAmount(quantity: string, price: string | null | undefined): string {
    if (!quantity || !price) return '0';
    try {
      // Decimal-safe string arithmetic, sharing the exact scaled helpers
      // (and the exact SCALE_FACTOR) that portfolio-accounting.types uses,
      // so both sides can never drift apart on scale.
      const q = parseScaled(quantity);
      const p = parseScaled(price);
      const amountScaled = (q * p) / SCALE_FACTOR;
      return formatScaled(amountScaled);
    } catch {
      return '0';
    }
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AccountingPolicyService } from './accounting-policy.service';
import {
  PortfolioPeriodState,
  PERIOD_VALID_TRANSITIONS,
  deterministicIdempotencyKey,
  redactSecrets,
} from './portfolio-accounting.types';

/**
 * Manages accounting periods with states OPEN→CLOSING→CLOSED only when required events present,
 * no critical reconciliation failures, valuation sufficient, NAV consistent, PnL reproducible,
 * fees/cash/positions reconcile; failure CLOSING→OPEN with evidence.
 * Closed periods immutable.
 */

@Injectable()
export class AccountingPeriodService {
  private readonly logger = new Logger(AccountingPeriodService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: AccountingPolicyService,
  ) {}

  async createPeriod(params: {
    tenantId: string;
    profileId: string;
    periodStart: Date;
    periodEnd: Date;
    periodType?: string;
    baseCurrency?: string;
  }): Promise<any> {
    const { tenantId, profileId, periodStart, periodEnd, periodType = 'DAILY' } = params;

    if (periodEnd <= periodStart) throw new BadRequestException('periodEnd must be after periodStart');

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });
    const baseCurrency = params.baseCurrency ?? policy.baseCurrency;

    const idempotencyKey = deterministicIdempotencyKey({
      type: `period:${periodType}:${periodStart.toISOString()}:${periodEnd.toISOString()}`,
      tenantId,
      profileId,
      sourceId: `${periodStart.toISOString()}_${periodEnd.toISOString()}`,
    });

    try {
      const existing = await (this.prisma as any).portfolioAccountingPeriod.findFirst({ where: { tenantId, idempotencyKey } });
      if (existing) return existing;
    } catch {}

    // Check for overlapping periods — conflict check
    try {
      const overlapping = await (this.prisma as any).portfolioAccountingPeriod.findFirst({
        where: {
          tenantId,
          profileId,
          periodStart: { lte: periodEnd },
          periodEnd: { gte: periodStart },
          state: { not: 'CLOSED' },
        },
      });
      if (overlapping) {
        throw new BadRequestException(`Overlapping period exists: ${overlapping.id}`);
      }
    } catch (e) {
      if (e instanceof BadRequestException) throw e;
    }

    const period = await (this.prisma as any).portfolioAccountingPeriod.create({
      data: {
        tenantId,
        profileId,
        periodStart,
        periodEnd,
        state: PortfolioPeriodState.OPEN as any,
        // No periodType column: it is kept in closeMetadata.
        closeMetadata: { periodType } as any,
        baseCurrency,
        calculationVersion: policy.calculationVersion,
        policyVersion: policy.policyVersion,
        idempotencyKey,
      },
    });

    this.logger.log({ event: 'portfolio.period.created', tenantId, profileId, periodId: period.id });

    return period;
  }

  async transitionPeriod(params: {
    tenantId: string;
    periodId: string;
    toState: PortfolioPeriodState;
    reason?: string;
    operatorId?: string;
  }): Promise<any> {
    const { tenantId, periodId, toState, reason, operatorId } = params;

    const period = await (this.prisma as any).portfolioAccountingPeriod.findFirst({ where: { id: periodId, tenantId } });
    if (!period) throw new BadRequestException('Period not found or tenant mismatch');

    const currentState = period.state as PortfolioPeriodState;

    // Closed periods immutable — cannot be silently rewritten
    if (currentState === PortfolioPeriodState.CLOSED) {
      throw new BadRequestException('Closed periods immutable — cannot transition');
    }

    const allowed = PERIOD_VALID_TRANSITIONS[currentState] ?? [];
    if (!allowed.includes(toState)) {
      throw new BadRequestException(`Invalid period transition ${currentState} → ${toState}`);
    }

    const updated = await (this.prisma as any).portfolioAccountingPeriod.update({
      where: { id: periodId },
      data: {
        state: toState as any,
        ...(toState === PortfolioPeriodState.CLOSED ? { closedAt: new Date() } : {}),
        // closedBy / closingStartedAt / transition evidence have no columns: kept in closeMetadata.
        closeMetadata: redactSecrets({
          ...((period.closeMetadata as any) ?? {}),
          ...(toState === PortfolioPeriodState.CLOSED ? { closedBy: operatorId ?? null } : {}),
          ...(toState === PortfolioPeriodState.CLOSING ? { closingStartedAt: new Date().toISOString() } : {}),
          lastTransition: { from: currentState, to: toState, reason, operatorId, at: new Date().toISOString() },
        }) as any,
      },
    });

    this.logger.log({ event: 'portfolio.period.transition', periodId, from: currentState, to: toState });

    return updated;
  }

  async getPeriod(params: { tenantId: string; periodId: string }): Promise<any | null> {
    return await (this.prisma as any).portfolioAccountingPeriod.findFirst({
      where: { id: params.periodId, tenantId: params.tenantId },
    });
  }

  async listPeriods(params: {
    tenantId: string;
    profileId?: string;
    state?: string;
    from?: Date;
    to?: Date;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId, profileId, state, from, to, page = 1, limit = 50 } = params;
    const where: any = { tenantId };
    if (profileId) where.profileId = profileId;
    if (state) where.state = state;
    if (from || to) {
      where.periodStart = {};
      if (from) where.periodStart.gte = from;
      if (to) where.periodStart.lte = to;
    }

    const [data, total] = await Promise.all([
      (this.prisma as any).portfolioAccountingPeriod.findMany({
        where,
        orderBy: { periodStart: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).portfolioAccountingPeriod.count({ where }),
    ]);
    return { data, total, page, limit };
  }

  async isPeriodClosed(params: { tenantId: string; profileId: string; at: Date }): Promise<boolean> {
    const period = await (this.prisma as any).portfolioAccountingPeriod.findFirst({
      where: {
        tenantId: params.tenantId,
        profileId: params.profileId,
        periodStart: { lte: params.at },
        periodEnd: { gte: params.at },
        state: 'CLOSED',
      },
    });
    return !!period;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AppConfigService } from '../../config/app-config.service';
import {
  PortfolioAccountingScope,
  PortfolioType,
  PortfolioReturnMethodology,
  CALCULATION_VERSION,
  POLICY_VERSION_DEFAULT,
} from './portfolio-accounting.types';

/**
 * Resolves accounting policies for tenant, trader, strategy, follower, and managed-account scopes,
 * including base currency, valuation frequency, return methodology, fee treatment, period boundaries,
 * close rules, rounding rules, and supported asset handling. Must reuse existing configuration/policy
 * sources where available.
 */

export interface AccountingPolicy {
  baseCurrency: string;
  valuationCurrency: string;
  valuationFrequency: string;
  returnMethodology: PortfolioReturnMethodology;
  costBasisMethod: string;
  feeTreatment: string;
  periodBoundary: string;
  roundingMode: string;
  roundingScale: number;
  supportedAssets: string[];
  closeRules: {
    requireReconciliation: boolean;
    requireValuation: boolean;
    requireFeeReconciliation: boolean;
    requireCashReconciliation: boolean;
    requirePositionReconciliation: boolean;
    allowIncompleteValuation: boolean;
  };
  policyVersion: string;
  calculationVersion: string;
}

@Injectable()
export class AccountingPolicyService {
  private readonly logger = new Logger(AccountingPolicyService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly config: AppConfigService,
  ) {}

  async resolvePolicy(params: {
    tenantId: string;
    scope: PortfolioAccountingScope;
    scopeId: string;
  }): Promise<AccountingPolicy> {
    const { tenantId, scope, scopeId } = params;

    // Reuse existing configuration/policy sources where available — check TenantSetting, TenantFeatureFlag, etc.
    let baseCurrency = 'USD';
    let supportedAssets: string[] = ['BTC', 'ETH', 'USDT', 'USDC', 'BNB', 'SOL'];

    try {
      const tenant = await this.prisma.tenant.findUnique({ where: { id: tenantId }, select: { defaultCurrency: true, supportedCurrencies: true } });
      if (tenant?.defaultCurrency) baseCurrency = tenant.defaultCurrency;
      if (tenant?.supportedCurrencies && tenant.supportedCurrencies.length > 0) {
        // supportedCurrencies are fiat, but we also support crypto — merge
        supportedAssets = [...new Set([...supportedAssets, ...tenant.supportedCurrencies])];
      }
    } catch {}

    // Check for existing accounting profile — if exists, use its policy
    try {
      const profile = await (this.prisma as any).portfolioAccountingProfile.findFirst({
        where: { tenantId, scope: scope as any, scopeId },
        orderBy: { createdAt: 'desc' },
      });
      if (profile) {
        return {
          baseCurrency: profile.baseCurrency,
          valuationCurrency: profile.valuationCurrency ?? profile.baseCurrency,
          valuationFrequency: profile.valuationFrequency,
          returnMethodology: profile.returnMethodology as PortfolioReturnMethodology,
          costBasisMethod: profile.costBasisMethod,
          feeTreatment: profile.feeTreatment,
          periodBoundary: profile.periodBoundary,
          roundingMode: profile.roundingMode,
          roundingScale: profile.roundingScale,
          supportedAssets,
          closeRules: {
            requireReconciliation: true,
            requireValuation: true,
            requireFeeReconciliation: true,
            requireCashReconciliation: true,
            requirePositionReconciliation: true,
            allowIncompleteValuation: false,
          },
          policyVersion: profile.policyVersion,
          calculationVersion: profile.calculationVersion,
        };
      }
    } catch {}

    // Default policy — explicit, auditable, not invented thresholds from nowhere
    const policy: AccountingPolicy = {
      baseCurrency,
      valuationCurrency: baseCurrency,
      valuationFrequency: 'DAILY',
      returnMethodology: PortfolioReturnMethodology.TIME_WEIGHTED_RETURN,
      costBasisMethod: 'FIFO',
      feeTreatment: 'NET',
      periodBoundary: 'UTC_MIDNIGHT',
      roundingMode: 'HALF_UP',
      roundingScale: 8,
      supportedAssets,
      closeRules: {
        requireReconciliation: true,
        requireValuation: true,
        requireFeeReconciliation: true,
        requireCashReconciliation: true,
        requirePositionReconciliation: true,
        allowIncompleteValuation: false,
      },
      policyVersion: POLICY_VERSION_DEFAULT,
      calculationVersion: CALCULATION_VERSION,
    };

    this.logger.debug({
      event: 'portfolio.policy.resolved',
      tenantId,
      scope,
      scopeId,
      baseCurrency,
      policyVersion: policy.policyVersion,
    });

    return policy;
  }

  async createOrUpdateProfile(params: {
    tenantId: string;
    scope: PortfolioAccountingScope;
    scopeId: string;
    portfolioType?: PortfolioType;
    baseCurrency?: string;
    returnMethodology?: PortfolioReturnMethodology;
    costBasisMethod?: string;
  }): Promise<any> {
    const policy = await this.resolvePolicy({ tenantId: params.tenantId, scope: params.scope, scopeId: params.scopeId });

    const baseCurrency = params.baseCurrency ?? policy.baseCurrency;
    const returnMethodology = params.returnMethodology ?? policy.returnMethodology;
    const costBasisMethod = params.costBasisMethod ?? policy.costBasisMethod;
    const portfolioType = params.portfolioType ?? PortfolioType.SPOT;

    try {
      const existing = await (this.prisma as any).portfolioAccountingProfile.findFirst({
        where: { tenantId: params.tenantId, scope: params.scope as any, scopeId: params.scopeId },
      });
      if (existing) {
        return await (this.prisma as any).portfolioAccountingProfile.update({
          where: { id: existing.id },
          data: {
            baseCurrency,
            returnMethodology: returnMethodology as any,
            costBasisMethod,
            portfolioType: portfolioType as any,
            policyVersion: policy.policyVersion,
            calculationVersion: policy.calculationVersion,
          },
        });
      }
      return await (this.prisma as any).portfolioAccountingProfile.create({
        data: {
          tenantId: params.tenantId,
          scope: params.scope as any,
          scopeId: params.scopeId,
          portfolioType: portfolioType as any,
          baseCurrency,
          valuationCurrency: baseCurrency,
          returnMethodology: returnMethodology as any,
          costBasisMethod,
          feeTreatment: policy.feeTreatment,
          valuationFrequency: policy.valuationFrequency,
          periodBoundary: policy.periodBoundary,
          roundingMode: policy.roundingMode,
          roundingScale: policy.roundingScale,
          policyVersion: policy.policyVersion,
          calculationVersion: policy.calculationVersion,
        },
      });
    } catch (e) {
      this.logger.warn(`Failed to create accounting profile: ${(e as Error).message}`);
      throw e;
    }
  }

  getCalculationVersion(): string {
    return CALCULATION_VERSION;
  }

  getPolicyVersion(): string {
    return POLICY_VERSION_DEFAULT;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AccountingPolicyService } from './accounting-policy.service';
import { add, sub, cmp, isValidDecimal, deterministicIdempotencyKey, redactSecrets } from './portfolio-accounting.types';

/** One-line summary for the required `summary` column, e.g. "2 discrepancies (1 critical): DUPLICATE_EVENT, MISSING_FX". */
export function summarizeDiscrepancies(discrepancies: Array<{ type: string; severity: string }>): string {
  if (discrepancies.length === 0) return 'No discrepancies';
  const critical = discrepancies.filter((d) => d.severity === 'CRITICAL').length;
  const types = Array.from(new Set(discrepancies.map((d) => d.type))).join(', ');
  const summary = `${discrepancies.length} discrepanc${discrepancies.length === 1 ? 'y' : 'ies'} (${critical} critical): ${types}`;
  return summary.length > 1000 ? `${summary.slice(0, 997)}...` : summary;
}

/** API view of a PortfolioAccountingReconciliation row: keeps scope/trigger/discrepancies/hasCriticalFailure/requestedBy. */
export function toReconciliationView(row: any): any {
  if (!row) return row;
  const detail = row.discrepancy && typeof row.discrepancy === 'object' ? row.discrepancy : {};
  return {
    ...row,
    scope: row.reconciliationType,
    trigger: detail.trigger ?? row.sourceType ?? null,
    discrepancies: Array.isArray(detail.items) ? detail.items : [],
    hasCriticalFailure: Boolean(row.isCritical),
    requestedBy: detail.requestedBy ?? null,
  };
}

/**
 * Reconciles against OMS fills, positions, balances, fees, finance ledger, copy allocations.
 * Detects missing events, double counting, quantity drift, cash drift, valuation inconsistencies,
 * period discrepancies without silently rewriting.
 */

@Injectable()
export class AccountingReconciliationService {
  private readonly logger = new Logger(AccountingReconciliationService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: AccountingPolicyService,
  ) {}

  async reconcilePeriod(params: {
    tenantId: string;
    profileId: string;
    periodStart: Date;
    periodEnd: Date;
  }): Promise<{ hasCriticalFailure: boolean; discrepancies: Array<{ type: string; severity: string; details: any }> }> {
    const discrepancies: Array<{ type: string; severity: string; details: any }> = [];

    // Check for duplicate events (same sourceId counted twice)
    try {
      const events = await (this.prisma as any).portfolioAccountingEvent.findMany({
        where: {
          tenantId: params.tenantId,
          profileId: params.profileId,
          sourceTimestamp: { gte: params.periodStart, lte: params.periodEnd },
          isReversed: false,
        },
      });

      const sourceMap = new Map<string, number>();
      for (const ev of events) {
        const key = `${ev.sourceType}:${ev.sourceId}`;
        sourceMap.set(key, (sourceMap.get(key) ?? 0) + 1);
      }
      for (const [key, count] of sourceMap.entries()) {
        if (count > 1) {
          discrepancies.push({ type: 'DUPLICATE_EVENT', severity: 'CRITICAL', details: { sourceKey: key, count } });
        }
      }

      // Check against OMS fills — missing events
      try {
        // OMS fills live in OmsFill (the OMS fill ledger).
        const omsFills = await this.prisma.omsFill.findMany({
          where: {
            tenantId: params.tenantId,
            createdAt: { gte: params.periodStart, lte: params.periodEnd },
          },
          select: { id: true, providerFillId: true },
        });
        if (omsFills) {
          for (const fill of omsFills) {
            const exists = events.some((e: any) => e.sourceType === 'OMS_FILL' && e.sourceId === (fill.providerFillId ?? fill.id));
            if (!exists) {
              discrepancies.push({ type: 'MISSING_EVENT', severity: 'WARNING', details: { sourceType: 'OMS_FILL', sourceId: fill.providerFillId ?? fill.id } });
            }
          }
        }
      } catch {}

      // Cash drift vs exchange balance — compare accounting cash vs exchange balance if available
      try {
        const cashEntries = await (this.prisma as any).portfolioCashLedgerEntry.findMany({
          where: { tenantId: params.tenantId, profileId: params.profileId, occurredAt: { gte: params.periodStart, lte: params.periodEnd } },
        });

        let accountingCash = '0';
        for (const entry of cashEntries) {
          const isOutflow = ['WITHDRAWAL', 'TRANSFER_OUT', 'FEE', 'PLATFORM_FEE', 'PERFORMANCE_FEE', 'TRADE_SETTLEMENT_BUY'].includes(entry.cashFlowType);
          const amt = entry.baseCurrencyAmount ?? entry.amount;
          if (!isValidDecimal(amt)) continue;
          accountingCash = isOutflow ? sub(accountingCash, amt) : add(accountingCash, amt);
        }

        // If exchange balance available, compare
        // For now, just check if cash entries have missing FX
        const missingFxEntries = cashEntries.filter((e: any) => e.conversionStatus === 'MISSING_FX');
        if (missingFxEntries.length > 0) {
          discrepancies.push({ type: 'MISSING_FX', severity: 'WARNING', details: { count: missingFxEntries.length, entries: missingFxEntries.map((e: any) => e.id) } });
        }
      } catch {}

      // Position mismatch — compare accounting lots vs OMS positions
      try {
        const lots = await (this.prisma as any).portfolioPositionLot.findMany({
          where: { tenantId: params.tenantId, profileId: params.profileId, isClosed: false },
        });

        const holdingsMap = new Map<string, string>();
        for (const lot of lots) {
          const existing = holdingsMap.get(lot.symbol) ?? '0';
          holdingsMap.set(lot.symbol, add(existing, lot.remainingQuantity));
        }

        // Try to get authoritative positions from existing position service
        const authoritativePositions = await (this.prisma as any).position?.findMany?.({
          where: { tenantId: params.tenantId },
        });

        if (authoritativePositions) {
          for (const pos of authoritativePositions) {
            const accountingQty = holdingsMap.get(pos.symbol) ?? '0';
            const authQty = pos.quantity?.toString() ?? '0';
            if (isValidDecimal(accountingQty) && isValidDecimal(authQty)) {
              const drift = sub(accountingQty, authQty);
              if (cmp(drift, '0') !== 0) {
                discrepancies.push({
                  type: 'POSITION_MISMATCH',
                  severity: cmp(this.absSafe(drift), '0.0001') > 0 ? 'WARNING' : 'INFO',
                  details: { symbol: pos.symbol, accountingQty, authoritativeQty: authQty, drift },
                });
              }
            }
          }
        }
      } catch {}

      // Fee mismatch — compare fee accruals vs cash ledger fees
      try {
        const feeAccruals = await (this.prisma as any).feeAccrual?.findMany?.({
          where: { tenantId: params.tenantId, createdAt: { gte: params.periodStart, lte: params.periodEnd } },
        });
        const feeCashEntries = await (this.prisma as any).portfolioCashLedgerEntry.findMany({
          where: {
            tenantId: params.tenantId,
            profileId: params.profileId,
            cashFlowType: { in: ['FEE', 'PLATFORM_FEE', 'PERFORMANCE_FEE'] },
            occurredAt: { gte: params.periodStart, lte: params.periodEnd },
          },
        });

        if (feeAccruals && feeAccruals.length !== feeCashEntries.length) {
          discrepancies.push({
            type: 'FEE_MISMATCH',
            severity: 'WARNING',
            details: { feeAccrualsCount: feeAccruals.length, cashFeeEntriesCount: feeCashEntries.length },
          });
        }
      } catch {}

      // Valuation staleness
      try {
        const valuations = await (this.prisma as any).portfolioValuation.findMany({
          where: {
            tenantId: params.tenantId,
            profileId: params.profileId,
            valuationTimestamp: { gte: params.periodStart, lte: params.periodEnd },
          },
        });

        const stale = valuations.filter((v: any) => v.valuationState === 'STALE');
        const missing = valuations.filter((v: any) => v.valuationState === 'MISSING_PRICE' || v.valuationState === 'MISSING_FX');

        if (stale.length > 0) {
          discrepancies.push({ type: 'VALUATION_STALENESS', severity: 'WARNING', details: { count: stale.length } });
        }
        if (missing.length > 0) {
          discrepancies.push({ type: 'MISSING_PRICE', severity: 'WARNING', details: { count: missing.length } });
        }
      } catch {}

      // Closed-period mutation check — if period is CLOSED, ensure no new events after close
      try {
        const closedPeriod = await (this.prisma as any).portfolioAccountingPeriod.findFirst({
          where: { tenantId: params.tenantId, profileId: params.profileId, periodStart: params.periodStart, periodEnd: params.periodEnd, state: 'CLOSED' },
        });
        if (closedPeriod && closedPeriod.closedAt) {
          const eventsAfterClose = await (this.prisma as any).portfolioAccountingEvent.count({
            where: {
              tenantId: params.tenantId,
              profileId: params.profileId,
              sourceTimestamp: { gte: params.periodStart, lte: params.periodEnd },
              createdAt: { gt: closedPeriod.closedAt },
              isReversed: false,
            },
          });
          if (eventsAfterClose > 0) {
            discrepancies.push({ type: 'CLOSED_PERIOD_MUTATION', severity: 'CRITICAL', details: { eventsAfterClose, closedAt: closedPeriod.closedAt } });
          }
        }
      } catch {}
    } catch (e) {
      this.logger.warn(`Reconciliation failed: ${(e as Error).message}`);
      discrepancies.push({ type: 'RECONCILIATION_FAILED', severity: 'WARNING', details: { error: (e as Error).message } });
    }

    const hasCriticalFailure = discrepancies.some((d) => d.severity === 'CRITICAL');

    return { hasCriticalFailure, discrepancies };
  }

  async runReconciliation(params: {
    tenantId: string;
    profileId: string;
    scope: string;
    periodId?: string | null;
    trigger?: string;
    requestedBy?: string | null;
  }): Promise<any> {
    const { tenantId, profileId, scope, periodId = null, trigger = 'MANUAL', requestedBy = null } = params;

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });

    let periodStart = new Date(Date.now() - 24 * 60 * 60 * 1000);
    let periodEnd = new Date();

    if (periodId) {
      try {
        const period = await (this.prisma as any).portfolioAccountingPeriod.findFirst({ where: { id: periodId, tenantId } });
        if (period) {
          periodStart = period.periodStart;
          periodEnd = period.periodEnd;
        }
      } catch {}
    }

    const result = await this.reconcilePeriod({ tenantId, profileId, periodStart, periodEnd });

    const idempotencyKey = deterministicIdempotencyKey({
      type: `reconciliation:${scope}:${periodStart.toISOString()}:${periodEnd.toISOString()}`,
      tenantId,
      profileId,
      sourceId: periodId ?? `${periodStart.toISOString()}_${periodEnd.toISOString()}`,
    });

    try {
      const existing = await (this.prisma as any).portfolioAccountingReconciliation.findFirst({ where: { tenantId, idempotencyKey } });
      if (existing) return toReconciliationView(existing);
    } catch {}

    const recon = await (this.prisma as any).portfolioAccountingReconciliation.create({
      data: {
        tenantId,
        profileId,
        periodId: periodId ?? null,
        // Model columns: reconciliationType (= scope), summary, severity, isCritical;
        // the discrepancy list, trigger, requester and evidence go into the discrepancy Json.
        reconciliationType: String(scope).slice(0, 64),
        state: result.hasCriticalFailure ? 'MISMATCH' : result.discrepancies.length > 0 ? 'MISMATCH' : 'MATCHED',
        summary: summarizeDiscrepancies(result.discrepancies),
        severity: result.hasCriticalFailure ? 'CRITICAL' : result.discrepancies.length > 0 ? 'WARNING' : 'NONE',
        isCritical: result.hasCriticalFailure,
        sourceType: trigger ? String(trigger).slice(0, 64) : null,
        discrepancy: redactSecrets({
          items: result.discrepancies,
          trigger,
          requestedBy: requestedBy ?? null,
          periodStart: periodStart.toISOString(),
          periodEnd: periodEnd.toISOString(),
        }) as any,
        calculationVersion: policy.calculationVersion,
        policyVersion: policy.policyVersion,
        idempotencyKey,
      },
    });

    return toReconciliationView(recon);
  }

  async listReconciliations(params: {
    tenantId: string;
    profileId?: string;
    periodId?: string;
    state?: string;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId, profileId, periodId, state, page = 1, limit = 50 } = params;
    const where: any = { tenantId };
    if (profileId) where.profileId = profileId;
    if (periodId) where.periodId = periodId;
    if (state) where.state = state;

    const [data, total] = await Promise.all([
      (this.prisma as any).portfolioAccountingReconciliation.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).portfolioAccountingReconciliation.count({ where }),
    ]);
    return { data: data.map(toReconciliationView), total, page, limit };
  }

  private absSafe(val: string): string {
    return val.startsWith('-') ? val.slice(1) : val;
  }
}

// # Responsibility: derive deterministic portfolio attribution from ledger-backed PnL components.
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AccountingPolicyService } from './accounting-policy.service';
import {
  PortfolioAttributionDimension,
  deterministicIdempotencyKey,
  add,
  sub,
  cmp,
  div,
  mul,
  redactSecrets,
  isValidDecimal,
} from './portfolio-accounting.types';

/** API view of a PortfolioAttributionRecord row: dimensionValue/pnl/percentage from dimensionId/pnlContribution/evidence. */
export function toAttributionRecordView(row: any): any {
  if (!row) return row;
  const evidence = row.evidence && typeof row.evidence === 'object' ? row.evidence : {};
  return { ...row, dimensionValue: row.dimensionId, pnl: row.pnlContribution, percentage: evidence.percentage ?? null };
}

/**
 * Produces deterministic attribution by strategy, trader, follower, symbol, asset, venue,
 * copy allocation, and fee, explaining total PnL without becoming a second PnL source.
 * Must detect and report unattributed, double-attributed, missing allocation, quantity mismatch,
 * and fee mismatch conditions.
 */

@Injectable()
export class AttributionService {
  private readonly logger = new Logger(AttributionService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: AccountingPolicyService,
  ) {}

  async calculateAttribution(params: {
    tenantId: string;
    profileId: string;
    periodStart: Date;
    periodEnd: Date;
    dimension: PortfolioAttributionDimension;
    totalPnl: string;
    baseCurrency?: string;
  }): Promise<{
    attributions: Array<{ dimensionValue: string; pnl: string; percentage: string }>;
    totalAttributed: string;
    unattributed: string;
    discrepancy: string;
    hasDiscrepancy: boolean;
    evidence: any;
  }> {
    const { tenantId, profileId, periodStart, periodEnd, dimension, totalPnl } = params;

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });
    const baseCurrency = params.baseCurrency ?? policy.baseCurrency;

    // Fetch accounting events for period and attribute
    let events: any[] = [];
    try {
      events = await (this.prisma as any).portfolioAccountingEvent.findMany({
        where: {
          tenantId,
          profileId,
          sourceTimestamp: { gte: periodStart, lte: periodEnd },
          isReversed: false,
        },
        orderBy: { sourceTimestamp: 'asc' },
      });
    } catch {
      events = [];
    }

    const attributionMap = new Map<string, string>();

    for (const event of events) {
      let dimensionValue: string | null = null;

      switch (dimension) {
        case PortfolioAttributionDimension.SYMBOL:
          dimensionValue = event.asset ?? 'UNKNOWN';
          break;
        case PortfolioAttributionDimension.ASSET:
          dimensionValue = event.asset ?? 'UNKNOWN';
          break;
        case PortfolioAttributionDimension.STRATEGY:
          dimensionValue = (event.metadata as any)?.strategyId ?? (event.metadata as any)?.strategy ?? 'UNKNOWN';
          break;
        case PortfolioAttributionDimension.TRADER:
          dimensionValue = (event.metadata as any)?.traderId ?? 'UNKNOWN';
          break;
        case PortfolioAttributionDimension.FOLLOWER:
          dimensionValue = (event.metadata as any)?.followerId ?? 'UNKNOWN';
          break;
        case PortfolioAttributionDimension.VENUE:
          dimensionValue = (event.metadata as any)?.venue ?? 'UNKNOWN';
          break;
        case PortfolioAttributionDimension.COPY_ALLOCATION:
          dimensionValue = event.copyAllocationId ?? 'UNKNOWN';
          break;
        case PortfolioAttributionDimension.FEE:
          dimensionValue = event.cashFlowType ?? 'UNKNOWN';
          break;
        default:
          dimensionValue = 'UNKNOWN';
      }

      if (!dimensionValue) dimensionValue = 'UNKNOWN';

      // For attribution, we need PnL per event — from metadata or calculate
      // Simplified: use amount as proxy for attribution, real would use realized PnL per event
      const eventPnl = event.amount ?? '0';
      if (!isValidDecimal(eventPnl)) continue;

      const existing = attributionMap.get(dimensionValue) ?? '0';
      attributionMap.set(dimensionValue, add(existing, eventPnl));
    }

    // Also fetch cash ledger fees for fee attribution
    if (dimension === PortfolioAttributionDimension.FEE) {
      try {
        const feeEntries = await (this.prisma as any).portfolioCashLedgerEntry.findMany({
          where: {
            tenantId,
            profileId,
            cashFlowType: { in: ['FEE', 'PLATFORM_FEE', 'PERFORMANCE_FEE'] },
            occurredAt: { gte: periodStart, lte: periodEnd },
          },
        });
        for (const fee of feeEntries) {
          const feeValue = fee.baseCurrencyAmount ?? fee.amount;
          const existing = attributionMap.get(fee.cashFlowType) ?? '0';
          attributionMap.set(fee.cashFlowType, add(existing, `-${feeValue}`)); // fees negative attribution
        }
      } catch {}
    }

    let totalAttributed = '0';
    const attributions: Array<{ dimensionValue: string; pnl: string; percentage: string }> = [];

    for (const [dimValue, pnl] of attributionMap.entries()) {
      totalAttributed = add(totalAttributed, pnl);
    }

    // Calculate percentages and detect discrepancies
    for (const [dimValue, pnl] of attributionMap.entries()) {
      let percentage = '0';
      try {
        if (cmp(totalPnl, '0') !== 0) {
          percentage = mul(div(pnl, totalPnl), '100');
        }
      } catch {
        percentage = '0';
      }
      attributions.push({ dimensionValue: dimValue, pnl, percentage });
    }

    const unattributed = sub(totalPnl, totalAttributed);
    const discrepancy = unattributed; // difference between total and sum of attributions
    const hasDiscrepancy = cmp(this.absSafe(unattributed), '0.0001') !== 0; // rounding tolerance 0.0001

    // Detect double-attributed, missing allocation, quantity mismatch, fee mismatch
    const diagnostics: string[] = [];
    if (hasDiscrepancy) {
      diagnostics.push(`ATTRIBUTION_DISCREPANCY: total=${totalPnl} attributed=${totalAttributed} unattributed=${unattributed}`);
    }
    if (attributionMap.has('UNKNOWN') && cmp(attributionMap.get('UNKNOWN') ?? '0', '0') !== 0) {
      diagnostics.push(`UNATTRIBUTED: ${attributionMap.get('UNKNOWN')} assigned to UNKNOWN dimension`);
    }

    // Check for duplicate source counting — if same sourceId appears multiple times
    const sourceIds = events.map((e: any) => e.sourceId);
    const duplicateSources = sourceIds.filter((id: string, idx: number) => sourceIds.indexOf(id) !== idx);
    if (duplicateSources.length > 0) {
      diagnostics.push(`DUPLICATE_SOURCE_DETECTED: ${[...new Set(duplicateSources)].join(',')}`);
    }

    const evidence = {
      dimension,
      periodStart: periodStart.toISOString(),
      periodEnd: periodEnd.toISOString(),
      totalPnl,
      totalAttributed,
      unattributed,
      discrepancy,
      hasDiscrepancy,
      diagnostics,
      baseCurrency,
      calculationVersion: policy.calculationVersion,
      policyVersion: policy.policyVersion,
      methodology: `ATTRIBUTION_BY_${dimension}`,
      dataCompleteness: hasDiscrepancy ? 'DISCREPANCY_DETECTED' : 'COMPLETE',
      sourceReferences: [...new Set(events.map((e: any) => `${e.sourceType}:${e.sourceId}`))],
    };

    return { attributions, totalAttributed, unattributed, discrepancy, hasDiscrepancy, evidence };
  }

  async persistAttribution(params: {
    tenantId: string;
    profileId: string;
    periodId?: string | null;
    dimension: PortfolioAttributionDimension;
    dimensionValue: string;
    pnl: string;
    percentage: string;
    periodStart: Date;
    periodEnd: Date;
    baseCurrency: string;
    calculationVersion: string;
    policyVersion: string;
    evidence: any;
  }): Promise<any> {
    const idempotencyKey = deterministicIdempotencyKey({
      type: `attribution:${params.dimension}:${params.dimensionValue}:${params.periodStart.toISOString()}:${params.periodEnd.toISOString()}`,
      tenantId: params.tenantId,
      profileId: params.profileId,
      sourceId: params.periodId ?? `${params.dimension}:${params.dimensionValue}`,
    });

    try {
      const existing = await (this.prisma as any).portfolioAttributionRecord.findFirst({ where: { tenantId: params.tenantId, idempotencyKey } });
      if (existing) return toAttributionRecordView(existing);
    } catch {}

    try {
      // Columns: dimensionId (the dimension value) and pnlContribution; the percentage is kept in evidence.
      const created = await (this.prisma as any).portfolioAttributionRecord.create({
        data: {
          tenantId: params.tenantId,
          profileId: params.profileId,
          periodId: params.periodId ?? null,
          dimension: params.dimension as any,
          dimensionId: params.dimensionValue,
          pnlContribution: params.pnl,
          periodStart: params.periodStart,
          periodEnd: params.periodEnd,
          baseCurrency: params.baseCurrency,
          calculationVersion: params.calculationVersion,
          policyVersion: params.policyVersion,
          evidence: redactSecrets({ ...(params.evidence ?? {}), percentage: params.percentage }) as any,
          idempotencyKey,
        },
      });
      return toAttributionRecordView(created);
    } catch (e) {
      this.logger.warn(`Failed to persist attribution: ${(e as Error).message}`);
      return null;
    }
  }

  private absSafe(val: string): string {
    return val.startsWith('-') ? val.slice(1) : val;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AccountingPolicyService } from './accounting-policy.service';
import { sub, mul, div } from './portfolio-accounting.types';

/**
 * Manages benchmark definitions and observations using verified market/index data, never fabricated.
 * Calculates alpha vs benchmark.
 */

@Injectable()
export class BenchmarkService {
  private readonly logger = new Logger(BenchmarkService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: AccountingPolicyService,
  ) {}

  async defineBenchmark(params: {
    tenantId: string;
    profileId: string;
    benchmarkId: string;
    name: string;
    description?: string | null;
    source: string;
    baseCurrency: string;
  }): Promise<any> {
    // Benchmark definition stored in evidence/metadata — for now return definition
    // In full implementation, would have Benchmark model, but we reuse existing structure
    const policy = await this.policyService.resolvePolicy({ tenantId: params.tenantId, scope: 'TENANT' as any, scopeId: params.profileId });
    return {
      benchmarkId: params.benchmarkId,
      name: params.name,
      description: params.description ?? null,
      source: params.source,
      baseCurrency: params.baseCurrency ?? policy.baseCurrency,
      calculationVersion: policy.calculationVersion,
      policyVersion: policy.policyVersion,
    };
  }

  /** Candle intervals in order of preference for a benchmark series. */
  private static readonly SERIES_INTERVALS: readonly string[] = ['1d', '4h', '1h', '15m', '5m', '1m'];

  /**
   * One venue/interval series out of mixed candle rows. Interleaving a 1m and
   * a 1d series (or two venues) would fabricate returns between unrelated
   * closes, so exactly one series is kept: the most preferred interval, and
   * within it the venue with the most observations. Input order is kept.
   */
  static pickSeries<T extends { venue: string; interval: string }>(rows: readonly T[]): T[] {
    if (rows.length === 0) {
      return [];
    }
    const groups = new Map<string, T[]>();
    for (const row of rows) {
      const key = `${row.venue}|${row.interval}`;
      const group = groups.get(key);
      if (group === undefined) {
        groups.set(key, [row]);
      } else {
        group.push(row);
      }
    }
    const rank = (interval: string): number => {
      const i = BenchmarkService.SERIES_INTERVALS.indexOf(interval);
      return i === -1 ? BenchmarkService.SERIES_INTERVALS.length : i;
    };
    let best: T[] | null = null;
    for (const group of groups.values()) {
      if (best === null) {
        best = group;
        continue;
      }
      const g = rank((group[0] as T).interval);
      const b = rank((best[0] as T).interval);
      if (g < b || (g === b && group.length > best.length)) {
        best = group;
      }
    }
    return best ?? [];
  }

  async getBenchmarkObservations(params: {
    tenantId: string;
    benchmarkId: string;
    from: Date;
    to: Date;
  }): Promise<Array<{ timestamp: Date; value: string; source: string }>> {
    // Must use verified market/index data: MarketDataRecord candles, keyed by
    // symbol (benchmarkId is a symbol such as BTCUSDT). No such data -> [].
    const rows = await this.prisma.marketDataRecord.findMany({
      where: { symbol: params.benchmarkId, closeTime: { gte: params.from, lte: params.to } },
      orderBy: { closeTime: 'asc' },
      select: { close: true, closeTime: true, venue: true, interval: true },
    });

    const series = BenchmarkService.pickSeries(rows);
    if (series.length > 0) {
      return series.map((p) => ({
        timestamp: p.closeTime,
        value: p.close.toString(),
        source: `MARKET_DATA:${p.venue}:${p.interval}`,
      }));
    }

    // No benchmark data — explicit, not fabricated
    return [];
  }

  async calculateBenchmarkReturn(params: {
    tenantId: string;
    profileId: string;
    benchmarkId: string;
    periodStart: Date;
    periodEnd: Date;
    baseCurrency?: string;
  }): Promise<{ returnPercent: string | null; evidence: any; canCalculate: boolean }> {
    const observations = await this.getBenchmarkObservations({
      tenantId: params.tenantId,
      benchmarkId: params.benchmarkId,
      from: params.periodStart,
      to: params.periodEnd,
    });

    const policy = await this.policyService.resolvePolicy({ tenantId: params.tenantId, scope: 'TENANT' as any, scopeId: params.profileId });

    if (observations.length < 2) {
      return {
        returnPercent: null,
        canCalculate: false,
        evidence: {
          benchmarkId: params.benchmarkId,
          periodStart: params.periodStart.toISOString(),
          periodEnd: params.periodEnd.toISOString(),
          observationsCount: observations.length,
          returnPercent: null,
          calculationVersion: policy.calculationVersion,
          policyVersion: policy.policyVersion,
          dataCompleteness: 'MISSING_BENCHMARK_OBSERVATIONS',
          sourceReferences: [],
        },
      };
    }

    const startValue = observations[0].value;
    const endValue = observations[observations.length - 1].value;

    try {
      const ratio = div(endValue, startValue);
      const ret = mul(sub(ratio, '1'), '100');
      return {
        returnPercent: ret,
        canCalculate: true,
        evidence: {
          benchmarkId: params.benchmarkId,
          periodStart: params.periodStart.toISOString(),
          periodEnd: params.periodEnd.toISOString(),
          startValue,
          endValue,
          observationsCount: observations.length,
          returnPercent: ret,
          calculationVersion: policy.calculationVersion,
          policyVersion: policy.policyVersion,
          dataCompleteness: 'COMPLETE',
          sourceReferences: [...new Set(observations.map((o) => o.source))],
        },
      };
    } catch {
      return {
        returnPercent: null,
        canCalculate: false,
        evidence: {
          benchmarkId: params.benchmarkId,
          periodStart: params.periodStart.toISOString(),
          periodEnd: params.periodEnd.toISOString(),
          observationsCount: observations.length,
          returnPercent: null,
          calculationVersion: policy.calculationVersion,
          policyVersion: policy.policyVersion,
          dataCompleteness: 'CALCULATION_FAILED',
          sourceReferences: [],
        },
      };
    }
  }

  async calculateAlpha(params: {
    tenantId: string;
    profileId: string;
    portfolioReturn: string | null;
    benchmarkReturn: string | null;
    benchmarkId: string;
  }): Promise<{ alpha: string | null; evidence: any }> {
    if (params.portfolioReturn === null || params.benchmarkReturn === null) {
      return { alpha: null, evidence: { benchmarkId: params.benchmarkId, portfolioReturn: params.portfolioReturn, benchmarkReturn: params.benchmarkReturn, alpha: null, dataCompleteness: 'MISSING_OBSERVATIONS' } };
    }

    try {
      const alpha = sub(params.portfolioReturn, params.benchmarkReturn);
      return {
        alpha,
        evidence: {
          benchmarkId: params.benchmarkId,
          portfolioReturn: params.portfolioReturn,
          benchmarkReturn: params.benchmarkReturn,
          alpha,
          dataCompleteness: 'COMPLETE',
        },
      };
    } catch {
      return { alpha: null, evidence: { benchmarkId: params.benchmarkId, alpha: null, dataCompleteness: 'CALCULATION_FAILED' } };
    }
  }
}

// # Responsibility: maintain portfolio cash accounting from authoritative financial events.
import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AccountingEventRepository } from './accounting-event.repository';
import { AccountingPolicyService } from './accounting-policy.service';
import { PortfolioCashFlowType, deterministicIdempotencyKey, add, sub, mul, isValidDecimal } from './portfolio-accounting.types';

/**
 * Maintains portfolio-level accounting cash movements derived from authoritative deposits,
 * withdrawals, transfers, trading settlement, fees, and other supported financial events.
 * Must never become an independent exchange-balance truth.
 */

@Injectable()
export class CashLedgerService {
  private readonly logger = new Logger(CashLedgerService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventRepo: AccountingEventRepository,
    private readonly policyService: AccountingPolicyService,
  ) {}

  async recordCashMovement(params: {
    tenantId: string;
    profileId: string;
    accountingEventId?: string | null;
    cashFlowType: PortfolioCashFlowType;
    asset: string;
    amount: string;
    currency: string;
    occurredAt: Date;
    sourceType?: string | null;
    sourceId?: string | null;
    correlationId?: string | null;
    baseCurrency?: string | null;
    conversionRate?: string | null;
    conversionSource?: string | null;
    conversionStatus?: string | null;
  }): Promise<any> {
    const { tenantId, profileId, accountingEventId = null, cashFlowType, asset, amount, currency, occurredAt, sourceType = null, sourceId = null, correlationId = null } = params;

    if (!isValidDecimal(amount)) throw new BadRequestException(`Invalid amount decimal: ${amount}`);

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });

    const idempotencyKey = deterministicIdempotencyKey({
      type: `cash:${cashFlowType}`,
      tenantId,
      profileId,
      sourceId: sourceId ?? accountingEventId ?? `${cashFlowType}:${asset}:${amount}:${occurredAt.toISOString()}`,
      timestampBucket: occurredAt.toISOString().slice(0, 10),
    });

    // Idempotency mandatory
    try {
      const existing = await (this.prisma as any).portfolioCashLedgerEntry.findFirst({ where: { tenantId, idempotencyKey } });
      if (existing) return existing;
    } catch {}

    // Calculate running balance — deterministic from prior entries, Decimal-safe
    let runningBalance = amount;
    try {
      const lastEntry = await (this.prisma as any).portfolioCashLedgerEntry.findFirst({
        where: { tenantId, profileId, asset },
        orderBy: { occurredAt: 'desc' },
      });
      if (lastEntry && lastEntry.runningBalance) {
        // Running balance = previous + current (for deposits/buys) or - for withdrawals/sells/fees
        const isOutflow = [PortfolioCashFlowType.WITHDRAWAL, PortfolioCashFlowType.TRANSFER_OUT, PortfolioCashFlowType.FEE, PortfolioCashFlowType.PLATFORM_FEE, PortfolioCashFlowType.PERFORMANCE_FEE, PortfolioCashFlowType.TRADE_SETTLEMENT_BUY].includes(cashFlowType);
        runningBalance = isOutflow ? sub(lastEntry.runningBalance, amount) : add(lastEntry.runningBalance, amount);
      }
    } catch {}

    const baseCurrency = params.baseCurrency ?? policy.baseCurrency;
    let baseCurrencyAmount: string | null = null;
    if (params.conversionRate && baseCurrency !== currency) {
      try {
        baseCurrencyAmount = mul(amount, params.conversionRate);
      } catch {
        baseCurrencyAmount = null;
      }
    } else if (baseCurrency === currency) {
      baseCurrencyAmount = amount;
    }

    const created = await (this.prisma as any).portfolioCashLedgerEntry.create({
      data: {
        tenantId,
        profileId,
        accountingEventId: accountingEventId ?? null,
        cashFlowType: cashFlowType as any,
        asset,
        amount,
        currency,
        runningBalance,
        baseCurrency,
        baseCurrencyAmount,
        conversionRate: params.conversionRate ?? null,
        conversionSource: params.conversionSource ?? null,
        conversionTimestamp: new Date(),
        conversionStatus: params.conversionStatus ?? (baseCurrency === currency ? 'SAME_CURRENCY' : params.conversionRate ? 'CONVERTED' : 'MISSING_FX'),
        sourceType: sourceType ?? null,
        sourceId: sourceId ?? null,
        idempotencyKey,
        calculationVersion: policy.calculationVersion,
        policyVersion: policy.policyVersion,
        correlationId: correlationId ?? null,
        occurredAt,
      },
    });

    this.logger.log({ event: 'portfolio.cash.recorded', tenantId, profileId, cashFlowType, asset, amount });

    return created;
  }

  async getCashBalance(params: {
    tenantId: string;
    profileId: string;
    asset?: string;
    currency?: string;
    at?: Date;
  }): Promise<{ asset: string; balance: string; currency: string; baseCurrency: string; baseCurrencyBalance: string | null }> {
    const { tenantId, profileId, asset, at = new Date() } = params;

    try {
      const where: any = { tenantId, profileId, occurredAt: { lte: at } };
      if (asset) where.asset = asset;

      const entries = await (this.prisma as any).portfolioCashLedgerEntry.findMany({
        where,
        orderBy: { occurredAt: 'asc' },
      });

      // Deterministic sum using Decimal-safe arithmetic
      let balance = '0';
      let baseBalance: string | null = null;
      let currency = asset ?? 'USD';
      let baseCurrency = 'USD';

      for (const entry of entries) {
        if (asset && entry.asset !== asset) continue;
        currency = entry.currency;
        baseCurrency = entry.baseCurrency;
        const isOutflow = [PortfolioCashFlowType.WITHDRAWAL, PortfolioCashFlowType.TRANSFER_OUT, PortfolioCashFlowType.FEE, PortfolioCashFlowType.PLATFORM_FEE, PortfolioCashFlowType.PERFORMANCE_FEE, PortfolioCashFlowType.TRADE_SETTLEMENT_BUY].includes(entry.cashFlowType as any);
        balance = isOutflow ? sub(balance, entry.amount) : add(balance, entry.amount);
        if (entry.baseCurrencyAmount) {
          if (baseBalance === null) baseBalance = '0';
          baseBalance = isOutflow ? sub(baseBalance, entry.baseCurrencyAmount) : add(baseBalance, entry.baseCurrencyAmount);
        }
      }

      return { asset: asset ?? 'CASH', balance, currency, baseCurrency, baseCurrencyBalance: baseBalance };
    } catch (e) {
      this.logger.warn(`Failed to get cash balance: ${(e as Error).message}`);
      return { asset: asset ?? 'CASH', balance: '0', currency: 'USD', baseCurrency: 'USD', baseCurrencyBalance: null };
    }
  }

  async listCashEntries(params: {
    tenantId: string;
    profileId: string;
    asset?: string;
    cashFlowType?: string;
    from?: Date;
    to?: Date;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId, profileId, asset, cashFlowType, from, to, page = 1, limit = 50 } = params;
    const where: any = { tenantId, profileId };
    if (asset) where.asset = asset;
    if (cashFlowType) where.cashFlowType = cashFlowType;
    if (from || to) {
      where.occurredAt = {};
      if (from) where.occurredAt.gte = from;
      if (to) where.occurredAt.lte = to;
    }

    const [data, total] = await Promise.all([
      (this.prisma as any).portfolioCashLedgerEntry.findMany({
        where,
        orderBy: { occurredAt: 'asc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).portfolioCashLedgerEntry.count({ where }),
    ]);
    return { data, total, page, limit };
  }

  async reconcileAgainstExchangeBalance(params: {
    tenantId: string;
    profileId: string;
    exchangeBalance: string;
    asset: string;
  }): Promise<{ matched: boolean; accountingBalance: string; exchangeBalance: string; drift: string }> {
    // Never become independent exchange-balance truth — we compare, not overwrite
    const accounting = await this.getCashBalance({ tenantId: params.tenantId, profileId: params.profileId, asset: params.asset });
    const drift = sub(accounting.balance, params.exchangeBalance);
    const matched = drift === '0';
    return {
      matched,
      accountingBalance: accounting.balance,
      exchangeBalance: params.exchangeBalance,
      drift,
    };
  }
}

// # Responsibility: calculate deterministic lot cost basis and realized gain or loss.
import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AccountingEventRepository } from './accounting-event.repository';
import { AccountingPolicyService } from './accounting-policy.service';
import { add, sub, mul, div, cmp, isValidDecimal, redactSecrets } from './portfolio-accounting.types';

/**
 * Calculates deterministic cost basis for every accounting lot and fill, preserving lot
 * references, acquisition values, disposals, realized gain/loss, and methodology/version
 * metadata. Must never silently switch methods.
 */

@Injectable()
export class CostBasisService {
  private readonly logger = new Logger(CostBasisService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventRepo: AccountingEventRepository,
    private readonly policyService: AccountingPolicyService,
  ) {}

  async calculateCostBasisForFill(params: {
    tenantId: string;
    profileId: string;
    fill: any;
    symbol: string;
    quantity: string;
    price: string;
    side: string;
    occurredAt: Date;
    accountingEventId: string;
  }): Promise<{ costBasisPerUnit: string; totalCostBasis: string; realizedPnl: string; method: string }> {
    const { tenantId, profileId, fill, symbol, quantity, price, side, occurredAt, accountingEventId } = params;

    if (!isValidDecimal(quantity) || !isValidDecimal(price)) throw new BadRequestException('Invalid quantity/price');

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });

    // FIFO deterministic — check open lots
    const openLots = await (this.prisma as any).portfolioPositionLot.findMany({
      where: { tenantId, profileId, symbol, isClosed: false, isReversed: false },
      orderBy: { openedAt: 'asc' },
    });

    if (side === 'BUY') {
      // Opening/increasing long — cost basis is fill price
      const costBasisPerUnit = price;
      const totalCostBasis = mul(quantity, price);
      return {
        costBasisPerUnit,
        totalCostBasis,
        realizedPnl: '0',
        method: policy.costBasisMethod,
      };
    } else {
      // SELL — reduce FIFO lots, realized PnL = proceeds - cost basis
      let remainingQty = quantity;
      let totalCost = '0';
      let realizedPnl = '0';

      for (const lot of openLots) {
        if (cmp(remainingQty, '0') <= 0) break;
        const lotQty = lot.remainingQuantity;
        const closeQty = cmp(remainingQty, lotQty) >= 0 ? lotQty : remainingQty;
        const lotCostPerUnit = lot.costBasisPerUnit ?? '0';
        const lotCost = mul(closeQty, lotCostPerUnit);
        const proceeds = mul(closeQty, price);
        const pnlForLot = sub(proceeds, lotCost);

        totalCost = add(totalCost, lotCost);
        realizedPnl = add(realizedPnl, pnlForLot);
        remainingQty = sub(remainingQty, closeQty);
      }

      // If remainingQty > 0 and no open lots, this is short or insufficient history — mark but don't invent cost basis
      // Realized PnL only for matched quantity
      const matchedQty = sub(quantity, remainingQty);
      const costBasisPerUnit = cmp(matchedQty, '0') > 0 ? this.divSafe(totalCost, matchedQty) : price;

      return {
        costBasisPerUnit,
        totalCostBasis: totalCost,
        realizedPnl,
        method: policy.costBasisMethod,
      };
    }
  }

  async recordCostBasis(params: {
    tenantId: string;
    profileId: string;
    symbol: string;
    lotId?: string | null;
    accountingEventId: string;
    quantity: string;
    costBasisPerUnit: string;
    totalCostBasis: string;
    realizedPnl?: string | null;
    method: string;
    occurredAt: Date;
  }): Promise<any> {
    // Cost basis record is part of position lot — update lot or create evidence record
    // For audit, we store evidence in lot's evidence/metadata
    try {
      if (params.lotId) {
        const lot = await (this.prisma as any).portfolioPositionLot.findUnique({ where: { id: params.lotId } });
        if (lot) {
          return await (this.prisma as any).portfolioPositionLot.update({
            where: { id: params.lotId },
            data: {
              costBasisPerUnit: params.costBasisPerUnit,
              totalCostBasis: params.totalCostBasis,
              evidence: redactSecrets({
                ...((lot.evidence as any) ?? {}),
                costBasisPerUnit: params.costBasisPerUnit,
                totalCostBasis: params.totalCostBasis,
                realizedPnl: params.realizedPnl ?? '0',
                method: params.method,
                calculationVersion: (await this.policyService.resolvePolicy({ tenantId: params.tenantId, scope: 'TENANT' as any, scopeId: params.profileId })).calculationVersion,
              }) as any,
            },
          });
        }
      }
      return { costBasisPerUnit: params.costBasisPerUnit, totalCostBasis: params.totalCostBasis, realizedPnl: params.realizedPnl };
    } catch (e) {
      this.logger.warn(`Failed to record cost basis: ${(e as Error).message}`);
      return { costBasisPerUnit: params.costBasisPerUnit, totalCostBasis: params.totalCostBasis, realizedPnl: params.realizedPnl };
    }
  }

  async getRealizedPnl(params: {
    tenantId: string;
    profileId: string;
    symbol?: string;
    from?: Date;
    to?: Date;
  }): Promise<{ realizedPnl: string; disposals: number }> {
    // Realized PnL from closed lots — deterministic, reproducible
    try {
      const where: any = { tenantId: params.tenantId, profileId: params.profileId, isClosed: true };
      if (params.symbol) where.symbol = params.symbol;
      if (params.from || params.to) {
        where.closedAt = {};
        if (params.from) where.closedAt.gte = params.from;
        if (params.to) where.closedAt.lte = params.to;
      }

      const lots = await (this.prisma as any).portfolioPositionLot.findMany({ where });

      let realizedPnl = '0';
      for (const lot of lots) {
        // Realized PnL stored in evidence or need to compute — for now sum from cost basis
        // We treat closed lots as having realized PnL evidence
        const evidence = lot.evidence as any;
        if (evidence?.realizedPnl && isValidDecimal(evidence.realizedPnl)) {
          realizedPnl = add(realizedPnl, evidence.realizedPnl);
        }
      }

      return { realizedPnl, disposals: lots.length };
    } catch {
      return { realizedPnl: '0', disposals: 0 };
    }
  }

  private divSafe(a: string, b: string): string {
    try {
      return div(a, b);
    } catch {
      return '0';
    }
  }
}

