import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';

/**
 * Resolves what tenant owner, trader, follower, managed-account operator,
 * compliance reviewer, platform admin may view based on existing IAM/RBAC/account ownership.
 */

export enum InvestorVisibilityRole {
  TENANT_OWNER = 'TENANT_OWNER',
  TRADER = 'TRADER',
  FOLLOWER = 'FOLLOWER',
  MANAGED_ACCOUNT_OPERATOR = 'MANAGED_ACCOUNT_OPERATOR',
  COMPLIANCE_REVIEWER = 'COMPLIANCE_REVIEWER',
  PLATFORM_ADMIN = 'PLATFORM_ADMIN',
}

@Injectable()
export class InvestorVisibilityService {
  private readonly logger = new Logger(InvestorVisibilityService.name);

  constructor(private readonly prisma: PrismaService) {}

  async resolveVisibleProfiles(params: {
    tenantId: string;
    userId: string;
    role: InvestorVisibilityRole;
    isPlatformUser?: boolean;
  }): Promise<Array<{ profileId: string; scope: string; scopeId: string }>> {
    const { tenantId, userId, role, isPlatformUser = false } = params;

    // Platform admin can view all profiles in tenant (with audit)
    if (isPlatformUser && role === InvestorVisibilityRole.PLATFORM_ADMIN) {
      const profiles = await (this.prisma as any).portfolioAccountingProfile.findMany({ where: { tenantId } });
      return profiles.map((p: any) => ({ profileId: p.id, scope: p.scope, scopeId: p.scopeId }));
    }

    // Compliance reviewer can view all profiles in tenant for compliance purposes
    if (role === InvestorVisibilityRole.COMPLIANCE_REVIEWER) {
      const profiles = await (this.prisma as any).portfolioAccountingProfile.findMany({ where: { tenantId } });
      return profiles.map((p: any) => ({ profileId: p.id, scope: p.scope, scopeId: p.scopeId }));
    }

    // Tenant owner can view all profiles in tenant
    if (role === InvestorVisibilityRole.TENANT_OWNER) {
      const profiles = await (this.prisma as any).portfolioAccountingProfile.findMany({ where: { tenantId } });
      return profiles.map((p: any) => ({ profileId: p.id, scope: p.scope, scopeId: p.scopeId }));
    }

    // Trader can view own trader-scoped profiles and strategy profiles they own
    if (role === InvestorVisibilityRole.TRADER) {
      const profiles = await (this.prisma as any).portfolioAccountingProfile.findMany({
        where: { tenantId, scopeId: userId, scope: { in: ['TRADER', 'STRATEGY'] } },
      });
      return profiles.map((p: any) => ({ profileId: p.id, scope: p.scope, scopeId: p.scopeId }));
    }

    // Follower can view own follower-scoped profiles
    if (role === InvestorVisibilityRole.FOLLOWER) {
      const profiles = await (this.prisma as any).portfolioAccountingProfile.findMany({
        where: { tenantId, scopeId: userId, scope: 'FOLLOWER' },
      });
      return profiles.map((p: any) => ({ profileId: p.id, scope: p.scope, scopeId: p.scopeId }));
    }

    // Managed account operator can view managed account profiles they operate
    if (role === InvestorVisibilityRole.MANAGED_ACCOUNT_OPERATOR) {
      // The accounts an operator runs are ACTIVE OPERATOR_TO_ACCOUNT
      // relationships (client-lifecycle): source = operator, target = account.
      const relationships = await this.prisma.accountRelationship.findMany({
        where: { tenantId, sourceId: userId, relationshipType: 'OPERATOR_TO_ACCOUNT', status: 'ACTIVE', endedAt: null },
        select: { targetId: true },
      });
      const accountIds = relationships.map((r) => r.targetId);
      if (accountIds.length === 0) {
        return [];
      }
      const profiles = await (this.prisma as any).portfolioAccountingProfile.findMany({
        where: { tenantId, scope: 'MANAGED_ACCOUNT', scopeId: { in: accountIds } },
      });
      return profiles.map((p: any) => ({ profileId: p.id, scope: p.scope, scopeId: p.scopeId }));
    }

    return [];
  }

  async canViewProfile(params: {
    tenantId: string;
    userId: string;
    profileId: string;
    role: InvestorVisibilityRole;
    isPlatformUser?: boolean;
  }): Promise<boolean> {
    const visible = await this.resolveVisibleProfiles({
      tenantId: params.tenantId,
      userId: params.userId,
      role: params.role,
      isPlatformUser: params.isPlatformUser,
    });
    return visible.some((v) => v.profileId === params.profileId);
  }

  async canViewStatement(params: {
    tenantId: string;
    userId: string;
    statementId: string;
    role: InvestorVisibilityRole;
    isPlatformUser?: boolean;
  }): Promise<boolean> {
    const statement = await (this.prisma as any).portfolioStatement.findFirst({
      where: { tenantId: params.tenantId, statementId: params.statementId },
    });
    if (!statement) return false;

    return await this.canViewProfile({
      tenantId: params.tenantId,
      userId: params.userId,
      profileId: statement.profileId,
      role: params.role,
      isPlatformUser: params.isPlatformUser,
    });
  }

  async enforceVisibility(params: {
    tenantId: string;
    userId: string;
    profileId: string;
    role: InvestorVisibilityRole;
    isPlatformUser?: boolean;
  }): Promise<void> {
    const canView = await this.canViewProfile(params);
    if (!canView) {
      throw new Error(`Access denied: user ${params.userId} cannot view profile ${params.profileId} as ${params.role}`);
    }
  }
}

/**
 * Portfolio accounting reads the platform's real data sources.
 *
 * Prices and benchmarks come from MarketDataRecord candles, OMS fills from
 * OmsFill, and an operator's accounts from ACTIVE OPERATOR_TO_ACCOUNT
 * relationships. The services used to read delegates that do not exist
 * (`priceSnapshot`, `fillConfirmation`, a managed-account lookup) behind `?.`,
 * so every valuation was MISSING_PRICE, every benchmark empty, missing fills
 * were never detected and operators saw no profiles.
 */
import { AccountingReconciliationService } from './accounting-reconciliation.service';
import { BenchmarkService } from './benchmark.service';
import { InvestorVisibilityRole, InvestorVisibilityService } from './investor-visibility.service';
import { PortfolioValuationState } from './portfolio-accounting.types';
import { ValuationService } from './valuation.service';

const TENANT = '11111111-1111-1111-1111-111111111111';
const POLICY = {
  resolvePolicy: jest.fn(async () => ({
    baseCurrency: 'USD',
    calculationVersion: 'c1',
    policyVersion: 'p1',
  })),
};

const candle = (closeTime: string, close: string, venue = 'binance', interval = '1m') => ({
  closeTime: new Date(closeTime),
  close: { toString: () => close },
  venue,
  interval,
});

describe('ValuationService.getVerifiedMarketPrice', () => {
  function build(findFirst: jest.Mock) {
    return new ValuationService({ marketDataRecord: { findFirst } } as any, POLICY as any);
  }
  const at = new Date('2026-09-20T12:00:00Z');

  it('prices from the latest candle closed by the valuation instant (no look-ahead)', async () => {
    const findFirst = jest.fn(async () => candle('2026-09-20T11:59:00Z', '64123.5'));
    const result = await build(findFirst).getVerifiedMarketPrice({
      tenantId: TENANT,
      symbol: 'BTCUSDT',
      asset: 'BTC',
      at,
    });
    expect(findFirst).toHaveBeenCalledWith({
      where: { symbol: 'BTCUSDT', closeTime: { lte: at } },
      orderBy: { closeTime: 'desc' },
      select: { close: true, closeTime: true, venue: true, interval: true },
    });
    expect(result).toEqual({
      price: '64123.5',
      source: 'MARKET_DATA:binance:1m',
      timestamp: new Date('2026-09-20T11:59:00Z'),
      state: PortfolioValuationState.VALID,
    });
  });

  it('measures staleness against the valuation instant, not the wall clock', async () => {
    const fresh = await build(
      jest.fn(async () => candle('2026-09-20T11:56:00Z', '1')),
    ).getVerifiedMarketPrice({ tenantId: TENANT, symbol: 'X', asset: 'X', at });
    const stale = await build(
      jest.fn(async () => candle('2026-09-20T11:50:00Z', '1')),
    ).getVerifiedMarketPrice({ tenantId: TENANT, symbol: 'X', asset: 'X', at });
    expect(fresh.state).toBe(PortfolioValuationState.VALID);
    expect(stale.state).toBe(PortfolioValuationState.STALE);
  });

  it('reports MISSING_PRICE instead of inventing one', async () => {
    const result = await build(jest.fn(async () => null)).getVerifiedMarketPrice({
      tenantId: TENANT,
      symbol: 'X',
      asset: 'X',
      at,
    });
    expect(result).toEqual({
      price: null,
      source: null,
      timestamp: null,
      state: PortfolioValuationState.MISSING_PRICE,
    });
  });

  it('reports UNAVAILABLE when the price source errors', async () => {
    const findFirst = jest.fn(async () => {
      throw new Error('db down');
    });
    const result = await build(findFirst).getVerifiedMarketPrice({
      tenantId: TENANT,
      symbol: 'X',
      asset: 'X',
      at,
    });
    expect(result.state).toBe(PortfolioValuationState.UNAVAILABLE);
  });
});

describe('BenchmarkService.pickSeries', () => {
  it('returns [] for no rows', () => {
    expect(BenchmarkService.pickSeries([])).toEqual([]);
  });

  it('keeps the most preferred interval rather than interleaving series', () => {
    const rows = [
      candle('2026-09-01T00:00:00Z', '1', 'binance', '1m'),
      candle('2026-09-01T00:00:00Z', '2', 'binance', '1d'),
      candle('2026-09-02T00:00:00Z', '3', 'binance', '1d'),
    ];
    const series = BenchmarkService.pickSeries(rows);
    expect(series.map((r) => r.interval)).toEqual(['1d', '1d']);
  });

  it('within one interval keeps the venue with the most observations', () => {
    const rows = [
      candle('2026-09-01T00:00:00Z', '1', 'okx', '1h'),
      candle('2026-09-01T00:00:00Z', '1', 'binance', '1h'),
      candle('2026-09-01T01:00:00Z', '2', 'binance', '1h'),
