import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { CashLedgerService } from './cash-ledger.service';
import { PositionAccountingService } from './position-accounting.service';
import { ValuationService } from './valuation.service';
import { AccountingPolicyService } from './accounting-policy.service';
import { add, sub, redactSecrets, isValidDecimal } from './portfolio-accounting.types';
import { isAdjustmentReversed } from './accounting-adjustment.service';

/**
 * Calculates NAV from cash + valued positions + adjustments, currency-safe, evidence.
 * Missing FX → explicit incomplete state never invent rate/NAV.
 * Must be deterministic and preserve calculationVersion/policyVersion/baseCurrency/valuationTimestamp/sourceReferences/methodology/dataCompleteness.
 */

@Injectable()
export class NavService {
  private readonly logger = new Logger(NavService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly cashLedger: CashLedgerService,
    private readonly positionAccounting: PositionAccountingService,
    private readonly valuationService: ValuationService,
    private readonly policyService: AccountingPolicyService,
  ) {}

  async calculateNav(params: {
    tenantId: string;
    profileId: string;
    at: Date;
    baseCurrency?: string;
    correlationId?: string | null;
  }): Promise<{
    nav: string | null;
    cash: string;
    grossAssetValue: string;
    grossLiability: string;
    adjustments: string;
    baseCurrency: string;
    valuationTimestamp: string;
    calculationVersion: string;
    policyVersion: string;
    sourceReferences: string[];
    methodology: string;
    dataCompleteness: string;
    evidences: any[];
    canPublish: boolean;
  }> {
    const { tenantId, profileId, at } = params;

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });
    const baseCurrency = params.baseCurrency ?? policy.baseCurrency;

    // Cash — from cash ledger, not exchange balance truth overwrite
    const cashEntries = await this.cashLedger.listCashEntries({ tenantId, profileId, page: 1, limit: 1000 });
    let cashBase = '0';
    for (const entry of cashEntries.data) {
      if (entry.occurredAt > at) continue;
      if (entry.baseCurrencyAmount) {
        const isOutflow = ['WITHDRAWAL', 'TRANSFER_OUT', 'FEE', 'PLATFORM_FEE', 'PERFORMANCE_FEE', 'TRADE_SETTLEMENT_BUY'].includes(entry.cashFlowType);
        cashBase = isOutflow ? sub(cashBase, entry.baseCurrencyAmount) : add(cashBase, entry.baseCurrencyAmount);
      } else if (entry.baseCurrency === baseCurrency) {
        const isOutflow = ['WITHDRAWAL', 'TRANSFER_OUT', 'FEE', 'PLATFORM_FEE', 'PERFORMANCE_FEE', 'TRADE_SETTLEMENT_BUY'].includes(entry.cashFlowType);
        cashBase = isOutflow ? sub(cashBase, entry.amount) : add(cashBase, entry.amount);
      }
    }

    // Holdings
    const holdings = await this.positionAccounting.getHoldings({ tenantId, profileId, at });

    // Valuation
    const valuation = await this.valuationService.valuePortfolio({
      tenantId,
      profileId,
      holdings,
      at,
      baseCurrency,
    });

    // NAV = cash + grossAsset - grossLiability + adjustments (adjustments from adjustment service — for now 0)
    let adjustments = '0';
    try {
      // Only manual adjustments (no originalEventId) move NAV directly: event-linked
      // reversals/corrections already act through isReversed and the correction event.
      const adjustmentRecords = await (this.prisma as any).portfolioAccountingAdjustment.findMany({
        where: { tenantId, profileId, createdAt: { lte: at }, originalEventId: null },
      });
      for (const adj of adjustmentRecords) {
        if (isAdjustmentReversed(adj)) continue;
        if (adj.amount && isValidDecimal(adj.amount)) {
          adjustments = add(adjustments, adj.amount);
        }
      }
    } catch {}

    let nav: string | null = null;
    let canPublish = true;
    let dataCompleteness = valuation.completeness;

    // Missing FX → no NAV, explicit incomplete state never invent rate/NAV
    if (valuation.hasMissingFx) {
      nav = null;
      canPublish = false;
      dataCompleteness = 'MISSING_FX_NO_NAV';
    } else if (valuation.hasMissingPrice) {
      // Missing price → NAV incomplete, but we can still calculate with evidence
      // For portfolio accounting, missing price means incomplete NAV — mark accordingly
      // We still compute NAV from available valuations, but completeness is MISSING_PRICE
      try {
        const grossNet = valuation.netValued;
        nav = add(add(cashBase, grossNet), adjustments);
      } catch {
        nav = null;
      }
      dataCompleteness = 'MISSING_PRICE_INCOMPLETE';
    } else {
      try {
        const grossNet = valuation.netValued;
        nav = add(add(cashBase, grossNet), adjustments);
      } catch {
        nav = null;
        canPublish = false;
        dataCompleteness = 'CALCULATION_FAILED';
      }
    }

    const sourceReferences = [
      ...new Set([
        ...valuation.evidences.flatMap((e: any) => e.sourceReferences ?? []),
        ...cashEntries.data.map((c: any) => c.sourceType ?? 'CASH_LEDGER').filter(Boolean),
      ]),
    ];

    return {
      nav,
      cash: cashBase,
      grossAssetValue: valuation.grossAssetValue,
      grossLiability: valuation.grossLiability,
      adjustments,
      baseCurrency,
      valuationTimestamp: at.toISOString(),
      calculationVersion: policy.calculationVersion,
      policyVersion: policy.policyVersion,
      sourceReferences,
      methodology: `CASH_PLUS_VALUED_POSITIONS_${policy.costBasisMethod}`,
      dataCompleteness,
      evidences: valuation.evidences,
      canPublish,
    };
  }

  async persistNavCalculation(params: {
    tenantId: string;
    profileId: string;
    navResult: Awaited<ReturnType<NavService['calculateNav']>>;
    at: Date;
  }): Promise<void> {
    // NAV itself is not a separate model — it's stored in Snapshot and PerformanceRecord and Period
    // For audit, we log
    this.logger.log(
      redactSecrets({
        event: 'portfolio.nav.calculated',
        tenantId: params.tenantId,
        profileId: params.profileId,
        nav: params.navResult.nav,
        baseCurrency: params.navResult.baseCurrency,
        dataCompleteness: params.navResult.dataCompleteness,
        calculationVersion: params.navResult.calculationVersion,
      }),
    );
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import type { PortfolioCashLedgerEntry } from '@prisma/client';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AccountingPolicyService } from './accounting-policy.service';
import { NavService } from './nav.service';
import {
  PortfolioAccountingScope,
  PortfolioReturnMethodology,
  deterministicIdempotencyKey,
  TWR_FLOW_BOUNDARY_RULE,
  add,
  sub,
  mul,
  div,
  cmp,
  isValidDecimal,
  redactSecrets,
} from './portfolio-accounting.types';

/**
 * # Responsibility: calculates source-backed TWR and MWR with exact-decimal flow-boundary handling.
 * Calculates TWR and MWR where sufficient data exists, rejects/marks unavailable when missing observations.
 * Must include periodStart/End starting/ending NAV externalCashFlows fees treatment version completeness.
 */

type ExternalCashFlowType = 'DEPOSIT' | 'WITHDRAWAL' | 'TRANSFER_IN' | 'TRANSFER_OUT';

type TWRCashFlowRow = Pick<
  PortfolioCashLedgerEntry,
  | 'id'
  | 'tenantId'
  | 'profileId'
  | 'idempotencyKey'
  | 'occurredAt'
  | 'cashFlowType'
  | 'amount'
  | 'currency'
  | 'baseCurrency'
  | 'baseCurrencyAmount'
  | 'conversionRate'
  | 'conversionSource'
  | 'conversionTimestamp'
  | 'conversionStatus'
  | 'sourceType'
  | 'sourceId'
>;

interface TWRExternalCashFlowEvidence {
  date: string;
  amount: string | null;
  type: string;
  currency: string;
  baseCurrency: string;
  sourceReference: string | null;
}

interface TWRPerformanceEvidence {
  methodology: PortfolioReturnMethodology.TIME_WEIGHTED_RETURN;
  flowBoundary: typeof TWR_FLOW_BOUNDARY_RULE;
  periodStart: string;
  periodEnd: string;
  startingNav: string | null;
  endingNav: string | null;
  externalCashFlows: TWRExternalCashFlowEvidence[] | null;
  feesTreatment: string;
  returnPercent: string | null;
  calculationVersion: string;
  policyVersion: string;
  dataCompleteness: 'COMPLETE' | 'UNAVAILABLE';
  sourceReferences: string[];
}

interface TWRCalculationResult {
  returnPercent: string | null;
  evidence: TWRPerformanceEvidence;
  canCalculate: boolean;
  reason?: string;
}

interface NormalizedExternalCashFlow {
  row: TWRCashFlowRow;
  amount: string;
  signedAmount: string;
  evidence: TWRExternalCashFlowEvidence;
}

function isExternalCashFlowType(value: string): value is ExternalCashFlowType {
  return value === 'DEPOSIT' || value === 'WITHDRAWAL' || value === 'TRANSFER_IN' || value === 'TRANSFER_OUT';
}

function isCompleteNavObservation(
  observation: Awaited<ReturnType<NavService['calculateNav']>>,
): observation is Awaited<ReturnType<NavService['calculateNav']>> & { nav: string } {
  return (
    typeof observation.nav === 'string' &&
    isValidDecimal(observation.nav) &&
    observation.dataCompleteness === 'COMPLETE' &&
    observation.canPublish === true
  );
}

@Injectable()
export class PerformanceService {
  private readonly logger = new Logger(PerformanceService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: AccountingPolicyService,
    private readonly navService: NavService,
  ) {}

  async calculateTWR(params: {
    tenantId: string;
    profileId: string;
    periodStart: Date;
    periodEnd: Date;
    baseCurrency?: string;
  }): Promise<TWRCalculationResult> {
    const { tenantId, profileId, periodStart, periodEnd } = params;
    if (
      !Number.isFinite(periodStart.getTime()) ||
      !Number.isFinite(periodEnd.getTime()) ||
      periodStart.getTime() >= periodEnd.getTime()
    ) {
      throw new BadRequestException('TWR periodStart and periodEnd must be valid dates in ascending order');
    }

    const policy = await this.policyService.resolvePolicy({
      tenantId,
      scope: PortfolioAccountingScope.TENANT,
      scopeId: profileId,
    });
    const baseCurrency = (params.baseCurrency ?? policy.baseCurrency).trim().toUpperCase();
    if (!baseCurrency) throw new BadRequestException('TWR baseCurrency is required');

    const periodStartIso = periodStart.toISOString();
    const periodEndIso = periodEnd.toISOString();
    const unavailable = (
      reason: string,
      externalCashFlows: TWRExternalCashFlowEvidence[] | null = [],
      startingNav: string | null = null,
      endingNav: string | null = null,
      sourceReferences: string[] = [],
    ): TWRCalculationResult => ({
      returnPercent: null,
      canCalculate: false,
      reason,
      evidence: {
        methodology: PortfolioReturnMethodology.TIME_WEIGHTED_RETURN,
        flowBoundary: TWR_FLOW_BOUNDARY_RULE,
        periodStart: periodStartIso,
        periodEnd: periodEndIso,
        startingNav,
        endingNav,
        externalCashFlows,
        feesTreatment: policy.feeTreatment,
        returnPercent: null,
        calculationVersion: policy.calculationVersion,
        policyVersion: policy.policyVersion,
        dataCompleteness: 'UNAVAILABLE',
        sourceReferences,
      },
    });
    const evidenceForRows = (rows: readonly TWRCashFlowRow[]): TWRExternalCashFlowEvidence[] =>
      rows.map((row) => ({
        date: Number.isFinite(row.occurredAt.getTime()) ? row.occurredAt.toISOString() : 'INVALID_DATE',
        amount: row.baseCurrencyAmount,
        type: String(row.cashFlowType),
        currency: row.currency,
        baseCurrency: row.baseCurrency,
        sourceReference:
          row.sourceType?.trim() && row.sourceId?.trim()
            ? `${row.sourceType}:${row.sourceId}`
            : null,
      }));

    let cashFlows: TWRCashFlowRow[];
    try {
      cashFlows = await this.prisma.portfolioCashLedgerEntry.findMany({
        where: {
          tenantId,
          profileId,
          cashFlowType: {
            in: ['DEPOSIT', 'WITHDRAWAL', 'TRANSFER_IN', 'TRANSFER_OUT'],
          },
          occurredAt: { gte: periodStart, lte: periodEnd },
        },
        orderBy: [{ occurredAt: 'asc' }, { id: 'asc' }],
        take: 101,
        select: {
          id: true,
          tenantId: true,
          profileId: true,
          idempotencyKey: true,
          occurredAt: true,
          cashFlowType: true,
          amount: true,
          currency: true,
          baseCurrency: true,
          baseCurrencyAmount: true,
          conversionRate: true,
          conversionSource: true,
          conversionTimestamp: true,
          conversionStatus: true,
          sourceType: true,
          sourceId: true,
        },
      });
    } catch (error) {
      this.logger.warn(
        `TWR cash-flow source unavailable tenant=${tenantId} profile=${profileId}: ${error instanceof Error ? error.message : 'unknown error'}`,
      );
      return unavailable('CASH_FLOW_SOURCE_UNAVAILABLE', null);
    }

    if (cashFlows.length > 100) {
      return unavailable('CASH_FLOW_LIMIT_EXCEEDED', null);
    }

    const duplicateKeys = new Set<string>();
    const normalizedFlows: NormalizedExternalCashFlow[] = [];
    const rawEvidence = evidenceForRows(cashFlows);
    for (const flow of cashFlows) {
      const flowDate = flow.occurredAt.getTime();
      if (
        flow.tenantId !== tenantId ||
        flow.profileId !== profileId ||
        !flow.id.trim() ||
        !flow.idempotencyKey.trim() ||
        duplicateKeys.has(flow.idempotencyKey) ||
        !Number.isFinite(flowDate) ||
        flowDate < periodStart.getTime() ||
        flowDate > periodEnd.getTime() ||
        !isExternalCashFlowType(flow.cashFlowType) ||
        !isValidDecimal(flow.amount) ||
        cmp(flow.amount, '0') < 0 ||
        !flow.currency.trim() ||
        !flow.baseCurrency.trim() ||
        flow.baseCurrency.trim().toUpperCase() !== baseCurrency
      ) {
        return unavailable('INVALID_EXTERNAL_CASH_FLOW_EVIDENCE', rawEvidence);
      }
      duplicateKeys.add(flow.idempotencyKey);

      if (flow.conversionStatus === 'MISSING_FX' || flow.baseCurrencyAmount === null) {
        return unavailable('MISSING_FX', rawEvidence);
      }
      if (!isValidDecimal(flow.baseCurrencyAmount) || cmp(flow.baseCurrencyAmount, '0') < 0) {
        return unavailable('INVALID_EXTERNAL_CASH_FLOW_EVIDENCE', rawEvidence);
      }

      const currency = flow.currency.trim().toUpperCase();
      if (currency === baseCurrency) {
        if (
          flow.conversionStatus !== 'SAME_CURRENCY' ||
          cmp(flow.baseCurrencyAmount, flow.amount) !== 0
        ) {
          return unavailable('INVALID_EXTERNAL_CASH_FLOW_EVIDENCE', rawEvidence);
        }
      } else if (
        flow.conversionStatus !== 'CONVERTED' ||
        flow.conversionRate === null ||
        !isValidDecimal(flow.conversionRate) ||
        cmp(flow.conversionRate, '0') <= 0 ||
        !flow.conversionSource?.trim() ||
        flow.conversionTimestamp === null ||
        !Number.isFinite(flow.conversionTimestamp.getTime())
      ) {
        return unavailable('MISSING_FX', rawEvidence);
      }

      if (!flow.sourceType?.trim() || !flow.sourceId?.trim()) {
        return unavailable('INVALID_EXTERNAL_CASH_FLOW_EVIDENCE', rawEvidence);
      }

      const isInflow = flow.cashFlowType === 'DEPOSIT' || flow.cashFlowType === 'TRANSFER_IN';
      normalizedFlows.push({
        row: flow,
        amount: flow.baseCurrencyAmount,
        signedAmount: isInflow ? flow.baseCurrencyAmount : sub('0', flow.baseCurrencyAmount),
        evidence: {
          date: flow.occurredAt.toISOString(),
          amount: flow.baseCurrencyAmount,
          type: flow.cashFlowType,
          currency: flow.currency,
          baseCurrency: flow.baseCurrency,
          sourceReference: `${flow.sourceType}:${flow.sourceId}`,
        },
      });
    }

    const externalCashFlows = normalizedFlows.map((flow) => flow.evidence);
    let navStart: Awaited<ReturnType<NavService['calculateNav']>>;
    let navEnd: Awaited<ReturnType<NavService['calculateNav']>>;
    try {
      [navStart, navEnd] = await Promise.all([
        this.navService.calculateNav({ tenantId, profileId, at: periodStart, baseCurrency }),
        this.navService.calculateNav({ tenantId, profileId, at: periodEnd, baseCurrency }),
      ]);
    } catch (error) {
      this.logger.warn(
        `TWR NAV source unavailable tenant=${tenantId} profile=${profileId}: ${error instanceof Error ? error.message : 'unknown error'}`,
      );
      return unavailable('NAV_SOURCE_UNAVAILABLE', externalCashFlows);
    }

    const boundaryReferences = [...new Set([...navStart.sourceReferences, ...navEnd.sourceReferences])];
    if (!isCompleteNavObservation(navStart) || !isCompleteNavObservation(navEnd)) {
      const missingFx =
        navStart.dataCompleteness === 'MISSING_FX_NO_NAV' ||
        navEnd.dataCompleteness === 'MISSING_FX_NO_NAV';
      return unavailable(
        missingFx ? 'MISSING_FX' : 'MISSING_NAV_OBSERVATIONS',
        externalCashFlows,
        navStart.nav,
        navEnd.nav,
        boundaryReferences,
      );
    }

    if (cmp(navStart.nav, '0') <= 0 || cmp(navEnd.nav, '0') < 0) {
      return unavailable(
        'NON_POSITIVE_NAV_BOUNDARY',
        externalCashFlows,
        navStart.nav,
        navEnd.nav,
        boundaryReferences,
      );
    }

    const sourceReferences = new Set<string>([
      ...boundaryReferences,
      ...normalizedFlows.map((flow) => flow.evidence.sourceReference).filter((value): value is string => value !== null),
    ]);
    const startTime = periodStart.getTime();
    const endTime = periodEnd.getTime();
    const groupedFlows = new Map<number, { occurredAt: Date; signedAmount: string }>();
    for (const flow of normalizedFlows) {
      const occurredAt = flow.row.occurredAt;
      const timestamp = occurredAt.getTime();
      if (timestamp <= startTime || timestamp >= endTime) continue;
      const current = groupedFlows.get(timestamp);
      groupedFlows.set(timestamp, {
        occurredAt,
        signedAmount: add(current?.signedAmount ?? '0', flow.signedAmount),
      });
    }

    const orderedFlowGroups = [...groupedFlows.values()].sort(
      (left, right) => left.occurredAt.getTime() - right.occurredAt.getTime(),
    );
    let chainFactor = '1';
    let previousPostFlowNav = navStart.nav;
    try {
      for (const group of orderedFlowGroups) {
        const navAtFlow = await this.navService.calculateNav({
          tenantId,
          profileId,
          at: group.occurredAt,
          baseCurrency,
        });
        if (!isCompleteNavObservation(navAtFlow) || cmp(navAtFlow.nav, '0') < 0) {
          return unavailable(
            'MISSING_SUBPERIOD_NAV',
            externalCashFlows,
            navStart.nav,
            navEnd.nav,
            [...new Set([...sourceReferences, ...navAtFlow.sourceReferences])],
          );
        }
        if (cmp(previousPostFlowNav, '0') <= 0) {
          return unavailable(
            'NON_POSITIVE_SUBPERIOD_NAV',
            externalCashFlows,
            navStart.nav,
            navEnd.nav,
            [...sourceReferences],
          );
        }

        // The NAV observation at an interior timestamp includes all flows at that timestamp.
        // Remove their net contribution to recover the pre-flow close, then chain to the next
        // post-flow NAV. This makes equal-time deposits and withdrawals one boundary event.
        const preFlowNav = sub(navAtFlow.nav, group.signedAmount);
        if (!isValidDecimal(preFlowNav) || cmp(preFlowNav, '0') < 0) {
          return unavailable(
            'INVALID_SUBPERIOD_NAV',
            externalCashFlows,
            navStart.nav,
            navEnd.nav,
            [...new Set([...sourceReferences, ...navAtFlow.sourceReferences])],
          );
        }
        chainFactor = mul(chainFactor, div(preFlowNav, previousPostFlowNav));
        previousPostFlowNav = navAtFlow.nav;
        for (const reference of navAtFlow.sourceReferences) sourceReferences.add(reference);
      }

      // Start flows are already included in the opening NAV. End flows are removed from the
      // closing NAV so a period-end withdrawal cannot inflate the return (and a deposit cannot
      // depress it).
      const netEndFlow = normalizedFlows
        .filter((flow) => flow.row.occurredAt.getTime() === endTime)
        .reduce((total, flow) => add(total, flow.signedAmount), '0');
      const closingNav = sub(navEnd.nav, netEndFlow);
      if (!isValidDecimal(closingNav) || cmp(closingNav, '0') < 0 || cmp(previousPostFlowNav, '0') <= 0) {
        return unavailable(
          'INVALID_CLOSING_NAV',
          externalCashFlows,
          navStart.nav,
          closingNav,
          [...new Set([...sourceReferences, ...navEnd.sourceReferences])],
        );
      }

      chainFactor = mul(chainFactor, div(closingNav, previousPostFlowNav));
      const returnPercent = mul(sub(chainFactor, '1'), '100');
      return {
        returnPercent,
        canCalculate: true,
        evidence: {
          methodology: PortfolioReturnMethodology.TIME_WEIGHTED_RETURN,
          flowBoundary: TWR_FLOW_BOUNDARY_RULE,
          periodStart: periodStartIso,
          periodEnd: periodEndIso,
          startingNav: navStart.nav,
          endingNav: closingNav,
          externalCashFlows,
          feesTreatment: policy.feeTreatment,
          returnPercent,
          calculationVersion: policy.calculationVersion,
          policyVersion: policy.policyVersion,
          dataCompleteness: 'COMPLETE',
          sourceReferences: [...sourceReferences],
        },
      };
    } catch (error) {
      this.logger.warn(
        `TWR exact-decimal calculation failed tenant=${tenantId} profile=${profileId}: ${error instanceof Error ? error.message : 'unknown error'}`,
      );
      return unavailable(
        'CALCULATION_FAILED',
        externalCashFlows,
        navStart.nav,
        navEnd.nav,
        [...new Set([...sourceReferences, ...navEnd.sourceReferences])],
      );
    }
  }

  async calculateMWR(params: {
    tenantId: string;
    profileId: string;
    periodStart: Date;
    periodEnd: Date;
    baseCurrency?: string;
  }): Promise<{ returnPercent: string | null; evidence: any; canCalculate: boolean; reason?: string }> {
    const { tenantId, profileId, periodStart, periodEnd } = params;

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });
    const baseCurrency = params.baseCurrency ?? policy.baseCurrency;

    const navStart = await this.navService.calculateNav({ tenantId, profileId, at: periodStart, baseCurrency });
    const navEnd = await this.navService.calculateNav({ tenantId, profileId, at: periodEnd, baseCurrency });

    if (!navStart.nav || !navEnd.nav) {
      return {
        returnPercent: null,
        canCalculate: false,
        reason: 'MISSING_NAV_OBSERVATIONS',
        evidence: {
          methodology: PortfolioReturnMethodology.MONEY_WEIGHTED_RETURN,
          periodStart: periodStart.toISOString(),
          periodEnd: periodEnd.toISOString(),
          startingNav: navStart.nav,
          endingNav: navEnd.nav,
          externalCashFlows: [],
          feesTreatment: policy.feeTreatment,
          returnPercent: null,
          calculationVersion: policy.calculationVersion,
          policyVersion: policy.policyVersion,
          dataCompleteness: 'MISSING_NAV_OBSERVATIONS',
          sourceReferences: [],
        },
      };
    }

    // MWR (IRR) requires cash flows and NAV observations — simplified: use Newton-Raphson or mark unavailable if insufficient data
    let cashFlows: any[] = [];
    try {
      cashFlows = await (this.prisma as any).portfolioCashLedgerEntry.findMany({
        where: {
          tenantId,
          profileId,
          cashFlowType: { in: ['DEPOSIT', 'WITHDRAWAL', 'TRANSFER_IN', 'TRANSFER_OUT'] },
          occurredAt: { gte: periodStart, lte: periodEnd },
        },
        orderBy: { occurredAt: 'asc' },
      });
    } catch {
      cashFlows = [];
    }

    // If no cash flows, MWR = TWR
    if (cashFlows.length === 0) {
      try {
        const ratio = div(navEnd.nav, navStart.nav);
        const mwr = mul(sub(ratio, '1'), '100');
        return {
          returnPercent: mwr,
          canCalculate: true,
          evidence: {
            methodology: PortfolioReturnMethodology.MONEY_WEIGHTED_RETURN,
            periodStart: periodStart.toISOString(),
            periodEnd: periodEnd.toISOString(),
            startingNav: navStart.nav,
            endingNav: navEnd.nav,
            externalCashFlows: [],
            feesTreatment: policy.feeTreatment,
            returnPercent: mwr,
            calculationVersion: policy.calculationVersion,
            policyVersion: policy.policyVersion,
            dataCompleteness: 'COMPLETE',
            sourceReferences: [...navStart.sourceReferences, ...navEnd.sourceReferences],
          },
        };
      } catch {
        return {
          returnPercent: null,
          canCalculate: false,
          reason: 'CALCULATION_FAILED',
          evidence: {
            methodology: PortfolioReturnMethodology.MONEY_WEIGHTED_RETURN,
            periodStart: periodStart.toISOString(),
            periodEnd: periodEnd.toISOString(),
            startingNav: navStart.nav,
            endingNav: navEnd.nav,
            externalCashFlows: [],
            feesTreatment: policy.feeTreatment,
            returnPercent: null,
            calculationVersion: policy.calculationVersion,
            policyVersion: policy.policyVersion,
            dataCompleteness: 'CALCULATION_FAILED',
            sourceReferences: [],
          },
        };
      }
    }

    // For MWR with cash flows, we need IRR calculation — simplified: mark as requires more observations if insufficient
    // Full IRR implementation would use iterative solver — for now, if we have observations, compute approximate
    // Using simple formula: MWR = (endingNav - startingNav - netCashFlows) / (startingNav + weightedCashFlows)
    try {
      let netCashFlows = '0';
      let weightedCashFlows = '0';
      const totalDays = (periodEnd.getTime() - periodStart.getTime()) / (1000 * 60 * 60 * 24) || 1;

      for (const cf of cashFlows) {
        const amt = cf.baseCurrencyAmount ?? cf.amount;
        const isInflow = ['DEPOSIT', 'TRANSFER_IN'].includes(cf.cashFlowType);
        netCashFlows = isInflow ? add(netCashFlows, amt) : sub(netCashFlows, amt);
        const daysRemaining = (periodEnd.getTime() - cf.occurredAt.getTime()) / (1000 * 60 * 60 * 24);
        const weight = (daysRemaining / totalDays).toString();
        const weighted = mul(amt, weight);
        weightedCashFlows = isInflow ? add(weightedCashFlows, weighted) : sub(weightedCashFlows, weighted);
      }

      const gain = sub(sub(navEnd.nav, navStart.nav), netCashFlows);
      const denominator = add(navStart.nav, weightedCashFlows);
      if (cmp(denominator, '0') === 0) {
        return {
          returnPercent: null,
          canCalculate: false,
          reason: 'ZERO_DENOMINATOR',
          evidence: {
            methodology: PortfolioReturnMethodology.MONEY_WEIGHTED_RETURN,
            periodStart: periodStart.toISOString(),
            periodEnd: periodEnd.toISOString(),
            startingNav: navStart.nav,
            endingNav: navEnd.nav,
            externalCashFlows: cashFlows.map((c: any) => ({ date: c.occurredAt.toISOString(), amount: c.baseCurrencyAmount ?? c.amount, type: c.cashFlowType })),
            feesTreatment: policy.feeTreatment,
            returnPercent: null,
            calculationVersion: policy.calculationVersion,
            policyVersion: policy.policyVersion,
            dataCompleteness: 'ZERO_DENOMINATOR',
            sourceReferences: [...navStart.sourceReferences, ...navEnd.sourceReferences],
          },
        };
      }

      const mwr = mul(div(gain, denominator), '100');
      return {
        returnPercent: mwr,
        canCalculate: true,
        evidence: {
          methodology: PortfolioReturnMethodology.MONEY_WEIGHTED_RETURN,
          periodStart: periodStart.toISOString(),
          periodEnd: periodEnd.toISOString(),
          startingNav: navStart.nav,
          endingNav: navEnd.nav,
          externalCashFlows: cashFlows.map((c: any) => ({ date: c.occurredAt.toISOString(), amount: c.baseCurrencyAmount ?? c.amount, type: c.cashFlowType })),
          feesTreatment: policy.feeTreatment,
          returnPercent: mwr,
          calculationVersion: policy.calculationVersion,
          policyVersion: policy.policyVersion,
          dataCompleteness: 'COMPLETE',
          sourceReferences: [...navStart.sourceReferences, ...navEnd.sourceReferences],
        },
      };
    } catch (e) {
      return {
        returnPercent: null,
        canCalculate: false,
        reason: `CALCULATION_FAILED: ${(e as Error).message}`,
        evidence: {
          methodology: PortfolioReturnMethodology.MONEY_WEIGHTED_RETURN,
          periodStart: periodStart.toISOString(),
          periodEnd: periodEnd.toISOString(),
          startingNav: navStart.nav,
          endingNav: navEnd.nav,
          externalCashFlows: cashFlows.map((c: any) => ({ date: c.occurredAt.toISOString(), amount: c.baseCurrencyAmount ?? c.amount, type: c.cashFlowType })),
          feesTreatment: policy.feeTreatment,
          returnPercent: null,
          calculationVersion: policy.calculationVersion,
          policyVersion: policy.policyVersion,
          dataCompleteness: 'CALCULATION_FAILED',
          sourceReferences: [],
        },
      };
    }
  }

  async persistPerformanceRecord(params: {
    tenantId: string;
    profileId: string;
    periodId?: string | null;
    methodology: PortfolioReturnMethodology;
    periodStart: Date;
    periodEnd: Date;
    startingNav: string | null;
    endingNav: string | null;
    externalCashFlows: any[];
    feesTreatment: string;
    returnPercent: string | null;
    calculationVersion: string;
    policyVersion: string;
    baseCurrency: string;
    dataCompleteness: string;
    sourceReferences: string[];
    evidence: any;
  }): Promise<any> {
    const idempotencyKey = deterministicIdempotencyKey({
      type: `performance:${params.methodology}:${params.periodStart.toISOString()}:${params.periodEnd.toISOString()}`,
      tenantId: params.tenantId,
      profileId: params.profileId,
      sourceId: params.periodId ?? `${params.periodStart.toISOString()}_${params.periodEnd.toISOString()}`,
    });

    try {
      const existing = await (this.prisma as any).portfolioPerformanceRecord.findFirst({ where: { tenantId: params.tenantId, idempotencyKey } });
      if (existing) return existing;
    } catch {}

    try {
      return await (this.prisma as any).portfolioPerformanceRecord.create({
        data: {
          tenantId: params.tenantId,
          profileId: params.profileId,
          periodId: params.periodId ?? null,
          methodology: params.methodology as any,
          periodStart: params.periodStart,
          periodEnd: params.periodEnd,
          startingNav: params.startingNav,
          endingNav: params.endingNav,
          externalCashFlows: params.externalCashFlows as any,
          feesTreatment: params.feesTreatment,
          returnPercent: params.returnPercent,
          calculationVersion: params.calculationVersion,
          policyVersion: params.policyVersion,
          baseCurrency: params.baseCurrency,
          valuationTimestamp: new Date(),
          dataCompleteness: params.dataCompleteness,
          sourceReferences: params.sourceReferences,
          evidence: redactSecrets(params.evidence) as any,
          idempotencyKey,
        },
      });
    } catch (e) {
      this.logger.warn(`Failed to persist performance record: ${(e as Error).message}`);
      return null;
    }
  }
}

import { Prisma } from '@prisma/client';
import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AccountingPeriodService } from './accounting-period.service';
import { NavService } from './nav.service';
import { PnLService } from './pnl.service';
import { PerformanceService } from './performance.service';
import { PortfolioSnapshotService } from './portfolio-snapshot.service';
import { AccountingReconciliationService } from './accounting-reconciliation.service';
import { AccountingPolicyService } from './accounting-policy.service';
import { PortfolioPeriodState, redactSecrets, deterministicIdempotencyKey } from './portfolio-accounting.types';

/**
 * Deterministic close validation, final outputs, verifies reconciliation, persists close metadata,
 * prevents close when critical discrepancies exist. Failure CLOSING→OPEN with evidence.
 */

@Injectable()
export class PeriodCloseService {
  private readonly logger = new Logger(PeriodCloseService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly periodService: AccountingPeriodService,
    private readonly navService: NavService,
    private readonly pnlService: PnLService,
    private readonly performanceService: PerformanceService,
    private readonly snapshotService: PortfolioSnapshotService,
    private readonly reconciliationService: AccountingReconciliationService,
    private readonly policyService: AccountingPolicyService,
  ) {}

  async initiateClose(params: {
    tenantId: string;
    periodId: string;
    operatorId: string;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, periodId, operatorId, correlationId = null } = params;

    const period = await this.periodService.getPeriod({ tenantId, periodId });
    if (!period) throw new BadRequestException('Period not found');

    if (period.state !== PortfolioPeriodState.OPEN) {
      throw new BadRequestException(`Period must be OPEN to initiate close, current: ${period.state}`);
    }

    // Transition to CLOSING
    const closing = await this.periodService.transitionPeriod({
      tenantId,
      periodId,
      toState: PortfolioPeriodState.CLOSING,
      reason: 'Close initiated',
      operatorId,
    });

    // Create close record
    const idempotencyKey = deterministicIdempotencyKey({
      type: `period-close:${periodId}`,
      tenantId,
      profileId: period.profileId,
      sourceId: periodId,
    });

    // A close record for this period already exists (an earlier attempt failed
    // validation and the period went back to OPEN): validate again on that record
    // instead of returning it and leaving the period stuck in CLOSING.
    let existing: any = null;
    try {
      existing = await (this.prisma as any).portfolioAccountingClose.findFirst({ where: { tenantId, idempotencyKey } });
    } catch {}
    if (existing) {
      return await this.validateAndClose({ tenantId, periodId, closeId: existing.id, operatorId, correlationId });
    }

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: period.profileId });

    // PortfolioAccountingClose columns: requestedBy, calculation/policy versions
    // (required), validationEvidence Json. Initiation details live in the evidence.
    const closeRecord = await (this.prisma as any).portfolioAccountingClose.create({
      data: {
        tenantId,
        periodId,
        requestedBy: operatorId,
        validationPassed: false,
        validationEvidence: redactSecrets({
          state: 'CLOSING',
          profileId: period.profileId,
          initiatedBy: operatorId,
          initiatedAt: new Date().toISOString(),
          correlationId: correlationId ?? null,
        }) as any,
        calculationVersion: policy.calculationVersion,
        policyVersion: policy.policyVersion,
        idempotencyKey,
      },
    });

    // Async validation — for now synchronous
    return await this.validateAndClose({ tenantId, periodId, closeId: closeRecord.id, operatorId, correlationId });
  }

  async validateAndClose(params: {
    tenantId: string;
    periodId: string;
    closeId: string;
    operatorId: string;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, periodId, closeId, operatorId } = params;

    const period = await this.periodService.getPeriod({ tenantId, periodId });
    if (!period) throw new BadRequestException('Period not found');

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: period.profileId });

    const validationSteps: Array<{ step: string; passed: boolean; evidence: any }> = [];

    // 1. Required events present
    let eventsCount = 0;
    try {
      eventsCount = await (this.prisma as any).portfolioAccountingEvent.count({
        where: { tenantId, profileId: period.profileId, sourceTimestamp: { gte: period.periodStart, lte: period.periodEnd } },
      });
    } catch {
      eventsCount = 0;
    }
    validationSteps.push({
      step: 'REQUIRED_EVENTS_PRESENT',
      passed: true, // Even 0 events could be valid for empty portfolio — but we log
      evidence: { eventsCount, periodStart: period.periodStart, periodEnd: period.periodEnd },
    });

    // 2. No critical reconciliation failures
    const reconciliation = await this.reconciliationService.reconcilePeriod({
      tenantId,
      profileId: period.profileId,
      periodStart: period.periodStart,
      periodEnd: period.periodEnd,
    });

    const hasCriticalReconciliationFailure = reconciliation.hasCriticalFailure;
    validationSteps.push({
      step: 'RECONCILIATION_NO_CRITICAL',
      passed: !hasCriticalReconciliationFailure,
      evidence: { hasCriticalFailure: hasCriticalReconciliationFailure, discrepancies: reconciliation.discrepancies },
    });

    // 3. Valuation sufficient
    const navResult = await this.navService.calculateNav({ tenantId, profileId: period.profileId, at: period.periodEnd, baseCurrency: period.baseCurrency });
    const valuationSufficient = navResult.nav !== null && navResult.dataCompleteness !== 'MISSING_FX_NO_NAV';
    validationSteps.push({
      step: 'VALUATION_SUFFICIENT',
      passed: policy.closeRules.allowIncompleteValuation ? true : valuationSufficient,
      evidence: { nav: navResult.nav, dataCompleteness: navResult.dataCompleteness, canPublish: navResult.canPublish },
    });

    // 4. NAV consistent — compare with previous snapshot if exists
    let navConsistent = true;
    try {
      const prevSnapshot = await (this.prisma as any).portfolioSnapshot.findFirst({
        where: { tenantId, profileId: period.profileId, timestamp: { lt: period.periodEnd } },
        orderBy: { timestamp: 'desc' },
      });
      if (prevSnapshot && navResult.nav && prevSnapshot.nav) {
        // NAV should be within reasonable bounds — not a full consistency check but detect huge jumps without cash flows
        // For now, always consistent if both exist
        navConsistent = true;
      }
    } catch {
      navConsistent = true;
    }
    validationSteps.push({ step: 'NAV_CONSISTENT', passed: navConsistent, evidence: { nav: navResult.nav } });

    // 5. PnL reproducible
    const pnlResult = await this.pnlService.calculateNetPnl({
      tenantId,
      profileId: period.profileId,
      from: period.periodStart,
      to: period.periodEnd,
      at: period.periodEnd,
      baseCurrency: period.baseCurrency,
    });
    const pnlReproducible = pnlResult.netPnl !== null || pnlResult.grossPnl !== null;
    validationSteps.push({ step: 'PNL_REPRODUCIBLE', passed: pnlReproducible, evidence: { netPnl: pnlResult.netPnl, grossPnl: pnlResult.grossPnl } });

    // 6. Fees/cash/positions reconcile
    const feesReconciled = !reconciliation.discrepancies.some((d: any) => d.type === 'FEE_MISMATCH' && d.severity === 'CRITICAL');
    const cashReconciled = !reconciliation.discrepancies.some((d: any) => d.type === 'CASH_MISMATCH' && d.severity === 'CRITICAL');
    const positionsReconciled = !reconciliation.discrepancies.some((d: any) => d.type === 'POSITION_MISMATCH' && d.severity === 'CRITICAL');

    validationSteps.push({ step: 'FEES_RECONCILED', passed: feesReconciled, evidence: {} });
    validationSteps.push({ step: 'CASH_RECONCILED', passed: cashReconciled, evidence: {} });
    validationSteps.push({ step: 'POSITIONS_RECONCILED', passed: positionsReconciled, evidence: {} });

    const allPassed = validationSteps.every((s) => s.passed);

    if (!allPassed) {
      // Failure CLOSING→OPEN with evidence
      await this.periodService.transitionPeriod({
        tenantId,
        periodId,
        toState: PortfolioPeriodState.OPEN,
        reason: `Close validation failed: ${validationSteps.filter((s) => !s.passed).map((s) => s.step).join(',')}`,
        operatorId,
      });

      await (this.prisma as any).portfolioAccountingClose.update({
        where: { id: closeId },
        data: {
          validationPassed: false,
          reconciliationStatus: hasCriticalReconciliationFailure ? 'CRITICAL_FAILURE' : 'OK',
          failureEvidence: redactSecrets({
            state: 'FAILED',
            failedAt: new Date().toISOString(),
            failureReason: validationSteps.filter((s) => !s.passed).map((s) => s.step).join(','),
            validationSteps,
            reconciliation,
          }) as any,
        },
      });

      throw new BadRequestException(`Period close validation failed: ${validationSteps.filter((s) => !s.passed).map((s) => s.step).join(', ')}`);
    }

    // All passed — create final snapshot
    const finalSnapshot = await this.snapshotService.createSnapshot({
      tenantId,
      profileId: period.profileId,
      timestamp: period.periodEnd,
      baseCurrency: period.baseCurrency,
      scope: 'TENANT',
      scopeId: period.profileId,
    });

    // Persist performance
    const twr = await this.performanceService.calculateTWR({
      tenantId,
      profileId: period.profileId,
      periodStart: period.periodStart,
      periodEnd: period.periodEnd,
      baseCurrency: period.baseCurrency,
    });

    await this.performanceService.persistPerformanceRecord({
      tenantId,
      profileId: period.profileId,
      periodId,
      methodology: 'TIME_WEIGHTED_RETURN' as any,
      periodStart: period.periodStart,
      periodEnd: period.periodEnd,
      startingNav: twr.evidence.startingNav ?? null,
      endingNav: twr.evidence.endingNav ?? null,
      externalCashFlows: twr.evidence.externalCashFlows ?? [],
      feesTreatment: policy.feeTreatment,
      returnPercent: twr.returnPercent,
      calculationVersion: policy.calculationVersion,
      policyVersion: policy.policyVersion,
      baseCurrency: period.baseCurrency,
      dataCompleteness: twr.evidence.dataCompleteness,
      sourceReferences: twr.evidence.sourceReferences ?? [],
      evidence: twr.evidence,
    });

    // Record the closing figures on the period while it is still CLOSING (it is immutable once CLOSED).
    await (this.prisma as any).portfolioAccountingPeriod.update({
      where: { id: periodId },
      data: {
        closingNav: navResult.nav ?? null,
        realizedPnl: pnlResult.evidence?.gross?.realized ?? null,
        unrealizedPnl: pnlResult.evidence?.gross?.unrealized ?? null,
        netPnl: pnlResult.netPnl ?? null,
        returnPercent: twr.returnPercent ?? null,
        validationEvidence: redactSecrets({ validationSteps }) as any,
      },
    });

    // Transition to CLOSED
    await this.periodService.transitionPeriod({
      tenantId,
      periodId,
      toState: PortfolioPeriodState.CLOSED,
      reason: 'Close validation passed',
      operatorId,
    });

    const closed = await (this.prisma as any).portfolioAccountingClose.update({
      where: { id: closeId },
      data: {
        closedBy: operatorId,
        validationPassed: true,
        closingNav: navResult.nav ?? null,
        reconciliationStatus: 'OK',
        failureEvidence: Prisma.DbNull,
        validationEvidence: redactSecrets({
          state: 'CLOSED',
          closedAt: new Date().toISOString(),
          grossAssetValue: navResult.grossAssetValue,
          grossLiability: navResult.grossLiability,
          realizedPnl: pnlResult.evidence?.gross?.realized ?? null,
          unrealizedPnl: pnlResult.evidence?.gross?.unrealized ?? null,
          netPnl: pnlResult.netPnl,
          snapshotId: finalSnapshot.id,
          validationSteps,
          nav: navResult,
          pnl: pnlResult,
          twr: twr.evidence,
          reconciliation,
        }) as any,
      },
    });

    this.logger.log({ event: 'portfolio.period.closed', periodId, nav: navResult.nav });

    return toCloseView(closed);
  }
}

/** API view of a PortfolioAccountingClose row: exposes state/nav/snapshotId kept in validationEvidence. */
export function toCloseView(row: any): any {
  if (!row) return row;
  const evidence = row.validationEvidence && typeof row.validationEvidence === 'object' ? row.validationEvidence : {};
  return {
    ...row,
    state: row.validationPassed ? 'CLOSED' : row.failureEvidence ? 'FAILED' : 'CLOSING',
    nav: row.closingNav ?? null,
    snapshotId: evidence.snapshotId ?? null,
    netPnl: evidence.netPnl ?? null,
    closedAt: evidence.closedAt ?? null,
  };
}

// # Responsibility: calculate realized and unrealized PnL from fills, cost basis, valuation, and fees.
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { CostBasisService } from './cost-basis.service';
import { ValuationService } from './valuation.service';
import { AccountingPolicyService } from './accounting-policy.service';
import { AccountingEventRepository } from './accounting-event.repository';
import { PortfolioPnLType, add, sub, mul, div, isValidDecimal } from './portfolio-accounting.types';

/**
 * Calculates realized, unrealized, gross, fee-adjusted, net PnL using fills,
 * cost basis, valuation, and fee records, not as a second execution PnL truth.
 * Distinguishes REALIZED/UNREALIZED/GROSS/FEE_ADJUSTED/NET with cost-basis/valuation refs,
 * missing/stale price not zero.
 */

@Injectable()
export class PnLService {
  private readonly logger = new Logger(PnLService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly costBasisService: CostBasisService,
    private readonly valuationService: ValuationService,
    private readonly policyService: AccountingPolicyService,
    private readonly eventRepo: AccountingEventRepository,
  ) {}

  async calculateRealizedPnl(params: {
    tenantId: string;
    profileId: string;
    from?: Date;
    to?: Date;
    symbol?: string;
  }): Promise<{ realizedPnl: string; evidence: any }> {
    const { tenantId, profileId, from, to, symbol } = params;

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });

    const result = await this.costBasisService.getRealizedPnl({ tenantId, profileId, symbol, from, to });

    return {
      realizedPnl: result.realizedPnl,
      evidence: {
        type: PortfolioPnLType.REALIZED,
        amount: result.realizedPnl,
        baseCurrency: policy.baseCurrency,
        calculationVersion: policy.calculationVersion,
        policyVersion: policy.policyVersion,
        methodology: `${policy.costBasisMethod}_FIFO_REALIZED`,
        dataCompleteness: 'COMPLETE',
        disposals: result.disposals,
      },
    };
  }

  async calculateUnrealizedPnl(params: {
    tenantId: string;
    profileId: string;
    at: Date;
    baseCurrency?: string;
  }): Promise<{ unrealizedPnl: string | null; evidence: any; hasMissingPrice: boolean; hasStalePrice: boolean }> {
    const { tenantId, profileId, at } = params;

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });
    const baseCurrency = params.baseCurrency ?? policy.baseCurrency;

    // Get open lots
    let openLots: any[] = [];
    try {
      openLots = await (this.prisma as any).portfolioPositionLot.findMany({
        where: { tenantId, profileId, isClosed: false, isReversed: false, openedAt: { lte: at } },
        orderBy: { openedAt: 'asc' },
      });
    } catch {
      openLots = [];
    }

    let unrealizedPnl = '0';
    let hasMissingPrice = false;
    let hasStalePrice = false;
    const valuationRefs: string[] = [];
    const costBasisRefs: string[] = [];

    for (const lot of openLots) {
      const valuation = await this.valuationService.valuePosition({
        tenantId,
        profileId,
        symbol: lot.symbol,
        asset: lot.asset,
        quantity: lot.remainingQuantity,
        at,
        baseCurrency,
      });

      if (valuation.evidence.valuationState === 'MISSING_PRICE' || valuation.evidence.valuationState === 'MISSING_FX' || valuation.valuedAmount === null || valuation.baseCurrencyAmount === null) {
        hasMissingPrice = true;
        continue; // missing/stale price not zero — skip, mark incomplete
      }
      if (valuation.evidence.valuationState === 'STALE') hasStalePrice = true;

      const currentValue = valuation.baseCurrencyAmount ?? '0';
      const costBasis = lot.totalCostBasis ? this.proportionalCostBasis(lot.totalCostBasis, lot.quantity, lot.remainingQuantity) : '0';

      try {
        const lotUnrealized = sub(currentValue, costBasis);
        unrealizedPnl = add(unrealizedPnl, lotUnrealized);
        valuationRefs.push(`${lot.symbol}:${valuation.evidence.marketPriceSource ?? 'UNKNOWN'}`);
        costBasisRefs.push(lot.id);
      } catch {}
    }

    if (hasMissingPrice) {
      return {
        unrealizedPnl: null,
        evidence: {
          type: PortfolioPnLType.UNREALIZED,
          amount: null,
          baseCurrency,
          calculationVersion: policy.calculationVersion,
          policyVersion: policy.policyVersion,
          methodology: 'MARKET_MINUS_COST_BASIS',
          dataCompleteness: 'MISSING_PRICE_INCOMPLETE',
          hasMissingPrice,
          hasStalePrice,
          valuationRefs,
          costBasisRefs,
        },
        hasMissingPrice,
        hasStalePrice,
      };
    }

    return {
      unrealizedPnl,
      evidence: {
        type: PortfolioPnLType.UNREALIZED,
        amount: unrealizedPnl,
        baseCurrency,
        calculationVersion: policy.calculationVersion,
        policyVersion: policy.policyVersion,
        methodology: 'MARKET_MINUS_COST_BASIS',
        dataCompleteness: hasStalePrice ? 'STALE_PRICE' : 'COMPLETE',
        hasMissingPrice,
        hasStalePrice,
        valuationRefs,
        costBasisRefs,
      },
      hasMissingPrice,
      hasStalePrice,
    };
  }

  async calculateGrossPnl(params: {
    tenantId: string;
    profileId: string;
    from?: Date;
    to?: Date;
    at: Date;
    baseCurrency?: string;
  }): Promise<{ grossPnl: string | null; realized: string; unrealized: string | null; evidence: any }> {
    const realized = await this.calculateRealizedPnl({ tenantId: params.tenantId, profileId: params.profileId, from: params.from, to: params.to });
    const unrealized = await this.calculateUnrealizedPnl({ tenantId: params.tenantId, profileId: params.profileId, at: params.at, baseCurrency: params.baseCurrency });

    let grossPnl: string | null = null;
    if (realized.realizedPnl !== null && unrealized.unrealizedPnl !== null) {
      grossPnl = add(realized.realizedPnl, unrealized.unrealizedPnl);
    } else if (realized.realizedPnl !== null && unrealized.hasMissingPrice) {
      // Gross incomplete if unrealized missing — explicit, not zero
      grossPnl = null;
    } else {
      grossPnl = realized.realizedPnl;
    }

    const policy = await this.policyService.resolvePolicy({ tenantId: params.tenantId, scope: 'TENANT' as any, scopeId: params.profileId });

    return {
      grossPnl,
      realized: realized.realizedPnl,
      unrealized: unrealized.unrealizedPnl,
      evidence: {
        type: PortfolioPnLType.GROSS,
        amount: grossPnl,
        realized: realized.realizedPnl,
        unrealized: unrealized.unrealizedPnl,
        baseCurrency: params.baseCurrency ?? policy.baseCurrency,
        calculationVersion: policy.calculationVersion,
        policyVersion: policy.policyVersion,
        methodology: 'REALIZED_PLUS_UNREALIZED',
        dataCompleteness: grossPnl === null ? 'MISSING_PRICE_INCOMPLETE' : unrealized.evidence.dataCompleteness,
        costBasisRefs: unrealized.evidence.costBasisRefs,
        valuationRefs: unrealized.evidence.valuationRefs,
      },
    };
  }

  async calculateNetPnl(params: {
    tenantId: string;
    profileId: string;
    from?: Date;
    to?: Date;
    at: Date;
    baseCurrency?: string;
  }): Promise<{ netPnl: string | null; grossPnl: string | null; fees: string; evidence: any }> {
    const gross = await this.calculateGrossPnl(params);
    const policy = await this.policyService.resolvePolicy({ tenantId: params.tenantId, scope: 'TENANT' as any, scopeId: params.profileId });
    const baseCurrency = params.baseCurrency ?? policy.baseCurrency;

    // Fees from cash ledger — authoritative Fees module, not duplicated
    let fees = '0';
    try {
      const feeEntries = await (this.prisma as any).portfolioCashLedgerEntry.findMany({
        where: {
          tenantId: params.tenantId,
          profileId: params.profileId,
          cashFlowType: { in: ['FEE', 'PLATFORM_FEE', 'PERFORMANCE_FEE'] },
          occurredAt: { gte: params.from ?? new Date(0), lte: params.to ?? params.at },
        },
      });
      for (const entry of feeEntries) {
        const amt = entry.baseCurrencyAmount ?? entry.amount;
        if (amt && isValidDecimal(amt)) fees = add(fees, amt);
      }
    } catch {}

    let netPnl: string | null = null;
    if (gross.grossPnl !== null) {
      netPnl = sub(gross.grossPnl, fees);
    }

    const feeAdjusted = gross.grossPnl !== null ? sub(gross.grossPnl, fees) : null;

    return {
      netPnl,
      grossPnl: gross.grossPnl,
      fees,
      evidence: {
        gross: gross.evidence,
        feeAdjusted: {
          type: PortfolioPnLType.FEE_ADJUSTED,
          amount: feeAdjusted,
          fees,
          baseCurrency,
          calculationVersion: policy.calculationVersion,
          policyVersion: policy.policyVersion,
          methodology: 'GROSS_MINUS_FEES',
          dataCompleteness: gross.evidence.dataCompleteness,
        },
        net: {
          type: PortfolioPnLType.NET,
          amount: netPnl,
          gross: gross.grossPnl,
          fees,
          baseCurrency,
          calculationVersion: policy.calculationVersion,
          policyVersion: policy.policyVersion,
          methodology: 'GROSS_MINUS_FEES',
          dataCompleteness: gross.evidence.dataCompleteness,
        },
      },
    };
  }

  private proportionalCostBasis(totalCostBasis: string, totalQuantity: string, remainingQuantity: string): string {
    try {
      if (totalQuantity === remainingQuantity) return totalCostBasis;
      const ratio = div(remainingQuantity, totalQuantity);
      return mul(totalCostBasis, ratio);
    } catch {
      return totalCostBasis;
    }
  }
}

import { BadRequestException, ForbiddenException, NotFoundException } from '@nestjs/common';
import { SYSTEM_ROLE_DEFINITIONS, SystemRole } from '@wlct/shared-types';
import { PortfolioAccountingController } from './portfolio-accounting.controller';
import { InvestorVisibilityRole } from './investor-visibility.service';

/**
 * Authorization of the portfolio-accounting API. Every route is reachable by
 * any authenticated user of the tenant, so the controller itself must keep
 * followers inside their own profiles and keep ledger writes for tenant
 * administrators.
 */

const TENANT = '11111111-1111-4111-8111-111111111111';
const OTHER_TENANT = '22222222-2222-4222-8222-222222222222';
const ALICE = 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
const BOB = 'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb';
const ADMIN = 'cccccccc-cccc-4ccc-8ccc-cccccccccccc';
const CAROL = 'dddddddd-dddd-4ddd-8ddd-dddddddddddd';

const PROFILES: Record<string, { id: string; tenantId: string; scope: string; scopeId: string }> = {
  'p-alice': { id: 'p-alice', tenantId: TENANT, scope: 'FOLLOWER', scopeId: ALICE },
  'p-bob': { id: 'p-bob', tenantId: TENANT, scope: 'FOLLOWER', scopeId: BOB },
  'p-foreign': { id: 'p-foreign', tenantId: OTHER_TENANT, scope: 'FOLLOWER', scopeId: ALICE },
};

function serviceMock(): any {
  const target: Record<string | symbol, jest.Mock> = {};
  return new Proxy(target, {
    get: (store, key) => {
      if (!store[key]) store[key] = jest.fn().mockResolvedValue({ id: 'result', data: [], total: 0, page: 1, limit: 50 });
      return store[key];
    },
  });
}

/** Principals carry the real system-role permission sets, not hand-picked ones. */
function principal(userId: string, role: SystemRole) {
  const definition = SYSTEM_ROLE_DEFINITIONS.find((d) => d.key === role);
  if (!definition) throw new Error(`unknown role ${role}`);
  return { user: { userId, tenantId: TENANT, permissions: [...definition.permissions] as string[], roles: [role] }, headers: {} };
}

function follower(userId: string) {
  return principal(userId, SystemRole.FOLLOWER);
}

function trader(userId: string) {
  return principal(userId, SystemRole.TRADER);
}

function tenantAdmin() {
  return principal(ADMIN, SystemRole.TENANT_ADMIN);
}

function finance() {
  return principal(ADMIN, SystemRole.FINANCE);
}

function compliance() {
  return principal(ADMIN, SystemRole.COMPLIANCE);
}

/** Mimics StatementService.listStatements: the visibility restriction is part of the query. */
function pageOfStatements(rows: Array<{ id: string; profileId: string }>, params: { profileIds?: string[] }) {
  const visible = params.profileIds ? rows.filter((row) => params.profileIds!.includes(row.profileId)) : rows;
  return { data: visible, total: visible.length, page: 1, limit: 50 };
}

