    });
  }
}

// # Proves portfolio snapshots commit with their developer webhook outbox event

import { PortfolioSnapshotService } from './portfolio-snapshot.service';
import { validateDeveloperEventPayload } from '../developer-platform/event-schemas/developer-event-schemas';

const TENANT_ID = '11111111-1111-4111-8111-111111111111';
const PROFILE_ID = '22222222-2222-4222-8222-222222222222';
const SNAPSHOT_AT = new Date('2026-10-09T12:00:00.000Z');

function buildHarness(options: { existing?: any; failAppend?: boolean } = {}) {
  let persisted = options.existing ?? null;
  const tx = {
    portfolioSnapshot: {
      findFirst: jest.fn(async () => persisted),
      create: jest.fn(async ({ data }: { data: Record<string, unknown> }) => {
        persisted = {
          id: 'snapshot-row-1',
          createdAt: SNAPSHOT_AT,
          ...data,
        };
        return persisted;
      }),
    },
  };
  const prisma = {
    withTenantRls: jest.fn(async (_tenantId: string, work: (transaction: unknown) => Promise<unknown>) => {
      const before = persisted;
      try {
        return await work(tx);
      } catch (error) {
        persisted = before;
        throw error;
      }
    }),
    portfolioCashLedgerEntry: { findMany: jest.fn(async () => []) },
  };
  const policyService = {
    resolvePolicy: jest.fn(async () => ({ baseCurrency: 'USD', calculationVersion: 'calc-v1', policyVersion: 'policy-v1' })),
  };
  const navService = {
    calculateNav: jest.fn(async () => ({
      nav: '100.00',
      grossAssetValue: '100.00',
      grossLiability: '0',
      methodology: { name: 'LEDGER' },
      evidences: [],
      sourceReferences: ['ledger:1'],
      dataCompleteness: 'COMPLETE',
    })),
  };
  const pnlService = {
    calculateNetPnl: jest.fn(async () => ({
      grossPnl: '5.00',
      netPnl: '4.50',
      fees: '0.50',
      evidence: { gross: { unrealized: '5.00' } },
    })),
    calculateRealizedPnl: jest.fn(async () => ({ realizedPnl: '1.00' })),
  };
  const performanceService = {
    calculateTWR: jest.fn(async () => ({ evidence: { returnPercent: '1.00' } })),
  };
  const positionAccounting = { getHoldings: jest.fn(async () => []) };
  const cashLedger = {
    getCashBalance: jest.fn(async () => ({ balance: '100.00', currency: 'USD', baseCurrencyBalance: '100.00' })),
  };
  const outbox = {
    append: jest.fn(async (_transaction: unknown, _input: Record<string, unknown>) => {
      if (options.failAppend) throw new Error('outbox unavailable');
      return undefined;
    }),
  };
  const service = new PortfolioSnapshotService(
    prisma as never,
    navService as never,
    pnlService as never,
    performanceService as never,
    positionAccounting as never,
    cashLedger as never,
    policyService as never,
    outbox as never,
  );
  return { service, prisma, tx, outbox, navService, persisted: () => persisted };
}

describe('PortfolioSnapshotService outbox transaction', () => {
  it('persists the snapshot and event together, using the immutable snapshot identity and as-of time', async () => {
    const { service, prisma, tx, outbox } = buildHarness();
    const snapshot = await service.createSnapshot({
      tenantId: TENANT_ID,
      profileId: PROFILE_ID,
      snapshotId: 'daily-snapshot-2026-10-09',
      timestamp: SNAPSHOT_AT,
      scope: 'TENANT',
      scopeId: PROFILE_ID,
      correlationId: 'request-123',
    });

    expect(prisma.withTenantRls).toHaveBeenCalledWith(TENANT_ID, expect.any(Function));
    expect(tx.portfolioSnapshot.create).toHaveBeenCalledTimes(1);
    expect(outbox.append).toHaveBeenCalledWith(tx, expect.objectContaining({
      tenantId: TENANT_ID,
      aggregateType: 'portfolio_snapshot',
      aggregateId: snapshot.id,
      eventType: 'portfolio.snapshot.created',
      idempotencyKey: `portfolio-snapshot:${snapshot.id}:created`,
      correlationId: 'request-123',
      payload: { snapshotId: 'daily-snapshot-2026-10-09', asOf: SNAPSHOT_AT.toISOString() },
    }));
    const event = outbox.append.mock.calls[0]?.[1];
    expect(validateDeveloperEventPayload('portfolio.snapshot.created', event?.payload)).toEqual({ valid: true, errors: [] });
  });

  it('reuses the original event identity on an idempotent snapshot retry', async () => {
    const existing = {
      id: 'snapshot-row-2',
      tenantId: TENANT_ID,
      profileId: PROFILE_ID,
      snapshotId: 'existing-snapshot',
      timestamp: SNAPSHOT_AT,
      nav: '100.00',
      createdAt: SNAPSHOT_AT,
      performanceMetrics: { correlationId: 'original-correlation' },
    };
    const { service, tx, outbox } = buildHarness({ existing });
    await service.createSnapshot({
      tenantId: TENANT_ID,
      profileId: PROFILE_ID,
      snapshotId: 'existing-snapshot',
      timestamp: SNAPSHOT_AT,
      scope: 'TENANT',
      scopeId: PROFILE_ID,
      correlationId: 'original-correlation',
    });

    expect(tx.portfolioSnapshot.create).not.toHaveBeenCalled();
    expect(outbox.append).toHaveBeenCalledWith(tx, expect.objectContaining({
      aggregateId: 'snapshot-row-2',
      idempotencyKey: 'portfolio-snapshot:snapshot-row-2:created',
      payload: { snapshotId: 'existing-snapshot', asOf: SNAPSHOT_AT.toISOString() },
    }));
  });

  it('rolls back the snapshot when event validation or persistence fails', async () => {
    const { service, tx, outbox, persisted } = buildHarness({ failAppend: true });
    await expect(service.createSnapshot({
      tenantId: TENANT_ID,
      profileId: PROFILE_ID,
      snapshotId: 'rollback-snapshot',
      timestamp: SNAPSHOT_AT,
      scope: 'TENANT',
      scopeId: PROFILE_ID,
    })).rejects.toThrow('outbox unavailable');

    expect(tx.portfolioSnapshot.create).toHaveBeenCalledTimes(1);
    expect(persisted()).toBeNull();
  });
});

import { Injectable, Logger, Optional } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OutboxService } from '../../infrastructure/outbox/outbox.service';
import { NavService } from './nav.service';
import { PnLService } from './pnl.service';
import { PerformanceService } from './performance.service';
import { PositionAccountingService } from './position-accounting.service';
import { CashLedgerService } from './cash-ledger.service';
import { AccountingPolicyService } from './accounting-policy.service';
import { deterministicIdempotencyKey } from './portfolio-accounting.types';
import { createHash } from 'crypto';

/** API view of a PortfolioSnapshot row: performance/methodology/fingerprint/correlationId from performanceMetrics. */
export function toSnapshotView(row: any): any {
  if (!row) return row;
  const metrics = row.performanceMetrics && typeof row.performanceMetrics === 'object' ? row.performanceMetrics : {};
  return {
    ...row,
    performance: metrics.twr ?? null,
    methodology: metrics.methodology ?? null,
    fingerprint: metrics.fingerprint ?? null,
    correlationId: metrics.correlationId ?? null,
  };
}

/**
 * Provides immutable point-in-time snapshots containing NAV, cash, positions, exposure refs,
 * PnL, fees, valuation evidence, source refs, calculationVersion, policyVersion, data completeness.
 * Must be idempotent and prevent duplicate snapshot creation.
 */

@Injectable()
export class PortfolioSnapshotService {
  private readonly logger = new Logger(PortfolioSnapshotService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly navService: NavService,
    private readonly pnlService: PnLService,
    private readonly performanceService: PerformanceService,
    private readonly positionAccounting: PositionAccountingService,
    private readonly cashLedger: CashLedgerService,
    private readonly policyService: AccountingPolicyService,
    @Optional() private readonly outbox?: OutboxService,
  ) {}

  async createSnapshot(params: {
    tenantId: string;
    profileId: string;
    snapshotId?: string;
    timestamp: Date;
    baseCurrency?: string;
    scope: string;
    scopeId: string;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, profileId, timestamp, scope, scopeId, correlationId = null } = params;

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: scope as any, scopeId });
    const baseCurrency = params.baseCurrency ?? policy.baseCurrency;

    const snapshotId = params.snapshotId ?? `snap_${tenantId.slice(0, 8)}_${profileId.slice(0, 8)}_${timestamp.toISOString().replace(/[:.]/g, '-')}`;

    const idempotencyKey = deterministicIdempotencyKey({
      type: `snapshot:${snapshotId}`,
      tenantId,
      profileId,
      sourceId: snapshotId,
      timestampBucket: timestamp.toISOString().slice(0, 10),
    });

    // Calculate NAV
    const navResult = await this.navService.calculateNav({ tenantId, profileId, at: timestamp, baseCurrency });

    // Calculate PnL
    const pnlResult = await this.pnlService.calculateNetPnl({
      tenantId,
      profileId,
      at: timestamp,
      baseCurrency,
      from: new Date(timestamp.getTime() - 24 * 60 * 60 * 1000), // last 24h for daily
      to: timestamp,
    });

    // Get holdings
    const holdings = await this.positionAccounting.getHoldings({ tenantId, profileId, at: timestamp });

    // Get cash
    const cash = await this.cashLedger.getCashBalance({ tenantId, profileId, at: timestamp });

    // Get performance (since inception)
    const inception = new Date('2020-01-01'); // would be profile creation date in real
    const twr = await this.performanceService.calculateTWR({ tenantId, profileId, periodStart: inception, periodEnd: timestamp, baseCurrency });

    // Fees from cash ledger
    let fees: any[] = [];
    try {
      const feeEntries = await (this.prisma as any).portfolioCashLedgerEntry.findMany({
        where: {
          tenantId,
          profileId,
          cashFlowType: { in: ['FEE', 'PLATFORM_FEE', 'PERFORMANCE_FEE'] },
          occurredAt: { lte: timestamp },
        },
        orderBy: { occurredAt: 'desc' },
        take: 100,
      });
      fees = feeEntries;
    } catch {
      fees = [];
    }

    const fingerprint = createHash('sha256')
      .update(JSON.stringify({ tenantId, profileId, snapshotId, timestamp: timestamp.toISOString(), nav: navResult.nav, holdings }))
      .digest('hex');

    if (!this.outbox) {
      throw new Error('Transactional outbox is unavailable; refusing portfolio snapshot without its portfolio.snapshot.created event');
    }
    const snapshot = await this.prisma.withTenantRls(tenantId, async (tx) => {
      const store = tx as any;
      const existing = await store.portfolioSnapshot.findFirst({
        where: { tenantId, OR: [{ idempotencyKey }, { snapshotId }] },
      });
      if (existing) {
        this.logger.log({ event: 'portfolio.snapshot.idempotent_hit', snapshotId, tenantId });
        await this.outbox!.append(tx, {
          tenantId,
          aggregateType: 'portfolio_snapshot',
          aggregateId: existing.id,
          eventType: 'portfolio.snapshot.created',
          idempotencyKey: `portfolio-snapshot:${existing.id}:created`,
          correlationId: correlationId && correlationId.length <= 64 ? correlationId : null,
          occurredAt: existing.timestamp,
          payload: { snapshotId: existing.snapshotId, asOf: new Date(existing.timestamp).toISOString() },
        });
        return existing;
      }

      const created = await store.portfolioSnapshot.create({
        data: {
          tenantId,
          profileId,
          snapshotId,
          timestamp,
          baseCurrency,
          cash: cash.balance,
          positions: holdings as any,
          nav: navResult.nav,
          grossAssetValue: navResult.grossAssetValue,
          grossLiability: navResult.grossLiability,
          realizedPnl: pnlResult.grossPnl ? (await this.pnlService.calculateRealizedPnl({ tenantId, profileId })).realizedPnl : null,
          unrealizedPnl: pnlResult.evidence?.gross?.unrealized ?? null,
          grossPnl: pnlResult.grossPnl,
          netPnl: pnlResult.netPnl,
          // fees is a decimal-string column: the fee total of the same window as gross/net PnL
          // (netPnl = grossPnl - fees). The fee ledger rows are kept as cash-breakdown evidence.
          fees: pnlResult.fees ?? null,
          cashBreakdown: {
            balance: cash.balance,
            currency: cash.currency,
            baseCurrencyBalance: cash.baseCurrencyBalance ?? null,
            recentFeeEntries: fees.map((entry: any) => ({
              id: entry.id,
              cashFlowType: entry.cashFlowType,
              amount: entry.amount,
              currency: entry.currency,
              baseCurrencyAmount: entry.baseCurrencyAmount ?? null,
              occurredAt: entry.occurredAt,
            })),
          } as any,
          // No performance/methodology/fingerprint/correlationId columns: kept in performanceMetrics.
          performanceMetrics: {
            twr: twr.evidence ?? null,
            methodology: navResult.methodology ?? null,
            fingerprint,
            correlationId: correlationId ?? null,
          } as any,
          valuationEvidence: navResult.evidences as any,
          sourceReferences: navResult.sourceReferences,
          calculationVersion: policy.calculationVersion,
          policyVersion: policy.policyVersion,
          dataCompleteness: navResult.dataCompleteness,
          idempotencyKey,
        },
      });
      await this.outbox!.append(tx, {
        tenantId,
        aggregateType: 'portfolio_snapshot',
        aggregateId: created.id,
        eventType: 'portfolio.snapshot.created',
        idempotencyKey: `portfolio-snapshot:${created.id}:created`,
        correlationId: correlationId && correlationId.length <= 64 ? correlationId : null,
        occurredAt: created.timestamp,
        payload: { snapshotId: created.snapshotId, asOf: new Date(created.timestamp).toISOString() },
      });
      return created;
    });

    this.logger.log({ event: 'portfolio.snapshot.created', snapshotId, tenantId, nav: navResult.nav });

    return toSnapshotView(snapshot);
  }

  async getSnapshot(params: { tenantId: string; snapshotId: string }): Promise<any | null> {
    const snapshot = await (this.prisma as any).portfolioSnapshot.findFirst({
      where: { tenantId: params.tenantId, snapshotId: params.snapshotId },
    });
    return snapshot ? toSnapshotView(snapshot) : null;
  }

  async listSnapshots(params: {
    tenantId: string;
    profileId?: string;
    from?: Date;
    to?: Date;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId, profileId, from, to, page = 1, limit = 50 } = params;
    const where: any = { tenantId };
    if (profileId) where.profileId = profileId;
    if (from || to) {
      where.timestamp = {};
      if (from) where.timestamp.gte = from;
      if (to) where.timestamp.lte = to;
    }

    const [data, total] = await Promise.all([
      (this.prisma as any).portfolioSnapshot.findMany({
        where,
        orderBy: { timestamp: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).portfolioSnapshot.count({ where }),
    ]);
    return { data: data.map(toSnapshotView), total, page, limit };
  }

  async verifySnapshotImmutability(snapshotId: string, currentHash: string): Promise<boolean> {
    const snapshot = await (this.prisma as any).portfolioSnapshot.findFirst({ where: { snapshotId } });
    if (!snapshot) return false;
    return toSnapshotView(snapshot).fingerprint === currentHash;
  }
}

// # Responsibility: build tenant-scoped position and lot accounting from authoritative positions and fills.
import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AccountingPolicyService } from './accounting-policy.service';
import {
  PortfolioPositionClassification,
  deterministicIdempotencyKey,
  add,
  sub,
  cmp,
  mul,
  redactSecrets,
  isValidDecimal,
} from './portfolio-accounting.types';

/**
 * Builds accounting views of holdings and position lots from authoritative positions/fills.
 * Must support opening, increasing, reducing, closing, realized/unrealized classification,
 * and lot continuity without changing the authoritative position engine.
 */

@Injectable()
export class PositionAccountingService {
  private readonly logger = new Logger(PositionAccountingService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: AccountingPolicyService,
  ) {}

  async openLot(params: {
    tenantId: string;
    profileId: string;
    accountingEventId?: string | null;
    symbol: string;
    asset: string;
    venue?: string | null;
    quantity: string;
    costBasisPerUnit?: string | null;
    currency: string;
    occurredAt: Date;
    correlationId?: string | null;
  }): Promise<any> {
    const { tenantId, profileId, accountingEventId = null, symbol, asset, venue = null, quantity, costBasisPerUnit = null, currency, occurredAt, correlationId = null } = params;

    if (!isValidDecimal(quantity)) throw new BadRequestException(`Invalid quantity: ${quantity}`);
    if (cmp(quantity, '0') <= 0) throw new BadRequestException('Quantity must be > 0');

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });

    const totalCostBasis = costBasisPerUnit ? this.mulSafe(quantity, costBasisPerUnit) : null;

    const idempotencyKey = deterministicIdempotencyKey({
      type: `position-lot:open:${symbol}`,
      tenantId,
      profileId,
      sourceId: accountingEventId ?? `${symbol}:${quantity}:${occurredAt.toISOString()}`,
      timestampBucket: occurredAt.toISOString().slice(0, 10),
    });

    try {
      const existing = await (this.prisma as any).portfolioPositionLot.findFirst({ where: { tenantId, idempotencyKey } });
      if (existing) return existing;
    } catch {}

    const lot = await (this.prisma as any).portfolioPositionLot.create({
      data: {
        tenantId,
        profileId,
        accountingEventId: accountingEventId ?? null,
        symbol,
        asset,
        venue: venue ?? null,
        classification: quantity.startsWith('-') ? PortfolioPositionClassification.SHORT : PortfolioPositionClassification.LONG,
        quantity,
        remainingQuantity: quantity,
        costBasisPerUnit: costBasisPerUnit ?? null,
        totalCostBasis: totalCostBasis ?? null,
        currency,
        baseCurrency: policy.baseCurrency,
        costBasisMethod: policy.costBasisMethod,
        calculationVersion: policy.calculationVersion,
        policyVersion: policy.policyVersion,
        isClosed: false,
        openedAt: occurredAt,
        idempotencyKey,
        metadata: redactSecrets({ symbol, venue }) as any,
        evidence: redactSecrets({ quantity, costBasisPerUnit, source: 'Position accounting from authoritative fills' }) as any,
      },
    });

    return lot;
  }

  async reduceLot(params: {
    tenantId: string;
    profileId: string;
    symbol: string;
    quantity: string;
    closingEventId?: string | null;
    occurredAt: Date;
    correlationId?: string | null;
  }): Promise<{ closedLots: any[]; remainingQuantity: string; realizedPnl: string }> {
    const { tenantId, profileId, symbol, quantity, closingEventId = null, occurredAt } = params;

    if (!isValidDecimal(quantity)) throw new BadRequestException(`Invalid quantity: ${quantity}`);

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });

    // FIFO reduction — deterministic
    const openLots = await (this.prisma as any).portfolioPositionLot.findMany({
      where: { tenantId, profileId, symbol, isClosed: false, isReversed: false },
      orderBy: { openedAt: 'asc' },
    });

    let remainingToClose = quantity;
    const totalRealizedPnl = '0';
    const closedLots: any[] = [];

    for (const lot of openLots) {
      if (cmp(remainingToClose, '0') <= 0) break;
      const lotRemaining = lot.remainingQuantity;
      const closeQty = cmp(remainingToClose, lotRemaining) >= 0 ? lotRemaining : remainingToClose;

      // Realized PnL = (closeQty * currentPrice?) — here we calculate as proportional cost basis release, actual PnL calculated in cost-basis service
      // For position accounting, we just reduce remainingQuantity
      const newRemaining = sub(lotRemaining, closeQty);
      const isNowClosed = cmp(newRemaining, '0') === 0;

      const updated = await (this.prisma as any).portfolioPositionLot.update({
        where: { id: lot.id },
        data: {
          remainingQuantity: newRemaining,
          isClosed: isNowClosed,
          closedAt: isNowClosed ? occurredAt : null,
          closingEventId: isNowClosed ? closingEventId : null,
        },
      });

      closedLots.push(updated);
      remainingToClose = sub(remainingToClose, closeQty);
    }

    return { closedLots, remainingQuantity: remainingToClose, realizedPnl: totalRealizedPnl };
  }

  async getHoldings(params: {
    tenantId: string;
    profileId: string;
    at?: Date;
  }): Promise<Array<{ symbol: string; asset: string; quantity: string; classification: string; costBasis: string | null }>> {
    const where: any = { tenantId: params.tenantId, profileId: params.profileId, isClosed: false, isReversed: false };
    if (params.at) where.openedAt = { lte: params.at };

    const lots = await (this.prisma as any).portfolioPositionLot.findMany({
      where,
      orderBy: { openedAt: 'asc' },
    });

    // Aggregate by symbol — deterministic
    const holdingsMap = new Map<string, { asset: string; quantity: string; classification: string; costBasis: string | null }>();
    for (const lot of lots) {
      const existing = holdingsMap.get(lot.symbol);
      if (!existing) {
        holdingsMap.set(lot.symbol, {
          asset: lot.asset,
          quantity: lot.remainingQuantity,
          classification: lot.classification,
          costBasis: lot.totalCostBasis,
        });
      } else {
        existing.quantity = add(existing.quantity, lot.remainingQuantity);
        if (existing.costBasis && lot.totalCostBasis) {
          existing.costBasis = add(existing.costBasis, lot.totalCostBasis);
        } else if (lot.totalCostBasis) {
          existing.costBasis = lot.totalCostBasis;
        }
      }
    }

    return Array.from(holdingsMap.entries()).map(([symbol, data]) => ({
      symbol,
      asset: data.asset,
      quantity: data.quantity,
      classification: data.classification,
      costBasis: data.costBasis,
    }));
  }

  async listLots(params: {
    tenantId: string;
    profileId: string;
    symbol?: string;
    isClosed?: boolean;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId, profileId, symbol, isClosed, page = 1, limit = 50 } = params;
    const where: any = { tenantId, profileId };
    if (symbol) where.symbol = symbol;
    if (isClosed !== undefined) where.isClosed = isClosed;

    const [data, total] = await Promise.all([
      (this.prisma as any).portfolioPositionLot.findMany({
        where,
        orderBy: { openedAt: 'asc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).portfolioPositionLot.count({ where }),
    ]);
    return { data, total, page, limit };
  }

  private mulSafe(a: string, b: string): string {
    try {
      return mul(a, b);
    } catch {
      return '0';
    }
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { StatementService } from './statement.service';
import { AccountingPolicyService } from './accounting-policy.service';
import { redactSecrets } from './portfolio-accounting.types';

/**
 * Produces CSV/JSON/report payloads from persisted records, tenant-safe, deterministic,
 * reproducible, free of secrets.
 */

@Injectable()
export class ReportExportService {
  private readonly logger = new Logger(ReportExportService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly statementService: StatementService,
    private readonly policyService: AccountingPolicyService,
  ) {}

  async exportStatementCsv(params: { tenantId: string; statementId: string }): Promise<{ csv: string; filename: string }> {
    const statement = await this.statementService.getStatement({ tenantId: params.tenantId, statementId: params.statementId });
    if (!statement) throw new BadRequestException('Statement not found');

    // Tenant isolation — statement already filtered by tenantId
    // Deterministic CSV from persisted records
    const headers = [
      'portfolioId',
      'periodStart',
      'periodEnd',
      'openingNav',
      'closingNav',
      'realizedPnl',
      'unrealizedPnl',
      'grossPnl',
      'fees',
      'netPnl',
      'baseCurrency',
      'returnMethodology',
      'calculationVersion',
      'policyVersion',
      'dataCompleteness',
    ];

    const evidence = (statement.evidence as any) ?? {};
    const isoDate = (value: unknown): string => (value instanceof Date ? value.toISOString() : value ? String(value) : '');
    const row = [
      statement.profileId,
      isoDate(statement.periodStart),
      isoDate(statement.periodEnd),
      statement.openingNav ?? '',
      statement.closingNav ?? '',
      statement.realizedPnl ?? '',
      statement.unrealizedPnl ?? '',
      (statement.fees as any)?.grossPnl ?? '',
      (statement.fees as any)?.total ?? '',
      statement.netPnl ?? '',
      statement.baseCurrency,
      statement.returnMethodology,
      statement.calculationVersion,
      statement.policyVersion,
      evidence.dataCompleteness ?? '',
    ];

    const csv = [headers.join(','), row.map((v) => `"${String(v).replace(/"/g, '""')}"`).join(',')].join('\n');

    return { csv, filename: `statement_${statement.statementId}.csv` };
  }

  async exportStatementJson(params: { tenantId: string; statementId: string }): Promise<{ json: any; filename: string }> {
    const statement = await this.statementService.getStatement({ tenantId: params.tenantId, statementId: params.statementId });
    if (!statement) throw new BadRequestException('Statement not found');

    // Export deterministic from persisted records, secrets redacted
    const evidence = (statement.evidence as any) ?? {};
    const json = redactSecrets({
      statementId: statement.statementId,
      portfolioId: statement.profileId,
      periodId: statement.periodId,
      periodStart: statement.periodStart,
      periodEnd: statement.periodEnd,
      openingNav: statement.openingNav,
      closingNav: statement.closingNav,
      deposits: statement.deposits,
      withdrawals: statement.withdrawals,
      transfers: statement.transfers,
      tradingActivity: statement.tradingActivity,
      realizedPnl: statement.realizedPnl,
      unrealizedPnl: statement.unrealizedPnl,
      grossPnl: (statement.fees as any)?.grossPnl ?? null,
      fees: statement.fees,
      netPnl: statement.netPnl,
      returnMethodology: statement.returnMethodology,
      holdings: statement.endingHoldings,
      cash: statement.cash,
      returnPercent: statement.returnPercent,
      performance: evidence.performance ?? null,
      benchmark: statement.benchmarkReturn ?? null,
      reconciliationStatus: statement.reconciliationStatus,
      baseCurrency: statement.baseCurrency,
      calculationVersion: statement.calculationVersion,
      policyVersion: statement.policyVersion,
      methodology: evidence.methodology ?? null,
      dataCompleteness: evidence.dataCompleteness ?? null,
      sourceReferences: statement.sourceReferences,
    });

    return { json, filename: `statement_${statement.statementId}.json` };
  }

  async exportHoldingsCsv(params: {
    tenantId: string;
    profileId: string;
    at: Date;
  }): Promise<{ csv: string; filename: string }> {
    let holdings: any[] = [];
    try {
      holdings = await (this.prisma as any).portfolioPositionLot.findMany({
        where: { tenantId: params.tenantId, profileId: params.profileId, isClosed: false, openedAt: { lte: params.at } },
        orderBy: { symbol: 'asc' },
      });
    } catch {
      holdings = [];
    }

    const headers = ['symbol', 'asset', 'quantity', 'remainingQuantity', 'costBasisPerUnit', 'totalCostBasis', 'currency', 'openedAt'];
    const rows = holdings.map((h: any) => [
      h.symbol,
      h.asset,
      h.quantity,
      h.remainingQuantity,
      h.costBasisPerUnit ?? '',
      h.totalCostBasis ?? '',
      h.currency,
      h.openedAt.toISOString(),
    ]);

    const csv = [headers.join(','), ...rows.map((r: any) => r.map((v: any) => `"${String(v).replace(/"/g, '""')}"`).join(','))].join('\n');

    return { csv, filename: `holdings_${params.profileId}_${params.at.toISOString().slice(0, 10)}.csv` };
  }

  async exportCashLedgerCsv(params: {
    tenantId: string;
    profileId: string;
    from?: Date;
    to?: Date;
  }): Promise<{ csv: string; filename: string }> {
    const where: any = { tenantId: params.tenantId, profileId: params.profileId };
    if (params.from || params.to) {
      where.occurredAt = {};
      if (params.from) where.occurredAt.gte = params.from;
      if (params.to) where.occurredAt.lte = params.to;
    }

    let entries: any[] = [];
    try {
      entries = await (this.prisma as any).portfolioCashLedgerEntry.findMany({
        where,
        orderBy: { occurredAt: 'asc' },
      });
    } catch {
      entries = [];
    }

    const headers = ['occurredAt', 'cashFlowType', 'asset', 'amount', 'currency', 'baseCurrency', 'baseCurrencyAmount', 'sourceType', 'sourceId'];
    const rows = entries.map((e: any) => [
      e.occurredAt.toISOString(),
      e.cashFlowType,
      e.asset,
      e.amount,
      e.currency,
      e.baseCurrency,
      e.baseCurrencyAmount ?? '',
      e.sourceType ?? '',
      e.sourceId ?? '',
    ]);

    const csv = [headers.join(','), ...rows.map((r: any) => r.map((v: any) => `"${String(v).replace(/"/g, '""')}"`).join(','))].join('\n');

    return { csv, filename: `cash_ledger_${params.profileId}_${Date.now()}.csv` };
  }
}

import { InMemoryPrisma } from '../../common/__fixtures__/in-memory-prisma.fixture-spec';
import { StatementService } from './statement.service';

/**
 * GET portfolio-accounting/statements validated `state` (StatementQueryDto)
 * but never passed it on: a client asking for FINAL statements got all of
 * them, drafts included.
 */
describe('StatementService.listStatements', () => {
  function build() {
    const findMany = jest.fn(async () => []);
    const count = jest.fn(async () => 0);
    const service = new (StatementService as any)({ portfolioStatement: { findMany, count } }) as StatementService;
    return { service, findMany, count };
  }

  it('applies the state filter to both the page and the total', async () => {
    const { service, findMany, count } = build();
    await service.listStatements({ tenantId: 't1', profileId: 'p1', state: 'FINAL' });
    expect(findMany).toHaveBeenCalledWith(expect.objectContaining({ where: { tenantId: 't1', profileId: 'p1', state: 'FINAL' } }));
    expect(count).toHaveBeenCalledWith({ where: { tenantId: 't1', profileId: 'p1', state: 'FINAL' } });
  });

  it('no state -> no state filter', async () => {
    const { service, findMany } = build();
