describe('Statement persistence matches the PortfolioStatement model', () => {
  it('finds the model in the generated client', () => {
    expect(statementModel).toBeDefined();
  });

  it('writes statement.generated in the same tenant transaction with the generated artifact identity', async () => {
    const created: { data?: any } = {};
    const { service, prisma, tx, outbox } = buildService(created);
    const statement = await service.generateStatement({ tenantId: TENANT, profileId: PROFILE, periodId: PERIOD, operatorId: 'admin-1' });

    expect(prisma.withTenantRls).toHaveBeenCalledTimes(1);
    expect(outbox.append).toHaveBeenCalledWith(tx, expect.objectContaining({
      tenantId: TENANT,
      aggregateType: 'statement',
      aggregateId: 'row-1',
      eventType: 'statement.generated',
      payload: expect.objectContaining({
        statementId: statement.statementId,
        generatedAt: expect.any(String),
      }),
    }));
    const event = outbox.append.mock.calls[0]?.[1];
    expect(validateDeveloperEventPayload('statement.generated', event?.payload)).toEqual({ valid: true, errors: [] });
  });

  it('writes only model columns, with every required column and the right scalar types', async () => {
    const created: { data?: any } = {};
    const { service } = buildService(created);
    await service.generateStatement({ tenantId: TENANT, profileId: PROFILE, periodId: PERIOD, operatorId: 'admin-1' });

    const data = created.data;
    expect(data).toBeDefined();
    const fields = new Map(statementModel!.fields.map((f) => [f.name, f]));

    const unknown = Object.keys(data).filter((key) => !fields.has(key) || fields.get(key)!.kind === 'object');
    expect(unknown).toEqual([]);

    const required = statementModel!.fields
      .filter((f) => f.kind !== 'object' && f.isRequired && !f.hasDefaultValue && !f.isUpdatedAt)
      .map((f) => f.name);
    const missing = required.filter((name) => data[name] === undefined || data[name] === null);
    expect(missing).toEqual([]);

    for (const [key, value] of Object.entries(data)) {
      if (value === null || value === undefined) continue;
      const field = fields.get(key)!;
      if (field.kind === 'scalar' && field.type === 'String') expect({ key, type: typeof value }).toEqual({ key, type: 'string' });
      if (field.kind === 'scalar' && field.type === 'DateTime') expect({ key, isDate: value instanceof Date }).toEqual({ key, isDate: true });
    }
  });

  it('stores decimal-exact totals and keeps the line items and evidence', async () => {
    const created: { data?: any } = {};
    const { service } = buildService(created);
    await service.generateStatement({ tenantId: TENANT, profileId: PROFILE, periodId: PERIOD, operatorId: 'admin-1' });
    const data = created.data;
    expect(data.deposits).toBe('500.3');
    expect(data.withdrawals).toBe('50');
    expect(data.transfers).toBe('17.5');
    expect(data.returnPercent).toBe('4.1');
    expect(data.cash).toBe('120.25');
    expect(data.fees).toEqual({ total: '1.5', grossPnl: '43' });
    expect(data.endingHoldings).toHaveLength(1);
    expect(data.tradingActivity.count).toBe(1);
    expect(data.tradingActivity.deposits).toHaveLength(2);
    expect(data.evidence.dataCompleteness).toBe('COMPLETE');
    expect(data.evidence.createdBy).toBe('admin-1');
  });

  it('sums ledger amounts without float error and skips non-decimal values', () => {
    expect(sumLedgerAmounts([{ amount: '0.1' }, { amount: '0.2' }])).toBe('0.3');
    expect(sumLedgerAmounts([{ amount: '10' }, { amount: '2.5', type: 'TRANSFER_OUT' }])).toBe('7.5');
    expect(sumLedgerAmounts([{ amount: 'abc' }, { amount: null }, { amount: '1' }])).toBe('1');
  });

  it('exports a CSV row with one value per header, in header order', async () => {
    const statement = {
      statementId: 'stmt-1',
      profileId: PROFILE,
      periodId: PERIOD,
      periodStart: new Date('2026-08-01T00:00:00Z'),
      periodEnd: new Date('2026-08-31T23:59:59Z'),
      openingNav: '1000',
      closingNav: '1041.5',
      realizedPnl: '20',
      unrealizedPnl: '23',
      fees: { total: '1.5', grossPnl: '43' },
      netPnl: '41.5',
      baseCurrency: 'USD',
      returnMethodology: 'TIME_WEIGHTED_RETURN',
      calculationVersion: 'calc-1',
      policyVersion: 'policy-1',
      evidence: { dataCompleteness: 'COMPLETE' },
    };
    const exporter = new ReportExportService({} as any, { getStatement: jest.fn(async () => statement) } as any, {} as any);
    const { csv } = await exporter.exportStatementCsv({ tenantId: TENANT, statementId: 'stmt-1' });
    const [headerLine, rowLine] = csv.split('\n');
    const headers = headerLine!.split(',');
    const values = rowLine!.split('","').map((v) => v.replace(/^"|"$/g, ''));
    expect(values).toHaveLength(headers.length);
    const byHeader = Object.fromEntries(headers.map((h, i) => [h, values[i]]));
    expect(byHeader).toMatchObject({
      portfolioId: PROFILE,
      periodStart: '2026-08-01T00:00:00.000Z',
      periodEnd: '2026-08-31T23:59:59.000Z',
      openingNav: '1000',
      closingNav: '1041.5',
      grossPnl: '43',
      fees: '1.5',
      netPnl: '41.5',
      dataCompleteness: 'COMPLETE',
    });
  });
});

import { Injectable, Logger, BadRequestException, Optional } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OutboxService } from '../../infrastructure/outbox/outbox.service';
import { AccountingPolicyService } from './accounting-policy.service';
import { AccountingPeriodService } from './accounting-period.service';
import { PortfolioSnapshotService } from './portfolio-snapshot.service';
import { PnLService } from './pnl.service';
import { PerformanceService } from './performance.service';
import { CashLedgerService } from './cash-ledger.service';
import { PositionAccountingService } from './position-accounting.service';
import {
  PortfolioReturnMethodology,
  PortfolioStatementState,
  add,
  deterministicIdempotencyKey,
  isValidDecimal,
  redactSecrets,
  sub,
} from './portfolio-accounting.types';

/** Decimal-safe total of ledger amounts; values that are not plain decimals are skipped, never coerced. */
export function sumLedgerAmounts(entries: Array<{ amount: unknown; type?: string }>): string {
  let total = '0';
  for (const entry of entries) {
    const value = entry.amount === null || entry.amount === undefined ? '' : String(entry.amount);
    if (!isValidDecimal(value)) continue;
    total = entry.type === 'TRANSFER_OUT' ? sub(total, value) : add(total, value);
  }
  return total;
}

/**
 * Generates statements from persisted periods and snapshots, including holdings, cash,
 * transactions, fees, PnL, returns, and methodology. Statements from persisted accounting include
 * portfolio ID, period, opening/closing NAV, deposits/withdrawals/transfers, trading activity,
 * realized/unrealized PnL, fees, net PnL, return methodology, holdings, cash, performance,
 * benchmark, reconciliation status, versions.
 */

@Injectable()
export class StatementService {
  private readonly logger = new Logger(StatementService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: AccountingPolicyService,
    private readonly periodService: AccountingPeriodService,
    private readonly snapshotService: PortfolioSnapshotService,
    private readonly pnlService: PnLService,
    private readonly performanceService: PerformanceService,
    private readonly cashLedger: CashLedgerService,
    private readonly positionAccounting: PositionAccountingService,
    @Optional() private readonly outbox?: OutboxService,
  ) {}

  async generateStatement(params: {
    tenantId: string;
    profileId: string;
    periodId: string;
    statementId?: string;
    operatorId?: string | null;
  }): Promise<any> {
    const { tenantId, profileId, periodId, operatorId = null } = params;

    const period = await this.periodService.getPeriod({ tenantId, periodId });
    if (!period) throw new BadRequestException('Period not found');
    if (period.profileId !== profileId) throw new BadRequestException('Period profile mismatch');

    const policy = await this.policyService.resolvePolicy({ tenantId, scope: 'TENANT' as any, scopeId: profileId });

    const statementId = params.statementId ?? `stmt_${tenantId.slice(0, 8)}_${periodId.slice(0, 8)}_${Date.now()}`;

    const idempotencyKey = deterministicIdempotencyKey({
      type: `statement:${statementId}`,
      tenantId,
      profileId,
      sourceId: periodId,
    });

    // Fetch persisted records — statements from persisted accounting
    const openingSnapshot = await (this.prisma as any).portfolioSnapshot.findFirst({
      where: { tenantId, profileId, timestamp: { lte: period.periodStart } },
      orderBy: { timestamp: 'desc' },
    });

    const closingSnapshot = await (this.prisma as any).portfolioSnapshot.findFirst({
      where: { tenantId, profileId, timestamp: { gte: period.periodEnd, lte: new Date(period.periodEnd.getTime() + 24 * 60 * 60 * 1000) } },
      orderBy: { timestamp: 'asc' },
    });

    const cashEntries = await this.cashLedger.listCashEntries({
      tenantId,
      profileId,
      from: period.periodStart,
      to: period.periodEnd,
      page: 1,
      limit: 1000,
    });

    const deposits = cashEntries.data.filter((e: any) => e.cashFlowType === 'DEPOSIT');
    const withdrawals = cashEntries.data.filter((e: any) => e.cashFlowType === 'WITHDRAWAL');
    const transfers = cashEntries.data.filter((e: any) => ['TRANSFER_IN', 'TRANSFER_OUT'].includes(e.cashFlowType));

    const holdings = await this.positionAccounting.getHoldings({ tenantId, profileId, at: period.periodEnd });

    const pnl = await this.pnlService.calculateNetPnl({
      tenantId,
      profileId,
      from: period.periodStart,
      to: period.periodEnd,
      at: period.periodEnd,
      baseCurrency: period.baseCurrency,
    });

    const twr = await this.performanceService.calculateTWR({
      tenantId,
      profileId,
      periodStart: period.periodStart,
      periodEnd: period.periodEnd,
      baseCurrency: period.baseCurrency,
    });

    const mwr = await this.performanceService.calculateMWR({
      tenantId,
      profileId,
      periodStart: period.periodStart,
      periodEnd: period.periodEnd,
      baseCurrency: period.baseCurrency,
    });

    // Reconciliation status
    let reconciliationStatus = 'UNKNOWN';
    try {
      const recon = await (this.prisma as any).portfolioAccountingReconciliation.findFirst({
        where: { tenantId, profileId, periodId },
        orderBy: { createdAt: 'desc' },
      });
      if (recon) reconciliationStatus = recon.state;
    } catch {
      reconciliationStatus = 'PENDING';
    }

    // Build statement from persisted records
    const statementData = {
      portfolioId: profileId,
      period: { id: period.id, start: period.periodStart, end: period.periodEnd, type: (period.closeMetadata as any)?.periodType ?? null },
      openingNav: openingSnapshot?.nav ?? null,
      closingNav: closingSnapshot?.nav ?? pnl.evidence?.gross?.endingNav ?? null,
      deposits: deposits.map((d: any) => ({ amount: d.baseCurrencyAmount ?? d.amount, currency: d.currency, occurredAt: d.occurredAt })),
      withdrawals: withdrawals.map((w: any) => ({ amount: w.baseCurrencyAmount ?? w.amount, currency: w.currency, occurredAt: w.occurredAt })),
      transfers: transfers.map((t: any) => ({ amount: t.baseCurrencyAmount ?? t.amount, currency: t.currency, type: t.cashFlowType, occurredAt: t.occurredAt })),
      tradingActivity: cashEntries.data.filter((e: any) => ['TRADE_SETTLEMENT_BUY', 'TRADE_SETTLEMENT_SELL'].includes(e.cashFlowType)).length,
      realizedPnl: pnl.evidence?.gross?.realized ?? null,
      unrealizedPnl: pnl.evidence?.gross?.unrealized ?? null,
      grossPnl: pnl.grossPnl,
      fees: pnl.fees,
      netPnl: pnl.netPnl,
      returnMethodology: policy.returnMethodology,
      holdings,
      cash: { balance: closingSnapshot?.cash ?? '0', currency: period.baseCurrency },
      performance: { twr: twr.returnPercent, mwr: mwr.returnPercent, twrEvidence: twr.evidence, mwrEvidence: mwr.evidence },
      benchmark: null, // Would include benchmark if configured
      reconciliationStatus,
      versions: { calculationVersion: policy.calculationVersion, policyVersion: policy.policyVersion },
    };

    const dataCompleteness = closingSnapshot?.dataCompleteness ?? 'COMPLETE';
    const returnPercent =
      policy.returnMethodology === PortfolioReturnMethodology.MONEY_WEIGHTED_RETURN ? mwr.returnPercent : twr.returnPercent;

    // Only columns of the PortfolioStatement model: Prisma rejects unknown
    // fields, so line items and evidence remain in the model's Json columns.
    const finalizedAt = new Date();
    const persistenceData = {
      tenantId,
      profileId,
      periodId,
      statementId,
      state: PortfolioStatementState.FINALIZED as any,
      periodStart: period.periodStart,
      periodEnd: period.periodEnd,
      openingNav: statementData.openingNav,
      closingNav: statementData.closingNav,
      deposits: sumLedgerAmounts(statementData.deposits),
      withdrawals: sumLedgerAmounts(statementData.withdrawals),
      transfers: sumLedgerAmounts(statementData.transfers),
      tradingActivity: {
        count: statementData.tradingActivity,
        deposits: statementData.deposits,
        withdrawals: statementData.withdrawals,
        transfers: statementData.transfers,
      } as any,
      realizedPnl: statementData.realizedPnl,
      unrealizedPnl: statementData.unrealizedPnl,
      fees: { total: statementData.fees, grossPnl: statementData.grossPnl } as any,
      netPnl: statementData.netPnl,
      returnMethodology: policy.returnMethodology as any,
      returnPercent: returnPercent ?? null,
      benchmarkReturn: null,
      endingHoldings: holdings as any,
      cash: statementData.cash.balance,
      reconciliationStatus,
      baseCurrency: period.baseCurrency,
      calculationVersion: policy.calculationVersion,
      policyVersion: policy.policyVersion,
      sourceReferences: [...new Set([...(closingSnapshot?.sourceReferences ?? []), ...(openingSnapshot?.sourceReferences ?? [])])],
      evidence: redactSecrets({
        statementData,
        period,
        openingSnapshotId: openingSnapshot?.id,
        closingSnapshotId: closingSnapshot?.id,
        performance: statementData.performance,
        methodology: `STATEMENT_${policy.returnMethodology}`,
        dataCompleteness,
        createdBy: operatorId,
      }) as any,
      idempotencyKey,
      finalizedAt,
    };
    if (!this.outbox) {
      throw new Error('Transactional outbox is unavailable; refusing statement generation without its statement.generated event');
    }
    const statement = await this.prisma.withTenantRls(tenantId, async (tx) => {
      const store = tx as any;
      const existing = await store.portfolioStatement.findFirst({ where: { tenantId, idempotencyKey } });
      const persisted = existing ?? await store.portfolioStatement.create({ data: persistenceData });
      const generatedAt = persisted.finalizedAt ?? persisted.createdAt ?? finalizedAt;
      await this.outbox!.append(tx, {
        tenantId,
        aggregateType: 'statement',
        aggregateId: persisted.id,
        eventType: 'statement.generated',
        idempotencyKey: `statement:${persisted.id}:generated`,
        occurredAt: generatedAt,
        payload: {
          statementId: persisted.statementId,
          generatedAt: new Date(generatedAt).toISOString(),
        },
      });
      return persisted;
    });

    this.logger.log({ event: 'portfolio.statement.generated', statementId, tenantId, periodId });

    return statement;
  }

  async getStatement(params: { tenantId: string; statementId: string }): Promise<any | null> {
    return await (this.prisma as any).portfolioStatement.findFirst({
      where: { tenantId: params.tenantId, statementId: params.statementId },
    });
  }

  async listStatements(params: {
    tenantId: string;
    profileId?: string;
    /**
     * Visibility restriction: only statements of these profiles. Applied in the WHERE clause,
     * i.e. BEFORE pagination, so page/limit/total describe the visible rows (filtering a page
     * afterwards produced short or empty pages and a total that counted one page only).
     */
    profileIds?: string[];
    periodId?: string;
    /** PortfolioStatementState; StatementQueryDto validated it but it was never applied. */
    state?: string;
    from?: Date;
    to?: Date;
    page?: number;
    limit?: number;
  }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const { tenantId, profileId, profileIds, periodId, state, from, to, page = 1, limit = 50 } = params;
    const where: any = { tenantId };
    if (profileIds) {
      if (profileId && !profileIds.includes(profileId)) return { data: [], total: 0, page, limit };
      where.profileId = profileId ? profileId : { in: profileIds };
    } else if (profileId) {
      where.profileId = profileId;
    }
    if (periodId) where.periodId = periodId;
    if (state) where.state = state;
    if (from || to) {
      where.createdAt = {};
      if (from) where.createdAt.gte = from;
      if (to) where.createdAt.lte = to;
    }

    const [data, total] = await Promise.all([
      (this.prisma as any).portfolioStatement.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      (this.prisma as any).portfolioStatement.count({ where }),
    ]);
    return { data, total, page, limit };
  }
}

// # Responsibility: calculate portfolio valuation only from verified prices and explicit completeness evidence.
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { AccountingPolicyService } from './accounting-policy.service';
import { PortfolioValuationState, deterministicIdempotencyKey, mul, div, sub, add, ValuationEvidence } from './portfolio-accounting.types';

/**
 * Produces point-in-time portfolio valuation from actual authoritative holdings plus
 * verified market prices via existing market-data sources. Missing, stale, or unavailable
 * market data must produce an explicit valuation state, not fabricated prices or fallback estimates.
 * Missing FX → explicit incomplete state never invent rate/NAV. Missing price → incomplete state never invent.
 * Explicit INCOMPLETE state for MISSING_PRICE, never invent rate/NAV.
 */

@Injectable()
export class ValuationService {
  private readonly logger = new Logger(ValuationService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: AccountingPolicyService,
  ) {}

  async getVerifiedMarketPrice(params: {
    tenantId: string;
    symbol: string;
    asset: string;
    at: Date;
  }): Promise<{ price: string | null; source: string | null; timestamp: Date | null; state: PortfolioValuationState }> {
    const { tenantId, symbol, asset, at } = params;

    // Reuse the existing market-price source: MarketDataRecord candles written by
    // the market-data pipeline. The price at `at` is the close of the latest
    // candle that had closed by then - never a later candle (look-ahead).
    try {
      const candle = await this.prisma.marketDataRecord.findFirst({
        where: { symbol, closeTime: { lte: at } },
        orderBy: { closeTime: 'desc' },
        select: { close: true, closeTime: true, venue: true, interval: true },
      });

      if (candle) {
        // Staleness is measured against the valuation instant, so a historical
        // valuation is not STALE merely for being historical. 5 min threshold -
        // explicit, not hidden; a daily candle is honestly reported as STALE.
        const ageMs = at.getTime() - candle.closeTime.getTime();
        const isStale = ageMs > 5 * 60 * 1000;
        return {
          price: candle.close.toString(),
          source: `MARKET_DATA:${candle.venue}:${candle.interval}`,
          timestamp: candle.closeTime,
          state: isStale ? PortfolioValuationState.STALE : PortfolioValuationState.VALID,
        };
      }

      // No price — explicit incomplete state, never invent rate/NAV
      return { price: null, source: null, timestamp: null, state: PortfolioValuationState.MISSING_PRICE };
    } catch (e) {
      this.logger.warn(`Valuation price fetch failed for ${symbol}: ${(e as Error).message}`);
      return { price: null, source: null, timestamp: null, state: PortfolioValuationState.UNAVAILABLE };
    }
  }

  async getFxRate(params: {
    tenantId: string;
    fromCurrency: string;
    toCurrency: string;
    at: Date;
  }): Promise<{ rate: string | null; source: string | null; timestamp: Date | null; status: string }> {
    const { fromCurrency, toCurrency, at } = params;

    if (fromCurrency === toCurrency) {
      return { rate: '1', source: 'SAME_CURRENCY', timestamp: at, status: 'SAME_CURRENCY' };
    }

    try {
      // Reuse existing FX or market data — check if there's a conversion pair
      const symbol = `${fromCurrency}${toCurrency}`;
      const altSymbol = `${fromCurrency}/${toCurrency}`;
      const reverseSymbol = `${toCurrency}${fromCurrency}`;

      const price = await this.getVerifiedMarketPrice({
        tenantId: params.tenantId,
        symbol,
        asset: fromCurrency,
        at,
      });

      if (price.price) {
        return { rate: price.price, source: price.source, timestamp: price.timestamp, status: 'CONVERTED' };
      }

      // Try reverse
      const reversePrice = await this.getVerifiedMarketPrice({
        tenantId: params.tenantId,
        symbol: reverseSymbol,
        asset: toCurrency,
        at,
      });

      if (reversePrice.price) {
        try {
          const inverted = div('1', reversePrice.price);
          return { rate: inverted, source: reversePrice.source, timestamp: reversePrice.timestamp, status: 'CONVERTED_INVERSE' };
        } catch {
          // fall through to missing
        }
      }

      // Missing FX — explicit incomplete state, never invent rate/NAV
      return { rate: null, source: null, timestamp: null, status: 'MISSING_FX' };
    } catch {
      return { rate: null, source: null, timestamp: null, status: 'MISSING_FX' };
    }
  }

  async valuePosition(params: {
    tenantId: string;
    profileId: string;
    symbol: string;
    asset: string;
    quantity: string;
    at: Date;
    baseCurrency: string;
  }): Promise<{ valuedAmount: string | null; baseCurrencyAmount: string | null; evidence: ValuationEvidence }> {
    const { tenantId, profileId, symbol, asset, quantity, at, baseCurrency } = params;

    const market = await this.getVerifiedMarketPrice({ tenantId, symbol, asset, at });

    if (!market.price) {
      // Missing price — incomplete, not zero
      const evidence: ValuationEvidence = {
        symbol,
        asset,
        quantity,
        marketPrice: null,
        marketPriceSource: null,
        marketPriceTimestamp: null,
        valuationState: market.state,
        conversionRate: null,
        conversionSource: null,
        conversionTimestamp: null,
        conversionStatus: 'MISSING_PRICE',
        baseCurrency,
        valuationTimestamp: at.toISOString(),
        dataCompleteness: `MISSING_PRICE for ${symbol}`,
        sourceReferences: [],
      };

      return { valuedAmount: null, baseCurrencyAmount: null, evidence };
    }

    // Calculate valued amount = quantity * marketPrice
    let valuedAmount: string;
    try {
      valuedAmount = mul(quantity, market.price);
    } catch {
      valuedAmount = '0';
    }

    // Convert to base currency if needed
    let baseCurrencyAmount: string | null = valuedAmount;
    let conversionRate: string | null = null;
    let conversionSource: string | null = null;
    let conversionTimestamp: string | null = null;
    let conversionStatus: string | null = null;

    // Assume market price quoted in USDT/USD — if baseCurrency != quote, need FX
    // For simplicity, assume quote is USDT; if baseCurrency is USD, use 1:1 or FX
    if (baseCurrency !== 'USDT' && baseCurrency !== 'USD') {
      const fx = await this.getFxRate({ tenantId, fromCurrency: 'USDT', toCurrency: baseCurrency, at });
      if (fx.rate) {
        try {
          baseCurrencyAmount = mul(valuedAmount, fx.rate);
          conversionRate = fx.rate;
          conversionSource = fx.source;
          conversionTimestamp = fx.timestamp?.toISOString() ?? null;
          conversionStatus = fx.status;
        } catch {
          baseCurrencyAmount = null;
          conversionStatus = 'CONVERSION_FAILED';
        }
      } else {
        baseCurrencyAmount = null;
        conversionStatus = 'MISSING_FX';
      }
    } else {
      conversionRate = '1';
      conversionSource = 'SAME_CURRENCY';
      conversionTimestamp = at.toISOString();
      conversionStatus = 'SAME_CURRENCY';
    }

    const evidence: ValuationEvidence = {
      symbol,
      asset,
      quantity,
      marketPrice: market.price,
      marketPriceSource: market.source,
      marketPriceTimestamp: market.timestamp?.toISOString() ?? null,
      valuationState: baseCurrencyAmount === null ? PortfolioValuationState.MISSING_FX : market.state,
      conversionRate,
      conversionSource,
      conversionTimestamp,
      conversionStatus,
      baseCurrency,
      valuationTimestamp: at.toISOString(),
      dataCompleteness: baseCurrencyAmount === null ? `MISSING_FX ${baseCurrency}` : market.state === PortfolioValuationState.VALID ? 'COMPLETE' : market.state,
      sourceReferences: [market.source ?? 'UNKNOWN'].filter(Boolean) as string[],
    };

    return { valuedAmount, baseCurrencyAmount, evidence };
  }

  async valuePortfolio(params: {
    tenantId: string;
    profileId: string;
    holdings: Array<{ symbol: string; asset: string; quantity: string }>;
    at: Date;
    baseCurrency: string;
  }): Promise<{
    grossAssetValue: string;
    grossLiability: string;
    netValued: string;
    evidences: ValuationEvidence[];
    completeness: string;
    hasMissingPrice: boolean;
    hasMissingFx: boolean;
    hasStalePrice: boolean;
  }> {
    let grossAssetValue = '0';
    let grossLiability = '0';
    const evidences: ValuationEvidence[] = [];
    let hasMissingPrice = false;
    let hasMissingFx = false;
    let hasStalePrice = false;

    for (const holding of params.holdings) {
      const valuation = await this.valuePosition({
        tenantId: params.tenantId,
        profileId: params.profileId,
        symbol: holding.symbol,
        asset: holding.asset,
        quantity: holding.quantity,
        at: params.at,
        baseCurrency: params.baseCurrency,
      });

      evidences.push(valuation.evidence);

      if (valuation.evidence.valuationState === PortfolioValuationState.MISSING_PRICE) hasMissingPrice = true;
      if (valuation.evidence.valuationState === PortfolioValuationState.MISSING_FX || valuation.evidence.conversionStatus === 'MISSING_FX') hasMissingFx = true;
      if (valuation.evidence.valuationState === PortfolioValuationState.STALE) hasStalePrice = true;

      if (valuation.baseCurrencyAmount) {
        if (valuation.baseCurrencyAmount.startsWith('-')) {
          grossLiability = add(grossLiability, valuation.baseCurrencyAmount.replace('-', ''));
        } else {
          grossAssetValue = add(grossAssetValue, valuation.baseCurrencyAmount);
        }
      }
    }

    const netValued = (() => {
      try {
        return sub(grossAssetValue, grossLiability);
      } catch {
        return grossAssetValue;
      }
    })();

    let completeness = 'COMPLETE';
    if (hasMissingPrice) completeness = 'MISSING_PRICE';
    else if (hasMissingFx) completeness = 'MISSING_FX';
    else if (hasStalePrice) completeness = 'STALE_PRICE';

    return { grossAssetValue, grossLiability, netValued, evidences, completeness, hasMissingPrice, hasMissingFx, hasStalePrice };
  }

  async persistValuation(params: {
    tenantId: string;
    profileId: string;
    symbol: string;
    asset: string;
    quantity: string;
    marketPrice: string | null;
    marketPriceSource: string | null;
    marketPriceTimestamp: Date | null;
    valuationState: PortfolioValuationState;
    valuedAmount: string | null;
    baseCurrency: string;
    baseCurrencyAmount: string | null;
    conversionRate: string | null;
    conversionSource: string | null;
    conversionTimestamp: Date | null;
    conversionStatus: string | null;
    dataCompleteness: string;
    calculationVersion: string;
    policyVersion: string;
    valuationTimestamp: Date;
    sourceReferences?: string[];
    accountingEventId?: string | null;
    /** Currency of valuedAmount (the market price quote currency); defaults to baseCurrency. */
    currency?: string | null;
  }): Promise<any> {
    const idempotencyKey = deterministicIdempotencyKey({
      type: `valuation:${params.symbol}:${params.asset}`,
      tenantId: params.tenantId,
      profileId: params.profileId,
      sourceId: `${params.symbol}:${params.valuationTimestamp.toISOString()}`,
      timestampBucket: params.valuationTimestamp.toISOString().slice(0, 10),
    });

    try {
      const existing = await (this.prisma as any).portfolioValuation.findFirst({ where: { tenantId: params.tenantId, idempotencyKey } });
      if (existing) return existing;
    } catch {}

    try {
      return await (this.prisma as any).portfolioValuation.create({
        data: {
          tenantId: params.tenantId,
          profileId: params.profileId,
          symbol: params.symbol,
          asset: params.asset,
          quantity: params.quantity,
          marketPrice: params.marketPrice,
          marketPriceSource: params.marketPriceSource,
          marketPriceTimestamp: params.marketPriceTimestamp,
          valuationState: params.valuationState as any,
          // Columns: grossValue (+ required currency) and baseCurrencyValue; accountingEventId goes to evidence.
          grossValue: params.valuedAmount,
          currency: params.currency ?? params.baseCurrency,
          baseCurrency: params.baseCurrency,
          baseCurrencyValue: params.baseCurrencyAmount,
          conversionRate: params.conversionRate,
          conversionSource: params.conversionSource,
          conversionTimestamp: params.conversionTimestamp,
          conversionStatus: params.conversionStatus,
          dataCompleteness: params.dataCompleteness,
          calculationVersion: params.calculationVersion,
          policyVersion: params.policyVersion,
          valuationTimestamp: params.valuationTimestamp,
          sourceReferences: params.sourceReferences ?? [],
          evidence: { accountingEventId: params.accountingEventId ?? null } as any,
          idempotencyKey,
        },
      });
    } catch (e) {
      this.logger.warn(`Failed to persist valuation: ${(e as Error).message}`);
      return null;
    }
  }
}

/**
 * Production AML/Sanctions Adapter Bridge
 * Uses existing AML provider interface and selected configured provider.
 * Normalizes screening results and never fabricates CLEAR/BLOCK decisions.
 */

import { Injectable, Logger } from '@nestjs/common';
import { ProviderDomain, ProviderName, ProviderCapability, ProviderResult, NormalizedAmlResult, ProviderErrorCode, ProviderOperationType } from '../../provider.types';
import { ProviderRequestService } from '../../provider-request.service';
import { ProviderObservationService } from '../../provider-observation.service';

export interface AmlScreenInput {
  tenantId: string;
  userId: string;
  jurisdiction: string;
  idempotencyKey: string;
  correlationId: string;
  safeMetadata?: Record<string, unknown>;
}

@Injectable()
export class AmlProductionAdapter {
  private readonly logger = new Logger(AmlProductionAdapter.name);
  readonly provider = ProviderName.AML_GENERIC;
  readonly domain = ProviderDomain.AML;

  readonly capabilities: ProviderCapability[] = [ProviderCapability.AML_SCREEN];

  constructor(
    private readonly requestService: ProviderRequestService,
    private readonly observationService: ProviderObservationService,
  ) {}

  isAvailable(): boolean {
    return !!process.env['AML_PROVIDER_API_KEY'] && !!process.env['AML_PROVIDER_BASE_URL'];
  }

  async screenPerson(input: AmlScreenInput): Promise<ProviderResult<NormalizedAmlResult>> {
    const start = Date.now();

    if (!this.isAvailable()) {
      return {
        success: true,
        provider: this.provider,
        domain: this.domain,
        data: {
          providerReference: `aml_pending_${input.userId}_${Date.now()}`,
          status: 'PENDING',
          decision: 'REVIEW_REQUIRED',
          riskLevel: 'UNKNOWN',
          matchedLists: [],
          reasonCode: 'PROVIDER_UNAVAILABLE',
          timestamp: new Date().toISOString(),
          safeMetadata: {
            tenantId: input.tenantId,
            userId: input.userId,
            jurisdiction: input.jurisdiction,
            providerUnavailable: true,
          },
        },
        correlationId: input.correlationId,
        timestamp: new Date().toISOString(),
        latencyMs: Date.now() - start,
      };
    }

    const baseUrl = process.env['AML_PROVIDER_BASE_URL']!;
    const apiKey = process.env['AML_PROVIDER_API_KEY']!;

    try {
      const response = await this.requestService.requestWithRetry<any>({
        method: 'POST',
        url: `${baseUrl}/v1/screening/person`,
        headers: {
          'Authorization': `Bearer ${apiKey}`,
          'Content-Type': 'application/json',
        },
        body: {
          userId: input.userId,
          jurisdiction: input.jurisdiction,
          idempotencyKey: input.idempotencyKey,
          metadata: input.safeMetadata || {},
        },
        correlationId: input.correlationId,
        domain: this.domain,
        provider: this.provider,
        operation: ProviderOperationType.CREATE,
        tenantId: input.tenantId,
        isIdempotent: true,
        idempotencyKey: input.idempotencyKey,
      });

      const data = response.data;

      const normalized: NormalizedAmlResult = {
        providerReference: data.id || data.reference || `aml_${Date.now()}`,
        status: this.normalizeStatus(data.status),
        decision: this.normalizeDecision(data.status, data.riskLevel),
        riskLevel: data.riskLevel || 'UNKNOWN',
        matchedLists: data.matchedLists || [],
        reasonCode: data.reasonCode || null,
        timestamp: new Date().toISOString(),
        safeMetadata: {
          tenantId: input.tenantId,
          userId: input.userId,
          providerStatus: data.status,
        },
      };

      await this.observationService.record({
        provider: this.provider,
        domain: this.domain,
        operation: ProviderOperationType.CREATE,
        correlationId: input.correlationId,
        idempotencyKey: input.idempotencyKey,
        tenantId: input.tenantId,
        userId: input.userId,
        providerReference: normalized.providerReference,
        status: normalized.status,
        safeEvidence: {
          tenantId: input.tenantId,
          status: normalized.status,
          decision: normalized.decision,
        },
      });

      return {
        success: true,
        provider: this.provider,
        domain: this.domain,
        data: normalized,
        correlationId: input.correlationId,
        providerReference: normalized.providerReference,
        timestamp: new Date().toISOString(),
        latencyMs: response.latencyMs,
        rawStatus: data.status,
      };
    } catch (error) {
      const normalizedErr = error as any;
      const err = normalizedErr.code ? normalizedErr : this.requestService.normalizeError(error as Error, this.provider, this.domain, input.correlationId);

      if (err.code === ProviderErrorCode.PROVIDER_UNAVAILABLE || err.code === ProviderErrorCode.NOT_CONFIGURED) {
        return {
          success: true,
          provider: this.provider,
          domain: this.domain,
          data: {
            providerReference: `aml_pending_${input.userId}_${Date.now()}`,
            status: 'PENDING',
            decision: 'REVIEW_REQUIRED',
            riskLevel: 'UNKNOWN',
            matchedLists: [],
            reasonCode: 'PROVIDER_UNAVAILABLE',
            timestamp: new Date().toISOString(),
            safeMetadata: { tenantId: input.tenantId, userId: input.userId, providerUnavailable: true },
          },
          correlationId: input.correlationId,
          timestamp: new Date().toISOString(),
          latencyMs: Date.now() - start,
        };
      }

      return {
        success: false,
        provider: this.provider,
        domain: this.domain,
        error: err as any,
        correlationId: input.correlationId,
        timestamp: new Date().toISOString(),
        latencyMs: Date.now() - start,
      };
    }
  }

  private normalizeStatus(providerStatus: string): string {
    const status = (providerStatus || '').toLowerCase();
    if (['clear', 'no_match', 'clean', 'passed'].includes(status)) return 'CLEAR';
    if (['blocked', 'match', 'hit', 'denied'].includes(status)) return 'BLOCKED';
    if (['potential_match', 'review', 'manual_review'].includes(status)) return 'REVIEW';
    if (['pending', 'processing'].includes(status)) return 'PENDING';
    return 'PENDING';
  }

  private normalizeDecision(providerStatus: string, riskLevel?: string): string {
    const status = (providerStatus || '').toLowerCase();
    if (['clear', 'no_match', 'clean', 'passed'].includes(status)) return 'ALLOW';
    if (['blocked', 'match', 'hit', 'denied'].includes(status)) return 'BLOCK';
    return 'REVIEW_REQUIRED';
  }
}

