@Injectable()
export class MarketDataProviderFactory {
  private readonly logger = new Logger(MarketDataProviderFactory.name);
  private readonly providers: Map<string, IMarketDataProvider> = new Map();

  constructor() {
    const providers: IMarketDataProvider[] = [
      new BinancePublicDataProvider(),
      new BybitMarketDataProvider(),
      new OkxMarketDataProvider(),
      new KrakenMarketDataProvider(),
      new PaperMarketDataProvider(),
      new LocalFileDataProvider(),
      new HistoricalDatasetProvider(),
    ];

    for (const provider of providers) {
      this.providers.set(provider.getName(), provider);
    }

    this.logger.log(`Market data providers initialized: ${Array.from(this.providers.keys()).join(', ')}`);
  }

  getProvider(name: string): IMarketDataProvider {
    const provider = this.providers.get(name);
    if (!provider) {
      throw new Error(
        `Market data provider ${name} not found. Available: ${Array.from(this.providers.keys()).join(', ')} - ` +
        `no fallback to fabricated data. Historical data must come from explicit source/provider abstraction.`
      );
    }
    return provider;
  }

  getDefaultProvider(): IMarketDataProvider {
    return this.providers.get('HISTORICAL_DATASET') || this.providers.get('BINANCE_PUBLIC_DATA') || this.providers.get('LOCAL_FILES')!;
  }

  listProviders(): { name: string; venues: string[]; timeframes: string[] }[] {
    return Array.from(this.providers.values()).map(p => ({ 
      name: p.getName(), 
      venues: p.getSupportedVenues(), 
      timeframes: p.getSupportedTimeframes() 
    }));
  }

  async selectProviderForRequest(params: { venue: string; symbol: string; timeframe: string; preferredProvider?: string }): Promise<IMarketDataProvider> {
    if (params.preferredProvider) {
      const provider = this.getProvider(params.preferredProvider);
      const supported = await provider.isSymbolSupported(params.venue, params.symbol);
      if (!supported) {
        throw new Error(`Symbol ${params.symbol} not supported by provider ${provider.getName()} for venue ${params.venue} - fail clearly`);
      }
      if (!provider.getSupportedVenues().includes(params.venue)) {
        throw new Error(`Venue ${params.venue} not supported by provider ${provider.getName()} - available: ${provider.getSupportedVenues().join(', ')}`);
      }
      if (!provider.getSupportedTimeframes().includes(params.timeframe)) {
        throw new Error(`Timeframe ${params.timeframe} not supported by provider ${provider.getName()} - available: ${provider.getSupportedTimeframes().join(', ')}`);
      }
      return provider;
    }

    // Auto-select first provider supporting venue/timeframe
    for (const provider of this.providers.values()) {
      if (provider.getSupportedVenues().includes(params.venue) && provider.getSupportedTimeframes().includes(params.timeframe)) {
        if (await provider.isSymbolSupported(params.venue, params.symbol)) {
          this.logger.log(`Auto-selected provider ${provider.getName()} for ${params.venue}/${params.symbol}/${params.timeframe}`);
          return provider;
        }
      }
    }

    throw new Error(
      `No market data provider supports venue=${params.venue} symbol=${params.symbol} timeframe=${params.timeframe} - ` +
      `data unavailable, fail clearly. Track timeframe/exchange/symbol/timezone/source. ` +
      `Available providers: ${Array.from(this.providers.keys()).join(', ')}`
    );
  }

  async getAvailableProvidersForVenue(venue: string): Promise<IMarketDataProvider[]> {
    const available: IMarketDataProvider[] = [];
    for (const provider of this.providers.values()) {
      if (provider.getSupportedVenues().includes(venue)) {
        available.push(provider);
      }
    }
    return available;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { MarketDataProviderFactory } from './market-data-provider.factory';
import { Candle, HistoricalRange } from './market-data-provider.interface';
import { createHash } from 'crypto';

/**
 * Historical market-data retrieval, normalization, gap detection, deduplication, pagination, and dataset fingerprinting.
 */
@Injectable()
export class MarketDataService {
  private readonly logger = new Logger(MarketDataService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly providerFactory: MarketDataProviderFactory,
  ) {}

  private normalizeSymbol(symbol: string): string {
    return symbol.trim().toUpperCase().replace('/', '-');
  }

  private normalizeTimestamp(ts: string): string {
    const d = new Date(ts);
    if (isNaN(d.getTime())) throw new Error(`Invalid timestamp ${ts}`);
    return d.toISOString();
  }

  private fingerprintDataset(params: { venue: string; symbol: string; timeframe: string; startTime: string; endTime: string; source: string; candles: Candle[] }): string {
    const hash = createHash('sha256');
    hash.update(`${params.venue}|${params.symbol}|${params.timeframe}|${params.startTime}|${params.endTime}|${params.source}|${params.candles.length}`);
    for (const c of params.candles.slice(0, 100)) {
      hash.update(`${c.openTime}|${c.closeTime}|${c.open}|${c.high}|${c.low}|${c.close}|${c.volume}`);
    }
    return hash.digest('hex');
  }

  async getCandles(params: { tenantId: string; venue: string; symbol: string; timeframe: string; startTime: string; endTime: string; source?: string; limit?: number }): Promise<{ candles: Candle[]; fingerprint: string; source: string; completeness: string; range: HistoricalRange }> {
    const normalizedSymbol = this.normalizeSymbol(params.symbol);
    const startTime = this.normalizeTimestamp(params.startTime);
    const endTime = this.normalizeTimestamp(params.endTime);

    // First try existing HistoricalDataset storage if available
    try {
      const dataset = await this.prisma.historicalDataset.findFirst({
        where: { venue: params.venue as any, symbols: { has: normalizedSymbol }, granularity: params.timeframe },
        orderBy: { createdAt: 'desc' },
        include: { versions: { where: { status: 'VALID' }, orderBy: { version: 'desc' }, take: 1 } },
      });

      if (dataset && dataset.versions.length > 0) {
        // In real implementation, would read files from storage
        this.logger.log(`Found existing dataset ${dataset.datasetKey} for ${params.venue}/${normalizedSymbol}/${params.timeframe}`);
        // For now, we still need to fetch via provider abstraction
      }
    } catch {}

    // Use provider factory
    const provider = await this.providerFactory.selectProviderForRequest({ venue: params.venue, symbol: normalizedSymbol, timeframe: params.timeframe, preferredProvider: params.source });

    // Attempt to retrieve - provider may throw explicit unavailable error
    try {
      const result = await provider.getCandles({ venue: params.venue, symbol: normalizedSymbol, timeframe: params.timeframe, startTime, endTime, limit: params.limit });

      // Deduplicate records
      const deduped = this.deduplicateCandles(result.data);

      // Normalize timestamps
      const normalized = deduped.map(c => ({ ...c, openTime: this.normalizeTimestamp(c.openTime), closeTime: this.normalizeTimestamp(c.closeTime), symbol: this.normalizeSymbol(c.symbol) }));

      const fingerprint = this.fingerprintDataset({ venue: params.venue, symbol: normalizedSymbol, timeframe: params.timeframe, startTime, endTime, source: result.source, candles: normalized });

      const range: HistoricalRange = {
        venue: params.venue,
        symbol: normalizedSymbol,
        timeframe: params.timeframe,
        startTime,
        endTime,
        source: result.source,
        dataTimestamp: result.dataTimestamp,
        completeness: result.completeness,
        recordCount: normalized.length,
        firstRecordTime: normalized[0]?.openTime || null,
        lastRecordTime: normalized[normalized.length-1]?.openTime || null,
      };

      return { candles: normalized, fingerprint, source: result.source, completeness: result.completeness, range };
    } catch (e: any) {
      // Explicit failure - do not manufacture missing data
      this.logger.warn(`Market data unavailable tenant=${params.tenantId} venue=${params.venue} symbol=${normalizedSymbol} timeframe=${params.timeframe} error=${e.message}`);
      throw new Error(`Historical market data unavailable for ${params.venue}/${normalizedSymbol}/${params.timeframe} from ${startTime} to ${endTime}: ${e.message}. If required market data is unavailable, fail clearly.`);
    }
  }

  private deduplicateCandles(candles: Candle[]): Candle[] {
    const seen = new Map<string, Candle>();
    for (const c of candles) {
      const key = `${c.symbol}|${c.timeframe}|${c.openTime}`;
      if (!seen.has(key)) seen.set(key, c);
    }
    return Array.from(seen.values()).sort((a,b) => new Date(a.openTime).getTime() - new Date(b.openTime).getTime());
  }

  async detectGaps(candles: Candle[], timeframe: string): Promise<{ gaps: { start: string; end: string; missingCount: number }[]; gapPercentage: number }> {
    if (candles.length < 2) return { gaps: [], gapPercentage: 0 };

    const timeframeMs = this.timeframeToMs(timeframe);
    const gaps: { start: string; end: string; missingCount: number }[] = [];

    for (let i=1; i<candles.length; i++) {
      const prev = new Date(candles[i-1].closeTime).getTime();
      const curr = new Date(candles[i].openTime).getTime();
      const diff = curr - prev;
      if (diff > timeframeMs * 1.5) {
        const missing = Math.floor(diff / timeframeMs) - 1;
        gaps.push({ start: candles[i-1].closeTime, end: candles[i].openTime, missingCount: missing });
      }
    }

    const totalExpected = Math.floor((new Date(candles[candles.length-1].openTime).getTime() - new Date(candles[0].openTime).getTime()) / timeframeMs) + 1;
    const gapPercentage = totalExpected > 0 ? (gaps.reduce((s,g)=>s+g.missingCount,0) / totalExpected) * 100 : 0;

    return { gaps, gapPercentage };
  }

  private timeframeToMs(tf: string): number {
    const map: Record<string, number> = {
      '1m': 60*1000,
      '3m': 3*60*1000,
      '5m': 5*60*1000,
      '15m': 15*60*1000,
      '30m': 30*60*1000,
      '1h': 60*60*1000,
      '2h': 2*60*60*1000,
      '4h': 4*60*60*1000,
      '6h': 6*60*60*1000,
      '8h': 8*60*60*1000,
      '12h': 12*60*60*1000,
      '1d': 24*60*60*1000,
      '3d': 3*24*60*60*1000,
      '1w': 7*24*60*60*1000,
    };
    return map[tf] || 60*1000;
  }

  async getAvailableRange(params: { venue: string; symbol: string; timeframe: string }): Promise<HistoricalRange | null> {
    try {
      const provider = await this.providerFactory.selectProviderForRequest(params);
      return provider.getAvailableRange(params);
    } catch {
      return null;
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { BacktestRepository } from './backtest-repository';
import { ResearchRepository } from './research-repository';
import { ResearchPolicyService } from './research-policy.service';
import { randomUUID } from 'crypto';

/**
 * Runs configurable Monte Carlo/resampling analysis from actual backtest trades/returns without claiming probabilistic certainty.
 * Clearly label results as simulation/analysis. Do not present Monte Carlo outputs as guaranteed probabilities of future performance.
 */
@Injectable()
export class MonteCarloService {
  private readonly logger = new Logger(MonteCarloService.name);

  constructor(
    private readonly backtestRepo: BacktestRepository,
    private readonly researchRepo: ResearchRepository,
    private readonly policyService: ResearchPolicyService,
  ) {}

  private seededRandom(seed: string): () => number {
    let hash = 0;
    for (let i=0; i<seed.length; i++) hash = ((hash << 5) - hash) + seed.charCodeAt(i);
    return () => {
      hash = (hash * 1664525 + 1013904223) % 4294967296;
      return (hash / 4294967296 + 1) / 2;
    };
  }

  async runMonteCarlo(input: {
    tenantId: string;
    backtestRunId: string;
    iterations: number;
    method: 'TRADE_ORDER_PERMUTATION' | 'RETURN_RESAMPLING' | 'DRAWDOWN_DISTRIBUTION';
    seed?: string | null;
    createdBy?: string | null;
    idempotencyKey?: string | null;
  }): Promise<{ percentiles: Record<string, string>; distribution: string[]; summary: Record<string, any> }> {
    const policy = await this.policyService.getPolicy(input.tenantId);
    if (input.iterations > policy.maxMonteCarloIterations) throw new Error(`Iterations ${input.iterations} exceeds max ${policy.maxMonteCarloIterations}`);
    if (input.iterations <= 0) throw new Error('Iterations must be positive');

    const backtestRun = await this.backtestRepo.findById(input.backtestRunId, input.tenantId);
    if (!backtestRun) throw new Error(`Backtest run ${input.backtestRunId} not found`);

    const tradesResult = await this.backtestRepo.listTrades(input.tenantId, input.backtestRunId, { page: 1, limit: 10000 });
    const trades = tradesResult.data;

    if (trades.length === 0) throw new Error('No trades available for Monte Carlo analysis');

    const seed = input.seed || randomUUID();
    const random = this.seededRandom(seed);

    const distribution: number[] = [];

    for (let i=0; i<input.iterations; i++) {
      let simulatedPnl = 0;

      if (input.method === 'TRADE_ORDER_PERMUTATION') {
        // Shuffle trade order
        const shuffled = [...trades].sort(() => random() - 0.5);
        for (const trade of shuffled) {
          const pnl = trade.netPnl ? parseFloat(trade.netPnl) : (trade.grossPnl ? parseFloat(trade.grossPnl) - parseFloat(trade.fee) : 0);
          simulatedPnl += pnl;
        }
      } else if (input.method === 'RETURN_RESAMPLING') {
        // Resample returns with replacement
        for (let j=0; j<trades.length; j++) {
          const idx = Math.floor(random() * trades.length);
          const trade = trades[idx];
          const pnl = trade.netPnl ? parseFloat(trade.netPnl) : 0;
          simulatedPnl += pnl;
        }
      } else if (input.method === 'DRAWDOWN_DISTRIBUTION') {
        // Simulate drawdown by cumulative sum of shuffled trades
        const shuffled = [...trades].sort(() => random() - 0.5);
        let peak = 0;
        let current = 0;
        let maxDd = 0;
        for (const trade of shuffled) {
          const pnl = trade.netPnl ? parseFloat(trade.netPnl) : 0;
          current += pnl;
          if (current > peak) peak = current;
          const dd = peak - current;
          if (dd > maxDd) maxDd = dd;
        }
        simulatedPnl = maxDd; // For drawdown distribution, we track max drawdown
      }

      distribution.push(simulatedPnl);
    }

    distribution.sort((a,b)=>a-b);

    const percentiles: Record<string, string> = {
      '5': distribution[Math.floor(distribution.length * 0.05)]?.toString() || '0',
      '25': distribution[Math.floor(distribution.length * 0.25)]?.toString() || '0',
      '50': distribution[Math.floor(distribution.length * 0.5)]?.toString() || '0',
      '75': distribution[Math.floor(distribution.length * 0.75)]?.toString() || '0',
      '95': distribution[Math.floor(distribution.length * 0.95)]?.toString() || '0',
      '99': distribution[Math.floor(distribution.length * 0.99)]?.toString() || '0',
    };

    const summary = {
      method: input.method,
      iterations: input.iterations,
      seed,
      tradeCount: trades.length,
      originalPnl: trades.reduce((s,t)=>s+(t.netPnl ? parseFloat(t.netPnl) : 0),0).toString(),
      mean: (distribution.reduce((a,b)=>a+b,0) / distribution.length).toString(),
      median: percentiles['50'],
      min: Math.min(...distribution).toString(),
      max: Math.max(...distribution).toString(),
      disclaimer: 'Monte Carlo simulation/analysis from actual backtest trades. Results are simulation, not guaranteed probabilities of future performance. Methodology: ' + input.method,
      isSimulated: true,
      isReproducible: !!input.seed,
    };

    await this.researchRepo.createAuditLog({
      tenantId: input.tenantId,
      event: 'MONTE_CARLO_COMPLETED',
      actorId: input.createdBy || null,
      backtestRunId: input.backtestRunId,
      result: 'SUCCESS',
      safeMetadata: { method: input.method, iterations: input.iterations, seed, tradeCount: trades.length },
    });

    this.logger.log(`Monte Carlo completed tenant=${input.tenantId} backtest=${input.backtestRunId} method=${input.method} iterations=${input.iterations} seed=${seed}`);

    return { percentiles, distribution: distribution.map(d=>d.toString()), summary };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PaperTradingRepository } from './paper-trading-repository';
import { ResearchRepository } from './research-repository';
import { BacktestExecutionModelService } from './backtest-execution-model.service';
import { randomUUID } from 'crypto';

/**
 * Creates and advances paper orders/fills with deterministic simulation state and isolated paper-trading persistence.
 * Never write paper orders into live order records.
 */
@Injectable()
export class PaperOrderService {
  private readonly logger = new Logger(PaperOrderService.name);

  constructor(
    private readonly paperRepo: PaperTradingRepository,
    private readonly researchRepo: ResearchRepository,
    private readonly executionModel: BacktestExecutionModelService,
  ) {}

  async createPaperOrder(input: {
    tenantId: string;
    sessionId: string;
    symbol: string;
    side: 'BUY' | 'SELL';
    type: 'MARKET' | 'LIMIT' | 'STOP' | 'STOP_LIMIT';
    quantity: string;
    price?: string | null;
    stopPrice?: string | null;
    createdBy?: string | null;
    idempotencyKey?: string | null;
  }): Promise<any> {
    const session = await this.paperRepo.findSessionById(input.sessionId, input.tenantId);
    if (!session) throw new Error(`Paper session ${input.sessionId} not found`);
    if (session.status !== 'RUNNING') throw new Error(`Paper session must be RUNNING to create orders, current=${session.status}`);

    if (!/^-?\d+(\.\d+)?$/.test(input.quantity)) throw new Error('quantity must be valid decimal string');
    if (parseFloat(input.quantity) <= 0) throw new Error('quantity must be positive');

    if (input.type !== 'MARKET' && input.price && !/^-?\d+(\.\d+)?$/.test(input.price)) throw new Error('price must be valid decimal string');

    const orderId = `paper_order_${randomUUID().substring(0,12)}_${Date.now()}`;
    const clientOrderId = `paper_client_${randomUUID().substring(0,12)}_${Date.now()}`;

    const order = await this.paperRepo.createPaperOrder({
      tenantId: input.tenantId,
      sessionId: input.sessionId,
      orderId,
      clientOrderId,
      symbol: input.symbol,
      side: input.side,
      type: input.type,
      quantity: input.quantity,
      price: input.price || null,
      stopPrice: input.stopPrice || null,
      status: 'PENDING',
      idempotencyKey: input.idempotencyKey || null,
    });

    this.logger.log(`Paper order created tenant=${input.tenantId} session=${input.sessionId} orderId=${orderId} PAPER_SIMULATION`);

    return order;
  }

  async simulateFill(input: {
    tenantId: string;
    sessionId: string;
    orderId: string;
    marketPrice: string;
    timestamp?: Date;
  }): Promise<any | null> {
    const order = await this.paperRepo.findPaperOrderById(input.orderId, input.tenantId);
    if (!order) throw new Error(`Paper order ${input.orderId} not found`);
    if (order.sessionId !== input.sessionId) throw new Error('Order does not belong to session');

    if (['FILLED','CANCELLED','REJECTED','EXPIRED'].includes(order.status)) throw new Error(`Order already ${order.status}`);

    const symbolMeta = await this.executionModel.getSymbolMetadata(input.tenantId, order.symbol);

    // Use execution model to simulate fill
    const executionResult = await this.executionModel.simulateOrderExecution({
      tenantId: input.tenantId,
      order: {
        orderId: order.orderId,
        clientOrderId: order.clientOrderId,
        symbol: order.symbol,
        side: order.side,
        type: order.type,
        quantity: order.quantity,
        price: order.price,
        stopPrice: order.stopPrice,
        timestamp: new Date().toISOString(),
        status: 'PENDING',
      },
      candle: {
        open: input.marketPrice,
        high: input.marketPrice,
        low: input.marketPrice,
        close: input.marketPrice,
        openTime: new Date().toISOString(),
        closeTime: new Date().toISOString(),
      },
      assumptions: {
        fee: { makerFeeRate: '0.001', takerFeeRate: '0.001' },
        slippage: { slippageBps: 5, slippageModel: 'FIXED' },
        latency: { latencyMs: 100 },
        execution: { type: 'MARKET', partialFills: true, minQuantity: null, tickSize: null, quantityStep: null, minNotional: null },
      },
      symbolMetadata: symbolMeta,
    });

    if (executionResult.rejected) {
      await this.paperRepo.updatePaperOrderStatus(order.orderId, input.tenantId, 'REJECTED');
      return null;
    }

    if (!executionResult.fill) return null;

    // Create fill in paper fill table - never live order/fill records
    const fill = await this.paperRepo.createPaperFill({
      tenantId: input.tenantId,
      sessionId: input.sessionId,
      orderId: order.orderId,
      fillId: executionResult.fill.fillId,
      tradeId: `trade_${randomUUID().substring(0,8)}`,
      symbol: order.symbol,
      side: order.side,
      quantity: executionResult.fill.quantity,
      price: executionResult.fill.price,
      fee: executionResult.fill.fee,
      isMaker: executionResult.fill.isMaker,
      timestamp: input.timestamp || new Date(),
    });

    // Update order as filled
    await this.paperRepo.updatePaperOrderStatus(order.orderId, input.tenantId, 'FILLED', {
      filledQuantity: executionResult.fill.quantity,
      averageFillPrice: executionResult.fill.price,
      fee: executionResult.fill.fee,
    });

    // Update session equity - simplified
    try {
      const session = await this.paperRepo.findSessionById(input.sessionId, input.tenantId);
      if (session) {
        const currentEquity = parseFloat(session.currentEquity || session.initialCapital);
        const fee = parseFloat(executionResult.fill.fee);
        // Simplified: just subtract fee for now
        const newEquity = (currentEquity - fee).toString();
        await this.paperRepo.updateSessionStatus(session.id, input.tenantId, session.status, { currentEquity: newEquity, feesPaid: (parseFloat(session.feesPaid) + fee).toString() });
      }
    } catch {}

    this.logger.log(`Paper order filled tenant=${input.tenantId} orderId=${order.orderId} fillId=${fill.fillId} price=${executionResult.fill.price} PAPER_SIMULATION`);

    return fill;
  }

  async cancelOrder(tenantId: string, sessionId: string, orderId: string): Promise<any | null> {
    const order = await this.paperRepo.findPaperOrderById(orderId, tenantId);
    if (!order) return null;
    if (order.sessionId !== sessionId) throw new Error('Order does not belong to session');
    if (['FILLED','CANCELLED','REJECTED'].includes(order.status)) throw new Error(`Order already ${order.status}`);

    return this.paperRepo.updatePaperOrderStatus(orderId, tenantId, 'CANCELLED');
  }

  async listOrders(tenantId: string, sessionId: string, filters?: { status?: string; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    return this.paperRepo.listPaperOrders(tenantId, sessionId, filters);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PaperTradingRepository } from './paper-trading-repository';

/**
 * Aggregates paper session performance from simulated portfolio/order/fill records and exposes ACTUAL_SIMULATION status, never live performance.
 * Every result must clearly identify PAPER_SIMULATION
 */
@Injectable()
export class PaperPerformanceService {
  private readonly logger = new Logger(PaperPerformanceService.name);

  constructor(private readonly paperRepo: PaperTradingRepository) {}

  async getPerformance(tenantId: string, sessionId: string): Promise<{
    sessionId: string;
    tenantId: string;
    initialCapital: string;
    currentEquity: string | null;
    realizedPnl: string;
    unrealizedPnl: string | null;
    totalReturn: string | null;
    totalReturnPercent: string | null;
    maxDrawdown: string | null;
    maxDrawdownPercent: string | null;
    tradeCount: number;
    winCount: number;
    lossCount: number;
    winRate: string | null;
    feesPaid: string;
    exposure: string | null;
    isSimulated: true;
    status: string;
    disclaimer: string;
    source: string;
  } | null> {
    const session = await this.paperRepo.findSessionById(sessionId, tenantId);
    if (!session) return null;

    const fillsResult = await this.paperRepo.listPaperFills(tenantId, sessionId, { page: 1, limit: 10000 });
    const fills = fillsResult.data;

    const snapshots = await this.paperRepo.listSnapshots(tenantId, sessionId);

    const initial = parseFloat(session.initialCapital);
    const current = session.currentEquity ? parseFloat(session.currentEquity) : initial;

    const totalReturn = (current - initial).toString();
    const totalReturnPercent = initial > 0 ? (((current / initial) - 1) * 100).toString() : null;

    // Calculate win/loss from fills - pair buys and sells FIFO
    let winCount = 0;
    let lossCount = 0;
    let realizedPnl = 0;

    const buys: { qty: number; price: number; cost: number }[] = [];

    for (const fill of fills.sort((a:any,b:any) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime())) {
      const qty = parseFloat(fill.quantity);
      const price = parseFloat(fill.price);
      const fee = parseFloat(fill.fee || '0');
      const notional = qty * price;

      if (fill.side === 'BUY') {
        buys.push({ qty, price, cost: notional + fee });
      } else {
        let remainingSellQty = qty;
        let tradePnl = 0;
        while (remainingSellQty > 0 && buys.length > 0) {
          const buy = buys[0];
          const matchedQty = Math.min(remainingSellQty, buy.qty);
          const buyCost = (buy.cost / buy.qty) * matchedQty;
          const sellProceeds = (notional / qty) * matchedQty;
          const pnl = sellProceeds - buyCost - fee;
          tradePnl += pnl;
          realizedPnl += pnl;

          buy.qty -= matchedQty;
          if (buy.qty <= 0.00000001) buys.shift();
          else buy.cost -= buyCost;

          remainingSellQty -= matchedQty;
        }

        if (tradePnl > 0) winCount++;
        else if (tradePnl < 0) lossCount++;
      }
    }

    const tradeCount = winCount + lossCount;
    const winRate = tradeCount > 0 ? (winCount / tradeCount).toString() : null;

    // Max drawdown from snapshots
    let maxDrawdown: string | null = null;
    let maxDrawdownPercent: string | null = null;
    if (snapshots.length > 0) {
      let peak = initial;
      let maxDd = 0;
      let maxDdPercent = 0;
      for (const snap of snapshots) {
        const eq = parseFloat(snap.equity);
        if (eq > peak) peak = eq;
        const dd = peak - eq;
        if (dd > maxDd) {
          maxDd = dd;
          maxDdPercent = peak > 0 ? (dd / peak) * 100 : 0;
        }
      }
      if (maxDd > 0) {
        maxDrawdown = maxDd.toString();
        maxDrawdownPercent = maxDdPercent.toString();
      }
    }

    return {
      sessionId,
      tenantId,
      initialCapital: session.initialCapital,
      currentEquity: session.currentEquity || null,
      realizedPnl: session.realizedPnl || realizedPnl.toString(),
      unrealizedPnl: session.unrealizedPnl || null,
      totalReturn,
      totalReturnPercent,
      maxDrawdown,
      maxDrawdownPercent,
      tradeCount,
      winCount,
      lossCount,
      winRate,
      feesPaid: session.feesPaid || '0',
      exposure: null,
      isSimulated: true,
      status: 'PAPER_SIMULATION',
      disclaimer: 'PAPER_SIMULATION: This is simulated paper trading performance, not live performance. Paper performance is not indicative of live performance; simulation does not guarantee real execution quality.',
      source: 'PAPER_TRADING',
    };
  }

  async getEquityCurve(tenantId: string, sessionId: string): Promise<any[]> {
    const snapshots = await this.paperRepo.listSnapshots(tenantId, sessionId);
    return snapshots.map((s:any) => ({
      timestamp: new Date(s.timestamp).toISOString(),
      sequence: s.sequence,
      equity: s.equity,
      cash: s.cash,
      realizedPnl: s.realizedPnl,
      unrealizedPnl: s.unrealizedPnl,
      drawdown: s.drawdown,
      isSimulated: true,
    }));
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { randomUUID } from 'crypto';
import { isRecordNotFound } from '../../common/errors/prisma-not-found';

/**
 * Persistence abstraction for paper sessions, paper orders, paper fills, portfolio snapshots, and session lifecycle.
 * Keep paper data separated from live trading data.
 */
@Injectable()
export class PaperTradingRepository {
  private readonly logger = new Logger(PaperTradingRepository.name);

  constructor(private readonly prisma: PrismaService) {}

  async createSession(input: {
    tenantId: string;
    strategyVersionId: string;
    sessionIdentifier: string;
    config?: Record<string, any>;
    initialCapital: string;
    symbols?: string[];
    timeframe?: string;
    expiresAt?: Date | null;
    createdBy?: string | null;
    idempotencyKey?: string | null;
  }): Promise<any> {
    if (input.idempotencyKey) {
      const existing = await (this.prisma as any).researchPaperSession.findFirst({ where: { tenantId: input.tenantId, idempotencyKey: input.idempotencyKey } });
      if (existing) return existing;
    }

    const existingByIdentifier = await (this.prisma as any).researchPaperSession.findFirst({ where: { tenantId: input.tenantId, sessionIdentifier: input.sessionIdentifier } });
    if (existingByIdentifier) return existingByIdentifier;

    const id = randomUUID();
    const data = {
      id,
      tenantId: input.tenantId,
      strategyVersionId: input.strategyVersionId,
      status: 'CREATED',
      sessionIdentifier: input.sessionIdentifier,
      config: input.config || {},
      initialCapital: input.initialCapital,
      currentEquity: input.initialCapital,
      symbols: input.symbols || [],
      timeframe: input.timeframe || '1m',
      realizedPnl: '0',
      unrealizedPnl: null,
      maxDrawdown: null,
      feesPaid: '0',
      isSimulated: true,
      expiresAt: input.expiresAt || null,
      idempotencyKey: input.idempotencyKey || null,
      createdBy: input.createdBy || null,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    try {
      const created = await (this.prisma as any).researchPaperSession.create({ data });
      this.logger.log(`Paper session created id=${created.id} tenant=${input.tenantId} identifier=${input.sessionIdentifier}`);
      return created;
    } catch (e: any) {
      if (e.code === 'P2002') {
        const existing = await (this.prisma as any).researchPaperSession.findFirst({ where: { tenantId: input.tenantId, sessionIdentifier: input.sessionIdentifier } });
        if (existing) return existing;
      }
      throw e;
    }
  }

  async findSessionById(id: string, tenantId: string): Promise<any | null> {
    return (this.prisma as any).researchPaperSession.findFirst({ where: { id, tenantId } }) || null;
  }

  async findSessionByIdentifier(tenantId: string, sessionIdentifier: string): Promise<any | null> {
    return (this.prisma as any).researchPaperSession.findFirst({ where: { tenantId, sessionIdentifier } }) || null;
  }

  async listSessions(tenantId: string, filters?: { strategyVersionId?: string; status?: string; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const skip = (page - 1) * limit;
    const where: any = { tenantId, ...(filters?.strategyVersionId ? { strategyVersionId: filters.strategyVersionId } : {}), ...(filters?.status ? { status: filters.status } : {}) };
    const [data, total] = await Promise.all([
      (this.prisma as any).researchPaperSession.findMany({ where, orderBy: { createdAt: 'desc' }, skip, take: limit }),
      (this.prisma as any).researchPaperSession.count({ where }),
    ]);
    return { data, total };
  }

  async updateSessionStatus(id: string, tenantId: string, status: string, extra?: { startedAt?: Date; stoppedAt?: Date; currentEquity?: string; realizedPnl?: string; unrealizedPnl?: string | null; maxDrawdown?: string | null; feesPaid?: string }): Promise<any | null> {
    try {
      return await (this.prisma as any).researchPaperSession.update({ where: { id, tenantId }, data: { status, ...extra, updatedAt: new Date() } });
    } catch (error) {
      if (isRecordNotFound(error)) return null;
      throw error;
    }
  }

  // Paper Orders - Never write paper orders into live order records
  async createPaperOrder(input: {
    tenantId: string;
    sessionId: string;
    orderId: string;
    clientOrderId: string;
    symbol: string;
    side: string;
    type: string;
    quantity: string;
    price?: string | null;
    stopPrice?: string | null;
    status?: string;
    idempotencyKey?: string | null;
  }): Promise<any> {
    const id = randomUUID();
    const data = {
      id,
      tenantId: input.tenantId,
      sessionId: input.sessionId,
      orderId: input.orderId,
      clientOrderId: input.clientOrderId,
      symbol: input.symbol,
      side: input.side,
      type: input.type,
      status: input.status || 'PENDING',
      quantity: input.quantity,
      price: input.price || null,
      stopPrice: input.stopPrice || null,
      filledQuantity: '0',
      averageFillPrice: null,
      fee: '0',
      isSimulated: true,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    try {
      const created = await (this.prisma as any).researchPaperOrder.create({ data });
      this.logger.log(`Paper order created id=${created.id} tenant=${input.tenantId} orderId=${input.orderId} PAPER_SIMULATION`);
      return created;
    } catch (e: any) {
      if (e.code === 'P2002') {
        const existing = await (this.prisma as any).researchPaperOrder.findFirst({ where: { tenantId: input.tenantId, orderId: input.orderId } });
        if (existing) return existing;
      }
      throw e;
    }
  }

  async findPaperOrderById(orderId: string, tenantId: string): Promise<any | null> {
    return (this.prisma as any).researchPaperOrder.findFirst({ where: { orderId, tenantId } }) || null;
  }

  async listPaperOrders(tenantId: string, sessionId: string, filters?: { status?: string; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const skip = (page - 1) * limit;
    const where: any = { tenantId, sessionId, ...(filters?.status ? { status: filters.status } : {}) };
    const [data, total] = await Promise.all([
      (this.prisma as any).researchPaperOrder.findMany({ where, orderBy: { createdAt: 'desc' }, skip, take: limit }),
      (this.prisma as any).researchPaperOrder.count({ where }),
    ]);
    return { data, total };
  }

  async updatePaperOrderStatus(orderId: string, tenantId: string, status: string, extra?: { filledQuantity?: string; averageFillPrice?: string | null; fee?: string }): Promise<any | null> {
    const existing = await (this.prisma as any).researchPaperOrder.findFirst({ where: { orderId, tenantId } });
    if (!existing) return null;
    return await (this.prisma as any).researchPaperOrder.update({ where: { id: existing.id, tenantId }, data: { status, ...extra, updatedAt: new Date() } });
  }

  // Paper Fills
  async createPaperFill(input: {
    tenantId: string;
    sessionId: string;
    orderId: string;
    fillId: string;
    tradeId?: string | null;
    symbol: string;
    side: string;
    quantity: string;
    price: string;
    fee?: string;
    isMaker?: boolean;
    timestamp: Date;
  }): Promise<any> {
    const id = randomUUID();
    const data = {
      id,
      tenantId: input.tenantId,
      sessionId: input.sessionId,
      orderId: input.orderId,
      fillId: input.fillId,
      tradeId: input.tradeId || null,
      symbol: input.symbol,
      side: input.side,
      quantity: input.quantity,
      price: input.price,
      fee: input.fee || '0',
      isMaker: input.isMaker || false,
      isSimulated: true,
      timestamp: input.timestamp,
      createdAt: new Date(),
    };

    try {
      const created = await (this.prisma as any).researchPaperFill.create({ data });
      this.logger.log(`Paper fill created tenant=${input.tenantId} fillId=${input.fillId} PAPER_SIMULATION`);
      return created;
    } catch (e: any) {
      if (e.code === 'P2002') {
        const existing = await (this.prisma as any).researchPaperFill.findFirst({ where: { tenantId: input.tenantId, fillId: input.fillId } });
        if (existing) return existing;
      }
      throw e;
    }
  }

  async listPaperFills(tenantId: string, sessionId: string, filters?: { page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 100;
    const skip = (page - 1) * limit;
    const where: any = { tenantId, sessionId };
    const [data, total] = await Promise.all([
      (this.prisma as any).researchPaperFill.findMany({ where, orderBy: { timestamp: 'asc' }, skip, take: limit }),
      (this.prisma as any).researchPaperFill.count({ where }),
    ]);
    return { data, total };
  }

  // Snapshots
  async createSnapshot(input: { tenantId: string; sessionId: string; sequence: number; timestamp: Date; cash: string; equity: string; realizedPnl?: string; unrealizedPnl?: string | null; drawdown?: string | null }): Promise<any> {
    const id = randomUUID();
    const data = {
      id,
      tenantId: input.tenantId,
      sessionId: input.sessionId,
      sequence: input.sequence,
      timestamp: input.timestamp,
      cash: input.cash,
      equity: input.equity,
      realizedPnl: input.realizedPnl || '0',
      unrealizedPnl: input.unrealizedPnl || null,
      drawdown: input.drawdown || null,
      isSimulated: true,
      createdAt: new Date(),
    };
    try {
      return await (this.prisma as any).researchPaperSnapshot.create({ data });
    } catch (e: any) {
      if (e.code === 'P2002') {
        const existing = await (this.prisma as any).researchPaperSnapshot.findFirst({ where: { sessionId: input.sessionId, sequence: input.sequence } });
        if (existing) return existing;
      }
      throw e;
    }
  }

  async listSnapshots(tenantId: string, sessionId: string): Promise<any[]> {
    return (this.prisma as any).researchPaperSnapshot.findMany({ where: { tenantId, sessionId }, orderBy: { sequence: 'asc' } }) || [];
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PaperTradingRepository } from './paper-trading-repository';
import { ResearchRepository } from './research-repository';
import { ResearchPolicyService } from './research-policy.service';
import { randomUUID } from 'crypto';

/**
 * Starts/stops/manages paper-trading sessions using market data and simulated execution without touching live order records.
 * Paper session must be physically/logically separated from live account state.
 */
@Injectable()
export class PaperTradingService {
  private readonly logger = new Logger(PaperTradingService.name);

  constructor(
    private readonly paperRepo: PaperTradingRepository,
    private readonly researchRepo: ResearchRepository,
    private readonly policyService: ResearchPolicyService,
  ) {}

  async createSession(input: {
    tenantId: string;
    strategyVersionId: string;
    initialCapital: string;
    symbols?: string[];
    timeframe?: string;
    config?: Record<string, any>;
    expiresAt?: Date | null;
    createdBy?: string | null;
    idempotencyKey?: string | null;
  }): Promise<any> {
    // Validate strategy version exists and is at least FROZEN
    const strategyVersion = await this.researchRepo.findStrategyVersionById(input.strategyVersionId, input.tenantId);
    if (!strategyVersion) throw new Error(`Strategy version ${input.strategyVersionId} not found`);
    if (!['FROZEN','PUBLISHED'].includes(strategyVersion.status)) throw new Error(`Strategy version must be FROZEN/PUBLISHED to start paper trading, current=${strategyVersion.status}`);

    // Validate initial capital Decimal-safe
    if (!/^-?\d+(\.\d+)?$/.test(input.initialCapital)) throw new Error('initialCapital must be valid decimal string');
    if (parseFloat(input.initialCapital) <= 0) throw new Error('initialCapital must be positive');

    const sessionIdentifier = `paper_${input.strategyVersionId.substring(0,8)}_${Date.now()}_${randomUUID().substring(0,6)}`;

    const session = await this.paperRepo.createSession({
      tenantId: input.tenantId,
      strategyVersionId: input.strategyVersionId,
      sessionIdentifier,
      config: input.config || {},
      initialCapital: input.initialCapital,
      symbols: input.symbols || [],
      timeframe: input.timeframe || '1m',
      expiresAt: input.expiresAt || null,
      createdBy: input.createdBy || null,
      idempotencyKey: input.idempotencyKey || null,
    });

    await this.researchRepo.createAuditLog({
      tenantId: input.tenantId,
      event: 'PAPER_SESSION_CREATED',
      actorId: input.createdBy || null,
      strategyVersionId: input.strategyVersionId,
      paperSessionId: session.id,
      result: 'SUCCESS',
      safeMetadata: { sessionIdentifier, initialCapital: input.initialCapital, symbols: input.symbols },
    });

    this.logger.log(`Paper session created id=${session.id} tenant=${input.tenantId} strategyVersion=${input.strategyVersionId}`);

    return session;
  }

  async startSession(tenantId: string, sessionId: string, actorId: string): Promise<any | null> {
    const session = await this.paperRepo.findSessionById(sessionId, tenantId);
    if (!session) return null;

    if (session.status !== 'CREATED') throw new Error(`Only CREATED session can be started, current=${session.status}`);

    const updated = await this.paperRepo.updateSessionStatus(sessionId, tenantId, 'RUNNING', { startedAt: new Date() });

    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'PAPER_SESSION_STARTED',
      actorId,
      strategyVersionId: session.strategyVersionId,
      paperSessionId: sessionId,
      result: 'SUCCESS',
      safeMetadata: { sessionIdentifier: session.sessionIdentifier },
    });

    this.logger.log(`Paper session started id=${sessionId} tenant=${tenantId} PAPER_SIMULATION`);

    return updated;
  }

  async pauseSession(tenantId: string, sessionId: string, actorId: string): Promise<any | null> {
    const session = await this.paperRepo.findSessionById(sessionId, tenantId);
    if (!session) return null;
    if (session.status !== 'RUNNING') throw new Error(`Only RUNNING session can be paused, current=${session.status}`);

    const updated = await this.paperRepo.updateSessionStatus(sessionId, tenantId, 'PAUSED');

    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'PAPER_SESSION_PAUSED',
      actorId,
      strategyVersionId: session.strategyVersionId,
      paperSessionId: sessionId,
      result: 'SUCCESS',
      safeMetadata: {},
    });

    return updated;
  }

  async resumeSession(tenantId: string, sessionId: string, actorId: string): Promise<any | null> {
    const session = await this.paperRepo.findSessionById(sessionId, tenantId);
    if (!session) return null;
    if (session.status !== 'PAUSED') throw new Error(`Only PAUSED session can be resumed, current=${session.status}`);

    const updated = await this.paperRepo.updateSessionStatus(sessionId, tenantId, 'RUNNING');

    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'PAPER_SESSION_RESUMED',
      actorId,
      strategyVersionId: session.strategyVersionId,
      paperSessionId: sessionId,
      result: 'SUCCESS',
      safeMetadata: {},
    });

    return updated;
  }

  async stopSession(tenantId: string, sessionId: string, actorId: string, reason?: string): Promise<any | null> {
    const session = await this.paperRepo.findSessionById(sessionId, tenantId);
    if (!session) return null;

    if (['STOPPED','FAILED','EXPIRED'].includes(session.status)) throw new Error(`Session already ${session.status}`);

    const updated = await this.paperRepo.updateSessionStatus(sessionId, tenantId, 'STOPPED', { stoppedAt: new Date() });

    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'PAPER_SESSION_STOPPED',
      actorId,
      strategyVersionId: session.strategyVersionId,
      paperSessionId: sessionId,
      result: 'SUCCESS',
      safeMetadata: { reason: reason || 'Manual stop' },
    });

    this.logger.log(`Paper session stopped id=${sessionId} tenant=${tenantId} reason=${reason}`);

    return updated;
  }

  async getSession(tenantId: string, sessionId: string): Promise<any | null> {
    return this.paperRepo.findSessionById(sessionId, tenantId);
  }

  async listSessions(tenantId: string, filters?: { strategyVersionId?: string; status?: string; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    return this.paperRepo.listSessions(tenantId, filters);
  }

  async checkMinimumDuration(tenantId: string, sessionId: string): Promise<{ meets: boolean; durationMinutes: number; requiredMinutes: number }> {
    const policy = await this.policyService.getPolicy(tenantId);
    const session = await this.paperRepo.findSessionById(sessionId, tenantId);
    if (!session) throw new Error('Session not found');

    const start = session.startedAt ? new Date(session.startedAt).getTime() : new Date(session.createdAt).getTime();
    const end = session.stoppedAt ? new Date(session.stoppedAt).getTime() : Date.now();
    const durationMinutes = (end - start) / (1000*60);

    return { meets: durationMinutes >= policy.paperTradingMinimumDurationMinutes, durationMinutes, requiredMinutes: policy.paperTradingMinimumDurationMinutes };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { BacktestRepository } from './backtest-repository';
import { ResearchRepository } from './research-repository';
import { BacktestEngineService } from './backtest-engine.service';
import { ResearchPolicyService } from './research-policy.service';
import { createHash, randomUUID } from 'crypto';

/**
 * Runs controlled strategy-parameter combinations with bounded concurrency and reproducible configuration fingerprints.
 * Do not automatically promote the highest historical result. Parameter selection must remain separate from production strategy publication.
 */
@Injectable()
export class ParameterSweepService {
  private readonly logger = new Logger(ParameterSweepService.name);

  constructor(
    private readonly backtestRepo: BacktestRepository,
    private readonly researchRepo: ResearchRepository,
    private readonly backtestEngine: BacktestEngineService,
    private readonly policyService: ResearchPolicyService,
  ) {}

  private fingerprintParams(params: Record<string, any>): string {
    const hash = createHash('sha256');
    hash.update(JSON.stringify(params, Object.keys(params).sort()));
    return hash.digest('hex');
  }

  private generateCombinations(paramRanges: Record<string, any[]>): Record<string, any>[] {
    const keys = Object.keys(paramRanges);
    const combinations: Record<string, any>[] = [];

    const recurse = (index: number, current: Record<string, any>) => {
      if (index === keys.length) {
        combinations.push({ ...current });
        return;
      }
      const key = keys[index];
      const values = paramRanges[key];
      for (const val of values) {
        current[key] = val;
        recurse(index+1, current);
      }
    };

    recurse(0, {});
    return combinations;
  }

  async runParameterSweep(input: {
    tenantId: string;
    strategyVersionId: string;
    symbols: string[];
    timeframe: string;
    startTime: string;
    endTime: string;
    initialCapital: string;
    paramRanges: Record<string, any[]>;
    concurrency?: number;
    createdBy?: string | null;
    idempotencyKey?: string | null;
  }): Promise<{ sweepId: string; combinations: number; results: any[]; bestResult: any | null; ranking: string[]; overfittingRisk: string | null }> {
    const policy = await this.policyService.getPolicy(input.tenantId);
    const combinations = this.generateCombinations(input.paramRanges);

    if (combinations.length > policy.maxParameterCombinations) throw new Error(`Parameter combinations ${combinations.length} exceeds max ${policy.maxParameterCombinations}`);
    if (combinations.length === 0) throw new Error('No parameter combinations generated');

    const concurrency = Math.min(input.concurrency || 3, policy.maxBacktestConcurrency);
    const sweepId = `sweep_${randomUUID().substring(0,8)}_${Date.now()}`;

    const results: { parameters: Record<string, any>; metrics: Record<string, any>; fingerprint: string; runId: string }[] = [];

    // Bounded concurrency - process in batches
    for (let i=0; i<combinations.length; i+=concurrency) {
      const batch = combinations.slice(i, i+concurrency);
      const batchPromises = batch.map(async (params) => {
        const fingerprint = this.fingerprintParams(params);
        try {
          const run = await this.backtestEngine.runBacktest({
            tenantId: input.tenantId,
            strategyVersionId: input.strategyVersionId,
            symbols: input.symbols,
            timeframe: input.timeframe,
            startTime: input.startTime,
            endTime: input.endTime,
            initialCapital: input.initialCapital,
            createdBy: input.createdBy || null,
            idempotencyKey: `sweep_${sweepId}_${fingerprint}`,
          });

          // Merge sweep params into run config for tracking
          return { parameters: params, metrics: run.metrics || {}, fingerprint, runId: run.id };
        } catch (e: any) {
          this.logger.warn(`Parameter sweep combination failed fingerprint=${fingerprint} error=${e.message}`);
          return { parameters: params, metrics: { error: e.message }, fingerprint, runId: '' };
        }
      });

      const batchResults = await Promise.all(batchPromises);
      results.push(...batchResults);
    }

    // Ranking by totalReturn
    const ranked = [...results].sort((a,b) => {
      const aRet = parseFloat(a.metrics.totalReturn || a.metrics.totalReturnPercent || '0');
      const bRet = parseFloat(b.metrics.totalReturn || b.metrics.totalReturnPercent || '0');
      return bRet - aRet;
    });

    const bestResult = ranked.length > 0 ? ranked[0] : null;

    // Overfitting safeguards - if best is much better than median, flag risk
    let overfittingRisk: string | null = null;
    if (ranked.length >= 10) {
      const returns = ranked.map(r => parseFloat(r.metrics.totalReturn || '0')).filter(n => !isNaN(n));
      if (returns.length > 0) {
        const median = returns[Math.floor(returns.length/2)];
        const best = returns[0];
        if (median !== 0 && best / median > 3) {
          overfittingRisk = `Best result ${best} is ${(best/median).toFixed(1)}x median ${median} - high overfitting risk. Do not automatically promote highest historical result.`;
        }
      }
    }

    const ranking = ranked.map(r => r.fingerprint);

    await this.researchRepo.createAuditLog({
      tenantId: input.tenantId,
      event: 'PARAMETER_SWEEP_COMPLETED',
      actorId: input.createdBy || null,
      strategyVersionId: input.strategyVersionId,
      result: 'SUCCESS',
      safeMetadata: { sweepId, combinations: combinations.length, bestFingerprint: bestResult?.fingerprint, overfittingRisk },
    });

    this.logger.log(`Parameter sweep completed sweepId=${sweepId} tenant=${input.tenantId} combinations=${combinations.length} best=${bestResult?.fingerprint}`);

    return { sweepId, combinations: combinations.length, results, bestResult, ranking, overfittingRisk };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { ResearchRepository } from './research-repository';

/**
 * Audit events for dataset use, strategy versioning, backtest runs, parameter sweeps, walk-forward, Monte Carlo, paper sessions, signals, and promotions.
 * Never log credentials, private keys, raw exchange API data containing secrets, user authentication tokens
 */
@Injectable()
export class ResearchAuditService {
  private readonly logger = new Logger(ResearchAuditService.name);

  constructor(private readonly researchRepo: ResearchRepository) {}

  async logDatasetRequested(tenantId: string, actorId: string | null, datasetId: string | null, metadata: Record<string, any>, requestId?: string | null): Promise<void> {
    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'DATASET_REQUESTED',
      actorId,
      datasetId,
      result: 'SUCCESS',
      safeMetadata: this.sanitizeMetadata(metadata),
      requestId: requestId || null,
    });
  }

  async logDatasetValidated(tenantId: string, actorId: string | null, datasetId: string, metadata: Record<string, any>): Promise<void> {
    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'DATASET_VALIDATED',
      actorId,
      datasetId,
      result: 'SUCCESS',
      safeMetadata: this.sanitizeMetadata(metadata),
    });
  }

  async logDatasetRejected(tenantId: string, actorId: string | null, datasetId: string | null, metadata: Record<string, any>): Promise<void> {
    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'DATASET_REJECTED',
      actorId,
      datasetId,
      result: 'FAILURE',
      safeMetadata: this.sanitizeMetadata(metadata),
    });
  }

  async logStrategyVersionCreated(tenantId: string, actorId: string | null, versionId: string, metadata: Record<string, any>): Promise<void> {
    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'STRATEGY_VERSION_CREATED',
      actorId,
      strategyVersionId: versionId,
      result: 'SUCCESS',
      safeMetadata: this.sanitizeMetadata(metadata),
    });
  }

  async logStrategyVersionFrozen(tenantId: string, actorId: string | null, versionId: string, metadata: Record<string, any>): Promise<void> {
    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'STRATEGY_VERSION_FROZEN',
      actorId,
      strategyVersionId: versionId,
      result: 'SUCCESS',
      safeMetadata: this.sanitizeMetadata(metadata),
    });
  }

  async logStrategyVersionPublished(tenantId: string, actorId: string | null, versionId: string, metadata: Record<string, any>): Promise<void> {
    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'STRATEGY_VERSION_PUBLISHED',
      actorId,
      strategyVersionId: versionId,
      result: 'SUCCESS',
      safeMetadata: this.sanitizeMetadata(metadata),
    });
  }

  async logBacktestStarted(tenantId: string, actorId: string | null, runId: string, versionId: string, metadata: Record<string, any>): Promise<void> {
    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'BACKTEST_STARTED',
      actorId,
      backtestRunId: runId,
      strategyVersionId: versionId,
      result: 'SUCCESS',
      safeMetadata: this.sanitizeMetadata(metadata),
    });
  }

  async logBacktestCompleted(tenantId: string, actorId: string | null, runId: string, versionId: string, metadata: Record<string, any>): Promise<void> {
    await this.researchRepo.createAuditLog({
      tenantId,
