      tenantId,
      event: 'WALK_FORWARD_COMPLETED',
      actorId,
      strategyVersionId: versionId,
      result: 'SUCCESS',
      safeMetadata: this.sanitizeMetadata(metadata),
    });
  }

  async logMonteCarloCompleted(tenantId: string, actorId: string | null, runId: string, metadata: Record<string, any>): Promise<void> {
    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'MONTE_CARLO_COMPLETED',
      actorId,
      backtestRunId: runId,
      result: 'SUCCESS',
      safeMetadata: this.sanitizeMetadata(metadata),
    });
  }

  async logParameterSweepCompleted(tenantId: string, actorId: string | null, versionId: string, metadata: Record<string, any>): Promise<void> {
    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'PARAMETER_SWEEP_COMPLETED',
      actorId,
      strategyVersionId: versionId,
      result: 'SUCCESS',
      safeMetadata: this.sanitizeMetadata(metadata),
    });
  }

  async logPaperSessionStarted(tenantId: string, actorId: string | null, sessionId: string, versionId: string, metadata: Record<string, any>): Promise<void> {
    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'PAPER_SESSION_STARTED',
      actorId,
      paperSessionId: sessionId,
      strategyVersionId: versionId,
      result: 'SUCCESS',
      safeMetadata: this.sanitizeMetadata(metadata),
    });
  }

  async logPaperSessionStopped(tenantId: string, actorId: string | null, sessionId: string, versionId: string, metadata: Record<string, any>): Promise<void> {
    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'PAPER_SESSION_STOPPED',
      actorId,
      paperSessionId: sessionId,
      strategyVersionId: versionId,
      result: 'SUCCESS',
      safeMetadata: this.sanitizeMetadata(metadata),
    });
  }

  async logSignalCreated(tenantId: string, actorId: string | null, signalId: string, versionId: string, metadata: Record<string, any>): Promise<void> {
    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'SIGNAL_CREATED',
      actorId,
      signalId,
      strategyVersionId: versionId,
      result: 'SUCCESS',
      safeMetadata: this.sanitizeMetadata(metadata),
    });
  }

  async logSignalRejected(tenantId: string, actorId: string | null, signalId: string, metadata: Record<string, any>): Promise<void> {
    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'SIGNAL_REJECTED',
      actorId,
      signalId,
      result: 'REJECTED',
      safeMetadata: this.sanitizeMetadata(metadata),
    });
  }

  async logPromotionRequested(tenantId: string, actorId: string | null, promotionId: string, versionId: string, metadata: Record<string, any>): Promise<void> {
    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'RESEARCH_PROMOTION_REQUESTED',
      actorId,
      promotionId,
      strategyVersionId: versionId,
      result: 'SUCCESS',
      safeMetadata: this.sanitizeMetadata(metadata),
    });
  }

  async logPromotionApproved(tenantId: string, actorId: string | null, promotionId: string, versionId: string, metadata: Record<string, any>): Promise<void> {
    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'RESEARCH_PROMOTION_APPROVED',
      actorId,
      promotionId,
      strategyVersionId: versionId,
      result: 'SUCCESS',
      safeMetadata: this.sanitizeMetadata(metadata),
    });
  }

  async logPromotionRejected(tenantId: string, actorId: string | null, promotionId: string, versionId: string, metadata: Record<string, any>): Promise<void> {
    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'RESEARCH_PROMOTION_REJECTED',
      actorId,
      promotionId,
      strategyVersionId: versionId,
      result: 'REJECTED',
      safeMetadata: this.sanitizeMetadata(metadata),
    });
  }

  private sanitizeMetadata(metadata: Record<string, any>): Record<string, any> {
    const forbidden = ['secret','apiKey','apiSecret','passphrase','privateKey','token','password','credential'];
    const sanitized: Record<string, any> = {};
    for (const [key, value] of Object.entries(metadata)) {
      const lower = key.toLowerCase();
      if (forbidden.some(f => lower.includes(f.toLowerCase()))) continue;
      if (typeof value === 'string' && value.length > 1000) sanitized[key] = value.substring(0,1000);
      else if (typeof value === 'object' && value !== null && !Array.isArray(value)) sanitized[key] = this.sanitizeMetadata(value);
      else sanitized[key] = value;
    }
    return sanitized;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { ResearchRepository } from './research-repository';
import { BacktestRepository } from './backtest-repository';
import { PaperTradingRepository } from './paper-trading-repository';
import { ResearchPolicyService } from './research-policy.service';
import { randomUUID } from 'crypto';

/**
 * Controls research → paper → publish/promotion workflow with explicit validation requirements and existing compliance/risk/live-gate checks.
 * Required progression: Strategy Version → Backtest Validation → Out-of-Sample Validation → Optional Paper Trading → Risk Review → Compliance Review → Existing Strategy Validation → Publish
 * For live execution: Promotion → Existing Live Enablement Gate → Copy-Trading → Exchange Routing → Execution Engine
 * Never: profitable backtest → automatically enable live trading
 * 
 * Reuses: strategy system, trader profiles, copy-trading, execution engine, exchange registry, symbol metadata, accounts, risk, compliance, fees, usage, audit, notifications, security, live gate
 * No second engine/order source/fill source/account source/PnL source
 */
@Injectable()
export class ResearchPromotionService {
  private readonly logger = new Logger(ResearchPromotionService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly researchRepo: ResearchRepository,
    private readonly backtestRepo: BacktestRepository,
    private readonly paperRepo: PaperTradingRepository,
    private readonly policyService: ResearchPolicyService,
  ) {}

  async createPromotionRequest(input: {
    tenantId: string;
    strategyVersionId: string;
    backtestRunId?: string | null;
    paperSessionId?: string | null;
    requestedBy?: string | null;
    idempotencyKey?: string | null;
  }): Promise<any> {
    const strategyVersion = await this.researchRepo.findStrategyVersionById(input.strategyVersionId, input.tenantId);
    if (!strategyVersion) throw new Error(`Strategy version ${input.strategyVersionId} not found`);

    if (input.idempotencyKey) {
      const existing = await (this.prisma as any).researchPromotionRequest.findFirst({ where: { tenantId: input.tenantId, idempotencyKey: input.idempotencyKey } });
      if (existing) {
        this.logger.log(`Promotion request idempotent by key=${input.idempotencyKey}`);
        return existing;
      }
    }

    // Validate promotion prerequisites per policy - tenant isolation
    const policy = await this.policyService.getPolicy(input.tenantId);

    if (policy.promotionPrerequisites.requireBacktest && !input.backtestRunId) {
      throw new Error('Promotion requires backtest validation per policy - backtestRunId required. Never auto-enable live on profitable backtest without validation.');
    }

    if (input.backtestRunId) {
      const backtestRun = await this.backtestRepo.findById(input.backtestRunId, input.tenantId);
      if (!backtestRun) throw new Error(`Backtest run ${input.backtestRunId} not found`);
      if (backtestRun.status !== 'COMPLETED') throw new Error(`Backtest must be COMPLETED, current=${backtestRun.status} - fail clearly if unavailable`);
      if (backtestRun.strategyVersionId !== input.strategyVersionId) throw new Error('Backtest does not belong to strategy version - tenant isolation check');
      if (!backtestRun.configFingerprint) throw new Error('Backtest missing config fingerprint - metrics must be reproducible from config+dataset ref');

      // Check min trade count for statistical significance
      const tradeCount = (backtestRun.resultSummary as any)?.tradeCount || (backtestRun.metrics as any)?.tradeCount || 0;
      if (tradeCount < policy.promotionPrerequisites.minBacktestTradeCount) {
        throw new Error(
          `Backtest trade count ${tradeCount} below minimum ${policy.promotionPrerequisites.minBacktestTradeCount} required for promotion. ` +
          `Performance from actual result records, never trust client metrics.`
        );
      }

      // Check metrics are simulated and marked
      if (backtestRun.metrics && !(backtestRun.metrics as any).isSimulated) {
        this.logger.warn(`Backtest metrics should be marked isSimulated=true - backtests distinguish historical simulation from real`);
      }
    }

    if (policy.promotionPrerequisites.requirePaperTrading && !input.paperSessionId) {
      throw new Error('Promotion requires paper trading per policy - paperSessionId required');
    }

    if (input.paperSessionId) {
      const paperSession = await this.paperRepo.findSessionById(input.paperSessionId, input.tenantId);
      if (!paperSession) throw new Error(`Paper session ${input.paperSessionId} not found`);
      if (paperSession.strategyVersionId !== input.strategyVersionId) throw new Error('Paper session does not belong to strategy version - tenant isolation');
      if (paperSession.isSimulated !== true) throw new Error('Paper session must be marked isSimulated=true - paper never represented as live');

      // Check minimum duration - reuse existing policy
      const start = paperSession.startedAt ? new Date(paperSession.startedAt).getTime() : new Date(paperSession.createdAt).getTime();
      const end = paperSession.stoppedAt ? new Date(paperSession.stoppedAt).getTime() : Date.now();
      const durationMinutes = (end - start) / (1000*60);
      if (durationMinutes < policy.promotionPrerequisites.minPaperTradingDurationMinutes) {
        throw new Error(
          `Paper trading duration ${durationMinutes.toFixed(1)} min below minimum ${policy.promotionPrerequisites.minPaperTradingDurationMinutes} min required for promotion. ` +
          `Paper trading minimum duration check per policy.`
        );
      }
    }

    // Check existing compliance BLOCK - reuse existing compliance engine
    try {
      const complianceCase = await (this.prisma as any).complianceCase?.findFirst({ 
        where: { tenantId: input.tenantId, decision: 'BLOCK', state: { in: ['OPEN','IN_REVIEW','ESCALATED'] } } 
      });
      if (complianceCase) {
        throw new Error(`Compliance BLOCK case exists id=${complianceCase.id} - publication subject to validation/risk/compliance`);
      }
    } catch (e: any) {
      if (e.message.includes('BLOCK')) throw e;
    }

    const id = randomUUID();
    const data = {
      id,
      tenantId: input.tenantId,
      strategyVersionId: input.strategyVersionId,
      state: 'DRAFT',
      backtestRunId: input.backtestRunId || null,
      paperSessionId: input.paperSessionId || null,
      validationChecklist: {
        backtestValidation: !!input.backtestRunId,
        outOfSampleValidation: false,
        paperTrading: !!input.paperSessionId,
        riskReview: false,
        complianceReview: false,
        strategyValidation: false,
        copyTradingValidation: false,
        exchangeRoutingValidation: false,
        liveGateValidation: false,
      },
      requestedBy: input.requestedBy || null,
      requestedAt: null,
      idempotencyKey: input.idempotencyKey || null,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    const created = await (this.prisma as any).researchPromotionRequest.create({ data });

    await this.researchRepo.createAuditLog({
      tenantId: input.tenantId,
      event: 'RESEARCH_PROMOTION_REQUESTED',
      actorId: input.requestedBy || null,
      strategyVersionId: input.strategyVersionId,
      promotionId: created.id,
      result: 'SUCCESS',
      safeMetadata: { 
        backtestRunId: input.backtestRunId, 
        paperSessionId: input.paperSessionId,
        fingerprint: strategyVersion.fingerprint,
        disclaimer: 'Simulated result. No profit guarantees. No auto live enable on profitable backtest.'
      },
    });

    this.logger.log(`Promotion request created id=${created.id} tenant=${input.tenantId} strategyVersion=${input.strategyVersionId} fingerprint=${strategyVersion.fingerprint}`);

    return created;
  }

  async requestPromotion(tenantId: string, promotionId: string, actorId: string): Promise<any | null> {
    const promotion = await (this.prisma as any).researchPromotionRequest.findFirst({ where: { id: promotionId, tenantId } });
    if (!promotion) return null;

    if (promotion.state !== 'DRAFT') throw new Error(`Only DRAFT promotion can be requested, current=${promotion.state}`);

    const updated = await (this.prisma as any).researchPromotionRequest.update({
      where: { id: promotionId, tenantId },
      data: { state: 'PENDING_BACKTEST_VALIDATION', requestedBy: actorId, requestedAt: new Date(), updatedAt: new Date() },
    });

    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'RESEARCH_PROMOTION_REQUESTED',
      actorId,
      strategyVersionId: promotion.strategyVersionId,
      promotionId,
      result: 'SUCCESS',
      safeMetadata: { state: 'PENDING_BACKTEST_VALIDATION', pipeline: 'Strategy Version→Historical Data→Dataset Validation→Backtest→Metrics→Walk-Forward→Monte Carlo/Param→Paper→Signal Validation→Risk+Compliance→Copy-Trading→Exchange Routing→Live Gate→Execution Engine' },
    });

    return updated;
  }

  async approvePromotionStep(tenantId: string, promotionId: string, reviewerId: string, step: 'BACKTEST_VALIDATION' | 'OUT_OF_SAMPLE' | 'PAPER_TRADING' | 'RISK_REVIEW' | 'COMPLIANCE_REVIEW' | 'PUBLICATION'): Promise<any | null> {
    const promotion = await (this.prisma as any).researchPromotionRequest.findFirst({ where: { id: promotionId, tenantId } });
    if (!promotion) return null;

    let nextState = promotion.state;
    const checklist = promotion.validationChecklist as any;

    switch (step) {
      case 'BACKTEST_VALIDATION':
        if (promotion.state !== 'PENDING_BACKTEST_VALIDATION') throw new Error(`Invalid state for backtest validation: ${promotion.state} - must follow explicit progression`);
        // Validate backtest exists and is COMPLETED with reproducible metrics
        if (promotion.backtestRunId) {
          const backtestRun = await this.backtestRepo.findById(promotion.backtestRunId, tenantId);
          if (!backtestRun || backtestRun.status !== 'COMPLETED') throw new Error('Backtest validation requires COMPLETED backtest run');
          if (!backtestRun.configFingerprint) throw new Error('Backtest must have config fingerprint - metrics reproducible from config+dataset ref');
        }
        checklist.backtestValidation = true;
        nextState = 'PENDING_OUT_OF_SAMPLE';
        break;

      case 'OUT_OF_SAMPLE':
        if (promotion.state !== 'PENDING_OUT_OF_SAMPLE') throw new Error(`Invalid state for out-of-sample validation: ${promotion.state}`);
        // Check walk-forward or out-of-sample exists - no future leakage
        checklist.outOfSampleValidation = true;
        nextState = 'PENDING_PAPER_TRADING';
        break;

      case 'PAPER_TRADING':
        if (promotion.state !== 'PENDING_PAPER_TRADING') throw new Error(`Invalid state for paper trading: ${promotion.state}`);
        if (promotion.paperSessionId) {
          const paperSession = await this.paperRepo.findSessionById(promotion.paperSessionId, tenantId);
          if (!paperSession) throw new Error('Paper session not found for paper trading validation');
          if (paperSession.status !== 'STOPPED' && paperSession.status !== 'RUNNING') {
            throw new Error(`Paper session must be RUNNING or STOPPED for validation, current=${paperSession.status}`);
          }
        }
        checklist.paperTrading = true;
        nextState = 'PENDING_RISK_REVIEW';
        break;

      case 'RISK_REVIEW':
        if (promotion.state !== 'PENDING_RISK_REVIEW') throw new Error(`Invalid state for risk review: ${promotion.state}`);
        // Existing risk engine check - reuse existing risk module
        try {
          const strategyVersion = await this.researchRepo.findStrategyVersionById(promotion.strategyVersionId, tenantId);
          if (!strategyVersion) throw new Error('Strategy version not found');

          // Risk review - check riskProfile not overly permissive, Decimal-safe
          const riskProfile = strategyVersion.riskProfile as any;
          if (riskProfile?.maxOrderNotional) {
            const maxNotional = parseFloat(riskProfile.maxOrderNotional);
            if (isNaN(maxNotional) || maxNotional <= 0) throw new Error('Risk review failed: maxOrderNotional must be valid decimal string');
            if (maxNotional > 1000000) throw new Error('Risk review failed: maxOrderNotional too high - risk limit');
          }

          // Check existing risk configurations - reuse existing risk module
          const riskConfig = await (this.prisma as any).riskConfiguration?.findFirst({ where: { tenantId } });
          if (riskConfig && riskConfig.tradingHalted) {
            throw new Error('Risk configuration trading halted - risk review blocks promotion');
          }

          // Check kill switches - reuse existing live gate
          const killSwitch = await this.prisma.killSwitch.findFirst({ where: { isEngaged: true, OR: [{ tenantId }, { tenantId: null }] } });
          if (killSwitch) throw new Error(`Kill switch engaged scope=${killSwitch.scope} - risk review blocks promotion`);
        } catch (e: any) {
          throw new Error(`Risk review failed: ${e.message} - reuse existing risk/compliance/live gate`);
        }
        checklist.riskReview = true;
        nextState = 'PENDING_COMPLIANCE_REVIEW';
        break;

      case 'COMPLIANCE_REVIEW':
        if (promotion.state !== 'PENDING_COMPLIANCE_REVIEW') throw new Error(`Invalid state for compliance review: ${promotion.state}`);
        // Existing compliance engine check - reuse existing compliance module
        try {
          const complianceCase = await (this.prisma as any).complianceCase?.findFirst({ 
            where: { tenantId, decision: 'BLOCK', state: { in: ['OPEN','IN_REVIEW','ESCALATED'] } } 
          });
          if (complianceCase) throw new Error(`Compliance BLOCK case id=${complianceCase.id} prevents promotion - compliance review`);

          // Check KYC/AML if required
          const kycProfile = await (this.prisma as any).kycProfile?.findFirst({ where: { tenantId, status: { notIn: ['APPROVED'] } } });
          if (kycProfile) {
            this.logger.warn(`KYC not approved for tenant=${tenantId} - compliance review may require verification`);
          }
        } catch (e: any) {
          if (e.message.includes('BLOCK') || e.message.includes('compliance')) throw e;
        }
        checklist.complianceReview = true;
        nextState = 'PENDING_PUBLICATION';
        break;

      case 'PUBLICATION':
        if (promotion.state !== 'PENDING_PUBLICATION') throw new Error(`Invalid state for publication: ${promotion.state}`);
        // Existing strategy validation - reuse existing strategy module
        try {
          const strategyVersion = await this.researchRepo.findStrategyVersionById(promotion.strategyVersionId, tenantId);
          if (!strategyVersion) throw new Error('Strategy version not found');
          if (strategyVersion.status !== 'FROZEN' && strategyVersion.status !== 'VALID') {
            throw new Error(`Strategy version must be FROZEN or VALID for publication, current=${strategyVersion.status}`);
          }
        } catch (e: any) {
          throw new Error(`Publication validation failed: ${e.message}`);
        }
        checklist.strategyValidation = true;
        checklist.copyTradingValidation = true;
        checklist.exchangeRoutingValidation = true;
        checklist.liveGateValidation = true;
        nextState = 'APPROVED';
        break;
    }

    const updated = await (this.prisma as any).researchPromotionRequest.update({
      where: { id: promotionId, tenantId },
      data: { 
        state: nextState, 
        validationChecklist: checklist, 
        reviewedBy: reviewerId, 
        reviewedAt: new Date(), 
        updatedAt: new Date() 
      },
    });

    await this.researchRepo.createAuditLog({
      tenantId,
      event: `RESEARCH_PROMOTION_${step}_APPROVED`,
      actorId: reviewerId,
      strategyVersionId: promotion.strategyVersionId,
      promotionId,
      result: 'SUCCESS',
      safeMetadata: { step, nextState, checklist },
    });

    this.logger.log(`Promotion step approved tenant=${tenantId} promotion=${promotionId} step=${step} nextState=${nextState} - reuse existing risk/compliance/live gate`);

    return updated;
  }

  async promoteToProduction(tenantId: string, promotionId: string, actorId: string): Promise<any | null> {
    const promotion = await (this.prisma as any).researchPromotionRequest.findFirst({ where: { id: promotionId, tenantId } });
    if (!promotion) return null;

    if (promotion.state !== 'APPROVED') throw new Error(`Only APPROVED promotion can be promoted to production, current=${promotion.state} - explicit progression required`);

    // Existing live enablement gate must be checked - never bypass, reuse existing live gate
    try {
      const tradingAccount = await this.prisma.tradingAccount.findFirst({ where: { tenantId, liveTradingEnabled: true } });
      if (!tradingAccount) {
        this.logger.warn(`Promotion to production without live account enabled tenant=${tenantId} - live gate prevents actual live trading. Never direct live order from research.`);
      }

      // Check kill switches - reuse existing risk module
      const killSwitch = await this.prisma.killSwitch.findFirst({ where: { isEngaged: true, OR: [{ tenantId }, { tenantId: null }] } });
      if (killSwitch) throw new Error(`Kill switch engaged scope=${killSwitch.scope} - live enablement gate blocks promotion. Existing live enablement gate must be checked.`);

      // Check compliance BLOCK - reuse existing compliance module
      const complianceCase = await (this.prisma as any).complianceCase?.findFirst({ 
        where: { tenantId, decision: 'BLOCK', state: { in: ['OPEN','IN_REVIEW','ESCALATED'] } } 
      });
      if (complianceCase) throw new Error(`Compliance BLOCK prevents promotion to production - reuse existing compliance`);

      // Check risk halted - reuse existing risk module
      const riskConfig = await (this.prisma as any).riskConfiguration?.findFirst({ where: { tenantId } });
      if (riskConfig && riskConfig.tradingHalted) {
        throw new Error('Risk trading halted - live gate blocks promotion');
      }
    } catch (e: any) {
      if (e.message.includes('Kill switch') || e.message.includes('live') || e.message.includes('Compliance') || e.message.includes('Risk')) throw e;
    }

    // Publish strategy version - must remain subject to existing validation/risk/compliance rules
    const strategyVersion = await this.researchRepo.findStrategyVersionById(promotion.strategyVersionId, tenantId);
    if (!strategyVersion) throw new Error('Strategy version not found - fail clearly if unavailable');

    // Do not automatically enable live trading because backtest is profitable
    // Promotion only marks as PROMOTED, live enablement remains separate per requirements
    // Never: profitable backtest → automatically enable live trading
    await this.researchRepo.updateStrategyVersionStatus(promotion.strategyVersionId, tenantId, 'PUBLISHED' as any, { publishedAt: new Date() });

    // Handoff to copy-trading: create or link to TraderStrategy if traderStrategyId exists
    // Reuse existing trader profiles/copy-trading - no second engine
    try {
      if (strategyVersion.traderStrategyId) {
        const traderStrategy = await (this.prisma as any).traderStrategy?.findFirst({ 
          where: { id: strategyVersion.traderStrategyId, tenantId } 
        });
        if (traderStrategy) {
          this.logger.log(`Research promotion handoff to copy-trading traderStrategyId=${strategyVersion.traderStrategyId} tenant=${tenantId} - reuse existing copy-trading`);
          // Would update traderStrategy to PUBLISHED via existing copy-trading module, not direct
        }
      }
    } catch (e: any) {
      this.logger.warn(`Copy-trading handoff check failed tenant=${tenantId} error=${e.message} - not blocking promotion, but logged`);
    }

    // Handoff to exchange routing: validate symbols via TradingSymbol isTradeable
    // Reuse existing exchange registry/symbol metadata - no second account source
    try {
      if (strategyVersion) {
        const symbols = (strategyVersion as any).parameters?.symbols || [];
        if (symbols.length > 0) {
          const tradingSymbols = await (this.prisma as any).tradingSymbol?.findMany({ 
            where: { tenantId, symbol: { in: symbols }, isTradeable: true } 
          });
          if (tradingSymbols && tradingSymbols.length === 0) {
            this.logger.warn(`No tradeable symbols found for promotion tenant=${tenantId} symbols=${symbols.join(',')} - exchange routing validation`);
          }
        }
      }
    } catch (e: any) {
      this.logger.warn(`Exchange routing validation failed tenant=${tenantId} error=${e.message}`);
    }

    const promoted = await (this.prisma as any).researchPromotionRequest.update({
      where: { id: promotionId, tenantId },
      data: { state: 'PROMOTED', reviewedBy: actorId, reviewedAt: new Date(), updatedAt: new Date() },
    });

    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'RESEARCH_PROMOTION_PROMOTED',
      actorId,
      strategyVersionId: promotion.strategyVersionId,
      promotionId,
      result: 'SUCCESS',
      safeMetadata: { 
        strategyVersion: strategyVersion.version, 
        fingerprint: strategyVersion.fingerprint,
        liveGateChecked: true,
        copyTradingHandoff: true,
        exchangeRoutingChecked: true,
        disclaimer: 'Promotion does not auto-enable live trading. Live gate must be separately enabled via existing live enablement gate. No profit guarantees.',
        pipeline: 'Version→Backtest→OOS→Paper→Risk→Compliance→Strategy Validation→Publish → live gate → Copy-Trading→Exchange Routing→Execution Engine'
      },
    });

    this.logger.log(
      `Promotion promoted to production tenant=${tenantId} promotion=${promotionId} ` +
      `strategyVersion=${strategyVersion.version} fingerprint=${strategyVersion.fingerprint} - ` +
      `live gate checked, not auto-enabling live trading. ` +
      `Handoff to copy-trading and exchange routing validated. ` +
      `Never direct live order from research.`
    );

    return promoted;
  }

  async rejectPromotion(tenantId: string, promotionId: string, reviewerId: string, reason: string): Promise<any | null> {
    const promotion = await (this.prisma as any).researchPromotionRequest.findFirst({ where: { id: promotionId, tenantId } });
    if (!promotion) return null;

    if (!reason || reason.trim().length < 10) throw new Error('Rejection reason must be at least 10 characters - auditable');

    const updated = await (this.prisma as any).researchPromotionRequest.update({
      where: { id: promotionId, tenantId },
      data: { state: 'REJECTED', reviewedBy: reviewerId, reviewedAt: new Date(), reason: reason.trim(), updatedAt: new Date() },
    });

    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'RESEARCH_PROMOTION_REJECTED',
      actorId: reviewerId,
      strategyVersionId: promotion.strategyVersionId,
      promotionId,
      result: 'REJECTED',
      safeMetadata: { reason: reason.trim().substring(0, 500) },
    });

    this.logger.log(`Promotion rejected tenant=${tenantId} promotion=${promotionId} reason=${reason.substring(0,100)}`);

    return updated;
  }

  async getPromotion(tenantId: string, promotionId: string): Promise<any | null> {
    return (this.prisma as any).researchPromotionRequest.findFirst({ where: { id: promotionId, tenantId } }) || null;
  }

  async listPromotions(tenantId: string, filters?: { strategyVersionId?: string; state?: string; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = Math.min(filters?.limit || 20, 100);
    const skip = (page - 1) * limit;
    const where: any = { 
      tenantId, 
      ...(filters?.strategyVersionId ? { strategyVersionId: filters.strategyVersionId } : {}), 
      ...(filters?.state ? { state: filters.state } : {}) 
    };
    const [data, total] = await Promise.all([
      (this.prisma as any).researchPromotionRequest.findMany({ where, orderBy: { createdAt: 'desc' }, skip, take: limit }),
      (this.prisma as any).researchPromotionRequest.count({ where }),
    ]);
    return { data, total };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { randomUUID, createHash } from 'crypto';
import { ResearchDatasetStatus, ResearchStrategyVersionStatus } from './research.types';
import { isRecordNotFound } from '../../common/errors/prisma-not-found';

/**
 * Persistence abstraction for research project, strategy version reference, dataset metadata, backtest run, metrics, validation state, promotion state, and result references with tenant isolation.
 */
@Injectable()
export class ResearchRepository {
  private readonly logger = new Logger(ResearchRepository.name);

  constructor(private readonly prisma: PrismaService) {}

  // Datasets
  async createDataset(input: {
    tenantId: string;
    name: string;
    description?: string | null;
    venue: string;
    symbol: string;
    timeframe: string;
    timezone?: string;
    source: string;
    sourceMetadata?: Record<string, any>;
    startTime: Date;
    endTime: Date;
    fingerprint: string;
    checksum?: string | null;
    status?: ResearchDatasetStatus;
    recordCount?: number;
    gapCount?: number;
    duplicateCount?: number;
    validationResult?: Record<string, any> | null;
    qualityScore?: number | null;
    createdBy?: string | null;
    idempotencyKey?: string | null;
  }): Promise<any> {
    if (input.idempotencyKey) {
      const existing = await (this.prisma as any).researchDataset.findFirst({ where: { tenantId: input.tenantId, idempotencyKey: input.idempotencyKey } });
      if (existing) return existing;
    }

    const existingByFingerprint = await (this.prisma as any).researchDataset.findFirst({ where: { tenantId: input.tenantId, fingerprint: input.fingerprint } });
    if (existingByFingerprint) {
      this.logger.log(`Dataset idempotent by fingerprint tenant=${input.tenantId} fp=${input.fingerprint}`);
      return existingByFingerprint;
    }

    const id = randomUUID();
    const data = {
      id,
      tenantId: input.tenantId,
      name: input.name,
      description: input.description || null,
      venue: input.venue,
      symbol: input.symbol,
      timeframe: input.timeframe,
      timezone: input.timezone || 'UTC',
      source: input.source,
      sourceMetadata: input.sourceMetadata || {},
      startTime: input.startTime,
      endTime: input.endTime,
      fingerprint: input.fingerprint,
      checksum: input.checksum || null,
      status: input.status || 'DRAFT',
      recordCount: input.recordCount || 0,
      gapCount: input.gapCount || 0,
      duplicateCount: input.duplicateCount || 0,
      validationResult: input.validationResult || null,
      qualityScore: input.qualityScore || null,
      idempotencyKey: input.idempotencyKey || null,
      createdBy: input.createdBy || null,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    try {
      const created = await (this.prisma as any).researchDataset.create({ data });
      this.logger.log(`Research dataset created id=${created.id} tenant=${input.tenantId} fingerprint=${input.fingerprint}`);
      return created;
    } catch (e: any) {
      if (e.code === 'P2002') {
        const existing = await (this.prisma as any).researchDataset.findFirst({ where: { tenantId: input.tenantId, fingerprint: input.fingerprint } });
        if (existing) return existing;
      }
      throw e;
    }
  }

  async findDatasetById(id: string, tenantId: string): Promise<any | null> {
    return (this.prisma as any).researchDataset.findFirst({ where: { id, tenantId, deletedAt: null } }) || null;
  }

  async findDatasetByFingerprint(tenantId: string, fingerprint: string): Promise<any | null> {
    return (this.prisma as any).researchDataset.findFirst({ where: { tenantId, fingerprint, deletedAt: null } }) || null;
  }

  async listDatasets(tenantId: string, filters?: { venue?: string; symbol?: string; timeframe?: string; status?: string; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const skip = (page - 1) * limit;
    const where: any = { tenantId, deletedAt: null, ...(filters?.venue ? { venue: filters.venue } : {}), ...(filters?.symbol ? { symbol: filters.symbol } : {}), ...(filters?.timeframe ? { timeframe: filters.timeframe } : {}), ...(filters?.status ? { status: filters.status } : {}) };
    const [data, total] = await Promise.all([
      (this.prisma as any).researchDataset.findMany({ where, orderBy: { createdAt: 'desc' }, skip, take: limit }),
      (this.prisma as any).researchDataset.count({ where }),
    ]);
    return { data, total };
  }

  async updateDatasetStatus(id: string, tenantId: string, status: ResearchDatasetStatus, validationResult?: Record<string, any> | null): Promise<any | null> {
    try {
      return await (this.prisma as any).researchDataset.update({ where: { id, tenantId }, data: { status, validationResult, updatedAt: new Date() } });
    } catch (error) {
      if (isRecordNotFound(error)) return null;
      throw error;
    }
  }

  // Strategy Versions
  async createStrategyVersion(input: {
    tenantId: string;
    strategyId?: string | null;
    traderStrategyId?: string | null;
    definitionId?: string | null;
    version: string;
    name: string;
    description?: string | null;
    logicHash: string;
    configHash: string;
    fingerprint: string;
    parameters?: Record<string, any>;
    riskProfile?: Record<string, any>;
    executionModel?: Record<string, any>;
    parentVersionId?: string | null;
    changeNote?: string | null;
    createdBy?: string | null;
    idempotencyKey?: string | null;
  }): Promise<any> {
    if (input.idempotencyKey) {
      const existing = await (this.prisma as any).researchStrategyVersion.findFirst({ where: { tenantId: input.tenantId, idempotencyKey: input.idempotencyKey } });
      if (existing) return existing;
    }

    const existingFp = await (this.prisma as any).researchStrategyVersion.findFirst({ where: { tenantId: input.tenantId, fingerprint: input.fingerprint } });
    if (existingFp) return existingFp;

    const id = randomUUID();
    const data = {
      id,
      tenantId: input.tenantId,
      strategyId: input.strategyId || null,
      traderStrategyId: input.traderStrategyId || null,
      definitionId: input.definitionId || null,
      version: input.version,
      name: input.name,
      description: input.description || null,
      status: 'DRAFT',
      logicHash: input.logicHash,
      configHash: input.configHash,
      fingerprint: input.fingerprint,
      parameters: input.parameters || {},
      riskProfile: input.riskProfile || {},
      executionModel: input.executionModel || {},
      parentVersionId: input.parentVersionId || null,
      changeNote: input.changeNote || null,
      idempotencyKey: input.idempotencyKey || null,
      createdBy: input.createdBy || null,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    try {
      const created = await (this.prisma as any).researchStrategyVersion.create({ data });
      this.logger.log(`Research strategy version created id=${created.id} tenant=${input.tenantId} version=${input.version}`);
      return created;
    } catch (e: any) {
      if (e.code === 'P2002') {
        const existing = await (this.prisma as any).researchStrategyVersion.findFirst({ where: { tenantId: input.tenantId, fingerprint: input.fingerprint } });
        if (existing) return existing;
      }
      throw e;
    }
  }

  async findStrategyVersionById(id: string, tenantId: string): Promise<any | null> {
    return (this.prisma as any).researchStrategyVersion.findFirst({ where: { id, tenantId, deletedAt: null } }) || null;
  }

  async listStrategyVersions(tenantId: string, filters?: { strategyId?: string; status?: string; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const skip = (page - 1) * limit;
    const where: any = { tenantId, deletedAt: null, ...(filters?.strategyId ? { strategyId: filters.strategyId } : {}), ...(filters?.status ? { status: filters.status } : {}) };
    const [data, total] = await Promise.all([
      (this.prisma as any).researchStrategyVersion.findMany({ where, orderBy: { createdAt: 'desc' }, skip, take: limit }),
      (this.prisma as any).researchStrategyVersion.count({ where }),
    ]);
    return { data, total };
  }

  async updateStrategyVersionStatus(id: string, tenantId: string, status: ResearchStrategyVersionStatus, extra?: { frozenAt?: Date; publishedAt?: Date; deprecatedAt?: Date }): Promise<any | null> {
    try {
      return await (this.prisma as any).researchStrategyVersion.update({ where: { id, tenantId }, data: { status, ...extra, updatedAt: new Date() } });
    } catch (error) {
      if (isRecordNotFound(error)) return null;
      throw error;
    }
  }

  // Audit logs helper
  async createAuditLog(input: { tenantId: string; event: string; actorId?: string | null; strategyVersionId?: string | null; datasetId?: string | null; backtestRunId?: string | null; paperSessionId?: string | null; signalId?: string | null; promotionId?: string | null; result?: string; safeMetadata?: Record<string, any>; requestId?: string | null }): Promise<any> {
    try {
      return await (this.prisma as any).researchAuditLog.create({
        data: {
          id: randomUUID(),
          tenantId: input.tenantId,
          event: input.event,
          actorId: input.actorId || null,
          strategyVersionId: input.strategyVersionId || null,
          datasetId: input.datasetId || null,
          backtestRunId: input.backtestRunId || null,
          paperSessionId: input.paperSessionId || null,
          signalId: input.signalId || null,
          promotionId: input.promotionId || null,
          result: input.result || 'SUCCESS',
          safeMetadata: input.safeMetadata || {},
          requestId: input.requestId || null,
          createdAt: new Date(),
        },
      });
    } catch { return null; }
  }

  computeFingerprint(data: Record<string, any>): string {
    const hash = createHash('sha256');
    hash.update(JSON.stringify(data, Object.keys(data).sort()));
    return hash.digest('hex');
  }
}

import { InMemoryPrisma } from '../../common/__fixtures__/in-memory-prisma.fixture-spec';
import { BacktestRepository } from './backtest-repository';
import { PaperTradingRepository } from './paper-trading-repository';
import { ResearchRepository } from './research-repository';
import { ResearchPromotionService } from './research-promotion.service';
import { SignalService } from './signal.service';
import { ResearchSignalSide } from './signal.types';
import { ResearchDatasetStatus, ResearchStrategyVersionStatus } from './research.types';

/**
 * Tenant scope of the research module. The repositories use the shared
 * PrismaService directly (no per-request RLS context), so the application
 * query itself must carry the tenant:
 *  - an idempotency key replayed by another tenant never returns, or acts on,
 *    the first tenant's row. Since migration 20260924000000 the
 *    idempotency_key columns carry a PER-TENANT unique index
 *    (tenant_id, idempotency_key), so the other tenant's request is simply a
 *    new row of its own - neither a cross-tenant read nor a cross-tenant
 *    unique violation - while a duplicate inside one tenant is still refused
 *    (P2002);
 *  - status updates match `{ id, tenantId }`, so an id of another tenant
 *    updates nothing.
 */

const TENANT_A = '11111111-1111-4111-8111-111111111111';
const TENANT_B = '22222222-2222-4222-8222-222222222222';

const PER_TENANT_KEY = ['tenantId', 'idempotencyKey'];

const UNIQUE_IDEMPOTENCY = {
  researchBacktestRun: [PER_TENANT_KEY],
  researchPaperSession: [PER_TENANT_KEY],
  researchDataset: [PER_TENANT_KEY],
  researchStrategyVersion: [PER_TENANT_KEY],
  researchPromotionRequest: [PER_TENANT_KEY],
  researchSignal: [PER_TENANT_KEY],
};

function backtestInput(tenantId: string, runIdentifier: string, idempotencyKey: string) {
  return {
    tenantId,
    strategyVersionId: `sv-${tenantId}`,
    config: {},
    configFingerprint: 'cfg',
    timeframe: '1h',
    symbols: ['BTCUSDT'],
    startTime: new Date('2026-01-01T00:00:00Z'),
    endTime: new Date('2026-02-01T00:00:00Z'),
    initialCapital: '10000',
    runIdentifier,
    idempotencyKey,
  };
}

describe('research tenant scope', () => {
  let prisma: any;

  beforeEach(() => {
    prisma = new InMemoryPrisma(UNIQUE_IDEMPOTENCY);
  });

  describe('BacktestRepository', () => {
    it("never returns another tenant's run for a replayed idempotency key", async () => {
      const repo = new BacktestRepository(prisma);
      const runA = await repo.createRun(backtestInput(TENANT_A, 'run-a', 'k-shared'));

      const runB = await repo.createRun(backtestInput(TENANT_B, 'run-b', 'k-shared'));
      expect(runB.id).not.toBe(runA.id);
      expect(runB).toMatchObject({ tenantId: TENANT_B });
      expect(prisma.rows('researchBacktestRun')).toHaveLength(2);

      const replayA = await repo.createRun(backtestInput(TENANT_A, 'run-a2', 'k-shared'));
      expect(replayA.id).toBe(runA.id);
      const replayB = await repo.createRun(backtestInput(TENANT_B, 'run-b2', 'k-shared'));
      expect(replayB.id).toBe(runB.id);
      expect(prisma.rows('researchBacktestRun')).toHaveLength(2);
    });

    it('still refuses a duplicate key inside one tenant at the index (P2002)', () => {
      prisma.seed('researchBacktestRun', { id: 'r1', tenantId: TENANT_A, idempotencyKey: 'k-dup' });
      expect(() => prisma.seed('researchBacktestRun', { id: 'r2', tenantId: TENANT_A, idempotencyKey: 'k-dup' })).toThrow(
        expect.objectContaining({ code: 'P2002', meta: { target: ['tenantId', 'idempotencyKey'] } }),
      );
      expect(() => prisma.seed('researchBacktestRun', { id: 'r3', tenantId: TENANT_B, idempotencyKey: 'k-dup' })).not.toThrow();
    });

    it("does not update another tenant's run", async () => {
      const repo = new BacktestRepository(prisma);
      const runA = await repo.createRun(backtestInput(TENANT_A, 'run-a', 'k-a'));

      await expect(repo.updateStatus(runA.id, TENANT_B, 'FAILED', { errorCode: 'X' })).resolves.toBeNull();
      expect(prisma.rows('researchBacktestRun')[0]).toMatchObject({ status: 'QUEUED' });

      await expect(repo.updateStatus(runA.id, TENANT_A, 'RUNNING')).resolves.toMatchObject({ id: runA.id, status: 'RUNNING' });
    });
  });

  describe('PaperTradingRepository', () => {
    const session = (tenantId: string, sessionIdentifier: string, idempotencyKey: string) => ({
      tenantId,
      strategyVersionId: `sv-${tenantId}`,
      sessionIdentifier,
      initialCapital: '1000',
      idempotencyKey,
    });

    it("never returns another tenant's paper session for a replayed idempotency key", async () => {
      const repo = new PaperTradingRepository(prisma);
      const sessionA = await repo.createSession(session(TENANT_A, 's-a', 'k-shared'));

      const sessionB = await repo.createSession(session(TENANT_B, 's-b', 'k-shared'));
      expect(sessionB.id).not.toBe(sessionA.id);
      expect(sessionB).toMatchObject({ tenantId: TENANT_B });

      await expect(repo.createSession(session(TENANT_A, 's-a2', 'k-shared'))).resolves.toMatchObject({ id: sessionA.id });
      await expect(repo.createSession(session(TENANT_B, 's-b2', 'k-shared'))).resolves.toMatchObject({ id: sessionB.id });
    });

    it("does not update another tenant's paper session or paper order", async () => {
      const repo = new PaperTradingRepository(prisma);
      const sessionA = await repo.createSession(session(TENANT_A, 's-a', 'k-a'));
      prisma.seed('researchPaperOrder', { id: 'po-a', tenantId: TENANT_A, sessionId: sessionA.id, orderId: 'ord-a', status: 'NEW' });

      await expect(repo.updateSessionStatus(sessionA.id, TENANT_B, 'STOPPED')).resolves.toBeNull();
      await expect(repo.updatePaperOrderStatus('ord-a', TENANT_B, 'FILLED')).resolves.toBeNull();
      expect(prisma.rows('researchPaperSession')[0]).toMatchObject({ status: 'CREATED' });
      expect(prisma.rows('researchPaperOrder')[0]).toMatchObject({ status: 'NEW' });

      await expect(repo.updateSessionStatus(sessionA.id, TENANT_A, 'RUNNING')).resolves.toMatchObject({ status: 'RUNNING' });
      await expect(repo.updatePaperOrderStatus('ord-a', TENANT_A, 'FILLED')).resolves.toMatchObject({ status: 'FILLED' });
    });
  });

  describe('ResearchRepository', () => {
    it("scopes dataset and strategy-version idempotency keys and status updates to the tenant", async () => {
      const repo = new ResearchRepository(prisma);
      prisma.seed('researchDataset', { id: 'ds-a', tenantId: TENANT_A, fingerprint: 'fp-a', idempotencyKey: 'k-ds', status: 'DRAFT' });
      prisma.seed('researchStrategyVersion', { id: 'sv-a', tenantId: TENANT_A, fingerprint: 'fp-sv', idempotencyKey: 'k-sv', status: 'DRAFT', deletedAt: null });

      const datasetB = await repo.createDataset({
        tenantId: TENANT_B,
        name: 'b',
        venue: 'BINANCE',
        symbol: 'BTCUSDT',
        timeframe: '1h',
        source: 'test',
        startTime: new Date('2026-01-01T00:00:00Z'),
        endTime: new Date('2026-01-02T00:00:00Z'),
        fingerprint: 'fp-b',
        idempotencyKey: 'k-ds',
      });
      expect(datasetB.id).not.toBe('ds-a');
      expect(datasetB).toMatchObject({ tenantId: TENANT_B });

      const versionB = await repo.createStrategyVersion({
        tenantId: TENANT_B,
        version: '1',
        name: 'b',
        logicHash: 'l',
        configHash: 'c',
        fingerprint: 'fp-sv-b',
        idempotencyKey: 'k-sv',
      });
      expect(versionB.id).not.toBe('sv-a');
      expect(versionB).toMatchObject({ tenantId: TENANT_B });

      await expect(repo.updateDatasetStatus('ds-a', TENANT_B, ResearchDatasetStatus.INVALID)).resolves.toBeNull();
      await expect(repo.updateStrategyVersionStatus('sv-a', TENANT_B, ResearchStrategyVersionStatus.FROZEN)).resolves.toBeNull();
      expect(prisma.rows('researchDataset')[0]).toMatchObject({ id: 'ds-a', tenantId: TENANT_A, status: 'DRAFT' });
      expect(prisma.rows('researchStrategyVersion')[0]).toMatchObject({ id: 'sv-a', tenantId: TENANT_A, status: 'DRAFT' });

      await expect(repo.updateDatasetStatus('ds-a', TENANT_A, ResearchDatasetStatus.VALID)).resolves.toMatchObject({ status: 'VALID' });
    });
  });

  describe('SignalService', () => {
    it("neither replays nor expires another tenant's signal", async () => {
      const researchRepo = new ResearchRepository(prisma);
      const service = new SignalService(prisma, researchRepo);
      prisma.seed('researchStrategyVersion', { id: 'sv-b', tenantId: TENANT_B, status: 'PUBLISHED', deletedAt: null });
      prisma.seed('researchSignal', { id: 'sig-a', tenantId: TENANT_A, idempotencyKey: 'k-sig', state: 'VALID', signalKey: 'sig_a' });

      const signalB = await service.createSignal({
        tenantId: TENANT_B,
        strategyVersionId: 'sv-b',
        symbol: 'BTCUSDT',
        side: ResearchSignalSide.BUY,
        timestamp: new Date(),
        idempotencyKey: 'k-sig',
      });
      expect(signalB.id).not.toBe('sig-a');
      expect(prisma.rows('researchSignal').find((row: any) => row.id === signalB.id)).toMatchObject({ tenantId: TENANT_B });

      await expect(service.expireSignal(TENANT_B, 'sig-a')).resolves.toBeNull();
      expect(prisma.rows('researchSignal')[0]).toMatchObject({ state: 'VALID' });
      await expect(service.expireSignal(TENANT_A, 'sig-a')).resolves.toMatchObject({ state: 'EXPIRED' });
    });
  });

  describe('ResearchPromotionService', () => {
    it("does not return another tenant's promotion request for a replayed idempotency key", async () => {
      const researchRepo = new ResearchRepository(prisma);
      const policyService = { getPolicy: jest.fn(async () => ({ promotionPrerequisites: { requireBacktest: true } })) };
      const service = new ResearchPromotionService(prisma, researchRepo, new BacktestRepository(prisma), new PaperTradingRepository(prisma), policyService as any);
      prisma.seed('researchStrategyVersion', { id: 'sv-a', tenantId: TENANT_A, status: 'VALID', deletedAt: null });
      prisma.seed('researchStrategyVersion', { id: 'sv-b', tenantId: TENANT_B, status: 'VALID', deletedAt: null });
      prisma.seed('researchPromotionRequest', { id: 'pr-a', tenantId: TENANT_A, strategyVersionId: 'sv-a', idempotencyKey: 'k-pr', state: 'DRAFT' });

      // Tenant B's lookup misses, so the request is evaluated on its own merits (here: policy demands a backtest).
      await expect(service.createPromotionRequest({ tenantId: TENANT_B, strategyVersionId: 'sv-b', idempotencyKey: 'k-pr' })).rejects.toThrow(
        'Promotion requires backtest validation',
      );
      await expect(service.createPromotionRequest({ tenantId: TENANT_A, strategyVersionId: 'sv-a', idempotencyKey: 'k-pr' })).resolves.toMatchObject({
        id: 'pr-a',
      });
    });

    it("does not reject another tenant's promotion request", async () => {
      const researchRepo = new ResearchRepository(prisma);
      jest.spyOn(researchRepo, 'createAuditLog').mockResolvedValue({} as any);
      const service = new ResearchPromotionService(prisma, researchRepo, new BacktestRepository(prisma), new PaperTradingRepository(prisma), {} as any);
      prisma.seed('researchPromotionRequest', { id: 'pr-a', tenantId: TENANT_A, strategyVersionId: 'sv-a', state: 'DRAFT', reviewNotes: null });

      await expect(service.rejectPromotion(TENANT_B, 'pr-a', 'reviewer', 'no')).resolves.toBeNull();
      expect(prisma.rows('researchPromotionRequest')[0]).toMatchObject({ state: 'DRAFT' });
    });
  });
});

