import { SignalFilterService } from './signal-filter.service';

/**
 * Research signal filtering. The compliance check matched ANY open BLOCK case
 * in the tenant (one blocked customer stopped every research signal) and,
 * like the exchange-capability check, ignored lookup errors; a non-array
 * risk-profile blockedSymbols matched substrings or threw into an empty catch.
 */
function build(opts: {
  createdBy?: string | null;
  blockCaseFor?: string[];
  riskProfile?: unknown;
  tradingSymbol?: { isTradeable: boolean } | null;
  failing?: 'compliance' | 'tradingSymbol';
}) {
  const fail = (what: string) => async () => {
    throw new Error(`${what} lookup failed`);
  };
  const complianceFindFirst = jest.fn(
    opts.failing === 'compliance'
      ? fail('compliance')
      : async (args: any) => {
          const ids: string[] = args.where.userId?.in ?? [];
          return ids.some((id) => (opts.blockCaseFor ?? []).includes(id)) ? { id: 'case-1' } : null;
        },
  );
  const prisma = {
    researchSignal: {
      findFirst: jest.fn(async (args: any) =>
        args.where.id === 'sig-1'
          ? { id: 'sig-1', tenantId: 't1', strategyVersionId: 'v1', symbol: 'ETH-USDT', side: 'BUY', signalKey: 'k1', expiresAt: null }
          : null,
      ),
      update: jest.fn(async () => ({})),
    },
    complianceCase: { findFirst: complianceFindFirst },
    tradingSymbol: {
      findFirst: jest.fn(opts.failing === 'tradingSymbol' ? fail('tradingSymbol') : async () => opts.tradingSymbol ?? { isTradeable: true }),
    },
  };
  const researchRepo = {
    findStrategyVersionById: jest.fn(async () => ({
      id: 'v1',
      status: 'PUBLISHED',
      createdBy: opts.createdBy === undefined ? 'author-1' : opts.createdBy,
      riskProfile: opts.riskProfile ?? {},
    })),
    createAuditLog: jest.fn(async () => ({})),
  };
  return { service: new SignalFilterService(prisma as never, researchRepo as never), complianceFindFirst };
}

const run = (s: SignalFilterService, actorUserId: string | null = 'actor-1') => s.filterSignal({ tenantId: 't1', signalId: 'sig-1', actorUserId });

describe('SignalFilterService compliance and capability checks', () => {
  it("a BLOCK case on some other tenant user no longer stops the signal", async () => {
    const { service, complianceFindFirst } = build({ blockCaseFor: ['someone-else'] });
    await expect(run(service)).resolves.toMatchObject({ allowed: true, filteredState: 'VALID' });
    expect(complianceFindFirst).toHaveBeenCalledWith(
      expect.objectContaining({ where: expect.objectContaining({ tenantId: 't1', userId: { in: ['author-1', 'actor-1'] } }) }),
    );
  });

  it("a BLOCK case on the version's author or on the acting user stops it", async () => {
    await expect(run(build({ blockCaseFor: ['author-1'] }).service)).resolves.toMatchObject({ allowed: false, ruleId: 'COMPLIANCE_BLOCK' });
    await expect(run(build({ blockCaseFor: ['actor-1'] }).service)).resolves.toMatchObject({ allowed: false, ruleId: 'COMPLIANCE_BLOCK' });
  });

  it('failed compliance or symbol lookups propagate instead of allowing', async () => {
    await expect(run(build({ failing: 'compliance' }).service)).rejects.toThrow('compliance lookup failed');
    await expect(run(build({ failing: 'tradingSymbol' }).service)).rejects.toThrow('tradingSymbol lookup failed');
  });

  it('a known non-tradeable symbol is rejected; an unknown one is allowed with a warning', async () => {
    await expect(run(build({ tradingSymbol: { isTradeable: false } }).service)).resolves.toMatchObject({
      allowed: false,
      ruleId: 'EXCHANGE_NOT_TRADEABLE',
    });
    const unknown = build({});
    (unknown.service as any).prisma.tradingSymbol.findFirst.mockResolvedValueOnce(null);
    await expect(run(unknown.service)).resolves.toMatchObject({ allowed: true });
  });

  it('risk-profile blockedSymbols must be an array (a string matched substrings)', async () => {
    await expect(run(build({ riskProfile: { blockedSymbols: ['ETH-USDT'] } }).service)).resolves.toMatchObject({
      allowed: false,
      ruleId: 'RISK_BLOCKED_SYMBOL',
    });
    await expect(run(build({ riskProfile: { blockedSymbols: 'BTC-ETH-USDT-X' } }).service)).resolves.toMatchObject({ allowed: true });
  });

  it('with no author and no actor there is no compliance subject to look up', async () => {
    const { service, complianceFindFirst } = build({ createdBy: null });
    await expect(run(service, null)).resolves.toMatchObject({ allowed: true });
    expect(complianceFindFirst).not.toHaveBeenCalled();
  });
});

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { ResearchRepository } from './research-repository';

/**
 * Filters signals by symbol, side, strategy policy, cooldown, duplicate event, market state, and risk constraints before downstream handoff.
 * A rejected signal must include an explicit reason/rule reference.
 */
@Injectable()
export class SignalFilterService {
  private readonly logger = new Logger(SignalFilterService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly researchRepo: ResearchRepository,
  ) {}

  async filterSignal(input: {
    tenantId: string;
    signalId: string;
    allowedSymbols?: string[] | null;
    blockedSymbols?: string[] | null;
    allowedSides?: string[] | null;
    cooldownMs?: number | null;
    /** The user filtering/publishing the signal; checked for compliance blocks with the version's author. */
    actorUserId?: string | null;
  }): Promise<{ allowed: boolean; reason: string | null; ruleId: string | null; filteredState: string }> {
    const signal = await (this.prisma as any).researchSignal.findFirst({ where: { id: input.signalId, tenantId: input.tenantId } });
    if (!signal) throw new Error(`Signal ${input.signalId} not found`);

    // Symbol filter
    if (input.blockedSymbols && input.blockedSymbols.includes(signal.symbol)) {
      await this.rejectSignal(input.tenantId, input.signalId, `Symbol ${signal.symbol} is blocked`, 'BLOCKED_SYMBOL');
      return { allowed: false, reason: `Symbol ${signal.symbol} is blocked`, ruleId: 'BLOCKED_SYMBOL', filteredState: 'FILTERED' };
    }

    if (input.allowedSymbols && input.allowedSymbols.length > 0 && !input.allowedSymbols.includes(signal.symbol)) {
      await this.rejectSignal(input.tenantId, input.signalId, `Symbol ${signal.symbol} not in allowed list`, 'ALLOWED_SYMBOL');
      return { allowed: false, reason: `Symbol ${signal.symbol} not in allowed list`, ruleId: 'ALLOWED_SYMBOL', filteredState: 'FILTERED' };
    }

    // Allowed side
    if (input.allowedSides && input.allowedSides.length > 0 && !input.allowedSides.includes(signal.side)) {
      await this.rejectSignal(input.tenantId, input.signalId, `Side ${signal.side} not allowed`, 'ALLOWED_SIDE');
      return { allowed: false, reason: `Side ${signal.side} not allowed`, ruleId: 'ALLOWED_SIDE', filteredState: 'FILTERED' };
    }

    // Cooldown check - prevent duplicate signals within cooldown
    if (input.cooldownMs && input.cooldownMs > 0) {
      const cooldownSince = new Date(Date.now() - input.cooldownMs);
      const recentDuplicate = await (this.prisma as any).researchSignal.findFirst({
        where: {
          tenantId: input.tenantId,
          strategyVersionId: signal.strategyVersionId,
          symbol: signal.symbol,
          side: signal.side,
          state: 'PUBLISHED',
          createdAt: { gte: cooldownSince },
          id: { not: signal.id },
        },
      });

      if (recentDuplicate) {
        await this.rejectSignal(input.tenantId, input.signalId, `Cooldown active: duplicate signal within ${input.cooldownMs}ms, recent=${recentDuplicate.id}`, 'COOLDOWN');
        return { allowed: false, reason: `Cooldown active: duplicate signal within ${input.cooldownMs}ms`, ruleId: 'COOLDOWN', filteredState: 'FILTERED' };
      }
    }

    // Strategy state check - strategy version must be PUBLISHED
    const strategyVersion = await this.researchRepo.findStrategyVersionById(signal.strategyVersionId, input.tenantId);
    if (!strategyVersion) {
      await this.rejectSignal(input.tenantId, input.signalId, 'Strategy version not found', 'STRATEGY_NOT_FOUND');
      return { allowed: false, reason: 'Strategy version not found', ruleId: 'STRATEGY_NOT_FOUND', filteredState: 'REJECTED' };
    }

    if (!['PUBLISHED','FROZEN'].includes(strategyVersion.status)) {
      await this.rejectSignal(input.tenantId, input.signalId, `Strategy version status ${strategyVersion.status} not allowed for signal publishing`, 'STRATEGY_STATE');
      return { allowed: false, reason: `Strategy version status ${strategyVersion.status} not allowed`, ruleId: 'STRATEGY_STATE', filteredState: 'REJECTED' };
    }

    // Risk constraints - the version's risk profile may block symbols. Only an
    // array counts: a string used to match substrings ('BTC-USDT,ETH' blocked
    // 'ETH') and anything else threw into an empty catch and allowed.
    const blockedByProfile = (strategyVersion.riskProfile as { blockedSymbols?: unknown } | null)?.blockedSymbols;
    if (Array.isArray(blockedByProfile) && blockedByProfile.includes(signal.symbol)) {
      await this.rejectSignal(input.tenantId, input.signalId, `Symbol ${signal.symbol} blocked by risk profile`, 'RISK_BLOCKED_SYMBOL');
      return { allowed: false, reason: `Symbol ${signal.symbol} blocked by risk profile`, ruleId: 'RISK_BLOCKED_SYMBOL', filteredState: 'REJECTED' };
    }

    // Compliance: an open BLOCK case on the version's author or on the user
    // acting now stops the signal. This used to match ANY open BLOCK case in
    // the tenant (one blocked customer stopped every research signal) and to
    // ignore lookup errors. A failed lookup now propagates (no publish).
    const subjects = [strategyVersion.createdBy, input.actorUserId].filter((u): u is string => typeof u === 'string' && u.length > 0);
    if (subjects.length > 0) {
      const complianceCase = await this.prisma.complianceCase.findFirst({
        where: { tenantId: input.tenantId, userId: { in: subjects }, decision: 'BLOCK', state: { in: ['OPEN', 'IN_REVIEW', 'ESCALATED'] } },
        select: { id: true },
      });
      if (complianceCase) {
        await this.rejectSignal(input.tenantId, input.signalId, 'Compliance BLOCK prevents signal', 'COMPLIANCE_BLOCK');
        return { allowed: false, reason: 'Compliance BLOCK prevents signal', ruleId: 'COMPLIANCE_BLOCK', filteredState: 'REJECTED' };
      }
    }

    // Exchange capability - a known, non-tradeable symbol is rejected; an
    // unknown symbol is allowed with a warning (research may precede venue
    // listing). A failed lookup propagates instead of allowing.
    const tradingSymbol = await this.prisma.tradingSymbol.findFirst({ where: { tenantId: input.tenantId, symbol: signal.symbol } });
    if (!tradingSymbol) {
      this.logger.warn(`Symbol ${signal.symbol} not found in trading symbols tenant=${input.tenantId} - allowing but flagged`);
    } else if (!tradingSymbol.isTradeable) {
      await this.rejectSignal(input.tenantId, input.signalId, `Symbol ${signal.symbol} not tradeable`, 'EXCHANGE_NOT_TRADEABLE');
      return { allowed: false, reason: `Symbol ${signal.symbol} not tradeable`, ruleId: 'EXCHANGE_NOT_TRADEABLE', filteredState: 'REJECTED' };
    }

    // Time validity - check expiry
    if (signal.expiresAt && new Date(signal.expiresAt).getTime() < Date.now()) {
      await this.rejectSignal(input.tenantId, input.signalId, 'Signal expired', 'EXPIRED');
      return { allowed: false, reason: 'Signal expired', ruleId: 'EXPIRED', filteredState: 'EXPIRED' };
    }

    // Duplicate event - check if same signalKey already published
    const duplicateEvent = await (this.prisma as any).researchSignal.findFirst({
      where: { tenantId: input.tenantId, signalKey: signal.signalKey, state: 'PUBLISHED', id: { not: signal.id } },
    });
    if (duplicateEvent) {
      await this.rejectSignal(input.tenantId, input.signalId, `Duplicate event: signalKey ${signal.signalKey} already published as ${duplicateEvent.id}`, 'DUPLICATE_EVENT');
      return { allowed: false, reason: `Duplicate event: signalKey ${signal.signalKey} already published`, ruleId: 'DUPLICATE_EVENT', filteredState: 'FILTERED' };
    }

    this.logger.log(`Signal filter passed tenant=${input.tenantId} signal=${input.signalId} symbol=${signal.symbol} side=${signal.side}`);

    return { allowed: true, reason: null, ruleId: null, filteredState: 'VALID' };
  }

  private async rejectSignal(tenantId: string, signalId: string, reason: string, ruleId: string): Promise<void> {
    try {
      await (this.prisma as any).researchSignal.update({ where: { id: signalId, tenantId }, data: { state: 'REJECTED', updatedAt: new Date() } });

      await this.researchRepo.createAuditLog({
        tenantId,
        event: 'SIGNAL_REJECTED',
        signalId,
        result: 'REJECTED',
        safeMetadata: { reason, ruleId },
      });

      this.logger.log(`Signal rejected tenant=${tenantId} signal=${signalId} reason=${reason} rule=${ruleId}`);
    } catch {}
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { ResearchRepository } from './research-repository';
import { ResearchSignalSide } from './signal.types';
import { randomUUID, createHash } from 'crypto';
import { isRecordNotFound } from '../../common/errors/prisma-not-found';

/**
 * Creates, validates, deduplicates, stores, and publishes strategy signals to the existing strategy/copy-trading integration boundary.
 * Do not place exchange orders here.
 */
@Injectable()
export class SignalService {
  private readonly logger = new Logger(SignalService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly researchRepo: ResearchRepository,
  ) {}

  private fingerprintSignal(input: { strategyVersionId: string; symbol: string; side: string; timestamp: string; price?: string | null; quantity?: string | null }): string {
    const hash = createHash('sha256');
    hash.update(`${input.strategyVersionId}|${input.symbol}|${input.side}|${input.timestamp}|${input.price||''}|${input.quantity||''}`);
    return hash.digest('hex');
  }

  async createSignal(input: {
    tenantId: string;
    strategyVersionId: string;
    symbol: string;
    side: ResearchSignalSide;
    strength?: string | null;
    confidence?: string | null;
    price?: string | null;
    quantity?: string | null;
    timestamp: Date;
    expiresAt?: Date | null;
    sourceEvent?: Record<string, any> | null;
    metadata?: Record<string, any>;
    idempotencyKey?: string | null;
    createdBy?: string | null;
  }): Promise<any> {
    // Validate strategy version exists and is PUBLISHED
    const strategyVersion = await this.researchRepo.findStrategyVersionById(input.strategyVersionId, input.tenantId);
    if (!strategyVersion) throw new Error(`Strategy version ${input.strategyVersionId} not found`);
    if (!['PUBLISHED','FROZEN'].includes(strategyVersion.status)) throw new Error(`Strategy version must be PUBLISHED/FROZEN to create signals, current=${strategyVersion.status}`);

    // Validate symbol format
    if (!input.symbol || input.symbol.length < 2) throw new Error('Symbol required');

    // Validate side
    if (!Object.values(ResearchSignalSide).includes(input.side as any)) throw new Error(`Invalid signal side ${input.side}`);

    // Decimal validation
    if (input.price && !/^-?\d+(\.\d+)?$/.test(input.price)) throw new Error('price must be valid decimal string');
    if (input.quantity && !/^-?\d+(\.\d+)?$/.test(input.quantity)) throw new Error('quantity must be valid decimal string');

    const fingerprint = this.fingerprintSignal({
      strategyVersionId: input.strategyVersionId,
      symbol: input.symbol,
      side: input.side,
      timestamp: input.timestamp.toISOString(),
      price: input.price || null,
      quantity: input.quantity || null,
    });

    const signalKey = `sig_${fingerprint.substring(0,16)}_${Date.now()}`;

    // Idempotency - deduplicate
    if (input.idempotencyKey) {
      const existingByKey = await (this.prisma as any).researchSignal.findFirst({ where: { tenantId: input.tenantId, idempotencyKey: input.idempotencyKey } });
      if (existingByKey) {
        this.logger.log(`Signal idempotent by key=${input.idempotencyKey}`);
        return existingByKey;
      }
    }

    const existingByFingerprint = await (this.prisma as any).researchSignal.findFirst({ where: { tenantId: input.tenantId, signalKey } });
    if (existingByFingerprint) {
      this.logger.log(`Signal duplicate by key=${signalKey}`);
      return existingByFingerprint;
    }

    const id = randomUUID();
    const data = {
      id,
      tenantId: input.tenantId,
      strategyVersionId: input.strategyVersionId,
      signalKey,
      symbol: input.symbol,
      side: input.side,
      strength: input.strength || null,
      confidence: input.confidence || null,
      price: input.price || null,
      quantity: input.quantity || null,
      timestamp: input.timestamp,
      expiresAt: input.expiresAt || null,
      state: 'DRAFT',
      sourceEvent: input.sourceEvent || null,
      metadata: input.metadata || {},
      idempotencyKey: input.idempotencyKey || `sig_${input.tenantId}_${fingerprint.substring(0,16)}_${Date.now()}`,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    try {
      const created = await (this.prisma as any).researchSignal.create({ data });

      await this.researchRepo.createAuditLog({
        tenantId: input.tenantId,
        event: 'SIGNAL_CREATED',
        actorId: input.createdBy || null,
        strategyVersionId: input.strategyVersionId,
        signalId: created.id,
        result: 'SUCCESS',
        safeMetadata: { signalKey, symbol: input.symbol, side: input.side, strength: input.strength },
      });

      this.logger.log(`Signal created id=${created.id} tenant=${input.tenantId} symbol=${input.symbol} side=${input.side}`);

      return created;
    } catch (e: any) {
      if (e.code === 'P2002') {
        const existing = await (this.prisma as any).researchSignal.findFirst({ where: { tenantId: input.tenantId, signalKey } });
        if (existing) return existing;
      }
      throw e;
    }
  }

  async validateSignal(tenantId: string, signalId: string): Promise<any | null> {
    const signal = await (this.prisma as any).researchSignal.findFirst({ where: { id: signalId, tenantId } });
    if (!signal) return null;

    if (signal.state !== 'DRAFT') throw new Error(`Only DRAFT signal can be validated, current=${signal.state}`);

    // Check expiry
    if (signal.expiresAt && new Date(signal.expiresAt).getTime() < Date.now()) {
      const updated = await (this.prisma as any).researchSignal.update({ where: { id: signalId, tenantId }, data: { state: 'EXPIRED', updatedAt: new Date() } });
      return updated;
    }

    const updated = await (this.prisma as any).researchSignal.update({ where: { id: signalId, tenantId }, data: { state: 'VALID', updatedAt: new Date() } });

    return updated;
  }

  async publishSignal(tenantId: string, signalId: string, actorId: string): Promise<any | null> {
    const signal = await (this.prisma as any).researchSignal.findFirst({ where: { id: signalId, tenantId } });
    if (!signal) return null;

    if (signal.state !== 'VALID') throw new Error(`Only VALID signal can be published, current=${signal.state}`);

    const updated = await (this.prisma as any).researchSignal.update({ where: { id: signalId, tenantId }, data: { state: 'PUBLISHED', updatedAt: new Date() } });

    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'SIGNAL_PUBLISHED',
      actorId,
      strategyVersionId: signal.strategyVersionId,
      signalId,
      result: 'SUCCESS',
      safeMetadata: { signalKey: signal.signalKey, symbol: signal.symbol, side: signal.side },
    });

    this.logger.log(`Signal published id=${signalId} tenant=${tenantId} symbol=${signal.symbol} side=${signal.side} - downstream handoff to copy-trading`);

    return updated;
  }

  async expireSignal(tenantId: string, signalId: string): Promise<any | null> {
    try {
      return await (this.prisma as any).researchSignal.update({ where: { id: signalId, tenantId }, data: { state: 'EXPIRED', updatedAt: new Date() } });
    } catch (error) {
      if (isRecordNotFound(error)) return null;
      throw error;
    }
  }

  async revokeSignal(tenantId: string, signalId: string, actorId: string, reason?: string): Promise<any | null> {
    const signal = await (this.prisma as any).researchSignal.findFirst({ where: { id: signalId, tenantId } });
    if (!signal) return null;

    const updated = await (this.prisma as any).researchSignal.update({ where: { id: signalId, tenantId }, data: { state: 'REVOKED', updatedAt: new Date() } });

    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'SIGNAL_REVOKED',
      actorId,
      strategyVersionId: signal.strategyVersionId,
      signalId,
      result: 'SUCCESS',
      safeMetadata: { reason: reason || 'Manual revoke' },
    });

    return updated;
  }

  async findById(tenantId: string, signalId: string): Promise<any | null> {
    return (this.prisma as any).researchSignal.findFirst({ where: { id: signalId, tenantId } }) || null;
  }

  async listByStrategyVersion(tenantId: string, strategyVersionId: string, filters?: { state?: string; symbol?: string; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const skip = (page - 1) * limit;
    const where: any = { tenantId, strategyVersionId, ...(filters?.state ? { state: filters.state } : {}), ...(filters?.symbol ? { symbol: filters.symbol } : {}) };
    const [data, total] = await Promise.all([
      (this.prisma as any).researchSignal.findMany({ where, orderBy: { timestamp: 'desc' }, skip, take: limit }),
      (this.prisma as any).researchSignal.count({ where }),
    ]);
    return { data, total };
  }

  async listByTenant(tenantId: string, filters?: { state?: string; symbol?: string; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const skip = (page - 1) * limit;
    const where: any = { tenantId, ...(filters?.state ? { state: filters.state } : {}), ...(filters?.symbol ? { symbol: filters.symbol } : {}) };
    const [data, total] = await Promise.all([
      (this.prisma as any).researchSignal.findMany({ where, orderBy: { timestamp: 'desc' }, skip, take: limit }),
      (this.prisma as any).researchSignal.count({ where }),
    ]);
    return { data, total };
  }
}

/**
 * Canonical signal domain types: signal key, side, strength, timestamp, symbol, strategy version, confidence metadata, and signal lifecycle.
 */

export enum ResearchSignalState {
  DRAFT = 'DRAFT',
  VALID = 'VALID',
  PUBLISHED = 'PUBLISHED',
  EXPIRED = 'EXPIRED',
  REVOKED = 'REVOKED',
  REJECTED = 'REJECTED',
  FILTERED = 'FILTERED',
}

export enum ResearchSignalSide {
  BUY = 'BUY',
  SELL = 'SELL',
  HOLD = 'HOLD',
  CLOSE_LONG = 'CLOSE_LONG',
  CLOSE_SHORT = 'CLOSE_SHORT',
}

export interface ResearchSignal {
  signalId: string;
  tenantId: string;
  strategyVersionId: string;
  signalKey: string;
  symbol: string;
  side: ResearchSignalSide;
  strength: string | null;
  confidence: string | null;
  price: string | null;
  quantity: string | null;
  timestamp: string;
  expiresAt: string | null;
  state: ResearchSignalState;
  sourceEvent: Record<string, any> | null;
  metadata: Record<string, any>;
  idempotencyKey: string;
  createdAt: string;
  updatedAt: string;
}

export interface SignalFilterResult {
  allowed: boolean;
  reason: string | null;
  ruleId: string | null;
  filteredState: ResearchSignalState;
}

export interface SignalPublishResult {
  signalId: string;
  published: boolean;
  reason: string | null;
  downstream: string | null;
}

import { Injectable, Logger } from '@nestjs/common';
import { BacktestRepository } from './backtest-repository';
import { ResearchRepository } from './research-repository';
import { MarketDataService } from './market-data-service';

/**
 * Compares strategy results against configured benchmarks using the same timeframe/dataset boundaries.
 * Use identical period boundaries and currency assumptions. Do not invent benchmark data.
 */
@Injectable()
export class StrategyBenchmarkService {
  private readonly logger = new Logger(StrategyBenchmarkService.name);

  constructor(
    private readonly backtestRepo: BacktestRepository,
    private readonly researchRepo: ResearchRepository,
    private readonly marketDataService: MarketDataService,
  ) {}

  async compareBenchmark(input: {
    tenantId: string;
    backtestRunId: string;
    benchmarkSymbol: string;
    benchmarkType?: 'BUY_AND_HOLD' | 'MARKET_INDEX';
    createdBy?: string | null;
  }): Promise<{ benchmarkSymbol: string; benchmarkReturn: string | null; strategyReturn: string | null; excessReturn: string | null; correlation: string | null; methodology: string; isSimulated: true }> {
    const backtestRun = await this.backtestRepo.findById(input.backtestRunId, input.tenantId);
    if (!backtestRun) throw new Error(`Backtest run ${input.backtestRunId} not found`);

    // Use identical period boundaries and currency assumptions
    const startTime = new Date(backtestRun.startTime).toISOString();
    const endTime = new Date(backtestRun.endTime).toISOString();
    const timeframe = backtestRun.timeframe;

    // Get benchmark data - do not invent benchmark data
    let benchmarkReturn: string | null = null;
    let benchmarkCandles: any[] = [];

    try {
      const benchmarkData = await this.marketDataService.getCandles({
        tenantId: input.tenantId,
        venue: 'BINANCE',
        symbol: input.benchmarkSymbol,
        timeframe,
        startTime,
        endTime,
      });

      benchmarkCandles = benchmarkData.candles;

      if (benchmarkCandles.length >= 2) {
        const firstClose = parseFloat(benchmarkCandles[0].close);
        const lastClose = parseFloat(benchmarkCandles[benchmarkCandles.length-1].close);
        if (firstClose > 0) {
          const ret = ((lastClose - firstClose) / firstClose) * 100;
          benchmarkReturn = ret.toString();
        }
      }
    } catch (e: any) {
      this.logger.warn(`Benchmark data unavailable symbol=${input.benchmarkSymbol} error=${e.message} - do not invent benchmark data`);
      throw new Error(`Benchmark data unavailable for ${input.benchmarkSymbol} from ${startTime} to ${endTime}: ${e.message}. Do not invent benchmark data.`);
    }

    const strategyReturn = backtestRun.metrics ? (backtestRun.metrics as any).totalReturnPercent || (backtestRun.metrics as any).totalReturn || null : null;

    let excessReturn: string | null = null;
    if (benchmarkReturn !== null && strategyReturn !== null) {
      const b = parseFloat(benchmarkReturn);
      const s = parseFloat(strategyReturn);
      if (!isNaN(b) && !isNaN(s)) excessReturn = (s - b).toString();
    }

    // Correlation - simplified
    let correlation: string | null = null;
    try {
      const snapshots = await this.backtestRepo.listSnapshots(input.tenantId, input.backtestRunId);
      if (snapshots.length > 1 && benchmarkCandles.length > 1) {
        // Align by timestamp and calculate correlation of returns
        const stratReturns: number[] = [];
        const benchReturns: number[] = [];

        for (let i=1; i<Math.min(snapshots.length, benchmarkCandles.length); i++) {
          const prevStrat = parseFloat(snapshots[i-1].equity);
          const currStrat = parseFloat(snapshots[i].equity);
          if (prevStrat > 0) stratReturns.push((currStrat - prevStrat) / prevStrat);

          const prevBench = parseFloat(benchmarkCandles[i-1].close);
          const currBench = parseFloat(benchmarkCandles[i].close);
          if (prevBench > 0) benchReturns.push((currBench - prevBench) / prevBench);
        }

        if (stratReturns.length > 2 && benchReturns.length === stratReturns.length) {
          const meanStrat = stratReturns.reduce((a,b)=>a+b,0) / stratReturns.length;
          const meanBench = benchReturns.reduce((a,b)=>a+b,0) / benchReturns.length;
          let num = 0, denStrat = 0, denBench = 0;
          for (let i=0; i<stratReturns.length; i++) {
            num += (stratReturns[i] - meanStrat) * (benchReturns[i] - meanBench);
            denStrat += Math.pow(stratReturns[i] - meanStrat, 2);
            denBench += Math.pow(benchReturns[i] - meanBench, 2);
          }
          const den = Math.sqrt(denStrat * denBench);
          if (den > 0) correlation = (num / den).toString();
        }
      }
    } catch {}

    const methodology = `Benchmark comparison using identical period boundaries ${startTime} to ${endTime}, timeframe ${timeframe}, currency ${backtestRun.quoteCurrency}. Benchmark type ${input.benchmarkType || 'BUY_AND_HOLD'}. Do not invent benchmark data. Simulated result.`;

    this.logger.log(`Benchmark comparison completed tenant=${input.tenantId} backtest=${input.backtestRunId} benchmark=${input.benchmarkSymbol} strategyReturn=${strategyReturn} benchmarkReturn=${benchmarkReturn}`);

    return {
      benchmarkSymbol: input.benchmarkSymbol,
      benchmarkReturn,
      strategyReturn,
      excessReturn,
      correlation,
      methodology,
      isSimulated: true,
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { ResearchRepository } from './research-repository';
import { ResearchStrategyVersionStatus } from './research.types';
import { createHash } from 'crypto';
import { isRecordNotFound } from '../../common/errors/prisma-not-found';

/**
 * Immutable strategy-version lifecycle: draft, validate, freeze, publish, deprecate, and version comparison using existing strategy references.
 * Once frozen/published, do not mutate logic/configuration in place. Create new version instead.
 */
@Injectable()
export class StrategyVersionService {
  private readonly logger = new Logger(StrategyVersionService.name);

  constructor(private readonly researchRepo: ResearchRepository) {}

  private hashLogic(logic: Record<string, any>): string {
    const h = createHash('sha256');
    h.update(JSON.stringify(logic, Object.keys(logic).sort()));
    return h.digest('hex');
  }

  private hashConfig(config: Record<string, any>): string {
    const h = createHash('sha256');
    h.update(JSON.stringify(config, Object.keys(config).sort()));
    return h.digest('hex');
  }

  private fingerprintVersion(input: { logicHash: string; configHash: string; parameters: Record<string, any>; name: string; version: string }): string {
    const h = createHash('sha256');
    h.update(`${input.logicHash}|${input.configHash}|${JSON.stringify(input.parameters)}|${input.name}|${input.version}`);
    return h.digest('hex');
  }

  async createDraftVersion(input: {
    tenantId: string;
    strategyId?: string | null;
    traderStrategyId?: string | null;
    definitionId?: string | null;
    version: string;
    name: string;
    description?: string | null;
    parameters?: Record<string, any>;
    riskProfile?: Record<string, any>;
    executionModel?: Record<string, any>;
    logic?: Record<string, any>;
    parentVersionId?: string | null;
    changeNote?: string | null;
    createdBy?: string | null;
    idempotencyKey?: string | null;
  }): Promise<any> {
    // Validate version format
    if (!/^\d+\.\d+\.\d+$/.test(input.version)) {
      throw new Error(`Version must be semver format x.y.z, got ${input.version}`);
    }

    const logicHash = this.hashLogic(input.logic || { name: input.name, version: input.version });
    const configHash = this.hashConfig({ parameters: input.parameters, riskProfile: input.riskProfile, executionModel: input.executionModel });
    const fingerprint = this.fingerprintVersion({ logicHash, configHash, parameters: input.parameters || {}, name: input.name, version: input.version });

    const created = await this.researchRepo.createStrategyVersion({
      tenantId: input.tenantId,
      strategyId: input.strategyId || null,
      traderStrategyId: input.traderStrategyId || null,
      definitionId: input.definitionId || null,
      version: input.version,
      name: input.name,
      description: input.description || null,
      logicHash,
      configHash,
      fingerprint,
      parameters: input.parameters || {},
      riskProfile: input.riskProfile || {},
      executionModel: input.executionModel || {},
      parentVersionId: input.parentVersionId || null,
      changeNote: input.changeNote || null,
      createdBy: input.createdBy || null,
      idempotencyKey: input.idempotencyKey || null,
    });

    await this.researchRepo.createAuditLog({
      tenantId: input.tenantId,
      event: 'STRATEGY_VERSION_CREATED',
      actorId: input.createdBy || null,
      strategyVersionId: created.id,
      result: 'SUCCESS',
      safeMetadata: { version: input.version, name: input.name, fingerprint },
    });

    this.logger.log(`Strategy version draft created id=${created.id} tenant=${input.tenantId} version=${input.version}`);

    return created;
  }

  async getVersion(tenantId: string, versionId: string): Promise<any | null> {
    return this.researchRepo.findStrategyVersionById(versionId, tenantId);
  }

  async listVersions(tenantId: string, filters?: { strategyId?: string; status?: string; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    return this.researchRepo.listStrategyVersions(tenantId, filters);
  }

  async updateDraft(tenantId: string, versionId: string, actorId: string, updates: { name?: string; description?: string | null; parameters?: Record<string, any>; riskProfile?: Record<string, any>; executionModel?: Record<string, any>; changeNote?: string | null }): Promise<any | null> {
    const existing = await this.researchRepo.findStrategyVersionById(versionId, tenantId);
    if (!existing) return null;

    // Once frozen/published, do not mutate in place
    if (['FROZEN','PUBLISHED','DEPRECATED','ARCHIVED'].includes(existing.status)) {
      throw new Error(`Strategy version ${versionId} is ${existing.status} and immutable. Create a new version instead.`);
    }

    // Only DRAFT and VALID can be updated
    if (!['DRAFT','VALIDATING','VALID'].includes(existing.status)) {
      throw new Error(`Strategy version ${versionId} status ${existing.status} cannot be updated`);
    }

    const newParams = updates.parameters || existing.parameters;
    const newRisk = updates.riskProfile || existing.riskProfile;
    const newExec = updates.executionModel || existing.executionModel;
    const newName = updates.name || existing.name;

    const configHash = this.hashConfig({ parameters: newParams, riskProfile: newRisk, executionModel: newExec });
    const fingerprint = this.fingerprintVersion({ logicHash: existing.logicHash, configHash, parameters: newParams, name: newName, version: existing.version });

    try {
      const updated = await (this.researchRepo as any).prisma.researchStrategyVersion.update({
        where: { id: versionId, tenantId },
        data: {
          name: newName,
          description: updates.description !== undefined ? updates.description : existing.description,
          parameters: newParams,
          riskProfile: newRisk,
          executionModel: newExec,
          configHash,
          fingerprint,
          changeNote: updates.changeNote || existing.changeNote,
          updatedAt: new Date(),
        },
      });

      await this.researchRepo.createAuditLog({
        tenantId,
        event: 'STRATEGY_VERSION_UPDATED',
        actorId,
        strategyVersionId: versionId,
        result: 'SUCCESS',
        safeMetadata: { name: newName, fingerprint },
      });

      return updated;
    } catch (error) {
      if (isRecordNotFound(error)) return null;
      throw error;
    }
  }

  async validateVersion(tenantId: string, versionId: string, actorId: string): Promise<any | null> {
    const existing = await this.researchRepo.findStrategyVersionById(versionId, tenantId);
    if (!existing) return null;

    if (existing.status !== 'DRAFT') throw new Error(`Only DRAFT can be validated, current=${existing.status}`);

    // Perform validation - check parameters not contain executable code
    const params = existing.parameters as any;
    if (params && typeof params === 'object') {
      const forbiddenKeys = ['eval','exec','Function','code','script','__proto__'];
      for (const key of Object.keys(params)) {
        if (forbiddenKeys.some(f => key.toLowerCase().includes(f.toLowerCase()))) {
          throw new Error(`Parameter key ${key} contains forbidden executable reference`);
        }
        const val = params[key];
        if (typeof val === 'string' && (val.includes('eval(') || val.includes('Function(') || val.includes('<script'))) {
          throw new Error(`Parameter ${key} contains forbidden executable code`);
        }
      }
    }

    const updated = await this.researchRepo.updateStrategyVersionStatus(versionId, tenantId, ResearchStrategyVersionStatus.VALID as any);

    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'STRATEGY_VERSION_VALIDATED',
      actorId,
      strategyVersionId: versionId,
      result: 'SUCCESS',
      safeMetadata: { version: existing.version },
    });

    return updated;
  }

  async freezeVersion(tenantId: string, versionId: string, actorId: string): Promise<any | null> {
    const existing = await this.researchRepo.findStrategyVersionById(versionId, tenantId);
    if (!existing) return null;

    if (!['VALID','DRAFT'].includes(existing.status)) throw new Error(`Only VALID/DRAFT can be frozen, current=${existing.status}`);

    const updated = await this.researchRepo.updateStrategyVersionStatus(versionId, tenantId, ResearchStrategyVersionStatus.FROZEN as any, { frozenAt: new Date() });

    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'STRATEGY_VERSION_FROZEN',
      actorId,
      strategyVersionId: versionId,
      result: 'SUCCESS',
      safeMetadata: { version: existing.version, fingerprint: existing.fingerprint },
    });

    this.logger.log(`Strategy version frozen id=${versionId} tenant=${tenantId}`);

    return updated;
  }

  async publishVersion(tenantId: string, versionId: string, actorId: string): Promise<any | null> {
    const existing = await this.researchRepo.findStrategyVersionById(versionId, tenantId);
    if (!existing) return null;

    if (existing.status !== 'FROZEN') throw new Error(`Only FROZEN can be published, current=${existing.status}. Freeze first.`);

    const updated = await this.researchRepo.updateStrategyVersionStatus(versionId, tenantId, ResearchStrategyVersionStatus.PUBLISHED as any, { publishedAt: new Date() });

    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'STRATEGY_VERSION_PUBLISHED',
      actorId,
      strategyVersionId: versionId,
      result: 'SUCCESS',
      safeMetadata: { version: existing.version, fingerprint: existing.fingerprint },
    });

    this.logger.log(`Strategy version published id=${versionId} tenant=${tenantId}`);

    return updated;
  }

  async deprecateVersion(tenantId: string, versionId: string, actorId: string): Promise<any | null> {
    const existing = await this.researchRepo.findStrategyVersionById(versionId, tenantId);
    if (!existing) return null;

    if (existing.status !== 'PUBLISHED') throw new Error(`Only PUBLISHED can be deprecated, current=${existing.status}`);

    const updated = await this.researchRepo.updateStrategyVersionStatus(versionId, tenantId, ResearchStrategyVersionStatus.DEPRECATED as any, { deprecatedAt: new Date() });

    await this.researchRepo.createAuditLog({
      tenantId,
      event: 'STRATEGY_VERSION_DEPRECATED',
      actorId,
      strategyVersionId: versionId,
      result: 'SUCCESS',
      safeMetadata: { version: existing.version },
    });

    return updated;
  }

  async compareVersions(tenantId: string, versionIdA: string, versionIdB: string): Promise<{ differences: Record<string, any>; isSameLogic: boolean; isSameConfig: boolean }> {
    const a = await this.researchRepo.findStrategyVersionById(versionIdA, tenantId);
    const b = await this.researchRepo.findStrategyVersionById(versionIdB, tenantId);
    if (!a || !b) throw new Error('One or both versions not found');

    const isSameLogic = a.logicHash === b.logicHash;
    const isSameConfig = a.configHash === b.configHash;

    const differences: Record<string, any> = {};
    if (a.version !== b.version) differences.version = { a: a.version, b: b.version };
    if (a.name !== b.name) differences.name = { a: a.name, b: b.name };
    if (JSON.stringify(a.parameters) !== JSON.stringify(b.parameters)) differences.parameters = { a: a.parameters, b: b.parameters };
    if (JSON.stringify(a.riskProfile) !== JSON.stringify(b.riskProfile)) differences.riskProfile = { a: a.riskProfile, b: b.riskProfile };
    if (JSON.stringify(a.executionModel) !== JSON.stringify(b.executionModel)) differences.executionModel = { a: a.executionModel, b: b.executionModel };
    if (a.logicHash !== b.logicHash) differences.logicHash = { a: a.logicHash, b: b.logicHash };
    if (a.configHash !== b.configHash) differences.configHash = { a: a.configHash, b: b.configHash };

    return { differences, isSameLogic, isSameConfig };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { BacktestRepository } from './backtest-repository';
import { ResearchRepository } from './research-repository';
import { BacktestEngineService } from './backtest-engine.service';
import { ResearchPolicyService } from './research-policy.service';


/**
 * Performs rolling train/test or validation windows with explicit out-of-sample boundaries and leakage protection.
 * Critical: Do not allow future test data to enter training/parameter selection. Every split must be explicit.
 */
@Injectable()
export class WalkForwardService {
  private readonly logger = new Logger(WalkForwardService.name);

  constructor(
    private readonly backtestRepo: BacktestRepository,
    private readonly researchRepo: ResearchRepository,
    private readonly backtestEngine: BacktestEngineService,
    private readonly policyService: ResearchPolicyService,
  ) {}

  async runWalkForward(input: {
    tenantId: string;
    strategyVersionId: string;
    symbols: string[];
    timeframe: string;
    startTime: string;
    endTime: string;
    initialCapital: string;
    trainingWindowDays: number;
    testingWindowDays: number;
    validationWindowDays?: number;
    mode: 'ROLLING' | 'EXPANDING';
    stepDays?: number;
    createdBy?: string | null;
    idempotencyKey?: string | null;
  }): Promise<{ windows: any[]; results: any[]; aggregatedMetrics: Record<string, any>; outOfSampleMetrics: Record<string, any> }> {
    const policy = await this.policyService.getPolicy(input.tenantId);
    if (input.trainingWindowDays <= 0 || input.testingWindowDays <= 0) throw new Error('Training and testing windows must be positive');

    const totalDurationDays = (new Date(input.endTime).getTime() - new Date(input.startTime).getTime()) / (1000*60*60*24);
    const expectedWindows = Math.floor(totalDurationDays / (input.trainingWindowDays + input.testingWindowDays));
    if (expectedWindows > policy.maxWalkForwardWindows) throw new Error(`Walk-forward windows ${expectedWindows} exceeds max ${policy.maxWalkForwardWindows}`);

    // Idempotency
    if (input.idempotencyKey) {
      const existing = await (this.researchRepo as any).prisma.researchAuditLog.findFirst({ where: { tenantId: input.tenantId, event: 'WALK_FORWARD_COMPLETED', safeMetadata: { path: ['idempotencyKey'], equals: input.idempotencyKey } } });
      // Simplified idempotency check
    }

    const windows: { windowId: string; type: 'TRAINING' | 'VALIDATION' | 'TEST'; startTime: string; endTime: string; trainingStart: string | null; trainingEnd: string | null; isOutOfSample: boolean }[] = [];
    const results: any[] = [];

    const start = new Date(input.startTime).getTime();
    const end = new Date(input.endTime).getTime();
    const trainingMs = input.trainingWindowDays * 24*60*60*1000;
    const testingMs = input.testingWindowDays * 24*60*60*1000;
    const validationMs = (input.validationWindowDays || 0) * 24*60*60*1000;
    const stepMs = (input.stepDays || input.testingWindowDays) * 24*60*60*1000;

    let currentStart = start;
    let windowIndex = 0;

    while (currentStart + trainingMs + validationMs + testingMs <= end) {
      const trainingStart = currentStart;
      const trainingEnd = input.mode === 'EXPANDING' ? start + trainingMs + windowIndex * stepMs : currentStart + trainingMs;
      const actualTrainingStart = input.mode === 'EXPANDING' ? start : trainingStart;

      const validationStart = trainingEnd;
      const validationEnd = validationStart + validationMs;

      const testingStart = validationMs > 0 ? validationEnd : trainingEnd;
      const testingEnd = testingStart + testingMs;

      // Ensure no future test data enters training - strict train/test separation
      // Training uses only data up to trainingEnd, testing uses only data from testingStart to testingEnd

      if (validationMs > 0) {
        windows.push({
          windowId: `wf_${windowIndex}_training`,
          type: 'TRAINING',
          startTime: new Date(actualTrainingStart).toISOString(),
          endTime: new Date(trainingEnd).toISOString(),
          trainingStart: new Date(actualTrainingStart).toISOString(),
          trainingEnd: new Date(trainingEnd).toISOString(),
          isOutOfSample: false,
        });
        windows.push({
          windowId: `wf_${windowIndex}_validation`,
          type: 'VALIDATION',
          startTime: new Date(validationStart).toISOString(),
          endTime: new Date(validationEnd).toISOString(),
          trainingStart: new Date(actualTrainingStart).toISOString(),
          trainingEnd: new Date(trainingEnd).toISOString(),
          isOutOfSample: false,
        });
        windows.push({
          windowId: `wf_${windowIndex}_test`,
          type: 'TEST',
          startTime: new Date(testingStart).toISOString(),
          endTime: new Date(testingEnd).toISOString(),
          trainingStart: new Date(actualTrainingStart).toISOString(),
          trainingEnd: new Date(trainingEnd).toISOString(),
          isOutOfSample: true,
        });
      } else {
        windows.push({
          windowId: `wf_${windowIndex}_training`,
          type: 'TRAINING',
          startTime: new Date(actualTrainingStart).toISOString(),
          endTime: new Date(trainingEnd).toISOString(),
          trainingStart: new Date(actualTrainingStart).toISOString(),
          trainingEnd: new Date(trainingEnd).toISOString(),
          isOutOfSample: false,
        });
        windows.push({
          windowId: `wf_${windowIndex}_test`,
          type: 'TEST',
          startTime: new Date(testingStart).toISOString(),
          endTime: new Date(testingEnd).toISOString(),
          trainingStart: new Date(actualTrainingStart).toISOString(),
          trainingEnd: new Date(trainingEnd).toISOString(),
          isOutOfSample: true,
        });
      }

      // Run backtest for training window (in-sample)
      try {
        const trainingRun = await this.backtestEngine.runBacktest({
          tenantId: input.tenantId,
          strategyVersionId: input.strategyVersionId,
          symbols: input.symbols,
          timeframe: input.timeframe,
          startTime: new Date(actualTrainingStart).toISOString(),
          endTime: new Date(trainingEnd).toISOString(),
          initialCapital: input.initialCapital,
          createdBy: input.createdBy || null,
          idempotencyKey: `wf_training_${input.tenantId}_${input.strategyVersionId}_${windowIndex}`,
        });
        results.push({ windowId: `wf_${windowIndex}_training`, type: 'TRAINING', runId: trainingRun.id, metrics: trainingRun.metrics, isOutOfSample: false });
      } catch (e: any) {
        this.logger.warn(`Walk-forward training window ${windowIndex} failed: ${e.message}`);
      }

      // Run backtest for test window (out-of-sample) - critical leakage protection
      try {
        const testingRun = await this.backtestEngine.runBacktest({
          tenantId: input.tenantId,
          strategyVersionId: input.strategyVersionId,
          symbols: input.symbols,
          timeframe: input.timeframe,
          startTime: new Date(testingStart).toISOString(),
          endTime: new Date(testingEnd).toISOString(),
          initialCapital: input.initialCapital,
          createdBy: input.createdBy || null,
          idempotencyKey: `wf_test_${input.tenantId}_${input.strategyVersionId}_${windowIndex}`,
        });
        results.push({ windowId: `wf_${windowIndex}_test`, type: 'TEST', runId: testingRun.id, metrics: testingRun.metrics, isOutOfSample: true });
      } catch (e: any) {
        this.logger.warn(`Walk-forward test window ${windowIndex} failed: ${e.message}`);
      }

      currentStart += stepMs;
      windowIndex++;
      if (windowIndex > 100) break; // Safety
    }

    // Aggregate metrics - out-of-sample only for final validation
    const inSampleResults = results.filter(r => !r.isOutOfSample);
    const outOfSampleResults = results.filter(r => r.isOutOfSample);

    const aggregatedMetrics = this.aggregateMetrics(results);
    const outOfSampleMetrics = this.aggregateMetrics(outOfSampleResults);

    await this.researchRepo.createAuditLog({
      tenantId: input.tenantId,
      event: 'WALK_FORWARD_COMPLETED',
      actorId: input.createdBy || null,
      strategyVersionId: input.strategyVersionId,
      result: 'SUCCESS',
      safeMetadata: { windows: windows.length, results: results.length, mode: input.mode, trainingWindowDays: input.trainingWindowDays, testingWindowDays: input.testingWindowDays },
    });

    this.logger.log(`Walk-forward completed tenant=${input.tenantId} strategyVersion=${input.strategyVersionId} windows=${windows.length} results=${results.length} mode=${input.mode}`);

    return { windows, results, aggregatedMetrics, outOfSampleMetrics };
  }

  private aggregateMetrics(results: any[]): Record<string, any> {
    if (results.length === 0) return {};

    let totalReturn = 0;
    let maxDrawdown = 0;
    let winRateSum = 0;
    let tradeCount = 0;
    let count = 0;

    for (const r of results) {
      if (r.metrics) {
        if (r.metrics.totalReturn) totalReturn += parseFloat(r.metrics.totalReturn);
        if (r.metrics.maxDrawdown) maxDrawdown = Math.max(maxDrawdown, parseFloat(r.metrics.maxDrawdown));
        if (r.metrics.winRate) winRateSum += parseFloat(r.metrics.winRate);
        if (r.metrics.tradeCount) tradeCount += r.metrics.tradeCount;
        count++;
      }
    }

    return {
      averageReturn: count > 0 ? (totalReturn / count).toString() : null,
      maxDrawdown: maxDrawdown.toString(),
      averageWinRate: count > 0 ? (winRateSum / count).toString() : null,
      totalTrades: tradeCount,
      windowCount: count,
      methodology: 'Average of window metrics, out-of-sample separated, no look-ahead leakage',
      isSimulated: true,
    };
  }
}

import { Injectable, Logger, ForbiddenException } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { InstitutionalRiskPolicyService } from './risk-policy.service';
import { RiskEventService } from './risk-event.service';
import { CircuitBreakerScope, CircuitBreakerState, RiskPolicyScope, RiskSeverity, RiskEventType } from './risk-management.types';

/**
 * Circuit breaker service with scopes SYMBOL/STRATEGY/TRADER/ACCOUNT/TENANT/VENUE/PLATFORM.
 * Triggers: loss/drawdown/outage/stale data/execution failure/rate-limit/liquidation/concentration/compliance/security.
 * States CLOSED/OPEN/HALF_OPEN, policy-controlled recovery.
 * Every activation/deactivation auditable.
 * Never directly places orders except through kill-switch boundary when policy permits.
 */

@Injectable()
export class CircuitBreakerService {
  private readonly logger = new Logger(CircuitBreakerService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: InstitutionalRiskPolicyService,
    private readonly eventService: RiskEventService,
  ) {}

  async getBreakerStatus(params: { tenantId?: string | null; scope: CircuitBreakerScope; scopeId: string }): Promise<any | null> {
    const { tenantId, scope, scopeId } = params;
    return this.prisma.circuitBreakerRecord.findFirst({
      where: { tenantId: tenantId ?? undefined, scope: scope as any, scopeId },
      orderBy: { createdAt: 'desc' },
    });
  }

  async listBreakers(params: { tenantId?: string | null; state?: CircuitBreakerState }): Promise<any[]> {
    const { tenantId, state } = params;
    return this.prisma.circuitBreakerRecord.findMany({
      where: { tenantId: tenantId ?? undefined, state: state as any },
      orderBy: { createdAt: 'desc' },
      take: 100,
    });
  }

  async triggerBreaker(params: {
    tenantId?: string | null;
    scope: CircuitBreakerScope;
    scopeId: string;
    triggerType: string; // loss/drawdown/outage/stale data/execution failure/rate-limit/liquidation/concentration/compliance/security
    triggerRuleId?: string;
    reason: string;
    policyVersion: string;
    triggeredByUserId?: string;
    traderId?: string;
    strategyId?: string;
    accountId?: string;
  }): Promise<{ id: string; state: CircuitBreakerState }> {
    const { tenantId, scope, scopeId, triggerType, triggerRuleId, reason, policyVersion, triggeredByUserId, traderId, strategyId, accountId } = params;

    if (!reason || reason.trim().length < 10) {
      throw new ForbiddenException('Circuit breaker reason must be at least 10 characters');
    }

    // Check existing breaker: if already OPEN, do not duplicate unless reason changed significantly
    const existing = await this.prisma.circuitBreakerRecord.findFirst({
      where: { tenantId: tenantId ?? undefined, scope: scope as any, scopeId, state: 'OPEN' as any },
      orderBy: { createdAt: 'desc' },
    });
    if (existing) {
      this.logger.log(`Circuit breaker already OPEN for ${scope} ${scopeId}, existing ${existing.id}`);
      return { id: existing.id, state: CircuitBreakerState.OPEN };
    }

    const created = await this.prisma.circuitBreakerRecord.create({
      data: {
        tenantId: tenantId ?? null,
        scope: scope as any,
        scopeId,
        state: 'OPEN' as any,
        triggerType,
        triggerRuleId: triggerRuleId ?? null,
        reason: reason.slice(0, 1000),
        policyVersion,
        triggeredAt: new Date(),
        triggeredByUserId: triggeredByUserId ?? null,
        metadata: { traderId, strategyId, accountId } as any,
      },
    });

    // Audit log
    await this.prisma.auditLog.create({
      data: {
        tenantId: tenantId ?? undefined,
        actorId: triggeredByUserId ?? undefined,
        actorType: triggeredByUserId ? 'USER' : 'SYSTEM',
        action: 'CIRCUIT_BREAKER_TRIGGERED',
        resourceType: 'CIRCUIT_BREAKER',
        resourceId: created.id,
        description: `Breaker OPEN ${scope} ${scopeId} trigger ${triggerType} rule ${triggerRuleId ?? ''} reason ${reason}`.slice(0, 500),
        metadata: { scope, scopeId, triggerType, triggerRuleId, reason, policyVersion } as any,
      },
    });

    // Emit risk event
    if (tenantId) {
      await this.eventService.emitThresholdBreached({
        tenantId,
        type: RiskEventType.CIRCUIT_BREAKER_TRIGGERED,
        ruleId: triggerRuleId ?? 'CIRCUIT_BREAKER_TRIGGERED',
        policyVersion,
        scope: this.mapScopeToPolicyScope(scope),
        scopeId,
        accountId: accountId ?? null,
        strategyId: strategyId ?? null,
        traderId: traderId ?? null,
        symbol: scope === CircuitBreakerScope.SYMBOL ? scopeId : null,
        venue: scope === CircuitBreakerScope.VENUE ? scopeId : null,
        severity: RiskSeverity.CRITICAL,
        message: `Circuit breaker TRIGGERED for ${scope} ${scopeId}: ${reason}`,
        sourceRefs: { breakerId: created.id, triggerType },
      });
    }

    this.logger.warn(`Circuit breaker TRIGGERED ${scope} ${scopeId} type ${triggerType} reason ${reason}`);
    return { id: created.id, state: CircuitBreakerState.OPEN };
  }

  async acknowledgeBreaker(params: { breakerId: string; acknowledgedByUserId: string; reason: string; tenantId?: string }): Promise<{ id: string }> {
    const { breakerId, acknowledgedByUserId, reason, tenantId } = params;
    const breaker = await this.prisma.circuitBreakerRecord.findUnique({ where: { id: breakerId } });
    if (!breaker) throw new ForbiddenException(`Breaker ${breakerId} not found`);
    if (breaker.state !== 'OPEN') throw new ForbiddenException(`Breaker ${breakerId} not in OPEN state, current ${breaker.state}`);

    await this.prisma.circuitBreakerRecord.update({
      where: { id: breakerId },
      data: { acknowledgedAt: new Date(), metadata: { ...(breaker.metadata as any), acknowledgedByUserId, acknowledgeReason: reason } as any },
    });

    await this.prisma.auditLog.create({
      data: {
        tenantId: tenantId ?? breaker.tenantId ?? undefined,
        actorId: acknowledgedByUserId,
        actorType: 'USER',
        action: 'CIRCUIT_BREAKER_ACKNOWLEDGED',
        resourceType: 'CIRCUIT_BREAKER',
        resourceId: breakerId,
        description: `Breaker ACKNOWLEDGED ${breaker.scope} ${breaker.scopeId} by ${acknowledgedByUserId} reason ${reason}`.slice(0, 500),
      },
    });

    return { id: breakerId };
  }

  async clearBreaker(params: {
    breakerId: string;
    clearedByUserId: string;
    reason: string;
    tenantId?: string;
    requireExplicitClear?: boolean;
  }): Promise<{ id: string; state: CircuitBreakerState }> {
    const { breakerId, clearedByUserId, reason, tenantId } = params;
    if (!reason || reason.trim().length < 20) {
      throw new ForbiddenException('Clear reason must be at least 20 characters');
    }
    const breaker = await this.prisma.circuitBreakerRecord.findUnique({ where: { id: breakerId } });
    if (!breaker) throw new ForbiddenException(`Breaker ${breakerId} not found`);
    if (breaker.state !== 'OPEN' && breaker.state !== 'HALF_OPEN') {
      throw new ForbiddenException(`Breaker ${breakerId} not in clearable state, current ${breaker.state}`);
    }

    // Policy-controlled recovery: check if policy requires explicit clear
    // For now allow if reason provided

    await this.prisma.circuitBreakerRecord.update({
      where: { id: breakerId },
      data: { state: 'CLOSED' as any, clearedAt: new Date(), clearedByUserId, metadata: { ...(breaker.metadata as any), clearReason: reason } as any },
    });

    await this.prisma.auditLog.create({
      data: {
        tenantId: tenantId ?? breaker.tenantId ?? undefined,
        actorId: clearedByUserId,
        actorType: 'USER',
        action: 'CIRCUIT_BREAKER_CLEARED',
        resourceType: 'CIRCUIT_BREAKER',
        resourceId: breakerId,
        description: `Breaker CLEARED ${breaker.scope} ${breaker.scopeId} by ${clearedByUserId} reason ${reason}`.slice(0, 500),
        metadata: { reason, previousState: breaker.state } as any,
      },
    });

    this.logger.log(`Circuit breaker CLEARED ${breaker.scope} ${breaker.scopeId} by ${clearedByUserId}`);
    return { id: breakerId, state: CircuitBreakerState.CLOSED };
  }

  async halfOpenBreaker(params: { breakerId: string; tenantId?: string }): Promise<{ id: string; state: CircuitBreakerState }> {
    const { breakerId, tenantId } = params;
    const breaker = await this.prisma.circuitBreakerRecord.findUnique({ where: { id: breakerId } });
    if (!breaker) throw new ForbiddenException(`Breaker ${breakerId} not found`);
    if (breaker.state !== 'OPEN') throw new ForbiddenException(`Breaker ${breakerId} not OPEN, cannot half-open`);

    await this.prisma.circuitBreakerRecord.update({
      where: { id: breakerId },
      data: { state: 'HALF_OPEN' as any, halfOpenAt: new Date() },
    });

    await this.prisma.auditLog.create({
      data: {
        tenantId: tenantId ?? breaker.tenantId ?? undefined,
        actorType: 'SYSTEM',
        action: 'CIRCUIT_BREAKER_HALF_OPEN',
        resourceType: 'CIRCUIT_BREAKER',
        resourceId: breakerId,
        description: `Breaker HALF_OPEN ${breaker.scope} ${breaker.scopeId}`.slice(0, 500),
      },
    });

    return { id: breakerId, state: CircuitBreakerState.HALF_OPEN };
  }

  async isBlocked(params: { tenantId?: string | null; scope: CircuitBreakerScope; scopeId: string }): Promise<boolean> {
    const breaker = await this.getBreakerStatus(params);
    return breaker?.state === 'OPEN' || breaker?.state === 'HALF_OPEN';
  }

  private mapScopeToPolicyScope(scope: CircuitBreakerScope): RiskPolicyScope {
    switch (scope) {
      case CircuitBreakerScope.SYMBOL:
        return RiskPolicyScope.TENANT;
      case CircuitBreakerScope.STRATEGY:
        return RiskPolicyScope.STRATEGY;
      case CircuitBreakerScope.TRADER:
        return RiskPolicyScope.TRADER;
      case CircuitBreakerScope.ACCOUNT:
        return RiskPolicyScope.TENANT;
      case CircuitBreakerScope.TENANT:
        return RiskPolicyScope.TENANT;
      case CircuitBreakerScope.VENUE:
        return RiskPolicyScope.TENANT;
      case CircuitBreakerScope.PLATFORM:
        return RiskPolicyScope.PLATFORM;
      default:
        return RiskPolicyScope.TENANT;
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { TradingVenue } from '@prisma/client';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { Decimal, isDecimalString } from '../../common/decimal-string';
import { InstitutionalRiskPolicyService } from './risk-policy.service';
import { CorrelationResult, RiskState, RiskSeverity } from './risk-management.types';
import type { CustomerCorrelationAssessment } from './customer-risk-analysis.types';

/**
 * Correlation risk: asset/strategy/portfolio correlation.
 * Uses canonical market data returns where sufficient observations exist.
 * Returns UNKNOWN when insufficient, never invents correlation.
 * Method versioned, lookback/min obs configurable.
 */

function isValidDecimal(v: any): boolean {
  return typeof v === 'string' && /^-?\d+(\.\d+)?$/.test(v);
}
const SCALE = 1_000_000_000_000n;
function parseScaled(s: string): bigint {
  const neg = s.startsWith('-');
  const clean = neg ? s.slice(1) : s;
  const [intP = '0', fracP = ''] = clean.split('.');
  const frac = (fracP + '0'.repeat(12)).slice(0, 12);
  const val = BigInt(intP) * SCALE + BigInt(frac || '0');
  return neg ? -val : val;
}
function formatScaled(b: bigint): string {
  const neg = b < 0n;
  const abs = neg ? -b : b;
  const intP = abs / SCALE;
  const frac = abs % SCALE;
  const fracStr = frac.toString().padStart(12, '0').replace(/0+$/, '');
  return (neg ? '-' : '') + (fracStr ? `${intP}.${fracStr}` : `${intP}`);
}

const DAY_MS = 24 * 60 * 60 * 1000;

/**
 * How old the newest aligned daily candle may be before a coefficient computed from it is withheld.
 *
 * This is 36 hours rather than a policy threshold because it is a property of the observation
 * interval, not of a tenant's risk appetite: a daily series whose newest close is more than a day
 * and a half old has missed the most recent session, so the number would describe a market that no
 * longer exists. The institutional `marketDataMaxAgeMs` threshold answers a different question -
 * how fresh a tick may be to price an order - and is far too strict for a daily close.
 */
const ALIGNED_DAILY_MAX_SOURCE_AGE_MS = 129_600_000;

/** Upper bound on pairs evaluated per request, so one request cannot fan out without limit. */
const MAX_CANDIDATE_PAIRS = 20;

@Injectable()
export class CorrelationRiskService {
  private readonly logger = new Logger(CorrelationRiskService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: InstitutionalRiskPolicyService,
  ) {}

  async evaluateCorrelation(params: {
    tenantId: string;
    traderId?: string;
    strategyId?: string;
    followerId?: string;
    pairs?: Array<{ assetA: string; assetB: string }>;
  }): Promise<CorrelationResult[]> {
    const { tenantId, traderId, strategyId, followerId, pairs } = params;
    const policy = await this.policyService.resolveEffectivePolicy({
      tenantId,
      traderId: traderId ?? null,
      strategyId: strategyId ?? null,
      followerId: followerId ?? null,
    });

    const lookbackDays = policy.thresholds.correlationLookbackDays;
    const minObs = policy.thresholds.correlationMinObservations;
    const threshold = policy.thresholds.maxCorrelation;
    const method = `PEARSON_${lookbackDays}D`;
    const methodVersion = 'v1.0.0';

    // Determine pairs: if not provided, derive from positions
    let effectivePairs = pairs;
    if (!effectivePairs || effectivePairs.length === 0) {
      const positions = await this.prisma.position.findMany({
        where: { tenantId },
        distinct: ['symbol'],
        select: { symbol: true },
      });
      const symbols = positions.map((p) => p.symbol);
      effectivePairs = [];
      for (let i = 0; i < symbols.length; i++) {
        for (let j = i + 1; j < symbols.length; j++) {
          effectivePairs.push({ assetA: symbols[i], assetB: symbols[j] });
        }
      }
      // Limit to first 20 pairs to avoid explosion
      effectivePairs = effectivePairs.slice(0, 20);
    }

    const results: CorrelationResult[] = [];
    const nowIso = new Date().toISOString();

    for (const pair of effectivePairs) {
      const pairKey = `${pair.assetA}:${pair.assetB}`;

      // Fetch historical market data for both assets
      const startDate = new Date(Date.now() - lookbackDays * 24 * 60 * 60 * 1000);

      const dataA = await this.prisma.marketDataRecord.findMany({
        where: { symbol: pair.assetA, openTime: { gte: startDate } },
        orderBy: { openTime: 'asc' },
        take: lookbackDays * 2,
      });
      const dataB = await this.prisma.marketDataRecord.findMany({
        where: { symbol: pair.assetB, openTime: { gte: startDate } },
        orderBy: { openTime: 'asc' },
        take: lookbackDays * 2,
      });

      const observations = Math.min(dataA.length, dataB.length);

      if (observations < minObs) {
        results.push({
          tenantId,
          method,
          methodVersion,
          lookbackDays,
          minObservations: minObs,
          observations,
          pairKey,
          correlation: null,
          threshold: threshold ?? null,
          isBreach: false,
          state: RiskState.UNKNOWN,
          ruleId: 'MAX_CORRELATION',
          policyVersion: policy.effectiveVersion,
          reason: `Insufficient observations for ${pairKey}: ${observations} < ${minObs} required (lookback ${lookbackDays}d), returning UNKNOWN per policy — must not invent correlation`,
          severity: RiskSeverity.INFO,
          isUnknown: true,
        });
        continue;
      }

      // Compute Pearson correlation on close returns
      // Returns = (close_t / close_{t-1} -1)
      // We need decimal-safe but correlation calculation involves floating math; we will use number for correlation but keep decimal string output.
      // This is acceptable for correlation analytics (not financial ledger) but we still avoid inventing.
      try {
        const returnsA: number[] = [];
        const returnsB: number[] = [];
        for (let i = 1; i < Math.min(dataA.length, dataB.length); i++) {
          const closeA = Number(dataA[i].close);
          const prevCloseA = Number(dataA[i - 1].close);
          const closeB = Number(dataB[i].close);
          const prevCloseB = Number(dataB[i - 1].close);
          if (prevCloseA === 0 || prevCloseB === 0) continue;
          returnsA.push(closeA / prevCloseA - 1);
          returnsB.push(closeB / prevCloseB - 1);
        }

        if (returnsA.length < minObs) {
          results.push({
            tenantId,
            method,
            methodVersion,
            lookbackDays,
            minObservations: minObs,
            observations: returnsA.length,
            pairKey,
            correlation: null,
            threshold: threshold ?? null,
            isBreach: false,
            state: RiskState.UNKNOWN,
            ruleId: 'MAX_CORRELATION',
            policyVersion: policy.effectiveVersion,
            reason: `Insufficient return observations for ${pairKey}: ${returnsA.length} < ${minObs}, UNKNOWN`,
            severity: RiskSeverity.INFO,
            isUnknown: true,
          });
          continue;
        }

        const meanA = returnsA.reduce((s, v) => s + v, 0) / returnsA.length;
        const meanB = returnsB.reduce((s, v) => s + v, 0) / returnsB.length;

        let num = 0;
        let denA = 0;
        let denB = 0;
        for (let i = 0; i < returnsA.length; i++) {
          const da = returnsA[i] - meanA;
          const db = returnsB[i] - meanB;
          num += da * db;
          denA += da * da;
          denB += db * db;
        }
        const denom = Math.sqrt(denA * denB);
        // A flat series has no correlation to report. Returning 0 here would publish the number
        // that means "no relationship", which is a measurement this data cannot support.
        if (denom === 0 || !Number.isFinite(denom)) {
          results.push({
            tenantId,
            method,
            methodVersion,
            lookbackDays,
            minObservations: minObs,
            observations: returnsA.length,
            pairKey,
            correlation: null,
            threshold: threshold ?? null,
            isBreach: false,
            state: RiskState.UNKNOWN,
            ruleId: 'MAX_CORRELATION',
            policyVersion: policy.effectiveVersion,
            reason: `Zero or invalid variance for ${pairKey}: at least one return series is constant, so no correlation exists to measure`,
            severity: RiskSeverity.INFO,
            isUnknown: true,
          });
          continue;
        }
        const corr = num / denom;
        const corrStr = corr.toFixed(6); // decimal string

        let isBreach = false;
        let state = RiskState.NORMAL;
        let reason = `Correlation ${corrStr} for ${pairKey} within threshold ${threshold ?? 'unlimited'}`;
        let severity = RiskSeverity.INFO;

        if (threshold && isValidDecimal(threshold)) {
          // If absolute correlation exceeds threshold, breach
          const absCorr = Math.abs(corr);
          const threshNum = Number(threshold);
          if (absCorr > threshNum) {
            isBreach = true;
            state = RiskState.HIGH;
            reason = `Correlation ${corrStr} for ${pairKey} exceeds threshold ${threshold} (absolute ${absCorr.toFixed(4)} > ${threshNum})`;
            severity = RiskSeverity.WARNING;
          }
        }

        results.push({
          tenantId,
          method,
          methodVersion,
          lookbackDays,
          minObservations: minObs,
          observations: returnsA.length,
          pairKey,
          correlation: corrStr,
          threshold: threshold ?? null,
          isBreach,
          state,
          ruleId: 'MAX_CORRELATION',
          policyVersion: policy.effectiveVersion,
          reason,
          severity,
          isUnknown: false,
        });
      } catch (e) {
        results.push({
          tenantId,
          method,
          methodVersion,
          lookbackDays,
          minObservations: minObs,
          observations,
          pairKey,
          correlation: null,
          threshold: threshold ?? null,
          isBreach: false,
          state: RiskState.UNKNOWN,
          ruleId: 'MAX_CORRELATION',
          policyVersion: policy.effectiveVersion,
          reason: `Correlation calculation failed for ${pairKey}: ${(e as Error).message}, returning UNKNOWN`,
          severity: RiskSeverity.WARNING,
          isUnknown: true,
        });
      }
    }

    return results;
  }

  /**
   * Correlation between the instruments the authenticated caller actually holds.
   *
   * Every input is owner-scoped: the accounts are the caller's own non-sandbox accounts, the
   * positions are open and not simulated, and the instrument identity comes from the tenant's
   * `tradingSymbol` rows rather than from the stored symbol string. The institutional method above
   * is left as it is because it answers for an operator-selected scope; this one answers only for
   * the caller, and takes no scope selector at all.
   *
   * Observations are paired by candle timestamp, never by array index. Two series that start on
   * different days are not the same 30 days of market, and pairing them positionally would compute a
   * coefficient from returns that never happened on the same day.
   */
  async evaluateMyCorrelation(params: {
    tenantId: string;
    userId: string;
    asOf?: Date | string;
  }): Promise<CustomerCorrelationAssessment> {
    const { tenantId, userId } = params;
    const asOfDate = params.asOf === undefined ? new Date() : new Date(params.asOf);
    const asOfTime = asOfDate.getTime();

    const policy = await this.policyService.resolveEffectivePolicy({ tenantId });
    const lookbackDays = policy.thresholds.correlationLookbackDays;
    const minObs = policy.thresholds.correlationMinObservations;
    const threshold = policy.thresholds.maxCorrelation;
    const method = `PEARSON_${lookbackDays}D_ALIGNED_DAILY`;
    const methodVersion = 'v1.0.0';

    const base = {
      tenantId,
      asOf: asOfDate.toISOString(),
      dataScope: 'SIGNED_IN_USER_NON_SANDBOX_NON_SIMULATED_ACCOUNTS' as const,
      method,
      methodVersion,
      interval: '1d' as const,
      lookbackDays,
      minObservations: minObs,
      maxSourceAgeMs: ALIGNED_DAILY_MAX_SOURCE_AGE_MS,
      notice:
        'A pair is evaluated only when both instruments share a quote asset and a market type and their daily candles align by timestamp. A coefficient is withheld, never estimated, when the aligned window is short, stale, or has no variance.',
    };

    if (!Number.isFinite(asOfTime)) {
      return {
        ...base,
        state: 'UNKNOWN',
        activePositionCount: null,
        instrumentCount: null,
        omittedPositionCount: null,
        candidatePairCount: null,
        evaluatedPairCount: 0,
        truncatedPairCount: null,
        pairs: [],
      };
    }

    const accounts = await this.prisma.tradingAccount.findMany({
      where: { tenantId, deletedAt: null, isSandbox: false, userId },
      select: { id: true },
    });
    const accountIds = accounts.map((account) => account.id);
    if (accountIds.length === 0) {
      return {
        ...base,
        state: 'EMPTY',
        activePositionCount: 0,
        instrumentCount: 0,
        omittedPositionCount: 0,
        candidatePairCount: 0,
        evaluatedPairCount: 0,
        truncatedPairCount: 0,
        pairs: [],
      };
    }

    const positions = await this.prisma.position.findMany({
      where: {
        tenantId,
        accountId: { in: accountIds },
        containsSimulatedFills: false,
        closedAt: null,
      },
      select: { symbolId: true, symbol: true, venue: true, quantity: true },
    });
    if (positions.length === 0) {
      return {
        ...base,
        state: 'EMPTY',
        activePositionCount: 0,
        instrumentCount: 0,
        omittedPositionCount: 0,
        candidatePairCount: 0,
        evaluatedPairCount: 0,
        truncatedPairCount: 0,
        pairs: [],
      };
    }

    // Insertion order is preserved deliberately: the instrument id list is part of the query that
    // resolves tenant instrument identity, and a stable order keeps that query reproducible.
    const symbolIds: string[] = [];
    for (const position of positions) {
      if (!symbolIds.includes(position.symbolId)) symbolIds.push(position.symbolId);
    }

    const tradingSymbols = await this.prisma.tradingSymbol.findMany({
      where: { tenantId, id: { in: symbolIds } },
      select: {
        id: true,
        symbol: true,
        marketType: true,
        baseAsset: true,
        quoteAsset: true,
        exchange: { select: { venue: true } },
      },
    });
    const symbolById = new Map(tradingSymbols.map((symbol) => [symbol.id, symbol]));

    interface Instrument {
      symbolId: string;
      symbol: string;
      venue: TradingVenue;
      marketType: string | null;
      baseAsset: string | null;
      quoteAsset: string | null;
    }

    const instruments = new Map<string, Instrument>();
    let omittedPositionCount = 0;
    for (const position of positions) {
      const resolved = symbolById.get(position.symbolId);
      if (!resolved) {
        omittedPositionCount += 1;
        continue;
      }
      if (instruments.has(resolved.id)) continue;
      instruments.set(resolved.id, {
        symbolId: resolved.id,
        symbol: resolved.symbol,
        venue: resolved.exchange?.venue ?? position.venue,
        marketType: resolved.marketType ?? null,
        baseAsset: resolved.baseAsset ?? null,
        quoteAsset: resolved.quoteAsset ?? null,
      });
    }

    const instrumentList = Array.from(instruments.values());
    const candidates: Array<{ left: Instrument; right: Instrument }> = [];
    for (let i = 0; i < instrumentList.length; i += 1) {
      for (let j = i + 1; j < instrumentList.length; j += 1) {
        const left = instrumentList[i];
        const right = instrumentList[j];
        // Two instruments can only be correlated through a common unit of value. Different quote
        // assets, or different market types, means the pair has no shared denominator.
        if (!left.quoteAsset || !right.quoteAsset) continue;
        if (left.quoteAsset !== right.quoteAsset) continue;
        if (!left.marketType || !right.marketType) continue;
        if (left.marketType !== right.marketType) continue;
        candidates.push({ left, right });
      }
    }

    const evaluated = candidates.slice(0, MAX_CANDIDATE_PAIRS);
    const truncatedPairCount = candidates.length - evaluated.length;

    const candleCache = new Map<string, AlignedCandle[]>();
    const loadCandles = async (instrument: Instrument): Promise<AlignedCandle[]> => {
      const cached = candleCache.get(instrument.symbolId);
      if (cached) return cached;
      const rows = await this.prisma.marketDataRecord.findMany({
        where: {
          symbolId: instrument.symbolId,
          venue: instrument.venue,
          interval: '1d',
          openTime: { gte: new Date(asOfTime - (lookbackDays + 2) * DAY_MS) },
        },
        orderBy: { openTime: 'asc' },
        select: { openTime: true, closeTime: true, close: true },
      });
      const candles = normalizeCandles(rows);
      candleCache.set(instrument.symbolId, candles);
      return candles;
    };

    const pairs: CorrelationResult[] = [];
    for (const { left, right } of evaluated) {
      const leftCandles = await loadCandles(left);
      const rightCandles = await loadCandles(right);

      const pairKey = `${left.symbol}:${right.symbol}`;
      const aligned = alignByTimestamp(leftCandles, rightCandles);
      const returns = alignedReturns(aligned);
      const observations = returns.length;
      const newestCloseTime = aligned.length > 0
        ? Math.max(...aligned.map((observation) => observation.closeTimeMs))
        : null;
      const sourceTimestamp = newestCloseTime === null ? null : new Date(newestCloseTime).toISOString();
      const isStale = newestCloseTime !== null && asOfTime - newestCloseTime > ALIGNED_DAILY_MAX_SOURCE_AGE_MS;

      const common = {
        tenantId,
        method,
        methodVersion,
        lookbackDays,
        minObservations: minObs,
        observations,
        pairKey,
        threshold: threshold ?? null,
        ruleId: 'MAX_CORRELATION',
        policyVersion: policy.effectiveVersion,
        sourceInterval: '1d',
        sourceMethodology: 'ALIGNED_DAILY_CLOSE_RETURNS',
        sourceTimestamp,
        sourceMaxAgeMs: ALIGNED_DAILY_MAX_SOURCE_AGE_MS,
      };

      // Freshness is decided before sufficiency. A window that is both short and stale is reported
      // as stale, because "your market data stopped" is the actionable fact and "you have 28 of 30
      // observations" would read as a passing hiccup.
      if (isStale) {
        pairs.push({
          ...common,
          correlation: null,
          isBreach: false,
          state: RiskState.STALE,
          reason: `The newest aligned daily close for ${pairKey} is ${sourceTimestamp}, older than the 36-hour freshness limit. No coefficient is published from a market that has moved on.`,
          severity: RiskSeverity.WARNING,
          isUnknown: true,
          isStale: true,
        });
        continue;
      }

      if (observations < minObs) {
        pairs.push({
          ...common,
          correlation: null,
          isBreach: false,
          state: RiskState.UNKNOWN,
          reason: `Only ${observations} timestamp-aligned daily return pairs for ${pairKey}; ${minObs} are required. Positions with no shared trading day are not paired.`,
          severity: RiskSeverity.INFO,
          isUnknown: true,
          isStale: false,
        });
        continue;
      }

      const statistics = pearson(returns);
      if (statistics === null) {
        pairs.push({
          ...common,
          correlation: null,
          isBreach: false,
          state: RiskState.UNKNOWN,
          reason: `The aligned return series for ${pairKey} has zero or invalid variance, so no correlation exists to measure.`,
          severity: RiskSeverity.INFO,
          isUnknown: true,
          isStale: false,
        });
        continue;
      }

      const correlation = formatCorrelation(statistics.correlation);
      const thresholdValue = threshold !== null && isDecimalString(threshold) ? Number(threshold) : null;
      // Absolute value: a strongly negative correlation concentrates risk in the same pair too, and
      // the configured limit is a bound on the strength of the relationship, not its sign.
      const isBreach = thresholdValue !== null && Math.abs(statistics.correlation) > thresholdValue;

      pairs.push({
        ...common,
        correlation,
        isBreach,
        state: isBreach ? RiskState.HIGH : RiskState.NORMAL,
        reason: thresholdValue === null
          ? `Correlation ${correlation} for ${pairKey} over ${observations} aligned daily returns; no correlation limit is configured.`
          : `Correlation ${correlation} for ${pairKey} over ${observations} aligned daily returns, ${isBreach ? 'above' : 'within'} the limit of ${threshold}.`,
        severity: isBreach ? RiskSeverity.WARNING : RiskSeverity.INFO,
        isUnknown: false,
        isStale: false,
      });
    }

    let state: CustomerCorrelationAssessment['state'];
    if (pairs.some((pair) => pair.state === RiskState.STALE)) state = 'STALE';
    else if (pairs.some((pair) => pair.isUnknown)) state = 'UNKNOWN';
    else if (pairs.length === 0) state = 'UNKNOWN';
    else state = 'CURRENT';

    return {
      ...base,
      state,
      activePositionCount: positions.length,
      instrumentCount: instruments.size,
      omittedPositionCount,
      candidatePairCount: candidates.length,
      evaluatedPairCount: evaluated.length,
      truncatedPairCount,
      pairs,
    };
  }
}

interface AlignedCandle {
  openTimeMs: number;
  closeTimeMs: number;
  close: Decimal;
}

interface AlignedObservation {
  openTimeMs: number;
  closeTimeMs: number;
  leftReturn: number;
  rightReturn: number;
}

/**
 * Reads candle rows into exact closes. A row whose close is not an exact decimal is dropped rather
 * than coerced, because coercing it would put an unverified number into a statistic.
 *
 * The column is a Prisma `Decimal` on the way out of the database and a plain string in fixtures and
 * tests, so the value is passed through the canonical parser rather than through `Number`. The
 * parser understands scientific notation exactly, which matters because a Decimal's own `toString`
 * may use it for small magnitudes.
 */
function normalizeCandles(rows: Array<{ openTime: Date; closeTime: Date; close: unknown }>): AlignedCandle[] {
  const candles: AlignedCandle[] = [];
  for (const row of rows) {
    if (!row) continue;
    const openTimeMs = new Date(row.openTime).getTime();
    const closeTimeMs = new Date(row.closeTime).getTime();
    if (!Number.isFinite(openTimeMs) || !Number.isFinite(closeTimeMs)) continue;
    let close: Decimal;
    try {
      close = Decimal.parse(String(row.close));
    } catch {
      continue;
    }
    if (!close.isPositive()) continue;
    candles.push({ openTimeMs, closeTimeMs, close });
  }
  candles.sort((a, b) => a.openTimeMs - b.openTimeMs);
  return candles;
}

/**
 * Pairs candles that opened at the same instant. Index pairing is deliberately not used: two series
 * that begin on different days would otherwise be compared day 1 to day 1 across different markets.
 */
function alignByTimestamp(left: AlignedCandle[], right: AlignedCandle[]) {
  const rightByOpen = new Map(right.map((candle) => [candle.openTimeMs, candle]));
  const aligned: Array<{ openTimeMs: number; closeTimeMs: number; left: AlignedCandle; right: AlignedCandle }> = [];
  for (const leftCandle of left) {
    const rightCandle = rightByOpen.get(leftCandle.openTimeMs);
    if (!rightCandle) continue;
    aligned.push({
      openTimeMs: leftCandle.openTimeMs,
      closeTimeMs: Math.max(leftCandle.closeTimeMs, rightCandle.closeTimeMs),
      left: leftCandle,
      right: rightCandle,
    });
  }
  return aligned;
}

/**
 * Daily returns over consecutive aligned candles. A gap in the aligned series is skipped rather than
 * bridged, so a return never spans an interval the data does not cover.
 *
 * The division is exact scaled-integer arithmetic; only the resulting dimensionless ratio becomes a
 * float, and no price ever does.
 */
function alignedReturns(aligned: Array<{ openTimeMs: number; closeTimeMs: number; left: AlignedCandle; right: AlignedCandle }>): AlignedObservation[] {
  const observations: AlignedObservation[] = [];
  for (let i = 1; i < aligned.length; i += 1) {
    const previous = aligned[i - 1];
    const current = aligned[i];
    if (current.openTimeMs - previous.openTimeMs !== DAY_MS) continue;
    const leftReturn = ratioMinusOne(current.left.close, previous.left.close);
    const rightReturn = ratioMinusOne(current.right.close, previous.right.close);
    if (leftReturn === null || rightReturn === null) continue;
    observations.push({
      openTimeMs: current.openTimeMs,
      closeTimeMs: current.closeTimeMs,
      leftReturn,
      rightReturn,
    });
  }
  return observations;
}

/**
 * `current / previous - 1`, as a float ratio.
 *
 * The division is exact big-integer arithmetic produced by the canonical decimal module; only the
 * resulting dimensionless ratio becomes a float, and it is read back at the scale the module
 * actually returned rather than assuming one, because a result such as exactly 1 normalises to scale
 * zero.
 */
function ratioMinusOne(current: Decimal, previous: Decimal): number | null {
  if (!previous.isPositive()) return null;
  try {
    const ratio = current.div(previous, 12);
    return Number(ratio.unscaled) / Math.pow(10, ratio.scale) - 1;
  } catch {
    return null;
  }
}

/**
 * Pearson's r, or null when the coefficient does not exist.
 *
 * Null covers both a zero-variance series and any non-finite intermediate. The caller turns null into
 * UNKNOWN; it never becomes a number, because 0 is the value that means "uncorrelated" and that is a
 * measurement this input cannot support.
 */
function pearson(observations: AlignedObservation[]): { correlation: number } | null {
  const count = observations.length;
  if (count < 2) return null;

  let sumLeft = 0;
  let sumRight = 0;
  for (const observation of observations) {
    sumLeft += observation.leftReturn;
    sumRight += observation.rightReturn;
  }
  const meanLeft = sumLeft / count;
  const meanRight = sumRight / count;

  let covariance = 0;
  let varianceLeft = 0;
  let varianceRight = 0;
  for (const observation of observations) {
    const leftDelta = observation.leftReturn - meanLeft;
    const rightDelta = observation.rightReturn - meanRight;
    covariance += leftDelta * rightDelta;
    varianceLeft += leftDelta * leftDelta;
    varianceRight += rightDelta * rightDelta;
  }

  const denominator = Math.sqrt(varianceLeft * varianceRight);
  if (!Number.isFinite(denominator) || denominator === 0) return null;
  const correlation = covariance / denominator;
  if (!Number.isFinite(correlation)) return null;
  return { correlation: Math.max(-1, Math.min(1, correlation)) };
}

function formatCorrelation(value: number): string {
  const plain = (Math.trunc(value * 1e12) / 1e12).toFixed(12);
  return plain.replace(/\.?0+$/, '') || '0';
}

