import { Injectable, Logger, ForbiddenException } from '@nestjs/common';
import { randomUUID } from 'node:crypto';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OutboxService } from '../../infrastructure/outbox/outbox.service';
import { RiskEventService } from './risk-event.service';
import { RiskPolicyScope, RiskSeverity, RiskEventType } from './risk-management.types';

/**
 * Kill-switch orchestrator wraps existing KillSwitch (Prisma model KillSwitch).
 * - Request/inspect/apply scoped/recover authorized/audit, no second implementation.
 * - Uses existing KillSwitch table as authoritative store.
 * - Never auto-disables account solely from advisory score unless policy permits.
 * - Every activation/deactivation auditable.
 */

export enum KillSwitchRequestScope {
  GLOBAL = 'GLOBAL',
  EXCHANGE = 'EXCHANGE',
  ACCOUNT = 'ACCOUNT',
  STRATEGY = 'STRATEGY',
  SYMBOL = 'SYMBOL',
  RISK = 'RISK',
}

@Injectable()
export class KillSwitchOrchestratorService {
  private readonly logger = new Logger(KillSwitchOrchestratorService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventService: RiskEventService,
    private readonly outbox: OutboxService,
  ) {}

  async requestKillSwitch(params: {
    tenantId?: string | null;
    scope: KillSwitchRequestScope;
    target?: string | null;
    reason: string;
    triggeredByRule?: string;
    severity?: RiskSeverity;
    requestedByUserId?: string;
    policyVersion: string;
    requiresExplicitClear?: boolean;
  }): Promise<{ id: string; isEngaged: boolean }> {
    const { tenantId, scope, target, reason, triggeredByRule, severity, requestedByUserId, policyVersion, requiresExplicitClear } = params;

    if (!reason || reason.trim().length < 10) {
      throw new ForbiddenException('Kill-switch reason must be at least 10 characters');
    }

    const now = new Date();
    const transitionEventId = randomUUID();
    const createData = {
      tenantId: tenantId ?? null,
      scope: scope as any,
      target: target ?? null,
      isEngaged: true,
      reason: reason.slice(0, 500),
      engagedByUserId: requestedByUserId ?? null,
      engagedAt: now,
      status: 'TRIGGERED' as any,
      triggeredByRule: triggeredByRule ?? null,
      triggeredAt: now,
      severity: (severity as any) ?? 'CRITICAL',
      requiresExplicitClear: requiresExplicitClear ?? true,
    };

    let created: any;
    if (tenantId) {
      const result = await this.prisma.withTenantRls(tenantId, async (tx) => {
        const existing = await tx.killSwitch.findFirst({
          where: { tenantId, scope: scope as any, target: target ?? null, isEngaged: true },
          orderBy: { createdAt: 'desc' },
        });
        if (existing) return { row: existing, created: false };

        const row = await tx.killSwitch.create({ data: createData });
        await this.outbox.append(tx, {
          tenantId,
          aggregateType: 'kill_switch',
          aggregateId: row.id,
          eventType: 'kill_switch.activated',
          idempotencyKey: `kill-switch:${row.id}:activated:${transitionEventId}`,
          payload: {
            killSwitchId: row.id,
            scope,
            target: target ?? null,
            isEngaged: true,
            activatedAt: now.toISOString(),
          },
        });
        return { row, created: true };
      });
      if (!result.created) {
        this.logger.log(`Kill-switch already engaged for ${scope} ${target ?? ''}, id ${result.row.id}`);
        return { id: result.row.id, isEngaged: true };
      }
      created = result.row;
    } else {
      const existing = await this.prisma.killSwitch.findFirst({
        where: { tenantId: null, scope: scope as any, target: target ?? null, isEngaged: true },
        orderBy: { createdAt: 'desc' },
      });
      if (existing) {
        this.logger.log(`Kill-switch already engaged for ${scope} ${target ?? ''}, id ${existing.id}`);
        return { id: existing.id, isEngaged: true };
      }
      created = await this.prisma.killSwitch.create({ data: createData });
    }

    await this.prisma.auditLog.create({
      data: {
        tenantId: tenantId ?? undefined,
        actorId: requestedByUserId ?? undefined,
        actorType: requestedByUserId ? 'USER' : 'SYSTEM',
        action: 'KILL_SWITCH_ENGAGED',
        resourceType: 'KILL_SWITCH',
        resourceId: created.id,
        description: `Kill-switch ENGAGED scope ${scope} target ${target ?? ''} reason ${reason}`.slice(0, 500),
        metadata: { scope, target, reason, triggeredByRule, severity, policyVersion } as any,
      },
    });

    if (tenantId) {
      await this.eventService.emitThresholdBreached({
        tenantId,
        type: RiskEventType.KILL_SWITCH_REQUESTED,
        ruleId: triggeredByRule ?? 'KILL_SWITCH_REQUESTED',
        policyVersion,
        scope: this.mapScopeToPolicyScope(scope),
        scopeId: target ?? tenantId,
        accountId: scope === KillSwitchRequestScope.ACCOUNT ? target ?? null : null,
        strategyId: scope === KillSwitchRequestScope.STRATEGY ? target ?? null : null,
        symbol: scope === KillSwitchRequestScope.SYMBOL ? target ?? null : null,
        venue: scope === KillSwitchRequestScope.EXCHANGE ? target ?? null : null,
        severity: severity ?? RiskSeverity.CRITICAL,
        message: `Kill-switch REQUESTED scope ${scope} target ${target ?? ''}: ${reason}`,
        sourceRefs: { killSwitchId: created.id },
        requestId: null,
      });
    }

    this.logger.warn(`Kill-switch ENGAGED scope ${scope} target ${target ?? ''} reason ${reason} id ${created.id}`);
    return { id: created.id, isEngaged: true };
  }

  async inspectKillSwitch(params: { tenantId?: string | null; scope?: KillSwitchRequestScope; target?: string }): Promise<any[]> {
    const { tenantId, scope, target } = params;
    return this.prisma.killSwitch.findMany({
      where: {
        tenantId: tenantId ?? undefined,
        scope: scope ? (scope as any) : undefined,
        target: target ?? undefined,
      },
      orderBy: { createdAt: 'desc' },
      take: 100,
    });
  }

  async isEngaged(params: { tenantId?: string | null; scope: KillSwitchRequestScope; target?: string }): Promise<boolean> {
    const { tenantId, scope, target } = params;
    const ks = await this.prisma.killSwitch.findFirst({
      where: { tenantId: tenantId ?? undefined, scope: scope as any, target: target ?? undefined, isEngaged: true },
      orderBy: { createdAt: 'desc' },
    });
    return !!ks;
  }

  async clearKillSwitch(params: {
    killSwitchId: string;
    clearedByUserId: string;
    reason: string;
    tenantId?: string;
    acknowledged?: boolean;
  }): Promise<{ id: string; isEngaged: boolean }> {
    const { killSwitchId, clearedByUserId, reason, tenantId } = params;
    if (!reason || reason.trim().length < 20) {
      throw new ForbiddenException('Kill-switch clear reason must be at least 20 characters');
    }

    const snapshot = await this.prisma.killSwitch.findUnique({ where: { id: killSwitchId } });
    if (!snapshot) throw new ForbiddenException(`Kill-switch ${killSwitchId} not found`);
    if (tenantId && snapshot.tenantId !== tenantId) throw new ForbiddenException('Kill-switch is outside the active tenant');
    if (!snapshot.isEngaged) throw new ForbiddenException(`Kill-switch ${killSwitchId} not engaged`);

    const ownerTenantId = tenantId ?? snapshot.tenantId ?? undefined;
    const releasedAt = new Date();
    const transitionEventId = randomUUID();
    let ks: NonNullable<typeof snapshot> = snapshot;
    if (ownerTenantId) {
      ks = await this.prisma.withTenantRls(ownerTenantId, async (tx) => {
        const current = await tx.killSwitch.findFirst({ where: { id: killSwitchId, tenantId: ownerTenantId } });
        if (!current) throw new ForbiddenException(`Kill-switch ${killSwitchId} not found`);
        if (!current.isEngaged) throw new ForbiddenException(`Kill-switch ${killSwitchId} not engaged`);
        const updated = await tx.killSwitch.update({
          where: { id: killSwitchId },
          data: {
            isEngaged: false,
            releasedByUserId: clearedByUserId,
            releasedAt,
            status: 'CLEARED' as any,
            clearedByUserId,
            clearedAt: releasedAt,
            clearedReason: reason.slice(0, 500),
          },
        });
        await this.outbox.append(tx, {
          tenantId: ownerTenantId,
          aggregateType: 'kill_switch',
          aggregateId: killSwitchId,
          eventType: 'kill_switch.released',
          idempotencyKey: `kill-switch:${killSwitchId}:released:${transitionEventId}`,
          payload: {
            killSwitchId,
            scope: updated.scope,
            target: updated.target,
            isEngaged: false,
            releasedAt: releasedAt.toISOString(),
          },
        });
        return updated;
      });
    } else {
      ks = await this.prisma.killSwitch.update({
        where: { id: killSwitchId },
        data: {
          isEngaged: false,
          releasedByUserId: clearedByUserId,
          releasedAt,
          status: 'CLEARED' as any,
          clearedByUserId,
          clearedAt: releasedAt,
          clearedReason: reason.slice(0, 500),
        },
      });
    }

    await this.prisma.auditLog.create({
      data: {
        tenantId: tenantId ?? ks.tenantId ?? undefined,
        actorId: clearedByUserId,
        actorType: 'USER',
        action: 'KILL_SWITCH_CLEARED',
        resourceType: 'KILL_SWITCH',
        resourceId: killSwitchId,
        description: `Kill-switch CLEARED scope ${ks.scope} target ${ks.target ?? ''} by ${clearedByUserId} reason ${reason}`.slice(0, 500),
        metadata: { reason, previousScope: ks.scope, target: ks.target } as any,
      },
    });

    this.logger.log(`Kill-switch CLEARED scope ${ks.scope} target ${ks.target ?? ''} id ${killSwitchId} by ${clearedByUserId}`);
    return { id: killSwitchId, isEngaged: false };
  }

  async acknowledgeKillSwitch(params: { killSwitchId: string; acknowledgedByUserId: string; reason: string; tenantId?: string }): Promise<{ id: string }> {
    const { killSwitchId, acknowledgedByUserId, reason, tenantId } = params;
    if (!reason || reason.trim().length < 10) throw new ForbiddenException('Acknowledge reason must be at least 10 characters');

    const ks = await this.prisma.killSwitch.findUnique({ where: { id: killSwitchId } });
    if (!ks) throw new ForbiddenException(`Kill-switch ${killSwitchId} not found`);
    if (ks.status !== 'TRIGGERED') throw new ForbiddenException(`Kill-switch ${killSwitchId} not in TRIGGERED state, current ${ks.status}`);

    await this.prisma.killSwitch.update({
      where: { id: killSwitchId },
      data: {
        status: 'ACKNOWLEDGED' as any,
        acknowledgedByUserId: acknowledgedByUserId,
        acknowledgedAt: new Date(),
        acknowledgementReason: reason.slice(0, 500),
      },
    });

    await this.prisma.auditLog.create({
      data: {
        tenantId: tenantId ?? ks.tenantId ?? undefined,
        actorId: acknowledgedByUserId,
        actorType: 'USER',
        action: 'KILL_SWITCH_ACKNOWLEDGED',
        resourceType: 'KILL_SWITCH',
        resourceId: killSwitchId,
        description: `Kill-switch ACKNOWLEDGED ${ks.scope} ${ks.target ?? ''} by ${acknowledgedByUserId} reason ${reason}`.slice(0, 500),
      },
    });

    return { id: killSwitchId };
  }

  private mapScopeToPolicyScope(scope: KillSwitchRequestScope): RiskPolicyScope {
    switch (scope) {
      case KillSwitchRequestScope.GLOBAL:
        return RiskPolicyScope.PLATFORM;
      case KillSwitchRequestScope.EXCHANGE:
        return RiskPolicyScope.TENANT;
      case KillSwitchRequestScope.ACCOUNT:
        return RiskPolicyScope.TENANT;
      case KillSwitchRequestScope.STRATEGY:
        return RiskPolicyScope.STRATEGY;
      case KillSwitchRequestScope.SYMBOL:
        return RiskPolicyScope.TENANT;
      case KillSwitchRequestScope.RISK:
        return RiskPolicyScope.TENANT;
      default:
        return RiskPolicyScope.TENANT;
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { InstitutionalRiskPolicyService } from './risk-policy.service';
import { LeverageRiskResult, RiskState, RiskSeverity } from './risk-management.types';

/**
 * Leverage validation against policy and exchange constraints.
 * Gross, net, symbol, account, projected leverage after order intent.
 * Decimal-safe, deterministic.
 */

function isValidDecimal(v: any): boolean {
  return typeof v === 'string' && /^-?\d+(\.\d+)?$/.test(v);
}
const SCALE = 1_000_000_000_000n;
function parseScaled(s: string): bigint {
  const neg = s.startsWith('-');
  const clean = neg ? s.slice(1) : s;
  const [intP = '0', fracP = ''] = clean.split('.');
  const frac = (fracP + '0'.repeat(12)).slice(0, 12);
  const val = BigInt(intP) * SCALE + BigInt(frac || '0');
  return neg ? -val : val;
}
function formatScaled(b: bigint): string {
  const neg = b < 0n;
  const abs = neg ? -b : b;
  const intP = abs / SCALE;
  const frac = abs % SCALE;
  const fracStr = frac.toString().padStart(12, '0').replace(/0+$/, '');
  return (neg ? '-' : '') + (fracStr ? `${intP}.${fracStr}` : `${intP}`);
}
function mul(a: string, b: string): string {
  return formatScaled((parseScaled(a) * parseScaled(b)) / SCALE);
}
function cmp(a: string, b: string): number {
  const av = parseScaled(a);
  const bv = parseScaled(b);
  return av < bv ? -1 : av > bv ? 1 : 0;
}

@Injectable()
export class LeverageRiskService {
  private readonly logger = new Logger(LeverageRiskService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: InstitutionalRiskPolicyService,
  ) {}

  async evaluateLeverage(params: {
    tenantId: string;
    accountId: string;
    symbol?: string;
    traderId?: string;
    strategyId?: string;
    followerId?: string;
    orderIntent?: { quantity: string; price: string | null; side: 'BUY' | 'SELL' } | null;
  }): Promise<LeverageRiskResult[]> {
    const { tenantId, accountId, symbol, traderId, strategyId, followerId, orderIntent } = params;
    const policy = await this.policyService.resolveEffectivePolicy({
      tenantId,
      traderId: traderId ?? null,
      strategyId: strategyId ?? null,
      followerId: followerId ?? null,
    });

    const positions = await this.prisma.position.findMany({
      where: { tenantId, accountId, ...(symbol ? { symbol } : {}) },
    });

    const balances = await this.prisma.accountBalanceSnapshot.findMany({
      where: { tenantId, accountId },
    });

    let walletTotal = 0n;
    for (const b of balances) {
      const totalStr = b.total.toString();
      if (isValidDecimal(totalStr)) walletTotal += parseScaled(totalStr);
    }

    const results: LeverageRiskResult[] = [];

    // Account-level leverage
    let grossNotional = 0n;
    let netNotional = 0n;
    for (const pos of positions) {
      const qtyStr = pos.quantity.toString();
      const markPrice = pos.markPrice?.toString() ?? pos.averageEntryPrice?.toString() ?? null;
      if (!isValidDecimal(qtyStr) || !markPrice || !isValidDecimal(markPrice)) continue;
      const absQty = qtyStr.startsWith('-') ? qtyStr.slice(1) : qtyStr;
      const notional = parseScaled(mul(absQty, markPrice));
      grossNotional += notional;
      const signedQty = parseScaled(qtyStr);
      netNotional += signedQty >= 0n ? notional : -notional;
    }

    let grossLeverage: string | null = null;
    let netLeverage: string | null = null;
    if (walletTotal > 0n) {
      grossLeverage = formatScaled((grossNotional * SCALE) / walletTotal);
      const netAbs = netNotional < 0n ? -netNotional : netNotional;
      netLeverage = formatScaled((netAbs * SCALE) / walletTotal);
    }

    // Projected leverage after order intent
    let projectedGrossLeverage: string | null = null;
    let projectedNetLeverage: string | null = null;
    if (orderIntent && isValidDecimal(orderIntent.quantity) && orderIntent.price && isValidDecimal(orderIntent.price)) {
      const intentNotional = parseScaled(mul(orderIntent.quantity, orderIntent.price));
      const projectedGross = grossNotional + intentNotional;
      if (walletTotal > 0n) {
        projectedGrossLeverage = formatScaled((projectedGross * SCALE) / walletTotal);
        // For net, need side: BUY adds, SELL subtracts
        const sideMultiplier = orderIntent.side === 'BUY' ? 1n : -1n;
        const projectedNet = netNotional + sideMultiplier * intentNotional;
        const projNetAbs = projectedNet < 0n ? -projectedNet : projectedNet;
        projectedNetLeverage = formatScaled((projNetAbs * SCALE) / walletTotal);
      }
    }

    // Exchange max leverage
    const account = await this.prisma.tradingAccount.findFirst({
      where: { id: accountId, tenantId },
      include: { exchange: true },
    });
    const exchangeMaxLeverage = account?.exchange?.maxLeverage?.toString() ?? null;

    const policyMaxLeverage = policy.thresholds.maxLeverageGross ?? null;

    let isBreach = false;
    let state = RiskState.NORMAL;
    let reason = `Leverage gross ${grossLeverage ?? 'unknown'} within policy ${policyMaxLeverage ?? 'unlimited'} and exchange ${exchangeMaxLeverage ?? 'unlimited'}`;
    let severity = RiskSeverity.INFO;
    let ruleId = 'MAX_LEVERAGE_GROSS';

    const leverageToCheck = projectedGrossLeverage ?? grossLeverage;

    if (leverageToCheck && policyMaxLeverage && isValidDecimal(leverageToCheck) && isValidDecimal(policyMaxLeverage)) {
      if (cmp(leverageToCheck, policyMaxLeverage) > 0) {
        isBreach = true;
        state = RiskState.BLOCKED;
        reason = `Leverage ${leverageToCheck}x exceeds policy max ${policyMaxLeverage}x for account ${accountId}${orderIntent ? ' after projected order' : ''}`;
        severity = RiskSeverity.CRITICAL;
      }
    }

    if (leverageToCheck && exchangeMaxLeverage && isValidDecimal(exchangeMaxLeverage)) {
      if (cmp(leverageToCheck, exchangeMaxLeverage) > 0) {
        isBreach = true;
        state = RiskState.BLOCKED;
        reason = `Leverage ${leverageToCheck}x exceeds exchange max ${exchangeMaxLeverage}x for account ${accountId}`;
        severity = RiskSeverity.CRITICAL;
        ruleId = 'MAX_LEVERAGE_EXCHANGE';
      }
    }

    results.push({
      tenantId,
      accountId,
      venue: account?.exchange?.venue ?? 'UNKNOWN',
      symbol: symbol ?? null,
      grossLeverage,
      netLeverage,
      projectedGrossLeverage,
      projectedNetLeverage,
      exchangeMaxLeverage,
      policyMaxLeverage,
      isBreach,
      state,
      ruleId,
      policyVersion: policy.effectiveVersion,
      reason,
      severity,
    });

    // Per-symbol leverage if symbol specified or for each position
    if (!symbol) {
      for (const pos of positions) {
        const qtyStr = pos.quantity.toString();
        const markPrice = pos.markPrice?.toString() ?? pos.averageEntryPrice?.toString() ?? null;
        if (!isValidDecimal(qtyStr) || !markPrice || !isValidDecimal(markPrice)) continue;
        const absQty = qtyStr.startsWith('-') ? qtyStr.slice(1) : qtyStr;
        const notional = parseScaled(mul(absQty, markPrice));
        let symGrossLeverage: string | null = null;
        if (walletTotal > 0n) {
          symGrossLeverage = formatScaled((notional * SCALE) / walletTotal);
        }
        const symPolicyMax = policy.thresholds.maxLeverageSymbol ?? policyMaxLeverage;
        let symBreach = false;
        let symState = RiskState.NORMAL;
        let symReason = `Symbol leverage ${symGrossLeverage ?? 'unknown'} for ${pos.symbol} within limits`;
        if (symGrossLeverage && symPolicyMax && isValidDecimal(symGrossLeverage) && isValidDecimal(symPolicyMax)) {
          if (cmp(symGrossLeverage, symPolicyMax) > 0) {
            symBreach = true;
            symState = RiskState.BLOCKED;
            symReason = `Symbol leverage ${symGrossLeverage}x exceeds max ${symPolicyMax}x for ${pos.symbol}`;
          }
        }
        results.push({
          tenantId,
          accountId,
          venue: pos.venue as string,
          symbol: pos.symbol,
          grossLeverage: symGrossLeverage,
          netLeverage: symGrossLeverage,
          projectedGrossLeverage: null,
          projectedNetLeverage: null,
          exchangeMaxLeverage,
          policyMaxLeverage: symPolicyMax ?? null,
          isBreach: symBreach,
          state: symState,
          ruleId: 'MAX_LEVERAGE_SYMBOL',
          policyVersion: policy.effectiveVersion,
          reason: symReason,
          severity: symBreach ? RiskSeverity.CRITICAL : RiskSeverity.INFO,
        });
      }
    }

    return results;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { InstitutionalRiskPolicyService } from './risk-policy.service';
import { MarginRiskResult, RiskState, RiskSeverity } from './risk-management.types';

/**
 * Margin risk from canonical sources only:
 * AccountBalanceSnapshot (free/locked/total) + Position notional + open orders.
 * Never trusts client-provided margin.
 * Decimal-safe, fail-closed.
 */

function isValidDecimal(v: any): boolean {
  return typeof v === 'string' && /^-?\d+(\.\d+)?$/.test(v);
}
const SCALE = 1_000_000_000_000n;
function parseScaled(s: string): bigint {
  const neg = s.startsWith('-');
  const clean = neg ? s.slice(1) : s;
  const [intP = '0', fracP = ''] = clean.split('.');
  const frac = (fracP + '0'.repeat(12)).slice(0, 12);
  const val = BigInt(intP) * SCALE + BigInt(frac || '0');
  return neg ? -val : val;
}
function formatScaled(b: bigint): string {
  const neg = b < 0n;
  const abs = neg ? -b : b;
  const intP = abs / SCALE;
  const frac = abs % SCALE;
  const fracStr = frac.toString().padStart(12, '0').replace(/0+$/, '');
  return (neg ? '-' : '') + (fracStr ? `${intP}.${fracStr}` : `${intP}`);
}
function mul(a: string, b: string): string {
  return formatScaled((parseScaled(a) * parseScaled(b)) / SCALE);
}
function add(a: string, b: string): string {
  return formatScaled(parseScaled(a) + parseScaled(b));
}
function cmp(a: string, b: string): number {
  const av = parseScaled(a);
  const bv = parseScaled(b);
  return av < bv ? -1 : av > bv ? 1 : 0;
}

@Injectable()
export class MarginRiskService {
  private readonly logger = new Logger(MarginRiskService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: InstitutionalRiskPolicyService,
  ) {}

  async evaluateMargin(params: {
    tenantId: string;
    accountId: string;
    orderIntent?: { symbol: string; quantity: string; price: string | null; side: 'BUY' | 'SELL' } | null;
    traderId?: string;
    strategyId?: string;
    followerId?: string;
  }): Promise<MarginRiskResult[]> {
    const { tenantId, accountId, orderIntent, traderId, strategyId, followerId } = params;
    const policy = await this.policyService.resolveEffectivePolicy({
      tenantId,
      traderId: traderId ?? null,
      strategyId: strategyId ?? null,
      followerId: followerId ?? null,
    });

    const balances = await this.prisma.accountBalanceSnapshot.findMany({
      where: { tenantId, accountId },
    });

    const positions = await this.prisma.position.findMany({
      where: { tenantId, accountId },
    });

    const openOrders = await this.prisma.order.findMany({
      where: {
        tenantId,
        accountId,
        status: { in: ['PENDING', 'SUBMITTED', 'ACKNOWLEDGED', 'PARTIALLY_FILLED'] },
      },
    });

    // Group balances by asset, sum total per account for quote asset (USDT assumed)
    // For margin we need wallet, available, locked, initial, maintenance
    // Since schema doesn't have margin-specific columns, we derive from balances:
    // wallet = sum(total), available = sum(free), locked = sum(locked)
    // initial/maintenance require exchange-specific data; if unavailable, return null and mark UNKNOWN where needed.

    const walletByAsset = new Map<string, { free: bigint; locked: bigint; total: bigint; updatedAt: Date }>();
    for (const b of balances) {
      const freeStr = b.free.toString();
      const lockedStr = b.locked.toString();
      const totalStr = b.total.toString();
      if (!isValidDecimal(freeStr) || !isValidDecimal(lockedStr) || !isValidDecimal(totalStr)) continue;
      const entry = walletByAsset.get(b.asset) ?? { free: 0n, locked: 0n, total: 0n, updatedAt: b.updatedAt };
      entry.free += parseScaled(freeStr);
      entry.locked += parseScaled(lockedStr);
      entry.total += parseScaled(totalStr);
      if (new Date(b.updatedAt) > entry.updatedAt) entry.updatedAt = b.updatedAt;
      walletByAsset.set(b.asset, entry);
    }

    // For simplicity, assume USDT is margin currency; aggregate USDT totals
    const usdt = walletByAsset.get('USDT') ?? walletByAsset.get('USD') ?? null;
    const walletBalance = usdt ? formatScaled(usdt.total) : null;
    const availableBalance = usdt ? formatScaled(usdt.free) : null;
    const lockedBalance = usdt ? formatScaled(usdt.locked) : null;

    // Compute used margin from positions: sum(abs(notional) * maintenance margin rate)
    // Since we don't have margin rate in Position, we approximate initial margin as notional / leverage if leverage known, else null.
    // We will return null for initial/maintenance when unavailable, and mark UNKNOWN accordingly.

    let totalNotional = 0n;
    for (const pos of positions) {
      const qtyStr = pos.quantity.toString();
      const markPrice = pos.markPrice?.toString() ?? pos.averageEntryPrice?.toString() ?? null;
      if (isValidDecimal(qtyStr) && markPrice && isValidDecimal(markPrice)) {
        const absQty = qtyStr.startsWith('-') ? qtyStr.slice(1) : qtyStr;
        const notional = parseScaled(mul(absQty, markPrice));
        totalNotional += notional;
      }
    }

    let openOrderNotional = 0n;
    for (const ord of openOrders) {
      const qtyStr = ord.quantity.toString();
      const priceStr = ord.price?.toString() ?? null;
      if (isValidDecimal(qtyStr) && priceStr && isValidDecimal(priceStr)) {
        openOrderNotional += parseScaled(mul(qtyStr, priceStr));
      }
    }

    // If wallet unavailable, state UNKNOWN
    const nowIso = new Date().toISOString();
    const sourceTimestamp = usdt?.updatedAt.toISOString() ?? nowIso;
    const ageMs = usdt ? Date.now() - usdt.updatedAt.getTime() : Infinity;
    const isStale = ageMs > policy.thresholds.marketDataMaxAgeMs;

    let marginUtilizationPercent: string | null = null;
    if (walletBalance && isValidDecimal(walletBalance) && parseScaled(walletBalance) > 0n) {
      // utilization = (locked + position notional) / wallet *100? Simplified: (totalNotional+openOrderNotional)/wallet
      const used = totalNotional + openOrderNotional;
      marginUtilizationPercent = formatScaled((used * 100n * SCALE) / parseScaled(walletBalance));
    }

    let projectedUtilization: string | null = null;
    if (orderIntent && walletBalance && isValidDecimal(walletBalance) && parseScaled(walletBalance) > 0n) {
      let intentNotional = 0n;
      if (isValidDecimal(orderIntent.quantity) && orderIntent.price && isValidDecimal(orderIntent.price)) {
        intentNotional = parseScaled(mul(orderIntent.quantity, orderIntent.price));
      }
      const projectedUsed = totalNotional + openOrderNotional + intentNotional;
      projectedUtilization = formatScaled((projectedUsed * 100n * SCALE) / parseScaled(walletBalance));
    }

    let state = RiskState.NORMAL;
    let reason = 'Margin within limits';
    let ruleId = 'MARGIN_UTILIZATION';
    let severity = RiskSeverity.INFO;

    if (!walletBalance) {
      state = RiskState.UNKNOWN;
      reason = `Wallet balance unavailable for account ${accountId}, cannot compute margin utilization`;
      severity = RiskSeverity.WARNING;
    } else if (marginUtilizationPercent && policy.thresholds.marginCriticalUtilization && isValidDecimal(policy.thresholds.marginCriticalUtilization)) {
      if (cmp(marginUtilizationPercent, policy.thresholds.marginCriticalUtilization) > 0) {
        state = RiskState.CRITICAL;
        reason = `Margin utilization ${marginUtilizationPercent}% exceeds critical ${policy.thresholds.marginCriticalUtilization}%`;
        severity = RiskSeverity.CRITICAL;
      } else if (policy.thresholds.marginWarningUtilization && cmp(marginUtilizationPercent, policy.thresholds.marginWarningUtilization) > 0) {
        state = RiskState.HIGH;
        reason = `Margin utilization ${marginUtilizationPercent}% exceeds warning ${policy.thresholds.marginWarningUtilization}%`;
        severity = RiskSeverity.WARNING;
      }
    }

    if (isStale) {
      state = state === RiskState.NORMAL ? RiskState.STALE : state;
      reason += ` (source stale ${ageMs}ms)`;
    }

    if (projectedUtilization && policy.thresholds.marginCriticalUtilization && isValidDecimal(policy.thresholds.marginCriticalUtilization)) {
      if (cmp(projectedUtilization, policy.thresholds.marginCriticalUtilization) > 0) {
        state = RiskState.BLOCKED;
        reason = `Projected margin utilization ${projectedUtilization}% would exceed critical ${policy.thresholds.marginCriticalUtilization}% after order`;
        ruleId = 'MARGIN_UTILIZATION';
        severity = RiskSeverity.CRITICAL;
      }
    }

    // For multi-venue, we return one per account aggregated; but interface expects array
    const result: MarginRiskResult = {
      tenantId,
      accountId,
      venue: 'AGGREGATED',
      walletBalance,
      availableBalance,
      lockedBalance,
      initialMargin: null, // not available in canonical source, must not invent
      maintenanceMargin: null,
      marginUtilizationPercent,
      projectedMarginUtilizationPercent: projectedUtilization,
      freeMargin: availableBalance,
      warnings: isStale ? [`Balance source stale for account ${accountId}`] : [],
      state,
      ruleId,
      policyVersion: policy.effectiveVersion,
      reason,
      severity,
      sourceTimestamp,
      isStale,
    };

    return [result];
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { InstitutionalRiskPolicyService } from './risk-policy.service';
import { PortfolioExposureService } from './portfolio-exposure.service';
import { PositionRiskService } from './position-risk.service';
import { MarginRiskService } from './margin-risk.service';
import { LeverageRiskService } from './leverage-risk.service';
import { ConcentrationRiskService } from './concentration-risk.service';
import { DrawdownRiskService } from './drawdown-risk.service';
import { DailyLossLimitService } from './daily-loss-limit.service';
import { RiskDecision, RiskState, RiskSeverity, RiskDimension, RiskPolicyScope, RiskDecisionDetail, UnifiedRiskDecision } from './risk-management.types';

/**
 * Pre-trade order risk flow:
 * Order Intent → Current Portfolio → Projected Portfolio → Exposure → Margin → Leverage → Concentration → Drawdown → Compliance → Security → Exchange Health → Decision
 *
 * Must NOT place order. Returns ALLOW/REDUCE/REVIEW_REQUIRED/BLOCK.
 * Decimal-safe, deterministic ruleId/policyVersion/reason, fail-closed.
 */

function isValidDecimal(v: any): boolean {
  return typeof v === 'string' && /^-?\d+(\.\d+)?$/.test(v);
}
const SCALE = 1_000_000_000_000n;
function parseScaled(s: string): bigint {
  const neg = s.startsWith('-');
  const clean = neg ? s.slice(1) : s;
  const [intP = '0', fracP = ''] = clean.split('.');
  const frac = (fracP + '0'.repeat(12)).slice(0, 12);
  const val = BigInt(intP) * SCALE + BigInt(frac || '0');
  return neg ? -val : val;
}
function formatScaled(b: bigint): string {
  const neg = b < 0n;
  const abs = neg ? -b : b;
  const intP = abs / SCALE;
  const frac = abs % SCALE;
  const fracStr = frac.toString().padStart(12, '0').replace(/0+$/, '');
  return (neg ? '-' : '') + (fracStr ? `${intP}.${fracStr}` : `${intP}`);
}
function mul(a: string, b: string): string {
  return formatScaled((parseScaled(a) * parseScaled(b)) / SCALE);
}
function add(a: string, b: string): string {
  return formatScaled(parseScaled(a) + parseScaled(b));
}
function cmp(a: string, b: string): number {
  const av = parseScaled(a);
  const bv = parseScaled(b);
  return av < bv ? -1 : av > bv ? 1 : 0;
}

@Injectable()
export class OrderRiskService {
  private readonly logger = new Logger(OrderRiskService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: InstitutionalRiskPolicyService,
    private readonly exposureService: PortfolioExposureService,
    private readonly positionRiskService: PositionRiskService,
    private readonly marginRiskService: MarginRiskService,
    private readonly leverageRiskService: LeverageRiskService,
    private readonly concentrationService: ConcentrationRiskService,
    private readonly drawdownService: DrawdownRiskService,
    private readonly dailyLossService: DailyLossLimitService,
  ) {}

  async checkOrderRisk(params: {
    tenantId: string;
    userId?: string;
    accountId: string;
    symbol: string;
    side: 'BUY' | 'SELL';
    quantity: string; // decimal string, validated
    orderType: 'MARKET' | 'LIMIT' | 'STOP' | 'STOP_LIMIT';
    price?: string | null;
    strategyId?: string;
    traderId?: string;
    followerId?: string;
    environment?: 'PAPER' | 'LIVE';
    requestId?: string;
  }): Promise<UnifiedRiskDecision> {
    const {
      tenantId,
      userId,
      accountId,
      symbol,
      side,
      quantity,
      orderType,
      price,
      strategyId,
      traderId,
      followerId,
      environment = 'PAPER',
      requestId,
    } = params;

    const nowIso = new Date().toISOString();
    const policy = await this.policyService.resolveEffectivePolicy({
      tenantId,
      traderId: traderId ?? null,
      strategyId: strategyId ?? null,
      followerId: followerId ?? null,
    });

    const details: RiskDecisionDetail[] = [];
    const blockingReasons: string[] = [];
    const warnings: string[] = [];

    // 1. Validate order intent basics
    if (!isValidDecimal(quantity) || parseScaled(quantity) <= 0n) {
      const d: RiskDecisionDetail = {
        dimension: RiskDimension.POSITION,
        decision: RiskDecision.BLOCK,
        state: RiskState.BLOCKED,
        ruleId: 'MAX_ORDER_QUANTITY',
        policyVersion: policy.effectiveVersion,
        current: quantity,
        threshold: null,
        severity: RiskSeverity.CRITICAL,
        reason: `Invalid quantity ${quantity}`,
        timestamp: nowIso,
        scope: RiskPolicyScope.TENANT,
        scopeId: accountId,
        isBlocking: true,
        isWarning: false,
      };
      details.push(d);
      blockingReasons.push(d.reason);
      return this.finalizeDecision({
        tenantId,
        userId: userId ?? null,
        accountId,
        symbol,
        traderId: traderId ?? null,
        followerId: followerId ?? null,
        strategyId: strategyId ?? null,
        environment,
        policy,
        details,
        blockingReasons,
        warnings,
        requestId: requestId ?? null,
      });
    }

    // 2. Current portfolio exposure
    const exposure = await this.exposureService.calculateExposure({ tenantId, accountId, traderId, strategyId, followerId });
    if (exposure.state === RiskState.STALE) {
      const d: RiskDecisionDetail = {
        dimension: RiskDimension.MARKET_DATA,
        decision: RiskDecision.REVIEW_REQUIRED,
        state: RiskState.STALE,
        ruleId: 'MARKET_DATA_STALE',
        policyVersion: policy.effectiveVersion,
        current: null,
        threshold: policy.thresholds.marketDataMaxAgeMs.toString(),
        severity: RiskSeverity.WARNING,
        reason: `Market data stale for symbols: ${exposure.staleSymbols.join(',')}`,
        timestamp: nowIso,
        scope: RiskPolicyScope.TENANT,
        scopeId: tenantId,
        isBlocking: false,
        isWarning: true,
      };
      details.push(d);
      warnings.push(d.reason);
      if (environment === 'LIVE') {
        // Stale exchange health blocks live per policy
        d.decision = RiskDecision.BLOCK;
        d.isBlocking = true;
        blockingReasons.push(`Live trading blocked due to stale market data: ${d.reason}`);
      }
    }

    // 3. Projected exposure after order
    let orderNotional: string | null = null;
    if (isValidDecimal(price)) {
      orderNotional = mul(quantity, price!);
    } else if (orderType === 'MARKET') {
      // Use mark price from exposure if available
      const symExp = exposure.symbolExposures.find((s) => s.symbol === symbol);
      if (symExp?.price && isValidDecimal(symExp.price)) {
        orderNotional = mul(quantity, symExp.price);
      }
    }

    if (orderNotional) {
      // Check max order notional
      if (policy.thresholds.maxOrderNotional && isValidDecimal(policy.thresholds.maxOrderNotional)) {
        if (cmp(orderNotional, policy.thresholds.maxOrderNotional) > 0) {
          const d: RiskDecisionDetail = {
            dimension: RiskDimension.EXPOSURE,
            decision: RiskDecision.BLOCK,
            state: RiskState.BLOCKED,
            ruleId: 'MAX_ORDER_NOTIONAL',
            policyVersion: policy.effectiveVersion,
            current: orderNotional,
            threshold: policy.thresholds.maxOrderNotional,
            severity: RiskSeverity.CRITICAL,
            reason: `Order notional ${orderNotional} exceeds max ${policy.thresholds.maxOrderNotional}`,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: accountId,
            isBlocking: true,
            isWarning: false,
          };
          details.push(d);
          blockingReasons.push(d.reason);
        }
      }

      // Check gross exposure projected
      if (policy.thresholds.maxGrossExposure && isValidDecimal(policy.thresholds.maxGrossExposure)) {
        const projectedGross = add(exposure.grossExposure, orderNotional);
        if (cmp(projectedGross, policy.thresholds.maxGrossExposure) > 0) {
          const d: RiskDecisionDetail = {
            dimension: RiskDimension.EXPOSURE,
            decision: RiskDecision.BLOCK,
            state: RiskState.BLOCKED,
            ruleId: 'MAX_GROSS_EXPOSURE',
            policyVersion: policy.effectiveVersion,
            current: projectedGross,
            threshold: policy.thresholds.maxGrossExposure,
            severity: RiskSeverity.CRITICAL,
            reason: `Projected gross exposure ${projectedGross} exceeds max ${policy.thresholds.maxGrossExposure}`,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: tenantId,
            isBlocking: true,
            isWarning: false,
          };
          details.push(d);
          blockingReasons.push(d.reason);
        } else if (cmp(projectedGross, mul(policy.thresholds.maxGrossExposure, '0.9')) > 0) {
          const d: RiskDecisionDetail = {
            dimension: RiskDimension.EXPOSURE,
            decision: RiskDecision.REDUCE,
            state: RiskState.HIGH,
            ruleId: 'MAX_GROSS_EXPOSURE',
            policyVersion: policy.effectiveVersion,
            current: projectedGross,
            threshold: policy.thresholds.maxGrossExposure,
            severity: RiskSeverity.WARNING,
            reason: `Projected gross exposure ${projectedGross} approaching limit ${policy.thresholds.maxGrossExposure} (90%)`,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: tenantId,
            isBlocking: false,
            isWarning: true,
          };
          details.push(d);
          warnings.push(d.reason);
        }
      }
    } else {
      const d: RiskDecisionDetail = {
        dimension: RiskDimension.EXPOSURE,
        decision: RiskDecision.REVIEW_REQUIRED,
        state: RiskState.UNKNOWN,
        ruleId: 'MAX_ORDER_NOTIONAL',
        policyVersion: policy.effectiveVersion,
        current: null,
        threshold: policy.thresholds.maxOrderNotional,
        severity: RiskSeverity.WARNING,
        reason: `Cannot compute order notional for ${symbol} — missing price and mark unavailable`,
        timestamp: nowIso,
        scope: RiskPolicyScope.TENANT,
        scopeId: accountId,
        isBlocking: false,
        isWarning: true,
      };
      details.push(d);
      warnings.push(d.reason);
    }

    // 4. Margin check
    try {
      const marginResults = await this.marginRiskService.evaluateMargin({ tenantId, accountId, orderIntent: { symbol, quantity, price: price ?? null, side } });
      for (const m of marginResults) {
        if (m.state === RiskState.BLOCKED || m.state === RiskState.CRITICAL) {
          const d: RiskDecisionDetail = {
            dimension: RiskDimension.MARGIN,
            decision: RiskDecision.BLOCK,
            state: m.state,
            ruleId: m.ruleId,
            policyVersion: m.policyVersion,
            current: m.marginUtilizationPercent,
            threshold: policy.thresholds.marginCriticalUtilization,
            severity: m.severity,
            reason: m.reason,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: accountId,
            isBlocking: true,
            isWarning: false,
          };
          details.push(d);
          blockingReasons.push(d.reason);
        } else if (m.state === RiskState.HIGH || m.state === RiskState.ELEVATED) {
          const d: RiskDecisionDetail = {
            dimension: RiskDimension.MARGIN,
            decision: RiskDecision.REDUCE,
            state: m.state,
            ruleId: m.ruleId,
            policyVersion: m.policyVersion,
            current: m.marginUtilizationPercent,
            threshold: policy.thresholds.marginWarningUtilization,
            severity: m.severity,
            reason: m.reason,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: accountId,
            isBlocking: false,
            isWarning: true,
          };
          details.push(d);
          warnings.push(d.reason);
        }
      }
    } catch (e) {
      const d: RiskDecisionDetail = {
        dimension: RiskDimension.MARGIN,
        decision: RiskDecision.REVIEW_REQUIRED,
        state: RiskState.UNKNOWN,
        ruleId: 'MARGIN_UTILIZATION',
        policyVersion: policy.effectiveVersion,
        current: null,
        threshold: policy.thresholds.marginCriticalUtilization,
        severity: RiskSeverity.WARNING,
        reason: `Margin evaluation failed: ${(e as Error).message}, fail-closed to REVIEW_REQUIRED`,
        timestamp: nowIso,
        scope: RiskPolicyScope.TENANT,
        scopeId: accountId,
        isBlocking: false,
        isWarning: true,
      };
      details.push(d);
      warnings.push(d.reason);
    }

    // 5. Leverage check
    try {
      const levResults = await this.leverageRiskService.evaluateLeverage({
        tenantId,
        accountId,
        symbol,
        orderIntent: { quantity, price: price ?? null, side },
      });
      for (const lev of levResults) {
        if (lev.isBreach) {
          const d: RiskDecisionDetail = {
            dimension: RiskDimension.LEVERAGE,
            decision: RiskDecision.BLOCK,
            state: lev.state,
            ruleId: lev.ruleId,
            policyVersion: lev.policyVersion,
            current: lev.projectedGrossLeverage ?? lev.grossLeverage,
            threshold: lev.policyMaxLeverage,
            severity: lev.severity,
            reason: lev.reason,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: accountId,
            isBlocking: true,
            isWarning: false,
          };
          details.push(d);
          blockingReasons.push(d.reason);
        }
      }
    } catch (e) {
      const d: RiskDecisionDetail = {
        dimension: RiskDimension.LEVERAGE,
        decision: RiskDecision.REVIEW_REQUIRED,
        state: RiskState.UNKNOWN,
        ruleId: 'MAX_LEVERAGE_GROSS',
        policyVersion: policy.effectiveVersion,
        current: null,
        threshold: policy.thresholds.maxLeverageGross,
        severity: RiskSeverity.WARNING,
        reason: `Leverage evaluation failed: ${(e as Error).message}`,
        timestamp: nowIso,
        scope: RiskPolicyScope.TENANT,
        scopeId: accountId,
        isBlocking: false,
        isWarning: true,
      };
      details.push(d);
      warnings.push(d.reason);
    }

    // 6. Concentration check
    try {
      const concResults = await this.concentrationService.evaluateConcentration({
        tenantId,
        accountId,
        symbol,
        orderIntent: orderNotional ? { notional: orderNotional, symbol } : null,
      });
      for (const c of concResults) {
        if (c.isBreach) {
          const d: RiskDecisionDetail = {
            dimension: RiskDimension.CONCENTRATION,
            decision: RiskDecision.BLOCK,
            state: c.state,
            ruleId: c.ruleId,
            policyVersion: c.policyVersion,
            current: c.currentPercent,
            threshold: c.thresholdPercent,
            severity: c.severity,
            reason: c.reason,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: tenantId,
            isBlocking: true,
            isWarning: false,
          };
          details.push(d);
          blockingReasons.push(d.reason);
        }
      }
    } catch (e) {
      this.logger.warn(`Concentration check failed: ${(e as Error).message}`);
    }

    // 7. Drawdown check
    try {
      const ddResults = await this.drawdownService.evaluateDrawdown({ tenantId, accountId, traderId, strategyId, followerId });
      for (const dd of ddResults) {
        if (dd.isBreach) {
          const d: RiskDecisionDetail = {
            dimension: RiskDimension.DRAWDOWN,
            decision: RiskDecision.BLOCK,
            state: dd.state,
            ruleId: dd.ruleId,
            policyVersion: dd.policyVersion,
            current: dd.drawdownPercent,
            threshold: dd.thresholdPercent,
            severity: dd.severity,
            reason: dd.reason,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: accountId,
            isBlocking: true,
            isWarning: false,
          };
          details.push(d);
          blockingReasons.push(d.reason);
        }
      }
    } catch (e) {
      this.logger.warn(`Drawdown check failed: ${(e as Error).message}`);
    }

    // 8. Daily loss check
    try {
      const dlResults = await this.dailyLossService.evaluateDailyLoss({ tenantId, accountId, traderId, strategyId, followerId });
      for (const dl of dlResults) {
        if (dl.isBreach) {
          const d: RiskDecisionDetail = {
            dimension: RiskDimension.DAILY_LOSS,
            decision: RiskDecision.BLOCK,
            state: dl.state,
            ruleId: dl.ruleId,
            policyVersion: dl.policyVersion,
            current: dl.dailyPnl,
            threshold: dl.threshold,
            severity: dl.severity,
            reason: dl.reason,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: accountId,
            isBlocking: true,
            isWarning: false,
          };
          details.push(d);
          blockingReasons.push(d.reason);
        }
      }
    } catch (e) {
      this.logger.warn(`Daily loss check failed: ${(e as Error).message}`);
    }

    // 9. Compliance check (reuse existing ComplianceModule)
    try {
      // Compliance check via canonical compliance status — if user blocked, prevent ALLOW
      const screening = await this.prisma.complianceScreeningRequest.findFirst({
        where: { tenantId, userId: userId ?? undefined, status: 'BLOCKED' },
        orderBy: { createdAt: 'desc' },
      });
      if (screening) {
        const d: RiskDecisionDetail = {
          dimension: RiskDimension.COMPLIANCE,
          decision: RiskDecision.BLOCK,
          state: RiskState.BLOCKED,
          ruleId: 'COMPLIANCE_BLOCK',
          policyVersion: policy.effectiveVersion,
          current: null,
          threshold: null,
          severity: RiskSeverity.CRITICAL,
          reason: `Compliance BLOCK for user ${userId ?? 'unknown'} — screening ${screening.id} blocked`,
          timestamp: nowIso,
          scope: RiskPolicyScope.TENANT,
          scopeId: tenantId,
          isBlocking: true,
          isWarning: false,
        };
        details.push(d);
        blockingReasons.push(d.reason);
      }
    } catch (e) {
      this.logger.warn(`Compliance check failed: ${(e as Error).message}`);
      // Fail-closed for compliance: if compliance unavailable and policy requires, block
      const d: RiskDecisionDetail = {
        dimension: RiskDimension.COMPLIANCE,
        decision: RiskDecision.REVIEW_REQUIRED,
        state: RiskState.UNKNOWN,
        ruleId: 'COMPLIANCE_BLOCK',
        policyVersion: policy.effectiveVersion,
        current: null,
        threshold: null,
        severity: RiskSeverity.WARNING,
        reason: `Compliance evaluation unavailable: ${(e as Error).message}, fail-closed to REVIEW_REQUIRED`,
        timestamp: nowIso,
        scope: RiskPolicyScope.TENANT,
        scopeId: tenantId,
        isBlocking: false,
        isWarning: true,
      };
      details.push(d);
      warnings.push(d.reason);
    }

    // 10. Security check
    try {
      const threat = await this.prisma.securityThreatSignal.findFirst({
        where: { tenantId, userId: userId ?? undefined, resolved: false, riskLevel: { in: ['HIGH', 'CRITICAL'] } },
        orderBy: { createdAt: 'desc' },
      });
      if (threat) {
        const d: RiskDecisionDetail = {
          dimension: RiskDimension.SECURITY,
          decision: RiskDecision.BLOCK,
          state: RiskState.BLOCKED,
          ruleId: 'SECURITY_BLOCK',
          policyVersion: policy.effectiveVersion,
          current: null,
          threshold: null,
          severity: RiskSeverity.CRITICAL,
          reason: `Security BLOCK for user ${userId ?? 'unknown'} — threat ${threat.ruleId} level ${threat.riskLevel}`,
          timestamp: nowIso,
          scope: RiskPolicyScope.TENANT,
          scopeId: tenantId,
          isBlocking: true,
          isWarning: false,
        };
        details.push(d);
        blockingReasons.push(d.reason);
      }
    } catch (e) {
      this.logger.warn(`Security check failed: ${(e as Error).message}`);
    }

    // 11. Exchange health
    try {
      const account = await this.prisma.tradingAccount.findFirst({ where: { id: accountId, tenantId } });
      if (account) {
        const ageMs = account.lastVerifiedAt ? Date.now() - new Date(account.lastVerifiedAt).getTime() : Infinity;
        if (ageMs > policy.thresholds.exchangeHealthMaxAgeMs) {
          const d: RiskDecisionDetail = {
            dimension: RiskDimension.EXCHANGE_HEALTH,
            decision: environment === 'LIVE' ? RiskDecision.BLOCK : RiskDecision.REVIEW_REQUIRED,
            state: RiskState.STALE,
            ruleId: 'EXCHANGE_HEALTH_DEGRADED',
            policyVersion: policy.effectiveVersion,
            current: ageMs.toString(),
            threshold: policy.thresholds.exchangeHealthMaxAgeMs.toString(),
            severity: RiskSeverity.WARNING,
            reason: `Exchange health stale for account ${accountId}, last verified ${ageMs}ms ago > ${policy.thresholds.exchangeHealthMaxAgeMs}ms`,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: accountId,
            isBlocking: environment === 'LIVE',
            isWarning: environment !== 'LIVE',
          };
          details.push(d);
          if (d.isBlocking) blockingReasons.push(d.reason);
          else warnings.push(d.reason);
        }
        if (account.status !== 'ACTIVE') {
          const d: RiskDecisionDetail = {
            dimension: RiskDimension.EXCHANGE_HEALTH,
            decision: RiskDecision.BLOCK,
            state: RiskState.BLOCKED,
            ruleId: 'EXCHANGE_HEALTH_DEGRADED',
            policyVersion: policy.effectiveVersion,
            current: account.status,
            threshold: 'ACTIVE',
            severity: RiskSeverity.CRITICAL,
            reason: `Trading account ${accountId} status ${account.status} not ACTIVE`,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: accountId,
            isBlocking: true,
            isWarning: false,
          };
          details.push(d);
          blockingReasons.push(d.reason);
        }
      }
    } catch (e) {
      this.logger.warn(`Exchange health check failed: ${(e as Error).message}`);
    }

    return this.finalizeDecision({
      tenantId,
      userId: userId ?? null,
      accountId,
      symbol,
      traderId: traderId ?? null,
      followerId: followerId ?? null,
      strategyId: strategyId ?? null,
      environment,
      policy,
      details,
      blockingReasons,
      warnings,
      requestId: requestId ?? null,
    });
  }

  private finalizeDecision(params: {
    tenantId: string;
    userId: string | null;
    accountId: string;
    symbol: string;
    traderId: string | null;
    followerId: string | null;
    strategyId: string | null;
    environment: string;
    policy: any;
    details: RiskDecisionDetail[];
    blockingReasons: string[];
    warnings: string[];
    requestId: string | null;
  }): UnifiedRiskDecision {
    const { tenantId, userId, accountId, symbol, traderId, followerId, strategyId, environment, policy, details, blockingReasons, warnings, requestId } = params;

    let finalDecision: RiskDecision = RiskDecision.ALLOW;
    let finalState = RiskState.NORMAL;

    // Priority: BLOCKED/KILL_SWITCH never becomes ALLOW
    const hasBlock = details.some((d) => d.decision === RiskDecision.BLOCK || d.decision === RiskDecision.KILL_SWITCH_REQUIRED);
    const hasReview = details.some((d) => d.decision === RiskDecision.REVIEW_REQUIRED);
    const hasReduce = details.some((d) => d.decision === RiskDecision.REDUCE);
    const hasPause = details.some((d) => d.decision === RiskDecision.PAUSE);
    const hasStopCopy = details.some((d) => d.decision === RiskDecision.STOP_COPY);

    if (hasBlock) {
      finalDecision = RiskDecision.BLOCK;
      finalState = RiskState.BLOCKED;
    } else if (details.some((d) => d.decision === RiskDecision.KILL_SWITCH_REQUIRED)) {
      finalDecision = RiskDecision.KILL_SWITCH_REQUIRED;
      finalState = RiskState.CRITICAL;
    } else if (hasPause) {
      finalDecision = RiskDecision.PAUSE;
      finalState = RiskState.HIGH;
    } else if (hasStopCopy) {
      finalDecision = RiskDecision.STOP_COPY;
      finalState = RiskState.HIGH;
    } else if (hasReview) {
      finalDecision = RiskDecision.REVIEW_REQUIRED;
      finalState = RiskState.UNKNOWN;
    } else if (hasReduce) {
      finalDecision = RiskDecision.REDUCE;
      finalState = RiskState.ELEVATED;
    }

    // If any STALE and live, block
    if (environment === 'LIVE' && details.some((d) => d.state === RiskState.STALE)) {
      finalDecision = RiskDecision.BLOCK;
      finalState = RiskState.STALE;
    }

    const ruleIds = Array.from(new Set(details.map((d) => d.ruleId)));

    return {
      id: `risk-dec-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      tenantId,
      userId,
      accountId,
      symbol,
      venue: null,
      traderId,
      followerId,
      strategyId,
      orderIntentId: requestId,
      decision: finalDecision,
      state: finalState,
      blockingReasons,
      warnings,
      details,
      policies: policy.scopeChain.map((s: any) => ({ scope: s.scope, scopeId: s.scopeId, version: s.version.toString(), digest: s.digest })),
      ruleIds,
      policyVersion: policy.effectiveVersion,
      timestamp: new Date().toISOString(),
      requestId,
      environment,
      complianceDecision: details.find((d) => d.dimension === RiskDimension.COMPLIANCE)?.decision ?? null,
      securityDecision: details.find((d) => d.dimension === RiskDimension.SECURITY)?.decision ?? null,
      exchangeHealth: details.find((d) => d.dimension === RiskDimension.EXCHANGE_HEALTH)?.state ?? null,
      circuitBreaker: null,
      killSwitch: null,
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { InstitutionalRiskPolicyService } from './risk-policy.service';
import {
  PortfolioExposure,
  SymbolExposure,
  VenueExposure,
  AccountExposure,
  RiskState,
} from './risk-management.types';

/**
 * Portfolio exposure aggregation from canonical sources only:
 * - Position (canonical, derived from fills, never venue snapshot)
 * - Order (open orders, canonical)
 * - AccountBalanceSnapshot (canonical, not client-provided)
 * - MarketDataRecord / TradingSymbol mark prices
 *
 * Decimal-safe arithmetic mandatory: uses scaled BigInt (1e12).
 * Never trusts client-provided balances/equity/exposure.
 * Stale/missing market data => explicit STALE/UNKNOWN, never invented.
 */

const SCALE = 1_000_000_000_000n; // 1e12
const SCALE_DIGITS = 12;

function isValidDecimalString(v: string | null | undefined): boolean {
  if (!v) return false;
  return /^-?\d+(\.\d+)?$/.test(v);
}

function parseScaled(s: string): bigint {
  const negative = s.startsWith('-');
  const clean = negative ? s.slice(1) : s;
  const [intPart = '0', fracPart = ''] = clean.split('.');
  const fracPadded = (fracPart + '0'.repeat(SCALE_DIGITS)).slice(0, SCALE_DIGITS);
  const scaled = BigInt(intPart || '0') * SCALE + BigInt(fracPadded || '0');
  return negative ? -scaled : scaled;
}

function formatScaled(b: bigint): string {
  const negative = b < 0n;
  const abs = negative ? -b : b;
  const intPart = abs / SCALE;
  const fracPart = abs % SCALE;
  const fracStr = fracPart.toString().padStart(SCALE_DIGITS, '0').replace(/0+$/, '');
  const result = fracStr ? `${intPart}.${fracStr}` : `${intPart}`;
  return negative ? `-${result}` : result;
}

function add(a: string, b: string): string {
  return formatScaled(parseScaled(a) + parseScaled(b));
}
function sub(a: string, b: string): string {
  return formatScaled(parseScaled(a) - parseScaled(b));
}
function absStr(a: string): string {
  return a.startsWith('-') ? a.slice(1) : a;
}
function mul(a: string, b: string): string {
  // (a*1e12 * b*1e12)/1e12
  const av = parseScaled(a);
  const bv = parseScaled(b);
  return formatScaled((av * bv) / SCALE);
}
function cmp(a: string, b: string): number {
  const av = parseScaled(a);
  const bv = parseScaled(b);
  if (av < bv) return -1;
  if (av > bv) return 1;
  return 0;
}

@Injectable()
export class PortfolioExposureService {
  private readonly logger = new Logger(PortfolioExposureService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: InstitutionalRiskPolicyService,
  ) {}

  async calculateExposure(params: {
    tenantId: string;
    accountId?: string;
    traderId?: string;
    strategyId?: string;
    followerId?: string;
    userId?: string;
  }): Promise<PortfolioExposure> {
    const { tenantId, accountId, traderId, strategyId, followerId } = params;

    const policy = await this.policyService.resolveEffectivePolicy({
      tenantId,
      traderId: traderId ?? null,
      strategyId: strategyId ?? null,
      followerId: followerId ?? null,
    });

    // Canonical positions
    const positions = await this.prisma.position.findMany({
      where: {
        tenantId,
        ...(accountId ? { accountId } : {}),
      },
      include: { symbolRef: true },
    });

    // Canonical open orders
    const openOrders = await this.prisma.order.findMany({
      where: {
        tenantId,
        ...(accountId ? { accountId } : {}),
        status: { in: ['PENDING', 'SUBMITTED', 'ACKNOWLEDGED', 'PARTIALLY_FILLED'] },
      },
    });

    // Canonical balances (latest per account asset, but we have snapshot table)
    const balances = await this.prisma.accountBalanceSnapshot.findMany({
      where: { tenantId, ...(accountId ? { accountId } : {}) },
    });

    // Trading symbols for price metadata
    const symbols = await this.prisma.tradingSymbol.findMany({
      where: { tenantId },
    });
    const symbolMap = new Map(symbols.map((s) => [s.symbol, s]));

    const now = new Date();
    const nowIso = now.toISOString();
    const staleSymbols: string[] = [];
    const unknownPrices: string[] = [];

    // Aggregate per symbol
    const symbolAgg = new Map<string, { long: bigint; short: bigint; net: bigint; gross: bigint; openOrder: bigint; venue: string; base: string | null; quote: string | null; price: string | null; priceTs: string | null; isStale: boolean }>();

    for (const pos of positions) {
      const sym = pos.symbol;
      const venue = pos.venue as string;
      const qtyStr = pos.quantity.toString();
      if (!isValidDecimalString(qtyStr)) continue;
      const markPrice = pos.markPrice?.toString() ?? pos.averageEntryPrice?.toString() ?? null;
      const priceValid = isValidDecimalString(markPrice);
      let notionalStr: string | null = null;
      if (priceValid) {
        notionalStr = mul(absStr(qtyStr), markPrice!);
      } else {
        unknownPrices.push(sym);
      }

      let agg = symbolAgg.get(sym);
      if (!agg) {
        agg = {
          long: 0n,
          short: 0n,
          net: 0n,
          gross: 0n,
          openOrder: 0n,
          venue,
          base: pos.symbolRef?.baseAsset ?? null,
          quote: pos.symbolRef?.quoteAsset ?? null,
          price: markPrice,
          priceTs: pos.updatedAt?.toISOString() ?? null,
          isStale: false,
        };
        symbolAgg.set(sym, agg);
      }
      if (notionalStr) {
        const signedQty = parseScaled(qtyStr);
        if (signedQty >= 0n) {
          agg.long += parseScaled(notionalStr);
        } else {
          agg.short += parseScaled(notionalStr);
        }
        agg.net += signedQty >= 0n ? parseScaled(notionalStr) : -parseScaled(notionalStr);
        agg.gross += parseScaled(notionalStr);
      }
      // Check stale: if markPrice older than policy marketDataMaxAgeMs
      const ageMs = now.getTime() - new Date(pos.updatedAt).getTime();
      if (ageMs > policy.thresholds.marketDataMaxAgeMs) {
        agg.isStale = true;
        if (!staleSymbols.includes(sym)) staleSymbols.push(sym);
      }
    }

    // Add open order notional per symbol
    for (const ord of openOrders) {
      const sym = ord.symbol;
      const qtyStr = ord.quantity.toString();
      const priceStr = ord.price?.toString() ?? null;
      let notionalStr: string | null = null;
      if (isValidDecimalString(qtyStr) && isValidDecimalString(priceStr)) {
        notionalStr = mul(qtyStr, priceStr!);
      } else if (isValidDecimalString(qtyStr)) {
        // If market order without price, use mark price if available
        const agg = symbolAgg.get(sym);
        if (agg?.price && isValidDecimalString(agg.price)) {
          notionalStr = mul(qtyStr, agg.price);
        }
      }
      if (notionalStr) {
        let agg = symbolAgg.get(sym);
        if (!agg) {
          agg = {
            long: 0n,
            short: 0n,
            net: 0n,
            gross: 0n,
            openOrder: 0n,
            venue: ord.venue as string,
            base: null,
            quote: null,
            price: null,
            priceTs: null,
            isStale: false,
          };
          symbolAgg.set(sym, agg);
        }
        agg.openOrder += parseScaled(notionalStr);
      }
    }

    // Compute totals
    let totalGross = 0n;
    let totalNet = 0n;
    let totalLong = 0n;
    let totalShort = 0n;
    let totalOpenOrder = 0n;

    for (const agg of symbolAgg.values()) {
      totalGross += agg.gross;
      totalNet += agg.net;
      totalLong += agg.long;
      totalShort += agg.short;
      totalOpenOrder += agg.openOrder;
    }

    const grossExposure = formatScaled(totalGross);
    const netExposure = formatScaled(totalNet);
    const longExposure = formatScaled(totalLong);
    const shortExposure = formatScaled(totalShort);
    const openOrderExposure = formatScaled(totalOpenOrder);
    const totalExposure = formatScaled(totalGross + totalOpenOrder);

    // Symbol exposures
    const symbolExposures: SymbolExposure[] = [];
    for (const [symbol, agg] of symbolAgg.entries()) {
      const grossStr = formatScaled(agg.gross);
      const conc = totalGross > 0n ? formatScaled((agg.gross * 100n * SCALE) / totalGross / SCALE) : null;
      // Actually percent = gross / totalGross *100
      const concPercent = totalGross > 0n ? formatScaled((agg.gross * 100n * SCALE) / totalGross) : null; // wait we already divided?
      // Let's compute properly: (agg.gross / totalGross)*100
      let concentrationPercent: string | null = null;
      if (totalGross > 0n) {
        const pctScaled = (agg.gross * 100n * SCALE) / totalGross;
        concentrationPercent = formatScaled(pctScaled);
      }
      symbolExposures.push({
        symbol,
        venue: agg.venue,
        baseAsset: agg.base,
        quoteAsset: agg.quote,
        longNotional: formatScaled(agg.long),
        shortNotional: formatScaled(agg.short),
        netNotional: formatScaled(agg.net),
        grossNotional: grossStr,
        openOrderNotional: formatScaled(agg.openOrder),
        totalExposure: formatScaled(agg.gross + agg.openOrder),
        concentrationPercent,
        price: agg.price,
        priceTimestamp: agg.priceTs,
        isStale: agg.isStale,
      });
    }

    // Venue exposures
    const venueMap = new Map<string, { gross: bigint; net: bigint; accounts: Set<string>; symbols: Set<string> }>();
    for (const [sym, agg] of symbolAgg.entries()) {
      const v = agg.venue;
      let vm = venueMap.get(v);
      if (!vm) {
        vm = { gross: 0n, net: 0n, accounts: new Set(), symbols: new Set() };
        venueMap.set(v, vm);
      }
      vm.gross += agg.gross;
      vm.net += agg.net;
      vm.symbols.add(sym);
    }
    // Add account info for venue
    for (const pos of positions) {
      const vm = venueMap.get(pos.venue as string);
      if (vm) vm.accounts.add(pos.accountId);
    }
    const venueExposures: VenueExposure[] = [];
    for (const [venue, vm] of venueMap.entries()) {
      const conc = totalGross > 0n ? formatScaled((vm.gross * 100n * SCALE) / totalGross) : null;
      venueExposures.push({
        venue,
        grossNotional: formatScaled(vm.gross),
        netNotional: formatScaled(vm.net),
        concentrationPercent: conc,
        accountCount: vm.accounts.size,
        symbolCount: vm.symbols.size,
      });
    }

    // Account exposures
    const accountMap = new Map<string, { venue: string; gross: bigint; net: bigint; long: bigint; short: bigint; openOrder: bigint; symbols: Set<string> }>();
    for (const pos of positions) {
      const qtyStr = pos.quantity.toString();
      const markPrice = pos.markPrice?.toString() ?? pos.averageEntryPrice?.toString() ?? null;
      let notional = 0n;
      if (isValidDecimalString(qtyStr) && isValidDecimalString(markPrice)) {
        notional = parseScaled(mul(absStr(qtyStr), markPrice!));
      }
      let am = accountMap.get(pos.accountId);
      if (!am) {
        am = { venue: pos.venue as string, gross: 0n, net: 0n, long: 0n, short: 0n, openOrder: 0n, symbols: new Set() };
        accountMap.set(pos.accountId, am);
      }
      am.gross += notional;
      const signed = parseScaled(qtyStr);
      if (signed >= 0n) {
        am.long += notional;
        am.net += notional;
      } else {
        am.short += notional;
        am.net -= notional;
      }
      am.symbols.add(pos.symbol);
    }
    for (const ord of openOrders) {
      const qtyStr = ord.quantity.toString();
      const priceStr = ord.price?.toString() ?? null;
      let notional = 0n;
      if (isValidDecimalString(qtyStr) && isValidDecimalString(priceStr)) {
        notional = parseScaled(mul(qtyStr, priceStr!));
      }
      let am = accountMap.get(ord.accountId);
      if (!am) {
        am = { venue: ord.venue as string, gross: 0n, net: 0n, long: 0n, short: 0n, openOrder: 0n, symbols: new Set() };
        accountMap.set(ord.accountId, am);
      }
      am.openOrder += notional;
    }
    const accountExposures: AccountExposure[] = [];
    for (const [accountId, am] of accountMap.entries()) {
      accountExposures.push({
        accountId,
        venue: am.venue,
        grossNotional: formatScaled(am.gross),
        netNotional: formatScaled(am.net),
        longNotional: formatScaled(am.long),
        shortNotional: formatScaled(am.short),
        openOrderNotional: formatScaled(am.openOrder),
        totalExposure: formatScaled(am.gross + am.openOrder),
        symbolCount: am.symbols.size,
      });
    }

    // Strategy exposures: need to map positions via orders? For now aggregate via strategyId in orders
    // If strategyId present in positions? Position doesn't have strategyId, so we use orders.
    const strategyMap = new Map<string, { gross: bigint; net: bigint; traderId: string | null }>();
    // Use copyTrading? For simplicity, use orders grouped by strategyId
    const ordersByStrategy = openOrders.filter((o) => o.strategyId);
    for (const o of ordersByStrategy) {
      const sid = o.strategyId!;
      let sm = strategyMap.get(sid);
      if (!sm) {
        sm = { gross: 0n, net: 0n, traderId: null };
        strategyMap.set(sid, sm);
      }
      const qtyStr = o.quantity.toString();
      const priceStr = o.price?.toString() ?? '0';
      if (isValidDecimalString(qtyStr) && isValidDecimalString(priceStr)) {
        const notional = parseScaled(mul(qtyStr, priceStr));
        sm.gross += notional >= 0n ? notional : -notional;
        sm.net += notional;
      }
    }
    const strategyExposures = Array.from(strategyMap.entries()).map(([strategyId, v]) => ({
      strategyId,
      grossNotional: formatScaled(v.gross),
      netNotional: formatScaled(v.net),
      traderId: v.traderId,
    }));

    // Trader exposures via TraderStrategy relation
    const traderExposures: PortfolioExposure['traderExposures'] = [];
    const followerExposures: PortfolioExposure['followerExposures'] = [];

    // Notional utilization
    let notionalUtilizationPercent: string | null = null;
    if (policy.thresholds.maxGrossExposure && isValidDecimalString(policy.thresholds.maxGrossExposure)) {
      const maxGross = parseScaled(policy.thresholds.maxGrossExposure);
      if (maxGross > 0n) {
        notionalUtilizationPercent = formatScaled((totalGross * 100n * SCALE) / maxGross);
      }
    }

    const state = this.determineExposureState(totalGross, policy, staleSymbols);

    const sourceTimestamps: Record<string, string> = {
      positions: positions.length ? (positions[0].updatedAt?.toISOString() ?? nowIso) : nowIso,
      orders: openOrders.length ? (openOrders[0].updatedAt?.toISOString() ?? nowIso) : nowIso,
      balances: balances.length ? (balances[0].updatedAt?.toISOString() ?? nowIso) : nowIso,
      calculatedAt: nowIso,
    };

    return {
      tenantId,
      asOf: nowIso,
      policyVersion: policy.effectiveVersion,
      grossExposure,
      netExposure,
      longExposure,
      shortExposure,
      openOrderExposure,
      totalExposure,
      notionalUtilizationPercent,
      symbolExposures,
      venueExposures,
      accountExposures,
      strategyExposures,
      traderExposures,
      followerExposures,
      staleSymbols,
      unknownPrices,
      sourceTimestamps,
      state,
      warnings: [...(staleSymbols.length ? [`Stale market data for: ${staleSymbols.join(',')}`] : []), ...(unknownPrices.length ? [`Unknown prices for: ${unknownPrices.join(',')}`] : [])],
    };
  }

  private determineExposureState(totalGross: bigint, policy: any, staleSymbols: string[]): RiskState {
    if (staleSymbols.length > 0) return RiskState.STALE;
    if (totalGross === 0n) return RiskState.NORMAL;
    const thresholds = policy.thresholds;
    if (thresholds.maxGrossExposure && isValidDecimalString(thresholds.maxGrossExposure)) {
      const max = parseScaled(thresholds.maxGrossExposure);
      if (totalGross > max) return RiskState.BLOCKED;
      if (totalGross > (max * 80n) / 100n) return RiskState.HIGH;
      if (totalGross > (max * 60n) / 100n) return RiskState.ELEVATED;
    }
    return RiskState.NORMAL;
  }
}

/**
 * Deterministic tests for the risk calculations that used to rely on
 * placeholders: day-start equity (daily loss), intraday drawdown and the
 * stress scenario model. Prisma and the policy service are in-memory fakes.
 */
import { resolveDayStartEquity, scopeAccountIdsOf } from './day-start-equity';
import { DailyLossLimitService } from './daily-loss-limit.service';
import { DrawdownRiskService } from './drawdown-risk.service';
import { StressTestService, computeScenarioImpact } from './stress-test.service';
import { PortfolioExposure, RiskState, StressScenario } from './risk-management.types';

const TENANT = '00000000-0000-0000-0000-00000000000a';
const ACC1 = '00000000-0000-0000-0000-000000000001';
const ACC2 = '00000000-0000-0000-0000-000000000002';
const today = () => new Date().toISOString().slice(0, 10);

function dec(v: string) {
  return { toString: () => v };
}

interface Meta {
  accountId: string;
  tradingDay: string;
  equity: string | null;
  capturedAt: Date;
}

function fakePrisma(opts: { metas?: Meta[]; balances?: Array<{ accountId: string; total: string }>; positions?: Array<{ accountId: string; unrealisedPnl: string | null }> }) {
  const settings = new Map<string, any>();
  return {
    settings,
    riskSnapshotMetadata: {
      findMany: jest.fn(async (args: any) => {
        const ids: string[] = args.where.accountId.in;
        return (opts.metas ?? [])
          .filter((m) => m.tradingDay === args.where.tradingDay && ids.includes(m.accountId) && m.equity !== null)
          .sort((a, b) => a.capturedAt.getTime() - b.capturedAt.getTime())
          .map((m) => ({ accountId: m.accountId, equity: m.equity === null ? null : dec(m.equity), capturedAt: m.capturedAt }));
      }),
    },
    accountBalanceSnapshot: {
      findMany: jest.fn(async (args: any) =>
        (opts.balances ?? []).filter((b) => !args.where.accountId || b.accountId === args.where.accountId).map((b) => ({ ...b, total: dec(b.total), updatedAt: new Date() })),
      ),
    },
    position: {
      findMany: jest.fn(async (args: any) =>
        (opts.positions ?? [])
          .filter((p) => !args.where.accountId || p.accountId === args.where.accountId)
          .map((p) => ({ ...p, unrealisedPnl: p.unrealisedPnl === null ? null : dec(p.unrealisedPnl), updatedAt: new Date() })),
      ),
    },
    fill: { findMany: jest.fn(async () => []) },
  } as any;
}

function fakePolicy(thresholds: Record<string, any>) {
  return { resolveEffectivePolicy: jest.fn(async () => ({ effectiveVersion: 'v-test', thresholds })) } as any;
}

function fakeSnapshotRepo() {
  const store = new Map<string, { highWaterMark: string; timestamp: string }>();
  return {
    store,
    getHighWaterMark: jest.fn(async (p: any) => store.get(`${p.scope}:${p.scopeId}`) ?? null),
    persistHighWaterMark: jest.fn(async (p: any) => {
      store.set(`${p.scope}:${p.scopeId}`, { highWaterMark: p.highWaterMark, timestamp: p.timestamp });
    }),
  } as any;
}

describe('resolveDayStartEquity', () => {
  test('earliest snapshot of the day per account, summed', async () => {
    const d = today();
    const prisma = fakePrisma({
      metas: [
        { accountId: ACC1, tradingDay: d, equity: '1200', capturedAt: new Date(`${d}T05:00:00Z`) },
        { accountId: ACC1, tradingDay: d, equity: '1000', capturedAt: new Date(`${d}T00:01:00Z`) },
        { accountId: ACC2, tradingDay: d, equity: '500.5', capturedAt: new Date(`${d}T00:02:00Z`) },
        { accountId: ACC2, tradingDay: '1999-01-01', equity: '9', capturedAt: new Date('1999-01-01T00:00:00Z') },
      ],
    });
    await expect(resolveDayStartEquity(prisma, TENANT, d, [ACC1, ACC2])).resolves.toBe('1500.5');
  });

  test('any account without a snapshot makes the reference unknown', async () => {
    const d = today();
    const prisma = fakePrisma({ metas: [{ accountId: ACC1, tradingDay: d, equity: '1000', capturedAt: new Date() }] });
    await expect(resolveDayStartEquity(prisma, TENANT, d, [ACC1, ACC2])).resolves.toBeNull();
    await expect(resolveDayStartEquity(prisma, TENANT, d, [])).resolves.toBeNull();
  });

  test('scopeAccountIdsOf: explicit account wins, else distinct rows', () => {
    expect(Array.from(scopeAccountIdsOf(ACC1, [{ accountId: ACC2 }]))).toEqual([ACC1]);
    expect(Array.from(scopeAccountIdsOf(undefined, [{ accountId: ACC2 }, { accountId: ACC1 }, { accountId: ACC2 }])).sort()).toEqual([ACC1, ACC2]);
  });
});

describe('DailyLossLimitService', () => {
  test('uses day-start EQUITY (not gross exposure) and breaches on a real loss', async () => {
    const d = today();
    const prisma = fakePrisma({
      metas: [{ accountId: ACC1, tradingDay: d, equity: '10000', capturedAt: new Date(`${d}T00:00:30Z`) }],
      balances: [{ accountId: ACC1, total: '8500' }],
      positions: [{ accountId: ACC1, unrealisedPnl: '-300' }],
    });
