    const [r] = await service.evaluateDailyLoss({ tenantId: TENANT, accountId: ACC1 });
    expect(r.startingEquity).toBe('10000');
    expect(r.currentEquity).toBe('8200');
    expect(r.dailyPnl).toBe('-1800');
