describe('DrawdownRiskService intraday drawdown', () => {
  test('peak seeded with day-start equity, ratchets up, persists per day', async () => {
    const d = today();
    let balance = '10500';
    const prisma = fakePrisma({ metas: [{ accountId: ACC1, tradingDay: d, equity: '10000', capturedAt: new Date() }], balances: [] });
    prisma.accountBalanceSnapshot.findMany = jest.fn(async () => [{ accountId: ACC1, total: dec(balance), updatedAt: new Date() }]);
    const repo = fakeSnapshotRepo();
    const service = new DrawdownRiskService(prisma, fakePolicy({ maxDrawdownPercent: '50' }), repo);

    const [first] = await service.evaluateDrawdown({ tenantId: TENANT, accountId: ACC1 });
    expect(first.intradayDrawdownPercent).toBe('0'); // new intraday peak 10500
    const key = `TENANT:${ACC1}:${d.replace(/-/g, '')}`;
    expect(repo.store.get(key)?.highWaterMark).toBe('10500');

    balance = '9450';
    const [second] = await service.evaluateDrawdown({ tenantId: TENANT, accountId: ACC1 });
    expect(second.intradayDrawdownPercent).toBe('10'); // (10500-9450)/10500
    expect(repo.store.get(key)?.highWaterMark).toBe('10500');
  });

  test('without day-start equity the intraday figure is null, not the rolling one', async () => {
    const prisma = fakePrisma({ balances: [{ accountId: ACC1, total: '9000' }] });
    const repo = fakeSnapshotRepo();
    repo.store.set(`TENANT:${ACC1}`, { highWaterMark: '10000', timestamp: new Date().toISOString() });
    const service = new DrawdownRiskService(prisma, fakePolicy({ maxDrawdownPercent: '50' }), repo);
    const [r] = await service.evaluateDrawdown({ tenantId: TENANT, accountId: ACC1 });
    expect(r.rollingDrawdownPercent).toBe('10');
    expect(r.intradayDrawdownPercent).toBeNull();
  });
});

function exposure(partial: Partial<PortfolioExposure>): PortfolioExposure {
  return {
    tenantId: TENANT,
    asOf: new Date().toISOString(),
    policyVersion: 'v',
    grossExposure: '0',
    netExposure: '0',
    longExposure: '0',
    shortExposure: '0',
    openOrderExposure: '0',
    totalExposure: '0',
    notionalUtilizationPercent: null,
    symbolExposures: [],
    venueExposures: [],
    accountExposures: [],
    strategyExposures: [],
    traderExposures: [],
    followerExposures: [],
    staleSymbols: [],
    unknownPrices: [],
    sourceTimestamps: {},
    state: RiskState.NORMAL,
    warnings: [],
    ...partial,
  };
}

function sym(symbol: string, base: string, net: string, gross: string) {
  return { symbol, venue: 'BINANCE', baseAsset: base, quoteAsset: 'USDT', longNotional: '0', shortNotional: '0', netNotional: net, grossNotional: gross, openOrderNotional: '0', totalExposure: gross, concentrationPercent: null, price: null, priceTimestamp: null, isStale: false };
}

function scenario(type: any, parameters: Record<string, string>, shockedAssets: string[] = []): StressScenario {
  return { scenarioId: `T_${type}`, type, name: type, description: type, parameters, shockedAssets };
}

describe('computeScenarioImpact', () => {
  // Long 10k BTC, short 4k ETH: gross 14k, net +6k.
  const book = exposure({
    grossExposure: '14000',
    netExposure: '6000',
    symbolExposures: [sym('BTC-USDT', 'BTC', '10000', '10000'), sym('ETH-USDT', 'ETH', '-4000', '4000')],
    venueExposures: [{ venue: 'BINANCE', grossNotional: '14000', netNotional: '6000', concentrationPercent: '100', accountCount: 1, symbolCount: 2 }],
  });
  const equity = 20000n * 1_000_000_000_000n;

  test('market shock revalues the signed net book (shorts gain on a down move)', () => {
    const r = computeScenarioImpact(scenario('MARKET_SHOCK', { shockPercent: '-10' }), book, equity);
    expect(r.pnl).toBe('-600'); // -1000 on BTC long, +400 on ETH short
    expect(r.exposure).toBe('12600');
    expect(r.margin).toBe('3'); // 600 / 20000
  });

  test('correlated shock only touches the listed assets', () => {
    const r = computeScenarioImpact(scenario('CORRELATED_SHOCK', { shockPercent: '-20' }, ['BTC']), book, equity);
    expect(r.pnl).toBe('-2000');
    expect(r.exposure).toBe('12000'); // BTC 10000 -> 8000, ETH unchanged 4000
  });

  test('gains consume no margin', () => {
    const r = computeScenarioImpact(scenario('GAP_MOVE', { gapPercent: '15' }), book, equity);
    expect(r.pnl).toBe('900');
    expect(r.margin).toBe('0');
  });

  test('margin impact is null when equity is unknown', () => {
    expect(computeScenarioImpact(scenario('MARKET_SHOCK', { shockPercent: '-10' }), book, null).margin).toBeNull();
  });

  test('slippage prices liquidation of the gross book from bps', () => {
    const r = computeScenarioImpact(scenario('SLIPPAGE_EXPANSION', { slippageBpsIncrease: '100' }), book, equity);
    expect(r.pnl).toBe('-140');
  });

  test('liquidity reduction uses stated parameters, no hidden 1%', () => {
    const r = computeScenarioImpact(scenario('LIQUIDITY_REDUCTION', { baseMarketImpactBps: '25', marketImpactMultiplier: '2' }), book, equity);
    expect(r.pnl).toBe('-70'); // 14000 * 0.25% * 2
    expect(computeScenarioImpact(scenario('LIQUIDITY_REDUCTION', { marketImpactMultiplier: '2' }), book, equity).pnl).toBeNull();
  });

  test('vol expansion needs an initial margin rate; otherwise margin impact is null', () => {
    expect(computeScenarioImpact(scenario('VOL_EXPANSION', { marginIncreasePercent: '50' }), book, equity).margin).toBeNull();
    const r = computeScenarioImpact(scenario('VOL_EXPANSION', { marginIncreasePercent: '50', initialMarginRatePercent: '10' }), book, equity);
    expect(r.margin).toBe('3.5'); // IM 1400, +50% = 700, / 20000
  });

  test('exchange outage traps only the named venue exposure', () => {
    expect(computeScenarioImpact(scenario('EXCHANGE_OUTAGE', { venue: 'BINANCE' }), book, equity)).toEqual(expect.objectContaining({ exposure: '14000', elevate: true }));
    expect(computeScenarioImpact(scenario('EXCHANGE_OUTAGE', { venue: 'OKX' }), book, equity)).toEqual(expect.objectContaining({ exposure: '0', elevate: false }));
  });

  test('empty book is zero impact', () => {
    expect(computeScenarioImpact(scenario('MARKET_SHOCK', { shockPercent: '-10' }), exposure({}), equity)).toEqual({ pnl: '0', exposure: '0', margin: '0', elevate: false });
  });
});

describe('StressTestService', () => {
  test('breach only on losses; levels never downgraded; unknown estimates are UNKNOWN', async () => {
    const book = exposure({ grossExposure: '14000', netExposure: '6000', symbolExposures: [sym('BTC-USDT', 'BTC', '10000', '10000'), sym('ETH-USDT', 'ETH', '-4000', '4000')] });
    const prisma = fakePrisma({ balances: [{ accountId: ACC1, total: '20000' }] });
    const exposureService = { calculateExposure: jest.fn(async () => book) } as any;
    const service = new StressTestService(prisma, fakePolicy({ stressLossThreshold: '500' }), exposureService);
    const results = await service.runStressTests({
      tenantId: TENANT,
      accountId: ACC1,
      scenarios: [
        scenario('MARKET_SHOCK', { shockPercent: '-10' }),
        scenario('MARKET_SHOCK', { shockPercent: '20' }),
        scenario('LIQUIDITY_REDUCTION', { marketImpactMultiplier: '2' }),
      ],
    });
    expect(results[0].isBreach).toBe(true);
    expect(results[0].riskLevel).toBe(RiskState.HIGH);
    expect(results[0].estimatedMarginImpact).toBe('3');
    expect(results[1].estimatedPnlImpact).toBe('1200');
    expect(results[1].isBreach).toBe(false);
    expect(results[2].estimatedPnlImpact).toBeNull();
    expect(results[2].riskLevel).toBe(RiskState.UNKNOWN);
  });
});

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OutboxService } from '../../infrastructure/outbox/outbox.service';
import { InstitutionalRiskPolicyService } from './risk-policy.service';
import { PortfolioExposureService } from './portfolio-exposure.service';
import { PositionRiskService } from './position-risk.service';
import { MarginRiskService } from './margin-risk.service';
import { LeverageRiskService } from './leverage-risk.service';
import { LiquidationRiskService } from './liquidation-risk.service';
import { ConcentrationRiskService } from './concentration-risk.service';
import { DrawdownRiskService } from './drawdown-risk.service';
import { DailyLossLimitService } from './daily-loss-limit.service';
import { CorrelationRiskService } from './correlation-risk.service';
import { VarRiskService } from './var-risk.service';
import { StressTestService } from './stress-test.service';
import { CircuitBreakerService } from './circuit-breaker.service';
import { KillSwitchOrchestratorService } from './kill-switch-orchestrator.service';
import { RiskManagementSnapshotRepository } from './risk-snapshot.repository';
import { RiskEventService } from './risk-event.service';
import {
  UnifiedRiskDecision,
  RiskDecision,
  RiskState,
  RiskDimension,
  RiskPolicyScope,
  RiskDecisionDetail,
  RiskSeverity,
  RiskEventType,
  CircuitBreakerScope,
} from './risk-management.types';

/**
 * Unified risk decision orchestration.
 * Input: tenant/user/account/order intent/strategy/follower/symbol/env
 * Compose: exposure/position/margin/leverage/liquidation/concentration/drawdown/daily loss/correlation/compliance/security/exchange health/circuit-breaker/kill-switch
 * Explicit priority: BLOCKED/KILL_SWITCH never becomes ALLOW.
 * Returns final decision/state/blocking reasons/warnings/policies/ruleIds/policy version/timestamp.
 *
 * Reuses existing RiskModule, ExecutionEngine, ExchangesModule, Compliance, Security, CopyTrading, etc via Prisma reads.
 * Never directly places order, never bypasses compliance/live-mode gate, never mutates ledger.
 * Decimal-safe, deterministic.
 */

@Injectable()
export class RiskDecisionService {
  private readonly logger = new Logger(RiskDecisionService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: InstitutionalRiskPolicyService,
    private readonly exposureService: PortfolioExposureService,
    private readonly positionService: PositionRiskService,
    private readonly marginService: MarginRiskService,
    private readonly leverageService: LeverageRiskService,
    private readonly liquidationService: LiquidationRiskService,
    private readonly concentrationService: ConcentrationRiskService,
    private readonly drawdownService: DrawdownRiskService,
    private readonly dailyLossService: DailyLossLimitService,
    private readonly correlationService: CorrelationRiskService,
    private readonly varService: VarRiskService,
    private readonly stressService: StressTestService,
    private readonly breakerService: CircuitBreakerService,
    private readonly killSwitchService: KillSwitchOrchestratorService,
    private readonly snapshotRepo: RiskManagementSnapshotRepository,
    private readonly eventService: RiskEventService,
    private readonly outbox: OutboxService,
  ) {}

  async evaluateUnifiedRisk(params: {
    tenantId: string;
    userId?: string;
    accountId?: string;
    symbol?: string;
    venue?: string;
    traderId?: string;
    followerId?: string;
    strategyId?: string;
    orderIntent?: { side: 'BUY' | 'SELL'; quantity: string; price?: string | null; orderType: 'MARKET' | 'LIMIT' | 'STOP' | 'STOP_LIMIT' } | null;
    environment?: 'PAPER' | 'LIVE';
    requestId?: string;
  }): Promise<UnifiedRiskDecision> {
    const {
      tenantId,
      userId,
      accountId,
      symbol,
      venue,
      traderId,
      followerId,
      strategyId,
      orderIntent,
      environment = 'PAPER',
      requestId,
    } = params;

    const nowIso = new Date().toISOString();
    const policy = await this.policyService.resolveEffectivePolicy({
      tenantId,
      traderId: traderId ?? null,
      strategyId: strategyId ?? null,
      followerId: followerId ?? null,
    });

    const details: RiskDecisionDetail[] = [];
    const blockingReasons: string[] = [];
    const warnings: string[] = [];

    // Helper to push detail
    const pushDetail = (d: RiskDecisionDetail) => {
      details.push(d);
      if (d.isBlocking) blockingReasons.push(d.reason);
      if (d.isWarning) warnings.push(d.reason);
    };

    // 1. Exposure
    try {
      const exposure = await this.exposureService.calculateExposure({ tenantId, accountId, traderId, strategyId, followerId });
      if (exposure.state === RiskState.BLOCKED) {
        pushDetail({
          dimension: RiskDimension.EXPOSURE,
          decision: RiskDecision.BLOCK,
          state: RiskState.BLOCKED,
          ruleId: 'MAX_GROSS_EXPOSURE',
          policyVersion: policy.effectiveVersion,
          current: exposure.grossExposure,
          threshold: policy.thresholds.maxGrossExposure,
          severity: RiskSeverity.CRITICAL,
          reason: `Gross exposure ${exposure.grossExposure} exceeds limit ${policy.thresholds.maxGrossExposure}`,
          timestamp: nowIso,
          scope: RiskPolicyScope.TENANT,
          scopeId: tenantId,
          isBlocking: true,
          isWarning: false,
        });
      } else if (exposure.state === RiskState.STALE) {
        pushDetail({
          dimension: RiskDimension.MARKET_DATA,
          decision: environment === 'LIVE' ? RiskDecision.BLOCK : RiskDecision.REVIEW_REQUIRED,
          state: RiskState.STALE,
          ruleId: 'MARKET_DATA_STALE',
          policyVersion: policy.effectiveVersion,
          current: null,
          threshold: policy.thresholds.marketDataMaxAgeMs.toString(),
          severity: RiskSeverity.WARNING,
          reason: `Exposure stale due to market data: ${exposure.staleSymbols.join(',')}`,
          timestamp: nowIso,
          scope: RiskPolicyScope.TENANT,
          scopeId: tenantId,
          isBlocking: environment === 'LIVE',
          isWarning: environment !== 'LIVE',
        });
      }
      // Check symbol exposure if order intent present
      if (orderIntent && symbol) {
        const symExp = exposure.symbolExposures.find((s) => s.symbol === symbol);
        if (symExp && policy.thresholds.maxSymbolExposure) {
          // Compare grossNotional vs threshold
          const gross = symExp.grossNotional;
          if (gross && policy.thresholds.maxSymbolExposure) {
            const cmp = this.cmpDecimal(gross, policy.thresholds.maxSymbolExposure);
            if (cmp > 0) {
              pushDetail({
                dimension: RiskDimension.EXPOSURE,
                decision: RiskDecision.BLOCK,
                state: RiskState.BLOCKED,
                ruleId: 'MAX_SYMBOL_EXPOSURE',
                policyVersion: policy.effectiveVersion,
                current: gross,
                threshold: policy.thresholds.maxSymbolExposure,
                severity: RiskSeverity.CRITICAL,
                reason: `Symbol exposure ${gross} for ${symbol} exceeds max ${policy.thresholds.maxSymbolExposure}`,
                timestamp: nowIso,
                scope: RiskPolicyScope.TENANT,
                scopeId: tenantId,
                isBlocking: true,
                isWarning: false,
              });
            }
          }
        }
      }
    } catch (e) {
      pushDetail({
        dimension: RiskDimension.EXPOSURE,
        decision: RiskDecision.REVIEW_REQUIRED,
        state: RiskState.UNKNOWN,
        ruleId: 'MAX_GROSS_EXPOSURE',
        policyVersion: policy.effectiveVersion,
        current: null,
        threshold: policy.thresholds.maxGrossExposure,
        severity: RiskSeverity.WARNING,
        reason: `Exposure evaluation failed: ${(e as Error).message}, fail-closed to REVIEW_REQUIRED`,
        timestamp: nowIso,
        scope: RiskPolicyScope.TENANT,
        scopeId: tenantId,
        isBlocking: false,
        isWarning: true,
      });
    }

    // 2. Position risk
    try {
      const posResults = await this.positionService.evaluatePositionRisk({ tenantId, accountId, symbol, traderId, strategyId, followerId });
      for (const pr of posResults) {
        if (pr.state === RiskState.BLOCKED || pr.state === RiskState.CRITICAL) {
          pushDetail({
            dimension: RiskDimension.POSITION,
            decision: RiskDecision.BLOCK,
            state: pr.state,
            ruleId: pr.ruleId,
            policyVersion: pr.policyVersion,
            current: pr.notional,
            threshold: policy.thresholds.maxPositionNotional,
            severity: pr.severity,
            reason: pr.reason,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: pr.accountId,
            isBlocking: true,
            isWarning: false,
          });
        } else if (pr.state === RiskState.STALE || pr.state === RiskState.UNKNOWN) {
          pushDetail({
            dimension: RiskDimension.POSITION,
            decision: RiskDecision.REVIEW_REQUIRED,
            state: pr.state,
            ruleId: pr.ruleId,
            policyVersion: pr.policyVersion,
            current: pr.notional,
            threshold: null,
            severity: pr.severity,
            reason: pr.reason,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: pr.accountId,
            isBlocking: false,
            isWarning: true,
          });
        }
      }
    } catch (e) {
      this.logger.warn(`Position risk failed: ${(e as Error).message}`);
    }

    // 3. Margin
    if (accountId) {
      try {
        const marginResults = await this.marginService.evaluateMargin({ tenantId, accountId, orderIntent: orderIntent ? { symbol: symbol ?? '', quantity: orderIntent.quantity, price: orderIntent.price ?? null, side: orderIntent.side } : null });
        for (const mr of marginResults) {
          if (mr.state === RiskState.BLOCKED || mr.state === RiskState.CRITICAL) {
            pushDetail({
              dimension: RiskDimension.MARGIN,
              decision: RiskDecision.BLOCK,
              state: mr.state,
              ruleId: mr.ruleId,
              policyVersion: mr.policyVersion,
              current: mr.marginUtilizationPercent,
              threshold: policy.thresholds.marginCriticalUtilization,
              severity: mr.severity,
              reason: mr.reason,
              timestamp: nowIso,
              scope: RiskPolicyScope.TENANT,
              scopeId: accountId,
              isBlocking: true,
              isWarning: false,
            });
          }
        }
      } catch (e) {
        this.logger.warn(`Margin risk failed: ${(e as Error).message}`);
      }
    }

    // 4. Leverage
    if (accountId) {
      try {
        const levResults = await this.leverageService.evaluateLeverage({
          tenantId,
          accountId,
          symbol,
          orderIntent: orderIntent ? { quantity: orderIntent.quantity, price: orderIntent.price ?? null, side: orderIntent.side } : null,
        });
        for (const lr of levResults) {
          if (lr.isBreach) {
            pushDetail({
              dimension: RiskDimension.LEVERAGE,
              decision: RiskDecision.BLOCK,
              state: lr.state,
              ruleId: lr.ruleId,
              policyVersion: lr.policyVersion,
              current: lr.projectedGrossLeverage ?? lr.grossLeverage,
              threshold: lr.policyMaxLeverage,
              severity: lr.severity,
              reason: lr.reason,
              timestamp: nowIso,
              scope: RiskPolicyScope.TENANT,
              scopeId: accountId,
              isBlocking: true,
              isWarning: false,
            });
          }
        }
      } catch (e) {
        this.logger.warn(`Leverage risk failed: ${(e as Error).message}`);
      }
    }

    // 5. Liquidation
    try {
      const liqResults = await this.liquidationService.evaluateLiquidationRisk({ tenantId, accountId, symbol, traderId, strategyId, followerId });
      for (const l of liqResults) {
        if (l.isCritical) {
          pushDetail({
            dimension: RiskDimension.LIQUIDATION,
            decision: RiskDecision.BLOCK,
            state: l.state,
            ruleId: l.ruleId,
            policyVersion: l.policyVersion,
            current: l.distancePercent,
            threshold: policy.thresholds.liquidationCriticalDistance,
            severity: l.severity,
            reason: l.reason,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: l.accountId,
            isBlocking: true,
            isWarning: false,
          });
        } else if (l.isWarning) {
          pushDetail({
            dimension: RiskDimension.LIQUIDATION,
            decision: RiskDecision.REDUCE,
            state: l.state,
            ruleId: l.ruleId,
            policyVersion: l.policyVersion,
            current: l.distancePercent,
            threshold: policy.thresholds.liquidationWarningDistance,
            severity: l.severity,
            reason: l.reason,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: l.accountId,
            isBlocking: false,
            isWarning: true,
          });
        }
      }
    } catch (e) {
      this.logger.warn(`Liquidation risk failed: ${(e as Error).message}`);
    }

    // 6. Concentration
    try {
      const concResults = await this.concentrationService.evaluateConcentration({
        tenantId,
        accountId,
        symbol,
        orderIntent: orderIntent && orderIntent.price ? { notional: this.mulDecimal(orderIntent.quantity, orderIntent.price), symbol: symbol ?? '' } : null,
      });
      for (const c of concResults) {
        if (c.isBreach) {
          pushDetail({
            dimension: RiskDimension.CONCENTRATION,
            decision: RiskDecision.BLOCK,
            state: c.state,
            ruleId: c.ruleId,
            policyVersion: c.policyVersion,
            current: c.currentPercent,
            threshold: c.thresholdPercent,
            severity: c.severity,
            reason: c.reason,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: tenantId,
            isBlocking: true,
            isWarning: false,
          });
        }
      }
    } catch (e) {
      this.logger.warn(`Concentration risk failed: ${(e as Error).message}`);
    }

    // 7. Drawdown
    try {
      const ddResults = await this.drawdownService.evaluateDrawdown({ tenantId, accountId, traderId, strategyId, followerId });
      for (const dd of ddResults) {
        if (dd.isBreach) {
          pushDetail({
            dimension: RiskDimension.DRAWDOWN,
            decision: RiskDecision.BLOCK,
            state: dd.state,
            ruleId: dd.ruleId,
            policyVersion: dd.policyVersion,
            current: dd.drawdownPercent,
            threshold: dd.thresholdPercent,
            severity: dd.severity,
            reason: dd.reason,
            timestamp: nowIso,
            scope: dd.scope,
            scopeId: dd.scopeId,
            isBlocking: true,
            isWarning: false,
          });
        }
      }
    } catch (e) {
      this.logger.warn(`Drawdown risk failed: ${(e as Error).message}`);
    }

    // 8. Daily loss
    try {
      const dlResults = await this.dailyLossService.evaluateDailyLoss({ tenantId, accountId, traderId, strategyId, followerId });
      for (const dl of dlResults) {
        if (dl.isBreach) {
          pushDetail({
            dimension: RiskDimension.DAILY_LOSS,
            decision: RiskDecision.BLOCK,
            state: dl.state,
            ruleId: dl.ruleId,
            policyVersion: dl.policyVersion,
            current: dl.dailyPnl,
            threshold: dl.threshold,
            severity: dl.severity,
            reason: dl.reason,
            timestamp: nowIso,
            scope: dl.scope,
            scopeId: dl.scopeId,
            isBlocking: true,
            isWarning: false,
          });
        }
      }
    } catch (e) {
      this.logger.warn(`Daily loss failed: ${(e as Error).message}`);
    }

    // 9. Correlation (advisory, not blocking unless policy says)
    try {
      const corrResults = await this.correlationService.evaluateCorrelation({ tenantId, traderId, strategyId, followerId });
      for (const cr of corrResults) {
        if (cr.isBreach) {
          pushDetail({
            dimension: RiskDimension.CORRELATION,
            decision: RiskDecision.REVIEW_REQUIRED,
            state: cr.state,
            ruleId: cr.ruleId,
            policyVersion: cr.policyVersion,
            current: cr.correlation,
            threshold: cr.threshold,
            severity: cr.severity,
            reason: cr.reason,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: tenantId,
            isBlocking: false,
            isWarning: true,
          });
        }
      }
    } catch (e) {
      this.logger.warn(`Correlation risk failed: ${(e as Error).message}`);
    }

    // 10. VaR (advisory)
    try {
      const varResults = await this.varService.evaluateVar({ tenantId, accountId, traderId, strategyId, followerId });
      for (const vr of varResults) {
        if (vr.isBreach) {
          pushDetail({
            dimension: RiskDimension.VAR,
            decision: RiskDecision.REVIEW_REQUIRED,
            state: vr.state,
            ruleId: vr.ruleId,
            policyVersion: vr.policyVersion,
            current: vr.varValue,
            threshold: vr.threshold,
            severity: vr.severity,
            reason: vr.reason,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: tenantId,
            isBlocking: false,
            isWarning: true,
          });
        }
      }
    } catch (e) {
      this.logger.warn(`VaR failed: ${(e as Error).message}`);
    }

    // 11. Stress (advisory)
    try {
      const stressResults = await this.stressService.runStressTests({ tenantId, accountId, traderId, strategyId, followerId });
      for (const sr of stressResults) {
        if (sr.isBreach) {
          pushDetail({
            dimension: RiskDimension.STRESS,
            decision: RiskDecision.REVIEW_REQUIRED,
            state: sr.riskLevel,
            ruleId: sr.ruleId,
            policyVersion: sr.policyVersion,
            current: sr.estimatedPnlImpact,
            threshold: sr.threshold,
            severity: sr.severity,
            reason: sr.reason,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: tenantId,
            isBlocking: false,
            isWarning: true,
          });
        }
      }
    } catch (e) {
      this.logger.warn(`Stress test failed: ${(e as Error).message}`);
    }

    // 12. Compliance — BLOCK prevents ALLOW
    try {
      if (userId) {
        const blocked = await this.prisma.complianceScreeningRequest.findFirst({
          where: { tenantId, userId, status: 'BLOCKED' },
          orderBy: { createdAt: 'desc' },
        });
        if (blocked) {
          pushDetail({
            dimension: RiskDimension.COMPLIANCE,
            decision: RiskDecision.BLOCK,
            state: RiskState.BLOCKED,
            ruleId: 'COMPLIANCE_BLOCK',
            policyVersion: policy.effectiveVersion,
            current: null,
            threshold: null,
            severity: RiskSeverity.CRITICAL,
            reason: `Compliance BLOCK for user ${userId} — screening ${blocked.id} blocked, decision ${blocked.decision}`,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: tenantId,
            isBlocking: true,
            isWarning: false,
          });
        }
      }
    } catch (e) {
      pushDetail({
        dimension: RiskDimension.COMPLIANCE,
        decision: RiskDecision.REVIEW_REQUIRED,
        state: RiskState.UNKNOWN,
        ruleId: 'COMPLIANCE_BLOCK',
        policyVersion: policy.effectiveVersion,
        current: null,
        threshold: null,
        severity: RiskSeverity.WARNING,
        reason: `Compliance evaluation unavailable: ${(e as Error).message}, fail-closed to REVIEW_REQUIRED`,
        timestamp: nowIso,
        scope: RiskPolicyScope.TENANT,
        scopeId: tenantId,
        isBlocking: false,
        isWarning: true,
      });
    }

    // 13. Security — BLOCK prevents ALLOW
    try {
      if (userId) {
        const threat = await this.prisma.securityThreatSignal.findFirst({
          where: { tenantId, userId, resolved: false, riskLevel: { in: ['HIGH', 'CRITICAL'] } },
          orderBy: { createdAt: 'desc' },
        });
        if (threat) {
          pushDetail({
            dimension: RiskDimension.SECURITY,
            decision: RiskDecision.BLOCK,
            state: RiskState.BLOCKED,
            ruleId: 'SECURITY_BLOCK',
            policyVersion: policy.effectiveVersion,
            current: null,
            threshold: null,
            severity: RiskSeverity.CRITICAL,
            reason: `Security BLOCK for user ${userId} — threat ${threat.ruleId} level ${threat.riskLevel}`,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: tenantId,
            isBlocking: true,
            isWarning: false,
          });
        }
      }
    } catch (e) {
      this.logger.warn(`Security check failed: ${(e as Error).message}`);
    }

    // 14. Exchange health — stale blocks live
    try {
      if (accountId) {
        const acc = await this.prisma.tradingAccount.findFirst({ where: { id: accountId, tenantId } });
        if (acc) {
          const ageMs = acc.lastVerifiedAt ? Date.now() - new Date(acc.lastVerifiedAt).getTime() : Infinity;
          if (ageMs > policy.thresholds.exchangeHealthMaxAgeMs) {
            pushDetail({
              dimension: RiskDimension.EXCHANGE_HEALTH,
              decision: environment === 'LIVE' ? RiskDecision.BLOCK : RiskDecision.REVIEW_REQUIRED,
              state: RiskState.STALE,
              ruleId: 'EXCHANGE_HEALTH_DEGRADED',
              policyVersion: policy.effectiveVersion,
              current: ageMs.toString(),
              threshold: policy.thresholds.exchangeHealthMaxAgeMs.toString(),
              severity: RiskSeverity.WARNING,
              reason: `Exchange health stale for account ${accountId}, age ${ageMs}ms > ${policy.thresholds.exchangeHealthMaxAgeMs}ms`,
              timestamp: nowIso,
              scope: RiskPolicyScope.TENANT,
              scopeId: accountId,
              isBlocking: environment === 'LIVE',
              isWarning: environment !== 'LIVE',
            });
          }
          if (acc.status !== 'ACTIVE') {
            pushDetail({
              dimension: RiskDimension.EXCHANGE_HEALTH,
              decision: RiskDecision.BLOCK,
              state: RiskState.BLOCKED,
              ruleId: 'EXCHANGE_HEALTH_DEGRADED',
              policyVersion: policy.effectiveVersion,
              current: acc.status,
              threshold: 'ACTIVE',
              severity: RiskSeverity.CRITICAL,
              reason: `Trading account ${accountId} status ${acc.status} not ACTIVE`,
              timestamp: nowIso,
              scope: RiskPolicyScope.TENANT,
              scopeId: accountId,
              isBlocking: true,
              isWarning: false,
            });
          }
        }
      }
    } catch (e) {
      this.logger.warn(`Exchange health check failed: ${(e as Error).message}`);
    }

    // 15. Circuit breaker
    try {
      const scopesToCheck: Array<{ scope: CircuitBreakerScope; id: string }> = [];
      if (symbol) scopesToCheck.push({ scope: CircuitBreakerScope.SYMBOL, id: symbol });
      if (strategyId) scopesToCheck.push({ scope: CircuitBreakerScope.STRATEGY, id: strategyId });
      if (traderId) scopesToCheck.push({ scope: CircuitBreakerScope.TRADER, id: traderId });
      if (accountId) scopesToCheck.push({ scope: CircuitBreakerScope.ACCOUNT, id: accountId });
      scopesToCheck.push({ scope: CircuitBreakerScope.TENANT, id: tenantId });
      if (venue) scopesToCheck.push({ scope: CircuitBreakerScope.VENUE, id: venue });

      for (const s of scopesToCheck) {
        const isBlocked = await this.breakerService.isBlocked({ tenantId, scope: s.scope, scopeId: s.id });
        if (isBlocked) {
          pushDetail({
            dimension: RiskDimension.EXECUTION_HEALTH,
            decision: RiskDecision.BLOCK,
            state: RiskState.BLOCKED,
            ruleId: 'CIRCUIT_BREAKER_OPEN',
            policyVersion: policy.effectiveVersion,
            current: 'OPEN',
            threshold: 'CLOSED',
            severity: RiskSeverity.CRITICAL,
            reason: `Circuit breaker OPEN for ${s.scope} ${s.id}, trading blocked`,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: s.id,
            isBlocking: true,
            isWarning: false,
          });
        }
      }
    } catch (e) {
      this.logger.warn(`Circuit breaker check failed: ${(e as Error).message}`);
    }

    // 16. Kill-switch — BLOCKED/KILL_SWITCH never becomes ALLOW
    try {
      const ksChecks = [];
      if (symbol) ksChecks.push({ scope: 'SYMBOL' as any, target: symbol });
      if (strategyId) ksChecks.push({ scope: 'STRATEGY' as any, target: strategyId });
      if (accountId) ksChecks.push({ scope: 'ACCOUNT' as any, target: accountId });
      ksChecks.push({ scope: 'TENANT' as any, target: tenantId });
      ksChecks.push({ scope: 'GLOBAL' as any, target: null });

      for (const k of ksChecks) {
        const engaged = await this.killSwitchService.isEngaged({ tenantId: k.scope === 'GLOBAL' ? null : tenantId, scope: k.scope, target: k.target ?? undefined });
        if (engaged) {
          pushDetail({
            dimension: RiskDimension.EXECUTION_HEALTH,
            decision: RiskDecision.KILL_SWITCH_REQUIRED,
            state: RiskState.BLOCKED,
            ruleId: 'KILL_SWITCH_ENGAGED',
            policyVersion: policy.effectiveVersion,
            current: 'ENGAGED',
            threshold: 'DISENGAGED',
            severity: RiskSeverity.EMERGENCY,
            reason: `Kill-switch ENGAGED for scope ${k.scope} target ${k.target ?? 'GLOBAL'}, trading must remain blocked`,
            timestamp: nowIso,
            scope: RiskPolicyScope.TENANT,
            scopeId: k.target ?? tenantId,
            isBlocking: true,
            isWarning: false,
          });
        }
      }
    } catch (e) {
      this.logger.warn(`Kill-switch check failed: ${(e as Error).message}`);
    }

    // Finalize decision with explicit priority: BLOCKED/KILL_SWITCH never becomes ALLOW
    let finalDecision = RiskDecision.ALLOW;
    let finalState = RiskState.NORMAL;

    const hasKillSwitch = details.some((d) => d.decision === RiskDecision.KILL_SWITCH_REQUIRED);
    const hasBlock = details.some((d) => d.decision === RiskDecision.BLOCK);
    const hasPause = details.some((d) => d.decision === RiskDecision.PAUSE);
    const hasStopCopy = details.some((d) => d.decision === RiskDecision.STOP_COPY);
    const hasReview = details.some((d) => d.decision === RiskDecision.REVIEW_REQUIRED);
    const hasReduce = details.some((d) => d.decision === RiskDecision.REDUCE);

    if (hasKillSwitch) {
      finalDecision = RiskDecision.KILL_SWITCH_REQUIRED;
      finalState = RiskState.CRITICAL;
    } else if (hasBlock) {
      finalDecision = RiskDecision.BLOCK;
      finalState = RiskState.BLOCKED;
    } else if (hasPause) {
      finalDecision = RiskDecision.PAUSE;
      finalState = RiskState.HIGH;
    } else if (hasStopCopy) {
      finalDecision = RiskDecision.STOP_COPY;
      finalState = RiskState.HIGH;
    } else if (hasReview) {
      finalDecision = RiskDecision.REVIEW_REQUIRED;
      finalState = RiskState.UNKNOWN;
    } else if (hasReduce) {
      finalDecision = RiskDecision.REDUCE;
      finalState = RiskState.ELEVATED;
    }

    // Compliance and security BLOCK always win
    if (details.some((d) => d.dimension === RiskDimension.COMPLIANCE && d.decision === RiskDecision.BLOCK)) {
      finalDecision = RiskDecision.BLOCK;
      finalState = RiskState.BLOCKED;
    }
    if (details.some((d) => d.dimension === RiskDimension.SECURITY && d.decision === RiskDecision.BLOCK)) {
      finalDecision = RiskDecision.BLOCK;
      finalState = RiskState.BLOCKED;
    }

    const ruleIds = Array.from(new Set(details.map((d) => d.ruleId)));

    const decision: UnifiedRiskDecision = {
      id: `risk-dec-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      tenantId,
      userId: userId ?? null,
      accountId: accountId ?? null,
      symbol: symbol ?? null,
      venue: venue ?? null,
      traderId: traderId ?? null,
      followerId: followerId ?? null,
      strategyId: strategyId ?? null,
      orderIntentId: requestId ?? null,
      decision: finalDecision,
      state: finalState,
      blockingReasons,
      warnings,
      details,
      policies: policy.scopeChain.map((s: any) => ({ scope: s.scope, scopeId: s.scopeId, version: s.version.toString(), digest: s.digest })),
      ruleIds,
      policyVersion: policy.effectiveVersion,
      timestamp: nowIso,
      requestId: requestId ?? null,
      environment,
      complianceDecision: details.find((d) => d.dimension === RiskDimension.COMPLIANCE)?.decision ?? null,
      securityDecision: details.find((d) => d.dimension === RiskDimension.SECURITY)?.decision ?? null,
      exchangeHealth: details.find((d) => d.dimension === RiskDimension.EXCHANGE_HEALTH)?.state ?? null,
      circuitBreaker: null,
      killSwitch: hasKillSwitch ? { isEngaged: true, scope: 'DETECTED' } : { isEngaged: false, scope: null },
    };

    // Persist a kill-switch-required decision and its developer event in one
    // tenant-RLS transaction. Other non-stop observations remain audit rows
    // only and do not masquerade as a triggered stop.
    const decisionData = {
      tenantId,
      userId: userId ?? null,
      accountId: accountId ?? null,
      traderId: traderId ?? null,
      followerId: followerId ?? null,
      strategyId: strategyId ?? null,
      symbol: symbol ?? null,
      venue: venue ?? null,
      decision: finalDecision as any,
      state: finalState as any,
      ruleIds,
      policyVersion: policy.effectiveVersion,
      blockingReasons,
      warnings,
      decisionJson: decision as any,
      requestId: requestId ?? null,
    };
    if (finalDecision === RiskDecision.KILL_SWITCH_REQUIRED) {
      await this.prisma.withTenantRls(tenantId, async (tx) => {
        await tx.riskDecisionRecord.create({ data: decisionData });
        await this.outbox.append(tx, {
          tenantId,
          aggregateType: 'risk.decision',
          aggregateId: decision.id,
          eventType: 'risk.stop_triggered',
          idempotencyKey: `risk-stop:${decision.id}`,
          payload: {
            decisionId: decision.id,
            ruleIds,
            policyVersion: policy.effectiveVersion,
            scope: RiskPolicyScope.TENANT,
            scopeId: accountId ?? strategyId ?? tenantId,
            severity: RiskSeverity.CRITICAL,
            triggeredAt: nowIso,
          },
        });
      });
    } else {
      await this.prisma.riskDecisionRecord.create({ data: decisionData });
    }

    // Emit event if blocked
    if (finalDecision === RiskDecision.BLOCK || finalDecision === RiskDecision.KILL_SWITCH_REQUIRED) {
      await this.eventService.emitThresholdBreached({
        tenantId,
        type: RiskEventType.RISK_THRESHOLD_BREACHED,
        ruleId: ruleIds[0] ?? 'RISK_THRESHOLD_BREACHED',
        policyVersion: policy.effectiveVersion,
        scope: RiskPolicyScope.TENANT,
        scopeId: tenantId,
        accountId: accountId ?? null,
        strategyId: strategyId ?? null,
        traderId: traderId ?? null,
        followerId: followerId ?? null,
        symbol: symbol ?? null,
        venue: venue ?? null,
        severity: RiskSeverity.CRITICAL,
        message: `Unified risk decision ${finalDecision} — blocking reasons: ${blockingReasons.join('; ')}`,
        sourceRefs: { decisionId: decision.id, requestId: requestId ?? '' },
        requestId: requestId ?? null,
      });
    }

    return decision;
  }

  private cmpDecimal(a: string, b: string): number {
    const SCALE = 1_000_000_000_000n;
    const parse = (s: string): bigint => {
      const neg = s.startsWith('-');
      const clean = neg ? s.slice(1) : s;
      const [intP = '0', fracP = ''] = clean.split('.');
      const frac = (fracP + '0'.repeat(12)).slice(0, 12);
      const val = BigInt(intP) * SCALE + BigInt(frac || '0');
      return neg ? -val : val;
    };
    const av = parse(a);
    const bv = parse(b);
    if (av < bv) return -1;
    if (av > bv) return 1;
    return 0;
  }

  private mulDecimal(a: string, b: string): string {
    const SCALE = 1_000_000_000_000n;
    const parse = (s: string): bigint => {
      const neg = s.startsWith('-');
      const clean = neg ? s.slice(1) : s;
      const [intP = '0', fracP = ''] = clean.split('.');
      const frac = (fracP + '0'.repeat(12)).slice(0, 12);
      const val = BigInt(intP) * SCALE + BigInt(frac || '0');
      return neg ? -val : val;
    };
    const format = (bb: bigint): string => {
      const neg = bb < 0n;
      const abs = neg ? -bb : bb;
      const intP = abs / SCALE;
      const frac = abs % SCALE;
      const fracStr = frac.toString().padStart(12, '0').replace(/0+$/, '');
      return (neg ? '-' : '') + (fracStr ? `${intP}.${fracStr}` : `${intP}`);
    };
    return format((parse(a) * parse(b)) / SCALE);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { RiskEvent, RiskEventType, RiskSeverity, RiskPolicyScope } from './risk-management.types';

/**
 * Risk event emission for all threshold breaches.
 * Events: RISK_THRESHOLD_BREACHED, EXPOSURE_LIMIT_BREACHED, MARGIN_WARNING, LIQUIDATION_WARNING,
 * LEVERAGE_LIMIT_BREACHED, CONCENTRATION_BREACH, DRAWDOWN_BREACH, DAILY_LOSS_BREACH, CORRELATION_WARNING,
 * VAR_BREACH, STRESS_BREACH, MARKET_DATA_STALE, EXCHANGE_HEALTH_DEGRADED, EXECUTION_FAILURE_BURST,
 * CIRCUIT_BREAKER_TRIGGERED, KILL_SWITCH_REQUESTED.
 *
 * Includes ruleId/policyVersion/tenant/scope/source refs/timestamp, auditable.
 */

@Injectable()
export class RiskEventService {
  private readonly logger = new Logger(RiskEventService.name);

  constructor(private readonly prisma: PrismaService) {}

  async emitEvent(event: RiskEvent): Promise<{ id: string }> {
    // Persist to RiskEvent table (existing) for compatibility plus new audit
    const dedupeKey = `${event.type}:${event.ruleId}:${event.scope}:${event.scopeId ?? ''}:${event.symbol ?? ''}:${event.tenantId}:${event.policyVersion}`.slice(0, 64);

    try {
      const created = await this.prisma.riskEvent.create({
        data: {
          tenantId: event.tenantId,
          accountId: event.accountId ?? undefined,
          strategyId: event.strategyId ?? undefined,
          eventType: this.mapEventType(event.type),
          severity: event.severity as any,
          code: event.ruleId,
          message: event.message.slice(0, 1000),
          limitValue: event.threshold?.slice(0, 64) ?? null,
          observedValue: event.current?.slice(0, 64) ?? null,
          venue: event.venue as any,
          symbol: event.symbol ?? null,
          ruleId: event.ruleId,
          scope: event.scope,
          scopeTarget: event.scopeId ?? null,
          source: event.sourceRefs ? JSON.stringify(event.sourceRefs).slice(0, 64) : 'RISK_MANAGEMENT',
          isSimulated: false,
          dedupeKey,
          metadata: {
            policyVersion: event.policyVersion,
            sourceRefs: event.sourceRefs,
            traderId: event.traderId,
            followerId: event.followerId,
            requestId: event.requestId,
            type: event.type,
          } as any,
        },
      });

      // Also audit log
      await this.prisma.auditLog.create({
        data: {
          tenantId: event.tenantId,
          actorType: 'SYSTEM',
          action: `RISK_EVENT_${event.type}`,
          resourceType: 'RISK_EVENT',
          resourceId: created.id,
          description: `${event.type} ${event.ruleId} ${event.message}`.slice(0, 500),
          metadata: {
            ruleId: event.ruleId,
            policyVersion: event.policyVersion,
            severity: event.severity,
            scope: event.scope,
            scopeId: event.scopeId,
            current: event.current,
            threshold: event.threshold,
            sourceRefs: event.sourceRefs,
          } as any,
        },
      });

      this.logger.log(`Risk event ${event.type} ${event.ruleId} tenant ${event.tenantId} scope ${event.scope} ${event.scopeId ?? ''}`);
      return { id: created.id };
    } catch (e: any) {
      // Dedupe collision: if dedupeKey exists, fetch existing
      if (e.code === 'P2002') {
        const existing = await this.prisma.riskEvent.findFirst({
          where: { tenantId: event.tenantId, dedupeKey },
        });
        if (existing) return { id: existing.id };
      }
      throw e;
    }
  }

  async emitThresholdBreached(params: {
    tenantId: string;
    type: RiskEventType;
    ruleId: string;
    policyVersion: string;
    scope: RiskPolicyScope;
    scopeId?: string | null;
    accountId?: string | null;
    strategyId?: string | null;
    traderId?: string | null;
    followerId?: string | null;
    symbol?: string | null;
    venue?: string | null;
    severity: RiskSeverity;
    message: string;
    current?: string | null;
    threshold?: string | null;
    sourceRefs?: Record<string, string>;
    requestId?: string | null;
  }): Promise<{ id: string }> {
    const event: RiskEvent = {
      id: `evt-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      tenantId: params.tenantId,
      type: params.type,
      ruleId: params.ruleId,
      policyVersion: params.policyVersion,
      scope: params.scope,
      scopeId: params.scopeId ?? null,
      accountId: params.accountId ?? null,
      strategyId: params.strategyId ?? null,
      traderId: params.traderId ?? null,
      followerId: params.followerId ?? null,
      symbol: params.symbol ?? null,
      venue: params.venue ?? null,
      severity: params.severity,
      message: params.message,
      current: params.current ?? null,
      threshold: params.threshold ?? null,
      sourceRefs: params.sourceRefs ?? {},
      timestamp: new Date().toISOString(),
      requestId: params.requestId ?? null,
    };
    return this.emitEvent(event);
  }

  async getEventsByTenant(tenantId: string, limit = 100): Promise<any[]> {
    return this.prisma.riskEvent.findMany({
      where: { tenantId },
      orderBy: { createdAt: 'desc' },
      take: limit,
    });
  }

  private mapEventType(type: RiskEventType): any {
    // Map new event types to existing RiskEventType enum where possible, else fallback to LIMIT_BREACHED
    const mapping: Record<string, string> = {
      RISK_THRESHOLD_BREACHED: 'LIMIT_BREACHED',
      EXPOSURE_LIMIT_BREACHED: 'LIMIT_BREACHED',
      MARGIN_WARNING: 'LIMIT_BREACHED',
      LIQUIDATION_WARNING: 'LIMIT_BREACHED',
      LEVERAGE_LIMIT_BREACHED: 'LIMIT_BREACHED',
      CONCENTRATION_BREACH: 'LIMIT_BREACHED',
      DRAWDOWN_BREACH: 'LIMIT_BREACHED',
      DAILY_LOSS_BREACH: 'DAILY_LOSS_BREACHED',
      CORRELATION_WARNING: 'LIMIT_BREACHED',
      VAR_BREACH: 'LIMIT_BREACHED',
      STRESS_BREACH: 'LIMIT_BREACHED',
      MARKET_DATA_STALE: 'STALE_MARKET_DATA',
      EXCHANGE_HEALTH_DEGRADED: 'RISK_STATE_UNAVAILABLE',
      EXECUTION_FAILURE_BURST: 'ORDER_REJECTED',
      CIRCUIT_BREAKER_TRIGGERED: 'KILL_SWITCH_TRIGGERED',
      KILL_SWITCH_REQUESTED: 'KILL_SWITCH_TRIGGERED',
    };
    return mapping[type] ?? 'LIMIT_BREACHED';
  }
}

import { Injectable, Logger, ForbiddenException, BadRequestException } from '@nestjs/common';
import { createHash } from 'crypto';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { EffectiveRiskPolicy, RiskPolicyScope, RiskPolicyThresholds } from './risk-management.types';

/**
 * Institutional risk policy resolver with precedence:
 * PLATFORM -> TENANT -> TRADER -> STRATEGY -> FOLLOWER
 *
 * Lower scope NEVER weakens mandatory higher-level safety rule.
 * Structured config only — no executable expressions.
 *
 * Reuses existing RiskConfiguration per account as fallback, but authoritative
 * for institutional thresholds is InstitutionalRiskPolicy table plus platform
 * env ceilings.
 *
 * Decimal-safe: thresholds are decimal strings, validated, never floats.
 */

const DECIMAL_PATTERN = /^-?\d+(\.\d+)?$/;
const MAX_POLICY_SIZE_BYTES = 64 * 1024;

function isValidDecimalString(v: string): boolean {
  if (typeof v !== 'string') return false;
  if (v.length > 64) return false;
  if (!DECIMAL_PATTERN.test(v)) return false;
  // No leading zeros abuse except "0.x"
  if (v.startsWith('00')) return false;
  if (v.includes('.') && v.split('.')[1].length > 12) return false;
  return true;
}

function sha256Hex(input: string): string {
  return createHash('sha256').update(input).digest('hex');
}

function canonicalJson(value: unknown): string {
  // Deterministic JSON: sort keys recursively, no whitespace.
  const sort = (x: any): any => {
    if (Array.isArray(x)) return x.map(sort);
    if (x && typeof x === 'object') {
      const out: any = {};
      Object.keys(x).sort().forEach((k) => (out[k] = sort(x[k])));
      return out;
    }
    return x;
  };
  return JSON.stringify(sort(value));
}

function defaultThresholds(): RiskPolicyThresholds {
  return {
    maxGrossExposure: null,
    maxNetExposure: null,
    maxSymbolExposure: null,
    maxVenueExposure: null,
    maxAccountExposure: null,
    maxStrategyExposure: null,
    maxTraderExposure: null,
    maxFollowerExposure: null,
    maxPositionNotional: null,
    maxOrderNotional: null,
    maxOpenOrders: null,
    maxLeverageGross: process.env.RISK_MAX_LEVERAGE_GROSS || '5',
    maxLeverageNet: process.env.RISK_MAX_LEVERAGE_NET || '5',
    maxLeverageSymbol: process.env.RISK_MAX_LEVERAGE_SYMBOL || '5',
    maxLeverageAccount: process.env.RISK_MAX_LEVERAGE_ACCOUNT || '5',
    marginWarningUtilization: '80',
    marginCriticalUtilization: '90',
    liquidationWarningDistance: '10', // %
    liquidationCriticalDistance: '5',
    maxConcentrationAssetPercent: '40',
    maxConcentrationSymbolPercent: '30',
    maxConcentrationVenuePercent: '60',
    maxConcentrationAccountPercent: '50',
    maxConcentrationStrategyPercent: '50',
    maxConcentrationTraderPercent: '50',
    maxConcentrationFollowerPercent: '50',
    maxDrawdownPercent: process.env.RISK_MAX_DRAWDOWN_PCT || '20',
    maxIntradayDrawdownPercent: process.env.RISK_MAX_INTRADAY_DRAWDOWN_PCT || '10',
    maxDailyLoss: process.env.RISK_MAX_DAILY_LOSS || '10000',
    dailyLossIncludesUnrealized: false,
    maxCorrelation: '0.8',
    correlationLookbackDays: 30,
    correlationMinObservations: 30,
    varConfidence: '95',
    varHorizonDays: 1,
    varWindowDays: 90,
    varMinObservations: 30,
    varThreshold: null,
    stressLossThreshold: null,
    marketDataMaxAgeMs: 30_000,
    exchangeHealthMaxAgeMs: 60_000,
    executionFailureBurstThreshold: 10,
    executionFailureWindowMs: 60_000,
    circuitBreakerLossThreshold: null,
    circuitBreakerDrawdownThreshold: null,
    circuitBreakerEnabled: true,
    killSwitchEnabled: true,
    allowRiskReducingOrders: true,
  };
}

function mergeThresholds(base: RiskPolicyThresholds, override: Partial<RiskPolicyThresholds>, isPlatform: boolean): RiskPolicyThresholds {
  const merged = { ...base };
  for (const [k, v] of Object.entries(override)) {
    if (v === null || v === undefined) continue;
    const key = k as keyof RiskPolicyThresholds;
    // Platform defines ceilings; lower scopes may only tighten, never loosen beyond platform ceiling for safety-critical.
    if (!isPlatform) {
      // Safety-critical tightening checks: if base has a limit, override must be <= base for max limits, >= for min distances?
      // For max exposure/leverage/drawdown/loss/concentration: smaller = tighter.
      // For margin utilization, liquidation distance: higher utilization = looser? Actually higher % = tighter warning? We treat same: override must be <= base for max, >= for distance?
      // Simplified: for max* and concentration, override must be <= base if base exists.
      if (typeof v === 'string' && typeof base[key] === 'string') {
        const baseVal = base[key] as string;
        // Skip if not decimal (booleans handled separately)
        if (isValidDecimalString(baseVal) && isValidDecimalString(v as string)) {
          const isMaxLimit = String(key).startsWith('max') || String(key).includes('Concentration') || String(key).includes('Leverage');
          if (isMaxLimit) {
            // override must be <= base (tighter)
            const cmp = compareDecimalStrings(v as string, baseVal);
            if (cmp > 0) {
              // Attempt to weaken higher-level safety rule -> forbidden
              throw new ForbiddenException(
                `Policy scope attempted to weaken higher-level limit ${key}: ${v} > ${baseVal}. Lower scope may only tighten.`,
              );
            }
          }
          // For liquidation distance, larger distance is tighter? Actually larger % means earlier warning, so tighter = larger. We allow larger.
          // For margin utilization, smaller % is tighter warning (earlier). So override <= base is tighter.
          if (String(key).includes('margin') || String(key).includes('Utilization')) {
            const cmp = compareDecimalStrings(v as string, baseVal);
            if (cmp > 0) {
              throw new ForbiddenException(`Policy scope attempted to weaken margin limit ${key}: ${v} > ${baseVal}`);
            }
          }
        }
      }
    }
    (merged as any)[key] = v;
  }
  return merged;
}

function compareDecimalStrings(a: string, b: string): number {
  // Parse as scaled BigInt with 12 decimals for comparison
  const parse = (s: string): bigint => {
    const [intPart, fracPart = ''] = s.replace('-', '').split('.');
    const sign = s.startsWith('-') ? -1n : 1n;
    const fracPadded = (fracPart + '000000000000').slice(0, 12);
    const scaled = BigInt(intPart) * 1_000_000_000_000n + BigInt(fracPadded || '0');
    return sign * scaled;
  };
  const av = parse(a);
  const bv = parse(b);
  if (av < bv) return -1;
  if (av > bv) return 1;
  return 0;
}

function validateThresholds(thresholds: Partial<RiskPolicyThresholds>): void {
  for (const [k, v] of Object.entries(thresholds)) {
    if (v === null || v === undefined) continue;
    if (typeof v === 'string') {
      if (!isValidDecimalString(v)) {
        throw new BadRequestException(`Invalid decimal threshold ${k}: ${v}`);
      }
      // No executable
      if (/[;`$\\{}()<>]/.test(v)) {
        throw new BadRequestException(`Threshold ${k} contains disallowed characters`);
      }
    }
    if (typeof v === 'number') {
      // Only maxOpenOrders and lookback etc allowed as numbers
      if (!Number.isInteger(v) || v < 0) {
        throw new BadRequestException(`Invalid numeric threshold ${k}: ${v}`);
      }
    }
  }
}

@Injectable()
export class InstitutionalRiskPolicyService {
  private readonly logger = new Logger(InstitutionalRiskPolicyService.name);

  constructor(private readonly prisma: PrismaService) {}

  /**
   * Resolve effective policy for a given scope chain.
   * Precedence: PLATFORM -> TENANT -> TRADER -> STRATEGY -> FOLLOWER
   * Lower never weakens higher.
   */
  async resolveEffectivePolicy(params: {
    tenantId?: string | null;
    traderId?: string | null;
    strategyId?: string | null;
    followerId?: string | null;
  }): Promise<EffectiveRiskPolicy> {
    const { tenantId, traderId, strategyId, followerId } = params;
    const chain: Array<{ scope: RiskPolicyScope; scopeId: string | null }> = [
      { scope: RiskPolicyScope.PLATFORM, scopeId: null },
      ...(tenantId ? [{ scope: RiskPolicyScope.TENANT, scopeId: tenantId }] : []),
      ...(traderId ? [{ scope: RiskPolicyScope.TRADER, scopeId: traderId }] : []),
      ...(strategyId ? [{ scope: RiskPolicyScope.STRATEGY, scopeId: strategyId }] : []),
      ...(followerId ? [{ scope: RiskPolicyScope.FOLLOWER, scopeId: followerId }] : []),
    ];

    // Fetch policies from DB: InstitutionalRiskPolicy where active, ordered by scope precedence
    const dbPolicies = await this.prisma.institutionalRiskPolicy.findMany({
      where: {
        isActive: true,
        OR: chain.map((c) => ({
          scope: c.scope as any,
          ...(c.scopeId ? { scopeId: c.scopeId } : c.scope === RiskPolicyScope.PLATFORM ? { tenantId: null } : {}),
          ...(c.scope === RiskPolicyScope.TENANT && tenantId ? { tenantId } : {}),
        })),
      },
      orderBy: [{ scope: 'asc' }, { version: 'desc' }],
    });

    // Build map latest per scope
    const latestByScope = new Map<string, (typeof dbPolicies)[number]>();
    for (const p of dbPolicies) {
      const key = `${p.scope}:${p.scopeId ?? ''}`;
      if (!latestByScope.has(key)) latestByScope.set(key, p);
    }

    let effective = defaultThresholds();
    const sourcePolicies: EffectiveRiskPolicy['sourcePolicies'] = [];
    const scopeChain: EffectiveRiskPolicy['scopeChain'] = [];

    // Platform defaults first (from env + defaultThresholds)
    const platformDigest = sha256Hex(canonicalJson(defaultThresholds()));
    scopeChain.push({ scope: RiskPolicyScope.PLATFORM, scopeId: null, version: 0, digest: platformDigest });

    // Apply in precedence order
    for (const step of chain) {
      const key = `${step.scope}:${step.scopeId ?? ''}`;
      const dbPol = latestByScope.get(key);
      if (!dbPol) continue;
      const policyJson = dbPol.policyJson as Partial<RiskPolicyThresholds>;
      validateThresholds(policyJson);
      const jsonStr = canonicalJson(policyJson);
      if (Buffer.byteLength(jsonStr, 'utf8') > MAX_POLICY_SIZE_BYTES) {
        throw new BadRequestException(`Policy too large for scope ${step.scope}`);
      }
      // Check no executable
      if (/__proto__|constructor|process|require|eval/.test(jsonStr)) {
        throw new BadRequestException(`Policy contains disallowed pattern for scope ${step.scope}`);
      }
      const isPlatform = step.scope === RiskPolicyScope.PLATFORM;
      effective = mergeThresholds(effective, policyJson, isPlatform);
      scopeChain.push({ scope: step.scope, scopeId: step.scopeId, version: dbPol.version, digest: dbPol.digest });
      sourcePolicies.push({
        scope: step.scope,
        scopeId: step.scopeId,
        version: dbPol.version,
        digest: dbPol.digest,
        thresholds: policyJson,
      });
    }

    // Also incorporate existing RiskConfiguration per account if tenantId provided? For institutional we keep separate but note.
    const effectiveDigest = sha256Hex(canonicalJson(effective));
    const effectiveVersion = sha256Hex(scopeChain.map((s) => `${s.scope}:${s.scopeId}:${s.version}:${s.digest}`).join('|')).slice(0, 16);

    const ruleIds = Array.from(
      new Set([
        'MAX_GROSS_EXPOSURE',
        'MAX_NET_EXPOSURE',
        'MAX_SYMBOL_EXPOSURE',
        'MAX_VENUE_EXPOSURE',
        'MAX_ACCOUNT_EXPOSURE',
        'MAX_STRATEGY_EXPOSURE',
        'MAX_TRADER_EXPOSURE',
        'MAX_FOLLOWER_EXPOSURE',
        'MAX_POSITION_NOTIONAL',
        'MAX_ORDER_NOTIONAL',
        'MAX_OPEN_ORDERS',
        'MAX_LEVERAGE_GROSS',
        'MAX_LEVERAGE_NET',
        'MARGIN_UTILIZATION',
        'LIQUIDATION_DISTANCE',
        'MAX_CONCENTRATION_ASSET',
        'MAX_CONCENTRATION_SYMBOL',
        'MAX_CONCENTRATION_VENUE',
        'MAX_DRAWDOWN',
        'MAX_INTRADAY_DRAWDOWN',
        'DAILY_LOSS_LIMIT',
        'MAX_CORRELATION',
        'VAR_LIMIT',
        'STRESS_LOSS_LIMIT',
        'MARKET_DATA_STALE',
        'EXCHANGE_HEALTH_DEGRADED',
        'EXECUTION_FAILURE_BURST',
        'CIRCUIT_BREAKER_LOSS',
        'COMPLIANCE_BLOCK',
        'SECURITY_BLOCK',
      ]),
    );

    return {
      tenantId: tenantId ?? null,
      scopeChain,
      effectiveVersion,
      effectiveDigest,
      thresholds: effective,
      ruleIds,
      precedence: [RiskPolicyScope.PLATFORM, RiskPolicyScope.TENANT, RiskPolicyScope.TRADER, RiskPolicyScope.STRATEGY, RiskPolicyScope.FOLLOWER],
      resolvedAt: new Date().toISOString(),
      sourcePolicies,
    };
  }

  async upsertPolicy(params: {
    scope: RiskPolicyScope;
    scopeId?: string | null;
    tenantId?: string | null;
    thresholds: Partial<RiskPolicyThresholds>;
    changeReason: string;
    changedByUserId: string;
    actorTenantId?: string;
  }): Promise<{ id: string; version: number; digest: string }> {
    const { scope, scopeId, tenantId, thresholds, changeReason, changedByUserId } = params;
    if (!changeReason || changeReason.trim().length < 10) {
      throw new BadRequestException('changeReason must be at least 10 characters');
    }
    validateThresholds(thresholds);
    const canonical = canonicalJson(thresholds);
    if (Buffer.byteLength(canonical, 'utf8') > MAX_POLICY_SIZE_BYTES) {
      throw new BadRequestException('Policy payload too large');
    }
    if (/__proto__|constructor|process|require|eval/.test(canonical)) {
      throw new BadRequestException('Policy contains disallowed executable pattern');
    }
    const digest = sha256Hex(canonical);

    // Platform scope requires PLATFORM_MANAGE (checked in controller) and tenantId must be null
    if (scope === RiskPolicyScope.PLATFORM && tenantId) {
      throw new BadRequestException('PLATFORM scope must have null tenantId');
    }

    // Fetch existing latest version for this scope
    const existing = await this.prisma.institutionalRiskPolicy.findFirst({
      where: { scope: scope as any, scopeId: scopeId ?? null, tenantId: tenantId ?? undefined },
      orderBy: { version: 'desc' },
    });

    // If existing, ensure not weakening higher-level (will be checked on resolve, but also here for immediate feedback)
    if (existing) {
      // If this is not platform, fetch platform policy to ensure not weakening
      if (scope !== RiskPolicyScope.PLATFORM) {
        const platformPolicy = await this.resolveEffectivePolicy({ tenantId: tenantId ?? null });
        // merge check will throw if weakening
        mergeThresholds(platformPolicy.thresholds, thresholds, false);
      }
    }

    const nextVersion = (existing?.version ?? 0) + 1;

    const created = await this.prisma.institutionalRiskPolicy.create({
      data: {
        scope: scope as any,
        scopeId: scopeId ?? null,
        tenantId: tenantId ?? null,
        version: nextVersion,
        digest,
        policyJson: thresholds as any,
        ruleIds: Object.keys(thresholds).map((k) => k.toUpperCase()),
        changeReason,
        changedByUserId,
        isActive: true,
      },
    });

    // Deactivate older versions for same scope (keep history but mark inactive)
    if (existing) {
      await this.prisma.institutionalRiskPolicy.updateMany({
        where: { scope: scope as any, scopeId: scopeId ?? null, tenantId: tenantId ?? undefined, id: { not: created.id } },
        data: { isActive: false },
      });
      // Reactivate the newly created one (in case updateMany deactivated it)
      await this.prisma.institutionalRiskPolicy.update({ where: { id: created.id }, data: { isActive: true } });
    }

    // Audit log
    await this.prisma.auditLog.create({
      data: {
        tenantId: tenantId ?? undefined,
        actorId: changedByUserId,
        actorType: 'USER',
        action: 'RISK_POLICY_UPSERT',
        resourceType: 'INSTITUTIONAL_RISK_POLICY',
        resourceId: created.id,
        description: `Upsert ${scope} ${scopeId ?? ''} v${nextVersion} digest ${digest}`,
        changes: { before: existing?.policyJson ?? null, after: thresholds } as any,
      },
    });

    this.logger.log(`Risk policy upsert ${scope} ${scopeId ?? ''} v${nextVersion} digest ${digest}`);
    return { id: created.id, version: nextVersion, digest };
  }

  async getPolicyHistory(params: { scope: RiskPolicyScope; scopeId?: string | null; tenantId?: string | null }): Promise<any[]> {
    return this.prisma.institutionalRiskPolicy.findMany({
      where: { scope: params.scope as any, scopeId: params.scopeId ?? undefined, tenantId: params.tenantId ?? undefined },
      orderBy: { version: 'desc' },
      take: 50,
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { InstitutionalRiskPolicyService } from './risk-policy.service';
import { PortfolioExposureService } from './portfolio-exposure.service';

/**
 * Risk reconciliation: Positions ↔ Orders ↔ Balances ↔ PnL ↔ Snapshot ↔ Breaker ↔ KillSwitch
 * Detects drift/mismatch/stale/missing/position without exposure/impossible leverage/negative margin/breaker mismatch/kill-switch inconsistency/compliance mismatch.
 * Deterministic categories, no silent rewrite.
 * Reports findings, never auto-corrects financial ledger.
 */

function isValidDecimal(v: any): boolean {
  return typeof v === 'string' && /^-?\d+(\.\d+)?$/.test(v);
}
const SCALE = 1_000_000_000_000n;
function parseScaled(s: string): bigint {
  const neg = s.startsWith('-');
  const clean = neg ? s.slice(1) : s;
  const [intP = '0', fracP = ''] = clean.split('.');
  const frac = (fracP + '0'.repeat(12)).slice(0, 12);
  const val = BigInt(intP) * SCALE + BigInt(frac || '0');
  return neg ? -val : val;
}
function formatScaled(b: bigint): string {
  const neg = b < 0n;
  const abs = neg ? -b : b;
  const intP = abs / SCALE;
  const frac = abs % SCALE;
  const fracStr = frac.toString().padStart(12, '0').replace(/0+$/, '');
  return (neg ? '-' : '') + (fracStr ? `${intP}.${fracStr}` : `${intP}`);
}

@Injectable()
export class RiskReconciliationService {
  private readonly logger = new Logger(RiskReconciliationService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: InstitutionalRiskPolicyService,
    private readonly exposureService: PortfolioExposureService,
  ) {}

  async reconcile(params: { tenantId: string; accountId?: string }): Promise<{
    findings: Array<{ category: string; severity: string; summary: string; expected: any; actual: any }>;
    totalFindings: number;
    timestamp: string;
  }> {
    const { tenantId, accountId } = params;
    const policy = await this.policyService.resolveEffectivePolicy({ tenantId });
    const nowIso = new Date().toISOString();

    const positions = await this.prisma.position.findMany({
      where: { tenantId, ...(accountId ? { accountId } : {}) },
    });
    const orders = await this.prisma.order.findMany({
      where: { tenantId, ...(accountId ? { accountId } : {}) },
    });
    const balances = await this.prisma.accountBalanceSnapshot.findMany({
      where: { tenantId, ...(accountId ? { accountId } : {}) },
    });
    const snapshots = await this.prisma.riskManagementSnapshot.findMany({
      where: { tenantId, ...(accountId ? { accountId } : {}) },
      orderBy: { capturedAt: 'desc' },
      take: 5,
    });
    const breakers = await this.prisma.circuitBreakerRecord.findMany({
      where: { tenantId, state: 'OPEN' as any },
    });
    const killSwitches = await this.prisma.killSwitch.findMany({
      where: { tenantId, isEngaged: true },
    });

    const findings: Array<{ category: string; severity: string; summary: string; expected: any; actual: any }> = [];

    // 1. Position without exposure: position exists but exposure service reports zero for that symbol?
    try {
      const exposure = await this.exposureService.calculateExposure({ tenantId, accountId });
      const exposureSymbols = new Set(exposure.symbolExposures.map((s) => s.symbol));
      for (const pos of positions) {
        const qtyStr = pos.quantity.toString();
        if (!isValidDecimal(qtyStr) || parseScaled(qtyStr) === 0n) continue;
        if (!exposureSymbols.has(pos.symbol)) {
          findings.push({
            category: 'POSITION_WITHOUT_EXPOSURE',
            severity: 'MEDIUM',
            summary: `Position ${pos.symbol} qty ${qtyStr} exists but no exposure reported for account ${pos.accountId}`,
            expected: { symbol: pos.symbol, shouldHaveExposure: true },
            actual: { symbol: pos.symbol, exposureFound: false, quantity: qtyStr },
          });
        }
      }
    } catch (e) {
      findings.push({
        category: 'EXPOSURE_WITHOUT_POSITION',
        severity: 'LOW',
        summary: `Exposure calculation failed during reconciliation: ${(e as Error).message}`,
        expected: { exposureCalculable: true },
        actual: { error: (e as Error).message },
      });
    }

    // 2. Order exposure mismatch: open orders notional vs exposure openOrderNotional
    const openOrders = orders.filter((o) => ['PENDING', 'SUBMITTED', 'ACKNOWLEDGED', 'PARTIALLY_FILLED'].includes(o.status as string));
    // We don't have exact expected, but we can flag if open order count differs from exposure openOrderExposure?
    // Simplified: if open orders exist but exposure openOrderExposure is zero, flag.

    // 3. Balance mismatch: wallet total vs sum of free+locked?
    for (const b of balances) {
      const freeStr = b.free.toString();
      const lockedStr = b.locked.toString();
      const totalStr = b.total.toString();
      if (isValidDecimal(freeStr) && isValidDecimal(lockedStr) && isValidDecimal(totalStr)) {
        const free = parseScaled(freeStr);
        const locked = parseScaled(lockedStr);
        const total = parseScaled(totalStr);
        if (free + locked !== total) {
          findings.push({
            category: 'BALANCE_MISMATCH',
            severity: 'HIGH',
            summary: `Balance mismatch for ${b.asset} account ${b.accountId}: free ${freeStr} + locked ${lockedStr} != total ${totalStr}`,
            expected: { freePlusLocked: formatScaled(free + locked) },
            actual: { total: totalStr, free: freeStr, locked: lockedStr },
          });
        }
      }
    }

    // 4. PnL drift: realized PnL vs fills? For now check if unrealized is null when mark price exists?
    for (const pos of positions) {
      if (pos.markPrice && !pos.unrealisedPnl) {
        findings.push({
          category: 'PNL_DRIFT',
          severity: 'LOW',
          summary: `Position ${pos.symbol} has mark price ${pos.markPrice} but no unrealized PnL`,
          expected: { unrealizedShouldExist: true },
          actual: { markPrice: pos.markPrice.toString(), unrealizedPnl: null },
        });
      }
    }

    // 5. Snapshot stale
    if (snapshots.length > 0) {
      const latest = snapshots[0];
      const ageMs = Date.now() - new Date(latest.capturedAt).getTime();
      if (ageMs > policy.thresholds.marketDataMaxAgeMs * 10) {
        findings.push({
          category: 'SNAPSHOT_STALE',
          severity: 'MEDIUM',
          summary: `Latest risk snapshot ${latest.id} stale: age ${ageMs}ms > ${policy.thresholds.marketDataMaxAgeMs * 10}ms`,
          expected: { maxAgeMs: policy.thresholds.marketDataMaxAgeMs * 10 },
          actual: { snapshotId: latest.id, ageMs, capturedAt: latest.capturedAt.toISOString() },
        });
      }
    } else {
      findings.push({
        category: 'MISSING_SOURCE',
        severity: 'LOW',
        summary: `No risk snapshots found for tenant ${tenantId} account ${accountId ?? 'all'}`,
        expected: { snapshotExists: true },
        actual: { count: 0 },
      });
    }

    // 6. Breaker mismatch: if breaker OPEN but no corresponding risk event?
    for (const br of breakers as any[]) {
      const event = await this.prisma.riskEvent.findFirst({
        where: { tenantId, ruleId: br.triggerRuleId ?? undefined, createdAt: { gte: new Date(Date.now() - 24 * 60 * 60 * 1000) } },
      });
      if (!event) {
        findings.push({
          category: 'BREAKER_MISMATCH',
          severity: 'MEDIUM',
          summary: `Circuit breaker OPEN for ${br.scope} ${br.scopeId} but no recent risk event for rule ${br.triggerRuleId ?? 'unknown'}`,
          expected: { riskEventExists: true },
          actual: { breakerId: br.id, scope: br.scope, scopeId: br.scopeId, triggerRuleId: br.triggerRuleId },
        });
      }
    }

    // 7. Kill-switch inconsistency: if kill-switch engaged but breaker not?
    for (const ks of killSwitches as any[]) {
      // For account-level kill-switch, expect breaker OPEN for same account?
      if (ks.scope === 'ACCOUNT' && ks.target) {
        const breaker = (breakers as any[]).find((b: any) => b.scope === 'ACCOUNT' && b.scopeId === ks.target);
        if (!breaker) {
          findings.push({
            category: 'KILL_SWITCH_INCONSISTENCY',
            severity: 'MEDIUM',
            summary: `Kill-switch engaged for ACCOUNT ${ks.target} but no circuit breaker OPEN for same account`,
            expected: { breakerOpen: true },
            actual: { killSwitchId: ks.id, scope: ks.scope, target: ks.target },
          });
        }
      }
    }

    // 8. Impossible leverage: gross leverage <0 or >1000?
    // We need to compute leverage from positions+balances
    let walletTotal = 0n;
    for (const b of balances) {
      const totalStr = b.total.toString();
      if (isValidDecimal(totalStr)) walletTotal += parseScaled(totalStr);
    }
    if (walletTotal > 0n) {
      let grossNotional = 0n;
      for (const pos of positions) {
        const qtyStr = pos.quantity.toString();
        const markPrice = pos.markPrice?.toString() ?? pos.averageEntryPrice?.toString() ?? null;
        if (isValidDecimal(qtyStr) && markPrice && isValidDecimal(markPrice)) {
          const absQty = qtyStr.startsWith('-') ? qtyStr.slice(1) : qtyStr;
          const notionalStr = formatScaled((parseScaled(absQty) * parseScaled(markPrice)) / SCALE);
          if (isValidDecimal(notionalStr)) grossNotional += parseScaled(notionalStr);
        }
      }
      if (grossNotional > 0n) {
        const leverage = (grossNotional * SCALE) / walletTotal;
        const leverageNum = Number(leverage) / Number(SCALE);
        if (leverageNum > 1000) {
          findings.push({
            category: 'IMPOSSIBLE_LEVERAGE',
            severity: 'CRITICAL',
            summary: `Impossible leverage ${leverageNum.toFixed(2)}x for tenant ${tenantId} account ${accountId ?? 'all'}: gross ${formatScaled(grossNotional)} / wallet ${formatScaled(walletTotal)}`,
            expected: { maxLeverage: 100 },
            actual: { leverage: leverageNum, grossNotional: formatScaled(grossNotional), walletTotal: formatScaled(walletTotal) },
          });
        }
      }
    }

    // 9. Negative margin: wallet total negative?
    if (walletTotal < 0n) {
      findings.push({
        category: 'NEGATIVE_MARGIN',
        severity: 'CRITICAL',
        summary: `Negative wallet total ${formatScaled(walletTotal)} for tenant ${tenantId} account ${accountId ?? 'all'}`,
        expected: { walletNonNegative: true },
        actual: { walletTotal: formatScaled(walletTotal) },
      });
    }

    // 10. Stale market data
    for (const pos of positions) {
      const ageMs = Date.now() - new Date(pos.updatedAt).getTime();
      if (ageMs > policy.thresholds.marketDataMaxAgeMs * 5) {
        findings.push({
          category: 'STALE_MARKET_DATA',
          severity: 'MEDIUM',
          summary: `Position ${pos.symbol} stale: age ${ageMs}ms > ${policy.thresholds.marketDataMaxAgeMs * 5}ms`,
          expected: { maxAgeMs: policy.thresholds.marketDataMaxAgeMs * 5 },
          actual: { symbol: pos.symbol, ageMs, updatedAt: pos.updatedAt.toISOString() },
        });
      }
    }

    // Persist findings
    for (const f of findings) {
      await this.prisma.riskReconciliationRecord.create({
        data: {
          tenantId,
          accountId: accountId ?? null,
          category: f.category as any,
          severity: f.severity,
          expected: f.expected as any,
          actual: f.actual as any,
          summary: f.summary.slice(0, 1000),
          policyVersion: policy.effectiveVersion,
        },
      });
    }

    this.logger.log(`Risk reconciliation for tenant ${tenantId} account ${accountId ?? 'all'}: ${findings.length} findings`);
    return { findings, totalFindings: findings.length, timestamp: nowIso };
  }

  async getReconciliationHistory(tenantId: string, limit = 50): Promise<any[]> {
    return this.prisma.riskReconciliationRecord.findMany({
      where: { tenantId },
      orderBy: { createdAt: 'desc' },
      take: limit,
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { RiskSnapshot, RiskState } from './risk-management.types';

/**
 * Risk snapshot repository: immutable/append-only, tenant/user/trader/follower/account scope,
 * timestamp/policy version/exposure/margin/leverage/drawdown/concentration/state/metric values/source timestamps.
 * Prevents duplicate snapshot events where same calculation repeated.
 * Tenant isolation enforced.
 */

@Injectable()
export class RiskManagementSnapshotRepository {
  private readonly logger = new Logger(RiskManagementSnapshotRepository.name);

  constructor(private readonly prisma: PrismaService) {}

  async saveSnapshot(snapshot: RiskSnapshot): Promise<{ id: string }> {
    // Dedupe: if same tenant/account/policyVersion/timestamp/metric hash exists, skip
    const existing = await this.prisma.riskManagementSnapshot.findFirst({
      where: {
        tenantId: snapshot.tenantId,
        accountId: snapshot.accountId ?? undefined,
        policyVersion: snapshot.policyVersion,
        capturedAt: { gte: new Date(new Date(snapshot.timestamp).getTime() - 1000), lte: new Date(new Date(snapshot.timestamp).getTime() + 1000) },
      },
    });

    if (existing) {
      // Check if metric values identical (prevent duplicate)
      const existingMetrics = JSON.stringify(existing.exposureJson ?? {});
      const newMetrics = JSON.stringify(snapshot.exposure ?? {});
      if (existingMetrics === newMetrics && existing.policyVersion === snapshot.policyVersion) {
        this.logger.log(`Duplicate snapshot detected for tenant ${snapshot.tenantId} account ${snapshot.accountId} policy ${snapshot.policyVersion}, skipping`);
        return { id: existing.id };
      }
    }

    const created = await this.prisma.riskManagementSnapshot.create({
      data: {
        tenantId: snapshot.tenantId,
        userId: snapshot.userId ?? null,
        traderId: snapshot.traderId ?? null,
        followerId: snapshot.followerId ?? null,
        accountId: snapshot.accountId ?? null,
        strategyId: snapshot.strategyId ?? null,
        policyVersion: snapshot.policyVersion,
        policyDigest: snapshot.policyDigest ?? null,
        state: snapshot.state as any,
        grossExposure: snapshot.exposure?.grossExposure ?? null,
        netExposure: snapshot.exposure?.netExposure ?? null,
        longExposure: snapshot.exposure?.longExposure ?? null,
        shortExposure: snapshot.exposure?.shortExposure ?? null,
        marginUtilization: snapshot.margin?.[0]?.marginUtilizationPercent ?? null,
        leverageGross: snapshot.leverage?.[0]?.grossLeverage ?? null,
        leverageNet: snapshot.leverage?.[0]?.netLeverage ?? null,
        drawdownAbs: snapshot.drawdown?.[0]?.drawdownAbs ?? null,
        drawdownPercent: snapshot.drawdown?.[0]?.drawdownPercent ?? null,
        dailyPnl: snapshot.dailyLoss?.[0]?.dailyPnl ?? null,
        dailyLossBudget: snapshot.dailyLoss?.[0]?.remainingBudget ?? null,
        concentrationJson: snapshot.concentration as any,
        exposureJson: snapshot.exposure as any,
        marginJson: snapshot.margin as any,
        leverageJson: snapshot.leverage as any,
        liquidationJson: snapshot.liquidation as any,
        correlationJson: snapshot.correlation as any,
        varJson: snapshot.var as any,
        stressJson: snapshot.stress as any,
        sourceTimestamps: snapshot.sourceTimestamps as any,
        capturedAt: new Date(snapshot.timestamp),
      },
    });

    return { id: created.id };
  }

  async getLatestSnapshot(params: { tenantId: string; accountId?: string; traderId?: string; followerId?: string; strategyId?: string }): Promise<RiskSnapshot | null> {
    const { tenantId, accountId, traderId, followerId, strategyId } = params;
    const row = await this.prisma.riskManagementSnapshot.findFirst({
      where: {
        tenantId,
        accountId: accountId ?? undefined,
        traderId: traderId ?? undefined,
        followerId: followerId ?? undefined,
        strategyId: strategyId ?? undefined,
      },
      orderBy: { capturedAt: 'desc' },
    });
    if (!row) return null;

    return {
      id: row.id,
      tenantId: row.tenantId,
      userId: row.userId ?? null,
      traderId: row.traderId ?? null,
      followerId: row.followerId ?? null,
      accountId: row.accountId ?? null,
      strategyId: row.strategyId ?? null,
      timestamp: row.capturedAt.toISOString(),
      policyVersion: row.policyVersion,
      policyDigest: row.policyDigest ?? null,
      state: row.state as RiskState,
      exposure: row.exposureJson as any,
      margin: (row.marginJson as any) ?? [],
      leverage: (row.leverageJson as any) ?? [],
      drawdown: [],
      concentration: (row.concentrationJson as any) ?? [],
      liquidation: (row.liquidationJson as any) ?? [],
      dailyLoss: [],
      var: (row.varJson as any) ?? [],
      stress: (row.stressJson as any) ?? [],
      correlation: (row.correlationJson as any) ?? [],
      circuitBreakers: [],
      killSwitch: null,
      metricValues: {},
      sourceTimestamps: (row.sourceTimestamps as any) ?? {},
    };
  }

  async getSnapshotsByTenant(tenantId: string, limit = 50): Promise<any[]> {
    return this.prisma.riskManagementSnapshot.findMany({
      where: { tenantId },
      orderBy: { capturedAt: 'desc' },
      take: limit,
    });
  }

  // High-water mark persistence for drawdown (separate from snapshot, but stored via snapshots table + TenantSetting fallback)

  async getHighWaterMark(params: { tenantId: string; scope: string; scopeId: string }): Promise<{ highWaterMark: string; timestamp: string } | null> {
    const { tenantId, scope, scopeId } = params;
    // Use TenantSetting with key hwm:<scope>:<scopeId> for quick lookup, plus snapshot history
    const key = `risk_hwm:${scope}:${scopeId}`;
    const setting = await this.prisma.tenantSetting.findFirst({
      where: { tenantId, key },
    });
    if (setting?.value && typeof setting.value === 'object') {
      const val = setting.value as any;
      if (val.highWaterMark && val.timestamp) {
        return { highWaterMark: val.highWaterMark, timestamp: val.timestamp };
      }
    }
    // Fallback: latest snapshot drawdown
    const latest = await this.prisma.riskManagementSnapshot.findFirst({
      where: { tenantId, ...(scope === 'TRADER' ? { traderId: scopeId } : scope === 'STRATEGY' ? { strategyId: scopeId } : scope === 'FOLLOWER' ? { followerId: scopeId } : { accountId: scopeId }) },
      orderBy: { capturedAt: 'desc' },
    });
    if (latest?.drawdownAbs) {
      // Not HWM, but we can approximate? Actually drawdown contains HWM? We stored drawdownAbs/percent but not HWM. So we need to search snapshot with HWM in exposureJson?
      // For now return null if not in TenantSetting.
    }
    return null;
  }

  async persistHighWaterMark(params: {
    tenantId: string;
    scope: string;
    scopeId: string;
    highWaterMark: string;
    timestamp: string;
    policyVersion: string;
  }): Promise<void> {
    const { tenantId, scope, scopeId, highWaterMark, timestamp, policyVersion } = params;
    const key = `risk_hwm:${scope}:${scopeId}`;
    await this.prisma.tenantSetting.upsert({
      where: { tenantId_key: { tenantId, key } },
      create: {
        tenantId,
        key,
        value: { highWaterMark, timestamp, policyVersion, scope, scopeId } as any,
        category: 'risk',
        description: `High-water mark for ${scope} ${scopeId}`,
      },
      update: {
        value: { highWaterMark, timestamp, policyVersion, scope, scopeId } as any,
        updatedAt: new Date(),
      },
    });
  }
}

import { Controller, Get, Post, Body, Param, Query, Req, ForbiddenException, BadRequestException, NotFoundException } from '@nestjs/common';
import { Permission } from '@wlct/shared-types';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { RequireAnyPermission, RequirePermissions } from '../../common/decorators/permissions.decorator';
import { RiskDecisionService } from './risk-decision.service';
import { InstitutionalRiskPolicyService } from './risk-policy.service';
import { PortfolioExposureService } from './portfolio-exposure.service';
import { PositionRiskService } from './position-risk.service';
import { MarginRiskService } from './margin-risk.service';
import { LeverageRiskService } from './leverage-risk.service';
import { LeveragePolicyService } from '../risk/leverage-policy.service';
import { LiquidationRiskService } from './liquidation-risk.service';
import { ConcentrationRiskService } from './concentration-risk.service';
import { DrawdownRiskService } from './drawdown-risk.service';
import { DailyLossLimitService } from './daily-loss-limit.service';
import { CorrelationRiskService } from './correlation-risk.service';
import { VarRiskService } from './var-risk.service';
import { StressTestService } from './stress-test.service';
import { RiskManagementSnapshotRepository } from './risk-snapshot.repository';
import { CircuitBreakerService } from './circuit-breaker.service';
import { KillSwitchOrchestratorService, KillSwitchRequestScope } from './kill-switch-orchestrator.service';
import { RiskReconciliationService } from './risk-reconciliation.service';
import { CustomerExposureService } from './customer-exposure.service';
import type { CustomerRiskAnalysisView } from './customer-risk-analysis.types';
import { RiskCheckDto } from './dto/risk-check.dto';
import { UpsertRiskPolicyDto, RiskPolicyScopeDto } from './dto/risk-policy.dto';
import { RiskPolicyScope, CircuitBreakerScope } from './risk-management.types';
import { authTenantId, authUserIdOrNull, principal } from '../../common/guards/request-principal';

/**
 * Institutional risk controller with RBAC:
 * - dashboard/pre-trade check/account/trader/strategy/follower risk/policy/breaker status/actions/kill-switch/reconciliation
 * - tenant risk admins own tenant, trader/follower own scope, platform risk admins PLATFORM_MANAGE, no cross-tenant
 * - No secrets in responses
 */

/**
 * Risk-management console (unified pre-trade check, exposure, margin, VaR,
 * policies, circuit breakers, kill switches, reconciliation).
 *
 * The controller carried no permission metadata, so any tenant user, a
 * follower included, could rewrite the tenant's risk policy or trigger and
 * clear circuit breakers and kill switches. Permissions now mirror the
 * decorated risk controller (/risk): reads risk:read, policy changes
 * risk:config:update (class default), trigger/request/acknowledge
 * risk:kill_switch_update, clear risk:protection_clear. The pre-trade check
 * needs execution:submit or risk:config:update.
 */
@RequirePermissions(Permission.RISK_CONFIG_UPDATE)
@Controller('risk-management')
export class RiskManagementController {
  constructor(
    private readonly prisma: PrismaService,
    private readonly decisionService: RiskDecisionService,
    private readonly policyService: InstitutionalRiskPolicyService,
    private readonly exposureService: PortfolioExposureService,
    private readonly positionService: PositionRiskService,
    private readonly marginService: MarginRiskService,
    private readonly leverageService: LeverageRiskService,
    private readonly leveragePolicyService: LeveragePolicyService,
    private readonly liquidationService: LiquidationRiskService,
    private readonly concentrationService: ConcentrationRiskService,
    private readonly drawdownService: DrawdownRiskService,
    private readonly dailyLossService: DailyLossLimitService,
    private readonly correlationService: CorrelationRiskService,
    private readonly varService: VarRiskService,
    private readonly stressService: StressTestService,
    private readonly snapshotRepo: RiskManagementSnapshotRepository,
    private readonly breakerService: CircuitBreakerService,
    private readonly killSwitchService: KillSwitchOrchestratorService,
    private readonly reconciliationService: RiskReconciliationService,
    // Customer-facing exposure: owner-scoped and non-sandbox-correct, unlike the institutional
    // PortfolioExposureService above, which answers for an operator-selected account. Both are
    // real routes; neither replaces the other.
    private readonly customerExposureService: CustomerExposureService,
  ) {}

  private getTenantId(req: any): string {
    // Token tenant only; a header can never select the tenant.
    return authTenantId(req);
  }

  private getUserId(req: any): string {
    return authUserIdOrNull(req) ?? 'system';
  }

  private checkTenantAccess(req: any, targetTenantId: string): void {
    const userTenantId = req.user?.tenantId;
    const isPlatform = req.user?.isPlatformUser || req.user?.roles?.includes('PLATFORM_ADMIN') || req.user?.permissions?.includes('PLATFORM_MANAGE');
    if (!isPlatform && userTenantId && userTenantId !== targetTenantId) {
      throw new ForbiddenException('Cross-tenant access denied');
    }
  }

  // ---------- Dashboard ----------

  @Get('dashboard')
  @RequirePermissions(Permission.RISK_READ)
  async getDashboard(@Req() req: any, @Query('accountId') accountId?: string, @Query('traderId') traderId?: string, @Query('strategyId') strategyId?: string, @Query('followerId') followerId?: string) {
    const tenantId = this.getTenantId(req);
    const exposure = await this.exposureService.calculateExposure({ tenantId, accountId, traderId, strategyId, followerId });
    const policy = await this.policyService.resolveEffectivePolicy({ tenantId, traderId: traderId ?? null, strategyId: strategyId ?? null, followerId: followerId ?? null });

    let margin = null;
    let leverage = null;
    let drawdown = null;
    let dailyLoss = null;
    if (accountId) {
      const margins = await this.marginService.evaluateMargin({ tenantId, accountId });
      margin = margins[0] ?? null;
      const levs = await this.leverageService.evaluateLeverage({ tenantId, accountId });
      leverage = levs[0] ?? null;
    }
    const drawdowns = await this.drawdownService.evaluateDrawdown({ tenantId, accountId, traderId, strategyId, followerId });
    drawdown = drawdowns[0] ?? null;
    const dailyLosses = await this.dailyLossService.evaluateDailyLoss({ tenantId, accountId, traderId, strategyId, followerId });
    dailyLoss = dailyLosses[0] ?? null;

    const concentrations = await this.concentrationService.evaluateConcentration({ tenantId, accountId, traderId, strategyId, followerId });
    const liquidations = await this.liquidationService.evaluateLiquidationRisk({ tenantId, accountId, traderId, strategyId, followerId });
    const vars = await this.varService.evaluateVar({ tenantId, accountId, traderId, strategyId, followerId });
    const stresses = await this.stressService.runStressTests({ tenantId, accountId, traderId, strategyId, followerId });
    const breakers = await this.breakerService.listBreakers({ tenantId });
    const killSwitches = await this.killSwitchService.inspectKillSwitch({ tenantId });

    const latestSnapshot = await this.snapshotRepo.getLatestSnapshot({ tenantId, accountId, traderId, followerId, strategyId });

    return {
      tenantId,
      asOf: new Date().toISOString(),
      policyVersion: policy.effectiveVersion,
      overallState: exposure.state,
      grossExposure: exposure.grossExposure,
      netExposure: exposure.netExposure,
      notionalUtilizationPercent: exposure.notionalUtilizationPercent,
      marginUtilizationPercent: margin?.marginUtilizationPercent ?? null,
      leverageGross: leverage?.grossLeverage ?? null,
      leverageNet: leverage?.netLeverage ?? null,
      drawdownPercent: drawdown?.drawdownPercent ?? null,
      drawdownAbs: drawdown?.drawdownAbs ?? null,
      dailyPnl: dailyLoss?.dailyPnl ?? null,
      dailyLossRemainingBudget: dailyLoss?.remainingBudget ?? null,
      concentration: concentrations.map((c) => ({ dimension: c.dimension, key: c.key, percent: c.currentPercent, threshold: c.thresholdPercent, isBreach: c.isBreach })),
      liquidationWarnings: liquidations.filter((l) => l.isWarning || l.isCritical).map((l) => ({ symbol: l.symbol ?? 'ACCOUNT', distancePercent: l.distancePercent, isCritical: l.isCritical, reason: l.reason })),
      varEstimate: vars[0] ? { value: vars[0].varValue, percent: vars[0].varPercent, confidence: vars[0].confidence, label: vars[0].label, isBreach: vars[0].isBreach } : null,
      stressSummary: stresses.map((s) => ({ scenarioId: s.scenario.scenarioId, type: s.scenario.type, pnlImpact: s.estimatedPnlImpact, riskLevel: s.riskLevel, isBreach: s.isBreach })),
      breakers: breakers.map((b: any) => ({ scope: b.scope, scopeId: b.scopeId, state: b.state, reason: b.reason })),
      killSwitch: killSwitches.length ? { isEngaged: killSwitches[0].isEngaged, scope: killSwitches[0].scope, reason: killSwitches[0].reason } : { isEngaged: false, scope: null, reason: null },
      freshness: {
        exposureAgeMs: exposure.sourceTimestamps ? Date.now() - new Date(exposure.sourceTimestamps.calculatedAt).getTime() : null,
        marginAgeMs: margin ? Date.now() - new Date(margin.sourceTimestamp ?? '').getTime() : null,
        marketDataStale: exposure.staleSymbols.length > 0,
        exchangeHealthStale: false,
      },
      warnings: exposure.warnings,
      timestamp: new Date().toISOString(),
      note: 'VaR and stress tests are RISK_ESTIMATE control signals, not guaranteed future loss. Past performance is not indicative of future results.',
    };
  }

  // ---------- Pre-trade check ----------

  @Post('check')
  @RequireAnyPermission(Permission.EXECUTION_SUBMIT, Permission.RISK_CONFIG_UPDATE)
  async checkOrder(@Req() req: any, @Body() dto: RiskCheckDto) {
    const tenantId = this.getTenantId(req);
    this.checkTenantAccess(req, tenantId);
    const userId = this.getUserId(req);

    // Validate decimal quantity
    if (!/^-?\d+(\.\d+)?$/.test(dto.quantity)) {
      throw new BadRequestException('Invalid quantity decimal string');
    }

    const decision = await this.decisionService.evaluateUnifiedRisk({
      tenantId,
      userId,
      accountId: dto.accountId,
      symbol: dto.symbol,
      traderId: dto.traderId ?? undefined,
      followerId: dto.followerId ?? undefined,
      strategyId: dto.strategyId ?? undefined,
      orderIntent: { side: dto.side as any, quantity: dto.quantity, price: dto.price ?? null, orderType: dto.orderType as any },
      environment: (dto.environment as any) ?? 'PAPER',
      requestId: dto.requestId ?? undefined,
    });

    return {
      decision: decision.decision,
      state: decision.state,
      blockingReasons: decision.blockingReasons,
      warnings: decision.warnings,
      ruleIds: decision.ruleIds,
      policyVersion: decision.policyVersion,
      timestamp: decision.timestamp,
      details: decision.details.map((d) => ({
        dimension: d.dimension,
        decision: d.decision,
        state: d.state,
        ruleId: d.ruleId,
        policyVersion: d.policyVersion,
        current: d.current,
        threshold: d.threshold,
        severity: d.severity,
        reason: d.reason,
      })),
    };
  }

  // ---------- Exposure ----------

  /**
   * Answers "may this account trade at this leverage?" against the two ceilings that actually
   * bind: the tenant's institutional policy and the venue's own capability for the account's
   * exchange. Both values are read from the same sources the risk evaluation uses, so a customer
   * asking before they trade gets the same answer the engine would give.
   *
   * `LeveragePolicyService` was written for exactly this and was injected nowhere - it had a spec
   * and no caller - so the effective ceiling existed as a rule with no surface. Every unknown
   * stays unknown: no account, no venue capability, or an unreadable policy is a refusal that
   * names the missing input, never a default allowance.
   */
  @Get('leverage-policy')
  @RequirePermissions(Permission.RISK_READ)
  async getLeveragePolicy(
    @Req() req: any,
    @Query('accountId') accountId?: string,
    @Query('requestedLeverage') requestedLeverage?: string,
    @Query('marginMode') marginMode?: string,
  ) {
    const tenantId = this.getTenantId(req);
    if (!accountId) throw new BadRequestException('accountId is required');
    const requested = Number(requestedLeverage);
    if (!Number.isInteger(requested) || requested < 1) {
      throw new BadRequestException('requestedLeverage is required and must be a positive integer');
    }
    const mode = marginMode === 'ISOLATED' ? 'ISOLATED' : 'CROSS';

    const account = await this.prisma.tradingAccount.findFirst({
      where: { id: accountId, tenantId },
      include: { exchange: true },
    });
    if (!account) throw new NotFoundException(`account ${accountId} not found`);

    // The policy service resolves over tenant / trader / strategy / follower, not account: its
    // account-scoped ceiling is a threshold value (`maxLeverageAccount`), while the *account's own*
    // ceiling below comes from the account's venue capability. Passing an account id here was a
    // type error - the parameter does not exist.
    const policy = await this.policyService.resolveEffectivePolicy({ tenantId });
    const policyCeiling = policy.thresholds.maxLeverageAccount ?? policy.thresholds.maxLeverageGross ?? null;

    // A non-integer policy ceiling cannot be reported as a leverage limit. The service's contract
    // is integral leverage, so an unparseable ceiling is passed as the sentinel that makes it
    // refuse - the reason will name the policy, which is the truthful cause.
    const maximumAllowed = policyCeiling !== null && /^\d+$/.test(policyCeiling) ? Number(policyCeiling) : 0;
    const venueMaximum = account.exchange?.maxLeverage ?? null;

    const result = this.leveragePolicyService.evaluate({
      requestedLeverage: requested,
      maximumAllowed,
      venueMaximum: typeof venueMaximum === 'number' ? venueMaximum : null,
      marginMode: mode,
      accountCanTrade: account.canTrade === true,
    });

    return {
      ...result,
      accountId,
      policyCeiling,
      venueCeiling: venueMaximum === null || venueMaximum === undefined ? null : String(venueMaximum),
    };
  }

