import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { InstitutionalRiskPolicyService } from './risk-policy.service';
import { VarResult, RiskState, RiskSeverity } from './risk-management.types';

/**
 * VaR risk: historical simulation, confidence/horizon/window, Decimal-safe output.
 * Labeled RISK_ESTIMATE not guaranteed loss.
 * Returns UNKNOWN/INSUFFICIENT_DATA when insufficient observations.
 * Never guarantees future loss.
 */

function isValidDecimal(v: any): boolean {
  return typeof v === 'string' && /^-?\d+(\.\d+)?$/.test(v);
}
const SCALE = 1_000_000_000_000n;
function parseScaled(s: string): bigint {
  const neg = s.startsWith('-');
  const clean = neg ? s.slice(1) : s;
  const [intP = '0', fracP = ''] = clean.split('.');
  const frac = (fracP + '0'.repeat(12)).slice(0, 12);
  const val = BigInt(intP) * SCALE + BigInt(frac || '0');
  return neg ? -val : val;
}
function formatScaled(b: bigint): string {
  const neg = b < 0n;
  const abs = neg ? -b : b;
  const intP = abs / SCALE;
  const frac = abs % SCALE;
  const fracStr = frac.toString().padStart(12, '0').replace(/0+$/, '');
  return (neg ? '-' : '') + (fracStr ? `${intP}.${fracStr}` : `${intP}`);
}
function cmp(a: string, b: string): number {
  const av = parseScaled(a);
  const bv = parseScaled(b);
  return av < bv ? -1 : av > bv ? 1 : 0;
}

@Injectable()
export class VarRiskService {
  private readonly logger = new Logger(VarRiskService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: InstitutionalRiskPolicyService,
  ) {}

  async evaluateVar(params: {
    tenantId: string;
    accountId?: string;
    traderId?: string;
    strategyId?: string;
    followerId?: string;
  }): Promise<VarResult[]> {
    const { tenantId, accountId, traderId, strategyId, followerId } = params;
    const policy = await this.policyService.resolveEffectivePolicy({
      tenantId,
      traderId: traderId ?? null,
      strategyId: strategyId ?? null,
      followerId: followerId ?? null,
    });

    const confidence = policy.thresholds.varConfidence ?? '95';
    const horizonDays = policy.thresholds.varHorizonDays;
    const windowDays = policy.thresholds.varWindowDays;
    const minObs = policy.thresholds.varMinObservations;
    const methodology = 'HISTORICAL_SIMULATION';
    const methodVersion = 'v1.0.0-historical';

    // Get portfolio exposure for current gross
    const positions = await this.prisma.position.findMany({
      where: { tenantId, ...(accountId ? { accountId } : {}) },
    });

    let grossNotional = 0n;
    for (const pos of positions) {
      const qtyStr = pos.quantity.toString();
      const markPrice = pos.markPrice?.toString() ?? pos.averageEntryPrice?.toString() ?? null;
      if (!qtyStr || !markPrice) continue;
      if (!isValidDecimal(qtyStr) || !isValidDecimal(markPrice)) continue;
      const absQty = qtyStr.startsWith('-') ? qtyStr.slice(1) : qtyStr;
      // Simple notional: qty * price
      const notionalStr = formatScaled((parseScaled(absQty) * parseScaled(markPrice)) / SCALE);
      if (isValidDecimal(notionalStr)) grossNotional += parseScaled(notionalStr);
    }

    // Fetch historical PnL / returns: use MarketDataRecord for portfolio? For simplicity use daily PnL from RiskSnapshotMetadata
    const startDate = new Date(Date.now() - windowDays * 24 * 60 * 60 * 1000);
    const snapshots = await this.prisma.riskSnapshotMetadata.findMany({
      where: { tenantId, ...(accountId ? { accountId } : {}), capturedAt: { gte: startDate } },
      orderBy: { capturedAt: 'asc' },
      take: windowDays * 2,
    });

    const observations = snapshots.length;

    if (observations < minObs) {
      return [
        {
          tenantId,
          methodology,
          confidence,
          horizonDays,
          windowDays,
          observations,
          minObservations: minObs,
          varValue: null,
          varPercent: null,
          varAmount: null,
          methodVersion,
          label: 'RISK_ESTIMATE',
          isBreach: false,
          threshold: policy.thresholds.varThreshold ?? null,
          state: RiskState.UNKNOWN,
          ruleId: 'VAR_LIMIT',
          policyVersion: policy.effectiveVersion,
          reason: `Insufficient observations for VaR: ${observations} < ${minObs} required (window ${windowDays}d), returning UNKNOWN/INSUFFICIENT_DATA per policy — must not invent VaR`,
          severity: RiskSeverity.INFO,
          isUnknown: true,
          note: 'VaR is an estimate, not a guaranteed maximum loss. Past performance is not indicative of future results.',
        },
      ];
    }

    // Compute daily PnL returns from snapshots
    const returns: number[] = [];
    for (let i = 1; i < snapshots.length; i++) {
      const prev = snapshots[i - 1].netDailyPnl;
      const curr = snapshots[i].netDailyPnl;
      if (prev === null || curr === null) continue;
      const prevNum = Number(prev);
      const currNum = Number(curr);
      // Daily PnL already is P&L, not equity. Use PnL as return for VaR?
      // For historical VaR we sort PnL losses.
      returns.push(currNum);
    }

    if (returns.length < minObs) {
      return [
        {
          tenantId,
          methodology,
          confidence,
          horizonDays,
          windowDays,
          observations: returns.length,
          minObservations: minObs,
          varValue: null,
          varPercent: null,
          varAmount: null,
          methodVersion,
          label: 'RISK_ESTIMATE',
          isBreach: false,
          threshold: policy.thresholds.varThreshold ?? null,
          state: RiskState.UNKNOWN,
          ruleId: 'VAR_LIMIT',
          policyVersion: policy.effectiveVersion,
          reason: `Insufficient return observations for VaR: ${returns.length} < ${minObs}, UNKNOWN`,
          severity: RiskSeverity.INFO,
          isUnknown: true,
          note: 'VaR is an estimate, not a guaranteed maximum loss.',
        },
      ];
    }

    // Historical VaR: sort PnL ascending (worst losses first), percentile at confidence
    const sorted = [...returns].sort((a, b) => a - b); // ascending: most negative first
    const confidenceNum = Number(confidence);
    const tailPercent = 100 - confidenceNum; // e.g. 95 -> 5% tail
    const index = Math.floor((tailPercent / 100) * sorted.length);
    const varPnl = sorted[index] ?? sorted[0]; // negative number expected for loss

    // VaR as positive loss amount: -varPnl if negative
    const varLoss = varPnl < 0 ? -varPnl : 0;
    const varValueStr = varLoss.toFixed(6); // decimal string
    const varAmountStr = varValueStr;

    let varPercent: string | null = null;
    if (grossNotional > 0n) {
      // varPercent = varLoss / grossNotional *100
      const varScaled = parseScaled(varValueStr);
      varPercent = formatScaled((varScaled * 100n * SCALE) / grossNotional);
    }

    let isBreach = false;
    let state = RiskState.NORMAL;
    let reason = `VaR ${varValueStr} (${varPercent ?? 'unknown'}%) at ${confidence}% confidence, ${horizonDays}d horizon — RISK_ESTIMATE, not guaranteed loss`;
    let severity = RiskSeverity.INFO;

    if (policy.thresholds.varThreshold && isValidDecimal(policy.thresholds.varThreshold)) {
      if (cmp(varValueStr, policy.thresholds.varThreshold) > 0) {
        isBreach = true;
        state = RiskState.HIGH;
        reason = `VaR ${varValueStr} exceeds threshold ${policy.thresholds.varThreshold} at ${confidence}% confidence — RISK_ESTIMATE breach, not guaranteed future loss`;
        severity = RiskSeverity.WARNING;
      }
    }

    return [
      {
        tenantId,
        methodology,
        confidence,
        horizonDays,
        windowDays,
        observations: returns.length,
        minObservations: minObs,
        varValue: varValueStr,
        varPercent,
        varAmount: varAmountStr,
        methodVersion,
        label: 'RISK_ESTIMATE',
        isBreach,
        threshold: policy.thresholds.varThreshold ?? null,
        state,
        ruleId: 'VAR_LIMIT',
        policyVersion: policy.effectiveVersion,
        reason,
        severity,
        isUnknown: false,
        note: 'VaR is an estimate, not a guaranteed maximum loss. Past performance is not indicative of future results. This metric is a control signal, not a promise.',
      },
    ];
  }
}

import { createHash } from 'crypto';
import { SignJWT, exportJWK, generateKeyPair, type JWK, type KeyLike } from 'jose';

import {
  OidcProviderService,
  OidcTransportError,
  ssoClientSecretAad,
  type OidcConfigRecord,
} from '../oidc-provider.service';

/**
 * TEST-ONLY in-process OpenID Provider for the Part 11 specs.
 *
 * It serves a discovery document, a JWKS and a token endpoint through the
 * provider's overridable transport hooks (fetchJson / postForm), and mints
 * ID tokens signed with real RS256 / ES256 keys via `jose`. The provider's
 * verification code runs unmodified against it.
 *
 * (File name matches "*.fixture-spec.ts": excluded from the production build by
 * tsconfig.build.json's "**\/*spec.ts" and not collected by jest's
 * ".spec.ts$" regex.)
 */

export const TEST_TENANT = '11111111-1111-4111-8111-111111111111';
export const OTHER_TENANT = '99999999-9999-4999-8999-999999999999';
export const TEST_CLIENT_ID = 'wlct-client-123';
export const TEST_CLIENT_SECRET = 'client-secret-value-not-logged';
export const TEST_REDIRECT_URI = 'https://acme.app.test/api/auth/sso/callback';

interface TestKey {
  kid: string;
  alg: 'RS256' | 'ES256';
  privateKey: KeyLike;
  publicJwk: JWK;
}

export interface TokenRequest {
  url: string;
  body: URLSearchParams;
  headers: Record<string, string>;
}

export class FakeOidcIdp {
  readonly issuer = 'https://idp.acme.test';
  readonly authorizationEndpoint = 'https://idp.acme.test/authorize';
  readonly tokenEndpoint = 'https://idp.acme.test/token';
  readonly jwksUri = 'https://idp.acme.test/jwks';
  readonly discoveryUrl = 'https://idp.acme.test/.well-known/openid-configuration';

  readonly keys = new Map<string, TestKey>();
  /** kids currently published in the JWKS. */
  published: string[] = [];
  /** Overrides of the discovery document (e.g. a different issuer). */
  discoveryOverrides: Record<string, unknown> = {};
  /** When set, every request fails like an unreachable IdP. */
  down = false;
  /** HTTP status the token endpoint answers with (200 = success). */
  tokenStatus = 200;
  tokenErrorBody: Record<string, unknown> = { error: 'invalid_grant' };
  /** The ID token the token endpoint returns next (set by the test). */
  nextIdToken: string | null = null;
  /** codes the token endpoint accepts, mapped to the ID token they redeem for. */
  readonly codes = new Map<string, { idToken: string; verifier?: string; redirectUri: string }>();

  readonly fetches: string[] = [];
  readonly tokenRequests: TokenRequest[] = [];

  static async create(): Promise<FakeOidcIdp> {
    const idp = new FakeOidcIdp();
    await idp.addKey('k1', 'RS256');
    await idp.addKey('k2', 'RS256');
    idp.published = ['k1', 'k2'];
    return idp;
  }

  async addKey(kid: string, alg: 'RS256' | 'ES256'): Promise<TestKey> {
    const { privateKey, publicKey } = await generateKeyPair(alg);
    const publicJwk = { ...(await exportJWK(publicKey)), kid, alg, use: 'sig' };
    const key = { kid, alg, privateKey, publicJwk };
    this.keys.set(kid, key);
    return key;
  }

  claims(overrides: Record<string, unknown> = {}): Record<string, unknown> {
    const now = Math.floor(Date.now() / 1000);
    return {
      iss: this.issuer,
      aud: TEST_CLIENT_ID,
      sub: 'oidc-subject-alice',
      iat: now,
      exp: now + 300,
      email: 'alice@acme.test',
      email_verified: true,
      given_name: 'Alice',
      family_name: 'Example',
      ...overrides,
    };
  }

  /** Signs claims with a test key. Claims set to undefined are omitted. */
  async sign(
    claims: Record<string, unknown>,
    kid = 'k1',
    headerOverrides: Record<string, unknown> = {},
  ): Promise<string> {
    const key = this.keys.get(kid);
    if (!key) throw new Error(`unknown test kid ${kid}`);
    const clean = Object.fromEntries(Object.entries(claims).filter(([, v]) => v !== undefined));
    return new SignJWT(clean)
      .setProtectedHeader({ alg: key.alg, kid, typ: 'JWT', ...headerOverrides })
      .sign(key.privateKey);
  }

  /** Registers an authorization code (as the IdP would after the user authenticated). */
  issueCode(
    code: string,
    idToken: string,
    redirectUri = TEST_REDIRECT_URI,
    verifier?: string,
  ): void {
    this.codes.set(code, { idToken, verifier, redirectUri });
  }

  async get(url: string): Promise<any> {
    this.fetches.push(url);
    if (this.down) throw new OidcTransportError('GET failed: ConnectTimeoutError');
    if (url === this.discoveryUrl) {
      return {
        issuer: this.issuer,
        authorization_endpoint: this.authorizationEndpoint,
        token_endpoint: this.tokenEndpoint,
        jwks_uri: this.jwksUri,
        code_challenge_methods_supported: ['S256'],
        ...this.discoveryOverrides,
      };
    }
    if (url === this.jwksUri) {
      return { keys: this.published.map((kid) => this.keys.get(kid)!.publicJwk) };
    }
    throw new OidcTransportError('GET returned HTTP 404', 404);
  }

  async post(url: string, body: URLSearchParams, headers: Record<string, string>): Promise<any> {
    this.tokenRequests.push({ url, body, headers });
    if (this.down) throw new OidcTransportError('POST failed: ConnectTimeoutError');
    if (url !== this.tokenEndpoint) throw new OidcTransportError('POST returned HTTP 404', 404);
    if (this.tokenStatus >= 500)
      throw new OidcTransportError(
        `POST returned HTTP ${this.tokenStatus}`,
        this.tokenStatus,
        null,
      );
    if (this.tokenStatus !== 200)
      throw new OidcTransportError(
        `POST returned HTTP ${this.tokenStatus}`,
        this.tokenStatus,
        this.tokenErrorBody,
      );

    const code = body.get('code') ?? '';
    const registered = this.codes.get(code);
    if (registered) {
      // Behave like a real IdP: one-time codes, exact redirect_uri, PKCE S256 check.
      this.codes.delete(code);
      if (body.get('redirect_uri') !== registered.redirectUri) {
        throw new OidcTransportError('POST returned HTTP 400', 400, {
          error: 'invalid_grant',
          error_description: 'redirect_uri mismatch',
        });
      }
      if (registered.verifier !== undefined) {
        const challenge = createHash('sha256')
          .update(body.get('code_verifier') ?? '', 'ascii')
          .digest('base64url');
        if (challenge !== registered.verifier) {
          throw new OidcTransportError('POST returned HTTP 400', 400, {
            error: 'invalid_grant',
            error_description: 'code_verifier invalid',
          });
        }
      }
      return {
        token_type: 'Bearer',
        access_token: 'at-never-used',
        id_token: registered.idToken,
        expires_in: 300,
      };
    }
    if (this.nextIdToken) {
      return {
        token_type: 'Bearer',
        access_token: 'at-never-used',
        id_token: this.nextIdToken,
        expires_in: 300,
      };
    }
    throw new OidcTransportError('POST returned HTTP 400', 400, { error: 'invalid_grant' });
  }
}

/** Decrypts only the fake client-secret envelope, and only with the tenant-bound AAD. */
export function fakeCrypto() {
  return {
    decrypt: (payload: unknown, aad?: string) => {
      const p = payload as { fakeSecret?: string; aad?: string };
      if (!p || p.aad !== aad || aad !== ssoClientSecretAad(TEST_TENANT))
        throw new Error('decrypt failed');
      return String(p.fakeSecret);
    },
  };
}

export function oidcConfig(
  idp: FakeOidcIdp,
  overrides: Partial<OidcConfigRecord> = {},
): OidcConfigRecord {
  return {
    id: '33333333-3333-4333-8333-333333333333',
    tenantId: TEST_TENANT,
    providerType: 'OIDC',
    state: 'ENABLED',
    isActive: true,
    issuer: idp.issuer,
    clientId: TEST_CLIENT_ID,
    audience: null,
    discoveryUrl: null,
    jwksUrl: null,
    ssoUrl: null,
    scopes: ['openid', 'email', 'profile'],
    clientSecretCiphertext: {
      fakeSecret: TEST_CLIENT_SECRET,
      aad: ssoClientSecretAad(TEST_TENANT),
    },
    tokenEndpointAuthMethod: 'client_secret_basic',
    redirectUri: TEST_REDIRECT_URI,
    pkceRequired: true,
    clockSkewSec: 60,
    maxAuthAgeSec: null,
    allowedAlgorithms: [],
    ...overrides,
  };
}

/** The production provider with only its HTTP transport pointed at the fake IdP. */
export class TestableOidcProvider extends OidcProviderService {
  constructor(
    private readonly idp: FakeOidcIdp,
    prisma: unknown = {},
    crypto: unknown = fakeCrypto(),
  ) {
    super(prisma as never, crypto as never);
  }

  protected override async fetchJson(url: string): Promise<any> {
    return this.idp.get(url);
  }

  protected override async postForm(
    url: string,
    body: URLSearchParams,
    headers: Record<string, string>,
  ): Promise<any> {
    return this.idp.post(url, body, headers);
  }
}

import { InMemoryPrisma } from '../../common/__fixtures__/in-memory-prisma.fixture-spec';
import { ApiKeyRepository } from './api-key.repository';
import { ApiKeyState } from './security.types';

/**
 * ApiKeyRepository.listByTenant merges two stores: EnterpriseApiKey (stored
 * state) and TenantApiKey (state derived from revokedAt / expiresAt). The state
 * filter must apply to both, `total` must count every matching row of both, and
 * pages must be cut from one list ordered by createdAt descending, so paging
 * through the list returns every key exactly once.
 */

const TENANT = '11111111-1111-4111-8111-111111111111';
const OTHER = '22222222-2222-4222-8222-222222222222';
const DAY = 24 * 60 * 60 * 1000;
const at = (daysAgo: number) => new Date(Date.now() - daysAgo * DAY);

describe('ApiKeyRepository', () => {
  let prisma: any;
  let repo: ApiKeyRepository;

  beforeEach(() => {
    prisma = new InMemoryPrisma({ enterpriseApiKey: [['tenantId', 'idempotencyKey']] });
    repo = new ApiKeyRepository(prisma);

    prisma.seed('enterpriseApiKey', { id: 'e-active', tenantId: TENANT, userId: 'u1', state: ApiKeyState.ACTIVE, createdAt: at(2), idempotencyKey: 'k-1' });
    prisma.seed('enterpriseApiKey', { id: 'e-revoked', tenantId: TENANT, userId: 'u2', state: ApiKeyState.REVOKED, createdAt: at(4) });
    prisma.seed('enterpriseApiKey', { id: 'e-rotated', tenantId: TENANT, userId: 'u1', state: ApiKeyState.ROTATED, createdAt: at(7) });
    prisma.seed('enterpriseApiKey', { id: 'e-other', tenantId: OTHER, userId: 'u9', state: ApiKeyState.ACTIVE, createdAt: at(1) });

    prisma.seed('tenantApiKey', { id: 't-active-future', tenantId: TENANT, keyId: 'tk1', createdById: 'u3', revokedAt: null, expiresAt: new Date(Date.now() + DAY), createdAt: at(1) });
    prisma.seed('tenantApiKey', { id: 't-active', tenantId: TENANT, keyId: 'tk2', createdById: null, revokedAt: null, expiresAt: null, createdAt: at(3) });
    prisma.seed('tenantApiKey', { id: 't-revoked', tenantId: TENANT, keyId: 'tk3', createdById: null, revokedAt: at(1), expiresAt: null, createdAt: at(5) });
    prisma.seed('tenantApiKey', { id: 't-expired', tenantId: TENANT, keyId: 'tk4', createdById: null, revokedAt: null, expiresAt: at(1), createdAt: at(6) });
    prisma.seed('tenantApiKey', { id: 't-other', tenantId: OTHER, keyId: 'tk9', createdById: null, revokedAt: null, expiresAt: null, createdAt: at(1) });
  });

  describe('listByTenant', () => {
    it('pages through the merged list in createdAt order, every key exactly once, with the full total', async () => {
      const page1 = await repo.listByTenant(TENANT, { page: 1, limit: 3 });
      const page2 = await repo.listByTenant(TENANT, { page: 2, limit: 3 });
      const page3 = await repo.listByTenant(TENANT, { page: 3, limit: 3 });

      expect(page1.data.map((k) => k.id)).toEqual(['t-active-future', 'e-active', 't-active']);
      expect(page2.data.map((k) => k.id)).toEqual(['e-revoked', 't-revoked', 't-expired']);
      expect(page3.data.map((k) => k.id)).toEqual(['e-rotated']);
      expect([page1.total, page2.total, page3.total]).toEqual([7, 7, 7]);
    });

    it('derives the state of TenantApiKey rows in the list shape', async () => {
      const { data } = await repo.listByTenant(TENANT, { limit: 50 });
      const byId = new Map(data.map((k) => [k.id, k]));
      expect(byId.get('t-active-future')).toMatchObject({ state: ApiKeyState.ACTIVE, userId: 'u3', fingerprint: 'tk1' });
      expect(byId.get('t-active')).toMatchObject({ state: ApiKeyState.ACTIVE, userId: 'unknown' });
      expect(byId.get('t-revoked')).toMatchObject({ state: ApiKeyState.REVOKED });
      expect(byId.get('t-expired')).toMatchObject({ state: ApiKeyState.EXPIRED });
    });

    it.each([
      [ApiKeyState.ACTIVE, ['t-active-future', 'e-active', 't-active']],
      [ApiKeyState.REVOKED, ['e-revoked', 't-revoked']],
      [ApiKeyState.EXPIRED, ['t-expired']],
      [ApiKeyState.ROTATED, ['e-rotated']],
    ])('applies the %s filter to both stores and counts only matching rows', async (state, expected) => {
      const result = await repo.listByTenant(TENANT, { state, limit: 50 });
      expect(result.data.map((k) => k.id)).toEqual(expected);
      expect(result.data.every((k) => k.state === state)).toBe(true);
      expect(result.total).toBe(expected.length);
    });

    it('lists only the enterprise keys of a user when a userId filter is given', async () => {
      const result = await repo.listByTenant(TENANT, { userId: 'u1', limit: 50 });
      expect(result.data.map((k) => k.id)).toEqual(['e-active', 'e-rotated']);
      expect(result.total).toBe(2);
    });

    it("never includes another tenant's keys", async () => {
      const result = await repo.listByTenant(TENANT, { limit: 50 });
      expect(result.data.some((k) => k.tenantId !== TENANT)).toBe(false);
    });

    it('falls back to the enterprise keys alone when TenantApiKey cannot be read', async () => {
      const broken: any = new Proxy(prisma, {
        get: (target, prop) => (prop === 'tenantApiKey' ? { findMany: async () => { throw new Error('unavailable'); }, count: async () => 0 } : target[prop]),
      });
      const result = await new ApiKeyRepository(broken).listByTenant(TENANT, { page: 1, limit: 2 });
      expect(result.data.map((k) => k.id)).toEqual(['e-active', 'e-revoked']);
      expect(result.total).toBe(3);
    });
  });

  describe('tenant-scoped writes', () => {
    it("revoke and updateLastUsed do not touch another tenant's key", async () => {
      await expect(repo.revoke('e-active', OTHER)).resolves.toBeNull();
      await expect(repo.revoke('t-active', OTHER)).resolves.toBeNull();
      await repo.updateLastUsed('e-active', OTHER);
      expect(prisma.rows('enterpriseApiKey').find((k: any) => k.id === 'e-active')).toMatchObject({ state: ApiKeyState.ACTIVE });
      expect(prisma.rows('enterpriseApiKey').find((k: any) => k.id === 'e-active').lastUsedAt).toBeUndefined();
      expect(prisma.rows('tenantApiKey').find((k: any) => k.id === 't-active').revokedAt).toBeNull();

      await expect(repo.revoke('e-active', TENANT)).resolves.toMatchObject({ state: ApiKeyState.REVOKED });
    });

    it("rotate marks only the caller tenant's key as rotated", async () => {
      jest.spyOn(repo, 'create').mockResolvedValue({ id: 'new' } as any);
      await repo.rotate('e-active', { tenantId: OTHER });
      expect(prisma.rows('enterpriseApiKey').find((k: any) => k.id === 'e-active')).toMatchObject({ state: ApiKeyState.ACTIVE });
      await repo.rotate('e-active', { tenantId: TENANT });
      expect(prisma.rows('enterpriseApiKey').find((k: any) => k.id === 'e-active')).toMatchObject({ state: ApiKeyState.ROTATED });
    });
  });
});

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { ApiKeyState } from './security.types';
import { randomUUID } from 'crypto';
import { isRecordNotFound } from '../../common/errors/prisma-not-found';

/**
 * Persistence abstraction for API keys, fingerprints, scopes, expiration, last-used metadata, revocation, and tenant isolation.
 * Prevent duplicate fingerprint, tenant isolation required.
 */
@Injectable()
export class ApiKeyRepository {
  private readonly logger = new Logger(ApiKeyRepository.name);

  constructor(private readonly prisma: PrismaService) {}

  async create(input: {
    tenantId: string;
    userId: string;
    name: string;
    keyId: string;
    secretHash: string;
    fingerprint: string;
    scopes: string[];
    ipAllowlist?: string[];
    expiresAt?: Date;
    createdById?: string;
    idempotencyKey?: string;
  }): Promise<any> {
    // Prevent duplicate fingerprint
    try {
      const existingFingerprint = await (this.prisma as any).enterpriseApiKey?.findFirst({
        where: { fingerprint: input.fingerprint },
      });
      if (existingFingerprint) {
        throw new Error(`Duplicate fingerprint ${input.fingerprint} - prevented`);
      }
    } catch (e: any) {
      if (e.message.includes('Duplicate fingerprint')) throw e;
    }

    // Idempotency check
    if (input.idempotencyKey) {
      try {
        const existing = await (this.prisma as any).enterpriseApiKey?.findFirst({
          where: { tenantId: input.tenantId, idempotencyKey: input.idempotencyKey },
        });
        if (existing) {
          this.logger.log(`Idempotent API key return key=${input.idempotencyKey}`);
          return existing;
        }
      } catch {}
    }

    const id = randomUUID();
    const now = new Date();

    const data = {
      id,
      tenantId: input.tenantId,
      userId: input.userId,
      name: input.name,
      keyId: input.keyId,
      secretHash: input.secretHash,
      fingerprint: input.fingerprint,
      scopes: input.scopes,
      state: ApiKeyState.ACTIVE,
      ipAllowlist: input.ipAllowlist || [],
      expiresAt: input.expiresAt || null,
      createdById: input.createdById || null,
      idempotencyKey: input.idempotencyKey || null,
      createdAt: now,
      updatedAt: now,
    };

    try {
      const created = await (this.prisma as any).enterpriseApiKey?.create({ data });
      if (created) {
        this.logger.log(`API key created id=${created.id} tenant=${input.tenantId} keyId=${input.keyId}`);
        return created;
      }
    } catch (e: any) {
      if (e.code === 'P2002') {
        // Check if it's idempotency or fingerprint duplicate
        if (input.idempotencyKey) {
          const existing = await (this.prisma as any).enterpriseApiKey?.findFirst({ where: { tenantId: input.tenantId, idempotencyKey: input.idempotencyKey } });
          if (existing) return existing;
        }
        throw new Error(`Duplicate API key constraint: ${e.message}`);
      }
      this.logger.warn(`Failed to create enterprise API key, fallback to TenantApiKey: ${e.message}`);

      // Fallback to TenantApiKey for backward compatibility
      try {
        const tenantKey = await (this.prisma as any).tenantApiKey?.create({
          data: {
            id,
            tenantId: input.tenantId,
            name: input.name,
            keyId: input.keyId,
            secretHash: input.secretHash,
            scopes: input.scopes,
            ipAllowlist: input.ipAllowlist || [],
            expiresAt: input.expiresAt || null,
            createdById: input.createdById || null,
            createdAt: now,
            updatedAt: now,
          },
        });
        if (tenantKey) return { ...tenantKey, fingerprint: input.fingerprint, userId: input.userId, state: ApiKeyState.ACTIVE };
      } catch (e2: any) {
        this.logger.warn(`Fallback TenantApiKey creation also failed: ${e2.message}`);
      }
    }

    return { ...data, lastUsedAt: null, revokedAt: null, rotatedAt: null };
  }

  async findByFingerprint(fingerprint: string): Promise<any | null> {
    const result = await (this.prisma as any).enterpriseApiKey?.findFirst({ where: { fingerprint } });
    if (result) return result;

    // Fallback to TenantApiKey by keyId? Fingerprint not in TenantApiKey, try keyId lookup
    return null;
  }

  async findByKeyId(keyId: string): Promise<any | null> {
    const result = await (this.prisma as any).enterpriseApiKey?.findFirst({ where: { keyId } });
    if (result) return result;

    const tenantResult = await (this.prisma as any).tenantApiKey?.findFirst({ where: { keyId } });
    return tenantResult || null;
  }

  async findById(id: string, tenantId: string): Promise<any | null> {
    const result = await (this.prisma as any).enterpriseApiKey?.findFirst({ where: { id, tenantId } });
    if (result) return result;

    const tenantResult = await (this.prisma as any).tenantApiKey?.findFirst({ where: { id, tenantId } });
    return tenantResult || null;
  }

  /**
   * Keys of a tenant from both stores: EnterpriseApiKey (per-user keys with a stored state) and,
   * when no userId filter is given, TenantApiKey (tenant-wide keys whose state is derived from
   * revokedAt/expiresAt). The state filter applies to both stores, `total` counts every matching
   * row of both stores, and the requested page is cut from the merged list ordered by createdAt
   * descending (each store contributes at most offset + limit rows to that merge).
   */
  async listByTenant(tenantId: string, filters?: { userId?: string; state?: ApiKeyState; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const offset = (page - 1) * limit;
    const now = new Date();

    const where: any = { tenantId };
    if (filters?.userId) where.userId = filters.userId;
    if (filters?.state) where.state = filters.state;

    // TenantApiKey rows belong to no user, so they only join an unfiltered tenant list, and a
    // state they can never be in (ROTATED) excludes them entirely.
    const tenantWhere = filters?.userId ? null : this.tenantApiKeyWhere(tenantId, filters?.state, now);

    if (!tenantWhere) {
      const [data, total] = await Promise.all([
        (this.prisma as any).enterpriseApiKey?.findMany({ where, orderBy: { createdAt: 'desc' }, skip: offset, take: limit }) || [],
        (this.prisma as any).enterpriseApiKey?.count({ where }) || 0,
      ]);
      return { data, total };
    }

    const window = offset + limit;
    const [enterpriseRows, enterpriseTotal] = await Promise.all([
      (this.prisma as any).enterpriseApiKey?.findMany({ where, orderBy: { createdAt: 'desc' }, take: window }) || [],
      (this.prisma as any).enterpriseApiKey?.count({ where }) || 0,
    ]);

    let tenantRows: any[];
    let tenantTotal: number;
    try {
      [tenantRows, tenantTotal] = await Promise.all([
        (this.prisma as any).tenantApiKey?.findMany({ where: tenantWhere, orderBy: { createdAt: 'desc' }, take: window }) || [],
        (this.prisma as any).tenantApiKey?.count({ where: tenantWhere }) || 0,
      ]);
    } catch {
      // TenantApiKey unavailable: the list is the enterprise keys alone.
      return { data: enterpriseRows.slice(offset, offset + limit), total: enterpriseTotal };
    }

    const merged = [...enterpriseRows, ...tenantRows.map((k: any) => this.toTenantKeyView(k, now))].sort(
      (a: any, b: any) => this.createdAtMs(b) - this.createdAtMs(a),
    );
    return { data: merged.slice(offset, offset + limit), total: enterpriseTotal + tenantTotal };
  }

  /** TenantApiKey filter for a list state; null when no TenantApiKey can be in that state. */
  private tenantApiKeyWhere(tenantId: string, state: ApiKeyState | undefined, now: Date): Record<string, any> | null {
    switch (state) {
      case undefined:
        return { tenantId };
      case ApiKeyState.ACTIVE:
        return { tenantId, revokedAt: null, OR: [{ expiresAt: null }, { expiresAt: { gte: now } }] };
      case ApiKeyState.EXPIRED:
        return { tenantId, revokedAt: null, expiresAt: { lt: now } };
      case ApiKeyState.REVOKED:
        return { tenantId, revokedAt: { not: null } };
      default:
        return null;
    }
  }

  /** A TenantApiKey row in the EnterpriseApiKey list shape (state derived as tenantApiKeyWhere filters it). */
  private toTenantKeyView(k: any, now: Date): any {
    const state = k.revokedAt
      ? ApiKeyState.REVOKED
      : k.expiresAt && new Date(k.expiresAt) < now
        ? ApiKeyState.EXPIRED
        : ApiKeyState.ACTIVE;
    return { ...k, userId: k.createdById || 'unknown', state, fingerprint: k.keyId };
  }

  private createdAtMs(row: any): number {
    const ms = row?.createdAt ? new Date(row.createdAt).getTime() : NaN;
    return Number.isNaN(ms) ? 0 : ms;
  }

  async listByUser(tenantId: string, userId: string, filters?: { state?: ApiKeyState; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    return this.listByTenant(tenantId, { ...filters, userId });
  }

  async updateLastUsed(id: string, tenantId: string): Promise<void> {
    try {
      await (this.prisma as any).enterpriseApiKey?.update({
        where: { id, tenantId },
        data: { lastUsedAt: new Date(), updatedAt: new Date() },
      });
    } catch {
      try {
        await (this.prisma as any).tenantApiKey?.update({
          where: { id, tenantId },
          data: { lastUsedAt: new Date(), updatedAt: new Date() },
        });
      } catch {}
    }
  }

  async revoke(id: string, tenantId: string, reason?: string): Promise<any | null> {
    try {
      const updated = await (this.prisma as any).enterpriseApiKey?.update({
        where: { id, tenantId },
        data: { state: ApiKeyState.REVOKED, revokedAt: new Date(), updatedAt: new Date() },
      });
      if (updated) return updated;
    } catch {}

    try {
      const updated = await (this.prisma as any).tenantApiKey?.update({
        where: { id, tenantId },
        data: { revokedAt: new Date(), updatedAt: new Date() },
      });
      return updated || null;
    } catch (error) {
      if (isRecordNotFound(error)) return null;
      throw error;
    }
  }

  async rotate(oldId: string, newRecord: any): Promise<any> {
    // Mark old as ROTATED
    try {
      await (this.prisma as any).enterpriseApiKey?.update({
        where: { id: oldId, tenantId: newRecord.tenantId },
        data: { state: ApiKeyState.ROTATED, rotatedAt: new Date(), updatedAt: new Date() },
      });
    } catch {}

    // Create new
    return this.create(newRecord);
  }

  async findExpired(beforeDate?: Date): Promise<any[]> {
    const before = beforeDate || new Date();
    return await (this.prisma as any).enterpriseApiKey?.findMany({
      where: { expiresAt: { lt: before }, state: ApiKeyState.ACTIVE },
    }) || [];
  }

  async expireKeys(): Promise<number> {
    const now = new Date();
    const result = await (this.prisma as any).enterpriseApiKey?.updateMany({
      where: { expiresAt: { lt: now }, state: ApiKeyState.ACTIVE },
      data: { state: ApiKeyState.EXPIRED, updatedAt: now },
    });
    return result?.count || 0;
  }
}

import { Injectable, Logger, BadRequestException, ForbiddenException, NotFoundException } from '@nestjs/common';
import { ApiKeyRepository } from './api-key.repository';
import { SecurityPolicyService } from './security-policy.service';
import { SecurityEventService } from './security-event.service';
import { SecurityAuditService } from './security-audit.service';
import { ApiKeyState, SecurityEventType, SecurityRisk } from './security.types';
import { randomBytes, createHash, createHmac } from 'crypto';
import { Permission, hasPermission } from '@wlct/shared-types';

const KNOWN_PERMISSIONS: ReadonlySet<string> = new Set(Object.values(Permission) as string[]);

const DEV_FALLBACK_HMAC_SECRET = 'dev_api_key_hmac_secret_change_in_production';

/**
 * Key used to fingerprint API key secrets. API_KEY_HMAC_SECRET (or the older
 * API_KEY_SECRET) wins. In production a missing value must never fall back to
 * the public development literal - anyone could recompute fingerprints - so a
 * domain-separated key is derived from DEVELOPER_SECRET_HMAC_KEY, which the
 * API already requires at boot; if that is absent too, startup fails.
 */
export function resolveApiKeyHmacSecret(env: NodeJS.ProcessEnv = process.env): string {
  const explicit = env.API_KEY_HMAC_SECRET || env.API_KEY_SECRET;
  if (explicit) return explicit;
  if (env.NODE_ENV !== 'production') return DEV_FALLBACK_HMAC_SECRET;
  const base = env.DEVELOPER_SECRET_HMAC_KEY;
  if (!base || base.length < 16) {
    throw new Error('API_KEY_HMAC_SECRET is required in production (or DEVELOPER_SECRET_HMAC_KEY of at least 16 characters).');
  }
  return createHmac('sha256', base).update('wlct:security-api-key-fingerprint:v1').digest('hex');
}

/**
 * Secure API key management: creation, hashing/fingerprinting, scoped permissions, expiration, rotation, revocation, tenant/user ownership using existing RBAC permissions.
 * Secret shown only at creation, persist hash/fingerprint not raw secret, cryptographically secure random generation.
 */
@Injectable()
export class ApiKeyService {
  private readonly logger = new Logger(ApiKeyService.name);
  private readonly secretKey: string;

  constructor(
    private readonly repository: ApiKeyRepository,
    private readonly policyService: SecurityPolicyService,
    private readonly eventService: SecurityEventService,
    private readonly auditService: SecurityAuditService,
  ) {
    this.secretKey = resolveApiKeyHmacSecret();
  }

  async createApiKey(params: {
    tenantId: string;
    userId: string;
    name: string;
    scopes: string[];
    ipAllowlist?: string[];
    expiresAt?: Date;
    createdById: string;
    callerPermissions: string[];
    idempotencyKey?: string;
    ipHash?: string;
    requestId?: string;
  }): Promise<{ record: any; secret: string }> {
    // Validate scopes cannot exceed caller permissions
    const forbiddenScopes = params.scopes.filter((scope) => !this.isScopeAllowed(scope, params.callerPermissions));
    if (forbiddenScopes.length > 0) {
      throw new ForbiddenException(`Scopes must be permission keys you hold yourself: ${forbiddenScopes.join(', ')}`);
    }

    // Prevent PLATFORM_MANAGE unless caller has it
    if (params.scopes.includes(Permission.PLATFORM_MANAGE) && !hasPermission(params.callerPermissions, Permission.PLATFORM_MANAGE)) {
      throw new ForbiddenException('Cannot assign platform:manage without having it');
    }

    // Validate tenant ownership
    if (!params.tenantId) {
      throw new BadRequestException('tenantId required');
    }

    const policy = await this.policyService.getEffectivePolicy({ tenantId: params.tenantId });

    // Determine expiration per policy if not provided
    let expiresAt = params.expiresAt;
    if (!expiresAt) {
      const expiryDays = policy.apiKeyExpirationDays || 90;
      expiresAt = new Date(Date.now() + expiryDays * 24 * 60 * 60 * 1000);
    } else {
      // Check if expiration exceeds policy max
      const maxExpiry = new Date(Date.now() + (policy.apiKeyExpirationDays || 90) * 24 * 60 * 60 * 1000);
      if (expiresAt > maxExpiry) {
        throw new BadRequestException(`Expiration exceeds policy maximum of ${policy.apiKeyExpirationDays} days`);
      }
    }

    // Generate cryptographically secure random secret
    const keyId = `ak_${randomBytes(8).toString('hex')}`;
    const secretPart = randomBytes(32).toString('base64url');
    const fullSecret = `${keyId}.${secretPart}`;

    // Hash and fingerprint - never store raw secret
    const secretHash = this.hashSecret(fullSecret);
    const fingerprint = this.createFingerprint(fullSecret);

    const record = await this.repository.create({
      tenantId: params.tenantId,
      userId: params.userId,
      name: params.name,
      keyId,
      secretHash,
      fingerprint,
      scopes: params.scopes,
      ipAllowlist: params.ipAllowlist || [],
      expiresAt,
      createdById: params.createdById,
      idempotencyKey: params.idempotencyKey,
    });

    await this.eventService.record({
      tenantId: params.tenantId,
      userId: params.userId,
      type: SecurityEventType.API_KEY_CREATED,
      severity: SecurityRisk.MEDIUM,
      description: `API key created name=${params.name} keyId=${keyId}`,
      safeMetadata: { keyId, name: params.name, scopes: params.scopes, expiresAt: expiresAt?.toISOString() },
      ipHash: params.ipHash,
      requestId: params.requestId,
    });

    await this.auditService.record({
      tenantId: params.tenantId,
      userId: params.userId,
      actorId: params.createdById,
      event: 'API_KEY_CREATED',
      result: 'SUCCESS',
      targetType: 'ApiKey',
      targetId: record.id,
      safeMetadata: { keyId, name: params.name, scopes: params.scopes },
      ipHash: params.ipHash,
      requestId: params.requestId,
    });

    this.logger.log(`API key created tenant=${params.tenantId} user=${params.userId} keyId=${keyId} - secret shown only once`);

    // Return secret ONLY at creation - never again
    return {
      record: {
        id: record.id,
        tenantId: record.tenantId,
        userId: record.userId,
        name: record.name,
        keyId: record.keyId,
        fingerprint: record.fingerprint,
        scopes: record.scopes,
        state: record.state,
        expiresAt: record.expiresAt ? new Date(record.expiresAt).toISOString() : undefined,
        createdAt: new Date(record.createdAt).toISOString(),
      },
      secret: fullSecret,
    };
  }

  async listApiKeys(tenantId: string, caller: { userId: string; tenantId: string; permissions: string[] }, filters?: { userId?: string; state?: ApiKeyState; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    // Tenant isolation
    if (caller.tenantId !== tenantId && !caller.permissions.includes('PLATFORM_MANAGE')) {
      throw new ForbiddenException('Cross-tenant access denied');
    }

    // Ordinary users can only list own keys unless admin
    const isPrivileged = caller.permissions.includes('ADMIN') || caller.permissions.includes('OWNER') || caller.permissions.includes('API_KEY_MANAGE') || caller.permissions.includes('PLATFORM_MANAGE');

    let effectiveUserId = filters?.userId;
    if (!isPrivileged) {
      effectiveUserId = caller.userId;
    }

    const result = await this.repository.listByTenant(tenantId, {
      userId: effectiveUserId,
      state: filters?.state as any,
      page: filters?.page,
      limit: filters?.limit,
    });

    // Never return secretHash
    const sanitized = result.data.map((k: any) => ({
      id: k.id,
      tenantId: k.tenantId,
      userId: k.userId,
      name: k.name,
      keyId: k.keyId,
      fingerprint: k.fingerprint,
      scopes: k.scopes,
      state: k.state,
      ipAllowlist: k.ipAllowlist,
      expiresAt: k.expiresAt ? new Date(k.expiresAt).toISOString() : null,
      lastUsedAt: k.lastUsedAt ? new Date(k.lastUsedAt).toISOString() : null,
      revokedAt: k.revokedAt ? new Date(k.revokedAt).toISOString() : null,
      rotatedAt: k.rotatedAt ? new Date(k.rotatedAt).toISOString() : null,
      createdAt: k.createdAt ? new Date(k.createdAt).toISOString() : null,
      updatedAt: k.updatedAt ? new Date(k.updatedAt).toISOString() : null,
    }));

    return { data: sanitized, total: result.total };
  }

  async validateApiKey(fullSecret: string, ip?: string): Promise<{ valid: boolean; record?: any; reason?: string }> {
    // Extract keyId and secret part
    const parts = fullSecret.split('.');
    if (parts.length !== 2) {
      return { valid: false, reason: 'INVALID_FORMAT' };
    }

    const keyId = parts[0];
    const fingerprint = this.createFingerprint(fullSecret);

    const record = await this.repository.findByKeyId(keyId);
    if (!record) {
      // Try fingerprint lookup
      const byFingerprint = await this.repository.findByFingerprint(fingerprint);
      if (!byFingerprint) {
        return { valid: false, reason: 'KEY_NOT_FOUND' };
      }
      return this.validateRecord(byFingerprint, fullSecret, ip, fingerprint);
    }

    return this.validateRecord(record, fullSecret, ip, fingerprint);
  }

  private async validateRecord(record: any, fullSecret: string, ip?: string, fingerprint?: string): Promise<{ valid: boolean; record?: any; reason?: string }> {
    // Check state
    if (record.state === 'REVOKED' || record.revokedAt) {
      return { valid: false, reason: 'REVOKED' };
    }
    if (record.state === 'EXPIRED') {
      return { valid: false, reason: 'EXPIRED' };
    }
    if (record.expiresAt && new Date(record.expiresAt) < new Date()) {
      return { valid: false, reason: 'EXPIRED' };
    }
    if (record.state === 'ROTATED') {
      return { valid: false, reason: 'ROTATED' };
    }

    // Validate hash
    const secretHash = this.hashSecret(fullSecret);
    if (record.secretHash !== secretHash) {
      // Also try to validate fingerprint match if secretHash is from old TenantApiKey (HMAC vs hash)
      if (fingerprint && record.fingerprint !== fingerprint && record.keyId) {
        // For TenantApiKey, fingerprint is keyId, check HMAC
        const hmacHash = createHmac('sha256', this.secretKey).update(fullSecret).digest('hex').substring(0, 128);
        if (record.secretHash !== hmacHash && record.secretHash !== secretHash) {
          return { valid: false, reason: 'INVALID_SECRET' };
        }
      } else if (record.secretHash !== secretHash) {
        return { valid: false, reason: 'INVALID_SECRET' };
      }
    }

    // IP allowlist check
    if (record.ipAllowlist && record.ipAllowlist.length > 0 && ip) {
      if (!record.ipAllowlist.includes(ip)) {
        return { valid: false, reason: 'IP_NOT_ALLOWED' };
      }
    }

    // Update last used
    try {
      await this.repository.updateLastUsed(record.id, record.tenantId);
    } catch {}

    return { valid: true, record };
  }

  async rotateApiKey(params: {
    id: string;
    tenantId: string;
    caller: { userId: string; tenantId: string; permissions: string[] };
    createdById: string;
    ipHash?: string;
    requestId?: string;
    idempotencyKey?: string;
  }): Promise<{ record: any; secret: string }> {
    const existing = await this.repository.findById(params.id, params.tenantId);
    if (!existing) {
      throw new NotFoundException(`API key ${params.id} not found`);
    }

    // Check ownership
    const isOwner = existing.userId === params.caller.userId;
    const isPrivileged = params.caller.permissions.includes('ADMIN') || params.caller.permissions.includes('OWNER') || params.caller.permissions.includes('API_KEY_MANAGE') || params.caller.permissions.includes('PLATFORM_MANAGE');

    if (!isOwner && !isPrivileged) {
      throw new ForbiddenException('Cannot rotate API key owned by another user');
    }

    if (existing.tenantId !== params.tenantId && !params.caller.permissions.includes('PLATFORM_MANAGE')) {
      throw new ForbiddenException('Cross-tenant access denied');
    }

    // Check if already revoked/expired
    if (existing.state === 'REVOKED' || existing.revokedAt) {
      throw new BadRequestException('Cannot rotate revoked key');
    }

    const policy = await this.policyService.getEffectivePolicy({ tenantId: params.tenantId });
    const expiresAt = new Date(Date.now() + (policy.apiKeyExpirationDays || 90) * 24 * 60 * 60 * 1000);

    const keyId = `ak_${randomBytes(8).toString('hex')}`;
    const secretPart = randomBytes(32).toString('base64url');
    const fullSecret = `${keyId}.${secretPart}`;
    const secretHash = this.hashSecret(fullSecret);
    const fingerprint = this.createFingerprint(fullSecret);

    const newRecordData = {
      tenantId: existing.tenantId,
      userId: existing.userId,
      name: existing.name,
      keyId,
      secretHash,
      fingerprint,
      scopes: existing.scopes,
      ipAllowlist: existing.ipAllowlist || [],
      expiresAt,
      createdById: params.createdById,
      idempotencyKey: params.idempotencyKey,
      rotatedFromId: existing.id,
    };

    const newRecord = await this.repository.rotate(existing.id, newRecordData);

    await this.eventService.record({
      tenantId: params.tenantId,
      userId: existing.userId,
      type: SecurityEventType.API_KEY_ROTATED,
      severity: SecurityRisk.MEDIUM,
      description: `API key rotated oldKeyId=${existing.keyId} newKeyId=${keyId}`,
      safeMetadata: { oldKeyId: existing.keyId, newKeyId: keyId, name: existing.name },
      ipHash: params.ipHash,
      requestId: params.requestId,
    });

    await this.auditService.record({
      tenantId: params.tenantId,
      userId: existing.userId,
      actorId: params.createdById,
      event: 'API_KEY_ROTATED',
      result: 'SUCCESS',
      targetType: 'ApiKey',
      targetId: newRecord.id,
      safeMetadata: { oldKeyId: existing.keyId, newKeyId: keyId },
      ipHash: params.ipHash,
      requestId: params.requestId,
    });

    this.logger.log(`API key rotated tenant=${params.tenantId} oldKeyId=${existing.keyId} newKeyId=${keyId} - new secret shown only once`);

    return {
      record: {
        id: newRecord.id,
        tenantId: newRecord.tenantId,
        userId: newRecord.userId,
        name: newRecord.name,
        keyId: newRecord.keyId,
        fingerprint: newRecord.fingerprint,
        scopes: newRecord.scopes,
        state: newRecord.state,
        expiresAt: newRecord.expiresAt ? new Date(newRecord.expiresAt).toISOString() : undefined,
        createdAt: new Date(newRecord.createdAt).toISOString(),
      },
      secret: fullSecret,
    };
  }

  async revokeApiKey(params: { id: string; tenantId: string; caller: { userId: string; tenantId: string; permissions: string[] }; reason?: string; ipHash?: string; requestId?: string }): Promise<any> {
    const existing = await this.repository.findById(params.id, params.tenantId);
    if (!existing) {
      throw new NotFoundException(`API key ${params.id} not found`);
    }

    const isOwner = existing.userId === params.caller.userId;
    const isPrivileged = params.caller.permissions.includes('ADMIN') || params.caller.permissions.includes('OWNER') || params.caller.permissions.includes('API_KEY_MANAGE') || params.caller.permissions.includes('PLATFORM_MANAGE');

    if (!isOwner && !isPrivileged) {
      throw new ForbiddenException('Cannot revoke API key owned by another user');
    }

    if (existing.tenantId !== params.tenantId && !params.caller.permissions.includes('PLATFORM_MANAGE')) {
      throw new ForbiddenException('Cross-tenant access denied');
    }

    const revoked = await this.repository.revoke(params.id, params.tenantId, params.reason);

    await this.eventService.record({
      tenantId: params.tenantId,
      userId: existing.userId,
      type: SecurityEventType.API_KEY_REVOKED,
      severity: SecurityRisk.MEDIUM,
      description: `API key revoked keyId=${existing.keyId} reason=${params.reason || 'manual'}`,
      safeMetadata: { keyId: existing.keyId, name: existing.name, reason: params.reason },
      ipHash: params.ipHash,
      requestId: params.requestId,
    });

    await this.auditService.record({
      tenantId: params.tenantId,
      userId: existing.userId,
      actorId: params.caller.userId,
      event: 'API_KEY_REVOKED',
      result: 'SUCCESS',
      targetType: 'ApiKey',
      targetId: existing.id,
      safeMetadata: { keyId: existing.keyId, reason: params.reason },
      ipHash: params.ipHash,
      requestId: params.requestId,
    });

    return { id: revoked?.id || existing.id, state: 'REVOKED', revokedAt: new Date().toISOString() };
  }

  private hashSecret(secret: string): string {
    return createHmac('sha256', this.secretKey).update(secret).digest('hex');
  }

  private createFingerprint(secret: string): string {
    return createHash('sha256').update(secret).digest('hex').substring(0, 64);
  }

  /**
   * A scope is a real permission key (Permission in @wlct/shared-types) that
   * the caller itself holds, using the same wildcard rules as the permission
   * guard (hasPermission): an API key can never carry more than its creator.
   * Unknown strings are rejected so a key cannot hold scopes nothing checks.
   */
  private isScopeAllowed(scope: string, callerPermissions: string[]): boolean {
    if (!KNOWN_PERMISSIONS.has(scope)) return false;
    return hasPermission(callerPermissions, scope);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { SecurityPolicyService } from './security-policy.service';
import { SecurityEventService } from './security-event.service';
import { SecurityAuditService } from './security-audit.service';
import { DeviceState, SecurityEventType, SecurityRisk, SecurityDecision } from './security.types';
import { createHash, randomUUID } from 'crypto';

/**
 * Device registration/trust lifecycle, device fingerprint reference, trust expiry, revocation, and step-up authentication requirements.
 * Use minimized device references/hashes, never override revoked session/blocked account/mandatory MFA/compliance restrictions.
 */
@Injectable()
export class DeviceTrustService {
  private readonly logger = new Logger(DeviceTrustService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: SecurityPolicyService,
    private readonly eventService: SecurityEventService,
    private readonly auditService: SecurityAuditService,
  ) {}

  private hashDevice(deviceId: string, userAgent?: string, ip?: string): string {
    const data = `${deviceId}|${userAgent || ''}|${ip || ''}`;
    return createHash('sha256').update(data).digest('hex').substring(0, 64);
  }

  private hashUserAgent(userAgent?: string): string {
    if (!userAgent) return '';
    return createHash('sha256').update(userAgent).digest('hex').substring(0, 32);
  }

  async registerDevice(params: {
    tenantId: string;
    userId: string;
    deviceId: string;
    userAgent?: string;
    ipHash?: string;
    requestId?: string;
  }): Promise<any> {
    const deviceHash = this.hashDevice(params.deviceId, params.userAgent, params.ipHash);
    const userAgentHash = this.hashUserAgent(params.userAgent);

    try {
      const existing = await (this.prisma as any).deviceTrust?.findFirst({
        where: { tenantId: params.tenantId, userId: params.userId, deviceHash },
      });

      if (existing) {
        // Update last seen
        const updated = await (this.prisma as any).deviceTrust?.update({
          where: { id: existing.id },
          data: { lastSeenAt: new Date(), ipHash: params.ipHash, userAgentHash, updatedAt: new Date() },
        });
        return this.sanitizeDeviceRecord(updated || existing);
      }
    } catch {}

    const policy = await this.policyService.getEffectivePolicy({ tenantId: params.tenantId });
    const expiresAt = new Date(Date.now() + policy.deviceTrustDurationDays * 24 * 60 * 60 * 1000);

    const id = randomUUID();
    const now = new Date();

    const data = {
      id,
      tenantId: params.tenantId,
      userId: params.userId,
      deviceId: params.deviceId,
      deviceHash,
      state: DeviceState.PENDING_TRUST,
      lastSeenAt: now,
      ipHash: params.ipHash || null,
      userAgentHash,
      metadata: {},
      createdAt: now,
      updatedAt: now,
    };

    try {
      const created = await (this.prisma as any).deviceTrust?.create({ data });
      if (created) {
        await this.eventService.record({
          tenantId: params.tenantId,
          userId: params.userId,
          type: SecurityEventType.DEVICE_REGISTERED,
          severity: SecurityRisk.LOW,
          description: `Device registered deviceId=${params.deviceId}`,
          safeMetadata: { deviceId: params.deviceId, deviceHash: deviceHash.substring(0, 16), state: DeviceState.PENDING_TRUST },
          ipHash: params.ipHash,
          requestId: params.requestId,
        });

        return this.sanitizeDeviceRecord(created);
      }
    } catch (e: any) {
      if (e.code === 'P2002') {
        const existing = await (this.prisma as any).deviceTrust?.findFirst({ where: { tenantId: params.tenantId, userId: params.userId, deviceHash } });
        if (existing) return this.sanitizeDeviceRecord(existing);
      }
      this.logger.warn(`Failed to create device trust: ${e.message}`);
    }

    return this.sanitizeDeviceRecord({ ...data, expiresAt, trustedAt: null, revokedAt: null });
  }

  async trustDevice(params: { tenantId: string; userId: string; deviceId: string; deviceHash?: string; actorId: string; ipHash?: string; requestId?: string }): Promise<any> {
    const deviceHash = params.deviceHash || this.hashDevice(params.deviceId);

    try {
      const device = await (this.prisma as any).deviceTrust?.findFirst({
        where: { tenantId: params.tenantId, userId: params.userId, ...(params.deviceHash ? { deviceHash } : { deviceId: params.deviceId }) },
      });

      if (!device) {
        throw new Error(`Device not found deviceId=${params.deviceId}`);
      }

      // Check if session revoked or account blocked - device trust must never override
      const user = await (this.prisma as any).user?.findUnique({ where: { id: params.userId }, select: { status: true } });
      if (user?.status === 'SUSPENDED' || user?.status === 'LOCKED' || user?.status === 'DEACTIVATED') {
        throw new Error(`Cannot trust device for blocked account status=${user.status} - device trust must never override blocked account`);
      }

      const policy = await this.policyService.getEffectivePolicy({ tenantId: params.tenantId });
      const expiresAt = new Date(Date.now() + policy.deviceTrustDurationDays * 24 * 60 * 60 * 1000);

      const updated = await (this.prisma as any).deviceTrust?.update({
        where: { id: device.id },
        data: { state: DeviceState.TRUSTED, trustedAt: new Date(), expiresAt, updatedAt: new Date() },
      });

      await this.eventService.record({
        tenantId: params.tenantId,
        userId: params.userId,
        type: SecurityEventType.DEVICE_TRUSTED,
        severity: SecurityRisk.LOW,
        description: `Device trusted deviceId=${params.deviceId}`,
        safeMetadata: { deviceId: params.deviceId, deviceHash: deviceHash.substring(0, 16) },
        ipHash: params.ipHash,
        requestId: params.requestId,
      });

      await this.auditService.record({
        tenantId: params.tenantId,
        userId: params.userId,
        actorId: params.actorId,
        event: 'DEVICE_TRUSTED',
        result: 'SUCCESS',
        targetType: 'Device',
        targetId: device.id,
        safeMetadata: { deviceId: params.deviceId },
        ipHash: params.ipHash,
        requestId: params.requestId,
      });

      return this.sanitizeDeviceRecord(updated || { ...device, state: DeviceState.TRUSTED, trustedAt: new Date(), expiresAt });
    } catch (e: any) {
      this.logger.warn(`trustDevice failed: ${e.message}`);
      throw e;
    }
  }

  async revokeDevice(params: { tenantId: string; userId: string; deviceId: string; deviceHash?: string; actorId: string; reason?: string; ipHash?: string; requestId?: string }): Promise<any> {
    try {
      const device = await (this.prisma as any).deviceTrust?.findFirst({
        where: { tenantId: params.tenantId, userId: params.userId, ...(params.deviceHash ? { deviceHash: params.deviceHash } : { deviceId: params.deviceId }) },
      });

      if (!device) {
        throw new Error(`Device not found deviceId=${params.deviceId}`);
      }

      const updated = await (this.prisma as any).deviceTrust?.update({
        where: { id: device.id },
        data: { state: DeviceState.REVOKED, revokedAt: new Date(), updatedAt: new Date() },
      });

      await this.eventService.record({
        tenantId: params.tenantId,
        userId: params.userId,
        type: SecurityEventType.DEVICE_REVOKED,
        severity: SecurityRisk.MEDIUM,
        description: `Device revoked deviceId=${params.deviceId} reason=${params.reason || 'manual'}`,
        safeMetadata: { deviceId: params.deviceId, reason: params.reason },
        ipHash: params.ipHash,
        requestId: params.requestId,
      });

      await this.auditService.record({
        tenantId: params.tenantId,
        userId: params.userId,
        actorId: params.actorId,
        event: 'DEVICE_REVOKED',
        result: 'SUCCESS',
        targetType: 'Device',
        targetId: device.id,
        safeMetadata: { deviceId: params.deviceId, reason: params.reason },
        ipHash: params.ipHash,
        requestId: params.requestId,
      });

      return this.sanitizeDeviceRecord(updated || { ...device, state: DeviceState.REVOKED, revokedAt: new Date() });
    } catch (e: any) {
      this.logger.warn(`revokeDevice failed: ${e.message}`);
      throw e;
    }
  }

  async listDevices(tenantId: string, userId: string, filters?: { state?: DeviceState; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const offset = (page - 1) * limit;

    const where: any = { tenantId, userId };
    if (filters?.state) where.state = filters.state;

    const [data, total] = await Promise.all([
      (this.prisma as any).deviceTrust?.findMany({ where, orderBy: { lastSeenAt: 'desc' }, skip: offset, take: limit }) || [],
      (this.prisma as any).deviceTrust?.count({ where }) || 0,
    ]);

    return { data: data.map((d: any) => this.sanitizeDeviceRecord(d)), total };
  }

  async evaluateDeviceTrust(params: { tenantId: string; userId: string; deviceId: string; userAgent?: string; ipHash?: string }): Promise<{ trusted: boolean; state: DeviceState; decision: SecurityDecision; requiresStepUp: boolean }> {
    const deviceHash = this.hashDevice(params.deviceId, params.userAgent, params.ipHash);

    try {
      const device = await (this.prisma as any).deviceTrust?.findFirst({
        where: { tenantId: params.tenantId, userId: params.userId, deviceHash },
      });

      if (!device) {
        return { trusted: false, state: DeviceState.UNKNOWN, decision: SecurityDecision.REVIEW_REQUIRED, requiresStepUp: true };
      }

      if (device.state === DeviceState.REVOKED || device.revokedAt) {
        return { trusted: false, state: DeviceState.REVOKED, decision: SecurityDecision.DENY, requiresStepUp: true };
      }

      if (device.state === DeviceState.TRUSTED) {
        // Check expiry
        if (device.expiresAt && new Date(device.expiresAt) < new Date()) {
          return { trusted: false, state: DeviceState.PENDING_TRUST, decision: SecurityDecision.STEP_UP_REQUIRED, requiresStepUp: true };
        }
        // Device trust must never override mandatory MFA - so if MFA required, still require step-up
        // This check is done in MfaPolicyService, but we return trusted true here
        return { trusted: true, state: DeviceState.TRUSTED, decision: SecurityDecision.ALLOW, requiresStepUp: false };
      }

      if (device.state === DeviceState.PENDING_TRUST) {
        return { trusted: false, state: DeviceState.PENDING_TRUST, decision: SecurityDecision.STEP_UP_REQUIRED, requiresStepUp: true };
      }

      return { trusted: false, state: DeviceState.UNKNOWN, decision: SecurityDecision.REVIEW_REQUIRED, requiresStepUp: true };
    } catch {
      return { trusted: false, state: DeviceState.UNKNOWN, decision: SecurityDecision.REVIEW_REQUIRED, requiresStepUp: true };
    }
  }

  private sanitizeDeviceRecord(record: any): any {
    return {
      id: record.id,
      tenantId: record.tenantId,
      userId: record.userId,
      deviceId: record.deviceId,
      deviceHash: record.deviceHash ? `${record.deviceHash.substring(0, 16)}...` : undefined,
      state: record.state,
      trustedAt: record.trustedAt ? new Date(record.trustedAt).toISOString() : null,
      expiresAt: record.expiresAt ? new Date(record.expiresAt).toISOString() : null,
      lastSeenAt: record.lastSeenAt ? new Date(record.lastSeenAt).toISOString() : new Date().toISOString(),
      revokedAt: record.revokedAt ? new Date(record.revokedAt).toISOString() : null,
      createdAt: record.createdAt ? new Date(record.createdAt).toISOString() : new Date().toISOString(),
    };
  }
}

import { Injectable, BadRequestException, ForbiddenException } from '@nestjs/common';
import { X509Certificate, createPrivateKey, type KeyObject } from 'crypto';
import type { SealedPayload } from '@wlct/utils';
import type { Prisma, SsoConfiguration } from '@prisma/client';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { CryptoService } from '../../infrastructure/crypto/crypto.service';
import { SsoProviderFactory } from './sso-provider.factory';
import { SecurityPolicyService } from './security-policy.service';
import { SecurityEventService } from './security-event.service';
import { SecurityAuditService } from './security-audit.service';
import { SamlProviderService, samlSpDecryptionKeyAad, samlSpSigningKeyAad } from './saml-provider.service';
import { ssoClientSecretAad } from './oidc-provider.service';
import { SsoProvider, SecurityEventType, SecurityRisk } from './security.types';
import { SSO_ASYMMETRIC_ALGORITHMS, SsoAuthError, isAllowedSsoUrl } from './sso-flow.types';

export interface SsoConfigurationInput {
  tenantId: string;
  providerType: SsoProvider;
  issuer?: string;
  audience?: string;
  clientId?: string;
  /** Write-only; envelope-encrypted before storage and never returned. */
  clientSecret?: string;
  metadataUrl?: string;
  entityId?: string;
  acsUrl?: string;
  ssoUrl?: string;
  certificate?: string;
  allowedDomains?: string[];
  enforced?: boolean;
  jitEnabled?: boolean;
  defaultRole?: string;
  discoveryUrl?: string;
  jwksUrl?: string;
  scopes?: string[];
  redirectUri?: string;
  tokenEndpointAuthMethod?: string;
  pkceRequired?: boolean;
  clockSkewSec?: number;
  maxAuthAgeSec?: number;
  allowedAlgorithms?: string[];
  wantResponseSigned?: boolean;
  /** SAML opt-in: require encrypted assertions. */
  wantAssertionsEncrypted?: boolean;
  /** SAML: SP RSA private key (PEM). Write-only; envelope-encrypted before storage, never returned. */
  spDecryptionPrivateKey?: string;
  /** SAML: certificate of that key (PEM), handed to the IdP. */
  spEncryptionCertificate?: string;
  /** SAML Single Logout: IdP SingleLogoutService URL (HTTP-Redirect binding). */
  sloUrl?: string;
  /** SAML Single Logout: our SingleLogoutService URL (…/v1/auth/sso/saml/slo), registered at the IdP. */
  logoutCallbackUrl?: string;
  /** SAML Single Logout: SP RSA signing key (PEM). Write-only; envelope-encrypted, never returned. */
  spSigningPrivateKey?: string;
  /** SAML Single Logout: certificate of that key (PEM), handed to the IdP. */
  spSigningCertificate?: string;
  isActive?: boolean;
  actorId: string;
  /**
   * True when the actor is platform staff. Platform staff are the break-glass
   * path and may enforce without having signed in through the tenant's IdP;
   * tenant administrators may not (see assertEnforcementWillNotLockOut).
   */
  actorIsPlatform?: boolean;
  ipHash?: string;
  requestId?: string;
}

/** What the API reports about a configuration. Secrets and certificates are never echoed. */
export interface SsoConfigurationView {
  id: string;
  tenantId: string;
  providerType: string;
  state: string;
  issuer: string | null;
  audience: string | null;
  clientId: string | null;
  entityId: string | null;
  acsUrl: string | null;
  ssoUrl: string | null;
  redirectUri: string | null;
  discoveryUrl: string | null;
  jwksUrl: string | null;
  scopes: string[];
  tokenEndpointAuthMethod: string;
  pkceRequired: boolean;
  clockSkewSec: number;
  maxAuthAgeSec: number | null;
  allowedAlgorithms: string[];
  wantResponseSigned: boolean;
  wantAssertionsEncrypted: boolean;
  /** True when an SP decryption key is stored (the key itself is never returned). */
  hasSpDecryptionKey: boolean;
  /** Public SP encryption certificate, so the administrator can give it to the IdP. */
  spEncryptionCertificate: string | null;
  /** SAML Single Logout: the IdP SLO URL. */
  sloUrl: string | null;
  /** SAML Single Logout: our SLO URL. */
  logoutCallbackUrl: string | null;
  /** True when an SP signing key is stored (the key itself is never returned). */
  hasSpSigningKey: boolean;
  /** Public SP signing certificate, so the administrator can give it to the IdP. */
  spSigningCertificate: string | null;
  hasClientSecret: boolean;
  hasCertificate: boolean;
  enforced: boolean;
  jitEnabled: boolean;
  isActive: boolean;
  allowedDomains: string[];
}

const TOKEN_AUTH_METHODS = ['client_secret_basic', 'client_secret_post', 'none'];
const DOMAIN_PATTERN = /^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;

/**
 * Tenant SSO configuration and enforcement.
 *
 * The login flow itself (transactions, code redemption, assertion
 * verification, identity mapping, session issuance) lives in
 * modules/auth/sso; this service manages the configuration those flows
 * read. Configuration changes are validated before they are stored:
 *  - every endpoint / redirect URL must pass isAllowedSsoUrl (https);
 *  - SAML certificates must parse as X.509 and at least one must be valid now;
 *  - the OIDC client secret is envelope-encrypted with AAD bound to the
 *    tenant and provider, and is never returned (only hasClientSecret);
 *  - updates are partial: fields that are not supplied are left unchanged;
 *  - a tenant administrator can only leave a configuration ENFORCED after
 *    signing in through that IdP (round 7: SSO is configured by the tenant
 *    administrator, not only by platform staff, so the service itself must
 *    stop a tenant locking its own administrators out).
 */
@Injectable()
export class EnterpriseSsoService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly ssoFactory: SsoProviderFactory,
    private readonly policyService: SecurityPolicyService,
    private readonly eventService: SecurityEventService,
    private readonly auditService: SecurityAuditService,
    private readonly crypto: CryptoService,
    private readonly samlProvider: SamlProviderService,
  ) {}

  async configureSso(params: SsoConfigurationInput): Promise<SsoConfigurationView> {
    const existing = await this.prisma.ssoConfiguration.findUnique({
      where: { tenantId_providerType: { tenantId: params.tenantId, providerType: params.providerType } },
    });

    const changes = this.buildChanges(params);
    const merged = { ...(existing ?? {}), ...changes } as Partial<SsoConfiguration>;
    this.validateSpEncryption(params, existing, merged);
    this.validateSingleLogout(params, existing, merged);
    this.validateMerged(params.providerType, merged, Boolean(existing?.clientSecretCiphertext) || changes.clientSecretCiphertext !== undefined);
    await this.assertEnforcementWillNotLockOut(params, existing, merged);

    let record: SsoConfiguration;
    if (existing) {
      record = await this.prisma.ssoConfiguration.update({
        where: { id: existing.id },
        data: changes as Prisma.SsoConfigurationUpdateInput,
      });
    } else {
      record = await this.prisma.ssoConfiguration.create({
        data: {
          tenantId: params.tenantId,
          providerType: params.providerType,
          state: params.enforced ? 'ENFORCED' : 'ENABLED',
          isActive: true,
          createdById: params.actorId,
          ...changes,
        } as Prisma.SsoConfigurationUncheckedCreateInput,
      });
    }

    await this.eventService.record({
      tenantId: params.tenantId,
      userId: params.actorId,
      type: SecurityEventType.SECURITY_POLICY_CHANGED,
      severity: SecurityRisk.MEDIUM,
      description: `SSO configuration ${existing ? 'updated' : 'created'} for provider ${params.providerType}`,
      safeMetadata: {
        providerType: params.providerType,
        enforced: record.enforced,
        jitEnabled: record.jitEnabled,
        clientSecretChanged: params.clientSecret !== undefined,
        certificateChanged: params.certificate !== undefined,
        spSigningKeyChanged: params.spSigningPrivateKey !== undefined,
      },
      ipHash: params.ipHash,
      requestId: params.requestId,
    });

    await this.auditService.record({
      tenantId: params.tenantId,
      actorId: params.actorId,
      event: 'SECURITY_POLICY_CHANGED',
      result: 'SUCCESS',
      targetType: 'SsoConfiguration',
      targetId: record.id,
      safeMetadata: { providerType: params.providerType, enforced: record.enforced, fields: Object.keys(changes).filter((k) => k !== 'clientSecretCiphertext') },
      ipHash: params.ipHash,
      requestId: params.requestId,
    });

    return this.toView(record);
  }

  async disableSso(params: { tenantId: string; providerType: SsoProvider; actorId: string; ipHash?: string; requestId?: string }): Promise<any> {
    const existing = await this.prisma.ssoConfiguration.findFirst({
      where: { tenantId: params.tenantId, providerType: params.providerType },
    });

    if (!existing) {
      throw new BadRequestException(`SSO configuration not found for provider ${params.providerType}`);
    }

    // Check platform policy - cannot disable if platform enforces SSO
    const platformPolicy = await this.policyService.getPlatformPolicy();
    if (platformPolicy.ssoEnforced) {
      throw new ForbiddenException('Cannot disable SSO when platform enforces it');
    }

    const updated = await this.prisma.ssoConfiguration.update({
      where: { id: existing.id },
      data: { state: 'DISABLED', isActive: false },
    });

    // Emergency disable: unfinished logins for this provider die immediately.
    await this.prisma.ssoAuthTransaction.updateMany({
      where: { tenantId: params.tenantId, configurationId: existing.id, status: { in: ['PENDING', 'VERIFIED'] } },
      data: { status: 'REJECTED', failureReason: 'PROVIDER_DISABLED', consumedAt: new Date() },
    });

    await this.eventService.record({
      tenantId: params.tenantId,
      userId: params.actorId,
      type: SecurityEventType.SECURITY_POLICY_CHANGED,
      severity: SecurityRisk.HIGH,
      description: `SSO disabled for provider ${params.providerType}`,
      safeMetadata: { providerType: params.providerType },
      ipHash: params.ipHash,
      requestId: params.requestId,
    });

    await this.auditService.record({
      tenantId: params.tenantId,
      actorId: params.actorId,
      event: 'SECURITY_POLICY_CHANGED',
      result: 'SUCCESS',
      targetType: 'SsoConfiguration',
      targetId: existing.id,
      safeMetadata: { providerType: params.providerType, action: 'DISABLED' },
      ipHash: params.ipHash,
      requestId: params.requestId,
    });

    return { id: updated.id, state: updated.state, isActive: updated.isActive };
  }

  async getSsoStatus(tenantId: string): Promise<{ enabled: boolean; enforced: boolean; providers: any[] }> {
    const providers = await this.ssoFactory.listTenantProviders(tenantId);
    const enabled = providers.some((p: any) => p.isActive && (p.state === 'ENABLED' || p.state === 'ENFORCED'));
    const enforced = providers.some((p: any) => p.enforced && p.state === 'ENFORCED');
    return { enabled, enforced, providers };
  }

  async enforceSsoCheck(tenantId: string, userEmail?: string): Promise<{ ssoRequired: boolean; providerType?: SsoProvider }> {
    const isEnforced = await this.ssoFactory.isSsoEnforced(tenantId);
    if (!isEnforced) {
      return { ssoRequired: false };
    }

    const providers = await this.ssoFactory.listTenantProviders(tenantId);
    const enforcedProvider = providers.find((p: any) => p.enforced && p.state === 'ENFORCED' && p.isActive);

    if (!enforcedProvider) {
      return { ssoRequired: false };
    }

    // Check domain restriction if email provided
    if (userEmail && enforcedProvider.allowedDomains && enforcedProvider.allowedDomains.length > 0) {
      const domain = userEmail.split('@')[1]?.toLowerCase();
      if (!enforcedProvider.allowedDomains.map((d: string) => d.toLowerCase()).includes(domain)) {
        return { ssoRequired: false };
      }
    }

    return { ssoRequired: true, providerType: enforcedProvider.providerType as SsoProvider };
  }

  toView(record: SsoConfiguration): SsoConfigurationView {
    return {
      id: record.id,
      tenantId: record.tenantId,
      providerType: record.providerType,
      state: record.state,
      issuer: record.issuer,
      audience: record.audience,
      clientId: record.clientId,
      entityId: record.entityId,
      acsUrl: record.acsUrl,
      ssoUrl: record.ssoUrl,
      redirectUri: record.redirectUri,
      discoveryUrl: record.discoveryUrl,
      jwksUrl: record.jwksUrl,
      scopes: record.scopes,
      tokenEndpointAuthMethod: record.tokenEndpointAuthMethod,
      pkceRequired: record.pkceRequired,
      clockSkewSec: record.clockSkewSec,
      maxAuthAgeSec: record.maxAuthAgeSec,
      allowedAlgorithms: record.allowedAlgorithms,
      wantResponseSigned: record.wantResponseSigned,
      wantAssertionsEncrypted: record.wantAssertionsEncrypted,
      hasSpDecryptionKey: record.spDecryptionKeyCiphertext !== null && record.spDecryptionKeyCiphertext !== undefined,
      spEncryptionCertificate: record.spEncryptionCertificate,
      sloUrl: record.sloUrl ?? null,
      logoutCallbackUrl: record.logoutCallbackUrl ?? null,
      hasSpSigningKey: record.spSigningKeyCiphertext !== null && record.spSigningKeyCiphertext !== undefined,
      spSigningCertificate: record.spSigningCertificate ?? null,
      hasClientSecret: record.clientSecretCiphertext !== null && record.clientSecretCiphertext !== undefined,
      hasCertificate: Boolean(record.certificate),
      enforced: record.enforced,
      jitEnabled: record.jitEnabled,
      isActive: record.isActive,
      allowedDomains: record.allowedDomains,
    };
  }

  /**
   * Enforcement closes password login for the configuration's domains (see
   * AuthService.assertPasswordLoginAllowed). A tenant administrator who
   * enforces a configuration that does not work for them - wrong certificate,
   * wrong issuer, a typo in the client id - would lock the tenant's
   * administrators out until platform staff intervene. So when the result of
   * this change is an ENFORCED, active configuration and the actor is not
   * platform staff, the actor must already hold an SSO identity linked to THIS
   * configuration under the issuer the configuration will have after the
   * change. In practice: create or update without enforcement, sign in with
   * SSO once, then enforce. Turning enforcement off is never blocked - that is
   * the tenant's own way back.
   */
  private async assertEnforcementWillNotLockOut(
    params: SsoConfigurationInput,
    existing: SsoConfiguration | null,
    merged: Partial<SsoConfiguration>,
  ): Promise<void> {
    if (params.actorIsPlatform === true) return;
    const resultingState = merged.state ?? (existing ? existing.state : 'ENABLED');
    const enforcing = merged.enforced === true && merged.isActive !== false && resultingState === 'ENFORCED';
    if (!enforcing) return;

    if (!existing) {
      throw new BadRequestException(
        'Single sign-on cannot be enforced in the same step that creates it. Save the configuration without enforcement, sign in through the identity provider once, then enforce it.',
      );
    }

    const link = await this.prisma.ssoIdentity.findFirst({
      where: { tenantId: params.tenantId, configurationId: existing.id, userId: params.actorId },
      select: { issuer: true },
    });
    if (!link || link.issuer !== merged.issuer) {
      throw new BadRequestException(
        'You have not signed in through this identity provider with its current settings. Sign in with single sign-on first, so enforcing it cannot lock administrators out.',
      );
    }
  }

  /**
   * SAML encrypted-assertion opt-in. When the resulting configuration has
   * wantAssertionsEncrypted, it must hold an SP decryption key AND an SP
   * encryption certificate, the certificate must be currently valid, and it
   * must be the certificate of that key (otherwise the IdP would encrypt to a
   * key we do not have and every login would fail). The key is RSA >= 2048
   * bits (XML Encryption key transport). The pair is re-checked whenever
   * either half changes, unsealing the stored key when only the certificate
   * is new.
   */
  private validateSpEncryption(
    params: SsoConfigurationInput,
    existing: SsoConfiguration | null,
    merged: Partial<SsoConfiguration>,
  ): void {
    if (params.providerType !== SsoProvider.SAML) {
      if (params.wantAssertionsEncrypted === true || params.spEncryptionCertificate) {
        throw new BadRequestException('Encrypted assertions apply to SAML configurations only');
      }
      return;
    }
    const touched =
      params.wantAssertionsEncrypted !== undefined ||
      params.spDecryptionPrivateKey !== undefined ||
      params.spEncryptionCertificate !== undefined;
    if (!touched || merged.wantAssertionsEncrypted !== true) return;

    if (!merged.spEncryptionCertificate) {
      throw new BadRequestException('spEncryptionCertificate is required when wantAssertionsEncrypted is set');
    }
    if (!merged.spDecryptionKeyCiphertext) {
      throw new BadRequestException('spDecryptionPrivateKey is required when wantAssertionsEncrypted is set');
    }

    let keyPem: string;
    if (params.spDecryptionPrivateKey !== undefined) {
      keyPem = params.spDecryptionPrivateKey.trim();
    } else {
      try {
        keyPem = this.crypto.decrypt(
          existing?.spDecryptionKeyCiphertext as unknown as SealedPayload,
          samlSpDecryptionKeyAad(params.tenantId),
        );
      } catch {
        throw new BadRequestException('The stored SP decryption key cannot be read; upload spDecryptionPrivateKey again');
      }
    }
    const key = this.parseSpPrivateKey(keyPem);

    let certificate: X509Certificate;
    try {
      certificate = new X509Certificate(merged.spEncryptionCertificate);
    } catch {
      throw new BadRequestException('spEncryptionCertificate is not a valid X.509 certificate');
    }
    const now = new Date();
    if (!(new Date(certificate.validFrom) <= now && now <= new Date(certificate.validTo))) {
      throw new BadRequestException('spEncryptionCertificate is not currently valid');
    }
    if (!certificate.checkPrivateKey(key)) {
      throw new BadRequestException('spEncryptionCertificate does not belong to spDecryptionPrivateKey');
    }
  }

  /**
   * SAML Single Logout (round 8). When the resulting configuration has an IdP
   * SLO URL, it must also have our SLO URL and an SP signing key + signing
   * certificate; the certificate must be currently valid and belong to the
   * key (otherwise the IdP could not verify our LogoutRequests and every
   * logout would fail at the IdP). The key is RSA >= 2048 bits. Checked
   * whenever one of the Single Logout fields changes, unsealing the stored
   * key when only the certificate is new. Clearing sloUrl turns SLO off.
   */
  private validateSingleLogout(
    params: SsoConfigurationInput,
    existing: SsoConfiguration | null,
    merged: Partial<SsoConfiguration>,
  ): void {
    const touched =
      params.sloUrl !== undefined ||
      params.logoutCallbackUrl !== undefined ||
      params.spSigningPrivateKey !== undefined ||
      params.spSigningCertificate !== undefined;
    if (!touched) return;
    if (params.providerType !== SsoProvider.SAML) {
      throw new BadRequestException('Single Logout settings apply to SAML configurations only');
    }
    if (!merged.sloUrl) return;

    if (!merged.logoutCallbackUrl) {
      throw new BadRequestException('logoutCallbackUrl is required when sloUrl is set');
    }
    if (!merged.spSigningCertificate) {
      throw new BadRequestException('spSigningCertificate is required when sloUrl is set');
    }
    if (!merged.spSigningKeyCiphertext) {
      throw new BadRequestException('spSigningPrivateKey is required when sloUrl is set');
    }

    let keyPem: string;
    if (params.spSigningPrivateKey !== undefined) {
      keyPem = params.spSigningPrivateKey.trim();
    } else {
      try {
        keyPem = this.crypto.decrypt(
          existing?.spSigningKeyCiphertext as unknown as SealedPayload,
          samlSpSigningKeyAad(params.tenantId),
        );
      } catch {
        throw new BadRequestException('The stored SP signing key cannot be read; upload spSigningPrivateKey again');
      }
    }
    const key = this.parseSpPrivateKey(keyPem, 'spSigningPrivateKey');

    let certificate: X509Certificate;
    try {
      certificate = new X509Certificate(merged.spSigningCertificate);
    } catch {
      throw new BadRequestException('spSigningCertificate is not a valid X.509 certificate');
    }
    const now = new Date();
    if (!(new Date(certificate.validFrom) <= now && now <= new Date(certificate.validTo))) {
      throw new BadRequestException('spSigningCertificate is not currently valid');
    }
    if (!certificate.checkPrivateKey(key)) {
      throw new BadRequestException('spSigningCertificate does not belong to spSigningPrivateKey');
    }
  }

  /** An RSA private key of at least 2048 bits, or a 400 naming the field. */
  private parseSpPrivateKey(pem: string, field: string = 'spDecryptionPrivateKey'): KeyObject {
    let key: KeyObject;
    try {
      key = createPrivateKey(pem.trim());
    } catch {
      throw new BadRequestException(`${field} is not a valid PEM private key`);
    }
    const bits = key.asymmetricKeyDetails?.modulusLength ?? 0;
    if (key.asymmetricKeyType !== 'rsa' || bits < 2048) {
      throw new BadRequestException(`${field} must be an RSA key of at least 2048 bits`);
    }
    return key;
  }

  /** Only the supplied fields; an empty string clears an optional text field. */
  private buildChanges(params: SsoConfigurationInput): Record<string, unknown> {
    const changes: Record<string, unknown> = {};
    const text = (key: keyof SsoConfigurationInput, column: string = key as string) => {
      const value = params[key];
      if (value === undefined) return;
      changes[column] = typeof value === 'string' && value.trim().length > 0 ? value.trim() : null;
    };
    text('issuer');
    text('audience');
    text('clientId');
    text('metadataUrl');
    text('entityId');
    text('acsUrl');
    text('ssoUrl');
    text('defaultRole');
    text('discoveryUrl');
    text('jwksUrl');
    text('redirectUri');
    text('sloUrl');
    text('logoutCallbackUrl');
    if (params.certificate !== undefined) {
      changes.certificate = params.certificate.trim().length > 0 ? params.certificate.trim() : null;
    }
    if (params.allowedDomains !== undefined) {
      const domains = params.allowedDomains.map((d) => d.trim().toLowerCase()).filter((d) => d.length > 0);
      for (const domain of domains) {
        if (!DOMAIN_PATTERN.test(domain)) {
          throw new BadRequestException(`Invalid allowed domain: ${domain.slice(0, 64)}`);
        }
      }
      changes.allowedDomains = [...new Set(domains)];
    }
    if (params.scopes !== undefined) changes.scopes = [...new Set(params.scopes.map((s) => s.trim()).filter((s) => s.length > 0))];
    if (params.enforced !== undefined) {
      changes.enforced = params.enforced;
      changes.state = params.enforced ? 'ENFORCED' : 'ENABLED';
    }
    if (params.isActive !== undefined) {
      changes.isActive = params.isActive;
      if (!params.isActive) changes.state = 'DISABLED';
      else if (params.enforced === undefined) changes.state = 'ENABLED';
    }
    if (params.jitEnabled !== undefined) changes.jitEnabled = params.jitEnabled;
    if (params.tokenEndpointAuthMethod !== undefined) changes.tokenEndpointAuthMethod = params.tokenEndpointAuthMethod;
    if (params.pkceRequired !== undefined) changes.pkceRequired = params.pkceRequired;
    if (params.clockSkewSec !== undefined) changes.clockSkewSec = params.clockSkewSec;
    if (params.maxAuthAgeSec !== undefined) changes.maxAuthAgeSec = params.maxAuthAgeSec;
    if (params.allowedAlgorithms !== undefined) changes.allowedAlgorithms = [...new Set(params.allowedAlgorithms)];
    if (params.wantResponseSigned !== undefined) changes.wantResponseSigned = params.wantResponseSigned;
    if (params.wantAssertionsEncrypted !== undefined) changes.wantAssertionsEncrypted = params.wantAssertionsEncrypted;
    if (params.spEncryptionCertificate !== undefined) {
      changes.spEncryptionCertificate = params.spEncryptionCertificate.trim().length > 0 ? params.spEncryptionCertificate.trim() : null;
    }
    if (params.spDecryptionPrivateKey !== undefined) {
      if (params.providerType !== SsoProvider.SAML) {
        throw new BadRequestException('spDecryptionPrivateKey applies to SAML configurations only');
      }
      // Parsed before it is sealed, so a malformed key is refused instead of stored.
      this.parseSpPrivateKey(params.spDecryptionPrivateKey);
      changes.spDecryptionKeyCiphertext = this.crypto.encrypt(
        params.spDecryptionPrivateKey.trim(),
        samlSpDecryptionKeyAad(params.tenantId),
      ) as unknown as Prisma.InputJsonValue;
    }
    if (params.spSigningCertificate !== undefined) {
      changes.spSigningCertificate = params.spSigningCertificate.trim().length > 0 ? params.spSigningCertificate.trim() : null;
    }
    if (params.spSigningPrivateKey !== undefined) {
      if (params.providerType !== SsoProvider.SAML) {
        throw new BadRequestException('spSigningPrivateKey applies to SAML configurations only');
      }
      // Parsed before it is sealed, so a malformed key is refused instead of stored.
      this.parseSpPrivateKey(params.spSigningPrivateKey, 'spSigningPrivateKey');
      changes.spSigningKeyCiphertext = this.crypto.encrypt(
        params.spSigningPrivateKey.trim(),
        samlSpSigningKeyAad(params.tenantId),
      ) as unknown as Prisma.InputJsonValue;
    }
    if (params.clientSecret !== undefined) {
      changes.clientSecretCiphertext = this.crypto.encrypt(params.clientSecret, ssoClientSecretAad(params.tenantId)) as unknown as Prisma.InputJsonValue;
    }
    return changes;
  }

  private validateMerged(providerType: SsoProvider, merged: Partial<SsoConfiguration>, hasSecret: boolean): void {
    const url = (value: string | null | undefined, label: string, required: boolean) => {
      if (!value) {
        if (required) throw new BadRequestException(`${label} is required`);
        return;
      }
      if (!isAllowedSsoUrl(value)) {
        throw new BadRequestException(`${label} must be an https URL`);
      }
    };

    if (!merged.issuer) {
      throw new BadRequestException('issuer is required');
    }

    if (providerType === SsoProvider.OIDC) {
      url(merged.issuer, 'issuer', true);
      if (!merged.clientId) throw new BadRequestException('clientId is required');
      url(merged.redirectUri, 'redirectUri', true);
      url(merged.discoveryUrl, 'discoveryUrl', false);
      url(merged.jwksUrl, 'jwksUrl', false);
      url(merged.ssoUrl, 'ssoUrl', false);
      const method = merged.tokenEndpointAuthMethod ?? 'client_secret_basic';
      if (!TOKEN_AUTH_METHODS.includes(method)) {
        throw new BadRequestException('Unsupported tokenEndpointAuthMethod');
      }
      if (method !== 'none' && !hasSecret) {
        throw new BadRequestException('clientSecret is required for a confidential client');
      }
      if (method === 'none' && merged.pkceRequired === false) {
        throw new BadRequestException('A public client (tokenEndpointAuthMethod "none") must use PKCE');
      }
      for (const alg of merged.allowedAlgorithms ?? []) {
        if (!SSO_ASYMMETRIC_ALGORITHMS.includes(alg)) {
          throw new BadRequestException(`Algorithm ${alg} is not an accepted asymmetric algorithm`);
        }
      }
      const scopes = merged.scopes ?? [];
      if (scopes.length > 0 && !scopes.includes('openid')) {
        throw new BadRequestException('scopes must include openid');
      }
      return;
    }

    // SAML
    url(merged.ssoUrl, 'ssoUrl', true);
    url(merged.acsUrl, 'acsUrl', false);
    url(merged.redirectUri, 'redirectUri', false);
    url(merged.sloUrl, 'sloUrl', false);
    url(merged.logoutCallbackUrl, 'logoutCallbackUrl', false);
    if (!merged.certificate) {
      throw new BadRequestException('certificate is required');
    }
    try {
      this.samlProvider.signingCertificates(merged.certificate);
    } catch (error) {
      if (error instanceof SsoAuthError) {
        throw new BadRequestException(error.message);
      }
      throw error;
    }
  }
}

import { BadRequestException } from '@nestjs/common';
import { Permission, SYSTEM_ROLE_DEFINITIONS, SystemRole } from '@wlct/shared-types';

import { PERMISSIONS_KEY, PERMISSIONS_MODE_KEY } from '../../common/constants/metadata.constants';
import { EnterpriseSsoService } from './enterprise-sso.service';
import { SecurityController } from './security.controller';
import { SsoProvider } from './security.types';

/**
 * Round 7 D2: SSO is configured by the tenant administrator.
 *
 * The configuration routes used to require PLATFORM_MANAGE in addition to
 * SSO_MANAGE + SECURITY_POLICY_WRITE (all-of), which made SSO a super-admin
 * feature even though the TENANT_ADMIN matrix carries both SSO permissions.
 * Opening the routes makes the service responsible for not letting a tenant
 * lock its own administrators out: an ENFORCED configuration can only be left
 * in place by a tenant actor who has signed in through that IdP (under the
 * issuer the configuration will have). Platform staff are exempt; turning
 * enforcement off is never blocked.
 */

const TENANT = '11111111-1111-4111-8111-111111111111';
const ADMIN = 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
const CONFIG_ID = 'cccccccc-cccc-4ccc-8ccc-cccccccccccc';
const ISSUER = 'https://idp.acme.test';

function existingOidc(overrides: Record<string, unknown> = {}) {
  return {
    id: CONFIG_ID,
    tenantId: TENANT,
    providerType: 'OIDC',
    state: 'ENABLED',
    issuer: ISSUER,
    audience: null,
    clientId: 'client-1',
    metadataUrl: null,
    entityId: null,
    acsUrl: null,
    ssoUrl: null,
    certificate: null,
    allowedDomains: ['acme.test'],
    enforced: false,
    jitEnabled: false,
    defaultRole: null,
    discoveryUrl: null,
    jwksUrl: null,
    scopes: [],
    isActive: true,
    createdById: ADMIN,
    createdAt: new Date('2026-09-01T00:00:00Z'),
    updatedAt: new Date('2026-09-01T00:00:00Z'),
    clientSecretCiphertext: { ciphertext: 'x' },
    tokenEndpointAuthMethod: 'client_secret_basic',
    redirectUri: 'https://acme.app.test/api/auth/sso/callback',
    pkceRequired: true,
    clockSkewSec: 60,
    maxAuthAgeSec: null,
    allowedAlgorithms: [],
    wantResponseSigned: false,
    ...overrides,
  };
}

function build(options: { existing?: Record<string, unknown> | null; link?: { issuer: string } | null } = {}) {
  const existing = options.existing === undefined ? existingOidc() : options.existing;
  const prisma: any = {
    ssoConfiguration: {
      findUnique: jest.fn(async () => existing),
      update: jest.fn(async ({ data }: any) => ({ ...existing, ...data })),
      create: jest.fn(async ({ data }: any) => ({ ...existingOidc(), ...data })),
    },
    ssoIdentity: {
      findFirst: jest.fn(async ({ where }: any) =>
        options.link && where.tenantId === TENANT && where.configurationId === CONFIG_ID && where.userId === ADMIN
          ? options.link
          : null,
      ),
    },
  };
  const eventService: any = { record: jest.fn(async () => undefined) };
  const auditService: any = { record: jest.fn(async () => undefined) };
  const crypto: any = { encrypt: jest.fn(() => ({ ciphertext: 'enc' })) };
  const unused: any = {};
  const service = new EnterpriseSsoService(prisma, unused, unused, eventService, auditService, crypto, unused);
  return { service, prisma };
}

const base = { tenantId: TENANT, providerType: SsoProvider.OIDC, actorId: ADMIN };

describe('EnterpriseSsoService enforcement lock-out guard (round 7)', () => {
  it('a tenant admin cannot create and enforce in one step', async () => {
    const h = build({ existing: null });
    await expect(
      h.service.configureSso({
        ...base,
        issuer: ISSUER,
        clientId: 'client-1',
        clientSecret: 'secret',
        redirectUri: 'https://acme.app.test/api/auth/sso/callback',
        enforced: true,
      }),
    ).rejects.toThrow(BadRequestException);
    expect(h.prisma.ssoConfiguration.create).not.toHaveBeenCalled();
  });

  it('a tenant admin can create without enforcement', async () => {
    const h = build({ existing: null });
    const view = await h.service.configureSso({
      ...base,
      issuer: ISSUER,
      clientId: 'client-1',
      clientSecret: 'secret',
      redirectUri: 'https://acme.app.test/api/auth/sso/callback',
    });
    expect(view.enforced).toBe(false);
    expect(h.prisma.ssoConfiguration.create).toHaveBeenCalledTimes(1);
  });

  it('a tenant admin who has not signed in through the IdP cannot enforce it', async () => {
    const h = build({ link: null });
    await expect(h.service.configureSso({ ...base, enforced: true })).rejects.toThrow(/signed in through this identity provider/);
    expect(h.prisma.ssoConfiguration.update).not.toHaveBeenCalled();
  });

  it('a tenant admin with a linked identity can enforce it', async () => {
    const h = build({ link: { issuer: ISSUER } });
    const view = await h.service.configureSso({ ...base, enforced: true });
    expect(view).toMatchObject({ enforced: true, state: 'ENFORCED' });
    expect(h.prisma.ssoIdentity.findFirst).toHaveBeenCalledWith({
      where: { tenantId: TENANT, configurationId: CONFIG_ID, userId: ADMIN },
      select: { issuer: true },
    });
  });

  it('changing the issuer of an enforced configuration needs a link under the NEW issuer', async () => {
    const h = build({ existing: existingOidc({ enforced: true, state: 'ENFORCED' }), link: { issuer: ISSUER } });
    await expect(h.service.configureSso({ ...base, issuer: 'https://other-idp.acme.test' })).rejects.toThrow(BadRequestException);
    expect(h.prisma.ssoConfiguration.update).not.toHaveBeenCalled();
    // A harmless change under the same issuer is accepted.
    await expect(h.service.configureSso({ ...base, jitEnabled: true })).resolves.toMatchObject({ jitEnabled: true });
  });

  it('turning enforcement off is never blocked', async () => {
    const h = build({ existing: existingOidc({ enforced: true, state: 'ENFORCED' }), link: null });
    await expect(h.service.configureSso({ ...base, enforced: false })).resolves.toMatchObject({ enforced: false, state: 'ENABLED' });
  });

  it('platform staff are exempt (break-glass)', async () => {
    const h = build({ link: null });
    await expect(h.service.configureSso({ ...base, enforced: true, actorIsPlatform: true })).resolves.toMatchObject({ enforced: true });
    expect(h.prisma.ssoIdentity.findFirst).not.toHaveBeenCalled();
  });
});

describe('SecurityController SSO route permissions (round 7)', () => {
  const metadata = (method: keyof SecurityController) => {
    const handler = SecurityController.prototype[method] as unknown as object;
    return {
      permissions: Reflect.getMetadata(PERMISSIONS_KEY, handler) as string[],
      mode: Reflect.getMetadata(PERMISSIONS_MODE_KEY, handler) as string,
    };
  };

  it.each(['configureSaml', 'configureOidc', 'updateSsoConfig', 'disableSso'] as const)(
    '%s requires SSO_MANAGE + SECURITY_POLICY_WRITE and no longer PLATFORM_MANAGE',
    (method) => {
      expect(metadata(method)).toEqual({
        permissions: [Permission.SSO_MANAGE, Permission.SECURITY_POLICY_WRITE],
        mode: 'all',
      });
    },
  );

  it('listing providers needs SSO_READ; cross-tenant reads stay platform-only in the handler', async () => {
    expect(metadata('listSsoProviders')).toEqual({ permissions: [Permission.SSO_READ], mode: 'all' });
    const listTenantProviders = jest.fn(async () => []);
    const unused: any = {};
    const controller = new SecurityController(
      unused,
      unused,
      { listTenantProviders } as any,
      unused,
      unused,
      unused,
      unused,
      unused,
      unused,
      unused,
      unused,
    );
    const tenantAdmin = { isPlatformUser: false, permissions: [Permission.SSO_READ] };
    await expect(controller.listSsoProviders(TENANT, '99999999-9999-4999-8999-999999999999', tenantAdmin)).rejects.toThrow(
      'Cross-tenant access denied',
    );
    await expect(controller.listSsoProviders(TENANT, undefined, tenantAdmin)).resolves.toEqual([]);
    expect(listTenantProviders).toHaveBeenCalledWith(TENANT);
  });

  it('the TENANT_ADMIN matrix holds every permission the configuration routes require', () => {
    const tenantAdmin = SYSTEM_ROLE_DEFINITIONS.find((role) => role.key === SystemRole.TENANT_ADMIN);
    expect(tenantAdmin?.permissions).toEqual(
      expect.arrayContaining([Permission.SSO_MANAGE, Permission.SECURITY_POLICY_WRITE, Permission.SSO_READ]),
    );
  });

  it('the controller passes actorIsPlatform from the authenticated principal, never from the body', async () => {
    const configureSso = jest.fn(async (input: any) => input);
    const unused: any = {};
    const controller = new SecurityController(
      unused,
      { configureSso } as any,
      unused,
      unused,
      unused,
      unused,
      unused,
      unused,
      unused,
      unused,
      { hashIp: () => 'h' } as any,
    );
    const req = (isPlatformUser: boolean) => ({ ip: '10.0.0.1', headers: {}, user: { isPlatformUser } });
    const dto: any = { issuer: ISSUER, clientId: 'c', redirectUri: 'https://x.test/cb', actorIsPlatform: true };
    await controller.configureOidc(dto, TENANT, { id: ADMIN }, req(false));
    await controller.configureOidc(dto, TENANT, { id: ADMIN }, req(true));
    expect(configureSso.mock.calls.map(([input]) => input.actorIsPlatform)).toEqual([false, true]);
  });
});

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { SecurityPolicyService } from './security-policy.service';
import { DeviceTrustService } from './device-trust.service';
import { SecurityDecision, SecurityRisk } from './security.types';

/**
 * Resolves MFA/security-factor requirements from existing auth policy, tenant policy, privileged-role requirements, and high-risk security signals.
 * This service decides WHEN MFA is required, does not implement another MFA engine.
 */
@Injectable()
export class MfaPolicyService {
  private readonly logger = new Logger(MfaPolicyService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: SecurityPolicyService,
    private readonly deviceTrustService: DeviceTrustService,
  ) {}

  async isMfaRequired(params: {
    tenantId: string;
    userId: string;
    roles?: string[];
    operation?: string;
    deviceId?: string;
    ipHash?: string;
    userAgent?: string;
    riskLevel?: SecurityRisk;
    isNewDevice?: boolean;
    isPrivileged?: boolean;
  }): Promise<{ required: boolean; decision: SecurityDecision; reasons: string[]; policyVersion: string }> {
    const policy = await this.policyService.getEffectivePolicy({ tenantId: params.tenantId });
    const reasons: string[] = [];

    // Platform mandatory MFA
    if (policy.mfaRequired) {
      reasons.push('PLATFORM_MFA_REQUIRED');
    }

    // Privileged roles require MFA
    const privilegedRoles = ['ADMIN', 'OWNER', 'PLATFORM_ADMIN', 'SUPER_ADMIN', 'COMPLIANCE_REVIEWER', 'SECURITY_ADMIN'];
    const hasPrivilegedRole = params.roles?.some((r) => privilegedRoles.includes(r)) || params.isPrivileged;

    if (hasPrivilegedRole && policy.mfaForPrivilegedRoles) {
      reasons.push('PRIVILEGED_ROLE_MFA_REQUIRED');
    }

    // Sensitive operations require MFA
    const sensitiveOps = ['API_KEY_CREATE', 'API_KEY_ROTATE', 'SSO_CONFIG_CHANGE', 'SECURITY_POLICY_CHANGE', 'USER_ROLE_ASSIGN', 'PAYOUT_CREATE', 'WITHDRAW', 'PRIVILEGED_ACTION'];
    if (params.operation && sensitiveOps.includes(params.operation) && policy.mfaForSensitiveOperations) {
      reasons.push(`SENSITIVE_OPERATION_MFA_REQUIRED:${params.operation}`);
    }

    // High risk signals require MFA
    if (params.riskLevel === SecurityRisk.HIGH || params.riskLevel === SecurityRisk.CRITICAL) {
      reasons.push(`HIGH_RISK_MFA_REQUIRED:${params.riskLevel}`);
    }

    // New device requires MFA
    if (params.isNewDevice) {
      reasons.push('NEW_DEVICE_MFA_REQUIRED');
    } else if (params.deviceId) {
      // Check device trust - untrusted device requires step-up
      const deviceTrust = await this.deviceTrustService.evaluateDeviceTrust({
        tenantId: params.tenantId,
        userId: params.userId,
        deviceId: params.deviceId,
        userAgent: params.userAgent,
        ipHash: params.ipHash,
      });

      if (!deviceTrust.trusted) {
        reasons.push(`UNTRUSTED_DEVICE_MFA_REQUIRED:${deviceTrust.state}`);
      }
    }

    // Check user's existing MFA status - if user has 2FA enabled, we still evaluate if required, but we don't weaken
    try {
      const user = await (this.prisma as any).user?.findUnique({ where: { id: params.userId }, select: { twoFactorEnabled: true } });
      if (user?.twoFactorEnabled && reasons.length === 0) {
        // User has MFA enabled but policy doesn't require - don't require step-up unless risk
        // But if platform requires MFA, we already added reason
      }
    } catch {}

    const required = reasons.length > 0;
    const decision = required ? SecurityDecision.STEP_UP_REQUIRED : SecurityDecision.ALLOW;

    this.logger.log(`MFA evaluation tenant=${params.tenantId} user=${params.userId} required=${required} reasons=${reasons.join(',')} operation=${params.operation || 'login'}`);

    return { required, decision, reasons, policyVersion: policy.policyVersion };
  }

  async requiresReauthForPrivileged(params: { tenantId: string; userId: string; operation: string; lastAuthAt?: Date }): Promise<{ required: boolean; reason?: string }> {
    const policy = await this.policyService.getEffectivePolicy({ tenantId: params.tenantId });

    if (!policy.privilegedReauthRequired) {
      return { required: false };
    }

    const privilegedOps = ['SECURITY_POLICY_CHANGE', 'SSO_CONFIG_CHANGE', 'API_KEY_CREATE', 'ROLE_ASSIGN', 'TENANT_DELETE', 'PAYOUT_CREATE'];
    if (!privilegedOps.includes(params.operation)) {
      return { required: false };
    }

    // Check last auth time - if more than 15 minutes ago, require re-auth
    const reauthWindowSec = 15 * 60;
    if (params.lastAuthAt) {
      const elapsedSec = (Date.now() - params.lastAuthAt.getTime()) / 1000;
      if (elapsedSec > reauthWindowSec) {
        return { required: true, reason: `PRIVILEGED_REAUTH_REQUIRED: elapsed ${elapsedSec}s > ${reauthWindowSec}s` };
      }
      return { required: false };
    }

    return { required: true, reason: 'PRIVILEGED_REAUTH_REQUIRED: no recent auth' };
  }

  async evaluateStepUp(params: {
    tenantId: string;
    userId: string;
    currentFactors: string[];
    requiredFactors: string[];
    riskLevel?: SecurityRisk;
  }): Promise<{ stepUpRequired: boolean; missingFactors: string[]; decision: SecurityDecision }> {
    const missing = params.requiredFactors.filter((f) => !params.currentFactors.includes(f));

    if (missing.length > 0) {
      return { stepUpRequired: true, missingFactors: missing, decision: SecurityDecision.STEP_UP_REQUIRED };
    }

    if (params.riskLevel === SecurityRisk.CRITICAL) {
      // Even if factors satisfied, critical risk requires review
      return { stepUpRequired: true, missingFactors: [], decision: SecurityDecision.REVIEW_REQUIRED };
    }

    return { stepUpRequired: false, missingFactors: [], decision: SecurityDecision.ALLOW };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { createHash, timingSafeEqual } from 'crypto';
import { createLocalJWKSet, decodeProtectedHeader, errors as joseErrors, jwtVerify, type JSONWebKeySet, type JWTPayload } from 'jose';
import type { SealedPayload } from '@wlct/utils';

import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { CryptoService } from '../../infrastructure/crypto/crypto.service';
import { ISsoProvider, SsoProviderMetadata, VerifiedSsoIdentity } from './sso-provider.interface';
import { SsoProvider } from './security.types';
import {
  SSO_ASYMMETRIC_ALGORITHMS,
  SSO_MAX_ID_TOKEN_AGE_SECONDS,
  SsoAuthError,
  SsoReasonCode,
  effectiveClockSkew,
  isAllowedSsoUrl,
} from './sso-flow.types';

/** The subset of an SsoConfiguration row the OIDC provider reads. */
export interface OidcConfigRecord {
  id: string;
  tenantId: string;
  providerType: string;
  state: string;
  isActive: boolean;
  issuer: string | null;
  clientId: string | null;
  audience?: string | null;
  discoveryUrl?: string | null;
  jwksUrl?: string | null;
  ssoUrl?: string | null;
  scopes?: string[] | null;
  clientSecretCiphertext?: unknown;
  tokenEndpointAuthMethod?: string | null;
  redirectUri?: string | null;
  pkceRequired?: boolean | null;
  clockSkewSec?: number | null;
  maxAuthAgeSec?: number | null;
  allowedAlgorithms?: string[] | null;
}

/** Trusted endpoints for one issuer, from its discovery document. */
export interface OidcEndpoints {
  issuer: string;
  authorizationEndpoint: string;
  tokenEndpoint: string;
  jwksUri: string;
  endSessionEndpoint?: string;
  codeChallengeMethods?: string[];
}

export type OidcClientAuthMethod = 'client_secret_basic' | 'client_secret_post' | 'none';
const CLIENT_AUTH_METHODS: readonly OidcClientAuthMethod[] = ['client_secret_basic', 'client_secret_post', 'none'];

/** AAD binding an OIDC client secret ciphertext to its tenant and provider. */
export function ssoClientSecretAad(tenantId: string): string {
  return `${tenantId}:sso:OIDC:client_secret`;
}

/** Thrown by fetchJson/postForm when the network or the server failed (not a protocol refusal). */
export class OidcTransportError extends Error {
  constructor(
    message: string,
    public readonly status?: number,
    public readonly body?: unknown,
  ) {
    super(message);
    this.name = 'OidcTransportError';
  }
}

const sha256Hex = (value: string): string => createHash('sha256').update(value, 'utf8').digest('hex');

/**
 * OpenID Connect relying party: authorization-code flow with PKCE.
 *
 * Everything that decides trust comes from server-side configuration (the
 * SsoConfiguration row): issuer, client id, client secret, redirect URI and
 * the discovery URL. Nothing a browser sends can change which IdP is asked,
 * where the code is redeemed or which keys verify the ID token. ID tokens are
 * verified with the `jose` library; no signature code is hand-written here.
 */
@Injectable()
export class OidcProviderService implements ISsoProvider {
  readonly providerType = SsoProvider.OIDC;
  readonly providerName = 'OIDC';
  private readonly logger = new Logger(OidcProviderService.name);

  private static readonly DISCOVERY_TTL_MS = 60 * 60 * 1000;
  private static readonly JWKS_TTL_MS = 10 * 60 * 1000;
  /** Minimum gap between forced JWKS refetches (unknown kid) per URL. */
  private static readonly JWKS_REFETCH_COOLDOWN_MS = 30 * 1000;
  private static readonly HTTP_TIMEOUT_MS = 8000;

  private readonly discoveryCache = new Map<string, { endpoints: OidcEndpoints; fetchedAt: number }>();
  private readonly jwksCache = new Map<string, { jwks: JSONWebKeySet; fetchedAt: number }>();
  private readonly lastForcedRefetch = new Map<string, number>();

  constructor(
    private readonly prisma: PrismaService,
    private readonly crypto: CryptoService,
  ) {}

  isAvailable(): boolean {
    return true;
  }

  async getMetadata(tenantId: string): Promise<SsoProviderMetadata> {
    const config = await this.loadConfig(tenantId);
    if (!config) {
      throw new SsoAuthError(SsoReasonCode.PROVIDER_NOT_CONFIGURED, 'OIDC is not configured for this tenant');
    }
    const endpoints = await this.resolveEndpoints(config);
    return {
      issuer: endpoints.issuer,
      authorizationEndpoint: endpoints.authorizationEndpoint,
      tokenEndpoint: endpoints.tokenEndpoint,
      jwksUri: endpoints.jwksUri,
      endSessionEndpoint: endpoints.endSessionEndpoint,
    };
  }

  /**
   * OpenID Connect RP-Initiated Logout 1.0 URL. With `expectedConfigurationId`
   * the URL is only built when that configuration is still the tenant's
   * active OIDC configuration (a session issued by a replaced or disabled IdP
   * configuration is not sent to whatever IdP is configured now).
   */
  async getLogoutUrl(tenantId: string, redirectUri?: string, expectedConfigurationId?: string): Promise<string> {
    const config = await this.loadConfig(tenantId);
    if (!config || config.state === 'DISABLED') {
      throw new SsoAuthError(SsoReasonCode.PROVIDER_NOT_CONFIGURED, 'OIDC is not configured for this tenant');
    }
    if (expectedConfigurationId !== undefined && config.id !== expectedConfigurationId) {
      throw new SsoAuthError(SsoReasonCode.PROVIDER_NOT_CONFIGURED, 'The configuration that issued this session is no longer active');
    }
    const endpoints = await this.resolveEndpoints(config);
    if (!endpoints.endSessionEndpoint) {
      throw new SsoAuthError(SsoReasonCode.CONFIG_INVALID, 'The IdP does not publish an end_session_endpoint');
    }
    const url = new URL(endpoints.endSessionEndpoint);
    if (config.clientId) url.searchParams.set('client_id', config.clientId);
    if (redirectUri && redirectUri.startsWith('/') && !redirectUri.startsWith('//') && config.redirectUri) {
      url.searchParams.set('post_logout_redirect_uri', new URL(redirectUri, config.redirectUri).toString());
    }
    return url.toString();
  }

  /** Effective client authentication method of a configuration. */
  clientAuthMethod(config: OidcConfigRecord): OidcClientAuthMethod {
    const method = (config.tokenEndpointAuthMethod || 'client_secret_basic') as OidcClientAuthMethod;
    return CLIENT_AUTH_METHODS.includes(method) ? method : 'client_secret_basic';
  }

  /** PKCE is used unless the configuration explicitly turns it off for a confidential client. */
  usesPkce(config: OidcConfigRecord): boolean {
    return config.pkceRequired !== false || this.clientAuthMethod(config) === 'none';
  }

  /**
   * Refuses a configuration that cannot run a secure authorization-code flow.
   * Called before every start and every callback.
   */
  assertConfigUsable(config: OidcConfigRecord): void {
    if (config.providerType !== 'OIDC') {
      throw new SsoAuthError(SsoReasonCode.PROVIDER_MISMATCH, 'Configuration is not an OIDC provider');
    }
    if (!config.isActive || config.state === 'DISABLED') {
      throw new SsoAuthError(SsoReasonCode.PROVIDER_DISABLED, 'OIDC provider is disabled');
    }
    if (!config.issuer || !isAllowedSsoUrl(config.issuer)) {
      throw new SsoAuthError(SsoReasonCode.CONFIG_INVALID, 'OIDC issuer must be an https URL');
    }
    if (!config.clientId) {
      throw new SsoAuthError(SsoReasonCode.CONFIG_INVALID, 'OIDC client id is not configured');
    }
    if (!config.redirectUri || !isAllowedSsoUrl(config.redirectUri)) {
      throw new SsoAuthError(SsoReasonCode.CONFIG_INVALID, 'OIDC redirect URI must be a registered https URL');
    }
    const rawMethod = config.tokenEndpointAuthMethod || 'client_secret_basic';
    if (!CLIENT_AUTH_METHODS.includes(rawMethod as OidcClientAuthMethod)) {
      throw new SsoAuthError(SsoReasonCode.CONFIG_INVALID, 'Unsupported token endpoint auth method');
    }
    if (rawMethod !== 'none' && !config.clientSecretCiphertext) {
      throw new SsoAuthError(SsoReasonCode.CONFIG_INVALID, 'OIDC client secret is not configured');
    }
    for (const url of [config.discoveryUrl, config.jwksUrl, config.ssoUrl]) {
      if (url && !isAllowedSsoUrl(url)) {
        throw new SsoAuthError(SsoReasonCode.CONFIG_INVALID, 'OIDC endpoint overrides must be https URLs');
      }
    }
    const scopes = this.scopes(config);
    if (!scopes.includes('openid')) {
      throw new SsoAuthError(SsoReasonCode.CONFIG_INVALID, 'OIDC scopes must include openid');
    }
    this.algorithms(config);
  }

  /**
   * Endpoints from the issuer's discovery document (or the configured
   * discoveryUrl). The document's `issuer` must equal the configured issuer
   * exactly, and every endpoint must be https. Cached for an hour.
   */
  async resolveEndpoints(config: OidcConfigRecord): Promise<OidcEndpoints> {
    const issuer = String(config.issuer);
    const discoveryUrl = config.discoveryUrl || `${issuer.replace(/\/+$/, '')}/.well-known/openid-configuration`;
    const cacheKey = `${issuer}|${discoveryUrl}`;
    const cached = this.discoveryCache.get(cacheKey);
    let endpoints: OidcEndpoints;
    if (cached && Date.now() - cached.fetchedAt < OidcProviderService.DISCOVERY_TTL_MS) {
      endpoints = cached.endpoints;
    } else {
      let doc: any;
      try {
        doc = await this.fetchJson(discoveryUrl);
      } catch (error) {
        throw new SsoAuthError(SsoReasonCode.PROVIDER_UNAVAILABLE, `OIDC discovery failed: ${(error as Error).message}`);
      }
      if (!doc || typeof doc !== 'object') {
        throw new SsoAuthError(SsoReasonCode.CONFIG_INVALID, 'OIDC discovery document is not an object');
      }
      if (doc.issuer !== issuer) {
        throw new SsoAuthError(SsoReasonCode.ISSUER_MISMATCH, 'OIDC discovery issuer does not match the configured issuer');
      }
      for (const field of ['authorization_endpoint', 'token_endpoint', 'jwks_uri']) {
        if (typeof doc[field] !== 'string' || !isAllowedSsoUrl(doc[field])) {
          throw new SsoAuthError(SsoReasonCode.CONFIG_INVALID, `OIDC discovery ${field} is missing or not https`);
        }
      }
      if (doc.end_session_endpoint !== undefined && (typeof doc.end_session_endpoint !== 'string' || !isAllowedSsoUrl(doc.end_session_endpoint))) {
        throw new SsoAuthError(SsoReasonCode.CONFIG_INVALID, 'OIDC discovery end_session_endpoint is not https');
      }
      endpoints = {
        issuer: doc.issuer,
        authorizationEndpoint: doc.authorization_endpoint,
        tokenEndpoint: doc.token_endpoint,
        jwksUri: doc.jwks_uri,
        endSessionEndpoint: doc.end_session_endpoint,
        codeChallengeMethods: Array.isArray(doc.code_challenge_methods_supported)
          ? doc.code_challenge_methods_supported.filter((m: unknown) => typeof m === 'string')
          : undefined,
      };
      this.discoveryCache.set(cacheKey, { endpoints, fetchedAt: Date.now() });
    }
    // Administrator overrides (validated as https in assertConfigUsable).
    return {
      ...endpoints,
      authorizationEndpoint: config.ssoUrl || endpoints.authorizationEndpoint,
      jwksUri: config.jwksUrl || endpoints.jwksUri,
    };
  }

  /** The IdP authorization URL for one transaction. Every parameter comes from config or the transaction. */
  buildAuthorizationUrl(
    config: OidcConfigRecord,
    endpoints: OidcEndpoints,
    input: { state: string; nonce: string; codeChallenge?: string },
  ): string {
    if (this.usesPkce(config)) {
      if (!input.codeChallenge) {
        throw new SsoAuthError(SsoReasonCode.PKCE_FAILED, 'PKCE challenge missing for a PKCE configuration');
      }
      if (endpoints.codeChallengeMethods && !endpoints.codeChallengeMethods.includes('S256')) {
        throw new SsoAuthError(SsoReasonCode.CONFIG_INVALID, 'The IdP does not support PKCE S256');
      }
    }
    const url = new URL(endpoints.authorizationEndpoint);
    url.searchParams.set('response_type', 'code');
    url.searchParams.set('client_id', String(config.clientId));
    url.searchParams.set('redirect_uri', String(config.redirectUri));
    url.searchParams.set('scope', this.scopes(config).join(' '));
    url.searchParams.set('state', input.state);
    url.searchParams.set('nonce', input.nonce);
    if (this.usesPkce(config) && input.codeChallenge) {
      url.searchParams.set('code_challenge', input.codeChallenge);
      url.searchParams.set('code_challenge_method', 'S256');
    }
    if (typeof config.maxAuthAgeSec === 'number' && config.maxAuthAgeSec >= 0) {
      url.searchParams.set('max_age', String(Math.trunc(config.maxAuthAgeSec)));
    }
    return url.toString();
  }

  /**
   * Redeems an authorization code at the token endpoint and returns the raw
   * ID token. `redirectUri` is the value stored on the transaction at start
   * (copied from configuration), never a request value. Access and refresh
   * tokens in the response are discarded unread.
   */
  async redeemCode(
    config: OidcConfigRecord,
    endpoints: OidcEndpoints,
    input: { code: string; redirectUri: string; codeVerifier?: string | null },
  ): Promise<string> {
    if (!input.code) {
      throw new SsoAuthError(SsoReasonCode.CODE_MISSING, 'Authorization code missing');
    }
    if (input.redirectUri !== config.redirectUri) {
      // The configuration changed between start and callback; the IdP would
      // reject the mismatch anyway, so refuse before sending anything.
      throw new SsoAuthError(SsoReasonCode.CONFIG_INVALID, 'Redirect URI changed during the login');
    }
    if (this.usesPkce(config) && !input.codeVerifier) {
      throw new SsoAuthError(SsoReasonCode.PKCE_FAILED, 'PKCE verifier missing');
    }

    const body = new URLSearchParams();
    body.set('grant_type', 'authorization_code');
    body.set('code', input.code);
    body.set('redirect_uri', input.redirectUri);
    if (input.codeVerifier) body.set('code_verifier', input.codeVerifier);

    const headers: Record<string, string> = {
      'content-type': 'application/x-www-form-urlencoded',
      accept: 'application/json',
    };
    const method = this.clientAuthMethod(config);
    const clientId = String(config.clientId);
    if (method === 'none') {
      body.set('client_id', clientId);
    } else {
      const secret = this.clientSecret(config);
      if (method === 'client_secret_basic') {
        const user = encodeURIComponent(clientId);
        const pass = encodeURIComponent(secret);
        headers.authorization = `Basic ${Buffer.from(`${user}:${pass}`).toString('base64')}`;
      } else {
        body.set('client_id', clientId);
        body.set('client_secret', secret);
      }
    }

    let response: any;
    try {
      response = await this.postForm(endpoints.tokenEndpoint, body, headers);
    } catch (error) {
      if (error instanceof OidcTransportError && error.status !== undefined && error.status >= 400 && error.status < 500) {
        const err = error.body && typeof error.body === 'object' ? (error.body as Record<string, unknown>) : {};
        const description = `${String(err.error ?? '')} ${String(err.error_description ?? '')}`.toLowerCase();
        if (description.includes('code_verifier') || description.includes('pkce') || description.includes('code challenge')) {
          throw new SsoAuthError(SsoReasonCode.PKCE_FAILED, 'Token endpoint rejected the PKCE verifier');
        }
        throw new SsoAuthError(SsoReasonCode.TOKEN_EXCHANGE_FAILED, `Token endpoint refused the code (HTTP ${error.status})`);
      }
      throw new SsoAuthError(SsoReasonCode.PROVIDER_UNAVAILABLE, `Token endpoint unavailable: ${(error as Error).message}`);
    }

    if (!response || typeof response !== 'object') {
      throw new SsoAuthError(SsoReasonCode.TOKEN_EXCHANGE_FAILED, 'Token endpoint returned no JSON object');
    }
    if (response.token_type !== undefined && String(response.token_type).toLowerCase() !== 'bearer') {
      throw new SsoAuthError(SsoReasonCode.TOKEN_EXCHANGE_FAILED, 'Token endpoint returned an unexpected token_type');
    }
    if (typeof response.id_token !== 'string' || response.id_token.length === 0) {
      throw new SsoAuthError(SsoReasonCode.ID_TOKEN_MISSING, 'Token response has no id_token');
    }
    return response.id_token;
  }

  /**
   * Verifies an ID token: header algorithm on the asymmetric allow-list,
   * signature by a key from the IdP's JWKS (selected by kid, refetched once
   * on an unknown kid, rate-limited), then iss / aud / exp / iat (with the
   * configured clock skew), azp, nonce (against the transaction's hash) and
   * auth_time when max_age is configured.
   */
  async verifyIdToken(
    config: OidcConfigRecord,
    endpoints: OidcEndpoints,
    idToken: string,
    expected: { nonceHash: string | null },
  ): Promise<VerifiedSsoIdentity> {
    let header: { alg?: string; kid?: string };
    try {
      header = decodeProtectedHeader(idToken);
    } catch {
      throw new SsoAuthError(SsoReasonCode.ID_TOKEN_MALFORMED, 'ID token is not a compact JWS');
    }
    const algorithms = this.algorithms(config);
    if (!header.alg || !algorithms.includes(header.alg)) {
      throw new SsoAuthError(SsoReasonCode.ALGORITHM_REJECTED, `ID token algorithm ${String(header.alg)} is not allowed`);
    }

    const skew = effectiveClockSkew(config.clockSkewSec);
    const clientId = String(config.clientId);
    const verify = async (jwks: JSONWebKeySet): Promise<JWTPayload> => {
      const { payload } = await jwtVerify(idToken, createLocalJWKSet(jwks), {
        issuer: endpoints.issuer,
        audience: clientId,
        algorithms,
        clockTolerance: skew,
        maxTokenAge: SSO_MAX_ID_TOKEN_AGE_SECONDS,
        requiredClaims: ['iss', 'sub', 'aud', 'exp', 'iat'],
      });
      return payload;
    };

    let payload: JWTPayload;
    try {
      const jwks = await this.loadJwks(endpoints.jwksUri, false);
      try {
        payload = await verify(jwks);
      } catch (error) {
        if (error instanceof joseErrors.JWKSNoMatchingKey && this.mayForceRefetch(endpoints.jwksUri)) {
          // Key rotation: the IdP may have published a new key since we cached.
          payload = await verify(await this.loadJwks(endpoints.jwksUri, true));
        } else {
          throw error;
        }
      }
    } catch (error) {
      throw this.mapJoseError(error);
    }

    // azp: required when there are several audiences; must be our client when present.
    const aud = payload.aud;
    const azp = (payload as Record<string, unknown>).azp;
    if (Array.isArray(aud) && aud.length > 1 && azp === undefined) {
      throw new SsoAuthError(SsoReasonCode.AZP_MISMATCH, 'ID token with several audiences has no azp');
    }
    if (azp !== undefined && azp !== clientId) {
      throw new SsoAuthError(SsoReasonCode.AZP_MISMATCH, 'ID token azp is not this client');
    }

    // nonce: must equal the transaction's nonce (stored as a SHA-256 hash).
    const nonce = (payload as Record<string, unknown>).nonce;
    if (!expected.nonceHash || typeof nonce !== 'string' || nonce.length === 0) {
      throw new SsoAuthError(SsoReasonCode.NONCE_MISMATCH, 'ID token nonce missing');
    }
    const got = Buffer.from(sha256Hex(nonce), 'hex');
    const want = Buffer.from(expected.nonceHash, 'hex');
    if (got.length !== want.length || !timingSafeEqual(got, want)) {
      throw new SsoAuthError(SsoReasonCode.NONCE_MISMATCH, 'ID token nonce does not match this login');
    }

    // auth_time: enforced when max_age is configured.
    if (typeof config.maxAuthAgeSec === 'number' && config.maxAuthAgeSec >= 0) {
      const authTime = (payload as Record<string, unknown>).auth_time;
      const nowSec = Math.floor(Date.now() / 1000);
      if (typeof authTime !== 'number') {
        throw new SsoAuthError(SsoReasonCode.CLAIMS_MISSING, 'ID token has no auth_time although max_age was requested');
      }
      if (authTime > nowSec + skew) {
        throw new SsoAuthError(SsoReasonCode.TOKEN_TIME_INVALID, 'ID token auth_time is in the future');
      }
      if (nowSec - authTime > config.maxAuthAgeSec + skew) {
        throw new SsoAuthError(SsoReasonCode.AUTH_TIME_TOO_OLD, 'IdP authentication is older than max_age');
      }
    }

    if (typeof payload.sub !== 'string' || payload.sub.length === 0 || payload.sub.length > 512) {
      throw new SsoAuthError(SsoReasonCode.CLAIMS_MISSING, 'ID token subject is missing or too long');
    }

    const claims = payload as Record<string, unknown>;
    const email = typeof claims.email === 'string' && claims.email.includes('@') ? claims.email.trim().toLowerCase() : null;
    const emailVerified = claims.email_verified === true || claims.email_verified === 'true';
    const str = (v: unknown): string | undefined => (typeof v === 'string' && v.length > 0 ? v.slice(0, 200) : undefined);
    const groups = Array.isArray(claims.groups) ? claims.groups.filter((g): g is string => typeof g === 'string').slice(0, 100) : undefined;

    this.logger.log(`OIDC ID token verified tenant=${config.tenantId} kid=${header.kid ?? 'none'} alg=${header.alg}`);

    return {
      providerType: SsoProvider.OIDC,
      issuer: String(payload.iss),
      subject: payload.sub,
      email,
      emailVerified: email !== null && emailVerified,
      displayName: str(claims.name),
      firstName: str(claims.given_name),
      lastName: str(claims.family_name),
      groups,
    };
  }

  /** GET a JSON document (discovery / JWKS). Overridable in tests. */
  protected async fetchJson(url: string): Promise<any> {
    let res: Response;
    try {
      res = await fetch(url, {
        headers: { accept: 'application/json' },
        redirect: 'error',
        signal: AbortSignal.timeout(OidcProviderService.HTTP_TIMEOUT_MS),
      });
    } catch (error) {
      throw new OidcTransportError(`GET failed: ${(error as Error).name}`);
    }
    if (!res.ok) throw new OidcTransportError(`GET returned HTTP ${res.status}`, res.status);
    return res.json();
  }

  /** POST a form to the token endpoint. Overridable in tests. Never logs the body. */
  protected async postForm(url: string, body: URLSearchParams, headers: Record<string, string>): Promise<any> {
    let res: Response;
    try {
      res = await fetch(url, {
        method: 'POST',
        headers,
        body: body.toString(),
        redirect: 'error',
        signal: AbortSignal.timeout(OidcProviderService.HTTP_TIMEOUT_MS),
      });
    } catch (error) {
      throw new OidcTransportError(`POST failed: ${(error as Error).name}`);
    }
    let parsed: unknown = null;
    try {
      parsed = await res.json();
    } catch {
      parsed = null;
    }
    if (!res.ok) throw new OidcTransportError(`POST returned HTTP ${res.status}`, res.status, parsed);
    return parsed;
  }

  private async loadConfig(tenantId: string): Promise<OidcConfigRecord | null> {
    return (await this.prisma.ssoConfiguration.findFirst({
      where: { tenantId, providerType: 'OIDC', isActive: true },
    })) as OidcConfigRecord | null;
  }

  private scopes(config: OidcConfigRecord): string[] {
    const configured = Array.isArray(config.scopes) && config.scopes.length > 0 ? config.scopes : ['openid', 'email', 'profile'];
    return [...new Set(configured.map((s) => s.trim()).filter(Boolean))];
  }

  /** Allowed algorithms: configured ones that are asymmetric, else the full asymmetric list. */
  private algorithms(config: OidcConfigRecord): string[] {
    const configured = Array.isArray(config.allowedAlgorithms) ? config.allowedAlgorithms : [];
    if (configured.length === 0) return [...SSO_ASYMMETRIC_ALGORITHMS];
    const rejected = configured.filter((alg) => !SSO_ASYMMETRIC_ALGORITHMS.includes(alg));
    if (rejected.length > 0) {
      throw new SsoAuthError(SsoReasonCode.CONFIG_INVALID, 'Only asymmetric ID-token algorithms may be configured');
    }
    return [...configured];
  }

  private clientSecret(config: OidcConfigRecord): string {
    if (!config.clientSecretCiphertext) {
      throw new SsoAuthError(SsoReasonCode.CONFIG_INVALID, 'OIDC client secret is not configured');
    }
    try {
      return this.crypto.decrypt(config.clientSecretCiphertext as SealedPayload, ssoClientSecretAad(config.tenantId));
    } catch {
      throw new SsoAuthError(SsoReasonCode.CONFIG_INVALID, 'OIDC client secret cannot be decrypted');
    }
  }

  private async loadJwks(url: string, forceRefresh: boolean): Promise<JSONWebKeySet> {
    const cached = this.jwksCache.get(url);
    if (!forceRefresh && cached && Date.now() - cached.fetchedAt < OidcProviderService.JWKS_TTL_MS) return cached.jwks;
    if (forceRefresh) this.lastForcedRefetch.set(url, Date.now());
    let body: any;
    try {
      body = await this.fetchJson(url);
    } catch (error) {
      throw new SsoAuthError(SsoReasonCode.PROVIDER_UNAVAILABLE, `JWKS unavailable: ${(error as Error).message}`);
    }
    if (!body || !Array.isArray(body.keys)) {
      throw new SsoAuthError(SsoReasonCode.CONFIG_INVALID, 'JWKS response has no keys array');
    }
    // Symmetric keys never verify ID tokens here.
    const keys = body.keys.filter((k: any) => k && typeof k === 'object' && k.kty !== 'oct');
    const jwks: JSONWebKeySet = { keys };
    this.jwksCache.set(url, { jwks, fetchedAt: Date.now() });
    return jwks;
  }

  private mayForceRefetch(url: string): boolean {
    const last = this.lastForcedRefetch.get(url);
    return last === undefined || Date.now() - last >= OidcProviderService.JWKS_REFETCH_COOLDOWN_MS;
  }

  private mapJoseError(error: unknown): SsoAuthError {
    if (error instanceof SsoAuthError) return error;
    if (error instanceof joseErrors.JWTExpired) {
      return error.claim === 'exp'
        ? new SsoAuthError(SsoReasonCode.TOKEN_EXPIRED, 'ID token expired')
        : new SsoAuthError(SsoReasonCode.TOKEN_TIME_INVALID, `ID token ${error.claim} check failed`);
    }
    if (error instanceof joseErrors.JWTClaimValidationFailed) {
      if (error.reason === 'missing') return new SsoAuthError(SsoReasonCode.CLAIMS_MISSING, `ID token claim ${error.claim} missing`);
      if (error.claim === 'iss') return new SsoAuthError(SsoReasonCode.ISSUER_MISMATCH, 'ID token issuer mismatch');
      if (error.claim === 'aud') return new SsoAuthError(SsoReasonCode.AUDIENCE_MISMATCH, 'ID token audience mismatch');
      if (error.claim === 'iat' || error.claim === 'nbf') return new SsoAuthError(SsoReasonCode.TOKEN_TIME_INVALID, `ID token ${error.claim} check failed`);
      return new SsoAuthError(SsoReasonCode.CLAIMS_MISSING, `ID token claim ${error.claim} invalid`);
    }
    if (error instanceof joseErrors.JWSSignatureVerificationFailed) {
      return new SsoAuthError(SsoReasonCode.SIGNATURE_INVALID, 'ID token signature verification failed');
    }
    if (error instanceof joseErrors.JOSEAlgNotAllowed || error instanceof joseErrors.JOSENotSupported) {
      return new SsoAuthError(SsoReasonCode.ALGORITHM_REJECTED, 'ID token algorithm rejected');
    }
    if (error instanceof joseErrors.JWKSNoMatchingKey) {
      return new SsoAuthError(SsoReasonCode.KEY_NOT_FOUND, 'No IdP key matches the ID token kid');
    }
    if (error instanceof joseErrors.JWKSMultipleMatchingKeys) {
      return new SsoAuthError(SsoReasonCode.SIGNATURE_INVALID, 'Several IdP keys match and none verified the token');
    }
    if (error instanceof joseErrors.JWSInvalid || error instanceof joseErrors.JWTInvalid || error instanceof joseErrors.JWKSInvalid) {
      return new SsoAuthError(SsoReasonCode.ID_TOKEN_MALFORMED, 'ID token is malformed');
    }
    return new SsoAuthError(SsoReasonCode.SIGNATURE_INVALID, `ID token verification failed: ${(error as Error)?.name ?? 'unknown'}`);
  }
}

// # Responsibility: exercise encrypted SAML assertions against the production verification path with runtime-generated keys.
import { generateKeyPairSync } from 'node:crypto';
import { createRequire } from 'node:module';
import { Prisma } from '@prisma/client';
import { BadRequestException } from '@nestjs/common';

import { loadSamlTestKeys } from './__fixtures__/saml-test-keys.fixture-spec';
import { SignedXml } from './__fixtures__/xml-signer.fixture-spec';
import { EnterpriseSsoService } from './enterprise-sso.service';
import { SamlProviderService, samlSpDecryptionKeyAad, type SamlConfigRecord } from './saml-provider.service';
import { SsoProvider } from './security.types';
import { SsoAuthError, SsoReasonCode } from './sso-flow.types';

// xml-encryption is the library node-saml decrypts with; the IdP side of these
// tests uses it to encrypt. Loaded without type declarations (it ships none).
const loadXmlEncryption = createRequire(__filename);
const xmlenc = loadXmlEncryption('xml-encryption') as {
  encrypt: (
    content: string,
    options: Record<string, unknown>,
    callback: (error: Error | null, result?: string) => void,
  ) => void;
};

/**
 * Round 7 D3: opt-in encrypted SAML assertions.
 *
 * The IdP side below is real: the assertion is signed with RSA-SHA256 XML-DSig
 * (xml-crypto) and then encrypted with XML Encryption (AES-256-GCM content key,
 * RSA-OAEP key transport) to the SP encryption certificate. The SP side is the
 * production path: SamlProviderService unseals the tenant's SP key, node-saml
 * decrypts, the signature INSIDE the decrypted assertion is verified, and our
 * Recipient / Destination / replay checks run on the decrypted, signed XML.
 * Every key is generated at test time (jest globalSetup or below); none is
 * committed.
 */

const KEYS = loadSamlTestKeys();
const TENANT = '11111111-1111-4111-8111-111111111111';
const IDP_ISSUER = 'https://idp.acme.test/saml';
const SP_ENTITY = 'https://acme.app.test/saml/sp';
const ACS = 'https://acme.app.test/v1/auth/sso/saml/acs';
const REQUEST_ID = '_0123456789abcdef0123456789abcdef01234567';

/** A stand-in for CryptoService that enforces the AAD binding like the real envelope. */
const fakeCrypto = {
  encrypt: (plaintext: string, aad?: string) => ({ sealed: plaintext, aad }),
  decrypt: (payload: { sealed: string; aad?: string }, aad?: string) => {
    if (payload.aad !== aad) throw new Error('AAD mismatch');
    return payload.sealed;
  },
};

function config(overrides: Partial<SamlConfigRecord> = {}): SamlConfigRecord {
  return {
    id: '22222222-2222-4222-8222-222222222222',
    tenantId: TENANT,
    providerType: 'SAML',
    state: 'ENABLED',
    isActive: true,
    issuer: IDP_ISSUER,
    entityId: SP_ENTITY,
    audience: null,
    ssoUrl: 'https://idp.acme.test/sso',
    acsUrl: ACS,
    certificate: KEYS.idpCert,
    clockSkewSec: 60,
    wantResponseSigned: false,
    wantAssertionsEncrypted: true,
    spDecryptionKeyCiphertext: fakeCrypto.encrypt(KEYS.spEncKey, samlSpDecryptionKeyAad(TENANT)),
    spEncryptionCertificate: KEYS.spEncCert,
    ...overrides,
  };
}

const iso = (d: Date) => d.toISOString();

function assertionXml(assertionId: string): string {
  const now = Date.now();
  return (
    `<saml:Assertion xmlns:saml="urn:oasis:names:tc:SAML:2.0:assertion" ID="${assertionId}" Version="2.0" IssueInstant="${iso(new Date(now))}">` +
    `<saml:Issuer>${IDP_ISSUER}</saml:Issuer>` +
    `<saml:Subject>` +
    `<saml:NameID Format="urn:oasis:names:tc:SAML:1.1:nameid-format:unspecified">subject-alice</saml:NameID>` +
    `<saml:SubjectConfirmation Method="urn:oasis:names:tc:SAML:2.0:cm:bearer">` +
    `<saml:SubjectConfirmationData InResponseTo="${REQUEST_ID}" NotOnOrAfter="${iso(new Date(now + 300_000))}" Recipient="${ACS}"/>` +
    `</saml:SubjectConfirmation>` +
    `</saml:Subject>` +
    `<saml:Conditions NotBefore="${iso(new Date(now - 30_000))}" NotOnOrAfter="${iso(new Date(now + 300_000))}">` +
    `<saml:AudienceRestriction><saml:Audience>${SP_ENTITY}</saml:Audience></saml:AudienceRestriction>` +
    `</saml:Conditions>` +
    `<saml:AuthnStatement AuthnInstant="${iso(new Date(now))}" SessionIndex="_session1">` +
    `<saml:AuthnContext><saml:AuthnContextClassRef>urn:oasis:names:tc:SAML:2.0:ac:classes:PasswordProtectedTransport</saml:AuthnContextClassRef></saml:AuthnContext>` +
    `</saml:AuthnStatement>` +
    `<saml:AttributeStatement>` +
    `<saml:Attribute Name="email"><saml:AttributeValue>alice@acme.test</saml:AttributeValue></saml:Attribute>` +
    `</saml:AttributeStatement>` +
    `</saml:Assertion>`
  );
}

function sign(xml: string, key: string, cert: string): string {
  const sig = new SignedXml({ privateKey: key, publicCert: cert });
  sig.addReference({
    xpath: "//*[local-name(.)='Assertion']",
    digestAlgorithm: 'http://www.w3.org/2001/04/xmlenc#sha256',
    transforms: ['http://www.w3.org/2000/09/xmldsig#enveloped-signature', 'http://www.w3.org/2001/10/xml-exc-c14n#'],
  });
  sig.canonicalizationAlgorithm = 'http://www.w3.org/2001/10/xml-exc-c14n#';
  sig.signatureAlgorithm = 'http://www.w3.org/2001/04/xmldsig-more#rsa-sha256';
  sig.computeSignature(xml, {
    location: { reference: "//*[local-name(.)='Assertion']/*[local-name(.)='Issuer']", action: 'after' },
  });
  return sig.getSignedXml();
}

function encryptTo(xml: string, cert: string): Promise<string> {
  return new Promise((resolve, reject) => {
    xmlenc.encrypt(
      xml,
      {
        rsa_pub: cert,
        pem: cert,
        encryptionAlgorithm: 'http://www.w3.org/2009/xmlenc11#aes256-gcm',
        keyEncryptionAlgorithm: 'http://www.w3.org/2001/04/xmlenc#rsa-oaep-mgf1p',
        disallowEncryptionWithInsecureAlgorithm: true,
        warnInsecureAlgorithm: false,
      },
      (error, result) => (error || !result ? reject(error ?? new Error('encryption failed')) : resolve(result)),
    );
  });
}

function response(inner: string): string {
  const xml =
    `<samlp:Response xmlns:samlp="urn:oasis:names:tc:SAML:2.0:protocol" xmlns:saml="urn:oasis:names:tc:SAML:2.0:assertion" ID="_resp${Math.random().toString(16).slice(2)}" Version="2.0" IssueInstant="${iso(new Date())}" Destination="${ACS}" InResponseTo="${REQUEST_ID}">` +
    `<saml:Issuer>${IDP_ISSUER}</saml:Issuer>` +
    `<samlp:Status><samlp:StatusCode Value="urn:oasis:names:tc:SAML:2.0:status:Success"/></samlp:Status>` +
    inner +
    `</samlp:Response>`;
  return Buffer.from(xml, 'utf8').toString('base64');
}

async function encryptedResponse(
  assertionId: string,
  options: { signKey?: string; signCert?: string; unsigned?: boolean; encryptTo?: string } = {},
): Promise<string> {
  const assertion = options.unsigned
    ? assertionXml(assertionId)
    : sign(assertionXml(assertionId), options.signKey ?? KEYS.idpKey, options.signCert ?? KEYS.idpCert);
  const encrypted = await encryptTo(assertion, options.encryptTo ?? KEYS.spEncCert);
  return response(`<saml:EncryptedAssertion>${encrypted}</saml:EncryptedAssertion>`);
}

function fakePrisma() {
  const replays = new Set<string>();
  return {
    ssoAssertionReplay: {
      create: jest.fn(async ({ data }: { data: { tenantId: string; issuer: string; assertionId: string } }) => {
        const key = `${data.tenantId}|${data.issuer}|${data.assertionId}`;
        if (replays.has(key)) {
          throw new Prisma.PrismaClientKnownRequestError('Unique constraint failed', { code: 'P2002', clientVersion: 'test' });
        }
        replays.add(key);
        return data;
      }),
    },
    ssoConfiguration: { findFirst: jest.fn(async () => null) },
  };
}

async function expectReason(promise: Promise<unknown>, reason: SsoReasonCode): Promise<void> {
  const error = await promise.then(
    () => {
      throw new Error('verification unexpectedly succeeded');
    },
    (e: unknown) => e,
  );
  expect(error).toBeInstanceOf(SsoAuthError);
  expect((error as SsoAuthError).reason).toBe(reason);
}

describe('SAML encrypted assertions (round 7, opt-in)', () => {
  const ORIGINAL = process.env.SSO_SAML_ENABLED;
  let saml: SamlProviderService;

  beforeEach(() => {
    process.env.SSO_SAML_ENABLED = 'true';
    saml = new SamlProviderService(fakePrisma() as never, fakeCrypto as never);
  });

  afterAll(() => {
    if (ORIGINAL === undefined) delete process.env.SSO_SAML_ENABLED;
    else process.env.SSO_SAML_ENABLED = ORIGINAL;
  });

  it('decrypts an encrypted, signed assertion and returns the verified identity', async () => {
    const result = await saml.verifyResponse(config(), {
      samlResponse: await encryptedResponse('_enc_ok'),
      expectedRequestId: REQUEST_ID,
    });
    expect(result.assertionId).toBe('_enc_ok');
    expect(result.identity).toMatchObject({ issuer: IDP_ISSUER, subject: 'subject-alice', email: 'alice@acme.test' });
  });

  it('with the opt-in, a plaintext (signed) assertion is refused', async () => {
    const plaintext = response(sign(assertionXml('_plain'), KEYS.idpKey, KEYS.idpCert));
    await expectReason(saml.verifyResponse(config(), { samlResponse: plaintext, expectedRequestId: REQUEST_ID }), SsoReasonCode.SAML_ASSERTION_NOT_ENCRYPTED);
  });

  it('a response with both a plaintext and an encrypted assertion is refused', async () => {
    const encrypted = await encryptTo(sign(assertionXml('_both_e'), KEYS.idpKey, KEYS.idpCert), KEYS.spEncCert);
    const both = response(sign(assertionXml('_both_p'), KEYS.idpKey, KEYS.idpCert) + `<saml:EncryptedAssertion>${encrypted}</saml:EncryptedAssertion>`);
    await expectReason(saml.verifyResponse(config(), { samlResponse: both, expectedRequestId: REQUEST_ID }), SsoReasonCode.SAML_ASSERTION_NOT_ENCRYPTED);
  });

  it('encryption is not a substitute for the signature: an unsigned encrypted assertion is refused', async () => {
    await expectReason(
      saml.verifyResponse(config(), { samlResponse: await encryptedResponse('_unsigned', { unsigned: true }), expectedRequestId: REQUEST_ID }),
      SsoReasonCode.SAML_SIGNATURE_INVALID,
    );
  });

  it('an encrypted assertion signed by an unknown key is refused', async () => {
    await expectReason(
      saml.verifyResponse(config(), {
        samlResponse: await encryptedResponse('_attacker', { signKey: KEYS.attackerKey, signCert: KEYS.attackerCert }),
        expectedRequestId: REQUEST_ID,
      }),
      SsoReasonCode.SAML_SIGNATURE_INVALID,
    );
  });

  it('an assertion encrypted to a different key cannot be decrypted and is refused', async () => {
    await expectReason(
      saml.verifyResponse(config(), {
        samlResponse: await encryptedResponse('_wrong_key', { encryptTo: KEYS.attackerCert }),
        expectedRequestId: REQUEST_ID,
      }),
      SsoReasonCode.SAML_MALFORMED,
    );
  });

  it('without the opt-in no key is loaded and an encrypted assertion is refused', async () => {
    await expectReason(
      saml.verifyResponse(config({ wantAssertionsEncrypted: false }), {
        samlResponse: await encryptedResponse('_no_optin'),
        expectedRequestId: REQUEST_ID,
      }),
      SsoReasonCode.SAML_MALFORMED,
    );
  });

  it('the opt-in without a stored key, or a key sealed for another tenant, fails closed as CONFIG_INVALID', async () => {
    const samlResponse = await encryptedResponse('_cfg');
    await expectReason(saml.verifyResponse(config({ spDecryptionKeyCiphertext: null }), { samlResponse, expectedRequestId: REQUEST_ID }), SsoReasonCode.CONFIG_INVALID);
    await expectReason(
      saml.verifyResponse(config({ spDecryptionKeyCiphertext: fakeCrypto.encrypt(KEYS.spEncKey, samlSpDecryptionKeyAad('99999999-9999-4999-8999-999999999999')) }), {
        samlResponse,
        expectedRequestId: REQUEST_ID,
      }),
      SsoReasonCode.CONFIG_INVALID,
    );
    const unwired = new SamlProviderService(fakePrisma() as never);
    await expectReason(unwired.verifyResponse(config(), { samlResponse, expectedRequestId: REQUEST_ID }), SsoReasonCode.CONFIG_INVALID);
  });

  it('a decrypted assertion is still accepted only once (replay)', async () => {
    const samlResponse = await encryptedResponse('_enc_replay');
    await saml.verifyResponse(config(), { samlResponse, expectedRequestId: REQUEST_ID });
    await expectReason(saml.verifyResponse(config(), { samlResponse, expectedRequestId: REQUEST_ID }), SsoReasonCode.SAML_REPLAY);
  });
});

describe('EnterpriseSsoService encrypted-assertion configuration (round 7)', () => {
  const CONFIG_ID = '22222222-2222-4222-8222-222222222222';

  function build(existing: Record<string, unknown> | null = null) {
    const prisma: any = {
      ssoConfiguration: {
        findUnique: jest.fn(async () => existing),
        update: jest.fn(async ({ data }: any) => ({ ...existing, ...data })),
        create: jest.fn(async ({ data }: any) => ({ id: CONFIG_ID, isActive: true, enforced: false, jitEnabled: false, ...data })),
      },
      ssoIdentity: { findFirst: jest.fn(async () => null) },
    };
    const unused: any = {};
    const events: any = { record: jest.fn(async () => undefined) };
    const samlProvider = new SamlProviderService(prisma);
    const service = new EnterpriseSsoService(prisma, unused, unused, events, events, fakeCrypto as never, samlProvider);
    return { service, prisma };
  }

  const samlInput = {
    tenantId: TENANT,
    providerType: SsoProvider.SAML,
    actorId: 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',
    issuer: IDP_ISSUER,
    ssoUrl: 'https://idp.acme.test/sso',
    acsUrl: ACS,
    entityId: SP_ENTITY,
    certificate: KEYS.idpCert,
  };

  it('stores the SP key sealed with the tenant AAD and never returns it', async () => {
    const h = build();
    const view = await h.service.configureSso({
      ...samlInput,
      wantAssertionsEncrypted: true,
      spDecryptionPrivateKey: KEYS.spEncKey,
      spEncryptionCertificate: KEYS.spEncCert,
    });
    expect(view).toMatchObject({ wantAssertionsEncrypted: true, hasSpDecryptionKey: true, spEncryptionCertificate: KEYS.spEncCert.trim() });
    expect(JSON.stringify(view)).not.toContain('PRIVATE KEY');
    const stored = h.prisma.ssoConfiguration.create.mock.calls[0][0].data;
    expect(stored.spDecryptionKeyCiphertext).toEqual({ sealed: KEYS.spEncKey.trim(), aad: samlSpDecryptionKeyAad(TENANT) });
  });

  it('refuses a certificate that does not belong to the key', async () => {
    const h = build();
    await expect(
      h.service.configureSso({ ...samlInput, wantAssertionsEncrypted: true, spDecryptionPrivateKey: KEYS.spEncKey, spEncryptionCertificate: KEYS.attackerCert }),
    ).rejects.toThrow('spEncryptionCertificate does not belong to spDecryptionPrivateKey');
    expect(h.prisma.ssoConfiguration.create).not.toHaveBeenCalled();
  });

  it('refuses the opt-in without a key or without a certificate', async () => {
    const h = build();
    await expect(h.service.configureSso({ ...samlInput, wantAssertionsEncrypted: true, spEncryptionCertificate: KEYS.spEncCert })).rejects.toThrow(
      'spDecryptionPrivateKey is required',
    );
    await expect(h.service.configureSso({ ...samlInput, wantAssertionsEncrypted: true, spDecryptionPrivateKey: KEYS.spEncKey })).rejects.toThrow(
      'spEncryptionCertificate is required',
    );
  });

  it('refuses malformed, non-RSA and short keys', async () => {
    const h = build();
    const ec = generateKeyPairSync('ec', { namedCurve: 'P-256' }).privateKey.export({ type: 'pkcs8', format: 'pem' }).toString();
    const rsa1024 = generateKeyPairSync('rsa', { modulusLength: 1024 }).privateKey.export({ type: 'pkcs8', format: 'pem' }).toString();
    for (const key of ['not a key', ec, rsa1024]) {
      await expect(
        h.service.configureSso({ ...samlInput, wantAssertionsEncrypted: true, spDecryptionPrivateKey: key, spEncryptionCertificate: KEYS.spEncCert }),
      ).rejects.toThrow(BadRequestException);
    }
    expect(h.prisma.ssoConfiguration.create).not.toHaveBeenCalled();
  });

  it('re-checks the pair against the stored key when only the certificate changes', async () => {
    const existing = {
      id: CONFIG_ID,
      tenantId: TENANT,
      providerType: 'SAML',
      state: 'ENABLED',
      isActive: true,
      enforced: false,
      issuer: IDP_ISSUER,
      ssoUrl: 'https://idp.acme.test/sso',
      acsUrl: ACS,
      entityId: SP_ENTITY,
      certificate: KEYS.idpCert,
      wantAssertionsEncrypted: true,
      spDecryptionKeyCiphertext: fakeCrypto.encrypt(KEYS.spEncKey, samlSpDecryptionKeyAad(TENANT)),
      spEncryptionCertificate: KEYS.spEncCert,
    };
    const h = build(existing);
    await expect(h.service.configureSso({ ...samlInput, spEncryptionCertificate: KEYS.idpCert })).rejects.toThrow(
      'spEncryptionCertificate does not belong to spDecryptionPrivateKey',
    );
    await expect(h.service.configureSso({ ...samlInput, spEncryptionCertificate: KEYS.spEncCert })).resolves.toMatchObject({ hasSpDecryptionKey: true });
  });

  it('encrypted assertions are SAML-only', async () => {
    const h = build();
    await expect(
      h.service.configureSso({
        tenantId: TENANT,
        providerType: SsoProvider.OIDC,
        actorId: 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',
        issuer: 'https://idp.acme.test',
        clientId: 'c',
        clientSecret: 's',
        redirectUri: 'https://acme.app.test/api/auth/sso/callback',
        wantAssertionsEncrypted: true,
      }),
    ).rejects.toThrow('Encrypted assertions apply to SAML configurations only');
  });
});

