      sloUrl: IDP_SLO,
      logoutCallbackUrl: SP_SLO,
      hasSpSigningKey: true,
      spSigningCertificate: KEYS.spEncCert.trim(),
    });
    expect(JSON.stringify(view)).not.toContain('PRIVATE KEY');
    const stored = h.prisma.ssoConfiguration.create.mock.calls[0][0].data;
    expect(stored.spSigningKeyCiphertext).toEqual({ sealed: KEYS.spEncKey.trim(), aad: samlSpSigningKeyAad(TENANT) });
    expect(stored.sloUrl).toBe(IDP_SLO);
    expect(stored.logoutCallbackUrl).toBe(SP_SLO);
    // The audit record names the change, never the key.
    expect(JSON.stringify(h.events.record.mock.calls)).not.toContain('PRIVATE KEY');
  });

  it('a configuration without Single Logout reports it plainly', async () => {
    const h = build();
    const view = await h.service.configureSso({ ...samlInput });
    expect(view).toMatchObject({ sloUrl: null, logoutCallbackUrl: null, hasSpSigningKey: false, spSigningCertificate: null });
  });

  it('with an IdP SLO URL, our SLO URL, the key and the certificate are all required', async () => {
    const h = build();
    const { logoutCallbackUrl: _a, ...noCallback } = sloInput;
    const { spSigningPrivateKey: _b, ...noKey } = sloInput;
    const { spSigningCertificate: _c, ...noCert } = sloInput;
    await expect(h.service.configureSso({ ...samlInput, ...noCallback })).rejects.toThrow('logoutCallbackUrl is required when sloUrl is set');
    await expect(h.service.configureSso({ ...samlInput, ...noKey })).rejects.toThrow('spSigningPrivateKey is required when sloUrl is set');
    await expect(h.service.configureSso({ ...samlInput, ...noCert })).rejects.toThrow('spSigningCertificate is required when sloUrl is set');
    expect(h.prisma.ssoConfiguration.create).not.toHaveBeenCalled();
  });

  it('refuses a certificate that does not belong to the key, and an expired certificate', async () => {
    const h = build();
    await expect(h.service.configureSso({ ...samlInput, ...sloInput, spSigningCertificate: KEYS.attackerCert })).rejects.toThrow(
      'spSigningCertificate does not belong to spSigningPrivateKey',
    );
    await expect(h.service.configureSso({ ...samlInput, ...sloInput, spSigningCertificate: KEYS.expiredCert })).rejects.toThrow(
      'spSigningCertificate is not currently valid',
    );
    await expect(h.service.configureSso({ ...samlInput, ...sloInput, spSigningCertificate: 'not a certificate' })).rejects.toThrow(
      'spSigningCertificate is not a valid X.509 certificate',
    );
    expect(h.prisma.ssoConfiguration.create).not.toHaveBeenCalled();
  });

  it('refuses malformed, non-RSA and short signing keys before anything is sealed', async () => {
    const h = build();
    const ec = generateKeyPairSync('ec', { namedCurve: 'P-256' }).privateKey.export({ type: 'pkcs8', format: 'pem' }).toString();
    const rsa1024 = generateKeyPairSync('rsa', { modulusLength: 1024 }).privateKey.export({ type: 'pkcs8', format: 'pem' }).toString();
    for (const key of ['not a key', ec, rsa1024]) {
      await expect(h.service.configureSso({ ...samlInput, ...sloInput, spSigningPrivateKey: key })).rejects.toThrow(BadRequestException);
    }
    expect(h.prisma.ssoConfiguration.create).not.toHaveBeenCalled();
  });

  it('refuses non-https SLO URLs', async () => {
    const h = build();
    await expect(h.service.configureSso({ ...samlInput, ...sloInput, sloUrl: 'http://idp.acme.test/slo' })).rejects.toThrow(BadRequestException);
    await expect(h.service.configureSso({ ...samlInput, ...sloInput, logoutCallbackUrl: 'javascript:alert(1)' })).rejects.toThrow(BadRequestException);
    expect(h.prisma.ssoConfiguration.create).not.toHaveBeenCalled();
  });

  it('re-checks a new certificate against the stored key, and refuses a stored key sealed for another tenant', async () => {
    const h = build(existingWithSlo());
    await expect(h.service.configureSso({ ...samlInput, spSigningCertificate: KEYS.idpCert })).rejects.toThrow(
      'spSigningCertificate does not belong to spSigningPrivateKey',
    );
    await expect(h.service.configureSso({ ...samlInput, spSigningCertificate: KEYS.spEncCert })).resolves.toMatchObject({ hasSpSigningKey: true });

    const foreign = build(
      existingWithSlo({ spSigningKeyCiphertext: fakeCrypto.encrypt(KEYS.spEncKey, samlSpSigningKeyAad('99999999-9999-4999-8999-999999999999')) }),
    );
    await expect(foreign.service.configureSso({ ...samlInput, spSigningCertificate: KEYS.spEncCert })).rejects.toThrow(
      'The stored SP signing key cannot be read; upload spSigningPrivateKey again',
    );
  });

  it('an empty sloUrl turns Single Logout off without needing the other fields', async () => {
    const h = build(existingWithSlo());
    await expect(h.service.configureSso({ ...samlInput, sloUrl: '' })).resolves.toMatchObject({ sloUrl: null });
    expect(h.prisma.ssoConfiguration.update.mock.calls[0][0].data.sloUrl).toBeNull();
  });

  it('Single Logout settings are SAML-only', async () => {
    const h = build();
    const oidc = {
      tenantId: TENANT,
      providerType: SsoProvider.OIDC,
      actorId: 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',
      issuer: 'https://idp.acme.test',
      clientId: 'c',
      clientSecret: 's',
      redirectUri: 'https://acme.app.test/api/auth/sso/callback',
    };
    await expect(h.service.configureSso({ ...oidc, sloUrl: IDP_SLO })).rejects.toThrow('Single Logout settings apply to SAML configurations only');
    await expect(h.service.configureSso({ ...oidc, spSigningPrivateKey: KEYS.spEncKey })).rejects.toThrow(
      'spSigningPrivateKey applies to SAML configurations only',
    );
    expect(h.prisma.ssoConfiguration.create).not.toHaveBeenCalled();
  });
});

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { sanitizeSecurityMetadata } from './security.types';
import { randomUUID } from 'crypto';

/**
 * Immutable security audit trail with safe metadata, actor/tenant references, result, policy reference, and sanitized context.
 * Never stores passwords, raw API keys, refresh tokens, SAML assertions, OIDC tokens, private keys, provider secrets, recovery secrets.
 */
@Injectable()
export class SecurityAuditService {
  private readonly logger = new Logger(SecurityAuditService.name);

  constructor(private readonly prisma: PrismaService) {}

  async record(params: {
    tenantId: string;
    userId?: string;
    actorId?: string;
    actorType?: string;
    event: string;
    result?: string;
    policyVersion?: string;
    targetType?: string;
    targetId?: string;
    safeMetadata?: Record<string, any>;
    ipHash?: string;
    requestId?: string;
  }): Promise<void> {
    const safeMeta = params.safeMetadata ? sanitizeSecurityMetadata(params.safeMetadata) : {};

    try {
      await (this.prisma as any).securityAuditLog?.create({
        data: {
          id: randomUUID(),
          tenantId: params.tenantId,
          userId: params.userId || null,
          actorId: params.actorId || null,
          actorType: params.actorType || 'USER',
          event: params.event as any,
          result: params.result || 'SUCCESS',
          policyVersion: params.policyVersion || null,
          targetType: params.targetType || null,
          targetId: params.targetId || null,
          safeMetadata: safeMeta,
          ipHash: params.ipHash || null,
          requestId: params.requestId || null,
          createdAt: new Date(),
        },
      });

      this.logger.log(`Security audit recorded event=${params.event} tenant=${params.tenantId} actor=${params.actorId || 'system'} target=${params.targetType || 'none'}:${params.targetId || 'none'}`);

      // Also record to legacy auditLog for backward compatibility
      try {
        await (this.prisma as any).auditLog?.create({
          data: {
            id: randomUUID(),
            tenantId: params.tenantId,
            actorType: (params.actorType as any) || 'USER',
            actorId: params.actorId || null,
            action: params.event,
            outcome: (params.result as any) || 'SUCCESS',
            resourceType: params.targetType || 'Security',
            resourceId: params.targetId || params.userId || 'unknown',
            description: `Security ${params.event}`,
            metadata: safeMeta,
            ipHash: params.ipHash || null,
            requestId: params.requestId || null,
            createdAt: new Date(),
          },
        });
      } catch {}
    } catch (e: any) {
      this.logger.warn(`Failed to record security audit ${params.event}: ${e.message}`);
    }
  }

  async recordLogin(tenantId: string, userId: string, success: boolean, ipHash?: string, requestId?: string, deviceId?: string): Promise<void> {
    await this.record({
      tenantId,
      userId,
      actorId: userId,
      event: success ? 'LOGIN_SUCCESS' : 'LOGIN_FAILURE',
      result: success ? 'SUCCESS' : 'FAILURE',
      targetType: 'User',
      targetId: userId,
      safeMetadata: { userId, deviceId, success },
      ipHash,
      requestId,
    });
  }

  async recordMfa(tenantId: string, userId: string, factor: string, success: boolean, ipHash?: string, requestId?: string): Promise<void> {
    await this.record({
      tenantId,
      userId,
      actorId: userId,
      event: success ? 'MFA_SUCCESS' : 'MFA_FAILURE',
      result: success ? 'SUCCESS' : 'FAILURE',
      targetType: 'User',
      targetId: userId,
      safeMetadata: { factor, success },
      ipHash,
      requestId,
    });
  }

  async recordSso(tenantId: string, userId: string | undefined, providerType: string, success: boolean, ipHash?: string, requestId?: string): Promise<void> {
    await this.record({
      tenantId,
      userId,
      actorId: userId,
      event: success ? 'SSO_LOGIN_SUCCESS' : 'SSO_LOGIN_FAILURE',
      result: success ? 'SUCCESS' : 'FAILURE',
      targetType: 'SsoConfiguration',
      targetId: providerType,
      safeMetadata: { providerType, success },
      ipHash,
      requestId,
    });
  }

  async recordApiKey(tenantId: string, userId: string, keyId: string, action: 'CREATED' | 'ROTATED' | 'REVOKED', actorId: string, ipHash?: string, requestId?: string): Promise<void> {
    await this.record({
      tenantId,
      userId,
      actorId,
      event: `API_KEY_${action}`,
      result: 'SUCCESS',
      targetType: 'ApiKey',
      targetId: keyId,
      safeMetadata: { keyId, action },
      ipHash,
      requestId,
    });
  }

  async recordSession(tenantId: string, userId: string, sessionId: string, action: 'CREATED' | 'REVOKED' | 'SUSPICIOUS', actorId?: string, ipHash?: string, requestId?: string): Promise<void> {
    await this.record({
      tenantId,
      userId,
      actorId: actorId || userId,
      event: `SESSION_${action}`,
      result: action === 'SUSPICIOUS' ? 'FAILURE' : 'SUCCESS',
      targetType: 'Session',
      targetId: sessionId,
      safeMetadata: { sessionId, action },
      ipHash,
      requestId,
    });
  }

  async recordDevice(tenantId: string, userId: string, deviceId: string, action: 'REGISTERED' | 'TRUSTED' | 'REVOKED', actorId: string, ipHash?: string, requestId?: string): Promise<void> {
    await this.record({
      tenantId,
      userId,
      actorId,
      event: `DEVICE_${action}`,
      result: 'SUCCESS',
      targetType: 'Device',
      targetId: deviceId,
      safeMetadata: { deviceId, action },
      ipHash,
      requestId,
    });
  }

  async recordPolicyChange(tenantId: string, policyVersion: string, actorId: string, ipHash?: string, requestId?: string): Promise<void> {
    await this.record({
      tenantId,
      actorId,
      event: 'SECURITY_POLICY_CHANGED',
      result: 'SUCCESS',
      targetType: 'SecurityPolicy',
      targetId: policyVersion,
      policyVersion,
      safeMetadata: { policyVersion },
      ipHash,
      requestId,
    });
  }

  async listAuditLogs(tenantId: string, filters?: { userId?: string; event?: string; fromDate?: Date; toDate?: Date; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const offset = (page - 1) * limit;

    const where: any = { tenantId };
    if (filters?.userId) where.userId = filters.userId;
    if (filters?.event) where.event = filters.event;
    if (filters?.fromDate || filters?.toDate) {
      where.createdAt = {};
      if (filters.fromDate) where.createdAt.gte = filters.fromDate;
      if (filters.toDate) where.createdAt.lte = filters.toDate;
    }

    const [data, total] = await Promise.all([
      (this.prisma as any).securityAuditLog?.findMany({ where, orderBy: { createdAt: 'desc' }, skip: offset, take: limit }) || [],
      (this.prisma as any).securityAuditLog?.count({ where }) || 0,
    ]);

    return { data, total };
  }
}

// # Proves tenant-owned security-event records commit with sanitized webhook events

import { SecurityEventService } from './security-event.service';
import { SecurityEventType, SecurityRisk } from './security.types';
import { validateDeveloperEventPayload } from '../developer-platform/event-schemas/developer-event-schemas';

const TENANT_ID = '11111111-1111-4111-8111-111111111111';

function buildService(options: { failAppend?: boolean } = {}) {
  let persisted: any = null;
  const tx = {
    securityEvent: {
      create: jest.fn(async ({ data }: { data: Record<string, unknown> }) => {
        persisted = { ...data };
        return persisted;
      }),
    },
  };
  const prisma: any = {
    withTenantRls: jest.fn(async (_tenantId: string, work: (transaction: unknown) => Promise<unknown>) => {
      const before = persisted;
      try {
        return await work(tx);
      } catch (error) {
        persisted = before;
        throw error;
      }
    }),
    securityAuditLog: { create: jest.fn(async () => ({})) },
  };
  const outbox = {
    append: jest.fn(async (_transaction: unknown, _input: Record<string, unknown>) => {
      if (options.failAppend) throw new Error('outbox unavailable');
      return undefined;
    }),
  };
  const service = new SecurityEventService(prisma as never, outbox as never);
  return { service, prisma, tx, outbox, persisted: () => persisted };
}

describe('SecurityEventService outbox transaction', () => {
  it('records a tenant security event and its redacted public event atomically', async () => {
    const { service, prisma, tx, outbox, persisted } = buildService();
    await service.record({
      tenantId: TENANT_ID,
      userId: 'user-1',
      type: SecurityEventType.MFA_FAILURE,
      severity: SecurityRisk.HIGH,
      description: 'MFA verification failed.',
      safeMetadata: { factor: 'TOTP', token: 'must-not-leave-the-security-table' },
      requestId: 'request-1',
    });

    const securityEventId = persisted().id;
    expect(prisma.withTenantRls).toHaveBeenCalledWith(TENANT_ID, expect.any(Function));
    expect(tx.securityEvent.create).toHaveBeenCalledTimes(1);
    expect(outbox.append).toHaveBeenCalledWith(tx, expect.objectContaining({
      tenantId: TENANT_ID,
      aggregateType: 'security_event',
      aggregateId: securityEventId,
      eventType: 'security.event',
      idempotencyKey: `security-event:${securityEventId}:recorded`,
      correlationId: 'request-1',
      payload: {
        securityEventId,
        category: SecurityEventType.MFA_FAILURE,
        severity: 'WARNING',
      },
    }));
    const event = outbox.append.mock.calls[0]?.[1];
    expect(validateDeveloperEventPayload('security.event', event?.payload)).toEqual({ valid: true, errors: [] });
    expect(JSON.stringify(event)).not.toContain('must-not-leave-the-security-table');
  });

  it('propagates an outbox failure so the transaction rolls back instead of silently losing delivery', async () => {
    const { service, tx, persisted } = buildService({ failAppend: true });
    await expect(service.record({
      tenantId: TENANT_ID,
      type: SecurityEventType.LOGIN_SUCCESS,
      severity: SecurityRisk.LOW,
      description: 'Login success.',
    })).rejects.toThrow('outbox unavailable');

    expect(tx.securityEvent.create).toHaveBeenCalledTimes(1);
    expect(persisted()).toBeNull();
  });

  it('rejects an invalid non-null tenant instead of downgrading it to a platform event', async () => {
    const { service, prisma, outbox } = buildService();

    await expect(service.record({
      tenantId: 'not-a-tenant-uuid',
      type: SecurityEventType.LOGIN_FAILURE,
      severity: SecurityRisk.HIGH,
      description: 'Invalid tenant event.',
    })).rejects.toThrow('tenantId must be a UUID or null');

    expect(prisma.withTenantRls).not.toHaveBeenCalled();
    expect(outbox.append).not.toHaveBeenCalled();
  });

  it('rejects unknown severities instead of projecting them as informational', async () => {
    const { service, prisma, outbox } = buildService();

    await expect(service.record({
      tenantId: TENANT_ID,
      type: SecurityEventType.LOGIN_FAILURE,
      severity: 'UNRECOGNIZED' as SecurityRisk,
      description: 'Invalid severity event.',
    })).rejects.toThrow('severity is invalid');

    expect(prisma.withTenantRls).not.toHaveBeenCalled();
    expect(outbox.append).not.toHaveBeenCalled();
  });
});

// # Responsibility: record security events with tenant attribution and privacy-preserving identifiers.
import { Injectable, Logger, Optional } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OutboxService } from '../../infrastructure/outbox/outbox.service';
import { SecurityEventType, SecurityRisk, sanitizeSecurityMetadata } from './security.types';
import { createHash, randomUUID } from 'node:crypto';

const TENANT_UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function requireSecurityRisk(value: SecurityRisk | string): SecurityRisk {
  if ((Object.values(SecurityRisk) as string[]).includes(value)) {
    return value as SecurityRisk;
  }
  throw new Error('Security event severity is invalid; refusing to persist the event');
}

/**
 * Canonical security event recording for login, logout, MFA, SSO, API key, session, device, policy, and privileged administrative events.
 * Preserves existing SecurityEventsService logic, adds enterprise event types.
 */
@Injectable()
export class SecurityEventService {
  private readonly logger = new Logger(SecurityEventService.name);

  constructor(
    private readonly prisma: PrismaService,
    @Optional() private readonly outbox?: OutboxService,
  ) {}

  async record(input: {
    tenantId: string | null;
    userId?: string | null;
    type: SecurityEventType | string;
    severity: SecurityRisk | string;
    description: string;
    safeMetadata?: Record<string, any> | null;
    metadata?: Record<string, any> | null;
    ipHash?: string | null;
    userAgent?: string | null;
    requestId?: string | null;
  }): Promise<void> {
    const rawMeta = (input as any).safeMetadata || (input as any).metadata || {};
    const safeMeta = rawMeta ? sanitizeSecurityMetadata(rawMeta) : {};

    const tenantScoped = input.tenantId !== null;
    if (tenantScoped && !TENANT_UUID_PATTERN.test(input.tenantId as string)) {
      throw new Error('Security event tenantId must be a UUID or null; refusing to persist the event');
    }
    const severity = requireSecurityRisk(input.severity);
    const eventData = {
      id: randomUUID(),
      tenantId: input.tenantId,
      userId: input.userId || null,
      type: input.type as any,
      severity,
      description: input.description.substring(0, 500),
      metadata: safeMeta,
      ipHash: input.ipHash || null,
      userAgent: input.userAgent ? input.userAgent.substring(0, 512) : null,
      requestId: input.requestId || null,
      createdAt: new Date(),
    };

    try {
      if (tenantScoped) {
        if (!this.outbox) {
          throw new Error('Transactional outbox is unavailable; refusing tenant security event without its security.event event');
        }
        const publicSeverity = severity === SecurityRisk.CRITICAL
          ? 'CRITICAL'
          : severity === SecurityRisk.HIGH || severity === SecurityRisk.MEDIUM
            ? 'WARNING'
            : 'INFO';
        await this.prisma.withTenantRls(input.tenantId!, async (tx) => {
          await (tx as any).securityEvent.create({ data: eventData });
          await this.outbox!.append(tx, {
            tenantId: input.tenantId!,
            aggregateType: 'security_event',
            aggregateId: eventData.id,
            eventType: 'security.event',
            idempotencyKey: `security-event:${eventData.id}:recorded`,
            correlationId: input.requestId && input.requestId.length <= 64 ? input.requestId : null,
            occurredAt: eventData.createdAt,
            payload: {
              securityEventId: eventData.id,
              category: String(input.type).slice(0, 96),
              severity: publicSeverity,
            },
          });
        });
      } else {
        // Platform-level events have no tenant webhook audience, but remain persisted locally.
        try {
          await (this.prisma as any).securityEvent?.create({ data: eventData });
        } catch (error) {
          this.logger.warn(`Failed to persist platform security event: ${(error as Error).message}`);
        }
      }

      // The enterprise audit mirror remains best-effort; the tenant SecurityEvent row and outbox
      // record above are the atomic developer-webhook source of truth.
      try {
        await (this.prisma as any).securityAuditLog?.create({
          data: {
            id: randomUUID(),
            tenantId: input.tenantId || 'platform',
            userId: input.userId || null,
            actorId: input.userId || null,
            actorType: 'USER',
            event: this.mapToEnterpriseCategory(input.type as any),
            result: severity === SecurityRisk.CRITICAL || input.type.includes('FAILURE') ? 'FAILURE' : 'SUCCESS',
            safeMetadata: safeMeta,
            ipHash: input.ipHash || null,
            requestId: input.requestId || null,
            createdAt: new Date(),
          },
        });
      } catch {}

      const logPayload = {
        event: 'security.event',
        type: input.type,
        severity,
        tenantId: input.tenantId,
        userId: input.userId,
        requestId: input.requestId,
      };
      if (severity === SecurityRisk.CRITICAL) {
        this.logger.error(logPayload, input.description);
      } else if (severity === SecurityRisk.HIGH) {
        this.logger.warn(logPayload, input.description);
      } else {
        this.logger.log(`${input.type} tenant=${input.tenantId} user=${input.userId} ${input.description}`);
      }
    } catch (error) {
      this.logger.error(`Failed to record security event ${input.type}: ${(error as Error).message}`);
      if (tenantScoped) throw error;
    }
  }

  async recordLoginSuccess(tenantId: string, userId: string, ipHash?: string, requestId?: string, deviceId?: string): Promise<void> {
    await this.record({
      tenantId,
      userId,
      type: SecurityEventType.LOGIN_SUCCESS,
      severity: SecurityRisk.LOW,
      description: `Login success user=${userId} device=${deviceId || 'unknown'}`,
      safeMetadata: { userId, deviceId },
      ipHash,
      requestId,
    });
  }

  async recordLoginFailure(tenantId: string, email: string, ipHash?: string, requestId?: string, reason?: string): Promise<void> {
    await this.record({
      tenantId,
      type: SecurityEventType.LOGIN_FAILURE,
      severity: SecurityRisk.MEDIUM,
      description: `Login failure emailHash=${this.hashEmail(email)} reason=${reason || 'unknown'}`,
      safeMetadata: { emailDomain: email.split('@')[1], reason },
      ipHash,
      requestId,
    });
  }

  async recordLogout(tenantId: string, userId: string, sessionId?: string, ipHash?: string, requestId?: string): Promise<void> {
    await this.record({
      tenantId,
      userId,
      type: SecurityEventType.LOGOUT,
      severity: SecurityRisk.LOW,
      description: `Logout user=${userId} session=${sessionId || 'unknown'}`,
      safeMetadata: { userId, sessionId },
      ipHash,
      requestId,
    });
  }

  async recordMfaSuccess(tenantId: string, userId: string, factor: string, ipHash?: string, requestId?: string): Promise<void> {
    await this.record({
      tenantId,
      userId,
      type: SecurityEventType.MFA_SUCCESS,
      severity: SecurityRisk.LOW,
      description: `MFA success user=${userId} factor=${factor}`,
      safeMetadata: { userId, factor },
      ipHash,
      requestId,
    });
  }

  async recordMfaFailure(tenantId: string, userId: string, factor: string, ipHash?: string, requestId?: string, reason?: string): Promise<void> {
    await this.record({
      tenantId,
      userId,
      type: SecurityEventType.MFA_FAILURE,
      severity: SecurityRisk.MEDIUM,
      description: `MFA failure user=${userId} factor=${factor} reason=${reason || 'unknown'}`,
      safeMetadata: { userId, factor, reason },
      ipHash,
      requestId,
    });
  }

  async listEvents(tenantId: string, filters?: { userId?: string; type?: string; severity?: string; fromDate?: Date; toDate?: Date; page?: number; limit?: number }): Promise<{ data: any[]; total: number; page: number; limit: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const offset = (page - 1) * limit;

    const where: any = { tenantId };
    if (filters?.userId) where.userId = filters.userId;
    if (filters?.type) where.type = filters.type;
    if (filters?.severity) where.severity = filters.severity;
    if (filters?.fromDate || filters?.toDate) {
      where.createdAt = {};
      if (filters.fromDate) where.createdAt.gte = filters.fromDate;
      if (filters.toDate) where.createdAt.lte = filters.toDate;
    }

    const [data, total] = await Promise.all([
      (this.prisma as any).securityEvent?.findMany({ where, orderBy: { createdAt: 'desc' }, skip: offset, take: limit }) || [],
      (this.prisma as any).securityEvent?.count({ where }) || 0,
    ]);

    return { data, total, page, limit };
  }

  // Backward compatibility aliases for old SecurityEventsService
  async list(filter: any): Promise<any> {
    const tenantId = filter?.tenantId || 'platform';
    const result = await this.listEvents(tenantId, {
      userId: filter?.userId,
      type: filter?.type,
      severity: filter?.severity,
      page: filter?.page,
      limit: filter?.limit,
    });
    return { items: result.data, pagination: { page: result.page, limit: result.limit, totalItems: result.total } };
  }

  async resolve(tenantId: string, eventId: string, resolvedById: string, resolution: string): Promise<void> {
    try {
      await (this.prisma as any).securityEvent?.updateMany({
        where: { id: eventId, tenantId },
        data: { resolved: true, resolvedAt: new Date(), resolvedById, resolution: resolution.substring(0, 500) },
      });
    } catch {}
  }

  private mapToEnterpriseCategory(type: string): any {
    const mapping: Record<string, string> = {
      [SecurityEventType.LOGIN_SUCCESS]: 'LOGIN_SUCCESS',
      [SecurityEventType.LOGIN_FAILURE]: 'LOGIN_FAILURE',
      [SecurityEventType.LOGOUT]: 'LOGOUT',
      [SecurityEventType.MFA_REQUIRED]: 'MFA_REQUIRED',
      [SecurityEventType.MFA_SUCCESS]: 'MFA_SUCCESS',
      [SecurityEventType.MFA_FAILURE]: 'MFA_FAILURE',
      [SecurityEventType.SSO_LOGIN_STARTED]: 'SSO_LOGIN_STARTED',
      [SecurityEventType.SSO_LOGIN_SUCCESS]: 'SSO_LOGIN_SUCCESS',
      [SecurityEventType.SSO_LOGIN_FAILURE]: 'SSO_LOGIN_FAILURE',
      [SecurityEventType.API_KEY_CREATED]: 'API_KEY_CREATED',
      [SecurityEventType.API_KEY_ROTATED]: 'API_KEY_ROTATED',
      [SecurityEventType.API_KEY_REVOKED]: 'API_KEY_REVOKED',
      [SecurityEventType.SESSION_CREATED]: 'SESSION_CREATED',
      [SecurityEventType.SESSION_REVOKED]: 'SESSION_REVOKED',
      [SecurityEventType.SESSION_SUSPICIOUS]: 'SESSION_SUSPICIOUS',
      [SecurityEventType.DEVICE_REGISTERED]: 'DEVICE_REGISTERED',
      [SecurityEventType.DEVICE_TRUSTED]: 'DEVICE_TRUSTED',
      [SecurityEventType.DEVICE_REVOKED]: 'DEVICE_REVOKED',
      [SecurityEventType.SECURITY_POLICY_CHANGED]: 'SECURITY_POLICY_CHANGED',
      [SecurityEventType.PRIVILEGED_ACTION]: 'PRIVILEGED_ACTION',
      [SecurityEventType.SECURITY_ALERT]: 'SECURITY_ALERT',
    };
    return mapping[type] || 'SECURITY_ALERT';
  }

  private hashEmail(email: string): string {
    return createHash('sha256').update(email.toLowerCase()).digest('hex').substring(0, 8);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { SecurityPolicy } from './security.types';
import { randomUUID } from 'crypto';

/**
 * Resolves tenant/platform security policy: MFA requirements, session duration, idle timeout, password/security requirements, device trust, API-key rules, and SSO enforcement.
 * Policy precedence explicit, tenant cannot weaken mandatory platform-wide security.
 */
@Injectable()
export class SecurityPolicyService {
  private readonly logger = new Logger(SecurityPolicyService.name);
  private readonly platformPolicy: SecurityPolicy;

  constructor(private readonly prisma: PrismaService) {
    this.platformPolicy = {
      id: 'platform_default',
      tenantId: null,
      policyVersion: process.env.SECURITY_POLICY_VERSION || 'v1.0.0',
      mfaRequired: process.env.SECURITY_MFA_REQUIRED === 'true',
      mfaForPrivilegedRoles: process.env.SECURITY_MFA_PRIVILEGED !== 'false',
      mfaForSensitiveOperations: process.env.SECURITY_MFA_SENSITIVE !== 'false',
      sessionAbsoluteTimeoutSec: parseInt(process.env.SECURITY_SESSION_ABSOLUTE_TIMEOUT || '86400', 10),
      sessionIdleTimeoutSec: parseInt(process.env.SECURITY_SESSION_IDLE_TIMEOUT || '1800', 10),
      maxConcurrentSessions: parseInt(process.env.SECURITY_MAX_CONCURRENT_SESSIONS || '5', 10),
      deviceTrustDurationDays: parseInt(process.env.SECURITY_DEVICE_TRUST_DAYS || '30', 10),
      apiKeyExpirationDays: parseInt(process.env.SECURITY_API_KEY_EXPIRY_DAYS || '90', 10),
      apiKeyRotationDays: parseInt(process.env.SECURITY_API_KEY_ROTATION_DAYS || '30', 10),
      ssoEnforced: process.env.SECURITY_SSO_ENFORCED === 'true',
      allowedSsoDomains: (process.env.SECURITY_ALLOWED_SSO_DOMAINS || '').split(',').map((s) => s.trim()).filter(Boolean),
      jitProvisioning: process.env.SECURITY_JIT_ENABLED === 'true',
      privilegedReauthRequired: process.env.SECURITY_PRIVILEGED_REAUTH !== 'false',
      securityNotifications: process.env.SECURITY_NOTIFICATIONS !== 'false',
      passwordMinLength: parseInt(process.env.SECURITY_PASSWORD_MIN_LENGTH || '12', 10),
      isActive: true,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
  }

  async getEffectivePolicy(params: { tenantId?: string; userId?: string }): Promise<SecurityPolicy> {
    try {
      if (params.tenantId) {
        const tenantPolicy = await (this.prisma as any).securityPolicy?.findFirst({
          where: { tenantId: params.tenantId, isActive: true },
          orderBy: { createdAt: 'desc' },
        });
        if (tenantPolicy) {
          return this.mergeWithPlatform(this.mapToPolicy(tenantPolicy));
        }
      }

      const platformPolicy = await (this.prisma as any).securityPolicy?.findFirst({
        where: { tenantId: null, isActive: true },
        orderBy: { createdAt: 'desc' },
      });
      if (platformPolicy) {
        return this.mapToPolicy(platformPolicy);
      }
    } catch (e: any) {
      this.logger.warn(`Failed to fetch security policy from DB: ${e.message}`);
    }
    return this.platformPolicy;
  }

  async getPlatformPolicy(): Promise<SecurityPolicy> {
    return this.getEffectivePolicy({});
  }

  async getTenantPolicy(tenantId: string): Promise<SecurityPolicy> {
    return this.getEffectivePolicy({ tenantId });
  }

  async listPolicies(): Promise<SecurityPolicy[]> {
    try {
      const records = await (this.prisma as any).securityPolicy?.findMany({ orderBy: { createdAt: 'desc' } }) || [];
      return records.map((r: any) => this.mapToPolicy(r));
    } catch {
      return [this.platformPolicy];
    }
  }

  async createOrUpdatePolicy(input: {
    tenantId?: string | null;
    policyVersion: string;
    mfaRequired?: boolean;
    mfaForPrivilegedRoles?: boolean;
    mfaForSensitiveOperations?: boolean;
    sessionAbsoluteTimeoutSec?: number;
    sessionIdleTimeoutSec?: number;
    maxConcurrentSessions?: number;
    deviceTrustDurationDays?: number;
    apiKeyExpirationDays?: number;
    apiKeyRotationDays?: number;
    ssoEnforced?: boolean;
    allowedSsoDomains?: string[];
    jitProvisioning?: boolean;
    privilegedReauthRequired?: boolean;
    securityNotifications?: boolean;
    passwordMinLength?: number;
    actorId: string;
  }): Promise<SecurityPolicy> {
    const tenantId = input.tenantId || null;

    // Enforce platform mandatory requirements cannot be weakened by tenant
    if (tenantId) {
      const platform = await this.getPlatformPolicy();
      if (platform.mfaRequired && input.mfaRequired === false) {
        throw new Error('Tenant cannot disable MFA when platform requires it');
      }
      if (platform.ssoEnforced && input.ssoEnforced === false) {
        throw new Error('Tenant cannot disable SSO enforcement when platform enforces it');
      }
      if (input.sessionAbsoluteTimeoutSec && input.sessionAbsoluteTimeoutSec > platform.sessionAbsoluteTimeoutSec) {
        throw new Error('Tenant cannot set longer absolute timeout than platform maximum');
      }
      if (input.passwordMinLength && input.passwordMinLength < platform.passwordMinLength) {
        throw new Error('Tenant cannot set weaker password policy than platform minimum');
      }
    }

    try {
      const existing = await (this.prisma as any).securityPolicy?.findFirst({
        where: { tenantId, policyVersion: input.policyVersion },
      });

      const data = {
        tenantId,
        policyVersion: input.policyVersion,
        mfaRequired: input.mfaRequired ?? this.platformPolicy.mfaRequired,
        mfaForPrivilegedRoles: input.mfaForPrivilegedRoles ?? this.platformPolicy.mfaForPrivilegedRoles,
        mfaForSensitiveOperations: input.mfaForSensitiveOperations ?? this.platformPolicy.mfaForSensitiveOperations,
        sessionAbsoluteTimeoutSec: input.sessionAbsoluteTimeoutSec ?? this.platformPolicy.sessionAbsoluteTimeoutSec,
        sessionIdleTimeoutSec: input.sessionIdleTimeoutSec ?? this.platformPolicy.sessionIdleTimeoutSec,
        maxConcurrentSessions: input.maxConcurrentSessions ?? this.platformPolicy.maxConcurrentSessions,
        deviceTrustDurationDays: input.deviceTrustDurationDays ?? this.platformPolicy.deviceTrustDurationDays,
        apiKeyExpirationDays: input.apiKeyExpirationDays ?? this.platformPolicy.apiKeyExpirationDays,
        apiKeyRotationDays: input.apiKeyRotationDays ?? this.platformPolicy.apiKeyRotationDays,
        ssoEnforced: input.ssoEnforced ?? this.platformPolicy.ssoEnforced,
        allowedSsoDomains: input.allowedSsoDomains ?? this.platformPolicy.allowedSsoDomains,
        jitProvisioning: input.jitProvisioning ?? this.platformPolicy.jitProvisioning,
        privilegedReauthRequired: input.privilegedReauthRequired ?? this.platformPolicy.privilegedReauthRequired,
        securityNotifications: input.securityNotifications ?? this.platformPolicy.securityNotifications,
        passwordMinLength: input.passwordMinLength ?? this.platformPolicy.passwordMinLength,
        isActive: true,
        updatedAt: new Date(),
      };

      let record: any;
      if (existing) {
        record = await (this.prisma as any).securityPolicy?.update({
          where: { id: existing.id },
          data,
        });
      } else {
        record = await (this.prisma as any).securityPolicy?.create({
          data: { id: randomUUID(), ...data, createdAt: new Date() },
        });
      }
      if (record) return this.mapToPolicy(record);
    } catch (e: any) {
      this.logger.warn(`Failed to create/update security policy: ${e.message}`);
    }

    return {
      ...this.platformPolicy,
      tenantId,
      policyVersion: input.policyVersion,
      mfaRequired: input.mfaRequired ?? this.platformPolicy.mfaRequired,
      ssoEnforced: input.ssoEnforced ?? this.platformPolicy.ssoEnforced,
    };
  }

  private mergeWithPlatform(tenantPolicy: SecurityPolicy): SecurityPolicy {
    // Platform mandatory requirements take precedence
    return {
      ...tenantPolicy,
      mfaRequired: this.platformPolicy.mfaRequired || tenantPolicy.mfaRequired,
      mfaForPrivilegedRoles: this.platformPolicy.mfaForPrivilegedRoles || tenantPolicy.mfaForPrivilegedRoles,
      mfaForSensitiveOperations: this.platformPolicy.mfaForSensitiveOperations || tenantPolicy.mfaForSensitiveOperations,
      ssoEnforced: this.platformPolicy.ssoEnforced || tenantPolicy.ssoEnforced,
      sessionAbsoluteTimeoutSec: Math.min(this.platformPolicy.sessionAbsoluteTimeoutSec, tenantPolicy.sessionAbsoluteTimeoutSec),
      passwordMinLength: Math.max(this.platformPolicy.passwordMinLength, tenantPolicy.passwordMinLength),
      // Tenant can be stricter on idle timeout (shorter)
      sessionIdleTimeoutSec: Math.min(this.platformPolicy.sessionIdleTimeoutSec, tenantPolicy.sessionIdleTimeoutSec),
    };
  }

  private mapToPolicy(raw: any): SecurityPolicy {
    return {
      id: raw.id,
      tenantId: raw.tenantId || null,
      policyVersion: raw.policyVersion,
      mfaRequired: raw.mfaRequired,
      mfaForPrivilegedRoles: raw.mfaForPrivilegedRoles,
      mfaForSensitiveOperations: raw.mfaForSensitiveOperations,
      sessionAbsoluteTimeoutSec: raw.sessionAbsoluteTimeoutSec,
      sessionIdleTimeoutSec: raw.sessionIdleTimeoutSec,
      maxConcurrentSessions: raw.maxConcurrentSessions,
      deviceTrustDurationDays: raw.deviceTrustDurationDays,
      apiKeyExpirationDays: raw.apiKeyExpirationDays,
      apiKeyRotationDays: raw.apiKeyRotationDays,
      ssoEnforced: raw.ssoEnforced,
      allowedSsoDomains: raw.allowedSsoDomains || [],
      jitProvisioning: raw.jitProvisioning,
      privilegedReauthRequired: raw.privilegedReauthRequired,
      securityNotifications: raw.securityNotifications,
      passwordMinLength: raw.passwordMinLength,
      isActive: raw.isActive,
      createdAt: raw.createdAt ? new Date(raw.createdAt).toISOString() : new Date().toISOString(),
      updatedAt: raw.updatedAt ? new Date(raw.updatedAt).toISOString() : new Date().toISOString(),
    };
  }
}

import { Injectable, Logger, Optional } from '@nestjs/common';
import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { SecurityPolicyService } from './security-policy.service';
import { SecurityEventService } from './security-event.service';
import { CacheService } from '../../infrastructure/redis/cache.service';
import { SecurityRisk, SecurityDecision, SecurityEventType } from './security.types';
import { randomUUID } from 'crypto';
import { isRecordNotFound } from '../../common/errors/prisma-not-found';

/**
 * Detects suspicious login/session/API-key/device patterns from existing security events without becoming a second auth engine.
 * Preserves existing SuspiciousLoginDetector logic, extends with enterprise threat signals.
 */
@Injectable()
export class SecurityThreatDetectionService {
  private readonly logger = new Logger(SecurityThreatDetectionService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly policyService: SecurityPolicyService,
    private readonly eventService: SecurityEventService,
    @Optional() private readonly cache?: CacheService,
  ) {}

  async detectThreats(params: { tenantId: string; userId?: string; fromDate?: Date; toDate?: Date }): Promise<{
    signals: { ruleId: string; riskLevel: SecurityRisk; decision: SecurityDecision; summary: string; recommendedAction: string; sourceEventIds: string[]; policyVersion: string }[];
    total: number;
  }> {
    const from = params.fromDate || new Date(Date.now() - 24 * 60 * 60 * 1000);
    const to = params.toDate || new Date();
    const policy = await this.policyService.getEffectivePolicy({ tenantId: params.tenantId });

    const signals: any[] = [];

    // Fetch security events for analysis
    let events: any[] = [];
    try {
      events = await (this.prisma as any).securityEvent?.findMany({
        where: { tenantId: params.tenantId, ...(params.userId ? { userId: params.userId } : {}), createdAt: { gte: from, lte: to } },
        orderBy: { createdAt: 'desc' },
        take: 500,
      }) || [];
    } catch {
      events = [];
    }

    // Rule: repeated failed login
    const failedLogins = events.filter((e: any) => e.type === 'LOGIN_FAILURE' || e.type === SecurityEventType.LOGIN_FAILURE);
    if (failedLogins.length >= 5) {
      signals.push({
        ruleId: 'REPEATED_FAILED_LOGIN',
        riskLevel: failedLogins.length >= 10 ? SecurityRisk.HIGH : SecurityRisk.MEDIUM,
        decision: failedLogins.length >= 10 ? SecurityDecision.DENY : SecurityDecision.REVIEW_REQUIRED,
        summary: `${failedLogins.length} failed login attempts in last 24h`,
        recommendedAction: failedLogins.length >= 10 ? 'BLOCK_IP_AND_REQUIRE_MFA' : 'REQUIRE_MFA_AND_NOTIFY',
        sourceEventIds: failedLogins.slice(0, 10).map((e: any) => e.id),
        policyVersion: policy.policyVersion,
      });
    }

    // Rule: repeated MFA failure
    const mfaFailures = events.filter((e: any) => e.type === SecurityEventType.MFA_FAILURE);
    if (mfaFailures.length >= 3) {
      signals.push({
        ruleId: 'REPEATED_MFA_FAILURE',
        riskLevel: mfaFailures.length >= 5 ? SecurityRisk.HIGH : SecurityRisk.MEDIUM,
        decision: SecurityDecision.SUSPICIOUS,
        summary: `${mfaFailures.length} MFA failures in last 24h`,
        recommendedAction: 'REQUIRE_RECOVERY_AND_NOTIFY',
        sourceEventIds: mfaFailures.slice(0, 10).map((e: any) => e.id),
        policyVersion: policy.policyVersion,
      });
    }

    // Rule: API-key abuse - unusual spike
    const apiKeyCreations = events.filter((e: any) => e.type === SecurityEventType.API_KEY_CREATED);
    if (apiKeyCreations.length >= 5) {
      signals.push({
        ruleId: 'API_KEY_ABUSE',
        riskLevel: SecurityRisk.MEDIUM,
        decision: SecurityDecision.REVIEW_REQUIRED,
        summary: `${apiKeyCreations.length} API keys created in last 24h`,
        recommendedAction: 'REVIEW_API_KEY_SCOPES',
        sourceEventIds: apiKeyCreations.slice(0, 10).map((e: any) => e.id),
        policyVersion: policy.policyVersion,
      });
    }

    // Rule: revoked key reuse attempt
    const revokedReuse = events.filter((e: any) => e.type === 'API_KEY_REVOKED_REUSE' || (e.description && e.description.includes('REVOKED')));
    if (revokedReuse.length > 0) {
      signals.push({
        ruleId: 'REVOKED_KEY_REUSE',
        riskLevel: SecurityRisk.HIGH,
        decision: SecurityDecision.DENY,
        summary: `Attempt to use revoked API key detected`,
        recommendedAction: 'BLOCK_AND_ALERT',
        sourceEventIds: revokedReuse.slice(0, 5).map((e: any) => e.id),
        policyVersion: policy.policyVersion,
      });
    }

    // Rule: expired key use
    const expiredUse = events.filter((e: any) => e.type === 'API_KEY_EXPIRED_USE');
    if (expiredUse.length > 0) {
      signals.push({
        ruleId: 'EXPIRED_KEY_USE',
        riskLevel: SecurityRisk.MEDIUM,
        decision: SecurityDecision.DENY,
        summary: `Attempt to use expired API key`,
        recommendedAction: 'ROTATE_KEY_AND_NOTIFY',
        sourceEventIds: expiredUse.slice(0, 5).map((e: any) => e.id),
        policyVersion: policy.policyVersion,
      });
    }

    // Rule: impossible session state - session created and revoked quickly
    const sessionCreated = events.filter((e: any) => e.type === SecurityEventType.SESSION_CREATED);
    const sessionRevoked = events.filter((e: any) => e.type === SecurityEventType.SESSION_REVOKED);
    if (sessionCreated.length >= 10 && sessionRevoked.length >= 10) {
      signals.push({
        ruleId: 'IMPOSSIBLE_SESSION_STATE',
        riskLevel: SecurityRisk.MEDIUM,
        decision: SecurityDecision.SUSPICIOUS,
        summary: `High session churn: ${sessionCreated.length} created, ${sessionRevoked.length} revoked in 24h`,
        recommendedAction: 'REVIEW_SESSION_ACTIVITY',
        sourceEventIds: [...sessionCreated.slice(0, 5), ...sessionRevoked.slice(0, 5)].map((e: any) => e.id),
        policyVersion: policy.policyVersion,
      });
    }

    // Rule: repeated SSO failures
    const ssoFailures = events.filter((e: any) => e.type === SecurityEventType.SSO_LOGIN_FAILURE);
    if (ssoFailures.length >= 3) {
      signals.push({
        ruleId: 'REPEATED_SSO_FAILURES',
        riskLevel: ssoFailures.length >= 5 ? SecurityRisk.HIGH : SecurityRisk.MEDIUM,
        decision: SecurityDecision.REVIEW_REQUIRED,
        summary: `${ssoFailures.length} SSO login failures in 24h`,
        recommendedAction: 'CHECK_SSO_CONFIG_AND_IDP',
        sourceEventIds: ssoFailures.slice(0, 10).map((e: any) => e.id),
        policyVersion: policy.policyVersion,
      });
    }

    // Rule: excessive session creation
    if (sessionCreated.length >= 20) {
      signals.push({
        ruleId: 'EXCESSIVE_SESSION_CREATION',
        riskLevel: SecurityRisk.MEDIUM,
        decision: SecurityDecision.SUSPICIOUS,
        summary: `Excessive session creation: ${sessionCreated.length} sessions in 24h`,
        recommendedAction: 'ENFORCE_CONCURRENT_LIMIT_AND_REVIEW',
        sourceEventIds: sessionCreated.slice(0, 10).map((e: any) => e.id),
        policyVersion: policy.policyVersion,
      });
    }

    // Rule: new device + high risk (preserve existing SuspiciousLoginDetector logic)
    const newDeviceLogins = events.filter((e: any) => e.type === 'NEW_DEVICE_LOGIN' || e.type === SecurityEventType.DEVICE_REGISTERED);
    if (newDeviceLogins.length >= 3) {
      signals.push({
        ruleId: 'NEW_DEVICE_BURST',
        riskLevel: SecurityRisk.MEDIUM,
        decision: SecurityDecision.STEP_UP_REQUIRED,
        summary: `${newDeviceLogins.length} new device logins in 24h`,
        recommendedAction: 'REQUIRE_MFA_FOR_NEW_DEVICES',
        sourceEventIds: newDeviceLogins.slice(0, 10).map((e: any) => e.id),
        policyVersion: policy.policyVersion,
      });
    }

    // Persist signals
    for (const signal of signals) {
      try {
        await (this.prisma as any).securityThreatSignal?.create({
          data: {
            id: randomUUID(),
            tenantId: params.tenantId,
            userId: params.userId || null,
            ruleId: signal.ruleId,
            riskLevel: signal.riskLevel,
            decision: signal.decision,
            sourceEventIds: signal.sourceEventIds,
            safeSummary: signal.summary.substring(0, 1000),
            policyVersion: signal.policyVersion,
            createdAt: new Date(),
          },
        });

        await this.eventService.record({
          tenantId: params.tenantId,
          userId: params.userId || null,
          type: SecurityEventType.SECURITY_ALERT,
          severity: signal.riskLevel,
          description: `Threat detected rule=${signal.ruleId} ${signal.summary}`,
          safeMetadata: { ruleId: signal.ruleId, riskLevel: signal.riskLevel, decision: signal.decision, recommendedAction: signal.recommendedAction },
        });
      } catch (e: any) {
        this.logger.warn(`Failed to persist threat signal ${signal.ruleId}: ${e.message}`);
      }
    }

    this.logger.log(`Threat detection completed tenant=${params.tenantId} signals=${signals.length} eventsScanned=${events.length}`);

    return { signals, total: signals.length };
  }

  async listThreats(tenantId: string, filters?: { userId?: string; riskLevel?: SecurityRisk; ruleId?: string; resolved?: boolean; page?: number; limit?: number }): Promise<{ data: any[]; total: number }> {
    const page = filters?.page || 1;
    const limit = filters?.limit || 20;
    const offset = (page - 1) * limit;

    const where: any = { tenantId };
    if (filters?.userId) where.userId = filters.userId;
    if (filters?.riskLevel) where.riskLevel = filters.riskLevel;
    if (filters?.ruleId) where.ruleId = filters.ruleId;
    if (filters?.resolved !== undefined) where.resolved = filters.resolved;

    const [data, total] = await Promise.all([
      (this.prisma as any).securityThreatSignal?.findMany({ where, orderBy: { createdAt: 'desc' }, skip: offset, take: limit }) || [],
      (this.prisma as any).securityThreatSignal?.count({ where }) || 0,
    ]);

    return { data, total };
  }

  async resolveThreat(signalId: string, tenantId: string, resolverId: string, resolution: string): Promise<any | null> {
    try {
      const updated = await (this.prisma as any).securityThreatSignal?.update({
        where: { id: signalId },
        data: { resolved: true, resolvedAt: new Date(), resolvedById: resolverId },
      });

      await this.eventService.record({
        tenantId,
        userId: resolverId,
        type: SecurityEventType.SECURITY_ALERT,
        severity: SecurityRisk.LOW,
        description: `Threat signal resolved signalId=${signalId} resolution=${resolution}`,
        safeMetadata: { signalId, resolution: resolution.substring(0, 500) },
      });

      return updated || null;
    } catch (e: any) {
      if (isRecordNotFound(e)) return null;
      throw e;
    }
  }

  // Backward compatibility: old SuspiciousLoginDetector API used by auth.service.ts
  async assess(signals: { tenantId: string; userId: string; emailIndex: string; ipHash: string; deviceId: string; userAgent: string | null; requestId: string; geoLabel: string | null }): Promise<{ isNewDevice: boolean; isNewIp: boolean; recentFailureCount: number; distinctIpCount: number; riskScore: number; requiresNotification: boolean }> {
    return this.assessLoginRisk(signals);
  }

  async recordFailure(tenantId: string, ipHash: string, requestId: string): Promise<void> {
    try {
      if (this.cache) {
        const key = `security:failed-ip:${tenantId}:${ipHash}`;
        const count = await this.cache.increment(key, 900);
        if (count === 25) {
          await this.eventService.record({
            tenantId,
            type: SecurityEventType.SECURITY_ALERT,
            severity: SecurityRisk.HIGH,
            description: 'A single client produced 25 failed sign-in attempts within 15 minutes.',
            safeMetadata: { windowSeconds: 900, attempts: count, ipHash, requestId },
          });
        }
      }
    } catch (e: any) {
      this.logger.warn(`recordFailure failed: ${e.message}`);
    }
  }

  // Preserve existing suspicious login detection logic
  async assessLoginRisk(signals: { tenantId: string; userId: string; emailIndex: string; ipHash: string; deviceId: string; userAgent: string | null; requestId: string; geoLabel: string | null }): Promise<{ isNewDevice: boolean; isNewIp: boolean; recentFailureCount: number; distinctIpCount: number; riskScore: number; requiresNotification: boolean }> {
    const since = new Date(Date.now() - 24 * 3_600_000);

    try {
      const [knownDevice, knownIp, recentFailureCount, distinctIps] = await Promise.all([
        (this.prisma as any).userSession?.findFirst({ where: { userId: signals.userId, deviceId: signals.deviceId }, select: { id: true } }) || null,
        (this.prisma as any).loginAttempt?.findFirst({ where: { userId: signals.userId, ipHash: signals.ipHash, successful: true }, select: { id: true } }) || null,
        (this.prisma as any).loginAttempt?.count({ where: { tenantId: signals.tenantId, emailIndex: signals.emailIndex, successful: false, createdAt: { gte: since } } }) || 0,
        (this.prisma as any).loginAttempt?.findMany({ where: { userId: signals.userId, createdAt: { gte: since } }, select: { ipHash: true }, distinct: ['ipHash'] }) || [],
      ]);

      const isNewDevice = knownDevice === null;
      const isNewIp = knownIp === null;
      const distinctIpCount = distinctIps.length;

      let riskScore = 0;
      if (isNewDevice) riskScore += 35;
      if (isNewIp) riskScore += 25;
      if (recentFailureCount >= 3) riskScore += Math.min(30, recentFailureCount * 5);
      if (distinctIpCount >= 5) riskScore += 20;

      return {
        isNewDevice,
        isNewIp,
        recentFailureCount,
        distinctIpCount,
        riskScore: Math.min(100, riskScore),
        requiresNotification: isNewDevice || riskScore >= 60,
      };
    } catch {
      return { isNewDevice: true, isNewIp: true, recentFailureCount: 0, distinctIpCount: 1, riskScore: 35, requiresNotification: true };
    }
  }
}

import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  Query,
  UseGuards,
  Req,
  ForbiddenException,
  BadRequestException,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { RequirePermissions } from '../../common/decorators/permissions.decorator';
import { Permission } from '@wlct/shared-types';
import { CurrentUser } from '../../common/decorators/current-user.decorator';
import { CurrentTenant, TenantId } from '../../common/decorators/current-tenant.decorator';
import { SecurityPolicyService } from './security-policy.service';
import { EnterpriseSsoService } from './enterprise-sso.service';
import { SsoProviderFactory } from './sso-provider.factory';
import { ApiKeyService } from './api-key.service';
import { SessionSecurityService } from './session-security.service';
import { DeviceTrustService } from './device-trust.service';
import { MfaPolicyService } from './mfa-policy.service';
import { SecurityEventService } from './security-event.service';
import { SecurityAuditService } from './security-audit.service';
import { SecurityThreatDetectionService } from './security-threat-detection.service';
import { CreateSamlConfigDto, CreateOidcConfigDto, UpdateSsoConfigDto } from './dto/sso-config.dto';
import { CryptoService } from '../../infrastructure/crypto/crypto.service';
import { CreateApiKeyDto, ListApiKeyDto, RotateApiKeyDto, RevokeApiKeyDto } from './dto/api-key.dto';
import { CreateSecurityPolicyDto, UpdateSecurityPolicyDto, SessionQueryDto, DeviceQueryDto, SecurityEventQueryDto, ThreatQueryDto } from './dto/security-policy.dto';
import { SsoProvider } from './security.types';
import { isPlatformPrincipal } from '../../common/guards/request-principal';

/**
 * RBAC-protected security API for SSO, API keys, sessions, devices, security events, and policy management.
 * Tenant security admins → own tenant, privileged platform admins → PLATFORM_MANAGE, ordinary users → only own sessions/API keys/devices.
 */

@Controller('security')
@UseGuards(AuthGuard('jwt'))
export class SecurityController {
  constructor(
    private readonly policyService: SecurityPolicyService,
    private readonly ssoService: EnterpriseSsoService,
    private readonly ssoFactory: SsoProviderFactory,
    private readonly apiKeyService: ApiKeyService,
    private readonly sessionService: SessionSecurityService,
    private readonly deviceService: DeviceTrustService,
    private readonly mfaPolicyService: MfaPolicyService,
    private readonly eventService: SecurityEventService,
    private readonly auditService: SecurityAuditService,
    private readonly threatService: SecurityThreatDetectionService,
    private readonly crypto: CryptoService,
  ) {}

  /** Keyed, non-reversible client IP for audit records (never the raw address). */
  private ipHashOf(req: { ip?: string }): string | undefined {
    return req.ip ? this.crypto.hashIp(req.ip) : undefined;
  }

  // ===== Security Policy =====

  @Get('policy')
  @RequirePermissions(Permission.SECURITY_POLICY_READ, Permission.PLATFORM_MANAGE, Permission.SECURITY_EVENT_READ)
  async getPolicy(@CurrentTenant() tenant: any, @Query('tenantId') tenantIdQuery?: string) {
    const tenantId = tenantIdQuery || tenant?.tenantId || tenant?.id;
    return this.policyService.getEffectivePolicy({ tenantId });
  }

  @Get('policy/platform')
  @RequirePermissions(Permission.PLATFORM_MANAGE)
  async getPlatformPolicy() {
    return this.policyService.getPlatformPolicy();
  }

  @Post('policy')
  @RequirePermissions(Permission.SECURITY_POLICY_WRITE, Permission.PLATFORM_MANAGE)
  async createPolicy(@Body() dto: CreateSecurityPolicyDto, @CurrentUser() user: any, @Req() req: any) {
    const tenantId = dto.tenantId || null;
    return this.policyService.createOrUpdatePolicy({
      tenantId,
      policyVersion: dto.policyVersion,
      mfaRequired: dto.mfaRequired,
      mfaForPrivilegedRoles: dto.mfaForPrivilegedRoles,
      mfaForSensitiveOperations: dto.mfaForSensitiveOperations,
      sessionAbsoluteTimeoutSec: dto.sessionAbsoluteTimeoutSec,
      sessionIdleTimeoutSec: dto.sessionIdleTimeoutSec,
      maxConcurrentSessions: dto.maxConcurrentSessions,
      deviceTrustDurationDays: dto.deviceTrustDurationDays,
      apiKeyExpirationDays: dto.apiKeyExpirationDays,
      apiKeyRotationDays: dto.apiKeyRotationDays,
      ssoEnforced: dto.ssoEnforced,
      allowedSsoDomains: dto.allowedSsoDomains,
      jitProvisioning: dto.jitProvisioning,
      privilegedReauthRequired: dto.privilegedReauthRequired,
      securityNotifications: dto.securityNotifications,
      passwordMinLength: dto.passwordMinLength,
      actorId: user.userId || user.id,
    });
  }

  @Put('policy/:id')
  @RequirePermissions(Permission.SECURITY_POLICY_WRITE, Permission.PLATFORM_MANAGE)
  async updatePolicy(@Param('id') id: string, @Body() dto: UpdateSecurityPolicyDto, @CurrentUser() user: any, @Req() req: any) {
    // For simplicity, treat update as createOrUpdate with same version if provided, else fetch existing version
    const existing = await (this.policyService as any).prisma?.securityPolicy?.findUnique?.({ where: { id } });
    const policyVersion = existing?.policyVersion || `v${Date.now()}`;
    const tenantId = existing?.tenantId || null;

    return this.policyService.createOrUpdatePolicy({
      tenantId,
      policyVersion,
      mfaRequired: dto.mfaRequired,
      mfaForPrivilegedRoles: dto.mfaForPrivilegedRoles,
      mfaForSensitiveOperations: dto.mfaForSensitiveOperations,
      sessionAbsoluteTimeoutSec: dto.sessionAbsoluteTimeoutSec,
      sessionIdleTimeoutSec: dto.sessionIdleTimeoutSec,
      maxConcurrentSessions: dto.maxConcurrentSessions,
      deviceTrustDurationDays: dto.deviceTrustDurationDays,
      apiKeyExpirationDays: dto.apiKeyExpirationDays,
      apiKeyRotationDays: dto.apiKeyRotationDays,
      ssoEnforced: dto.ssoEnforced,
      allowedSsoDomains: dto.allowedSsoDomains,
      jitProvisioning: dto.jitProvisioning,
      privilegedReauthRequired: dto.privilegedReauthRequired,
      securityNotifications: dto.securityNotifications,
      passwordMinLength: dto.passwordMinLength,
      actorId: user.userId || user.id,
    });
  }

  // ===== SSO Configuration =====
  //
  // Round 7: tenant administrators (SSO_MANAGE + SECURITY_POLICY_WRITE, both in
  // the TENANT_ADMIN matrix) manage SSO for their own tenant; the tenant comes
  // from @TenantId, never from the body. PLATFORM_MANAGE used to be required as
  // well, which made SSO a super-admin-only feature. The service refuses an
  // enforcement that could lock the tenant's administrators out.

  @Post('sso/saml/config')
  @RequirePermissions(Permission.SSO_MANAGE, Permission.SECURITY_POLICY_WRITE)
  async configureSaml(@Body() dto: CreateSamlConfigDto, @TenantId() tenantId: string, @CurrentUser() user: any, @Req() req: any) {
    return this.ssoService.configureSso({
      tenantId,
      providerType: SsoProvider.SAML,
      issuer: dto.issuer,
      entityId: dto.entityId,
      ssoUrl: dto.ssoUrl,
      acsUrl: dto.acsUrl,
      audience: dto.audience,
      certificate: dto.certificate,
      redirectUri: dto.redirectUri,
      wantResponseSigned: dto.wantResponseSigned,
      wantAssertionsEncrypted: dto.wantAssertionsEncrypted,
      spDecryptionPrivateKey: dto.spDecryptionPrivateKey,
      spEncryptionCertificate: dto.spEncryptionCertificate,
      sloUrl: dto.sloUrl,
      logoutCallbackUrl: dto.logoutCallbackUrl,
      spSigningPrivateKey: dto.spSigningPrivateKey,
      spSigningCertificate: dto.spSigningCertificate,
      clockSkewSec: dto.clockSkewSec,
      allowedDomains: dto.allowedDomains,
      enforced: dto.enforced,
      jitEnabled: dto.jitEnabled,
      defaultRole: dto.defaultRole,
      actorId: user.userId || user.id,
      actorIsPlatform: isPlatformPrincipal(req),
      ipHash: this.ipHashOf(req),
      requestId: req.headers['x-request-id'],
    });
  }

  @Post('sso/oidc/config')
  @RequirePermissions(Permission.SSO_MANAGE, Permission.SECURITY_POLICY_WRITE)
  async configureOidc(@Body() dto: CreateOidcConfigDto, @TenantId() tenantId: string, @CurrentUser() user: any, @Req() req: any) {
    return this.ssoService.configureSso({
      tenantId,
      providerType: SsoProvider.OIDC,
      issuer: dto.issuer,
      clientId: dto.clientId,
      clientSecret: dto.clientSecret,
      redirectUri: dto.redirectUri,
      tokenEndpointAuthMethod: dto.tokenEndpointAuthMethod,
      pkceRequired: dto.pkceRequired,
      clockSkewSec: dto.clockSkewSec,
      maxAuthAgeSec: dto.maxAuthAgeSec,
      allowedAlgorithms: dto.allowedAlgorithms,
      audience: dto.audience,
      discoveryUrl: dto.discoveryUrl,
      jwksUrl: dto.jwksUrl,
      ssoUrl: dto.ssoUrl,
      allowedDomains: dto.allowedDomains,
      enforced: dto.enforced,
      jitEnabled: dto.jitEnabled,
      defaultRole: dto.defaultRole,
      scopes: dto.scopes,
      actorId: user.userId || user.id,
      actorIsPlatform: isPlatformPrincipal(req),
      ipHash: this.ipHashOf(req),
      requestId: req.headers['x-request-id'],
    });
  }

  @Put('sso/:providerType/config')
  @RequirePermissions(Permission.SSO_MANAGE, Permission.SECURITY_POLICY_WRITE)
  async updateSsoConfig(@Param('providerType') providerType: string, @Body() dto: UpdateSsoConfigDto, @TenantId() tenantId: string, @CurrentUser() user: any, @Req() req: any) {
    const provider = providerType.toUpperCase() as SsoProvider;
    if (![SsoProvider.SAML, SsoProvider.OIDC].includes(provider)) {
      throw new BadRequestException(`Invalid provider type ${providerType}`);
    }
    return this.ssoService.configureSso({
      tenantId,
      providerType: provider,
      issuer: dto.issuer,
      entityId: dto.entityId,
      ssoUrl: dto.ssoUrl,
      acsUrl: dto.acsUrl,
      audience: dto.audience,
      certificate: dto.certificate,
      clientId: dto.clientId,
      clientSecret: dto.clientSecret,
      redirectUri: dto.redirectUri,
      tokenEndpointAuthMethod: dto.tokenEndpointAuthMethod,
      pkceRequired: dto.pkceRequired,
      clockSkewSec: dto.clockSkewSec,
      maxAuthAgeSec: dto.maxAuthAgeSec,
      allowedAlgorithms: dto.allowedAlgorithms,
      wantResponseSigned: dto.wantResponseSigned,
      wantAssertionsEncrypted: dto.wantAssertionsEncrypted,
      spDecryptionPrivateKey: dto.spDecryptionPrivateKey,
      spEncryptionCertificate: dto.spEncryptionCertificate,
      sloUrl: dto.sloUrl,
      logoutCallbackUrl: dto.logoutCallbackUrl,
      spSigningPrivateKey: dto.spSigningPrivateKey,
      spSigningCertificate: dto.spSigningCertificate,
      isActive: dto.isActive,
      allowedDomains: dto.allowedDomains,
      enforced: dto.enforced,
      jitEnabled: dto.jitEnabled,
      defaultRole: dto.defaultRole,
      discoveryUrl: dto.discoveryUrl,
      jwksUrl: dto.jwksUrl,
      scopes: dto.scopes,
      actorId: user.userId || user.id,
      actorIsPlatform: isPlatformPrincipal(req),
      ipHash: this.ipHashOf(req),
      requestId: req.headers['x-request-id'],
    });
  }

  @Delete('sso/:providerType/config')
  @RequirePermissions(Permission.SSO_MANAGE, Permission.SECURITY_POLICY_WRITE)
  async disableSso(@Param('providerType') providerType: string, @TenantId() tenantId: string, @CurrentUser() user: any, @Req() req: any) {
    const provider = providerType.toUpperCase() as SsoProvider;
    if (![SsoProvider.SAML, SsoProvider.OIDC].includes(provider)) {
      throw new BadRequestException(`Invalid provider type ${providerType}`);
    }
    return this.ssoService.disableSso({
      tenantId,
      providerType: provider,
      actorId: user.userId || user.id,
      ipHash: this.ipHashOf(req),
      requestId: req.headers['x-request-id'],
    });
  }

  @Get('sso/status')
  @RequirePermissions(Permission.SSO_READ, Permission.SECURITY_EVENT_READ)
  async getSsoStatus(@TenantId() tenantId: string) {
    return this.ssoService.getSsoStatus(tenantId);
  }

  @Get('sso/providers')
  @RequirePermissions(Permission.SSO_READ)
  async listSsoProviders(@TenantId() tenantId: string, @Query('tenantId') tenantIdQuery?: string, @CurrentUser() user?: any) {
    const effectiveTenantId = tenantIdQuery || tenantId;
    // Platform admin can query any tenant
    if (tenantIdQuery && tenantIdQuery !== tenantId) {
      // Cross-tenant reads are for platform staff holding platform:manage only.
      const perms: string[] = Array.isArray(user?.permissions) ? user.permissions : [];
      if (user?.isPlatformUser !== true || !perms.includes(Permission.PLATFORM_MANAGE)) {
        throw new ForbiddenException('Cross-tenant access denied');
      }
    }
    return this.ssoFactory.listTenantProviders(effectiveTenantId);
  }

  // SSO login itself is served by the public, rate-limited routes in
  // modules/auth/sso (POST /v1/auth/sso/start, /callback, /saml/acs).

  // ===== API Keys =====

  @Post('api-keys')
  @RequirePermissions(Permission.API_KEY_WRITE, Permission.API_KEY_MANAGE)
  async createApiKey(@Body() dto: CreateApiKeyDto, @TenantId() tenantId: string, @CurrentUser() user: any, @Req() req: any) {
    const result = await this.apiKeyService.createApiKey({
      tenantId,
      userId: user.userId || user.id,
      name: dto.name,
      scopes: dto.scopes,
      ipAllowlist: dto.ipAllowlist,
      expiresAt: dto.expiresAt ? new Date(dto.expiresAt) : undefined,
      createdById: user.userId || user.id,
      callerPermissions: user.permissions || user.roles || [],
      idempotencyKey: dto.idempotencyKey,
      ipHash: this.ipHashOf(req),
      requestId: req.headers['x-request-id'],
    });

    // Secret shown only once
    return {
      ...result.record,
      secret: result.secret,
      warning: 'Secret shown only once - store securely, it will never be shown again',
    };
  }

  @Get('api-keys')
  @RequirePermissions(Permission.API_KEY_READ, Permission.API_KEY_MANAGE)
  async listApiKeys(@Query() query: ListApiKeyDto, @TenantId() tenantId: string, @CurrentUser() user: any) {
    const caller = {
      userId: user.userId || user.id,
      tenantId: tenantId,
      permissions: user.permissions || user.roles || [],
    };
    return this.apiKeyService.listApiKeys(tenantId, caller, {
      userId: query.userId,
      state: query.state as any,
      page: query.page,
      limit: query.limit,
    });
  }

  @Post('api-keys/:id/rotate')
  @RequirePermissions(Permission.API_KEY_WRITE, Permission.API_KEY_MANAGE)
  async rotateApiKey(@Param('id') id: string, @Body() dto: RotateApiKeyDto, @TenantId() tenantId: string, @CurrentUser() user: any, @Req() req: any) {
    const caller = {
      userId: user.userId || user.id,
      tenantId,
      permissions: user.permissions || user.roles || [],
    };
    const result = await this.apiKeyService.rotateApiKey({
      id,
      tenantId,
      caller,
      createdById: user.userId || user.id,
      ipHash: this.ipHashOf(req),
      requestId: req.headers['x-request-id'],
      idempotencyKey: dto.idempotencyKey,
    });

    return {
      ...result.record,
      secret: result.secret,
      warning: 'New secret shown only once - old key rotated per policy',
    };
  }

  @Post('api-keys/:id/revoke')
  @RequirePermissions(Permission.API_KEY_WRITE, Permission.API_KEY_MANAGE)
  async revokeApiKey(@Param('id') id: string, @Body() dto: RevokeApiKeyDto, @TenantId() tenantId: string, @CurrentUser() user: any, @Req() req: any) {
    const caller = {
      userId: user.userId || user.id,
      tenantId,
      permissions: user.permissions || user.roles || [],
    };
    return this.apiKeyService.revokeApiKey({
      id,
      tenantId,
      caller,
      reason: dto.reason,
      ipHash: this.ipHashOf(req),
      requestId: req.headers['x-request-id'],
    });
  }

  // ===== Sessions =====

  @Get('sessions')
  @RequirePermissions(Permission.SESSION_READ, Permission.SECURITY_EVENT_READ)
  async listSessions(@Query() query: SessionQueryDto, @TenantId() tenantId: string, @CurrentUser() user: any, @Req() req: any) {
    const userId = query.userId || user.userId || user.id;
    const perms = user.permissions || user.roles || [];
    const isPrivileged = perms.includes('ADMIN') || perms.includes('OWNER') || perms.includes('PLATFORM_MANAGE');

    if (query.userId && query.userId !== (user.userId || user.id) && !isPrivileged) {
      throw new ForbiddenException('Cannot list other users sessions');
    }

    const sessions = await this.sessionService.listUserSessions(userId, tenantId, (req as any).sessionId || null);
    return { data: sessions, total: sessions.length };
  }

  @Post('sessions/:sessionId/revoke')
  @RequirePermissions(Permission.SESSION_WRITE)
  async revokeSession(@Param('sessionId') sessionId: string, @TenantId() tenantId: string, @CurrentUser() user: any, @Req() req: any) {
    const userId = user.userId || user.id;
    // Users can revoke own sessions, admins can revoke any in tenant
    return this.sessionService.revokeSession({
      sessionId,
      userId,
      tenantId,
      reason: 'user_revoked',
      actorId: userId,
      ipHash: this.ipHashOf(req),
      requestId: req.headers['x-request-id'],
    });
  }

  @Post('sessions/revoke-all')
  @RequirePermissions(Permission.SESSION_WRITE)
  async revokeAllSessions(@Body() body: { exceptCurrent?: boolean }, @TenantId() tenantId: string, @CurrentUser() user: any, @Req() req: any) {
    const userId = user.userId || user.id;
    const exceptSessionId = body.exceptCurrent ? (req as any).sessionId || null : null;
    const count = await this.sessionService.revokeAllSessions({
      userId,
      tenantId,
      exceptSessionId,
      reason: 'global_logout',
      actorId: userId,
      ipHash: this.ipHashOf(req),
      requestId: req.headers['x-request-id'],
    });
    return { revoked: count };
  }

  // ===== Devices =====

  @Get('devices')
  @RequirePermissions(Permission.DEVICE_READ, Permission.SECURITY_EVENT_READ)
  async listDevices(@Query() query: DeviceQueryDto, @TenantId() tenantId: string, @CurrentUser() user: any) {
    const userId = query.userId || user.userId || user.id;
    const perms = user.permissions || user.roles || [];
    const isPrivileged = perms.includes('ADMIN') || perms.includes('OWNER') || perms.includes('PLATFORM_MANAGE');

    if (query.userId && query.userId !== (user.userId || user.id) && !isPrivileged) {
      throw new ForbiddenException('Cannot list other users devices');
    }

    return this.deviceService.listDevices(tenantId, userId, { state: query.state as any, page: query.page, limit: query.limit });
  }

  @Post('devices/register')
  @RequirePermissions(Permission.DEVICE_WRITE)
  async registerDevice(@Body() body: { deviceId: string; userAgent?: string }, @TenantId() tenantId: string, @CurrentUser() user: any, @Req() req: any) {
    return this.deviceService.registerDevice({
      tenantId,
      userId: user.userId || user.id,
      deviceId: body.deviceId,
      userAgent: body.userAgent || req.headers['user-agent'],
      ipHash: this.ipHashOf(req),
      requestId: req.headers['x-request-id'],
    });
  }

  @Post('devices/:deviceId/trust')
  @RequirePermissions(Permission.DEVICE_WRITE, Permission.SECURITY_POLICY_WRITE)
  async trustDevice(@Param('deviceId') deviceId: string, @TenantId() tenantId: string, @CurrentUser() user: any, @Req() req: any) {
    return this.deviceService.trustDevice({
      tenantId,
      userId: user.userId || user.id,
      deviceId,
      actorId: user.userId || user.id,
      ipHash: this.ipHashOf(req),
      requestId: req.headers['x-request-id'],
    });
  }

  @Post('devices/:deviceId/revoke')
  @RequirePermissions(Permission.DEVICE_WRITE)
  async revokeDevice(@Param('deviceId') deviceId: string, @Body() body: { reason?: string }, @TenantId() tenantId: string, @CurrentUser() user: any, @Req() req: any) {
    return this.deviceService.revokeDevice({
      tenantId,
      userId: user.userId || user.id,
      deviceId,
      actorId: user.userId || user.id,
      reason: body.reason,
      ipHash: this.ipHashOf(req),
      requestId: req.headers['x-request-id'],
    });
  }

  @Get('devices/trust/evaluate')
  @RequirePermissions(Permission.DEVICE_READ)
  async evaluateDeviceTrust(@Query('deviceId') deviceId: string, @TenantId() tenantId: string, @CurrentUser() user: any, @Req() req: any) {
    if (!deviceId) throw new BadRequestException('deviceId required');
    return this.deviceService.evaluateDeviceTrust({
      tenantId,
      userId: user.userId || user.id,
      deviceId,
      userAgent: req.headers['user-agent'],
      ipHash: this.ipHashOf(req),
    });
  }

  // ===== MFA Policy =====

  @Get('mfa/required')
  @RequirePermissions(Permission.MFA_READ, Permission.SECURITY_EVENT_READ)
  async isMfaRequired(@Query('operation') operation: string, @Query('deviceId') deviceId: string, @TenantId() tenantId: string, @CurrentUser() user: any, @Req() req: any) {
    return this.mfaPolicyService.isMfaRequired({
      tenantId,
      userId: user.userId || user.id,
      roles: user.permissions || user.roles || [],
      operation,
      deviceId,
      ipHash: this.ipHashOf(req),
      userAgent: req.headers['user-agent'],
    });
  }

  // ===== Security Events =====

  @Get('events')
  @RequirePermissions(Permission.SECURITY_EVENT_READ, Permission.PLATFORM_MANAGE)
  async listSecurityEvents(@Query() query: SecurityEventQueryDto, @TenantId() tenantId: string, @CurrentUser() user: any) {
    // Tenant isolation - platform admin can query any tenant via query param? For now tenantId from context
    const effectiveTenantId = (query as any).tenantId || tenantId;
    if ((query as any).tenantId && (query as any).tenantId !== tenantId) {
      const perms = user.permissions || user.roles || [];
      if (!perms.includes('PLATFORM_MANAGE')) {
        throw new ForbiddenException('Cross-tenant access denied');
      }
    }

    return this.eventService.listEvents(effectiveTenantId, {
      userId: query.userId,
      type: query.type,
      severity: query.severity,
      fromDate: query.fromDate ? new Date(query.fromDate) : undefined,
      toDate: query.toDate ? new Date(query.toDate) : undefined,
      page: query.page,
      limit: query.limit,
    });
  }

  @Get('audit')
  @RequirePermissions(Permission.SECURITY_EVENT_READ, Permission.PLATFORM_MANAGE)
  async listAuditLogs(@Query() query: SecurityEventQueryDto, @TenantId() tenantId: string, @CurrentUser() user: any) {
    const effectiveTenantId = (query as any).tenantId || tenantId;
    if ((query as any).tenantId && (query as any).tenantId !== tenantId) {
      const perms = user.permissions || user.roles || [];
      if (!perms.includes('PLATFORM_MANAGE')) {
        throw new ForbiddenException('Cross-tenant access denied');
      }
    }

    return this.auditService.listAuditLogs(effectiveTenantId, {
      userId: query.userId,
      event: query.type,
      fromDate: query.fromDate ? new Date(query.fromDate) : undefined,
      toDate: query.toDate ? new Date(query.toDate) : undefined,
      page: query.page,
      limit: query.limit,
    });
  }

  // ===== Threat Detection =====

  @Get('threats')
  @RequirePermissions(Permission.SECURITY_EVENT_READ, Permission.PLATFORM_MANAGE)
  async listThreats(@Query() query: ThreatQueryDto, @TenantId() tenantId: string, @CurrentUser() user: any) {
    const effectiveTenantId = (query as any).tenantId || tenantId;
    if ((query as any).tenantId && (query as any).tenantId !== tenantId) {
      const perms = user.permissions || user.roles || [];
      if (!perms.includes('PLATFORM_MANAGE')) {
        throw new ForbiddenException('Cross-tenant access denied');
      }
    }

    return this.threatService.listThreats(effectiveTenantId, {
      userId: query.userId,
      riskLevel: query.riskLevel as any,
      ruleId: query.ruleId,
      resolved: query.resolved ? query.resolved === 'true' : undefined,
      page: query.page,
      limit: query.limit,
    });
  }

  @Post('threats/detect')
  @RequirePermissions(Permission.PLATFORM_MANAGE, Permission.SECURITY_EVENT_READ)
  async detectThreats(@Body() body: { tenantId?: string; userId?: string; fromDate?: string; toDate?: string }, @TenantId() tenantId: string) {
    const effectiveTenantId = body.tenantId || tenantId;
    return this.threatService.detectThreats({
      tenantId: effectiveTenantId,
      userId: body.userId,
      fromDate: body.fromDate ? new Date(body.fromDate) : undefined,
      toDate: body.toDate ? new Date(body.toDate) : undefined,
    });
  }

  @Post('threats/:id/resolve')
  @RequirePermissions(Permission.SECURITY_EVENT_WRITE, Permission.PLATFORM_MANAGE)
  async resolveThreat(@Param('id') id: string, @Body() body: { resolution: string }, @TenantId() tenantId: string, @CurrentUser() user: any) {
    return this.threatService.resolveThreat(id, tenantId, user.userId || user.id, body.resolution);
  }

  // Preserve old security events endpoints for backward compatibility

  @Get('events/legacy')
  @RequirePermissions(Permission.SECURITY_EVENT_READ)
  async listLegacyEvents(@Query() query: any, @TenantId() tenantId: string) {
    return this.eventService.listEvents(tenantId, {
      userId: query.userId,
      type: query.type,
      severity: query.severity,
      page: query.page,
      limit: query.limit,
    });
  }
}

