import { SamlProviderService } from './saml-provider.service';
import { OidcProviderService } from './oidc-provider.service';

/**
 * Selects tenant's configured SSO provider based on tenant/provider configuration without bypassing authentication.
 * SAML/OIDC support, explicit configuration, disabled rejected, outage becomes auth failure, no fallback to insecure when enforced.
 */

class DisabledSsoProvider implements ISsoProvider {
  readonly providerType: SsoProvider;
  readonly providerName = 'DISABLED';

  constructor(providerType: SsoProvider = SsoProvider.SAML) {
    this.providerType = providerType;
  }

  isAvailable(): boolean {
    return false;
  }

  async getMetadata(tenantId: string): Promise<SsoProviderMetadata> {
    throw new SsoAuthError(
      SsoReasonCode.PROVIDER_DISABLED,
      `SSO provider ${this.providerType} disabled for tenant ${tenantId} - explicit authentication failure, no fallback to insecure login`,
    );
  }
}

@Injectable()
export class SsoProviderFactory {
  private readonly logger = new Logger(SsoProviderFactory.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly samlProvider: SamlProviderService,
    private readonly oidcProvider: OidcProviderService,
  ) {}

  async getProvider(tenantId: string, providerType?: SsoProvider): Promise<ISsoProvider> {
    try {
      const where: any = { tenantId, isActive: true };
      if (providerType) where.providerType = providerType;

      const config = await (this.prisma as any).ssoConfiguration?.findFirst({
        where,
        orderBy: { createdAt: 'desc' },
      });

      if (!config) {
        if (providerType) {
          this.logger.warn(`SSO config not found tenant=${tenantId} provider=${providerType} - explicit failure, no insecure fallback`);
          return new DisabledSsoProvider(providerType);
        }
        // Try any enabled
        const anyConfig = await (this.prisma as any).ssoConfiguration?.findFirst({
          where: { tenantId, isActive: true, state: { in: ['ENABLED', 'ENFORCED'] } },
          orderBy: { createdAt: 'desc' },
        });
        if (!anyConfig) {
          this.logger.warn(`No SSO config for tenant=${tenantId} - disabled`);
          return new DisabledSsoProvider();
        }
        return this.resolveProviderFromConfig(anyConfig);
      }

      if (config.state === 'DISABLED' || !config.isActive) {
        this.logger.warn(`SSO provider disabled tenant=${tenantId} provider=${config.providerType} state=${config.state}`);
        return new DisabledSsoProvider(config.providerType as SsoProvider);
      }

      return this.resolveProviderFromConfig(config);
    } catch (e: any) {
      this.logger.warn(`Failed to get SSO provider tenant=${tenantId}: ${e.message} - explicit failure`);
      return new DisabledSsoProvider(providerType);
    }
  }

  async getProviderByType(providerType: SsoProvider): Promise<ISsoProvider> {
    switch (providerType) {
      case SsoProvider.SAML:
        return this.samlProvider;
      case SsoProvider.OIDC:
        return this.oidcProvider;
      default:
        this.logger.warn(`Unknown SSO provider type ${providerType} - rejected`);
        return new DisabledSsoProvider(providerType);
    }
  }

  async isSsoEnabled(tenantId: string): Promise<boolean> {
    const provider = await this.getProvider(tenantId);
    return provider.isAvailable();
  }

  async isSsoEnforced(tenantId: string): Promise<boolean> {
    const config = await (this.prisma as any).ssoConfiguration?.findFirst({
      where: { tenantId, isActive: true },
      orderBy: { createdAt: 'desc' },
    });
    return config?.enforced === true && config?.state === 'ENFORCED';
  }

  private resolveProviderFromConfig(config: any): ISsoProvider {
    switch (config.providerType) {
      case 'SAML':
      case SsoProvider.SAML:
        return this.samlProvider;
      case 'OIDC':
      case SsoProvider.OIDC:
        return this.oidcProvider;
      default:
        this.logger.warn(`Unknown provider type in config ${config.providerType}`);
        return new DisabledSsoProvider(config.providerType as SsoProvider);
    }
  }

  async listTenantProviders(tenantId: string): Promise<any[]> {
    const configs = await (this.prisma as any).ssoConfiguration?.findMany({
      where: { tenantId },
      orderBy: { createdAt: 'desc' },
    }) || [];
    return configs.map((c: any) => ({
      id: c.id,
      tenantId: c.tenantId,
      providerType: c.providerType,
      state: c.state,
      issuer: c.issuer,
      audience: c.audience,
      enforced: c.enforced,
      jitEnabled: c.jitEnabled,
      isActive: c.isActive,
      allowedDomains: c.allowedDomains,
      createdAt: c.createdAt,
      updatedAt: c.updatedAt,
    }));
  }
}

import { Injectable, Optional } from '@nestjs/common';
import { InjectPinoLogger, PinoLogger } from 'nestjs-pino';
import {
  AuditAction,
  AuditActorType,
  AuditOutcome,
  SystemRole,
  TenantStatus,
  type PaginatedResult,
  type SupportedCurrency,
  type SupportedLocale,
  type TenantDto,
  type TenantPublicConfigDto,
} from '@wlct/shared-types';
import { CACHE_KEY, CACHE_TTL } from '@wlct/config';
import { buildPaginationMeta, normalisePagination } from '@wlct/utils';
import type { Prisma } from '@prisma/client';

import { PrismaService } from '../../infrastructure/prisma/prisma.service';
import { OutboxService } from '../../infrastructure/outbox/outbox.service';
import { CacheService } from '../../infrastructure/redis/cache.service';
import { CryptoService } from '../../infrastructure/crypto/crypto.service';
import { PasswordService } from '../../infrastructure/crypto/password.service';
import { TenantResolverService } from './tenant-resolver.service';
import { AuditService } from '../audit/audit.service';
import { FeatureFlagsService } from '../feature-flags/feature-flags.service';
import { ConflictException, NotFoundException } from '../../common/errors/app.exception';
import type { CreateTenantDto } from './dto/create-tenant.dto';
import type { UpdateTenantDto, UpdateTenantStatusDto } from './dto/update-tenant.dto';
import type { ListTenantsDto } from './dto/list-tenants.dto';
import type { CreateTenantDomainDto } from './dto/tenant-settings.dto';

const SORTABLE_FIELDS = ['createdAt', 'name', 'slug', 'status'] as const;

const TENANT_INCLUDE = {
  branding: true,
  domains: true,
} satisfies Prisma.TenantInclude;

type TenantRecord = Prisma.TenantGetPayload<{ include: typeof TENANT_INCLUDE }>;

/**
 * Tenant lifecycle and the public bootstrap configuration consumed by clients.
 *
 * Creating a tenant provisions its complete environment atomically: branding,
 * default settings, the system role set cloned for the tenant, feature flag
 * defaults and (optionally) the first administrator. A partially provisioned
 * brand is worse than none, so everything happens in one transaction.
 */
@Injectable()
export class TenantsService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly cache: CacheService,
    private readonly crypto: CryptoService,
    private readonly passwords: PasswordService,
    private readonly resolver: TenantResolverService,
    private readonly audit: AuditService,
    private readonly featureFlags: FeatureFlagsService,
    @InjectPinoLogger(TenantsService.name) private readonly logger: PinoLogger,
    @Optional() private readonly outbox?: OutboxService,
  ) {}

  async list(query: ListTenantsDto): Promise<PaginatedResult<TenantDto>> {
    const pagination = normalisePagination(query, SORTABLE_FIELDS);

    const where: Prisma.TenantWhereInput = {
      ...(query.includeDeleted ? {} : { deletedAt: null }),
      ...(query.status ? { status: query.status } : {}),
      ...(pagination.search
        ? {
            OR: [
              { name: { contains: pagination.search, mode: 'insensitive' } },
              { slug: { contains: pagination.search.toLowerCase() } },
              { contactEmail: { contains: pagination.search, mode: 'insensitive' } },
            ],
          }
        : {}),
    };

    const [items, totalItems] = await this.prisma.$transaction([
      this.prisma.tenant.findMany({
        where,
        include: TENANT_INCLUDE,
        orderBy: { [pagination.sortBy ?? 'createdAt']: pagination.sortOrder },
        skip: pagination.skip,
        take: pagination.take,
      }),
      this.prisma.tenant.count({ where }),
    ]);

    return {
      items: items.map((tenant) => this.toDto(tenant)),
      pagination: buildPaginationMeta(pagination.page, pagination.limit, totalItems),
    };
  }

  async findById(tenantId: string): Promise<TenantDto> {
    const tenant = await this.prisma.tenant.findFirst({
      where: { id: tenantId, deletedAt: null },
      include: TENANT_INCLUDE,
    });

    if (!tenant) {
      throw new NotFoundException('Tenant', tenantId);
    }

    return this.toDto(tenant);
  }

  /**
   * Unauthenticated bootstrap payload: branding, locales and feature flags that
   * a mobile app or web client needs before a user signs in. Contains nothing
   * sensitive by design.
   */
  async getPublicConfig(tenantId: string): Promise<TenantPublicConfigDto> {
    return this.cache.remember(
      CACHE_KEY.tenantPublicConfig(tenantId),
      CACHE_TTL.TENANT_PUBLIC_CONFIG_SECONDS,
      async () => {
        const tenant = await this.prisma.tenant.findFirst({
          where: { id: tenantId, deletedAt: null },
          include: { branding: true },
        });

        if (!tenant) {
          throw new NotFoundException('Tenant', tenantId);
        }

        const flags = await this.featureFlags.getAllForTenant(tenantId);

        return {
          tenantId: tenant.id,
          slug: tenant.slug,
          name: tenant.name,
          status: tenant.status as TenantStatus,
          branding: {
            appName: tenant.branding?.appName ?? tenant.name,
            logoUrl: tenant.branding?.logoUrl ?? null,
            logoDarkUrl: tenant.branding?.logoDarkUrl ?? null,
            faviconUrl: tenant.branding?.faviconUrl ?? null,
            primaryColor: tenant.branding?.primaryColor ?? '#1B2A4A',
            secondaryColor: tenant.branding?.secondaryColor ?? '#0F172A',
            accentColor: tenant.branding?.accentColor ?? '#22C55E',
            backgroundColor: tenant.branding?.backgroundColor ?? '#FFFFFF',
            textColor: tenant.branding?.textColor ?? '#0B1220',
            fontFamily: tenant.branding?.fontFamily ?? 'Inter',
            themeMode: (tenant.branding?.themeMode ?? 'system') as 'light' | 'dark' | 'system',
            supportEmail: tenant.branding?.supportEmail ?? null,
            supportUrl: tenant.branding?.supportUrl ?? null,
            termsUrl: tenant.branding?.termsUrl ?? null,
            privacyUrl: tenant.branding?.privacyUrl ?? null,
            customCss: tenant.branding?.customCss ?? null,
            socialLinks: (tenant.branding?.socialLinks as Record<string, string>) ?? {},
          },
          defaultLocale: tenant.defaultLocale as SupportedLocale,
          supportedLocales: tenant.supportedLocales as SupportedLocale[],
          defaultCurrency: tenant.defaultCurrency as SupportedCurrency,
          supportedCurrencies: tenant.supportedCurrencies as SupportedCurrency[],
          features: flags,
          registrationEnabled: flags.public_registration ?? true,
          twoFactorRequired: flags.two_factor_mandatory ?? false,
        };
      },
    );
  }

  async create(
    dto: CreateTenantDto,
    context: { actorId: string; ipHash: string; requestId: string },
  ): Promise<TenantDto> {
    const existing = await this.prisma.tenant.findUnique({
      where: { slug: dto.slug },
      select: { id: true },
    });

    if (existing) {
      throw new ConflictException('This slug is already taken by another organisation.', {
        slug: dto.slug,
      });
    }

    const ownerPasswordHash = dto.owner ? await this.passwords.hash(dto.owner.password) : null;
    if (dto.owner) {
      this.passwords.assertPolicy(dto.owner.password, { email: dto.owner.email });
    }

    const systemRoleTemplates = await this.prisma.role.findMany({
      where: { tenantId: null, isSystem: true, scope: 'TENANT', deletedAt: null },
      include: { permissions: { select: { permissionId: true } } },
    });

    const tenant = await this.prisma.$transaction(async (tx) => {
      const created = await tx.tenant.create({
        data: {
          slug: dto.slug,
          name: dto.name,
          legalName: dto.legalName ?? null,
          status: TenantStatus.ACTIVE,
          contactEmail: dto.contactEmail,
          contactPhone: dto.contactPhone ?? null,
          countryCode: dto.countryCode ?? null,
          defaultLocale: dto.defaultLocale,
          supportedLocales: dto.supportedLocales,
          defaultCurrency: dto.defaultCurrency,
          supportedCurrencies: dto.supportedCurrencies,
          timezone: dto.timezone,
          platformFeeBps: dto.platformFeeBps,
          performanceFeeBps: dto.performanceFeeBps,
          maxUsers: dto.maxUsers ?? null,
          maxTraders: dto.maxTraders ?? null,
          branding: {
            create: {
              appName: dto.name,
            },
          },
        },
        select: { id: true, slug: true },
      });

      // Clone the platform role templates so the tenant owns editable copies
      // while keeping the same keys the guards already understand.
      for (const template of systemRoleTemplates) {
        await tx.role.create({
          data: {
            tenantId: created.id,
            key: template.key,
            name: template.name,
            description: template.description,
            scope: template.scope,
            isSystem: true,
            isDefault: template.key === SystemRole.FOLLOWER,
            priority: template.priority,
            permissions: {
              create: template.permissions.map((entry) => ({ permissionId: entry.permissionId })),
            },
          },
        });
      }

      if (dto.owner && ownerPasswordHash) {
        const adminRole = await tx.role.findFirst({
          where: { tenantId: created.id, key: SystemRole.TENANT_ADMIN },
          select: { id: true },
        });

        const owner = await tx.user.create({
          data: {
            tenantId: created.id,
            email: dto.owner.email,
            emailIndex: this.crypto.blindIndex(dto.owner.email),
            passwordHash: ownerPasswordHash,
            status: 'ACTIVE',
            emailVerifiedAt: new Date(),
            profile: {
              create: {
                firstName: dto.owner.firstName ?? null,
                lastName: dto.owner.lastName ?? null,
                locale: dto.defaultLocale,
                preferredCurrency: dto.defaultCurrency,
                timezone: dto.timezone,
              },
            },
          },
          select: { id: true },
        });

        if (adminRole) {
          await tx.userRole.create({
            data: { userId: owner.id, roleId: adminRole.id, tenantId: created.id },
          });
        }

        await tx.tenant.update({
          where: { id: created.id },
          data: { ownerUserId: owner.id },
        });
      }

      if (dto.planId) {
        const plan = await tx.subscriptionPlan.findFirst({
          where: { id: dto.planId, deletedAt: null },
          select: { id: true, trialDays: true, interval: true },
        });

        if (plan) {
          const periodEnd = new Date();
          periodEnd.setMonth(
            periodEnd.getMonth() +
              (plan.interval === 'YEARLY' ? 12 : plan.interval === 'QUARTERLY' ? 3 : 1),
          );

          await tx.tenantSubscription.create({
            data: {
              tenantId: created.id,
              planId: plan.id,
              status: plan.trialDays > 0 ? 'TRIALING' : 'ACTIVE',
              currentPeriodEnd: periodEnd,
              trialEndsAt:
                plan.trialDays > 0
                  ? new Date(Date.now() + plan.trialDays * 86_400_000)
                  : null,
            },
          });
        }
      }

      if (!this.outbox) {
        throw new Error('Transactional outbox is unavailable; refusing tenant creation without its customer.created event');
      }
      await (tx as any).$executeRaw`SELECT set_config('app.tenant_id', ${created.id}, true)`;
      await this.outbox.append(tx, {
        tenantId: created.id,
        aggregateType: 'customer',
        aggregateId: created.id,
        eventType: 'customer.created',
        idempotencyKey: `tenant:${created.id}:customer.created`,
        correlationId: context.requestId.length <= 64 ? context.requestId : null,
        payload: { customerId: created.id },
      });

      return created;
    });

    await this.featureFlags.applyDefaultsForTenant(tenant.id);

    this.logger.info(
      { event: 'tenant.created', tenantId: tenant.id, slug: tenant.slug },
      'Tenant provisioned',
    );

    await this.audit.recordImmediate({
      tenantId: tenant.id,
      actorType: AuditActorType.USER,
      actorId: context.actorId,
      action: AuditAction.TENANT_CREATED,
      outcome: AuditOutcome.SUCCESS,
      resourceType: 'Tenant',
      resourceId: tenant.id,
      description: `Created tenant ${dto.slug}`,
      metadata: { slug: dto.slug, withOwner: Boolean(dto.owner) },
      ipHash: context.ipHash,
      requestId: context.requestId,
    });

    return this.findById(tenant.id);
  }

  async update(
    tenantId: string,
    dto: UpdateTenantDto,
    context: { actorId: string; ipHash: string; requestId: string },
  ): Promise<TenantDto> {
    const before = await this.prisma.tenant.findFirst({
      where: { id: tenantId, deletedAt: null },
      include: TENANT_INCLUDE,
    });

    if (!before) {
      throw new NotFoundException('Tenant', tenantId);
    }

    if (!this.outbox) {
      throw new Error('Transactional outbox is unavailable; refusing tenant update without its customer.updated event');
    }
    const updated = await this.prisma.withTenantRls(tenantId, async (tx) => {
      const tenantUpdate = await tx.tenant.update({
        where: { id: tenantId },
        data: {
          ...(dto.name !== undefined ? { name: dto.name } : {}),
          ...(dto.legalName !== undefined ? { legalName: dto.legalName } : {}),
          ...(dto.contactEmail !== undefined ? { contactEmail: dto.contactEmail } : {}),
          ...(dto.contactPhone !== undefined ? { contactPhone: dto.contactPhone } : {}),
          ...(dto.countryCode !== undefined ? { countryCode: dto.countryCode } : {}),
          ...(dto.defaultLocale !== undefined ? { defaultLocale: dto.defaultLocale } : {}),
          ...(dto.supportedLocales !== undefined ? { supportedLocales: dto.supportedLocales } : {}),
          ...(dto.defaultCurrency !== undefined ? { defaultCurrency: dto.defaultCurrency } : {}),
          ...(dto.supportedCurrencies !== undefined
            ? { supportedCurrencies: dto.supportedCurrencies }
            : {}),
          ...(dto.timezone !== undefined ? { timezone: dto.timezone } : {}),
          ...(dto.platformFeeBps !== undefined ? { platformFeeBps: dto.platformFeeBps } : {}),
          ...(dto.performanceFeeBps !== undefined
            ? { performanceFeeBps: dto.performanceFeeBps }
            : {}),
          ...(dto.maxUsers !== undefined ? { maxUsers: dto.maxUsers } : {}),
          ...(dto.maxTraders !== undefined ? { maxTraders: dto.maxTraders } : {}),
        },
        include: TENANT_INCLUDE,
      });
      await this.outbox!.append(tx, {
        tenantId,
        aggregateType: 'customer',
        aggregateId: tenantId,
        eventType: 'customer.updated',
        idempotencyKey: `tenant:${tenantId}:customer.updated:${context.requestId.slice(0, 128)}`,
        correlationId: context.requestId.length <= 64 ? context.requestId : null,
        payload: { customerId: tenantId },
      });
      return tenantUpdate;
    });

    await this.resolver.invalidate(
      tenantId,
      updated.slug,
      updated.domains.map((domain) => domain.domain),
    );

    await this.audit.record({
      tenantId,
      actorType: AuditActorType.USER,
      actorId: context.actorId,
      action: AuditAction.TENANT_UPDATED,
      outcome: AuditOutcome.SUCCESS,
      resourceType: 'Tenant',
      resourceId: tenantId,
      changes: {
        tenant: { before: this.toDto(before), after: this.toDto(updated) },
      },
      ipHash: context.ipHash,
      requestId: context.requestId,
    });

    return this.toDto(updated);
  }

  async updateStatus(
    tenantId: string,
    dto: UpdateTenantStatusDto,
    context: { actorId: string; ipHash: string; requestId: string },
  ): Promise<TenantDto> {
    const tenant = await this.prisma.tenant.findFirst({
      where: { id: tenantId },
      include: TENANT_INCLUDE,
    });

    if (!tenant) {
      throw new NotFoundException('Tenant', tenantId);
    }

    if (!this.outbox) {
      throw new Error('Transactional outbox is unavailable; refusing tenant status update without its customer.updated event');
    }
    const updated = await this.prisma.withTenantRls(tenantId, async (tx) => {
      const tenantUpdate = await tx.tenant.update({
        where: { id: tenantId },
        data: { status: dto.status },
        include: TENANT_INCLUDE,
      });
      await this.outbox!.append(tx, {
        tenantId,
        aggregateType: 'customer',
        aggregateId: tenantId,
        eventType: 'customer.updated',
        idempotencyKey: `tenant:${tenantId}:customer.status:${context.requestId.slice(0, 128)}`,
        correlationId: context.requestId.length <= 64 ? context.requestId : null,
        payload: { customerId: tenantId },
      });
      return tenantUpdate;
    });

    // Suspension must stop live traffic immediately.
    if (dto.status === TenantStatus.SUSPENDED || dto.status === TenantStatus.ARCHIVED) {
      await this.prisma.$transaction([
        this.prisma.userSession.updateMany({
          where: { tenantId, revokedAt: null },
          data: { revokedAt: new Date(), revokeReason: 'tenant_suspended' },
        }),
        this.prisma.refreshToken.updateMany({
          where: { tenantId, status: 'ACTIVE' },
          data: { status: 'REVOKED', revokedAt: new Date(), revokeReason: 'tenant_suspended' },
        }),
      ]);
    }

    await this.resolver.invalidate(
      tenantId,
      updated.slug,
      updated.domains.map((domain) => domain.domain),
    );

    await this.audit.recordImmediate({
      tenantId,
      actorType: AuditActorType.USER,
      actorId: context.actorId,
      action:
        dto.status === TenantStatus.SUSPENDED
          ? AuditAction.TENANT_SUSPENDED
          : AuditAction.TENANT_UPDATED,
      outcome: AuditOutcome.SUCCESS,
      resourceType: 'Tenant',
      resourceId: tenantId,
      description: dto.reason ?? `Status changed to ${dto.status}`,
      changes: { status: { before: tenant.status, after: dto.status } },
      ipHash: context.ipHash,
      requestId: context.requestId,
    });

    return this.toDto(updated);
  }

  async softDelete(
    tenantId: string,
    context: { actorId: string; ipHash: string; requestId: string },
  ): Promise<{ id: string; deleted: true }> {
    const tenant = await this.prisma.tenant.findFirst({
      where: { id: tenantId, deletedAt: null },
      include: TENANT_INCLUDE,
    });

    if (!tenant) {
      throw new NotFoundException('Tenant', tenantId);
    }

    await this.prisma.tenant.update({
      where: { id: tenantId },
      data: { deletedAt: new Date(), status: TenantStatus.ARCHIVED },
    });

    await this.resolver.invalidate(
      tenantId,
      tenant.slug,
      tenant.domains.map((domain) => domain.domain),
    );

    await this.audit.recordImmediate({
      tenantId,
      actorType: AuditActorType.USER,
      actorId: context.actorId,
      action: AuditAction.TENANT_DELETED,
      outcome: AuditOutcome.SUCCESS,
      resourceType: 'Tenant',
      resourceId: tenantId,
      ipHash: context.ipHash,
      requestId: context.requestId,
    });

    return { id: tenantId, deleted: true };
  }

  async addDomain(
    tenantId: string,
    dto: CreateTenantDomainDto,
    context: { actorId: string; ipHash: string; requestId: string },
  ): Promise<{ id: string; domain: string; verificationToken: string; status: string }> {
    const existing = await this.prisma.tenantDomain.findUnique({
      where: { domain: dto.domain },
      select: { id: true, tenantId: true },
    });

    if (existing) {
      throw new ConflictException('This domain is already registered.', { domain: dto.domain });
    }

    // The token proves ownership via a DNS TXT record before we serve the brand.
    const verificationToken = this.crypto.generateToken(16);

    const domain = await this.prisma.tenantDomain.create({
      data: {
        tenantId,
        domain: dto.domain,
        isPrimary: dto.isPrimary ?? false,
        status: 'PENDING_DNS',
        verificationToken,
      },
    });

    await this.audit.record({
      tenantId,
      actorType: AuditActorType.USER,
      actorId: context.actorId,
      action: AuditAction.TENANT_DOMAIN_ADDED,
      outcome: AuditOutcome.SUCCESS,
      resourceType: 'TenantDomain',
      resourceId: domain.id,
      description: `Registered custom domain ${dto.domain}`,
      ipHash: context.ipHash,
      requestId: context.requestId,
    });

    return {
      id: domain.id,
      domain: domain.domain,
      verificationToken: domain.verificationToken,
      status: domain.status,
    };
  }

  async removeDomain(
    tenantId: string,
    domainId: string,
    context: { actorId: string; ipHash: string; requestId: string },
  ): Promise<{ id: string; deleted: true }> {
    const domain = await this.prisma.tenantDomain.findFirst({
      where: { id: domainId, tenantId },
      select: { id: true, domain: true },
    });

    if (!domain) {
      throw new NotFoundException('Domain', domainId);
    }

    await this.prisma.tenantDomain.delete({ where: { id: domainId } });
    await this.resolver.invalidate(tenantId, undefined, [domain.domain]);

    await this.audit.record({
      tenantId,
      actorType: AuditActorType.USER,
      actorId: context.actorId,
      action: AuditAction.TENANT_DOMAIN_REMOVED,
      outcome: AuditOutcome.SUCCESS,
      resourceType: 'TenantDomain',
      resourceId: domainId,
      description: `Removed custom domain ${domain.domain}`,
      ipHash: context.ipHash,
      requestId: context.requestId,
    });

    return { id: domainId, deleted: true };
  }

  private toDto(tenant: TenantRecord): TenantDto {
    return {
      id: tenant.id,
      slug: tenant.slug,
      name: tenant.name,
      legalName: tenant.legalName,
      status: tenant.status as TenantStatus,
      ownerUserId: tenant.ownerUserId,
      defaultLocale: tenant.defaultLocale as SupportedLocale,
      supportedLocales: tenant.supportedLocales as SupportedLocale[],
      defaultCurrency: tenant.defaultCurrency as SupportedCurrency,
      supportedCurrencies: tenant.supportedCurrencies as SupportedCurrency[],
      timezone: tenant.timezone,
      contactEmail: tenant.contactEmail,
      contactPhone: tenant.contactPhone,
      countryCode: tenant.countryCode,
      platformFeeBps: tenant.platformFeeBps,
      performanceFeeBps: tenant.performanceFeeBps,
      maxUsers: tenant.maxUsers,
      maxTraders: tenant.maxTraders,
      branding: tenant.branding
        ? {
            id: tenant.branding.id,
            tenantId: tenant.branding.tenantId,
            appName: tenant.branding.appName,
            logoUrl: tenant.branding.logoUrl,
            logoDarkUrl: tenant.branding.logoDarkUrl,
            faviconUrl: tenant.branding.faviconUrl,
            primaryColor: tenant.branding.primaryColor,
            secondaryColor: tenant.branding.secondaryColor,
            accentColor: tenant.branding.accentColor,
            backgroundColor: tenant.branding.backgroundColor,
            textColor: tenant.branding.textColor,
            fontFamily: tenant.branding.fontFamily,
            themeMode: tenant.branding.themeMode as 'light' | 'dark' | 'system',
            supportEmail: tenant.branding.supportEmail,
            supportUrl: tenant.branding.supportUrl,
            termsUrl: tenant.branding.termsUrl,
            privacyUrl: tenant.branding.privacyUrl,
            customCss: tenant.branding.customCss,
            socialLinks: (tenant.branding.socialLinks as Record<string, string>) ?? {},
            createdAt: tenant.branding.createdAt.toISOString(),
            updatedAt: tenant.branding.updatedAt.toISOString(),
          }
        : undefined,
      domains: tenant.domains.map((domain) => ({
        id: domain.id,
        tenantId: domain.tenantId,
        domain: domain.domain,
        isPrimary: domain.isPrimary,
        status: domain.status as never,
        verificationToken: domain.verificationToken,
        verifiedAt: domain.verifiedAt ? domain.verifiedAt.toISOString() : null,
        createdAt: domain.createdAt.toISOString(),
      })),
      createdAt: tenant.createdAt.toISOString(),
      updatedAt: tenant.updatedAt.toISOString(),
      deletedAt: tenant.deletedAt ? tenant.deletedAt.toISOString() : null,
    };
  }
}

/**
 * Part 20 — the `/status` mirror is a parser, not a preference.
 *
 * These tests are the reason the table in `engine-status-contract.ts` can be trusted:
 * a required key that arrives absent is a refusal naming the key, an optional key that
 * arrives absent is the engine's documented "too old to answer" value, and a key that
 * arrives with the wrong type is a refusal even when a lax reader could have coerced it.
 * The last law is the one a `String(x ?? '')`-style reader breaks silently, and it is
 * the reason the whole file exists.
 */

import {
  ENGINE_STATUS_KEYS,
  EngineStatusShapeError,
  parseEngineStatus,
} from './engine-status-contract';

/** The smallest reply a real engine can send: the eight keys `StatusResponse` declares
 * without a default. Every other key in these tests is either absent (and must read as
 * the documented default) or present (and must be checked). */
const requiredOnly = (): Record<string, unknown> => ({
  instanceId: 'exec-a',
  mode: 'simulated',
  dryRun: true,
  adapter: 'PaperTradingAdapter',
  store: 'InMemoryOrderStore',
  storeDurable: false,
  locksDistributed: false,
  commands: ['cancel-order'],
});

describe('engine status contract - the required eight', () => {
  it('reads a required-only reply without inventing a single value', () => {
    const status = parseEngineStatus(requiredOnly());
    expect(status.mode).toBe('simulated');
    expect(status.commands).toEqual(['cancel-order']);
    // The Part 13/14/15/16/18/19 additions all read as "this engine did not say".
    expect(status.storeBackend).toBe('unknown');
    expect(status.retentionEnabled).toBe(false);
    expect(status.retentionEventDays).toBe(90);
    expect(status.enablementMaxAgeDays).toBe(30);
    expect(status.credentialSource).toBe('none');
    expect(status.credentialFetcher).toBeNull();
    expect(status.operatorConfirmation).toBe(false);
    expect(status.liveEnablement).toBeNull();
    expect(status.placement).toBeNull();
    expect(status.incidents).toBeNull();
    expect(status.metricsConfigured).toBe(false);
    expect(status.simulated).toBe(true);
  });

  it('refuses a missing required key by name, for every one of the eight', () => {
    for (const key of [
      'instanceId',
      'mode',
      'dryRun',
      'adapter',
      'store',
      'storeDurable',
      'locksDistributed',
      'commands',
    ]) {
      const body = requiredOnly();
      delete body[key];
      let thrown: unknown = null;
      try {
        parseEngineStatus(body);
      } catch (error) {
        thrown = error;
      }
      expect(thrown).toBeInstanceOf(EngineStatusShapeError);
      expect((thrown as EngineStatusShapeError).field).toBe(key);
      expect((thrown as EngineStatusShapeError).why).toBe('missing');
      // The message is operator-facing: it must say what to do about it, not just
      // that something failed.
      expect((thrown as Error).message).toMatch(/older than the contract/);
    }
  });

  it('refuses a wrongly typed required key rather than coercing it', () => {
    for (const [key, value] of [
      ['mode', 7],
      ['dryRun', 'true'],
      ['commands', 'cancel-order'],
      ['storeDurable', 1],
    ] as const) {
      const body = { ...requiredOnly(), [key]: value };
      expect(() => parseEngineStatus(body)).toThrow(EngineStatusShapeError);
      try {
        parseEngineStatus(body);
      } catch (error) {
        expect((error as EngineStatusShapeError).why).toBe('type');
        expect((error as EngineStatusShapeError).field).toBe(key);
      }
    }
  });

  it('a null in place of a required string is a refusal, not an empty string', () => {
    // `String(body.instanceId ?? '')` - the reader this part replaced - accepted this
    // and reported an engine with no identity.
    expect(() => parseEngineStatus({ ...requiredOnly(), instanceId: null })).toThrow(
      EngineStatusShapeError,
    );
  });
});

describe('engine status contract - optional keys keep their documented meaning', () => {
  it('a wrong type on an optional key is still a refusal', () => {
    // Absent means "too old to answer". Present-and-wrong means the engine is lying
    // about something the reader will act on, so it cannot be defaulted away.
    for (const [key, value] of [
      ['retentionEventDays', '90'],
      ['credentialSource', null],
      ['metricsConfigured', 'yes'],
      ['simulated', 1],
    ] as const) {
      expect(() => parseEngineStatus({ ...requiredOnly(), [key]: value })).toThrow(
        EngineStatusShapeError,
      );
    }
  });

  it('a non-array commands is refused even though Array.isArray would have hidden it', () => {
    expect(() => parseEngineStatus({ ...requiredOnly(), commands: { a: 1 } })).toThrow(
      EngineStatusShapeError,
    );
    expect(() =>
      parseEngineStatus({ ...requiredOnly(), commands: ['ok', 3] }),
    ).toThrow(/expected stringArray/);
  });
});

describe('engine status contract - the three sub-documents', () => {
  const placement = {
    label: 'placement-review',
    mode: 'local',
    requiresVenueAttestation: false,
    cacheTtlMillis: 5_000,
    attestorSource: 'unattested',
    policy: { requireOperatorConfirmation: false },
  };

  it('parses a placement block and defaults its three optional keys', () => {
    const status = parseEngineStatus({ ...requiredOnly(), placement });
    expect(status.placement).not.toBeNull();
    expect(status.placement?.attestorSource).toBe('unattested');
    expect(status.placement?.cache).toBeNull();
    expect(status.placement?.confirmationConfigured).toBe(false);
    expect(status.placement?.operatorConfirmation).toEqual({});
  });

  it('refuses a placement block missing one of its own required keys', () => {
    const broken = { ...placement } as Record<string, unknown>;
    delete broken.requiresVenueAttestation;
    let thrown: EngineStatusShapeError | null = null;
    try {
      parseEngineStatus({ ...requiredOnly(), placement: broken });
    } catch (error) {
      thrown = error as EngineStatusShapeError;
    }
    expect(thrown).toBeInstanceOf(EngineStatusShapeError);
    // The nested path is named, so the reader learns WHICH half of the engine
    // answered badly rather than "placement is wrong".
    expect(thrown?.field).toBe('placement.requiresVenueAttestation');
  });

  it('tells the two same-named keys apart: top-level bool, nested dict', () => {
    expect(ENGINE_STATUS_KEYS).toContain('operatorConfirmation');
    const bare = parseEngineStatus(requiredOnly());
    expect(bare.operatorConfirmation).toBe(false);
    const withView = parseEngineStatus({
      ...requiredOnly(),
      operatorConfirmation: true,
      placement: { ...placement, operatorConfirmation: { windowMillis: 60_000 } },
    });
    expect(withView.operatorConfirmation).toBe(true);
    expect(withView.placement?.operatorConfirmation).toEqual({ windowMillis: 60_000 });
    // A bool where a dict belongs, and vice versa, are both refusals: this is the
    // collision the contract module warns about in its own comment.
    expect(() =>
      parseEngineStatus({ ...requiredOnly(), placement: { ...placement, operatorConfirmation: true } }),
    ).toThrow(EngineStatusShapeError);
    expect(() => parseEngineStatus({ ...requiredOnly(), operatorConfirmation: {} })).toThrow(
      EngineStatusShapeError,
    );
  });

  it('parses the live-enablement block and refuses a fabricated permission', () => {
    const status = parseEngineStatus({
      ...requiredOnly(),
      liveEnablement: {
        liveRefused: true,
        missing: ['SIGNED_TRANSPORT_WIRED'],
        satisfied: ['IP_ALLOWLIST_ENFORCED'],
        missingCodes: ['LIVE_SIGNED_TRANSPORT_WIRED'],
        hardBlockersPresent: true,
        credentialSource: 'vault',
      },
    });
    expect(status.liveEnablement?.missing).toEqual(['SIGNED_TRANSPORT_WIRED']);
    expect(status.liveEnablement?.credentialSource).toBe('vault');
    // A string where a list belongs would let a producer's mistake read as "nothing
    // is missing", which is the one thing this block must never appear to say.
    expect(() =>
      parseEngineStatus({ ...requiredOnly(), liveEnablement: { liveRefused: true, missing: 'none' } }),
    ).toThrow(/liveEnablement.missing/);
  });

  it('parses the incident sink and its default-empty stats', () => {
    const status = parseEngineStatus({
      ...requiredOnly(),
      incidents: { durable: true, sink: 'postgres' },
    });
    expect(status.incidents).toEqual({ durable: true, sink: 'postgres', stats: {} });
    expect(() =>
      parseEngineStatus({ ...requiredOnly(), incidents: { durable: 'yes', sink: 'postgres' } }),
    ).toThrow(/incidents.durable/);
  });

  it('refuses a sub-document that arrives as an array or a scalar', () => {
    for (const value of [[], 'placement', 3] as const) {
      expect(() => parseEngineStatus({ ...requiredOnly(), placement: value })).toThrow(
        /expected an object at "placement"/,
      );
    }
  });
});

describe('engine status contract - the Part 21-23 posture blocks (round 8)', () => {
  // Values copied from a real `GET /internal/v1/status` answered by the
  // execution-engine container in the round-8 Docker run (simulated mode, in-memory
  // locks, no venue attestor). Before the fix the worker refused exactly this reply
  // at `distributedLockWiring.fencingEnabled`, so its start-up gate never passed.
  const distributedLockWiring = {
    distributed: false,
    manager: 'InMemoryLockManager',
    mode: 'memory',
    ttlMs: 15000,
    acquisitionTimeoutMs: 5000,
    renewalRatio: 0.3333333333333333,
    instanceId: 'execution-engine-1',
    fencingRequired: true,
    fenced: false,
  };
  const credentialRegistry = {
    providerSource: 'none',
    credentialSource: 'none',
    capabilities: {
      resolvesPerAccount: true,
      multiExchange: false,
      cacheInvalidation: true,
      redactedLogging: true,
    },
    builtAtMicros: 1790927057108725,
    selection: 'composition-root-singleton',
  };
  const venueAttestation = {
    enabled: true,
    testnet: true,
    cacheTtlMs: 300000,
    includeAccountFlags: false,
    attestorSource: 'binance:testnet',
    venueBacked: true,
  };

  it('parses the blocks a real simulated engine publishes', () => {
    const status = parseEngineStatus({
      ...requiredOnly(),
      distributedLockWiring,
      venueAttestation: null,
      credentialRegistry,
    });
    expect(status.distributedLockWiring).toEqual(distributedLockWiring);
    expect(status.venueAttestation).toBeNull();
    expect(status.credentialRegistry).toEqual(credentialRegistry);
    expect(status.unmappedKeys).toEqual([]);
  });

  it('parses a wired venue attestation block', () => {
    const status = parseEngineStatus({ ...requiredOnly(), venueAttestation });
    expect(status.venueAttestation).toEqual(venueAttestation);
  });

  it('keeps renewalRatio a fraction instead of demanding an integer', () => {
    const status = parseEngineStatus({ ...requiredOnly(), distributedLockWiring });
    expect(status.distributedLockWiring?.renewalRatio).toBeCloseTo(1 / 3);
    expect(() =>
      parseEngineStatus({
        ...requiredOnly(),
        distributedLockWiring: { ...distributedLockWiring, renewalRatio: 'a third' },
      }),
    ).toThrow(/distributedLockWiring.renewalRatio/);
  });

  it('still refuses a posture block missing one of its published keys', () => {
    const { fenced: _fenced, ...withoutFenced } = distributedLockWiring;
    expect(() =>
      parseEngineStatus({ ...requiredOnly(), distributedLockWiring: withoutFenced }),
    ).toThrow(/distributedLockWiring.fenced/);
    const { capabilities: _capabilities, ...withoutCapabilities } = credentialRegistry;
    expect(() =>
      parseEngineStatus({ ...requiredOnly(), credentialRegistry: withoutCapabilities }),
    ).toThrow(/credentialRegistry.capabilities/);
  });
});

describe('engine status contract - what the engine starts saying later', () => {
  it('tolerates an unknown key and reports it instead of dropping it', () => {
    const status = parseEngineStatus({ ...requiredOnly(), zetaNewFact: 1, alphaNewFact: 2 });
    expect(status.unmappedKeys).toEqual(['alphaNewFact', 'zetaNewFact']);
    expect(status.mode).toBe('simulated');
  });

  it('reports nothing unmapped for a contract-shaped reply', () => {
    expect(parseEngineStatus(requiredOnly()).unmappedKeys).toEqual([]);
  });

  it('refuses a body that is not an object at all (the proxy-page case)', () => {
    for (const body of ['<html>502</html>', null, [], 42] as const) {
      expect(() => parseEngineStatus(body)).toThrow(EngineStatusShapeError);
    }
  });

  it('is a frozen result, so a panel cannot edit the mirror into a different answer', () => {
    const status = parseEngineStatus(requiredOnly());
    expect(Object.isFrozen(status)).toBe(true);
    expect(() => {
      (status as { mode: string }).mode = 'live';
    }).toThrow(TypeError);
  });
});
